    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v ops.tour_source_evidence%rowtype; v_id uuid;
begin
  select * into v from jsonb_populate_record(null::ops.tour_source_evidence,p_payload);
  if v.id is not null or v.organization_tenant_id is null or v.stable_locator is null
     or v.evidence_class is null or v.retrieved_at is null or v.retrieval_status is null
     or v.content_digest is null or v.rights_receipt_id is null or v.rights_provider is null
     or v.rights_policy_key is null or v.data_classification is null then
    raise exception 'source evidence append payload is invalid';
  end if;
  insert into ops.tour_source_evidence (organization_tenant_id,stable_locator,evidence_class,retrieved_at,retrieval_status,content_digest,rights_receipt_id,rights_provider,rights_policy_key,data_classification)
  values (v.organization_tenant_id,v.stable_locator,v.evidence_class,v.retrieved_at,v.retrieval_status,v.content_digest,v.rights_receipt_id,v.rights_provider,v.rights_policy_key,v.data_classification)
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: applicable_rules(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.applicable_rules(p_workflow text DEFAULT NULL::text, p_surface text DEFAULT NULL::text, p_tier text DEFAULT NULL::text) RETURNS TABLE(rule_id uuid, statement text, enforcement_class text, binding_moment text, applicability jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select r.id,r.statement,a.enforcement_class,a.binding_moment,a.applicability
    from rule r
    join ops.rule_admission a on a.rule_id=r.id
    join ops.rule_approval_receipt ar
      on ar.rule_id=r.id and ar.actor_id=r.activated_by
     and (
       (
         (ar.rule_version=r.version or exists (
           select 1 from ops.rule_approval_lifecycle_anchor legacy
            where legacy.approval_receipt_id=ar.id and legacy.rule_id=r.id
              and legacy.rule_version_after=r.version
              and legacy.statement_hash=ar.statement_hash))
         and ar.statement_hash=encode(digest(r.statement,'sha256'),'hex')
       )
       -- (0349) An amended active rule's VERSION and STATEMENT both moved
       -- together, so both the version-match and the hash-match above are
       -- expected to fail for it -- rule_amendment_reaches() proves the two
       -- moved together through a genuine, tamper-evident chain rather than
       -- checking either number in isolation.
       or ops.rule_amendment_reaches(r.id,ar.rule_version,ar.statement_hash,
                                      r.version,encode(digest(r.statement,'sha256'),'hex'))
     )
     and ar.policy_kind=a.enforcement_class
     and ar.enforcement_status=a.enforcement_status
     and ar.normalized_contract->>'binding_moment'=a.binding_moment
     and ar.normalized_contract->'applicability'=a.applicability
     and ar.normalized_contract->'projection'=a.projection
     and ar.normalized_contract->'reachability'=a.reachability
     and ar.normalized_contract->'input_contract'=a.input_contract
     and ar.evidence_refs=a.fixture_refs
   where r.status='active' and a.state='admitted' and a.admitted_by=ar.actor_id
     and exists (
       select 1 from ops.authority_receipt auth
        where auth.idempotency_key='approval:'||ar.idempotency_key
          and auth.kind='activation' and auth.subject_type='rule'
          and auth.subject_id=r.id and auth.actor_id=ar.actor_id
          and auth.contract_hash=ar.contract_hash)
     and not exists (
       select 1 from unnest(ar.requested_control_keys) requested(control_key)
        where not exists (
          select 1 from ops.rule_enforcement_point ep
          join ops.enforcement_control_catalog c using (control_key)
          join ops.rule_control_binding b
            on b.rule_id=ep.rule_id and b.control_key=ep.control_key
         where ep.rule_id=r.id and ep.control_key=requested.control_key
           and ep.installed and c.installed and c.verified_at is not null
           and b.statement_hash=ar.statement_hash
           and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')))
     and (p_workflow is null or not (a.applicability ? 'workflows')
          or a.applicability->'workflows' ? '*'
          or a.applicability->'workflows' ? p_workflow)
     and (p_surface is null or not (a.applicability ? 'surfaces')
          or a.applicability->'surfaces' ? '*'
          or a.applicability->'surfaces' ? p_surface)
     and (p_tier is null or not (a.applicability ? 'tiers')
          or a.applicability->'tiers' ? '*'
          or a.applicability->'tiers' ? p_tier)
   order by r.created_at,r.id
$$;


--
-- Name: FUNCTION applicable_rules(p_workflow text, p_surface text, p_tier text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.applicable_rules(p_workflow text, p_surface text, p_tier text) IS 'Compiles the active admitted rule set for a workflow/surface/tier. SECURITY DEFINER with a pinned search_path (0188): the caller is the worker''s carr_reader role, which is views-only by design and cannot read public.rule or ops.rule_admission directly. Read-only, no dynamic SQL. Statement match accepts the original exact approval hash OR (0349) a proven ops.rule_amendment_receipt chain, so an amended active rule keeps reciting instead of silently dropping out.';


--
-- Name: apply_guidance_import_batch(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.apply_guidance_import_batch(p_batch_id uuid, p_manifest_digest text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch ops.guidance_import_batch%rowtype;
  v_existing record;
  v_entry ops.guidance_import_entry%rowtype;
  v_item_id uuid;
  v_revision_id uuid;
  v_mapping jsonb;
  v_mapping_ordinal integer;
  v_proposed_mapping_id uuid;
  v_apply_event_id uuid;
begin
  if p_manifest_digest !~ '^[0-9a-f]{64}$'
     or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance import apply requires digest, idempotency key and reason';
  end if;
  select * into v_batch from ops.guidance_import_batch where id=p_batch_id;
  if v_batch.id is null or v_batch.manifest_digest<>p_manifest_digest then
    raise exception 'unknown guidance import batch or mismatched manifest digest';
  end if;
  select * into v_existing from ops.guidance_import_apply_event where idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.batch_id<>p_batch_id or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different guidance import apply';
    end if;
    return v_existing.id;
  end if;
  if exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id) then
    raise exception 'guidance import batch is already applied under another idempotency key';
  end if;
  perform ops.assert_guidance_import_inventory(p_batch_id);
  for v_entry in select * from ops.guidance_import_entry where batch_id=p_batch_id order by ordinal loop
    select id into v_item_id from ops.guidance_item
      where source_rule_id=v_entry.source_rule_id and source_clause=v_entry.source_clause;
    if v_item_id is null then
      insert into ops.guidance_item
        (source_rule_id,source_clause,is_primary,split_group_id,created_by)
      values (v_entry.source_rule_id,v_entry.source_clause,v_entry.is_primary,
              ops.guidance_import_split_group_id(v_entry.split_group_key),v_batch.classifier_actor_id)
      returning id into v_item_id;
    elsif not exists (
      select 1 from ops.guidance_item where id=v_item_id
        and is_primary=v_entry.is_primary
        and split_group_id is not distinct from ops.guidance_import_split_group_id(v_entry.split_group_key)) then
      raise exception 'existing guidance item conflicts with import entry %',v_entry.guidance_id;
    end if;
    select id into v_revision_id from ops.guidance_revision
      where guidance_item_id=v_item_id and version=1;
    if v_revision_id is null then
      if exists (select 1 from ops.guidance_revision where guidance_item_id=v_item_id) then
        raise exception 'existing guidance item has a non-import revision history for entry %',v_entry.guidance_id;
      end if;
      insert into ops.guidance_revision
        (guidance_item_id,version,guidance_type,scope,activation,consumer,verification,
         provenance,delivery,is_constitution,classified_by,reason)
      values (v_item_id,1,v_entry.guidance_type,v_entry.scope,v_entry.activation,v_entry.consumer,
              v_entry.verification,v_entry.provenance,v_entry.delivery,v_entry.is_constitution,
              v_batch.classifier_actor_id,v_entry.revision_reason)
      returning id into v_revision_id;
    elsif not exists (
      select 1 from ops.guidance_revision where id=v_revision_id
        and guidance_type=v_entry.guidance_type and scope=v_entry.scope
        and activation=v_entry.activation and consumer=v_entry.consumer
        and verification=v_entry.verification and provenance=v_entry.provenance
        and delivery=v_entry.delivery and is_constitution=v_entry.is_constitution
        and reason=v_entry.revision_reason and classified_by=v_batch.classifier_actor_id) then
      raise exception 'existing guidance revision conflicts with import entry %',v_entry.guidance_id;
    end if;
    v_mapping_ordinal := 0;
    for v_mapping in select value from jsonb_array_elements(v_entry.situation_mappings) loop
      v_mapping_ordinal := v_mapping_ordinal + 1;
      select proposed_mapping_id into v_proposed_mapping_id
        from ops.guidance_import_mapping_execution
       where batch_id=p_batch_id and entry_id=v_entry.id and ordinal=v_mapping_ordinal;
      if v_proposed_mapping_id is null then
        v_proposed_mapping_id := ops.propose_guidance_situation_mapping(
          v_revision_id,(v_mapping->>'concept_id')::uuid,
          (v_mapping->>'doctrine_section_id')::uuid,v_mapping->>'reason');
        insert into ops.guidance_import_mapping_execution
          (batch_id,entry_id,ordinal,concept_id,doctrine_section_id,proposed_mapping_id)
        values (p_batch_id,v_entry.id,v_mapping_ordinal,(v_mapping->>'concept_id')::uuid,
                (v_mapping->>'doctrine_section_id')::uuid,v_proposed_mapping_id);
      end if;
    end loop;
  end loop;
  insert into ops.guidance_import_apply_event
    (batch_id,manifest_digest,idempotency_key,applied_by,reason)
  values (p_batch_id,p_manifest_digest,p_idempotency_key,v_batch.classifier_actor_id,p_reason)
  returning id into v_apply_event_id;
  return v_apply_event_id;
end $_$;


--
-- Name: approve_program5_release(text, text, uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_program5_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
  select ops.approve_program5_release($1,$2,$3,$4,null,null)
$_$;


--
-- Name: approve_program5_release(text, text, uuid, integer, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_program5_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer, p_verifier_actor text, p_verifier_evidence_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare actor_slug text; rel ops.release%rowtype; existing ops.release_approval_receipt%rowtype;
  rehearsal_run ops.run%rowtype; approval_uuid uuid; approved_time timestamptz; expiry_time timestamptz;
  projection jsonb; approval_hash text; approval_ref text; supplied_verifier_actor text; supplied_verifier_evidence text;
  candidate_verifier_actor text; candidate_verifier_evidence text; verifier_actor_value text; verifier_evidence_value text;
begin
  actor_slug:=ops.authority_actor_slug();
  if actor_slug<>'joe' then raise exception 'Program 5 Production approval requires Joe authority'; end if;
  if p_idempotency_key is null or coalesce(p_release_key,'')='' or coalesce(p_plan_hash,'')='' or coalesce(p_expires_hours,0) not between 1 and 24 then raise exception 'invalid Program 5 approval input'; end if;
  if (p_verifier_actor is null)<>(p_verifier_evidence_ref is null) or (p_verifier_actor is not null and (btrim(p_verifier_actor)='' or btrim(p_verifier_evidence_ref)='')) then raise exception 'supplied verifier actor and evidence must be an atomic nonblank pair'; end if;
  supplied_verifier_actor:=case when p_verifier_actor is null then null else lower(btrim(p_verifier_actor)) end;
  supplied_verifier_evidence:=case when p_verifier_evidence_ref is null then null else btrim(p_verifier_evidence_ref) end;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into existing from ops.release_approval_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.plan_hash<>p_plan_hash or existing.approval_expires_at-existing.approved_at<>make_interval(hours=>p_expires_hours)
       or not exists(select 1 from ops.release where id=existing.release_id and release_key=p_release_key and plan_hash=existing.plan_hash and approval_receipt_id=existing.id and state in ('approved','deploying','verifying','complete') and approved_at=existing.approved_at and approval_expires_at=existing.approval_expires_at and (supplied_verifier_actor is null or existing.verifier_actor=supplied_verifier_actor) and (supplied_verifier_evidence is null or existing.verifier_evidence_ref=supplied_verifier_evidence)) then raise exception 'Program 5 approval idempotency key was reused with changed input'; end if;
    return jsonb_build_object('approval_receipt_id',existing.id,'approval_ref',existing.evidence_ref,'approval_expires_at',existing.approval_expires_at,'replayed',true);
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment<>'production' or rel.state<>'candidate' or rel.plan_hash is distinct from p_plan_hash then raise exception 'release is not the exact Production candidate plan requested'; end if;
  if (rel.verifier_actor is null)<>(rel.verifier_evidence_ref is null) or (rel.verifier_actor is not null and (btrim(rel.verifier_actor)='' or btrim(rel.verifier_evidence_ref)='')) then raise exception 'candidate verifier actor and evidence must be an atomic nonblank pair'; end if;
  candidate_verifier_actor:=case when rel.verifier_actor is null then null else lower(btrim(rel.verifier_actor)) end;
  candidate_verifier_evidence:=case when rel.verifier_evidence_ref is null then null else btrim(rel.verifier_evidence_ref) end;
  verifier_actor_value:=coalesce(supplied_verifier_actor,candidate_verifier_actor);
  verifier_evidence_value:=coalesce(supplied_verifier_evidence,candidate_verifier_evidence);
  if verifier_actor_value is null or verifier_evidence_value is null then raise exception 'release cannot be approved without an INDEPENDENT VERIFIER and verification evidence'; end if;
  if rel.maker_actor is not null and verifier_actor_value=lower(btrim(rel.maker_actor)) then raise exception 'maker cannot independently verify their own release'; end if;
  select * into rehearsal_run from ops.run where id=ops.program5_exact_recovery_rehearsal(rel.id,clock_timestamp()-interval '24 hours');
  if not found then raise exception 'release has no exact typed recovery rehearsal'; end if;
  approved_time:=clock_timestamp(); expiry_time:=approved_time+make_interval(hours=>p_expires_hours);
  projection:=jsonb_build_object('release_id',rel.id,'plan_hash',rel.plan_hash,'recovery_run_id',rehearsal_run.id,'recovery_bundle_id',rehearsal_run.recovery_rehearsal_bundle_id,'approved_by_actor',actor_slug,'approved_at',approved_time,'approval_expires_at',expiry_time,'verifier_actor',verifier_actor_value,'verifier_evidence_ref',verifier_evidence_value);
  approval_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex'); approval_ref:='ops.program5-release-approval:'||approval_hash;
  insert into ops.release_approval_receipt(idempotency_key,release_id,recovery_run_id,recovery_bundle_id,plan_hash,approved_by_actor,approved_at,approval_expires_at,verifier_actor,verifier_evidence_ref,approval_sha256,evidence_ref)
  values(p_idempotency_key,rel.id,rehearsal_run.id,rehearsal_run.recovery_rehearsal_bundle_id,rel.plan_hash,actor_slug,approved_time,expiry_time,verifier_actor_value,verifier_evidence_value,approval_hash,approval_ref) returning id into approval_uuid;
  update ops.release set verifier_actor=verifier_actor_value,verifier_evidence_ref=verifier_evidence_value,state='approved',approved_by_actor=actor_slug,approved_at=approved_time,approval_expires_at=expiry_time,approval_receipt_id=approval_uuid where id=rel.id;
  return jsonb_build_object('approval_receipt_id',approval_uuid,'approval_ref',approval_ref,'approval_expires_at',expiry_time,'replayed',false);
end $$;


--
-- Name: approve_rule(uuid, text, text[], text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_rule(p_rule_id uuid, p_policy_kind text, p_control_keys text[], p_idempotency_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_bind_controls text[];
begin
  v_bind_controls := array(
    select distinct btrim(u.control_key)
      from unnest(coalesce(p_control_keys,'{}'::text[])) as u(control_key)
     where btrim(u.control_key)<>''
     order by btrim(u.control_key));
  if p_policy_kind='human_only'
     and not ('human_authority_runtime'=any(v_bind_controls)) then
    v_bind_controls := array_append(v_bind_controls,'human_authority_runtime');
  end if;

  perform ops.bind_rule_delivery(p_rule_id,p_reason);
  perform ops.bind_rule_controls(p_rule_id,v_bind_controls,p_reason);
  return ops.approve_rule_receipt_activation_v1(
    p_rule_id,p_policy_kind,p_control_keys,p_idempotency_key,p_reason);
end $$;


--
-- Name: approve_rule_receipt_activation_v1(uuid, text, text[], text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_rule_receipt_activation_v1(p_rule_id uuid, p_policy_kind text, p_control_keys text[], p_idempotency_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_rule rule%rowtype;
  v_intake_id uuid;
  v_requested text[];
  v_installed text[];
  v_missing text[];
  v_evidence text[];
  v_status text;
  v_contract jsonb;
  v_contract_hash text;
  v_receipt ops.rule_approval_receipt%rowtype;
  v_prior ops.rule_approval_receipt%rowtype;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug <> 'joe' then
    raise exception 'system rule approval requires Joe authority; % may teach and participate but cannot replace Joe approval',
      v_actor_slug;
  end if;
  select id into v_actor_id from actor
   where slug=v_actor_slug and kind='human' and active;
  if v_actor_id is null then
    raise exception 'authority actor % is not an active human',v_actor_slug;
  end if;
  if p_policy_kind='judgment_advisory' then
    raise exception 'advisory guidance is not an unbreakable rule; build a mechanical control before approval';
  end if;
  if p_policy_kind not in ('machine_enforceable','human_only') then
    raise exception 'unsupported policy kind %',p_policy_kind;
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' or btrim(coalesce(p_reason,''))='' then
    raise exception 'idempotency key and approval reason are required';
  end if;

  v_requested := array(
    select distinct btrim(u.control_key)
      from unnest(coalesce(p_control_keys,'{}'::text[])) as u(control_key)
     where btrim(u.control_key)<>'' order by btrim(u.control_key));
  if p_policy_kind='human_only'
     and not ('human_authority_runtime'=any(v_requested)) then
    v_requested := array_append(v_requested,'human_authority_runtime');
    select array_agg(u.control_key order by u.control_key) into v_requested
      from unnest(v_requested) as u(control_key);
  end if;
  if cardinality(v_requested)=0 then
    raise exception 'exact registered controls must be implemented before approval';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-approval:'||p_idempotency_key,0));
  select * into v_prior from ops.rule_approval_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if v_prior.rule_id is distinct from p_rule_id
       or v_prior.policy_kind is distinct from p_policy_kind
       or v_prior.requested_control_keys is distinct from v_requested
       or v_prior.reason is distinct from btrim(p_reason) then
      raise exception 'rule approval idempotency key was reused with different input';
    end if;
    select * into v_rule from rule where id=p_rule_id for update;
    if not found
       or v_rule.status is distinct from 'active'
       or not (v_rule.version=v_prior.rule_version or exists (
         select 1 from ops.rule_approval_lifecycle_anchor legacy
          where legacy.approval_receipt_id=v_prior.id and legacy.rule_id=v_rule.id
            and legacy.rule_version_after=v_rule.version
            and legacy.statement_hash=v_prior.statement_hash))
       or encode(digest(v_rule.statement,'sha256'),'hex') is distinct from v_prior.statement_hash
       or v_rule.activated_by is distinct from v_prior.actor_id then
      raise exception 'rule approval replay refused: current active rule no longer matches the immutable approval';
    end if;
    if not exists (
      select 1 from ops.rule_admission a
       where a.rule_id=v_rule.id and a.state='admitted'
         and a.enforcement_status=v_prior.enforcement_status
         and a.enforcement_class=v_prior.policy_kind
         and a.admitted_by=v_prior.actor_id
         and a.binding_moment=v_prior.normalized_contract->>'binding_moment'
         and a.applicability=v_prior.normalized_contract->'applicability'
         and a.projection=v_prior.normalized_contract->'projection'
         and a.reachability=v_prior.normalized_contract->'reachability'
         and a.input_contract=v_prior.normalized_contract->'input_contract'
         and a.fixture_refs=v_prior.evidence_refs
    ) or exists (
      select 1 from unnest(v_prior.requested_control_keys) requested(control_key)
       where not exists (
         select 1
           from ops.rule_enforcement_point ep
           join ops.enforcement_control_catalog c using (control_key)
           join ops.rule_control_binding b
             on b.rule_id=ep.rule_id and b.control_key=ep.control_key
          where ep.rule_id=v_rule.id
            and ep.control_key=requested.control_key
            and ep.installed and c.installed and c.verified_at is not null
            and b.statement_hash=v_prior.statement_hash
            and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')
       )
    ) or not exists (
      select 1 from ops.authority_receipt ar
       where ar.idempotency_key='approval:'||v_prior.idempotency_key
         and ar.kind='activation' and ar.subject_type='rule'
         and ar.subject_id=v_rule.id and ar.actor_id=v_prior.actor_id
         and ar.contract_hash=v_prior.contract_hash
    ) then
      raise exception 'rule approval replay refused: exact installed enforcement or authority evidence is stale';
    end if;
    return jsonb_build_object(
      'ok',true,'replayed',true,'rule_id',v_prior.rule_id,
      'policy_status','active','enforcement_status',v_prior.enforcement_status,
      'installed_controls',v_prior.installed_control_keys,
      'pending_controls','{}'::text[],'approval_receipt_id',v_prior.id);
  end if;

  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status<>'proposed' then
    raise exception 'rule % is %, only a proposed rule can be approved',p_rule_id,v_rule.status;
  end if;

  select coalesce(array_agg(c.control_key order by c.control_key),'{}'::text[]),
         coalesce(array_agg(c.test_ref order by c.control_key),'{}'::text[])
    into v_installed,v_evidence
    from ops.enforcement_control_catalog c
    join ops.rule_control_binding b using (control_key)
   where c.installed and c.verified_at is not null
     and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')
     and b.rule_id=p_rule_id
     and b.statement_hash=encode(digest(v_rule.statement,'sha256'),'hex')
     and c.control_key=any(v_requested);
  v_missing := array(
    select requested.control_key from unnest(v_requested) as requested(control_key)
     where not (requested.control_key=any(v_installed)) order by requested.control_key);
  if cardinality(v_missing)>0 or cardinality(v_installed)<>cardinality(v_requested) then
    raise exception 'rule approval refused: exact enforcement is not installed; missing %',v_missing;
  end if;
  v_status := case when p_policy_kind='human_only'
                   then 'authority_enforced' else 'hard_enforced' end;

  v_contract := jsonb_build_object(
    'rule_id',p_rule_id,
    'rule_version',v_rule.version,
    'statement_hash',encode(digest(v_rule.statement,'sha256'),'hex'),
    'enforcement_class',p_policy_kind,
    'enforcement_status',v_status,
    'binding_moment','when the approved rule applies',
    'applicability',case when v_rule.scope='{}'::jsonb
      then '{"workflows":["*"],"surfaces":["*"],"tiers":["*"]}'::jsonb
      else v_rule.scope end,
    'projection',jsonb_build_object('targets',jsonb_build_array(
      'standing-context','applicable-rules','rule-enforcement-status')),
    'reachability',jsonb_build_object('paths',jsonb_build_array(
      'record-layer','session-boot','registered-controls')),
    'input_contract','{"type":"object","required":["workflow","surface","tier"]}'::jsonb,
    'requested_controls',v_requested);
  v_contract_hash := encode(digest(v_contract::text,'sha256'),'hex');

  select id into v_intake_id from ops.guidance_intake
   where lane='rule' and source_ref='rule:'||p_rule_id::text
   order by captured_at limit 1;
  if v_intake_id is null then
    insert into ops.guidance_intake
      (lane,source_kind,source_ref,statement,state,normalized_contract,captured_by)
    values ('rule','human','rule:'||p_rule_id::text,v_rule.statement,'admitted',
            v_contract,v_actor_id) returning id into v_intake_id;
  else
    update ops.guidance_intake
       set state='admitted',normalized_contract=v_contract,updated_at=now(),version=version+1
     where id=v_intake_id;
  end if;

  insert into ops.rule_admission
    (rule_id,guidance_intake_id,enforcement_class,enforcement_status,binding_moment,
     applicability,projection,reachability,input_contract,fixture_refs,state,
     admitted_by,admitted_at,reason,coverage_detail)
  values
    (p_rule_id,v_intake_id,p_policy_kind,v_status,'when the approved rule applies',
     v_contract->'applicability',v_contract->'projection',v_contract->'reachability',
     v_contract->'input_contract',v_evidence,'admitted',v_actor_id,now(),btrim(p_reason),
     jsonb_build_object('requested',v_requested,'installed',v_installed,'missing','{}'::text[]))
  on conflict (rule_id) do update set
    guidance_intake_id=excluded.guidance_intake_id,
    enforcement_class=excluded.enforcement_class,
    enforcement_status=excluded.enforcement_status,
    binding_moment=excluded.binding_moment,
    applicability=excluded.applicability,
    projection=excluded.projection,
    reachability=excluded.reachability,
    input_contract=excluded.input_contract,
    fixture_refs=excluded.fixture_refs,
    state='admitted',admitted_by=excluded.admitted_by,admitted_at=excluded.admitted_at,
    reason=excluded.reason,coverage_detail=excluded.coverage_detail,
    version=ops.rule_admission.version+1,updated_at=now();

  update ops.rule_enforcement_point set installed=false,verified_at=null
   where rule_id=p_rule_id and not (control_key=any(v_installed));
  insert into ops.rule_enforcement_point
    (rule_id,control_key,implementation_ref,test_ref,enforcement_class,installed,verified_at)
  select p_rule_id,control_key,implementation_ref,test_ref,enforcement_class,true,verified_at
    from ops.enforcement_control_catalog
   where control_key=any(v_installed)
  on conflict (rule_id,control_key) do update set
    implementation_ref=excluded.implementation_ref,test_ref=excluded.test_ref,
    enforcement_class=excluded.enforcement_class,installed=true,
    verified_at=excluded.verified_at;

  insert into ops.rule_approval_receipt
    (idempotency_key,rule_id,rule_version,statement_hash,actor_id,policy_kind,
     enforcement_status,requested_control_keys,installed_control_keys,reason,
     normalized_contract,contract_hash,evidence_refs)
  -- The activation UPDATE below is the one permitted active transition and
  -- trg_touch_row increments the rule version in that same statement. Store
  -- the post-activation version so replay can prove no later mutation occurred.
  values (p_idempotency_key,p_rule_id,v_rule.version+1,
          encode(digest(v_rule.statement,'sha256'),'hex'),v_actor_id,p_policy_kind,v_status,
          v_requested,v_installed,btrim(p_reason),v_contract,v_contract_hash,v_evidence)
  returning * into v_receipt;

  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,contract_hash,evidence_refs)
  values ('approval:'||p_idempotency_key,'activation','rule',p_rule_id,v_actor_id,
          'approved, enforced and activated atomically',v_contract_hash,v_evidence);

  update rule
     set status='active',activated_by=v_actor_id,activated_at=now(),
         enforcement=case when v_status='hard_enforced' then 'gate' else 'constraint' end
   where id=p_rule_id and status='proposed';
  if not found then raise exception 'rule % did not activate',p_rule_id; end if;

  return jsonb_build_object(
    'ok',true,'replayed',false,'rule_id',p_rule_id,'policy_status','active',
    'enforcement_status',v_status,'installed_controls',v_installed,
    'pending_controls','{}'::text[],'approval_receipt_id',v_receipt.id);
end $$;


--
-- Name: approve_staging_release(text, text, uuid, integer, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.approve_staging_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid, p_expires_hours integer, p_verifier_actor text, p_verifier_evidence_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  actor_slug text; rel ops.release%rowtype; existing ops.staging_release_approval_receipt%rowtype;
  approved_time timestamptz; expiry_time timestamptz; projection jsonb; approval_hash text;
  approval_ref text; approval_uuid uuid; verifier_actor_value text; verifier_evidence_value text;
begin
  actor_slug:=ops.authority_actor_slug();
  if session_user<>'carr_authority_joe' or actor_slug<>'joe' then
    raise exception 'staging approval requires Joe authority';
  end if;
  if p_idempotency_key is null or coalesce(p_release_key,'')='' or coalesce(p_plan_hash,'')=''
     or coalesce(p_expires_hours,0) not between 1 and 24
     or coalesce(btrim(p_verifier_actor),'')='' or coalesce(btrim(p_verifier_evidence_ref),'')='' then
    raise exception 'invalid typed staging approval input';
  end if;
  verifier_actor_value:=lower(btrim(p_verifier_actor));
  verifier_evidence_value:=btrim(p_verifier_evidence_ref);
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,219));
  select * into existing from ops.staging_release_approval_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.plan_hash<>p_plan_hash
       or existing.approval_expires_at-existing.approved_at<>make_interval(hours=>p_expires_hours)
       or existing.verifier_actor<>verifier_actor_value or existing.verifier_evidence_ref<>verifier_evidence_value
       or not exists (select 1 from ops.release where id=existing.release_id and release_key=p_release_key
                        and environment='staging' and plan_hash=existing.plan_hash
                        and state in ('approved','deploying','verifying','complete')
                        and approved_by_actor='joe' and approved_at=existing.approved_at
                        and approval_expires_at=existing.approval_expires_at
                        and staging_approval_receipt_id=existing.id
                        and verifier_actor=existing.verifier_actor
                        and verifier_evidence_ref=existing.verifier_evidence_ref) then
      raise exception 'staging approval idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('approval_receipt_id',existing.id,'approval_ref',existing.evidence_ref,
      'approval_expires_at',existing.approval_expires_at,'replayed',true);
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment<>'staging' or rel.state<>'candidate'
     or rel.plan_hash is distinct from p_plan_hash or rel.rollback_ready is not true
     or coalesce(btrim(rel.rollback_plan_ref),'')='' then
    raise exception 'release is not the exact rollback-ready staging candidate plan requested';
  end if;
  if rel.maker_actor is not null and verifier_actor_value=lower(btrim(rel.maker_actor)) then
    raise exception 'maker cannot independently verify their own staging release';
  end if;
  approved_time:=clock_timestamp(); expiry_time:=approved_time+make_interval(hours=>p_expires_hours);
  projection:=jsonb_build_object('release_id',rel.id,'environment','staging','plan_hash',rel.plan_hash,'approved_by_actor',actor_slug,
    'approved_at',approved_time,'approval_expires_at',expiry_time,'verifier_actor',verifier_actor_value,
    'verifier_evidence_ref',verifier_evidence_value);
  approval_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  approval_ref:='ops.staging-release-approval:'||approval_hash;
  insert into ops.staging_release_approval_receipt(idempotency_key,release_id,plan_hash,approved_by_actor,
    approved_at,approval_expires_at,verifier_actor,verifier_evidence_ref,approval_sha256,evidence_ref)
  values(p_idempotency_key,rel.id,rel.plan_hash,actor_slug,approved_time,expiry_time,verifier_actor_value,
    verifier_evidence_value,approval_hash,approval_ref) returning id into approval_uuid;
  update ops.release set state='approved',approved_by_actor=actor_slug,approved_at=approved_time,
    approval_expires_at=expiry_time,verifier_actor=verifier_actor_value,
    verifier_evidence_ref=verifier_evidence_value,staging_approval_receipt_id=approval_uuid where id=rel.id;
  return jsonb_build_object('approval_receipt_id',approval_uuid,'approval_ref',approval_ref,
    'approval_expires_at',expiry_time,'replayed',false);
end $$;


--
-- Name: assert_guidance_import_inventory(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_import_inventory(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ops.guidance_import_batch where id=p_batch_id) then
    raise exception 'unknown guidance import batch %',p_batch_id;
  end if;
  if exists (
    (select id from rule
      where status='active' and coalesce(scope->>'kind','') <> 'intro_politics')
    except
    (select distinct source_rule_id from ops.guidance_import_entry where batch_id=p_batch_id)
  ) or exists (
    (select distinct source_rule_id from ops.guidance_import_entry where batch_id=p_batch_id)
    except
    (select id from rule
      where status='active' and coalesce(scope->>'kind','') <> 'intro_politics')
  ) then
    raise exception 'guidance import batch source inventory no longer exactly matches standing-context active rules';
  end if;
end $$;


--
-- Name: assert_guidance_import_materialization(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_import_materialization(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id)
     or not exists (select 1 from ops.guidance_import_decision_event
                     where batch_id=p_batch_id and state='active') then
    raise exception 'guidance import batch is not applied and human-approved';
  end if;
  if (select count(*) from ops.guidance_import_entry where batch_id=p_batch_id)
     <> (select count(*) from ops.guidance_import_entry e
          join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
          join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
          where e.batch_id=p_batch_id) then
    raise exception 'guidance import batch lacks an exact materialized revision for one or more entries';
  end if;
  if exists (
    (select g.guidance_revision_id from ops.v_guidance_materialized_current g)
    except
    (select r.id from ops.guidance_import_entry e
      join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where e.batch_id=p_batch_id)
  ) or exists (
    (select r.id from ops.guidance_import_entry e
      join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where e.batch_id=p_batch_id)
    except
    (select g.guidance_revision_id from ops.v_guidance_materialized_current g)
  ) then
    raise exception 'active guidance revisions do not exactly match the approved import batch';
  end if;
  if exists (
    (select m.guidance_revision_id,m.concept_id,m.doctrine_section_id
       from ops.v_guidance_materialized_situation_mapping_current m
       join ops.v_guidance_materialized_current g on g.guidance_revision_id=m.guidance_revision_id
      where m.state='active' and g.guidance_type='doctrine')
    except
    (select r.id,x.concept_id,x.doctrine_section_id
       from ops.guidance_import_mapping_execution x
       join ops.guidance_import_entry e on e.id=x.entry_id
       join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
       join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
      where x.batch_id=p_batch_id)
  ) or exists (
    (select r.id,x.concept_id,x.doctrine_section_id
       from ops.guidance_import_mapping_execution x
       join ops.guidance_import_entry e on e.id=x.entry_id
       join ops.guidance_item i on i.source_rule_id=e.source_rule_id and i.source_clause=e.source_clause
       join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
      where x.batch_id=p_batch_id)
    except
    (select m.guidance_revision_id,m.concept_id,m.doctrine_section_id
       from ops.v_guidance_materialized_situation_mapping_current m
       join ops.v_guidance_materialized_current g on g.guidance_revision_id=m.guidance_revision_id
      where m.state='active' and g.guidance_type='doctrine')
  ) then
    raise exception 'active doctrine mappings do not exactly match the approved import batch';
  end if;
end $$;


--
-- Name: assert_guidance_registry_coverage(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assert_guidance_registry_coverage() RETURNS TABLE(source_rule_id uuid, issue text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  with active_rules as (
    select id from rule
     where status='active' and coalesce(scope->>'kind','') <> 'intro_politics'
  ), primary_counts as (
    select ar.id,
           count(g.*) filter (where g.is_primary) as primary_count
      from active_rules ar
      left join ops.v_guidance_materialized_current g on g.source_rule_id=ar.id
     group by ar.id
  )
  select id,
         case when primary_count=0 then 'missing active primary guidance'
              else 'multiple active primary guidance records' end
    from primary_counts where primary_count <> 1
  union all
  select g.source_rule_id,'constraint lacks admitted installed enforcement projection'
    from ops.v_guidance_materialized_current g
   where g.is_primary and g.guidance_type='constraint'
     and not exists (
       select 1
         from ops.rule_admission a
         join ops.rule_enforcement_point ep
           on ep.rule_id=a.rule_id and ep.installed
        where a.rule_id=g.source_rule_id and a.state='admitted')
  union all
  select g.source_rule_id,'doctrine lacks active WR-AI-006 situation bridge'
    from ops.v_guidance_materialized_current g
   where g.is_primary and g.guidance_type='doctrine'
     and not exists (
       select 1
         from ops.v_guidance_materialized_situation_mapping_current m
         join retrieval_concept c on c.id=m.concept_id and c.status='approved'
         join doctrine_section s on s.id=m.doctrine_section_id and s.status='active'
         join doctrine_concept_mapping dcm
           on dcm.concept_id=m.concept_id
          and dcm.section_id=m.doctrine_section_id
          and dcm.status='approved'
        where m.guidance_revision_id=g.guidance_revision_id and m.state='active')
$$;


--
-- Name: assign_execution_profile(text, text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assign_execution_profile(p_work_request text, p_profile_key text, p_environment text, p_policy_ref text, p_policy_digest text, p_idempotency_key uuid) RETURNS TABLE(assignment_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id', true); work ops.work_request%rowtype;
  profile agent_profile%rowtype; sponsor actor%rowtype; existing ops.work_request_execution_assignment%rowtype;
begin
  if session_user !~ '^carr_authority_' then raise exception 'execution profile assignment requires the authoritative policy gateway'; end if;
  select * into work from ops.work_request where ref=p_work_request and organization_tenant_id=tenant for share;
  if not found then raise exception 'execution profile assignment work request is not visible'; end if;
  select * into profile from agent_profile where profile_key=p_profile_key and status='active' and current_model is not null and current_desk is not null for share;
  if not found or p_environment not in ('local','rehearsal','staging','production') or p_policy_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or p_policy_digest !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'execution profile assignment requires active profile and exact policy binding';
  end if;
  select * into sponsor from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  if not found then raise exception 'execution profile assignment cannot derive sponsoring human'; end if;
  select * into existing from ops.work_request_execution_assignment where work_request_id=work.id;
  if found then
    if existing.profile_id<>profile.id or existing.sponsoring_human_id<>sponsor.id or existing.environment<>p_environment or existing.policy_ref<>p_policy_ref or existing.policy_digest<>p_policy_digest then raise exception 'execution profile assignment conflicts with immutable existing lane'; end if;
    return query select existing.id,true; return;
  end if;
  insert into ops.work_request_execution_assignment(work_request_id,profile_id,sponsoring_human_id,environment,policy_ref,policy_digest,idempotency_key)
  values(work.id,profile.id,sponsor.id,p_environment,p_policy_ref,p_policy_digest,p_idempotency_key) returning id into assignment_id;
  return query select assignment_id,false;
end $_$;


--
-- Name: assurance_all_tokens_absent(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_all_tokens_absent(p_value jsonb) RETURNS boolean
    LANGUAGE sql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select not exists (
    select 1 from ops.canonical_ownership_lease
     where not ops.assurance_token_absent(p_value,lease_token))
$$;


--
-- Name: assurance_append_lineage_current(uuid, uuid, timestamp with time zone, uuid, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_append_lineage_current(p_lease_id uuid, p_receipt_id uuid, p_now timestamp with time zone, p_lease_token uuid DEFAULT NULL::uuid, p_fencing_generation bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare state text;
begin
  select l.state into state from ops.canonical_ownership_lease l where l.id=p_lease_id;
  if state='active' then
    if p_lease_token is not null or p_fencing_generation is not null then
      return ops.canonical_ownership_validate_live(
        p_lease_id,p_lease_token,p_fencing_generation,true);
    end if;
    return ops.assurance_lease_lineage_current(p_lease_id,p_now);
  end if;
  if state='released' then
    if p_lease_token is null or p_fencing_generation is null then
      return ops.assurance_terminal_receipt_lineage_current(p_lease_id,p_receipt_id,p_now);
    end if;
    return ops.assurance_terminal_evidence_lineage_current(
      p_lease_id,p_receipt_id,p_now,p_lease_token,p_fencing_generation);
  end if;
  return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
    '"active lease or 0532a terminal release"'::jsonb,to_jsonb(state));
end $$;


--
-- Name: assurance_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_digest(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(p_value),'sha256'),'hex')
$$;


--
-- Name: assurance_exact_object(jsonb, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_exact_object(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_typeof(p_value)='object'
     and (select coalesce(array_agg(k order by k),'{}'::text[]) from jsonb_object_keys(p_value) k)
         = (select coalesce(array_agg(k order by k),'{}'::text[]) from unnest(p_keys) k)
$$;


--
-- Name: assurance_identifier_valid(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_identifier_valid(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  select coalesce(p_value ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
$_$;


--
-- Name: assurance_lease_lineage_current(uuid, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_lease_lineage_current(p_lease_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare l ops.canonical_ownership_lease%rowtype; currentness jsonb;
        canonical_deps jsonb; stored_deps jsonb; dep record; dep_state jsonb;
        current_subject uuid; subject_count integer; holder_slug text;
        tenant text; refs text[];
begin
  select organization_tenant_id into tenant
    from ops.canonical_ownership_lease where id=p_lease_id;
  if tenant is null then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"existing canonical lease"'::jsonb,'"absent"'::jsonb);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-ownership:'||tenant,0));
  perform 1 from ops.canonical_ownership_lease
   where organization_tenant_id=tenant order by id for update;
  select * into l from ops.canonical_ownership_lease where id=p_lease_id;
  if not found or l.state<>'active' or l.expires_at<=p_now then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"active unexpired canonical lease"'::jsonb,'"stale"'::jsonb);
  end if;
  select array_agg(ref order by ref) into refs from (
    select l.slice_ref ref union
    select dependency_slice_ref from ops.canonical_ownership_dependency
     where lease_id=l.id
  ) q;
  perform ops.canonical_ownership_lock_lineage(
    l.holder_actor_id,l.slice_plan_id,refs);
  select * into l from ops.canonical_ownership_lease where id=p_lease_id;
  p_now:=clock_timestamp();
  if not found or l.state<>'active' or l.expires_at<=p_now then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"active unexpired canonical lease after lineage lock"'::jsonb,'"stale"'::jsonb);
  end if;
  select slug into holder_slug from public.actor
   where id=l.holder_actor_id and active for share;
  if holder_slug is distinct from l.holder_actor_slug then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.holder_actor',
      '"active exact holder actor"'::jsonb,'"stale"'::jsonb);
  end if;
  currentness:=ops.canonical_ownership_currentness(
    l.work_request_id,l.work_request_version,l.work_request_digest,
    l.accepted_plan_id,l.accepted_plan_digest,l.slice_plan_id,l.slice_plan_digest,l.slice_ref);
  if not coalesce((currentness->>'ok')::boolean,false) then return currentness; end if;
  select count(*),(array_agg(id order by id))[1] into subject_count,current_subject
    from ops.engineering_execution_envelope e
   where e.work_request_id=l.work_request_id and e.slice_plan_id=l.slice_plan_id
     and e.slice_ref=l.slice_ref
     and not exists (select 1 from ops.engineering_execution_envelope successor
                      where successor.supersedes_envelope_id=e.id);
  if subject_count<>1 or current_subject is distinct from l.subject_envelope_id then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.subject_envelope',
      '"current exact subject envelope"'::jsonb,'"stale"'::jsonb);
  end if;
  canonical_deps:=ops.canonical_ownership_plan_dependencies(l.slice_plan_id,l.slice_ref);
  if not coalesce((canonical_deps->>'ok')::boolean,false) then return canonical_deps; end if;
  select coalesce(jsonb_agg(jsonb_build_object('slice_ref',dependency_slice_ref,
           'required_state',required_state) order by dependency_slice_ref),'[]'::jsonb)
    into stored_deps from ops.canonical_ownership_dependency where lease_id=l.id;
  if stored_deps is distinct from canonical_deps->'dependencies' then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.dependencies',
      canonical_deps->'dependencies',stored_deps);
  end if;
  for dep in select * from ops.canonical_ownership_dependency
              where lease_id=l.id order by dependency_slice_ref loop
    dep_state:=ops.canonical_ownership_dependency_state(
      l.work_request_id,l.slice_plan_id,dep.dependency_slice_ref,dep.required_state);
    if not coalesce((dep_state->>'ok')::boolean,false) then return dep_state; end if;
  end loop;
  return jsonb_build_object('ok',true,'lease_id',l.id,'evaluated_at',p_now);
end $$;


--
-- Name: assurance_manifest_currentness(uuid, text, text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_manifest_currentness(p_manifest_id uuid, p_required_stage text, p_observed_commit_sha text, p_observed_tree_sha text, p_observed_rule_snapshot_digest text, p_observed_coordination_snapshot_digest text, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare m ops.assurance_execution_manifest%rowtype; live jsonb; now_at timestamptz;
begin
  select * into m from ops.assurance_execution_manifest where id=p_manifest_id;
  if not found then return ops.assurance_refusal('ASSURANCE_BINDING_STALE','manifest.id','"existing manifest"'::jsonb,'null'::jsonb); end if;
  perform pg_advisory_xact_lock(hashtextextended('assurance-lease-scan',0));
  live:=ops.canonical_ownership_validate_live(m.lease_id,p_lease_token,m.fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  lock table ops.canonical_ownership_lease in share mode;
  live:=ops.canonical_ownership_validate_live(m.lease_id,p_lease_token,m.fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  select * into m from ops.assurance_execution_manifest where id=p_manifest_id for key share;
  if not found then return ops.assurance_refusal('ASSURANCE_BINDING_STALE','manifest.id','"existing manifest"'::jsonb,'null'::jsonb); end if;
  now_at:=clock_timestamp();
  if not ops.assurance_all_tokens_absent(jsonb_build_array(
       p_required_stage,p_observed_commit_sha,p_observed_tree_sha,
       p_observed_rule_snapshot_digest,p_observed_coordination_snapshot_digest)) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','assurance.token_nondisclosure',
      '"lease token absent from currentness inputs"'::jsonb,'"token_present"'::jsonb);
  end if;
  if now_at>=m.snapshot_valid_until then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','manifest.snapshot_valid_until',to_jsonb(m.snapshot_valid_until),to_jsonb(now_at));
  end if;
  if p_required_stage is distinct from m.repository_stage then
    return ops.assurance_refusal('ASSURANCE_STAGE_MISMATCH','manifest.repository_stage',to_jsonb(m.repository_stage),to_jsonb(p_required_stage));
  end if;
  if p_observed_commit_sha is distinct from m.repository_commit_sha
     or p_observed_tree_sha is distinct from m.repository_tree_sha then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','manifest.repository',
      jsonb_build_object('commit_sha',m.repository_commit_sha,'tree_sha',m.repository_tree_sha),
      jsonb_build_object('commit_sha',p_observed_commit_sha,'tree_sha',p_observed_tree_sha));
  end if;
  if p_observed_rule_snapshot_digest is distinct from m.applicable_rule_snapshot_digest then
    return ops.assurance_refusal('ASSURANCE_RULE_SNAPSHOT_STALE','manifest.applicable_rule_snapshot_digest',
      to_jsonb(m.applicable_rule_snapshot_digest),to_jsonb(p_observed_rule_snapshot_digest));
  end if;
  if p_observed_coordination_snapshot_digest is distinct from m.coordination_snapshot_digest then
    return ops.assurance_refusal('ASSURANCE_COORDINATION_SNAPSHOT_STALE','manifest.coordination_snapshot_digest',
      to_jsonb(m.coordination_snapshot_digest),to_jsonb(p_observed_coordination_snapshot_digest));
  end if;
  return jsonb_build_object('ok',true,'manifest_id',m.id,'repository_stage',m.repository_stage,
    'repository_commit_sha',m.repository_commit_sha,'repository_tree_sha',m.repository_tree_sha,
    'authorizes_action',false,'evaluated_at',now_at);
end $$;


--
-- Name: assurance_normalized_set(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_normalized_set(p_value jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    from jsonb_array_elements(p_value)
$$;


--
-- Name: assurance_pinned_pointer(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_pinned_pointer(p_field text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select case p_field
    when 'argv' then '/command/argv'
    when 'cwd' then '/command/cwd'
    when 'commit_sha' then '/repository/commit_sha'
    when 'tree_sha' then '/repository/tree_sha'
    when 'environment' then '/environment'
    when 'toolchain' then '/toolchain'
    when 'output' then '/output'
    when 'timestamps' then '/timestamps'
    when 'artifacts' then '/artifacts'
    when 'exit_code' then '/output/exit_code'
    when 'stdout_digest' then '/output/stdout_digest'
    when 'stderr_digest' then '/output/stderr_digest'
    else null end
$$;


--
-- Name: assurance_pointer_value(jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_pointer_value(p_value jsonb, p_pointer text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select case p_pointer
    when '/command/argv' then p_value#>'{command,argv}'
    when '/command/cwd' then p_value#>'{command,cwd}'
    when '/repository/commit_sha' then p_value#>'{repository,commit_sha}'
    when '/repository/tree_sha' then p_value#>'{repository,tree_sha}'
    when '/environment' then p_value->'environment'
    when '/toolchain' then p_value->'toolchain'
    when '/output' then p_value->'output'
    when '/timestamps' then p_value->'timestamps'
    when '/artifacts' then p_value->'artifacts'
    when '/output/exit_code' then p_value#>'{output,exit_code}'
    when '/output/stdout_digest' then p_value#>'{output,stdout_digest}'
    when '/output/stderr_digest' then p_value#>'{output,stderr_digest}'
    else null end
$$;


--
-- Name: assurance_refusal(text, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_refusal(p_code text, p_causal_object text, p_expected jsonb, p_actual jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if p_code is null or p_code<>all(array[
    'ASSURANCE_INPUT_INVALID','ASSURANCE_DIGEST_MISMATCH','ASSURANCE_BINDING_STALE',
    'ASSURANCE_STAGE_MISMATCH','ASSURANCE_SNAPSHOT_EXPIRED','ASSURANCE_RULE_SNAPSHOT_STALE',
    'ASSURANCE_COORDINATION_SNAPSHOT_STALE','REVIEWER_POLICY_UNSUPPORTED',
    'EVIDENCE_STAGE_UNSUPPORTED','EVIDENCE_REQUIREMENT_MISMATCH','EVIDENCE_FIELD_UNSUPPORTED',
    'EVIDENCE_POINTER_INVALID','EVIDENCE_ARTIFACT_MISMATCH','ASSURANCE_SELF_REVIEW',
    'OWNER_IDENTITY_MISMATCH','OWNER_ACCEPTANCE_NOT_REVIEW','IDEMPOTENCY_CONFLICT'
  ]::text[]) then
    raise exception 'assurance persistence refusal code is not registered';
  end if;
  return jsonb_build_object('ok',false,'refusal',jsonb_build_object(
    'code',p_code,'causal_object',p_causal_object,'expected',p_expected,'actual',p_actual));
end $$;


--
-- Name: assurance_sorted_strings(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_sorted_strings(p_value jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(value) order by value),'[]'::jsonb)
    from jsonb_array_elements_text(p_value)
$$;


--
-- Name: assurance_terminal_evidence_lineage_current(uuid, uuid, timestamp with time zone, uuid, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_terminal_evidence_lineage_current(p_lease_id uuid, p_receipt_id uuid, p_now timestamp with time zone, p_lease_token uuid, p_fencing_generation bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare live jsonb; l ops.canonical_ownership_lease%rowtype;
        rs ops.canonical_ownership_runtime_session%rowtype;
begin
  live:=ops.assurance_terminal_receipt_lineage_current(p_lease_id,p_receipt_id,p_now);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  select * into l from ops.canonical_ownership_lease where id=p_lease_id for key share;
  select * into rs from ops.canonical_ownership_runtime_session
   where organization_tenant_id=l.organization_tenant_id
     and subject_envelope_id=l.subject_envelope_id
     and ownership_session_ref=l.holder_session_ref for key share;
  if p_lease_token is distinct from l.lease_token
     or p_fencing_generation is distinct from l.fencing_generation then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.terminal_authorization',
      '"exact released lease token and fence"'::jsonb,'"mismatch"'::jsonb);
  end if;
  return live;
end $$;


--
-- Name: assurance_terminal_receipt_lineage_current(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_terminal_receipt_lineage_current(p_lease_id uuid, p_receipt_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  l ops.canonical_ownership_lease%rowtype;
  r ops.engineering_slice_receipt%rowtype;
  e ops.engineering_execution_envelope%rowtype;
  j ops.job%rowtype;
  a ops.job_attempt%rowtype;
  rs ops.canonical_ownership_runtime_session%rowtype;
  issuer_generation ops.canonical_ownership_issuer_generation%rowtype;
  terminal_event ops.canonical_ownership_lease_event%rowtype;
begin
  if p_lease_id is null or p_receipt_id is null or p_now is null then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.terminal_lineage',
      '"released lease and claimed-complete receipt"'::jsonb,'"missing"'::jsonb);
  end if;
  select * into l from ops.canonical_ownership_lease where id=p_lease_id for key share;
  if l.id is null then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.terminal_lineage',
      '"existing released lease"'::jsonb,'"missing"'::jsonb);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-ownership:'||l.organization_tenant_id,0));
  lock table ops.canonical_ownership_lease in share mode;
  select * into l from ops.canonical_ownership_lease where id=p_lease_id for key share;
  select * into r from ops.engineering_slice_receipt where id=p_receipt_id for key share;
  select * into e from ops.engineering_execution_envelope where id=r.envelope_id for key share;
  select * into j from ops.job where id=e.job_id for key share;
  select * into a from ops.job_attempt where id=r.job_attempt_id for key share;
  select * into rs from ops.canonical_ownership_runtime_session
   where organization_tenant_id=l.organization_tenant_id
     and subject_envelope_id=l.subject_envelope_id
     and ownership_session_ref=l.holder_session_ref
   for key share;
  select * into issuer_generation from ops.canonical_ownership_issuer_generation
   where principal=rs.issuer_principal and state in ('active','draining')
   for key share;
  select * into terminal_event from ops.canonical_ownership_lease_event
   where lease_id=l.id and event_kind='released'
     and cause='{"reason":"release_before_terminal"}'::jsonb
     and occurred_at=l.released_at
   order by id desc limit 1 for key share;
  if l.state is distinct from 'released' or l.released_at is null
     or l.expires_at<=l.released_at or terminal_event.id is null
     or terminal_event.organization_tenant_id is distinct from l.organization_tenant_id
     or terminal_event.fencing_generation is distinct from l.fencing_generation
     or terminal_event.actor_id is distinct from l.holder_actor_id
     or terminal_event.session_ref is distinct from l.holder_session_ref
     or terminal_event.host_ref is distinct from l.holder_host_ref
     or r.id is null or r.outcome is distinct from 'claimed_complete'
     or e.id is null or e.id is distinct from l.subject_envelope_id
     or r.work_request_id is distinct from l.work_request_id
     or r.slice_ref is distinct from l.slice_ref
     or r.executor_actor_id is distinct from l.holder_actor_id
     or e.work_request_id is distinct from l.work_request_id
     or e.accepted_plan_id is distinct from l.accepted_plan_id
     or e.slice_plan_id is distinct from l.slice_plan_id
     or e.slice_ref is distinct from l.slice_ref
     or j.id is null or j.definition_key is distinct from 'engineering-slice'
     or j.state is distinct from 'succeeded' or j.attempt is distinct from rs.attempt
     or a.id is null or a.job_id is distinct from j.id or a.attempt is distinct from j.attempt
     or a.state is distinct from 'succeeded' or a.ended_at is null
     or rs.capability_token_hash is distinct from encode(public.digest(a.lease_token::text,'sha256'),'hex')
     or rs.id is null or rs.state is distinct from 'expired' or rs.phase is distinct from 'build'
     or rs.actor_id is distinct from l.holder_actor_id
     or rs.actor_slug is distinct from l.holder_actor_slug
     or rs.work_request_id is distinct from l.work_request_id
     or rs.accepted_plan_id is distinct from l.accepted_plan_id
     or rs.runtime_session_ref is distinct from e.envelope#>>'{agent_session,id}'
     or rs.execution_host_ref is distinct from l.holder_host_ref
     or issuer_generation.principal is null then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.terminal_lineage',
      '"0532a release-before-terminal receipt lineage"'::jsonb,'"mismatch"'::jsonb);
  end if;
  return jsonb_build_object('ok',true,'lease_id',l.id,'receipt_id',r.id,
    'released_at',l.released_at,'evaluated_at',p_now);
end $$;


--
-- Name: assurance_text_token_absent(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_text_token_absent(p_value text, p_token uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select position(replace(p_token::text,'-','') in
    regexp_replace(lower(p_value),'[-{}]','','g'))=0
$$;


--
-- Name: assurance_timestamp_valid(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_timestamp_valid(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
declare parsed timestamptz;
begin
  if p_value is null
     or p_value !~ '^[1-9][0-9]{3}-(0[1-9]|1[0-2])-([0-2][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]Z$' then
    return false;
  end if;
  parsed:=p_value::timestamptz;
  return isfinite(parsed)
     and to_char(parsed at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')=p_value;
exception when others then return false;
end $_$;


--
-- Name: assurance_token_absent(jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_token_absent(p_value jsonb, p_token uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select ops.assurance_text_token_absent(
    ops.guidance_import_canonical_json(p_value),p_token)
$$;


--
-- Name: assurance_unique_array(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_unique_array(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='array'
     and jsonb_array_length(p_value)=(
       select count(distinct ops.assurance_digest(value))
         from jsonb_array_elements(p_value))
$$;


--
-- Name: assurance_validate_compiler_input(uuid, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.assurance_validate_compiler_input(p_lease_id uuid, p_compiler_input jsonb, p_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare l ops.canonical_ownership_lease%rowtype; sp ops.engineering_slice_plan%rowtype;
        contract jsonb; rules jsonb; coord jsonb; selected jsonb; required_test jsonb;
        planned_check jsonb; expected_claims jsonb; expected_dependencies jsonb;
        expected_resources jsonb; expected_declared_resources jsonb;
        activated_runtime boolean;
        expected_coord_dependencies jsonb; expected_leases jsonb;
        expected_slice jsonb;
        expected_currentness jsonb; expected_base jsonb; expected_manifest jsonb;
        rule jsonb; requirement jsonb; forbidden jsonb;
        evaluation_at timestamptz; snapshot_as_of timestamptz; snapshot_until timestamptz;
        lease_expires_text text; selected_count integer;
begin
  select * into l from ops.canonical_ownership_lease where id=p_lease_id for key share;
  select * into sp from ops.engineering_slice_plan where id=l.slice_plan_id for key share;
  if l.id is null or sp.id is null then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','compiler_input.lineage',
      '"existing lease and Engineering Slice Plan"'::jsonb,'"absent"'::jsonb);
  end if;
  if not coalesce(ops.assurance_exact_object(p_compiler_input,array[
       'schema_version','work_request','accepted_plan_revision','engineering_slice_plan',
       'assurance_slice','repository','applicable_rules','coordination_snapshot',
       'declared_evaluation_time']),false)
     or p_compiler_input->>'schema_version' is distinct from 'assurance-compiler-input.v1'
     or p_compiler_input->'engineering_slice_plan' is distinct from sp.plan
     or not coalesce(ops.assurance_exact_object(p_compiler_input->'work_request',
          array['id','state_version','canonical_record_digest']),false)
     or not coalesce(ops.assurance_exact_object(p_compiler_input->'accepted_plan_revision',
          array['id','revision','digest']),false)
     or not coalesce(ops.assurance_exact_object(p_compiler_input->'repository',
          array['repository_id','commit_sha','tree_sha']),false)
     or p_compiler_input#>>'{repository,repository_id}' is distinct from 'repo:jbookout-carr-system'
     or not coalesce(p_compiler_input#>>'{repository,commit_sha}' ~ '^[0-9a-f]{40}$',false)
     or not coalesce(p_compiler_input#>>'{repository,tree_sha}' ~ '^[0-9a-f]{40}$',false)
     or not ops.assurance_timestamp_valid(p_compiler_input->>'declared_evaluation_time') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input',
      '"closed normalized assurance-compiler-input.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  contract:=p_compiler_input->'assurance_slice';
  rules:=p_compiler_input->'applicable_rules';
  coord:=p_compiler_input->'coordination_snapshot';
  evaluation_at:=(p_compiler_input->>'declared_evaluation_time')::timestamptz;
  if not coalesce(ops.assurance_exact_object(contract,array[
       'schema_version','contract_digest','ownership_contract_digest','work_request','accepted_plan_revision',
       'engineering_slice_plan_digest','slice_ref','outcome','risk','path_claims',
       'forbidden_paths','dependencies','required_tests','evidence_requirements',
       'reviewer_policy','observable_output','rollback','release_class','unfinished_work',
       'repository_binding','rule_snapshot_binding','lease_binding','executor_identity']),false)
     or contract->>'schema_version' is distinct from 'assurance-slice-contract.v1'
     or not coalesce(contract->>'contract_digest' ~ '^sha256:[0-9a-f]{64}$',false)
     or not coalesce(contract->>'ownership_contract_digest' ~ '^sha256:[0-9a-f]{64}$',false)
     or not coalesce(ops.assurance_exact_object(contract->'work_request',
          array['id','state_version','canonical_record_digest']),false)
     or not ops.assurance_identifier_valid(contract#>>'{work_request,id}')
     or jsonb_typeof(contract#>'{work_request,state_version}')<>'number'
     or not coalesce(contract#>>'{work_request,state_version}'~'^[1-9][0-9]*$',false)
     or not coalesce(contract#>>'{work_request,canonical_record_digest}'~'^sha256:[0-9a-f]{64}$',false)
     or not coalesce(ops.assurance_exact_object(contract->'accepted_plan_revision',
          array['id','revision','digest']),false)
     or not ops.assurance_identifier_valid(contract#>>'{accepted_plan_revision,id}')
     or jsonb_typeof(contract#>'{accepted_plan_revision,revision}')<>'number'
     or not coalesce(contract#>>'{accepted_plan_revision,revision}'~'^[1-9][0-9]*$',false)
     or not coalesce(contract#>>'{accepted_plan_revision,digest}'~'^sha256:[0-9a-f]{64}$',false)
     or not coalesce(contract->>'engineering_slice_plan_digest'~'^sha256:[0-9a-f]{64}$',false)
     or not coalesce(ops.assurance_identifier_valid(contract->>'slice_ref'),false)
     or jsonb_typeof(contract->'outcome') is distinct from 'string'
     or not coalesce(btrim(contract->>'outcome')<>'',false)
     or not coalesce(ops.assurance_exact_object(contract->'risk',array['risk_class','summary']),false)
     or not coalesce(contract#>>'{risk,risk_class}'=any(array['R0','R1','R2','R3','R4','R5','R6']),false)
     or jsonb_typeof(contract#>'{risk,summary}')<>'string'
     or not coalesce(btrim(contract#>>'{risk,summary}')<>'',false)
     or jsonb_typeof(contract->'path_claims') is distinct from 'array'
     or jsonb_typeof(contract->'forbidden_paths') is distinct from 'array'
     or jsonb_array_length(contract->'path_claims')=0
     or jsonb_array_length(contract->'forbidden_paths')=0
     or jsonb_typeof(contract->'dependencies') is distinct from 'array'
     or jsonb_typeof(contract->'required_tests') is distinct from 'array'
     or jsonb_typeof(contract->'evidence_requirements') is distinct from 'array'
     or jsonb_typeof(contract->'unfinished_work') is distinct from 'array'
     or not coalesce(ops.assurance_unique_array(contract->'path_claims'),false)
     or not coalesce(ops.assurance_unique_array(contract->'forbidden_paths'),false)
     or not coalesce(ops.assurance_unique_array(contract->'dependencies'),false)
     or not coalesce(ops.assurance_unique_array(contract->'required_tests'),false)
     or not coalesce(ops.assurance_unique_array(contract->'evidence_requirements'),false)
     or not coalesce(ops.assurance_unique_array(contract->'unfinished_work'),false)
     or contract->'path_claims' is distinct from ops.assurance_normalized_set(contract->'path_claims')
     or contract->'forbidden_paths' is distinct from ops.assurance_normalized_set(contract->'forbidden_paths')
     or contract->'dependencies' is distinct from ops.assurance_normalized_set(contract->'dependencies')
     or contract->'required_tests' is distinct from ops.assurance_normalized_set(contract->'required_tests')
     or contract->'evidence_requirements' is distinct from ops.assurance_normalized_set(contract->'evidence_requirements')
     or contract->'unfinished_work' is distinct from ops.assurance_normalized_set(contract->'unfinished_work') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.assurance_slice',
      '"full normalized assurance-slice-contract.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  select count(*),(jsonb_agg(value)->0) into selected_count,selected
    from jsonb_array_elements(sp.plan->'slices') value
   where value->>'slice_ref'=l.slice_ref;
  if selected_count<>1
     or contract->'work_request' is distinct from p_compiler_input->'work_request'
     or contract->'accepted_plan_revision' is distinct from p_compiler_input->'accepted_plan_revision'
     or contract->>'engineering_slice_plan_digest' is distinct from sp.plan_digest
     or contract->>'slice_ref' is distinct from l.slice_ref
     or contract#>>'{risk,risk_class}' is distinct from selected->>'risk_class'
     or p_compiler_input->'work_request' is distinct from sp.plan->'work_request'
     or p_compiler_input->'accepted_plan_revision' is distinct from sp.plan->'accepted_plan_revision'
     or p_compiler_input#>>'{work_request,id}' is distinct from 'wr:'||l.work_request_id::text
     or (p_compiler_input#>>'{work_request,state_version}')::integer is distinct from l.work_request_version
     or p_compiler_input#>>'{work_request,canonical_record_digest}' is distinct from l.work_request_digest
     or p_compiler_input#>>'{accepted_plan_revision,id}' is distinct from
        (select plan_ref from ops.sourced_work_request_plan where id=l.accepted_plan_id)
     or p_compiler_input#>>'{accepted_plan_revision,digest}' is distinct from l.accepted_plan_digest
     or p_compiler_input#>>'{repository,repository_id}' is distinct from contract#>>'{repository_binding,repository_id}'
     or p_compiler_input#>>'{repository,commit_sha}' is distinct from contract#>>'{repository_binding,commit_sha}'
     or p_compiler_input#>>'{repository,tree_sha}' is distinct from contract#>>'{repository_binding,tree_sha}' then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','compiler_input.canonical_lineage',
      '"exact live Work Request, plan, slice, and repository bindings"'::jsonb,'"mismatch"'::jsonb);
  end if;
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    into expected_claims from (
      select jsonb_build_object('path',claim_value,'mode',claim_mode,'operation',operation) value
        from ops.canonical_ownership_claim
       where lease_id=l.id and claim_kind='path') q;
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    into expected_dependencies from (
      select jsonb_build_object('slice_ref',dependency_slice_ref,'required_state',required_state) value
        from ops.canonical_ownership_dependency where lease_id=l.id) q;
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    into expected_coord_dependencies from (
      select jsonb_build_object(
        'slice_ref',d.dependency_slice_ref,'state',d.required_state,
        'evidence_digest',case when d.required_state='independently_verified'
          then ops.assurance_digest(f.fact) else r.receipt_digest end) value
        from ops.canonical_ownership_dependency d
        join ops.engineering_slice_receipt r on r.id=d.observed_receipt_id
        left join ops.engineering_reviewer_fact f on f.id=d.observed_reviewer_fact_id
       where d.lease_id=l.id) q;
  select exists(
    select 1 from ops.canonical_ownership_runtime_session rs
     where rs.organization_tenant_id=l.organization_tenant_id
       and rs.subject_envelope_id=l.subject_envelope_id
       and rs.ownership_session_ref=l.holder_session_ref)
    into activated_runtime;
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    into expected_resources from (
      select jsonb_build_object('resource',claim_value) value
        from ops.canonical_ownership_claim
       where lease_id=l.id and claim_kind='resource') q;
  select coalesce(jsonb_agg(jsonb_build_object('resource',ref)
      order by ops.assurance_digest(jsonb_build_object('resource',ref))),'[]'::jsonb)
    into expected_declared_resources from (
      select distinct value ref from jsonb_array_elements_text(
        (selected->'declared_resource_refs')||(selected->'declared_component_refs'))) q;
  if exists(select 1 from jsonb_array_elements(contract->'path_claims') x
       where not coalesce(ops.assurance_exact_object(x,array['path','mode','operation']),false)
          or not ops.canonical_ownership_path_valid(x->>'path')
          or jsonb_typeof(x->'mode') is distinct from 'string'
          or not coalesce(x->>'mode'=any(array['file','tree']),false)
          or jsonb_typeof(x->'operation') is distinct from 'string'
          or not coalesce(x->>'operation'=any(array['write','rename_source','rename_destination']),false))
     or exists(select 1 from jsonb_array_elements(contract->'dependencies') x
       where not coalesce(ops.assurance_exact_object(x,array['slice_ref','required_state']),false)
          or not ops.assurance_identifier_valid(x->>'slice_ref')
          or jsonb_typeof(x->'required_state') is distinct from 'string'
          or not coalesce(x->>'required_state'=any(array['completed','independently_verified']),false))
     or contract->'path_claims' is distinct from expected_claims
     or contract->'dependencies' is distinct from expected_dependencies
     or (not activated_runtime and exists(
          select 1 from ops.canonical_ownership_claim
           where lease_id=l.id and claim_kind<>'path'))
     or (activated_runtime and (
          expected_resources is distinct from expected_declared_resources
          or exists(select 1 from ops.canonical_ownership_claim
                     where lease_id=l.id and claim_kind not in ('path','resource'))))
     or exists(select 1 from jsonb_array_elements(contract->'forbidden_paths') x
       where not coalesce(ops.assurance_exact_object(x,array['path','mode']),false)
          or not ops.canonical_ownership_path_valid(x->>'path')
          or jsonb_typeof(x->'mode') is distinct from 'string'
          or not coalesce(x->>'mode'=any(array['file','tree']),false))
     or exists(select 1 from (
          select value->>'path' path from jsonb_array_elements(contract->'path_claims')
          union all
          select value->>'path' path from jsonb_array_elements(contract->'forbidden_paths')) paths,
          lateral (select row_number() over () ordinal) marker
          where exists(select 1 from (
            select value->>'path' other_path from jsonb_array_elements(contract->'path_claims')
            union all
            select value->>'path' other_path from jsonb_array_elements(contract->'forbidden_paths')) others
            where paths.path<>others.other_path
              and ops.canonical_ownership_path_case_alias(paths.path,others.other_path)))
     or exists(select 1 from jsonb_array_elements(contract->'path_claims') a,
                    jsonb_array_elements(contract->'forbidden_paths') f
                where a->>'path'=f->>'path'
                   or left(a->>'path',length(f->>'path')+1)=f->>'path'||'/'
                   or left(f->>'path',length(a->>'path')+1)=a->>'path'||'/') then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','compiler_input.assurance_slice.scope',
      '"exact A2 claims/dependencies and non-overlapping forbidden paths"'::jsonb,'"mismatch"'::jsonb);
  end if;
  if jsonb_array_length(selected->'planned_checks')<>1
     or jsonb_array_length(contract->'required_tests')<>1 then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.required_tests',
      '"one compiler-registered planned check"'::jsonb,'"invalid"'::jsonb);
  end if;
  planned_check:=selected->'planned_checks'->0;
  required_test:=contract->'required_tests'->0;
  if planned_check->>'check_ref' is distinct from 'check:compiler'
     or not coalesce(ops.assurance_exact_object(required_test,array[
       'check_ref','planned_check_digest','check_profile_ref','runner','test_artifact',
       'environment','environment_gate','argv','cwd','causal_failure','evidence_fields']),false)
     or required_test->>'check_ref' is distinct from 'check:compiler'
     or required_test->>'planned_check_digest' is distinct from ops.assurance_digest(planned_check)
     or required_test->>'check_profile_ref' is distinct from 'check-profile:assurance-compiler-v1'
     or required_test->>'runner' is distinct from 'python_pytest'
     or required_test->'argv' is distinct from
        '["python3","-m","pytest","-q","tools/test-assurance-slice-compiler.py"]'::jsonb
     or required_test->>'cwd' is distinct from '.'
     or required_test->'environment_gate' is distinct from
        '{"argv":["python3","-c","import pytest"],"must_pass_before_test":true,
          "causal_failure":{"code":"TEST_ENVIRONMENT_NOT_MATERIALIZED",
          "object":"environment:repository-python-lock",
          "expected":"pytest importable from requirements.lock"}}'::jsonb
     or not coalesce(ops.assurance_exact_object(required_test->'test_artifact',array['path','digest']),false)
     or required_test#>>'{test_artifact,path}' is distinct from 'tools/test-assurance-slice-compiler.py'
     or not coalesce(required_test#>>'{test_artifact,digest}' ~ '^sha256:[0-9a-f]{64}$',false)
     or not coalesce(ops.assurance_exact_object(required_test->'environment',
          array['environment_ref','runtime','version_source','dependency_lock']),false)
     or not coalesce(ops.assurance_exact_object(required_test#>'{environment,version_source}',
          array['path','digest']),false)
     or not coalesce(ops.assurance_exact_object(required_test#>'{environment,dependency_lock}',
          array['path','digest']),false)
     or required_test#>>'{environment,environment_ref}' is distinct from 'environment:repository-python-lock'
     or required_test#>>'{environment,runtime}' is distinct from 'python3'
     or required_test#>>'{environment,version_source,path}' is distinct from '.python-version'
     or required_test#>>'{environment,dependency_lock,path}' is distinct from 'requirements.lock'
     or not coalesce(required_test#>>'{environment,version_source,digest}' ~ '^sha256:[0-9a-f]{64}$',false)
     or not coalesce(required_test#>>'{environment,dependency_lock,digest}' ~ '^sha256:[0-9a-f]{64}$',false)
     or required_test->'causal_failure' is distinct from jsonb_build_object(
          'code','REQUIRED_CHECK_FAILED','object','check:compiler',
          'expected',planned_check->>'failure_condition')
     or jsonb_typeof(required_test->'evidence_fields') is distinct from 'array'
     or jsonb_array_length(required_test->'evidence_fields')=0
     or required_test->'evidence_fields' is distinct from
        ops.assurance_sorted_strings(required_test->'evidence_fields')
     or exists(select 1 from jsonb_array_elements(required_test->'evidence_fields') x
                where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')
     or (select count(*) from jsonb_array_elements(required_test->'evidence_fields'))<>
        (select count(distinct x#>>'{}') from jsonb_array_elements(required_test->'evidence_fields') x) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.required_tests.check:compiler',
      '"exact compiler-registered check refinement"'::jsonb,'"invalid"'::jsonb);
  end if;
  if jsonb_array_length(contract->'evidence_requirements')=0
     or exists(select 1 from jsonb_array_elements(contract->'evidence_requirements') x
       where not coalesce(ops.assurance_exact_object(x,array[
          'evidence_ref','artifact_kind','required_fields']),false)
          or not ops.assurance_identifier_valid(x->>'evidence_ref')
          or not ops.assurance_identifier_valid(x->>'artifact_kind')
          or jsonb_typeof(x->'required_fields')<>'array'
          or jsonb_array_length(x->'required_fields')=0
          or exists(select 1 from jsonb_array_elements(x->'required_fields') f
                     where jsonb_typeof(f)<>'string'
                        or btrim(f#>>'{}')='')
          or (select count(*) from jsonb_array_elements(x->'required_fields'))<>
             (select count(distinct f#>>'{}') from jsonb_array_elements(x->'required_fields') f))
     or exists(select 1 from jsonb_array_elements(contract->'evidence_requirements') x
               group by x->>'evidence_ref' having count(*)>1)
     or not coalesce(ops.assurance_exact_object(contract->'reviewer_policy',array[
          'minimum_independent_reviewers','executor_actor_ref','executor_session_ref',
          'owner_acceptance_is_review','distinct_actor_and_session']),false)
     or jsonb_typeof(contract#>'{reviewer_policy,minimum_independent_reviewers}')<>'number'
     or not coalesce(contract#>>'{reviewer_policy,minimum_independent_reviewers}'~'^[1-9][0-9]*$',false)
     or contract#>'{reviewer_policy,owner_acceptance_is_review}' is distinct from 'false'::jsonb
     or contract#>'{reviewer_policy,distinct_actor_and_session}' is distinct from 'true'::jsonb
     or contract#>>'{reviewer_policy,executor_actor_ref}' is distinct from 'actor:'||l.holder_actor_slug
     or contract#>>'{reviewer_policy,executor_session_ref}' is distinct from l.holder_session_ref
     or not coalesce(ops.assurance_exact_object(contract->'observable_output',
          array['description','evidence_ref']),false)
     or jsonb_typeof(contract#>'{observable_output,description}')<>'string'
     or not coalesce(btrim(contract#>>'{observable_output,description}')<>'',false)
     or not ops.assurance_identifier_valid(contract#>>'{observable_output,evidence_ref}')
     or not coalesce(ops.assurance_exact_object(contract->'rollback',
          array['strategy','argv','cwd','observable_success']),false)
     or jsonb_typeof(contract#>'{rollback,strategy}')<>'string'
     or not coalesce(btrim(contract#>>'{rollback,strategy}')<>'',false)
     or jsonb_typeof(contract#>'{rollback,argv}')<>'array'
     or jsonb_array_length(contract#>'{rollback,argv}')=0
     or exists(select 1 from jsonb_array_elements(contract#>'{rollback,argv}') x
                where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')
     or jsonb_typeof(contract#>'{rollback,cwd}') is distinct from 'string'
     or not coalesce(ops.canonical_ownership_path_valid(contract#>>'{rollback,cwd}'),false)
     or jsonb_typeof(contract#>'{rollback,observable_success}')<>'string'
     or not coalesce(btrim(contract#>>'{rollback,observable_success}')<>'',false)
     or jsonb_typeof(contract->'release_class') is distinct from 'string'
     or not coalesce(contract->>'release_class'=any(array['none','repository_only','runtime','production']),false)
     or exists(select 1 from jsonb_array_elements(contract->'unfinished_work') x
                where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')
     or not coalesce(ops.assurance_exact_object(contract->'repository_binding',
          array['repository_id','commit_sha','tree_sha']),false)
     or not coalesce(ops.assurance_exact_object(contract->'rule_snapshot_binding',
          array['snapshot_ref','snapshot_digest']),false)
     or not coalesce(ops.assurance_exact_object(contract->'lease_binding',
          array['lease_id','fencing_generation','holder_session_id','holder_host_id']),false)
     or jsonb_typeof(contract#>'{lease_binding,fencing_generation}')<>'number'
     or not ops.assurance_identifier_valid(contract#>>'{lease_binding,lease_id}')
     or not ops.assurance_identifier_valid(contract#>>'{lease_binding,holder_session_id}')
     or not ops.assurance_identifier_valid(contract#>>'{lease_binding,holder_host_id}')
     or not coalesce(ops.assurance_exact_object(contract->'executor_identity',
          array['actor_ref','session_ref','host_ref']),false)
     or not ops.assurance_identifier_valid(contract#>>'{executor_identity,actor_ref}')
     or not ops.assurance_identifier_valid(contract#>>'{executor_identity,session_ref}')
     or not ops.assurance_identifier_valid(contract#>>'{executor_identity,host_ref}')
     or contract#>>'{lease_binding,lease_id}' is distinct from 'lease:'||l.id::text
     or (contract#>>'{lease_binding,fencing_generation}')::bigint is distinct from l.fencing_generation
     or contract#>>'{lease_binding,holder_session_id}' is distinct from l.holder_session_ref
     or contract#>>'{lease_binding,holder_host_id}' is distinct from l.holder_host_ref
     or contract#>>'{executor_identity,actor_ref}' is distinct from 'actor:'||l.holder_actor_slug
     or contract#>>'{executor_identity,session_ref}' is distinct from l.holder_session_ref
     or contract#>>'{executor_identity,host_ref}' is distinct from l.holder_host_ref then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.assurance_slice.contract',
      '"complete typed A1a contract"'::jsonb,'"invalid"'::jsonb);
  end if;
  if contract->>'ownership_contract_digest' is distinct from
        ops.assurance_digest(contract-array['contract_digest','ownership_contract_digest','lease_binding']) then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH',
      'compiler_input.assurance_slice.ownership_contract_digest',
      to_jsonb(ops.assurance_digest(
        contract-array['contract_digest','ownership_contract_digest','lease_binding'])),
      contract->'ownership_contract_digest');
  end if;
  if contract->>'contract_digest' is distinct from
       ops.assurance_digest(contract-'contract_digest') then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','compiler_input.assurance_slice.contract_digest',
      to_jsonb(ops.assurance_digest(contract-'contract_digest')),
      contract->'contract_digest');
  end if;
  if not coalesce(ops.assurance_exact_object(rules,array[
       'schema_version','snapshot_ref','snapshot_digest','rules']),false)
     or rules->>'schema_version' is distinct from 'applicable-rule-snapshot.v1'
     or not ops.assurance_identifier_valid(rules->>'snapshot_ref')
     or jsonb_typeof(rules->'rules') is distinct from 'array'
     or not coalesce(ops.assurance_unique_array(rules->'rules'),false)
     or rules->'rules' is distinct from ops.assurance_normalized_set(rules->'rules')
     or exists(select 1 from jsonb_array_elements(rules->'rules') x
       where not coalesce(ops.assurance_exact_object(x,array['rule_ref','revision','digest']),false)
          or not ops.assurance_identifier_valid(x->>'rule_ref')
          or jsonb_typeof(x->'revision')<>'number'
          or not coalesce((x->>'revision') ~ '^[1-9][0-9]*$',false)
          or not coalesce(x->>'digest' ~ '^sha256:[0-9a-f]{64}$',false))
     or exists(select 1 from jsonb_array_elements(rules->'rules') x
               group by x->>'rule_ref' having count(*)>1)
     or rules->>'snapshot_digest' is distinct from ops.assurance_digest(
          jsonb_build_object('snapshot_ref',rules->'snapshot_ref','rules',rules->'rules'))
     or contract#>>'{rule_snapshot_binding,snapshot_ref}' is distinct from rules->>'snapshot_ref'
     or contract#>>'{rule_snapshot_binding,snapshot_digest}' is distinct from rules->>'snapshot_digest' then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.applicable_rules',
      '"unique normalized typed rule snapshot"'::jsonb,'"invalid"'::jsonb);
  end if;
  lease_expires_text:=to_char(l.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
  select coalesce(jsonb_agg(value order by ops.assurance_digest(value)),'[]'::jsonb)
    into expected_leases from (
      select jsonb_build_object(
        'lease_id','lease:'||other.id::text,'state','active',
        'holder_session_id',other.holder_session_ref,'holder_host_id',other.holder_host_ref,
        'expires_at',to_char(other.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'fencing_generation',other.fencing_generation,
        'claims',(select coalesce(jsonb_agg(jsonb_build_object(
          'path',claim_value,'mode',claim_mode,'operation',operation)
          order by ops.assurance_digest(jsonb_build_object(
          'path',claim_value,'mode',claim_mode,'operation',operation))),'[]'::jsonb)
          from ops.canonical_ownership_claim c
         where c.lease_id=other.id and c.claim_kind='path')) value
        from ops.canonical_ownership_lease other
       where other.organization_tenant_id=l.organization_tenant_id
         and other.state='active' and other.expires_at>evaluation_at) live_rows;
  if not coalesce(ops.assurance_exact_object(coord,array[
       'schema_version','snapshot_digest','as_of','valid_until','manifest_phase',
       'requesting_session_id','requesting_host_id','leases','dependencies']),false)
     or coord->>'schema_version' is distinct from 'assurance-coordination-snapshot.v1'
     or coord->>'manifest_phase' is distinct from 'baseline'
     or coord->>'requesting_session_id' is distinct from l.holder_session_ref
     or coord->>'requesting_host_id' is distinct from l.holder_host_ref
     or jsonb_typeof(coord->'leases') is distinct from 'array'
     or jsonb_typeof(coord->'dependencies') is distinct from 'array'
     or not coalesce(ops.assurance_unique_array(coord->'leases'),false)
     or not coalesce(ops.assurance_unique_array(coord->'dependencies'),false)
     or coord->'leases' is distinct from ops.assurance_normalized_set(coord->'leases')
     or coord->'dependencies' is distinct from ops.assurance_normalized_set(coord->'dependencies')
     or exists(select 1 from jsonb_array_elements(coord->'leases') x
       where not coalesce(ops.assurance_exact_object(x,array[
         'lease_id','state','holder_session_id','holder_host_id','expires_at',
         'fencing_generation','claims']),false)
          or x->>'state'<>all(array['active','released'])
          or not ops.assurance_identifier_valid(x->>'lease_id')
          or not ops.assurance_identifier_valid(x->>'holder_session_id')
          or not ops.assurance_identifier_valid(x->>'holder_host_id')
          or not ops.assurance_timestamp_valid(x->>'expires_at')
          or jsonb_typeof(x->'fencing_generation')<>'number'
          or not coalesce((x->>'fencing_generation')~'^[1-9][0-9]*$',false)
          or jsonb_typeof(x->'claims')<>'array'
          or not coalesce(ops.assurance_unique_array(x->'claims'),false)
          or x->'claims' is distinct from ops.assurance_normalized_set(x->'claims'))
     or exists(select 1 from jsonb_array_elements(coord->'dependencies') x
       where not coalesce(ops.assurance_exact_object(x,array[
         'slice_ref','state','evidence_digest']),false)
          or not ops.assurance_identifier_valid(x->>'slice_ref')
          or x->>'state'<>all(array['pending','completed','independently_verified'])
          or (x->'evidence_digest'<>'null'::jsonb
              and not coalesce(x->>'evidence_digest'~'^sha256:[0-9a-f]{64}$',false)))
     or exists(select 1 from jsonb_array_elements(coord->'leases') x
               group by x->>'lease_id' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(coord->'dependencies') x
               group by x->>'slice_ref' having count(*)>1)
     or coord->'leases' is distinct from expected_leases
     or coord->'dependencies' is distinct from expected_coord_dependencies
     or not ops.assurance_timestamp_valid(coord->>'as_of')
     or not ops.assurance_timestamp_valid(coord->>'valid_until')
     or coord->>'snapshot_digest' is distinct from ops.assurance_digest(coord-'snapshot_digest') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.coordination_snapshot',
      '"exact normalized live A2 coordination snapshot"'::jsonb,'"invalid"'::jsonb);
  end if;
  snapshot_as_of:=(coord->>'as_of')::timestamptz;
  snapshot_until:=(coord->>'valid_until')::timestamptz;
  if snapshot_until<=snapshot_as_of or evaluation_at<snapshot_as_of
     or evaluation_at>=snapshot_until or clock_timestamp()>=snapshot_until
     or snapshot_until>l.expires_at then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','compiler_input.coordination_snapshot.valid_until',
      '"as_of <= evaluation < valid_until <= live lease expiry"'::jsonb,'"outside current window"'::jsonb);
  end if;
  if p_compiler_input is distinct from jsonb_build_object(
       'schema_version',p_compiler_input->'schema_version',
       'work_request',p_compiler_input->'work_request',
       'accepted_plan_revision',p_compiler_input->'accepted_plan_revision',
       'engineering_slice_plan',p_compiler_input->'engineering_slice_plan',
       'assurance_slice',contract,'repository',p_compiler_input->'repository',
       'applicable_rules',rules,'coordination_snapshot',coord,
       'declared_evaluation_time',p_compiler_input->'declared_evaluation_time') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.normalization',
      '"canonical normalized input"'::jsonb,'"noncanonical"'::jsonb);
  end if;
  expected_slice:=jsonb_build_object(
    'slice_ref',contract->'slice_ref','objective',selected->'objective',
    'outcome',contract->'outcome','risk',contract->'risk',
    'allowed_paths',contract->'path_claims','forbidden_paths',contract->'forbidden_paths',
    'dependency_gates',contract->'dependencies','required_tests',contract->'required_tests',
    'evidence_requirements',contract->'evidence_requirements',
    'reviewer_policy',contract->'reviewer_policy','observable_output',contract->'observable_output',
    'rollback',contract->'rollback','release_class',contract->'release_class',
    'unfinished_work',contract->'unfinished_work','lease_binding',contract->'lease_binding',
    'executor_identity',contract->'executor_identity');
  expected_currentness:=jsonb_build_object(
    'manifest_phase','baseline','authorizes_action',false,
    'currentness_state','declared_window_consistent_not_live_verified',
    'live_currentness_verified',false,
    'declared_evaluation_time',p_compiler_input->'declared_evaluation_time',
    'snapshot_as_of',coord->'as_of','snapshot_valid_until',coord->'valid_until',
    'lease_expires_at',to_jsonb(lease_expires_text),
    'usable_only_as_preflight_for','[]'::jsonb,
    'requires_live_currentness_check_before',
      '["write","test","commit","push","pr_update","review","merge","runtime_action"]'::jsonb,
    'recompile_against_resulting_commit_tree_before',
      '["commit","push","pr_update","review","merge","runtime_action"]'::jsonb);
  expected_base:=jsonb_build_object(
    'schema_version','assurance-execution-manifest.v1',
    'compiler',jsonb_build_object('id','carr-assurance-slice-compiler','version','1.1.0'),
    'authority_state','compiled_not_authorized','verification_state','unverified',
    'self_certification',false,'input_digest',ops.assurance_digest(p_compiler_input),
    'input_bindings',jsonb_build_object(
      'work_request',p_compiler_input->'work_request',
      'accepted_plan_revision',p_compiler_input->'accepted_plan_revision',
      'engineering_slice_plan_digest',to_jsonb(sp.plan_digest),
      'assurance_slice_ownership_contract_digest',contract->'ownership_contract_digest',
      'assurance_slice_contract_digest',contract->'contract_digest',
      'repository',p_compiler_input->'repository',
      'applicable_rule_snapshot_digest',rules->'snapshot_digest',
      'coordination_snapshot_digest',coord->'snapshot_digest'),
    'slice',expected_slice,'currentness',expected_currentness,
    'refusal_vocabulary','["INPUT_NOT_OBJECT","INPUT_UNKNOWN_FIELD","INPUT_MISSING_FIELD",
      "INPUT_SCHEMA_UNSUPPORTED","FIELD_INVALID","ENGINEERING_SLICE_PLAN_INVALID",
      "ASSURANCE_SLICE_ABSENT","OWNERSHIP_CONTRACT_DIGEST_MISMATCH",
      "ASSURANCE_CONTRACT_DIGEST_MISMATCH",
      "WORK_REQUEST_BINDING_MISMATCH","ACCEPTED_PLAN_BINDING_MISMATCH",
      "ENGINEERING_SLICE_PLAN_BINDING_MISMATCH","SLICE_BINDING_MISMATCH",
      "REPOSITORY_IDENTITY_MISMATCH","RULE_SNAPSHOT_DIGEST_MISMATCH",
      "RULE_SNAPSHOT_STALE","COORDINATION_SNAPSHOT_DIGEST_MISMATCH",
      "COORDINATION_SNAPSHOT_STALE","LEASE_NOT_FOUND","LEASE_RELEASED","LEASE_EXPIRED",
      "LEASE_BINDING_MISMATCH","REQUESTER_IDENTITY_MISMATCH","LEASE_CLAIMS_MISMATCH",
      "FOREIGN_LEASE_COLLISION","DEPENDENCY_MISSING","DEPENDENCY_UNSATISFIED","PATH_INVALID",
      "PATH_CASE_ALIAS","PATH_SCOPE_COLLISION","REQUIRED_TEST_BINDING_MISMATCH",
      "REVIEWER_POLICY_INVALID","COMPILER_INTERNAL_ERROR"]'::jsonb);
  expected_manifest:=expected_base||jsonb_build_object(
    'manifest_hash',ops.assurance_digest(expected_base));
  if p_manifest is distinct from expected_manifest then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','manifest.compiler_output',
      jsonb_build_object('manifest_hash',expected_manifest->'manifest_hash',
        'input_digest',expected_manifest->'input_digest'),
      jsonb_build_object('exact_compiler_output',false));
  end if;
  return jsonb_build_object('ok',true,'input_digest',p_manifest->'input_digest',
    'manifest_hash',p_manifest->'manifest_hash');
exception when others then
  return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','compiler_input.typed_shape',
    '"well-typed recursively closed A1a input"'::jsonb,
    jsonb_build_object('sqlstate',sqlstate));
end $_$;


--
-- Name: attempt_receipt_binding_valid(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attempt_receipt_binding_valid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare binding ops.context_activation_binding%rowtype; envelope_row ops.execution_envelope_v1%rowtype; expected_unresolved jsonb; expected_closure_state text;
  disposition jsonb; reliability jsonb; expected_reliability_state text; expected_reliability_reasons jsonb; required_evaluator_kinds text[]; held_out_count integer;
begin
  select * into binding from ops.context_activation_binding where id=new.activation_binding_id;
  select * into envelope_row from ops.execution_envelope_v1 where id=new.execution_envelope_id;
  if not found or binding.organization_tenant_id is distinct from new.organization_tenant_id
     or binding.work_request_id is distinct from new.work_request_id
     or binding.plan_hash is distinct from new.plan_hash
     or binding.expires_at < now()
     or exists (select 1 from ops.work_request current_work where current_work.id=binding.work_request_id and (current_work.version<>binding.work_request_version or current_work.organization_tenant_id<>binding.organization_tenant_id))
     or envelope_row.organization_tenant_id is distinct from new.organization_tenant_id
     or envelope_row.work_request_id is distinct from new.work_request_id
     or envelope_row.plan_hash is distinct from new.plan_hash
     or envelope_row.activation_binding_id is distinct from binding.id
     or envelope_row.envelope_digest is distinct from new.envelope_digest
     or envelope_row.expires_at < now()
     or jsonb_typeof(new.receipt) is distinct from 'object'::text
     or new.receipt->>'schema_version' <> 'attempt-receipt.v1'
     or new.receipt->>'envelope_digest' is distinct from new.envelope_digest
     or new.receipt->>'attempt_id' is distinct from new.attempt_id
     or not (new.receipt ?& array['schema_version','attempt_id','envelope_digest','attempt_ordinal','adapter','lifecycle','result','attestation','negative_knowledge','telemetry','tool_event_summaries','observation','interventions','handoff_proposal','visual_artifacts','evaluation_binding'])
     or exists (select 1 from jsonb_object_keys(new.receipt) key where key <> all(array['schema_version','attempt_id','envelope_digest','attempt_ordinal','adapter','lifecycle','result','attestation','negative_knowledge','telemetry','tool_event_summaries','observation','interventions','handoff_proposal','visual_artifacts','evaluation_binding','knowledge_activation','reliability']))
     or ops.attempt_receipt_contains_raw_content(new.receipt)
     or not (new.receipt ?& array['knowledge_activation','reliability'])
     or coalesce(new.receipt->'knowledge_activation'->'closure'->>'derived_by','') <> 'server' then
    raise exception 'attempt receipt is cross-bound, malformed, or contains raw content';
  end if;
  -- A `derived_by: server` label is not proof.  Recompute the required-item
  -- closure from the immutable activation rows and reject any forged or stale
  -- nested receipt before it is admitted.
  if jsonb_typeof(new.receipt->'knowledge_activation') <> 'object'
     or not (new.receipt->'knowledge_activation' ?& array['bundle_digest','item_dispositions','closure','mode','canonical_binding'])
     or exists (select 1 from jsonb_object_keys(new.receipt->'knowledge_activation') key where key <> all(array['bundle_digest','item_dispositions','closure','mode','canonical_binding']))
     or jsonb_typeof(new.receipt->'knowledge_activation'->'canonical_binding') <> 'object'
     or not (new.receipt->'knowledge_activation'->'canonical_binding' ?& array['work_request_id','work_request_version','accepted_plan_digest','envelope_digest','activation_binding_ref'])
     or exists (select 1 from jsonb_object_keys(new.receipt->'knowledge_activation'->'canonical_binding') key where key <> all(array['work_request_id','work_request_version','accepted_plan_digest','envelope_digest','activation_binding_ref']))
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'work_request_id' <> (select ref from ops.work_request where id=binding.work_request_id)
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'work_request_version' <> binding.work_request_version::text
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'accepted_plan_digest' <> binding.plan_hash
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'envelope_digest' <> new.envelope_digest
     or new.receipt->'knowledge_activation'->'canonical_binding'->>'activation_binding_ref' <> binding.binding_id
     or new.receipt->'knowledge_activation'->>'bundle_digest' <> binding.bundle_digest
     or jsonb_typeof(new.receipt->'knowledge_activation'->'item_dispositions') <> 'array'
     or (select count(*) from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions'))
          <> (select count(*) from ops.context_activation_item where binding_id=binding.id)
     or exists (
       select 1 from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
        where jsonb_typeof(d) <> 'object'
           or not (d ?& array['item_ref','disposition','evidence_refs','reason_ref'])
           or exists (select 1 from jsonb_object_keys(d) key where key <> all(array['item_ref','disposition','evidence_refs','reason_ref','stage_ref','tool_ref']))
           or d->>'disposition' not in ('applied','not_applicable','conflicted','stale','missing')
           or jsonb_typeof(d->'evidence_refs') <> 'array'
           or coalesce(d->>'reason_ref','') !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
           or (d->>'disposition'='applied' and (jsonb_array_length(d->'evidence_refs')=0 or not (d ?| array['stage_ref','tool_ref'])))
     )
     or exists (
       select 1 from ops.context_activation_item i
       left join lateral (
         select d from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
          where d->>'item_ref'=i.canonical_ref limit 1
       ) supplied on true
       where i.binding_id=binding.id and supplied.d is null
          or (i.binding_id=binding.id and i.required and coalesce(supplied.d->>'disposition','missing') <> 'applied'
              and (jsonb_typeof(supplied.d->'evidence_refs') <> 'array' or jsonb_array_length(supplied.d->'evidence_refs')=0))
     ) then
    raise exception 'attempt receipt knowledge activation is not exactly bound';
  end if;
  select coalesce(jsonb_agg(i.canonical_ref order by i.canonical_ref),'[]'::jsonb)
    into expected_unresolved
    from ops.context_activation_item i
    left join lateral (
      select d from jsonb_array_elements(new.receipt->'knowledge_activation'->'item_dispositions') d
       where d->>'item_ref'=i.canonical_ref limit 1
    ) disposition on true
   where i.binding_id=binding.id and i.required
     and coalesce(disposition.d->>'disposition','missing') <> 'applied';
  expected_closure_state := case when binding.mode='shadow' then 'not_activated'
    when expected_unresolved='[]'::jsonb then 'closed' else 'blocked' end;
  if new.receipt->'knowledge_activation'->'closure'->'unresolved_required_item_refs' is distinct from expected_unresolved
     or new.receipt->'knowledge_activation'->'closure'->>'state' is distinct from expected_closure_state then
    raise exception 'attempt receipt knowledge closure was not server-derived';
  end if;
  reliability := new.receipt->'reliability';
  if jsonb_typeof(reliability) <> 'object'
     or not (reliability ?& array['route_digest','topology_digest','evaluation_plan_digest','grounding_sufficiency','deterministic_checks','model_judgement','human_acceptance','trajectory','evaluator_results','corrections','defects','incidents','downstream_outcome','outcome_horizon','process_metrics','eval_candidates','shadow_comparisons','learning_disposition','telemetry','closure'])
     or exists (select 1 from jsonb_object_keys(reliability) key where key <> all(array['route_digest','topology_digest','evaluation_plan_digest','grounding_sufficiency','deterministic_checks','model_judgement','human_acceptance','trajectory','evaluator_results','corrections','defects','incidents','downstream_outcome','outcome_horizon','process_metrics','eval_candidates','shadow_comparisons','learning_disposition','telemetry','closure','environment_binding_digest','environment_evidence']))
     or jsonb_typeof(reliability->'deterministic_checks') <> 'array'
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where jsonb_typeof(check_row) <> 'object' or not (check_row ?& array['check_id','state','critical','evidence_refs']) or check_row->>'check_id' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or check_row->>'state' not in ('passed','failed','unknown','not_run') or jsonb_typeof(check_row->'critical')<>'boolean' or jsonb_typeof(check_row->'evidence_refs')<>'array')
     or jsonb_typeof(reliability->'trajectory') <> 'array'
     or exists (select 1 from jsonb_array_elements(reliability->'trajectory') trace_row where jsonb_typeof(trace_row) <> 'object' or not (trace_row ?& array['sequence','stage_ref','parent_event_ref','decision_class','tool_class','result_state','fallback_state','guardrail_state','latency_ms','evidence_refs']) or exists (select 1 from jsonb_object_keys(trace_row) key where key <> all(array['sequence','stage_ref','parent_event_ref','decision_class','tool_class','result_state','fallback_state','guardrail_state','latency_ms','evidence_refs'])))
     or jsonb_typeof(reliability->'evaluator_results') <> 'array' or jsonb_array_length(reliability->'evaluator_results')=0
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where jsonb_typeof(evaluator) <> 'object' or not (evaluator ?& array['kind','evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','status','confidence','critical','independence_state','held_out_case_count','check_refs','dimension_refs','evidence_refs','judge_provenance','calibration_evidence_refs']) or exists (select 1 from jsonb_object_keys(evaluator) key where key <> all(array['kind','evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','status','confidence','critical','independence_state','held_out_case_count','check_refs','dimension_refs','evidence_refs','judge_provenance','calibration_evidence_refs'])) or evaluator->>'kind' not in ('deterministic','judge','human_acceptance') or evaluator->>'status' not in ('passed','failed','blocked','unknown','not_run') or evaluator->>'independence_state' not in ('not_independent','unknown') or jsonb_typeof(evaluator->'held_out_case_count')<>'number' or (evaluator->>'held_out_case_count')::integer<0 or jsonb_typeof(evaluator->'check_refs')<>'array' or jsonb_typeof(evaluator->'dimension_refs')<>'array')
     or jsonb_typeof(reliability->'grounding_sufficiency') <> 'object' or not (reliability->'grounding_sufficiency' ?& array['state','evidence_refs','required_supplied','required_used','required_missing','advisory_supplied','advisory_used','freshness_failures','retrieval_failures'])
     -- Learning facts are canonical, redacted metadata.  The executor cannot
     -- smuggle a candidate, free-text case body, or a fact into the wrong lane.
     or jsonb_typeof(reliability->'eval_candidates') <> 'array' or jsonb_array_length(reliability->'eval_candidates') <> 0
     -- Executor receipts cannot carry a shadow route or its side-effect
     -- claims. Governed shadows are admitted only by Policy Learning.
     or jsonb_typeof(reliability->'shadow_comparisons') <> 'array' or jsonb_array_length(reliability->'shadow_comparisons') <> 0
     or exists (select 1 from jsonb_array_elements(reliability->'corrections') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'correction' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or exists (select 1 from jsonb_array_elements(reliability->'defects') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'defect' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or exists (select 1 from jsonb_array_elements(reliability->'incidents') event_row where jsonb_typeof(event_row)<>'object' or not (event_row ?& array['event_ref','kind','evidence_refs','summary']) or exists(select 1 from jsonb_object_keys(event_row) key where key<>all(array['event_ref','kind','evidence_refs','summary'])) or event_row->>'kind'<>'incident' or event_row->>'event_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or event_row->>'summary' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or jsonb_typeof(event_row->'evidence_refs')<>'array' or jsonb_array_length(event_row->'evidence_refs')=0)
     or jsonb_typeof(reliability->'human_acceptance')<>'object' or not (reliability->'human_acceptance' ?& array['state','actor_ref','evidence_refs','outcome_feedback_ref','outcome_feedback_hash'])
     or reliability->'human_acceptance'->>'state' not in ('accepted','rejected','absent','unknown')
     or (reliability->'human_acceptance'->>'state'='accepted' and (reliability->'human_acceptance'->>'outcome_feedback_ref' is null or reliability->'human_acceptance'->>'outcome_feedback_hash' !~ '^sha256:[0-9a-f]{64}$'))
     or (reliability->'human_acceptance'->>'state'<>'accepted' and ((reliability->'human_acceptance'->'outcome_feedback_ref')<>'null'::jsonb or (reliability->'human_acceptance'->'outcome_feedback_hash')<>'null'::jsonb))
     or jsonb_typeof(reliability->'downstream_outcome')<>'object' or not (reliability->'downstream_outcome' ?& array['state','brokerage_ref','evidence_refs','outcome_feedback_ref','outcome_feedback_hash'])
     or reliability->'downstream_outcome'->>'state' not in ('observed','not_observed','unknown')
     or (reliability->'downstream_outcome'->>'state'='observed' and (reliability->'downstream_outcome'->>'outcome_feedback_ref' is null or reliability->'downstream_outcome'->>'outcome_feedback_hash' !~ '^sha256:[0-9a-f]{64}$'))
     or (reliability->'downstream_outcome'->>'state'<>'observed' and ((reliability->'downstream_outcome'->'outcome_feedback_ref')<>'null'::jsonb or (reliability->'downstream_outcome'->'outcome_feedback_hash')<>'null'::jsonb))
     or jsonb_typeof(reliability->'outcome_horizon') <> 'object' or not (reliability->'outcome_horizon' ?& array['state','ends_at','as_of','evidence_refs'])
     or jsonb_typeof(reliability->'process_metrics') <> 'object' or not (reliability->'process_metrics' ?& array['latency_ms','cost_usd','input_tokens','output_tokens','cached_input_tokens','retry_count','recovery_count','context_reconstruction_ms','human_intervention_count','security_event_refs'])
     or jsonb_typeof(reliability->'closure') <> 'object' or not (reliability->'closure' ?& array['state','reasons','derived_by']) or reliability->'closure'->>'derived_by'<>'server'
     or jsonb_typeof(reliability->'telemetry') <> 'array' or jsonb_array_length(reliability->'telemetry') <> 0 then
    raise exception 'attempt receipt reliability extension is malformed';
  end if;
  if reliability ? 'route_digest' and reliability->>'route_digest' <> envelope_row.runtime_profile->>'digest'
     or reliability ? 'topology_digest' and reliability->>'topology_digest' <> envelope_row.execution_topology->>'digest'
     or reliability ? 'evaluation_plan_digest' and reliability->>'evaluation_plan_digest' <> envelope_row.evaluation_plan->>'digest' then
    raise exception 'attempt receipt route/topology/evaluation digests do not bind the server-issued envelope';
  end if;
  if (select coalesce(jsonb_agg(check_row->>'check_id' order by check_row->>'check_id'),'[]'::jsonb) from jsonb_array_elements(reliability->'deterministic_checks') check_row)
       is distinct from (select coalesce(jsonb_agg(value order by value),'[]'::jsonb) from jsonb_array_elements_text(envelope_row.evaluation_plan->'required_deterministic_check_refs') value)
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean is not true)
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'='deterministic' and (jsonb_array_length(evaluator->'check_refs')<>1 or evaluator->'dimension_refs' is distinct from envelope_row.evaluation_plan->'critical_dimensions'))
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'<>'deterministic' and (jsonb_array_length(evaluator->'check_refs')<>0 or evaluator->'dimension_refs' is distinct from envelope_row.evaluation_plan->'critical_dimensions')) then
    raise exception 'evaluation evidence does not exactly bind server-required checks and critical dimensions';
  end if;
  -- Executor-submitted actor/status labels are never acceptance evidence.  A
  -- claimed human acceptance/outcome must resolve to the existing immutable,
  -- human-authority Program 6 feedback receipt for this exact Work Request and
  -- accepted plan; absent/unknown feedback remains visibly unavailable.
  if reliability->'human_acceptance'->>'state'='accepted' and not exists (
    select 1 from ops.sourced_work_request_outcome_feedback f
      join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
      join public.actor a on a.id=fr.accepted_by_actor_id
     where f.work_request_id=new.work_request_id and f.plan_id=binding.plan_id
       and f.feedback_ref=reliability->'human_acceptance'->>'outcome_feedback_ref'
       and f.feedback_hash=reliability->'human_acceptance'->>'outcome_feedback_hash'
       and ('actor:'||a.slug)=reliability->'human_acceptance'->>'actor_ref'
  ) then raise exception 'attempt receipt human acceptance is not bound to accepted Work Request outcome feedback'; end if;
  if reliability->'downstream_outcome'->>'state'='observed' and (
    reliability->'downstream_outcome'->>'outcome_feedback_ref' is distinct from reliability->'human_acceptance'->>'outcome_feedback_ref'
    or reliability->'downstream_outcome'->>'outcome_feedback_hash' is distinct from reliability->'human_acceptance'->>'outcome_feedback_hash'
    or not exists (
      select 1 from ops.sourced_work_request_outcome_feedback f
        join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
       where f.work_request_id=new.work_request_id and f.plan_id=binding.plan_id
         and f.feedback_ref=reliability->'downstream_outcome'->>'outcome_feedback_ref'
         and f.feedback_hash=reliability->'downstream_outcome'->>'outcome_feedback_hash'
    )
  ) then raise exception 'attempt receipt observed outcome is not bound to accepted Work Request feedback'; end if;
  select coalesce(array_agg(value),array[]::text[]) into required_evaluator_kinds from jsonb_array_elements_text(envelope_row.evaluation_plan->'requirements'->'required_evaluator_kinds');
  select coalesce(sum((evaluator->>'held_out_case_count')::integer),0) into held_out_count from jsonb_array_elements(reliability->'evaluator_results') evaluator;
  if exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean and check_row->>'state'='failed')
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where (evaluator->>'critical')::boolean and evaluator->>'status' in ('failed','blocked')) then
    expected_reliability_state := 'blocked';
  elsif reliability->'grounding_sufficiency'->>'state'<>'sufficient'
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'outcome_horizon_required')::boolean,false) and reliability->'outcome_horizon'->>'state'<>'mature'
     or reliability->'model_judgement'->>'state'<>'pass'
     or exists (select 1 from jsonb_array_elements(reliability->'deterministic_checks') check_row where (check_row->>'critical')::boolean and check_row->>'state' in ('unknown','not_run'))
     or exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where (evaluator->>'critical')::boolean and evaluator->>'status' in ('unknown','not_run'))
     or exists (select 1 from unnest(required_evaluator_kinds) kind where not exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'kind'=kind))
     or held_out_count < coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_held_out_case_count')::integer,0)
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'independent_review_required')::boolean,false) and not exists (select 1 from jsonb_array_elements(reliability->'evaluator_results') evaluator where evaluator->>'independence_state'='independent')
     or coalesce((envelope_row.evaluation_plan->'requirements'->>'human_acceptance_required')::boolean,false) and reliability->'human_acceptance'->>'state'<>'accepted' then
    expected_reliability_state := 'insufficient_evidence';
  -- AttemptReceipt is executor evidence, never the authoritative evaluator
  -- event.  It cannot promote its own judge/held-out/calibration claims.
  else expected_reliability_state := 'insufficient_evidence';
  end if;
  if reliability->'closure'->>'state' is distinct from expected_reliability_state then
    raise exception 'attempt receipt reliability closure was not server-derived for attempt %, expected %, got %',new.attempt_id,expected_reliability_state,reliability->'closure'->>'state';
  end if;
  expected_reliability_reasons := case when expected_reliability_state='blocked' then
    jsonb_build_array('reason:authority_evaluation_evidence_missing','reason:critical_deterministic_or_evaluator_failure')
  else jsonb_build_array('reason:authority_evaluation_evidence_missing') end;
  if reliability->'closure'->'reasons' is distinct from expected_reliability_reasons then
    raise exception 'attempt receipt reliability closure reasons were not server-derived';
  end if;
  return new;
end $_$;


--
-- Name: attempt_receipt_contains_raw_content(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attempt_receipt_contains_raw_content(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare entry record;
begin
  if jsonb_typeof(p_value) = 'object' then
    -- Held-out expected outputs are evaluator material, not executor or
    -- Passport material.  Refuse them at the same recursive persistence
    -- boundary as prompts and tool bodies.
    if p_value ?| array['raw_prompt','raw_transcript','tool_payload','raw_output','prompt','transcript','expected_output','expected_answer','held_out_expected_output','held_out_answer'] then
      return true;
    end if;
    for entry in select value from jsonb_each(p_value) loop
      if ops.attempt_receipt_contains_raw_content(entry.value) then return true; end if;
    end loop;
  elsif jsonb_typeof(p_value) = 'array' then
    for entry in select value from jsonb_array_elements(p_value) loop
      if ops.attempt_receipt_contains_raw_content(entry.value) then return true; end if;
    end loop;
  elsif jsonb_typeof(p_value) = 'string' then
    -- This projection is an identifier/enumeration/timestamp/digest contract,
    -- never a prose transport.  A sentence cannot be made safe merely by
    -- changing its field name.
    if char_length(p_value #>> '{}') > 127 or (p_value #>> '{}') ~ '[[:space:]]' then return true; end if;
  end if;
  return false;
end $$;


--
-- Name: attest_attempt_receipt_evaluation(text, text, text, jsonb, text, boolean, jsonb, jsonb, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attest_attempt_receipt_evaluation(p_attempt_id text, p_evaluator_kind text, p_check_ref text, p_dimension_refs jsonb, p_status text, p_independent boolean, p_evidence_refs jsonb, p_evaluation_metadata jsonb, p_outcome_feedback_ref text, p_outcome_feedback_hash text, p_idempotency_key uuid) RETURNS TABLE(attestation_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id',true); receipt_row ops.attempt_receipt%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype; authority_actor actor%rowtype; existing ops.attempt_receipt_evaluation_attestation%rowtype;
  derived_horizon text; accepted_feedback boolean;
begin
  if session_user !~ '^carr_authority_' then raise exception 'evaluation attestation requires human authority'; end if;
  select * into authority_actor from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  select * into receipt_row from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id for share;
  select * into envelope_row from ops.execution_envelope_v1 where id=receipt_row.execution_envelope_id and organization_tenant_id=tenant for share;
  if authority_actor.id is null or receipt_row.id is null or envelope_row.id is null
     or jsonb_typeof(p_dimension_refs)<>'array' or jsonb_array_length(p_dimension_refs)=0
     or jsonb_typeof(p_evidence_refs)<>'array' or jsonb_array_length(p_evidence_refs)=0
     or jsonb_typeof(p_evaluation_metadata)<>'object'
     or not (p_evaluation_metadata ?& array['evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','confidence','held_out_case_count','calibration_refs','lower_bound_ref'])
     or exists (select 1 from jsonb_object_keys(p_evaluation_metadata) k where k <> all(array['evaluator_ref','rubric_ref','evaluator_version','evaluator_digest','confidence','held_out_case_count','calibration_refs','lower_bound_ref']))
     or p_evaluation_metadata->>'evaluator_ref' <> envelope_row.evaluation_plan->>'evaluator_ref'
     or p_evaluation_metadata->>'rubric_ref' <> envelope_row.evaluation_plan->>'rubric_ref'
     or p_evaluation_metadata->>'evaluator_version' <> envelope_row.evaluation_plan->>'evaluator_version'
     or p_evaluation_metadata->>'evaluator_digest' <> envelope_row.evaluation_plan->>'evaluator_digest'
     or p_evaluation_metadata->>'confidence' not in ('high','medium','low','unknown')
     or jsonb_typeof(p_evaluation_metadata->'held_out_case_count') <> 'number' or (p_evaluation_metadata->>'held_out_case_count')::integer < 0
     or jsonb_typeof(p_evaluation_metadata->'calibration_refs') <> 'array'
     or ops.attempt_receipt_contains_raw_content(p_evidence_refs) or ops.attempt_receipt_contains_raw_content(p_evaluation_metadata)
     or p_evaluator_kind not in ('deterministic','judge','human_acceptance','outcome_horizon')
     or p_status not in ('passed','failed','blocked','unknown','not_run','mature','immature')
     or p_dimension_refs is distinct from envelope_row.evaluation_plan->'critical_dimensions' then
    raise exception 'evaluation attestation lacks exact canonical binding';
  end if;
  if (p_evaluator_kind='deterministic' and (p_check_ref='' or not ((envelope_row.evaluation_plan->'required_deterministic_check_refs') ? p_check_ref) or p_status not in ('passed','failed','blocked','unknown','not_run')))
     or (p_evaluator_kind<>'deterministic' and p_check_ref<>'')
     or (p_evaluator_kind='judge' and p_status not in ('passed','failed','blocked','unknown','not_run'))
     or (p_evaluator_kind='human_acceptance' and p_status not in ('passed','failed','blocked','unknown','not_run'))
     or (p_evaluator_kind='outcome_horizon' and p_status not in ('mature','immature'))
     or (p_evaluator_kind='judge' and not p_independent)
     or (p_evaluator_kind<>'judge' and p_independent) then
    raise exception 'evaluation attestation kind/check/status/independence is invalid';
  end if;
  select exists (
    select 1 from ops.sourced_work_request_outcome_feedback f join ops.sourced_work_request_outcome_feedback_acceptance_receipt accepted on accepted.feedback_id=f.id
      where f.work_request_id=receipt_row.work_request_id and f.plan_id=(select plan_id from ops.context_activation_binding where id=receipt_row.activation_binding_id)
        and f.feedback_ref=p_outcome_feedback_ref and f.feedback_hash=p_outcome_feedback_hash
  ) into accepted_feedback;
  if p_evaluator_kind in ('human_acceptance','outcome_horizon') and (not accepted_feedback or p_outcome_feedback_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or p_outcome_feedback_hash !~ '^sha256:[0-9a-f]{64}$') then
    raise exception 'authority attestation requires exact accepted Program 6 outcome feedback';
  elsif p_evaluator_kind not in ('human_acceptance','outcome_horizon') and (p_outcome_feedback_ref is not null or p_outcome_feedback_hash is not null) then
    raise exception 'only outcome-bound authority facts may name Program 6 feedback';
  end if;
  derived_horizon := case when clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz then 'mature' else 'immature' end;
  if p_evaluator_kind='outcome_horizon' and p_status <> derived_horizon then
    raise exception 'outcome horizon is derived from the issued policy and database clock';
  end if;
  select * into existing from ops.attempt_receipt_evaluation_attestation where idempotency_key=p_idempotency_key for share;
  if found then
    if existing.attempt_receipt_id<>receipt_row.id or existing.evaluator_kind<>p_evaluator_kind or existing.check_ref<>p_check_ref or existing.dimension_refs is distinct from p_dimension_refs or existing.status<>p_status or existing.independent<>p_independent or existing.evidence_refs is distinct from p_evidence_refs or existing.evaluator_ref<>p_evaluation_metadata->>'evaluator_ref' or existing.rubric_ref<>p_evaluation_metadata->>'rubric_ref' or existing.evaluator_version<>p_evaluation_metadata->>'evaluator_version' or existing.evaluator_digest<>p_evaluation_metadata->>'evaluator_digest' or existing.confidence<>p_evaluation_metadata->>'confidence' or existing.held_out_case_count<>(p_evaluation_metadata->>'held_out_case_count')::integer or existing.calibration_refs is distinct from p_evaluation_metadata->'calibration_refs' or existing.lower_bound_ref is distinct from nullif(p_evaluation_metadata->>'lower_bound_ref','') or existing.outcome_feedback_ref is distinct from p_outcome_feedback_ref or existing.outcome_feedback_hash is distinct from p_outcome_feedback_hash then raise exception 'evaluation attestation idempotency conflict'; end if;
    return query select existing.id,true; return;
  end if;
  insert into ops.attempt_receipt_evaluation_attestation(organization_tenant_id,attempt_receipt_id,evaluator_kind,check_ref,dimension_refs,evaluator_policy_digest,evaluator_ref,rubric_ref,evaluator_version,evaluator_digest,confidence,held_out_case_count,calibration_refs,lower_bound_ref,outcome_feedback_ref,outcome_feedback_hash,status,independent,evidence_refs,attested_by_actor_id,idempotency_key)
  values(tenant,receipt_row.id,p_evaluator_kind,p_check_ref,p_dimension_refs,envelope_row.evaluation_plan->>'evaluator_policy_digest',p_evaluation_metadata->>'evaluator_ref',p_evaluation_metadata->>'rubric_ref',p_evaluation_metadata->>'evaluator_version',p_evaluation_metadata->>'evaluator_digest',p_evaluation_metadata->>'confidence',(p_evaluation_metadata->>'held_out_case_count')::integer,p_evaluation_metadata->'calibration_refs',nullif(p_evaluation_metadata->>'lower_bound_ref',''),p_outcome_feedback_ref,p_outcome_feedback_hash,p_status,p_independent,p_evidence_refs,authority_actor.id,p_idempotency_key)
  returning id into attestation_id;
  return query select attestation_id,false;
end $_$;


--
-- Name: attest_execution_environment_conformance(text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.attest_execution_environment_conformance(p_provider_ref text, p_observation jsonb, p_idempotency_key uuid) RETURNS TABLE(conformance_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare actor_row actor%rowtype; provider ops.execution_environment_provider%rowtype; existing ops.execution_environment_conformance%rowtype;
  allowed text[] := array['schema_version','provider_ref','manifest_digest','implementation_digest','package_digest','package_revision_ref','configuration_schema_digest','contract_ref','contract_digest','run_ref','status','check_results','version_ref','backend_kind','evidence_refs','contains_secrets','run_digest','observed_at'];
  derived_run_digest text; observed_at_value timestamptz;
begin
  if session_user !~ '^carr_authority_' then raise exception 'environment conformance attestation requires human authority'; end if;
  select * into actor_row from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  select * into provider from ops.execution_environment_provider p where p_provider_ref='environment-provider:'||p.provider_key||':v'||p.provider_version for share;
  begin observed_at_value := (p_observation->>'observed_at')::timestamptz; exception when others then raise exception 'environment conformance observed_at is invalid'; end;
  derived_run_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(p_observation-'run_digest'-'observed_at'),'sha256'),'hex');
  if actor_row.id is null or provider.id is null or jsonb_typeof(p_observation)<>'object'
     or not (p_observation ?& allowed) or exists(select 1 from jsonb_object_keys(p_observation) k where k<>all(allowed))
     or p_observation->>'schema_version'<>'execution-environment-conformance.v1'
     or p_observation->>'provider_ref'<>p_provider_ref
     or p_observation->>'manifest_digest'<>provider.manifest_digest
     or p_observation->>'implementation_digest' !~ '^sha256:[0-9a-f]{64}$'
     or (p_observation->>'implementation_digest'<>provider.manifest->>'implementation_digest' and not (p_observation->>'status'='failed' and p_observation->'check_results'->'check:implementation-digest-exact'='false'::jsonb))
     or p_observation->>'package_digest' !~ '^sha256:[0-9a-f]{64}$'
     or (p_observation->>'package_digest'<>provider.manifest->'package_provenance'->>'package_digest' and not (p_observation->>'status'='failed' and p_observation->'check_results'->'check:package-provenance-exact'='false'::jsonb))
     or p_observation->>'package_revision_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_observation->>'configuration_schema_digest'<>provider.manifest->>'configuration_schema_digest'
     or p_observation->>'contract_ref'<>provider.manifest->>'conformance_contract_ref'
     or p_observation->>'contract_digest'<>provider.manifest->>'conformance_contract_digest'
     or p_observation->>'run_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_observation->>'run_digest' is distinct from derived_run_digest
     or p_observation->>'status' not in ('passed','failed')
     or p_observation->>'backend_kind' not in ('none','local','container','remote','cloud','unknown')
     or (p_observation->>'backend_kind'<>provider.backend_kind and not (p_observation->>'status'='failed' and p_observation->'check_results'->'check:terminal-backend-local'='false'::jsonb))
     or p_observation->>'version_ref' !~ '^[^[:cntrl:]]{1,160}$'
     or p_observation->>'contains_secrets' not in ('true','false')
     or (p_observation->>'contains_secrets'='true' and not (p_observation->>'status'='failed' and p_observation->'check_results'->'check:source-secret-scan'='false'::jsonb))
     or jsonb_typeof(p_observation->'check_results')<>'object' or p_observation->'check_results'='{}'::jsonb
     or exists(select 1 from jsonb_each(p_observation->'check_results') c where c.key !~ '^check:[a-z0-9-]+$' or jsonb_typeof(c.value)<>'boolean')
     or (p_observation->>'status'='passed' and exists(select 1 from jsonb_each(p_observation->'check_results') c where c.value<>'true'::jsonb))
     or (p_observation->>'status'='failed' and not exists(select 1 from jsonb_each(p_observation->'check_results') c where c.value='false'::jsonb))
     or jsonb_typeof(p_observation->'evidence_refs')<>'array' or jsonb_array_length(p_observation->'evidence_refs')=0
     or exists(select 1 from jsonb_array_elements_text(p_observation->'evidence_refs') value where value !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$')
     or observed_at_value>clock_timestamp() then
    raise exception 'environment conformance attestation is invalid';
  end if;
  select * into existing from ops.execution_environment_conformance where idempotency_key=p_idempotency_key for share;
  if found then
    if existing.provider_id<>provider.id or existing.observation is distinct from p_observation then raise exception 'environment conformance idempotency conflict'; end if;
    return query select existing.id,true; return;
  end if;
  insert into ops.execution_environment_conformance(provider_id,contract_ref,contract_digest,run_ref,run_digest,manifest_digest,implementation_digest,package_digest,configuration_schema_digest,status,check_refs,evidence_refs,observation,observed_at,recorded_by_actor_id,idempotency_key)
  values(provider.id,provider.manifest->>'conformance_contract_ref',provider.manifest->>'conformance_contract_digest',p_observation->>'run_ref',derived_run_digest,provider.manifest_digest,p_observation->>'implementation_digest',p_observation->>'package_digest',p_observation->>'configuration_schema_digest',p_observation->>'status',to_jsonb(array(select key from jsonb_each(p_observation->'check_results') order by key)),p_observation->'evidence_refs',p_observation,observed_at_value,actor_row.id,p_idempotency_key)
  returning id into conformance_id;
  return query select conformance_id,false;
end $_$;


--
-- Name: authenticated_canonical_ownership_controller_binding(uuid, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.authenticated_canonical_ownership_controller_binding(p_job_id uuid, p_lease_token uuid, p_worker text, p_operation text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare e ops.engineering_execution_envelope%rowtype; j ops.job%rowtype;
  bound jsonb; candidates integer; s ops.capability_agent_session%rowtype;
  sp ops.engineering_slice_plan%rowtype; a public.actor%rowtype;
begin
  if not ops.canonical_ownership_runtime_principal_valid()
     or p_job_id is null or p_lease_token is null or nullif(btrim(p_worker),'') is null
     or p_operation is null or p_operation not in ('acquire','check','renew','release') then return null; end if;
  select count(*) into candidates from ops.engineering_execution_envelope env
    where env.job_id=p_job_id and not exists(select 1 from ops.engineering_execution_envelope successor
      where successor.supersedes_envelope_id=env.id);
  if candidates<>1 then return null; end if;
  select * into e from ops.engineering_execution_envelope env where env.job_id=p_job_id
    and not exists(select 1 from ops.engineering_execution_envelope successor where successor.supersedes_envelope_id=env.id);
  if p_operation='acquire' then
    bound:=ops.engineering_controller_binding(e.id,p_job_id,p_lease_token);
    if bound is null then return null; end if;
  else
    perform ops.canonical_ownership_lock_lineage(null,e.slice_plan_id,array[e.slice_ref]);
    select * into s from ops.capability_agent_session where id=e.agent_session_id for share;
    select * into a from public.actor where id=s.executor_actor_id and active and kind='automation' and slug='codex' for share;
    select * into sp from ops.engineering_slice_plan where id=e.slice_plan_id for share;
    if s.id is null or a.id is null or sp.id is null or s.state not in ('claimed','in_progress')
       or s.lease_expires_at is null or s.lease_expires_at<=clock_timestamp() or e.expires_at<=clock_timestamp()
       or not coalesce((ops.engineering_envelope_currentness(e.id,p_job_id)->>'eligible')::boolean,false) then return null; end if;
    bound:=jsonb_build_object('envelope_id',e.id,'envelope_digest',e.envelope_digest,
      'slice_ref',e.slice_ref,'plan_digest',sp.plan_digest,'slice_plan',sp.plan,
      'executor_actor',jsonb_build_object('id',a.id,'slug',a.slug),'agent_session_id',s.id,
      'agent_session_lease_expires_at',s.lease_expires_at);
  end if;
  select * into j from ops.job where id=p_job_id for share;
  if not found or j.definition_key<>'engineering-slice' or j.state<>'running'
     or j.lease_token is distinct from p_lease_token or j.lease_owner is distinct from p_worker
     or j.leased_until<=clock_timestamp() then return null; end if;
  return jsonb_build_object('envelope_id',e.id,'work_request_id',e.work_request_id,
    'accepted_plan_id',e.accepted_plan_id,'slice_plan_id',e.slice_plan_id,
    'state_version',e.state_version,'canonical_record_digest',e.canonical_record_digest,
    'expires_at',e.expires_at,
    'runtime_expires_at',least(e.expires_at,j.leased_until,(bound->>'agent_session_lease_expires_at')::timestamptz),
    'attempt',j.attempt,'agent_session_id',e.agent_session_id,'binding',bound);
end $$;


--
-- Name: authority_actor_slug(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.authority_actor_slug() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  case session_user
    when 'carr_authority_joe' then return 'joe';
    when 'carr_authority_dell' then return 'dell';
    else raise exception 'authority session user % is not an admitted human authority principal', session_user;
  end case;
end $$;


--
-- Name: authority_login_slug(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.authority_login_slug(p_login text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_login
           when 'carr_authority_joe'  then 'joe'
           when 'carr_authority_dell' then 'dell'
         end
$$;


--
-- Name: FUNCTION authority_login_slug(p_login text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.authority_login_slug(p_login text) IS 'The partner slug for an admitted human authority LOGIN role, or NULL for any other role. IMMUTABLE and pure so ops.release.maker_authority_verified can be a generated column over it. 0161''s authority_actor_slug() answers the same question about the CURRENT session and raises instead of returning NULL; this one answers it about a recorded name, which is what a stored row needs.';


--
-- Name: benchmark_accept_manifest_draft(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_accept_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_accepted_payload_digest text, p_review_id uuid, p_portfolio_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_id uuid; v_partner text; v_actor uuid; v_benchmark_ref text;
  v_portfolio jsonb; v_gate_zero jsonb; v_coverage jsonb;
  v_existing ops.benchmark_manifest_acceptance_receipt%rowtype;
begin
  select * into v_existing from ops.benchmark_manifest_acceptance_receipt
   where idempotency_key = p_idempotency_key;
  if found then
    -- p_portfolio_ref is compared too: it is a stored column and it selects
    -- WHICH portfolio the receipt binds, so a replay naming a different one is a
    -- different request wearing the same key.
    if v_existing.draft_id is distinct from p_draft_id
       or v_existing.accepted_payload_digest is distinct from p_accepted_payload_digest
       or v_existing.review_id is distinct from p_review_id
       or v_existing.portfolio_ref is distinct from p_portfolio_ref then
      raise exception 'benchmark idempotency key % was already used for a different acceptance', p_idempotency_key;
    end if;
    return v_existing.id;
  end if;

  -- Raises unless session_user is an admitted partner authority principal.
  v_partner := ops.authority_actor_slug();
  select id into v_actor from public.actor where slug = v_partner and active and kind = 'human';
  if not found then
    raise exception 'partner authority session % has no active human actor', v_partner;
  end if;

  -- THE WRITER'S HALF OF THE LOCK PROTOCOL described at
  -- ops.benchmark_content_frozen_after_acceptance(). FOR UPDATE on the draft row
  -- conflicts with the FOR SHARE that trigger takes on the same row, so a content
  -- insert racing this acceptance must settle before either proceeds and the
  -- digest recomputed below cannot be recomputed over rows a neighbour is still
  -- adding to. It serializes those two paths and nothing else: any future writer
  -- gets the same guarantee only by taking a conflicting mode on this row, and
  -- inserts into the six content tables do so through the trigger, which fires
  -- whatever code path issued them.
  select benchmark_ref into v_benchmark_ref from ops.benchmark_manifest_draft
   where id = p_draft_id for update;
  if not found then raise exception 'benchmark acceptance names an unknown draft'; end if;

  -- All three bindings, derived. Order is deliberate: a caller missing an
  -- accepted portfolio learns about that first rather than being told only about
  -- the unimplemented Gate Zero reader, and the coverage binding is read LAST so
  -- that deleting the Gate Zero throw cannot SKIP it -- the coverage record is
  -- checked on the way to every acceptance, not only on the ones a bound Gate
  -- Zero would have let through anyway. Once the Gate Zero record lands, this
  -- clause PASSES for an attested review and refuses an unattested or outgrown
  -- one; it is not a second gate held shut behind the first. All three refusals
  -- are terminal.
  v_portfolio := ops.benchmark_portfolio_prerequisite(p_portfolio_ref);
  v_gate_zero := ops.benchmark_gate_zero_outcome();
  v_coverage := ops.benchmark_measurement_coverage_binding(p_review_id);

  insert into ops.benchmark_manifest_acceptance_receipt(
    draft_id, benchmark_ref, idempotency_key, gate_id, producer_step_ref, status,
    accepted_payload_digest, review_id,
    portfolio_ref, portfolio_revision_id, portfolio_accepted_digest, portfolio_accepted_at,
    gate_zero_step_ref, gate_zero_outcome_digest, gate_zero_observed_at,
    accepted_by_actor_id)
  values (p_draft_id, v_benchmark_ref, p_idempotency_key,
    'benchmark-contract-accepted',
    'step:benchmark-contract-human-exact-hash-acceptance-receipt', 'accepted',
    p_accepted_payload_digest, p_review_id,
    p_portfolio_ref,
    (v_portfolio ->> 'portfolio_revision_id')::uuid,
    v_portfolio ->> 'portfolio_accepted_digest',
    (v_portfolio ->> 'portfolio_accepted_at')::timestamptz,
    v_gate_zero ->> 'step_ref',
    v_gate_zero ->> 'outcome_digest',
    (v_gate_zero ->> 'observed_at')::timestamptz,
    v_actor)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: FUNCTION benchmark_accept_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_accepted_payload_digest text, p_review_id uuid, p_portfolio_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_accept_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_accepted_payload_digest text, p_review_id uuid, p_portfolio_ref text) IS 'The only way to accept a benchmark manifest draft. The acceptor, the portfolio binding, the Gate Zero outcome and the measurement coverage proof are all derived, never parameters. It takes FOR UPDATE on the draft row, which the content freeze trigger''s FOR SHARE conflicts with. It cannot succeed unless BOTH a current passing Gate Zero outcome record and a measurement coverage attestation exist here; either one missing still leaves it refusing.';


--
-- Name: benchmark_acceptance_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_acceptance_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_draft ops.benchmark_manifest_draft%rowtype;
  v_review ops.benchmark_manifest_review%rowtype;
  v_live text; v_error text; v_partner text; v_partner_actor_id uuid;
  v_portfolio jsonb; v_gate_zero jsonb; v_coverage jsonb;
begin
  select * into v_draft from ops.benchmark_manifest_draft where id = new.draft_id;
  if not found then raise exception 'benchmark acceptance names an unknown draft'; end if;
  if new.benchmark_ref <> v_draft.benchmark_ref then
    raise exception 'benchmark acceptance names the wrong benchmark';
  end if;

  -- EXACT HASH. The digest is RECOMPUTED from the persisted rows; a supplied
  -- hash is only ever compared against it, never trusted as the value.
  v_live := ops.benchmark_payload_digest(new.draft_id);
  if new.accepted_payload_digest <> v_live or v_draft.payload_digest <> v_live then
    raise exception 'benchmark acceptance digest is stale: expected %', v_live;
  end if;
  v_error := ops.benchmark_draft_structure_error(new.draft_id);
  if v_error is not null then
    raise exception 'benchmark acceptance requires a complete r7 payload: %', v_error;
  end if;

  select * into v_review from ops.benchmark_manifest_review where id = new.review_id;
  if not found then raise exception 'benchmark acceptance names an unknown review'; end if;
  if v_review.draft_id <> new.draft_id then
    raise exception 'benchmark acceptance names a review of a different draft';
  end if;
  if v_review.verdict <> 'pass' then
    raise exception 'benchmark acceptance requires a passing independent review';
  end if;
  if v_review.reviewed_payload_digest <> v_live then
    raise exception 'the passing benchmark review was written against different bytes';
  end if;
  -- NAMING, NOT PROVING. A passing review must name the measurement set its
  -- writer read; this clause checks that it did. It is not a coverage check, and
  -- the coverage proof binding below is what refuses to treat it as one.
  if v_review.measurement_set_digest is null then
    raise exception 'the passing benchmark review names no measurement set';
  end if;
  if v_review.reviewer_actor_id = v_draft.proposed_by_actor_id then
    raise exception 'the reviewer may not be the proposer of the same benchmark draft';
  end if;

  -- THE TRUST BOUNDARY. An actor id in the payload proves nothing: anyone able
  -- to insert could name Joe. What authenticates the acceptor is the database
  -- session -- the per-partner authority credential the server selects from
  -- verified session state. ops.authority_actor_slug() reads session_user and
  -- raises for any other principal, so a supplied id may only agree with it.
  v_partner := ops.authority_actor_slug();
  select id into v_partner_actor_id from public.actor
   where slug = v_partner and active and kind = 'human';
  if not found then
    raise exception 'partner authority session % has no active human actor', v_partner;
  end if;
  if new.accepted_by_actor_id <> v_partner_actor_id then
    raise exception 'benchmark acceptance actor does not match the authenticated partner session';
  end if;

  -- Three distinct roles, not two: a reviewer who can accept their own pass is
  -- not an independent reviewer, and a proposer who can accept their own draft
  -- is not being reviewed at all.
  if new.accepted_by_actor_id = v_draft.proposed_by_actor_id then
    raise exception 'the acceptor may not be the proposer of the same benchmark draft';
  end if;
  if new.accepted_by_actor_id = v_review.reviewer_actor_id then
    raise exception 'the acceptor may not also be the independent reviewer';
  end if;

  -- EVERY BINDING BELOW GOES THROUGH ops.benchmark_assert_bound(), AND THE
  -- REASON IS A FAIL-OPEN THAT USED TO BE HERE. These comparisons were written
  -- as `new.x <> (derived ->> 'x')`. When the derived side is null -- which is
  -- exactly what a reader that has not been implemented, or has been implemented
  -- badly, produces -- `<>` evaluates to NULL, `or` of NULLs is NULL, the IF does
  -- not fire, and an acceptance binding NOTHING is admitted. The helper refuses a
  -- null derived value, refuses a null supplied value, and compares with IS
  -- DISTINCT FROM.
  --
  -- PREREQUISITE ONE, re-derived here rather than trusted from the write
  -- function: the portfolio binding on this row must be the one the rail
  -- currently produces. What that proves is stated at the receipt's columns: the
  -- named portfolio is accepted and intact, not that this benchmark descends
  -- from it.
  v_portfolio := ops.benchmark_portfolio_prerequisite(new.portfolio_ref);
  perform ops.benchmark_assert_bound('accepted portfolio constitution', 'revision id',
    new.portfolio_revision_id, (v_portfolio ->> 'portfolio_revision_id')::uuid);
  perform ops.benchmark_assert_bound('accepted portfolio constitution', 'accepted digest',
    new.portfolio_accepted_digest, v_portfolio ->> 'portfolio_accepted_digest');
  perform ops.benchmark_assert_bound('accepted portfolio constitution', 'acceptance instant',
    new.portfolio_accepted_at, (v_portfolio ->> 'portfolio_accepted_at')::timestamptz);

  -- PREREQUISITE TWO, likewise re-derived. This raises today, which is why no
  -- row reaches the table.
  v_gate_zero := ops.benchmark_gate_zero_outcome();
  perform ops.benchmark_assert_bound('Gate Zero read-only outcome', 'step reference',
    new.gate_zero_step_ref, v_gate_zero ->> 'step_ref');
  perform ops.benchmark_assert_bound('Gate Zero read-only outcome', 'outcome digest',
    new.gate_zero_outcome_digest, v_gate_zero ->> 'outcome_digest');
  perform ops.benchmark_assert_bound('Gate Zero read-only outcome', 'observed instant',
    new.gate_zero_observed_at, (v_gate_zero ->> 'observed_at')::timestamptz);

  -- THE THIRD BINDING, WHICH NOW READS A RECORD RATHER THAN REFUSING FOR WANT OF
  -- ONE. The passing review named a measurement set above; the attestation
  -- recorded in the same call says which kernel evaluator proved it, against
  -- which payload digest, over which bytes. The reader recomputes the payload
  -- digest and refuses a stale attestation, so this binds a checked record.
  --
  -- IT STILL BINDS ONLY WHAT THE RECORD SAYS. The samples are outside this
  -- database, the evaluation cannot be repeated here, and this clause does not
  -- turn a trusted writer's attributed statement into an independent
  -- verification. It is also still ordered AFTER the Gate Zero binding, which
  -- still raises: acceptance refuses at Gate Zero, and reaching this line at all
  -- requires a fact this record layer does not hold.
  v_coverage := ops.benchmark_measurement_coverage_binding(new.review_id);
  perform ops.benchmark_assert_bound('measurement coverage proof', 'measurement set digest',
    v_review.measurement_set_digest, v_coverage ->> 'measurement_set_digest');
  -- The evaluator is bound too, against the closed set rather than against a
  -- value the receipt carries: there is no evaluator column on the receipt, and
  -- adding one would record a coverage claim the receipt does not make.
  perform ops.benchmark_assert_bound('measurement coverage proof', 'coverage evaluator',
    v_coverage ->> 'coverage_proved_by',
    (select e from unnest(ops.benchmark_coverage_evaluators()) e
      where e = v_coverage ->> 'coverage_proved_by'));

  -- STRICTLY AFTER, on the exclusive reading benchmark-minimum.v5.js uses for
  -- every member: an acceptance recorded AT a prerequisite instant did not
  -- follow it. The table constraints assert the same two inequalities; both are
  -- kept so a future direct insert cannot lose either.
  if new.accepted_at <= new.gate_zero_observed_at then
    raise exception 'benchmark acceptance must be strictly after the Gate Zero outcome';
  end if;
  if new.accepted_at <= new.portfolio_accepted_at then
    raise exception 'benchmark acceptance must be strictly after the portfolio constitution acceptance';
  end if;
  if new.accepted_at <= v_review.created_at then
    raise exception 'benchmark acceptance must be strictly after the review it rests on';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION benchmark_acceptance_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_acceptance_guard() IS 'Authoritative benchmark acceptance precondition: recomputed exact payload digest, complete payload, a fresh passing independent review on the same bytes naming its measurement set, three distinct identities, an acceptor derived from the authenticated partner session, the accepted portfolio constitution the acceptor named, the Gate Zero outcome as authenticated here, the recorded coverage proof binding for the review''s measurement set and its named evaluator, and an acceptance strictly after the portfolio, the Gate Zero instant and the review. Every binding comparison runs through ops.benchmark_assert_bound(), so an underived binding refuses instead of comparing to NULL and falling through. It still cannot succeed: the Gate Zero reader is read first and always raises.';


--
-- Name: benchmark_accepted_draft(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_accepted_draft(p_benchmark_ref text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_id uuid; v_error text;
begin
  v_id := ops.benchmark_current_accepted_draft(p_benchmark_ref);
  if v_id is null then return null; end if;
  v_error := ops.benchmark_draft_integrity_error(v_id);
  if v_error is not null then
    raise exception 'accepted benchmark % failed integrity: %', p_benchmark_ref, v_error
      using errcode = 'integrity_constraint_violation';
  end if;
  return v_id;
end;
$$;


--
-- Name: FUNCTION benchmark_accepted_draft(p_benchmark_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_accepted_draft(p_benchmark_ref text) IS 'The current accepted benchmark draft. Null when nothing is accepted; an explicit refusal when the current accepted draft fails integrity.';


--
-- Name: benchmark_assert_bound(text, text, anyelement, anyelement); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_assert_bound(p_binding text, p_field text, p_supplied anyelement, p_derived anyelement) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if p_derived is null then
    raise exception 'benchmark acceptance cannot bind the %: its % was not derived, and an underived binding is a refusal rather than a match',
      p_binding, p_field;
  end if;
  if p_supplied is null then
    raise exception 'benchmark acceptance names no % for the %', p_field, p_binding;
  end if;
  if p_supplied is distinct from p_derived then
    raise exception 'benchmark acceptance does not bind the current %: its % differs from the derived one',
      p_binding, p_field;
  end if;
end;
$$;


--
-- Name: FUNCTION benchmark_assert_bound(p_binding text, p_field text, p_supplied anyelement, p_derived anyelement); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_assert_bound(p_binding text, p_field text, p_supplied anyelement, p_derived anyelement) IS 'Fail-closed equality for one acceptance binding field: refuses a null derived value, refuses a null supplied value, and otherwise compares with IS DISTINCT FROM so a null can never make the comparison itself evaluate to NULL and fall through.';


--
-- Name: benchmark_content_frozen_after_acceptance(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_content_frozen_after_acceptance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  -- The shared half of the protocol above. Taken BEFORE the receipt lookup, so
  -- an acceptance in flight on this draft must commit or abort first and this
  -- statement then reads a settled answer rather than a stale one.
  perform 1 from ops.benchmark_manifest_draft where id = new.draft_id for share;
  if exists (select 1 from ops.benchmark_manifest_acceptance_receipt
              where draft_id = new.draft_id) then
    raise exception 'benchmark draft % is accepted; its content is closed to further % rows',
      new.draft_id, tg_table_name;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION benchmark_content_frozen_after_acceptance(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_content_frozen_after_acceptance() IS 'Refuses a dimension, workload, request-size, concurrency, browser or evaluator insert against a draft that already carries an acceptance receipt, so no payload row can appear outside the hash the partner accepted. Takes FOR SHARE on the draft row first; ops.benchmark_accept_manifest_draft takes FOR UPDATE on the same row, and it is that shared protocol -- not the lock alone -- that keeps a concurrent content insert and an acceptance from committing past each other.';


--
-- Name: benchmark_cost_variance_thresholds(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_cost_variance_thresholds() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'warn_basis_points', 15000,
    'mandatory_replan_basis_points', 20000)
$$;


--
-- Name: FUNCTION benchmark_cost_variance_thresholds(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_cost_variance_thresholds() IS 'The two fixed r7 cost variance thresholds in basis points. Emitted into every payload preimage and never stored per draft.';


--
-- Name: benchmark_coverage_evaluators(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_coverage_evaluators() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select array['benchmark-minimum.v5.js#evaluateBenchmarkWorkloadCoverage']::text[] $$;


--
-- Name: FUNCTION benchmark_coverage_evaluators(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_coverage_evaluators() IS 'The closed set of names a measurement coverage attestation may cite as the evaluator that proved coverage. A name, not an implementation: nothing in this database evaluates coverage.';


--
-- Name: benchmark_current_accepted_draft(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_current_accepted_draft(p_benchmark_ref text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select d.id from ops.benchmark_manifest_draft d
    join ops.benchmark_manifest_acceptance_receipt a on a.draft_id = d.id
   where d.benchmark_ref = p_benchmark_ref
   order by d.draft_version desc limit 1
$$;


--
-- Name: FUNCTION benchmark_current_accepted_draft(p_benchmark_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_current_accepted_draft(p_benchmark_ref text) IS 'The highest-version benchmark draft carrying an acceptance receipt, regardless of integrity.';


--
-- Name: benchmark_deadline_contract(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_deadline_contract() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'timezone', 'America/Chicago',
    'calendar_days', 30,
    'clock_origin_gate_id', 'foundation-assurance-minimum-accepted',
    'clock_origin_rule', 'observed_at of the first current passing foundation-assurance-minimum receipt that makes Journey 1 admissible',
    'maximum_external_blocker_pause_days', 5,
    'reset_policy', 'never_reset_or_rebase_elapsed_history',
    'amendment_policy', 'verified_partner_exact_hash_amendment_preserves_original_origin_and_elapsed_history',
    'clock_terminus_gate_id', 'journey-one-kernel-production-accepted',
    'kernel_obligation_decision_ids', jsonb_build_array('Q002.D1', 'Q014.D1', 'Q123.D1'),
    'miss_consequence', 'mark_deadline_missed_require_replan_preserve_origin_and_elapsed_continue_safe_construction_without_claiming_deadline_success')
$$;


--
-- Name: FUNCTION benchmark_deadline_contract(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_deadline_contract() IS 'The fixed r7 benchmark deadline contract, pause budget in DAYS. Emitted into every payload preimage and never stored per draft.';


--
-- Name: benchmark_dimension_array(uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_dimension_array(p_draft_id uuid, p_dimension text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(d.value) order by d.ordinal), '[]'::jsonb)
    from ops.benchmark_manifest_dimension d
   where d.draft_id = p_draft_id and d.dimension = p_dimension
$$;


--
-- Name: FUNCTION benchmark_dimension_array(p_draft_id uuid, p_dimension text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_dimension_array(p_draft_id uuid, p_dimension text) IS 'One stored benchmark dimension as a JSON array in its declared ordinal order.';


--
-- Name: benchmark_draft_complete(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_draft_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_error text; v_live text;
begin
  v_error := ops.benchmark_draft_structure_error(new.id);
  if v_error is not null then
    raise exception 'benchmark draft is not a complete r7 payload: %', v_error;
  end if;
  v_live := ops.benchmark_payload_digest(new.id);
  if new.payload_digest <> v_live then
    raise exception 'benchmark payload digest does not match its rows: stored %, computed %',
      new.payload_digest, v_live;
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION benchmark_draft_complete(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_draft_complete() IS 'Deferred completeness check: at commit a benchmark draft must be a complete r7 payload and its stored payload digest must equal the digest recomputed from its own rows.';


--
-- Name: benchmark_draft_integrity_error(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_draft_integrity_error(p_draft_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_draft ops.benchmark_manifest_draft%rowtype;
        v_receipt ops.benchmark_manifest_acceptance_receipt%rowtype;
        v_live text; v_error text;
begin
  select * into v_draft from ops.benchmark_manifest_draft where id = p_draft_id;
  if not found then return format('draft %s does not exist', p_draft_id); end if;
  v_error := ops.benchmark_draft_structure_error(p_draft_id);
  if v_error is not null then return v_error; end if;
  v_live := ops.benchmark_payload_digest(p_draft_id);
  if v_draft.payload_digest <> v_live then
    return format('draft %s payload digest no longer matches its rows', p_draft_id);
  end if;
  select * into v_receipt from ops.benchmark_manifest_acceptance_receipt where draft_id = p_draft_id;
  if found and v_receipt.accepted_payload_digest <> v_live then
    return format('draft %s acceptance receipt names a digest the rows no longer produce', p_draft_id);
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION benchmark_draft_integrity_error(p_draft_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_draft_integrity_error(p_draft_id uuid) IS 'Why one benchmark draft is not trustworthy, recomputed from its rows, or null when it is intact.';


--
-- Name: benchmark_draft_structure_error(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_draft_structure_error(p_draft_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_draft ops.benchmark_manifest_draft%rowtype;
  v_dimension text; v_count integer; v_total integer;
begin
  select * into v_draft from ops.benchmark_manifest_draft where id = p_draft_id;
  if not found then return format('draft %s does not exist', p_draft_id); end if;

  -- Every ordered list must be present, non-empty, and contiguously ordinaled
  -- from zero. A gap in the ordinals means a row was expected and is missing,
  -- which is the shape a partial insert leaves behind.
  foreach v_dimension in array array[
    'capacity_profiles', 'arrival_patterns', 'routes', 'runtime_versions',
    'device_profiles', 'hardware_profiles', 'network_profiles',
    'acknowledgement_endpoints', 'comparator_versions', 'cache_states'
  ] loop
    select count(*) into v_count from ops.benchmark_manifest_dimension d
     where d.draft_id = p_draft_id and d.dimension = v_dimension;
    if v_count < 1 then
      return format('draft %s declares no %s', p_draft_id, v_dimension);
    end if;
    if v_count <> (select coalesce(max(d.ordinal), -1) + 1 from ops.benchmark_manifest_dimension d
                    where d.draft_id = p_draft_id and d.dimension = v_dimension) then
      return format('draft %s has a gap in the %s ordinals', p_draft_id, v_dimension);
    end if;
  end loop;

  -- cache_states carries minItems 2 over a closed two-value enum, so both
  -- states are required and neither is optional.
  select count(*) into v_count from ops.benchmark_manifest_dimension d
   where d.draft_id = p_draft_id and d.dimension = 'cache_states';
  if v_count <> 2 then
    return format('draft %s must declare both cache states, it declares %s', p_draft_id, v_count);
  end if;

  for v_dimension, v_count in
    select 'workload_mix', count(*) from ops.benchmark_manifest_workload where draft_id = p_draft_id
    union all
    select 'request_size_distribution', count(*) from ops.benchmark_manifest_request_size where draft_id = p_draft_id
    union all
    select 'concurrency_levels', count(*) from ops.benchmark_manifest_concurrency where draft_id = p_draft_id
    union all
    select 'browsers', count(*) from ops.benchmark_manifest_browser where draft_id = p_draft_id
    union all
    select 'evaluator_identities', count(*) from ops.benchmark_manifest_evaluator where draft_id = p_draft_id
  loop
    if v_count < 1 then
      return format('draft %s declares no %s', p_draft_id, v_dimension);
    end if;
  end loop;

  if (select count(*) from ops.benchmark_manifest_workload where draft_id = p_draft_id)
     <> (select coalesce(max(ordinal), -1) + 1 from ops.benchmark_manifest_workload where draft_id = p_draft_id)
   or (select count(*) from ops.benchmark_manifest_request_size where draft_id = p_draft_id)
     <> (select coalesce(max(ordinal), -1) + 1 from ops.benchmark_manifest_request_size where draft_id = p_draft_id)
   or (select count(*) from ops.benchmark_manifest_concurrency where draft_id = p_draft_id)
     <> (select coalesce(max(ordinal), -1) + 1 from ops.benchmark_manifest_concurrency where draft_id = p_draft_id)
   or (select count(*) from ops.benchmark_manifest_browser where draft_id = p_draft_id)
     <> (select coalesce(max(ordinal), -1) + 1 from ops.benchmark_manifest_browser where draft_id = p_draft_id)
   or (select count(*) from ops.benchmark_manifest_evaluator where draft_id = p_draft_id)
     <> (select coalesce(max(ordinal), -1) + 1 from ops.benchmark_manifest_evaluator where draft_id = p_draft_id) then
    return format('draft %s has a gap in a payload list''s ordinals', p_draft_id);
  end if;

  select coalesce(sum(weight_basis_points), 0) into v_total
    from ops.benchmark_manifest_workload where draft_id = p_draft_id;
  if v_total <> 10000 then
    return format('draft %s workload weights total %s basis points, not 10000', p_draft_id, v_total);
  end if;

  return null;
end;
$$;


--
-- Name: FUNCTION benchmark_draft_structure_error(p_draft_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_draft_structure_error(p_draft_id uuid) IS 'Why one benchmark draft is not a complete r7 payload, recomputed from its rows, or null when it is.';


