-- Name: benchmark_draft_structure_valid(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_draft_structure_valid(p_draft_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$ select ops.benchmark_draft_structure_error(p_draft_id) is null $$;


--
-- Name: FUNCTION benchmark_draft_structure_valid(p_draft_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_draft_structure_valid(p_draft_id uuid) IS 'True when one benchmark draft is a complete r7 payload.';


--
-- Name: benchmark_gate_zero_outcome(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_gate_zero_outcome() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_row ops.gate_zero_read_only_outcome%rowtype;
  v_any boolean;
  v_recomputed_digest text;
begin
  select * into v_row from ops.gate_zero_read_only_outcome
   where status = 'pass' and ttl_expires_at > now()
   order by observed_at desc, outcome_digest collate "C" desc
   limit 1;
  if not found then
    select exists (select 1 from ops.gate_zero_read_only_outcome) into v_any;
    if v_any then
      raise exception 'benchmark acceptance requires a current passing Gate Zero read-only outcome; every outcome recorded here is non-passing or past its expiry. No caller-supplied, configured or synthetic Gate Zero outcome is accepted.';
    end if;
    raise exception 'benchmark acceptance requires an authenticated Gate Zero read-only outcome binding, and none has been recorded here yet. The record exists (ops.gate_zero_read_only_outcome) and the independent oracle seat writes it; until it does, acceptance fails closed. No caller-supplied, configured or synthetic Gate Zero outcome is accepted.';
  end if;
  v_recomputed_digest := ops.gate_zero_outcome_digest(v_row.receipt);
  if v_row.outcome_digest <> v_recomputed_digest then
    raise exception 'Gate Zero outcome digest divergence: stored %, recomputed % from the tagged consumer-gate-receipt.v1 receipt',
      v_row.outcome_digest, v_recomputed_digest;
  end if;
  -- THE CLOSED THREE-FIELD OBJECT the whole foundation join hangs on
  -- (benchmark-minimum.v5.js:435, :1449-1453). Nothing else is returned: a
  -- fourth field here is a value some future reader consumes as something it
  -- is not.
  return jsonb_build_object(
    'step_ref', v_row.step_ref,
    'outcome_digest', v_row.outcome_digest,
    'observed_at', to_char(v_row.observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
end;
$$;


--
-- Name: FUNCTION benchmark_gate_zero_outcome(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_gate_zero_outcome() IS 'PRIVATE reader for the current Gate Zero read-only outcome: the latest passing, unexpired row in ops.gate_zero_read_only_outcome, as the closed { step_ref, outcome_digest, observed_at }. Recomputes the tagged consumer-gate-receipt.v1 digest from the stored receipt and refuses a mismatch before answering. Raises when there is no current row, which is the same fail-closed posture this reader had while it was a stub. Granted to no role; reachable only from the definer write path in this file.';


--
-- Name: benchmark_measurement_coverage_binding(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_measurement_coverage_binding(p_review_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_review ops.benchmark_manifest_review%rowtype;
  v_attestation ops.benchmark_measurement_coverage_attestation%rowtype;
  v_live text;
begin
  select * into v_review from ops.benchmark_manifest_review where id = p_review_id;
  if not found then
    raise exception 'the coverage proof binding names an unknown benchmark review %', p_review_id;
  end if;

  select * into v_attestation from ops.benchmark_measurement_coverage_attestation
   where review_id = p_review_id;
  if not found then
    raise exception 'benchmark acceptance requires a recorded coverage proof binding for the measurement set named by review %, and none is recorded: measurement_set_digest names the bytes a trusted writer read, and without an attestation beside it nothing binds those bytes to a coverage evaluation by benchmark-minimum.v5.js. Accepting on the digest alone would claim an independent verification that does not exist. This function evaluates no coverage and is not a second coverage authority.', p_review_id;
  end if;

  -- RECOMPUTED, not read back. This is the half of the attestation the database
  -- can check for itself, and checking it is what makes the record more than a
  -- note the writer left.
  v_live := ops.benchmark_payload_digest(v_attestation.draft_id);
  if v_attestation.benchmark_payload_digest is distinct from v_live then
    raise exception 'the coverage proof binding for review % attests payload digest %, which this draft no longer produces: it now produces %',
      p_review_id, v_attestation.benchmark_payload_digest, v_live;
  end if;
  if v_attestation.draft_id is distinct from v_review.draft_id then
    raise exception 'the coverage proof binding for review % attests a different draft', p_review_id;
  end if;
  -- The attestation must attest THIS review's bytes. The write path already
  -- refuses a divergence, so this is the fail-closed half: a future write path
  -- that lost that check must not become an acceptance that bound nothing.
  if v_attestation.measurement_set_digest is distinct from v_review.measurement_set_digest then
    raise exception 'the coverage proof binding for review % attests measurement set %, which is not the set the review names',
      p_review_id, v_attestation.measurement_set_digest;
  end if;
  if not (v_attestation.coverage_proved_by = any (ops.benchmark_coverage_evaluators())) then
    raise exception 'the coverage proof binding for review % names %, which is not a benchmark coverage evaluator this rail admits',
      p_review_id, v_attestation.coverage_proved_by;
  end if;

  -- The documented return: exactly what acceptance binds. The evaluation digest
  -- is deliberately NOT returned -- acceptance binds nothing to it, and a value
  -- on this result that nothing consumes invites a future reader to consume it.
  return jsonb_build_object(
    'review_id', v_review.id,
    'measurement_set_digest', v_attestation.measurement_set_digest,
    'coverage_proved_by', v_attestation.coverage_proved_by);
end;
$$;


--
-- Name: FUNCTION benchmark_measurement_coverage_binding(p_review_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_measurement_coverage_binding(p_review_id uuid) IS 'PRIVATE reader for the proof binding between a review''s measurement_set_digest and a kernel coverage evaluation. Returns { review_id, measurement_set_digest, coverage_proved_by } for an attested review and raises for one with no attestation, one whose attested payload digest the draft no longer produces, one whose measurement digest is not the review''s, and one naming an evaluator outside ops.benchmark_coverage_evaluators(). Evaluates no coverage and is not a second coverage authority: the samples are outside this record layer and the evaluation cannot be repeated here. Independent of the Gate Zero binding on purpose. Granted to no role.';


--
-- Name: benchmark_pass_requires_attestation(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_pass_requires_attestation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if new.verdict = 'pass' and not exists (
       select 1 from ops.benchmark_measurement_coverage_attestation where review_id = new.id) then
    raise exception 'benchmark review % passes and records no measurement coverage attestation; an unattested pass is refused', new.id;
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION benchmark_pass_requires_attestation(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_pass_requires_attestation() IS 'Commit-time refusal of a passing benchmark review with no coverage attestation. The write function refuses one first; this is the half that binds the table owner, from whom INSERT cannot be revoked.';


--
-- Name: benchmark_payload_digest(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_payload_digest(p_draft_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(jsonb_build_array(
      ops.benchmark_payload_domain_tag(),
      ops.benchmark_payload_preimage(p_draft_id))),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION benchmark_payload_digest(p_draft_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_payload_digest(p_draft_id uuid) IS 'The r7 exact hash a verified partner accepts: sha256 over the canonical [domain_tag, payload] of one benchmark draft, recomputed from its rows.';


--
-- Name: benchmark_payload_domain_tag(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_payload_domain_tag() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre:benchmark-payload:v1'::text $$;


--
-- Name: FUNCTION benchmark_payload_domain_tag(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_payload_domain_tag() IS 'The r7 domain tag for the benchmark-manifest.v1 payload digest.';


--
-- Name: benchmark_payload_preimage(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_payload_preimage(p_draft_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_draft ops.benchmark_manifest_draft%rowtype;
  v_workloads jsonb; v_sizes jsonb; v_levels jsonb; v_browsers jsonb; v_evaluators jsonb;
begin
  select * into v_draft from ops.benchmark_manifest_draft where id = p_draft_id;
  if not found then
    raise exception 'benchmark draft % does not exist', p_draft_id;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'workload_id', w.workload_id,
           'weight_basis_points', w.weight_basis_points,
           'operation_mix_digest', w.operation_mix_digest) order by w.ordinal), '[]'::jsonb)
    into v_workloads from ops.benchmark_manifest_workload w where w.draft_id = p_draft_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'percentile', r.percentile,
           'bytes', r.bytes) order by r.ordinal), '[]'::jsonb)
    into v_sizes from ops.benchmark_manifest_request_size r where r.draft_id = p_draft_id;

  select coalesce(jsonb_agg(to_jsonb(c.concurrency_level) order by c.ordinal), '[]'::jsonb)
    into v_levels from ops.benchmark_manifest_concurrency c where c.draft_id = p_draft_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'name', b.name, 'version', b.version, 'build', b.build) order by b.ordinal), '[]'::jsonb)
    into v_browsers from ops.benchmark_manifest_browser b where b.draft_id = p_draft_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'actor_id', e.actor_id, 'session_ref', e.session_ref,
           'authority_class', e.authority_class) order by e.ordinal), '[]'::jsonb)
    into v_evaluators from ops.benchmark_manifest_evaluator e where e.draft_id = p_draft_id;

  -- Exactly the twenty-six r7 payload fields: the thirty manifest fields minus
  -- the four acceptance-envelope fields the canonicalization contract excludes,
  -- so no artifact hashes its own digest.
  return jsonb_build_object(
    'subject_digest', v_draft.subject_digest,
    'candidate_digest', v_draft.candidate_digest,
    'policy_digest', v_draft.policy_digest,
    'capacity_profiles', ops.benchmark_dimension_array(p_draft_id, 'capacity_profiles'),
    'workload_mix', v_workloads,
    'request_size_distribution', v_sizes,
    'concurrency_levels', v_levels,
    'arrival_patterns', ops.benchmark_dimension_array(p_draft_id, 'arrival_patterns'),
    'routes', ops.benchmark_dimension_array(p_draft_id, 'routes'),
    'browsers', v_browsers,
    'runtime_versions', ops.benchmark_dimension_array(p_draft_id, 'runtime_versions'),
    'device_profiles', ops.benchmark_dimension_array(p_draft_id, 'device_profiles'),
    'hardware_profiles', ops.benchmark_dimension_array(p_draft_id, 'hardware_profiles'),
    'network_profiles', ops.benchmark_dimension_array(p_draft_id, 'network_profiles'),
    'cache_states', ops.benchmark_dimension_array(p_draft_id, 'cache_states'),
    'samples_per_cell', v_draft.samples_per_cell,
    'warmup_runs', v_draft.warmup_runs,
    'p95_aggregation_method', v_draft.p95_aggregation_method,
    'outlier_rule', v_draft.outlier_rule,
    'acknowledgement_endpoints', ops.benchmark_dimension_array(p_draft_id, 'acknowledgement_endpoints'),
    'evaluator_identities', v_evaluators,
    'comparator_versions', ops.benchmark_dimension_array(p_draft_id, 'comparator_versions'),
    'slo_thresholds', ops.benchmark_slo_thresholds(),
    'cost_expectation_matrix_digest', v_draft.cost_expectation_matrix_digest,
    'cost_variance_thresholds', ops.benchmark_cost_variance_thresholds(),
    'deadline_contract', ops.benchmark_deadline_contract());
end;
$$;


--
-- Name: FUNCTION benchmark_payload_preimage(p_draft_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_payload_preimage(p_draft_id uuid) IS 'The twenty-six r7 payload fields of one benchmark draft, rebuilt from its persisted rows with the fixed constants emitted rather than stored.';


--
-- Name: benchmark_portfolio_prerequisite(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_portfolio_prerequisite(p_portfolio_ref text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_revision_id uuid; v_live text; v_stored text; v_accepted_at timestamptz;
begin
  if p_portfolio_ref is null or btrim(p_portfolio_ref) = '' then
    raise exception 'benchmark acceptance requires the accepted portfolio constitution it descends from; no portfolio reference was supplied';
  end if;
  -- Raises on integrity failure; null means nothing is accepted.
  v_revision_id := ops.portfolio_accepted_revision(p_portfolio_ref);
  if v_revision_id is null then
    raise exception 'benchmark acceptance requires an accepted portfolio constitution; portfolio % has no acceptance receipt. r7 makes step:benchmark-contract-human-exact-hash-acceptance-receipt depend on step:portfolio-constitution-human-exact-hash-acceptance-receipt, and no accepted portfolio is created or assumed here.',
      p_portfolio_ref;
  end if;
  v_live := ops.portfolio_accepted_digest(v_revision_id);
  -- An absent recomputed digest is a refusal, not a match. Without this, a null
  -- on both sides would satisfy the IS DISTINCT FROM below and the prerequisite
  -- would return a binding with no digest in it.
  if v_live is null then
    raise exception 'accepted portfolio % produced no accepted digest', p_portfolio_ref
      using errcode = 'integrity_constraint_violation';
  end if;
  select r.accepted_digest into v_stored from ops.portfolio_revision r where r.id = v_revision_id;
  if v_stored is distinct from v_live then
    raise exception 'accepted portfolio % no longer produces its accepted digest', p_portfolio_ref
      using errcode = 'integrity_constraint_violation';
  end if;
  select a.accepted_at into v_accepted_at
    from ops.portfolio_revision_acceptance_receipt a
   where a.portfolio_revision_id = v_revision_id;
  if v_accepted_at is null then
    raise exception 'accepted portfolio % carries no acceptance instant', p_portfolio_ref
      using errcode = 'integrity_constraint_violation';
  end if;
  return jsonb_build_object(
    'portfolio_ref', p_portfolio_ref,
    'portfolio_revision_id', v_revision_id,
    'portfolio_accepted_digest', v_live,
    'portfolio_accepted_at', v_accepted_at);
end;
$$;


--
-- Name: FUNCTION benchmark_portfolio_prerequisite(p_portfolio_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_portfolio_prerequisite(p_portfolio_ref text) IS 'The accepted portfolio constitution NAMED BY THE ACCEPTOR, resolved through the existing 0496 rail and verified against digests recomputed from its rows. Proves that the named portfolio is accepted and intact; it does not prove that the benchmark descends from it, because no benchmark-to-portfolio lineage is recorded anywhere. Refuses when no portfolio is accepted; invents none.';


--
-- Name: benchmark_proposal_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_proposal_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_units integer;
begin
  if new.proposed_by_actor_id <> ops.portfolio_writer_actor_id() then
    raise exception 'benchmark proposal actor does not match the authenticated writer context';
  end if;
  -- THE ONE BOUND THE COLUMN CHECK CANNOT STATE. r7 bounds outlier_rule at
  -- 5..300 and the kernel enforces that with String#length, in UTF-16 code
  -- units; the column's char_length check counts codepoints, so it would admit a
  -- 300-character astral string the kernel refuses at 600 units. Both bounds are
  -- kept: the column decides the shape, this decides the same number the kernel
  -- means by it.
  v_units := ops.benchmark_utf16_length(new.outlier_rule);
  if v_units < 5 or v_units > 300 then
    raise exception 'benchmark outlier rule is % UTF-16 code units; r7 bounds it to 5..300 as benchmark-minimum.v5.js measures it', v_units;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION benchmark_proposal_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_proposal_guard() IS 'Binds a benchmark draft to the server-established writer, so a draft cannot be attributed to another actor, and bounds outlier_rule by the UTF-16 code-unit length the kernel measures rather than by codepoints alone.';


--
-- Name: benchmark_propose_manifest_draft(text, integer, uuid, text, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_propose_manifest_draft(p_benchmark_ref text, p_draft_version integer, p_idempotency_key uuid, p_payload_digest text, p_scalars jsonb, p_dimensions jsonb, p_workloads jsonb, p_request_sizes jsonb, p_concurrency jsonb, p_browsers jsonb, p_evaluators jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_draft uuid; v_actor uuid; v_existing ops.benchmark_manifest_draft%rowtype;
        d jsonb; w jsonb; r jsonb; c jsonb; b jsonb; e jsonb;
begin
  select * into v_existing from ops.benchmark_manifest_draft where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.benchmark_ref <> p_benchmark_ref
       or v_existing.draft_version <> p_draft_version
       or v_existing.payload_digest <> p_payload_digest then
      raise exception 'benchmark idempotency key % was already used for a different draft', p_idempotency_key;
    end if;
    return v_existing.id;
  end if;

  v_actor := ops.portfolio_writer_actor_id();
  insert into ops.benchmark_manifest_draft(
    benchmark_ref, draft_version, idempotency_key, schema_version, payload_domain_tag,
    gate_id, producer_step_ref, producer_role, combiner,
    subject_digest, candidate_digest, policy_digest, cost_expectation_matrix_digest,
    samples_per_cell, warmup_runs, p95_aggregation_method, outlier_rule,
    payload_digest, proposed_by_actor_id)
  values (p_benchmark_ref, p_draft_version, p_idempotency_key,
    'benchmark-manifest.v1', ops.benchmark_payload_domain_tag(),
    'benchmark-contract-accepted',
    'step:benchmark-contract-human-exact-hash-acceptance-receipt',
    'verified_partner_benchmark_authority', 'exact_verified_partner_hash_acceptance',
    p_scalars ->> 'subject_digest', p_scalars ->> 'candidate_digest',
    p_scalars ->> 'policy_digest', p_scalars ->> 'cost_expectation_matrix_digest',
    (p_scalars ->> 'samples_per_cell')::integer, (p_scalars ->> 'warmup_runs')::integer,
    p_scalars ->> 'p95_aggregation_method', p_scalars ->> 'outlier_rule',
    p_payload_digest, v_actor)
  returning id into v_draft;

  for d in select value from jsonb_array_elements(p_dimensions) loop
    insert into ops.benchmark_manifest_dimension(draft_id, dimension, ordinal, value)
    values (v_draft, d ->> 'dimension', (d ->> 'ordinal')::integer, d ->> 'value');
  end loop;

  for w in select value from jsonb_array_elements(p_workloads) loop
    insert into ops.benchmark_manifest_workload(
      draft_id, ordinal, workload_id, weight_basis_points, operation_mix_digest)
    values (v_draft, (w ->> 'ordinal')::integer, w ->> 'workload_id',
      (w ->> 'weight_basis_points')::integer, w ->> 'operation_mix_digest');
  end loop;

  for r in select value from jsonb_array_elements(p_request_sizes) loop
    insert into ops.benchmark_manifest_request_size(draft_id, ordinal, percentile, bytes)
    values (v_draft, (r ->> 'ordinal')::integer, (r ->> 'percentile')::integer,
      (r ->> 'bytes')::bigint);
  end loop;

  for c in select value from jsonb_array_elements(p_concurrency) loop
    insert into ops.benchmark_manifest_concurrency(draft_id, ordinal, concurrency_level)
    values (v_draft, (c ->> 'ordinal')::integer, (c ->> 'concurrency_level')::integer);
  end loop;

  for b in select value from jsonb_array_elements(p_browsers) loop
    insert into ops.benchmark_manifest_browser(draft_id, ordinal, name, version, build)
    values (v_draft, (b ->> 'ordinal')::integer, b ->> 'name', b ->> 'version', b ->> 'build');
  end loop;

  for e in select value from jsonb_array_elements(p_evaluators) loop
    insert into ops.benchmark_manifest_evaluator(
      draft_id, ordinal, actor_id, session_ref, authority_class)
    values (v_draft, (e ->> 'ordinal')::integer, e ->> 'actor_id',
      e ->> 'session_ref', e ->> 'authority_class');
  end loop;

  return v_draft;
end;
$$;


--
-- Name: FUNCTION benchmark_propose_manifest_draft(p_benchmark_ref text, p_draft_version integer, p_idempotency_key uuid, p_payload_digest text, p_scalars jsonb, p_dimensions jsonb, p_workloads jsonb, p_request_sizes jsonb, p_concurrency jsonb, p_browsers jsonb, p_evaluators jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_propose_manifest_draft(p_benchmark_ref text, p_draft_version integer, p_idempotency_key uuid, p_payload_digest text, p_scalars jsonb, p_dimensions jsonb, p_workloads jsonb, p_request_sizes jsonb, p_concurrency jsonb, p_browsers jsonb, p_evaluators jsonb) IS 'The only way to create a benchmark manifest draft. The draft is inert; the proposer is derived from the server-established writer context and is not a parameter. The supplied payload digest is compared at commit against one recomputed from the stored rows.';


--
-- Name: benchmark_readback(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_readback(p_benchmark_ref text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_draft ops.benchmark_manifest_draft%rowtype; v_accepted_id uuid;
begin
  select * into v_draft from ops.benchmark_manifest_draft
   where benchmark_ref = p_benchmark_ref
   order by draft_version desc limit 1;
  if not found then
    return jsonb_build_object('benchmark_ref', p_benchmark_ref, 'exists', false);
  end if;
  v_accepted_id := ops.benchmark_accepted_draft(p_benchmark_ref);

  return jsonb_build_object(
    'benchmark_ref', v_draft.benchmark_ref,
    'exists', true,
    'schema_version', v_draft.schema_version,
    'draft_version', v_draft.draft_version,
    'gate_id', v_draft.gate_id,
    'producer_step_ref', v_draft.producer_step_ref,
    'producer_role', v_draft.producer_role,
    'combiner', v_draft.combiner,
    -- Both digests are exposed on purpose: the STORED one is what the proposal
    -- claimed, the RECOMPUTED one is what the rows say now, and a reader that
    -- only ever saw one of them could not tell a tampered draft from a healthy
    -- one.
    'payload_digest', ops.benchmark_payload_digest(v_draft.id),
    'stored_payload_digest', v_draft.payload_digest,
    'payload', ops.benchmark_payload_preimage(v_draft.id),
    'structure_valid', ops.benchmark_draft_structure_valid(v_draft.id),
    'structure_error', ops.benchmark_draft_structure_error(v_draft.id),
    -- ORDERED BY (created_at, id), NOT created_at ALONE. created_at defaults to
    -- now(), which is transaction start time: every review written in one
    -- transaction carries the SAME instant, and an order that ties there returns
    -- rows in whatever order the plan happens to produce. The primary key breaks
    -- the tie, so two readers of the same draft see the same list.
    'reviews', (select coalesce(jsonb_agg(jsonb_build_object(
                         'verdict', r.verdict,
                         'reviewed_payload_digest', r.reviewed_payload_digest,
                         -- The bytes the review's writer NAMED. See
                         -- measurement_coverage_binding below before reading this
                         -- as verified coverage.
                         'measurement_set_digest', r.measurement_set_digest,
                         -- Per review, so a reader can see WHICH reviews carry an
                         -- attestation rather than being told about the rail in
                         -- general. A fail verdict carries none and needs none.
                         'coverage_proved_by', (
                           select a.coverage_proved_by
                             from ops.benchmark_measurement_coverage_attestation a
                            where a.review_id = r.id),
                         'reviewer_actor_id', r.reviewer_actor_id)
                       order by r.created_at, r.id), '[]'::jsonb)
                  from ops.benchmark_manifest_review r where r.draft_id = v_draft.id),
    -- Said out loud in the readback, because a caller reading a measurement
    -- digest off a passing review is entitled to know exactly how much this
    -- database checked -- which is more than nothing and much less than a
    -- verification.
    'measurement_coverage_binding', jsonb_build_object(
      'resolved', true,
      'note', 'measurement_set_digest names the bytes the review''s writer read. Beside each passing review this database records an attestation naming the kernel evaluator that proved coverage, the payload digest it proved against and the measurement digest it proved over, and it refuses an attestation whose payload digest the draft no longer produces. It still evaluates no coverage itself: the samples are outside this record layer and the evaluation cannot be repeated here, so this is an attributed, checkable assertion by a trusted writer and not an independent verification.'),
    'accepted', v_accepted_id is not null and v_accepted_id = v_draft.id,
    'accepted_draft_id', v_accepted_id,
    -- Inert by construction. Acceptance remains a separate human exact-hash act
    -- and starts no clock: the Journey 1 clock origin is the first current
    -- passing foundation-assurance-minimum receipt, which this rail neither
    -- issues nor reaches.
    'clock_started', false,
    'effects', jsonb_build_object(
      'creates_effect', false, 'jobs', 0, 'capabilities', 0, 'execution_envelopes', 0,
      'admissions', 0, 'schedules', 0, 'deployments', 0));
end;
$$;


--
-- Name: FUNCTION benchmark_readback(p_benchmark_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_readback(p_benchmark_ref text) IS 'Deterministic zero-effect readback of one benchmark: its payload rebuilt from the stored rows, both the stored and the recomputed digest, its reviews, and whether a partner has accepted it.';


--
-- Name: benchmark_review_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_review_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_live text; v_proposer uuid; v_error text; v_units integer;
begin
  select proposed_by_actor_id into v_proposer from ops.benchmark_manifest_draft
   where id = new.draft_id;
  if not found then
    raise exception 'benchmark review names an unknown draft';
  end if;
  -- The record layer's own bound on review_summary, counted the way the module
  -- that supplies it counts. See the proposal guard: the column check counts
  -- codepoints, this counts UTF-16 code units, and the two differ on astral
  -- text. r7 states no bound here at all -- this one belongs to this rail.
  v_units := ops.benchmark_utf16_length(new.review_summary);
  if v_units > 1000 then
    raise exception 'benchmark review summary is % UTF-16 code units; this rail bounds it to 1000', v_units;
  end if;
  -- The reviewer is the server-established writer, never a payload field.
  if new.reviewer_actor_id <> ops.portfolio_writer_actor_id() then
    raise exception 'benchmark review actor does not match the authenticated writer context';
  end if;
  -- CURRENTNESS. The digest is recomputed from the rows; a review naming
  -- anything else was written against different bytes.
  v_live := ops.benchmark_payload_digest(new.draft_id);
  if new.reviewed_payload_digest <> v_live then
    raise exception 'benchmark review digest is stale: expected %', v_live;
  end if;
  if new.verdict = 'pass' then
    v_error := ops.benchmark_draft_structure_error(new.draft_id);
    if v_error is not null then
      raise exception 'a benchmark draft that is not a complete r7 payload cannot pass review: %', v_error;
    end if;
    if new.reviewer_actor_id = v_proposer then
      raise exception 'a proposer may not pass their own benchmark draft';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION benchmark_review_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_review_guard() IS 'Refuses a benchmark review that is misattributed, over-long as the module measures length, written against a digest the draft no longer produces, a pass over an incomplete payload, or a self-review pass. It does not check coverage: nothing in this database does.';


--
-- Name: benchmark_review_manifest_draft(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_review_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_reviewed_payload_digest text, p_verdict text, p_measurement_set_digest text, p_review_summary text, p_coverage_attestation jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_id uuid;
  v_existing ops.benchmark_manifest_review%rowtype;
  v_existing_attestation ops.benchmark_measurement_coverage_attestation%rowtype;
  v_proved_by text; v_payload_digest text; v_measurements text; v_evaluation text;
  v_key text;
begin
  select * into v_existing from ops.benchmark_manifest_review where idempotency_key = p_idempotency_key;
  if found then
    -- EVERY STORED PARAMETER IS COMPARED, review_summary included. A replay that
    -- matched on the digests but carried different prose would return the first
    -- row while the caller believed the second had been recorded, which is the
    -- same silent divergence the digest comparison exists to prevent. The
    -- comparisons use IS DISTINCT FROM so a null measurement digest on both
    -- sides is a match rather than an unknown.
    if v_existing.draft_id is distinct from p_draft_id
       or v_existing.reviewed_payload_digest is distinct from p_reviewed_payload_digest
       or v_existing.verdict is distinct from p_verdict
       or v_existing.measurement_set_digest is distinct from p_measurement_set_digest
       or v_existing.review_summary is distinct from p_review_summary then
      raise exception 'benchmark idempotency key % was already used for a different review', p_idempotency_key;
    end if;
    -- THE ATTESTATION IS A STORED PARAMETER TOO, so it is compared on a replay
    -- for the same reason review_summary is: a replay carrying a different
    -- attestation is a different request wearing the same key, and returning the
    -- first row would leave the caller believing the second had been recorded.
    select * into v_existing_attestation from ops.benchmark_measurement_coverage_attestation
     where review_id = v_existing.id;
    if found <> (p_coverage_attestation is not null)
       or (p_coverage_attestation is not null and (
            v_existing_attestation.coverage_proved_by is distinct from (p_coverage_attestation ->> 'coverage_proved_by')
         or v_existing_attestation.benchmark_payload_digest is distinct from (p_coverage_attestation ->> 'benchmark_payload_digest')
         or v_existing_attestation.measurement_set_digest is distinct from (p_coverage_attestation ->> 'measurement_set_digest')
         or v_existing_attestation.evaluation_digest is distinct from (p_coverage_attestation ->> 'evaluation_digest'))) then
      raise exception 'benchmark idempotency key % was already used for a different review', p_idempotency_key;
    end if;
    return v_existing.id;
  end if;

  -- THE PASS/ATTESTATION PAIR, CHECKED BEFORE EITHER ROW EXISTS.
  if p_verdict = 'pass' and p_coverage_attestation is null then
    raise exception 'a passing benchmark review must record a measurement coverage attestation naming the kernel evaluator that proved coverage, the payload digest it proved against and the measurement digest it proved over; an unattested pass is refused';
  end if;
  if p_verdict <> 'pass' and p_coverage_attestation is not null then
    raise exception 'a benchmark review that does not pass proves no coverage and must record no coverage attestation';
  end if;

  if p_coverage_attestation is not null then
    if jsonb_typeof(p_coverage_attestation) <> 'object' then
      raise exception 'the benchmark coverage attestation must be an object';
    end if;
    -- CLOSED, the way every other shape in this rail is closed: an unknown key is
    -- a caller believing it recorded something that was silently dropped.
    for v_key in select key from jsonb_object_keys(p_coverage_attestation) as t(key) loop
      if v_key not in ('coverage_proved_by', 'benchmark_payload_digest',
                       'measurement_set_digest', 'evaluation_digest') then
        raise exception 'the benchmark coverage attestation carries an unknown field %', v_key;
      end if;
    end loop;
    v_proved_by      := p_coverage_attestation ->> 'coverage_proved_by';
    v_payload_digest := p_coverage_attestation ->> 'benchmark_payload_digest';
    v_measurements   := p_coverage_attestation ->> 'measurement_set_digest';
    v_evaluation     := p_coverage_attestation ->> 'evaluation_digest';
    if v_proved_by is null or v_payload_digest is null
       or v_measurements is null or v_evaluation is null then
      raise exception 'the benchmark coverage attestation must name the evaluator, the payload digest, the measurement digest and the evaluation digest';
    end if;
    if not (v_proved_by = any (ops.benchmark_coverage_evaluators())) then
      raise exception 'the benchmark coverage attestation names %, which is not a benchmark coverage evaluator this rail admits', v_proved_by;
    end if;
    -- THE ATTESTATION MUST BE ABOUT THIS REVIEW'S BYTES. Refused here as well as
    -- in the reader, because a row that never diverges is better than a
    -- divergence a later reader has to catch.
    if v_measurements is distinct from p_measurement_set_digest then
      raise exception 'the benchmark coverage attestation proves coverage over measurement set %, which is not the set this review names', v_measurements;
    end if;
    -- AND ABOUT THIS REVIEW'S PAYLOAD, pinned to the digest the review itself
    -- names rather than to a second recomputation here.
    --
    -- THAT IS NOT A WEAKER CHECK, AND THE REASON IS WORTH STATING. The review
    -- guard already refuses this insert unless p_reviewed_payload_digest is the
    -- digest ops.benchmark_payload_digest() produces from the draft's rows right
    -- now; it is the rail's ONE currentness authority and the same insert runs
    -- it. Pinning the attestation to that value therefore binds it to the live
    -- digest transitively, through the check that already exists, instead of
    -- adding a second currentness authority that could disagree with it. It also
    -- keeps an unknown draft arriving as the guard's named refusal rather than as
    -- a raw digest error, and it does not rebuild the whole preimage twice per
    -- review. The reader recomputes independently at acceptance time, which is
    -- where an attestation that has been outgrown actually matters.
    if v_payload_digest is distinct from p_reviewed_payload_digest then
      raise exception 'the benchmark coverage attestation proves coverage against payload digest %, which this draft does not produce', v_payload_digest;
    end if;
  end if;

  insert into ops.benchmark_manifest_review(
    draft_id, idempotency_key, reviewed_payload_digest, verdict,
    measurement_set_digest, review_summary, reviewer_actor_id)
  values (p_draft_id, p_idempotency_key, p_reviewed_payload_digest, p_verdict,
    p_measurement_set_digest, p_review_summary, ops.portfolio_writer_actor_id())
  returning id into v_id;

  if p_coverage_attestation is not null then
    -- SAME CALL, SAME TRANSACTION, SAME DERIVED ACTOR. The attesting writer is
    -- ops.portfolio_writer_actor_id() exactly as the reviewer is: the attestation
    -- is attributed to whoever recorded the review, and is not a parameter.
    insert into ops.benchmark_measurement_coverage_attestation(
      review_id, draft_id, coverage_proved_by, benchmark_payload_digest,
      measurement_set_digest, evaluation_digest, attested_by_actor_id)
    values (v_id, p_draft_id, v_proved_by, v_payload_digest,
      v_measurements, v_evaluation, ops.portfolio_writer_actor_id());
  end if;

  return v_id;
end;
$$;


--
-- Name: FUNCTION benchmark_review_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_reviewed_payload_digest text, p_verdict text, p_measurement_set_digest text, p_review_summary text, p_coverage_attestation jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_review_manifest_draft(p_draft_id uuid, p_idempotency_key uuid, p_reviewed_payload_digest text, p_verdict text, p_measurement_set_digest text, p_review_summary text, p_coverage_attestation jsonb) IS 'The only way to record an independent benchmark review, and the only way to record the coverage attestation that must accompany a passing one. The reviewer and the attesting writer are both derived from the server-established writer context and neither is a parameter. A pass with no attestation is refused and a non-pass with one is refused, so the pass and its attestation cannot come apart. The attestation is still a TRUSTED WRITER''s statement -- through the MCP verb its values are benchmark-minimum.v5.js''s own return value, through a direct call they are the writer''s assertion -- but it is now explicit, attributed, closed to a known evaluator set, and checked against the digest this draft actually produces. Every stored parameter, review_summary and the attestation included, is compared on an idempotent replay.';


--
-- Name: benchmark_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'DoctorCRE v5 benchmark rows are append-only: % is refused on ops.%',
    tg_op, tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: FUNCTION benchmark_rows_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_rows_immutable() IS 'Refuses every update, delete and truncate on the DoctorCRE v5 benchmark manifest tables. Installed twice per relation because a row-level trigger never sees TRUNCATE, and TRUNCATE cannot be revoked from the table owner.';


--
-- Name: benchmark_slo_thresholds(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_slo_thresholds() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'warm_core_navigation_p95_ms', 2000,
    'cold_lcp_p95_ms', 4000,
    'command_acknowledgement_p95_ms', 300)
$$;


--
-- Name: FUNCTION benchmark_slo_thresholds(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_slo_thresholds() IS 'The three fixed r7 SLO thresholds. Identity, not configuration: emitted into every payload preimage and never stored per draft.';


--
-- Name: benchmark_utf16_length(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.benchmark_utf16_length(p_text text) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select char_length(p_text) + coalesce((
    select count(*)::integer
      from unnest(regexp_split_to_array(p_text, '')) as ch
     where ascii(ch) > 65535), 0)
$$;


--
-- Name: FUNCTION benchmark_utf16_length(p_text text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.benchmark_utf16_length(p_text text) IS 'The length JavaScript String#length would report for this text: codepoints plus one per codepoint above U+FFFF. Used so a bound the kernel states in UTF-16 code units means the same thing in SQL.';


--
-- Name: bind_execution_environment_to_assignment(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.bind_execution_environment_to_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare provider ops.execution_environment_provider%rowtype; conformance ops.execution_environment_conformance%rowtype;
  requirement jsonb; configuration jsonb; requirement_digest text; configuration_digest text; binding jsonb; binding_digest text;
begin
  select p.* into provider from ops.execution_environment_provider p
   where p.provider_key='hermes-local' and ops.execution_environment_provider_current_state(p.id)='active'
   order by p.provider_version desc limit 1;
  select c.* into conformance from ops.execution_environment_conformance c
   where c.provider_id=provider.id order by c.observed_at desc,c.id desc limit 1;
  if provider.id is null or conformance.id is null or conformance.status<>'passed' then raise exception 'no admitted execution environment provider satisfies the route'; end if;
  requirement := jsonb_build_object('authority_capability_ref','capability:metadata-only','required_operation_refs',jsonb_build_array('operation:health'),'selection_policy_ref','selection:server-active-provider-v1','side_effect_policy_ref','side-effects:none','network_policy_ref','egress:denied-by-capability');
  configuration := jsonb_build_object('backend','local','persistent_shell',false,'timeout_seconds',180,'resource_policy_ref',provider.manifest->>'resource_policy_ref','secret_forwarding','none');
  requirement_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(requirement),'sha256'),'hex');
  configuration_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(configuration),'sha256'),'hex');
  binding := jsonb_build_object('provider_ref','environment-provider:'||provider.provider_key||':v'||provider.provider_version,'provider_version',provider.provider_version,'provider_digest',provider.manifest_digest,'requirement_digest',requirement_digest,'configuration_digest',configuration_digest,'backend_kind',provider.backend_kind,'source_class',provider.source_class,'isolation_class',provider.manifest->>'isolation_class','capability_refs',provider.manifest->'capability_refs','conformance_ref',conformance.run_ref,'conformance_digest',conformance.run_digest);
  binding_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(binding),'sha256'),'hex');
  binding := binding||jsonb_build_object('binding_digest',binding_digest);
  insert into ops.work_request_execution_environment_binding(assignment_id,provider_id,conformance_id,requirement,requirement_digest,configuration,configuration_digest,binding,binding_digest)
  values(new.id,provider.id,conformance.id,requirement,requirement_digest,configuration,configuration_digest,binding,binding_digest);
  return new;
end $$;


--
-- Name: bind_execution_environment_to_envelope(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.bind_execution_environment_to_envelope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare route ops.work_request_execution_environment_binding%rowtype; provider ops.execution_environment_provider%rowtype; runtime jsonb; topology jsonb;
begin
  select eb.* into route from ops.work_request_execution_assignment a join ops.work_request_execution_environment_binding eb on eb.assignment_id=a.id where a.work_request_id=new.work_request_id;
  select * into provider from ops.execution_environment_provider where id=route.provider_id;
  if route.id is null or provider.id is null or ops.execution_environment_provider_current_state(provider.id)<>'active'
     or route.conformance_id is distinct from (select c.id from ops.execution_environment_conformance c where c.provider_id=provider.id order by c.observed_at desc,c.id desc limit 1)
     or not exists(select 1 from ops.execution_environment_conformance c where c.id=route.conformance_id and c.status='passed') then
    raise exception 'execution envelope requires an active conformance-passed environment provider binding';
  end if;
  runtime := (new.runtime_profile-'digest')||jsonb_build_object(
    'environment_provider_ref',route.binding->>'provider_ref','environment_provider_version',(route.binding->>'provider_version')::integer,
    'environment_provider_digest',route.binding->>'provider_digest','environment_requirement_digest',route.requirement_digest,
    'environment_configuration_digest',route.configuration_digest,'environment_backend_kind',route.binding->>'backend_kind',
    'environment_source_class',route.binding->>'source_class','environment_isolation_class',route.binding->>'isolation_class',
    'environment_capability_refs',route.binding->'capability_refs','environment_conformance_ref',route.binding->>'conformance_ref',
    'environment_conformance_digest',route.binding->>'conformance_digest','environment_binding_digest',route.binding_digest);
  new.runtime_profile := runtime||jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(runtime),'sha256'),'hex'));
  topology := (new.execution_topology-'digest')||jsonb_build_object('sandbox_ref',route.binding->>'provider_ref');
  new.execution_topology := topology||jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(topology),'sha256'),'hex'));
  new.configuration_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(new.runtime_profile||new.execution_topology||new.evaluation_plan),'sha256'),'hex');
  new.envelope := jsonb_set(jsonb_set(new.envelope,'{runtime_profile}',new.runtime_profile,true),'{execution_topology}',new.execution_topology,true);
  new.envelope := jsonb_set(new.envelope,'{server_binding,adapter,configuration_fingerprint}',to_jsonb(new.configuration_digest),true);
  new.envelope_digest := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(new.envelope),'sha256'),'hex');
  return new;
end $$;


--
-- Name: bind_rule_controls(uuid, text[], text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.bind_rule_controls(p_rule_id uuid, p_control_keys text[], p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_rule rule%rowtype;
  v_requested text[];
  v_available text[];
  v_missing text[];
  v_statement_hash text;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug <> 'joe' then
    raise exception 'rule-control binding requires Joe authority; % cannot bind system enforcement',
      v_actor_slug;
  end if;
  if btrim(coalesce(p_reason,''))='' then
    raise exception 'rule-control binding reason is required';
  end if;

  v_requested := array(
    select distinct btrim(u.control_key)
      from unnest(coalesce(p_control_keys,'{}'::text[])) as u(control_key)
     where btrim(u.control_key)<>''
     order by btrim(u.control_key));
  if cardinality(v_requested)=0 then
    raise exception 'at least one registered control key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-control-binding:'||p_rule_id::text,0));
  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status not in ('proposed','active') then
    raise exception 'rule % is %, only proposed rules may be bound and active rules may only be verified',
      p_rule_id,v_rule.status;
  end if;
  v_statement_hash := encode(digest(v_rule.statement,'sha256'),'hex');

  select coalesce(array_agg(c.control_key order by c.control_key),'{}'::text[])
    into v_available
    from ops.enforcement_control_catalog c
   where c.control_key=any(v_requested)
     and c.installed and c.verified_at is not null
     and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema');
  v_missing := array(
    select requested.control_key
      from unnest(v_requested) as requested(control_key)
     where not (requested.control_key=any(v_available))
     order by requested.control_key);
  if cardinality(v_missing)>0 or cardinality(v_available)<>cardinality(v_requested) then
    raise exception 'rule-control binding refused: registered installed controls are missing %',v_missing;
  end if;

  -- An approved contract is immutable. Approval replay reaches this function,
  -- so an ACTIVE rule is accepted only as an exact no-write verification.
  if v_rule.status='active' then
    if exists (
      select 1 from unnest(v_requested) requested(control_key)
       where not exists (
         select 1 from ops.rule_control_binding b
          where b.rule_id=p_rule_id
            and b.control_key=requested.control_key
            and b.statement_hash=v_statement_hash)
    ) then
      raise exception 'active rule % lacks its immutable exact control binding',p_rule_id;
    end if;
    return jsonb_build_object(
      'ok',true,'replayed',true,'rule_id',p_rule_id,
      'bound_controls',v_available,'statement_hash',v_statement_hash);
  end if;

  insert into ops.rule_control_binding
    (rule_id,control_key,statement_hash,binding_contract)
  select p_rule_id,c.control_key,v_statement_hash,
         jsonb_build_object(
           'source','ops.bind_rule_controls',
           'rule_id',p_rule_id,
           'rule_version',v_rule.version,
           'statement_hash',v_statement_hash,
           'control_key',c.control_key,
           'implementation_ref',c.implementation_ref,
           'test_ref',c.test_ref,
           'binding_reason',btrim(p_reason),
           'bound_by',v_actor_slug)
    from ops.enforcement_control_catalog c
   where c.control_key=any(v_available)
  on conflict (rule_id,control_key) do update set
    statement_hash=excluded.statement_hash,
    binding_contract=excluded.binding_contract,
    bound_at=now();

  return jsonb_build_object(
    'ok',true,'replayed',false,'rule_id',p_rule_id,
    'bound_controls',v_available,'statement_hash',v_statement_hash);
end $$;


--
-- Name: bind_rule_delivery(uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.bind_rule_delivery(p_rule_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_rule rule%rowtype;
  v_admission ops.rule_admission%rowtype;
  v_delivery jsonb;
  v_load_layer text;
  v_packs text[];
  v_scope text;
  v_why text;
  v_digest text;
  v_existing ops.rule_load_layer%rowtype;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug <> 'joe' then
    raise exception 'rule-delivery binding requires Joe authority; % cannot bind system delivery',
      v_actor_slug;
  end if;
  if btrim(coalesce(p_reason,''))='' then
    raise exception 'rule-delivery binding reason is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-delivery-binding:'||p_rule_id::text,0));
  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status not in ('proposed','active') then
    raise exception 'rule % is %, only proposed rules may be bound and active rules may only be verified',
      p_rule_id,v_rule.status;
  end if;

  select coalesce(owner.slug,'shared') into v_scope
    from rule r left join actor owner on owner.id=r.personal_to
   where r.id=p_rule_id;
  if v_scope not in ('shared','joe','dell') then
    raise exception 'rule % has unsupported delivery scope %',p_rule_id,v_scope;
  end if;

  -- A durable row can predate this writer (migrations and existing acceptance
  -- fixtures used the owner-only table directly). Verify that legacy prebind
  -- instead of demanding it be rewritten through a newer admission shape.
  -- Active approval replay uses the same exact verification path.
  select * into v_existing from ops.rule_load_layer where rule_id=p_rule_id;
  if found then
    if v_existing.short_id<>left(p_rule_id::text,8)
       or v_existing.scope<>v_scope
       or v_existing.load_layer not in ('layer0','control','pack')
       or (v_existing.load_layer='layer0' and
           (cardinality(v_existing.packs)<>0 or nullif(btrim(coalesce(v_existing.why,'')),'') is null))
       or (v_existing.load_layer='pack' and cardinality(v_existing.packs)=0)
       or exists (select 1 from unnest(v_existing.packs) pack where pack='' or pack='*') then
      raise exception 'rule % delivery binding no longer matches its durable identity or activation contract',
        p_rule_id;
    end if;
    return jsonb_build_object(
      'ok',true,'replayed',true,'rule_id',p_rule_id,
      'load_layer',v_existing.load_layer,'packs',v_existing.packs,'scope',v_existing.scope);
  end if;
  if v_rule.status='active' then
    if v_existing.rule_id is null then
      raise exception 'active rule % lacks its delivery binding',p_rule_id;
    end if;
  end if;

  select * into v_admission from ops.rule_admission
   where rule_id=p_rule_id and state='admitted';
  if not found then
    raise exception 'rule % cannot bind delivery: admitted rule contract is missing',p_rule_id;
  end if;
  v_delivery := v_admission.projection->'delivery';
  if v_delivery is null or jsonb_typeof(v_delivery)<>'object' then
    raise exception 'rule % delivery projection is not activation-safe: projection.delivery is required',
      p_rule_id;
  end if;
  v_load_layer := btrim(coalesce(v_delivery->>'load_layer',''));
  if v_load_layer not in ('layer0','control','pack') then
    raise exception 'rule % delivery projection has invalid load_layer %',p_rule_id,v_load_layer;
  end if;
  if jsonb_typeof(v_delivery->'packs') is distinct from 'array'
     or exists (select 1 from jsonb_array_elements(v_delivery->'packs') item
                 where jsonb_typeof(item)<>'string') then
    raise exception 'rule % delivery projection packs must be an array of names',p_rule_id;
  end if;
  select coalesce(array_agg(pack order by pack),'{}'::text[]) into v_packs
    from (select distinct btrim(value) as pack
            from jsonb_array_elements_text(v_delivery->'packs') item(value)) named;
  if exists (select 1 from unnest(v_packs) pack where pack='' or pack='*') then
    raise exception 'rule % delivery projection contains an empty or wildcard pack',p_rule_id;
  end if;
  v_why := nullif(btrim(coalesce(v_delivery->>'why','')),'');
  if v_load_layer='layer0' and (cardinality(v_packs)<>0 or v_why is null) then
    raise exception 'rule % layer0 delivery must be unconditional and explain why',p_rule_id;
  end if;
  if v_load_layer='pack' and cardinality(v_packs)=0 then
    raise exception 'rule % pack delivery names no pack',p_rule_id;
  end if;
  v_digest := encode(digest(v_delivery::text,'sha256'),'hex');

  insert into ops.rule_load_layer
    (rule_id,short_id,load_layer,packs,scope,why,source,map_digest)
  values
    (p_rule_id,left(p_rule_id::text,8),v_load_layer,v_packs,v_scope,v_why,
     'ops.bind_rule_delivery',v_digest)
  on conflict (rule_id) do update set
    short_id=excluded.short_id,
    load_layer=excluded.load_layer,
    packs=excluded.packs,
    scope=excluded.scope,
    why=excluded.why,
    source=excluded.source,
    map_digest=excluded.map_digest,
    updated_at=now();

  return jsonb_build_object(
    'ok',true,'replayed',false,'rule_id',p_rule_id,
    'load_layer',v_load_layer,'packs',v_packs,'scope',v_scope,'map_digest',v_digest);
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: job; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.job (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    definition_key text CONSTRAINT job_definition_key_not_null1 NOT NULL,
    definition_version integer CONSTRAINT job_definition_version_not_null1 NOT NULL,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    scheduled_for timestamp with time zone NOT NULL,
    mode text DEFAULT 'live'::text NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    max_attempts integer NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_owner text,
    lease_token uuid,
    leased_until timestamp with time zone,
    timeout_seconds integer NOT NULL,
    last_failure_class text,
    last_failure_detail text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT job_max_attempts_check CHECK ((max_attempts > 0)),
    CONSTRAINT job_mode_check CHECK ((mode = ANY (ARRAY['shadow'::text, 'canary'::text, 'live'::text, 'replay'::text]))),
    CONSTRAINT job_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'retry_wait'::text, 'waiting_approval'::text, 'succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'dead_lettered'::text, 'skipped'::text]))),
    CONSTRAINT job_timeout_seconds_check CHECK ((timeout_seconds > 0)),
    CONSTRAINT running_job_has_a_lease CHECK (((state <> 'running'::text) OR ((lease_owner IS NOT NULL) AND (lease_token IS NOT NULL) AND (leased_until IS NOT NULL)))),
    CONSTRAINT terminal_job_has_ended CHECK (((state <> ALL (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'dead_lettered'::text, 'skipped'::text])) OR (ended_at IS NOT NULL)))
);


--
-- Name: calendar_canary_live_job(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_canary_live_job(p_job_id uuid, p_lease uuid) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; k text;
begin
 if session_user<>'carr_jobs' then raise exception using errcode='42501',message='calendar canary requires carr_jobs identity'; end if;
 select * into j from ops.job where id=p_job_id for update;
 select execution_kind into k from ops.job_definition where key=j.definition_key and version=j.definition_version;
 if not found or j.state<>'running' or j.lease_token<>p_lease or j.leased_until<now() then raise exception using errcode='55000',message='calendar canary requires current live job lease'; end if;
 if j.definition_key<>'calendar-fetch-daily' or j.definition_version<>5 or j.mode<>'canary' or k<>'deterministic' then raise exception using errcode='22023',message='job is not calendar-fetch-daily v5 deterministic canary'; end if;
 return j;
end $$;


--
-- Name: calendar_prebrief_attestor_sponsor(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_attestor_sponsor() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not pg_has_role(session_user,'carr_calendar_prebrief_attestors','member') then
    raise exception using errcode='42501',message='calendar prebrief attestor identity lacks its capability bundle';
  end if;
  case session_user
    when 'carr_calendar_prebrief_attestor_joe' then return 'joe';
    when 'carr_calendar_prebrief_attestor_dell' then return 'dell';
    else raise exception using errcode='42501',message='calendar prebrief requires its exact sponsor-bound verifier identity';
  end case;
end $$;


--
-- Name: calendar_prebrief_canonical_event_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_canonical_event_digest(p_events jsonb) RETURNS TABLE(event_count integer, canonical_event_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_events jsonb;
begin
  if p_events is null or pg_column_size(p_events)>262144 or jsonb_typeof(p_events)<>'array' then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires a bounded event array';
  end if;
  if jsonb_array_length(p_events)>128 or exists(
      select 1 from jsonb_array_elements(p_events) e(value)
       where pg_column_size(e.value)>4096 or jsonb_typeof(e.value)<>'object'
          or jsonb_typeof(e.value->'participant_refs')<>'array') then
    raise exception using errcode='22023',message='calendar prebrief verified envelope has invalid bounded events';
  end if;
  select coalesce(jsonb_agg(event order by event->>'occurrence_key'),'[]'::jsonb) into v_events
    from (select jsonb_set(e.value,'{participant_refs}',coalesce((select jsonb_agg(ref order by ref)
             from jsonb_array_elements_text(e.value->'participant_refs') refs(ref)),'[]'::jsonb)) event
            from jsonb_array_elements(p_events) e(value)) normalized;
  event_count:=jsonb_array_length(p_events);
  canonical_event_digest:=encode(digest(convert_to(v_events::text,'UTF8'),'sha256'),'hex');
  return next;
end $$;


--
-- Name: calendar_prebrief_joe_live_due_at(timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.calendar_prebrief_joe_live_due_at(p_now timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare local_now timestamp; local_due timestamp; due timestamptz;
begin
  if p_now is null then
    raise exception 'Joe calendar scheduler requires an observed instant';
  end if;
  local_now := p_now at time zone 'America/Chicago';
  if extract(isodow from local_now) not between 1 and 5
     or local_now::time < time '06:30'
     or local_now::time >= time '06:45' then
    return null;
  end if;
  local_due := local_now::date + time '06:30';
  due := local_due at time zone 'America/Chicago';
  return due;
end $$;


