--
-- Name: canonical_ownership_claim_projection(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_claim_projection(p_lease_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare ctx jsonb:=ops.canonical_ownership_trusted_context(); result jsonb;
begin
  if not coalesce((ctx->>'ok')::boolean,false) then return ctx; end if;
  if not exists(select 1 from ops.canonical_ownership_lease where id=p_lease_id
     and holder_session_ref=ctx->>'ownership_session_ref'
     and subject_envelope_id=(ctx->>'subject_envelope_id')::uuid) then
    return jsonb_build_object('ok',false,'reason_id','ownership_operation_subject_mismatch');
  end if;
  select jsonb_build_object('ok',true,'lease_id',p_lease_id,
    'path_claims',coalesce(jsonb_agg(jsonb_build_object('path',claim_value,'mode',claim_mode,'operation',operation)
      order by claim_value collate "C") filter(where claim_kind='path'),'[]'::jsonb),
    'resource_claims',coalesce(jsonb_agg(jsonb_build_object('resource',claim_value) order by claim_value collate "C")
      filter(where claim_kind='resource'),'[]'::jsonb)) into result
    from ops.canonical_ownership_claim where lease_id=p_lease_id;
  return result;
end $$;


--
-- Name: canonical_ownership_context(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_context jsonb:=ops.canonical_ownership_trusted_context();
begin
  if not coalesce((v_context->>'ok')::boolean,false) then
    return ops.canonical_ownership_refusal('IDENTITY_CONTEXT_INVALID','identity_context',
      '"active database-minted runtime binding"'::jsonb,
      jsonb_build_object('reason',coalesce(v_context->>'reason_id','binding_invalid'),
        'value_redacted',true));
  end if;
  return jsonb_build_object('ok',true,
    'tenant',v_context->>'organization_tenant_id',
    'actor_id',v_context->>'acting_actor_id',
    'actor_slug',v_context->>'acting_actor_slug',
    'session_ref',v_context->>'ownership_session_ref',
    'host_ref',v_context->>'execution_host_ref');
end $$;


--
-- Name: canonical_ownership_context_v1(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_context_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare tenant text:=nullif(btrim(current_setting('carr.organization_tenant_id',true)),'');
        actor_slug text:=nullif(btrim(current_setting('carr.acting_actor_slug',true)),'');
        session_ref text:=nullif(btrim(current_setting('carr.ownership_session_id',true)),'');
        host_ref text:=nullif(btrim(current_setting('carr.execution_host_id',true)),'');
        actor_id uuid;
begin
  if tenant is null or actor_slug is null or session_ref is null or host_ref is null then
    return ops.canonical_ownership_refusal('IDENTITY_CONTEXT_MISSING','identity_context',
      '["organization_tenant_id","acting_actor_slug","ownership_session_id","execution_host_id"]'::jsonb,
      jsonb_build_object('organization_tenant_id',tenant is not null,'acting_actor_slug',actor_slug is not null,
        'ownership_session_id',session_ref is not null,'execution_host_id',host_ref is not null));
  end if;
  if session_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or host_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' then
    return ops.canonical_ownership_refusal('IDENTITY_CONTEXT_INVALID','identity_context',
      '"canonical server identity refs"'::jsonb,'"invalid"'::jsonb);
  end if;
  select id into actor_id from public.actor where slug=actor_slug and active;
  if not found then
    return ops.canonical_ownership_refusal('IDENTITY_CONTEXT_INVALID','identity_context.actor',
      '"active canonical actor"'::jsonb,
      jsonb_build_object('reason','unknown_or_inactive','value_redacted',true));
  end if;
  return jsonb_build_object('ok',true,'tenant',tenant,'actor_id',actor_id,'actor_slug',actor_slug,
    'session_ref',session_ref,'host_ref',host_ref);
end $_$;


--
-- Name: canonical_ownership_currentness(uuid, integer, text, uuid, text, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_currentness(p_work_request_id uuid, p_work_request_version integer, p_work_request_digest text, p_accepted_plan_id uuid, p_accepted_plan_digest text, p_slice_plan_id uuid, p_slice_plan_digest text, p_slice_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_plan_ref text; v_plan_hash text;
begin
  perform 1 from ops.work_request w where w.id=p_work_request_id for share;
  select plan_ref,plan_hash into v_plan_ref,v_plan_hash
    from ops.sourced_work_request_plan where id=p_accepted_plan_id;
  if ops.engineering_contract_stale(v_plan_ref,coalesce(v_plan_hash,p_accepted_plan_digest),null) then
    return ops.canonical_ownership_refusal('WORK_REQUEST_BINDING_STALE','accepted_plan',
      '"current executable accepted plan"'::jsonb,
      jsonb_build_object('reason','accepted_plan_retired','value_redacted',true));
  end if;
  return ops.canonical_ownership_currentness_v1(p_work_request_id,p_work_request_version,
    p_work_request_digest,p_accepted_plan_id,p_accepted_plan_digest,p_slice_plan_id,
    p_slice_plan_digest,p_slice_ref);
end $$;


--
-- Name: canonical_ownership_currentness_v1(uuid, integer, text, uuid, text, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_currentness_v1(p_work_request_id uuid, p_work_request_version integer, p_work_request_digest text, p_accepted_plan_id uuid, p_accepted_plan_digest text, p_slice_plan_id uuid, p_slice_plan_digest text, p_slice_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare work_row ops.work_request%rowtype; plan_row ops.engineering_slice_plan%rowtype;
        source jsonb; canonical_deps jsonb;
        tenant text:=current_setting('carr.organization_tenant_id',true);
begin
  select * into work_row from ops.work_request where id=p_work_request_id;
  if not found or (work_row.organization_tenant_id is not null
     and work_row.organization_tenant_id is distinct from tenant) then
    return ops.canonical_ownership_refusal('WORK_REQUEST_NOT_FOUND','work_request',
      '"tenant-visible canonical work request"'::jsonb,'"absent"'::jsonb);
  end if;
  source:=ops.engineering_admission_source(work_row.ref);
  if source is null or work_row.version is distinct from p_work_request_version
     or source->'work_request'->>'id' is distinct from 'wr:'||p_work_request_id::text
     or (source->'work_request'->>'version')::integer is distinct from p_work_request_version
     or source->'work_request'->>'canonical_record_digest' is distinct from p_work_request_digest
     or (source->'accepted_plan'->>'record_id')::uuid is distinct from p_accepted_plan_id
     or source->'accepted_plan'->>'digest' is distinct from p_accepted_plan_digest then
    return ops.canonical_ownership_refusal('WORK_REQUEST_BINDING_STALE','work_request.binding',
      '"submitted binding matches canonical source"'::jsonb,
      jsonb_build_object('reason','binding_stale','value_redacted',true));
  end if;
  select * into plan_row from ops.engineering_slice_plan where id=p_slice_plan_id;
  if not found then
    return ops.canonical_ownership_refusal('SLICE_PLAN_NOT_FOUND','slice_plan',
      '"canonical slice plan"'::jsonb,'"absent"'::jsonb);
  end if;
  if plan_row.work_request_id is distinct from p_work_request_id
     or plan_row.accepted_plan_id is distinct from p_accepted_plan_id
     or plan_row.work_request_version is distinct from p_work_request_version
     or plan_row.accepted_plan_hash is distinct from p_accepted_plan_digest
     or plan_row.plan_digest is distinct from p_slice_plan_digest then
    return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.binding',
      '"submitted binding matches canonical slice plan"'::jsonb,
      jsonb_build_object('reason','binding_stale','value_redacted',true));
  end if;
  canonical_deps:=ops.canonical_ownership_plan_dependencies(p_slice_plan_id,p_slice_ref);
  if not coalesce((canonical_deps->>'ok')::boolean,false) then
    return canonical_deps;
  end if;
  return jsonb_build_object('ok',true);
end $$;


--
-- Name: canonical_ownership_dependency_state(uuid, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_dependency_state(p_work_request_id uuid, p_slice_plan_id uuid, p_slice_ref text, p_required_state text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare leaf_count integer; leaf ops.engineering_execution_envelope%rowtype;
        receipt ops.engineering_slice_receipt%rowtype; review ops.engineering_reviewer_fact%rowtype;
        plan_row ops.engineering_slice_plan%rowtype; receipt_slice jsonb;
        receipt_slice_count integer; receipt_attempt integer;
        session_executor uuid; session_slug text;
        reviewer_slug text; executor_session text; deviation_refs text[];
        -- V5-F03: the accepted slice field set for this plan's own version.
        slice_fields text[];
begin
  select count(*) into leaf_count from ops.engineering_execution_envelope e
   where e.work_request_id=p_work_request_id and e.slice_plan_id=p_slice_plan_id and e.slice_ref=p_slice_ref
     and not exists (select 1 from ops.engineering_execution_envelope successor
                      where successor.supersedes_envelope_id=e.id);
  if leaf_count<>1 then
    return ops.canonical_ownership_refusal('DEPENDENCY_MISSING','dependency',
      '"exactly one unsuperseded envelope leaf"'::jsonb,
      jsonb_build_object('slice_ref',p_slice_ref,'leaf_count',leaf_count));
  end if;
  select e.* into leaf from ops.engineering_execution_envelope e
   where e.work_request_id=p_work_request_id and e.slice_plan_id=p_slice_plan_id and e.slice_ref=p_slice_ref
     and not exists (select 1 from ops.engineering_execution_envelope successor
                      where successor.supersedes_envelope_id=e.id);
  select r.* into receipt from ops.engineering_slice_receipt r where r.envelope_id=leaf.id
   order by r.created_at desc,r.id desc limit 1;
  select sp.* into plan_row from ops.engineering_slice_plan sp
   where sp.id=p_slice_plan_id;
  select count(*),min(value::text)::jsonb
    into receipt_slice_count,receipt_slice
    from jsonb_array_elements(case
      when jsonb_typeof(plan_row.plan->'slices')='array'
      then plan_row.plan->'slices' else '[]'::jsonb end)
   where value->>'slice_ref'=p_slice_ref;
  -- V5-F03: the accepted slice field set is now selected by the plan's own
  -- sealed schema_version.  NULL means an unsupported version; the condition
  -- below refuses on it explicitly, and ops.engineering_receipt_exact_object is
  -- STRICT so it would refuse on it anyway.
  slice_fields := ops.engineering_slice_plan_slice_fields(plan_row.plan->>'schema_version');
  select ja.attempt into receipt_attempt from ops.job_attempt ja
   where ja.id=receipt.job_attempt_id and ja.job_id=leaf.job_id;
  select s.executor_actor_id,a.slug into session_executor,session_slug
    from ops.capability_agent_session s
    join public.actor a on a.id=s.executor_actor_id and a.active
   where s.id=leaf.agent_session_id and s.work_request_id=p_work_request_id;
  if receipt.id is null or receipt.outcome is distinct from 'claimed_complete'
     or receipt.work_request_id is distinct from p_work_request_id
     or receipt.envelope_id is distinct from leaf.id
     or receipt.slice_ref is distinct from p_slice_ref
     or plan_row.id is null
     or plan_row.work_request_id is distinct from p_work_request_id
     or leaf.slice_plan_id is distinct from plan_row.id
     or slice_fields is null
     or leaf.envelope->>'envelope_id'
          is distinct from 'env:'||leaf.id::text
     or leaf.envelope#>>'{request,job_ref}'
          is distinct from 'job:'||leaf.job_id::text
     or leaf.envelope#>>'{agent_session,id}'
          is distinct from 'session:'||leaf.agent_session_id::text
     or receipt.executor_actor_id is distinct from session_executor
     or session_slug is null
     or receipt_attempt is null
     or receipt.attempt_id is distinct from ('attempt:'||receipt_attempt)
     or receipt_slice_count<>1
     or not coalesce(ops.engineering_receipt_exact_object(receipt.receipt,array[
          'actual_component_refs','actual_resource_refs','artifact_refs','attribution','attempt_id','checks',
          'deviations','envelope_digest','evidence_refs','executor_claim','independent_verification_required',
          'outcome','plan_digest','planned_component_refs','planned_resource_refs','reset_reconstruction',
          'schema_version','slice_ref','source_evidence'
        ]),false)
     or receipt.receipt->>'schema_version' is distinct from 'engineering-slice-receipt.v1'
     or receipt.receipt_digest is distinct from
        ('sha256:'||encode(public.digest(
          ops.guidance_import_canonical_json(receipt.receipt),'sha256'),'hex'))
     or receipt.receipt->>'outcome' is distinct from 'claimed_complete'
     or receipt.receipt->>'slice_ref' is distinct from p_slice_ref
     or receipt.receipt->>'attempt_id' is distinct from receipt.attempt_id
     or receipt.receipt->>'envelope_digest' is distinct from leaf.envelope_digest
     or receipt.receipt->>'plan_digest' is distinct from plan_row.plan_digest
     or receipt.receipt->'independent_verification_required' is distinct from 'true'::jsonb
     or not coalesce(ops.engineering_receipt_exact_object(
          receipt.receipt->'attribution',array['actor_ref','adapter_ref','session_ref']),false)
     or leaf.envelope#>>'{server_binding,identity,agent_principal_id}' is null
     or leaf.envelope#>>'{agent_session,id}' is null
     or leaf.envelope#>>'{server_binding,adapter,adapter_id}' is null
     or receipt.receipt#>>'{attribution,actor_ref}' is distinct from
        leaf.envelope#>>'{server_binding,identity,agent_principal_id}'
     or receipt.receipt#>>'{attribution,session_ref}' is distinct from
        leaf.envelope#>>'{agent_session,id}'
     or receipt.receipt#>>'{attribution,adapter_ref}' is distinct from
        leaf.envelope#>>'{server_binding,adapter,adapter_id}'
     -- V5-F03: the one replaced expression.  0450:433-439 hard-coded the 16 v1
     -- fields here, which refused every engineering-slice-plan.v2 slice.
     or not coalesce(ops.engineering_receipt_exact_object(receipt_slice,slice_fields),false)
     or receipt_slice->>'slice_ref' is distinct from p_slice_ref
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt_slice->'declared_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt_slice->'declared_component_refs'),false)
     or jsonb_typeof(receipt_slice->'planned_checks') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(receipt_slice->'planned_checks')='array'
                          then jsonb_array_length(receipt_slice->'planned_checks')>0
                          else false end,false)
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt_slice->'planned_checks')='array'
         then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
        where not coalesce(ops.engineering_receipt_exact_object(
                planned_check,array['check_ref','evidence_requirement',
                                    'failure_condition']),false)
           or not coalesce((planned_check->>'check_ref') ~
                '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or not coalesce(planned_check->>'evidence_requirement'=any(array[
                'redacted_evidence_required','metadata_only_sufficient']),false)
           or jsonb_typeof(planned_check->'failure_condition') is distinct from 'string'
           or not coalesce(btrim(planned_check->>'failure_condition')<>'',false)
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt_slice->'planned_checks')='array'
         then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
       group by planned_check->>'check_ref' having count(*)>1
     )
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt.receipt->'planned_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt.receipt->'actual_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt.receipt->'planned_component_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt.receipt->'actual_component_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          receipt.receipt->'artifact_refs'),false)
     or not coalesce(ops.engineering_receipt_evidence_array(
          receipt.receipt->'evidence_refs'),false)
     or not coalesce(case
          when jsonb_typeof(receipt.receipt->'artifact_refs')='array'
          then jsonb_array_length(receipt.receipt->'artifact_refs')>0
          else false end,false)
     or not coalesce(case
          when jsonb_typeof(receipt.receipt->'evidence_refs')='array'
          then jsonb_array_length(receipt.receipt->'evidence_refs')>0
          else false end,false)
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          receipt.receipt->'planned_resource_refs',
          receipt_slice->'declared_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          receipt.receipt->'planned_component_refs',
          receipt_slice->'declared_component_refs'),false)
     or jsonb_typeof(receipt.receipt->'checks') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(receipt.receipt->'checks')='array'
                          then jsonb_array_length(receipt.receipt->'checks')>0
                          else false end,false)
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'checks')='array'
         then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
        where not coalesce(ops.engineering_receipt_exact_object(
                receipt_check,array['check_ref','evidence_refs','state']),false)
           or not coalesce((receipt_check->>'check_ref') ~
                '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or receipt_check->>'state' is distinct from 'passed'
           or not coalesce(ops.engineering_receipt_evidence_array(
                receipt_check->'evidence_refs'),false)
           or not coalesce(case
                when jsonb_typeof(receipt_check->'evidence_refs')='array'
                then jsonb_array_length(receipt_check->'evidence_refs')>0
                else false end,false)
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'checks')='array'
         then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
       group by receipt_check->>'check_ref' having count(*)>1
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'checks')='array'
         then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
        where not exists (
          select 1 from jsonb_array_elements(case
            when jsonb_typeof(receipt_slice->'planned_checks')='array'
            then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
           where planned_check->>'check_ref'=receipt_check->>'check_ref')
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt_slice->'planned_checks')='array'
         then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
        where not exists (
          select 1 from jsonb_array_elements(case
            when jsonb_typeof(receipt.receipt->'checks')='array'
            then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
           where receipt_check->>'check_ref'=planned_check->>'check_ref')
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'checks')='array'
         then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
       join jsonb_array_elements(case
         when jsonb_typeof(receipt_slice->'planned_checks')='array'
         then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
         on planned_check->>'check_ref'=receipt_check->>'check_ref'
        where not exists (
          select 1 from jsonb_array_elements(case
            when jsonb_typeof(receipt_check->'evidence_refs')='array'
            then receipt_check->'evidence_refs' else '[]'::jsonb end) evidence
           where evidence->>'redaction_class'=case
             when planned_check->>'evidence_requirement'='redacted_evidence_required'
             then 'redacted_evidence' else 'metadata_only' end)
     )
     or jsonb_typeof(receipt.receipt->'deviations') is distinct from 'array'
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'deviations')='array'
         then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
        where not coalesce(ops.engineering_receipt_exact_object(deviation,array[
                'category','deviation_ref','evidence_refs','impact','out_of_scope_component_refs',
                'out_of_scope_resource_refs','plan_revision_required','reason','review_state'
              ]),false)
           or not coalesce((deviation->>'deviation_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or exists (select 1 from unnest(array['category','reason','impact']) field
                       where jsonb_typeof(deviation->field) is distinct from 'string'
                          or not coalesce(btrim(deviation->>field)<>'',false))
           or jsonb_typeof(deviation->'plan_revision_required') is distinct from 'boolean'
           or not coalesce(ops.engineering_receipt_evidence_array(deviation->'evidence_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_resource_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_component_refs'),false)
           or deviation->>'review_state' is distinct from 'resolved'
           or deviation->'plan_revision_required' is distinct from 'false'::jsonb
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'deviations')='array'
         then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
       group by deviation->>'deviation_ref' having count(*)>1
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'actual_resource_refs')='array'
         then receipt.receipt->'actual_resource_refs' else '[]'::jsonb end) actual_ref
        where not exists (
          select 1 from jsonb_array_elements(case
            when jsonb_typeof(receipt_slice->'declared_resource_refs')='array'
            then receipt_slice->'declared_resource_refs' else '[]'::jsonb end) declared_ref
           where declared_ref=actual_ref)
          and not exists (
            select 1 from jsonb_array_elements(case
              when jsonb_typeof(receipt.receipt->'deviations')='array'
              then receipt.receipt->'deviations' else '[]'::jsonb end) deviation,
              jsonb_array_elements(case
                when jsonb_typeof(deviation->'out_of_scope_resource_refs')='array'
                then deviation->'out_of_scope_resource_refs' else '[]'::jsonb end) approved_ref
             where deviation->>'review_state'='resolved' and approved_ref=actual_ref)
     )
     or exists (
       select 1 from jsonb_array_elements(case
         when jsonb_typeof(receipt.receipt->'actual_component_refs')='array'
         then receipt.receipt->'actual_component_refs' else '[]'::jsonb end) actual_ref
        where not exists (
          select 1 from jsonb_array_elements(case
            when jsonb_typeof(receipt_slice->'declared_component_refs')='array'
            then receipt_slice->'declared_component_refs' else '[]'::jsonb end) declared_ref
           where declared_ref=actual_ref)
          and not exists (
            select 1 from jsonb_array_elements(case
              when jsonb_typeof(receipt.receipt->'deviations')='array'
              then receipt.receipt->'deviations' else '[]'::jsonb end) deviation,
              jsonb_array_elements(case
                when jsonb_typeof(deviation->'out_of_scope_component_refs')='array'
                then deviation->'out_of_scope_component_refs' else '[]'::jsonb end) approved_ref
             where deviation->>'review_state'='resolved' and approved_ref=actual_ref)
     )
     or not coalesce(ops.engineering_receipt_exact_object(
          receipt.receipt->'source_evidence',
          array['branch_ref','evidence_refs','source_sha','worktree_ref']),false)
     or exists (
       select 1 from unnest(array['worktree_ref','branch_ref','source_sha']) field
        where jsonb_typeof(receipt.receipt->'source_evidence'->field)
                is distinct from 'string'
           or not coalesce(btrim(
                receipt.receipt->'source_evidence'->>field)<>'',false)
           or (field<>'source_sha' and not coalesce(
                (receipt.receipt->'source_evidence'->>field) ~
                '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false))
     )
     or not coalesce(ops.engineering_receipt_evidence_array(
          receipt.receipt->'source_evidence'->'evidence_refs'),false)
     or not coalesce(ops.engineering_receipt_exact_object(
          receipt.receipt->'reset_reconstruction',array[
            'fresh_session','inherited_transcript_used',
            'reconstruction_free','remediation_action']),false)
     or receipt.receipt->'reset_reconstruction'->'fresh_session'
          is distinct from 'true'::jsonb
     or receipt.receipt->'reset_reconstruction'->'inherited_transcript_used'
          is distinct from 'false'::jsonb
     or jsonb_typeof(receipt.receipt->'reset_reconstruction'
          ->'reconstruction_free') is distinct from 'boolean'
     or (receipt.receipt->'reset_reconstruction'->'reconstruction_free'='false'::jsonb
         and (jsonb_typeof(receipt.receipt->'reset_reconstruction'
                ->'remediation_action') is distinct from 'string'
              or not coalesce(btrim(receipt.receipt->'reset_reconstruction'
                ->>'remediation_action')<>'',false)))
     or (receipt.receipt->'reset_reconstruction'->'reconstruction_free'='true'::jsonb
         and receipt.receipt->'reset_reconstruction'->'remediation_action'
                is distinct from 'null'::jsonb
         and (jsonb_typeof(receipt.receipt->'reset_reconstruction'
                ->'remediation_action') is distinct from 'string'
              or not coalesce(btrim(receipt.receipt->'reset_reconstruction'
                ->>'remediation_action')<>'',false)))
     or not coalesce(ops.engineering_receipt_exact_object(
          receipt.receipt->'executor_claim',
          array['claim_state','claimed_at','claimed_by']),false)
     or receipt.receipt->'executor_claim'->>'claim_state'
          is distinct from 'executor_claim'
     or receipt.receipt->'executor_claim'->>'claimed_by'
          is distinct from session_slug
     or jsonb_typeof(receipt.receipt->'executor_claim'->'claimed_at')
          is distinct from 'string'
     or not coalesce(btrim(receipt.receipt->'executor_claim'
          ->>'claimed_at')<>'',false) then
    return ops.canonical_ownership_refusal('DEPENDENCY_UNSATISFIED','dependency',
      to_jsonb(p_required_state),jsonb_build_object(
        'slice_ref',p_slice_ref,'receipt_id',receipt.id,'outcome',receipt.outcome));
  end if;
  if p_required_state='completed' then
    return jsonb_build_object('ok',true,'envelope_id',leaf.id,'receipt_id',receipt.id,'reviewer_fact_id',null);
  end if;
  select f.* into review from ops.engineering_reviewer_fact f where f.receipt_id=receipt.id
   order by f.created_at desc,f.id desc limit 1;
  select a.slug into reviewer_slug from public.actor a
   where a.id=review.reviewer_actor_id and a.active;
  executor_session:=receipt.receipt#>>'{attribution,session_ref}';
  select coalesce(array_agg(d->>'deviation_ref' order by d->>'deviation_ref'),'{}'::text[])
    into deviation_refs from jsonb_array_elements(receipt.receipt->'deviations') d;
  if review.id is null or review.state is distinct from 'passed'
     or review.contract_version is distinct from 'engineering-review.v1'
     or review.work_request_id is distinct from receipt.work_request_id
     or review.slice_ref is distinct from receipt.slice_ref
     or reviewer_slug is null
     or not coalesce(ops.engineering_receipt_exact_object(review.fact,array[
          'attempt_id','evidence_refs','is_independent','resolved_deviation_refs',
          'reviewed_deviation_refs','reviewer_ref','session_ref','slice_ref','state'
        ]),false)
     or review.reviewer_actor_id=receipt.executor_actor_id
     or review.fact->>'state' is distinct from 'passed' or review.fact->'is_independent' is distinct from 'true'::jsonb
     or review.fact->>'attempt_id' is distinct from receipt.attempt_id or review.fact->>'slice_ref' is distinct from p_slice_ref
     or not coalesce(review.fact->>'reviewer_ref'=any(array[
          reviewer_slug,'actor:'||reviewer_slug,'reviewer:'||reviewer_slug
        ]),false)
     or review.reviewer_session_ref is distinct from review.fact->>'session_ref'
     or review.reviewer_session_ref=executor_session
     or not coalesce(ops.engineering_receipt_evidence_array(review.fact->'evidence_refs'),false)
     or not coalesce(case when jsonb_typeof(review.fact->'evidence_refs')='array'
                          then jsonb_array_length(review.fact->'evidence_refs')>0
                          else false end,false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          review.fact->'reviewed_deviation_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(
          review.fact->'resolved_deviation_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          review.fact->'reviewed_deviation_refs',to_jsonb(deviation_refs)),false)
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          review.fact->'resolved_deviation_refs',to_jsonb(deviation_refs)),false) then
    return ops.canonical_ownership_refusal('DEPENDENCY_UNSATISFIED','dependency',
      '"independently_verified"'::jsonb,jsonb_build_object(
        'slice_ref',p_slice_ref,'receipt_id',receipt.id,
        'reviewer_fact_id',review.id,'review_state',review.state));
  end if;
  return jsonb_build_object('ok',true,'envelope_id',leaf.id,'receipt_id',receipt.id,'reviewer_fact_id',review.id);
end $_$;


--
-- Name: FUNCTION canonical_ownership_dependency_state(p_work_request_id uuid, p_slice_plan_id uuid, p_slice_ref text, p_required_state text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.canonical_ownership_dependency_state(p_work_request_id uuid, p_slice_plan_id uuid, p_slice_ref text, p_required_state text) IS 'Current Engineering lineage state for one dependency slice. The accepted slice field set is selected by the plan''s own sealed schema_version; every dependency, lease, currentness, identity and reviewer rule is unchanged, and an unsupported version or a malformed slice still fails closed.';


--
-- Name: canonical_ownership_lifecycle(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_lifecycle(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare ctx jsonb:=ops.canonical_ownership_trusted_context();
  rs ops.canonical_ownership_runtime_session%rowtype;
  e ops.engineering_execution_envelope%rowtype;
  sp ops.engineering_slice_plan%rowtype;
  prior ops.canonical_ownership_operation%rowtype;
  op text:=p_request->>'operation'; key uuid; digest text; result jsonb; keys text[];
  ttl integer; lease ops.canonical_ownership_lease%rowtype;
  scope ops.source_merge_plan_scope%rowtype; paths jsonb; resources jsonb; deps jsonb; slice jsonb;
begin
  if not coalesce((ctx->>'ok')::boolean,false) then return ctx; end if;
  keys:=case op
    when 'acquire' then array['operation','idempotency_key','ttl_seconds']
    when 'check' then array['operation','idempotency_key','lease_id','lease_token','fencing_generation']
    when 'renew' then array['operation','idempotency_key','lease_id','lease_token','fencing_generation','ttl_seconds']
    when 'release' then array['operation','idempotency_key','lease_id','lease_token','fencing_generation'] end;
  if keys is null or not coalesce(ops.engineering_receipt_exact_object(p_request,keys),false)
     or coalesce(p_request->>'idempotency_key','') !~ '^[0-9a-f-]{36}$' then
    return jsonb_build_object('ok',false,'reason_id','ownership_operation_invalid');
  end if;
  key:=(p_request->>'idempotency_key')::uuid;
  digest:=encode(public.digest(p_request::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('ownership-operation:'||key::text,0));
  select * into prior from ops.canonical_ownership_operation where idempotency_key=key;
  if found then
    if prior.runtime_binding_id is distinct from (ctx->>'binding_id')::uuid
       or prior.request_digest is distinct from digest then
      return jsonb_build_object('ok',false,'reason_id','ownership_operation_idempotency_conflict');
    end if;
    return prior.response||jsonb_build_object('replayed',true);
  end if;
  select * into rs from ops.canonical_ownership_runtime_session where id=(ctx->>'binding_id')::uuid;
  select * into e from ops.engineering_execution_envelope where id=rs.subject_envelope_id;
  select * into sp from ops.engineering_slice_plan where id=e.slice_plan_id;
  if op in ('acquire','renew') then
    ttl:=(p_request->>'ttl_seconds')::integer;
    if ttl is null or ttl<30 or ttl>1800 or clock_timestamp()+make_interval(secs=>ttl)>rs.expires_at then
      return jsonb_build_object('ok',false,'reason_id','ownership_operation_ttl_exceeds_binding');
    end if;
  end if;
  if op='acquire' then
    if not exists(select 1 from ops.canonical_ownership_issuer_generation
        where principal=session_user and state='active') then
      return jsonb_build_object('ok',false,'reason_id','ownership_issuer_draining');
    end if;
    select s.* into scope from ops.source_merge_plan_scope s
      join ops.sourced_work_request_plan_acceptance_receipt ar on ar.id=s.acceptance_receipt_id
      where s.accepted_plan_id=rs.accepted_plan_id and s.work_request_id=rs.work_request_id
        and s.organization_tenant_id=rs.organization_tenant_id and ar.result_version=e.state_version;
    if not found then return jsonb_build_object('ok',false,'reason_id','ownership_accepted_scope_missing'); end if;
    select jsonb_agg(jsonb_build_object('path',p,'mode','file','operation','write') order by p collate "C")
      into paths from jsonb_array_elements_text(scope.authorized_paths) p;
    select item into slice from jsonb_array_elements(sp.plan->'slices') item where item->>'slice_ref'=e.slice_ref;
    if slice is null or jsonb_typeof(slice->'declared_resource_refs') is distinct from 'array'
       or jsonb_typeof(slice->'declared_component_refs') is distinct from 'array' then
      return jsonb_build_object('ok',false,'reason_id','ownership_registered_claims_invalid');
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('resource',ref) order by ref collate "C"),'[]'::jsonb)
      into resources from (select distinct value ref from jsonb_array_elements_text(
        (slice->'declared_resource_refs')||(slice->'declared_component_refs'))) r;
    deps:=ops.canonical_ownership_plan_dependencies(e.slice_plan_id,e.slice_ref);
    if not coalesce((deps->>'ok')::boolean,false) then return deps; end if;
    result:=ops.acquire_canonical_ownership_lease(e.work_request_id,e.state_version,
      e.canonical_record_digest,e.accepted_plan_id,sp.accepted_plan_hash,e.slice_plan_id,
      sp.plan_digest,e.slice_ref,scope.scope_digest,paths,resources,deps->'dependencies',ttl);
  else
    select * into lease from ops.canonical_ownership_lease where id=(p_request->>'lease_id')::uuid;
    if not found or lease.subject_envelope_id is distinct from rs.subject_envelope_id
       or lease.holder_session_ref is distinct from rs.ownership_session_ref then
      return jsonb_build_object('ok',false,'reason_id','ownership_operation_subject_mismatch');
    end if;
    case op
      when 'check' then
        select coalesce(jsonb_agg(jsonb_build_object('path',claim_value,'mode',claim_mode,'operation',operation)
          order by claim_value collate "C") filter(where claim_kind='path'),'[]'::jsonb),
          coalesce(jsonb_agg(jsonb_build_object('resource',claim_value) order by claim_value collate "C")
          filter(where claim_kind='resource'),'[]'::jsonb) into paths,resources
          from ops.canonical_ownership_claim where lease_id=lease.id;
        result:=ops.check_canonical_ownership_lease(lease.id,
        (p_request->>'lease_token')::uuid,(p_request->>'fencing_generation')::bigint,
        paths,resources);
      when 'renew' then result:=ops.renew_canonical_ownership_lease(lease.id,
        (p_request->>'lease_token')::uuid,(p_request->>'fencing_generation')::bigint,ttl);
      when 'release' then result:=ops.release_canonical_ownership_lease(lease.id,
        (p_request->>'lease_token')::uuid,(p_request->>'fencing_generation')::bigint);
    end case;
  end if;
  insert into ops.canonical_ownership_operation(idempotency_key,runtime_binding_id,request_digest,operation,response)
  values(key,rs.id,digest,op,result);
  return result||jsonb_build_object('replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range then
  return jsonb_build_object('ok',false,'reason_id','ownership_operation_invalid');
end $_$;


--
-- Name: canonical_ownership_lock_lineage(uuid, uuid, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_lock_lineage(p_holder_actor_id uuid, p_slice_plan_id uuid, p_slice_refs text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare lock_key text;
begin
  perform 1 from ops.capability_agent_session s
   where s.id in (select e.agent_session_id from ops.engineering_execution_envelope e
                   where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs))
   order by s.id for share;
  perform 1 from public.actor a
   where a.id in (
     select s.executor_actor_id from ops.capability_agent_session s
      join ops.engineering_execution_envelope e on e.agent_session_id=s.id
     where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs)
     union
     select r.reviewer_actor_id from ops.engineering_reviewer_fact r
      join ops.engineering_slice_receipt receipt on receipt.id=r.receipt_id
      join ops.engineering_execution_envelope e on e.id=receipt.envelope_id
     where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs)
     union
     select p_holder_actor_id
   ) order by a.id for share;
  for lock_key in
    select 'engineering-envelope:'||p_slice_plan_id::text||':'||slice_ref
      from unnest(p_slice_refs) slice_ref order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended(lock_key,0));
  end loop;
  perform 1 from ops.engineering_execution_envelope e
   where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs)
   order by e.id for key share;
  perform 1 from ops.engineering_slice_plan sp where sp.id=p_slice_plan_id order by sp.id for key share;
  perform 1 from ops.work_request w
   where w.id=(select sp.work_request_id from ops.engineering_slice_plan sp where sp.id=p_slice_plan_id)
   order by w.id for share;
  perform 1 from ops.engineering_slice_receipt r
   where r.envelope_id in (select e.id from ops.engineering_execution_envelope e
                            where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs))
   order by r.created_at,r.id for key share;
  perform 1 from ops.engineering_reviewer_fact f
   where f.receipt_id in (
     select r.id from ops.engineering_slice_receipt r
      join ops.engineering_execution_envelope e on e.id=r.envelope_id
     where e.slice_plan_id=p_slice_plan_id and e.slice_ref=any(p_slice_refs))
   order by f.created_at,f.id for key share;
end $$;


--
-- Name: canonical_ownership_merge_binding_valid(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_merge_binding_valid(p_binding_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select exists(select 1 from ops.canonical_ownership_runtime_session rs
    join ops.canonical_ownership_merge_binding m on m.runtime_binding_id=rs.id
    join ops.work_request w on w.id=rs.work_request_id and w.organization_tenant_id=rs.organization_tenant_id
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.result_version=w.version and ar.plan_id=rs.accepted_plan_id
    join ops.sourced_work_request_plan p on p.id=ar.plan_id and p.plan_hash=ar.plan_hash
    join ops.source_merge_plan_scope scope on scope.id=m.scope_id and scope.accepted_plan_id=p.id
      and scope.work_request_id=w.id and scope.acceptance_receipt_id=ar.id
    join ops.engineering_execution_envelope env on env.id=rs.subject_envelope_id
      and env.accepted_plan_id=p.id and env.work_request_id=w.id and env.state_version=w.version
    join ops.engineering_slice_receipt receipt on receipt.id=m.receipt_id and receipt.envelope_id=env.id
      and receipt.outcome='claimed_complete' and receipt.receipt#>>'{source_evidence,source_sha}'=m.head_sha
    join public.event ev on ev.id=m.decision_event_id and ev.subject_id=m.decision_id
    join public.actor a on a.id=rs.actor_id and a.slug=rs.actor_slug and a.active
   where rs.id=p_binding_id and rs.phase='merge' and rs.state='active'
     and rs.expires_at>statement_timestamp() and m.decision_expires_at>=rs.expires_at
     and w.state='ready' and w.blocker_code is null
     and not ops.engineering_contract_stale(p.plan_ref,p.plan_hash,null)
     and not exists(select 1 from ops.engineering_execution_envelope successor where successor.supersedes_envelope_id=env.id)
     and ev.verb='log-decision' and ev.subject_type='decision'
     and ev.organization_tenant_id=rs.organization_tenant_id
     and ev.sponsoring_human_slug='joe' and ev.authorization_class='human'
     and ev.new_value->>'title'='Gate A2 source-merge authority: '||w.ref
     and ev.new_value->'quote_absent'='false'::jsonb
     and ev.human_quote='I approve Gate A2 for '||w.ref||' PR #'||m.pr_number::text||' at '||m.head_sha||' for 120 minutes'
     and ev.occurred_at<=statement_timestamp()
     and m.decision_expires_at=ev.occurred_at+interval '120 minutes');
$$;


--
-- Name: canonical_ownership_path_case_alias(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_path_case_alias(p_left text, p_right text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  with parts as (
    select string_to_array(p_left,'/') l,string_to_array(p_right,'/') r
  )
  select exists (
    select 1 from parts,generate_series(1,least(cardinality(l),cardinality(r))) n
     where lower(l[n])=lower(r[n]) and l[n]<>r[n]
  );
$$;


--
-- Name: canonical_ownership_path_valid(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_path_valid(p_path text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  select p_path<>''
     and length(p_path)=octet_length(p_path)
     and p_path ~ '^[!-~]+$'
     and left(p_path,1)<>'/' and right(p_path,1)<>'/'
     and strpos(p_path,chr(92))=0
     and strpos(p_path,'*')=0 and strpos(p_path,'?')=0
     and strpos(p_path,'[')=0 and strpos(p_path,']')=0
     and strpos(p_path,'{')=0 and strpos(p_path,'}')=0 and strpos(p_path,'!')=0
     and not exists (
       select 1 from unnest(string_to_array(p_path,'/')) component
        where component in ('','.','..')
     );
$_$;


--
-- Name: canonical_ownership_paths_overlap(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_paths_overlap(p_left text, p_left_mode text, p_right text, p_right_mode text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  select lower(p_left)=lower(p_right)
      or (p_left_mode='tree' and left(lower(p_right),length(p_left)+1)=lower(p_left)||'/')
      or (p_right_mode='tree' and left(lower(p_left),length(p_right)+1)=lower(p_right)||'/');
$$;


--
-- Name: canonical_ownership_plan_dependencies(uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_plan_dependencies(p_slice_plan_id uuid, p_slice_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare plan_row ops.engineering_slice_plan%rowtype; slice jsonb; slice_count integer;
        dependencies jsonb;
        -- V5-F03: the accepted slice field set for this plan's own version.
        slice_fields text[];
begin
  select * into plan_row from ops.engineering_slice_plan where id=p_slice_plan_id;
  if not found then
    return ops.canonical_ownership_refusal('SLICE_PLAN_NOT_FOUND','slice_plan',
      '"canonical slice plan"'::jsonb,'"absent"'::jsonb);
  end if;
  if jsonb_typeof(plan_row.plan->'slices') is distinct from 'array' then
    return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.dependencies',
      '"one typed canonical dependency set"'::jsonb,
      jsonb_build_object('reason','malformed_plan','value_redacted',true));
  end if;
  -- V5-F03: an unsupported or absent slice-plan schema version is refused here
  -- rather than defaulted to the v1 shape.
  slice_fields := ops.engineering_slice_plan_slice_fields(plan_row.plan->>'schema_version');
  if slice_fields is null then
    return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.dependencies',
      '"one typed canonical dependency set"'::jsonb,
      jsonb_build_object('reason','unsupported_plan_schema_version','value_redacted',true));
  end if;
  select count(*),min(value::text)::jsonb into slice_count,slice
    from jsonb_array_elements(plan_row.plan->'slices')
   where value->>'slice_ref'=p_slice_ref;
  if slice_count<>1 or not coalesce(ops.engineering_receipt_exact_object(slice,slice_fields),false)
     or not coalesce(ops.engineering_receipt_identifier_array(slice->'dependency_refs'),false) then
    return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.dependencies',
      '"one typed canonical dependency set"'::jsonb,
      jsonb_build_object('reason','malformed_dependencies','value_redacted',true));
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'slice_ref',dependency_ref,'required_state','independently_verified')
           order by dependency_ref),'[]'::jsonb)
    into dependencies
    from jsonb_array_elements_text(slice->'dependency_refs') dependency_ref;
  return jsonb_build_object('ok',true,'dependencies',dependencies);
end $$;


--
-- Name: FUNCTION canonical_ownership_plan_dependencies(p_slice_plan_id uuid, p_slice_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.canonical_ownership_plan_dependencies(p_slice_plan_id uuid, p_slice_ref text) IS 'Canonical dependency snapshot for one slice of one slice plan. The accepted slice field set is selected by the plan''s own sealed schema_version, so an engineering-slice-plan.v2 slice is read rather than refused; an unsupported version and a malformed slice both still fail closed.';


--
-- Name: canonical_ownership_refusal(text, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_refusal(p_code text, p_causal_object text, p_expected jsonb, p_actual jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if p_code is null or p_code<>all(array[
    'IDENTITY_CONTEXT_MISSING','IDENTITY_CONTEXT_INVALID','INPUT_INVALID',
    'PATH_INVALID','PATH_CASE_ALIAS','RESOURCE_INVALID','DUPLICATE_CLAIM',
    'WORK_REQUEST_NOT_FOUND','WORK_REQUEST_BINDING_STALE','SLICE_PLAN_NOT_FOUND',
    'SLICE_PLAN_BINDING_STALE','DEPENDENCY_MISSING','DEPENDENCY_UNSATISFIED',
    'FOREIGN_LEASE_COLLISION','LEASE_NOT_FOUND','LEASE_HOLDER_MISMATCH',
    'LEASE_TOKEN_STALE','FENCING_GENERATION_STALE','LEASE_RELEASED',
    'LEASE_REPLACED','LEASE_EXPIRED','LEASE_CLAIMS_MISMATCH'
  ]::text[]) then
    raise exception 'canonical ownership refusal code is not registered';
  end if;
  return jsonb_build_object('ok',false,'refusal',jsonb_build_object(
    'code',p_code,'causal_object',p_causal_object,'expected',p_expected,'actual',p_actual));
end $$;


--
-- Name: canonical_ownership_release_for_job(uuid, integer, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_release_for_job(p_job_id uuid, p_attempt integer, p_lease_token uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare rs ops.canonical_ownership_runtime_session%rowtype;
  l ops.canonical_ownership_lease%rowtype; stamp timestamptz; event_kind text;
begin
  for rs in select r.* from ops.canonical_ownership_runtime_session r
    join ops.engineering_execution_envelope e on e.id=r.subject_envelope_id
    where e.job_id=p_job_id and r.attempt=p_attempt and r.state='active' and r.phase='build' order by r.id loop
    if rs.capability_token_hash is distinct from encode(public.digest(p_lease_token::text,'sha256'),'hex') then
      raise exception 'ownership terminal capability binding mismatch';
    end if;
    if not pg_try_advisory_xact_lock(hashtextextended('canonical-ownership:'||rs.organization_tenant_id,0)) then
      raise exception using errcode='40001',message='ownership terminal cleanup contended; retry exact transition';
    end if;
    for l in select * from ops.canonical_ownership_lease where holder_session_ref=rs.ownership_session_ref
      and subject_envelope_id=rs.subject_envelope_id and state='active' order by id for update loop
      stamp:=clock_timestamp();
      event_kind:=case when l.expires_at<=stamp then 'expired' else 'released' end;
      update ops.canonical_ownership_lease set state=event_kind,
        released_at=case when event_kind='released' then stamp else null end,updated_at=stamp where id=l.id;
      insert into ops.canonical_ownership_lease_event(organization_tenant_id,lease_id,event_kind,
        fencing_generation,actor_id,session_ref,host_ref,cause,occurred_at,created_at)
      values(l.organization_tenant_id,l.id,event_kind,l.fencing_generation,l.holder_actor_id,
        l.holder_session_ref,l.holder_host_ref,'{"reason":"release_before_terminal"}',stamp,stamp);
    end loop;
    update ops.canonical_ownership_runtime_session set state='expired' where id=rs.id;
  end loop;
end $$;


--
-- Name: canonical_ownership_resource_valid(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_resource_valid(p_resource text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
  select length(p_resource)=octet_length(p_resource)
     and p_resource ~ '^[A-Za-z][A-Za-z0-9._:/-]{2,239}$';
$_$;


--
-- Name: canonical_ownership_runtime_principal_valid(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_runtime_principal_valid() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select exists(select 1 from ops.canonical_ownership_issuer_generation g
       join pg_roles r on r.rolname=g.principal
      where g.principal=session_user and g.state in ('active','draining')
        and r.rolcanlogin and not r.rolinherit and not r.rolbypassrls and not r.rolsuper
        and not r.rolcreaterole and not r.rolcreatedb)
     and pg_has_role(session_user,'carr_ownership_issuer','member')
     and not pg_has_role(session_user,'carr_writer','member')
     and not pg_has_role(session_user,'carr_jobs','member')
     and not pg_has_role(session_user,'carr_authority','member');
$$;


--
-- Name: canonical_ownership_trusted_context(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_trusted_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_tenant text:=nullif(btrim(current_setting('carr.organization_tenant_id',true)),'');
        v_actor text:=nullif(btrim(current_setting('carr.acting_actor_slug',true)),'');
        v_runtime text:=nullif(btrim(current_setting('carr.receipt_session_ref',true)),'');
        v_session text:=nullif(btrim(current_setting('carr.ownership_session_id',true)),'');
        v_host text:=nullif(btrim(current_setting('carr.execution_host_id',true)),'');
        v_capability text:=nullif(current_setting('carr.engineering_job_lease_token',true),'');
        v_row ops.canonical_ownership_runtime_session%rowtype; v_job_id uuid;
begin
  if not ops.canonical_ownership_runtime_principal_valid() then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_principal_untrusted');
  end if;
  if v_tenant is null or v_actor is null or v_runtime is null
     or v_session is null or v_host is null or v_capability is null then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_context_missing');
  end if;
  select * into v_row from ops.canonical_ownership_runtime_session
   where organization_tenant_id=v_tenant and ownership_session_ref=v_session;
  select job_id into v_job_id from ops.engineering_execution_envelope
   where id=v_row.subject_envelope_id;
  if not found or v_row.state<>'active' or v_row.expires_at<=clock_timestamp()
     or v_row.actor_slug<>v_actor or v_row.runtime_session_ref<>v_runtime
     or v_row.execution_host_ref<>v_host
     or v_row.issuer_principal is distinct from session_user
     or v_row.capability_token_hash is distinct from encode(public.digest(v_capability,'sha256'),'hex')
     or (v_row.phase='build' and not exists(select 1 from ops.engineering_execution_envelope e
       join ops.capability_agent_session s on s.id=e.agent_session_id
       join ops.job j on j.id=e.job_id
       join public.actor a on a.id=s.executor_actor_id and a.active
       where e.id=v_row.subject_envelope_id and s.executor_actor_id=v_row.actor_id
         and v_row.runtime_session_ref='session:'||s.id::text
         and s.state in ('claimed','in_progress') and s.lease_expires_at>clock_timestamp()
         and j.state='running' and j.attempt=v_row.attempt
         and j.lease_token::text=v_capability and j.leased_until>clock_timestamp()))
     or (v_row.phase='merge' and not ops.canonical_ownership_merge_binding_valid(v_row.id))
     or not exists(
       select 1 from ops.work_request w
       join ops.sourced_work_request_plan_acceptance_receipt ar
         on ar.work_request_id=w.id and ar.result_version=w.version
       join ops.sourced_work_request_plan p on p.id=ar.plan_id
        where w.id=v_row.work_request_id and w.state='ready'
          and ar.plan_id=v_row.accepted_plan_id and ar.plan_hash=p.plan_hash
          and not ops.engineering_contract_stale(p.plan_ref,p.plan_hash,null))
     or (v_row.phase='build' and coalesce((ops.engineering_envelope_currentness(
          v_row.subject_envelope_id,v_job_id)->>'eligible')::boolean,false) is not true) then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_context_stale');
  end if;
  return jsonb_build_object('ok',true,'organization_tenant_id',v_tenant,
    'acting_actor_id',v_row.actor_id,'acting_actor_slug',v_actor,'ownership_session_ref',v_session,
    'execution_host_ref',v_host,'binding_id',v_row.id,
    'work_request_id',v_row.work_request_id,'accepted_plan_id',v_row.accepted_plan_id,
    'subject_envelope_id',v_row.subject_envelope_id,'attempt',v_row.attempt,
    'runtime_session_ref',v_row.runtime_session_ref,'phase',v_row.phase,'expires_at',v_row.expires_at);
end $$;


--
-- Name: canonical_ownership_validate_live(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.canonical_ownership_validate_live(p_lease_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_check_currentness boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare context jsonb:=ops.canonical_ownership_context(); lease_row ops.canonical_ownership_lease%rowtype;
        currentness jsonb; canonical_deps jsonb; stored_deps jsonb;
        dep record; dep_state jsonb; refs text[]; now_at timestamptz;
        current_subject uuid; subject_count integer;
begin
  if not coalesce((context->>'ok')::boolean,false) then return context; end if;
  if p_lease_id is null or p_lease_token is null or p_fencing_generation is null or p_fencing_generation<1 then
    return ops.canonical_ownership_refusal('INPUT_INVALID','lease.binding','"lease id, token, positive generation"'::jsonb,'"invalid"'::jsonb);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-ownership:'||(context->>'tenant'),0));
  select * into lease_row from ops.canonical_ownership_lease
   where id=p_lease_id and organization_tenant_id=context->>'tenant' for update;
  if not found then return ops.canonical_ownership_refusal('LEASE_NOT_FOUND','lease',
    '"tenant lease"'::jsonb,'"absent"'::jsonb); end if;
  if lease_row.holder_actor_id is distinct from (context->>'actor_id')::uuid
     or lease_row.holder_actor_slug is distinct from context->>'actor_slug'
     or lease_row.holder_session_ref is distinct from context->>'session_ref'
     or lease_row.holder_host_ref is distinct from context->>'host_ref' then
    return ops.canonical_ownership_refusal('LEASE_HOLDER_MISMATCH','lease.holder',
      '"acquiring actor, session, and host"'::jsonb,
      jsonb_build_object('actor_matches',lease_row.holder_actor_id=(context->>'actor_id')::uuid,
        'session_matches',lease_row.holder_session_ref=context->>'session_ref',
        'host_matches',lease_row.holder_host_ref=context->>'host_ref'));
  end if;
  if lease_row.lease_token<>p_lease_token then
    return ops.canonical_ownership_refusal('LEASE_TOKEN_STALE','lease.token',
      '"current lease token"'::jsonb,'"redacted"'::jsonb);
  end if;
  if lease_row.fencing_generation<>p_fencing_generation then
    return ops.canonical_ownership_refusal('FENCING_GENERATION_STALE','lease.fencing_generation',
      to_jsonb(lease_row.fencing_generation),to_jsonb(p_fencing_generation));
  end if;
  if lease_row.state='released' then return ops.canonical_ownership_refusal('LEASE_RELEASED','lease.lifecycle','"active"'::jsonb,'"released"'::jsonb); end if;
  if lease_row.state='replaced' then return ops.canonical_ownership_refusal('LEASE_REPLACED','lease.lifecycle','"active"'::jsonb,'"replaced"'::jsonb); end if;
  if lease_row.state='expired' then return ops.canonical_ownership_refusal('LEASE_EXPIRED','lease.lifecycle','"active and unexpired"'::jsonb,'"expired"'::jsonb); end if;
  select array_agg(ref order by ref) into refs from (
    select lease_row.slice_ref ref union
    select dependency_slice_ref from ops.canonical_ownership_dependency where lease_id=p_lease_id
  ) q;
  perform ops.canonical_ownership_lock_lineage(
    (context->>'actor_id')::uuid,lease_row.slice_plan_id,refs);
  perform 1 from public.actor a
   where a.id=(context->>'actor_id')::uuid
     and a.slug=context->>'actor_slug' and a.active;
  if not found then
    return ops.canonical_ownership_refusal('IDENTITY_CONTEXT_INVALID','identity_context.actor',
      '"active canonical actor"'::jsonb,
      jsonb_build_object('reason','unknown_or_inactive','value_redacted',true));
  end if;
  now_at:=clock_timestamp();
  if lease_row.expires_at<=now_at then
    return ops.canonical_ownership_refusal('LEASE_EXPIRED','lease.expiry',
      '"future expiry"'::jsonb,'"elapsed"'::jsonb);
  end if;
  if p_check_currentness then
    currentness:=ops.canonical_ownership_currentness(lease_row.work_request_id,lease_row.work_request_version,
      lease_row.work_request_digest,lease_row.accepted_plan_id,lease_row.accepted_plan_digest,
      lease_row.slice_plan_id,lease_row.slice_plan_digest,lease_row.slice_ref);
    if not coalesce((currentness->>'ok')::boolean,false) then return currentness; end if;
    select count(*),(array_agg(id order by id))[1] into subject_count,current_subject
      from ops.engineering_execution_envelope e
     where e.work_request_id=lease_row.work_request_id
       and e.slice_plan_id=lease_row.slice_plan_id and e.slice_ref=lease_row.slice_ref
       and not exists (select 1 from ops.engineering_execution_envelope successor
                        where successor.supersedes_envelope_id=e.id);
    if subject_count<>1 or current_subject is distinct from lease_row.subject_envelope_id then
      return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.subject',
        '"acquired subject envelope remains current"'::jsonb,
        jsonb_build_object('reason','subject_lineage_stale','value_redacted',true));
    end if;
    canonical_deps:=ops.canonical_ownership_plan_dependencies(lease_row.slice_plan_id,lease_row.slice_ref);
    if not coalesce((canonical_deps->>'ok')::boolean,false) then return canonical_deps; end if;
    select coalesce(jsonb_agg(jsonb_build_object('slice_ref',dependency_slice_ref,
             'required_state',required_state) order by dependency_slice_ref),'[]'::jsonb)
      into stored_deps from ops.canonical_ownership_dependency where lease_id=p_lease_id;
    if stored_deps is distinct from canonical_deps->'dependencies' then
      return ops.canonical_ownership_refusal('SLICE_PLAN_BINDING_STALE','slice_plan.dependencies',
        '"persisted dependencies match canonical plan"'::jsonb,
        jsonb_build_object('reason','canonical_drift','value_redacted',true));
    end if;
    for dep in select * from ops.canonical_ownership_dependency where lease_id=p_lease_id order by dependency_slice_ref loop
      dep_state:=ops.canonical_ownership_dependency_state(lease_row.work_request_id,lease_row.slice_plan_id,
        dep.dependency_slice_ref,dep.required_state);
      if not coalesce((dep_state->>'ok')::boolean,false) then return dep_state; end if;
    end loop;
  end if;
  return jsonb_build_object('ok',true,'lease_id',lease_row.id,'fencing_generation',lease_row.fencing_generation,
    'expires_at',lease_row.expires_at,'evaluated_at',now_at);
end $$;


--
-- Name: capability_agent_session_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_agent_session_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.state <> 'claimed' or new.candidate_evidence is not null
       or new.candidate_kind is not null or new.candidate_fingerprint is not null then
      raise exception 'capability session must be created claimed with no candidate';
    end if;
  else
    if old.state in ('completed','cancelled') then
      if new is distinct from old then
        raise exception 'terminal capability session is immutable';
      end if;
      return old;
    end if;
    if new.work_request_id is distinct from old.work_request_id
       or new.executor_actor_id is distinct from old.executor_actor_id
       or new.created_by_actor_id is distinct from old.created_by_actor_id
       or new.source_commit_sha is distinct from old.source_commit_sha
       or new.worktree_ref is distinct from old.worktree_ref
       or new.scope_ref is distinct from old.scope_ref then
      raise exception 'capability session identity is immutable';
    end if;
    if old.candidate_kind is not null
       and new.candidate_kind is distinct from old.candidate_kind then
      raise exception 'prepared capability candidate kind is immutable';
    end if;
    if old.candidate_evidence is not null
       and new.candidate_evidence is distinct from old.candidate_evidence then
      raise exception 'prepared capability candidate is immutable';
    end if;
    if old.candidate_fingerprint is not null
       and new.candidate_fingerprint is distinct from old.candidate_fingerprint then
      raise exception 'prepared capability fingerprint is immutable';
    end if;
    if old.state = 'claimed' and new.state not in ('in_progress','cancelled') then
      raise exception 'capability session claimed may only move to in_progress or cancelled';
    elsif old.state = 'in_progress' and new.state not in ('verification','cancelled') then
      raise exception 'capability session in_progress may only move to verification or cancelled';
    elsif old.state = 'verification' and new.state not in ('completed','cancelled') then
      raise exception 'capability session verification may only move to completed or cancelled';
    end if;
  end if;

  if new.candidate_evidence is not null then
    new.candidate_fingerprint := md5(new.candidate_evidence::text);
  elsif new.candidate_fingerprint is not null then
    raise exception 'candidate fingerprint requires candidate evidence';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: capability_agent_session_lease_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_agent_session_lease_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if tg_op='UPDATE' and new.lease_expires_at is distinct from old.lease_expires_at then
    raise exception 'capability agent session lease is immutable';
  end if;
  return new;
end $$;


--
-- Name: capability_attestation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_attestation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s ops.capability_agent_session%rowtype;
begin
  select * into s from ops.capability_agent_session where id = new.build_session_id for key share;
  if not found then raise exception 'capability build session does not exist'; end if;
  if s.work_request_id <> new.work_request_id then
    raise exception 'attestation work request does not match build session';
  end if;
  if s.state <> 'verification' then
    raise exception 'attestation requires a session in verification';
  end if;
  if new.verifier_actor_id = s.executor_actor_id then
    raise exception 'capability executor may not attest its own candidate';
  end if;
  if new.candidate_fingerprint <> s.candidate_fingerprint then
    raise exception 'attestation candidate does not match the prepared candidate';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_close_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_close_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare s ops.capability_agent_session%rowtype; pass_id uuid;
begin
  if new.program_key is distinct from 'carr-ai-engineering-suite-v1'
     or new.state <> 'confirmed_closed' or old.state = 'confirmed_closed' then
    return new;
  end if;
  select * into s from ops.capability_agent_session
   where work_request_id=new.id and state='verification'
   order by prepared_at desc limit 1 for key share;
  if not found or s.candidate_kind <> new.completion_kind
     or (new.completion_evidence -> 'candidate') is distinct from s.candidate_evidence then
    raise exception 'capability programme close requires its frozen prepared candidate';
  end if;
  begin
    pass_id := new.verification_evidence_ref::uuid;
  exception when invalid_text_representation then
    raise exception 'capability programme close requires a stored pass attestation id';
  end;
  if not exists (
    select 1 from ops.capability_verification a
     where a.id=pass_id and a.build_session_id=s.id and a.work_request_id=new.id
       and a.outcome='pass' and a.candidate_fingerprint=s.candidate_fingerprint
       and a.verifier_actor_id <> s.executor_actor_id
  ) then
    raise exception 'capability programme close requires an independent stored pass';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_closed_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_closed_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.program_key = 'carr-ai-engineering-suite-v1'
     and old.state = 'confirmed_closed'
     and new is distinct from old then
    if coalesce(current_setting('carr.legacy_program_tenant_backfill', true), '') = 'on'
       and old.organization_tenant_id is null
       and new.organization_tenant_id = 'carr-internal'
       and (to_jsonb(new) - 'organization_tenant_id')
           is not distinct from
           (to_jsonb(old) - 'organization_tenant_id') then
      return new;
    end if;
    raise exception 'closed capability programme evidence is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: capability_program_identity_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_program_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.program_key = 'carr-ai-engineering-suite-v1'
     and (new.program_key is distinct from old.program_key
          or new.program_ordinal is distinct from old.program_ordinal) then
    raise exception 'capability programme identity is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: capability_verification_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capability_verification_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'capability verification records are immutable';
end;
$$;


--
-- Name: capture_source_merge_plan_scope(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capture_source_merge_plan_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare p ops.sourced_work_request_plan%rowtype;
        w ops.work_request%rowtype;
        scope jsonb;
        normalized_paths jsonb;
        digest text;
begin
  select * into p from ops.sourced_work_request_plan where id=new.plan_id for share;
  select * into w from ops.work_request where id=new.work_request_id for share;
  scope:=p.caps->'source_merge';
  if scope is null then return new; end if;
  if p.work_request_id is distinct from new.work_request_id
     or p.plan_hash is distinct from new.plan_hash
     or new.accepted_by_actor_id is null
     or not coalesce(ops.source_merge_scope_valid(scope),false) then
    raise exception 'accepted source merge scope is not an exact valid plan-hash binding';
  end if;
  select jsonb_agg(to_jsonb(path) order by lower(path) collate "C",path collate "C")
    into normalized_paths from jsonb_array_elements_text(scope->'authorized_paths') path;
  digest:='sha256:'||encode(public.digest(jsonb_build_object(
    'accepted_plan_id',p.id,'plan_hash',p.plan_hash,'scope',scope)::text,'sha256'),'hex');
  insert into ops.source_merge_plan_scope(
    organization_tenant_id,work_request_id,accepted_plan_id,acceptance_receipt_id,
    accepted_by_actor_id,repository,base_branch,authorized_paths,scope_digest,created_at)
  values(w.organization_tenant_id,w.id,p.id,new.id,new.accepted_by_actor_id,
    scope->>'repository',scope->>'base_branch',normalized_paths,digest,new.accepted_at);
  return new;
end $$;


--
-- Name: capture_sourced_work_request(text, text, text, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid) RETURNS TABLE(id uuid, ref text, state text, version integer, organization_tenant_id text, doctrine_section_id uuid, doctrine_revision_id uuid, doctrine_source_label text, source_current boolean, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  v_section public.doctrine_section%rowtype;
  v_document public.doctrine_document%rowtype;
  v_existing ops.work_request%rowtype;
  v_sequence bigint;
  v_ref text;
  v_label text;
begin
  if p_idempotency_key is null
     or coalesce(btrim(p_origin_ref), '') !~ '^doctrine:[a-z0-9][a-z0-9-]*#[a-z0-9][a-z0-9-]*$'
     or char_length(p_origin_ref) > 300
     or coalesce(btrim(p_title), '') = '' or char_length(p_title) > 240
     or coalesce(btrim(p_desired_outcome), '') = '' or char_length(p_desired_outcome) > 4000
     or jsonb_typeof(p_acceptance_criteria) <> 'array'
     or jsonb_array_length(p_acceptance_criteria) not between 1 and 12
     or exists (select 1 from jsonb_array_elements(p_acceptance_criteria) x
                 where jsonb_typeof(x) <> 'object' or x ?| array['id','text'] is false
                    or (select array_agg(k order by k) from jsonb_object_keys(x) k) <> array['id','text']
                    or coalesce(x->>'id','') !~ '^[A-Z][A-Z0-9-]{1,63}$'
                    or coalesce(btrim(x->>'text'),'') = '' or char_length(x->>'text') > 500) then
    raise exception 'sourced capture requires bounded exact acceptance criteria plus a doctrine origin, title, outcome, and UUID idempotency key';
  end if;
  if exists (select x->>'id' from jsonb_array_elements(p_acceptance_criteria) x
               group by x->>'id' having count(*) > 1) then
    raise exception 'sourced capture acceptance criterion IDs must be unique';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-sourced-capture:' || p_idempotency_key, 0));
  select w.* into v_existing from ops.work_request w
   where w.capture_idempotency_key=p_idempotency_key;
  if found then
    if v_existing.organization_tenant_id is distinct from 'carr-internal'
       or v_existing.origin_ref is distinct from p_origin_ref
       or v_existing.title is distinct from p_title
       or v_existing.desired_outcome is distinct from p_desired_outcome
       or v_existing.acceptance_criteria is distinct from p_acceptance_criteria
       or v_existing.doctrine_section_id is distinct from p_doctrine_section_id
       or v_existing.doctrine_revision_id is distinct from p_doctrine_revision_id then
      raise exception 'idempotency key already names a different sourced capture';
    end if;
    select coalesce(s.title, s.section_key) into v_label from public.doctrine_section s where s.id=v_existing.doctrine_section_id;
    return query select v_existing.id, v_existing.ref, v_existing.state, v_existing.version,
      v_existing.organization_tenant_id, v_existing.doctrine_section_id,
      v_existing.doctrine_revision_id, v_label,
      exists (select 1 from public.doctrine_section s where s.id=v_existing.doctrine_section_id
                and s.status='active' and s.current_revision_id=v_existing.doctrine_revision_id), true;
    return;
  end if;

  select s.* into v_section from public.doctrine_section s
   where s.id=p_doctrine_section_id
   for update;
  if not found then
    raise exception 'sourced capture requires an exact current active shared doctrine revision';
  end if;
  select d.* into v_document from public.doctrine_document d where d.id=v_section.document_id for share;
  perform 1 from public.doctrine_revision r
   where r.id=p_doctrine_revision_id and r.section_id=p_doctrine_section_id for share;
  if not found or v_section.current_revision_id is distinct from p_doctrine_revision_id
     or v_section.status <> 'active'
     or v_document.visibility <> 'shared' then
    raise exception 'sourced capture requires an exact current active shared doctrine revision';
  end if;
  if p_origin_ref is distinct from ('doctrine:' || v_document.slug || '#' || v_section.section_key) then
    raise exception 'sourced capture origin reference does not name its exact doctrine evidence';
  end if;
  if not exists (select 1 from public.doctrine_revision r where r.id=p_doctrine_revision_id and r.section_id=p_doctrine_section_id) then
    raise exception 'sourced capture doctrine evidence is invented';
  end if;

  select nextval('ops.work_request_ref_seq') into v_sequence;
  v_ref := 'WR-' || lpad(v_sequence::text, 6, '0');
  v_label := coalesce(v_section.title, v_section.section_key);
  insert into ops.work_request
    (ref,state,title,desired_outcome,acceptance_criteria,origin_ref,requester_actor,
     organization_tenant_id,doctrine_section_id,doctrine_revision_id,
     capture_idempotency_key,sourced_capture_sequence)
  values
    (v_ref,'captured',p_title,p_desired_outcome,p_acceptance_criteria,p_origin_ref,'mcp-authenticated',
     'carr-internal',p_doctrine_section_id,p_doctrine_revision_id,p_idempotency_key,v_sequence)
  returning * into v_existing;
  return query select v_existing.id, v_existing.ref, v_existing.state, v_existing.version,
    v_existing.organization_tenant_id, v_existing.doctrine_section_id,
    v_existing.doctrine_revision_id, v_label, true, false;
end;
$_$;


--
-- Name: FUNCTION capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.capture_sourced_work_request(p_origin_ref text, p_title text, p_desired_outcome text, p_acceptance_criteria jsonb, p_doctrine_section_id uuid, p_doctrine_revision_id uuid, p_idempotency_key uuid) IS 'The sole carr_writer INSERT path for Work Requests. Validates and locks exact current shared doctrine evidence; actor attribution remains in the MCP tool_call/event envelope.';


--
-- Name: check_canonical_ownership_lease(uuid, uuid, bigint, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.check_canonical_ownership_lease(p_lease_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_path_claims jsonb DEFAULT '[]'::jsonb, p_resource_claims jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare context jsonb:=ops.canonical_ownership_context(); live jsonb; claim jsonb;
        claim_ordinal bigint; mismatch_kind text; mismatch_ordinal bigint;
begin
  if not coalesce((context->>'ok')::boolean,false) then return context; end if;
  if jsonb_typeof(p_path_claims) is distinct from 'array'
     or jsonb_typeof(p_resource_claims) is distinct from 'array' then
    return ops.canonical_ownership_refusal('INPUT_INVALID','required_claims','"arrays"'::jsonb,'"invalid"'::jsonb);
  end if;
  for claim,claim_ordinal in
    select value,ordinality from jsonb_array_elements(p_path_claims) with ordinality
  loop
    if not coalesce(ops.engineering_receipt_exact_object(claim,array['path','mode','operation']),false)
       or claim->>'mode' not in ('file','tree') or claim->>'operation' not in ('write','rename_source','rename_destination')
       or not coalesce(ops.canonical_ownership_path_valid(claim->>'path'),false) then
      return ops.canonical_ownership_refusal('INPUT_INVALID','required_claims.path',
        '"exact path claim"'::jsonb,
        jsonb_build_object('ordinal',claim_ordinal,'field','path_claim',
          'reason','invalid','value_redacted',true));
    end if;
  end loop;
  for claim,claim_ordinal in
    select value,ordinality from jsonb_array_elements(p_resource_claims) with ordinality
  loop
    if not coalesce(ops.engineering_receipt_exact_object(claim,array['resource']),false)
       or not coalesce(ops.canonical_ownership_resource_valid(claim->>'resource'),false) then
      return ops.canonical_ownership_refusal('INPUT_INVALID','required_claims.resource',
        '"exact resource claim"'::jsonb,
        jsonb_build_object('ordinal',claim_ordinal,'field','resource_claim',
          'reason','invalid','value_redacted',true));
    end if;
  end loop;
  live:=ops.canonical_ownership_validate_live(p_lease_id,p_lease_token,p_fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  for claim,claim_ordinal in
    select value,ordinality from jsonb_array_elements(p_path_claims) with ordinality
  loop
    if not exists(select 1 from ops.canonical_ownership_claim c where c.lease_id=p_lease_id and c.claim_kind='path'
      and c.claim_value=claim->>'path' and c.claim_mode=claim->>'mode' and c.operation=claim->>'operation') then
      mismatch_kind:='path'; mismatch_ordinal:=claim_ordinal; exit;
    end if;
  end loop;
  if mismatch_ordinal is null then
    for claim,claim_ordinal in
      select value,ordinality from jsonb_array_elements(p_resource_claims) with ordinality
    loop
      if not exists(select 1 from ops.canonical_ownership_claim c where c.lease_id=p_lease_id and c.claim_kind='resource'
        and c.claim_value=claim->>'resource') then
        mismatch_kind:='resource'; mismatch_ordinal:=claim_ordinal; exit;
      end if;
    end loop;
  end if;
  if mismatch_ordinal is not null then return ops.canonical_ownership_refusal(
    'LEASE_CLAIMS_MISMATCH','lease.claims','"claimed scope"'::jsonb,
    jsonb_build_object('claim_kind',mismatch_kind,'submitted_ordinal',mismatch_ordinal,
      'reason','unowned_claim','value_redacted',true)); end if;
  return live;
end $$;


--
-- Name: claim_calendar_prebrief_joe_live_job(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_calendar_prebrief_joe_live_job(p_worker text, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease uuid, scheduled_for timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v ops.job%rowtype;
begin
 if session_user<>'carr_jobs' or btrim(coalesce(p_worker,''))='' or p_lease_seconds not between 1 and 300 then raise exception 'Joe calendar runtime identity or lease refused'; end if;
 if not exists(
   select 1
     from ops.calendar_prebrief_allowed_calendar a
     join lateral (
       select r.allowlist_revision_id
         from ops.calendar_prebrief_runtime_activation_receipt r
        where r.sponsor='joe'
        order by r.activated_at desc,r.id desc limit 1
     ) latest on latest.allowlist_revision_id=a.active_revision_id
     join ops.calendar_prebrief_allowlist_receipt l
       on l.id=a.active_revision_id and l.sponsor='joe'
      and l.configuration_digest=a.configuration_digest
    where a.sponsor='joe'
 ) then raise exception 'Joe claim activation gate refused'; end if;
 perform ops.reap_expired_jobs();
 select j.* into v from ops.job j join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version where d.enabled and j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1 and d.owner_actor='joe' and j.mode='live' and j.state in ('queued','retry_wait') and j.next_attempt_at<=now() order by j.scheduled_for,j.created_at for update of j,d skip locked limit 1;
 if not found then return; end if;
 update ops.job set state='running',attempt=v.attempt+1,lease_owner=p_worker,lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),started_at=coalesce(started_at,now()),updated_at=now() where id=v.id returning * into v;
 insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state) values(v.id,v.attempt,v.lease_owner,v.lease_token,'running');
 return query select v.id,v.lease_token,v.scheduled_for;
end $$;


--
-- Name: claim_job(text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_job(p_worker text, p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease_token uuid, definition_key text, definition_version integer, payload jsonb, execution_kind text, execution_contract jsonb, attempt integer, timeout_seconds integer, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if btrim(coalesce(p_worker,''))='' or p_limit<1 or p_lease_seconds<1 then
    raise exception 'worker, positive limit and positive lease are required';
  end if;
  perform ops.reap_expired_jobs();
  return query
  with candidate as (
    select j.id from ops.job j join ops.job_definition d
      on d.key=j.definition_key and d.version=j.definition_version
     where d.enabled and j.state in ('queued','retry_wait') and j.next_attempt_at<=now()
       and j.definition_key<>'engineering-slice'
       and not (j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1)
     order by j.scheduled_for,j.created_at for update of j,d skip locked limit p_limit
  ), claimed as (
    update ops.job j set state='running',attempt=j.attempt+1,lease_owner=p_worker,
      lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),
      started_at=coalesce(j.started_at,now()),updated_at=now()
      from candidate c where j.id=c.id returning j.*
  ), attempts(claimed_job_id) as (
    insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state)
    select c.id,c.attempt,c.lease_owner,c.lease_token,'running' from claimed c
    returning ops.job_attempt.job_id
  )
  select c.id,c.lease_token,c.definition_key,c.definition_version,c.payload,
         d.execution_kind,d.execution_contract,c.attempt,c.timeout_seconds,c.mode
    from claimed c join ops.job_definition d
      on d.key=c.definition_key and d.version=c.definition_version
    join attempts a on a.claimed_job_id=c.id;
end $$;


--
-- Name: claim_job_mode(text, text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_job_mode(p_worker text, p_mode text, p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(job_id uuid, lease_token uuid, definition_key text, definition_version integer, payload jsonb, execution_kind text, execution_contract jsonb, attempt integer, timeout_seconds integer, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if btrim(coalesce(p_worker,''))='' or p_mode not in ('shadow','canary','live','replay')
     or p_limit<1 or p_lease_seconds<1 then
    raise exception 'worker, valid mode, positive limit and positive lease are required';
  end if;
  perform ops.reap_expired_jobs();
  return query
  with candidate as (
    select j.id from ops.job j join ops.job_definition d
      on d.key=j.definition_key and d.version=j.definition_version
     where d.enabled and j.state in ('queued','retry_wait') and j.next_attempt_at<=now()
       and j.mode=p_mode and j.definition_key<>'engineering-slice'
       and not (j.definition_key='calendar-prebrief-projection-joe-daily' and j.definition_version=1)
     order by j.scheduled_for,j.created_at for update of j,d skip locked limit p_limit
  ), claimed as (
    update ops.job j set state='running',attempt=j.attempt+1,lease_owner=p_worker,
      lease_token=gen_random_uuid(),leased_until=now()+make_interval(secs=>p_lease_seconds),
      started_at=coalesce(j.started_at,now()),updated_at=now()
      from candidate c where j.id=c.id returning j.*
  ), attempts(claimed_job_id) as (
    insert into ops.job_attempt(job_id,attempt,lease_owner,lease_token,state)
    select c.id,c.attempt,c.lease_owner,c.lease_token,'running' from claimed c
    returning ops.job_attempt.job_id
  )
  select c.id,c.lease_token,c.definition_key,c.definition_version,c.payload,
         d.execution_kind,d.execution_contract,c.attempt,c.timeout_seconds,c.mode
    from claimed c join ops.job_definition d
      on d.key=c.definition_key and d.version=c.definition_version
    join attempts a on a.claimed_job_id=c.id;
end $$;


--
-- Name: claim_meeting_processing(uuid, text, boolean, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_meeting_processing(p_meeting uuid, p_client_instance text, p_release boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype; v_lease ops.meeting_processing_lease%rowtype;
        v_now timestamptz := clock_timestamp(); v_decision text; v_holder boolean;
begin
  select * into v_who from ops.meeting_mode_actor();
  select * into v_row from ops.meeting
   where id = p_meeting and organization_tenant_id = v_who.tenant for update;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  select * into v_lease from ops.meeting_processing_lease where meeting_id = p_meeting for update;
  v_holder := v_lease.meeting_id is not null and v_lease.holder_actor = v_who.actor_id
    and v_lease.holder_instance = p_client_instance and v_lease.released_at is null;

  if coalesce(p_release, false) then
    if not v_holder then
      v_decision := 'not_holder';
    else
      update ops.meeting_processing_lease set released_at = v_now where meeting_id = p_meeting;
      perform ops.meeting_mode_append(p_meeting, 'processing_released', v_who.actor_id,
        p_client_instance, null, null, null, v_lease.lease_epoch, p_idempotency_key);
      v_decision := 'released';
    end if;
  elsif v_row.mode_state = 'ended' then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_ended', 'meeting_id', p_meeting);
  elsif v_lease.meeting_id is null then
    insert into ops.meeting_processing_lease(meeting_id, holder_actor, holder_instance,
      lease_epoch, acquired_at, expires_at)
    values (p_meeting, v_who.actor_id, p_client_instance, 1, v_now,
      v_now + ops.meeting_processing_lease_ttl());
    perform ops.meeting_mode_append(p_meeting, 'processing_acquired', v_who.actor_id,
      p_client_instance, null, null, null, 1, p_idempotency_key);
    v_decision := 'acquired';
  elsif v_holder then
    -- Renewal by the same device. Nobody else took the lease, so the epoch
    -- does not move and nothing is appended: a heartbeat is not history.
    update ops.meeting_processing_lease
       set expires_at = v_now + ops.meeting_processing_lease_ttl()
     where meeting_id = p_meeting;
    v_decision := 'renewed';
  elsif v_lease.released_at is null and v_lease.expires_at > v_now then
    v_decision := 'held_by_other';
  else
    update ops.meeting_processing_lease
       set holder_actor = v_who.actor_id, holder_instance = p_client_instance,
           lease_epoch = lease_epoch + 1, acquired_at = v_now,
           expires_at = v_now + ops.meeting_processing_lease_ttl(), released_at = null
     where meeting_id = p_meeting;
    perform ops.meeting_mode_append(p_meeting, 'processing_taken_over', v_who.actor_id,
      p_client_instance, null, null, null, v_lease.lease_epoch + 1, p_idempotency_key);
    v_decision := 'taken_over_after_expiry';
  end if;

  select * into v_lease from ops.meeting_processing_lease where meeting_id = p_meeting;
  return jsonb_build_object('ok', true, 'meeting_id', p_meeting, 'decision', v_decision,
    'is_holder', v_lease.meeting_id is not null and v_lease.released_at is null
      and v_lease.holder_actor = v_who.actor_id and v_lease.holder_instance = p_client_instance,
    'lease', case when v_lease.meeting_id is null then null else jsonb_build_object(
      'holder', (select slug from public.actor where id = v_lease.holder_actor),
      'holder_instance', v_lease.holder_instance, 'lease_epoch', v_lease.lease_epoch,
      'expires_at', v_lease.expires_at, 'released', v_lease.released_at is not null) end);
end $$;


--
-- Name: claim_staging_deployment_attempt(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_staging_deployment_attempt(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare attempt ops.staging_deployment_attempt%rowtype; inserted_count integer;
begin
  if session_user<>'carr_jobs' then
    raise exception 'staging attempt claim requires the carr_jobs session';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt
    where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging attempt must be prepared before claim'; end if;
  if exists(select 1 from ops.staging_release_readback_receipt
            where deployment_attempt_id=attempt.id) then
    return jsonb_build_object('attempt_id',attempt.id,'deploy_allowed',false,
      'replayed',true,'state','observed');
  end if;
  insert into ops.staging_deployment_claim(deployment_attempt_id,writer_session_user)
    values(attempt.id,session_user) on conflict do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('attempt_id',attempt.id,
    'deploy_allowed',inserted_count=1,'replayed',inserted_count=0,
    'state',case when inserted_count=1 then 'claimed' else 'claimed_pending_readback' end);
end $$;


--
-- Name: claim_staging_forward_fix_rehearsal(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_staging_forward_fix_rehearsal(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare attempt ops.staging_forward_fix_rehearsal_attempt%rowtype; result_row ops.staging_forward_fix_rehearsal_result%rowtype; inserted_count integer;
begin
  if session_user<>'carr_jobs' then raise exception 'forward-fix rehearsal claim requires the carr_jobs session'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,315));
  select * into attempt from ops.staging_forward_fix_rehearsal_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'forward-fix rehearsal must be prepared before claim'; end if;
  select * into result_row from ops.staging_forward_fix_rehearsal_result where rehearsal_attempt_id=attempt.id;
  if found then return jsonb_build_object('forward_fix_rehearsal_attempt_id',attempt.id,'mutation_allowed',false,'state','observed','replayed',true); end if;
  insert into ops.staging_forward_fix_rehearsal_claim(rehearsal_attempt_id,writer_session_user)
  values(attempt.id,session_user) on conflict do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('forward_fix_rehearsal_attempt_id',attempt.id,'mutation_allowed',inserted_count=1,
    'state',case when inserted_count=1 then 'claimed' else 'claimed_pending_result' end,'replayed',inserted_count=0);
end $$;


--
-- Name: claim_staging_restore_only_attempt(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.claim_staging_restore_only_attempt(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare attempt ops.staging_restore_only_attempt%rowtype; inserted_count integer; result_row ops.staging_restore_only_result%rowtype;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only claim requires the carr_jobs session'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'restore-only attempt must be prepared before claim'; end if;
  select * into result_row from ops.staging_restore_only_result where restore_attempt_id=attempt.id;
  if found then return jsonb_build_object('restore_attempt_id',attempt.id,'mutation_allowed',false,'state',result_row.status,'replayed',true); end if;
  insert into ops.staging_restore_only_claim(restore_attempt_id,writer_session_user) values(attempt.id,session_user) on conflict do nothing;
  get diagnostics inserted_count=row_count;
  return jsonb_build_object('restore_attempt_id',attempt.id,'mutation_allowed',inserted_count=1,'state',case when inserted_count=1 then 'claimed' else 'claimed_pending_result' end,'replayed',inserted_count=0);
end $$;


--
-- Name: classify_sourced_work_request_build(text, integer, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.classify_sourced_work_request_build(p_work_request text, p_base_version integer, p_scope_summary text, p_dependency_refs jsonb, p_caps jsonb) RETURNS TABLE(work_request_id uuid, ref text, tier text, reasons jsonb, shape_disposition text, shape_ready boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  w ops.work_request%rowtype;
  classification jsonb;
begin
  select x.* into w from ops.work_request x
   where x.ref = p_work_request and x.state = 'triaged' and x.version = p_base_version
     and x.capture_idempotency_key is not null and x.organization_tenant_id = 'carr-internal';
  if not found then return; end if;
  classification := ops.heavy_build_classification(w.id, p_scope_summary, p_dependency_refs, p_caps);
  return query select w.id, w.ref, classification->>'tier', classification->'reasons',
    classification->>'shape_disposition', (classification->>'shape_ready')::boolean;
end;
$$;


--
-- Name: clear_recovered_incident(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.clear_recovered_incident(p_ref text, p_required integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_id           uuid;
  v_state        text;
  v_severity     text;
  v_source_kind  text;
  v_signature    text;
  v_environment  text;
  v_service      text;
  v_env          text;
  v_run_key      text;
  v_required     int;
  v_total        int;
  v_green        int;
  v_latest       uuid;
begin
  -- THE FLOOR IS THE FUNCTION'S, NOT THE CALLER'S. A caller that asks for a
  -- shorter sequence than the system's definition of recovered gets the
  -- system's definition. Asking for a longer one is allowed: that is a caller
  -- being more careful, which never needs preventing.
  v_required := greatest(coalesce(p_required, 3), 3);

  select i.id, i.state, i.severity, i.source_kind, i.signature, i.environment
    into v_id, v_state, v_severity, v_source_kind, v_signature, v_environment
    from ops.incident i where i.ref = p_ref for update;
  if not found then return false; end if;

  -- Everything below is a REFUSAL, and each one is the reason a job role may
  -- hold EXECUTE on a function that writes resolved_at.
  if v_state in ('resolved', 'reviewed') then return false; end if;

  -- SEV-1 (and any SEV-0) NEVER CLOSES HERE. The council was explicit that the
  -- critical incidents are the work, not hygiene, and 0117 made human closure a
  -- grant rather than a convention. This keeps that true through the one door
  -- the grant no longer covers.
  if v_severity !~ '^SEV-[2-4]$' then return false; end if;

  -- Only what the machine opened. A human who writes an incident by hand is
  -- describing something the run ledger cannot see, so the run ledger has no
  -- standing to declare it over.
  if v_source_kind <> 'collector' then return false; end if;
  if v_signature is null then return false; end if;

  v_service := split_part(v_signature, '|', 1);
  v_env     := split_part(v_signature, '|', 2);
  v_run_key := split_part(v_signature, '|', 3);
  if v_service = '' or v_env = '' or v_run_key = '' then return false; end if;
  if v_env is distinct from v_environment then return false; end if;

  -- RE-DERIVED, NOT BELIEVED. The caller passes no evidence and no count; the
  -- sequence is read here, from the same ledger a human would read. skipped and
  -- cancelled runs are excluded rather than counted either way — a step that was
  -- gated out is not proof of health and not proof of breakage.
  with recent as (
    select r.id, r.state, r.observed_at
      from ops.run r join ops.service s on s.id = r.service_id
     where s.key = v_service
       and r.environment = v_env
       and r.run_key = v_run_key
       and r.state in ('succeeded', 'failed', 'timed_out')
     order by r.observed_at desc, r.id desc
     limit v_required)
  select count(*), count(*) filter (where recent.state = 'succeeded'),
         (select r2.id from recent r2 order by r2.observed_at desc, r2.id desc limit 1)
    into v_total, v_green, v_latest
    from recent;

  -- A job with fewer than v_required terminal runs on record has not yet
  -- demonstrated the sequence, however green the ones it has are.
  if v_total < v_required or v_green < v_required then return false; end if;

  update ops.incident i
     set state = 'resolved',
         resolved_at = now(),
         monitoring_until = coalesce(i.monitoring_until, now()),
         recovery_evidence_ref = 'ops.run:' || v_latest::text,
         root_cause = format(
           'recovered: %s has run green %s consecutive times in %s, which is the '
           'success sequence this system calls recovered. Closed automatically by '
           'ops.clear_recovered_incident with those runs as the evidence.',
           v_run_key, v_required, v_env),
         next_action = 'review and record a followup disposition',
         last_seen_at = i.last_seen_at,
         observed_at = now()
   where i.id = v_id;

  insert into ops.incident_fact (incident_id, text, source_ref)
  values (v_id,
          format('%s consecutive healthy runs of %s (%s); latest green run %s',
                 v_required, v_run_key, v_env, v_latest),
          'ops.clear_recovered_incident');

  return true;
end;
$_$;


--
-- Name: FUNCTION clear_recovered_incident(p_ref text, p_required integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.clear_recovered_incident(p_ref text, p_required integer) IS 'The only path by which a scheduled job may close an incident. SECURITY DEFINER because 0117 withholds resolved_at from carr_jobs and that grant stands: the role gains one function that re-derives the success sequence from ops.run and refuses SEV-1, refuses hand-opened incidents, and refuses anything whose evidence does not hold. Returns false rather than raising, so a refusal never costs the caller its run row.';


--
-- Name: commit_cost_ledger_operation(text, integer, text, text, text, text, jsonb, text, integer, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.commit_cost_ledger_operation(p_tree_ref text, p_base_version integer, p_base_state_digest text, p_operation_id text, p_argument_digest text, p_kind text, p_outcome jsonb, p_refusal_reason_id text, p_next_version integer, p_next_state_digest text, p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_prior ops.cost_ledger_operation%rowtype; v_cur integer; v_dig text; v_entry jsonb;
begin
  -- 1. REPLAY FIRST, before the cell is looked at at all. A legitimate replay
  --    offered from its ORIGINAL base must not meet the already-moved cell and
  --    come back as a conflict.
  select * into v_prior from ops.cost_ledger_operation
    where tree_ref = p_tree_ref and operation_id = p_operation_id;
  if v_prior.operation_id is not null then
    if v_prior.argument_digest is distinct from p_argument_digest then
      raise exception 'operation_id_reused_with_different_arguments'
        using errcode = '22023',
        detail = format('operation %s on tree %s was applied with a different argument digest',
          p_operation_id, p_tree_ref);
    end if;
    select ledger_version into v_cur from ops.cost_ledger_cell where tree_ref = p_tree_ref;
    return jsonb_build_object('ok', true, 'replayed', true,
      'outcome', v_prior.outcome, 'ledger_version', v_cur);
  end if;

  -- 2. THEN THE LOCK, inside this function. The library already holds it from
  --    step (0) of its own transaction and a second `for update` on a row this
  --    transaction already holds is a no-op -- so the library path is
  --    unchanged. What it adds is that an AUTHORITY caller reaching this
  --    function directly is serialized too.
  perform 1 from ops.cost_ledger_cell where tree_ref = p_tree_ref for update;

  -- 3. THEN THE BASE, as a predicated write. ZERO ROWS MATCHED IS THE REFUSAL.
  --    The predicate carries both the version and the digest, so the refusal is
  --    correct even for two operations that would land on the same number.
  update ops.cost_ledger_cell
     set ledger_version = p_next_version, state_digest = p_next_state_digest, updated_at = now()
   where tree_ref = p_tree_ref
     and ledger_version = p_base_version
     and state_digest = p_base_state_digest;
  if not found then
    select ledger_version, state_digest into v_cur, v_dig
      from ops.cost_ledger_cell where tree_ref = p_tree_ref;
    -- THE FOUR NAMES ARE THE MODULE'S OWN (conflictOutcome :1439-1447 and the
    -- version_conflict branch :1517-1527). Never expected_/actual_.
    return jsonb_build_object(
      'ok', false, 'reason_id', 'version_conflict',
      'base_version', p_base_version, 'current_version', v_cur,
      'base_state_digest', p_base_state_digest, 'current_state_digest', v_dig);
  end if;

  -- 4. THEN THE ROWS. A refusal is an applied operation with an empty entry
  --    array, and it is stored exactly like an accepted one.
  insert into ops.cost_ledger_operation(
    tree_ref, operation_id, kind, argument_digest, outcome, refusal_reason_id,
    produced_version, correlation_id)
  values (p_tree_ref, p_operation_id, p_kind, p_argument_digest, p_outcome,
          p_refusal_reason_id, p_next_version,
          nullif(current_setting('carr.correlation_id', true), ''));

  for v_entry in select value from jsonb_array_elements(coalesce(p_entries, '[]'::jsonb))
                  order by (value->>'sequence')::integer
  loop
    insert into ops.cost_ledger_entry(
      tree_ref, sequence, entry_id, kind, node_id, amount_units, operation_id,
      occurred_at, reservation_id, liability_id, conversion_id, vendor_reference, basis_digest)
    values (p_tree_ref, (v_entry->>'sequence')::integer, v_entry->>'entry_id',
            v_entry->>'kind', v_entry->>'node_id', (v_entry->>'amount_units')::bigint,
            v_entry->>'operation_id', (v_entry->>'occurred_at')::timestamptz,
            v_entry->>'reservation_id', v_entry->>'liability_id', v_entry->>'conversion_id',
            v_entry->>'vendor_reference', v_entry->>'basis_digest');
  end loop;

  return jsonb_build_object('ok', true, 'replayed', false, 'outcome', p_outcome,
    'ledger_version', p_next_version, 'state_digest', p_next_state_digest);
end $$;


--
-- Name: FUNCTION commit_cost_ledger_operation(p_tree_ref text, p_base_version integer, p_base_state_digest text, p_operation_id text, p_argument_digest text, p_kind text, p_outcome jsonb, p_refusal_reason_id text, p_next_version integer, p_next_state_digest text, p_entries jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.commit_cost_ledger_operation(p_tree_ref text, p_base_version integer, p_base_state_digest text, p_operation_id text, p_argument_digest text, p_kind text, p_outcome jsonb, p_refusal_reason_id text, p_next_version integer, p_next_state_digest text, p_entries jsonb) IS 'WR-000111: the single admission point. Replay first, then the row lock, then a version-and-digest predicated cell move whose zero-row result IS the refusal, then the operation and entry rows.';


--
-- Name: compile_context_bundle(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.compile_context_bundle(p_work_request text, p_plan_ref text, p_tenant text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare work ops.work_request%rowtype; plan ops.sourced_work_request_plan%rowtype; body jsonb;
begin
  if coalesce(current_setting('carr.organization_tenant_id',true),'') <> p_tenant then
    raise exception 'context compilation tenant must match authenticated tenant context';
  end if;
  if p_tenant is null or p_tenant='' then raise exception 'context compiler requires authenticated tenant'; end if;
  select * into work from ops.work_request where ref=p_work_request and organization_tenant_id=p_tenant;
  select * into plan from ops.sourced_work_request_plan where work_request_id=work.id and plan_ref=p_plan_ref order by plan_version desc limit 1;
  if not found then raise exception 'context compiler plan not found'; end if;
  if work.id is null then raise exception 'context compiler Work Request not found'; end if;
  if jsonb_typeof(plan.preimage->'context_activation_items') <> 'array'
     or jsonb_array_length(plan.preimage->'context_activation_items') < 1 then
    raise exception 'context compiler accepted plan has no frozen canonical items';
  end if;
  body := ops.context_activation_bundle_from_items(
    p_tenant, work.ref, 'plan:runbook:' || plan.runbook_revision_id::text, 1,
    coalesce(plan.preimage->'context_activation'->>'base_plan_digest',plan.plan_hash),
    work.triaged_at, plan.preimage->'context_activation_items'
  );
  return body || jsonb_build_object('bundle_digest',ops.context_activation_bundle_digest(body));
end $$;


--
-- Name: complete_calendar_prebrief_joe_live_job(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.complete_calendar_prebrief_joe_live_job(p_job uuid, p_lease uuid, p_attestation uuid, p_receipt uuid) RETURNS TABLE(job_id uuid, attempt integer, state text, attestation_id uuid, receipt_id uuid, allowlist_revision_id uuid, allowlist_digest text, scheduled_for timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; r ops.calendar_prebrief_projection_receipt%rowtype; a ops.calendar_prebrief_source_attestation_receipt%rowtype;
begin
 if session_user<>'carr_jobs' then raise exception 'Joe completion identity refused'; end if;
 select * into j from ops.job where id=p_job for update;
 if not found or j.definition_key<>'calendar-prebrief-projection-joe-daily' or j.definition_version<>1 or j.mode<>'live' or j.state<>'running' or j.lease_token is distinct from p_lease then raise exception 'Joe completion lease refused'; end if;
 select * into r from ops.calendar_prebrief_projection_receipt where job_id=j.id and attempt=j.attempt and id=p_receipt;
 select * into a from ops.calendar_prebrief_source_attestation_receipt where job_id=j.id and attempt=j.attempt and id=p_attestation;
 if r.id is null or a.id is null or r.source_attestation_id<>a.id or r.sponsor<>'joe' or a.sponsor<>'joe' or a.lease_token<>p_lease then raise exception 'Joe completion evidence refused'; end if;
 perform ops.complete_job(j.id,p_lease,jsonb_build_object('sponsor','joe','mode','live','attestation_id',p_attestation,'receipt_id',p_receipt,'allowlist_revision_id',r.allowlist_revision_id,'allowlist_digest',r.allowlist_digest),'calendar-prebrief:joe:'||j.id::text||':'||j.attempt::text);
 return query select j.id,j.attempt,'succeeded'::text,a.id,r.id,r.allowlist_revision_id,r.allowlist_digest,j.scheduled_for;
end $$;


--
-- Name: complete_job(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.complete_job(p_job_id uuid, p_lease_token uuid, p_evidence jsonb, p_receipt_ref text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if found and j.definition_key='engineering-slice' then
    raise exception 'engineering jobs require scoped controller functions';
  end if;
  if not found or j.state <> 'running' or j.lease_token <> p_lease_token
     or j.leased_until < now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  update ops.job_attempt set state='succeeded',ended_at=now()
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  update ops.job set state='succeeded',ended_at=now(),lease_owner=null,
         lease_token=null,leased_until=null,updated_at=now() where id=j.id;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,'completion',p_receipt_ref,coalesce(p_evidence,'{}'::jsonb));
  return true;
end $$;


