--
-- Name: create_calendar_canary_source_snapshot(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_calendar_canary_source_snapshot(p_job_id uuid, p_lease uuid) RETURNS TABLE(id uuid, snapshot_digest text, contact_count integer, snapshot_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;s jsonb;r ops.calendar_canary_source_snapshot%rowtype;
begin
 j:=ops.calendar_canary_live_job(p_job_id,p_lease);
 select coalesce(jsonb_agg(x order by source_rank,x->>'email',x->>'ref'),'[]') into s from(
  select jsonb_build_object('email',lower(btrim("Email")),'ref',"Client ID",'name',"Name",'org',"Practice / Entity") x,1 source_rank from v_export_clients where "Email" is not null and position('@' in btrim("Email"))>1
  union all select jsonb_build_object('email',lower(btrim("Email")),'ref',"Lead ID",'name',"Contact Name",'org',"Practice"),2 from v_export_leads where "Email" is not null and position('@' in btrim("Email"))>1)q;
 if jsonb_array_length(s)=0 then raise exception using errcode='22023',message='calendar canary source snapshot is empty'; end if;
 insert into ops.calendar_canary_source_snapshot(job_id,attempt,workflow_version,snapshot,snapshot_digest,contact_count)
 values(j.id,j.attempt,5,s,encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex'),jsonb_array_length(s)) on conflict(job_id,attempt) do nothing returning * into r;
 if not found then
  select * into r from ops.calendar_canary_source_snapshot where job_id=j.id and attempt=j.attempt;
  if r.snapshot_digest<>encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex') or r.contact_count<>jsonb_array_length(s) then raise exception using errcode='23505',message='calendar canary source snapshot replay conflicts with canonical contacts'; end if;
 end if;
 return query select r.id,r.snapshot_digest,r.contact_count,r.snapshot::text;
end $$;


--
-- Name: create_doc_conversation(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_doc_conversation(p_title text, p_visibility text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_id uuid; v_version integer; v_visibility text;
        v_prior ops.doc_conversation%rowtype;
begin
  v_actor := ops.portfolio_writer_actor_id();
  if p_idempotency_key is null then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_idempotency_key_required');
  end if;
  v_visibility := coalesce(p_visibility, 'private');
  -- The table's own check at 0520:34 would refuse this anyway; refusing here
  -- gives the caller a reason_id instead of a constraint error.
  if v_visibility not in ('private', 'shared') then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_visibility_invalid');
  end if;

  insert into ops.doc_conversation(id, title, created_by_actor, visibility)
  values (p_idempotency_key, p_title, v_actor, v_visibility)
  on conflict (id) do nothing
  returning id, version into v_id, v_version;

  if v_id is null then
    select * into v_prior from ops.doc_conversation where id = p_idempotency_key;
    if v_prior.id is null then
      return jsonb_build_object('ok', false, 'reason_id', 'dedup_row_vanished');
    end if;
    -- The append's full-field replay comparison (0520:137-149): the same key
    -- offered with different content is a REUSE, not a duplicate.
    if v_prior.title is distinct from p_title
       or v_prior.visibility is distinct from v_visibility
       or v_prior.created_by_actor is distinct from v_actor then
      return jsonb_build_object('ok', false,
        'reason_id', 'doc_conversation_idempotency_key_reuse', 'id', p_idempotency_key);
    end if;
    return jsonb_build_object('ok', true, 'deduplicated', true, 'id', v_prior.id,
      'version', v_prior.version, 'title', v_prior.title, 'visibility', v_prior.visibility,
      'created_by', v_prior.created_by_actor);
  end if;

  return jsonb_build_object('ok', true, 'deduplicated', false, 'id', v_id,
    'version', v_version, 'title', p_title, 'visibility', v_visibility,
    'created_by', v_actor);
end $$;


--
-- Name: FUNCTION create_doc_conversation(p_title text, p_visibility text, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.create_doc_conversation(p_title text, p_visibility text, p_idempotency_key uuid) IS 'WR-000114: the only door that starts a Doc conversation. The creator is derived from the transaction context and the row id IS the idempotency key, so a replayed create is one row by construction.';


--
-- Name: create_nightly_availability_canary_source_snapshot(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_nightly_availability_canary_source_snapshot(p_job_id uuid, p_lease uuid) RETURNS TABLE(id uuid, snapshot_digest text, availability_count integer, open_search_count integer, snapshot_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;s jsonb;r ops.nightly_availability_canary_source_snapshot%rowtype;
begin
 j:=ops.nightly_availability_canary_live_job(p_job_id,p_lease);
 select jsonb_build_object(
   'availabilities',coalesce((select jsonb_agg(x order by x->>'id') from (
      select jsonb_build_object('id',av.id::text,'status',av.status,'rate_norm',av.rate_norm_sf_yr,
        'owed',av.norm_owed,'available_on',av.available_on,'observed',av.observed_at::date,
        'source',av.source,'area',sp.area_amount,'suite',sp.suite,'city',b.city,'state',b.state,
        'sub_type',b.sub_type,'address',b.address,'bname',b.name) x
        from (select distinct on (av.space_id) av.* from availability av
               order by av.space_id,av.observed_at desc,av.id desc) av
        join space sp on sp.id=av.space_id join building b on b.id=sp.building_id)q),'[]'::jsonb),
   'searches',coalesce((select jsonb_agg(x order by x->>'ref',x->>'id') from (
      select jsonb_build_object('id',s.id::text,'spec',s.spec,'ref',coalesce(c.roster_ref,''),'name',p.name) x
        from space_search s join client c on c.id=s.client_id join party p on p.id=c.party_id where s.status='open')q),'[]'::jsonb)) into s;
 if jsonb_array_length(s->'availabilities')=0 or jsonb_array_length(s->'searches')=0 then
   raise exception using errcode='22023',message='nightly availability canary source must contain availability and open-search evidence';
 end if;
 insert into ops.nightly_availability_canary_source_snapshot(job_id,attempt,workflow_version,snapshot,snapshot_digest,availability_count,open_search_count)
 values(j.id,j.attempt,3,s,encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex'),jsonb_array_length(s->'availabilities'),jsonb_array_length(s->'searches'))
 on conflict(job_id,attempt) do nothing returning * into r;
 if not found then
  select * into r from ops.nightly_availability_canary_source_snapshot where job_id=j.id and attempt=j.attempt;
  if r.snapshot_digest<>encode(digest(convert_to(s::text,'UTF8'),'sha256'),'hex') or r.availability_count<>jsonb_array_length(s->'availabilities') or r.open_search_count<>jsonb_array_length(s->'searches') then raise exception using errcode='23505',message='nightly availability canary source replay conflicts with canonical snapshot'; end if;
 end if;
 return query select r.id,r.snapshot_digest,r.availability_count,r.open_search_count,r.snapshot::text;
end $$;


--
-- Name: create_tour_domain(text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_tour_domain(p_tenant text, p_tour_name text, p_subject_type text, p_subject_id text, p_canonical_dataset_version text, p_start_point jsonb, p_end_point jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_id uuid; v_actor text;
begin
  v_actor:=ops.tour_server_actor_id();
  if p_tenant is null or p_tour_name is null or p_tour_name !~ '^.{1,240}$' or p_subject_type not in ('client','work') or p_subject_id is null or p_subject_id !~ '^[A-Za-z0-9._:-]{1,200}$' or p_canonical_dataset_version is null or p_canonical_dataset_version !~ '^.{1,240}$' or jsonb_typeof(p_start_point)<>'object' or jsonb_typeof(p_end_point)<>'object' then raise exception 'tour subject binding is invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant || ':' || p_subject_type || ':' || p_subject_id,386));
  insert into ops.tour(organization_tenant_id,tour_name,tour_status,route_version,canonical_dataset_version,subject_type,subject_id,subject_bound_at) values(p_tenant,p_tour_name,'draft',1,p_canonical_dataset_version,p_subject_type,p_subject_id,now()) returning id into v_id;
  insert into ops.tour_route_version(organization_tenant_id,tour_id,route_version,start_point,end_point,routing_source,routing_request,created_by_actor_id) values(p_tenant,v_id,1,p_start_point,p_end_point,'manual','{}',v_actor);
  return v_id;
end $_$;


--
-- Name: create_tour_public_projection_draft(text, uuid, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.create_tour_public_projection_draft(p_tenant text, p_tour_id uuid, p_projection_version integer, p_route_version integer, p_as_of timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_digest text;
begin
  if p_tenant is null or p_tour_id is null or p_projection_version is null
     or p_route_version is null or p_as_of is null then
    raise exception 'projection draft payload is invalid';
  end if;
  v_digest := 'sha256:' || encode(public.digest(jsonb_build_object(
    'organization_tenant_id',p_tenant,'tour_id',p_tour_id,'projection_version',p_projection_version,
    'route_version',p_route_version,'as_of',p_as_of,'facts','[]'::jsonb,'kind','draft')::text,'sha256'),'hex');
  insert into ops.tour_public_projection (organization_tenant_id,tour_id,projection_version,route_version,as_of,facts_only,projection_digest,status)
  values (p_tenant,p_tour_id,p_projection_version,p_route_version,p_as_of,true,v_digest,'draft')
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: current_sourced_work_requests(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.current_sourced_work_requests(p_organization_tenant_id text) RETURNS TABLE(ref text, title text, state text, source_label text, source_freshness text, next_human_action text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select w.ref,
         w.title,
         w.state,
         coalesce(s.title, s.section_key) as source_label,
         'current'::text as source_freshness,
         case
           when w.state = 'captured' then 'Review and triage'
           when w.state = 'triaged' then 'Prepare or review bounded plan'
           when w.state = 'ready' then 'Record or review outcome evidence'
         end as next_human_action
    from ops.work_request w
    join public.doctrine_section s on s.id = w.doctrine_section_id
    join public.doctrine_document d on d.id = s.document_id
   where p_organization_tenant_id = 'carr-internal'
     and w.organization_tenant_id = p_organization_tenant_id
     and w.capture_idempotency_key is not null
     and w.state in ('captured', 'triaged', 'ready')
     -- V5-F09: an accepted outcome feedback receipt removes ACTIONABILITY and
     -- nothing else. The Work Request keeps its state, its plan, its feedback
     -- and its card/history lookups; it simply stops being offered as work
     -- somebody still has to do. Read-only: this function mutates no row.
     and not exists (
       select 1
         from ops.sourced_work_request_outcome_feedback_acceptance_receipt accepted_outcome
        where accepted_outcome.work_request_id = w.id
     )
     and d.visibility = 'shared'
     and s.status = 'active'
     and s.current_revision_id = w.doctrine_revision_id
     and (
       w.state <> 'triaged'
       or (
         not exists (
           select 1
             from ops.sourced_work_request_plan existing_plan
            where existing_plan.work_request_id = w.id
         )
         and exists (
           select 1
             from public.doctrine_document runbook_document
             join public.doctrine_section runbook_section
               on runbook_section.document_id = runbook_document.id
             join public.doctrine_revision runbook_revision
               on runbook_revision.id = runbook_section.current_revision_id
              and runbook_revision.section_id = runbook_section.id
            where runbook_document.slug = 'runbook'
              and runbook_document.visibility = 'shared'
              and runbook_section.section_key = 'diagnosis-checklist-in-order-2-minutes'
              and runbook_section.status = 'active'
              and runbook_revision.content_hash ~ '^[0-9a-f]{64}$'
              and encode(public.digest(runbook_revision.plain_text, 'sha256'), 'hex') = runbook_revision.content_hash
              and runbook_revision.body = jsonb_build_object('text', runbook_revision.plain_text)
         )
       )
       or exists (
         select 1
           from ops.sourced_work_request_plan current_plan
           join public.doctrine_section planned_runbook_section
             on planned_runbook_section.id = current_plan.runbook_section_id
           join public.doctrine_document planned_runbook_document
             on planned_runbook_document.id = planned_runbook_section.document_id
           join public.doctrine_revision planned_runbook_revision
             on planned_runbook_revision.id = planned_runbook_section.current_revision_id
            and planned_runbook_revision.section_id = planned_runbook_section.id
          where current_plan.id = (
            select latest_plan.id
              from ops.sourced_work_request_plan latest_plan
             where latest_plan.work_request_id = w.id
             order by latest_plan.plan_version desc
             limit 1
          )
            and planned_runbook_document.slug = 'runbook'
            and planned_runbook_document.visibility = 'shared'
            and planned_runbook_section.status = 'active'
            and planned_runbook_revision.id = current_plan.runbook_revision_id
            and planned_runbook_revision.content_hash = current_plan.runbook_content_hash
            and ('doctrine:' || planned_runbook_document.slug || '#' || planned_runbook_section.section_key) = current_plan.runbook_ref
            and encode(public.digest(planned_runbook_revision.plain_text, 'sha256'), 'hex') = planned_runbook_revision.content_hash
            and planned_runbook_revision.body = jsonb_build_object('text', planned_runbook_revision.plain_text)
       )
     )
   order by w.captured_at asc, w.ref asc
   limit 20;
$_$;


--
-- Name: deactivate_guidance_registry(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deactivate_guidance_registry(p_registry_id uuid, p_manifest_digest text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_authority_slug text;
  v_authority_actor uuid;
  v_registry_owner uuid;
  v_active_digest text;
  v_existing record;
  v_receipt_id uuid;
  v_event_id uuid;
begin
  v_authority_slug := ops.authority_actor_slug();
  select id into v_authority_actor from actor where slug=v_authority_slug and kind='human' and active;
  select created_by into v_registry_owner from ops.guidance_registry where id=p_registry_id;
  if v_authority_actor is null or v_registry_owner is null or v_authority_actor<>v_registry_owner then
    raise exception 'guidance registry deactivation requires its accountable human authority actor';
  end if;
  if p_manifest_digest !~ '^[0-9a-f]{64}$' or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'deactivation requires a sha256 manifest digest, idempotency key and reason';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('guidance-registry-deactivation:' || p_idempotency_key,0));
  select ar.id,ar.kind,ar.subject_type,ar.subject_id,ar.actor_id,ar.decision,
         ar.contract_hash,ge.id as event_id,ge.manifest_digest,ge.reason
    into v_existing from ops.authority_receipt ar
    left join ops.guidance_registry_event ge on ge.authority_receipt_id=ar.id
   where ar.idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.kind<>'rejection' or v_existing.subject_type<>'guidance'
       or v_existing.subject_id<>p_registry_id or v_existing.actor_id<>v_authority_actor
       or v_existing.decision<>'retired' or v_existing.contract_hash<>p_manifest_digest
       or v_existing.event_id is null or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different or incomplete guidance registry deactivation';
    end if;
    return v_existing.event_id;
  end if;
  select manifest_digest into v_active_digest from ops.v_guidance_registry_state
   where registry_id=p_registry_id and state='active';
  if v_active_digest is null or v_active_digest<>p_manifest_digest then
    raise exception 'guidance registry deactivation requires the exact currently active manifest digest';
  end if;
  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,contract_hash,evidence_refs)
  values (p_idempotency_key,'rejection','guidance',p_registry_id,v_authority_actor,
          'retired',p_manifest_digest,array[p_registry_id::text])
  returning id into v_receipt_id;
  insert into ops.guidance_registry_event
    (registry_id,state,authority_receipt_id,manifest_digest,reason)
  values (p_registry_id,'inactive',v_receipt_id,p_manifest_digest,p_reason)
  returning id into v_event_id;
  return v_event_id;
end $_$;


--
-- Name: decide_guidance_import_batch(uuid, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.decide_guidance_import_batch(p_batch_id uuid, p_manifest_digest text, p_state text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch ops.guidance_import_batch%rowtype;
  v_authority_slug text;
  v_authority_actor uuid;
  v_registry_owner uuid;
  v_existing record;
  v_decision_id uuid;
  v_entry ops.guidance_import_entry%rowtype;
  v_item_id uuid;
  v_revision_id uuid;
  v_lifecycle_id uuid;
  v_binding_id uuid;
  v_mapping ops.guidance_import_mapping_execution%rowtype;
  v_active_mapping_id uuid;
begin
  v_authority_slug := ops.authority_actor_slug();
  select id into v_authority_actor from actor where slug=v_authority_slug and kind='human' and active;
  select created_by into v_registry_owner from ops.guidance_registry where singleton;
  if v_authority_actor is null or v_authority_actor<>v_registry_owner then
    raise exception 'guidance import batch decision requires the accountable registry human authority';
  end if;
  if p_state <> 'active' or p_manifest_digest !~ '^[0-9a-f]{64}$'
     or coalesce(btrim(p_idempotency_key),'')='' or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance import decision requires state, digest, idempotency key and reason';
  end if;
  select * into v_batch from ops.guidance_import_batch where id=p_batch_id;
  if v_batch.id is null or v_batch.manifest_digest<>p_manifest_digest
     or not exists (select 1 from ops.guidance_import_apply_event where batch_id=p_batch_id) then
    raise exception 'guidance import batch must be staged, exact-digest matched and applied before a decision';
  end if;
  perform ops.assert_guidance_import_inventory(p_batch_id);
  select * into v_existing from ops.guidance_import_decision_event where idempotency_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.batch_id<>p_batch_id or v_existing.manifest_digest<>p_manifest_digest
       or v_existing.state<>p_state or v_existing.authority_actor_id<>v_authority_actor
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different guidance import decision';
    end if;
    return v_existing.id;
  end if;
  insert into ops.guidance_import_decision_event
    (batch_id,manifest_digest,state,idempotency_key,authority_actor_id,reason)
  values (p_batch_id,p_manifest_digest,p_state,p_idempotency_key,v_authority_actor,p_reason)
  returning id into v_decision_id;
  for v_entry in select * from ops.guidance_import_entry where batch_id=p_batch_id order by ordinal loop
    select i.id,r.id into v_item_id,v_revision_id from ops.guidance_item i
      join ops.guidance_revision r on r.guidance_item_id=i.id and r.version=1
     where i.source_rule_id=v_entry.source_rule_id and i.source_clause=v_entry.source_clause;
    if v_revision_id is null then
      raise exception 'applied import entry % has no exact revision',v_entry.guidance_id;
    end if;
    v_lifecycle_id := ops.record_guidance_decision(
      v_revision_id,p_state,
      encode(digest(convert_to(p_idempotency_key || ':revision:' || v_revision_id::text,'UTF8'),'sha256'),'hex'),
      p_reason);
    if p_state='active' then
      select authority_binding_id into v_binding_id from ops.guidance_lifecycle_event where id=v_lifecycle_id;
      for v_mapping in select * from ops.guidance_import_mapping_execution
          where batch_id=p_batch_id and entry_id=v_entry.id
            and active_mapping_id is null order by ordinal loop
        if exists (select 1 from ops.guidance_import_mapping_execution prior
                    where prior.proposed_mapping_id=v_mapping.proposed_mapping_id
                      and prior.active_mapping_id is not null) then
          continue;
        end if;
        v_active_mapping_id := ops.activate_guidance_situation_mapping(
          v_mapping.proposed_mapping_id,v_binding_id,p_reason);
        -- Mapping execution is append-only; record the activated counterpart
        -- in a second immutable row rather than rewriting the proposal row.
        insert into ops.guidance_import_mapping_execution
          (batch_id,entry_id,ordinal,concept_id,doctrine_section_id,proposed_mapping_id,active_mapping_id)
        values (p_batch_id,v_entry.id,v_mapping.ordinal + 1000000,
                v_mapping.concept_id,v_mapping.doctrine_section_id,
                v_mapping.proposed_mapping_id,v_active_mapping_id);
      end loop;
    end if;
  end loop;
  return v_decision_id;
end $_$;


--
-- Name: decide_meeting_action(uuid, integer, text, integer, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.decide_meeting_action(p_meeting uuid, p_action_number integer, p_decision text, p_base_revision integer, p_disposition text, p_assignee_slug text, p_client_instance text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype; v_head ops.meeting_action%rowtype;
        v_latest ops.meeting_action_revision%rowtype; v_assignee uuid; v_disposition text;
begin
  select * into v_who from ops.meeting_mode_actor();
  if not coalesce(v_who.is_partner, false) then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_decision_requires_verified_partner');
  end if;
  if p_decision not in ('accept', 'decline') then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_decision_invalid');
  end if;
  select * into v_row from ops.meeting
   where id = p_meeting and organization_tenant_id = v_who.tenant for update;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  select * into v_head from ops.meeting_action
   where meeting_id = p_meeting and action_number = p_action_number for update;
  if v_head.meeting_id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_not_found',
      'action_number', p_action_number);
  end if;
  if exists (select 1 from ops.meeting_stream where idempotency_key = p_idempotency_key
               and kind in ('action_accepted', 'action_declined')) then
    return jsonb_build_object('ok', true, 'deduplicated', true, 'already', true,
      'meeting_id', p_meeting, 'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;

  if v_head.state <> 'proposed' then
    if p_decision = 'accept' and v_head.state in ('accepted', 'executed', 'delegated') then
      return jsonb_build_object('ok', true, 'deduplicated', false, 'already', true,
        'resolved_once', true, 'meeting_id', p_meeting,
        'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
    end if;
    if p_decision = 'decline' and v_head.state = 'declined' then
      return jsonb_build_object('ok', true, 'deduplicated', false, 'already', true,
        'meeting_id', p_meeting, 'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
    end if;
    return jsonb_build_object('ok', false,
      'reason_id', case when v_head.state = 'declined' then 'meeting_action_already_declined'
                        else 'meeting_action_already_accepted_requires_correction' end,
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  if p_base_revision is distinct from v_head.current_revision then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_revised_since_read',
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;

  if p_decision = 'decline' then
    update ops.meeting_action
       set state = 'declined', decided_revision = v_head.current_revision,
           decided_by_actor = v_who.actor_id, decided_at = clock_timestamp()
     where meeting_id = p_meeting and action_number = p_action_number;
    perform ops.meeting_mode_append(p_meeting, 'action_declined', v_who.actor_id,
      p_client_instance, null, p_action_number, v_head.current_revision, null, p_idempotency_key);
    return jsonb_build_object('ok', true, 'deduplicated', false, 'already', false,
      'meeting_id', p_meeting, 'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;

  select * into v_latest from ops.meeting_action_revision
   where meeting_id = p_meeting and action_number = p_action_number
     and revision = v_head.current_revision;
  if v_latest.command is null then
    -- A tentative item with nothing to execute stays a proposal; accepting it
    -- would make this table the task store.
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_has_no_canonical_command',
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  v_disposition := coalesce(p_disposition, 'execute');
  if v_disposition not in ('execute', 'delegate') then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_disposition_invalid');
  end if;
  if p_assignee_slug is null then
    if v_disposition = 'delegate' then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_delegation_requires_assignee');
    end if;
    v_assignee := v_who.actor_id;
  else
    select id into v_assignee from public.actor where slug = p_assignee_slug and active;
    if v_assignee is null then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_assignee_not_found');
    end if;
  end if;
  perform ops.meeting_mode_accept(p_meeting, p_action_number, v_head.current_revision,
    v_who.actor_id, v_disposition, v_assignee, p_client_instance, p_idempotency_key);
  return jsonb_build_object('ok', true, 'deduplicated', false, 'already', false,
    'resolved_once', true, 'meeting_id', p_meeting,
    'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
end $$;


--
-- Name: decline_sourced_work_request(text, integer, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.decline_sourced_work_request(p_work_request text, p_base_version integer, p_exit_reason text, p_actor_slug text, p_idempotency_key uuid) RETURNS TABLE(ref text, state text, version integer, exit_reason text, closed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  v_id uuid;
  v_actor uuid;
  v_now timestamp with time zone := now();
begin
  if p_exit_reason is null or btrim(p_exit_reason) = '' then
    raise exception 'a withdrawal must record why';
  end if;
  select a.id into v_actor from public.actor a where a.slug = p_actor_slug;
  if v_actor is null then
    raise exception 'unknown actor %', p_actor_slug;
  end if;

  select w.id into v_id from ops.work_request w
   where w.ref = p_work_request and w.capture_idempotency_key is not null
     and w.state = 'captured' and w.version = p_base_version
   for update;
  if v_id is null then
    raise exception 'no captured sourced Work Request % at version %', p_work_request, p_base_version;
  end if;

  insert into ops.work_request_withdrawal_receipt
    (work_request_id, idempotency_key, base_version, result_version, final_state,
     exit_reason, superseded_by, withdrawn_by_actor_id, withdrawn_at)
  values (v_id, p_idempotency_key, p_base_version, p_base_version + 1, 'declined',
          p_exit_reason, null, v_actor, v_now)
  on conflict (idempotency_key) do nothing;

  update ops.work_request w
     set state = 'declined', exit_reason = p_exit_reason, closed_at = v_now,
         version = w.version + 1, updated_at = v_now
   where w.id = v_id;

  return query
    select w.ref, w.state, w.version, w.exit_reason, w.closed_at
      from ops.work_request w where w.id = v_id;
end;
$$;


--
-- Name: deployment_provider_identity_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deployment_provider_identity_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.environment = 'production'
     and old.state in ('deploying', 'verifying', 'complete')
     and (new.provider is distinct from old.provider
          or new.provider_version_id is distinct from old.provider_version_id) then
    raise exception 'Production deployment provider identity is immutable after promotion begins';
  end if;
  return new;
end $$;


--
-- Name: deployment_requires_a_live_approval(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.deployment_requires_a_live_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare rel ops.release%rowtype; receipt ops.release_readiness_receipt%rowtype;
begin
  if new.environment<>'production' then return new; end if;
  if new.release_id is null then raise exception 'Production deployment requires a release'; end if;
  select * into rel from ops.release where id=new.release_id;
  if not found or rel.environment is distinct from new.environment
     or rel.git_sha is distinct from new.git_sha
     or rel.provider is distinct from new.provider
     or rel.provider_version_id is distinct from new.provider_version_id then
    raise exception 'Production deployment differs from exact release identity';
  end if;
  if rel.readiness_receipt_id is not null then
    select * into receipt from ops.release_readiness_receipt
      where id=rel.readiness_receipt_id;
    if rel.state not in ('ready','deploying','verifying','complete')
       or not found or receipt.release_id<>rel.id
       or receipt.git_sha<>rel.git_sha or receipt.provider<>rel.provider
       or receipt.provider_version_id<>rel.provider_version_id
       or receipt.plan_hash<>rel.plan_hash
       or (rel.state<>'complete'
           and not ops.release_technical_readiness_current(rel.id)) then
      raise exception 'Production deployment lacks exact technical readiness';
    end if;
  elsif rel.state not in ('approved','deploying','verifying','complete')
     or rel.approval_expires_at is null or rel.approval_expires_at<=now() then
    raise exception 'Production deployment lacks live historical approval';
  end if;
  return new;
end $$;


--
-- Name: disable_legacy_schedule(text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.disable_legacy_schedule(p_workflow_key text, p_surface_id text, p_locator text, p_reason text, p_pre_observation_ref text, p_post_observation_ref text, p_sibling_surface_id text, p_sibling_locator text, p_sibling_pre_observation_ref text, p_sibling_post_observation_ref text, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  n integer; v integer; ref text; kind text; group_name text;
  sibling_kind text; sibling_group text;
  existing ops.legacy_schedule_disable_receipt%rowtype;
  pre ops.legacy_schedule_observation_receipt%rowtype;
  post ops.legacy_schedule_observation_receipt%rowtype;
  sibling_pre ops.legacy_schedule_observation_receipt%rowtype;
  sibling_post ops.legacy_schedule_observation_receipt%rowtype;
begin
  if ops.authority_actor_slug() <> 'joe' then
    raise exception 'legacy schedule retirement requires Joe authority session';
  end if;
  if btrim(coalesce(p_workflow_key,''))='' or btrim(coalesce(p_surface_id,''))=''
     or btrim(coalesce(p_locator,''))='' or btrim(coalesce(p_reason,''))=''
     or btrim(coalesce(p_pre_observation_ref,''))=''
     or btrim(coalesce(p_post_observation_ref,''))=''
     or btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'cutover subject, reason, native observations, and idempotency key are required';
  end if;
  if (p_sibling_surface_id is null) <> (p_sibling_locator is null)
     or (p_sibling_surface_id is null) <> (p_sibling_pre_observation_ref is null)
     or (p_sibling_surface_id is null) <> (p_sibling_post_observation_ref is null)
     or (p_sibling_surface_id is not null and (
       btrim(p_sibling_surface_id)='' or btrim(p_sibling_locator)=''
       or btrim(p_sibling_pre_observation_ref)='' or btrim(p_sibling_post_observation_ref)='')) then
    raise exception 'duplicate scheduler evidence fields must be supplied together';
  end if;

  select * into existing from ops.legacy_schedule_disable_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.workflow_key is distinct from p_workflow_key
       or existing.surface_id is distinct from p_surface_id
       or existing.locator is distinct from p_locator
       or existing.reason is distinct from p_reason
       or existing.pre_observation_ref is distinct from p_pre_observation_ref
       or existing.post_observation_ref is distinct from p_post_observation_ref
       or existing.sibling_surface_id is distinct from p_sibling_surface_id
       or existing.sibling_locator is distinct from p_sibling_locator
       or existing.sibling_pre_observation_ref is distinct from p_sibling_pre_observation_ref
       or existing.sibling_post_observation_ref is distinct from p_sibling_post_observation_ref then
      raise exception 'idempotency key is bound to different verified legacy disable evidence';
    end if;
    return existing.receipt_ref;
  end if;

  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  select scheduler_kind,duplicate_group into kind,group_name
    from ops.legacy_schedule_surface_registry
   where workflow_key=p_workflow_key and workflow_version=v
     and surface_id=p_surface_id and locator=p_locator;
  if kind is null then raise exception 'legacy schedule surface is not registered'; end if;

  if group_name is null then
    if p_sibling_surface_id is not null then
      raise exception 'single-surface cutover does not accept sibling evidence';
    end if;
  else
    if p_sibling_surface_id is null or p_surface_id >= p_sibling_surface_id then
      raise exception 'duplicate scheduler evidence must use canonical primary and sibling order';
    end if;
    select scheduler_kind,duplicate_group into sibling_kind,sibling_group
      from ops.legacy_schedule_surface_registry
     where workflow_key=p_workflow_key and workflow_version=v
       and surface_id=p_sibling_surface_id and locator=p_sibling_locator;
    if sibling_kind is null or sibling_group is distinct from group_name
       or (select count(*) from ops.legacy_schedule_surface_registry
            where workflow_key=p_workflow_key and workflow_version=v
              and duplicate_group=group_name) <> 2
       or array[kind,sibling_kind]::text[] @> array['claude-code','launchd']::text[] is not true then
      raise exception 'Notes duplicate retirement requires exact claude-code and launchd surfaces';
    end if;
  end if;

  if not exists (
    select 1 from ops.workflow_acceptance
     where workflow_key=p_workflow_key and workflow_version=v and mode='shadow' and status='accepted'
  ) or not exists (
    select 1 from ops.workflow_acceptance
     where workflow_key=p_workflow_key and workflow_version=v and mode='canary' and status='accepted'
  ) then
    raise exception 'legacy schedule retirement requires accepted shadow and canary evidence';
  end if;

  select r.* into pre from ops.legacy_schedule_observation_receipt r
   where r.receipt_ref=p_pre_observation_ref and r.scheduler_kind=kind
     and ((kind='claude-code' and exists (
       select 1 from ops.legacy_schedule_provider_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.cron_expression=r.cron_expression and c.timezone=r.timezone
          and c.definition_sha256=r.definition_sha256))
       or (kind='launchd' and exists (
       select 1 from ops.legacy_schedule_launchd_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
          and c.plist_sha256=r.definition_sha256)));
  select r.* into post from ops.legacy_schedule_observation_receipt r
   where r.receipt_ref=p_post_observation_ref and r.scheduler_kind=kind
     and ((kind='claude-code' and exists (
       select 1 from ops.legacy_schedule_provider_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.cron_expression=r.cron_expression and c.timezone=r.timezone
          and c.definition_sha256=r.definition_sha256))
       or (kind='launchd' and exists (
       select 1 from ops.legacy_schedule_launchd_contract c
        where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
          and c.workflow_version=r.workflow_version and c.locator=r.locator
          and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
          and c.plist_sha256=r.definition_sha256)));
  if pre.id is null or post.id is null
     or pre.workflow_key<>p_workflow_key or post.workflow_key<>p_workflow_key
     or pre.workflow_version<>v or post.workflow_version<>v
     or pre.surface_id<>p_surface_id or post.surface_id<>p_surface_id
     or pre.locator<>p_locator or post.locator<>p_locator
     or pre.scheduler_state<>'enabled' or post.scheduler_state<>'disabled'
     or pre.observed_at<now()-interval '15 minutes'
     or post.observed_at<now()-interval '15 minutes'
     or pre.observed_at>now()+interval '5 minutes'
     or post.observed_at>now()+interval '5 minutes'
     or post.observed_at<pre.observed_at
     or pre.source_fingerprint=post.source_fingerprint then
    raise exception 'native scheduler evidence is not a current enabled-to-disabled readback';
  end if;

  if p_sibling_surface_id is not null then
    select r.* into sibling_pre from ops.legacy_schedule_observation_receipt r
     where r.receipt_ref=p_sibling_pre_observation_ref and r.scheduler_kind=sibling_kind
       and ((sibling_kind='claude-code' and exists (
         select 1 from ops.legacy_schedule_provider_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.cron_expression=r.cron_expression and c.timezone=r.timezone
            and c.definition_sha256=r.definition_sha256))
         or (sibling_kind='launchd' and exists (
         select 1 from ops.legacy_schedule_launchd_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
            and c.plist_sha256=r.definition_sha256)));
    select r.* into sibling_post from ops.legacy_schedule_observation_receipt r
     where r.receipt_ref=p_sibling_post_observation_ref and r.scheduler_kind=sibling_kind
       and ((sibling_kind='claude-code' and exists (
         select 1 from ops.legacy_schedule_provider_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.cron_expression=r.cron_expression and c.timezone=r.timezone
            and c.definition_sha256=r.definition_sha256))
         or (sibling_kind='launchd' and exists (
         select 1 from ops.legacy_schedule_launchd_contract c
          where c.surface_id=r.surface_id and c.workflow_key=r.workflow_key
            and c.workflow_version=r.workflow_version and c.locator=r.locator
            and c.schedule_sha256=r.cron_expression and c.timezone=r.timezone
            and c.plist_sha256=r.definition_sha256)));
    if sibling_pre.id is null or sibling_post.id is null
       or sibling_pre.workflow_key<>p_workflow_key or sibling_post.workflow_key<>p_workflow_key
       or sibling_pre.workflow_version<>v or sibling_post.workflow_version<>v
       or sibling_pre.surface_id<>p_sibling_surface_id or sibling_post.surface_id<>p_sibling_surface_id
       or sibling_pre.locator<>p_sibling_locator or sibling_post.locator<>p_sibling_locator
       or sibling_pre.scheduler_state<>'enabled' or sibling_post.scheduler_state<>'disabled'
       or sibling_pre.observed_at<now()-interval '15 minutes'
       or sibling_post.observed_at<now()-interval '15 minutes'
       or sibling_pre.observed_at>now()+interval '5 minutes'
       or sibling_post.observed_at>now()+interval '5 minutes'
       or sibling_post.observed_at<sibling_pre.observed_at
       or sibling_pre.source_fingerprint=sibling_post.source_fingerprint then
      raise exception 'native duplicate scheduler evidence is not a current enabled-to-disabled readback';
    end if;
  end if;

  ref := 'legacy-disable:' || p_idempotency_key;
  update ops.job_definition set legacy_disabled_at=now(),legacy_disable_reason=p_reason,updated_at=now()
   where key=p_workflow_key and version=v and legacy_disabled_at is null;
  get diagnostics n=row_count;
  if n<>1 then raise exception 'legacy schedule was not disabled'; end if;
  insert into ops.legacy_schedule_disable_receipt
    (receipt_ref,idempotency_key,workflow_key,workflow_version,surface_id,locator,reason,
     approved_by,pre_observation_ref,post_observation_ref,sibling_observation_ref,
     sibling_surface_id,sibling_locator,sibling_pre_observation_ref,sibling_post_observation_ref)
  values
    (ref,p_idempotency_key,p_workflow_key,v,p_surface_id,p_locator,p_reason,'joe',
     p_pre_observation_ref,p_post_observation_ref,null,
     p_sibling_surface_id,p_sibling_locator,p_sibling_pre_observation_ref,p_sibling_post_observation_ref);
  return ref;
end $$;


--
-- Name: discover_ready_plan_amendments(bigint, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.discover_ready_plan_amendments(p_after_notice_id bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_slug text; v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
        v_items jsonb; v_next bigint; v_more boolean;
begin
  v_actor:=ops.portfolio_writer_actor_id();
  if p_after_notice_id is not null and p_after_notice_id<0 then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_discovery_cursor_invalid');
  end if;
  select slug into v_slug from public.actor where id=v_actor;
  select coalesce(jsonb_agg(item order by notice_id),'[]'::jsonb),max(notice_id) into v_items,v_next
    from (select n.id notice_id,jsonb_build_object('notice_id',n.id,'work_request_ref',w.ref,
      'prior_plan_ref',prior.plan_ref,'prior_plan_hash',prior.plan_hash,
      'successor_plan_ref',next.plan_ref,'successor_plan_hash',next.plan_hash,
      'accepted_at',a.accepted_at,'acknowledged_at',ack.acknowledged_at) item
      from ops.ready_plan_amendment_notice n
      join ops.ready_plan_amendment_acceptance_receipt a on a.id=n.acceptance_receipt_id
      join ops.work_request w on w.id=a.work_request_id
      join ops.sourced_work_request_plan prior on prior.id=a.predecessor_plan_id
      join ops.sourced_work_request_plan next on next.id=a.successor_plan_id
      left join ops.ready_plan_amendment_ack ack on ack.notice_id=n.id
      where n.actor_id=v_actor and n.id>coalesce(p_after_notice_id,0)
      order by n.id limit v_limit) page;
  select exists(select 1 from ops.ready_plan_amendment_notice n
    where n.actor_id=v_actor and n.id>coalesce(v_next,p_after_notice_id,0)) into v_more;
  return jsonb_build_object('ok',true,'actor',v_slug,'items',v_items,
    'next_after_notice_id',v_next,'has_more',v_more);
end $$;


--
-- Name: doc_conversation_facts(uuid, text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.doc_conversation_facts(p_conversation_id uuid, p_actor_id text, p_after_sequence integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_row ops.doc_conversation%rowtype; v_limit integer; v_after integer;
        v_turns jsonb; v_latest integer; v_more boolean; v_grants jsonb; v_visible integer;
begin
  begin
    v_actor := p_actor_id::uuid;
  exception when others then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_not_found');
  end;
  v_limit := least(greatest(coalesce(p_limit, 200), 1), 200);
  v_after := greatest(coalesce(p_after_sequence, 0), 0);

  select * into v_row from ops.doc_conversation where id = p_conversation_id;
  if v_row.id is null
     or not (v_row.created_by_actor = v_actor
             or exists (select 1 from ops.doc_conversation_grant g
                         where g.conversation_id = v_row.id and g.grantee_actor = v_actor
                           and g.revoked_at is null)) then
    -- One answer for absent and for not-permitted. A distinguishable refusal
    -- would itself disclose that a private conversation exists.
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_not_found');
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.sequence), '[]'::jsonb) into v_turns
    from (select sequence, role, body, msg_id, origin_channel, origin_actor, at
            from ops.doc_conversation_turn
           where conversation_id = v_row.id and sequence >= v_after
           order by sequence limit v_limit) t;
  select coalesce(max(sequence), -1) into v_latest
    from ops.doc_conversation_turn where conversation_id = v_row.id;
  v_more := exists (select 1 from ops.doc_conversation_turn
                     where conversation_id = v_row.id
                       and sequence >= v_after + jsonb_array_length(v_turns));
  select coalesce(jsonb_agg(to_jsonb(g) order by g.granted_at), '[]'::jsonb) into v_grants
    from (select grantee_actor, granted_at, granted_by_actor
            from ops.doc_conversation_grant
           where conversation_id = v_row.id and revoked_at is null) g;
  -- The count this actor is entitled to see, computed here and nowhere else.
  select count(*) into v_visible from ops.doc_conversation c
   where c.created_by_actor = v_actor
      or exists (select 1 from ops.doc_conversation_grant g
                  where g.conversation_id = c.id and g.grantee_actor = v_actor
                    and g.revoked_at is null);

  return jsonb_build_object('ok', true,
    'identity', jsonb_build_object('id', v_row.id, 'title', v_row.title,
      'visibility', v_row.visibility, 'pinned_at', v_row.pinned_at,
      'archived_at', v_row.archived_at, 'version', v_row.version,
      'created_by', v_row.created_by_actor),
    'turns', v_turns, 'latest_sequence', v_latest, 'more', v_more,
    'effective_grants', v_grants, 'visible_conversation_count', v_visible);
end $$;


--
-- Name: FUNCTION doc_conversation_facts(p_conversation_id uuid, p_actor_id text, p_after_sequence integer, p_limit integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.doc_conversation_facts(p_conversation_id uuid, p_actor_id text, p_after_sequence integer, p_limit integer) IS 'WR-000112: the only read door for the Doc conversation store. Enforces the access list itself and computes the visible-conversation count inside, so a non-member learns nothing from a count.';


--
-- Name: doc_conversation_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.doc_conversation_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin
  raise exception 'doc conversation turns and title revisions are immutable';
end $$;


--
-- Name: effective_ready_plan(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.effective_ready_plan(p_work_request text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_work ops.work_request%rowtype; v_plan ops.sourced_work_request_plan%rowtype;
begin
  select * into v_work from ops.work_request where ref=p_work_request
    and organization_tenant_id=current_setting('carr.organization_tenant_id',true);
  if not found then return jsonb_build_object('ok',false,'reason_id','work_request_not_found'); end if;
  select p.* into v_plan from ops.sourced_work_request_plan_acceptance_receipt ar
    join ops.sourced_work_request_plan p on p.id=ar.plan_id
   where ar.work_request_id=v_work.id and ar.result_version=v_work.version;
  if not found or ops.engineering_contract_stale(v_plan.plan_ref,v_plan.plan_hash,null) then
    return jsonb_build_object('ok',false,'reason_id','current_plan_stale_or_missing');
  end if;
  return jsonb_build_object('ok',true,
    'work_request',jsonb_build_object('id',v_work.id,'ref',v_work.ref,'state',v_work.state,'version',v_work.version),
    'current_plan',jsonb_build_object('id',v_plan.id,'ref',v_plan.plan_ref,'hash',v_plan.plan_hash,'version',v_plan.plan_version),
    'lineage',(select coalesce(jsonb_agg(jsonb_build_object(
      'plan_ref',p.plan_ref,'plan_hash',p.plan_hash,'plan_version',p.plan_version,
      'predecessor_plan_ref',prior.plan_ref,'accepted',ar.id is not null)
      order by p.plan_version),'[]'::jsonb)
      from ops.sourced_work_request_plan p
      left join ops.ready_plan_amendment a on a.plan_id=p.id
      left join ops.sourced_work_request_plan prior on prior.id=a.predecessor_plan_id
      left join ops.sourced_work_request_plan_acceptance_receipt ar on ar.plan_id=p.id
      where p.work_request_id=v_work.id));
end $$;


--
-- Name: work_request; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.work_request (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ref text NOT NULL,
    state text DEFAULT 'captured'::text NOT NULL,
    title text NOT NULL,
    desired_outcome text,
    acceptance_criteria jsonb DEFAULT '[]'::jsonb NOT NULL,
    origin_ref text,
    requester_actor text NOT NULL,
    owner_actor text,
    executor_actor text,
    blocker_code text,
    blocker_detail text,
    verification_accepted_at timestamp with time zone,
    verification_evidence_ref text,
    exit_reason text,
    superseded_by uuid,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    started_at timestamp with time zone,
    closed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    correlation_id uuid,
    program_key text,
    program_ordinal smallint,
    disposition text,
    existing_status text,
    project_context jsonb DEFAULT '{}'::jsonb NOT NULL,
    completion_kind text,
    completion_evidence jsonb,
    version integer DEFAULT 1 NOT NULL,
    shape_disposition text,
    shape_fixed_surface_ref text,
    shape_rationale text,
    shape_decided_by_actor_id uuid,
    shape_decided_at timestamp with time zone,
    organization_tenant_id text,
    doctrine_section_id uuid,
    doctrine_revision_id uuid,
    capture_idempotency_key uuid,
    sourced_capture_sequence bigint,
    triage_classification text,
    triaged_by_actor_id uuid,
    triaged_at timestamp with time zone,
    CONSTRAINT blocked_needs_a_named_blocker CHECK (((state <> 'blocked'::text) OR ((blocker_code IS NOT NULL) AND (blocker_detail IS NOT NULL)))),
    CONSTRAINT confirmed_close_needs_accepted_verification CHECK (((state <> 'confirmed_closed'::text) OR (verification_accepted_at IS NOT NULL))),
    CONSTRAINT side_exits_record_a_reason CHECK (((state <> ALL (ARRAY['declined'::text, 'superseded'::text, 'failed'::text])) OR (exit_reason IS NOT NULL))),
    CONSTRAINT superseded_names_its_successor CHECK (((state <> 'superseded'::text) OR (superseded_by IS NOT NULL))),
    CONSTRAINT terminal_rows_are_closed CHECK (((state = ANY (ARRAY['confirmed_closed'::text, 'declined'::text, 'superseded'::text])) = (closed_at IS NOT NULL))),
    CONSTRAINT work_request_program_close_has_bundle CHECK (((program_key IS NULL) OR (state <> 'confirmed_closed'::text) OR ((completion_kind IS NOT NULL) AND (completion_evidence IS NOT NULL)))),
    CONSTRAINT work_request_program_completion_kind CHECK (((completion_kind IS NULL) OR (completion_kind = ANY (ARRAY['built'::text, 'extended'::text, 'adopted'::text, 'declined'::text])))),
    CONSTRAINT work_request_program_disposition CHECK (((disposition IS NULL) OR (disposition = ANY (ARRAY['build'::text, 'extend'::text, 'adopt'::text, 'decline'::text])))),
    CONSTRAINT work_request_program_fields_travel_together CHECK (((program_key IS NULL) = (program_ordinal IS NULL))),
    CONSTRAINT work_request_program_ordinal_positive CHECK (((program_ordinal IS NULL) OR (program_ordinal > 0))),
    CONSTRAINT work_request_shape_disposition_complete CHECK ((((shape_disposition IS NULL) AND (shape_fixed_surface_ref IS NULL) AND (shape_rationale IS NULL) AND (shape_decided_by_actor_id IS NULL) AND (shape_decided_at IS NULL)) OR ((shape_disposition = 'required'::text) AND (shape_fixed_surface_ref IS NULL) AND (shape_rationale IS NOT NULL) AND (btrim(shape_rationale) <> ''::text) AND (shape_decided_by_actor_id IS NOT NULL) AND (shape_decided_at IS NOT NULL)) OR ((shape_disposition = 'not_required'::text) AND (shape_fixed_surface_ref IS NOT NULL) AND (btrim(shape_fixed_surface_ref) <> ''::text) AND (shape_rationale IS NOT NULL) AND (btrim(shape_rationale) <> ''::text) AND (shape_decided_by_actor_id IS NOT NULL) AND (shape_decided_at IS NOT NULL)))),
    CONSTRAINT work_request_shape_disposition_valid CHECK (((shape_disposition IS NULL) OR (shape_disposition = ANY (ARRAY['required'::text, 'not_required'::text])))),
    CONSTRAINT work_request_sourced_capture_shape CHECK ((((capture_idempotency_key IS NULL) AND (organization_tenant_id IS NULL) AND (doctrine_section_id IS NULL) AND (doctrine_revision_id IS NULL) AND (sourced_capture_sequence IS NULL) AND (triage_classification IS NULL) AND (triaged_by_actor_id IS NULL) AND (triaged_at IS NULL) AND (program_key IS NULL) AND (program_ordinal IS NULL)) OR ((capture_idempotency_key IS NULL) AND (NOT (organization_tenant_id IS DISTINCT FROM 'carr-internal'::text)) AND (doctrine_section_id IS NULL) AND (doctrine_revision_id IS NULL) AND (sourced_capture_sequence IS NULL) AND (triage_classification IS NULL) AND (triaged_by_actor_id IS NULL) AND (triaged_at IS NULL) AND (program_key = ANY (ARRAY['carr-ai-engineering-suite-v1'::text, 'carr-system-integrity-elimination-v1'::text])) AND (program_ordinal IS NOT NULL) AND (program_ordinal > 0) AND (NOT (requester_actor IS DISTINCT FROM 'joe'::text)) AND (NOT (owner_actor IS DISTINCT FROM 'joe'::text))) OR ((capture_idempotency_key IS NOT NULL) AND (NOT (organization_tenant_id IS DISTINCT FROM 'carr-internal'::text)) AND (doctrine_section_id IS NOT NULL) AND (doctrine_revision_id IS NOT NULL) AND (sourced_capture_sequence IS NOT NULL) AND (program_key IS NULL) AND (program_ordinal IS NULL) AND (origin_ref IS NOT NULL) AND (origin_ref ~ '^doctrine:[a-z0-9][a-z0-9-]*#[a-z0-9][a-z0-9-]*$'::text) AND (((state = 'captured'::text) AND (triage_classification IS NULL) AND (triaged_by_actor_id IS NULL) AND (triaged_at IS NULL)) OR ((state = ANY (ARRAY['triaged'::text, 'ready'::text])) AND (triage_classification = ANY (ARRAY['operational'::text, 'needs_judgment'::text, 'safety_review'::text])) AND (triaged_by_actor_id IS NOT NULL) AND (triaged_at IS NOT NULL)) OR ((state = ANY (ARRAY['declined'::text, 'superseded'::text])) AND (triage_classification IS NULL) AND (triaged_by_actor_id IS NULL) AND (triaged_at IS NULL) AND (exit_reason IS NOT NULL) AND (btrim(exit_reason) <> ''::text) AND (closed_at IS NOT NULL) AND (((state = 'declined'::text) AND (superseded_by IS NULL)) OR ((state = 'superseded'::text) AND (superseded_by IS NOT NULL)))))))),
    CONSTRAINT work_request_state_check CHECK ((state = ANY (ARRAY['captured'::text, 'triaged'::text, 'ready'::text, 'claimed'::text, 'in_progress'::text, 'verification'::text, 'awaiting_release'::text, 'released'::text, 'confirmed_closed'::text, 'needs_joe'::text, 'blocked'::text, 'declined'::text, 'superseded'::text, 'failed'::text])))
);


--
-- Name: TABLE work_request; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.work_request IS 'The canonical Work Request. States come from control-room/contracts/state-machines.v1.json; the Workspace projection is defined by control-room/contracts/work-request-projection.v1.json and is derived, never stored. TRANSITIONS ARE SERVER-ENFORCED, not enforced here: doctrine requires it and the guards need evidence a CHECK cannot see. This table guarantees only that a row is never in an undefined state and never violates an invariant the machine declares about states.';


--
-- Name: COLUMN work_request.correlation_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.correlation_id IS 'Nullable on purpose: rows predate correlation, and a work request captured by hand has no journey behind it. Present when the request came out of a traced failure.';


--
-- Name: COLUMN work_request.project_context; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.project_context IS 'Session-complete context for one governed portfolio item: scope, non-goals, prerequisites, first deliverable, acceptance, rollback, data risk, effort, evidence and completion meaning. Operational metadata only; never client payload or secrets.';


--
-- Name: COLUMN work_request.shape_disposition; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.shape_disposition IS 'Mandatory before a request enters implementation: required runs the evidence-backed shape method; not_required cites the already-fixed implementation surface. Null is permitted while work is captured or triaged and on pre-0130 ready rows, which the implementation-entry gate still refuses until classified.';


--
-- Name: COLUMN work_request.organization_tenant_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.organization_tenant_id IS 'Server-derived CARR tenant for sourced Program 6 plus the exact fixed AI and SIEP programs. Other historical rows remain null.';


--
-- Name: COLUMN work_request.doctrine_revision_id; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.work_request.doctrine_revision_id IS 'Exact current doctrine revision that grounded a sourced capture; a stale or invented revision is refused.';


--
-- Name: effective_sourced_work_request_shape_disposition(ops.work_request); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.effective_sourced_work_request_shape_disposition(p_work_request ops.work_request) RETURNS TABLE(work_request_id uuid, original_receipt_id uuid, correction_receipt_id uuid, receipt_kind text, disposition text, fixed_surface_ref text, rationale text, decided_by_actor_id uuid, decided_at timestamp with time zone, base_version integer, result_version integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  e record;
begin
  if p_work_request.id is null or p_work_request.capture_idempotency_key is null then return; end if;
  select l.* into e from ops.sourced_work_request_shape_disposition_lineage(p_work_request.id) l;
  if not found then return; end if;
  if e.result_version is distinct from p_work_request.version
     or (p_work_request.shape_disposition, p_work_request.shape_fixed_surface_ref, p_work_request.shape_rationale,
         p_work_request.shape_decided_by_actor_id, p_work_request.shape_decided_at)
        is distinct from (e.disposition, e.fixed_surface_ref, e.rationale, e.decided_by_actor_id, e.decided_at) then
    return;
  end if;
  return query select e.work_request_id, e.original_receipt_id, e.correction_receipt_id, e.receipt_kind,
    e.disposition, e.fixed_surface_ref, e.rationale, e.decided_by_actor_id, e.decided_at,
    e.base_version, e.result_version;
end;
$$;


--
-- Name: end_meeting(uuid, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.end_meeting(p_meeting uuid, p_client_instance text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype;
begin
  select * into v_who from ops.meeting_mode_actor();
  if not coalesce(v_who.is_partner, false) then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_end_requires_verified_partner');
  end if;
  select * into v_row from ops.meeting
   where id = p_meeting and organization_tenant_id = v_who.tenant for update;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  if v_row.mode_state = 'ended' then
    return jsonb_build_object('ok', true, 'already', true, 'meeting_id', p_meeting,
      'ended_at', v_row.ended_at);
  end if;
  update ops.meeting set mode_state = 'ended', ended_at = clock_timestamp(),
         ended_by_actor = v_who.actor_id
   where id = p_meeting;
  update ops.meeting_processing_lease set released_at = clock_timestamp()
   where meeting_id = p_meeting and released_at is null;
  perform ops.meeting_mode_append(p_meeting, 'meeting_ended', v_who.actor_id, p_client_instance,
    null, null, null, null, p_idempotency_key);
  return jsonb_build_object('ok', true, 'already', false, 'meeting_id', p_meeting,
    'ended_at', (select ended_at from ops.meeting where id = p_meeting));
end $$;


--
-- Name: enforce_completion_capsule(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_completion_capsule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  cap         record;
  implementer text;
  n_predicates int;
  declining   boolean;
begin
  if new.state <> 'confirmed_closed' then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.state = 'confirmed_closed' then
    return new;
  end if;

  if new.completion_evidence is null
     or jsonb_typeof(new.completion_evidence) <> 'object' then
    raise exception
      'closing %: done needs an evidence capsule, and completion_evidence is not an object.',
      new.ref using errcode = 'check_violation';
  end if;

  select * into cap from ops.completion_capsule(new.completion_evidence);

  -- KEYED ON THE DECLARED KIND, never on the capsule looking thin. If a missing
  -- change reference were itself the signal, "I have no change reference" would
  -- become the way to buy the cheaper close.
  declining := (new.completion_kind = 'declined');

  if declining then
    -- A DECLINE HAS NO CHANGE, NO ACCEPTANCE TESTS AND NO JOURNEY. What it has
    -- is a decision, and someone other than the implementer who checked it.
    if coalesce(btrim(cap.decision_ref),'') = '' then
      raise exception
        'closing %: a decline needs the DECISION that made it. Nothing else here is '
        'evidence — there is no change to point at and no test that passed.',
        new.ref using errcode = 'check_violation';
    end if;
  else
    select count(*) into n_predicates
      from jsonb_array_elements_text(coalesce(cap.acceptance_predicates,'[]'::jsonb)) p
     where btrim(p) <> '';
    if n_predicates = 0 then
      raise exception
        'closing %: the evidence capsule states no acceptance predicates. What would have '
        'made this done had to be sayable before it was done.', new.ref
        using errcode = 'check_violation';
    end if;

    if coalesce(btrim(cap.change_ref),'') = '' then
      raise exception
        'closing %: the evidence capsule names no change reference, so nothing ties this '
        'closure to what actually shipped.', new.ref
        using errcode = 'check_violation';
    end if;

    if cap.user_facing is null then
      raise exception
        'closing %: the evidence capsule does not say whether this is user-facing. Say so '
        'explicitly — silence here is how a capability gets reported live before a human '
        'has used it.', new.ref
        using errcode = 'check_violation';
    end if;

    if cap.user_facing and coalesce(btrim(cap.user_journey_ref),'') = '' then
      raise exception
        'closing %: this is declared user-facing, so the capsule must name an EXERCISED user '
        'journey. A user-facing thing nobody has used is not done.', new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  -- IDENTICAL FOR BOTH KINDS, and that is the point. A decline waved through on
  -- the implementer's own say-so is exactly as unaccountable as a self-attested
  -- build. The uuid-or-slug resolution stays too: every capability-lane
  -- attestation records a uuid, so a slug-only comparison would pass every
  -- self-attestation ever made.
  if coalesce(btrim(cap.attestor),'') = '' then
    raise exception
      'closing %: no attestor. Done requires somebody who did not build it saying it is done.',
      new.ref using errcode = 'check_violation';
  end if;

  implementer := coalesce(new.executor_actor, new.owner_actor);
  if implementer is not null then
    if lower(btrim(cap.attestor)) = lower(btrim(implementer))
       or exists (select 1 from actor a
                   where a.id::text = cap.attestor
                     and lower(a.slug) = lower(btrim(implementer))) then
      raise exception
        'closing %: % attested their own work. The whole point of an independent attestor '
        'is that it is somebody else.', new.ref, implementer
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;


--
-- Name: FUNCTION enforce_completion_capsule(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.enforce_completion_capsule() IS 'Tune-up council 2026-08-21: a Work Request cannot reach confirmed_closed on a timestamp alone. Fires on the TRANSITION into confirmed_closed. A BUILT closure pays acceptance predicates, a change reference, an explicit user-facing boolean and a journey where that is true; a DECLINED closure pays the decision that made it, because there is no change and no test (0281). The independent-attestor test is identical for both.';


--
-- Name: enforce_work_in_progress_limit(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_work_in_progress_limit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  system_wide     int;
  per_executor    int;
  who             text;
  who_before      text;
  already_in_flight boolean;
  limit_system    constant int := 2;
  limit_each      constant int := 1;
begin
  if new.state not in ('claimed','in_progress') then
    return new;
  end if;

  already_in_flight := (tg_op = 'UPDATE' and old.state in ('claimed','in_progress'));

  -- SYSTEM-WIDE: entry only. A row already in flight is already counted, and
  -- re-checking here would make a full queue uneditable.
  if not already_in_flight then
    select count(*) into system_wide
      from ops.work_request
     where state in ('claimed','in_progress')
       and id <> new.id;

    if system_wide + 1 > limit_system then
      raise exception
        'work-in-progress limit: % already in flight system-wide and the limit is %. '
        'Move something to blocked, verification or confirmed_closed before claiming %.',
        system_wide, limit_system, new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  who := coalesce(new.executor_actor, new.owner_actor);

  -- PER-EXECUTOR: on entry, and on any reassignment of a row already in flight.
  -- Reassignment does not move the system-wide total but it does move this one.
  if already_in_flight then
    who_before := coalesce(old.executor_actor, old.owner_actor);
    if who_before is not distinct from who then
      return new;
    end if;
  end if;

  if who is not null then
    select count(*) into per_executor
      from ops.work_request
     where state in ('claimed','in_progress')
       and coalesce(executor_actor, owner_actor) = who
       and id <> new.id;

    if per_executor + 1 > limit_each then
      raise exception
        'work-in-progress limit: % already has % in flight and the limit per executor is %. '
        'One thing at a time is the point; finish or park it before claiming %.',
        who, per_executor, limit_each, new.ref
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;


--
-- Name: FUNCTION enforce_work_in_progress_limit(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.enforce_work_in_progress_limit() IS 'Tune-up council 2026-08-21: work-in-progress limit of 2 system-wide and 1 per executor, enforced at the row transition because the claim path has more than one route. Counts claimed and in_progress only; held-but-not-active states are deliberately excluded so a blocked row cannot freeze the queue. The system-wide check runs on entry into flight only; the per-executor check ALSO runs when a row already in flight changes hands, because reassignment moves that count without moving the total (0277).';


--
-- Name: engineering_admission_source(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_admission_source(p_work_request text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
    'work_request',jsonb_build_object(
      'id','wr:'||w.id::text,'ref',w.ref,'state',w.state,'version',w.version,
      'title',w.title,'desired_outcome',w.desired_outcome,
      'acceptance_criteria',w.acceptance_criteria,
      'canonical_record_digest','sha256:'||encode(public.digest(
        jsonb_build_object('id',w.id,'ref',w.ref,'state',w.state,'version',w.version,
          'title',w.title,'desired_outcome',w.desired_outcome,
          'acceptance_criteria',w.acceptance_criteria)::text,'sha256'),'hex')),
    'accepted_plan',jsonb_build_object(
      'id',p.plan_ref,'record_id',p.id,'plan_ref',p.plan_ref,
      'revision',p.plan_version,'digest',p.plan_hash,
      'work_request_version',p.work_request_version,'preimage',p.preimage,
      'scope_summary',p.scope_summary,'dependency_refs',p.dependency_refs,
      'recovery_ref',p.recovery_ref,'observability_ref',p.observability_ref,
      'caps',p.caps,'accepted_at',ar.accepted_at,
      'accepted_by_actor_id',ar.accepted_by_actor_id),
    'execution_authorized',not ops.engineering_contract_stale(p.plan_ref,p.plan_hash,null),
    'execution_refusal_reason',case when ops.engineering_contract_stale(p.plan_ref,p.plan_hash,null)
      then (select f.reason from ops.engineering_stale_contract_fence f where f.plan_ref=p.plan_ref)
      else null end)
    from ops.work_request w
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.result_version=w.version
    join ops.sourced_work_request_plan p
      on p.id=ar.plan_id and p.work_request_id=w.id and p.plan_hash=ar.plan_hash
   where w.ref=p_work_request and w.state='ready';
$$;


--
-- Name: engineering_claim_slice(text, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_claim_slice(p_worker text, p_limit integer DEFAULT 1, p_lease_seconds integer DEFAULT 960) RETURNS TABLE(job_id uuid, lease_token uuid, definition_key text, definition_version integer, payload jsonb, execution_kind text, execution_contract jsonb, attempt integer, timeout_seconds integer, mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_job_id uuid; v_envelope_id uuid; v_slice_plan_id uuid; v_slice_ref text;
        v_work_request_id uuid; v_executor_actor_id uuid;
        v_currentness jsonb; v_claim_at timestamptz; v_runway_sufficient boolean;
begin
  if btrim(coalesce(p_worker,''))='' or p_limit is distinct from 1 then raise exception 'worker and exactly one claim are required'; end if;
  if p_lease_seconds is distinct from 960 then raise exception 'engineering controller lease must be 960 seconds'; end if;
  -- Identifier lookup is deliberately unlocked.  Every authority predicate is
  -- re-read only after the global session-first lock order below.
  select j.id,e.id,e.slice_plan_id,e.slice_ref,e.work_request_id
    into v_job_id,v_envelope_id,v_slice_plan_id,v_slice_ref,v_work_request_id
    from ops.job j
    join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version
    join ops.engineering_execution_envelope e on e.job_id=j.id
   where d.enabled and j.definition_key='engineering-slice' and j.definition_version=1
     and j.state in ('queued','retry_wait') and j.next_attempt_at<=now()
     and j.attempt<j.max_attempts
     and ops.engineering_envelope_is_executable(e.id,j.id)
     and coalesce((ops.engineering_envelope_currentness(e.id,j.id)
                    ->>'dispatch_runway_sufficient')::boolean,false)
   order by j.scheduled_for,j.created_at limit 1;
  if not found then return; end if;
  select s.executor_actor_id into v_executor_actor_id
    from ops.capability_agent_session s
    join ops.engineering_execution_envelope e on e.agent_session_id=s.id
   where e.id=v_envelope_id and e.job_id=v_job_id for share of s;
  if not found then return; end if;
  perform 1 from public.actor a
   where a.id=v_executor_actor_id and a.active and a.kind='automation' and a.slug='codex'
   order by a.id for share;
  if not found then return; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-envelope:'||v_slice_plan_id::text||':'||v_slice_ref,0));
  perform 1 from ops.engineering_execution_envelope e
    join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id
   where e.id=v_envelope_id and e.job_id=v_job_id
   for key share of e,sp;
  if not found then return; end if;
  perform 1 from ops.work_request where id=v_work_request_id for share;
  if not found then return; end if;
  perform 1 from ops.job_definition d
   where d.key='engineering-slice' and d.version=1 for share;
  if not found then return; end if;
  perform 1 from ops.job j
   where j.id=v_job_id for update;
  if not found then return; end if;
  v_claim_at:=clock_timestamp();
  perform 1 from ops.job j
    join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version
   where j.id=v_job_id and d.enabled and j.definition_key='engineering-slice'
     and j.definition_version=1 and j.state in ('queued','retry_wait')
     and j.next_attempt_at<=v_claim_at and j.attempt<j.max_attempts;
  if not found then return; end if;
  v_currentness:=ops.engineering_envelope_currentness(v_envelope_id,v_job_id);
  select e.expires_at>=v_claim_at+make_interval(secs=>p_lease_seconds)
         and s.lease_expires_at is not null
         and s.lease_expires_at>=v_claim_at+make_interval(secs=>p_lease_seconds)
    into v_runway_sufficient
    from ops.engineering_execution_envelope e
    join ops.capability_agent_session s on s.id=e.agent_session_id
   where e.id=v_envelope_id and e.job_id=v_job_id;
  if coalesce((v_currentness->>'eligible')::boolean,false) is not true
     or coalesce(v_runway_sufficient,false) is not true then return; end if;
  return query with claimed as (
    update ops.job j set state='running',attempt=j.attempt+1,lease_owner=p_worker,
      lease_token=gen_random_uuid(),leased_until=v_claim_at+make_interval(secs=>p_lease_seconds),
      started_at=coalesce(j.started_at,v_claim_at),updated_at=v_claim_at
    where j.id=v_job_id and j.state in ('queued','retry_wait')
    returning j.*
  ), attempts as (
    insert into ops.job_attempt as claimed_attempt(job_id,attempt,lease_owner,lease_token,state)
    select c.id,c.attempt,c.lease_owner,c.lease_token,'running' from claimed c returning claimed_attempt.job_id
  ) select c.id,c.lease_token,c.definition_key,c.definition_version,c.payload,d.execution_kind,d.execution_contract,c.attempt,c.timeout_seconds,c.mode from claimed c join ops.job_definition d on d.key=c.definition_key and d.version=c.definition_version join attempts a on a.job_id=c.id;
end $$;


--
-- Name: engineering_contract_stale(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_contract_stale(p_plan_ref text, p_plan_hash text, p_migration_filename text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select exists (
    select 1 from ops.engineering_stale_contract_fence f
     where (p_plan_ref is not null and f.plan_ref=p_plan_ref)
        or (p_plan_hash is not null and f.plan_hash=p_plan_hash)
        or (p_migration_filename is not null and p_migration_filename=any(f.migration_filenames))
  );
$$;


--
-- Name: engineering_controller_binding(uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_controller_binding(p_envelope_id uuid, p_job_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare binding jsonb; lineage_plan uuid; lineage_slice text; lineage_work_request uuid;
        v_executor_actor_id uuid; v_binding_at timestamptz;
begin
  if p_lease_token is null then return null; end if;
  -- Unlocked identifiers first; all mutable authority is re-read after locks.
  select e.slice_plan_id,e.slice_ref,e.work_request_id,e.agent_session_id
    into lineage_plan,lineage_slice,lineage_work_request,v_executor_actor_id
    from ops.engineering_execution_envelope e
   where e.id=p_envelope_id and e.job_id=p_job_id;
  if not found then return null; end if;
  select s.executor_actor_id into v_executor_actor_id
    from ops.capability_agent_session s
    join ops.engineering_execution_envelope e on e.agent_session_id=s.id
   where e.id=p_envelope_id and e.job_id=p_job_id for share of s;
  if not found then return null; end if;
  perform 1 from public.actor a
   where a.id=v_executor_actor_id and a.active and a.kind='automation' and a.slug='codex'
   order by a.id for share;
  if not found then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-envelope:'||lineage_plan::text||':'||lineage_slice,0));
  perform 1 from ops.engineering_execution_envelope e
    join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id
   where e.id=p_envelope_id and e.job_id=p_job_id for key share of e,sp;
  if not found then return null; end if;
  perform 1 from ops.work_request where id=lineage_work_request for share;
  if not found then return null; end if;
  perform 1 from ops.job_definition d
   where d.key='engineering-slice' and d.version=1 and d.enabled for share;
  if not found then return null; end if;
  perform 1 from ops.job where id=p_job_id for share;
  if not found then return null; end if;
  v_binding_at:=clock_timestamp();
  if not ops.engineering_envelope_is_executable(p_envelope_id,p_job_id) then return null; end if;
  select jsonb_build_object(
    'envelope_id',e.id::text,'envelope_digest',e.envelope_digest,
    'slice_ref',e.slice_ref,'plan_digest',sp.plan_digest,'slice_plan',sp.plan,
    'executor_actor',jsonb_build_object('id',a.id::text,'slug',a.slug),
    'agent_session_id',s.id::text,
    'agent_session_lease_expires_at',to_char(s.lease_expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'job_lease_expires_at',to_char(j.leased_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
  ) into binding
    from ops.engineering_execution_envelope e
    join ops.job j on j.id=e.job_id
    join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version
    join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id
    join ops.capability_agent_session s on s.id=e.agent_session_id
    join public.actor a on a.id=s.executor_actor_id
   where e.id=p_envelope_id and e.job_id=p_job_id
     and a.active and a.kind='automation' and a.slug='codex'
     and d.enabled and d.key='engineering-slice' and d.version=1
     and j.state='running' and j.lease_token=p_lease_token
     and j.leased_until>=v_binding_at+interval '930 seconds';
  return binding;
end $$;


--
-- Name: engineering_enqueue_slice_job(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_enqueue_slice_job(p_work_request text, p_slice_ref text, p_plan_digest text, p_idempotency_key text) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare row ops.job%rowtype;
        facts jsonb;
        job_key text;
begin
  if btrim(p_work_request) = '' or btrim(p_slice_ref) = ''
     or p_plan_digest !~ '^sha256:[0-9a-f]{64}$' or btrim(p_idempotency_key) = '' then
    raise exception 'engineering job admission fields are invalid';
  end if;
  job_key := 'engineering-slice:' || p_plan_digest || ':' || p_work_request || ':' || p_slice_ref;
  perform pg_advisory_xact_lock(hashtextextended('engineering-slice:' || p_plan_digest || ':' || p_slice_ref, 0));
  facts := ops.engineering_passport_facts(p_work_request);
  if not exists (
    select 1
      from jsonb_array_elements(coalesce(facts->'slice_plans','[]'::jsonb)) sp,
           jsonb_array_elements(coalesce(sp->'plan'->'slices','[]'::jsonb)) s
     where sp->>'plan_digest' = p_plan_digest
       and s->>'slice_ref' = p_slice_ref
  ) then
    raise exception 'engineering slice is not registered for the exact plan';
  end if;
  if exists (
    select 1
      from jsonb_array_elements(coalesce(facts->'slice_plans','[]'::jsonb)) sp,
           jsonb_array_elements(coalesce(sp->'plan'->'slices','[]'::jsonb)) s,
           jsonb_array_elements_text(coalesce(s->'dependency_refs','[]'::jsonb)) dep
     where s->>'slice_ref' = p_slice_ref
       and not exists (
         select 1
           from jsonb_array_elements(coalesce(facts->'receipts','[]'::jsonb)) r,
                jsonb_array_elements(coalesce(facts->'reviewer_facts','[]'::jsonb)) v
          where r->>'slice_ref' = dep
            and r->>'outcome' = 'claimed_complete'
            and v->>'slice_ref' = dep
            and v->'fact'->>'attempt_id' = r->>'attempt_id'
            and v->>'state' = 'passed'
       )
  ) then
    raise exception 'engineering slice dependencies are not independently verified';
  end if;
  select * into row from ops.job where idempotency_key=job_key;
  if row.id is not null then return row; end if;
  select * into row from ops.enqueue_job(
    'engineering-slice', 1, now(),
    jsonb_build_object('work_request',p_work_request,'slice_ref',p_slice_ref,'plan_digest',p_plan_digest),
    job_key, 'shadow');
  return row;
end $_$;


--
-- Name: engineering_enqueue_slice_job(text, text, text, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_enqueue_slice_job(p_work_request text, p_slice_ref text, p_plan_digest text, p_idempotency_key text, p_generation integer) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare row ops.job%rowtype;
        slice_plan ops.engineering_slice_plan%rowtype;
        dependency_ref text;
        job_key text;
        current_source jsonb;
begin
  if btrim(coalesce(p_work_request,''))='' or btrim(coalesce(p_slice_ref,''))=''
     or p_plan_digest is null or p_plan_digest !~ '^sha256:[0-9a-f]{64}$'
     or btrim(coalesce(p_idempotency_key,''))='' or p_generation is null or p_generation<1 then
    raise exception 'engineering job admission fields are invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-slice:'||p_plan_digest||':'||p_slice_ref,0));
  current_source:=ops.engineering_admission_source(p_work_request);
  if current_source is null then
    raise exception 'engineering job admission source is not current';
  end if;
  select sp.* into slice_plan
    from ops.engineering_slice_plan sp
   where sp.plan_digest=p_plan_digest
     and sp.work_request_id=regexp_replace(current_source->'work_request'->>'id','^wr:','')::uuid
     and sp.accepted_plan_id=(current_source->'accepted_plan'->>'record_id')::uuid
     and sp.accepted_plan_hash=current_source->'accepted_plan'->>'digest'
     and sp.work_request_version=(current_source->'work_request'->>'version')::integer
     and sp.plan->'work_request'->>'canonical_record_digest'=
         current_source->'work_request'->>'canonical_record_digest'
     and sp.plan->'accepted_plan_revision'->>'id'=
         current_source->'accepted_plan'->>'plan_ref'
     and sp.plan->'accepted_plan_revision'->>'digest'=
         current_source->'accepted_plan'->>'digest'
     and exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(sp.plan->'slices')='array'
                                        then sp.plan->'slices' else '[]'::jsonb end) slice_item
        where slice_item->>'slice_ref'=p_slice_ref
     )
   for key share;
  if not found then
    raise exception 'engineering slice is not registered for the exact current plan';
  end if;
  perform 1 from ops.work_request w
   where w.id=slice_plan.work_request_id and w.ref=p_work_request for share;
  if not found or ops.engineering_admission_source(p_work_request) is distinct from current_source then
    raise exception 'engineering job admission source changed during serialization';
  end if;

  for dependency_ref in
    select dependency#>>'{}'
      from jsonb_array_elements(
        coalesce((select slice_item->'dependency_refs'
                    from jsonb_array_elements(slice_plan.plan->'slices') slice_item
                   where slice_item->>'slice_ref'=p_slice_ref),'[]'::jsonb)) dependency
     order by dependency#>>'{}'
  loop
    perform pg_advisory_xact_lock(hashtextextended(
      'engineering-envelope:'||slice_plan.id::text||':'||dependency_ref,0));
  end loop;

  if exists (
    select 1
      from jsonb_array_elements(slice_plan.plan->'slices') slice_item,
           jsonb_array_elements_text(coalesce(slice_item->'dependency_refs','[]'::jsonb)) dependency
     where slice_item->>'slice_ref'=p_slice_ref
       and not exists (
         select 1
           from ops.engineering_slice_receipt receipt
           join ops.engineering_execution_envelope envelope
             on envelope.id=receipt.envelope_id
            and envelope.slice_plan_id=slice_plan.id
            and envelope.work_request_id=slice_plan.work_request_id
            and envelope.slice_ref=dependency
           join ops.capability_agent_session executor_session
             on executor_session.id=envelope.agent_session_id
            and executor_session.executor_actor_id=receipt.executor_actor_id
           join public.actor executor_actor
             on executor_actor.id=receipt.executor_actor_id
            and executor_actor.active
           join ops.engineering_reviewer_fact review
             on review.receipt_id=receipt.id
            and review.work_request_id=receipt.work_request_id
            and review.slice_ref=receipt.slice_ref
           join public.actor reviewer_actor
             on reviewer_actor.id=review.reviewer_actor_id
            and reviewer_actor.active
          where receipt.work_request_id=slice_plan.work_request_id
            and receipt.slice_ref=dependency
            and receipt.outcome='claimed_complete'
            and receipt.receipt->>'outcome'='claimed_complete'
            and coalesce(ops.engineering_receipt_exact_object(receipt.receipt,array[
                  'actual_component_refs','actual_resource_refs','artifact_refs','attribution','attempt_id','checks',
                  'deviations','envelope_digest','evidence_refs','executor_claim','independent_verification_required',
                  'outcome','plan_digest','planned_component_refs','planned_resource_refs','reset_reconstruction',
                  'schema_version','slice_ref','source_evidence'
                ]),false)
            and receipt.receipt->>'schema_version'='engineering-slice-receipt.v1'
            and receipt.receipt_digest=
                ('sha256:'||encode(public.digest(ops.guidance_import_canonical_json(receipt.receipt),'sha256'),'hex'))
            and receipt.receipt->>'plan_digest'=slice_plan.plan_digest
            and receipt.receipt->>'slice_ref'=receipt.slice_ref
            and receipt.receipt->>'attempt_id'=receipt.attempt_id
            and receipt.receipt->>'envelope_digest'=envelope.envelope_digest
            and envelope.envelope->>'envelope_id'='env:'||envelope.id::text
            and envelope.envelope#>>'{request,job_ref}'='job:'||envelope.job_id::text
            and envelope.envelope#>>'{agent_session,id}'='session:'||executor_session.id::text
            and receipt.receipt->'independent_verification_required'='true'::jsonb
            and coalesce(ops.engineering_receipt_exact_object(receipt.receipt->'attribution',array[
                  'actor_ref','adapter_ref','session_ref'
                ]),false)
            and receipt.receipt#>>'{attribution,actor_ref}'=
                envelope.envelope#>>'{server_binding,identity,agent_principal_id}'
            and receipt.receipt#>>'{attribution,session_ref}'=
                envelope.envelope#>>'{agent_session,id}'
            and receipt.receipt#>>'{attribution,adapter_ref}'=
                envelope.envelope#>>'{server_binding,adapter,adapter_id}'
            and jsonb_typeof(receipt.receipt->'deviations')='array'
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'deviations')='array'
                                               then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
               where not coalesce(ops.engineering_receipt_exact_object(deviation,array[
                       'category','deviation_ref','evidence_refs','impact','out_of_scope_component_refs',
                       'out_of_scope_resource_refs','plan_revision_required','reason','review_state'
                     ]),false)
                  or not coalesce((deviation->>'deviation_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
                  or exists (
                    select 1 from unnest(array['category','reason','impact']) field
                     where jsonb_typeof(deviation->field) is distinct from 'string'
                        or not coalesce(btrim(deviation->>field)<>'',false)
                  )
                  or jsonb_typeof(deviation->'plan_revision_required') is distinct from 'boolean'
                  or not coalesce(ops.engineering_receipt_evidence_array(deviation->'evidence_refs'),false)
                  or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_resource_refs'),false)
                  or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_component_refs'),false)
                  or not coalesce(deviation->>'review_state'=any(array['unreviewed','reviewed','resolved']),false)
            )
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'deviations')='array'
                                               then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
               group by deviation->>'deviation_ref'
              having count(*)>1
            )
            and coalesce(ops.engineering_receipt_identifier_array(receipt.receipt->'planned_resource_refs'),false)
            and coalesce(ops.engineering_receipt_identifier_array(receipt.receipt->'actual_resource_refs'),false)
            and coalesce(ops.engineering_receipt_identifier_array(receipt.receipt->'planned_component_refs'),false)
            and coalesce(ops.engineering_receipt_identifier_array(receipt.receipt->'actual_component_refs'),false)
            and coalesce(ops.engineering_receipt_identifier_sets_equal(
                  receipt.receipt->'planned_resource_refs',(
                    select dependency_slice->'declared_resource_refs'
                      from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice
                     where dependency_slice->>'slice_ref'=receipt.slice_ref
                  )),false)
            and coalesce(ops.engineering_receipt_identifier_sets_equal(
                  receipt.receipt->'planned_component_refs',(
                    select dependency_slice->'declared_component_refs'
                      from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice
                     where dependency_slice->>'slice_ref'=receipt.slice_ref
                  )),false)
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'actual_resource_refs')='array'
                                               then receipt.receipt->'actual_resource_refs' else '[]'::jsonb end) actual_ref
               where not exists (
                 select 1
                   from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice,
                        jsonb_array_elements(dependency_slice->'declared_resource_refs') declared_ref
                  where dependency_slice->>'slice_ref'=receipt.slice_ref and declared_ref=actual_ref
               ) and not exists (
                 select 1
                   from jsonb_array_elements(receipt.receipt->'deviations') deviation,
                        jsonb_array_elements(deviation->'out_of_scope_resource_refs') approved_ref
                  where deviation->>'review_state'='resolved' and approved_ref=actual_ref
               )
            )
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'actual_component_refs')='array'
                                               then receipt.receipt->'actual_component_refs' else '[]'::jsonb end) actual_ref
               where not exists (
                 select 1
                   from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice,
                        jsonb_array_elements(dependency_slice->'declared_component_refs') declared_ref
                  where dependency_slice->>'slice_ref'=receipt.slice_ref and declared_ref=actual_ref
               ) and not exists (
                 select 1
                   from jsonb_array_elements(receipt.receipt->'deviations') deviation,
                        jsonb_array_elements(deviation->'out_of_scope_component_refs') approved_ref
                  where deviation->>'review_state'='resolved' and approved_ref=actual_ref
               )
            )
            and coalesce(ops.engineering_receipt_identifier_array(receipt.receipt->'artifact_refs'),false)
            and coalesce(case when jsonb_typeof(receipt.receipt->'artifact_refs')='array'
                              then jsonb_array_length(receipt.receipt->'artifact_refs')>0 else false end,false)
            and coalesce(ops.engineering_receipt_evidence_array(receipt.receipt->'evidence_refs'),false)
            and coalesce(case when jsonb_typeof(receipt.receipt->'evidence_refs')='array'
                              then jsonb_array_length(receipt.receipt->'evidence_refs')>0 else false end,false)
            and jsonb_typeof(receipt.receipt->'checks')='array'
            and coalesce(case when jsonb_typeof(receipt.receipt->'checks')='array'
                              then jsonb_array_length(receipt.receipt->'checks')>0 else false end,false)
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'checks')='array'
                                               then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
               where not coalesce(ops.engineering_receipt_exact_object(receipt_check,array[
                       'check_ref','evidence_refs','state'
                     ]),false)
                  or not coalesce((receipt_check->>'check_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
                  or receipt_check->>'state' is distinct from 'passed'
                  or not coalesce(ops.engineering_receipt_evidence_array(receipt_check->'evidence_refs'),false)
                  or not coalesce(case when jsonb_typeof(receipt_check->'evidence_refs')='array'
                                       then jsonb_array_length(receipt_check->'evidence_refs')>0 else false end,false)
            )
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'checks')='array'
                                               then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
               group by receipt_check->>'check_ref'
              having count(*)>1
            )
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'checks')='array'
                                               then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
               where not exists (
                 select 1
                   from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice,
                        jsonb_array_elements(dependency_slice->'planned_checks') planned_check
                  where dependency_slice->>'slice_ref'=receipt.slice_ref
                    and planned_check->>'check_ref'=receipt_check->>'check_ref'
               )
            )
            and not exists (
              select 1
                from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice,
                     jsonb_array_elements(dependency_slice->'planned_checks') planned_check
               where dependency_slice->>'slice_ref'=receipt.slice_ref
                 and not exists (
                   select 1 from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'checks')='array'
                                                          then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
                    where receipt_check->>'check_ref'=planned_check->>'check_ref'
                 )
            )
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'checks')='array'
                                               then receipt.receipt->'checks' else '[]'::jsonb end) receipt_check
                join lateral (
                  select planned_check
                    from jsonb_array_elements(slice_plan.plan->'slices') dependency_slice,
                         jsonb_array_elements(dependency_slice->'planned_checks') planned_check
                   where dependency_slice->>'slice_ref'=receipt.slice_ref
                     and planned_check->>'check_ref'=receipt_check->>'check_ref'
                ) planned on true
               where not exists (
                 select 1 from jsonb_array_elements(case when jsonb_typeof(receipt_check->'evidence_refs')='array'
                                                        then receipt_check->'evidence_refs' else '[]'::jsonb end) evidence
                  where evidence->>'redaction_class'=case planned.planned_check->>'evidence_requirement'
                    when 'redacted_evidence_required' then 'redacted_evidence' else 'metadata_only' end
               )
            )
            and coalesce(ops.engineering_receipt_exact_object(receipt.receipt->'source_evidence',array[
                  'branch_ref','evidence_refs','source_sha','worktree_ref'
                ]),false)
            and not exists (
              select 1 from unnest(array['worktree_ref','branch_ref','source_sha']) field
               where jsonb_typeof(receipt.receipt->'source_evidence'->field) is distinct from 'string'
                  or not coalesce(btrim(receipt.receipt->'source_evidence'->>field)<>'',false)
                  or (field<>'source_sha' and not coalesce(
                       (receipt.receipt->'source_evidence'->>field) ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false))
            )
            and coalesce(ops.engineering_receipt_evidence_array(receipt.receipt->'source_evidence'->'evidence_refs'),false)
            and coalesce(ops.engineering_receipt_exact_object(receipt.receipt->'reset_reconstruction',array[
                  'fresh_session','inherited_transcript_used','reconstruction_free','remediation_action'
                ]),false)
            and receipt.receipt->'reset_reconstruction'->'fresh_session'='true'::jsonb
            and receipt.receipt->'reset_reconstruction'->'inherited_transcript_used'='false'::jsonb
            and jsonb_typeof(receipt.receipt->'reset_reconstruction'->'reconstruction_free')='boolean'
            and (
              (receipt.receipt->'reset_reconstruction'->'reconstruction_free'='false'::jsonb and
               jsonb_typeof(receipt.receipt->'reset_reconstruction'->'remediation_action')='string' and
               btrim(receipt.receipt->'reset_reconstruction'->>'remediation_action')<>'')
              or
              (receipt.receipt->'reset_reconstruction'->'reconstruction_free'='true'::jsonb and
               (receipt.receipt->'reset_reconstruction'->'remediation_action'='null'::jsonb or
                (jsonb_typeof(receipt.receipt->'reset_reconstruction'->'remediation_action')='string' and
                 btrim(receipt.receipt->'reset_reconstruction'->>'remediation_action')<>'')))
            )
            and coalesce(ops.engineering_receipt_exact_object(receipt.receipt->'executor_claim',array[
                  'claim_state','claimed_at','claimed_by'
                ]),false)
            and receipt.receipt->'executor_claim'->>'claim_state'='executor_claim'
            and receipt.receipt->'executor_claim'->>'claimed_by'=executor_actor.slug
            and jsonb_typeof(receipt.receipt->'executor_claim'->'claimed_at')='string'
            and btrim(receipt.receipt->'executor_claim'->>'claimed_at')<>''
            and review.state='passed'
            and review.contract_version='engineering-review.v1'
            and review.fact->>'state'='passed'
            and coalesce(ops.engineering_receipt_exact_object(review.fact,array[
                  'attempt_id','evidence_refs','is_independent','resolved_deviation_refs',
                  'reviewed_deviation_refs','reviewer_ref','session_ref','slice_ref','state'
                ]),false)
            and review.fact->>'slice_ref'=receipt.slice_ref
            and review.fact->>'attempt_id'=receipt.attempt_id
            and review.reviewer_actor_id<>receipt.executor_actor_id
            and review.fact->>'reviewer_ref'=any(array[
                  reviewer_actor.slug,'actor:'||reviewer_actor.slug,'reviewer:'||reviewer_actor.slug
                ])
            and review.reviewer_session_ref=review.fact->>'session_ref'
            and review.reviewer_session_ref<>receipt.receipt#>>'{attribution,session_ref}'
            and review.reviewer_session_ref ~ '^session:[A-Za-z0-9][A-Za-z0-9._:-]{1,119}$'
            and review.fact->>'reviewer_ref' ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
            and review.fact->'is_independent'='true'::jsonb
            and coalesce(ops.engineering_receipt_evidence_array(review.fact->'evidence_refs'),false)
            and coalesce(case when jsonb_typeof(review.fact->'evidence_refs')='array'
                              then jsonb_array_length(review.fact->'evidence_refs')>0 else false end,false)
            and coalesce(ops.engineering_receipt_identifier_sets_equal(
                  review.fact->'reviewed_deviation_refs',
                  coalesce((
                    select jsonb_agg(to_jsonb(deviation->>'deviation_ref') order by deviation->>'deviation_ref')
                      from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'deviations')='array'
                                                     then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
                  ),'[]'::jsonb)),false)
            and coalesce(ops.engineering_receipt_identifier_sets_equal(
                  review.fact->'resolved_deviation_refs',
                  coalesce((
                    select jsonb_agg(to_jsonb(deviation->>'deviation_ref') order by deviation->>'deviation_ref')
                      from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'deviations')='array'
                                                     then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
                  ),'[]'::jsonb)),false)
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(receipt.receipt->'deviations')='array'
                                               then receipt.receipt->'deviations' else '[]'::jsonb end) deviation
               where deviation->>'review_state' is distinct from 'resolved'
                  or deviation->'plan_revision_required' is distinct from 'false'::jsonb
            )
            and not exists (
              select 1 from ops.engineering_execution_envelope successor
               where successor.supersedes_envelope_id=envelope.id
            )
            and 1=(
              select count(*)
                from ops.engineering_execution_envelope leaf
               where leaf.slice_plan_id=slice_plan.id
                 and leaf.slice_ref=receipt.slice_ref
                 and not exists (
                   select 1 from ops.engineering_execution_envelope successor
                    where successor.supersedes_envelope_id=leaf.id
                 )
            )
       )
  ) then
    raise exception 'engineering slice dependencies are not independently verified';
  end if;

  job_key := 'engineering-slice:'||p_plan_digest||':'||p_work_request||':'||
             p_slice_ref||':generation:'||p_generation;
  select * into row from ops.job where idempotency_key=job_key;
  if row.id is not null then return row; end if;
  select * into row from ops.enqueue_job(
    'engineering-slice',1,now(),
    jsonb_build_object('work_request',p_work_request,'slice_ref',p_slice_ref,
                       'plan_digest',p_plan_digest,'generation',p_generation),
    job_key,'shadow');
  return row;
end $_$;


--
-- Name: engineering_envelope_currentness(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_envelope_currentness(p_envelope_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_plan ops.sourced_work_request_plan%rowtype; v_result jsonb;
begin
  select p.* into v_plan from ops.engineering_execution_envelope e
    join ops.sourced_work_request_plan p on p.id=e.accepted_plan_id
   where e.id=p_envelope_id and e.job_id=p_job_id;
  if v_plan.id is not null then
    perform 1 from ops.work_request w where w.id=v_plan.work_request_id for share;
  end if;
  if v_plan.id is not null and ops.engineering_contract_stale(v_plan.plan_ref,v_plan.plan_hash,null) then
    return jsonb_build_object('eligible',false,'dispatch_runway_sufficient',false,
      'execution_authorized',false,'reason','accepted_plan_retired');
  end if;
  v_result:=ops.engineering_envelope_currentness_v1(p_envelope_id,p_job_id);
  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('execution_authorized',
    coalesce((v_result->>'eligible')::boolean,false));
end $$;


--
-- Name: engineering_envelope_currentness_v1(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_envelope_currentness_v1(p_envelope_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
  with candidate as (
    select e.*, j.id as queue_job_id, j.payload, j.definition_key, j.definition_version, j.mode,
           d.enabled, sp.plan_digest, sp.accepted_plan_hash,
           sp.accepted_plan_id as slice_plan_accepted_plan_id, sp.work_request_id as slice_plan_work_request_id,
           sp.work_request_version as slice_plan_work_request_version, sp.plan as slice_plan,
           s.state as session_state,
           s.lease_expires_at as session_lease_expires_at, s.work_request_id as session_work_request_id,
           s.source_commit_sha as session_source_commit_sha, s.worktree_ref as session_worktree_ref,
           s.scope_ref as session_scope_ref,
           actor.slug as executor_slug, actor.active as executor_active,
           actor.kind as executor_kind, ops.engineering_admission_source(w.ref) as source
      from ops.engineering_execution_envelope e
      join ops.job j on j.id=e.job_id
      join ops.job_definition d on d.key=j.definition_key and d.version=j.definition_version
      join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id
      join ops.work_request w on w.id=e.work_request_id
      join ops.capability_agent_session s on s.id=e.agent_session_id
      join public.actor actor on actor.id=s.executor_actor_id
     where e.id=p_envelope_id and e.job_id=p_job_id
  ), checked as (
    select c.*,
      ops.engineering_safe_timestamptz(c.envelope->>'expires_at') as json_expires_at,
      ops.engineering_safe_timestamptz(c.envelope->>'issued_at') as json_issued_at,
      ops.engineering_safe_timestamptz(c.envelope->'agent_session'->>'lease_expires_at') as json_session_expires_at,
      exists(select 1 from ops.engineering_execution_envelope successor
               where successor.supersedes_envelope_id=c.id) as has_successor,
      exists(select 1 from ops.engineering_slice_receipt receipt
               where receipt.envelope_id=c.id
                 and receipt.outcome='claimed_complete') as has_receipt
    from candidate c
  )
  select jsonb_build_object(
    'eligible',
      enabled and definition_key='engineering-slice' and definition_version=1 and mode='shadow'
      and payload->>'work_request' = source->'work_request'->>'ref'
      and payload->>'slice_ref'=slice_ref and payload->>'plan_digest'=plan_digest
      and jsonb_typeof(payload->'generation')='number' and (payload->>'generation') ~ '^[1-9][0-9]*$'
      and source is not null
      and source->'work_request'->>'id'='wr:'||work_request_id::text
      and (source->'work_request'->>'version') ~ '^[1-9][0-9]*$'
      and (source->'work_request'->>'version')::integer=state_version
      and source->'work_request'->>'canonical_record_digest'=canonical_record_digest
      and source->'accepted_plan'->>'record_id'=accepted_plan_id::text
      and source->'accepted_plan'->>'digest'=accepted_plan_hash
      and slice_plan_accepted_plan_id=accepted_plan_id and slice_plan_accepted_plan_id::text=source->'accepted_plan'->>'record_id'
      and slice_plan_work_request_id=work_request_id and slice_plan_work_request_id::text=regexp_replace(source->'work_request'->>'id','^wr:','')
      and slice_plan_work_request_version=state_version
      and slice_plan->>'plan_digest'=plan_digest
      and slice_plan->'accepted_plan_revision'->>'id'=source->'accepted_plan'->>'plan_ref'
      and slice_plan->'accepted_plan_revision'->>'revision'=source->'accepted_plan'->>'revision'
      and slice_plan->'accepted_plan_revision'->>'digest'=source->'accepted_plan'->>'digest'
      and jsonb_typeof(envelope)='object' and envelope->>'schema_version'='execution-envelope.v1'
      and envelope->>'envelope_id'='env:'||id::text
      and envelope->>'work_request_id'='wr:'||work_request_id::text
      and envelope->'request'->>'job_ref'='job:'||queue_job_id::text
      and envelope->'request'->>'input_digest' is not null
      and envelope->'plan_revision'->>'id'=source->'accepted_plan'->>'plan_ref'
      and envelope->'plan_revision'->>'revision'=source->'accepted_plan'->>'revision'
      and envelope->'plan_revision'->>'digest'=source->'accepted_plan'->>'digest'
      and envelope->'plan_revision'->>'digest'=accepted_plan_hash
      and envelope->'phase_binding'->>'phase_id'='phase:'||slice_ref
      and envelope->'state_binding'->>'state_version'=state_version::text
      and envelope->'state_binding'->>'canonical_record_digest'=canonical_record_digest
      and envelope->'agent_session'->>'id'='session:'||agent_session_id::text
      and json_issued_at is not null and envelope->>'issued_at'=to_char(issued_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
      and json_issued_at=issued_at
      and json_expires_at is not null and envelope->>'expires_at'=to_char(expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
      and json_expires_at=expires_at and expires_at>issued_at and expires_at<=issued_at+interval '30 minutes' and json_expires_at>statement_timestamp()
      and json_session_expires_at is not null and session_lease_expires_at is not null
      and envelope->'agent_session'->>'lease_expires_at'=to_char(session_lease_expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')
      and json_session_expires_at=session_lease_expires_at and json_session_expires_at=expires_at and json_session_expires_at>statement_timestamp()
      and session_work_request_id=work_request_id and session_state in ('claimed','in_progress')
      and session_source_commit_sha=repeat('0',40) and session_worktree_ref='engineering:server-admission'
      and session_scope_ref='slice:'||slice_ref
      and executor_active and executor_kind='automation' and executor_slug='codex'
      and envelope->'server_binding'->'authority'->>'read_only'='false'
      and envelope->'server_binding'->'authority'->>'capability_profile'='capability:engineering-repository-write'
      and envelope->'server_binding'->'adapter'->>'surface'='codex_desktop'
      and envelope#>>'{server_binding,adapter,adapter_id}'='adapter:codex-desktop'
      and envelope->'server_binding'->'identity'->>'agent_principal_id'='agent:codex'
      and envelope->'server_binding'->'identity'->>'runtime_principal'='runtime:codex'
      and envelope->'request'->'allowed_actions'=
        '["repository:create-worktree","repository:create-branch","repository:write-declared-scope","repository:run-checks","repository:commit","repository:push-branch","repository:open-pr"]'::jsonb
      and not has_successor and not has_receipt,
    'dispatch_runway_sufficient',
      expires_at>=statement_timestamp()+interval '960 seconds'
      and session_lease_expires_at>=statement_timestamp()+interval '960 seconds',
    'reason', case
      when id is null then 'envelope_or_job_not_found'
      when has_successor then 'superseded_envelope'
      when has_receipt then 'already_receipted'
      when jsonb_typeof(envelope)<>'object' or envelope->>'schema_version'<>'execution-envelope.v1' then 'malformed_envelope_schema'
      when json_issued_at is null or json_issued_at<>issued_at or json_expires_at is null or json_expires_at<>expires_at or expires_at<=issued_at or expires_at>issued_at+interval '30 minutes' or json_expires_at<=statement_timestamp() then 'envelope_expired_or_mismatched'
      when json_session_expires_at is null or session_lease_expires_at is null or json_session_expires_at<>session_lease_expires_at or json_session_expires_at<=statement_timestamp() then 'agent_session_lease_expired_or_mismatched'
      when session_state not in ('claimed','in_progress') or session_work_request_id<>work_request_id then 'agent_session_not_active'
      when envelope->'server_binding'->'authority'->>'read_only'<>'false' then 'read_only_authority'
      when source is null then 'source_not_current'
      else 'identity_or_currentness_mismatch' end
  ) from checked;
$_$;


--
-- Name: engineering_envelope_is_executable(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_envelope_is_executable(p_envelope_id uuid, p_job_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$ select coalesce((ops.engineering_envelope_currentness(p_envelope_id,p_job_id)->>'eligible')::boolean,false) $$;


--
-- Name: engineering_fail_claim(uuid, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_fail_claim(p_job_id uuid, p_lease_token uuid, p_failure_class text, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare j ops.job%rowtype; next_state text; transitioned integer; v_now timestamptz;
begin
  select * into j from ops.job where id=p_job_id for update;
  v_now:=clock_timestamp();
  if not found or j.definition_key<>'engineering-slice' or j.state<>'running'
     or j.lease_token<>p_lease_token or j.leased_until<=v_now then
    raise exception 'engineering job does not hold this live scoped lease';
  end if;
  next_state:=case when j.attempt<j.max_attempts then 'retry_wait' else 'dead_lettered' end;
  perform ops.canonical_ownership_release_for_job(j.id,j.attempt,p_lease_token);
  update ops.job_attempt set state='failed',ended_at=v_now,
         failure_class=p_failure_class,detail=left(coalesce(p_detail,''),1000)
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token and state='running';
  get diagnostics transitioned=row_count;
  if transitioned<>1 then raise exception 'engineering failure attempt is not current'; end if;
  update ops.job set state=next_state,
         next_attempt_at=case when next_state='retry_wait'
           then v_now+make_interval(secs=>ops.retry_delay_seconds(j)) else next_attempt_at end,
         ended_at=case when next_state='dead_lettered' then v_now else null end,
         last_failure_class=p_failure_class,last_failure_detail=left(coalesce(p_detail,''),1000),
         lease_owner=null,lease_token=null,leased_until=null,updated_at=v_now
   where id=j.id and state='running' and lease_token=p_lease_token;
  get diagnostics transitioned=row_count;
  if transitioned<>1 then raise exception 'engineering failure did not transition the claimed job'; end if;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
  values(j.id,j.attempt,case when next_state='dead_lettered' then 'dead_letter' else 'failure' end,
         concat('engineering-failure:',j.id,':',j.attempt),
         jsonb_build_object('failure_class',p_failure_class,
           'detail',left(coalesce(p_detail,''),1000),'next_state',next_state));
  return next_state;
end $$;


--
-- Name: engineering_slice_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.engineering_slice_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_attempt_id uuid NOT NULL,
    envelope_id uuid NOT NULL,
    work_request_id uuid NOT NULL,
    slice_ref text NOT NULL,
    attempt_id text NOT NULL,
    executor_actor_id uuid NOT NULL,
    receipt_digest text NOT NULL,
    outcome text NOT NULL,
    receipt jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT engineering_slice_receipt_attempt_id_check CHECK ((attempt_id ~ '^attempt:[1-9][0-9]*$'::text)),
    CONSTRAINT engineering_slice_receipt_outcome_check CHECK ((outcome = ANY (ARRAY['claimed_complete'::text, 'failed'::text, 'blocked'::text, 'reopened'::text]))),
    CONSTRAINT engineering_slice_receipt_receipt_check CHECK ((jsonb_typeof(receipt) = 'object'::text)),
    CONSTRAINT engineering_slice_receipt_receipt_digest_check CHECK ((receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT engineering_slice_receipt_slice_ref_check CHECK ((btrim(slice_ref) <> ''::text))
);


--
-- Name: engineering_finalize_slice_receipt(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_finalize_slice_receipt(p_envelope_id uuid, p_lease_token uuid, p_receipt jsonb, p_receipt_digest text, p_executor_actor_id uuid) RETURNS ops.engineering_slice_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare e ops.engineering_execution_envelope%rowtype;
        row ops.engineering_slice_receipt%rowtype;
        j ops.job%rowtype;
        terminal_state text;
        transitioned integer;
        v_transition_at timestamptz;
begin
  select * into e from ops.engineering_execution_envelope where id=p_envelope_id;
  if not found then raise exception 'engineering envelope not found'; end if;
  select * into row from ops.engineering_record_slice_receipt(
    p_envelope_id,p_lease_token,p_receipt,p_receipt_digest,p_executor_actor_id);
  select * into j from ops.job where id=e.job_id for update;
  v_transition_at:=clock_timestamp();
  if not found or j.definition_key<>'engineering-slice' or j.state<>'running'
     or j.lease_token<>p_lease_token or j.leased_until<=v_transition_at then
    raise exception 'engineering job does not hold this live scoped lease';
  end if;
  perform ops.canonical_ownership_release_for_job(j.id,j.attempt,p_lease_token);
  if row.outcome='claimed_complete' then
    update ops.job_attempt set state='succeeded',ended_at=v_transition_at
     where id=row.job_attempt_id and job_id=j.id and attempt=j.attempt
       and lease_token=p_lease_token and state='running';
    get diagnostics transitioned=row_count;
    if transitioned<>1 then raise exception 'engineering completion attempt is not current'; end if;
    update ops.job set state='succeeded',ended_at=v_transition_at,
           lease_owner=null,lease_token=null,leased_until=null,updated_at=v_transition_at
     where id=j.id and state='running' and lease_token=p_lease_token;
    get diagnostics transitioned=row_count;
    if transitioned<>1 then raise exception 'engineering completion did not transition the claimed job'; end if;
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,'completion','engineering:'||row.id::text,
           jsonb_build_object('engineering_receipt_id',row.id,'receipt_digest',p_receipt_digest));
    update ops.capability_agent_session
       set state='cancelled',cancelled_at=v_transition_at,version=version+1
     where id=e.agent_session_id and work_request_id=e.work_request_id
       and state in ('claimed','in_progress');
    get diagnostics transitioned=row_count;
    if transitioned<>1 then raise exception 'engineering agent session could not be atomically retired'; end if;
  else
    terminal_state:=case when j.attempt<j.max_attempts then 'retry_wait' else 'dead_lettered' end;
    update ops.job_attempt set state='failed',ended_at=v_transition_at,
           failure_class='engineering_'||row.outcome,
           detail='typed engineering receipt reported non-complete outcome'
     where id=row.job_attempt_id and job_id=j.id and attempt=j.attempt
       and lease_token=p_lease_token and state='running';
    get diagnostics transitioned=row_count;
    if transitioned<>1 then raise exception 'engineering failure attempt is not current'; end if;
    update ops.job set state=terminal_state,
           next_attempt_at=case when terminal_state='retry_wait'
             then v_transition_at+make_interval(secs=>ops.retry_delay_seconds(j)) else next_attempt_at end,
           ended_at=case when terminal_state='dead_lettered' then v_transition_at else null end,
           last_failure_class='engineering_'||row.outcome,
           last_failure_detail='typed engineering receipt reported non-complete outcome',
           lease_owner=null,lease_token=null,leased_until=null,updated_at=v_transition_at
     where id=j.id and state='running' and lease_token=p_lease_token;
    get diagnostics transitioned=row_count;
    if transitioned<>1 then raise exception 'engineering failure did not transition the claimed job'; end if;
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,case when terminal_state='dead_lettered' then 'dead_letter' else 'failure' end,
           concat('engineering-failure:',j.id,':',j.attempt),
           jsonb_build_object('failure_class','engineering_'||row.outcome,
             'detail','typed engineering receipt reported non-complete outcome','next_state',terminal_state));
  end if;
  return row;
end $$;


--
-- Name: engineering_passport_facts(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_passport_facts(p_work_request text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
    'source',ops.engineering_admission_source(p_work_request),
    'slice_plans',coalesce((
      select jsonb_agg(to_jsonb(sp) order by sp.created_at)
        from ops.engineering_slice_plan sp
        join ops.work_request w on w.id=sp.work_request_id
       where w.ref=p_work_request
    ),'[]'::jsonb),
    'envelopes',coalesce((
      select jsonb_agg(to_jsonb(e) order by e.created_at)
        from ops.engineering_execution_envelope e
        join ops.work_request w on w.id=e.work_request_id
       where w.ref=p_work_request
    ),'[]'::jsonb),
    'receipts',coalesce((
      select jsonb_agg(
               to_jsonb(r)||jsonb_build_object(
                 'executor_actor_active',executor.active,
                 'executor_actor_slug',executor.slug
               ) order by r.created_at
             )
        from ops.engineering_slice_receipt r
        join ops.work_request w on w.id=r.work_request_id
        join public.actor executor on executor.id=r.executor_actor_id
       where w.ref=p_work_request
    ),'[]'::jsonb),
    'reviewer_facts',coalesce((
      select jsonb_agg(
               to_jsonb(f)||jsonb_build_object(
                 'contract_version',f.contract_version,
                 'reviewer_actor_active',reviewer.active,
                 'reviewer_actor_slug',reviewer.slug
               ) order by f.created_at
             )
        from ops.engineering_reviewer_fact f
        join ops.work_request w on w.id=f.work_request_id
        join public.actor reviewer on reviewer.id=f.reviewer_actor_id
       where w.ref=p_work_request
    ),'[]'::jsonb)
  );
$$;


--
-- Name: engineering_plan_identifier_list(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_plan_identifier_list(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select jsonb_typeof(p_value)='array'
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_value)='array' then p_value else '[]'::jsonb end) value
        where jsonb_typeof(value)<>'string'
           or not coalesce((value#>>'{}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     );
$_$;


--
-- Name: FUNCTION engineering_plan_identifier_list(p_value jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.engineering_plan_identifier_list(p_value jsonb) IS 'An array of well-formed identifier strings, duplicates allowed. This is the exact predicate the JS and Python plan validators apply to a slice declared-ref array; ops.engineering_receipt_identifier_array additionally requires uniqueness and is used everywhere the source validators require it.';


--
-- Name: engineering_receipt_design_binding_refusal(jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_binding_refusal(p_slice jsonb, p_envelope jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare routing jsonb; authority jsonb; binding jsonb; mismatch_field text;
begin
  if jsonb_typeof(p_slice) is distinct from 'object'
     or jsonb_typeof(p_envelope) is distinct from 'object' then return 'envelope'; end if;
  routing := p_slice#>'{design_contract,routing}';
  authority := p_slice#>'{design_contract,authority}';
  binding := p_envelope->'server_binding';
  if jsonb_typeof(routing) is distinct from 'object'
     or jsonb_typeof(authority) is distinct from 'object'
     or jsonb_typeof(binding) is distinct from 'object'
     or jsonb_typeof(binding->'adapter') is distinct from 'object'
     or jsonb_typeof(binding->'authority') is distinct from 'object' then
    return 'envelope.server_binding';
  end if;
  -- Codex is the only executable adapter at this seam, so an accepted contract
  -- routed to an attended human names an executor no receipt here can come from.
  if not coalesce((routing->>'executor_class')=any(array['deterministic_code','model_assisted']),false) then
    return 'design_contract.routing.executor_class';
  end if;
  if binding#>>'{adapter,adapter_id}' is null
     or (routing->>'adapter_ref') is distinct from (binding#>>'{adapter,adapter_id}') then
    return 'design_contract.routing.adapter_ref';
  end if;
  -- environment, capability_profile and read_only are compared as jsonb, so a
  -- boolean false and the string "false" are not interchangeable.
  select fields.name into mismatch_field
    from unnest(array['environment','capability_profile','read_only']) with ordinality as fields(name,ord)
   where binding->'authority'->fields.name is null
      or authority->fields.name is distinct from binding->'authority'->fields.name
   order by fields.ord
   limit 1;
  if mismatch_field is not null then
    return 'design_contract.authority.'||mismatch_field;
  end if;
  return null;
end $$;


--
-- Name: engineering_receipt_design_contract_refusal(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_contract_refusal(p_slice jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare contract jsonb; decision jsonb; steps jsonb; routing jsonb; authority jsonb;
        isolation jsonb; tests jsonb; review jsonb; failure jsonb; evidence jsonb;
        deployment jsonb; completion jsonb; seam jsonb; measurement jsonb;
        refs jsonb; template jsonb; depth text;
begin
  if jsonb_typeof(p_slice) is distinct from 'object' then return 'slice'; end if;
  if not coalesce(ops.engineering_receipt_design_self_label_free(p_slice),false) then
    return 'slice.design_depth_self_label';
  end if;
  contract := p_slice->'design_contract';
  if jsonb_typeof(contract) is distinct from 'object' then return 'design_contract'; end if;
  if not coalesce(ops.engineering_receipt_design_self_label_free(contract),false) then
    return 'design_contract.design_depth_self_label';
  end if;
  if not coalesce(ops.engineering_receipt_exact_object(contract,array[
       'authority','code_model_decision','completion','contract_version','dependency_rationale',
       'deployment','evidence','failure','full_design_refs','isolation','rationale','review',
       'routing','seam_decision','short_template','tests']),false) then
    return 'design_contract.shape';
  end if;
  -- An unknown design-contract version is refused, never defaulted: the frozen
  -- depth predicate is selected by the contract's own sealed version.
  if contract->>'contract_version' is distinct from 'engineering-design-contract.v1' then
    return 'design_contract.contract_version';
  end if;
  depth := ops.engineering_receipt_design_depth(p_slice,contract->>'contract_version');
  if depth is null then return 'design_contract.design_depth'; end if;
  if not coalesce(ops.engineering_receipt_design_string(contract->'rationale'),false) then
    return 'design_contract.rationale';
  end if;
  if not coalesce(ops.engineering_receipt_design_string(contract->'dependency_rationale'),false) then
    return 'design_contract.dependency_rationale';
  end if;

  decision := contract->'code_model_decision';
  if not coalesce(ops.engineering_receipt_exact_object(decision,array[
       'model_judgment_steps','rationale','selection_basis']),false) then
    return 'design_contract.code_model_decision';
  end if;
  if not coalesce(ops.engineering_receipt_design_string(decision->'rationale'),false) then
    return 'design_contract.code_model_decision.rationale';
  end if;
  if not coalesce(ops.engineering_receipt_design_selection_basis(decision->'selection_basis'),false) then
    return 'design_contract.code_model_decision.selection_basis';
  end if;
  steps := decision->'model_judgment_steps';
  if not coalesce(ops.engineering_receipt_design_model_steps(p_slice,steps),false) then
    return 'design_contract.code_model_decision.model_judgment_steps';
  end if;

  routing := contract->'routing';
  if not coalesce(ops.engineering_receipt_exact_object(routing,array[
       'adapter_ref','executor_class','fresh_session_required']),false) then
    return 'design_contract.routing';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(routing->'executor_class',array[
       'deterministic_code','attended_human','model_assisted']),false) then
    return 'design_contract.routing.executor_class';
  end if;
  if not coalesce(ops.engineering_receipt_design_identifier(routing->'adapter_ref'),false) then
    return 'design_contract.routing.adapter_ref';
  end if;
  if routing->'fresh_session_required' is distinct from 'true'::jsonb then
    return 'design_contract.routing.fresh_session_required';
  end if;
  if (routing->>'executor_class')='deterministic_code' and jsonb_array_length(steps)>0 then
    return 'design_contract.routing.executor_class';
  end if;
  if (routing->>'executor_class')='model_assisted' and jsonb_array_length(steps)=0 then
    return 'design_contract.routing.executor_class';
  end if;

  authority := contract->'authority';
  if not coalesce(ops.engineering_receipt_exact_object(authority,array[
       'capability_profile','environment','read_only']),false) then
    return 'design_contract.authority';
  end if;
  if not coalesce(ops.engineering_receipt_design_identifier(authority->'capability_profile'),false) then
    return 'design_contract.authority.capability_profile';
  end if;
  if jsonb_typeof(authority->'read_only') is distinct from 'boolean' then
    return 'design_contract.authority.read_only';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(authority->'environment',array[
       'local','rehearsal','staging','production']),false) then
    return 'design_contract.authority.environment';
  end if;
  if authority->'read_only'='false'::jsonb
     and (authority->>'capability_profile') is distinct from 'capability:engineering-repository-write' then
    return 'design_contract.authority.capability_profile';
  end if;

  isolation := contract->'isolation';
  if not coalesce(ops.engineering_receipt_exact_object(isolation,array[
       'branch_required','shared_resource_refs','worktree_required']),false) then
    return 'design_contract.isolation';
  end if;
  if isolation->'worktree_required' is distinct from 'true'::jsonb
     or isolation->'branch_required' is distinct from 'true'::jsonb then
    return 'design_contract.isolation.worktree_required';
  end if;
  if not coalesce(ops.engineering_receipt_design_identifier_subset(
       isolation->'shared_resource_refs',p_slice->'declared_resource_refs'),false) then
    return 'design_contract.isolation.shared_resource_refs';
  end if;
  if jsonb_array_length(isolation->'shared_resource_refs')>0
     and (p_slice->>'concurrency_posture')='parallel_safe' then
    return 'design_contract.isolation.shared_resource_refs';
  end if;

  tests := contract->'tests';
  if not coalesce(ops.engineering_receipt_exact_object(tests,array[
       'planned_check_refs','verification_lanes']),false) then
    return 'design_contract.tests';
  end if;
  if not coalesce(ops.engineering_receipt_identifier_array(tests->'planned_check_refs'),false) then
    return 'design_contract.tests.planned_check_refs';
  end if;
  -- Ordered equality, exactly as both source validators compare them: the
  -- contract binds the accepted planned checks in their accepted order.
  if (select array_agg(value#>>'{}' order by ord)
        from jsonb_array_elements(case when jsonb_typeof(tests->'planned_check_refs')='array'
                                       then tests->'planned_check_refs' else '[]'::jsonb end)
             with ordinality as bound_refs(value,ord))
     is distinct from
     (select array_agg(check_row->>'check_ref' order by ord)
        from jsonb_array_elements(case when jsonb_typeof(p_slice->'planned_checks')='array'
                                       then p_slice->'planned_checks' else '[]'::jsonb end)
             with ordinality as planned(check_row,ord)) then
    return 'design_contract.tests.planned_check_refs';
  end if;
  if jsonb_typeof(tests->'verification_lanes') is distinct from 'array'
     or coalesce(case when jsonb_typeof(tests->'verification_lanes')='array'
                      then jsonb_array_length(tests->'verification_lanes') else null end,0)=0
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(tests->'verification_lanes')='array'
                                        then tests->'verification_lanes' else '[]'::jsonb end) lane
        where jsonb_typeof(lane)<>'string'
           or not coalesce((lane#>>'{}')=any(array['unit','contract','integration','manual_qa']),false))
     or (select count(*)<>count(distinct (lane#>>'{}'))
           from jsonb_array_elements(case when jsonb_typeof(tests->'verification_lanes')='array'
                                          then tests->'verification_lanes' else '[]'::jsonb end) lane) then
    return 'design_contract.tests.verification_lanes';
  end if;
  if (tests->'verification_lanes' @> '["manual_qa"]'::jsonb)
     is distinct from (p_slice->'manual_qa_required'='true'::jsonb) then
    return 'design_contract.tests.verification_lanes';
  end if;

  review := contract->'review';
  if not coalesce(ops.engineering_receipt_exact_object(review,array[
       'independent_review_required','reviewer_class']),false) then
    return 'design_contract.review';
  end if;
  if review->'independent_review_required' is distinct from 'true'::jsonb then
    return 'design_contract.review.independent_review_required';
  end if;
  -- review-engineering-slice is the only reviewer provider this seam has and it
  -- records one independent automation actor's typed fact.  independent_human
  -- would seal a requirement into an immutable plan that no code can satisfy or
  -- refuse, so it stays refused until a human-review provider exists.
  if not coalesce(ops.engineering_receipt_design_enum(review->'reviewer_class',
       array['independent_agent']),false) then
    return 'design_contract.review.reviewer_class';
  end if;

  failure := contract->'failure';
  if not coalesce(ops.engineering_receipt_exact_object(failure,array['failure_modes']),false) then
    return 'design_contract.failure';
  end if;
  if jsonb_typeof(failure->'failure_modes') is distinct from 'array'
     or coalesce(case when jsonb_typeof(failure->'failure_modes')='array'
                      then jsonb_array_length(failure->'failure_modes') else null end,0)=0
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(failure->'failure_modes')='array'
                                        then failure->'failure_modes' else '[]'::jsonb end) mode
        where not coalesce(ops.engineering_receipt_exact_object(mode,array[
                'compensation','detection','failure_ref']),false)
           or not coalesce(ops.engineering_receipt_design_identifier(mode->'failure_ref'),false)
           or not coalesce(ops.engineering_receipt_design_string(mode->'detection'),false)
           or not coalesce(ops.engineering_receipt_design_string(mode->'compensation'),false))
     or (select count(*)<>count(distinct (mode->>'failure_ref'))
           from jsonb_array_elements(case when jsonb_typeof(failure->'failure_modes')='array'
                                          then failure->'failure_modes' else '[]'::jsonb end) mode) then
    return 'design_contract.failure.failure_modes';
  end if;

  evidence := contract->'evidence';
  if not coalesce(ops.engineering_receipt_exact_object(evidence,array[
       'evidence_refs','redaction_class','retention']),false) then
    return 'design_contract.evidence';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(evidence->'redaction_class',array[
       'metadata_only','redacted_evidence']),false) then
    return 'design_contract.evidence.redaction_class';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(evidence->'retention',array[
       'ephemeral','material_redacted']),false) then
    return 'design_contract.evidence.retention';
  end if;
  if not coalesce(ops.engineering_receipt_evidence_array(evidence->'evidence_refs'),false) then
    return 'design_contract.evidence.evidence_refs';
  end if;
  if exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(evidence->'evidence_refs')='array'
                                        then evidence->'evidence_refs' else '[]'::jsonb end) item
        where (item->>'redaction_class') is distinct from (evidence->>'redaction_class')) then
    return 'design_contract.evidence.evidence_refs';
  end if;
  if exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_slice->'planned_checks')='array'
                                        then p_slice->'planned_checks' else '[]'::jsonb end) planned_check
        where (planned_check->>'evidence_requirement')='redacted_evidence_required')
     and (evidence->>'redaction_class') is distinct from 'redacted_evidence' then
    return 'design_contract.evidence.redaction_class';
  end if;

  deployment := contract->'deployment';
  if not coalesce(ops.engineering_receipt_exact_object(deployment,array[
       'confirmation_required','release_requirement','rollback_ref']),false) then
    return 'design_contract.deployment';
  end if;
  if (deployment->>'release_requirement') is distinct from (p_slice->>'release_requirement') then
    return 'design_contract.deployment.release_requirement';
  end if;
  if (deployment->>'release_requirement')='required' then
    if not coalesce(ops.engineering_receipt_design_identifier(deployment->'rollback_ref'),false) then
      return 'design_contract.deployment.rollback_ref';
    end if;
  elsif deployment->'rollback_ref' is distinct from 'null'::jsonb
        and not coalesce(ops.engineering_receipt_design_identifier(deployment->'rollback_ref'),false) then
    return 'design_contract.deployment.rollback_ref';
  end if;
  if jsonb_typeof(deployment->'confirmation_required') is distinct from 'boolean' then
    return 'design_contract.deployment.confirmation_required';
  end if;
  -- The canonical explicit confirmation gate above R1 is retained, not waived.
  if not coalesce((p_slice->>'risk_class')=any(array['R0','R1']),false)
     and deployment->'confirmation_required' is distinct from 'true'::jsonb then
    return 'design_contract.deployment.confirmation_required';
  end if;

  completion := contract->'completion';
  if not coalesce(ops.engineering_receipt_exact_object(completion,array[
       'completion_predicate','verified_by']),false) then
    return 'design_contract.completion';
  end if;
  if not coalesce(ops.engineering_receipt_design_string(completion->'completion_predicate'),false) then
    return 'design_contract.completion.completion_predicate';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(completion->'verified_by',array[
       'independent_review','independent_review_and_manual_qa']),false) then
    return 'design_contract.completion.verified_by';
  end if;
  if (completion->>'verified_by') is distinct from
     (case when p_slice->'manual_qa_required'='true'::jsonb
           then 'independent_review_and_manual_qa' else 'independent_review' end) then
    return 'design_contract.completion.verified_by';
  end if;

  -- Q063.D1 / Q122.D1: extend a proven deep module or replace it cleanly; a new
  -- module needs a real seam, and a replacement may not leave residual
  -- authority behind.
  seam := contract->'seam_decision';
  if not coalesce(ops.engineering_receipt_exact_object(seam,array[
       'measurement','mode','new_module_justification','replaced_seam_refs',
       'residual_authority_refs','target_seam_ref']),false) then
    return 'design_contract.seam_decision';
  end if;
  if not coalesce(ops.engineering_receipt_design_enum(seam->'mode',array[
       'reuse','extend','replace','new_module']),false) then
    return 'design_contract.seam_decision.mode';
  end if;
  if not coalesce(ops.engineering_receipt_design_identifier(seam->'target_seam_ref'),false) then
    return 'design_contract.seam_decision.target_seam_ref';
  end if;
  measurement := seam->'measurement';
  if not coalesce(ops.engineering_receipt_exact_object(measurement,array['basis','note']),false)
     or not coalesce(ops.engineering_receipt_design_enum(measurement->'basis',array[
          'complexity_reduction','defect_rate','coverage','latency','operator_effort']),false)
     or not coalesce(ops.engineering_receipt_design_string(measurement->'note'),false) then
    return 'design_contract.seam_decision.measurement';
  end if;
  if not coalesce(ops.engineering_receipt_identifier_array(seam->'replaced_seam_refs'),false) then
    return 'design_contract.seam_decision.replaced_seam_refs';
  end if;
  if not coalesce(ops.engineering_receipt_identifier_array(seam->'residual_authority_refs'),false) then
    return 'design_contract.seam_decision.residual_authority_refs';
  end if;
  if (seam->>'mode')='new_module' then
    if not coalesce(ops.engineering_receipt_design_enum(seam->'new_module_justification',array[
         'authority','lifecycle','failure_isolation','multi_adapter']),false) then
      return 'design_contract.seam_decision.new_module_justification';
    end if;
  elsif seam->'new_module_justification' is distinct from 'null'::jsonb then
    return 'design_contract.seam_decision.new_module_justification';
  end if;
  if (seam->>'mode')='replace' then
    if jsonb_array_length(seam->'replaced_seam_refs')=0
       or seam->'replaced_seam_refs' @> jsonb_build_array(seam->'target_seam_ref') then
      return 'design_contract.seam_decision.replaced_seam_refs';
    end if;
    if jsonb_array_length(seam->'residual_authority_refs')>0 then
      return 'design_contract.seam_decision.residual_authority_refs';
    end if;
  else
    if jsonb_array_length(seam->'replaced_seam_refs')>0 then
      return 'design_contract.seam_decision.replaced_seam_refs';
    end if;
    if jsonb_array_length(seam->'residual_authority_refs')>0 then
      return 'design_contract.seam_decision.residual_authority_refs';
    end if;
  end if;

  -- Q035.D1 depth material.  The classifier decides which template the accepted
  -- slice must carry; the slice never decides for itself.
  if depth='full' then
    if contract->'short_template' is distinct from 'null'::jsonb then
      return 'design_contract.short_template';
    end if;
    refs := contract->'full_design_refs';
    if not coalesce(ops.engineering_receipt_exact_object(refs,array[
         'authority_envelope_ref','design_interview_ref','failure_model_ref','fixture_refs','oracle_ref']),false) then
      return 'design_contract.full_design_refs';
    end if;
    if exists (
         select 1
           from unnest(array['design_interview_ref','authority_envelope_ref','failure_model_ref','oracle_ref']) field
          where not coalesce(ops.engineering_receipt_design_identifier(refs->field),false)) then
      return 'design_contract.full_design_refs';
    end if;
    if not coalesce(ops.engineering_receipt_identifier_array(refs->'fixture_refs'),false)
       or coalesce(case when jsonb_typeof(refs->'fixture_refs')='array'
                        then jsonb_array_length(refs->'fixture_refs') else null end,0)=0 then
      return 'design_contract.full_design_refs.fixture_refs';
    end if;
  else
    if contract->'full_design_refs' is distinct from 'null'::jsonb then
      return 'design_contract.full_design_refs';
    end if;
    template := contract->'short_template';
    if not coalesce(ops.engineering_receipt_exact_object(template,array[
         'objective_summary','template_ref','verification_ref']),false) then
      return 'design_contract.short_template';
    end if;
    if not coalesce(ops.engineering_receipt_design_identifier(template->'template_ref'),false)
       or not coalesce(ops.engineering_receipt_design_identifier(template->'verification_ref'),false) then
      return 'design_contract.short_template';
    end if;
    if not coalesce(ops.engineering_receipt_design_string(template->'objective_summary'),false) then
      return 'design_contract.short_template.objective_summary';
    end if;
  end if;

  return null;
end $$;


--
-- Name: engineering_receipt_design_depth(jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_depth(p_slice jsonb, p_contract_version text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select case
    when p_contract_version<>'engineering-design-contract.v1' then null
    when not (
           coalesce(ops.engineering_receipt_design_enum(p_slice->'risk_class',
             array['R0','R1','R2','R3','R4','R5','R6']),false)
       and coalesce(ops.engineering_receipt_design_enum(p_slice->'concurrency_posture',
             array['parallel_safe','serial_after_dependencies','exclusive_resource']),false)
       and jsonb_typeof(p_slice->'manual_qa_required')='boolean'
       and coalesce(ops.engineering_receipt_design_enum(p_slice->'release_requirement',
             array['required','not_required']),false)
       and coalesce((select bool_and(jsonb_typeof(p_slice->field)='array')
                       from unnest(array['dependency_refs','declared_resource_refs',
                                         'declared_component_refs','declared_plan_step_refs']) field),false)
         ) then null
    when (p_slice->>'risk_class')=any(array['R0','R1','R2','R3'])
     and (p_slice->>'concurrency_posture')='parallel_safe'
     and p_slice->'manual_qa_required'='false'::jsonb
     and (p_slice->>'release_requirement')='not_required'
     and jsonb_array_length(p_slice->'dependency_refs')=0
     and jsonb_array_length(p_slice->'declared_resource_refs')<=1
     and jsonb_array_length(p_slice->'declared_component_refs')<=1
     and jsonb_array_length(p_slice->'declared_plan_step_refs')<=1
      then 'short'
    else 'full'
  end;
$$;


--
-- Name: engineering_receipt_design_enum(jsonb, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_enum(p_value jsonb, p_allowed text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='string'
     and coalesce((p_value#>>'{}')=any(p_allowed),false);
$$;


--
-- Name: engineering_receipt_design_identifier(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_identifier(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select jsonb_typeof(p_value)='string'
     and coalesce((p_value#>>'{}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false);
$_$;


--
-- Name: engineering_receipt_design_identifier_subset(jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_identifier_subset(p_subset jsonb, p_superset jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select coalesce(ops.engineering_receipt_identifier_array(p_subset),false)
     and jsonb_typeof(p_superset)='array'
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_superset)='array' then p_superset else '[]'::jsonb end) value
        where not coalesce(ops.engineering_receipt_design_identifier(value),false)
     )
     and not exists (
       (select value#>>'{}'
          from jsonb_array_elements(case when jsonb_typeof(p_subset)='array' then p_subset else '[]'::jsonb end) value)
       except
       (select value#>>'{}'
          from jsonb_array_elements(case when jsonb_typeof(p_superset)='array' then p_superset else '[]'::jsonb end) value)
     );
$$;


--
-- Name: engineering_receipt_design_model_steps(jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_model_steps(p_slice jsonb, p_steps jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_steps)='array'
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_steps)='array' then p_steps else '[]'::jsonb end) step
        where not coalesce(ops.engineering_receipt_exact_object(step,array[
                'input_contract_ref','output_contract_ref','rationale','responsibility_class',
                'selection_basis','step_ref']),false)
           or not coalesce(ops.engineering_receipt_design_identifier(step->'step_ref'),false)
           or not exists (
                select 1
                  from jsonb_array_elements(case when jsonb_typeof(p_slice->'declared_plan_step_refs')='array'
                                                 then p_slice->'declared_plan_step_refs' else '[]'::jsonb end) declared
                 where declared=step->'step_ref')
           or coalesce((step->>'responsibility_class')=any(array[
                'identity','policy','permissions','state','validation','idempotency','execution']),false)
           or not coalesce(ops.engineering_receipt_design_enum(step->'responsibility_class',array[
                'classification','extraction','summarization','ranking','drafting','disambiguation']),false)
           or not coalesce(ops.engineering_receipt_design_identifier(step->'input_contract_ref'),false)
           or not coalesce(ops.engineering_receipt_design_identifier(step->'output_contract_ref'),false)
           or not coalesce(ops.engineering_receipt_design_string(step->'rationale'),false)
           or not coalesce(ops.engineering_receipt_design_selection_basis(step->'selection_basis'),false)
     )
     and (select count(*)=count(distinct (step->>'step_ref'))
            from jsonb_array_elements(case when jsonb_typeof(p_steps)='array'
                                           then p_steps else '[]'::jsonb end) step);
$$;


--
-- Name: engineering_receipt_design_selection_basis(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_selection_basis(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='array'
     and coalesce(case when jsonb_typeof(p_value)='array'
                       then jsonb_array_length(p_value)>0 else false end,false)
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_value)='array' then p_value else '[]'::jsonb end) value
        where jsonb_typeof(value)<>'string'
           or not coalesce((value#>>'{}')=any(array[
                'typed_uncertainty','capability_gain','quality_gain','adaptability_gain','cost']),false)
     )
     and (select count(*)=count(distinct (value#>>'{}'))
            from jsonb_array_elements(case when jsonb_typeof(p_value)='array'
                                           then p_value else '[]'::jsonb end) value)
     and p_value<>'["cost"]'::jsonb;
$$;


--
-- Name: engineering_receipt_design_self_label_free(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_self_label_free(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='object'
     and not exists (
       select 1
         from jsonb_object_keys(case when jsonb_typeof(p_value)='object' then p_value else '{}'::jsonb end) as keys(key)
        where key=any(array['design_depth','depth','template','template_kind','complexity','complexity_class',
                            'simple','is_simple','classification','classifier_override','bypass'])
     );
$$;


--
-- Name: engineering_receipt_design_string(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_design_string(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='string' and coalesce(btrim(p_value#>>'{}')<>'',false);
$$;


--
-- Name: engineering_receipt_evidence_array(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_evidence_array(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select jsonb_typeof(p_value)='array'
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_value)='array' then p_value else '[]'::jsonb end) evidence
        where not ops.engineering_receipt_exact_object(
                evidence,array['content_digest','redaction_class','ref'])
           or not coalesce((evidence->>'ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or not coalesce(evidence->>'redaction_class'=any(array['metadata_only','redacted_evidence']),false)
           or not coalesce((evidence->>'content_digest') ~ '^sha256:[0-9a-f]{64}$',false)
     );
$_$;


--
-- Name: engineering_receipt_exact_object(jsonb, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_exact_object(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_value)='object'
     and (select array_agg(key order by key)
            from jsonb_object_keys(case when jsonb_typeof(p_value)='object' then p_value else '{}'::jsonb end) as keys(key))
         is not distinct from
         (select array_agg(key order by key) from unnest(p_keys) as keys(key));
$$;


--
-- Name: engineering_receipt_identifier_array(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_identifier_array(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select jsonb_typeof(p_value)='array'
     and not exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_value)='array' then p_value else '[]'::jsonb end) value
        where jsonb_typeof(value)<>'string'
           or not coalesce((value#>>'{}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     )
     and (select count(*)=count(distinct (value#>>'{}'))
            from jsonb_array_elements(case when jsonb_typeof(p_value)='array'
                                           then p_value else '[]'::jsonb end) value);
$_$;


--
-- Name: engineering_receipt_identifier_sets_equal(jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_receipt_identifier_sets_equal(p_left jsonb, p_right jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select coalesce(ops.engineering_receipt_identifier_array(p_left),false)
     and coalesce(ops.engineering_receipt_identifier_array(p_right),false)
     and not exists (
       (select value#>>'{}'
         from jsonb_array_elements(case when jsonb_typeof(p_left)='array' then p_left else '[]'::jsonb end) value)
       except
       (select value#>>'{}'
         from jsonb_array_elements(case when jsonb_typeof(p_right)='array' then p_right else '[]'::jsonb end) value)
     )
     and not exists (
       (select value#>>'{}'
         from jsonb_array_elements(case when jsonb_typeof(p_right)='array' then p_right else '[]'::jsonb end) value)
       except
       (select value#>>'{}'
         from jsonb_array_elements(case when jsonb_typeof(p_left)='array' then p_left else '[]'::jsonb end) value)
     );
$$;


--
-- Name: engineering_record_slice_receipt(uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_record_slice_receipt(p_envelope_id uuid, p_lease_token uuid, p_receipt jsonb, p_receipt_digest text, p_executor_actor_id uuid) RETURNS ops.engineering_slice_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare e ops.engineering_execution_envelope%rowtype; s ops.capability_agent_session%rowtype;
        j ops.job%rowtype; a ops.job_attempt%rowtype; v_checked_at timestamptz; v_append_at timestamptz;
        session_executor uuid; session_slug text; receipt_plan_digest text; receipt_plan jsonb; receipt_slice jsonb;
        receipt_outcome text; slice_count integer;
        -- V5-F03 (1/4): the bound plan's schema version, the version-dependent
        -- slice field set, the design-contract refusal token, and the whole-plan
        -- refusal token (NULL when the bound plan itself is a valid typed plan).
        plan_schema_version text; slice_fields text[]; design_refusal text;
        plan_refusal text;
        row ops.engineering_slice_receipt%rowtype;
begin
  -- One atomic seam: lineage, session, job, receipt append, and terminal job
  -- transition all succeed together or roll back together.
  select * into e from ops.engineering_execution_envelope where id=p_envelope_id;
  if not found then raise exception 'engineering envelope not found'; end if;
  if p_lease_token is null then raise exception 'engineering claim or lease is not current'; end if;
  if jsonb_typeof(p_receipt) is distinct from 'object'
     or p_receipt->>'schema_version' is distinct from 'engineering-slice-receipt.v1'
     or p_receipt_digest is null or p_receipt_digest !~ '^sha256:[0-9a-f]{64}$'
     or p_receipt_digest is distinct from
        ('sha256:'||encode(public.digest(ops.guidance_import_canonical_json(p_receipt),'sha256'),'hex'))
     or not coalesce(ops.engineering_receipt_exact_object(p_receipt,array[
       'actual_component_refs','actual_resource_refs','artifact_refs','attribution','attempt_id','checks',
       'deviations','envelope_digest','evidence_refs','executor_claim','independent_verification_required',
       'outcome','plan_digest','planned_component_refs','planned_resource_refs','reset_reconstruction',
       'schema_version','slice_ref','source_evidence'
     ]),false) then
    raise exception 'engineering receipt is malformed';
  end if;
  -- The identifier lookup above is intentionally unlocked.  From here through
  -- append we retain the global session -> actor -> lineage lock order.
  select * into s from ops.capability_agent_session where id=e.agent_session_id for update;
  if not found then raise exception 'engineering agent session is not current'; end if;
  session_executor := s.executor_actor_id;
  select actor.slug into session_slug
    from public.actor actor
   where actor.id=s.executor_actor_id and actor.active and actor.kind='automation' and actor.slug='codex'
   order by actor.id for share;
  if not found then raise exception 'engineering executor actor is not current'; end if;
  perform pg_advisory_xact_lock(hashtextextended('engineering-envelope:' || e.slice_plan_id::text || ':' || e.slice_ref,0));
  select * into e from ops.engineering_execution_envelope where id=p_envelope_id for key share;
  if not found or e.agent_session_id is distinct from s.id then
    raise exception 'engineering envelope or agent session binding changed';
  end if;
  select plan_digest,plan into receipt_plan_digest,receipt_plan
    from ops.engineering_slice_plan where id=e.slice_plan_id for key share;
  if not found then raise exception 'engineering receipt slice plan is not current'; end if;
  perform 1 from ops.work_request where id=e.work_request_id for share;
  if not found then raise exception 'engineering Work Request is not current'; end if;
  select * into j from ops.job where id=e.job_id for update;
  if not found then raise exception 'engineering claim or lease is not current'; end if;
  select * into a from ops.job_attempt
   where job_id=j.id and attempt=j.attempt and lease_token is not distinct from p_lease_token
     and state is not distinct from 'running'
   for update;
  if not found then raise exception 'engineering claim or lease is not current'; end if;
  -- statement_timestamp() is fixed at function entry and can be stale after a
  -- session/actor/lineage/job lock wait.  Sample only after all ordered locks.
  v_checked_at := clock_timestamp();
  if j.state is distinct from 'running' or j.lease_token is distinct from p_lease_token
     or j.leased_until is null or j.leased_until<v_checked_at
     or e.expires_at<=v_checked_at or s.lease_expires_at is null or s.lease_expires_at<=v_checked_at
     or (s.state is distinct from 'claimed' and s.state is distinct from 'in_progress') then
    raise exception 'engineering claim, envelope, or agent-session lease is not current';
  end if;
  if not ops.engineering_envelope_is_executable(e.id,e.job_id) then raise exception 'engineering envelope is no longer executable'; end if;
  if session_executor is null or p_executor_actor_id is distinct from session_executor then raise exception 'engineering receipt executor is not the server-bound agent session'; end if;
  if not found or p_receipt->>'plan_digest' is distinct from receipt_plan_digest
     or p_receipt->>'envelope_digest' is distinct from e.envelope_digest
     or p_receipt->>'slice_ref' is distinct from e.slice_ref
     or p_receipt->>'attempt_id' is distinct from ('attempt:'||a.attempt) then
    raise exception 'engineering receipt is not bound to the claimed envelope';
  end if;
  -- V5-F03 (2/4): 0335 pinned the bound plan to engineering-slice-plan.v1 here,
  -- which made a registered v2 plan un-receiptable.  The pin becomes an explicit
  -- closed membership test over the two accepted slice-plan versions.  A missing,
  -- non-string or unknown schema_version refuses; membership is not loosened, and
  -- the rest of the plan surface below is unchanged for both versions.
  --
  -- DELETION, outside this marker.  The single line
  --   receipt_plan->>'schema_version' is distinct from 'engineering-slice-plan.v1'
  -- at 0335:550 is removed from inside the plan exact_object block reproduced
  -- further down, which begins after this marker ends.  That is the only
  -- statement removed from 0335 anywhere in this file; nothing else in that
  -- block changes.
  plan_schema_version := receipt_plan->>'schema_version';
  if not coalesce(plan_schema_version=any(array[
       'engineering-slice-plan.v1','engineering-slice-plan.v2']),false) then
    raise exception 'engineering receipt slice plan schema version is not supported';
  end if;
  slice_fields := array[
    'baseline_evidence_refs','concurrency_posture','declared_component_refs','declared_plan_step_refs',
    'declared_resource_refs','definition_of_done','dependency_refs','forbidden_change_refs','manual_qa_required',
    'objective','ordinal','planned_checks','release_requirement','risk_class','scope_boundary','slice_ref'];
  if plan_schema_version='engineering-slice-plan.v2' then
    slice_fields := slice_fields||'design_contract'::text;
  end if;
  -- The immutable slice-plan projection is the only declaration of what the
  -- direct receipt seam may claim.  Re-validate the narrow plan surface here
  -- rather than trusting a caller-side Passport validator.
  if not coalesce(ops.engineering_receipt_exact_object(receipt_plan,array[
       'accepted_plan_revision','plan_digest','schema_version','slices','work_request'
     ]),false)
     or receipt_plan->>'plan_digest' is distinct from receipt_plan_digest
     or not coalesce(ops.engineering_receipt_exact_object(receipt_plan->'work_request',array[
       'canonical_record_digest','id','state_version'
     ]),false)
     or receipt_plan->'work_request' is distinct from jsonb_build_object(
       'id','wr:'||e.work_request_id::text,
       'state_version',e.state_version,
       'canonical_record_digest',e.canonical_record_digest)
     or not coalesce(ops.engineering_receipt_exact_object(receipt_plan->'accepted_plan_revision',array[
       'digest','id','revision'
     ]),false)
     or receipt_plan->'accepted_plan_revision' is distinct from e.envelope->'plan_revision'
     or jsonb_typeof(receipt_plan->'slices') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(receipt_plan->'slices')='array'
                          then jsonb_array_length(receipt_plan->'slices')>0 else false end,false) then
    raise exception 'engineering receipt slice plan is malformed or not bound to the envelope';
  end if;
  select count(*) into slice_count
    from jsonb_array_elements(case when jsonb_typeof(receipt_plan->'slices')='array'
                                   then receipt_plan->'slices' else '[]'::jsonb end) candidate
   where candidate->>'slice_ref'=e.slice_ref;
  if slice_count<>1 then
    raise exception 'engineering receipt slice plan does not name exactly one bound slice';
  end if;
  select candidate into receipt_slice
    from jsonb_array_elements(receipt_plan->'slices') candidate
   where candidate->>'slice_ref'=e.slice_ref;
  -- V5-F03 (3/4): the exact slice field set is now version-dependent.  For v1 it
  -- is byte-identical to 0335; for v2 it is the same 16 fields plus
  -- design_contract, so a v2 slice missing the contract and a v1 slice carrying
  -- one both refuse.  Every typing rule below is unchanged.
  if not coalesce(ops.engineering_receipt_exact_object(receipt_slice,slice_fields),false)
     or receipt_slice->>'slice_ref' is distinct from e.slice_ref
     or jsonb_typeof(receipt_slice->'ordinal') is distinct from 'number'
     or not coalesce((receipt_slice->>'ordinal') ~ '^[1-9][0-9]*$',false)
     or exists (select 1 from unnest(array['objective','definition_of_done','scope_boundary']) field
                 where jsonb_typeof(receipt_slice->field) is distinct from 'string'
                    or not coalesce(btrim(receipt_slice->>field)<>'',false))
     or not coalesce(ops.engineering_receipt_identifier_array(receipt_slice->'dependency_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(receipt_slice->'declared_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(receipt_slice->'declared_component_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(receipt_slice->'declared_plan_step_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(receipt_slice->'forbidden_change_refs'),false)
     or not coalesce(ops.engineering_receipt_evidence_array(receipt_slice->'baseline_evidence_refs'),false)
     or jsonb_typeof(receipt_slice->'planned_checks') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(receipt_slice->'planned_checks')='array'
                          then jsonb_array_length(receipt_slice->'planned_checks')>0 else false end,false)
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(receipt_slice->'planned_checks')='array'
                                        then receipt_slice->'planned_checks' else '[]'::jsonb end) planned_check
        where not coalesce(ops.engineering_receipt_exact_object(planned_check,array[
                'check_ref','evidence_requirement','failure_condition'
              ]),false)
           or not coalesce((planned_check->>'check_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or jsonb_typeof(planned_check->'failure_condition') is distinct from 'string'
           or not coalesce(btrim(planned_check->>'failure_condition')<>'',false)
           or not coalesce(planned_check->>'evidence_requirement'=any(array['redacted_evidence_required','metadata_only_sufficient']),false)
     )
     or exists (
       select 1 from jsonb_array_elements(receipt_slice->'planned_checks') planned_check
       group by planned_check->>'check_ref' having count(*)>1
     )
     or not coalesce(receipt_slice->>'concurrency_posture'=any(array['parallel_safe','serial_after_dependencies','exclusive_resource']),false)
     or jsonb_typeof(receipt_slice->'manual_qa_required') is distinct from 'boolean'
     or not coalesce(receipt_slice->>'risk_class'=any(array['R0','R1','R2','R3','R4','R5','R6']),false)
     or not coalesce(receipt_slice->>'release_requirement'=any(array['required','not_required']),false) then
    raise exception 'engineering receipt bound slice plan is not fully typed';
  end if;
  -- V5-F03 (4/4): the successor version's additional surface at the existing
  -- seam.  All three predicates are pure JSON over rows already read under the
  -- locks taken above; none takes a lock, samples a clock, reads another table,
  -- or writes anything.  A v1 receipt never reaches this branch.
  --
  -- The first two validate the ONE bound slice, exactly as 0335 validated the
  -- one bound slice.  The third validates the WHOLE stored plan, and it is here
  -- because the bound-slice checks structurally cannot reach a plan-wide fault:
  -- see WHY THE WHOLE PLAN IS VALIDATED HERE in the header.  receipt_plan is the
  -- row already read at the slice-plan FOR KEY SHARE above, so no additional row
  -- is read and the lock order is unchanged.
  if plan_schema_version='engineering-slice-plan.v2' then
    design_refusal := ops.engineering_receipt_design_contract_refusal(receipt_slice);
    if design_refusal is not null then
      raise exception 'engineering receipt bound slice design contract is invalid: %',design_refusal;
    end if;
    design_refusal := ops.engineering_receipt_design_binding_refusal(receipt_slice,e.envelope);
    if design_refusal is not null then
      raise exception 'engineering receipt bound slice design contract contradicts the server execution binding: %',design_refusal;
    end if;
    -- The whole-plan predicate lives in ops/f03-plan-ownership-validator.candidate.sql
    -- and is the SAME single statement the registration seam uses; it is called
    -- here, never restated.  If that file has not been applied this raises
    -- 'function ops.engineering_slice_plan_refusal(jsonb) does not exist' and the
    -- append is refused -- the half-installed state fails closed in either
    -- install order.  The revoke at the end of that file does not block this
    -- call: ops.engineering_record_slice_receipt is SECURITY DEFINER, so the
    -- call is made as ITS owner, and that owner is the same migration role that
    -- creates the whole-plan validator when both files are applied normally --
    -- an owner's own EXECUTE is not what a revoke from public and the four
    -- application roles removes.  Applying the two files as DIFFERENT roles
    -- would need an explicit grant and is not an intended installation.
    plan_refusal := ops.engineering_slice_plan_refusal(receipt_plan);
    if plan_refusal is not null then
      raise exception 'engineering receipt bound slice plan is not a valid typed slice plan: %',plan_refusal;
    end if;
  end if;
  receipt_outcome := p_receipt->>'outcome';
  if receipt_outcome is null or not coalesce(receipt_outcome=any(array['claimed_complete','failed','blocked','reopened']),false) then
    raise exception 'engineering receipt outcome is invalid';
  end if;
  if not coalesce(ops.engineering_receipt_identifier_array(p_receipt->'planned_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(p_receipt->'actual_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(p_receipt->'planned_component_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(p_receipt->'actual_component_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(p_receipt->'artifact_refs'),false)
     or not coalesce(ops.engineering_receipt_evidence_array(p_receipt->'evidence_refs'),false)
     or jsonb_typeof(p_receipt->'checks') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(p_receipt->'checks')='array'
                          then jsonb_array_length(p_receipt->'checks')>0 else false end,false)
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_receipt->'checks')='array'
                                        then p_receipt->'checks' else '[]'::jsonb end) receipt_check
        where not coalesce(ops.engineering_receipt_exact_object(receipt_check,array[
                'check_ref','evidence_refs','state'
              ]),false)
           or not coalesce((receipt_check->>'check_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or not coalesce(receipt_check->>'state'=any(array['passed','failed','blocked','not_run']),false)
           or not coalesce(ops.engineering_receipt_evidence_array(receipt_check->'evidence_refs'),false)
     )
     or exists (
       select 1 from jsonb_array_elements(p_receipt->'checks') receipt_check
       group by receipt_check->>'check_ref' having count(*)>1
     )
     or exists (
       select 1 from jsonb_array_elements(p_receipt->'checks') receipt_check
        where not exists (
          select 1 from jsonb_array_elements(receipt_slice->'planned_checks') planned_check
           where planned_check->>'check_ref'=receipt_check->>'check_ref'
        )
     )
     or exists (
       select 1 from jsonb_array_elements(receipt_slice->'planned_checks') planned_check
        where not exists (
          select 1 from jsonb_array_elements(p_receipt->'checks') receipt_check
           where receipt_check->>'check_ref'=planned_check->>'check_ref'
        )
     )
     or exists (
       select 1
         from jsonb_array_elements(p_receipt->'checks') receipt_check
         join jsonb_array_elements(receipt_slice->'planned_checks') planned_check
           on planned_check->>'check_ref'=receipt_check->>'check_ref'
        where receipt_check->>'state'='passed'
          and (jsonb_array_length(receipt_check->'evidence_refs')=0
               or not exists (
                 select 1 from jsonb_array_elements(receipt_check->'evidence_refs') evidence
                  where evidence->>'redaction_class'=case planned_check->>'evidence_requirement'
                    when 'redacted_evidence_required' then 'redacted_evidence' else 'metadata_only' end
               ))
     )
     or jsonb_typeof(p_receipt->'deviations') is distinct from 'array'
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(p_receipt->'deviations')='array'
                                        then p_receipt->'deviations' else '[]'::jsonb end) deviation
        where not coalesce(ops.engineering_receipt_exact_object(deviation,array[
                'category','deviation_ref','evidence_refs','impact','out_of_scope_component_refs',
                'out_of_scope_resource_refs','plan_revision_required','reason','review_state'
              ]),false)
           or not coalesce((deviation->>'deviation_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or exists (select 1 from unnest(array['category','reason','impact']) field
                       where jsonb_typeof(deviation->field) is distinct from 'string'
                          or not coalesce(btrim(deviation->>field)<>'',false))
           or jsonb_typeof(deviation->'plan_revision_required') is distinct from 'boolean'
           or not coalesce(ops.engineering_receipt_evidence_array(deviation->'evidence_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_resource_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_component_refs'),false)
           or not coalesce(deviation->>'review_state'=any(array['unreviewed','reviewed','resolved']),false)
     )
     or exists (
       select 1 from jsonb_array_elements(p_receipt->'deviations') deviation
       group by deviation->>'deviation_ref' having count(*)>1
     )
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          p_receipt->'planned_resource_refs',receipt_slice->'declared_resource_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_sets_equal(
          p_receipt->'planned_component_refs',receipt_slice->'declared_component_refs'),false)
     or exists (
       select 1 from jsonb_array_elements(p_receipt->'actual_resource_refs') actual_ref
        where not exists (
          select 1 from jsonb_array_elements(receipt_slice->'declared_resource_refs') declared_ref
           where declared_ref=actual_ref
        ) and not exists (
          select 1 from jsonb_array_elements(p_receipt->'deviations') deviation,
                        jsonb_array_elements(deviation->'out_of_scope_resource_refs') approved_ref
           where deviation->>'review_state'='resolved' and approved_ref=actual_ref
        )
     )
     or exists (
       select 1 from jsonb_array_elements(p_receipt->'actual_component_refs') actual_ref
        where not exists (
          select 1 from jsonb_array_elements(receipt_slice->'declared_component_refs') declared_ref
           where declared_ref=actual_ref
        ) and not exists (
          select 1 from jsonb_array_elements(p_receipt->'deviations') deviation,
                        jsonb_array_elements(deviation->'out_of_scope_component_refs') approved_ref
           where deviation->>'review_state'='resolved' and approved_ref=actual_ref
        )
     )
     or (receipt_outcome='claimed_complete' and (
       jsonb_array_length(p_receipt->'artifact_refs')=0
       or jsonb_array_length(p_receipt->'evidence_refs')=0
       or exists (select 1 from jsonb_array_elements(p_receipt->'checks') receipt_check
                   where receipt_check->>'state' is distinct from 'passed')
     ))
     or not coalesce(ops.engineering_receipt_exact_object(p_receipt->'source_evidence',array[
          'branch_ref','evidence_refs','source_sha','worktree_ref'
        ]),false)
     or exists (select 1 from unnest(array['worktree_ref','branch_ref','source_sha']) field
                 where jsonb_typeof(p_receipt->'source_evidence'->field) is distinct from 'string'
                    or not coalesce(btrim(p_receipt->'source_evidence'->>field)<>'',false)
                    or (field<>'source_sha' and not coalesce(
                         (p_receipt->'source_evidence'->>field) ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)))
     or not coalesce(ops.engineering_receipt_evidence_array(p_receipt->'source_evidence'->'evidence_refs'),false)
     or not coalesce(ops.engineering_receipt_exact_object(p_receipt->'reset_reconstruction',array[
          'fresh_session','inherited_transcript_used','reconstruction_free','remediation_action'
        ]),false)
     or p_receipt->'reset_reconstruction'->'fresh_session' is distinct from 'true'::jsonb
     or p_receipt->'reset_reconstruction'->'inherited_transcript_used' is distinct from 'false'::jsonb
     or jsonb_typeof(p_receipt->'reset_reconstruction'->'reconstruction_free') is distinct from 'boolean'
     or (p_receipt->'reset_reconstruction'->'reconstruction_free'='false'::jsonb and
         (jsonb_typeof(p_receipt->'reset_reconstruction'->'remediation_action') is distinct from 'string'
          or not coalesce(btrim(p_receipt->'reset_reconstruction'->>'remediation_action')<>'',false)))
     or (p_receipt->'reset_reconstruction'->'reconstruction_free'='true'::jsonb and
         p_receipt->'reset_reconstruction'->'remediation_action' is distinct from 'null'::jsonb
         and (jsonb_typeof(p_receipt->'reset_reconstruction'->'remediation_action') is distinct from 'string'
              or not coalesce(btrim(p_receipt->'reset_reconstruction'->>'remediation_action')<>'',false)))
     or not coalesce(ops.engineering_receipt_exact_object(p_receipt->'executor_claim',array[
          'claim_state','claimed_at','claimed_by'
        ]),false)
     or p_receipt->'executor_claim'->>'claim_state' is distinct from 'executor_claim'
     or not coalesce((p_receipt->'executor_claim'->>'claimed_by') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     or jsonb_typeof(p_receipt->'executor_claim'->'claimed_at') is distinct from 'string'
     or not coalesce(btrim(p_receipt->'executor_claim'->>'claimed_at')<>'',false)
     or p_receipt->'independent_verification_required' is distinct from 'true'::jsonb
     or not coalesce(ops.engineering_receipt_exact_object(p_receipt->'attribution',array[
          'actor_ref','adapter_ref','session_ref'
        ]),false)
     or exists (select 1 from unnest(array['actor_ref','session_ref','adapter_ref']) field
                 where not coalesce((p_receipt->'attribution'->>field) ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false))
     or session_slug is null or p_receipt->'executor_claim'->>'claimed_by' is distinct from session_slug
     or e.envelope#>>'{server_binding,identity,agent_principal_id}' is null
     or e.envelope#>>'{agent_session,id}' is null
     or e.envelope#>>'{server_binding,adapter,adapter_id}' is null
     or p_receipt->'attribution'->>'actor_ref' is distinct from e.envelope#>>'{server_binding,identity,agent_principal_id}'
     or p_receipt->'attribution'->>'session_ref' is distinct from e.envelope#>>'{agent_session,id}'
     or p_receipt->'attribution'->>'adapter_ref' is distinct from e.envelope#>>'{server_binding,adapter,adapter_id}' then
    raise exception 'engineering receipt typed contract is invalid';
  end if;
  -- No receipt may cross the append boundary on authority sampled only before
  -- JSON validation.  All rows remain locked from the first ordered check.
  v_append_at := clock_timestamp();
  if j.state is distinct from 'running' or j.lease_token is distinct from p_lease_token
     or j.leased_until is null or j.leased_until<v_append_at
     or e.expires_at<=v_append_at or s.lease_expires_at is null or s.lease_expires_at<=v_append_at
     or (s.state is distinct from 'claimed' and s.state is distinct from 'in_progress') then
    raise exception 'engineering claim, envelope, or agent-session lease is not current at receipt append';
  end if;
  if not ops.engineering_envelope_is_executable(e.id,e.job_id) then
    raise exception 'engineering envelope is no longer executable at receipt append';
  end if;
  insert into ops.engineering_slice_receipt(job_attempt_id,envelope_id,work_request_id,slice_ref,attempt_id,executor_actor_id,receipt_digest,outcome,receipt) values(a.id,e.id,e.work_request_id,e.slice_ref,p_receipt->>'attempt_id',session_executor,p_receipt_digest,p_receipt->>'outcome',p_receipt) returning * into row;
  return row;
end $_$;


--
-- Name: FUNCTION engineering_record_slice_receipt(p_envelope_id uuid, p_lease_token uuid, p_receipt jsonb, p_receipt_digest text, p_executor_actor_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.engineering_record_slice_receipt(p_envelope_id uuid, p_lease_token uuid, p_receipt jsonb, p_receipt_digest text, p_executor_actor_id uuid) IS 'Lease-bound typed engineering slice receipt append. Accepts engineering-slice-plan.v1 exactly as before and engineering-slice-plan.v2 with its closed per-slice design_contract. For v2 the whole bound slice plan must also be a valid typed plan under ops.engineering_slice_plan_refusal, so a plan registered around the caller-side validators cannot become receiptable. Unknown slice-plan or design-contract versions are refused, never defaulted.';


--
-- Name: engineering_slice_plan; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.engineering_slice_plan (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    accepted_plan_id uuid NOT NULL,
    accepted_plan_hash text NOT NULL,
    work_request_version integer NOT NULL,
    plan_digest text NOT NULL,
    plan jsonb NOT NULL,
    idempotency_key uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT engineering_slice_plan_accepted_plan_hash_check CHECK ((accepted_plan_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT engineering_slice_plan_plan_check CHECK ((jsonb_typeof(plan) = 'object'::text)),
    CONSTRAINT engineering_slice_plan_plan_digest_check CHECK ((plan_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT engineering_slice_plan_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: TABLE engineering_slice_plan; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.engineering_slice_plan IS 'Typed engineering-slice projection over one accepted sourced plan. It is never an alternate Work Request or acceptance authority.';


--
-- Name: engineering_register_slice_plan(text, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_register_slice_plan(p_work_request text, p_plan jsonb, p_plan_digest text, p_idempotency_key uuid) RETURNS ops.engineering_slice_plan
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare source jsonb; row ops.engineering_slice_plan%rowtype;
        -- V5-F03: the whole-plan refusal token, NULL when the plan is accepted.
        plan_refusal text;
begin
  source := ops.engineering_admission_source(p_work_request);
  if source is null then raise exception 'engineering admission requires a current accepted ready plan'; end if;
  if p_plan_digest !~ '^sha256:[0-9a-f]{64}$' then raise exception 'invalid engineering slice plan digest'; end if;
  if p_plan->'work_request'->>'id' <> source->'work_request'->>'id'
     or (p_plan->'work_request'->>'state_version')::integer <> (source->'work_request'->>'version')::integer
     or p_plan->'accepted_plan_revision'->>'id' <> source->'accepted_plan'->>'plan_ref'
     or p_plan->'accepted_plan_revision'->>'digest' <> source->'accepted_plan'->>'digest'
     or (p_plan->'accepted_plan_revision'->>'revision')::integer <> (source->'accepted_plan'->>'revision')::integer
     or p_plan->>'plan_digest' <> p_plan_digest then
    raise exception 'engineering slice plan is not bound to the exact accepted Work Request and plan';
  end if;
  -- V5-F03: the whole-plan check the database has never had.  It runs AFTER the
  -- five binding comparisons above, so every existing refusal keeps its exact
  -- text and its exact precedence, and it runs BEFORE the insert, so a refused
  -- plan is never written.  It is a pure JSON predicate: it takes no lock,
  -- samples no clock and reads no table, so the transaction's behavior around
  -- it is unchanged.
  --
  -- For engineering-slice-plan.v1 this returns NULL as soon as it has checked
  -- the top-level shape and version, so a v1 registration is unchanged; see THE
  -- v1 BOUNDARY in the header for the two narrow exceptions.  For
  -- engineering-slice-plan.v2 it is the full requirePlan predicate, including
  -- the plan_digest-binds-content check, which is what closes the direct
  -- carr_writer bypass of the caller-side validators for plans stored FROM NOW
  -- ON.  Plans already stored are covered at the receipt seam by the same
  -- function; see REGISTRATION ALONE IS NOT ENOUGH in the header.
  --
  -- It runs before the ON CONFLICT ... DO NOTHING replay below, so re-asserting
  -- an already-stored malformed v2 plan under its original idempotency key
  -- raises rather than replaying.  See consequence (ii) in the header.
  plan_refusal := ops.engineering_slice_plan_refusal(p_plan);
  if plan_refusal is not null then
    raise exception 'engineering slice plan is not a valid typed slice plan: %', plan_refusal;
  end if;
  insert into ops.engineering_slice_plan
    (work_request_id,accepted_plan_id,accepted_plan_hash,work_request_version,plan_digest,plan,idempotency_key)
  values (regexp_replace(source->'work_request'->>'id', '^wr:', '')::uuid,
          (source->'accepted_plan'->>'record_id')::uuid,
          source->'accepted_plan'->>'digest',(source->'work_request'->>'version')::integer,
          p_plan_digest,p_plan,p_idempotency_key)
  on conflict (idempotency_key) do nothing
  returning * into row;
  if row.id is null then
    select * into row from ops.engineering_slice_plan where idempotency_key=p_idempotency_key;
    if row.plan_digest <> p_plan_digest or row.plan <> p_plan then
      raise exception 'engineering slice plan idempotency key was reused with different content';
    end if;
  end if;
  return row;
end $_$;


--
-- Name: FUNCTION engineering_register_slice_plan(p_work_request text, p_plan jsonb, p_plan_digest text, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.engineering_register_slice_plan(p_work_request text, p_plan jsonb, p_plan_digest text, p_idempotency_key uuid) IS 'Register one typed Engineering Slice Plan as an immutable projection of the exact accepted sourced plan. Every 0310 binding, idempotency and refusal behavior is unchanged; an engineering-slice-plan.v2 plan is additionally held to the whole-plan contract by ops.engineering_slice_plan_refusal, which closes the direct carr_writer bypass of the caller-side validators.';


--
-- Name: engineering_retire_permanently_ineligible_jobs(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_retire_permanently_ineligible_jobs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare retired integer;
begin
  with doomed as (
    select j.id,j.attempt,case when e.id is null then 'engineering_orphaned_job' else 'engineering_superseded_predecessor' end reason
      from ops.job j left join ops.engineering_execution_envelope e on e.job_id=j.id
     where j.definition_key='engineering-slice' and j.definition_version=1
       and j.state in ('queued','retry_wait')
       and (e.id is null or exists(select 1 from ops.engineering_execution_envelope successor where successor.supersedes_envelope_id=e.id))
     for update of j skip locked
  ), changed as (
    update ops.job j set state='dead_lettered',ended_at=now(),lease_owner=null,lease_token=null,
      leased_until=null,last_failure_class=d.reason,last_failure_detail='permanently ineligible engineering job',updated_at=now()
      from doomed d where j.id=d.id returning j.id,j.attempt,d.reason
  ), receipts as (
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    select id,attempt,'dead_letter','engineering-currentness:'||id::text||':'||attempt::text,
      jsonb_build_object('reason',reason,'derived_by','ops.engineering_retire_permanently_ineligible_jobs') from changed
    returning 1
  ) select count(*) into retired from receipts;
  return retired;
end $$;


--
-- Name: engineering_safe_timestamptz(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_safe_timestamptz(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
begin
  return p_value::timestamptz;
exception when others then
  return null;
end $$;


--
-- Name: engineering_slice_plan_refusal(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_slice_plan_refusal(p_plan jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_schema_version text; v_slice_fields text[]; v_slice jsonb; v_slice_ref text;
        v_design_refusal text; v_token text; v_remaining text[]; v_peeled text[];
begin
  if jsonb_typeof(p_plan) is distinct from 'object' then return 'plan'; end if;
  if not coalesce(ops.engineering_receipt_exact_object(p_plan,array[
       'accepted_plan_revision','plan_digest','schema_version','slices','work_request']),false) then
    return 'plan.shape';
  end if;
  v_schema_version := p_plan->>'schema_version';
  if not coalesce(v_schema_version=any(array[
       'engineering-slice-plan.v1','engineering-slice-plan.v2']),false) then
    return 'plan.schema_version';
  end if;
  v_slice_fields := ops.engineering_slice_plan_slice_fields(v_schema_version);
  if v_slice_fields is null then return 'plan.schema_version'; end if;
  -- THE v1 BOUNDARY.  See the header: an accepted v1 plan is not put through the
  -- successor version's whole-plan rules, so a v1 registration keeps its exact
  -- 0310 behavior from here on.
  if v_schema_version is distinct from 'engineering-slice-plan.v2' then
    return null;
  end if;

  -- ---- plan bindings ------------------------------------------------------
  if not coalesce(ops.engineering_receipt_exact_object(p_plan->'work_request',array[
       'canonical_record_digest','id','state_version']),false) then
    return 'plan.work_request';
  end if;
  if not coalesce((p_plan#>>'{work_request,id}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false) then
    return 'plan.work_request.id';
  end if;
  if not coalesce((p_plan#>>'{work_request,canonical_record_digest}') ~ '^sha256:[0-9a-f]{64}$',false) then
    return 'plan.work_request.canonical_record_digest';
  end if;
  -- The regex is how 0335:583 already spells "a positive integer": it refuses 0,
  -- a negative, and a non-integral spelling such as 1.0 that jsonb would keep.
  if jsonb_typeof(p_plan#>'{work_request,state_version}') is distinct from 'number'
     or not coalesce((p_plan#>>'{work_request,state_version}') ~ '^[1-9][0-9]*$',false) then
    return 'plan.work_request.state_version';
  end if;
  if not coalesce(ops.engineering_receipt_exact_object(p_plan->'accepted_plan_revision',array[
       'digest','id','revision']),false) then
    return 'plan.accepted_plan_revision';
  end if;
  if not coalesce((p_plan#>>'{accepted_plan_revision,id}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false) then
    return 'plan.accepted_plan_revision.id';
  end if;
  if not coalesce((p_plan#>>'{accepted_plan_revision,digest}') ~ '^sha256:[0-9a-f]{64}$',false) then
    return 'plan.accepted_plan_revision.digest';
  end if;
  if jsonb_typeof(p_plan#>'{accepted_plan_revision,revision}') is distinct from 'number'
     or not coalesce((p_plan#>>'{accepted_plan_revision,revision}') ~ '^[1-9][0-9]*$',false) then
    return 'plan.accepted_plan_revision.revision';
  end if;
  if not coalesce((p_plan->>'plan_digest') ~ '^sha256:[0-9a-f]{64}$',false) then
    return 'plan.plan_digest';
  end if;
  if jsonb_typeof(p_plan->'slices') is distinct from 'array'
     or not coalesce(case when jsonb_typeof(p_plan->'slices')='array'
                          then jsonb_array_length(p_plan->'slices')>0 else false end,false) then
    return 'plan.slices';
  end if;

  -- ---- every slice, closed and fully typed --------------------------------
  for v_slice in select value from jsonb_array_elements(p_plan->'slices') loop
    v_slice_ref := coalesce(v_slice->>'slice_ref','<unnamed>');
    if jsonb_typeof(v_slice) is distinct from 'object' then
      return 'slices['||v_slice_ref||'].shape';
    end if;
    -- The agent may never hand the design-depth classifier its own answer.  The
    -- closed field set below already refuses unknown keys; this is the named
    -- refusal, and it is tested before the shape exactly as requirePlan tests
    -- refuseSelfLabel before its own closed-field-set comparison.
    if not coalesce(ops.engineering_receipt_design_self_label_free(v_slice),false) then
      return 'slices['||v_slice_ref||'].design_depth_self_label';
    end if;
    if not coalesce(ops.engineering_receipt_exact_object(v_slice,v_slice_fields),false) then
      return 'slices['||v_slice_ref||'].shape';
    end if;
    if not coalesce(v_slice_ref ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false) then
      return 'slices['||v_slice_ref||'].slice_ref';
    end if;
    if jsonb_typeof(v_slice->'ordinal') is distinct from 'number'
       or not coalesce((v_slice->>'ordinal') ~ '^[1-9][0-9]*$',false) then
      return 'slices['||v_slice_ref||'].ordinal';
    end if;
    if exists (select 1 from unnest(array['objective','definition_of_done','scope_boundary']) field
                where jsonb_typeof(v_slice->field) is distinct from 'string'
                   or not coalesce(btrim(v_slice->>field)<>'',false)) then
      return 'slices['||v_slice_ref||'].text_fields';
    end if;
    if not coalesce((v_slice->>'concurrency_posture')=any(array[
         'parallel_safe','serial_after_dependencies','exclusive_resource']),false)
       or not coalesce((v_slice->>'risk_class')=any(array['R0','R1','R2','R3','R4','R5','R6']),false)
       or not coalesce((v_slice->>'release_requirement')=any(array['required','not_required']),false)
       or jsonb_typeof(v_slice->'manual_qa_required') is distinct from 'boolean' then
      return 'slices['||v_slice_ref||'].enums';
    end if;
    if exists (select 1 from unnest(array['dependency_refs','declared_resource_refs',
                                          'declared_component_refs','declared_plan_step_refs',
                                          'forbidden_change_refs']) field
                where not coalesce(ops.engineering_plan_identifier_list(v_slice->field),false)) then
      return 'slices['||v_slice_ref||'].identifier_arrays';
    end if;
    if not coalesce(ops.engineering_receipt_evidence_array(v_slice->'baseline_evidence_refs'),false) then
      return 'slices['||v_slice_ref||'].baseline_evidence_refs';
    end if;
    if jsonb_typeof(v_slice->'planned_checks') is distinct from 'array'
       or not coalesce(case when jsonb_typeof(v_slice->'planned_checks')='array'
                            then jsonb_array_length(v_slice->'planned_checks')>0 else false end,false)
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(v_slice->'planned_checks')='array'
                                          then v_slice->'planned_checks' else '[]'::jsonb end) planned_check
          where not coalesce(ops.engineering_receipt_exact_object(planned_check,array[
                  'check_ref','evidence_requirement','failure_condition']),false)
             or not coalesce((planned_check->>'check_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
             or jsonb_typeof(planned_check->'failure_condition') is distinct from 'string'
             or not coalesce(btrim(planned_check->>'failure_condition')<>'',false)
             or not coalesce((planned_check->>'evidence_requirement')=any(array[
                  'redacted_evidence_required','metadata_only_sufficient']),false))
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(v_slice->'planned_checks')='array'
                                          then v_slice->'planned_checks' else '[]'::jsonb end) planned_check
          group by planned_check->>'check_ref' having count(*)>1) then
      return 'slices['||v_slice_ref||'].planned_checks';
    end if;
    -- Every dependency must name a slice this same plan declares.  Direction is
    -- not constrained here; a self-edge is caught by the cycle test below.
    if exists (
         select 1
           from jsonb_array_elements_text(case when jsonb_typeof(v_slice->'dependency_refs')='array'
                                               then v_slice->'dependency_refs' else '[]'::jsonb end) dep
          where not exists (select 1 from jsonb_array_elements(p_plan->'slices') other
                             where other->>'slice_ref'=dep)) then
      return 'slices['||v_slice_ref||'].dependency_refs_unknown';
    end if;
    -- The closed Q046.D1 contract, from its single authority in candidate 2.
    -- The envelope-binding comparison is deliberately NOT run here: there is no
    -- envelope at registration time, and admission is where that comparison
    -- belongs in both source validators.
    v_design_refusal := ops.engineering_receipt_design_contract_refusal(v_slice);
    if v_design_refusal is not null then
      return 'slices['||v_slice_ref||'].'||v_design_refusal;
    end if;
  end loop;

  -- ---- plan-wide uniqueness -----------------------------------------------
  -- EVERY interpolated value in the plan-wide tokens below is wrapped in
  -- coalesce.  Each of them is already known to be a non-NULL typed identifier
  -- or number by the time these run, because the per-slice loop above ran
  -- ops.engineering_receipt_design_contract_refusal and the closed field/typing
  -- tests first.  That makes the guard POSITIONAL: an SQL NULL anywhere in a
  -- token would make the whole concatenation NULL, and a NULL v_token is read as
  -- "accept".  coalesce makes the fail-closed local instead, so a future
  -- reordering of this function cannot turn a refusal into a silent acceptance.
  select 'plan.duplicate_slice_ref['||coalesce(candidate->>'slice_ref','<unnamed>')||']' into v_token
    from jsonb_array_elements(p_plan->'slices') candidate
   group by candidate->>'slice_ref' having count(*)>1
   order by 1 limit 1;
  if v_token is not null then return v_token; end if;

  select 'plan.duplicate_ordinal['||coalesce(min(candidate->>'ordinal'),'<unnamed>')||']' into v_token
    from jsonb_array_elements(p_plan->'slices') candidate
   group by candidate->'ordinal' having count(*)>1
   order by 1 limit 1;
  if v_token is not null then return v_token; end if;

  -- ---- acyclic dependencies ------------------------------------------------
  -- Kahn's peel: repeatedly drop every slice that no longer waits on a slice
  -- still in the set.  A set that stops shrinking is exactly a cycle, and a
  -- self-edge is a one-member cycle.  Every dependency ref is already known to
  -- name a declared slice, so nothing outside the set can hold a member.  The
  -- loop is bounded by the slice count: each pass either shrinks the set or
  -- exits.
  select array_agg(candidate->>'slice_ref' order by candidate->>'slice_ref') into v_remaining
    from jsonb_array_elements(p_plan->'slices') candidate;
  loop
    select coalesce(array_agg(ref order by ref),'{}'::text[]) into v_peeled
      from unnest(v_remaining) ref
     where exists (
       select 1
         from jsonb_array_elements(p_plan->'slices') candidate,
              jsonb_array_elements_text(case when jsonb_typeof(candidate->'dependency_refs')='array'
                                             then candidate->'dependency_refs' else '[]'::jsonb end) dep
        where candidate->>'slice_ref'=ref and dep=any(v_remaining));
    exit when coalesce(array_length(v_peeled,1),0)=0;
    exit when array_length(v_peeled,1)=array_length(v_remaining,1);
    v_remaining := v_peeled;
  end loop;
  if coalesce(array_length(v_peeled,1),0)>0 then
    return 'plan.dependency_cycle['||array_to_string(v_peeled,',')||']';
  end if;

  -- ---- seam authority (Q063.D1 / Q122.D1) ---------------------------------
  -- One seam may have at most one owning slice, may be retired at most once, and
  -- may not be built on by one slice while another retires it.
  select 'plan.seam_duplicate_authority['
         ||coalesce(candidate#>>'{design_contract,seam_decision,target_seam_ref}','<unnamed>')||']'
    into v_token
    from jsonb_array_elements(p_plan->'slices') candidate
   where coalesce((candidate#>>'{design_contract,seam_decision,mode}')=any(array['new_module','replace']),false)
   group by candidate#>>'{design_contract,seam_decision,target_seam_ref}'
   having count(*)>1
   order by 1 limit 1;
  if v_token is not null then return v_token; end if;

  select 'plan.seam_retired_twice['||coalesce(retired_ref,'<unnamed>')||']' into v_token
    from jsonb_array_elements(p_plan->'slices') candidate,
         jsonb_array_elements_text(
           case when jsonb_typeof(candidate#>'{design_contract,seam_decision,replaced_seam_refs}')='array'
                then candidate#>'{design_contract,seam_decision,replaced_seam_refs}'
                else '[]'::jsonb end) retired_ref
   group by retired_ref having count(*)>1
   order by 1 limit 1;
  if v_token is not null then return v_token; end if;

  select 'plan.seam_half_replacement['
         ||coalesce(candidate#>>'{design_contract,seam_decision,target_seam_ref}','<unnamed>')||']'
    into v_token
    from jsonb_array_elements(p_plan->'slices') candidate
   where coalesce((candidate#>>'{design_contract,seam_decision,mode}')=any(array['reuse','extend']),false)
     and exists (
       select 1
         from jsonb_array_elements(p_plan->'slices') other,
              jsonb_array_elements_text(
                case when jsonb_typeof(other#>'{design_contract,seam_decision,replaced_seam_refs}')='array'
                     then other#>'{design_contract,seam_decision,replaced_seam_refs}'
                     else '[]'::jsonb end) retired_ref
        where retired_ref = candidate#>>'{design_contract,seam_decision,target_seam_ref}')
   order by 1 limit 1;
  if v_token is not null then return v_token; end if;

  -- ---- parallel-safe resource isolation -----------------------------------
  -- Two parallel_safe slices that both declare one resource are two
  -- contradictory statements sealed in one plan -- each has already had to state
  -- isolation.shared_resource_refs as empty -- and both become admissible at
  -- once.  A dependency edge in either direction removes the contradiction, so
  -- the transitive closure is consulted before refusing.  Nothing here restricts
  -- a serial_after_dependencies or exclusive_resource posture, which is how
  -- contention is meant to be declared.
  --
  -- The recursive closure is only reached after the cycle test above returned
  -- clean, so the edge graph is a DAG and the UNION recursion terminates.
  select q.refusal into v_token from (
    with recursive edge(src,dst) as (
      select candidate->>'slice_ref', dep
        from jsonb_array_elements(p_plan->'slices') candidate,
             jsonb_array_elements_text(case when jsonb_typeof(candidate->'dependency_refs')='array'
                                            then candidate->'dependency_refs' else '[]'::jsonb end) dep
    ), closure(src,dst) as (
      select src,dst from edge
      union
      select c.src,e.dst from closure c join edge e on e.src=c.dst
    ), owner_row(slice_ref,resource_ref) as (
      select distinct candidate->>'slice_ref', res
        from jsonb_array_elements(p_plan->'slices') candidate,
             jsonb_array_elements_text(case when jsonb_typeof(candidate->'declared_resource_refs')='array'
                                            then candidate->'declared_resource_refs' else '[]'::jsonb end) res
       where candidate->>'concurrency_posture'='parallel_safe'
    )
    select 'plan.parallel_resource_conflict['||coalesce(a.resource_ref,'<unnamed>')||':'
             ||coalesce(a.slice_ref,'<unnamed>')||','||coalesce(b.slice_ref,'<unnamed>')||']'
             as refusal
      from owner_row a
      join owner_row b on b.resource_ref=a.resource_ref and a.slice_ref<b.slice_ref
     where not exists (select 1 from closure k where k.src=a.slice_ref and k.dst=b.slice_ref)
       and not exists (select 1 from closure k where k.src=b.slice_ref and k.dst=a.slice_ref)
     order by 1
     limit 1
  ) q;
  if v_token is not null then return v_token; end if;

  -- ---- the digest must bind the content ------------------------------------
  -- This is the check the database has never had.  It reuses the EXISTING
  -- canonicalization, ops.guidance_import_canonical_json (db/schema.sql:9274),
  -- which is the same function the receipt seam already digests receipts with at
  -- 0335:491 -- no second canonicalization authority is created here.  It sorts
  -- object keys with collate "C" and emits jsonb's own scalar spellings, which is
  -- what canonicalDigest (engineering-runtime.js) and base.canonical_digest do.
  --
  -- KNOWN NARROW EXPOSURE, stated rather than assumed.  The receipt path proves
  -- this equivalence for strings, booleans, nulls, objects and arrays, because
  -- every appended receipt has passed 0335:490.  It does NOT prove it for
  -- NUMBERS: a receipt carries none, and a plan carries three (ordinal,
  -- work_request.state_version, accepted_plan_revision.revision).  jsonb
  -- preserves numeric scale, so a producer emitting 1.0 rather than 1 would be
  -- refused here where JSON.stringify would have written 1.  Every one of those
  -- three fields is separately pinned above to ^[1-9][0-9]*$, so a plan that
  -- could hit that divergence is already refused by the time this runs, and the
  -- companion fixture registers a positive v2 plan whose acceptance depends on
  -- this equivalence holding.
  if ('sha256:'||encode(public.digest(
        ops.guidance_import_canonical_json(p_plan - 'plan_digest'),'sha256'),'hex'))
     is distinct from (p_plan->>'plan_digest') then
    return 'plan.plan_digest_does_not_bind_content';
  end if;

  return null;
end $_$;


--
-- Name: FUNCTION engineering_slice_plan_refusal(p_plan jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.engineering_slice_plan_refusal(p_plan jsonb) IS 'Whole-plan validator for a typed engineering slice plan. Returns NULL when the plan is accepted, otherwise a stable refusal token. engineering-slice-plan.v1 is accepted after its top-level shape and version only, so registered v1 plans are not retroactively upgraded; engineering-slice-plan.v2 is held to the full closed plan/slice/design-contract rules, unique ordinals, acyclic dependencies, unique seam authority, parallel-safe resource isolation, and a plan_digest that binds its own canonical content. Unknown slice-plan and design-contract versions are refused, never defaulted. It reads no table, takes no lock and writes nothing, and it is the single statement of those rules for both callers: ops.engineering_register_slice_plan (new plans) and ops.engineering_record_slice_receipt (already-stored plans, before append).';


--
-- Name: engineering_slice_plan_slice_fields(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_slice_plan_slice_fields(p_schema_version text) RETURNS text[]
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select case p_schema_version
    when 'engineering-slice-plan.v1' then array[
      'baseline_evidence_refs','concurrency_posture','declared_component_refs','declared_plan_step_refs',
      'declared_resource_refs','definition_of_done','dependency_refs','forbidden_change_refs','manual_qa_required',
      'objective','ordinal','planned_checks','release_requirement','risk_class','scope_boundary','slice_ref']
    when 'engineering-slice-plan.v2' then array[
      'baseline_evidence_refs','concurrency_posture','declared_component_refs','declared_plan_step_refs',
      'declared_resource_refs','definition_of_done','dependency_refs','forbidden_change_refs','manual_qa_required',
      'objective','ordinal','planned_checks','release_requirement','risk_class','scope_boundary','slice_ref',
      'design_contract']
    else null
  end;
$$;


--
-- Name: FUNCTION engineering_slice_plan_slice_fields(p_schema_version text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.engineering_slice_plan_slice_fields(p_schema_version text) IS 'The exact accepted slice field set for one engineering-slice-plan schema version. NULL means the version is unsupported; every caller treats NULL as a refusal.';


--
-- Name: engineering_stale_contract_fence_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.engineering_stale_contract_fence_immutable() RETURNS trigger
    LANGUAGE plpgsql
