--
-- Name: foundation_assurance_producer_material(text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_producer_material(p_verb text, p_identity jsonb, p_runtime_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_actor uuid; v_evidence ops.foundation_assurance_evidence%rowtype; v_draft uuid;
        v_manifest jsonb; v_subject jsonb; v_comparator jsonb; v_members jsonb; v_coverage jsonb;
begin
  v_actor:=ops.foundation_assurance_require_seat(p_verb,p_identity);
  if p_runtime_binding->>'schema_version'<>'doctorcre-v5-foundation-assurance-runtime-binding.v1'
     or p_runtime_binding->>'environment'<>'production'
     or p_runtime_binding->>'provider'<>'cloudflare-workers'
     or coalesce(p_runtime_binding->>'source_sha','') !~ '^[0-9a-f]{40}$'
     or coalesce(p_runtime_binding->>'provider_version','') !~ '^[0-9a-f-]{36}$' then
    raise exception 'foundation assurance runtime binding is unavailable';
  end if;
  select * into v_evidence from ops.foundation_assurance_evidence
   where source_sha=p_runtime_binding->>'source_sha'
     and final_provider_version=(p_runtime_binding->>'provider_version')::uuid
   order by stored_at desc limit 1;
  if not found then raise exception 'foundation assurance evidence is unavailable for the serving Worker'; end if;
  select ops.benchmark_current_accepted_draft(ops.foundation_assurance_benchmark_ref()) into v_draft;
  if v_draft is null then raise exception 'foundation assurance benchmark has not been accepted'; end if;
  v_manifest:=ops.foundation_assurance_accepted_manifest(v_draft);
  v_subject:=ops.foundation_assurance_subject_maker(v_draft);
  if v_manifest is null or v_subject is null
     or v_manifest->>'benchmark_manifest_digest' is distinct from v_evidence.benchmark_payload_digest then
    raise exception 'foundation assurance accepted benchmark provenance is unavailable';
  end if;
  if p_verb='produce-foundation-assurance-benchmark-coverage' then
    return jsonb_build_object('config',v_evidence.config,'evidence',v_evidence.evidence,
      'accepted_manifest',v_manifest,'subject_maker_identity',v_subject,
      'observed_at',to_jsonb(clock_timestamp()));
  elsif ops.foundation_assurance_expected_step(p_verb) is not null then
    select value into v_comparator from jsonb_array_elements(v_evidence.evidence->'comparators')
     where value->>'id'=ops.foundation_assurance_expected_comparator(p_verb);
    if v_comparator is null then raise exception 'foundation assurance comparator is unavailable'; end if;
    return jsonb_build_object('config',v_evidence.config,'evidence',v_evidence.evidence,
      'accepted_manifest',v_manifest,'subject_maker_identity',v_subject,
      'comparator',v_comparator,'observed_at',to_jsonb(clock_timestamp()));
  elsif p_verb='record-foundation-assurance-minimum-outcome' then
    select artifact->'fact' into v_coverage from ops.foundation_assurance_production
     where evidence_digest=v_evidence.evidence_digest and kind='benchmark_coverage';
    select jsonb_agg(artifact order by verb collate "C") into v_members
      from ops.foundation_assurance_production where evidence_digest=v_evidence.evidence_digest and kind='member_receipt';
    if v_coverage is null or jsonb_array_length(coalesce(v_members,'[]'::jsonb))<>7 then
      raise exception 'foundation assurance predecessor production is incomplete';
    end if;
    return jsonb_build_object('config',v_evidence.config,'evidence',v_evidence.evidence,
      'accepted_manifest',v_manifest,'subject_maker_identity',v_subject,
      'coverage_fact',v_coverage,'member_receipts',v_members,
      'gate_zero',ops.benchmark_gate_zero_outcome(),'observed_at',to_jsonb(now()));
  end if;
  raise exception 'unknown foundation assurance producer verb %',p_verb;
end $_$;


--
-- Name: foundation_assurance_record_production(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_record_production(p_verb text, p_idempotency_key uuid, p_identity jsonb, p_produced jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_existing ops.foundation_assurance_production%rowtype;
        v_kind text; v_evidence text; v_digest text; v_result jsonb; v_id uuid:=gen_random_uuid();
        v_receipt jsonb; v_receipt_digest text; v_inventory uuid; v_scope jsonb; v_scope_key text;
        v_at text; v_admission uuid; v_event uuid; v_link text; v_evidence_row ops.foundation_assurance_evidence%rowtype;
begin
  v_actor:=ops.foundation_assurance_require_seat(p_verb,p_identity);
  if p_idempotency_key is null then
    raise exception 'foundation assurance production requires an idempotency key';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,0));
  select * into v_existing from ops.foundation_assurance_production where idempotency_key=p_idempotency_key;
  if found then
    if v_existing.verb is distinct from p_verb or v_existing.actor_id is distinct from v_actor
       or (p_produced is not null and v_existing.artifact_digest is distinct from
         'sha256:'||encode(public.digest(convert_to(ops.portfolio_canonical_json(p_produced),'UTF8'),'sha256'),'hex')) then
      raise exception 'foundation assurance idempotency key was reused for different production';
    end if;
    return v_existing.result||jsonb_build_object('replayed',true);
  end if;
  if p_produced is null or jsonb_typeof(p_produced)<>'object' then return null; end if;
  v_digest:='sha256:'||encode(public.digest(convert_to(ops.portfolio_canonical_json(p_produced),'UTF8'),'sha256'),'hex');
  if p_verb='produce-foundation-assurance-benchmark-coverage' then
    v_kind:='benchmark_coverage'; v_evidence:=p_produced->>'evidence_digest';
    if p_produced#>>'{fact,status}'<>'pass' or p_produced#>>'{fact,evaluator_identity,actor_id}'<>'codex-fa-coverage' then
      raise exception 'foundation assurance benchmark coverage is not a passing staffed fact';
    end if;
  elsif ops.foundation_assurance_expected_step(p_verb) is not null then
    v_kind:='member_receipt'; v_evidence:=p_produced->>'environment_manifest_digest';
    if p_produced->>'status'<>'pass'
       or p_produced->>'receipt_producer_step_ref' is distinct from ops.foundation_assurance_expected_step(p_verb)
       or p_produced#>>'{producer_identity,actor_id}' is distinct from ops.foundation_assurance_expected_actor(p_verb) then
      raise exception 'foundation assurance member receipt does not match its staffed producer';
    end if;
  elsif p_verb='record-foundation-assurance-minimum-outcome' then
    v_kind:='minimum_outcome'; v_receipt:=p_produced->'proposed_receipt';
    v_evidence:=v_receipt->>'environment_manifest_digest';
    if p_produced->>'admissible'<>'true' or p_produced->>'issued'<>'false'
       or v_receipt->>'status'<>'pass'
       or v_receipt#>>'{producer_identity,actor_id}'<>'codex-fa-minimum' then
      raise exception 'foundation assurance minimum was not an admissible unissued proposal';
    end if;
  else raise exception 'unknown foundation assurance producer verb %',p_verb;
  end if;
  select * into v_evidence_row from ops.foundation_assurance_evidence where evidence_digest=v_evidence;
  if not found then raise exception 'foundation assurance production names unknown sealed evidence'; end if;

  if v_kind='minimum_outcome' then
    if exists(select 1 from ops.foundation_assurance_production where evidence_digest=v_evidence and kind='minimum_outcome') then
      raise exception 'foundation assurance minimum already exists for this evidence';
    end if;
    if (select count(*) from ops.foundation_assurance_production
         where evidence_digest=v_evidence and kind in ('benchmark_coverage','member_receipt'))<>8 then
      raise exception 'foundation assurance minimum requires exactly eight stored predecessors';
    end if;
    v_scope:=jsonb_build_object('tenant','carr-internal','scope_ref',
      'safe:wr95-foundation-assurance/'||substr(v_evidence,8),
      'clock_origin_gate_id','foundation-assurance-minimum-accepted',
      'clock_terminus_gate_id','journey-one-kernel-production-accepted',
      'benchmark_subject_digest',v_receipt->>'subject_digest',
      'benchmark_candidate_digest',v_receipt->>'candidate_digest',
      'benchmark_policy_digest',v_receipt->>'policy_digest');
    v_scope_key:=ops.j1_clock_scope_digest(v_scope);
    insert into ops.j1_minimum_inventory(clock_scope_key,clock_scope,clock_scope_ref,tenant,
      minimum_receipt_ttl_policy_ms,minimum_environment_manifest_digest,opened_by_actor_id)
    values(v_scope_key,v_scope,v_scope->>'scope_ref','carr-internal',
      (v_evidence_row.config->>'minimum_receipt_ttl_ms')::bigint,v_evidence,v_actor)
    on conflict(clock_scope_key) do nothing;
    select id into v_inventory from ops.j1_minimum_inventory where clock_scope_key=v_scope_key;
    if exists(select 1 from ops.j1_minimum_admission where inventory_id=v_inventory) then
      raise exception 'foundation assurance minimum inventory already has an admission';
    end if;
    v_at:=ops.j1_minimum_admission_instant();
    v_receipt_digest:=ops.j1_minimum_receipt_digest(v_receipt);
    v_link:=ops.j1_minimum_admission_digest(v_at,v_scope_key,v_evidence,
      (v_evidence_row.config->>'minimum_receipt_ttl_ms')::bigint,null,v_receipt_digest,'carr-internal');
    insert into ops.j1_minimum_admission(inventory_id,admission_ordinal,idempotency_key,
      prior_admission_digest,admission_digest,receipt,receipt_digest,admitted_at,gate_id,
      receipt_producer_step_ref,observed_at,ttl_expires_at,status,
      minimum_receipt_ttl_policy_ms,minimum_environment_manifest_digest,receipt_schema_ref,
      source_ref,input_authority,written_by_actor_id)
    values(v_inventory,0,p_idempotency_key,null,v_link,v_receipt,v_receipt_digest,v_at,
      v_receipt->>'gate_id',v_receipt->>'receipt_producer_step_ref',v_receipt->>'observed_at',
      v_receipt->>'ttl_expires_at',v_receipt->>'status',
      (v_evidence_row.config->>'minimum_receipt_ttl_ms')::bigint,v_evidence,
      'consumer-gate-receipt.v1',v_evidence_row.evidence_ref,
      'trusted_admission_not_independently_verified_by_this_record_layer',v_actor)
    returning id into v_admission;
    insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,new_value,cause,
      agent_rationale,idempotency_key)
    values(now(),v_actor,p_verb,'foundation_assurance_minimum',v_id,'minimum_outcome',
      jsonb_build_object('receipt_digest',v_receipt_digest,'evidence_digest',v_evidence,
        'admission_id',v_admission),'automation_job',
      'WR-000095 exact minimum join admitted after all nine independent inputs passed',p_idempotency_key::text)
    returning id into v_event;
    v_result:=jsonb_build_object('ok',true,'outcome_id',v_id,'receipt_digest',v_receipt_digest,
      'evidence_digest',v_evidence,'admission_id',v_admission,'event_id',v_event,'replayed',false);
  else
    v_result:=jsonb_build_object('ok',true,'production_id',v_id,'verb',p_verb,
      'artifact_digest',v_digest,'evidence_digest',v_evidence,'replayed',false);
  end if;
  insert into ops.foundation_assurance_production(id,idempotency_key,verb,kind,evidence_digest,
    actor_id,session_ref,artifact,artifact_digest,admission_id,event_id,result)
  values(v_id,p_idempotency_key,p_verb,v_kind,v_evidence,v_actor,p_identity->>'session_ref',
    p_produced,v_digest,v_admission,v_event,v_result);
  return v_result;
end $$;


--
-- Name: foundation_assurance_require_seat(text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_require_seat(p_verb text, p_identity jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_expected text; v_actor uuid;
begin
  if session_user is distinct from ops.foundation_assurance_login_role() then
    raise exception 'foundation assurance production requires the dedicated oracle connection';
  end if;
  v_expected := ops.foundation_assurance_expected_actor(p_verb);
  if v_expected is null or p_identity->>'actor_id' is distinct from v_expected then
    raise exception 'foundation assurance verb % requires actor %', p_verb, coalesce(v_expected,'(unknown)');
  end if;
  v_actor := ops.foundation_assurance_identity_actor(p_identity);
  return v_actor;
end $$;


--
-- Name: foundation_assurance_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin
  raise exception 'foundation assurance evidence and production rows are immutable';
end $$;


--
-- Name: foundation_assurance_store_evidence(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_store_evidence(p_idempotency_key uuid, p_config jsonb, p_evidence jsonb, p_seal jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_session text; v_release ops.release%rowtype; v_existing ops.foundation_assurance_evidence%rowtype;
begin
  -- EXECUTE is granted only to the authority bundle below. Evidence and its
  -- candidate binding are authority decisions, not routine writer actions.
  v_actor:=ops.portfolio_writer_actor_id();
  v_session:=nullif(current_setting('carr.receipt_session_ref',true),'');
  if v_session is null then raise exception 'foundation assurance evidence requires session provenance'; end if;
  select * into v_existing from ops.foundation_assurance_evidence where idempotency_key=p_idempotency_key;
  if found then
    if v_existing.evidence_digest is distinct from p_seal->>'evidence_digest' then
      raise exception 'foundation assurance evidence idempotency key was reused';
    end if;
    return jsonb_build_object('ok',true,'evidence_ref',v_existing.evidence_ref,'replayed',true);
  end if;
  if jsonb_typeof(p_config)<>'object' or jsonb_typeof(p_evidence)<>'object' or jsonb_typeof(p_seal)<>'object'
     or p_seal->>'schema_version'<>'doctorcre-v5-foundation-assurance-evidence-seal.v1'
     or p_evidence->>'schema_version'<>'doctorcre-v5-foundation-assurance-evidence.v1'
     or p_seal->>'evidence_ref' is distinct from p_evidence#>>'{release,test_evidence_ref}'
     or p_seal->>'source_sha' is distinct from p_evidence->>'source_sha'
     or p_seal->>'final_provider_version' is distinct from p_evidence->>'final_provider_version'
     or p_seal->>'benchmark_payload_digest' is distinct from p_evidence#>>'{measurements,benchmark_payload_digest}' then
    raise exception 'foundation assurance evidence/seal binding is invalid';
  end if;
  -- The final-upload sealer binds the caller-chosen unique key, never the row
  -- UUID that PostgreSQL generates. The wrapper files that exact candidate
  -- first, then this transaction attaches the derived evidence ref and bytes;
  -- approval can therefore name only a candidate whose evidence is complete.
  select * into v_release from ops.release where release_key=p_evidence#>>'{release,key}';
  if not found or v_release.environment<>'production' or v_release.state<>'candidate'
     or v_release.git_sha is distinct from p_evidence->>'source_sha'
     or v_release.provider is distinct from 'cloudflare-workers'
     or v_release.provider_version_id is distinct from p_evidence->>'final_provider_version'
     or (v_release.test_evidence_ref is not null
         and v_release.test_evidence_ref is distinct from p_seal->>'evidence_ref') then
    raise exception 'foundation assurance evidence is not bound to the exact production candidate';
  end if;
  -- Candidacy is deliberately filed before live acquisition so an interrupted
  -- run leaves a stable provider/release target that the sealer can resume.
  -- Bind the derived ref and insert its immutable bytes in this one transaction;
  -- approval can never observe one without the other.
  update ops.release set test_evidence_ref=p_seal->>'evidence_ref'
   where id=v_release.id and test_evidence_ref is null;
  insert into ops.foundation_assurance_evidence(evidence_digest,evidence_ref,benchmark_payload_digest,
    source_sha,source_tree,staging_provider_version,final_provider_version,release_id,config,evidence,seal,
    idempotency_key,stored_by_actor_id,stored_by_session_ref)
  values(p_seal->>'evidence_digest',p_seal->>'evidence_ref',p_seal->>'benchmark_payload_digest',
    p_evidence->>'source_sha',p_evidence->>'source_tree',(p_evidence->>'staging_provider_version')::uuid,
    (p_evidence->>'final_provider_version')::uuid,v_release.id,p_config,p_evidence,p_seal,
    p_idempotency_key,v_actor,v_session);
  return jsonb_build_object('ok',true,'evidence_ref',p_seal->>'evidence_ref','replayed',false);
end $$;


--
-- Name: foundation_assurance_subject_maker(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.foundation_assurance_subject_maker(p_draft_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$ select jsonb_build_object('actor_id',a.slug,'session_ref',d.proposed_by_session_ref,
  'authority_class','review_agent') from ops.benchmark_manifest_draft d join public.actor a on a.id=d.proposed_by_actor_id
  where d.id=p_draft_id and d.proposed_by_session_ref is not null $$;


--
-- Name: freshness(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.freshness(observed_at timestamp with time zone, expires_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when observed_at is null then 'missing'
    when expires_at  is null then 'unknown'
    when now() > expires_at  then 'stale'
    else 'fresh'
  end
$$;


--
-- Name: FUNCTION freshness(observed_at timestamp with time zone, expires_at timestamp with time zone); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.freshness(observed_at timestamp with time zone, expires_at timestamp with time zone) IS 'The four freshness states from control-room/contracts/entity-schemas.v1.json. unknown is NOT stale: it means the observation carried no expiry, so nobody can say. Never collapse the two.';


--
-- Name: gate_zero_outcome_candidate_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_outcome_candidate_digest(p_receipt jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(ops.gate_zero_outcome_candidate_projection(p_receipt)),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION gate_zero_outcome_candidate_digest(p_receipt jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_outcome_candidate_digest(p_receipt jsonb) IS 'Canonical-JSON sha256 over ops.gate_zero_outcome_candidate_projection(receipt). This informational digest can show whether non-time, non-session evidence differs between an offered and recorded observation. It is not evidence or an idempotency key and does not admit or refuse a retry; candidate_digest arbitrates the immutable row.';


--
-- Name: gate_zero_outcome_candidate_projection(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_outcome_candidate_projection(p_receipt jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select (p_receipt - 'observed_at' - 'ttl_expires_at')
      || jsonb_build_object(
           'subject_maker_identity', (p_receipt -> 'subject_maker_identity') - 'session_ref',
           'producer_identity', (p_receipt -> 'producer_identity') - 'session_ref',
           'evaluator_identity', (p_receipt -> 'evaluator_identity') - 'session_ref')
$$;


--
-- Name: FUNCTION gate_zero_outcome_candidate_projection(p_receipt jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_outcome_candidate_projection(p_receipt jsonb) IS 'One consumer-gate-receipt.v1 reduced by removing observed_at, ttl_expires_at and each identity''s per-call session_ref. It is an informational view used to explain differences between offered and recorded observations. It is not evidence and does not admit or refuse a retry; candidate_digest arbitrates the immutable row.';


--
-- Name: gate_zero_outcome_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_outcome_digest(p_receipt jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(
      jsonb_build_array('consumer-gate-receipt.v1'::text, p_receipt)),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION gate_zero_outcome_digest(p_receipt jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_outcome_digest(p_receipt jsonb) IS 'sha256 over the canonical JSON of ["consumer-gate-receipt.v1", <receipt>] -- the TAGGED preimage r7''s receipt_payload_digest_rule declares for this schema (amended 2026-09-13, packet 4379c60e9a4fefbcf044f4bc5a34e5a95c90f77b9adf348b6da7475e17d5e6d7). The same bytes artifact-trust.js digest([schema, receipt]) hashes. Replaces 0502''s plain digest over the receipt object, which that rule now states does not satisfy it.';


--
-- Name: gate_zero_outcome_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_outcome_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'DoctorCRE v5 Gate Zero outcome rows are append-only: % is refused on ops.%',
    tg_op, tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: FUNCTION gate_zero_outcome_rows_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_outcome_rows_immutable() IS 'Refuses every update, delete and whole-table wipe on the Gate Zero outcome record. Installed twice because a row-level trigger never sees the statement event.';


--
-- Name: gate_zero_producer_actor_id(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_producer_actor_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_login text; v_lane text; v_id uuid; v_human boolean;
begin
  v_login := session_user;
  if v_login is distinct from ops.gate_zero_producer_login_role() then
    raise exception 'recording a Gate Zero read-only outcome requires the dedicated producer connection: the record layer admits % and this transaction authenticated as %',
      ops.gate_zero_producer_login_role(), coalesce(v_login, '(none)');
  end if;
  v_lane := split_part(ops.gate_zero_producer_seat_holder_ref(), ':', 2);
  if v_lane = '' then
    raise exception 'the Gate Zero oracle seat is unstaffed; no actor may record an outcome';
  end if;
  select id, kind = 'human' into v_id, v_human from public.actor where slug = v_lane and active;
  if not found then
    raise exception 'the Gate Zero oracle seat lane % is not an active actor', v_lane;
  end if;
  if v_human then
    raise exception 'the Gate Zero oracle seat must be a machine identity; actor % is a human actor, and the human act in this chain is the benchmark acceptance downstream', v_lane;
  end if;
  return v_id;
end;
$$;


--
-- Name: FUNCTION gate_zero_producer_actor_id(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_producer_actor_id() IS 'Refuses every transaction except one that AUTHENTICATED as the dedicated Gate Zero producer login role and whose staffed seat lane is an active, non-human actor. Derived from session_user; carr.acting_actor_slug is informational and is not read here. This is the record layer half of Joe''s 2026-09-13 ruling d4e5f6a7-b8c9-4d0e-9f1a-2b3c4d5e6f70 as amended by standing-rule amendment 9 (2026-09-14, seat-only write is enforced by connection role); the gateway half is in mcp-server/src/tools.js and neither substitutes for the other.';


--
-- Name: gate_zero_producer_login_role(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_producer_login_role() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'carr_gate_zero_producer'::text $$;


--
-- Name: FUNCTION gate_zero_producer_login_role(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_producer_login_role() IS 'The ONE role admitted to record a Gate Zero read-only outcome, and the only holder of EXECUTE on ops.gate_zero_record_read_only_outcome. Created here without a credential; its password and DSN are provisioned out of band by tools/provision-staging-app-writer.py and reach the Worker as DATABASE_URL_GATE_ZERO_WRITER, which is used for nothing else.';


--
-- Name: gate_zero_producer_seat_holder_ref(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_producer_seat_holder_ref() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'seat:codex-reviewer:gpt-5.6-sol'::text $$;


--
-- Name: FUNCTION gate_zero_producer_seat_holder_ref(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_producer_seat_holder_ref() IS 'The staffed holder of oracle:gate-producer:gate-zero-read-only, as a literal. The same value gate-zero-producer-registration.v5.js declares module-private; the two are asserted equal by test.';


--
-- Name: gate_zero_record_read_only_outcome(uuid, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.gate_zero_record_read_only_outcome(p_idempotency_key uuid, p_receipt jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare
  v_actor uuid; v_slug text; v_seat text; v_id uuid;
  v_existing ops.gate_zero_read_only_outcome%rowtype;
  v_digest text; v_candidate_scoped_digest text;
  v_field text; v_keys integer; v_identity jsonb; v_identity_keys integer;
begin
  if p_idempotency_key is null then
    raise exception 'recording a Gate Zero read-only outcome requires an idempotency key';
  end if;
  if p_receipt is null or jsonb_typeof(p_receipt) <> 'object' then
    raise exception 'recording a Gate Zero read-only outcome requires one consumer-gate-receipt.v1 object';
  end if;

  v_actor := ops.gate_zero_producer_actor_id();
  v_seat := ops.gate_zero_producer_seat_holder_ref();
  v_slug := split_part(v_seat, ':', 2);

  foreach v_field in array array[
    'gate_id', 'receipt_producer_step_ref', 'subject_digest', 'candidate_digest',
    'policy_digest', 'environment_manifest_digest', 'subject_environment', 'evidence_scope',
    'subject_maker_identity', 'producer_identity', 'evaluator_identity', 'producer_role',
    'independent_oracle_ref', 'oracle_version', 'evidence_ref', 'fixture_set_digest',
    'observed_at', 'ttl_expires_at', 'status', 'comparator', 'negative_admission_result'
  ] loop
    if not (p_receipt ? v_field) then
      raise exception 'the Gate Zero receipt is missing the required consumer-gate-receipt.v1 field %', v_field;
    end if;
  end loop;
  select count(*) into v_keys from jsonb_object_keys(p_receipt);
  if v_keys <> 21 then
    raise exception 'consumer-gate-receipt.v1 is a closed schema: the Gate Zero receipt carries % fields rather than 21', v_keys;
  end if;

  foreach v_field in array array['subject_maker_identity', 'producer_identity', 'evaluator_identity'] loop
    v_identity := p_receipt -> v_field;
    if jsonb_typeof(v_identity) <> 'object' then
      raise exception 'the Gate Zero receipt field % is not an authenticated-receipt-identity.v1 object', v_field;
    end if;
    select count(*) into v_identity_keys from jsonb_object_keys(v_identity);
    if v_identity_keys <> 3
       or not (v_identity ? 'actor_id')
       or not (v_identity ? 'session_ref')
       or not (v_identity ? 'authority_class') then
      raise exception 'authenticated-receipt-identity.v1 is a closed schema: the Gate Zero receipt field % carries % fields rather than exactly actor_id, session_ref and authority_class',
        v_field, v_identity_keys;
    end if;
    if coalesce(v_identity ->> 'actor_id', '') = ''
       or coalesce(v_identity ->> 'authority_class', '') = '' then
      raise exception 'the Gate Zero receipt field % has an empty actor_id or authority_class', v_field;
    end if;
    if coalesce(v_identity ->> 'session_ref', '') !~ '^session:[a-z0-9][a-z0-9:._/-]{8,199}$' then
      raise exception 'the Gate Zero receipt field % has a session_ref that is not r7''s authenticated-receipt-identity.v1 pattern: %',
        v_field, coalesce(v_identity ->> 'session_ref', '');
    end if;
  end loop;
  if p_receipt -> 'producer_identity' ->> 'actor_id' <> v_slug
     or p_receipt -> 'evaluator_identity' ->> 'actor_id' <> v_slug then
    raise exception 'the Gate Zero receipt names a producer or evaluator other than the staffed seat lane %', v_slug;
  end if;
  if p_receipt -> 'producer_identity' ->> 'authority_class' <> 'review_agent'
     or p_receipt -> 'evaluator_identity' ->> 'authority_class' <> 'review_agent' then
    raise exception 'the Gate Zero receipt names a producer or evaluator authority class other than review_agent';
  end if;
  if p_receipt -> 'subject_maker_identity' ->> 'actor_id' = v_slug then
    raise exception 'the Gate Zero receipt names the oracle seat as the maker of its own subject; r7 requires the subject maker to differ from the evaluator';
  end if;
  if p_receipt -> 'subject_maker_identity' ->> 'session_ref'
     = p_receipt -> 'evaluator_identity' ->> 'session_ref' then
    raise exception 'the Gate Zero receipt names one session as both subject maker and evaluator';
  end if;

  insert into ops.gate_zero_read_only_outcome (
    idempotency_key, step_ref, receipt_producer_step_ref, gate_id, receipt_schema,
    producer_role, independent_oracle_ref, oracle_version, evidence_scope,
    subject_environment, negative_admission_result, producing_seat_ref, producing_actor_id,
    candidate_digest, subject_digest, policy_digest, environment_manifest_digest,
    fixture_set_digest, evidence_ref, receipt, outcome_digest, candidate_scoped_digest,
    status, comparator, observed_at, ttl_expires_at)
  values (
    p_idempotency_key,
    'step:gate-zero-read-only-outcome',
    p_receipt ->> 'receipt_producer_step_ref',
    p_receipt ->> 'gate_id',
    'consumer-gate-receipt.v1',
    p_receipt ->> 'producer_role',
    p_receipt ->> 'independent_oracle_ref',
    p_receipt ->> 'oracle_version',
    p_receipt ->> 'evidence_scope',
    p_receipt ->> 'subject_environment',
    p_receipt ->> 'negative_admission_result',
    v_seat,
    v_actor,
    p_receipt ->> 'candidate_digest',
    p_receipt ->> 'subject_digest',
    p_receipt ->> 'policy_digest',
    p_receipt ->> 'environment_manifest_digest',
    p_receipt ->> 'fixture_set_digest',
    p_receipt ->> 'evidence_ref',
    p_receipt,
    ops.gate_zero_outcome_digest(p_receipt),
    ops.gate_zero_outcome_candidate_digest(p_receipt),
    p_receipt ->> 'status',
    p_receipt ->> 'comparator',
    (p_receipt ->> 'observed_at')::timestamptz,
    (p_receipt ->> 'ttl_expires_at')::timestamptz)
  on conflict (candidate_digest) do nothing
  returning id into v_id;
  if v_id is not null then
    return v_id;
  end if;

  select * into v_existing from ops.gate_zero_read_only_outcome
   where candidate_digest = p_receipt ->> 'candidate_digest';
  if not found then
    raise exception 'the Gate Zero outcome for candidate % was neither inserted nor found; the record layer is in a state this writer cannot account for',
      p_receipt ->> 'candidate_digest';
  end if;
  -- RETURN THE IMMUTABLE FIRST ROW UNCONDITIONALLY. The outcome and its audit
  -- event use different authenticated connections and transactions; the seat
  -- commits first, so a later outer failure can leave this row eventless. Every
  -- normal retry has new per-call identity and time bytes, and its evidence may
  -- also have moved. Refusing those bytes prevents the retry from reaching the
  -- event write. Returning the existing row changes no state here: the gateway
  -- recomputes and labels recorded versus offered digests before healing exactly
  -- one event under an advisory lock.
  v_digest := ops.gate_zero_outcome_digest(p_receipt);
  v_candidate_scoped_digest := ops.gate_zero_outcome_candidate_digest(p_receipt);
  if v_existing.outcome_digest <> v_digest then
    raise notice 'candidate % already has an immutable outcome; returning it unchanged (recorded full %, offered full %, recorded projection %, offered projection %)',
      v_existing.candidate_digest, v_existing.outcome_digest, v_digest,
      v_existing.candidate_scoped_digest, v_candidate_scoped_digest;
  end if;
  return v_existing.id;
end;
$_$;


--
-- Name: FUNCTION gate_zero_record_read_only_outcome(p_idempotency_key uuid, p_receipt jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.gate_zero_record_read_only_outcome(p_idempotency_key uuid, p_receipt jsonb) IS 'The only way to record a Gate Zero read-only outcome. The producing seat, actor and outcome digest are derived; the receipt and idempotency key are the only parameters. It admits only the staffed non-human oracle seat and validates the closed receipt and identity schemas. One insert is arbitrated by candidate_digest; its fallback always returns the immutable first row, including when later evidence, identity or time bytes differ, so the caller can report convergence and heal a missing outer audit event. No receipt is replaced. outcome_digest is the tagged digest r7 declares; candidate_scoped_digest is informational only.';


--
-- Name: get_cognition_cache(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.get_cognition_cache(p_cache_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select proposal from ops.cognition_result_cache
   where cache_key=p_cache_key and invalidated_at is null and expires_at>now()
$$;


--
-- Name: get_cognition_cache_for_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.get_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_cache_key text) RETURNS TABLE(cache_state text, proposal jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; c ops.cognition_result_cache%rowtype; observed_kind text; execution_kind text;
        declared_cognition_key text; active_contract_count integer; contract ops.cognition_job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind,d.execution_contract->>'cognition_job' into execution_kind,declared_cognition_key from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition' then
    raise exception 'job % is not a cognition workflow',p_job_id;
  end if;
  select count(*) into active_contract_count from ops.cognition_job
   where key=declared_cognition_key and active;
  if active_contract_count <> 1 then raise exception 'job % lacks one active cognition contract',p_job_id; end if;
  select * into contract from ops.cognition_job where key=declared_cognition_key and active;
  if btrim(coalesce(p_cache_key,''))='' then raise exception 'cache key is required'; end if;
  select * into c from ops.cognition_result_cache where cache_key=p_cache_key;
  observed_kind := case when c.cache_key is null then 'miss'
                        when c.cognition_key<>contract.key or c.cognition_version<>contract.version
                          or c.output_schema_version<>contract.output_schema_version then 'miss'
                        when c.invalidated_at is not null then 'invalidated'
                        when c.expires_at<=now() then 'expired' else 'hit' end;
  insert into ops.cognition_cache_observation
    (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind)
  values (j.id,j.attempt,j.definition_key,j.definition_version,j.mode,p_cache_key,observed_kind)
  on conflict (job_id,attempt,cache_key,observation_kind) do nothing;
  return query select observed_kind,case when observed_kind='hit' then c.proposal else null end;
end $$;


--
-- Name: guard_engineering_actor_authority_update(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_engineering_actor_authority_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if (new.active,new.kind,new.slug) is distinct from (old.active,old.kind,old.slug)
     and exists (
       select 1 from ops.capability_agent_session s
       join ops.engineering_execution_envelope e on e.agent_session_id=s.id
       join ops.job j on j.id=e.job_id
       where s.executor_actor_id=old.id
         and j.definition_key='engineering-slice' and j.definition_version=1
         and j.state='running' and j.lease_token is not null
         and j.leased_until>clock_timestamp()
     ) then
    raise exception 'Engineering actor authority is reserved by a live scoped lease';
  end if;
  return new;
end $$;


--
-- Name: guard_engineering_envelope_supersession(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_engineering_envelope_supersession() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare prior ops.engineering_execution_envelope%rowtype;
        current_plan ops.engineering_slice_plan%rowtype;
        prior_count integer; v_executor_actor_id uuid;
        current_source jsonb; current_work_ref text;
begin
  select s.executor_actor_id into v_executor_actor_id
    from ops.capability_agent_session s where s.id=new.agent_session_id for share;
  if not found then raise exception 'engineering envelope session is not current'; end if;
  perform 1 from public.actor a
   where a.id=v_executor_actor_id and a.active and a.kind='automation' and a.slug='codex'
   order by a.id for share;
  if not found then raise exception 'engineering envelope executor actor is not current'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-envelope:' || new.slice_plan_id::text || ':' || new.slice_ref,0));
  select * into current_plan from ops.engineering_slice_plan
   where id=new.slice_plan_id for key share;
  if not found then raise exception 'engineering envelope slice plan is not current'; end if;
  select ref into current_work_ref from ops.work_request
   where id=new.work_request_id for share;
  if not found then raise exception 'engineering envelope Work Request is not current'; end if;
  current_source:=ops.engineering_admission_source(current_work_ref);
  if current_source is null
     or new.work_request_id is distinct from
        regexp_replace(current_source->'work_request'->>'id','^wr:','')::uuid
     or new.accepted_plan_id is distinct from
        (current_source->'accepted_plan'->>'record_id')::uuid
     or new.state_version is distinct from
        (current_source->'work_request'->>'version')::integer
     or new.canonical_record_digest is distinct from
        current_source->'work_request'->>'canonical_record_digest'
     or current_plan.work_request_id is distinct from new.work_request_id
     or current_plan.accepted_plan_id is distinct from new.accepted_plan_id
     or current_plan.accepted_plan_hash is distinct from
        current_source->'accepted_plan'->>'digest'
     or current_plan.work_request_version is distinct from new.state_version
     or current_plan.plan->'accepted_plan_revision'->>'id' is distinct from
        current_source->'accepted_plan'->>'plan_ref'
     or current_plan.plan->'accepted_plan_revision'->>'digest' is distinct from
        current_source->'accepted_plan'->>'digest' then
    raise exception 'engineering envelope source or accepted plan is not current';
  end if;
  select count(*) into prior_count from ops.engineering_execution_envelope
   where slice_plan_id=new.slice_plan_id and slice_ref=new.slice_ref;
  if prior_count=0 then
    if new.supersedes_envelope_id is not null then raise exception 'first engineering envelope cannot supersede another envelope'; end if;
    return new;
  end if;
  if new.supersedes_envelope_id is null then raise exception 'later engineering envelope must name its immutable predecessor'; end if;
  select * into prior from ops.engineering_execution_envelope where id=new.supersedes_envelope_id for key share;
  if not found or prior.slice_plan_id<>new.slice_plan_id or prior.slice_ref<>new.slice_ref
     or prior.accepted_plan_id<>new.accepted_plan_id or prior.work_request_id<>new.work_request_id then
    raise exception 'engineering envelope predecessor is outside the exact slice binding';
  end if;
  if exists (select 1 from ops.engineering_execution_envelope where supersedes_envelope_id=prior.id) then raise exception 'engineering envelope predecessor already has a successor'; end if;
  if exists (select 1 from ops.job j where j.id=prior.job_id and j.state='running' and j.lease_token is not null and j.leased_until>clock_timestamp()) then raise exception 'leased engineering envelope cannot be superseded'; end if;
  if prior.expires_at>clock_timestamp()
     and prior.envelope->'server_binding'->'authority'->>'read_only'='false'
     and exists (select 1 from ops.capability_agent_session s where s.id=prior.agent_session_id and s.state not in ('completed','cancelled'))
     and not exists (select 1 from ops.engineering_slice_receipt r where r.envelope_id=prior.id and r.outcome in ('failed','blocked','reopened')) then
    raise exception 'current executable engineering envelope cannot be superseded';
  end if;
  return new;
end $$;


--
-- Name: guard_engineering_job_definition_currentness_update(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_engineering_job_definition_currentness_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if (to_jsonb(new)-'updated_at') is distinct from (to_jsonb(old)-'updated_at')
     and old.key='engineering-slice' and old.version=1
     and exists (
       select 1 from ops.job j
        where j.definition_key=old.key and j.definition_version=old.version
          and j.state='running' and j.lease_token is not null
          and j.leased_until>clock_timestamp()
     ) then
    raise exception 'Engineering job definition currentness is reserved by a live scoped lease';
  end if;
  return new;
end $$;


--
-- Name: guard_engineering_reviewer_fact_insert(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_engineering_reviewer_fact_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare r ops.engineering_slice_receipt%rowtype;
        e ops.engineering_execution_envelope%rowtype;
        sp ops.engineering_slice_plan%rowtype;
        executor_session ops.capability_agent_session%rowtype;
        executor_slug text; reviewer_slug text; receipt_deviation_refs jsonb;
        locked_actor_count integer;
begin
  if new.contract_version is not null then
    raise exception 'engineering reviewer contract version is caller-controlled';
  end if;
  if not coalesce(ops.engineering_receipt_exact_object(new.fact,array[
       'attempt_id','evidence_refs','is_independent','resolved_deviation_refs',
       'reviewed_deviation_refs','reviewer_ref','session_ref','slice_ref','state'
     ]),false)
     or not coalesce(new.fact->>'state'=any(array['passed','failed','blocked']),false)
     or new.state is distinct from new.fact->>'state'
     or jsonb_typeof(new.fact->'is_independent') is distinct from 'boolean'
     or new.fact->'is_independent' is distinct from 'true'::jsonb
     or not coalesce((new.fact->>'attempt_id') ~ '^attempt:[1-9][0-9]*$',false)
     or not coalesce((new.fact->>'slice_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     or not coalesce((new.fact->>'reviewer_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     or not coalesce((new.fact->>'session_ref') ~ '^session:[A-Za-z0-9][A-Za-z0-9._:-]{1,119}$',false)
     or not coalesce(ops.engineering_receipt_evidence_array(new.fact->'evidence_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(new.fact->'reviewed_deviation_refs'),false)
     or not coalesce(ops.engineering_receipt_identifier_array(new.fact->'resolved_deviation_refs'),false) then
    raise exception 'engineering reviewer fact is malformed';
  end if;
  -- Derive identifiers unlocked, then retain session -> actor -> lineage order.
  select * into r from ops.engineering_slice_receipt where id=new.receipt_id;
  if not found then raise exception 'engineering reviewer receipt not found'; end if;
  if new.reviewer_actor_id is not distinct from r.executor_actor_id then
    raise exception 'engineering reviewer cannot be the receipt executor';
  end if;
  select * into e from ops.engineering_execution_envelope where id=r.envelope_id;
  if not found then raise exception 'engineering reviewer envelope not found'; end if;
  select * into executor_session from ops.capability_agent_session where id=e.agent_session_id for share;
  if not found then raise exception 'engineering reviewer executor session not found'; end if;
  perform 1 from public.actor actor
   where (actor.id=r.executor_actor_id and actor.active and actor.kind='automation' and actor.slug='codex')
      or (actor.id=new.reviewer_actor_id and actor.active)
   order by actor.id for share;
  select count(*) into locked_actor_count from public.actor actor
   where (actor.id=r.executor_actor_id and actor.active and actor.kind='automation' and actor.slug='codex')
      or (actor.id=new.reviewer_actor_id and actor.active);
  if locked_actor_count<>2 then raise exception 'engineering reviewer actor authority is not current'; end if;
  select actor.slug into executor_slug from public.actor actor where actor.id=r.executor_actor_id;
  select actor.slug into reviewer_slug from public.actor actor where actor.id=new.reviewer_actor_id;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-envelope:'||e.slice_plan_id::text||':'||e.slice_ref,0));
  select * into e from ops.engineering_execution_envelope where id=r.envelope_id for key share;
  if not found then raise exception 'engineering reviewer envelope changed'; end if;
  select * into sp from ops.engineering_slice_plan where id=e.slice_plan_id for key share;
  if not found then raise exception 'engineering reviewer slice plan not found'; end if;
  perform 1 from ops.work_request where id=e.work_request_id for share;
  if not found then raise exception 'engineering reviewer Work Request is not current'; end if;
  select * into r from ops.engineering_slice_receipt where id=new.receipt_id for key share;
  if not found then raise exception 'engineering reviewer receipt changed'; end if;

  if not coalesce(ops.engineering_receipt_exact_object(r.receipt,array[
       'actual_component_refs','actual_resource_refs','artifact_refs','attribution','attempt_id','checks',
       'deviations','envelope_digest','evidence_refs','executor_claim','independent_verification_required',
       'outcome','plan_digest','planned_component_refs','planned_resource_refs','reset_reconstruction',
       'schema_version','slice_ref','source_evidence'
     ]),false)
     or r.receipt->>'schema_version' is distinct from 'engineering-slice-receipt.v1'
     or r.receipt_digest is distinct from
        ('sha256:'||encode(public.digest(ops.guidance_import_canonical_json(r.receipt),'sha256'),'hex'))
     or not coalesce(ops.engineering_receipt_exact_object(r.receipt->'attribution',array[
          'actor_ref','adapter_ref','session_ref'
        ]),false)
     or not coalesce((r.receipt#>>'{attribution,session_ref}') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
     or r.receipt->'independent_verification_required' is distinct from 'true'::jsonb
     or jsonb_typeof(r.receipt->'deviations') is distinct from 'array'
     or exists (
       select 1
         from jsonb_array_elements(case when jsonb_typeof(r.receipt->'deviations')='array'
                                        then r.receipt->'deviations' else '[]'::jsonb end) deviation
        where not coalesce(ops.engineering_receipt_exact_object(deviation,array[
                'category','deviation_ref','evidence_refs','impact','out_of_scope_component_refs',
                'out_of_scope_resource_refs','plan_revision_required','reason','review_state'
              ]),false)
           or not coalesce((deviation->>'deviation_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
           or exists (
             select 1 from unnest(array['category','reason','impact']) field
              where jsonb_typeof(deviation->field) is distinct from 'string'
                 or not coalesce(btrim(deviation->>field)<>'',false)
           )
           or jsonb_typeof(deviation->'plan_revision_required') is distinct from 'boolean'
           or not coalesce(ops.engineering_receipt_evidence_array(deviation->'evidence_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_resource_refs'),false)
           or not coalesce(ops.engineering_receipt_identifier_array(deviation->'out_of_scope_component_refs'),false)
           or not coalesce(deviation->>'review_state'=any(array['unreviewed','reviewed','resolved']),false)
     )
     or exists (
       select 1 from jsonb_array_elements(case when jsonb_typeof(r.receipt->'deviations')='array'
                                               then r.receipt->'deviations' else '[]'::jsonb end) deviation
        group by deviation->>'deviation_ref' having count(*)>1
     )
     or new.work_request_id is distinct from r.work_request_id
     or new.slice_ref is distinct from r.slice_ref
     or new.fact->>'slice_ref' is distinct from r.slice_ref
     or new.fact->>'attempt_id' is distinct from r.attempt_id
     or new.reviewer_session_ref is distinct from new.fact->>'session_ref'
     or new.reviewer_actor_id is not distinct from r.executor_actor_id
     or reviewer_slug is null
     or not coalesce(new.fact->>'reviewer_ref'=any(array[
          reviewer_slug,'actor:'||reviewer_slug,'reviewer:'||reviewer_slug
        ]),false)
     or new.reviewer_session_ref is not distinct from r.receipt#>>'{attribution,session_ref}'
     or r.receipt->>'slice_ref' is distinct from r.slice_ref
     or r.receipt->>'attempt_id' is distinct from r.attempt_id
     or r.receipt->>'outcome' is distinct from r.outcome
     or r.receipt->>'plan_digest' is distinct from sp.plan_digest
     or r.receipt->>'envelope_digest' is distinct from e.envelope_digest
     or e.work_request_id is distinct from r.work_request_id
     or e.slice_ref is distinct from r.slice_ref
     or e.envelope->>'envelope_id' is distinct from 'env:'||e.id::text
     or e.envelope#>>'{request,job_ref}' is distinct from 'job:'||e.job_id::text
     or e.envelope#>>'{agent_session,id}' is distinct from 'session:'||e.agent_session_id::text
     or executor_session.executor_actor_id is distinct from r.executor_actor_id
     or executor_slug is null
     or r.receipt#>>'{attribution,actor_ref}' is distinct from e.envelope#>>'{server_binding,identity,agent_principal_id}'
     or r.receipt#>>'{attribution,session_ref}' is distinct from e.envelope#>>'{agent_session,id}'
     or r.receipt#>>'{attribution,adapter_ref}' is distinct from e.envelope#>>'{server_binding,adapter,adapter_id}' then
    raise exception 'engineering reviewer fact is not independently bound to the exact receipt';
  end if;

  select coalesce(jsonb_agg(to_jsonb(deviation_ref) order by deviation_ref),'[]'::jsonb)
    into receipt_deviation_refs
    from (
      select deviation->>'deviation_ref' as deviation_ref
        from jsonb_array_elements(case when jsonb_typeof(r.receipt->'deviations')='array'
                                       then r.receipt->'deviations' else '[]'::jsonb end) deviation
    ) refs;
  if not coalesce(ops.engineering_receipt_identifier_sets_equal(
       new.fact->'reviewed_deviation_refs',receipt_deviation_refs),false)
     or exists (
       select 1
         from jsonb_array_elements(new.fact->'resolved_deviation_refs') resolved
        where not exists (
          select 1 from jsonb_array_elements(receipt_deviation_refs) expected
           where expected=resolved
        )
     ) then
    raise exception 'engineering reviewer fact does not cover the receipt deviations';
  end if;

  if new.state='passed' and (
       r.outcome is distinct from 'claimed_complete'
       or r.receipt->>'outcome' is distinct from 'claimed_complete'
       or not coalesce(ops.engineering_receipt_identifier_array(r.receipt->'planned_resource_refs'),false)
       or not coalesce(ops.engineering_receipt_identifier_array(r.receipt->'actual_resource_refs'),false)
       or not coalesce(ops.engineering_receipt_identifier_array(r.receipt->'planned_component_refs'),false)
       or not coalesce(ops.engineering_receipt_identifier_array(r.receipt->'actual_component_refs'),false)
       or not coalesce(ops.engineering_receipt_identifier_sets_equal(
            r.receipt->'planned_resource_refs',(
              select dependency_slice->'declared_resource_refs'
                from jsonb_array_elements(sp.plan->'slices') dependency_slice
               where dependency_slice->>'slice_ref'=r.slice_ref
            )),false)
       or not coalesce(ops.engineering_receipt_identifier_sets_equal(
            r.receipt->'planned_component_refs',(
              select dependency_slice->'declared_component_refs'
                from jsonb_array_elements(sp.plan->'slices') dependency_slice
               where dependency_slice->>'slice_ref'=r.slice_ref
            )),false)
       or exists (
         select 1 from jsonb_array_elements(r.receipt->'actual_resource_refs') actual_ref
          where not exists (
            select 1
              from jsonb_array_elements(sp.plan->'slices') dependency_slice,
                   jsonb_array_elements(dependency_slice->'declared_resource_refs') declared_ref
             where dependency_slice->>'slice_ref'=r.slice_ref and declared_ref=actual_ref
          ) and not exists (
            select 1
              from jsonb_array_elements(r.receipt->'deviations') deviation,
                   jsonb_array_elements(deviation->'out_of_scope_resource_refs') approved_ref
             where deviation->>'review_state'='resolved' and approved_ref=actual_ref
          )
       )
       or exists (
         select 1 from jsonb_array_elements(r.receipt->'actual_component_refs') actual_ref
          where not exists (
            select 1
              from jsonb_array_elements(sp.plan->'slices') dependency_slice,
                   jsonb_array_elements(dependency_slice->'declared_component_refs') declared_ref
             where dependency_slice->>'slice_ref'=r.slice_ref and declared_ref=actual_ref
          ) and not exists (
            select 1
              from jsonb_array_elements(r.receipt->'deviations') deviation,
                   jsonb_array_elements(deviation->'out_of_scope_component_refs') approved_ref
             where deviation->>'review_state'='resolved' and approved_ref=actual_ref
          )
       )
       or not coalesce(ops.engineering_receipt_identifier_array(r.receipt->'artifact_refs'),false)
       or not coalesce(case when jsonb_typeof(r.receipt->'artifact_refs')='array'
                            then jsonb_array_length(r.receipt->'artifact_refs')>0 else false end,false)
       or not coalesce(ops.engineering_receipt_evidence_array(r.receipt->'evidence_refs'),false)
       or not coalesce(case when jsonb_typeof(r.receipt->'evidence_refs')='array'
                            then jsonb_array_length(r.receipt->'evidence_refs')>0 else false end,false)
       or jsonb_typeof(r.receipt->'checks') is distinct from 'array'
       or not coalesce(case when jsonb_typeof(r.receipt->'checks')='array'
                            then jsonb_array_length(r.receipt->'checks')>0 else false end,false)
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(r.receipt->'checks')='array'
                                          then r.receipt->'checks' else '[]'::jsonb end) receipt_check
          where not coalesce(ops.engineering_receipt_exact_object(receipt_check,array[
                  'check_ref','evidence_refs','state'
                ]),false)
             or not coalesce((receipt_check->>'check_ref') ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
             or receipt_check->>'state' is distinct from 'passed'
             or not coalesce(ops.engineering_receipt_evidence_array(receipt_check->'evidence_refs'),false)
             or not coalesce(case when jsonb_typeof(receipt_check->'evidence_refs')='array'
                                  then jsonb_array_length(receipt_check->'evidence_refs')>0 else false end,false)
       )
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(r.receipt->'checks')='array'
                                          then r.receipt->'checks' else '[]'::jsonb end) receipt_check
          group by receipt_check->>'check_ref' having count(*)>1
       )
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(r.receipt->'checks')='array'
                                          then r.receipt->'checks' else '[]'::jsonb end) receipt_check
          where not exists (
            select 1
              from jsonb_array_elements(sp.plan->'slices') dependency_slice,
                   jsonb_array_elements(dependency_slice->'planned_checks') planned_check
             where dependency_slice->>'slice_ref'=r.slice_ref
               and planned_check->>'check_ref'=receipt_check->>'check_ref'
          )
       )
       or exists (
         select 1
           from jsonb_array_elements(sp.plan->'slices') dependency_slice,
                jsonb_array_elements(dependency_slice->'planned_checks') planned_check
          where dependency_slice->>'slice_ref'=r.slice_ref
            and not exists (
              select 1
                from jsonb_array_elements(case when jsonb_typeof(r.receipt->'checks')='array'
                                               then r.receipt->'checks' else '[]'::jsonb end) receipt_check
               where receipt_check->>'check_ref'=planned_check->>'check_ref'
            )
       )
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(r.receipt->'checks')='array'
                                          then r.receipt->'checks' else '[]'::jsonb end) receipt_check
           join lateral (
             select planned_check
               from jsonb_array_elements(sp.plan->'slices') dependency_slice,
                    jsonb_array_elements(dependency_slice->'planned_checks') planned_check
              where dependency_slice->>'slice_ref'=r.slice_ref
                and planned_check->>'check_ref'=receipt_check->>'check_ref'
           ) planned on true
          where not exists (
            select 1
              from jsonb_array_elements(case when jsonb_typeof(receipt_check->'evidence_refs')='array'
                                             then receipt_check->'evidence_refs' else '[]'::jsonb end) evidence
             where evidence->>'redaction_class'=case planned.planned_check->>'evidence_requirement'
               when 'redacted_evidence_required' then 'redacted_evidence' else 'metadata_only' end
          )
       )
       or not coalesce(ops.engineering_receipt_exact_object(r.receipt->'source_evidence',array[
            'branch_ref','evidence_refs','source_sha','worktree_ref'
          ]),false)
       or exists (
         select 1 from unnest(array['worktree_ref','branch_ref','source_sha']) field
          where jsonb_typeof(r.receipt->'source_evidence'->field) is distinct from 'string'
             or not coalesce(btrim(r.receipt->'source_evidence'->>field)<>'',false)
             or (field<>'source_sha' and not coalesce(
                  (r.receipt->'source_evidence'->>field) ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false))
       )
       or not coalesce(ops.engineering_receipt_evidence_array(r.receipt->'source_evidence'->'evidence_refs'),false)
       or not coalesce(ops.engineering_receipt_exact_object(r.receipt->'reset_reconstruction',array[
            'fresh_session','inherited_transcript_used','reconstruction_free','remediation_action'
          ]),false)
       or r.receipt->'reset_reconstruction'->'fresh_session' is distinct from 'true'::jsonb
       or r.receipt->'reset_reconstruction'->'inherited_transcript_used' is distinct from 'false'::jsonb
       or jsonb_typeof(r.receipt->'reset_reconstruction'->'reconstruction_free') is distinct from 'boolean'
       or (r.receipt->'reset_reconstruction'->'reconstruction_free'='false'::jsonb and
           (jsonb_typeof(r.receipt->'reset_reconstruction'->'remediation_action') is distinct from 'string'
            or not coalesce(btrim(r.receipt->'reset_reconstruction'->>'remediation_action')<>'',false)))
       or (r.receipt->'reset_reconstruction'->'reconstruction_free'='true'::jsonb and
           r.receipt->'reset_reconstruction'->'remediation_action' is distinct from 'null'::jsonb
           and (jsonb_typeof(r.receipt->'reset_reconstruction'->'remediation_action') is distinct from 'string'
            or not coalesce(btrim(r.receipt->'reset_reconstruction'->>'remediation_action')<>'',false)))
       or not coalesce(ops.engineering_receipt_exact_object(r.receipt->'executor_claim',array[
            'claim_state','claimed_at','claimed_by'
          ]),false)
       or r.receipt->'executor_claim'->>'claim_state' is distinct from 'executor_claim'
       or r.receipt->'executor_claim'->>'claimed_by' is distinct from executor_slug
       or jsonb_typeof(r.receipt->'executor_claim'->'claimed_at') is distinct from 'string'
       or not coalesce(btrim(r.receipt->'executor_claim'->>'claimed_at')<>'',false)
       or jsonb_array_length(new.fact->'evidence_refs')=0
       or not coalesce(ops.engineering_receipt_identifier_sets_equal(
            new.fact->'resolved_deviation_refs',receipt_deviation_refs),false)
       or exists (
         select 1
           from jsonb_array_elements(case when jsonb_typeof(r.receipt->'deviations')='array'
                                          then r.receipt->'deviations' else '[]'::jsonb end) deviation
          where deviation->>'review_state' is distinct from 'resolved'
             or deviation->'plan_revision_required' is distinct from 'false'::jsonb
       )
     ) then
    raise exception 'engineering reviewer pass requires a complete exact receipt and resolved deviations';
  end if;
  new.contract_version:='engineering-review.v1';
  return new;
end $_$;


--
-- Name: guard_engineering_session_terminalization(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_engineering_session_terminalization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare lineage record;
begin
  if new.state not in ('completed','cancelled') or new.state=old.state then
    return new;
  end if;
  for lineage in
    select distinct e.slice_plan_id,e.slice_ref
     from ops.engineering_execution_envelope e
     where e.agent_session_id=old.id
     order by e.slice_plan_id,e.slice_ref
  loop
    perform pg_advisory_xact_lock(hashtextextended(
      'engineering-envelope:' || lineage.slice_plan_id::text || ':' || lineage.slice_ref,0));
    if exists (
      select 1 from ops.engineering_execution_envelope e
      join ops.job j on j.id=e.job_id
       where e.agent_session_id=old.id and e.slice_plan_id=lineage.slice_plan_id
         and e.slice_ref=lineage.slice_ref and j.state='running'
         and j.lease_token is not null and j.leased_until>statement_timestamp()
    ) then
      raise exception 'engineering session terminalization deferred while its dispatch lease is live';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: guard_siep_engineering_evidence_binding(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_siep_engineering_evidence_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_envelope_id uuid; v_plan_id uuid; v_slice_ref text; v_work_request_id uuid;
        v_session_id uuid; v_executor_actor_id uuid; v_reviewer_actor_id uuid;
        v_actor_count integer;
begin
  if new.engineering_contract_version is not null then
    raise exception 'SIEP Engineering contract version is caller-controlled';
  end if;
  -- IDs are read unlocked; every authority condition is re-read after the
  -- session/actor/lineage/envelope/Work-Request lock chain.
  select e.id,e.slice_plan_id,e.slice_ref,e.work_request_id,e.agent_session_id,
         r.executor_actor_id,review.reviewer_actor_id
    into v_envelope_id,v_plan_id,v_slice_ref,v_work_request_id,v_session_id,
         v_executor_actor_id,v_reviewer_actor_id
    from ops.job j
    join ops.engineering_execution_envelope e on e.job_id=j.id
    join ops.engineering_slice_receipt r on r.envelope_id=e.id
    join ops.engineering_reviewer_fact review on review.receipt_id=r.id
   where j.id=new.job_id and j.definition_key='engineering-slice'
   order by r.created_at desc,r.id desc limit 1;
  if not found then raise exception 'SIEP evidence binding requires an Engineering receipt and review'; end if;
  perform 1 from ops.capability_agent_session s where s.id=v_session_id for share;
  if not found then raise exception 'SIEP Engineering session is not current'; end if;
  perform 1 from public.actor a
   where a.id=any(array[v_executor_actor_id,v_reviewer_actor_id]) and a.active
   order by a.id for share;
  select count(*) into v_actor_count from public.actor a
   where a.id=any(array[v_executor_actor_id,v_reviewer_actor_id]) and a.active;
  if v_executor_actor_id is null or v_reviewer_actor_id is null or v_executor_actor_id=v_reviewer_actor_id
     or v_actor_count<>2 then raise exception 'SIEP Engineering actor authority is not current'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'engineering-envelope:'||v_plan_id::text||':'||v_slice_ref,0));
  perform 1 from ops.engineering_execution_envelope e
    join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id
   where e.id=v_envelope_id and e.job_id=new.job_id for key share of e,sp;
  if not found then raise exception 'SIEP Engineering envelope is not current'; end if;
  perform 1 from ops.work_request where id=v_work_request_id for share;
  if not found then raise exception 'SIEP Engineering Work Request is not current'; end if;
  if new.definition_key is distinct from 'engineering-slice'
     or new.definition_version is distinct from 1
     or not exists (
       select 1 from ops.job j
       join ops.engineering_execution_envelope e on e.job_id=j.id
       join ops.engineering_slice_plan sp on sp.id=e.slice_plan_id and sp.work_request_id=e.work_request_id
       join ops.engineering_slice_receipt receipt on receipt.envelope_id=e.id and receipt.work_request_id=e.work_request_id
       join ops.job_attempt attempt on attempt.id=receipt.job_attempt_id and attempt.job_id=j.id and attempt.attempt=j.attempt and attempt.state='succeeded'
       join ops.engineering_reviewer_fact review on review.receipt_id=receipt.id and review.work_request_id=receipt.work_request_id and review.slice_ref=receipt.slice_ref
       join public.actor reviewer on reviewer.id=review.reviewer_actor_id and reviewer.slug='joe' and reviewer.active
       join ops.siep_package_contract package on package.package_key=new.package_key and package.work_request_id=e.work_request_id
      where j.id=new.job_id and j.definition_key='engineering-slice' and j.definition_version=1 and j.state='succeeded'
        and e.state_version=new.work_request_version and sp.work_request_version=new.work_request_version
        and receipt.outcome='claimed_complete' and review.state='passed'
        and review.contract_version='engineering-review.v1'
        and review.reviewer_actor_id<>receipt.executor_actor_id
        and exists (select 1 from ops.job_receipt jr where jr.job_id=j.id and jr.attempt=j.attempt and jr.kind='completion')
        and e.id=v_envelope_id
        and not exists (
          select 1 from ops.engineering_execution_envelope successor
           where successor.supersedes_envelope_id=e.id
        )
        and 1=(
          select count(*) from ops.engineering_execution_envelope leaf
           where leaf.slice_plan_id=e.slice_plan_id
             and leaf.slice_ref=e.slice_ref
             and not exists (
               select 1 from ops.engineering_execution_envelope successor
                where successor.supersedes_envelope_id=leaf.id
             )
        )
     ) then
    raise exception 'SIEP evidence binding requires a 0335-verified Engineering receipt and review';
  end if;
  new.engineering_contract_version:='engineering-review.v1';
  return new;
end $$;


--
-- Name: guidance_import_canonical_json(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_kind text := jsonb_typeof(p_value);
  v_result text;
begin
  if v_kind='object' then
    select '{' || coalesce(string_agg(
             to_jsonb(entry.key)::text || ':' || ops.guidance_import_canonical_json(entry.value),
             ',' order by entry.key collate "C"), '') || '}'
      into v_result
      from jsonb_each(p_value) as entry(key,value);
    return v_result;
  elsif v_kind='array' then
    select '[' || coalesce(string_agg(
             ops.guidance_import_canonical_json(entry.value), ',' order by entry.ordinality), '') || ']'
      into v_result
      from jsonb_array_elements(p_value) with ordinality as entry(value,ordinality);
    return v_result;
  elsif v_kind='string' then
    return to_jsonb(p_value #>> '{}')::text;
  end if;
  -- The compiler emits only integral structural numbers; jsonb's scalar
  -- representation is identical for that admitted subset.  Booleans and null
  -- are likewise already the portable JSON spellings.
  return p_value::text;
end $$;


--
-- Name: guidance_import_manifest_digest(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_manifest_digest(p_manifest_text text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select encode(digest(convert_to(p_manifest_text,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: guidance_import_split_group_id(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_import_split_group_id(p_key text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  select (substr(md5('guidance-import-split:' || p_key),1,8) || '-' ||
          substr(md5('guidance-import-split:' || p_key),9,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),13,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),17,4) || '-' ||
          substr(md5('guidance-import-split:' || p_key),21,12))::uuid
$$;


--
-- Name: guidance_revision_contract_hash(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guidance_revision_contract_hash(p_revision_id uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select encode(digest(jsonb_build_object(
    'guidance_revision_id',r.id,
    'guidance_item_id',r.guidance_item_id,
    'version',r.version,
    'guidance_type',r.guidance_type,
    'scope',r.scope,
    'activation',r.activation,
    'consumer',r.consumer,
    'verification',r.verification,
    'provenance',r.provenance,
    'delivery',r.delivery,
    'is_constitution',r.is_constitution,
    'supersedes_revision_id',r.supersedes_revision_id,
    'reason',r.reason
  )::text,'sha256'),'hex')
    from ops.guidance_revision r where r.id=p_revision_id
$$;


--
-- Name: heartbeat_job(uuid, uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heartbeat_job(p_job_id uuid, p_lease_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; n integer;
begin
  select * into j from ops.job where id=p_job_id for update;
  if found and j.definition_key='engineering-slice' then
    raise exception 'engineering jobs require scoped controller functions';
  end if;
  update ops.job set leased_until=now()+make_interval(secs=>p_lease_seconds),updated_at=now()
   where id=p_job_id and state='running' and lease_token=p_lease_token
     and leased_until>=now();
  get diagnostics n=row_count;
  return n=1;
end $$;


--
-- Name: heavy_build_admission_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heavy_build_admission_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'heavy-build admission and review receipts are append-only';
end;
$$;


--
-- Name: heavy_build_classification(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heavy_build_classification(p_work_request_id uuid, p_scope_summary text, p_dependency_refs jsonb, p_caps jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype;
  signal_text text;
  reasons jsonb := '[]'::jsonb;
  criteria_count integer;
  dependency_count integer;
  step_count integer;
  shape_ready boolean;
begin
  select x.* into w from ops.work_request x where x.id = p_work_request_id;
  if not found then return null; end if;
  if jsonb_typeof(coalesce(p_dependency_refs, '[]'::jsonb)) is distinct from 'array'
     or jsonb_typeof(coalesce(p_caps, '{}'::jsonb)) is distinct from 'object' then
    raise exception 'heavy-build classification requires typed dependency refs and caps';
  end if;

  -- THE PLAN'S WORDING IS NOT EVIDENCE ABOUT THE WORK. p_scope_summary used to
  -- join this signal text, which meant the tier could be flipped by rewording the
  -- summary while the change itself stayed identical. Observed 2026-08-27: the
  -- same four-step additive guard classified heavy with the word "schema" in its
  -- summary and standard without it, and the plan was accepted on the second
  -- wording. A gate that a rewrite can pass teaches sessions to write around it
  -- rather than through it. Heaviness is now a property of the REQUEST -- its
  -- title, its desired outcome, its acceptance criteria -- plus the plan's SHAPE,
  -- which the scale signals below still read from caps and dependency refs.
  -- Nothing is relaxed: every signal that fired before still fires, and a request
  -- that was heavy is heavy no matter how its plan is phrased.
  signal_text := lower(concat_ws(' ', w.title, w.desired_outcome,
    coalesce(w.acceptance_criteria::text, '')));
  criteria_count := case when jsonb_typeof(w.acceptance_criteria) = 'array' then jsonb_array_length(w.acceptance_criteria) else 0 end;
  dependency_count := jsonb_array_length(coalesce(p_dependency_refs, '[]'::jsonb));
  step_count := case when coalesce(p_caps->>'max_steps','') ~ '^[0-9]+$' then (p_caps->>'max_steps')::integer else 0 end;

  if signal_text ~ '\m(heavy[ -]build|first[ -]of[ -](its|the)[ -]kind|first[ -]of[ -]kind)\M' then
    reasons := reasons || jsonb_build_array('signal:first_of_kind_or_explicit_heavy');
  end if;
  if signal_text ~ '\m(build|create|extend|implement|ship|design)\M.{0,80}\m(new |complete |governed )?(capability|system|platform|engine|service|workflow|kernel)\M' then
    reasons := reasons || jsonb_build_array('signal:new_capability');
  end if;
  if signal_text ~ '\m(architecture|architectural|system design|multi[ -]surface|end[ -]to[ -]end)\M' then
    reasons := reasons || jsonb_build_array('signal:architecture_or_multi_surface');
  end if;
  if signal_text ~ '\m(migration|schema|deploy|deployment|rebuild|refactor|integration)\M' then
    reasons := reasons || jsonb_build_array('signal:structural_change');
  end if;
  if signal_text ~ '\m(agent learning|memory kernel|learning system|memory engine)\M' then
    reasons := reasons || jsonb_build_array('signal:agent_learning');
  end if;
  if criteria_count >= 5 then reasons := reasons || jsonb_build_array('scale:acceptance_criteria'); end if;
  if dependency_count >= 3 then reasons := reasons || jsonb_build_array('scale:dependency_refs'); end if;
  if step_count >= 5 then reasons := reasons || jsonb_build_array('scale:max_steps'); end if;

  shape_ready := w.shape_disposition = 'required'
    and exists (
      select 1 from ops.work_shape_revision sr
       where sr.work_request_id = w.id and sr.work_request_version = w.version
         and sr.version = (select max(current_sr.version) from ops.work_shape_revision current_sr where current_sr.work_request_id = w.id)
    );
  return jsonb_build_object(
    'tier', case when jsonb_array_length(reasons) > 0 then 'heavy' else 'standard' end,
    'reasons', reasons,
    'shape_disposition', w.shape_disposition,
    'shape_ready', shape_ready,
    'acceptance_criteria_count', criteria_count,
    'dependency_ref_count', dependency_count,
    'max_steps', step_count
  );
end;
$_$;


--
-- Name: heavy_build_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heavy_build_digest(p_preimage jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select 'sha256:' || encode(public.digest(p_preimage::text, 'sha256'), 'hex');
$$;


--
-- Name: heavy_build_jsonb_has_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heavy_build_jsonb_has_exact_keys(p_document jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_typeof(p_document) = 'object'
     and (select array_agg(k order by k) from jsonb_object_keys(p_document) k)
         is not distinct from
         (select array_agg(k order by k) from unnest(p_keys) k);
$$;


--
-- Name: heavy_build_ready_plan_gate(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.heavy_build_ready_plan_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  p ops.sourced_work_request_plan%rowtype;
  a ops.heavy_build_admission_revision%rowtype;
  r ops.heavy_build_plan_review%rowtype;
  classification jsonb;
  heavy boolean;
  admission_found boolean;
begin
  if old.state = 'triaged' and new.state = 'ready' and old.capture_idempotency_key is not null then
    select plan.* into p
      from ops.sourced_work_request_plan_acceptance_receipt acceptance
      join ops.sourced_work_request_plan plan on plan.id=acceptance.plan_id
     where acceptance.work_request_id=old.id and acceptance.base_version=old.version and acceptance.result_version=new.version
     order by acceptance.accepted_at desc limit 1;
    if not found then return new; end if;
    classification := ops.heavy_build_classification(old.id,p.scope_summary,p.dependency_refs,p.caps);
    select x.* into a from ops.heavy_build_admission_revision x where x.plan_id=p.id order by x.version desc limit 1;
    admission_found := found;
    heavy := classification->>'tier'='heavy' or admission_found;
    if heavy then
      if new.shape_disposition is distinct from 'required'
         or not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id=old.id and sr.work_request_version=old.version
                         and sr.version=(select max(current_sr.version) from ops.work_shape_revision current_sr where current_sr.work_request_id=old.id)) then
        raise exception 'heavy build plan requires a current evidence-backed Work Shape';
      end if;
      if a.id is null then
        raise exception 'heavy build plan requires a typed research and master-plan admission receipt';
      end if;
      select x.* into r from ops.heavy_build_plan_review x where x.admission_id=a.id order by x.version desc limit 1;
      if r.id is null or r.verdict <> 'pass' then
        raise exception 'heavy build plan requires a fresh passing independent review';
      end if;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: hermes_runtime_admission_for_brief(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.hermes_runtime_admission_for_brief(p_runtime_slug text, p_profile_key text, p_sponsor_slug text, p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare
  base jsonb;
  tenant text := current_setting('carr.organization_tenant_id',true);
  runtime jsonb;
  route ops.work_request_execution_environment_binding%rowtype;
  provider ops.execution_environment_provider%rowtype;
  conformance ops.execution_environment_conformance%rowtype;
begin
  base := ops.hermes_runtime_admission_for_brief_v1(
    p_runtime_slug,p_profile_key,p_sponsor_slug,p_work_request,p_binding_id);
  if coalesce((base->>'authorized')::boolean,false) is not true then return base; end if;

  select e.runtime_profile
    into runtime
    from ops.execution_envelope_v1 e
    join ops.context_activation_binding b on b.id=e.activation_binding_id
    join ops.work_request w on w.id=b.work_request_id
   where e.organization_tenant_id=tenant and b.organization_tenant_id=tenant
     and w.organization_tenant_id=tenant and w.ref=p_work_request
     and b.binding_id=p_binding_id and e.activation_binding_id=b.id
     and b.expires_at>now() and e.expires_at>now() and w.version=b.work_request_version;
  if not found then
    return jsonb_build_object('status','stale','authorized',false,'reason','execution_environment_binding_not_exact');
  end if;
  select eb.* into route
    from ops.context_activation_binding b
    join ops.work_request_execution_assignment a on a.work_request_id=b.work_request_id
    join ops.work_request_execution_environment_binding eb on eb.assignment_id=a.id
   where b.binding_id=p_binding_id and b.organization_tenant_id=tenant;
  select * into provider from ops.execution_environment_provider where id=route.provider_id;
  select * into conformance from ops.execution_environment_conformance where id=route.conformance_id;
  if route.id is null or provider.id is null or conformance.id is null
     or ops.execution_environment_provider_current_state(provider.id)<>'active' or conformance.status<>'passed'
     or conformance.id is distinct from (select c.id from ops.execution_environment_conformance c where c.provider_id=provider.id order by c.observed_at desc,c.id desc limit 1)
     or runtime->>'environment_provider_ref' is distinct from route.binding->>'provider_ref'
     or runtime->>'environment_provider_version' is distinct from route.binding->>'provider_version'
     or runtime->>'environment_provider_digest' is distinct from provider.manifest_digest
     or runtime->>'environment_requirement_digest' is distinct from route.requirement_digest
     or runtime->>'environment_configuration_digest' is distinct from route.configuration_digest
     or runtime->>'environment_backend_kind' is distinct from provider.backend_kind
     or runtime->>'environment_source_class' is distinct from provider.source_class
     or runtime->>'environment_isolation_class' is distinct from provider.manifest->>'isolation_class'
     or runtime->'environment_capability_refs' is distinct from provider.manifest->'capability_refs'
     or runtime->>'environment_conformance_ref' is distinct from conformance.run_ref
     or runtime->>'environment_conformance_digest' is distinct from conformance.run_digest
     or runtime->>'environment_binding_digest' is distinct from route.binding_digest then
    return jsonb_build_object('status','stale','authorized',false,'reason','execution_environment_binding_not_exact');
  end if;

  return base||jsonb_build_object(
    'environment_provider_ref',runtime->>'environment_provider_ref',
    'environment_provider_version',(runtime->>'environment_provider_version')::integer,
    'environment_provider_digest',runtime->>'environment_provider_digest',
    'environment_requirement_digest',runtime->>'environment_requirement_digest',
    'environment_configuration_digest',runtime->>'environment_configuration_digest',
    'environment_backend_kind',runtime->>'environment_backend_kind',
    'environment_source_class',runtime->>'environment_source_class',
    'environment_isolation_class',runtime->>'environment_isolation_class',
    'environment_capability_refs',runtime->'environment_capability_refs',
    'environment_conformance_ref',runtime->>'environment_conformance_ref',
    'environment_conformance_digest',runtime->>'environment_conformance_digest',
    'environment_binding_digest',runtime->>'environment_binding_digest',
    'execution_environment_operator_surface','job-passport:route-and-agent-topology',
    'execution_environment_telemetry_ref','observatory:execution-environment:'||provider.provider_key);
end $$;


--
-- Name: hermes_runtime_admission_for_brief_v1(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.hermes_runtime_admission_for_brief_v1(p_runtime_slug text, p_profile_key text, p_sponsor_slug text, p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare
  tenant text := current_setting('carr.organization_tenant_id', true);
  runtime_actor actor%rowtype;
  sponsor actor%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype;
  expected_state_version integer;
  expected_plan_hash text;
  expected_runtime text := 'runtime:' || p_profile_key;
  expected_agent text := 'agent:' || p_profile_key;
  actual_envelope_digest text;
begin
  -- The caller cannot choose any of these values in the tool payload: the
  -- Worker passes the authenticated actor and sponsor, while the rest is the
  -- exact Bot-Brief request. Unknown actors and missing tenant context refuse
  -- without revealing another tenant's registration.
  if p_runtime_slug is distinct from 'hermes-pilot' then
    return jsonb_build_object('status','not_registered','authorized',false,'reason','runtime_identity_not_registered');
  end if;
  select * into runtime_actor from actor
   where slug='hermes-pilot' and kind='automation' and active;
  if runtime_actor.id is null or coalesce(tenant,'')='' or p_work_request is null or p_binding_id is null then
    return jsonb_build_object('status','not_registered','authorized',false,'reason','runtime_or_activation_missing');
  end if;
  select * into sponsor from actor where slug=p_sponsor_slug and kind='human' and active;
  if sponsor.id is null then
    return jsonb_build_object('status','stale','authorized',false,'reason','sponsoring_human_unavailable');
  end if;

  select e.* into envelope_row
    from ops.execution_envelope_v1 e
    join ops.context_activation_binding b on b.id=e.activation_binding_id
    join ops.work_request w on w.id=b.work_request_id
    join ops.sourced_work_request_plan plan on plan.id=b.plan_id
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.plan_id=plan.id
    join ops.work_request_execution_assignment a on a.work_request_id=w.id
      and a.sponsoring_human_id=sponsor.id
    join agent_profile p on p.id=a.profile_id
   where e.organization_tenant_id=tenant and b.organization_tenant_id=tenant
     and w.organization_tenant_id=tenant and w.ref=p_work_request
     and b.binding_id=p_binding_id and e.activation_binding_id=b.id
     and b.expires_at > now() and e.expires_at > now()
     and w.version=b.work_request_version and plan.work_request_id=w.id
     and plan.plan_hash=b.plan_hash and ar.plan_hash=b.plan_hash
     and ar.result_version=w.version and p.profile_key=p_profile_key
     and e.work_request_id=w.id and e.plan_hash=b.plan_hash
     and p.status='active' and p.current_model is not null and p.current_desk is not null;
  if not found then
    return jsonb_build_object('status','stale','authorized',false,'reason','activation_or_envelope_not_exact');
  end if;

  select b.work_request_version, b.plan_hash
    into expected_state_version, expected_plan_hash
    from ops.context_activation_binding b
   where b.id=envelope_row.activation_binding_id;

  actual_envelope_digest := 'sha256:' || encode(
    public.digest(ops.guidance_import_canonical_json(envelope_row.envelope),'sha256'),'hex');

  if envelope_row.envelope->'server_binding'->'identity'->>'runtime_principal' is distinct from expected_runtime
     or envelope_row.envelope->'server_binding'->'identity'->>'agent_principal_id' is distinct from expected_agent
     or envelope_row.envelope->'server_binding'->'identity'->>'sponsoring_human_id' is distinct from ('human:' || p_sponsor_slug)
     or envelope_row.envelope->'server_binding'->'identity'->>'organization_tenant_id' is distinct from tenant
     or envelope_row.envelope->'server_binding'->'identity'->>'client_mutable' is distinct from 'false'
     or envelope_row.envelope->'server_binding'->'authority'->>'read_only' is distinct from 'true'
     or envelope_row.envelope->'server_binding'->'authority'->>'client_mutable' is distinct from 'false'
     or envelope_row.envelope->'server_binding'->'authority'->>'capability_profile' is distinct from 'capability:metadata-only'
     or envelope_row.envelope->'server_binding'->'adapter'->>'surface' is distinct from 'hermes_desktop'
     or envelope_row.envelope->'server_binding'->'adapter'->>'adapter_id' is distinct from 'adapter:hermes-desktop'
     or envelope_row.envelope->'server_binding'->'adapter'->>'adapter_version' is distinct from 'v1'
     or envelope_row.envelope->'server_binding'->'adapter'->>'native_session_ref' is distinct from ('native:profile-' || p_profile_key)
     or envelope_row.envelope->'server_binding'->'adapter'->>'configuration_fingerprint' is distinct from envelope_row.configuration_digest
     or envelope_row.runtime_profile->>'profile_key' is distinct from p_profile_key
     or envelope_row.runtime_profile->>'profile_version' is distinct from (
       select p.version::text from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.runtime_profile->>'model_id' is distinct from (
       select 'model:' || p.current_model from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.runtime_profile->>'desk' is distinct from (
       select p.current_desk from agent_profile p where p.profile_key=p_profile_key)
     or envelope_row.envelope->'server_binding'->'adapter'->>'provider_id' is distinct from envelope_row.runtime_profile->>'provider_id'
     or envelope_row.envelope->'server_binding'->'adapter'->>'model_id' is distinct from envelope_row.runtime_profile->>'model_id'
     or envelope_row.envelope->'state_binding'->>'state_version' is distinct from expected_state_version::text
     or envelope_row.envelope->'state_binding'->>'canonical_record_digest' is distinct from expected_plan_hash
     or envelope_row.envelope->>'work_request_id' is distinct from p_work_request
     or envelope_row.envelope->>'context_activation_ref' is distinct from p_binding_id
     or envelope_row.envelope_digest is distinct from actual_envelope_digest then
    return jsonb_build_object('status','stale','authorized',false,'reason','server_envelope_identity_mismatch');
  end if;

  return jsonb_build_object(
    'status','registered','authorized',true,'reason','exact_server_envelope',
    'registration_scope','execution_envelope','grants_authority',false,
    'runtime_registration_id','envelope:' || envelope_row.id::text,
    'runtime_principal',envelope_row.envelope->'server_binding'->'identity'->>'runtime_principal',
    'agent_principal_id',envelope_row.envelope->'server_binding'->'identity'->>'agent_principal_id',
    'organization_tenant_id',tenant,'sponsoring_human_slug',p_sponsor_slug,
    'work_request',p_work_request,
    'profile_version',(envelope_row.runtime_profile->>'profile_version')::integer,
    'native_session_ref',envelope_row.envelope->'server_binding'->'adapter'->>'native_session_ref',
    'surface',envelope_row.envelope->'server_binding'->'adapter'->>'surface',
    'adapter_id',envelope_row.envelope->'server_binding'->'adapter'->>'adapter_id',
    'adapter_version',envelope_row.envelope->'server_binding'->'adapter'->>'adapter_version',
    'provider_id',envelope_row.envelope->'server_binding'->'adapter'->>'provider_id',
    'model_id',envelope_row.envelope->'server_binding'->'adapter'->>'model_id',
    'configuration_fingerprint',envelope_row.envelope->'server_binding'->'adapter'->>'configuration_fingerprint',
    'capability_profile',envelope_row.envelope->'server_binding'->'authority'->>'capability_profile',
    'read_only',true,'envelope_digest',envelope_row.envelope_digest,
    'activation_binding_id',p_binding_id,'expires_at',envelope_row.expires_at,
    'device_binding_status','not_asserted',
    'operator_surface','job-passport:context-activation',
    'telemetry_ref','observatory:activation-reliability:' || p_binding_id
  );
end $$;


--
-- Name: calendar_prebrief_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    sponsor text NOT NULL,
    destination text NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    allowlist_revision_id uuid NOT NULL,
    source_attestation_id uuid NOT NULL,
    canonical_event_digest text CONSTRAINT calendar_prebrief_canary_receip_canonical_event_digest_not_null NOT NULL,
    event_count integer NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT calendar_prebrief_canary_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_canary_receipt_canonical_event_digest_check CHECK ((canonical_event_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_canary_receipt_destination_check CHECK ((destination = ANY (ARRAY['calendar-prebrief-canary-joe'::text, 'calendar-prebrief-canary-dell'::text]))),
    CONSTRAINT calendar_prebrief_canary_receipt_event_count_check CHECK ((event_count >= 0)),
    CONSTRAINT calendar_prebrief_canary_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: ingest_calendar_prebrief_canary_projection(uuid, uuid, text, text[], jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_calendar_prebrief_canary_projection(p_job_id uuid, p_lease uuid, p_destination text, p_observed_calendar_keys text[], p_events jsonb) RETURNS ops.calendar_prebrief_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_job ops.job%rowtype; v_sponsor text; v_session_sponsor text; v_destination text;
  v_observed text[]; v_event_count integer; v_event_digest text; v_source ops.calendar_prebrief_source_attestation_receipt%rowtype;
  v_receipt ops.calendar_prebrief_canary_receipt%rowtype; v_event jsonb;
  v_current_revision uuid; v_current_digest text;
begin
  case session_user
    when 'carr_calendar_prebrief_canary_joe' then v_session_sponsor := 'joe';
    when 'carr_calendar_prebrief_canary_dell' then v_session_sponsor := 'dell';
    else raise exception using errcode='42501',message='calendar prebrief canary requires its named externally provisioned execution identity';
  end case;
  if not pg_has_role(session_user,'carr_calendar_prebrief_canary_jobs','member') then
    raise exception using errcode='42501',message='calendar prebrief canary execution identity lacks its capability bundle';
  end if;
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief canary requires current live job lease';
  end if;
  select owner_actor into v_sponsor from ops.job_definition
    where key=v_job.definition_key and version=v_job.definition_version for update;
  v_destination:=case v_job.definition_key
    when 'calendar-prebrief-canary-joe-daily' then 'calendar-prebrief-canary-joe'
    when 'calendar-prebrief-canary-dell-daily' then 'calendar-prebrief-canary-dell'
  end;
  if not found or v_job.mode<>'canary' or v_sponsor<>v_session_sponsor or p_destination is distinct from v_destination
     or (v_job.definition_key='calendar-prebrief-canary-joe-daily' and v_sponsor<>'joe')
     or (v_job.definition_key='calendar-prebrief-canary-dell-daily' and v_sponsor<>'dell')
     or v_job.definition_key not in ('calendar-prebrief-canary-joe-daily','calendar-prebrief-canary-dell-daily') then
    raise exception using errcode='42501',message='calendar prebrief canary mode or destination does not match the static job owner';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  select event_count,canonical_event_digest into v_event_count,v_event_digest
    from ops.calendar_prebrief_canonical_event_digest(p_events);
  select * into v_source from ops.calendar_prebrief_source_attestation_receipt
   where job_id=v_job.id and attempt=v_job.attempt;
  if not found then
    raise exception using errcode='55000',message='calendar prebrief canary requires an exact immutable verified source envelope';
  end if;
  select active_revision_id,configuration_digest into v_current_revision,v_current_digest
    from ops.calendar_prebrief_allowed_calendar where sponsor=v_sponsor for update;
  if v_current_revision is null or v_current_digest is null or v_source.lease_token<>p_lease or v_source.sponsor<>v_sponsor or v_source.mode<>'canary'
     or v_source.destination<>v_destination or v_source.snapshot_at<>v_job.scheduled_for
     or v_source.allowlist_revision_id<>v_current_revision or v_source.allowlist_digest<>v_current_digest
     or v_source.observed_calendar_keys is distinct from v_observed or v_source.event_count<>v_event_count
     or v_source.canonical_event_digest<>v_event_digest then
    raise exception using errcode='55000',message='calendar prebrief canary requires an exact immutable verified source envelope';
  end if;
  select * into v_receipt from ops.calendar_prebrief_canary_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_receipt.source_attestation_id<>v_source.id or v_receipt.destination<>v_destination
       or v_receipt.canonical_event_digest<>v_event_digest then
      raise exception using errcode='23505',message='calendar prebrief canary replay conflicts with immutable attempt';
    end if;
    return v_receipt;
  end if;
  if exists(select 1 from ops.calendar_prebrief_canary_receipt where sponsor=v_sponsor and destination=v_destination and snapshot_at>v_job.scheduled_for) then
    raise exception using errcode='22023',message='calendar prebrief canary refuses stale snapshot';
  end if;
  if not exists(select 1 from ops.job where id=v_job.id and state='running' and lease_token=p_lease and leased_until>=now()) then
    raise exception using errcode='55000',message='calendar prebrief canary lease expired before isolated replacement';
  end if;
  if exists(select 1 from jsonb_array_elements(p_events) e(value)
      where coalesce(e.value->>'occurrence_key','') !~ '^[0-9a-f]{64}$')
     or v_event_count<>(select count(distinct e.value->>'occurrence_key') from jsonb_array_elements(p_events) e(value)) then
    raise exception using errcode='22023',message='calendar prebrief canary requires distinct opaque occurrence keys';
  end if;
  delete from ops.calendar_prebrief_canary_event where sponsor=v_sponsor and destination=v_destination;
  for v_event in select value from jsonb_array_elements(p_events) loop
    insert into ops.calendar_prebrief_canary_event(sponsor,destination,occurrence_key,snapshot_at,allowlist_revision_id,source_attestation_id)
    values(v_sponsor,v_destination,v_event->>'occurrence_key',v_job.scheduled_for,v_source.allowlist_revision_id,v_source.id);
  end loop;
  insert into ops.calendar_prebrief_canary_receipt(job_id,attempt,sponsor,destination,snapshot_at,allowlist_revision_id,source_attestation_id,canonical_event_digest,event_count)
  values(v_job.id,v_job.attempt,v_sponsor,v_destination,v_job.scheduled_for,v_source.allowlist_revision_id,v_source.id,v_event_digest,v_event_count)
  returning * into v_receipt;
  return v_receipt;
end $_$;


--
-- Name: calendar_prebrief_projection_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_projection_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    sponsor text NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    allowlist_revision_id uuid CONSTRAINT calendar_prebrief_projection_rec_allowlist_revision_id_not_null NOT NULL,
    allowlist_digest text NOT NULL,
    snapshot_digest text NOT NULL,
    event_count integer NOT NULL,
    participant_count integer NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    source_attestation_id uuid CONSTRAINT calendar_prebrief_projection_rec_source_attestation_id_not_null NOT NULL,
    CONSTRAINT calendar_prebrief_projection_receipt_allowlist_digest_check CHECK ((allowlist_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_projection_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_event_count_check CHECK ((event_count >= 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_participant_count_check CHECK ((participant_count >= 0)),
    CONSTRAINT calendar_prebrief_projection_receipt_snapshot_digest_check CHECK ((snapshot_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_projection_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: ingest_calendar_prebrief_projection(uuid, uuid, text[], jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_calendar_prebrief_projection(p_job_id uuid, p_lease uuid, p_observed_calendar_keys text[], p_events jsonb) RETURNS ops.calendar_prebrief_projection_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_job ops.job%rowtype;
  v_sponsor text;
  v_session_sponsor text;
  v_execution_kind text;
  v_allowed text[];
  v_allowlist_digest text;
  v_allowlist_revision_id uuid;
  v_observed text[];
  v_event jsonb;
  v_event_id uuid;
  v_calendar_key text;
  v_event_key text;
  v_occurrence_key text;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_title text;
  v_location text;
  v_participant_ref text;
  v_party_id uuid;
  v_subject_type text;
  v_subject_id uuid;
  v_match_count integer;
  v_event_participant_count integer;
  v_event_count integer := 0;
  v_participant_count integer := 0;
  v_canonical_events jsonb;
  v_event_digest text;
  v_snapshot_digest text;
  v_receipt ops.calendar_prebrief_projection_receipt%rowtype;
  v_source ops.calendar_prebrief_source_attestation_receipt%rowtype;
begin
  case session_user
    when 'carr_calendar_prebrief_joe' then v_session_sponsor := 'joe';
    when 'carr_calendar_prebrief_dell' then v_session_sponsor := 'dell';
    else raise exception using errcode='42501',message='calendar prebrief projection requires its named externally provisioned execution identity';
  end case;
  if not pg_has_role(session_user,'carr_calendar_prebrief_jobs','member') then
    raise exception using errcode='42501',message='calendar prebrief projection execution identity lacks its capability bundle';
  end if;
  if p_events is null or pg_column_size(p_events)>262144 or jsonb_typeof(p_events)<>'array' then
    raise exception using errcode='22023',message='calendar prebrief projection requires a bounded event array';
  end if;
  if jsonb_array_length(p_events)>128 then
    raise exception using errcode='22023',message='calendar prebrief projection event count exceeds its bound';
  end if;

  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief projection requires current live job lease';
  end if;
  if v_job.scheduled_for < now()-interval '30 minutes' or v_job.scheduled_for > now()+interval '5 minutes' then
    raise exception using errcode='22023',message='calendar prebrief projection refuses job scheduled outside its DB-clock window';
  end if;
  select owner_actor,execution_kind into v_sponsor,v_execution_kind
    from ops.job_definition where key=v_job.definition_key and version=v_job.definition_version for update;
  if not found or v_job.definition_key not in ('calendar-prebrief-projection-joe-daily','calendar-prebrief-projection-dell-daily')
     or v_job.definition_version<>1 or v_job.mode<>'live' or v_execution_kind<>'deterministic'
     or (v_job.definition_key='calendar-prebrief-projection-joe-daily' and v_sponsor<>'joe')
     or (v_job.definition_key='calendar-prebrief-projection-dell-daily' and v_sponsor<>'dell')
     or v_sponsor<>v_session_sponsor then
    raise exception using errcode='42501',message='calendar prebrief projection execution identity does not match the static job owner';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('calendar-prebrief-projection:' || v_sponsor,0));
  select calendar_keys,configuration_digest,active_revision_id into v_allowed,v_allowlist_digest,v_allowlist_revision_id from ops.calendar_prebrief_allowed_calendar
   where sponsor=v_sponsor for update;
  if not found or coalesce(cardinality(v_allowed),0)=0
     or array_position(v_allowed,null) is not null
     or v_allowlist_digest !~ '^[0-9a-f]{64}$' or v_allowlist_revision_id is null
     or exists(select 1 from unnest(v_allowed) keys(k) where k !~ '^[0-9a-f]{64}$')
     or cardinality(v_allowed)<>(select count(distinct k) from unnest(v_allowed) keys(k))
     or not exists(select 1 from ops.calendar_prebrief_allowlist_receipt ar
                   where ar.id=v_allowlist_revision_id and ar.sponsor=v_sponsor
                     and ar.configuration_digest=v_allowlist_digest and ar.calendar_keys=v_allowed) then
    raise exception using errcode='22023',message='calendar prebrief projection requires a valid DB-owned sponsor allowlist';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  if coalesce(cardinality(v_observed),0)=0 or array_position(v_observed,null) is not null
     or exists(select 1 from unnest(v_observed) keys(k) where k !~ '^[0-9a-f]{64}$')
     or cardinality(v_observed)<>(select count(distinct k) from unnest(v_observed) keys(k))
     or v_observed is distinct from v_allowed then
    raise exception using errcode='22023',message='calendar prebrief observed calendars must have exact DB allowlist coverage';
  end if;

  -- Prevalidate every event and every participant before deleting a current
  -- projection.  A bad event cannot partially replace a good one.
  for v_event in select value from jsonb_array_elements(p_events) loop
    if pg_column_size(v_event)>4096 or jsonb_typeof(v_event)<>'object'
       or exists(select 1 from jsonb_object_keys(v_event) keys(key)
                 where key not in ('calendar_key','event_key','occurrence_key','starts_at','ends_at','title','location','participant_refs'))
       or exists(select key from unnest(array['calendar_key','event_key','occurrence_key','starts_at','ends_at','title','location','participant_refs']) required(key)
                 except select key from jsonb_object_keys(v_event) actual(key)) then
      raise exception using errcode='22023',message='calendar prebrief event has fields outside its bounded contract';
    end if;
    if jsonb_typeof(v_event->'calendar_key')<>'string' or jsonb_typeof(v_event->'event_key')<>'string'
       or jsonb_typeof(v_event->'occurrence_key')<>'string' or jsonb_typeof(v_event->'starts_at')<>'string'
       or jsonb_typeof(v_event->'ends_at')<>'string' or jsonb_typeof(v_event->'title')<>'string'
       or jsonb_typeof(v_event->'participant_refs')<>'array'
       or (v_event->'location' is not null and jsonb_typeof(v_event->'location') not in ('string','null')) then
      raise exception using errcode='22023',message='calendar prebrief event has invalid bounded fields';
    end if;
    v_event_participant_count:=jsonb_array_length(v_event->'participant_refs');
    if v_event_participant_count>16 or exists(select 1 from jsonb_array_elements(v_event->'participant_refs') refs(value) where jsonb_typeof(refs.value)<>'string')
       or v_event_participant_count<>(select count(distinct value#>>'{}') from jsonb_array_elements(v_event->'participant_refs') refs(value)) then
      raise exception using errcode='22023',message='calendar prebrief event has invalid or duplicate participant refs';
    end if;
    v_participant_count:=v_participant_count+v_event_participant_count;
    if v_participant_count>256 then
      raise exception using errcode='22023',message='calendar prebrief projection participant count exceeds its bound';
    end if;
    v_calendar_key:=v_event->>'calendar_key'; v_event_key:=v_event->>'event_key';
    v_occurrence_key:=v_event->>'occurrence_key'; v_title:=v_event->>'title'; v_location:=v_event->>'location';
    if v_calendar_key!~'^[0-9a-f]{64}$' or v_event_key!~'^[0-9a-f]{64}$' or v_occurrence_key!~'^[0-9a-f]{64}$'
       or length(v_title)>240 or coalesce(length(v_location),0)>240 or btrim(v_title)=''
       or v_title~'[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
       or coalesce(v_location,'')~'[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
       or v_title~*'(^|[^[:alnum:]])[a-z][a-z0-9+.-]*:[^[:space:]]' or coalesce(v_location,'')~*'(^|[^[:alnum:]])[a-z][a-z0-9+.-]*:[^[:space:]]'
       or v_title~*'www\.' or coalesce(v_location,'')~*'www\.'
       or v_title~*'\m(join|meeting|conference)[[:space:]]*(id|code|link)?[[:space:]]*[:#=]?[[:space:]]*[a-z0-9_-]{6,}\M'
       or coalesce(v_location,'')~*'\m(join|meeting|conference)[[:space:]]*(id|code|link)?[[:space:]]*[:#=]?[[:space:]]*[a-z0-9_-]{6,}\M' then
      raise exception using errcode='22023',message='calendar prebrief bounded fields must not contain email, URI, www, or join locator';
    end if;
    v_starts_at:=(v_event->>'starts_at')::timestamptz; v_ends_at:=(v_event->>'ends_at')::timestamptz;
    if v_ends_at<=v_starts_at or v_starts_at<v_job.scheduled_for-interval '7 days'
       or v_starts_at>v_job.scheduled_for+interval '45 days' or v_ends_at<v_job.scheduled_for-interval '7 days'
       or v_ends_at>v_job.scheduled_for+interval '45 days' then
      raise exception using errcode='22023',message='calendar prebrief event is outside its bounded snapshot window';
    end if;
    if not (v_calendar_key=any(v_allowed)) then
      raise exception using errcode='22023',message='calendar prebrief event calendar is outside the DB allowlist';
    end if;
    for v_participant_ref in select value from jsonb_array_elements_text(v_event->'participant_refs') loop
      if length(v_participant_ref)>128 or v_participant_ref!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' then
        raise exception using errcode='22023',message='calendar prebrief participant ref must be a bounded canonical ref';
      end if;
      select count(*) into v_match_count from v_ref_index r where r.ref=v_participant_ref and not r.merged and r.party_id is not null;
      if v_match_count<>1 then
        raise exception using errcode='22023',message='calendar prebrief participant ref does not resolve uniquely to one live unmerged party';
      end if;
    end loop;
  end loop;
  if (select count(*) from jsonb_array_elements(p_events) element(value))
     <> (select count(distinct value->>'occurrence_key') from jsonb_array_elements(p_events) element(value)) then
    raise exception using errcode='22023',message='calendar prebrief snapshot has duplicate occurrence keys';
  end if;

  select coalesce(jsonb_agg(event order by event->>'occurrence_key'),'[]'::jsonb) into v_canonical_events
  from (select jsonb_set(element.value,'{participant_refs}',coalesce((select jsonb_agg(ref order by ref)
          from jsonb_array_elements_text(element.value->'participant_refs') refs(ref)),'[]'::jsonb)) event
        from jsonb_array_elements(p_events) element(value)) normalized;
  v_event_digest:=encode(digest(convert_to(v_canonical_events::text,'UTF8'),'sha256'),'hex');
  v_snapshot_digest:=encode(digest(convert_to(jsonb_build_object(
    'allowlist_revision_id',v_allowlist_revision_id,'allowlist_digest',v_allowlist_digest,'observed_calendar_keys',to_jsonb(v_observed),
    'events',v_canonical_events,'snapshot_at',v_job.scheduled_for)::text,'UTF8'),'sha256'),'hex');
  select * into v_source from ops.calendar_prebrief_source_attestation_receipt
   where job_id=v_job.id and attempt=v_job.attempt;
  if not found or v_source.lease_token<>p_lease or v_source.sponsor<>v_sponsor
     or v_source.mode<>'live' or v_source.destination<>'live'
     or v_source.snapshot_at<>v_job.scheduled_for or v_source.allowlist_revision_id<>v_allowlist_revision_id
     or v_source.allowlist_digest<>v_allowlist_digest or v_source.observed_calendar_keys is distinct from v_observed
     or v_source.event_count<>jsonb_array_length(p_events) or v_source.canonical_event_digest<>v_event_digest then
    raise exception using errcode='55000',message='calendar prebrief projection requires an exact immutable verified source envelope';
  end if;
  select * into v_receipt from ops.calendar_prebrief_projection_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_receipt.snapshot_digest<>v_snapshot_digest then raise exception using errcode='23505',message='calendar prebrief job attempt conflicts with immutable snapshot'; end if;
    return v_receipt;
  end if;
  select * into v_receipt from ops.calendar_prebrief_projection_receipt where sponsor=v_sponsor and snapshot_at=v_job.scheduled_for;
  if found then
    if v_receipt.snapshot_digest<>v_snapshot_digest then raise exception using errcode='23505',message='calendar prebrief equal snapshot timestamp conflicts with immutable digest'; end if;
    return v_receipt;
  end if;
  if exists(select 1 from ops.calendar_prebrief_projection_receipt where sponsor=v_sponsor and snapshot_at>v_job.scheduled_for) then
    raise exception using errcode='22023',message='calendar prebrief projection refuses stale snapshot';
  end if;

  -- The second check is deliberately adjacent to the destructive replacement.
  if not exists(select 1 from ops.job where id=v_job.id and state='running' and lease_token=p_lease
                and leased_until is not null and leased_until>=now()) then
    raise exception using errcode='55000',message='calendar prebrief projection lease expired before current projection replacement';
  end if;
  delete from ops.calendar_prebrief_projection_event where sponsor=v_sponsor;
  v_participant_count:=0;
  for v_event in select value from jsonb_array_elements(p_events) loop
    insert into ops.calendar_prebrief_projection_event
      (sponsor,calendar_key,event_key,occurrence_key,starts_at,ends_at,title,location,snapshot_at,allowlist_revision_id)
    values(v_sponsor,v_event->>'calendar_key',v_event->>'event_key',v_event->>'occurrence_key',
      (v_event->>'starts_at')::timestamptz,(v_event->>'ends_at')::timestamptz,v_event->>'title',v_event->>'location',v_job.scheduled_for,v_allowlist_revision_id)
    returning id into v_event_id;
    v_event_count:=v_event_count+1;
    for v_participant_ref in select value from jsonb_array_elements_text(v_event->'participant_refs') loop
      select r.party_id,r.subject_type,r.subject_id into v_party_id,v_subject_type,v_subject_id from v_ref_index r
       where r.ref=v_participant_ref and not r.merged and r.party_id is not null;
      insert into ops.calendar_prebrief_projection_participant(event_id,party_id,subject_type,subject_id,participant_ref)
      values(v_event_id,v_party_id,v_subject_type,v_subject_id,v_participant_ref);
      v_participant_count:=v_participant_count+1;
    end loop;
  end loop;
  insert into ops.calendar_prebrief_projection_receipt(job_id,attempt,sponsor,snapshot_at,allowlist_revision_id,allowlist_digest,source_attestation_id,snapshot_digest,event_count,participant_count)
  values(v_job.id,v_job.attempt,v_sponsor,v_job.scheduled_for,v_allowlist_revision_id,v_allowlist_digest,v_source.id,v_snapshot_digest,v_event_count,v_participant_count)
  returning * into v_receipt;
  return v_receipt;
end $_$;


--
-- Name: ingest_renewal_signed_snapshot(uuid, uuid, uuid, text, text, timestamp with time zone, text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ingest_renewal_signed_snapshot(p_job_id uuid, p_lease uuid, p_snapshot_id uuid, p_provider text, p_key_fingerprint text, p_source_observed_at timestamp with time zone, p_payload_sha256 text, p_signature_sha256 text, p_rows jsonb) RETURNS TABLE(source_run_id uuid, row_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare v_job ops.job%rowtype; v_snapshot ops.renewal_source_snapshot%rowtype; v_row jsonb; v_candidate_id uuid; v_run ops.renewal_decision_source_run%rowtype; v_count integer; v_seq integer:=0; v_key text;
begin
 if session_user<>'carr_renewal_source_attestor' or not pg_has_role(session_user,'carr_renewal_source_attestors','member') then raise exception using errcode='42501',message='renewal signed ingress requires the exact renewal source attestor capability'; end if;
 if p_provider is null or btrim(p_provider)='' or octet_length(p_provider)>256 or p_key_fingerprint !~ '^[0-9a-f]{64}$' or p_payload_sha256 !~ '^[0-9a-f]{64}$' or p_signature_sha256 !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='renewal signed ingress provenance is malformed'; end if;
 if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>10000 or octet_length(p_rows::text)>8388608 then raise exception using errcode='22023',message='renewal signed ingress source rows are not bounded'; end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x(value) where jsonb_typeof(value)<>'object'
           or (select array_agg(key order by key) from jsonb_object_keys(value) key) is distinct from array['address','city','county','email','est_basis','est_lease_event','name','org_name','phone','segment','source_key','source_row','state','vertical']
           or nullif(btrim(value->>'source_key'),'') is null or nullif(btrim(value->>'name'),'') is null or octet_length(value->>'source_key')>512 or octet_length(value->>'name')>512 or octet_length((value->'source_row')::text)>65536 or octet_length(value::text)>131072 or jsonb_typeof(value->'source_row')<>'object') then
   raise exception using errcode='22023',message='renewal signed ingress source row shape is malformed'; end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x(value) group by value->>'source_key' having count(*)<>1) then raise exception using errcode='23505',message='renewal signed ingress source key is duplicated'; end if;
 select * into v_job from ops.job where id=p_job_id for update;
 if not found or v_job.definition_key<>'renewal-radar-source-daily' or v_job.definition_version<>1 or v_job.mode<>'live' or v_job.state<>'running' or v_job.lease_token is distinct from p_lease or v_job.leased_until is null or v_job.leased_until<now() then raise exception using errcode='55000',message='renewal signed ingress requires its exact current live job lease'; end if;
 if p_source_observed_at < now()-interval '36 hours' or p_source_observed_at > now()+interval '5 minutes' then raise exception using errcode='22023',message='renewal signed ingress source observation is outside its DB-clock window'; end if;
 insert into ops.renewal_source_snapshot(id,job_id,attempt,provider,key_fingerprint,source_observed_at,payload_sha256,signature_sha256,row_count)
 values(p_snapshot_id,v_job.id,v_job.attempt,p_provider,p_key_fingerprint,p_source_observed_at,p_payload_sha256,p_signature_sha256,jsonb_array_length(p_rows)) on conflict(id) do nothing;
 select * into v_snapshot from ops.renewal_source_snapshot where id=p_snapshot_id for update;
 if not found or v_snapshot.job_id<>v_job.id or v_snapshot.attempt<>v_job.attempt or v_snapshot.provider<>p_provider or v_snapshot.key_fingerprint<>p_key_fingerprint or v_snapshot.source_observed_at<>p_source_observed_at or v_snapshot.payload_sha256<>p_payload_sha256 or v_snapshot.signature_sha256<>p_signature_sha256 or v_snapshot.row_count<>jsonb_array_length(p_rows) then raise exception using errcode='23505',message='renewal signed ingress snapshot identity conflicts with immutable receipt'; end if;
 select count(*) into v_count from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id;
 if v_count>0 then
   if v_count<>jsonb_array_length(p_rows) or exists((select value->>'source_key' from jsonb_array_elements(p_rows) x(value)) except (select source_key from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id)) or exists((select source_key from ops.renewal_source_snapshot_member where snapshot_id=p_snapshot_id) except (select value->>'source_key' from jsonb_array_elements(p_rows) x(value))) then raise exception using errcode='23505',message='renewal signed ingress replay conflicts with immutable source membership'; end if;
 else
   for v_row in select value from jsonb_array_elements(p_rows) x(value) loop
     v_seq:=v_seq+1; v_key:=btrim(v_row->>'source_key');
     insert into ingest_inbox(source,external_id,payload,status,triage_note) values('renewal-radar-signed',p_snapshot_id::text||':'||v_key,jsonb_build_object('provider',p_provider,'snapshot_id',p_snapshot_id,'observed_at',p_source_observed_at,'row',v_row),'new','signed renewal source ingress; payload is untrusted source data') on conflict(source,external_id) do nothing;
     insert into candidate_pool(source,source_key,source_seq,source_row,name,org_name,vertical,address,city,county,state,email,phone,segment,score,score_basis,est_lease_event,est_basis,status,created_by,updated_by)
       select 'renewal-radar',v_key,v_seq,v_row->'source_row',btrim(v_row->>'name'),nullif(btrim(v_row->>'org_name'),''),nullif(btrim(v_row->>'vertical'),''),nullif(btrim(v_row->>'address'),''),nullif(btrim(v_row->>'city'),''),nullif(btrim(v_row->>'county'),''),nullif(btrim(v_row->>'state'),''),nullif(btrim(v_row->>'email'),''),nullif(btrim(v_row->>'phone'),''),nullif(btrim(v_row->>'segment'),''),null,'unscored signed renewal source snapshot',nullif(v_row->>'est_lease_event','')::date,nullif(btrim(v_row->>'est_basis'),''),'pool',a.id,a.id from actor a where a.slug='system'
       on conflict(source,source_key) do update set source_seq=excluded.source_seq,source_row=excluded.source_row,name=excluded.name,org_name=excluded.org_name,vertical=excluded.vertical,address=excluded.address,city=excluded.city,county=excluded.county,state=excluded.state,email=excluded.email,phone=excluded.phone,segment=excluded.segment,score=null,score_basis='unscored signed renewal source snapshot',est_lease_event=excluded.est_lease_event,est_basis=excluded.est_basis,updated_by=excluded.updated_by where candidate_pool.status='pool' returning id into v_candidate_id;
     if v_candidate_id is null then raise exception using errcode='23505',message='renewal signed ingress source key conflicts with a non-pool candidate'; end if;
     insert into ops.renewal_source_snapshot_member(snapshot_id,source_key,candidate_id) values(p_snapshot_id,v_key,v_candidate_id);
     update ingest_inbox set status='filed',filed_refs=jsonb_build_object('candidate_pool',v_candidate_id::text) where source='renewal-radar-signed' and external_id=p_snapshot_id::text||':'||v_key and status='new';
   end loop;
 end if;
 select * into v_run from ops.seal_renewal_decision_source_run(p_job_id,p_lease,p_snapshot_id);
 source_run_id:=v_run.id; row_count:=v_snapshot.row_count; return next;
end $_$;


--
-- Name: initialize_cost_scope_tree(text, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.initialize_cost_scope_tree(p_tree_ref text, p_compiled_tree jsonb, p_empty_state_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_node jsonb;
begin
  if exists (select 1 from ops.cost_scope_tree where tree_ref = p_tree_ref) then
    return jsonb_build_object('ok', false, 'reason_id', 'cost_scope_tree_exists',
      'tree_ref', p_tree_ref);
  end if;
  insert into ops.cost_scope_tree(tree_ref, tree_id, tree_version)
  values (p_tree_ref, p_compiled_tree->>'tree_id', p_compiled_tree->>'tree_version');
  -- Parents before children: the self-referencing foreign key is checked per
  -- row, so the node rows are ordered by their ancestor depth here rather than
  -- by whatever key order the caller's JSON happened to carry.
  for v_node in
    select value from jsonb_array_elements(p_compiled_tree->'node_rows')
     order by (value->>'depth')::integer, value->>'node_id'
  loop
    insert into ops.cost_scope_node(
      tree_ref, node_id, parent_node_id, scope_kind, authorization_ceiling_units)
    values (p_tree_ref, v_node->>'node_id', v_node->>'parent_node_id',
            v_node->>'scope_kind', (v_node->>'authorization_ceiling_units')::bigint);
  end loop;
  insert into ops.cost_ledger_cell(tree_ref, ledger_version, state_digest)
  values (p_tree_ref, 0, p_empty_state_digest);
  return jsonb_build_object('ok', true, 'tree_ref', p_tree_ref,
    'ledger_version', 0, 'state_digest', p_empty_state_digest);
end $$;


--
-- Name: FUNCTION initialize_cost_scope_tree(p_tree_ref text, p_compiled_tree jsonb, p_empty_state_digest text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.initialize_cost_scope_tree(p_tree_ref text, p_compiled_tree jsonb, p_empty_state_digest text) IS 'WR-000111: the only way a cost scope tree, its nodes and its compare-and-swap cell come into existence. Every direct write on those relations is revoked.';


--
-- Name: invalidate_cognition_cache(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.invalidate_cognition_cache(p_dependency_ref text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  update ops.cognition_result_cache set invalidated_at=now()
   where invalidated_at is null and p_dependency_ref=any(dependency_refs);
  get diagnostics n=row_count;
  return n;
end $$;


--
-- Name: invalidate_cognition_cache_for_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.invalidate_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_dependency_ref text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; n integer; execution_kind text;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind into execution_kind from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition' then
    raise exception 'job % is not a cognition workflow',p_job_id;
  end if;
  if btrim(coalesce(p_dependency_ref,''))='' then raise exception 'dependency ref is required'; end if;
  with changed as (
    update ops.cognition_result_cache set invalidated_at=now()
     where invalidated_at is null and p_dependency_ref=any(dependency_refs)
     returning cache_key
  ), evidence as (
    insert into ops.cognition_cache_observation
      (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind,dependency_ref)
    select j.id,j.attempt,j.definition_key,j.definition_version,j.mode,cache_key,'invalidate',p_dependency_ref
      from changed
    on conflict (job_id,attempt,cache_key,observation_kind) do nothing
    returning 1
  ) select count(*) into n from evidence;
  return n;
end $$;


--
-- Name: issue_calendar_prebrief_capture_contract(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_calendar_prebrief_capture_contract(p_job_id uuid, p_lease uuid) RETURNS TABLE(challenge_id uuid, sponsor text, job_id uuid, attempt integer, lease_token uuid, scheduled_for timestamp with time zone, window_starts_at timestamp with time zone, window_ends_at timestamp with time zone, mode text, destination text, allowlist_revision_id uuid, allowlist_digest text, calendar_keys text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_job ops.job%rowtype; v_sponsor text; v_resolver_sponsor text; v_destination text;
  v_keys text[]; v_digest text; v_revision uuid; v_challenge ops.calendar_prebrief_capture_challenge%rowtype;
begin
  v_resolver_sponsor:=ops.calendar_prebrief_resolver_sponsor();
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief capture contract requires current live job lease';
  end if;
  if v_job.scheduled_for < now()-interval '30 minutes' or v_job.scheduled_for > now()+interval '5 minutes' then
    raise exception using errcode='22023',message='calendar prebrief capture contract refuses job scheduled outside its DB-clock window';
  end if;
  select owner_actor into v_sponsor from ops.job_definition where key=v_job.definition_key and version=v_job.definition_version for update;
  v_destination:=case v_job.definition_key
    when 'calendar-prebrief-projection-joe-daily' then 'live'
    when 'calendar-prebrief-projection-dell-daily' then 'live'
    when 'calendar-prebrief-canary-joe-daily' then 'calendar-prebrief-canary-joe'
    when 'calendar-prebrief-canary-dell-daily' then 'calendar-prebrief-canary-dell'
  end;
  if not found or v_sponsor<>v_resolver_sponsor or v_destination is null
     or (v_destination='live' and v_job.mode<>'live') or (v_destination<>'live' and v_job.mode<>'canary') then
    raise exception using errcode='42501',message='calendar prebrief capture contract identity, mode, or static job owner mismatch';
  end if;
  select a.calendar_keys,a.configuration_digest,a.active_revision_id into v_keys,v_digest,v_revision
    from ops.calendar_prebrief_allowed_calendar a where a.sponsor=v_sponsor for update;
  if not found or coalesce(cardinality(v_keys),0)=0 or v_revision is null then
    raise exception using errcode='22023',message='calendar prebrief capture contract requires current DB allowlist';
  end if;
  insert into ops.calendar_prebrief_capture_challenge
    (job_id,attempt,lease_token,sponsor,resolver_identity,mode,destination,scheduled_for,window_starts_at,window_ends_at,allowlist_revision_id,allowlist_digest,calendar_keys)
  values(v_job.id,v_job.attempt,p_lease,v_sponsor,session_user,v_job.mode,v_destination,v_job.scheduled_for,
         v_job.scheduled_for-interval '7 days',v_job.scheduled_for+interval '45 days',v_revision,v_digest,v_keys)
  returning * into v_challenge;
  return query select v_challenge.id,v_challenge.sponsor,v_challenge.job_id,v_challenge.attempt,v_challenge.lease_token,
    v_challenge.scheduled_for,v_challenge.window_starts_at,v_challenge.window_ends_at,v_challenge.mode,v_challenge.destination,
    v_challenge.allowlist_revision_id,v_challenge.allowlist_digest,v_challenge.calendar_keys;
end $$;


--
-- Name: issue_execution_envelope_v1(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_execution_envelope_v1(p_work_request text, p_binding_id text, p_idempotency_key uuid) RETURNS TABLE(envelope_id uuid, envelope_digest text, envelope jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id',true); provider_id uuid; provider_state text;
begin
  select eb.provider_id into provider_id
    from ops.context_activation_binding b
    join ops.work_request w on w.id=b.work_request_id
    join ops.work_request_execution_assignment a on a.work_request_id=w.id
    join ops.work_request_execution_environment_binding eb on eb.assignment_id=a.id
    join ops.execution_environment_conformance c on c.id=eb.conformance_id and c.status='passed'
   where b.binding_id=p_binding_id and b.organization_tenant_id=tenant
     and w.ref=p_work_request and w.organization_tenant_id=tenant
     and b.expires_at>now() and w.version=b.work_request_version
     and c.id=(select latest.id from ops.execution_environment_conformance latest where latest.provider_id=eb.provider_id order by latest.observed_at desc,latest.id desc limit 1);
  provider_state := ops.execution_environment_provider_current_state(provider_id);
  if provider_id is null or provider_state<>'active' then
    raise exception 'execution envelope requires an active conformance-passed environment provider binding';
  end if;
  return query select * from ops.issue_execution_envelope_v1_without_environment_gate(
    p_work_request,p_binding_id,p_idempotency_key);
end $$;


--
-- Name: issue_execution_envelope_v1_without_environment_gate(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_execution_envelope_v1_without_environment_gate(p_work_request text, p_binding_id text, p_idempotency_key uuid) RETURNS TABLE(envelope_id uuid, envelope_digest text, envelope jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id', true); binding ops.context_activation_binding%rowtype;
  work ops.work_request%rowtype; plan ops.sourced_work_request_plan%rowtype; assignment ops.work_request_execution_assignment%rowtype; profile agent_profile%rowtype; sponsor actor%rowtype; existing ops.execution_envelope_v1%rowtype; issued timestamptz := now(); expires timestamptz;
  runtime jsonb; topology jsonb; evaluation jsonb; configuration text; body jsonb; digest_text text;
begin
  if coalesce(tenant,'')='' then raise exception 'execution envelope requires authenticated tenant context'; end if;
  select b.* into binding from ops.context_activation_binding b join ops.work_request w on w.id=b.work_request_id
   where b.binding_id=p_binding_id and b.organization_tenant_id=tenant and w.ref=p_work_request
     and b.expires_at>=now() and w.version=b.work_request_version for share;
  if not found then raise exception 'execution envelope binding is not visible to tenant'; end if;
  select * into work from ops.work_request where id=binding.work_request_id for share;
  select * into plan from ops.sourced_work_request_plan where id=binding.plan_id for share;
  if plan.id is null or plan.work_request_id<>work.id or plan.plan_hash<>binding.plan_hash
     or not exists (select 1 from ops.sourced_work_request_plan_acceptance_receipt ar where ar.work_request_id=work.id and ar.plan_id=plan.id and ar.plan_hash=binding.plan_hash and ar.result_version=work.version) then
    raise exception 'execution envelope binding is stale or no longer the exact accepted plan';
  end if;
  select * into assignment from ops.work_request_execution_assignment where work_request_id=work.id for share;
  if not found then raise exception 'execution envelope requires a preassigned server-owned profile lane'; end if;
  select * into profile from agent_profile where id=assignment.profile_id and status='active' and current_model is not null and current_desk is not null for share;
  select * into sponsor from actor where id=assignment.sponsoring_human_id and kind='human' and active for share;
  if profile.id is null or sponsor.id is null then raise exception 'execution envelope assignment has no active durable runtime profile/sponsor'; end if;
  select * into existing from ops.execution_envelope_v1 where organization_tenant_id=tenant and idempotency_key=p_idempotency_key for share;
  if found then
    if existing.work_request_id<>work.id or existing.activation_binding_id<>binding.id then raise exception 'execution envelope idempotency conflict'; end if;
    return query select existing.id,existing.envelope_digest,existing.envelope,true; return;
  end if;
  -- A binding has one server-issued envelope.  A later request cannot cause a
  -- timestamp/profile snapshot to fork the same governed attempt.
  select * into existing from ops.execution_envelope_v1
   where organization_tenant_id=tenant and activation_binding_id=binding.id for share;
  if found then
    return query select existing.id,existing.envelope_digest,existing.envelope,true; return;
  end if;
  -- These bounded versioned metadata refs are server-issued configuration,
  -- never caller authority/provider/model selections. They contain no secret
  -- values and are retained with the immutable envelope for audit.
  runtime := jsonb_build_object('ref','runtime-profile:'||profile.profile_key||':v'||profile.version::text,'profile_key',profile.profile_key,'profile_version',profile.version,'provider_id','provider:'||split_part(profile.current_model,'/',1),'model_id','model:'||profile.current_model,'desk',profile.current_desk,'policy_ref',assignment.policy_ref,'policy_digest',assignment.policy_digest,'modality','modality:text','reasoning_effort_ref','reasoning-effort:governed-default','sampling_profile_ref','sampling:governed-default','context_budget',8192,'cache_policy_ref','cache:governed-default','knowledge_cutoff_posture','knowledge-cutoff:provider-declared','tool_calling_mode','tool-calling:metadata-only');
  runtime := runtime || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(runtime),'sha256'),'hex'));
  topology := jsonb_build_object('ref','execution-topology:single-governed-attempt-v1','kind','single_agent_loop','harness_digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object('harness','postgres-governed-attempt-v1')),'sha256'),'hex'),'parallelism','sequential','code_model_step_refs',jsonb_build_array('step:model-governed'),'fallback_policy_ref','fallback:stop-and-escalate','stop_condition_refs',jsonb_build_array('stop:capability-expired','stop:critical-failure'),'context_refresh_policy_ref','context-refresh:bound-revisions-only','memory_policy_ref','memory:context-never-authority','sandbox_ref','sandbox:metadata-only','guardrail_ref','guardrail:governed-default','threat_model_ref','threat-model:governed-default');
  topology := topology || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(topology),'sha256'),'hex'));
  evaluation := jsonb_build_object('ref','evaluation-plan:independent-risk-v1','lane_ref','lane:governed-work','risk_class','R2','rubric_digest','sha256:'||encode(public.digest('rubric:independent-risk-v1','sha256'),'hex'),'case_set_digest',binding.bundle_digest,'evaluator_policy_digest','sha256:'||encode(public.digest('evaluator-policy:r2-v1','sha256'),'hex'),'evaluator_ref','evaluator:authority-independent-v1','rubric_ref','rubric:independent-risk-v1','evaluator_version','version:v1','evaluator_digest','sha256:'||encode(public.digest('evaluator:authority-independent-v1:version:v1','sha256'),'hex'),'required_rungs',jsonb_build_array('rung:smoke','rung:regression'),'required_deterministic_check_refs',jsonb_build_array('check:activation-binding','check:critical-security'),'critical_dimensions',jsonb_build_array('dimension:correctness','dimension:security'),'human_acceptance_required',true,'outcome_horizon_ref',case when assignment.environment='rehearsal' then 'outcome-horizon:synthetic-fixture-zero' else 'outcome-horizon:r2-seven-day' end,'outcome_horizon_not_before',to_char((issued + case when assignment.environment='rehearsal' then interval '0' else interval '7 days' end) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'requirements',jsonb_build_object('required_evaluator_kinds',jsonb_build_array('deterministic','judge','human_acceptance'),'minimum_held_out_case_count',1,'minimum_calibration_ref_count',1,'maximum_critical_failure_count',0,'maximum_critical_failure_rate',0,'confidence_posture','lower_bound_required','drift_tolerance','no_critical_regression','independent_review_required',true,'human_acceptance_required',true,'outcome_horizon_required',true));
  evaluation := evaluation || jsonb_build_object('digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(evaluation),'sha256'),'hex'));
  configuration := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(runtime||topology||evaluation),'sha256'),'hex');
  expires := least(binding.expires_at, issued + interval '1 hour');
  body := jsonb_build_object(
    'schema_version','execution-envelope.v1','envelope_id','env:'||binding.binding_id,
    'work_request_id',work.ref,
    'plan_revision',jsonb_build_object('id','plan:'||binding.plan_id::text,'revision',plan.plan_version,'digest',binding.plan_hash),
    'agent_session',jsonb_build_object('id','session:'||binding.binding_id,'lease_expires_at',to_char(expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')),
    'issued_at',to_char(issued at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'expires_at',to_char(expires at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'state_binding',jsonb_build_object('state_version',work.version,'canonical_record_digest',binding.plan_hash,'accepted_resource_revisions','[]'::jsonb,'compare_and_swap_required',true),
    'phase_binding',jsonb_build_object('phase_id','phase:governed-execution','session_affinity','same_native_session_preferred','switch_conditions',jsonb_build_array('verified_checkpoint','phase_boundary'),'native_session_transfer','semantic_state_only'),
    'evaluation_context',jsonb_build_object('experiment_arm','same_pair_audited_state','auditor_mode','diverse_read_only_auditor','evaluation_kernel_ref',evaluation->>'ref','workflow_rubric_digest',evaluation->>'rubric_digest','case_set_digest',binding.bundle_digest),
    'request',jsonb_build_object('job_ref','job:'||work.ref,'input_digest',binding.bundle_digest,'data_class','metadata_only','allowed_actions','[]'::jsonb,'declared_expectations',jsonb_build_object('plan_step_refs','[]'::jsonb,'component_refs','[]'::jsonb,'component_dependencies','[]'::jsonb,'resource_refs','[]'::jsonb)),
    'server_binding',jsonb_build_object('identity',jsonb_build_object('organization_tenant_id',tenant,'sponsoring_human_id','human:'||sponsor.slug,'agent_principal_id','agent:'||profile.profile_key,'runtime_principal','runtime:'||profile.profile_key,'personal_brain_scope','none','personal_brain_version','none','personal_rule_count',0,'derived_by','server_identity_resolution','client_mutable',false),'authority',jsonb_build_object('environment',assignment.environment,'risk_class','R2','capability_profile','capability:metadata-only','capability_grant_ref','grant:'||assignment.id::text,'read_only',true,'derived_by','server_capability_resolution','client_mutable',false),'adapter',jsonb_build_object('surface','hermes_desktop','adapter_id','adapter:hermes-desktop','adapter_version','v1','harness_id','harness:postgres','harness_version','v1','provider_id','provider:'||split_part(profile.current_model,'/',1),'model_id','model:'||profile.current_model,'native_session_ref','native:profile-'||profile.profile_key,'configuration_fingerprint',configuration)),
    'handoff',jsonb_build_object('mode','original','replaces_agent_session_id',null,'capability_inherited',false,'checkpoint_ref',null,'native_session_transfer','semantic_state_only'),
    'activation_binding',jsonb_build_object('bundle_digest',binding.bundle_digest,'item_refs',(select coalesce(jsonb_agg(canonical_ref order by ordinal),'[]'::jsonb) from ops.context_activation_item where binding_id=binding.id),'mode',binding.mode,'retrieval_policy_version','v1'),
    'reliability_policy_binding',jsonb_build_object('policy_ref',assignment.policy_ref,'policy_digest',assignment.policy_digest,'risk_class','R2','mode',binding.mode),
    'context_activation_ref',binding.binding_id,'runtime_profile',runtime,'execution_topology',topology,'evaluation_plan',evaluation
  );
  digest_text := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(body),'sha256'),'hex');
  insert into ops.execution_envelope_v1(idempotency_key,organization_tenant_id,work_request_id,plan_hash,activation_binding_id,envelope_digest,envelope,runtime_profile,execution_topology,evaluation_plan,configuration_digest,issued_at,expires_at)
  values(p_idempotency_key,tenant,work.id,binding.plan_hash,binding.id,digest_text,body,runtime,topology,evaluation,configuration,issued,expires)
  returning id,ops.execution_envelope_v1.envelope_digest,ops.execution_envelope_v1.envelope into envelope_id,envelope_digest,envelope;
  return query select envelope_id,envelope_digest,envelope,false;
end $$;


--
-- Name: issue_tour_share_grant(text, uuid, text, jsonb, timestamp with time zone, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.issue_tour_share_grant(p_tenant text, p_projection_id uuid, p_token_digest text, p_permission_scopes jsonb, p_expires_at timestamp with time zone, p_receipt_digest text, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_id uuid; v_projection ops.tour_public_projection%rowtype;
begin
  if p_token_digest !~ '^sha256:[a-f0-9]{64}$' or p_receipt_digest !~ '^sha256:[a-f0-9]{64}$' or p_expires_at<=now() or jsonb_typeof(p_permission_scopes)<>'array' or not (p_permission_scopes <@ '["view_packet","view_map"]'::jsonb) or jsonb_array_length(p_permission_scopes)=0 or nullif(btrim(p_actor_id),'') is null then raise exception 'tour share payload is invalid'; end if;
  select * into v_projection from ops.tour_public_projection p where p.organization_tenant_id=p_tenant and p.id=p_projection_id and p.status='approved' and exists(select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id and s.canonical_projection_digest=p.projection_digest) and ops.read_tour_public_projection(p.organization_tenant_id,p.id) is not null for update;
  if not found then raise exception 'tour share requires a sealed projection'; end if;
  if p_permission_scopes ? 'view_map' and not ops.tour_public_map_projection_ready(p_tenant,p_projection_id)
  then raise exception 'tour map share requires current rights, sealed entrance coordinates, and an approved promotion receipt'; end if;
  if exists(select 1 from ops.tour_share_grant where organization_tenant_id=p_tenant and projection_id=p_projection_id) then raise exception 'tour share issue requires rotation'; end if;
  insert into ops.tour_share_grant(organization_tenant_id,projection_id,grant_version,token_digest,audience,permission_scopes,expires_at,status,receipt_digest,created_by_actor_id)
  values(p_tenant,p_projection_id,1,p_token_digest,'client',p_permission_scopes,p_expires_at,'active',p_receipt_digest,p_actor_id) returning id into v_id;
  return v_id;
end $_$;


--
-- Name: j1_clock_append_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_append_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_clock ops.j1_clock%rowtype;
  v_prior ops.j1_clock_revision%rowtype;
  v_binding ops.j1_clock_scope_binding%rowtype;
  v_error text; v_head_ordinal integer; v_prior_events integer; v_new_events integer;
  v_row record; v_field text;
begin
  select * into v_clock from ops.j1_clock where id = new.clock_id;
  if not found then
    raise exception '[j1_clock_identity_derived_from_origin] Journey 1 clock revision names an unknown clock';
  end if;

  -- VERSION CONFUSION, REFUSED BY NAME. A v1 record names an origin digest the
  -- current kernel cannot recompute; silently re-deriving it would rebase a
  -- sealed origin, so migration is explicit and external.
  if new.state_schema_version = any (ops.j1_clock_legacy_state_schemas()) then
    raise exception '[j1_clock_state_schema_current] Journey 1 clock history % is a legacy state schema and requires an explicit migration; this rail stores % only and never re-derives a sealed origin',
      new.state_schema_version, ops.j1_clock_state_schema();
  end if;
  if new.state_schema_version <> ops.j1_clock_state_schema() then
    raise exception '[j1_clock_state_schema_current] Journey 1 clock history % is not a state schema this rail stores',
      new.state_schema_version;
  end if;
  if v_clock.state_schema_version <> new.state_schema_version then
    raise exception '[j1_clock_state_schema_current] Journey 1 clock revision changes the state schema of its clock';
  end if;

  -- TENANT. A revision is stored under the tenant its identity was derived with.
  if v_clock.tenant <> 'carr-internal' then
    raise exception '[j1_clock_tenant_bound] Journey 1 clock % is not this tenant''s', v_clock.clock_key;
  end if;

  -- ATTRIBUTION. The writer is the server-established one, never a payload
  -- field. This is not one of the shared append invariants -- it is the record
  -- layer's own attribution rule and carries no invariant id, because it does
  -- not exist on the JavaScript side: there, the writer is derived from the live
  -- actor before a store can be constructed at all.
  if new.written_by_actor_id <> ops.portfolio_writer_actor_id() then
    raise exception 'Journey 1 clock revision actor does not match the authenticated writer context';
  end if;

  -- IDENTITY. The clock is the one this revision's OWN ORIGIN derives.
  if ops.j1_clock_identity_digest(v_clock.tenant, new.origin_receipt_digest,
       new.origin_at, new.origin_benchmark_manifest_digest) is distinct from v_clock.clock_key then
    raise exception '[j1_clock_identity_derived_from_origin] Journey 1 clock revision is being filed under %, but its own origin derives a different clock. A clock is addressed by its kernel origin and never by a name a caller chose',
      v_clock.clock_key;
  end if;

  -- THE AUTHORITATIVE SCOPE. A clock with NO scope binding is exactly the clock
  -- a second origin could have opened beside a running one, so a revision for an
  -- unbound clock is refused here rather than stored and explained afterwards.
  -- ops.j1_clock_bind_scope writes the binding earlier in the same transaction;
  -- this clause is what makes that mandatory for a direct caller of
  -- ops.j1_clock_append_revision who never runs the JavaScript at all.
  select * into v_binding from ops.j1_clock_scope_binding where clock_key = v_clock.clock_key;
  if not found then
    raise exception '[j1_clock_scope_binds_one_clock] Journey 1 clock % has no authoritative scope binding; bind the accepted scope with ops.j1_clock_bind_scope before appending. An unbound clock is one a second origin could have created beside another, and this rail does not store one',
      v_clock.clock_key;
  end if;
  if v_binding.tenant is distinct from v_clock.tenant then
    raise exception '[j1_clock_scope_sealed_at_creation] Journey 1 clock % is bound to a scope of another tenant', v_clock.clock_key;
  end if;

  -- CONTENT. It rebuilds to the digest it is filed under, or it is not the
  -- history it claims to be. Everything below this line diffs two histories, and
  -- diffing content that does not hash to its own digest would be meaningless.
  v_error := ops.j1_clock_revision_integrity_error(new.id);
  if v_error is not null then
    raise exception 'Journey 1 clock revision is not a storable history: %', v_error;
  end if;

  -- THE COMPARE-AND-SWAP.
  select coalesce(max(revision_ordinal), -1) into v_head_ordinal
    from ops.j1_clock_revision where clock_id = new.clock_id and id <> new.id;
  if new.prior_history_digest is null then
    if v_head_ordinal >= 0 then
      raise exception '[j1_clock_exact_prior_history_digest] Journey 1 clock % already has history; a null prior is a creation and a clock is created once. A caller-chosen label cannot restart it, because the identity is derived from the kernel origin',
        v_clock.clock_key;
    end if;
    if new.revision_ordinal <> 0 then
      raise exception '[j1_clock_exact_prior_history_digest] a creating revision is ordinal 0';
    end if;
    return null;
  end if;

  if v_head_ordinal < 0 then
    raise exception '[j1_clock_exact_prior_history_digest] Journey 1 clock % has no history, so there is no prior digest to match; create it with an explicit null prior',
      v_clock.clock_key;
  end if;
  select * into v_prior from ops.j1_clock_revision
   where clock_id = new.clock_id and revision_ordinal = v_head_ordinal;
  if new.revision_ordinal <> v_head_ordinal + 1 then
    raise exception '[j1_clock_exact_prior_history_digest] Journey 1 clock revision ordinal % does not follow the head at %',
      new.revision_ordinal, v_head_ordinal;
  end if;
  if new.prior_history_digest is distinct from v_prior.history_digest then
    raise exception '[j1_clock_exact_prior_history_digest] stale prior history digest for clock %: the head is %, this revision names %. Another writer appended first and this revision was computed against a history that is no longer the head',
      v_clock.clock_key, v_prior.history_digest, new.prior_history_digest;
  end if;
  -- The head must still be intact, or an already-corrupted head could authorize
  -- an illegal append.
  v_error := ops.j1_clock_revision_integrity_error(v_prior.id);
  if v_error is not null then
    raise exception 'Journey 1 clock head is not a readable history: %', v_error;
  end if;

  -- THE ORIGIN AND THE BASE DEADLINE IT PRODUCED ARE NEVER REWRITTEN. The base
  -- deadline rides along because the kernel derives it from the origin alone: a
  -- base deadline that moved means the origin moved, whatever the origin digest
  -- still says.
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'origin_receipt_digest',
    v_prior.origin_receipt_digest, new.origin_receipt_digest);
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'origin_at',
    v_prior.origin_at, new.origin_at);
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'origin_benchmark_manifest_digest',
    v_prior.origin_benchmark_manifest_digest, new.origin_benchmark_manifest_digest);
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'origin_receipt_ttl_policy_ms',
    v_prior.origin_receipt_ttl_policy_ms, new.origin_receipt_ttl_policy_ms);
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'base_deadline_at',
    v_prior.base_deadline_at, new.base_deadline_at);
  perform ops.j1_clock_assert_same('j1_clock_origin_never_rewritten', 'base_deadline_resolution',
    v_prior.base_deadline_resolution, new.base_deadline_resolution);

  -- THE COMPLETION SEALS. Once a completion is recorded, all five are identical
  -- in every later revision. The kernel refuses a PROJECTION that changes them;
  -- this refuses a WRITE that does, which the kernel cannot see.
  if v_prior.completion_receipt_digest is not null then
    perform ops.j1_clock_assert_same('j1_clock_completion_seals_never_changed', 'completion_receipt_digest',
      v_prior.completion_receipt_digest, new.completion_receipt_digest);
    perform ops.j1_clock_assert_same('j1_clock_completion_seals_never_changed', 'completion_observed_at',
      v_prior.completion_observed_at, new.completion_observed_at);
    perform ops.j1_clock_assert_same('j1_clock_completion_seals_never_changed', 'completion_receipt_ttl_policy_ms',
      v_prior.completion_receipt_ttl_policy_ms, new.completion_receipt_ttl_policy_ms);
    perform ops.j1_clock_assert_same('j1_clock_completion_seals_never_changed', 'completion_artifact_digest',
      v_prior.completion_artifact_digest, new.completion_artifact_digest);
    perform ops.j1_clock_assert_same('j1_clock_completion_seals_never_changed', 'completion_fixture_set_digest',
      v_prior.completion_fixture_set_digest, new.completion_fixture_set_digest);
  end if;

  -- A DURABLY RECORDED MISS NEVER UN-STICKS.
  if v_prior.miss_at is not null then
    perform ops.j1_clock_assert_same('j1_clock_recorded_miss_never_removed', 'miss_at',
      v_prior.miss_at, new.miss_at);
  end if;

  -- THE PRIOR EVENT CHAIN IS AN EXACT PREFIX OF THE NEXT. This is what makes a
  -- lost event, a removed miss event and an erased pause or amendment approval
  -- all unwritable, whichever field a writer tried to change.
  select count(*) into v_prior_events from ops.j1_clock_revision_event where revision_id = v_prior.id;
  select count(*) into v_new_events from ops.j1_clock_revision_event where revision_id = new.id;
  if v_new_events < v_prior_events then
    raise exception '[j1_clock_events_are_append_only] this revision carries % events where the head carries %; events are appended, never dropped',
      v_new_events, v_prior_events;
  end if;
  for v_row in
    select p.ordinal, p.event_digest as prior_digest, n.event_digest as next_digest
      from ops.j1_clock_revision_event p
      left join ops.j1_clock_revision_event n
        on n.revision_id = new.id and n.ordinal = p.ordinal
     where p.revision_id = v_prior.id
     order by p.ordinal
  loop
    if v_row.next_digest is distinct from v_row.prior_digest then
      raise exception '[j1_clock_events_are_append_only] event % is not the event the head recorded at that position: head %, supplied %',
        v_row.ordinal, v_row.prior_digest, coalesce(v_row.next_digest, 'nothing');
    end if;
  end loop;

  -- NO BACKDATING. `evaluated_at` is kernel time and compared as an instant, so
  -- the same instant spelled `Z` and `+00:00` is not a move. `recorded_at` is
  -- server time; the comparison is non-strict because two revisions written in
  -- one transaction share now().
  if new.evaluated_at::timestamptz < v_prior.evaluated_at::timestamptz then
    raise exception '[j1_clock_no_backdated_evaluation] this revision was evaluated at %, before the head at %',
      new.evaluated_at, v_prior.evaluated_at;
  end if;
  if new.recorded_at < v_prior.recorded_at then
    raise exception '[j1_clock_no_backdated_evaluation] the server clock moved backwards between two revisions of clock %',
      v_clock.clock_key;
  end if;

  -- DELIBERATELY NOT CONSTRAINED, because a plausible-looking guard here would
  -- be WRONG and would make the only writable answer the false one:
  --   * paused_ms is NOT monotone. A pause whose end was unknown is counted to
  --     the evaluation instant; when the blocker's actual end is honestly
  --     reported later, the credited hours GO DOWN.
  --   * due_at may move forward PAST an existing miss_at, when a pause approved
  --     before the deadline is reported after the miss. That never erases the
  --     miss -- which is why the miss rule is stated on miss_at and never on
  --     due_at.
  --   * current_benchmark_manifest_digest may change: that is what a
  --     partner-signed amendment does. The ORIGIN manifest is the immutable one.
  --   * status may move between the kernel's own values. This rail does not
  --     decide status and does not police its transitions; the one shape it
  --     refuses is the contradiction Q008.D1 names, at the table constraint and
  --     again in the integrity reader.
  return null;
end;
$$;


--
-- Name: FUNCTION j1_clock_append_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_append_guard() IS 'The authoritative Journey 1 clock append precondition, checked from the persisted rows at commit: current state schema, bound tenant, authenticated writer, an identity derived from the revision''s own origin, content that rebuilds to its digest, the exact prior-history compare-and-swap, an unchanged origin and base deadline, unchanged completion seals, a preserved recorded miss, an event chain the head''s is an exact prefix of, and no backdating. It deliberately does not constrain paused_ms, due_at, the current benchmark manifest or the status transition; see the body for why each would be wrong.';


--
-- Name: j1_clock_append_revision(text, text, text, text, uuid, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_append_revision(p_clock_key text, p_tenant text, p_clock_ref text, p_expected_prior_history_digest text, p_idempotency_key uuid, p_history_digest text, p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb, p_provenance jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_existing ops.j1_clock_revision%rowtype;
  v_clock ops.j1_clock%rowtype; v_actor uuid; v_revision uuid;
  v_ordinal integer; v_derived text; v_live text; v_row jsonb;
begin
  if p_idempotency_key is null then
    raise exception '[j1_clock_idempotency_key_binds_its_payload] a Journey 1 clock append must carry an idempotency key';
  end if;
  select * into v_existing from ops.j1_clock_revision where idempotency_key = p_idempotency_key;
  if found then
    -- EVERY BINDING PARAMETER IS COMPARED. A replay that matched on the content
    -- digest but named a different clock or a different prior is a different
    -- request wearing the same key.
    if (select c.clock_key from ops.j1_clock c where c.id = v_existing.clock_id) is distinct from p_clock_key
       or v_existing.history_digest is distinct from p_history_digest
       or v_existing.prior_history_digest is distinct from p_expected_prior_history_digest then
      raise exception '[j1_clock_idempotency_key_binds_its_payload] idempotency key % was already used for a different Journey 1 clock revision',
        p_idempotency_key;
    end if;
    return ops.j1_clock_revision_json(v_existing.id) || jsonb_build_object('replayed', true);
  end if;

  v_actor := ops.portfolio_writer_actor_id();

  -- IDENTITY IS DERIVED, NEVER ACCEPTED. The caller supplies a key; it is only
  -- ever compared against the one this revision's own origin produces.
  v_derived := ops.j1_clock_identity_digest(p_tenant,
    p_scalars ->> 'origin_receipt_digest', p_scalars ->> 'origin_at',
    p_scalars ->> 'origin_benchmark_manifest_digest');
  if v_derived is distinct from p_clock_key then
    raise exception '[j1_clock_identity_derived_from_origin] the supplied clock key is not the one this origin derives: derived %, supplied %',
      v_derived, p_clock_key;
  end if;

  -- The writer's half of the lock protocol described at
  -- ops.j1_clock_child_frozen_after_next_revision(). Taken before the head is
  -- read, so a neighbour's append settles first and the head read below is a
  -- settled answer rather than a stale one.
  perform ops.j1_clock_lock(p_clock_key);

  select * into v_clock from ops.j1_clock where clock_key = p_clock_key;
  if not found then
    if p_expected_prior_history_digest is not null then
      raise exception '[j1_clock_exact_prior_history_digest] Journey 1 clock % does not exist, so there is no prior digest to match; create it with an explicit null prior',
        p_clock_key;
    end if;
    insert into ops.j1_clock(clock_key, tenant, clock_ref, state_schema_version,
      origin_receipt_digest, origin_at, origin_benchmark_manifest_digest, created_by_actor_id)
    values (p_clock_key, p_tenant, p_clock_ref, p_scalars ->> 'schema_version',
      p_scalars ->> 'origin_receipt_digest', p_scalars ->> 'origin_at',
      p_scalars ->> 'origin_benchmark_manifest_digest', v_actor)
    returning * into v_clock;
  elsif v_clock.tenant is distinct from p_tenant then
    raise exception '[j1_clock_tenant_bound] Journey 1 clock % belongs to another tenant', p_clock_key;
  end if;

  select coalesce(max(revision_ordinal), -1) + 1 into v_ordinal
    from ops.j1_clock_revision where clock_id = v_clock.id;

  -- THE GUARD'S DEFERRAL MODE IS OWNED BY THIS FUNCTION, FOR THE LENGTH OF THIS
  -- CALL, AND IS SET BEFORE THE PARENT ROW EXISTS.
  --
  -- SET CONSTRAINTS is TRANSACTION-SCOPED, not statement-scoped: the IMMEDIATE
  -- below outlives the call that issued it. Without this line the second append
  -- in one transaction would insert its revision row while the guard was still
  -- IMMEDIATE from the FIRST call, so the trigger would fire at the end of that
  -- INSERT -- before this function had inserted a single event or pause-interval
  -- child. The guard reads the persisted children (an empty event chain, a
  -- digest over content that is not there yet) and would refuse a PERFECTLY
  -- VALID append, by a name that describes nothing the caller did.
  --
  -- It is unconditional because the mode cannot be read back: a caller may have
  -- entered the transaction under SET CONSTRAINTS ALL IMMEDIATE, and a previous
  -- call of this function may have left it IMMEDIATE for the same reason. Both
  -- arrive here identically and both are corrected the same way.
  --
  -- IT DEFERS NOTHING PAST THIS CALL. The forced IMMEDIATE below still validates
  -- this revision before the function returns; deferral is narrowed to the
  -- window between the parent insert and its own complete children, which is the
  -- only window in which the guard could read an incomplete revision.
  execute 'set constraints ops.j1_clock_append_guard deferred';

  insert into ops.j1_clock_revision(
    clock_id, revision_ordinal, idempotency_key, prior_history_digest, history_digest,
    state_schema_version, origin_receipt_digest, origin_at, origin_benchmark_manifest_digest,
    current_benchmark_manifest_digest, origin_receipt_ttl_policy_ms,
    base_deadline_at, base_deadline_resolution, due_at, paused_ms, status, miss_at,
    completion_receipt_digest, completion_observed_at, completion_receipt_ttl_policy_ms,
    completion_artifact_digest, completion_fixture_set_digest, evaluated_at,
    computed_by, projection_schema_version, verifier_ref, input_authority, written_by_actor_id)
  values (v_clock.id, v_ordinal, p_idempotency_key,
    p_expected_prior_history_digest, p_history_digest,
    p_scalars ->> 'schema_version', p_scalars ->> 'origin_receipt_digest',
    p_scalars ->> 'origin_at', p_scalars ->> 'origin_benchmark_manifest_digest',
    p_scalars ->> 'current_benchmark_manifest_digest',
    (p_scalars ->> 'origin_receipt_ttl_policy_ms')::bigint,
    p_scalars ->> 'base_deadline_at', p_scalars ->> 'base_deadline_resolution',
    p_scalars ->> 'due_at', (p_scalars ->> 'paused_ms')::bigint,
    p_scalars ->> 'status', p_scalars ->> 'miss_at',
    p_scalars ->> 'completion_receipt_digest', p_scalars ->> 'completion_observed_at',
    (p_scalars ->> 'completion_receipt_ttl_policy_ms')::bigint,
    p_scalars ->> 'completion_artifact_digest', p_scalars ->> 'completion_fixture_set_digest',
    p_scalars ->> 'evaluated_at',
    -- PROVENANCE IS PINNED, NOT COPIED. computed_by, the projection schema and
    -- input_authority are CHECK-constrained to single values, so a direct writer
    -- cannot widen them into a claim of verification. verifier_ref NAMES the
    -- installed verifier and is the only free field; naming is not proving.
    'mcp-server/src/journey-one-clock.v5.js',
    'doctorcre-v5-journey-one-clock-projection.v2',
    p_provenance ->> 'verifier_ref',
    'trusted_projection_not_independently_verified_by_this_record_layer',
    v_actor)
  returning id into v_revision;

  insert into ops.j1_clock_revision_pause_interval(revision_id, ordinal, pause_id, ends_at)
  select v_revision, (value ->> 'ordinal')::integer, value ->> 'pause_id', value ->> 'ends_at'
    from jsonb_array_elements(coalesce(p_pause_intervals, '[]'::jsonb));

  insert into ops.j1_clock_revision_event(
    revision_id, ordinal, event_type, happened_at, kernel_recorded_at,
    evidence_digest, previous_event_digest, event_digest)
  select v_revision, (value ->> 'ordinal')::integer, value ->> 'type',
         value ->> 'at', value ->> 'recorded_at', value ->> 'evidence_digest',
         value ->> 'previous_event_digest', value ->> 'event_digest'
    from jsonb_array_elements(coalesce(p_events, '[]'::jsonb));

  -- THE CALLER'S HASH IS NEVER THE ANSWER. It is compared here against the
  -- digest the rows just written produce, and the guard compares it again over
  -- the settled rows a few lines below, where it is forced to run.
  v_live := ops.j1_clock_history_digest(v_revision);
  if p_history_digest is distinct from v_live then
    raise exception '[j1_clock_claimed_history_digest_is_never_trusted] the named history digest is not the one these rows produce: named %, computed %',
      p_history_digest, v_live;
  end if;

  -- FORCE THE DEFERRED APPEND GUARD TO RUN HERE, over the COMPLETE rows -- the
  -- revision, its pause intervals and its whole event chain -- rather than at
  -- COMMIT. Two reasons, and the second one matters more than it looks: a caller
  -- gets the named refusal at the point of the call instead of a surprise at
  -- commit, and a ROLLBACK-ONLY PROOF FIXTURE can exercise the guard at all -- a
  -- deferred constraint that only ever fires at commit is one no
  -- transaction-scoped test can reach.
  --
  -- Issued through EXECUTE rather than as a bare statement so it is handed
  -- straight to the SQL engine and does not depend on PL/pgSQL's own statement
  -- parser accepting SET CONSTRAINTS.
  execute 'set constraints ops.j1_clock_append_guard immediate';

  -- AND RESTORED BEFORE RETURNING, because the line above would otherwise stay
  -- in force for the whole transaction and break the NEXT append in it: that
  -- one's revision row would be validated at the end of its own INSERT, against
  -- children this function had not written yet. The guard is DEFERRABLE
  -- INITIALLY DEFERRED by declaration, so restoring DEFERRED returns the
  -- transaction to the trigger's declared state rather than to some state this
  -- function invented.
  --
  -- IT WEAKENS NOTHING. Every revision this function writes has already been
  -- validated, one line above, over its own settled rows; nothing is left
  -- pending for commit to catch, and no caller can batch past the check by
  -- deferring the constraint, because the check does not happen at commit.
  -- A caller who deliberately entered under SET CONSTRAINTS ALL IMMEDIATE gets
  -- that same guarantee -- validation at the point of the call -- and this
  -- function does not restore their ad-hoc mode, which it has no way to read.
  --
  -- THE REFUSING PATH NEEDS NO RESTORE AND DOES NOT GET ONE. If the forced check
  -- above raises, this line is never reached -- and it does not have to be: the
  -- raise aborts the transaction, or the subtransaction of a caller that caught
  -- it, and a constraint-mode change is rolled back with everything else that
  -- subtransaction did. A refusal therefore cannot leave IMMEDIATE behind for
  -- the next append either.
  execute 'set constraints ops.j1_clock_append_guard deferred';

  v_row := ops.j1_clock_revision_json(v_revision);
  return v_row || jsonb_build_object('replayed', false);
end;
$$;


--
-- Name: FUNCTION j1_clock_append_revision(p_clock_key text, p_tenant text, p_clock_ref text, p_expected_prior_history_digest text, p_idempotency_key uuid, p_history_digest text, p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb, p_provenance jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_append_revision(p_clock_key text, p_tenant text, p_clock_ref text, p_expected_prior_history_digest text, p_idempotency_key uuid, p_history_digest text, p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb, p_provenance jsonb) IS 'The only way to append a Journey 1 clock revision. The writer, the clock identity and the history digest are all DERIVED; the caller supplies content, an idempotency key and the exact prior-history digest it believes is the head. It creates the clock row when the prior is an explicit null, refuses a stale prior, replays an exact idempotent repeat and refuses a key whose payload changed. It records a computation with scoped provenance: it accepts no deadline, admits no receipt, verifies no input and starts nothing. It owns the append guard''s deferral mode for the length of the call -- DEFERRED before the revision row is inserted, IMMEDIATE once its children are complete, DEFERRED again before returning -- so repeated appends in one transaction, and callers who entered under SET CONSTRAINTS ALL IMMEDIATE, are each validated over complete rows rather than over a revision whose children do not exist yet.';


--
-- Name: j1_clock_assert_same(text, text, anyelement, anyelement); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_assert_same(p_invariant text, p_field text, p_recorded anyelement, p_supplied anyelement) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if p_recorded is null and p_supplied is null then return; end if;
  if p_recorded is distinct from p_supplied then
    raise exception '[%] Journey 1 clock revision changes %: recorded %, supplied %',
      p_invariant, p_field, coalesce(p_recorded::text, 'null'), coalesce(p_supplied::text, 'null');
  end if;
end;
$$;


--
-- Name: FUNCTION j1_clock_assert_same(p_invariant text, p_field text, p_recorded anyelement, p_supplied anyelement); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_assert_same(p_invariant text, p_field text, p_recorded anyelement, p_supplied anyelement) IS 'Fail-closed equality for one append-only field, comparing with IS DISTINCT FROM so a null can never make the comparison itself evaluate to NULL and fall through. Raises with the shared invariant id.';


--
-- Name: j1_clock_bind_scope(text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_bind_scope(p_clock_key text, p_clock_scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_key text; v_existing ops.j1_clock_scope_binding%rowtype; v_id uuid;
begin
  if p_clock_key is null or p_clock_key !~ '^sha256:[0-9a-f]{64}$' then
    raise exception '[j1_clock_identity_derived_from_origin] a Journey 1 scope binding names a derived clock key';
  end if;
  v_key := ops.j1_clock_scope_digest(p_clock_scope);
  perform ops.j1_clock_scope_lock(v_key);

  select * into v_existing from ops.j1_clock_scope_binding where clock_scope_key = v_key;
  if found then
    if v_existing.clock_key is distinct from p_clock_key then
      raise exception '[j1_clock_scope_binds_one_clock] authoritative clock scope % already holds clock %, and this revision''s origin derives %. A new origin for a scope that already has a clock is a reset wearing a new address: append to the clock that exists, or refuse',
        v_key, v_existing.clock_key, p_clock_key;
    end if;
    -- THE LABEL IS SEALED AT BINDING. It is not identity -- v_key ignores it,
    -- which is exactly what makes a relabelled scope the SAME scope -- and for
    -- that reason the record must not end up holding two names for one scope or
    -- quietly replacing the one it was bound under. Renaming is external.
    if v_existing.clock_scope_ref is distinct from (p_clock_scope ->> 'scope_ref') then
      raise exception '[j1_clock_scope_label_is_not_identity] authoritative clock scope % was bound under label %, and % was supplied. The label is provenance, is recorded once, and is never rewritten by a later write',
        v_key, v_existing.clock_scope_ref, coalesce(p_clock_scope ->> 'scope_ref', 'null');
    end if;
    return ops.j1_clock_scope_binding_json(v_existing.id);
  end if;

  select * into v_existing from ops.j1_clock_scope_binding where clock_key = p_clock_key;
  if found then
    raise exception '[j1_clock_scope_sealed_at_creation] Journey 1 clock % is bound to authoritative scope % and is never rebound; scope % was supplied',
      p_clock_key, v_existing.clock_scope_key, v_key;
  end if;

  insert into ops.j1_clock_scope_binding(
    clock_scope_key, clock_key, clock_scope, clock_scope_ref, tenant, bound_by_actor_id)
  values (v_key, p_clock_key, p_clock_scope,
    p_clock_scope ->> 'scope_ref', p_clock_scope ->> 'tenant',
    ops.portfolio_writer_actor_id())
  returning id into v_id;
  return ops.j1_clock_scope_binding_json(v_id);
end;
$_$;


--
-- Name: FUNCTION j1_clock_bind_scope(p_clock_key text, p_clock_scope jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_bind_scope(p_clock_key text, p_clock_scope jsonb) IS 'Bind one Journey 1 clock to the authoritative scope it is the clock for, deriving the scope key from the scope''s six identity fields. Idempotent for the exact pair; refuses a second clock for one scope, a second scope for one clock, and a second label for one scope. It proves nothing about whether the supplied scope is the accepted scope of the projection the kernel read -- the stored state carries nothing to check that against, and ops.j1_clock_record_layer_cannot_prove() says so.';


--
-- Name: j1_clock_child_frozen_after_next_revision(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_child_frozen_after_next_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_clock uuid; v_ordinal integer;
begin
  select r.clock_id, r.revision_ordinal into v_clock, v_ordinal
    from ops.j1_clock_revision r where r.id = new.revision_id;
  if not found then
    raise exception '[j1_clock_content_rebuilds_to_its_digest] Journey 1 clock % row names an unknown revision', tg_table_name;
  end if;
  perform 1 from ops.j1_clock where id = v_clock for share;
  if exists (select 1 from ops.j1_clock_revision r
              where r.clock_id = v_clock and r.revision_ordinal > v_ordinal) then
    raise exception '[j1_clock_content_rebuilds_to_its_digest] revision % of this clock is sealed behind a later revision; its content is closed to further % rows',
      v_ordinal, tg_table_name;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION j1_clock_child_frozen_after_next_revision(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_child_frozen_after_next_revision() IS 'Refuses a pause-interval or event insert against a revision that a later revision already follows, so no hashed row can appear outside the digest the revision was sealed under. Takes FOR SHARE on the clock row; ops.j1_clock_append_revision takes FOR UPDATE on the same row, and it is that shared protocol -- not the lock alone -- that keeps a concurrent child insert and an append from committing past each other.';


--
-- Name: j1_clock_event_digest(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_event_digest(p_type text, p_at text, p_recorded_at text, p_evidence_digest text, p_previous_event_digest text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(jsonb_build_object(
      'at', p_at,
      'evidence_digest', p_evidence_digest,
      'previous_event_digest', to_jsonb(p_previous_event_digest),
      'recorded_at', p_recorded_at,
      'type', p_type)),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_clock_event_digest(p_type text, p_at text, p_recorded_at text, p_evidence_digest text, p_previous_event_digest text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_event_digest(p_type text, p_at text, p_recorded_at text, p_evidence_digest text, p_previous_event_digest text) IS 'The digest journey-one-clock.v5.js gives one history event: sha256 over the canonical {at, evidence_digest, previous_event_digest, recorded_at, type}. Recomputing a hash the kernel defined; it decides nothing about which events may exist.';


--
-- Name: j1_clock_head(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_head(p_clock_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_clock_revision_json(r.id)
    from ops.j1_clock_revision r join ops.j1_clock c on c.id = r.clock_id
   where c.clock_key = p_clock_key
   order by r.revision_ordinal desc limit 1
$$;


--
-- Name: FUNCTION j1_clock_head(p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_head(p_clock_key text) IS 'The current head revision of one clock, or null when the clock has none. The compare-and-swap token an append must name is this row''s history_digest.';


--
-- Name: j1_clock_history(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history(p_clock_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_clock ops.j1_clock%rowtype; v_head ops.j1_clock_revision%rowtype; v_error text;
begin
  select * into v_clock from ops.j1_clock where clock_key = p_clock_key;
  if not found then
    return jsonb_build_object(
      'clock_key', p_clock_key, 'exists', false,
      'record_layer_cannot_prove', ops.j1_clock_record_layer_cannot_prove(),
      'deadline_accepted_by_record_layer', false);
  end if;
  select * into v_head from ops.j1_clock_revision
   where clock_id = v_clock.id order by revision_ordinal desc limit 1;
  if not found then
    raise exception '[j1_clock_content_rebuilds_to_its_digest] Journey 1 clock % exists with no revisions; this record layer cannot produce the history it holds',
      p_clock_key using errcode = 'integrity_constraint_violation';
  end if;
  -- A TAMPERED READBACK REFUSES. It does not fall back to an earlier healthy
  -- revision and does not report a corrupted clock as no clock: both would turn
  -- corruption into ordinary source.
  v_error := ops.j1_clock_revision_integrity_error(v_head.id);
  if v_error is not null then
    raise exception 'Journey 1 clock % failed integrity: %', p_clock_key, v_error
      using errcode = 'integrity_constraint_violation';
  end if;
  return jsonb_build_object(
    'clock_key', v_clock.clock_key,
    'tenant', v_clock.tenant,
    'exists', true,
    'clock_ref', to_jsonb(v_clock.clock_ref),
    -- WHICH AUTHORITATIVE SCOPE HOLDS THIS CLOCK. `false` is a real answer: an
    -- unbound clock is exactly the shape a second origin could have created
    -- beside another, and a reader sees that rather than an absent field.
    'clock_scope_bound', exists (select 1 from ops.j1_clock_scope_binding b
                                  where b.clock_key = v_clock.clock_key),
    'clock_scope_key', (select b.clock_scope_key from ops.j1_clock_scope_binding b
                         where b.clock_key = v_clock.clock_key),
    'clock_scope_ref', (select b.clock_scope_ref from ops.j1_clock_scope_binding b
                         where b.clock_key = v_clock.clock_key),
    'state_schema_version', v_head.state_schema_version,
    'revision_count', (select count(*) from ops.j1_clock_revision where clock_id = v_clock.id),
    'head_revision_ordinal', v_head.revision_ordinal,
    'history_digest', v_head.history_digest,
    -- BOTH DIGESTS ARE EXPOSED ON PURPOSE: the STORED one is what the append
    -- claimed, the RECOMPUTED one is what the rows say now, and a reader that
    -- only ever saw one of them could not tell a tampered revision from a
    -- healthy one.
    'recomputed_history_digest', ops.j1_clock_history_digest(v_head.id),
    -- SERVER TIME and KERNEL TIME, both reported, neither standing in for the
    -- other.
    'recorded_at', v_head.recorded_at,
    'evaluated_at', v_head.evaluated_at,
    'history', ops.j1_clock_history_state(v_head.id),
    'revisions', ops.j1_clock_revisions(p_clock_key),
    -- Said out loud on every read. A consumer that saw only `status` would
    -- otherwise be entitled to assume this database had checked something.
    'record_layer_cannot_prove', ops.j1_clock_record_layer_cannot_prove(),
    'deadline_accepted_by_record_layer', false,
    'clock_started_by_this_record_layer', false,
    'effects', jsonb_build_object(
      'creates_effect', false, 'database_writes', 0, 'network_calls', 0,
      'provider_actions', 0, 'notifications', 0, 'schedules', 0,
      'deployments', 0, 'activations', 0, 'acceptances', 0));
end;
$$;


--
-- Name: FUNCTION j1_clock_history(p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history(p_clock_key text) IS 'Deterministic zero-write readback of one Journey 1 clock: the head rebuilt from its stored rows, both the stored and the recomputed digest, the full revision chain, and an explicit statement of what this record layer cannot prove. A tampered head refuses rather than serving an older revision.';


--
-- Name: j1_clock_history_digest(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history_digest(p_revision_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(ops.j1_clock_history_preimage(p_revision_id)),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_clock_history_digest(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history_digest(p_revision_id uuid) IS 'The history digest one stored revision''s rows produce right now. A caller may name a digest; it is only ever compared against this.';


--
-- Name: j1_clock_history_digest_of(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history_digest_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(
      ops.j1_clock_history_preimage_of(p_scalars, p_pause_intervals, p_events)),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_clock_history_digest_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history_digest_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb) IS 'The history digest a set of decomposed content produces. A fixture can learn a digest with this without writing a row; ops.j1_clock_append_revision still compares against the digest the STORED rows produce, so the two can never diverge silently.';


--
-- Name: j1_clock_history_preimage(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history_preimage(p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_clock_history_preimage_of(
    ops.j1_clock_revision_scalars(p_revision_id),
    ops.j1_clock_revision_pause_interval_rows(p_revision_id),
    ops.j1_clock_revision_event_rows(p_revision_id))
$$;


--
-- Name: FUNCTION j1_clock_history_preimage(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history_preimage(p_revision_id uuid) IS 'The twenty hashed fields of one stored Journey 1 clock revision, rebuilt from its own rows. The twenty-first, history_digest, is the hash OF this object and is therefore not in it.';


--
-- Name: j1_clock_history_preimage_of(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history_preimage_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select p_scalars || jsonb_build_object(
    'pause_intervals', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'pause_id', x.value ->> 'pause_id',
               -- `->` and not `->>`, so a null stays JSON null instead of
               -- vanishing from the object and changing the hash.
               'ends_at', x.value -> 'ends_at')
             order by (x.value ->> 'ordinal')::integer), '[]'::jsonb)
        from jsonb_array_elements(coalesce(p_pause_intervals, '[]'::jsonb)) x),
    'events', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'type', x.value ->> 'type',
               'at', x.value ->> 'at',
               'recorded_at', x.value ->> 'recorded_at',
               'evidence_digest', x.value ->> 'evidence_digest',
               'previous_event_digest', x.value -> 'previous_event_digest',
               'event_digest', x.value ->> 'event_digest')
             order by (x.value ->> 'ordinal')::integer), '[]'::jsonb)
        from jsonb_array_elements(coalesce(p_events, '[]'::jsonb)) x))
$$;


--
-- Name: FUNCTION j1_clock_history_preimage_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history_preimage_of(p_scalars jsonb, p_pause_intervals jsonb, p_events jsonb) IS 'The twenty hashed fields of a Journey 1 clock history, assembled from decomposed content. The ordinals order the arrays and are dropped from the hashed object. The uuid form below delegates to this, so stored rows and offered content are hashed by one rule.';


--
-- Name: j1_clock_history_state(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_history_state(p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_clock_history_preimage(p_revision_id)
         || jsonb_build_object('history_digest',
              (select r.history_digest from ops.j1_clock_revision r where r.id = p_revision_id))
$$;


--
-- Name: FUNCTION j1_clock_history_state(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_history_state(p_revision_id uuid) IS 'One stored revision rebuilt into the kernel''s twenty-one-field state, ready to be handed back to journey-one-clock.v5.js as its `history`.';


--
-- Name: j1_clock_identity_digest(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_identity_digest(p_tenant text, p_origin_receipt_digest text, p_origin_at text, p_origin_benchmark_manifest_digest text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(jsonb_build_array(
      ops.j1_clock_identity_domain_tag(),
      jsonb_build_object(
        'origin_at', p_origin_at,
        'origin_benchmark_manifest_digest', p_origin_benchmark_manifest_digest,
        'origin_receipt_digest', p_origin_receipt_digest,
        'tenant', p_tenant))),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_clock_identity_digest(p_tenant text, p_origin_receipt_digest text, p_origin_at text, p_origin_benchmark_manifest_digest text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_identity_digest(p_tenant text, p_origin_receipt_digest text, p_origin_at text, p_origin_benchmark_manifest_digest text) IS 'The identity of one Journey 1 clock: sha256 over the canonical [domain_tag, {origin_at, origin_benchmark_manifest_digest, origin_receipt_digest, tenant}]. Derived from the kernel origin, never chosen by a caller.';


--
-- Name: j1_clock_identity_domain_tag(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_identity_domain_tag() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre:j1-clock-identity:v1'::text $$;


--
-- Name: FUNCTION j1_clock_identity_domain_tag(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_identity_domain_tag() IS 'The domain tag under which a Journey 1 clock identity is derived. Matches JOURNEY_ONE_CLOCK_IDENTITY_DOMAIN_TAG in mcp-server/src/journey-one-clock-store.v5.js.';


--
-- Name: j1_clock_legacy_state_schemas(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_legacy_state_schemas() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select array['doctorcre-v5-journey-one-clock.v1']::text[] $$;


--
-- Name: FUNCTION j1_clock_legacy_state_schemas(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_legacy_state_schemas() IS 'State schemas this rail refuses by name rather than reinterpreting. v1 sealed its origin digest over a different minimum and carries neither the TTL policy that selected its origin nor the deadline resolution that produced its base deadline; re-deriving any of those would rebase a sealed origin. Migration is explicit and external, exactly as the kernel says.';


--
-- Name: j1_clock_lock(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_lock(p_clock_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if p_clock_key is null then
    raise exception '[j1_clock_exact_prior_history_digest] a Journey 1 clock append must name the clock it is appending to';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_clock_key, 0));
  perform 1 from ops.j1_clock where clock_key = p_clock_key for update;
end;
$$;


--
-- Name: FUNCTION j1_clock_lock(p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_lock(p_clock_key text) IS 'Opens the serialized same-clock append section for the calling transaction: a transaction-scoped advisory lock on the clock key (which serializes concurrent CREATIONS, which have no row yet) plus FOR UPDATE on the clock row when it exists. The child-freeze trigger takes FOR SHARE on the same row, and the two modes conflict.';


--
-- Name: j1_clock_origin_gate_id(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_origin_gate_id() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'foundation-assurance-minimum-accepted'::text $$;


--
-- Name: j1_clock_record_layer_cannot_prove(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_record_layer_cannot_prove() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_array(
    'that the origin receipt was a genuine, current, passing foundation-assurance-minimum receipt: no authenticated admission ledger exists here, and admitted_at is a projection fact',
    'that the recorded pauses were approved by a real verified partner strictly before they started, or that an approval was not backdated',
    'that the terminus receipt was admitted under the accepted per-receipt TTL policy against the accepted kernel scope',
    'that the projection the kernel read was authentic: the verifier is trusted server code and this record layer never sees it',
    'that a revision written by a direct holder of the writer bundle is a kernel computation rather than that writer''s assertion; both are trusted writers and nothing recorded here tells them apart',
    'that the authoritative scope a stored revision is bound to is the accepted scope of the projection the kernel actually read. The module''s trusted recorder compares the kernel''s own verified_binding for that computation against its store''s scope before anything is written; a direct caller of this function is checked against neither, because doctorcre-v5-journey-one-clock.v2 carries no subject, candidate or policy digest and this rail never derives one from a stored history',
    'anything about deadline SUCCESS. A stored status is a recorded computation, never an acceptance of a deadline by this record layer')
$$;


--
-- Name: FUNCTION j1_clock_record_layer_cannot_prove(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_record_layer_cannot_prove() IS 'The explicit list of things a stored Journey 1 clock revision does NOT prove. Returned on every readback so a stored status is never read as a verified deadline acceptance.';


--
-- Name: j1_clock_revision_by_idempotency_key(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_by_idempotency_key(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_clock_revision_json(r.id)
    from ops.j1_clock_revision r where r.idempotency_key = p_idempotency_key
$$;


--
-- Name: FUNCTION j1_clock_revision_by_idempotency_key(p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_by_idempotency_key(p_idempotency_key uuid) IS 'The revision one idempotency key already wrote, or null. An exact replay returns it; a key presented with different content is refused by ops.j1_clock_append_revision.';


--
-- Name: j1_clock_revision_event_rows(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_event_rows(p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'ordinal', e.ordinal, 'type', e.event_type, 'at', e.happened_at,
           'recorded_at', e.kernel_recorded_at, 'evidence_digest', e.evidence_digest,
           'previous_event_digest', to_jsonb(e.previous_event_digest),
           'event_digest', e.event_digest) order by e.ordinal), '[]'::jsonb)
    from ops.j1_clock_revision_event e where e.revision_id = p_revision_id
$$;


--
-- Name: FUNCTION j1_clock_revision_event_rows(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_event_rows(p_revision_id uuid) IS 'The stored event chain of one revision, with its ordinals, in ordinal order.';


--
-- Name: j1_clock_revision_integrity_error(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_integrity_error(p_revision_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v ops.j1_clock_revision%rowtype; v_clock ops.j1_clock%rowtype;
  v_live text; v_derived text; v_count integer; v_max integer;
  v_previous text; v_row record;
begin
  select * into v from ops.j1_clock_revision where id = p_revision_id;
  if not found then return format('revision %s does not exist', p_revision_id); end if;
  select * into v_clock from ops.j1_clock where id = v.clock_id;
  if not found then return format('revision %s names an unknown clock', p_revision_id); end if;

  if v.state_schema_version <> ops.j1_clock_state_schema() then
    return format('[j1_clock_state_schema_current] revision %s stores %s, not %s',
      p_revision_id, v.state_schema_version, ops.j1_clock_state_schema());
  end if;

  -- THE CONTENT REBUILDS TO ITS DIGEST, or it is not the history it claims.
  v_live := ops.j1_clock_history_digest(p_revision_id);
  if v.history_digest is distinct from v_live then
    return format('[j1_clock_content_rebuilds_to_its_digest] revision %s no longer rebuilds to its stored digest: stored %s, computed %s',
      p_revision_id, v.history_digest, v_live);
  end if;

  -- THE CLOCK IS THE ONE THIS REVISION''S OWN ORIGIN DERIVES.
  v_derived := ops.j1_clock_identity_digest(
    v_clock.tenant, v.origin_receipt_digest, v.origin_at, v.origin_benchmark_manifest_digest);
  if v_derived is distinct from v_clock.clock_key then
    return format('[j1_clock_identity_derived_from_origin] revision %s is filed under %s but its own origin derives %s',
      p_revision_id, v_clock.clock_key, v_derived);
  end if;
  if v_clock.origin_receipt_digest is distinct from v.origin_receipt_digest
     or v_clock.origin_at is distinct from v.origin_at
     or v_clock.origin_benchmark_manifest_digest is distinct from v.origin_benchmark_manifest_digest then
    return format('[j1_clock_origin_never_rewritten] revision %s disagrees with its clock row about the origin', p_revision_id);
  end if;

  -- Contiguous ordinals in both child relations. A gap is a row that was
  -- expected and is missing, which is the shape a partial insert leaves behind.
  select count(*), coalesce(max(ordinal), -1) into v_count, v_max
    from ops.j1_clock_revision_event where revision_id = p_revision_id;
  if v_count = 0 then
    return format('[j1_clock_events_are_append_only] revision %s carries no events', p_revision_id);
  end if;
  if v_count <> v_max + 1 then
    return format('[j1_clock_events_are_append_only] revision %s has a gap in its event ordinals', p_revision_id);
  end if;
  select count(*), coalesce(max(ordinal), -1) into v_count, v_max
    from ops.j1_clock_revision_pause_interval where revision_id = p_revision_id;
  if v_count <> v_max + 1 then
    return format('[j1_clock_content_rebuilds_to_its_digest] revision %s has a gap in its pause-interval ordinals', p_revision_id);
  end if;

  -- The chain is a chain: each link names the link before it, AND each link
  -- hashes to its own content. Linkage alone would let a writer hand this rail
  -- any sha256-shaped strings that happened to point at each other.
  v_previous := null;
  for v_row in select ordinal, event_type, happened_at, kernel_recorded_at,
                      evidence_digest, previous_event_digest, event_digest
                 from ops.j1_clock_revision_event
                where revision_id = p_revision_id order by ordinal loop
    if v_row.previous_event_digest is distinct from v_previous then
      return format('[j1_clock_events_are_append_only] revision %s event %s does not link to the event before it',
        p_revision_id, v_row.ordinal);
    end if;
    if v_row.event_digest is distinct from ops.j1_clock_event_digest(
         v_row.event_type, v_row.happened_at, v_row.kernel_recorded_at,
         v_row.evidence_digest, v_row.previous_event_digest) then
      return format('[j1_clock_events_are_append_only] revision %s event %s does not hash to its own event_digest',
        p_revision_id, v_row.ordinal);
    end if;
    v_previous := v_row.event_digest;
  end loop;

  -- The one contradiction Q008.D1 states outright. The table constraint refuses
  -- it at insert; this refuses it on read too, so a record that reached the
  -- table by any other route is still reported rather than served.
  if v.miss_at is not null and v.status = 'completed_on_time' then
    return format('[j1_clock_no_deadline_success_after_recorded_miss] revision %s claims deadline success beside a recorded miss',
      p_revision_id);
  end if;
  return null;
end;
$$;


--
-- Name: FUNCTION j1_clock_revision_integrity_error(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_integrity_error(p_revision_id uuid) IS 'Why one stored Journey 1 clock revision is not trustworthy, recomputed from its rows, or null when it is intact. Every message carries the shared invariant id.';


--
-- Name: j1_clock_revision_json(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_json(p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
           'revision_id', r.id,
           'clock_key', c.clock_key,
           'tenant', c.tenant,
           'clock_ref', to_jsonb(c.clock_ref),
           'revision_ordinal', r.revision_ordinal,
           'state_schema_version', r.state_schema_version,
           'history_digest', r.history_digest,
           'expected_prior_history_digest', to_jsonb(r.prior_history_digest),
           'recorded_at', r.recorded_at,
                    'scalars', ops.j1_clock_revision_scalars(r.id),
           'pause_intervals', ops.j1_clock_revision_pause_interval_rows(r.id),
           'events', ops.j1_clock_revision_event_rows(r.id),
           'provenance', jsonb_build_object(
             'computed_by', r.computed_by,
             'kernel_state_schema_version', r.state_schema_version,
             'projection_schema_version', r.projection_schema_version,
             'verifier_ref', r.verifier_ref,
             'input_authority', r.input_authority,
             'written_by_actor_id', r.written_by_actor_id),
           'integrity_error', to_jsonb(ops.j1_clock_revision_integrity_error(r.id)))
    from ops.j1_clock_revision r join ops.j1_clock c on c.id = r.clock_id
   where r.id = p_revision_id
$$;


--
-- Name: FUNCTION j1_clock_revision_json(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_json(p_revision_id uuid) IS 'One stored revision in the exact shape createPostgresJourneyOneClockJournal expects: the decomposed rows, the stored digest, the CAS token it was written under, the server instant it was recorded at, and its scoped provenance. `scalars` is the hashed preimage minus its two relations, so the reader and the hasher cannot disagree about which fields are scalar.';


--
-- Name: j1_clock_revision_pause_interval_rows(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_pause_interval_rows(p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'ordinal', p.ordinal, 'pause_id', p.pause_id,
           'ends_at', to_jsonb(p.ends_at)) order by p.ordinal), '[]'::jsonb)
    from ops.j1_clock_revision_pause_interval p where p.revision_id = p_revision_id
$$;


--
-- Name: FUNCTION j1_clock_revision_pause_interval_rows(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_pause_interval_rows(p_revision_id uuid) IS 'The stored pause intervals of one revision, with their ordinals, in ordinal order.';


--
-- Name: j1_clock_revision_scalars(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revision_scalars(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v ops.j1_clock_revision%rowtype;
begin
  select * into v from ops.j1_clock_revision where id = p_revision_id;
  if not found then
    raise exception '[j1_clock_content_rebuilds_to_its_digest] Journey 1 clock revision % does not exist', p_revision_id;
  end if;
  -- to_jsonb on every nullable field, so a null is stored in the object as JSON
  -- null rather than being dropped: a dropped key is a different hash.
  return jsonb_build_object(
    'schema_version', v.state_schema_version,
    'origin_receipt_digest', v.origin_receipt_digest,
    'origin_at', v.origin_at,
    'origin_benchmark_manifest_digest', v.origin_benchmark_manifest_digest,
    'current_benchmark_manifest_digest', v.current_benchmark_manifest_digest,
    'origin_receipt_ttl_policy_ms', v.origin_receipt_ttl_policy_ms,
    'base_deadline_at', to_jsonb(v.base_deadline_at),
    'base_deadline_resolution', v.base_deadline_resolution,
    'due_at', to_jsonb(v.due_at),
    'paused_ms', v.paused_ms,
    'status', v.status,
    'miss_at', to_jsonb(v.miss_at),
    'completion_receipt_digest', to_jsonb(v.completion_receipt_digest),
    'completion_observed_at', to_jsonb(v.completion_observed_at),
    'completion_receipt_ttl_policy_ms', to_jsonb(v.completion_receipt_ttl_policy_ms),
    'completion_artifact_digest', to_jsonb(v.completion_artifact_digest),
    'completion_fixture_set_digest', to_jsonb(v.completion_fixture_set_digest),
    'evaluated_at', v.evaluated_at);
end;
$$;


--
-- Name: FUNCTION j1_clock_revision_scalars(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revision_scalars(p_revision_id uuid) IS 'The eighteen scalar state fields of one stored revision, as the kernel spells them.';


--
-- Name: j1_clock_revisions(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_revisions(p_clock_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(ops.j1_clock_revision_json(r.id) order by r.revision_ordinal), '[]'::jsonb)
    from ops.j1_clock_revision r join ops.j1_clock c on c.id = r.clock_id
   where c.clock_key = p_clock_key
$$;


--
-- Name: FUNCTION j1_clock_revisions(p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_revisions(p_clock_key text) IS 'Every revision of one clock, ascending by revision_ordinal. Ordered by the ordinal and not by recorded_at: now() is transaction start time, so two revisions written in one transaction share an instant and an order that tied there would return rows in whatever order the plan produced.';


--
-- Name: j1_clock_row(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_row(p_clock_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
           'clock_key', c.clock_key,
           'tenant', c.tenant,
           'clock_ref', to_jsonb(c.clock_ref),
           'state_schema_version', c.state_schema_version,
           'origin_receipt_digest', c.origin_receipt_digest,
           'origin_at', c.origin_at,
           'origin_benchmark_manifest_digest', c.origin_benchmark_manifest_digest,
           -- The authoritative scope this clock is bound to, or null. Null is a
           -- real answer and is reported rather than hidden: an unbound clock is
           -- the shape a second origin leaves behind.
           'clock_scope_key', (select b.clock_scope_key from ops.j1_clock_scope_binding b
                                where b.clock_key = c.clock_key),
           'clock_scope_ref', (select b.clock_scope_ref from ops.j1_clock_scope_binding b
                                where b.clock_key = c.clock_key),
           'created_at', c.created_at)
    from ops.j1_clock c where c.clock_key = p_clock_key
$$;


--
-- Name: FUNCTION j1_clock_row(p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_row(p_clock_key text) IS 'One Journey 1 clock addressed by its DERIVED key, or null. There is deliberately no lookup by clock_ref: a label selects nothing on this rail.';


--
-- Name: j1_clock_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception '[j1_clock_rows_are_append_only] Journey 1 clock rows are append-only: % is refused on ops.%',
    tg_op, tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: FUNCTION j1_clock_rows_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_rows_immutable() IS 'Refuses every update, delete and truncate on the Journey 1 clock storage tables. Carries the shared invariant id j1_clock_rows_are_append_only. It is installed twice per relation because a row-level trigger never sees TRUNCATE, and TRUNCATE cannot be revoked from the table owner.';


--
-- Name: j1_clock_scope_binding_json(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_scope_binding_json(p_binding_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
           'clock_scope_key', b.clock_scope_key,
           'clock_key', b.clock_key,
           'clock_scope_ref', b.clock_scope_ref,
           'clock_scope', b.clock_scope,
           'tenant', b.tenant,
           'bound_at', b.bound_at)
    from ops.j1_clock_scope_binding b where b.id = p_binding_id
$$;


--
-- Name: FUNCTION j1_clock_scope_binding_json(p_binding_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_scope_binding_json(p_binding_id uuid) IS 'One scope binding in the shape createPostgresJourneyOneClockJournal expects. The stored scope object travels with it: a reader is entitled to see WHICH accepted scope was named, not merely that something hashed to this key.';


--
-- Name: j1_clock_scope_bindings(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_scope_bindings(p_clock_scope_key text, p_clock_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
    'by_scope', (select ops.j1_clock_scope_binding_json(b.id) from ops.j1_clock_scope_binding b
                  where p_clock_scope_key is not null and b.clock_scope_key = p_clock_scope_key),
    'by_clock', (select ops.j1_clock_scope_binding_json(b.id) from ops.j1_clock_scope_binding b
                  where p_clock_key is not null and b.clock_key = p_clock_key))
$$;


--
-- Name: FUNCTION j1_clock_scope_bindings(p_clock_scope_key text, p_clock_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_scope_bindings(p_clock_scope_key text, p_clock_key text) IS 'Which clock this authoritative scope already holds, and which scope this clock is already bound to. Either side may be null. This is the READ a creation presenting a new origin has to meet before it can become a second clock for one program.';


--
-- Name: j1_clock_scope_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_scope_digest(p_scope jsonb) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_field text; v_fields jsonb;
begin
  if p_scope is null or jsonb_typeof(p_scope) <> 'object' then
    raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock scope binding must be a json object';
  end if;
  -- EXACTLY THE SEVEN DECLARED FIELDS. An extra one would hash to an object the
  -- module never computes, and a missing one would hash to a shorter object
  -- rather than refusing.
  if (select count(*) from jsonb_object_keys(p_scope)) <> 7 then
    raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock scope binding carries exactly its seven declared fields';
  end if;
  if coalesce(p_scope ->> 'tenant', '') <> 'carr-internal' then
    raise exception '[j1_clock_tenant_bound] a Journey 1 clock scope binding names another tenant';
  end if;
  if coalesce(p_scope ->> 'clock_origin_gate_id', '') <> ops.j1_clock_origin_gate_id()
     or coalesce(p_scope ->> 'clock_terminus_gate_id', '') <> ops.j1_clock_terminus_gate_id() then
    raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock scope binding names gates other than % and %, so it is not a Journey 1 clock scope',
      ops.j1_clock_origin_gate_id(), ops.j1_clock_terminus_gate_id();
  end if;
  if coalesce(p_scope ->> 'scope_ref', '') !~ '^safe:[A-Za-z0-9:._/-]+$'
     or char_length(coalesce(p_scope ->> 'scope_ref', '')) not between 8 and 295 then
    raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock scope binding needs a safe: scope_ref';
  end if;
  foreach v_field in array array['benchmark_candidate_digest', 'benchmark_policy_digest',
                                 'benchmark_subject_digest'] loop
    if coalesce(p_scope ->> v_field, '') !~ '^sha256:[0-9a-f]{64}$' then
      raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock scope binding needs a sha256 %', v_field;
    end if;
  end loop;
  -- Rebuilt by name and C-sorted, so a reviewer can check it against
  -- JOURNEY_ONE_CLOCK_SCOPE_IDENTITY_FIELDS by eye. Key order is irrelevant to
  -- the hash. `scope_ref` is validated above and DELIBERATELY ABSENT here: a
  -- label a caller chose is not a fact about which program a clock belongs to,
  -- and hashing it would let one accepted scope hold one clock PER NAME.
  -- [j1_clock_scope_label_is_not_identity]
  v_fields := jsonb_build_object(
    'benchmark_candidate_digest', p_scope ->> 'benchmark_candidate_digest',
    'benchmark_policy_digest', p_scope ->> 'benchmark_policy_digest',
    'benchmark_subject_digest', p_scope ->> 'benchmark_subject_digest',
    'clock_origin_gate_id', p_scope ->> 'clock_origin_gate_id',
    'clock_terminus_gate_id', p_scope ->> 'clock_terminus_gate_id',
    'tenant', p_scope ->> 'tenant');
  return 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(jsonb_build_array(
      ops.j1_clock_scope_domain_tag(), v_fields)),
    'UTF8'), 'sha256'), 'hex');
end;
$_$;


--
-- Name: FUNCTION j1_clock_scope_digest(p_scope jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_scope_digest(p_scope jsonb) IS 'The key of one authoritative Journey 1 clock scope: sha256 over the canonical [domain_tag, the SIX identity fields]. All seven declared fields are required and validated, but the human scope_ref label is excluded from the preimage -- it is provenance, not identity, and hashing it made one accepted scope addressable under two keys. The gate ids and the tenant are checked rather than believed; the three benchmark digests are checked for shape only, because the stored clock state carries none of them and there is nothing here to compare them against.';


--
-- Name: j1_clock_scope_domain_tag(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_scope_domain_tag() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre:j1-clock-scope:v2'::text $$;


--
-- Name: FUNCTION j1_clock_scope_domain_tag(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_scope_domain_tag() IS 'The domain tag under which a Journey 1 authoritative clock scope is derived. Matches JOURNEY_ONE_CLOCK_SCOPE_DOMAIN_TAG in mcp-server/src/journey-one-clock-store.v5.js. v2 excludes the human scope_ref label from the preimage; v1 hashed it and made one accepted scope addressable under two keys.';


--
-- Name: j1_clock_scope_lock(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_scope_lock(p_clock_scope_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if p_clock_scope_key is null then
    raise exception '[j1_clock_scope_binds_one_clock] a Journey 1 clock append must name the authoritative scope it is writing for';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_clock_scope_key, 1));
  perform 1 from ops.j1_clock_scope_binding where clock_scope_key = p_clock_scope_key for update;
end;
$$;


--
-- Name: FUNCTION j1_clock_scope_lock(p_clock_scope_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_clock_scope_lock(p_clock_scope_key text) IS 'Opens the serialized same-scope section for the calling transaction, so two creations for one authoritative scope under two different origins cannot both read an unbound scope and both bind it. The clock-key lock does not cover this: their clock keys differ.';


--
-- Name: j1_clock_state_schema(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_state_schema() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre-v5-journey-one-clock.v2'::text $$;


--
-- Name: j1_clock_terminus_gate_id(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_clock_terminus_gate_id() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'journey-one-kernel-production-accepted'::text $$;


--
-- Name: j1_minimum_admission_by_idempotency_key(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admission_by_idempotency_key(p_key uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_minimum_admission_json(a.id)
    from ops.j1_minimum_admission a where a.idempotency_key = p_key
$$;


--
-- Name: j1_minimum_admission_digest(text, text, text, bigint, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admission_digest(p_admitted_at text, p_clock_scope_key text, p_minimum_environment_manifest_digest text, p_minimum_receipt_ttl_policy_ms bigint, p_previous_admission_digest text, p_receipt_digest text, p_tenant text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(jsonb_build_array(
      ops.j1_minimum_admission_domain_tag(),
      jsonb_build_object(
        'admitted_at', p_admitted_at,
        'clock_scope_key', p_clock_scope_key,
        'minimum_environment_manifest_digest', p_minimum_environment_manifest_digest,
        'minimum_receipt_ttl_policy_ms', p_minimum_receipt_ttl_policy_ms,
        'previous_admission_digest', to_jsonb(p_previous_admission_digest),
        'receipt_digest', p_receipt_digest,
        'tenant', p_tenant))),
    'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_minimum_admission_digest(p_admitted_at text, p_clock_scope_key text, p_minimum_environment_manifest_digest text, p_minimum_receipt_ttl_policy_ms bigint, p_previous_admission_digest text, p_receipt_digest text, p_tenant text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_admission_digest(p_admitted_at text, p_clock_scope_key text, p_minimum_environment_manifest_digest text, p_minimum_receipt_ttl_policy_ms bigint, p_previous_admission_digest text, p_receipt_digest text, p_tenant text) IS 'One admitted-minimum chain link: sha256 over the canonical [domain tag, the seven declared fields]. Each link hashes the link before it, so a row cannot be removed, reordered or re-dated without every later link failing to rebuild.';


--
-- Name: j1_minimum_admission_domain_tag(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admission_domain_tag() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre:j1-minimum-admission:v1'::text $$;


--
-- Name: FUNCTION j1_minimum_admission_domain_tag(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_admission_domain_tag() IS 'The domain tag under which one admitted-minimum chain link is derived. Matches JOURNEY_ONE_MINIMUM_ADMISSION_DOMAIN_TAG in mcp-server/src/journey-one-clock-input-store.v5.js.';


--
-- Name: j1_minimum_admission_instant(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admission_instant() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ select to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') $$;


--
-- Name: FUNCTION j1_minimum_admission_instant(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_admission_instant() IS 'The record layer''s own admission instant, in the kernel''s instant grammar, derived from now() -- the transaction timestamp -- so every reading of it inside one transaction is the same reading. A caller never supplies this value; ops.j1_minimum_append_admission only ever compares one against it.';


--
-- Name: j1_minimum_admission_json(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admission_json(p_admission_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
           'clock_scope_key', i.clock_scope_key,
           'clock_scope_ref', i.clock_scope_ref,
           'tenant', i.tenant,
           'admission_ordinal', a.admission_ordinal,
           'admitted_at', a.admitted_at,
           'receipt', a.receipt,
           'receipt_digest', a.receipt_digest,
           -- RECOMPUTED, not echoed: a reader is told what the stored artifact
           -- hashes to now, beside the digest it was admitted under.
           'recomputed_receipt_digest', ops.j1_minimum_receipt_digest(a.receipt),
           'gate_id', a.gate_id,
           'receipt_producer_step_ref', a.receipt_producer_step_ref,
           'observed_at', a.observed_at,
           'ttl_expires_at', a.ttl_expires_at,
           'status', a.status,
           'minimum_receipt_ttl_policy_ms', a.minimum_receipt_ttl_policy_ms,
           'minimum_environment_manifest_digest', a.minimum_environment_manifest_digest,
           'previous_admission_digest', a.prior_admission_digest,
           'admission_digest', a.admission_digest,
           'recorded_at', a.recorded_at,
           'written_by_actor_id', (select ac.slug from public.actor ac where ac.id = a.written_by_actor_id),
           -- FIVE KEYS WHERE THE MODULE'S PROVENANCE HAS SIX, and the missing one
           -- is deliberate. admitted_by_authority_class is derived by identity.js
           -- from the LIVE actor; this database has no such derivation, and a
           -- column filled from a caller -- or back-derived from a stored row --
           -- would be exactly the caller boolean the whole rail exists to
           -- prevent. The actor slug agrees on both sides.
           'provenance', jsonb_build_object(
             'receipt_schema_ref', a.receipt_schema_ref,
             'receipt_producer_step_ref', a.receipt_producer_step_ref,
             'source_ref', a.source_ref,
             'input_authority', a.input_authority,
             'admitted_by_actor_id', (select ac.slug from public.actor ac where ac.id = a.written_by_actor_id)))
    from ops.j1_minimum_admission a
    join ops.j1_minimum_inventory i on i.id = a.inventory_id
   where a.id = p_admission_id
$$;


--
-- Name: FUNCTION j1_minimum_admission_json(p_admission_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_admission_json(p_admission_id uuid) IS 'One admitted-minimum row in the shape createPostgresJourneyOneMinimumAdmissionJournal consumes, with the receipt digest RECOMPUTED beside the one it was admitted under. Its provenance carries five of the module''s six keys: admitted_by_authority_class is derived from the live actor by identity.js and this database derives no authority class, so it is absent rather than invented.';


--
-- Name: j1_minimum_admissions(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_admissions(p_clock_scope_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(ops.j1_minimum_admission_json(a.id) order by a.admission_ordinal), '[]'::jsonb)
    from ops.j1_minimum_admission a
    join ops.j1_minimum_inventory i on i.id = a.inventory_id
   where i.clock_scope_key = p_clock_scope_key
$$;


--
-- Name: FUNCTION j1_minimum_admissions(p_clock_scope_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_admissions(p_clock_scope_key text) IS 'One inventory''s admissions in admission order, each with its receipt, the digest it was admitted under and the digest that receipt hashes to now. The kernel''s minimum_history is [{admitted_at, receipt}] read straight off this list.';


--
-- Name: j1_minimum_append_admission(text, text, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_append_admission(p_clock_scope_key text, p_tenant text, p_idempotency_key uuid, p_prior_admission_digest text, p_admitted_at text, p_receipt_digest text, p_receipt jsonb, p_provenance jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_existing ops.j1_minimum_admission%rowtype;
  v_inventory ops.j1_minimum_inventory%rowtype;
  v_actor uuid; v_admission uuid; v_ordinal integer;
  v_derived text; v_at text; v_link text;
begin
  if p_idempotency_key is null then
    raise exception '[j1_minimum_idempotency_key_binds_its_payload] an admitted-minimum append must carry an idempotency key';
  end if;
  select * into v_existing from ops.j1_minimum_admission where idempotency_key = p_idempotency_key;
  if found then
    -- EVERY BINDING PARAMETER IS COMPARED. A replay matching on the artifact but
    -- naming a different inventory or prior is a different request in one key.
    if (select i.clock_scope_key from ops.j1_minimum_inventory i where i.id = v_existing.inventory_id)
         is distinct from p_clock_scope_key
       or v_existing.receipt_digest is distinct from p_receipt_digest
       or v_existing.prior_admission_digest is distinct from p_prior_admission_digest then
      raise exception '[j1_minimum_idempotency_key_binds_its_payload] idempotency key % was already used for a different minimum admission',
        p_idempotency_key;
    end if;
    return ops.j1_minimum_admission_json(v_existing.id) || jsonb_build_object('replayed', true);
  end if;

  v_actor := ops.portfolio_writer_actor_id();
  perform ops.j1_minimum_lock(p_clock_scope_key);

  select * into v_inventory from ops.j1_minimum_inventory where clock_scope_key = p_clock_scope_key;
  if not found then
    raise exception '[j1_minimum_inventory_scope_bound] authoritative clock scope % holds no admitted-minimum inventory; open it with ops.j1_minimum_open_inventory before admitting',
      p_clock_scope_key;
  end if;
  if v_inventory.tenant is distinct from p_tenant then
    raise exception '[j1_minimum_tenant_bound] admitted-minimum inventory % belongs to another tenant', p_clock_scope_key;
  end if;

  -- THE ARTIFACT'S IDENTITY IS DERIVED, NEVER ACCEPTED. A caller may name one;
  -- it is only ever compared against the one the artifact produces.
  v_derived := ops.j1_minimum_receipt_digest(p_receipt);
  if p_receipt_digest is distinct from v_derived then
    raise exception '[j1_minimum_claimed_digest_is_never_trusted] the named receipt digest is not the one this artifact produces: named %, computed %',
      coalesce(p_receipt_digest, 'null'), v_derived;
  end if;
  if exists (select 1 from ops.j1_minimum_admission
              where inventory_id = v_inventory.id and receipt_digest = v_derived) then
    raise exception '[j1_minimum_receipt_never_readmitted] receipt % is already in this inventory; re-presenting one artifact under a new admission instant is a replay, not a second admission',
      v_derived;
  end if;

  -- AND SO IS THE ADMISSION INSTANT. now() is the transaction timestamp, so the
  -- value the caller read from ops.j1_minimum_admission_instant() in this same
  -- transaction is bit-for-bit this one; a differing value is a caller trying to
  -- date its own admission.
  v_at := ops.j1_minimum_admission_instant();
  if p_admitted_at is not null and p_admitted_at is distinct from v_at then
    raise exception '[j1_minimum_admission_instant_is_server_time] admitted_at is stamped by this record layer and is never a caller field: derived %, supplied %',
      v_at, p_admitted_at;
  end if;

  select coalesce(max(admission_ordinal), -1) + 1 into v_ordinal
    from ops.j1_minimum_admission where inventory_id = v_inventory.id;

  v_link := ops.j1_minimum_admission_digest(v_at, v_inventory.clock_scope_key,
    v_inventory.minimum_environment_manifest_digest, v_inventory.minimum_receipt_ttl_policy_ms,
    p_prior_admission_digest, v_derived, v_inventory.tenant);

  insert into ops.j1_minimum_admission(
    inventory_id, admission_ordinal, idempotency_key, prior_admission_digest, admission_digest,
    receipt, receipt_digest, admitted_at, gate_id, receipt_producer_step_ref,
    observed_at, ttl_expires_at, status,
    minimum_receipt_ttl_policy_ms, minimum_environment_manifest_digest,
    receipt_schema_ref, source_ref, input_authority, written_by_actor_id)
  values (v_inventory.id, v_ordinal, p_idempotency_key, p_prior_admission_digest, v_link,
    p_receipt, v_derived, v_at,
    p_receipt ->> 'gate_id', p_receipt ->> 'receipt_producer_step_ref',
    p_receipt ->> 'observed_at', p_receipt ->> 'ttl_expires_at', p_receipt ->> 'status',
    v_inventory.minimum_receipt_ttl_policy_ms, v_inventory.minimum_environment_manifest_digest,
    -- PROVENANCE IS PINNED, NOT COPIED. The schema ref and input_authority are
    -- CHECK-constrained to single values so a direct writer cannot widen them
    -- into a claim of verification; source_ref NAMES the origin of the artifact.
    ops.j1_minimum_receipt_schema(), p_provenance ->> 'source_ref',
    'trusted_admission_not_independently_verified_by_this_record_layer', v_actor)
  returning id into v_admission;

  return ops.j1_minimum_admission_json(v_admission) || jsonb_build_object('replayed', false);
end;
$$;


--
-- Name: FUNCTION j1_minimum_append_admission(p_clock_scope_key text, p_tenant text, p_idempotency_key uuid, p_prior_admission_digest text, p_admitted_at text, p_receipt_digest text, p_receipt jsonb, p_provenance jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_append_admission(p_clock_scope_key text, p_tenant text, p_idempotency_key uuid, p_prior_admission_digest text, p_admitted_at text, p_receipt_digest text, p_receipt jsonb, p_provenance jsonb) IS 'The only way to admit a foundation-assurance-minimum receipt to an inventory. The writer, the admission instant, the receipt digest and the chain link are all DERIVED; the caller supplies the artifact, an idempotency key, a source reference and the exact prior chain digest it believes is the head. It replays an exact idempotent repeat and refuses a key whose payload changed. It records an INPUT with scoped provenance: it admits nothing to a gate, verifies no artifact, accepts no benchmark and starts no clock.';


--
-- Name: j1_minimum_append_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_append_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare
  v_inventory ops.j1_minimum_inventory%rowtype;
  v_head ops.j1_minimum_admission%rowtype;
  v_field text; v_seat_field text; v_keys integer;
  v_observed timestamptz; v_expires timestamptz; v_admitted timestamptz;
begin
  select * into v_inventory from ops.j1_minimum_inventory where id = new.inventory_id;
  if not found then
    raise exception '[j1_minimum_inventory_scope_bound] an admitted-minimum row names an unknown inventory';
  end if;
  -- TENANT. An admission is stored under the tenant its inventory was opened with.
  if v_inventory.tenant <> 'carr-internal' then
    raise exception '[j1_minimum_tenant_bound] admitted-minimum inventory % is not this tenant''s', v_inventory.clock_scope_key;
  end if;

  -- ATTRIBUTION. The writer is the server-established one, never a payload
  -- field. This is the record layer's own rule and carries no shared invariant
  -- id: on the JavaScript side the writer is derived from the live actor before
  -- a store can be constructed at all.
  if new.written_by_actor_id <> ops.portfolio_writer_actor_id() then
    raise exception 'admitted-minimum row actor does not match the authenticated writer context';
  end if;

  -- THE ARTIFACT IS A CLOSED consumer-gate-receipt.v1 FROM THIS PRODUCER.
  if jsonb_typeof(new.receipt) <> 'object' then
    raise exception '[j1_minimum_receipt_producer_bound] an admitted minimum receipt is a json object';
  end if;
  select count(*) into v_keys from jsonb_object_keys(new.receipt);
  if v_keys <> 21 then
    raise exception '[j1_minimum_receipt_producer_bound] an admitted minimum receipt carries exactly the twenty-one declared fields of %', ops.j1_minimum_receipt_schema();
  end if;
  foreach v_field in array ops.j1_minimum_receipt_fields() loop
    if not (new.receipt ? v_field) then
      raise exception '[j1_minimum_receipt_producer_bound] an admitted minimum receipt is missing %', v_field;
    end if;
  end loop;
  if (new.receipt ->> 'gate_id') is distinct from ops.j1_clock_origin_gate_id()
     or (new.receipt ->> 'receipt_producer_step_ref') is distinct from ops.j1_minimum_producer_step_ref()
     or (new.receipt ->> 'producer_role') is distinct from ops.j1_minimum_producer_role()
     or (new.receipt ->> 'independent_oracle_ref') is distinct from ops.j1_minimum_oracle_ref()
     or (new.receipt ->> 'oracle_version') is distinct from ops.j1_minimum_oracle_version()
     or (new.receipt ->> 'evidence_scope') is distinct from ops.j1_minimum_evidence_scope()
     or (new.receipt ->> 'subject_environment') is distinct from ops.j1_minimum_subject_environment() then
    raise exception '[j1_minimum_receipt_producer_bound] this inventory admits the % receipt its own producer step issues, and nothing else; the kernel refuses another producer fatally and an append-only inventory could never shed the row',
      ops.j1_clock_origin_gate_id();
  end if;

  -- THE REMAINING FATAL-IN-KERNEL SHAPE FACTS, mirroring the module's clauses in
  -- journeyOneMinimumAdmissionView. Each is fatal in the kernel rather than
  -- skipped -- invalid_reference, invalid_identity, invalid_digest,
  -- invalid_comparator -- so one admitted row would make every later evaluation
  -- of this inventory throw, and an append-only inventory cannot shed it.
  --
  -- IT IS SHAPE, NOT ELIGIBILITY AND NOT SEAT AUTHORITY. No independence between
  -- the seats is judged here and no authority class is derived: that belongs to
  -- the join that PROPOSES a receipt, which is the only seat holding the live
  -- identities, and it is disclosed in ops.j1_minimum_record_layer_cannot_prove().
  -- TYPE FIRST, THEN VALUE, AND THE TYPE TEST IS NULL-AWARE.
  --
  -- `->>` RENDERS a jsonb number, boolean or null as text, so a regex or a
  -- length applied to it silently judges a value the JavaScript home refuses
  -- outright: the numeric comparator 12345 becomes '12345' and passes a bare
  -- length test, and a numeric actor_id becomes a non-empty string. That is a
  -- BOTH-homes invariant admitting on one side what it refuses on the other, so
  -- every field below is type-checked against jsonb_typeof before its value is
  -- read. IS DISTINCT FROM is the null-aware form: an absent key yields NULL,
  -- and `if NULL then` does not fire, which would fail open on exactly the
  -- missing field.
  --
  -- The bounds are the KERNEL'S, counted the kernel's way: its ref() tests the
  -- prefix and then the WHOLE string against [A-Za-z0-9:._/-]{3,300}, so the
  -- five-character prefix leaves 295 and the eight-character one leaves 292.
  if jsonb_typeof(new.receipt -> 'evidence_ref') is distinct from 'string'
     or coalesce(new.receipt ->> 'evidence_ref', '') !~ '^safe:[A-Za-z0-9:._/-]*$'
     or char_length(coalesce(new.receipt ->> 'evidence_ref', '')) not between 5 and 300 then
    raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.evidence_ref is a json string holding a safe: reference the kernel can read';
  end if;
  if jsonb_typeof(new.receipt -> 'fixture_set_digest') is distinct from 'string'
     or coalesce(new.receipt ->> 'fixture_set_digest', '') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.fixture_set_digest is a json string holding a sha256 reference';
  end if;
  -- UTF-16 CODE UNITS, WHICH IS WHAT THE KERNEL COUNTS. char_length() counts
  -- CODEPOINTS, and the two differ on text above U+FFFF in BOTH directions: 151
  -- astral characters are 151 codepoints and 302 UTF-16 units, so a codepoint
  -- test admits a comparator the kernel refuses; three astral characters are 3
  -- codepoints and 6 UTF-16 units, so a codepoint test refuses one the kernel
  -- ACCEPTS. Narrowing the accepted domain is as wrong as widening it, so the
  -- count is exact rather than approximated in either direction.
  -- ops.benchmark_utf16_length() is the ONE home of that count -- its name is
  -- historical, its contract is "the length JavaScript String#length would
  -- report" -- and a rail-local copy would be a second counter that agrees today.
  -- The type test in front of it also keeps its STRICT null from failing open.
  if jsonb_typeof(new.receipt -> 'comparator') is distinct from 'string'
     or ops.benchmark_utf16_length(new.receipt ->> 'comparator') < 5
     or ops.benchmark_utf16_length(new.receipt ->> 'comparator') > 300 then
    raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.comparator is a json string of between 5 and 300 UTF-16 code units';
  end if;
  -- THE SEATS. Written as nested statements rather than one OR chain because
  -- jsonb_object_keys ERRORS on a non-object and SQL does not promise to
  -- short-circuit an OR: the type test has to have already run.
  foreach v_field in array array[
    'evaluator_identity', 'producer_identity', 'subject_maker_identity'
  ] loop
    if jsonb_typeof(new.receipt -> v_field) is distinct from 'object' then
      raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.% is a json object seat', v_field;
    end if;
    if (select count(*) from jsonb_object_keys(new.receipt -> v_field)) <> 3 then
      raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.% carries exactly the three declared fields of an authenticated-receipt-identity.v1 seat',
        v_field;
    end if;
    -- Three names AND three string types: a seat with three keys under other
    -- names fails here rather than on the count, because a missing name yields
    -- NULL from jsonb_typeof and IS DISTINCT FROM refuses it.
    foreach v_seat_field in array array['actor_id', 'authority_class', 'session_ref'] loop
      if jsonb_typeof(new.receipt -> v_field -> v_seat_field) is distinct from 'string' then
        raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.%.% is a json string', v_field, v_seat_field;
      end if;
      if (new.receipt -> v_field ->> v_seat_field) = '' then
        raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.%.% is a non-empty string', v_field, v_seat_field;
      end if;
    end loop;
    if (new.receipt -> v_field ->> 'session_ref') !~ '^session:[A-Za-z0-9:._/-]*$'
       or char_length(new.receipt -> v_field ->> 'session_ref') not between 8 and 300 then
      raise exception '[j1_minimum_receipt_readable_by_kernel] receipt.%.session_ref is a session: reference the kernel can read',
        v_field;
    end if;
  end loop;

  -- THE ACCEPTED SCOPE DECIDES, NOT THE RECEIPT. The three digests come from the
  -- scope this inventory was opened under and the environment from its sealed
  -- policy, so a receipt for another subject is refused rather than quietly
  -- widening the inventory's own binding.
  --
  -- ops.j1_clock_assert_same is the clock rail's fail-closed comparison and is
  -- reused rather than copied: `a <> b` is NULL when either side is null and
  -- would fall through exactly when the value was never derived. Its message
  -- text says "clock revision" because that rail wrote it; the INVARIANT ID it
  -- raises is this rail's, and the id is what the two homes are compared on.
  perform ops.j1_clock_assert_same('j1_minimum_receipt_binds_accepted_scope', 'subject_digest',
    v_inventory.clock_scope ->> 'benchmark_subject_digest', new.receipt ->> 'subject_digest');
  perform ops.j1_clock_assert_same('j1_minimum_receipt_binds_accepted_scope', 'candidate_digest',
    v_inventory.clock_scope ->> 'benchmark_candidate_digest', new.receipt ->> 'candidate_digest');
  perform ops.j1_clock_assert_same('j1_minimum_receipt_binds_accepted_scope', 'policy_digest',
    v_inventory.clock_scope ->> 'benchmark_policy_digest', new.receipt ->> 'policy_digest');
  perform ops.j1_clock_assert_same('j1_minimum_receipt_binds_accepted_scope',
    'environment_manifest_digest', v_inventory.minimum_environment_manifest_digest,
    new.receipt ->> 'environment_manifest_digest');

  -- THE EXTRACTED COLUMNS ARE A PROJECTION OF THE ARTIFACT.
  perform ops.j1_clock_assert_same('j1_minimum_content_rebuilds_to_its_digest', 'gate_id',
    new.receipt ->> 'gate_id', new.gate_id);
  perform ops.j1_clock_assert_same('j1_minimum_content_rebuilds_to_its_digest',
    'receipt_producer_step_ref', new.receipt ->> 'receipt_producer_step_ref',
    new.receipt_producer_step_ref);
  perform ops.j1_clock_assert_same('j1_minimum_content_rebuilds_to_its_digest', 'observed_at',
    new.receipt ->> 'observed_at', new.observed_at);
  perform ops.j1_clock_assert_same('j1_minimum_content_rebuilds_to_its_digest', 'ttl_expires_at',
    new.receipt ->> 'ttl_expires_at', new.ttl_expires_at);
  perform ops.j1_clock_assert_same('j1_minimum_content_rebuilds_to_its_digest', 'status',
    new.receipt ->> 'status', new.status);

  -- CONTENT. The stored artifact hashes to the digest it is filed under.
  if ops.j1_minimum_receipt_digest(new.receipt) is distinct from new.receipt_digest then
    raise exception '[j1_minimum_content_rebuilds_to_its_digest] the stored receipt does not hash to the digest it is admitted under: computed %, filed %',
      ops.j1_minimum_receipt_digest(new.receipt), new.receipt_digest;
  end if;

  -- THE SEALED ACCEPTED POLICY travels on the row and must be the inventory's.
  perform ops.j1_clock_assert_same('j1_minimum_inventory_policy_sealed',
    'minimum_receipt_ttl_policy_ms', v_inventory.minimum_receipt_ttl_policy_ms,
    new.minimum_receipt_ttl_policy_ms);
  perform ops.j1_clock_assert_same('j1_minimum_inventory_policy_sealed',
    'minimum_environment_manifest_digest', v_inventory.minimum_environment_manifest_digest,
    new.minimum_environment_manifest_digest);

  -- THE WINDOW, against the accepted policy. An overlong window is a misissued
  -- receipt or a misbound policy, which the kernel refuses FATALLY rather than
  -- skipping, so it can never be stored here.
  v_observed := new.observed_at::timestamptz;
  v_expires := new.ttl_expires_at::timestamptz;
  v_admitted := new.admitted_at::timestamptz;
  if v_expires <= v_observed then
    raise exception '[j1_minimum_receipt_window_within_accepted_policy] a receipt''s ttl_expires_at is after its observed_at';
  end if;
  if extract(epoch from (v_expires - v_observed)) * 1000
     > new.minimum_receipt_ttl_policy_ms then
    raise exception '[j1_minimum_receipt_window_within_accepted_policy] the receipt''s window exceeds the accepted maximum of % ms this inventory was opened under',
      new.minimum_receipt_ttl_policy_ms;
  end if;

  -- THE ADMISSION INSTANT IS THIS DATABASE'S OWN, AND IT IS BOUND TO THE
  -- ARTIFACT'S OBSERVATION WITHOUT SKEW.
  if new.admitted_at is distinct from ops.j1_minimum_admission_instant() then
    raise exception '[j1_minimum_admission_instant_is_server_time] admitted_at is stamped by this record layer and is never a caller field: derived %, supplied %',
      ops.j1_minimum_admission_instant(), new.admitted_at;
  end if;
  if v_observed > v_admitted then
    raise exception '[j1_minimum_admission_not_before_observation] this receipt reports being observed at %, after the instant % the record layer admitted it. A single instant of skew is fatal to every later evaluation of the inventory and an append-only inventory cannot shed the row',
      new.observed_at, new.admitted_at;
  end if;

  -- ORDER AND THE ORIGIN. THE LEDGER IS STORED IN THE KERNEL'S OWN SELECTION
  -- ORDER AND AN APPEND ONLY EVER EXTENDS IT: admitted_at non-decreasing, and
  -- STRICTLY INCREASING receipt digest within one admitted_at group.
  --
  -- The kernel orders candidates by (admitted_at, receipt_digest) and takes the
  -- FIRST ELIGIBLE one, skipping every inadmissible attempt, so the row it
  -- selected is not necessarily the first row in this ledger. Comparing a
  -- newcomer against the FIRST ROW is therefore the wrong comparison: with a
  -- failed attempt at T0 and a passing one at T1, the origin is the T1 row, and
  -- a second T1 row with a lower digest ties nothing at T0 while taking the
  -- origin away from the row that had it -- which surfaces on the next
  -- evaluation as origin_reset_or_rebase against a retained history and leaves
  -- the clock unreadable rather than wrong.
  --
  -- Keeping the stored sequence in that same total order closes it without this
  -- database computing eligibility, which is the kernel's and stays the
  -- kernel's: a new row sorts after every stored row, so it cannot be preferred
  -- to any of them, whichever ones were eligible. The head alone is enough to
  -- compare against because it is the maximum of its own group under this
  -- invariant, and ops.j1_minimum_history re-checks the whole sequence rather
  -- than trusting the induction.
  select * into v_head from ops.j1_minimum_admission
    where inventory_id = new.inventory_id and id <> new.id
    order by admission_ordinal desc limit 1;
  if found then
    if new.prior_admission_digest is distinct from v_head.admission_digest then
      raise exception '[j1_minimum_exact_prior_admission_digest] the prior admission digest is not the current head: head %, supplied %',
        v_head.admission_digest, coalesce(new.prior_admission_digest, 'null');
    end if;
    if new.admission_ordinal <> v_head.admission_ordinal + 1 then
      raise exception '[j1_minimum_content_rebuilds_to_its_digest] admitted-minimum ordinals are not contiguous: head %, supplied %',
        v_head.admission_ordinal, new.admission_ordinal;
    end if;
    if v_admitted < v_head.admitted_at::timestamptz then
      raise exception '[j1_minimum_first_origin_never_replaced] an append-only admission inventory only ever gains LATER admissions; this one is dated % and the head is %',
        new.admitted_at, v_head.admitted_at;
    end if;
    if new.recorded_at < v_head.recorded_at then
      raise exception '[j1_minimum_admission_instant_is_server_time] the server clock moved backwards between two admissions of one inventory';
    end if;
    -- COLLATE "C": byte order, matching the JavaScript home's UTF-16 code-unit
    -- comparison, rather than whatever collation this database happens to default
    -- to. See the same pin in ops.j1_minimum_history.
    if v_admitted = v_head.admitted_at::timestamptz
       and new.receipt_digest collate "C" <= v_head.receipt_digest then
      raise exception '[j1_minimum_first_origin_never_replaced] this admission shares the head''s admission instant % and does not sort after it (head digest %, supplied %), so the kernel could prefer it to a row already stored in that group -- including the eligible row it has already selected as the origin. Within one admission instant the receipt digest strictly increases, because that is the order the kernel selects in',
        v_head.admitted_at, v_head.receipt_digest, new.receipt_digest;
    end if;
  else
    if new.prior_admission_digest is not null then
      raise exception '[j1_minimum_exact_prior_admission_digest] this inventory holds no admissions, so there is no prior digest to match; open it with an explicit null prior';
    end if;
    if new.admission_ordinal <> 0 then
      raise exception '[j1_minimum_content_rebuilds_to_its_digest] the opening admission of an inventory is ordinal 0';
    end if;
  end if;

  -- THE CHAIN LINK, recomputed rather than accepted.
  if ops.j1_minimum_admission_digest(new.admitted_at, v_inventory.clock_scope_key,
       new.minimum_environment_manifest_digest, new.minimum_receipt_ttl_policy_ms,
       new.prior_admission_digest, new.receipt_digest, v_inventory.tenant)
     is distinct from new.admission_digest then
    raise exception '[j1_minimum_claimed_digest_is_never_trusted] the named admission digest is not the one this row produces';
  end if;

  return new;
end;
$_$;


--
-- Name: FUNCTION j1_minimum_append_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_append_guard() IS 'Everything an admitted-minimum row depends on, checked from the persisted rows and the artifact itself: the closed receipt shape and its producer, the accepted scope and sealed policy, the recomputed receipt digest and chain link, the server admission instant and its binding to the receipt''s observation, and the append-only ordering that keeps the stored sequence in the kernel''s own (admitted_at, receipt_digest) selection order, so no append can displace the eligible row the kernel already selected as the origin. It judges no receipt''s internal seat independence, computes no eligibility, and filters nothing: a non-passing or lapsed receipt is an ordinary fact of the ledger and is stored.';


--
-- Name: j1_minimum_evidence_scope(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_evidence_scope() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'candidate-and-test'::text $$;


--
-- Name: j1_minimum_head(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_head(p_clock_scope_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.j1_minimum_admission_json(a.id)
    from ops.j1_minimum_admission a
    join ops.j1_minimum_inventory i on i.id = a.inventory_id
   where i.clock_scope_key = p_clock_scope_key
   order by a.admission_ordinal desc
   limit 1
$$;


--
-- Name: j1_minimum_history(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_history(p_clock_scope_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_row record; v_previous text := null; v_ordinal integer := 0; v_history jsonb := '[]'::jsonb;
  v_last_at timestamptz := null; v_last_digest text := null;
  v_inventory ops.j1_minimum_inventory%rowtype;
begin
  select * into v_inventory from ops.j1_minimum_inventory where clock_scope_key = p_clock_scope_key;
  if not found then
    return jsonb_build_object(
      'schema_version', 'doctorcre-v5-journey-one-minimum-inventory-readback.v1',
      'clock_scope_key', p_clock_scope_key,
      'tenant', 'carr-internal',
      'exists', false,
      'record_layer_cannot_prove', ops.j1_minimum_record_layer_cannot_prove(),
      -- THE MODULE'S OWN exists:false KEY SET, EXACTLY. read() returns
      -- {schema_version, clock_scope_key, tenant, exists, record_layer_cannot_
      -- prove, effects} and nothing else -- no gate_admitted_by_record_layer,
      -- because there is no inventory to say anything about. An earlier revision
      -- carried that key here and no `effects`, so five of the six agreed while
      -- the header claimed the branch matched; a claimed parity that is off by
      -- one field is worse than no claim, because it is the reason nobody checks.
      'effects', jsonb_build_object(
        'creates_effect', false, 'database_writes', 0, 'network_calls', 0,
        'provider_actions', 0, 'notifications', 0, 'schedules', 0,
        'deployments', 0, 'activations', 0, 'acceptances', 0));
  end if;
  for v_row in
    select a.* from ops.j1_minimum_admission a
      join ops.j1_minimum_inventory i on i.id = a.inventory_id
     where i.clock_scope_key = p_clock_scope_key
     order by a.admission_ordinal
  loop
    if v_row.admission_ordinal <> v_ordinal then
      raise exception '[j1_minimum_content_rebuilds_to_its_digest] admitted-minimum ordinals are not contiguous from zero at position %', v_ordinal;
    end if;
    if ops.j1_minimum_receipt_digest(v_row.receipt) is distinct from v_row.receipt_digest then
      raise exception '[j1_minimum_content_rebuilds_to_its_digest] admission % no longer hashes to the digest it was admitted under', v_ordinal;
    end if;
    if v_row.prior_admission_digest is distinct from v_previous
       or ops.j1_minimum_admission_digest(v_row.admitted_at, p_clock_scope_key,
            v_row.minimum_environment_manifest_digest, v_row.minimum_receipt_ttl_policy_ms,
            v_previous, v_row.receipt_digest, 'carr-internal')
          is distinct from v_row.admission_digest then
      raise exception '[j1_minimum_exact_prior_admission_digest] admission % does not link to the admission before it', v_ordinal;
    end if;
    -- THE SELECTION ORDER, RE-CHECKED ON READ RATHER THAN ASSUMED. The guard
    -- compares a newcomer against the head only, which is sound by induction;
    -- this validates the whole sequence, because the induction is exactly what
    -- a row inserted by some other route would break. Serving an out-of-order
    -- inventory would hand the kernel an origin this rail never admitted first.
    -- COLLATE "C" IS THE PARITY, NOT A PREFERENCE. The JavaScript home compares
    -- these digests with UTF-16 code units; a database default collation is
    -- locale-dependent, and two homes that agree by coincidence of locale are
    -- two homes that can disagree after one initdb. Byte order is the rule on
    -- both sides, so it is pinned here and in the guard rather than inherited.
    if v_last_at is not null
       and (v_row.admitted_at::timestamptz < v_last_at
            or (v_row.admitted_at::timestamptz = v_last_at
                and v_row.receipt_digest collate "C" <= v_last_digest)) then
      raise exception '[j1_minimum_first_origin_never_replaced] admission % does not sort after the one it follows; a stored inventory is in the kernel''s own (admitted_at, receipt_digest) selection order',
        v_ordinal;
    end if;
    v_last_at := v_row.admitted_at::timestamptz;
    v_last_digest := v_row.receipt_digest;
    v_history := v_history || jsonb_build_array(jsonb_build_object(
      'admitted_at', v_row.admitted_at, 'receipt', v_row.receipt));
    v_previous := v_row.admission_digest;
    v_ordinal := v_ordinal + 1;
  end loop;
  if v_ordinal = 0 then
    raise exception '[j1_minimum_content_rebuilds_to_its_digest] inventory % exists with no admissions', p_clock_scope_key;
  end if;
  return jsonb_build_object(
    'schema_version', 'doctorcre-v5-journey-one-minimum-inventory-readback.v1',
    'clock_scope_key', p_clock_scope_key,
    'tenant', v_inventory.tenant,
    'exists', true,
    'clock_scope_ref', v_inventory.clock_scope_ref,
    'clock_scope', v_inventory.clock_scope,
    'minimum_receipt_ttl_policy_ms', v_inventory.minimum_receipt_ttl_policy_ms,
    'minimum_environment_manifest_digest', v_inventory.minimum_environment_manifest_digest,
    'inventory', ops.j1_minimum_inventory_row(p_clock_scope_key),
    'admission_count', v_ordinal,
    'head_admission_digest', v_previous,
    'minimum_history', v_history,
    'admissions', ops.j1_minimum_admissions(p_clock_scope_key),
    'record_layer_cannot_prove', ops.j1_minimum_record_layer_cannot_prove(),
    'gate_admitted_by_record_layer', false,
    'effects', jsonb_build_object(
      'creates_effect', false, 'database_writes', 0, 'network_calls', 0,
      'provider_actions', 0, 'notifications', 0, 'schedules', 0,
      'deployments', 0, 'activations', 0, 'acceptances', 0));
end;
$$;


--
-- Name: FUNCTION j1_minimum_history(p_clock_scope_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_history(p_clock_scope_key text) IS 'Deterministic zero-write readback of one authoritative scope''s admitted-minimum inventory, with the kernel''s own minimum_history assembled from the stored rows. Every receipt is re-hashed, every chain link recomputed, and the whole sequence re-validated against the kernel''s (admitted_at, receipt_digest) selection order; a tampered or out-of-order row refuses rather than being skipped, because a dropped attempt is a discard and a row out of that order could hand the kernel an origin this rail never admitted first.';


--
-- Name: j1_minimum_inventory_row(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_inventory_row(p_clock_scope_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object(
           'clock_scope_key', i.clock_scope_key,
           'clock_scope_ref', i.clock_scope_ref,
           'scope', i.clock_scope,
           'tenant', i.tenant,
           'minimum_receipt_ttl_policy_ms', i.minimum_receipt_ttl_policy_ms,
           'minimum_environment_manifest_digest', i.minimum_environment_manifest_digest,
           'opened_at', i.opened_at)
    from ops.j1_minimum_inventory i where i.clock_scope_key = p_clock_scope_key
$$;


--
-- Name: j1_minimum_lock(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_lock(p_clock_scope_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  if p_clock_scope_key is null then
    raise exception '[j1_minimum_inventory_scope_bound] an admitted-minimum append must name the authoritative scope it is writing for';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_clock_scope_key, 2));
  perform 1 from ops.j1_minimum_inventory where clock_scope_key = p_clock_scope_key for update;
end;
$$;


--
-- Name: FUNCTION j1_minimum_lock(p_clock_scope_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_lock(p_clock_scope_key text) IS 'Opens the serialized same-inventory section for the calling transaction: a transaction-scoped advisory lock on the scope key (which serializes concurrent OPENINGS, which have no row yet) plus FOR UPDATE on the inventory row when it exists.';


--
-- Name: j1_minimum_open_inventory(jsonb, bigint, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_open_inventory(p_clock_scope jsonb, p_minimum_receipt_ttl_policy_ms bigint, p_minimum_environment_manifest_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_key text; v_existing ops.j1_minimum_inventory%rowtype;
begin
  -- ONE SCOPE DERIVATION, AND IT IS THE CLOCK RAIL'S. A second one here would
  -- address one program's inputs and one program's clock under two keys.
  v_key := ops.j1_clock_scope_digest(p_clock_scope);
  if p_minimum_receipt_ttl_policy_ms is null or p_minimum_receipt_ttl_policy_ms <= 0 then
    raise exception '[j1_minimum_inventory_policy_sealed] an admitted-minimum inventory needs the accepted maximum minimum-receipt TTL it admits under';
  end if;
  if coalesce(p_minimum_environment_manifest_digest, '') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception '[j1_minimum_inventory_policy_sealed] an admitted-minimum inventory needs the accepted minimum environment manifest digest it admits under';
  end if;
  perform ops.j1_minimum_lock(v_key);

  select * into v_existing from ops.j1_minimum_inventory where clock_scope_key = v_key;
  if found then
    if v_existing.minimum_receipt_ttl_policy_ms is distinct from p_minimum_receipt_ttl_policy_ms
       or v_existing.minimum_environment_manifest_digest
          is distinct from p_minimum_environment_manifest_digest then
      raise exception '[j1_minimum_inventory_policy_sealed] admitted-minimum inventory % was opened under TTL policy % and environment %, and % / % was supplied. The accepted policy is sealed at the first admission and is never applied to rows it did not judge',
        v_key, v_existing.minimum_receipt_ttl_policy_ms,
        v_existing.minimum_environment_manifest_digest,
        p_minimum_receipt_ttl_policy_ms, p_minimum_environment_manifest_digest;
    end if;
    -- THE LABEL IS SEALED AT OPENING. It is not identity -- v_key ignores it,
    -- which is what makes a relabelled scope the SAME scope -- and precisely
    -- because it is not identity the record must not hold two names for one
    -- scope or silently replace the one it was opened under.
    if v_existing.clock_scope_ref is distinct from (p_clock_scope ->> 'scope_ref') then
      raise exception '[j1_minimum_scope_label_is_not_identity] admitted-minimum inventory % was opened under label %, and % was supplied. The label is provenance, is recorded once, and is never rewritten by a later write',
        v_key, v_existing.clock_scope_ref, coalesce(p_clock_scope ->> 'scope_ref', 'null');
    end if;
    return ops.j1_minimum_inventory_row(v_key);
  end if;

  insert into ops.j1_minimum_inventory(
    clock_scope_key, clock_scope, clock_scope_ref, tenant,
    minimum_receipt_ttl_policy_ms, minimum_environment_manifest_digest, opened_by_actor_id)
  values (v_key, p_clock_scope, p_clock_scope ->> 'scope_ref', p_clock_scope ->> 'tenant',
    p_minimum_receipt_ttl_policy_ms, p_minimum_environment_manifest_digest,
    ops.portfolio_writer_actor_id());
  return ops.j1_minimum_inventory_row(v_key);
end;
$_$;


--
-- Name: FUNCTION j1_minimum_open_inventory(p_clock_scope jsonb, p_minimum_receipt_ttl_policy_ms bigint, p_minimum_environment_manifest_digest text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_open_inventory(p_clock_scope jsonb, p_minimum_receipt_ttl_policy_ms bigint, p_minimum_environment_manifest_digest text) IS 'Open the admitted-minimum inventory of one authoritative clock scope, deriving the scope key with the clock rail''s own ops.j1_clock_scope_digest. Idempotent for the exact binding; refuses a changed accepted policy, a changed environment manifest and a second label. It proves nothing about whether the supplied scope or policy is any projection''s accepted one.';


--
-- Name: j1_minimum_oracle_ref(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_oracle_ref() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'oracle:gate-producer:foundation-assurance-minimum'::text $$;


