    AS $$ select '1.0.0'::text $$;


--
-- Name: j1_minimum_producer_role(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_producer_role() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'independent_foundation_assurance_minimum_oracle'::text $$;


--
-- Name: j1_minimum_producer_step_ref(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_producer_step_ref() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'step:foundation-assurance-minimum-receipt'::text $$;


--
-- Name: j1_minimum_receipt_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_receipt_digest(p_receipt jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(p_receipt), 'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION j1_minimum_receipt_digest(p_receipt jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_receipt_digest(p_receipt jsonb) IS 'The identity of one admitted minimum receipt: sha256 over the canonical serialization of the artifact, untagged, exactly as journey-one-clock.v5.js computes digest(admission.receipt) and seals it as origin_receipt_digest.';


--
-- Name: j1_minimum_receipt_fields(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_receipt_fields() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select array[
  'candidate_digest','comparator','environment_manifest_digest','evaluator_identity',
  'evidence_ref','evidence_scope','fixture_set_digest','gate_id','independent_oracle_ref',
  'negative_admission_result','observed_at','oracle_version','policy_digest',
  'producer_identity','producer_role','receipt_producer_step_ref','status',
  'subject_digest','subject_environment','subject_maker_identity','ttl_expires_at']::text[] $$;


--
-- Name: FUNCTION j1_minimum_receipt_fields(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_receipt_fields() IS 'The closed twenty-one field set of consumer-gate-receipt.v1, matching CONSUMER_GATE_RECEIPT_FIELDS in mcp-server/src/benchmark-minimum.v5.js. Neither home declares a schema_version: the r7 schema does not have one, and the producer step ref is the discriminator.';


--
-- Name: j1_minimum_receipt_schema(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_receipt_schema() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'consumer-gate-receipt.v1'::text $$;


--
-- Name: j1_minimum_record_layer_cannot_prove(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_record_layer_cannot_prove() RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select jsonb_build_array(
    'that an admitted artifact is a receipt a real independent foundation-assurance-minimum oracle issued: no issuance adapter exists, benchmark-minimum.v5.js proposes a receipt and marks it proposed_not_issued, and a trusted writer''s composed object is indistinguishable here from a genuine one',
    'that the three seats inside an admitted receipt are independent of one another and of the subject''s maker: that is enforced where the receipt is proposed and refused by name by the kernel, and this rail owns no second copy',
    'that the identities inside a receipt are live authenticated seats rather than strings',
    'that the Gate Zero outcome and the benchmark coverage fact the join consumed were bound to this receipt: consumer-gate-receipt.v1 has no field for either and this rail stores neither',
    'that the accepted scope and accepted minimum policy an inventory was opened under are the ones a verifier accepted for any projection: both are trusted bindings, compared and sealed, never verified',
    'that a row written by a direct holder of the writer bundle is a genuine admission rather than that writer''s assertion',
    'anything about a deadline. An admitted row is an INPUT the kernel may read: it starts no clock, accepts no benchmark and grants no gate')
$$;


--
-- Name: FUNCTION j1_minimum_record_layer_cannot_prove(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_record_layer_cannot_prove() IS 'The explicit list of things a stored admitted-minimum row does NOT prove. Returned on every readback so a stored receipt is never read as an admitted gate.';


--
-- Name: j1_minimum_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception '[j1_minimum_rows_are_append_only] Journey 1 minimum-input rows are append-only: % is refused on ops.%',
    tg_op, tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: FUNCTION j1_minimum_rows_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.j1_minimum_rows_immutable() IS 'Refuses every update, delete and truncate on the admitted-minimum storage tables. Carries the shared invariant id j1_minimum_rows_are_append_only. It is installed twice per relation because a row-level trigger never sees TRUNCATE, and TRUNCATE cannot be revoked from the table owner.';


--
-- Name: j1_minimum_subject_environment(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.j1_minimum_subject_environment() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'candidate'::text $$;


--
-- Name: legacy_rule_admission_note(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.legacy_rule_admission_note(p_rule_id uuid, p_status text, p_activated_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select case
    when p_status is distinct from 'active' then null
    when exists (select 1 from ops.rule_approval_receipt where rule_id=p_rule_id) then null
    when not exists (select 1 from ops.rule_approval_receipt) then
      'legacy_admission: rule '||p_rule_id||' carries no approval receipt and the approval-receipt system has never issued one; accepted as predating the ledger'
    when p_activated_at is not null
         and p_activated_at < (select min(created_at) from ops.rule_approval_receipt) then
      'legacy_admission: rule '||p_rule_id||' was activated at '||p_activated_at::text||
      ', before the approval-receipt system''s earliest receipt at '||
      (select min(created_at) from ops.rule_approval_receipt)::text||
      '; it predates the receipt cutover and carries none'
    else null
  end
$$;


--
-- Name: FUNCTION legacy_rule_admission_note(p_rule_id uuid, p_status text, p_activated_at timestamp with time zone); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.legacy_rule_admission_note(p_rule_id uuid, p_status text, p_activated_at timestamp with time zone) IS 'Shared legacy predicate for ops.retire_rule and ops.amend_rule_statement (0351). Non-null only for an ACTIVE rule with no ops.rule_approval_receipt row that also predates the receipt system''s own cutover (or predates a receipt system that has never issued any receipt at all). An active, receiptless rule that postdates the cutover returns null -- that is a real defect, not a historical fact, and both callers keep refusing it exactly as before.';


--
-- Name: list_doc_conversations(text, integer, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.list_doc_conversations(p_cursor text, p_limit integer, p_include_archived boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_limit integer; v_include_archived boolean;
        v_cursor jsonb; v_cursor_pinned timestamptz; v_cursor_updated timestamptz;
        v_cursor_id uuid; v_fetched jsonb; v_count integer; v_rows jsonb;
        v_more boolean; v_next text; v_last jsonb; v_visible integer;
begin
  -- The acting actor, resolved from the server-installed transaction context.
  -- A caller cannot name one: there is no parameter for it.
  v_actor := ops.portfolio_writer_actor_id();
  -- Clamped, never refused: a caller asking for 1000 gets 100 and an honest
  -- `more`. The idiom is 0520:181's.
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_include_archived := coalesce(p_include_archived, false);

  if p_cursor is not null then
    begin
      v_cursor := convert_from(decode(p_cursor, 'base64'), 'utf8')::jsonb;
      v_cursor_pinned := (v_cursor->>'p')::timestamptz;
      v_cursor_updated := (v_cursor->>'u')::timestamptz;
      v_cursor_id := (v_cursor->>'i')::uuid;
    exception when others then
      -- The token is the server's own; any failure to read one back is ONE
      -- refusal, never a partial page from a half-understood key.
      return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_cursor_invalid');
    end;
    if v_cursor_pinned is null or v_cursor_updated is null or v_cursor_id is null then
      return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_cursor_invalid');
    end if;
  end if;

  -- v_limit + 1 rows are fetched so `more` comes from the extra row rather
  -- than from a second count(*) over a set that is moving. The latest-turn
  -- lateral is applied to the subquery that has ALREADY ordered and cut the
  -- page, so its work is bounded by the page size (at most 101 backward index
  -- scans on doc_conversation_turn_cursor, 0520:59) and is independent of how
  -- many conversations or turns exist. Joining it before the limit would make
  -- the work proportional to the actor's whole visible set.
  select coalesce(jsonb_agg(to_jsonb(r) - 'ord' order by r.ord), '[]'::jsonb), count(*)
    into v_fetched, v_count
    from (
      select row_number() over (
               order by coalesce(c.pinned_at, '-infinity'::timestamptz) desc,
                        c.updated_at desc, c.id desc) as ord,
             c.id, c.title, c.visibility, c.pinned_at, c.archived_at, c.version,
             c.created_by_actor as created_by, c.updated_at as sort_updated,
             coalesce(t.sequence, -1) as latest_sequence, t.at as latest_turn_at
        from (select c.* from ops.doc_conversation c
               where (
       c.created_by_actor = v_actor
      or exists (select 1 from ops.doc_conversation_grant g
                  where g.conversation_id = c.id and g.grantee_actor = v_actor
                    and g.revoked_at is null)
                     )
                 and (v_include_archived or c.archived_at is null)
                 and (p_cursor is null or
                      row(coalesce(c.pinned_at, '-infinity'::timestamptz), c.updated_at, c.id)
                    < row(v_cursor_pinned, v_cursor_updated, v_cursor_id))
               order by coalesce(c.pinned_at, '-infinity'::timestamptz) desc,
                        c.updated_at desc, c.id desc
               limit v_limit + 1) c
        left join lateral (
          select t.sequence, t.at from ops.doc_conversation_turn t
           where t.conversation_id = c.id
           order by t.sequence desc limit 1) t on true
    ) r;

  v_more := v_count > v_limit;
  -- The page is the first v_limit of what was fetched; sort_updated is the
  -- cursor's own middle component and is stripped from what a caller sees.
  select coalesce(jsonb_agg(e - 'sort_updated' order by n), '[]'::jsonb) into v_rows
    from jsonb_array_elements(v_fetched) with ordinality as page(e, n)
   where n <= v_limit;
  -- next_cursor is the sort key of the LAST RETURNED row, and is null exactly
  -- when `more` is false.
  if v_more then
    v_last := v_fetched->(v_limit - 1);
    v_next := encode(convert_to(jsonb_build_object(
      'p', coalesce((v_last->>'pinned_at')::timestamptz, '-infinity'::timestamptz),
      'u', (v_last->>'sort_updated')::timestamptz,
      'i', (v_last->>'id')::uuid)::text, 'utf8'), 'base64');
  end if;

  -- 0520:210-214 UNCHANGED: the WHOLE visible set, archived rows included and
  -- paging ignored, so this door and the single-row read cannot disagree about
  -- the number the page prints. It does NOT count the filtered page.
  select count(*) into v_visible from ops.doc_conversation c
   where c.created_by_actor = v_actor
      or exists (select 1 from ops.doc_conversation_grant g
                  where g.conversation_id = c.id and g.grantee_actor = v_actor
                    and g.revoked_at is null);

  return jsonb_build_object('ok', true,
    'conversations', v_rows, 'more', v_more, 'next_cursor', v_next,
    'visible_conversation_count', v_visible);
end $$;


--
-- Name: FUNCTION list_doc_conversations(p_cursor text, p_limit integer, p_include_archived boolean); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.list_doc_conversations(p_cursor text, p_limit integer, p_include_archived boolean) IS 'WR-000115: the only door that answers which Doc conversations the acting actor may see. The actor is derived from the server-installed transaction context -- there is no parameter for it, no offset and no sort argument; the cursor is an opaque server-minted token carrying the whole three-part sort key.';


--
-- Name: list_tour_library(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.list_tour_library(p_tenant text, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('tours',coalesce(jsonb_agg(jsonb_build_object(
    'id',t.id,'tour_name',t.tour_name,'tour_status',t.tour_status,'route_version',t.route_version,
    'updated_at',t.updated_at,'property_count',(select count(*) from ops.tour_property_membership m where m.organization_tenant_id=t.organization_tenant_id and m.tour_id=t.id and m.route_version=t.route_version),
    'projection_count',(select count(*) from ops.tour_public_projection p where p.organization_tenant_id=t.organization_tenant_id and p.tour_id=t.id),
    'share_count',(select count(*) from ops.tour_share_grant g join ops.tour_public_projection p on p.organization_tenant_id=g.organization_tenant_id and p.id=g.projection_id where p.organization_tenant_id=t.organization_tenant_id and p.tour_id=t.id)
  ) order by t.updated_at desc,t.id),'[]'::jsonb))
  from ops.tour t where t.organization_tenant_id=p_tenant and nullif(btrim(p_actor_id),'') is not null;
$$;


--
-- Name: lock_cost_ledger_cell(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.lock_cost_ledger_cell(p_tree_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_version integer; v_digest text;
begin
  select ledger_version, state_digest into v_version, v_digest
    from ops.cost_ledger_cell where tree_ref = p_tree_ref for update;
  if v_version is null then
    return jsonb_build_object('ok', false, 'reason_id', 'cost_ledger_cell_absent',
      'tree_ref', p_tree_ref);
  end if;
  return jsonb_build_object('ok', true, 'tree_ref', p_tree_ref,
    'ledger_version', v_version, 'state_digest', v_digest);
end $$;


--
-- Name: FUNCTION lock_cost_ledger_cell(p_tree_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.lock_cost_ledger_cell(p_tree_ref text) IS 'WR-000111: takes the row lock the in-process ledger cell cannot. Held for the caller transaction; this is the serialization point the module names.';


--
-- Name: meeting_facts(uuid, bigint, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_facts(p_meeting uuid, p_after_seq bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype; v_limit integer;
begin
  select * into v_who from ops.meeting_mode_actor();
  select * into v_row from ops.meeting where id = p_meeting and organization_tenant_id = v_who.tenant;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  v_limit := least(greatest(coalesce(p_limit, 200), 1), 500);
  return jsonb_build_object('ok', true,
    'meeting', jsonb_build_object('id', v_row.id, 'title', v_row.title,
      'platform', v_row.platform,
      'native_identity', jsonb_build_object('source_system', v_row.source_system,
        'native_id', v_row.native_id, 'native_id_epoch', v_row.native_id_epoch),
      'mode_state', v_row.mode_state, 'recording', v_row.recording,
      'activation_intent', v_row.activation_intent,
      'started_by', (select slug from public.actor where id = v_row.started_by_actor),
      'started_at', v_row.started_at,
      'ended_by', (select slug from public.actor where id = v_row.ended_by_actor),
      'ended_at', v_row.ended_at, 'last_seq', v_row.last_seq),
    'lease', (select jsonb_build_object(
      'holder', (select slug from public.actor where id = l.holder_actor),
      'holder_instance', l.holder_instance, 'lease_epoch', l.lease_epoch,
      'expires_at', l.expires_at, 'released', l.released_at is not null,
      'live', l.released_at is null and l.expires_at > clock_timestamp())
      from ops.meeting_processing_lease l where l.meeting_id = p_meeting),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('note_number', n.note_number,
      'revision', n.revision, 'body', n.body,
      'author', (select slug from public.actor where id = n.author_actor),
      'author_instance', n.author_instance, 'at', n.created_at)
      order by n.note_number, n.revision)
      from ops.meeting_note n where n.meeting_id = p_meeting), '[]'::jsonb),
    'actions', coalesce((select jsonb_agg(ops.meeting_mode_action_view(p_meeting, a.action_number)
      || jsonb_build_object('revisions', (select jsonb_agg(jsonb_build_object(
          'revision', r.revision, 'summary', r.summary, 'command', r.command, 'basis', r.basis,
          'source', r.source, 'processing_epoch', r.processing_epoch,
          'proposed_by', (select slug from public.actor where id = r.proposed_by_actor),
          'proposed_by_instance', r.proposed_by_instance, 'at', r.created_at)
          order by r.revision)
        from ops.meeting_action_revision r
        where r.meeting_id = p_meeting and r.action_number = a.action_number))
      order by a.action_number)
      from ops.meeting_action a where a.meeting_id = p_meeting), '[]'::jsonb),
    'stream', coalesce((select jsonb_agg(jsonb_build_object('seq', s.seq, 'kind', s.kind,
      'actor', (select slug from public.actor where id = s.actor_id),
      'client_instance', s.client_instance, 'note_number', s.note_number,
      'action_number', s.action_number, 'revision', s.revision, 'lease_epoch', s.lease_epoch,
      'at', s.at) order by s.seq)
      from (select * from ops.meeting_stream where meeting_id = p_meeting
              and seq > coalesce(p_after_seq, 0) order by seq limit v_limit) s), '[]'::jsonb),
    'more', exists (select 1 from ops.meeting_stream where meeting_id = p_meeting
                     and seq > coalesce(p_after_seq, 0) + v_limit));
end $$;


--
-- Name: meeting_mode_accept(uuid, integer, integer, uuid, text, uuid, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_mode_accept(p_meeting uuid, p_action integer, p_revision integer, p_actor uuid, p_disposition text, p_assignee uuid, p_instance text, p_key uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_operation uuid := gen_random_uuid();
begin
  update ops.meeting_action
     set state = 'accepted', decided_revision = p_revision, decided_by_actor = p_actor,
         decided_at = clock_timestamp(), disposition = p_disposition, assignee_actor = p_assignee,
         operation_key = v_operation
   where meeting_id = p_meeting and action_number = p_action and state = 'proposed';
  if not found then
    raise exception 'meeting action %/% is not pending acceptance', p_meeting, p_action;
  end if;
  perform ops.meeting_mode_append(p_meeting, 'action_accepted', p_actor, p_instance, null,
    p_action, p_revision, null, p_key);
  return v_operation;
end $$;


--
-- Name: meeting_mode_action_view(uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_mode_action_view(p_meeting uuid, p_action integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select jsonb_build_object('action_number', a.action_number, 'state', a.state,
    'current_revision', a.current_revision, 'decided_revision', a.decided_revision,
    'decided_by', (select slug from public.actor where id = a.decided_by_actor),
    'disposition', a.disposition,
    'assignee', (select slug from public.actor where id = a.assignee_actor),
    'command', r.command,
    'dispatch', case when a.operation_key is null then null else jsonb_build_object(
      'verb', d.command->>'verb', 'args', d.command->'args',
      'idempotency_key', a.operation_key) end,
    'outcome', a.outcome)
  from ops.meeting_action a
  join ops.meeting_action_revision r
    on r.meeting_id = a.meeting_id and r.action_number = a.action_number
   and r.revision = a.current_revision
  left join ops.meeting_action_revision d
    on d.meeting_id = a.meeting_id and d.action_number = a.action_number
   and d.revision = a.decided_revision
  where a.meeting_id = p_meeting and a.action_number = p_action
$$;


--
-- Name: meeting_mode_actor(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_mode_actor(OUT actor_id uuid, OUT actor_slug text, OUT is_partner boolean, OUT tenant text) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  actor_id := ops.portfolio_writer_actor_id();
  select a.slug, a.kind = 'human' into actor_slug, is_partner from public.actor a where a.id = actor_id;
  tenant := nullif(current_setting('carr.organization_tenant_id', true), '');
end $$;


--
-- Name: meeting_mode_append(uuid, text, uuid, text, integer, integer, integer, bigint, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_mode_append(p_meeting uuid, p_kind text, p_actor uuid, p_instance text, p_note integer, p_action integer, p_revision integer, p_lease_epoch bigint, p_key uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_seq bigint;
begin
  if exists (select 1 from ops.meeting_stream where idempotency_key = p_key and kind = p_kind) then
    return null;
  end if;
  update ops.meeting set last_seq = last_seq + 1 where id = p_meeting returning last_seq into v_seq;
  insert into ops.meeting_stream(meeting_id, seq, kind, actor_id, client_instance, note_number,
    action_number, revision, lease_epoch, idempotency_key)
  values (p_meeting, v_seq, p_kind, p_actor, p_instance, p_note, p_action, p_revision,
    p_lease_epoch, p_key);
  return v_seq;
end $$;


--
-- Name: meeting_mode_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_mode_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
begin
  raise exception '% is append-only: % refused', tg_table_name, tg_op;
end $$;


--
-- Name: meeting_processing_lease_ttl(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.meeting_processing_lease_ttl() RETURNS interval
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select interval '120 seconds' $$;


--
-- Name: mint_canonical_ownership_merge_session(uuid, uuid, text, integer, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.mint_canonical_ownership_merge_session(p_subject_envelope_id uuid, p_decision_id uuid, p_head_sha text, p_pr_number integer, p_execution_host_ref text, p_expires_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare tenant text:=nullif(current_setting('carr.organization_tenant_id',true),'');
  actor_slug text:=nullif(current_setting('carr.acting_actor_slug',true),'');
  host text:=nullif(current_setting('carr.execution_host_id',true),'');
  e ops.engineering_execution_envelope%rowtype; w ops.work_request%rowtype;
  ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
  scope ops.source_merge_plan_scope%rowtype; receipt ops.engineering_slice_receipt%rowtype;
  ev public.event%rowtype; a public.actor%rowtype;
  rs ops.canonical_ownership_runtime_session%rowtype; m ops.canonical_ownership_merge_binding%rowtype;
  v_id uuid; capability uuid;
begin
  if not ops.canonical_ownership_runtime_principal_valid() then
    return jsonb_build_object('ok',false,'reason_id','ownership_merge_issuer_untrusted');
  end if;
  if tenant is null or actor_slug is null or host is null or p_execution_host_ref is distinct from host
     or host !~ '^cloudflare-workers:[A-Za-z0-9][A-Za-z0-9._:-]{2,95}$'
     or p_idempotency_key is null or coalesce(p_head_sha,'') !~ '^[0-9a-f]{40}$'
     or p_pr_number is null or p_pr_number<1 or p_expires_at is null or p_expires_at<=clock_timestamp() then
    return jsonb_build_object('ok',false,'reason_id','ownership_merge_input_invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-ownership-runtime:'||p_idempotency_key::text,0));
  select * into rs from ops.canonical_ownership_runtime_session where idempotency_key=p_idempotency_key;
  if found then
    select * into m from ops.canonical_ownership_merge_binding where runtime_binding_id=rs.id;
    if rs.phase<>'merge' or rs.issuer_principal is distinct from session_user
       or (rs.organization_tenant_id,rs.actor_slug,rs.subject_envelope_id,rs.execution_host_ref,rs.expires_at,
           m.decision_id,m.head_sha,m.pr_number) is distinct from
          (tenant,actor_slug,p_subject_envelope_id,host,p_expires_at,p_decision_id,p_head_sha,p_pr_number) then
      return jsonb_build_object('ok',false,'reason_id','ownership_merge_idempotency_conflict');
    end if;
    if not ops.canonical_ownership_merge_binding_valid(rs.id) then
      return jsonb_build_object('ok',false,'reason_id','ownership_merge_binding_stale');
    end if;
  else
    if not exists(select 1 from ops.canonical_ownership_issuer_generation where principal=session_user and state='active') then
      return jsonb_build_object('ok',false,'reason_id','ownership_issuer_draining');
    end if;
    select * into e from ops.engineering_execution_envelope where id=p_subject_envelope_id for share;
    select * into w from ops.work_request where id=e.work_request_id and organization_tenant_id=tenant for update;
    select * into ar from ops.sourced_work_request_plan_acceptance_receipt
     where work_request_id=w.id and result_version=w.version and plan_id=e.accepted_plan_id;
    select * into scope from ops.source_merge_plan_scope where work_request_id=w.id
      and accepted_plan_id=e.accepted_plan_id and acceptance_receipt_id=ar.id;
    select * into receipt from ops.engineering_slice_receipt slice_receipt where slice_receipt.envelope_id=e.id
      and outcome='claimed_complete' and slice_receipt.receipt#>>'{source_evidence,source_sha}'=p_head_sha;
    select * into ev from public.event where subject_type='decision' and verb='log-decision'
      and subject_id=p_decision_id order by recorded_at desc,id desc limit 1;
    select * into a from public.actor where slug=actor_slug and active;
    if e.id is null or w.id is null or ar.id is null or scope.id is null or receipt.id is null or a.id is null
       or ev.id is null or ev.organization_tenant_id is distinct from tenant
       or ev.sponsoring_human_slug is distinct from 'joe'
       or ev.authorization_class is distinct from 'human'
       or ev.new_value->>'title' is distinct from 'Gate A2 source-merge authority: '||w.ref
       or ev.new_value->'quote_absent' is distinct from 'false'::jsonb
       or ev.human_quote is distinct from 'I approve Gate A2 for '||w.ref||' PR #'||p_pr_number::text||' at '||p_head_sha||' for 120 minutes'
       or ev.occurred_at>clock_timestamp() or p_expires_at>ev.occurred_at+interval '120 minutes'
       or w.state<>'ready' or w.blocker_code is not null or e.state_version<>w.version
       or ops.engineering_contract_stale(null,ar.plan_hash,null)
       or exists(select 1 from ops.engineering_execution_envelope successor where successor.supersedes_envelope_id=e.id) then
      return jsonb_build_object('ok',false,'reason_id','ownership_merge_authority_invalid');
    end if;
    v_id:=gen_random_uuid(); capability:=gen_random_uuid();
    insert into ops.canonical_ownership_runtime_session(id,idempotency_key,organization_tenant_id,actor_id,actor_slug,
      work_request_id,accepted_plan_id,subject_envelope_id,attempt,runtime_session_ref,ownership_session_ref,
      execution_host_ref,issuer_principal,capability_token_hash,phase,expires_at)
    values(v_id,p_idempotency_key,tenant,a.id,a.slug,w.id,e.accepted_plan_id,e.id,split_part(receipt.attempt_id,':',2)::integer,
      'session:merge:'||v_id::text,'ownership:'||v_id::text,host,session_user,
      encode(public.digest(capability::text,'sha256'),'hex'),'merge',p_expires_at) returning * into rs;
    insert into ops.canonical_ownership_merge_binding(runtime_binding_id,decision_id,decision_event_id,
      receipt_id,scope_id,head_sha,pr_number,capability_token,decision_expires_at)
    values(v_id,p_decision_id,ev.id,receipt.id,scope.id,p_head_sha,p_pr_number,capability,ev.occurred_at+interval '120 minutes')
    returning * into m;
  end if;
  return jsonb_build_object('ok',true,'binding_id',rs.id,'phase','merge',
    'ownership_session_ref',rs.ownership_session_ref,'runtime_session_ref',rs.runtime_session_ref,
    'organization_tenant_id',rs.organization_tenant_id,'acting_actor_slug',rs.actor_slug,
    'execution_host_ref',rs.execution_host_ref,'expires_at',rs.expires_at,
    'merge_capability_token',m.capability_token,'decision_id',m.decision_id,
    'head_sha',m.head_sha,'pr_number',m.pr_number);
end $_$;


--
-- Name: mint_canonical_ownership_runtime_session(uuid, uuid, uuid, integer, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.mint_canonical_ownership_runtime_session(p_work_request_id uuid, p_accepted_plan_id uuid, p_subject_envelope_id uuid, p_attempt integer, p_runtime_session_ref text, p_execution_host_ref text, p_expires_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_tenant text:=nullif(btrim(current_setting('carr.organization_tenant_id',true)),'');
        v_actor_slug text:=nullif(btrim(current_setting('carr.acting_actor_slug',true)),'');
        v_runtime_context text:=nullif(btrim(current_setting('carr.receipt_session_ref',true)),'');
        v_host_context text:=nullif(btrim(current_setting('carr.execution_host_id',true)),'');
        v_capability text:=nullif(current_setting('carr.engineering_job_lease_token',true),'');
        v_actor public.actor%rowtype; v_work ops.work_request%rowtype;
        v_plan ops.sourced_work_request_plan%rowtype;
        v_env ops.engineering_execution_envelope%rowtype;
        v_job ops.job%rowtype; v_agent_session ops.capability_agent_session%rowtype;
        v_row ops.canonical_ownership_runtime_session%rowtype; v_id uuid;
begin
  if not ops.canonical_ownership_runtime_principal_valid() then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_principal_untrusted');
  end if;
  if v_tenant is null or v_actor_slug is null or v_runtime_context is null
     or v_host_context is null or v_capability is null then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_identity_missing');
  end if;
  if p_idempotency_key is null or p_attempt is null or p_attempt<1
     or coalesce(p_runtime_session_ref,'') !~ '^session:[a-z0-9][a-z0-9:._/-]{8,199}$'
     or coalesce(p_execution_host_ref,'') !~ '^cloudflare-workers:[A-Za-z0-9][A-Za-z0-9._:-]{2,95}$'
     or p_runtime_session_ref is distinct from v_runtime_context
     or p_execution_host_ref is distinct from v_host_context
     or p_expires_at is null or p_expires_at<=clock_timestamp()
     or p_expires_at>clock_timestamp()+interval '2 hours' then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_binding_invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('canonical-ownership-runtime:'||p_idempotency_key::text,0));
  select * into v_row from ops.canonical_ownership_runtime_session
   where idempotency_key=p_idempotency_key for share;
  if found then
    if (v_row.work_request_id,v_row.accepted_plan_id,v_row.subject_envelope_id,v_row.attempt,
        v_row.runtime_session_ref,v_row.execution_host_ref,v_row.expires_at)
       is distinct from
       (p_work_request_id,p_accepted_plan_id,p_subject_envelope_id,p_attempt,
        p_runtime_session_ref,p_execution_host_ref,p_expires_at) then
      return jsonb_build_object('ok',false,'reason_id','ownership_runtime_idempotency_conflict');
    end if;
    if v_row.phase<>'build' or v_row.organization_tenant_id is distinct from v_tenant
       or v_row.actor_slug is distinct from v_actor_slug
       or v_row.issuer_principal is distinct from session_user
       or v_row.capability_token_hash is distinct from encode(public.digest(v_capability,'sha256'),'hex')
       or v_row.state<>'active' or v_row.expires_at<=clock_timestamp()
       or not exists(select 1 from ops.engineering_execution_envelope e
         join ops.job j on j.id=e.job_id
         join ops.capability_agent_session s on s.id=e.agent_session_id
         where e.id=v_row.subject_envelope_id and j.attempt=v_row.attempt and j.state='running'
           and j.lease_token::text=v_capability and j.leased_until>clock_timestamp()
           and s.executor_actor_id=v_row.actor_id and s.state in ('claimed','in_progress')
           and s.lease_expires_at>clock_timestamp())
       or not exists(
         select 1 from ops.work_request w
         join ops.sourced_work_request_plan_acceptance_receipt ar
           on ar.work_request_id=w.id and ar.result_version=w.version
          where w.id=v_row.work_request_id and w.state='ready'
            and ar.plan_id=v_row.accepted_plan_id)
       or coalesce((select (ops.engineering_envelope_currentness(
            e.id,e.job_id)->>'eligible')::boolean
          from ops.engineering_execution_envelope e
         where e.id=v_row.subject_envelope_id),false) is not true then
      return jsonb_build_object('ok',false,'reason_id','ownership_runtime_binding_stale');
    end if;
    return jsonb_build_object('ok',true,'replayed',true,'binding_id',v_row.id,
      'ownership_session_ref',v_row.ownership_session_ref,
      'organization_tenant_id',v_row.organization_tenant_id,
      'acting_actor_slug',v_row.actor_slug,'execution_host_ref',v_row.execution_host_ref,
      'expires_at',v_row.expires_at);
  end if;
  if not exists(select 1 from ops.canonical_ownership_issuer_generation
      where principal=session_user and state='active') then
    return jsonb_build_object('ok',false,'reason_id','ownership_issuer_draining');
  end if;
  select * into v_actor from public.actor where slug=v_actor_slug and active for share;
  select * into v_work from ops.work_request where id=p_work_request_id for update;
  select * into v_plan from ops.sourced_work_request_plan where id=p_accepted_plan_id for share;
  select * into v_env from ops.engineering_execution_envelope where id=p_subject_envelope_id for share;
  select * into v_job from ops.job where id=v_env.job_id for share;
  select * into v_agent_session from ops.capability_agent_session
    where id=v_env.agent_session_id for share;
  if v_actor.id is null or v_work.id is null or v_plan.id is null or v_env.id is null
     or v_job.id is null or v_agent_session.id is null
     or v_work.organization_tenant_id is distinct from v_tenant
     or v_work.state<>'ready' or v_plan.work_request_id<>v_work.id
     or v_env.work_request_id<>v_work.id or v_env.accepted_plan_id<>v_plan.id
     or v_env.state_version<>v_work.version or v_env.expires_at<=clock_timestamp()
     or p_expires_at>v_env.expires_at
     or v_agent_session.work_request_id<>v_work.id
     or v_actor.id is distinct from v_agent_session.executor_actor_id
     or p_runtime_session_ref is distinct from 'session:'||v_agent_session.id::text
     or v_agent_session.state not in ('claimed','in_progress')
     or v_agent_session.lease_expires_at is null
     or v_agent_session.lease_expires_at<=clock_timestamp()
     or p_expires_at>v_agent_session.lease_expires_at
     or ops.engineering_contract_stale(v_plan.plan_ref,v_plan.plan_hash,null)
     or not exists (
       select 1 from ops.sourced_work_request_plan_acceptance_receipt ar
        where ar.work_request_id=v_work.id and ar.plan_id=v_plan.id
          and ar.plan_hash=v_plan.plan_hash and ar.result_version=v_work.version)
     or v_job.attempt<>p_attempt or v_job.state<>'running'
     or v_job.lease_token::text is distinct from v_capability
     or v_job.leased_until is null or v_job.leased_until<=clock_timestamp()
     or p_expires_at>v_job.leased_until
     or coalesce((ops.engineering_envelope_currentness(v_env.id,v_job.id)->>'eligible')::boolean,false)
        is not true then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_binding_stale');
  end if;
  update ops.canonical_ownership_runtime_session set state='expired'
    where subject_envelope_id=v_env.id and attempt=p_attempt and phase='build'
      and state='active' and expires_at<=clock_timestamp();
  if exists(select 1 from ops.canonical_ownership_runtime_session
      where subject_envelope_id=v_env.id and attempt=p_attempt and phase='build' and state='active') then
    return jsonb_build_object('ok',false,'reason_id','ownership_runtime_binding_already_exists');
  end if;
  v_id:=gen_random_uuid();
  insert into ops.canonical_ownership_runtime_session(
    id,idempotency_key,organization_tenant_id,actor_id,actor_slug,work_request_id,
    accepted_plan_id,subject_envelope_id,attempt,runtime_session_ref,
    ownership_session_ref,execution_host_ref,expires_at,issuer_principal,capability_token_hash)
  values(v_id,p_idempotency_key,v_tenant,v_actor.id,v_actor.slug,v_work.id,v_plan.id,
    v_env.id,p_attempt,p_runtime_session_ref,'ownership:'||v_id::text,
    p_execution_host_ref,p_expires_at,session_user,encode(public.digest(v_capability,'sha256'),'hex'))
  returning * into v_row;
  return jsonb_build_object('ok',true,'replayed',false,'binding_id',v_row.id,
    'ownership_session_ref',v_row.ownership_session_ref,
    'organization_tenant_id',v_row.organization_tenant_id,
    'acting_actor_slug',v_row.actor_slug,'execution_host_ref',v_row.execution_host_ref,
    'expires_at',v_row.expires_at);
end $_$;


--
-- Name: mint_notification(text, uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.mint_notification(p_event_source text, p_event_ref uuid, p_subject_type text, p_subject_ref text, p_reason text, p_severity text, p_deep_link text, p_dedupe_key text, p_recipient_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_recipient uuid; v_id uuid; v_prior uuid; v_pref ops.notification_preference%rowtype;
        v_local time; v_quiet boolean; v_source_exists boolean;
begin
  -- The 0230:68 idiom: a definer function granted to a routine bundle carries
  -- its own membership check.
  if not (pg_has_role(current_user, 'carr_writer', 'member')
       or pg_has_role(current_user, 'carr_authority', 'member')) then
    raise exception using errcode = '42501',
      message = 'minting a notification requires the writer or authority capability';
  end if;

  select (case p_event_source
            when 'event' then exists (select 1 from public.event where id = p_event_ref)
            when 'signal_event' then exists (select 1 from public.signal_event where id = p_event_ref)
            else false end)
    into v_source_exists;
  if not v_source_exists then
    raise exception 'notification_requires_an_existing_event'
      using errcode = '23503',
      detail = format('no %s row named %s', p_event_source, p_event_ref);
  end if;

  -- The retrieval_visibility_actor_id(text) body, inlined. ACTIVE HUMAN ONLY.
  select id into v_recipient from public.actor
   where slug = p_recipient_slug and kind = 'human' and active = true;
  if v_recipient is null then
    -- ops.notification.recipient_actor is NOT NULL and there is no honest value
    -- here, so this function writes NOTHING and RAISES NOTHING: a raise would
    -- abort the caller's transaction (25P02) and roll back the signal insert
    -- that is the actual product.
    return jsonb_build_object('ok', true, 'minted', false,
      'reason_id', 'no_sponsoring_partner');
  end if;

  insert into ops.notification(subject_type, subject_ref, event_ref, event_source,
    recipient_actor, reason, severity, deep_link, dedupe_key, correlation_id)
  values (p_subject_type, p_subject_ref, p_event_ref, p_event_source,
    v_recipient, p_reason, p_severity, p_deep_link, p_dedupe_key,
    nullif(current_setting('carr.correlation_id', true), ''))
  on conflict (recipient_actor, dedupe_key) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_prior from ops.notification
     where recipient_actor = v_recipient and dedupe_key = p_dedupe_key;
    return jsonb_build_object('ok', true, 'minted', false, 'deduplicated', true,
      'notification_id', v_prior, 'recipient_actor', v_recipient);
  end if;

  insert into ops.notification_delivery(notification_id, channel, state)
  values (v_id, 'in_app', 'pending');

  select * into v_pref from ops.notification_preference where actor = v_recipient;
  if coalesce(v_pref.device_opt_in, false) then
    v_quiet := false;
    if v_pref.quiet_hours_start is not null then
      v_local := (now() at time zone coalesce(v_pref.timezone, 'UTC'))::time;
      v_quiet := case
        when v_pref.quiet_hours_start <= v_pref.quiet_hours_end
          then v_local >= v_pref.quiet_hours_start and v_local < v_pref.quiet_hours_end
        else v_local >= v_pref.quiet_hours_start or v_local < v_pref.quiet_hours_end
      end;
    end if;
    -- SUPPRESSED IS RECORDED, never absent and never dropped.
    insert into ops.notification_delivery(notification_id, channel, state, settled_at)
    values (v_id, 'device',
            case when v_quiet then 'suppressed_quiet_hours' else 'pending' end,
            case when v_quiet then now() else null end);
  end if;

  return jsonb_build_object('ok', true, 'minted', true, 'notification_id', v_id,
    'recipient_actor', v_recipient, 'severity', p_severity, 'dedupe_key', p_dedupe_key);
end $$;


--
-- Name: FUNCTION mint_notification(p_event_source text, p_event_ref uuid, p_subject_type text, p_subject_ref text, p_reason text, p_severity text, p_deep_link text, p_dedupe_key text, p_recipient_slug text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.mint_notification(p_event_source text, p_event_ref uuid, p_subject_type text, p_subject_ref text, p_reason text, p_severity text, p_deep_link text, p_dedupe_key text, p_recipient_slug text) IS 'WR-000113: the only notification writer. Verifies the named source row exists, resolves the sponsoring partner slug to an ACTIVE HUMAN row, and returns a no-op rather than raising when there is none.';


--
-- Name: model_role_content_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_content_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare v_created xid8;
begin
  select created_xid into v_created from ops.model_role_revision where id = new.revision_id;
  if not found then
    raise exception 'model role content names an unknown revision' using errcode = '23503';
  end if;
  if v_created <> pg_current_xact_id() then
    raise exception 'model role revision % is sealed; its content was written by another transaction and cannot be added to',
      new.revision_id using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION model_role_content_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_content_guard() IS 'Refuses a skill, rule, evidence, capability, quality-floor or task-class row for a revision created by a different transaction, so a revision''s content is exactly what its own creating transaction wrote. It does not order two different revisions of one role; ops.model_role_lock() does that.';


--
-- Name: model_role_current_revision(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_current_revision(p_role_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_cur ops.model_role_current_pointer%rowtype;
  v_entry jsonb; v_acting_slug text;
begin
  select * into v_cur from ops.model_role_current_pointer
   where tenant = ops.model_role_tenant() and role_key = p_role_key
   order by pointer_no desc limit 1;
  -- NULL MEANS "NOBODY HAS SELECTED ONE", NEVER "THERE IS NO ROLE" AND NEVER A
  -- DEFAULT. No revision is current until a system-authority act makes one so,
  -- and nothing in this file seeds, assumes or hardcodes one.
  if not found then return null; end if;
  v_entry := ops.model_role_revision_readback(v_cur.revision_id);
  if v_entry is null then
    raise exception 'model role % current pointer names a revision that is not stored', p_role_key
      using errcode = '22000';
  end if;
  select slug into v_acting_slug from public.actor where id = v_cur.acting_actor_id;
  -- POINTER-PREFIXED ON PURPOSE. This entry already carries the ROLE'S OWN
  -- declared authority class at preimage.authority.authority_class, and that one
  -- can never be 'system_authority'. Merging the POINTER'S class in under the
  -- bare name `authority_class` put a top-level 'system_authority' on the
  -- readback of a rail whose central rule is that no role may declare it, which
  -- is a misread waiting to happen. The names say which one they are.
  return v_entry || jsonb_build_object(
    'pointer_id', v_cur.id,
    'pointer_no', v_cur.pointer_no,
    'expected_prior_revision_no', v_cur.expected_prior_revision_no,
    -- The authority LOGIN scope: which partner's authority connection the act
    -- was made on. Shared with that partner's sponsored agents by design.
    'set_by_partner_slug', v_cur.set_by_partner_slug,
    -- WHO ACTUALLY ACTED, reported separately and never folded into the line
    -- above. The writer and the guard both require these to be the same human
    -- partner, so on a stored row they agree -- and they are still reported as
    -- two facts, because they are two facts.
    'set_by_acting_actor_id', v_cur.acting_actor_id,
    'set_by_acting_actor_slug', v_acting_slug,
    'pointer_authority_class', v_cur.authority_class,
    'pointer_authority_grant_kind', v_cur.authority_grant_kind,
    'set_at', v_cur.set_at);
end;
$$;


--
-- Name: FUNCTION model_role_current_revision(p_role_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_current_revision(p_role_key text) IS 'The current revision of one role description, or null when no system-authority act has selected one. Null is an unanswered question, never a default role. The pointer''s own authority class is reported as pointer_authority_class so it cannot be misread as the role''s declared class, which is at preimage.authority.authority_class and can never be system_authority.';


--
-- Name: model_role_digest(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_digest(p_revision_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select ops.model_role_digest_of_preimage(ops.model_role_preimage(p_revision_id))
$$;


--
-- Name: FUNCTION model_role_digest(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_digest(p_revision_id uuid) IS 'The role_digest model-routing.v5.js''s defineRole computes, recomputed here from the persisted rows. No domain tag is wrapped around the preimage, because role-description.v1 declares none.';


--
-- Name: model_role_digest_of_preimage(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_digest_of_preimage(p_preimage jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(
    ops.portfolio_canonical_json(p_preimage), 'UTF8'), 'sha256'), 'hex')
$$;


--
-- Name: FUNCTION model_role_digest_of_preimage(p_preimage jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_digest_of_preimage(p_preimage jsonb) IS 'sha256 over the canonical JSON of one role-description.v1 preimage, with no domain tag. The only hashing step in this rail; ops.model_role_digest feeds it the preimage rebuilt from stored rows.';


--
-- Name: model_role_ecmascript_whitespace(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_ecmascript_whitespace() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  -- WRITTEN AS CODE POINTS, NEVER AS LITERAL CHARACTERS. Every one of these 25
  -- is either invisible or indistinguishable from a space on screen, so a
  -- literal form could be silently widened or narrowed by one keystroke and no
  -- reviewer would see it. Here the set is readable, countable and diffable.
  select string_agg(chr(cp), '' order by cp)
    from unnest(array[
      9,     -- U+0009 CHARACTER TABULATION
      10,    -- U+000A LINE FEED
      11,    -- U+000B LINE TABULATION
      12,    -- U+000C FORM FEED
      13,    -- U+000D CARRIAGE RETURN
      32,    -- U+0020 SPACE
      160,   -- U+00A0 NO-BREAK SPACE
      5760,  -- U+1680 OGHAM SPACE MARK
      8192, 8193, 8194, 8195, 8196, 8197,
      8198, 8199, 8200, 8201, 8202,
             -- U+2000..U+200A, the Space_Separator run
      8232,  -- U+2028 LINE SEPARATOR
      8233,  -- U+2029 PARAGRAPH SEPARATOR
      8239,  -- U+202F NARROW NO-BREAK SPACE
      8287,  -- U+205F MEDIUM MATHEMATICAL SPACE
      12288, -- U+3000 IDEOGRAPHIC SPACE
      65279  -- U+FEFF ZERO WIDTH NO-BREAK SPACE (BOM)
    ]) as cp
$$;


--
-- Name: FUNCTION model_role_ecmascript_whitespace(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_ecmascript_whitespace() IS 'The exact 25 code points ECMAScript String.prototype.trim strips, so this rail''s non-empty-text rule is the one model-routing.v5.js''s assertText applies rather than PostgreSQL''s space-only btrim.';


--
-- Name: model_role_is_nonempty_text(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_is_nonempty_text(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops'
    AS $$ select ops.model_role_trim(p_text) <> '' $$;


--
-- Name: FUNCTION model_role_is_nonempty_text(p_text text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_is_nonempty_text(p_text text) IS 'True when a value is non-empty under the ECMAScript trim rule model-routing.v5.js''s assertText applies. A tab, a newline, an NBSP, a BOM or a Unicode space -- alone or in combination -- is empty here exactly as it is there.';


--
-- Name: model_role_is_ref(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_is_ref(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$ select p_text ~ '^[a-z0-9][a-z0-9_.:/-]{0,127}$' $_$;


--
-- Name: model_role_keys(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_keys() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select array['architect', 'builder', 'operator', 'program_manager',
               'release_controller', 'reviewer']::text[]
$$;


--
-- Name: model_role_lock(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_lock(p_role_key text) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select pg_advisory_xact_lock(
    hashtextextended('doctorcre:v5:model-role:' || ops.model_role_tenant() || ':' || p_role_key, 0))
$$;


--
-- Name: FUNCTION model_role_lock(p_role_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_lock(p_role_key text) IS 'The single per-role transaction lock both role-store writers take first, so revision numbering and the current-pointer compare-and-swap are serial per role.';


--
-- Name: model_role_occupiable_authority_classes(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_occupiable_authority_classes() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select array['developer', 'ordinary_business', 'release_admin']::text[] $$;


--
-- Name: model_role_pointer_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_pointer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_rev ops.model_role_revision%rowtype;
  v_cur ops.model_role_current_pointer%rowtype;
  v_partner text; v_actor uuid; v_acting uuid; v_acting_slug text;
  v_err text; v_live text;
begin
  -- 1. THE AUTHORITY LOGIN SCOPE, DERIVED. ops.authority_actor_slug() reads
  --    session_user and raises for anything that is not an admitted partner
  --    authority principal. It is called rather than compared to a parameter,
  --    and the comparison below is against the S01 constant rather than against
  --    anything supplied.
  v_partner := ops.authority_actor_slug();
  if v_partner <> ops.model_role_system_authority_partner() then
    raise exception 'naming the current revision of a durable role is a retained system-authority act reserved to %; this authority session is %',
      ops.model_role_system_authority_partner(), v_partner using errcode = '42501';
  end if;
  if new.set_by_partner_slug <> v_partner then
    raise exception 'model role current pointer names a partner other than the authenticated authority session'
      using errcode = '42501';
  end if;
  select id into v_actor from public.actor
   where slug = v_partner and active and kind = 'human';
  if not found then
    raise exception 'partner authority session % has no active human actor', v_partner
      using errcode = '23503';
  end if;
  if new.set_by_actor_id <> v_actor then
    raise exception 'model role current pointer names an actor other than the authenticated partner'
      using errcode = '42501';
  end if;

  -- 1b. WHO ACTUALLY ACTED, DERIVED SEPARATELY AND REQUIRED TO BE THE PARTNER.
  --     The authority LOGIN is shared: partner-authority.js routes the sponsored
  --     agents codex, claude, joe-local and dell-local onto the partner's own
  --     carr_authority_<partner> connection, so step 1 alone answers 'joe' for an
  --     act a sponsored agent performed. ops.portfolio_writer_actor_id() resolves
  --     carr.acting_actor_slug on THIS transaction and, for a human actor, also
  --     requires the narrower carr.verified_human_actor_slug context to name the
  --     same slug -- so a sponsored agent cannot resolve to the partner here.
  v_acting := ops.portfolio_writer_actor_id();
  if v_acting <> v_actor then
    select slug into v_acting_slug from public.actor where id = v_acting;
    raise exception 'naming the current revision of a durable role is non-delegable: the % authority login is shared with that partner''s sponsored agents, and this transaction''s acting actor is %, not the partner''s own active human actor',
      v_partner, coalesce(v_acting_slug, v_acting::text) using errcode = '42501';
  end if;
  if new.acting_actor_id <> v_acting then
    raise exception 'model role current pointer names an acting actor other than the one this transaction established'
      using errcode = '42501';
  end if;
  if new.tenant <> ops.model_role_tenant() then
    raise exception 'model role current pointer tenant must be the one server tenant'
      using errcode = '42501';
  end if;

  -- 2. THE REVISION, LOADED. A pointer at a revision nobody recorded is not a
  --    pointer, and naming a uuid never brings one into existence.
  select * into v_rev from ops.model_role_revision where id = new.revision_id;
  if not found then
    raise exception 'model role current pointer names an unknown revision' using errcode = '23503';
  end if;
  if v_rev.role_key <> new.role_key or v_rev.tenant <> new.tenant then
    raise exception 'model role current pointer names a revision of a different role' using errcode = '23503';
  end if;
  if v_rev.revision_no <> new.revision_no then
    raise exception 'model role current pointer names revision % of a row that is revision %',
      new.revision_no, v_rev.revision_no using errcode = '22023';
  end if;

  -- 3. THE WHOLE CONTRACT, RECHECKED FROM THE STORED CONTENT. Not the writer's
  --    word, and not the row's own claim: the shape is re-derived (including the
  --    kernel's non-empty-text rule) and the digest is re-hashed from the
  --    persisted rows. A revision that a direct writer somehow poisoned can
  --    therefore never become current, whatever its stored digest says.
  v_err := ops.model_role_structure_error(new.revision_id);
  if v_err is not null then
    raise exception 'a revision that is not a complete role description cannot become current: %', v_err
      using errcode = '22023';
  end if;
  v_live := ops.model_role_digest(new.revision_id);
  if new.role_digest <> v_live or v_rev.role_digest <> v_live then
    raise exception 'model role current pointer digest is stale: the stored rows produce %', v_live
      using errcode = '22000';
  end if;

  -- 4. THE COMPARE-AND-SWAP, RE-EVALUATED under the lock the writer already
  --    holds. Creation and replacement are two shapes and neither is inferred
  --    from a null: pointer_no fixes which one this row claims to be, and the
  --    ledger decides whether that claim is true.
  select * into v_cur from ops.model_role_current_pointer
   where tenant = new.tenant and role_key = new.role_key
   order by pointer_no desc limit 1;
  if not found then
    if new.pointer_no <> 1 or new.expected_prior_revision_no is not null then
      raise exception 'model role % has no current revision; the first pointer is number 1 with no prior expectation',
        new.role_key using errcode = '40001';
    end if;
  else
    if new.pointer_no <> v_cur.pointer_no + 1 then
      raise exception 'model role % current pointer is number %; the next is %, not %',
        new.role_key, v_cur.pointer_no, v_cur.pointer_no + 1, new.pointer_no using errcode = '40001';
    end if;
    if new.expected_prior_revision_no is null then
      raise exception 'model role % already has current revision %; a creation compare-and-swap cannot move it',
        new.role_key, v_cur.revision_no using errcode = '40001';
    end if;
    if new.expected_prior_revision_no <> v_cur.revision_no then
      raise exception 'model role % current revision is %, not the expected %',
        new.role_key, v_cur.revision_no, new.expected_prior_revision_no using errcode = '40001';
    end if;
    if v_cur.revision_no = new.revision_no then
      raise exception 'revision % of model role % is already current', new.revision_no, new.role_key
        using errcode = '42710';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION model_role_pointer_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_pointer_guard() IS 'Refuses a current-pointer change unless the authority login is the retained system-authority partner''s AND this transaction''s server-established acting actor is that partner''s own active human actor, so a sponsored agent on the shared partner login is refused rather than recorded as the partner. Also refuses an unknown revision, a revision of another role, stored content that no longer rebuilds its own digest or is not a complete role description, and a compare-and-swap that does not match the ledger. It grants nothing: it records which authority was exercised and who exercised it.';


--
-- Name: model_role_preimage(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_preimage(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v ops.model_role_revision%rowtype;
begin
  select * into v from ops.model_role_revision where id = p_revision_id;
  if not found then
    raise exception 'model role revision % does not exist', p_revision_id using errcode = '23503';
  end if;
  -- Exactly the twelve content fields of role-description.v1. schema_version and
  -- tenant are EMITTED, never stored per revision: taking either from a row would
  -- make a fixed constant something a row could move.
  return jsonb_build_object(
    'schema_version', ops.model_role_schema_version(),
    'tenant', ops.model_role_tenant(),
    'role_key', v.role_key,
    'title', v.title,
    'mission', v.mission,
    'skills', ops.model_role_text_array(p_revision_id, 'skills'),
    'rules', ops.model_role_text_array(p_revision_id, 'rules'),
    'authority', jsonb_build_object(
      'authority_class', v.authority_class,
      'capability_refs', ops.model_role_ref_array(p_revision_id, 'capability_refs')),
    'evidence_requirements', ops.model_role_text_array(p_revision_id, 'evidence_requirements'),
    'quality_floor_refs', ops.model_role_ref_array(p_revision_id, 'quality_floor_refs'),
    'minimum_strength_ref', v.minimum_strength_ref,
    'task_classes', ops.model_role_ref_array(p_revision_id, 'task_classes'));
end;
$$;


--
-- Name: FUNCTION model_role_preimage(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_preimage(p_revision_id uuid) IS 'The twelve role-description.v1 content fields of one revision, rebuilt from its persisted rows with schema_version and tenant emitted rather than stored. These are the exact bytes defineRole hashes.';


--
-- Name: model_role_readback(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_readback(p_role_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_history jsonb := '[]'::jsonb;
  v_pointers jsonb := '[]'::jsonb;
  r record;
begin
  if not (p_role_key = any (ops.model_role_keys())) then
    raise exception '% is not one of the settled v5 roles', p_role_key using errcode = '22023';
  end if;
  for r in select id from ops.model_role_revision
            where tenant = ops.model_role_tenant() and role_key = p_role_key
            order by revision_no
  loop
    v_history := v_history || jsonb_build_array(ops.model_role_revision_readback(r.id));
  end loop;
  for r in select p.*, a.slug as acting_slug
             from ops.model_role_current_pointer p
             left join public.actor a on a.id = p.acting_actor_id
            where p.tenant = ops.model_role_tenant() and p.role_key = p_role_key
            order by p.pointer_no
  loop
    v_pointers := v_pointers || jsonb_build_array(jsonb_build_object(
      'pointer_no', r.pointer_no,
      'revision_no', r.revision_no,
      'role_digest', r.role_digest,
      'expected_prior_revision_no', r.expected_prior_revision_no,
      'set_by_partner_slug', r.set_by_partner_slug,
      'set_by_acting_actor_id', r.acting_actor_id,
      'set_by_acting_actor_slug', r.acting_slug,
      'pointer_authority_class', r.authority_class,
      'pointer_authority_grant_kind', r.authority_grant_kind,
      'set_at', r.set_at));
  end loop;
  return jsonb_build_object(
    'schema_version', ops.model_role_readback_schema_version(),
    'role_schema_version', ops.model_role_schema_version(),
    'tenant', ops.model_role_tenant(),
    'role_key', p_role_key,
    'current', ops.model_role_current_revision(p_role_key),
    'history', v_history,
    'pointer_history', v_pointers,
    'integrity', 'recomputed_from_committed_rows',
    -- The exact scope of what a read here establishes. It is re-derivation from
    -- committed rows; it is not a signature, not a capability token, and not
    -- evidence that any model is qualified for this role or occupies it.
    'signed', false,
    'capability_token_issued', false,
    'confers_authority', false,
    'occupant_bound', false,
    'measured_qualification_bound', false);
end;
$$;


--
-- Name: FUNCTION model_role_readback(p_role_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_readback(p_role_key text) IS 'One role description''s whole durable state: every revision rebuilt from its rows with both digests and the contract version it was stored under, the current pointer, and the ledger of what has been current with both the authority login scope and the actual acting principal on every entry. It establishes re-derivation from committed rows and says so; it is not a signature and not a qualification.';


--
-- Name: model_role_readback_schema_version(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_readback_schema_version() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre-v5-model-role-readback.v1'::text $$;


--
-- Name: model_role_record_revision(text, integer, uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_record_revision(p_role_key text, p_revision_no integer, p_idempotency_key uuid, p_role_digest text, p_scalars jsonb, p_texts jsonb, p_refs jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  v_id uuid; v_existing ops.model_role_revision%rowtype;
  v_actor uuid; v_err text; v_live text; t jsonb; r jsonb;
begin
  perform ops.model_role_lock(p_role_key);
  v_actor := ops.portfolio_writer_actor_id();

  select * into v_existing from ops.model_role_revision where idempotency_key = p_idempotency_key;
  if found then
    -- THE REPLAY IS BOUND TO THE EXACT CONTENT, ROLE, VERSION AND WRITER. A key
    -- reused for anything else is a different request wearing the same name, and
    -- the writer comparison is what stops one actor's key returning a row
    -- another actor authored.
    if v_existing.role_key is distinct from p_role_key
       or v_existing.revision_no is distinct from p_revision_no
       or v_existing.role_digest is distinct from p_role_digest
       or v_existing.recorded_by_actor_id is distinct from v_actor then
      raise exception 'model role idempotency key % was already used for a different revision, role, version or writer',
        p_idempotency_key using errcode = '23505';
    end if;
    return v_existing.id;
  end if;

  if exists (select 1 from ops.model_role_revision
              where tenant = ops.model_role_tenant() and role_key = p_role_key
                and role_digest = p_role_digest) then
    raise exception 'model role % already has a revision with these exact bytes; a revision that records no change is not history',
      p_role_key using errcode = '23505';
  end if;

  insert into ops.model_role_revision(
    tenant, role_key, revision_no, idempotency_key, schema_version, role_digest,
    title, mission, minimum_strength_ref, authority_class, recorded_by_actor_id)
  values (ops.model_role_tenant(), p_role_key, p_revision_no, p_idempotency_key,
    ops.model_role_schema_version(), p_role_digest,
    p_scalars ->> 'title', p_scalars ->> 'mission',
    p_scalars ->> 'minimum_strength_ref', p_scalars ->> 'authority_class', v_actor)
  returning id into v_id;

  for t in select value from jsonb_array_elements(p_texts) loop
    insert into ops.model_role_revision_text(revision_id, field, ordinal, value)
    values (v_id, t ->> 'field', (t ->> 'ordinal')::integer, t ->> 'value');
  end loop;

  for r in select value from jsonb_array_elements(p_refs) loop
    insert into ops.model_role_revision_ref(revision_id, field, ordinal, value)
    values (v_id, r ->> 'field', (r ->> 'ordinal')::integer, r ->> 'value');
  end loop;

  -- THE COMMIT CHECK, from the stored content rather than from the parameters.
  -- Shape first, then the digest binding, so a caller learns which one failed.
  v_err := ops.model_role_structure_error(v_id);
  if v_err is not null then
    raise exception 'model role revision is not a complete role description: %', v_err
      using errcode = '22023';
  end if;
  v_live := ops.model_role_digest(v_id);
  if v_live is distinct from p_role_digest then
    raise exception 'model role digest is stale: the stored rows produce %, not %', v_live, p_role_digest
      using errcode = '22000';
  end if;
  return v_id;
end;
$$;


--
-- Name: FUNCTION model_role_record_revision(p_role_key text, p_revision_no integer, p_idempotency_key uuid, p_role_digest text, p_scalars jsonb, p_texts jsonb, p_refs jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_record_revision(p_role_key text, p_revision_no integer, p_idempotency_key uuid, p_role_digest text, p_scalars jsonb, p_texts jsonb, p_refs jsonb) IS 'The only way to record a revision of a durable role description. The author is derived from the server-established writer context and is not a parameter; the supplied digest is compared against one recomputed from the stored rows before the transaction may commit. The revision is inert and does not become current.';


--
-- Name: model_role_ref_array(uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_ref_array(p_revision_id uuid, p_field text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(r.value) order by r.value collate "C"), '[]'::jsonb)
    from ops.model_role_revision_ref r
   where r.revision_id = p_revision_id and r.field = p_field
$$;


--
-- Name: FUNCTION model_role_ref_array(p_revision_id uuid, p_field text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_ref_array(p_revision_id uuid, p_field text) IS 'One reference set of a role revision, sorted the way defineRole sorts it rather than in the order its rows were written.';


--
-- Name: model_role_revision_entry_schema_version(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_revision_entry_schema_version() RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ select 'doctorcre-v5-model-role-revision-entry.v1'::text $$;


--
-- Name: model_role_revision_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_prev integer;
begin
  -- THE AUTHOR IS THE SERVER-ESTABLISHED WRITER, never a payload field.
  if new.recorded_by_actor_id <> ops.portfolio_writer_actor_id() then
    raise exception 'model role revision actor does not match the authenticated writer context'
      using errcode = '42501';
  end if;
  if new.tenant <> ops.model_role_tenant() then
    raise exception 'model role revision tenant must be the one server tenant' using errcode = '42501';
  end if;
  if new.schema_version <> ops.model_role_schema_version() then
    raise exception 'model role revision must be a %', ops.model_role_schema_version()
      using errcode = '22023';
  end if;
  -- Refused BY NAME as well as by the column list, so the prohibition reads as a
  -- decision rather than as an omission from an enum.
  if new.authority_class = 'system_authority' then
    raise exception 'a durable role occupied by a replaceable model may not declare system authority: S01 retains that class and makes it non-delegable'
      using errcode = '42501';
  end if;
  -- The kernel's non-empty rule, restated at the row the constraint also covers,
  -- so the refusal a caller sees names the contract rather than a constraint id.
  if not ops.model_role_is_nonempty_text(new.title)
     or not ops.model_role_is_nonempty_text(new.mission) then
    raise exception 'a role title and mission must be non-empty under the ECMAScript trim rule defineRole applies; whitespace alone -- tab, newline, NBSP, BOM or a Unicode space -- is empty'
      using errcode = '22023';
  end if;
  -- VERSIONS ARE CONTIGUOUS. A hole in the history is a revision somebody wrote
  -- and lost, and it makes "the version before this one" unanswerable.
  select coalesce(max(revision_no), 0) into v_prev from ops.model_role_revision
   where tenant = new.tenant and role_key = new.role_key;
  if new.revision_no <> v_prev + 1 then
    raise exception 'model role % is at revision %; the next revision is %, not %',
      new.role_key, v_prev, v_prev + 1, new.revision_no using errcode = '23505';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION model_role_revision_guard(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_revision_guard() IS 'Binds a role revision to the server-established writer and the one tenant, refuses a system-authority role class by name, refuses an empty title or mission under the kernel''s own trim rule, and refuses a non-contiguous version.';


--
-- Name: model_role_revision_readback(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_role_revision_readback(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v ops.model_role_revision%rowtype;
begin
  select * into v from ops.model_role_revision where id = p_revision_id;
  if not found then return null; end if;
  return jsonb_build_object(
    'schema_version', ops.model_role_revision_entry_schema_version(),
    'revision_id', v.id,
    'role_key', v.role_key,
    'revision_no', v.revision_no,
    -- THE ROLE CONTRACT VERSION THIS REVISION WAS STORED UNDER, reported rather
    -- than assumed. A CHECK pins it to role-description.v1 today; reporting it
    -- is what lets a future versioned reader refuse a revision it cannot
    -- revalidate BY NAME instead of failing somewhere inside a rebuild -- and
    -- what makes "we need a versioned reader" the remedy rather than "we need to
    -- rewrite the rows", which append-only history forbids.
    'role_schema_version', v.schema_version,
    'role_digest', v.role_digest,
    -- RECOMPUTED, beside the stored claim rather than instead of it. The module
    -- re-derives a third value from the preimage and refuses unless all three
    -- agree, which is what makes a read a statement about bytes.
    'recomputed_role_digest', ops.model_role_digest(v.id),
    'structure_error', ops.model_role_structure_error(v.id),
    'recorded_at', v.recorded_at,
    'preimage', ops.model_role_preimage(v.id),
    -- Said on every read, because the whole risk here is that somebody reads a
    -- durable job description as a grant, an occupancy or a measurement.
    'confers_authority', false,
    'occupant_bound', false,
    'measured_qualification_bound', false,
    'integrity', 'recomputed_from_committed_rows');
end;
$$;


--
-- Name: FUNCTION model_role_revision_readback(p_revision_id uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_revision_readback(p_revision_id uuid) IS 'One stored role revision: its preimage rebuilt from the rows, the role contract version it was stored under, the digest recorded at write and the digest recomputed now, its structural validity, and the database''s own custody time. Null when no such revision exists.';


