--

CREATE FUNCTION ops.model_role_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'DoctorCRE v5 model role rows are append-only; % on %.% is refused',
    tg_op, tg_table_schema, tg_table_name using errcode = '42501';
end;
$$;


--
-- Name: FUNCTION model_role_rows_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_rows_immutable() IS 'Refuses every update, delete and truncate on the DoctorCRE v5 model role relations. A recorded revision is not edited, and a superseded current pointer is not erased.';


