    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops'
    AS $$ select btrim(p_text, ops.model_role_ecmascript_whitespace()) $$;


--
-- Name: FUNCTION model_role_trim(p_text text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.model_role_trim(p_text text) IS 'One value trimmed the way ECMAScript String.prototype.trim trims it. Used only to decide emptiness; no stored value is ever rewritten, because defineRole hashes the value verbatim and a trimmed store would hash to something no proposer computed.';


--
-- Name: nightly_availability_canary_live_job(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.nightly_availability_canary_live_job(p_job_id uuid, p_lease uuid) RETURNS ops.job
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; k text;
begin
 if session_user<>'carr_jobs' then raise exception using errcode='42501',message='nightly availability canary requires carr_jobs identity'; end if;
 select * into j from ops.job where id=p_job_id for update;
 select execution_kind into k from ops.job_definition where key=j.definition_key and version=j.definition_version;
 if not found or j.state<>'running' or j.lease_token<>p_lease or j.leased_until<now() then raise exception using errcode='55000',message='nightly availability canary requires current live job lease'; end if;
 if j.definition_key<>'nightly-record-layer' or j.definition_version<>3 or j.mode<>'canary' or k<>'deterministic' then raise exception using errcode='22023',message='job is not nightly-record-layer v3 deterministic canary'; end if;
 return j;
end $$;


--
-- Name: notification_feed_facts(timestamp with time zone, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.notification_feed_facts(p_after timestamp with time zone, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_limit integer; v_rows jsonb; v_unread integer;
begin
  if not (pg_has_role(current_user, 'carr_writer', 'member')
       or pg_has_role(current_user, 'carr_authority', 'member')) then
    raise exception using errcode = '42501',
      message = 'reading the notification feed requires the writer or authority capability';
  end if;
  v_actor := ops.portfolio_writer_actor_id();
  v_limit := least(greatest(coalesce(p_limit, 50), 1), 200);

  select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at desc), '[]'::jsonb) into v_rows
    from (
      select n.id, n.severity, n.reason, n.subject_type, n.subject_ref, n.deep_link,
             n.created_at, r.read_at,
             coalesce((select jsonb_agg(jsonb_build_object('channel', d.channel, 'state', d.state)
                                        order by d.channel)
                         from ops.notification_delivery d where d.notification_id = n.id),
                      '[]'::jsonb) as delivery
        from ops.notification n
        left join ops.notification_read r
          on r.notification_id = n.id and r.recipient_actor = n.recipient_actor
       where n.recipient_actor = v_actor
         and (p_after is null or n.created_at > p_after)
       order by n.created_at desc limit v_limit) f;

  select count(*) into v_unread from ops.notification n
   where n.recipient_actor = v_actor
     and not exists (select 1 from ops.notification_read r
                      where r.notification_id = n.id and r.recipient_actor = v_actor);

  return jsonb_build_object('ok', true, 'unread_count', v_unread, 'notifications', v_rows);
end $$;


--
-- Name: FUNCTION notification_feed_facts(p_after timestamp with time zone, p_limit integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.notification_feed_facts(p_after timestamp with time zone, p_limit integer) IS 'WR-000113: resolves the caller''s own actor internally and returns only that actor''s notifications. There is no argument for a recipient.';


--
-- Name: notification_preference_facts(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.notification_preference_facts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_pref ops.notification_preference%rowtype;
        v_local time; v_quiet boolean;
begin
  -- The 0230:68 idiom: a definer function granted to a routine bundle carries
  -- its own membership check, so a mis-grant is caught rather than silently
  -- widening the door.
  if not (pg_has_role(current_user, 'carr_writer', 'member')
       or pg_has_role(current_user, 'carr_authority', 'member')) then
    raise exception using errcode = '42501',
      message = 'reading notification preferences requires the writer or authority capability';
  end if;
  v_actor := ops.portfolio_writer_actor_id();

  select * into v_pref from ops.notification_preference where actor = v_actor;

  v_quiet := false;
  if v_pref.quiet_hours_start is not null then
    v_local := (now() at time zone coalesce(v_pref.timezone, 'UTC'))::time;
    v_quiet := case
      when v_pref.quiet_hours_start <= v_pref.quiet_hours_end
        then v_local >= v_pref.quiet_hours_start and v_local < v_pref.quiet_hours_end
      else v_local >= v_pref.quiet_hours_start or v_local < v_pref.quiet_hours_end
    end;
  end if;

  return jsonb_build_object(
    'ok', true,
    'exists', v_pref.actor is not null,
    'device_opt_in', coalesce(v_pref.device_opt_in, false),
    'quiet_hours_start', v_pref.quiet_hours_start,
    'quiet_hours_end', v_pref.quiet_hours_end,
    'timezone', coalesce(v_pref.timezone, 'UTC'),
    'version', coalesce(v_pref.version, 1),
    'quiet_now', v_quiet);
end $$;


--
-- Name: FUNCTION notification_preference_facts(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.notification_preference_facts() IS 'WR-000116: reads the acting actor''s own notification preferences and whether quiet hours cover this instant. ZERO arguments: the actor is resolved inside the body. A missing row returns the table''s declared defaults and inserts nothing.';


