--
-- Name: portfolio_structure_frozen_after_acceptance(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.portfolio_structure_frozen_after_acceptance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if exists (select 1 from ops.portfolio_revision_acceptance_receipt
              where portfolio_revision_id = new.portfolio_revision_id) then
    raise exception 'portfolio revision % is accepted; its structure is closed to further % rows',
      new.portfolio_revision_id, tg_table_name;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION portfolio_structure_frozen_after_acceptance(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.portfolio_structure_frozen_after_acceptance() IS 'Refuses a child, node or edge insert against a revision that already carries an acceptance receipt, so no structural row can appear outside the hash the partner accepted.';


--
-- Name: portfolio_writer_actor_id(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.portfolio_writer_actor_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_slug text; v_id uuid; v_human boolean; v_verified text;
begin
  v_slug := nullif(current_setting('carr.acting_actor_slug', true), '');
  if v_slug is null then
    raise exception 'portfolio writes require the server-established actor context; none is set on this transaction';
  end if;
  select id, kind = 'human' into v_id, v_human from public.actor where slug = v_slug and active;
  if not found then
    raise exception 'acting actor % is not an active actor', v_slug;
  end if;
  -- Writing AS A HUMAN needs the second, narrower context the server sets only
  -- for a verified partner. Without it a sponsored agent could name a partner
  -- as the author of its own work.
  if v_human then
    v_verified := nullif(current_setting('carr.verified_human_actor_slug', true), '');
    if v_verified is distinct from v_slug then
      raise exception 'writing as human actor % requires the verified-partner context, which names %',
        v_slug, coalesce(v_verified, '(none)');
    end if;
  end if;
  return v_id;
end;
$$;


--
-- Name: FUNCTION portfolio_writer_actor_id(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.portfolio_writer_actor_id() IS 'The active actor the server established for this transaction through carr.acting_actor_slug. Portfolio proposal and review derive authorship from it instead of accepting an actor in the payload.';


--
-- Name: prepare_staging_deployment_attempt(uuid, uuid, text, text, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_deployment_attempt(p_idempotency_key uuid, p_correlation_id uuid, p_release_key text, p_prior_release_key text, p_recovery_attempt_id uuid, p_recovery_step text, p_git_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  observed_release ops.release%rowtype;
  attempt_uuid uuid;
  expected_tag text;
  migration_hash text;
  migration_count integer;
  receipt ops.staging_release_readback_receipt%rowtype;
begin
  if session_user<>'carr_jobs' then
    raise exception 'staging attempt writer requires the carr_jobs session';
  end if;
  if p_idempotency_key is null or p_correlation_id is null
     or coalesce(p_release_key,'')='' or coalesce(p_git_sha,'') !~ '^[0-9a-f]{40}$'
     or p_recovery_step not in ('standalone','current_before','prior','current_after') then
    raise exception 'invalid typed staging attempt input';
  end if;
  if (p_recovery_step='standalone' and (p_recovery_attempt_id is not null or p_prior_release_key is not null))
     or (p_recovery_step<>'standalone' and
         (p_recovery_attempt_id is null or p_prior_release_key is null
          or p_correlation_id<>p_recovery_attempt_id)) then
    raise exception 'recovery fields do not match the requested staging step';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  if p_recovery_attempt_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_recovery_attempt_id::text,202));
  end if;
  select * into current_release from ops.release where release_key=p_release_key;
  if not found or current_release.service_id is null then
    raise exception 'staging attempt release does not exist';
  end if;
  if coalesce(cardinality(current_release.migration_set),0)<=0
     or coalesce(current_release.schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(current_release.schema_applied_count,0)<=0
     or coalesce(current_release.schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'release does not declare an exact migration/schema set';
  end if;
  migration_hash:=ops.program5_migration_set_sha256(current_release.migration_set);
  migration_count:=cardinality(current_release.migration_set);
  if p_recovery_step='standalone' then
    if current_release.environment not in ('staging','production')
       or current_release.state not in ('candidate','approved','deploying','verifying') then
      raise exception 'standalone staging attempt release is not deployable';
    end if;
    observed_release:=current_release;
  else
    if current_release.environment<>'production' or current_release.state<>'candidate'
       or current_release.recovery_strategy is distinct from 'rollback'
       or coalesce(current_release.rollback_plan_ref,'')=''
       or coalesce(current_release.plan_hash,'')='' then
      raise exception 'current release is not a rollback-ready Production candidate';
    end if;
    select * into prior_release from ops.release where release_key=p_prior_release_key;
    if not found or prior_release.id=current_release.id
       or prior_release.environment<>'production' or prior_release.state<>'complete'
       or prior_release.service_id<>current_release.service_id then
      raise exception 'prior release is not a distinct completed Production release';
    end if;
    if not exists (
      select 1 from ops.deployment d where d.release_id=prior_release.id
       and d.service_id=current_release.service_id and d.environment='production'
       and d.state='complete' and d.read_back_at is not null
       and d.git_sha=prior_release.git_sha and d.provider=prior_release.provider
       and d.provider_version_id=prior_release.provider_version_id) then
      raise exception 'prior release has no exact completed Production readback';
    end if;
    observed_release:=case when p_recovery_step='prior' then prior_release else current_release end;
  end if;
  if p_git_sha<>observed_release.git_sha then
    raise exception 'staging attempt SHA does not match the release required for this step';
  end if;
  expected_tag:='carr-staging-'||replace(p_idempotency_key::text,'-','');
  select * into existing from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if found then
    if (existing.correlation_id,existing.recovery_attempt_id,existing.recovery_step,
        existing.rehearsal_release_id,existing.observed_release_id,existing.prior_release_id,
        existing.service_id,existing.git_sha,existing.expected_provider_tag,
        existing.declared_migration_set_sha256,existing.declared_migration_count,
        existing.declared_schema_highest_migration,
        existing.declared_schema_applied_count,existing.declared_schema_ledger_sha256) is distinct from
       (p_correlation_id,p_recovery_attempt_id,p_recovery_step,current_release.id,
        observed_release.id,case when p_recovery_step='standalone' then null else prior_release.id end,
        current_release.service_id,p_git_sha,expected_tag,migration_hash,migration_count,
        current_release.schema_highest_migration,current_release.schema_applied_count,
        current_release.schema_ledger_sha256) then
      raise exception 'staging attempt idempotency key was reused with changed input';
    end if;
    select * into receipt from ops.staging_release_readback_receipt
      where deployment_attempt_id=existing.id;
    return jsonb_build_object('attempt_id',existing.id,
      'expected_provider_tag',existing.expected_provider_tag,
      'state',case when receipt.id is null then 'prepared' else 'observed' end,
      'deploy_claimed',exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=existing.id),
      'provider_version_id',receipt.provider_version_id,'receipt_ref',receipt.evidence_ref,
      'replayed',true);
  end if;
  insert into ops.staging_deployment_attempt(
    idempotency_key,recovery_attempt_id,recovery_step,correlation_id,
    rehearsal_release_id,observed_release_id,prior_release_id,service_id,
    environment,git_sha,provider,expected_provider_tag,
    declared_migration_set_sha256,declared_migration_count,
    declared_schema_highest_migration,declared_schema_applied_count,
    declared_schema_ledger_sha256,writer_session_user)
  values(p_idempotency_key,p_recovery_attempt_id,p_recovery_step,p_correlation_id,
    current_release.id,observed_release.id,
    case when p_recovery_step='standalone' then null else prior_release.id end,
    current_release.service_id,'staging',p_git_sha,'cloudflare-workers',expected_tag,
    migration_hash,migration_count,current_release.schema_highest_migration,
    current_release.schema_applied_count,current_release.schema_ledger_sha256,session_user)
  returning id into attempt_uuid;
  return jsonb_build_object('attempt_id',attempt_uuid,'expected_provider_tag',expected_tag,
    'state','prepared','deploy_claimed',false,'provider_version_id',null,
    'receipt_ref',null,'replayed',false);
end $_$;


--
-- Name: prepare_staging_forward_fix_rehearsal(uuid, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_forward_fix_rehearsal(p_idempotency_key uuid, p_correlation_id uuid, p_release_key text, p_git_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare rel ops.release%rowtype; existing ops.staging_forward_fix_rehearsal_attempt%rowtype;
  result_row ops.staging_forward_fix_rehearsal_result%rowtype; migration_hash text;
  migration_count integer; provider_uuid uuid; attempt_uuid uuid; expected_tag text;
begin
  if session_user<>'carr_jobs' then raise exception 'forward-fix rehearsal writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_correlation_id is null or coalesce(p_release_key,'')=''
     or coalesce(p_git_sha,'') !~ '^[0-9a-f]{40}$' then
    raise exception 'invalid typed forward-fix rehearsal input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,315));
  perform pg_advisory_xact_lock(hashtextextended(p_correlation_id::text,315));
  select * into rel from ops.release where release_key=p_release_key;
  if not found or rel.environment<>'production' or rel.state<>'candidate'
     or rel.recovery_strategy<>'forward_fix' or rel.rollback_ready is not true
     or coalesce(btrim(rel.rollback_plan_ref),'')='' or coalesce(btrim(rel.plan_hash),'')=''
     or rel.service_id is null or rel.provider<>'cloudflare-workers'
     or coalesce(btrim(rel.provider_version_id),'')='' then
    raise exception 'forward-fix rehearsal target is not an exact forward-fix Production candidate';
  end if;
  provider_uuid:=rel.provider_version_id::uuid;
  if p_git_sha<>rel.git_sha or coalesce(cardinality(rel.migration_set),0)<=0
     or coalesce(rel.schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(rel.schema_applied_count,0)<=0
     or coalesce(rel.schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'forward-fix rehearsal target lacks the exact declared candidate identity';
  end if;
  migration_hash:=ops.program5_migration_set_sha256(rel.migration_set);
  migration_count:=cardinality(rel.migration_set);
  expected_tag:='carr-staging-forward-fix-'||replace(p_idempotency_key::text,'-','');
  select * into existing from ops.staging_forward_fix_rehearsal_attempt where idempotency_key=p_idempotency_key;
  if found then
    if (existing.correlation_id,existing.release_id,existing.service_id,existing.git_sha,
        existing.candidate_provider_version_id,existing.recovery_strategy,existing.recovery_plan_ref,
        existing.plan_hash,existing.expected_provider_tag,existing.declared_migration_set_sha256,
        existing.declared_migration_count,existing.declared_schema_highest_migration,
        existing.declared_schema_applied_count,existing.declared_schema_ledger_sha256) is distinct from
       (p_correlation_id,rel.id,rel.service_id,p_git_sha,provider_uuid,'forward_fix',rel.rollback_plan_ref,
        rel.plan_hash,expected_tag,migration_hash,migration_count,rel.schema_highest_migration,
        rel.schema_applied_count,rel.schema_ledger_sha256) then
      raise exception 'forward-fix rehearsal idempotency key was reused with changed input';
    end if;
    select * into result_row from ops.staging_forward_fix_rehearsal_result where rehearsal_attempt_id=existing.id;
    return jsonb_build_object('forward_fix_rehearsal_attempt_id',existing.id,
      'expected_provider_tag',existing.expected_provider_tag,
      'state',case when result_row.id is null then 'prepared' else 'observed' end,
      'mutation_claimed',exists(select 1 from ops.staging_forward_fix_rehearsal_claim where rehearsal_attempt_id=existing.id),
      'result_ref',result_row.evidence_ref,'replayed',true);
  end if;
  insert into ops.staging_forward_fix_rehearsal_attempt(
    idempotency_key,correlation_id,release_id,service_id,environment,git_sha,provider,
    candidate_provider_version_id,recovery_strategy,recovery_plan_ref,plan_hash,expected_provider_tag,
    declared_migration_set_sha256,declared_migration_count,declared_schema_highest_migration,
    declared_schema_applied_count,declared_schema_ledger_sha256,writer_session_user)
  values(p_idempotency_key,p_correlation_id,rel.id,rel.service_id,'staging',p_git_sha,'cloudflare-workers',
    provider_uuid,'forward_fix',rel.rollback_plan_ref,rel.plan_hash,expected_tag,migration_hash,migration_count,
    rel.schema_highest_migration,rel.schema_applied_count,rel.schema_ledger_sha256,session_user)
  returning id into attempt_uuid;
  return jsonb_build_object('forward_fix_rehearsal_attempt_id',attempt_uuid,
    'expected_provider_tag',expected_tag,'state','prepared','mutation_claimed',false,
    'result_ref',null,'replayed',false);
end $_$;


--
-- Name: prepare_staging_replacement_project(uuid, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_replacement_project(p_idempotency_key uuid, p_contract jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare
  expected_keys constant text[] := array[
    'artifact_sha256','config_sha256','dependency_sha256',
    'expected_production_overlap_count','expected_synthetic_data_count','git_sha',
    'migration_count','migration_highest','migration_ledger','migration_ledger_sha256',
    'prior_staging_project_id','replacement_branch_id','replacement_endpoint_id',
    'replacement_project_id','schema_version','source_tree_entry_count',
    'source_tree_oid','source_tree_sha256','tree_mode'
  ];
  production_project_id constant text := 'steep-field-48688294';
  supplied_keys text[]; ledger jsonb; declared_ledger_digest text;
  declared_count integer; declared_highest text; invalid_entries integer;
  existing ops.staging_replacement_project_contract%rowtype;
  receipt ops.staging_replacement_project_receipt%rowtype; contract_uuid uuid;
begin
  if session_user<>'carr_jobs' then
    raise exception 'staging replacement preparation requires the carr_jobs session';
  end if;
  if p_idempotency_key is null or jsonb_typeof(p_contract)<>'object' then
    raise exception 'invalid staging replacement preparation input';
  end if;
  select array_agg(k order by k collate "C") into supplied_keys
    from jsonb_object_keys(p_contract) as keys(k);
  if supplied_keys is distinct from expected_keys then
    raise exception 'staging replacement contract has missing or unknown keys';
  end if;
  if jsonb_typeof(p_contract->'migration_ledger')<>'object'
     or jsonb_typeof(p_contract->'migration_count')<>'number'
     or jsonb_typeof(p_contract->'source_tree_entry_count')<>'number'
     or jsonb_typeof(p_contract->'expected_synthetic_data_count')<>'number'
     or jsonb_typeof(p_contract->'expected_production_overlap_count')<>'number' then
    raise exception 'staging replacement contract has invalid typed values';
  end if;
  ledger:=p_contract->'migration_ledger';
  select count(*)::integer, max(e.key collate "C"),
         count(*) filter (where e.key !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
                           or e.value !~ '^[0-9a-f]{64}$')::integer,
         'sha256:'||encode(public.digest(
           coalesce(string_agg(
             convert_to(e.key,'UTF8')||decode('00','hex')||
             convert_to(e.value,'UTF8')||decode('0a','hex'),
             ''::bytea order by e.key collate "C"),''::bytea),'sha256'),'hex')
    into declared_count,declared_highest,invalid_entries,declared_ledger_digest
    from jsonb_each_text(ledger) e;
  if declared_count=0 or invalid_entries<>0
     or (p_contract->>'migration_count')::integer<>declared_count
     or p_contract->>'migration_highest' is distinct from declared_highest
     or p_contract->>'migration_ledger_sha256' is distinct from declared_ledger_digest then
    raise exception 'staging replacement contract is not the exact full migration tree';
  end if;
  if p_contract->>'schema_version'<>'clean-staging-replacement-contract.v1'
     or p_contract->>'tree_mode'<>'full'
     or coalesce(p_contract->>'git_sha','') !~ '^[0-9a-f]{40}$'
     or coalesce(p_contract->>'source_tree_oid','') !~ '^[0-9a-f]{40}$'
     or coalesce(p_contract->>'source_tree_sha256','') !~ '^sha256:[0-9a-f]{64}$'
     or (p_contract->>'source_tree_entry_count')::integer<=0
     or coalesce(p_contract->>'artifact_sha256','') !~ '^sha256:[0-9a-f]{64}$'
     or coalesce(p_contract->>'config_sha256','') !~ '^sha256:[0-9a-f]{64}$'
     or coalesce(p_contract->>'dependency_sha256','') !~ '^sha256:[0-9a-f]{64}$'
     or coalesce(btrim(p_contract->>'prior_staging_project_id'),'')=''
     or coalesce(btrim(p_contract->>'replacement_project_id'),'')=''
     or coalesce(btrim(p_contract->>'replacement_branch_id'),'')=''
     or coalesce(btrim(p_contract->>'replacement_endpoint_id'),'')=''
     or p_contract->>'prior_staging_project_id'=p_contract->>'replacement_project_id'
     or p_contract->>'prior_staging_project_id'=production_project_id
     or p_contract->>'replacement_project_id'=production_project_id
     or (p_contract->>'expected_synthetic_data_count')::bigint<=0
     or (p_contract->>'expected_production_overlap_count')::bigint<>0 then
    raise exception 'staging replacement contract identity or isolation assertion is invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,322));
  select * into existing from ops.staging_replacement_project_contract
   where idempotency_key=p_idempotency_key;
  if found then
    if (existing.schema_version,existing.tree_mode,existing.git_sha,
        existing.source_tree_oid,existing.source_tree_sha256,existing.source_tree_entry_count,
        existing.artifact_sha256,existing.config_sha256,existing.dependency_sha256,
        existing.migration_ledger,existing.migration_count,existing.migration_highest,
        existing.migration_ledger_sha256,existing.prior_staging_project_id,
        existing.replacement_project_id,existing.replacement_branch_id,
        existing.replacement_endpoint_id,existing.expected_synthetic_data_count,
        existing.expected_production_overlap_count) is distinct from
       (p_contract->>'schema_version',p_contract->>'tree_mode',p_contract->>'git_sha',
        p_contract->>'source_tree_oid',p_contract->>'source_tree_sha256',
        (p_contract->>'source_tree_entry_count')::integer,p_contract->>'artifact_sha256',
        p_contract->>'config_sha256',p_contract->>'dependency_sha256',ledger,
        declared_count,declared_highest,declared_ledger_digest,
        p_contract->>'prior_staging_project_id',p_contract->>'replacement_project_id',
        p_contract->>'replacement_branch_id',p_contract->>'replacement_endpoint_id',
        (p_contract->>'expected_synthetic_data_count')::bigint,0::bigint) then
      raise exception 'staging replacement idempotency key was reused with changed input';
    end if;
    select * into receipt from ops.staging_replacement_project_receipt
     where contract_id=existing.id;
    return jsonb_build_object('contract_id',existing.id,
      'state',case when receipt.id is null then 'prepared' else 'observed' end,
      'receipt_id',receipt.id,'evidence_ref',receipt.evidence_ref,'replayed',true);
  end if;

  insert into ops.staging_replacement_project_contract(
    idempotency_key,schema_version,tree_mode,git_sha,source_tree_oid,
    source_tree_sha256,source_tree_entry_count,artifact_sha256,config_sha256,
    dependency_sha256,migration_ledger,migration_count,migration_highest,
    migration_ledger_sha256,prior_staging_project_id,replacement_project_id,
    replacement_branch_id,replacement_endpoint_id,expected_synthetic_data_count,
    expected_production_overlap_count,writer_session_user)
  values(p_idempotency_key,p_contract->>'schema_version',p_contract->>'tree_mode',
    p_contract->>'git_sha',p_contract->>'source_tree_oid',p_contract->>'source_tree_sha256',
    (p_contract->>'source_tree_entry_count')::integer,p_contract->>'artifact_sha256',
    p_contract->>'config_sha256',p_contract->>'dependency_sha256',ledger,
    declared_count,declared_highest,declared_ledger_digest,
    p_contract->>'prior_staging_project_id',p_contract->>'replacement_project_id',
    p_contract->>'replacement_branch_id',p_contract->>'replacement_endpoint_id',
    (p_contract->>'expected_synthetic_data_count')::bigint,0,session_user)
  returning id into contract_uuid;
  return jsonb_build_object('contract_id',contract_uuid,'state','prepared',
    'receipt_id',null,'evidence_ref',null,'replayed',false);
end $_$;


--
-- Name: prepare_staging_restore_only_attempt(uuid, uuid, text, text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_staging_restore_only_attempt(p_idempotency_key uuid, p_correlation_id uuid, p_release_key text, p_prior_release_key text, p_recovery_attempt_id uuid, p_git_sha text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_restore_only_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  migration_hash text;
  migration_count integer;
  attempt_uuid uuid;
  target_provider_version uuid;
  expected_tag text;
  existing_result ops.staging_restore_only_result%rowtype;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_correlation_id is null or p_recovery_attempt_id is null
     or coalesce(p_release_key,'')='' or coalesce(p_prior_release_key,'' )=''
     or coalesce(p_git_sha,'') !~ '^[0-9a-f]{40}$' or p_correlation_id<>p_recovery_attempt_id then
    raise exception 'invalid typed restore-only attempt input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  perform pg_advisory_xact_lock(hashtextextended(p_recovery_attempt_id::text,202));
  select * into current_release from ops.release where release_key=p_release_key;
  if not found or current_release.environment<>'production' or current_release.state<>'candidate'
     or current_release.recovery_strategy<>'rollback' or coalesce(current_release.rollback_plan_ref,'')=''
     or coalesce(current_release.plan_hash,'')='' or current_release.service_id is null
     or current_release.provider<>'cloudflare-workers' or current_release.provider_version_id is null then
    raise exception 'restore-only target is not an exact rollback-ready Production candidate';
  end if;
  if current_release.provider_version_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'restore-only target provider version is not a canonical UUID';
  end if;
  target_provider_version:=current_release.provider_version_id::uuid;
  select * into prior_release from ops.release where release_key=p_prior_release_key;
  if not found or prior_release.id=current_release.id or prior_release.environment<>'production'
     or prior_release.state<>'complete' or prior_release.service_id<>current_release.service_id then
    raise exception 'restore-only prior release is not a distinct completed Production release';
  end if;
  if not exists (select 1 from ops.deployment d where d.release_id=prior_release.id
      and d.service_id=current_release.service_id and d.environment='production'
      and d.state='complete' and d.read_back_at is not null and d.git_sha=prior_release.git_sha
      and d.provider=prior_release.provider and d.provider_version_id=prior_release.provider_version_id) then
    raise exception 'restore-only prior release has no exact completed Production readback';
  end if;
  if p_git_sha<>current_release.git_sha then raise exception 'restore-only SHA does not match the current target'; end if;
  if coalesce(cardinality(current_release.migration_set),0)<=0
     or coalesce(current_release.schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(current_release.schema_applied_count,0)<=0
     or coalesce(current_release.schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$' then
    raise exception 'restore-only target does not declare an exact migration/schema set';
  end if;
  migration_hash:=ops.program5_migration_set_sha256(current_release.migration_set);
  migration_count:=cardinality(current_release.migration_set);
  expected_tag:='carr-staging-'||replace(p_idempotency_key::text,'-','');
  select * into existing from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if found then
    if (existing.correlation_id,existing.recovery_attempt_id,existing.rehearsal_release_id,
        existing.prior_release_id,existing.service_id,existing.git_sha,existing.target_provider_version_id,
        existing.recovery_strategy,existing.rollback_plan_ref,existing.plan_hash,existing.expected_provider_tag,
        existing.declared_migration_set_sha256,existing.declared_migration_count,
        existing.declared_schema_highest_migration,existing.declared_schema_applied_count,
        existing.declared_schema_ledger_sha256) is distinct from
       (p_correlation_id,p_recovery_attempt_id,current_release.id,prior_release.id,current_release.service_id,
        p_git_sha,target_provider_version,current_release.recovery_strategy,
        current_release.rollback_plan_ref,current_release.plan_hash,expected_tag,migration_hash,migration_count,
        current_release.schema_highest_migration,current_release.schema_applied_count,
        current_release.schema_ledger_sha256) then
      raise exception 'restore-only idempotency key was reused with changed input';
    end if;
    select * into existing_result from ops.staging_restore_only_result where restore_attempt_id=existing.id;
    return jsonb_build_object('restore_attempt_id',existing.id,'expected_provider_tag',existing.expected_provider_tag,
      'state',coalesce(existing_result.status,'prepared'),'mutation_claimed',exists(select 1 from ops.staging_restore_only_claim where restore_attempt_id=existing.id),
      'result_ref',existing_result.evidence_ref,'replayed',true);
  end if;
  insert into ops.staging_restore_only_attempt(idempotency_key,recovery_attempt_id,correlation_id,
    rehearsal_release_id,prior_release_id,service_id,environment,git_sha,provider,target_provider_version_id,
    recovery_strategy,rollback_plan_ref,plan_hash,expected_provider_tag,declared_migration_set_sha256,
    declared_migration_count,declared_schema_highest_migration,declared_schema_applied_count,
    declared_schema_ledger_sha256,writer_session_user)
  values(p_idempotency_key,p_recovery_attempt_id,p_correlation_id,current_release.id,prior_release.id,
    current_release.service_id,'staging',p_git_sha,'cloudflare-workers',target_provider_version,
    current_release.recovery_strategy,current_release.rollback_plan_ref,current_release.plan_hash,expected_tag,
    migration_hash,migration_count,current_release.schema_highest_migration,current_release.schema_applied_count,
    current_release.schema_ledger_sha256,session_user) returning id into attempt_uuid;
  return jsonb_build_object('restore_attempt_id',attempt_uuid,'expected_provider_tag',expected_tag,
    'state','prepared','mutation_claimed',false,'result_ref',null,'replayed',false);
end $_$;


--
-- Name: prepare_tour_route_version(text, uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.prepare_tour_route_version(p_tenant text, p_tour_id uuid, p_base_route_version_id uuid, p_expected_route_version integer, p_stop_ids jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_tour ops.tour%rowtype; v_base ops.tour_route_version%rowtype; v_source ops.tour_route_version%rowtype; v_new uuid; v_new_stop uuid; v_next integer; v_stop record; v_old_stop ops.tour_route_stop%rowtype; v_label text;
begin
  if jsonb_typeof(p_stop_ids)<>'array' or jsonb_array_length(p_stop_ids)=0 or jsonb_array_length(p_stop_ids)>100
     or exists(select 1 from jsonb_array_elements_text(p_stop_ids) x(value) where value !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
     or (select count(*) from jsonb_array_elements_text(p_stop_ids))<>(select count(distinct value) from jsonb_array_elements_text(p_stop_ids) x(value)) then raise exception 'tour route preparation payload is invalid'; end if;
  select * into v_tour from ops.tour where organization_tenant_id=p_tenant and id=p_tour_id for update;
  if not found or v_tour.route_version<>p_expected_route_version then raise exception 'tour route preparation refuses stale state'; end if;
  select v.* into v_base from ops.tour_route_version v join ops.tour_route_version_acceptance a on a.organization_tenant_id=v.organization_tenant_id and a.route_version_id=v.id where v.organization_tenant_id=p_tenant and v.tour_id=p_tour_id and v.route_version=p_expected_route_version;
  if not found then raise exception 'tour route preparation base is unavailable'; end if;
  if p_base_route_version_id is null then v_source:=v_base;
  else
    select * into v_source from ops.tour_route_version where organization_tenant_id=p_tenant and tour_id=p_tour_id and id=p_base_route_version_id;
    if not found then raise exception 'tour route preparation base is unavailable'; end if;
  end if;
  if exists(select 1 from jsonb_array_elements_text(p_stop_ids) x(value) left join ops.tour_route_stop s on s.organization_tenant_id=p_tenant and s.route_version_id=v_source.id and s.id=x.value::uuid and s.stop_state='active' where s.id is null) then raise exception 'tour route preparation stop is unavailable'; end if;
  if exists(
    select 1 from (
      select s.appointment_start,
        lag(s.appointment_start) over (order by x.ordinality) as prior_appointment_start
      from jsonb_array_elements_text(p_stop_ids) with ordinality x(value,ordinality)
      join ops.tour_route_stop s on s.organization_tenant_id=p_tenant
        and s.route_version_id=v_source.id and s.id=x.value::uuid
      where s.stop_state='active' and s.locked_appointment
    ) locked
    where locked.prior_appointment_start is not null
      and locked.appointment_start < locked.prior_appointment_start
  ) then raise exception 'tour route preparation violates locked appointment order'; end if;
  select coalesce(max(route_version),0)+1 into v_next from ops.tour_route_version where organization_tenant_id=p_tenant and tour_id=p_tour_id;
  v_new:=ops.append_tour_route_version(p_tenant,p_tour_id,v_next,v_base.id,v_base.start_point,v_base.end_point,'manual',null,null,'{}',null,p_expected_route_version,null);
  for v_stop in select s.*,x.ordinality::integer new_sequence from jsonb_array_elements_text(p_stop_ids) with ordinality x(value,ordinality) join ops.tour_route_stop s on s.organization_tenant_id=p_tenant and s.route_version_id=v_source.id and s.id=x.value::uuid order by x.ordinality loop
    v_label:=case when v_stop.new_sequence<=26 then chr(64+v_stop.new_sequence) else chr(64+((v_stop.new_sequence-1)/26))||chr(65+((v_stop.new_sequence-1)%26)) end;
    v_new_stop:=ops.append_tour_route_stop(p_tenant,v_new,v_stop.property_id,v_stop.new_sequence,v_label,'active',v_stop.appointment_start,v_stop.appointment_end,v_stop.locked_appointment,v_stop.dwell_minutes,v_stop.buffer_minutes,v_stop.access_coordinate_status,v_stop.assertion_set_digest);
    select * into v_old_stop from ops.tour_route_stop where organization_tenant_id=p_tenant and route_version_id=v_base.id and property_id=v_stop.property_id;
    if found then
      perform ops.append_tour_route_stop_transition(p_tenant,v_base.id,v_new,v_old_stop.id,v_new_stop,case when v_old_stop.route_sequence=v_stop.new_sequence then 'unchanged' else 'reordered' end);
    else
      perform ops.append_tour_route_stop_transition(p_tenant,null,v_new,null,v_new_stop,'added');
    end if;
  end loop;
  for v_stop in select s.* from ops.tour_route_stop s where s.organization_tenant_id=p_tenant and s.route_version_id=v_base.id and not exists(
    select 1 from jsonb_array_elements_text(p_stop_ids) x(value) join ops.tour_route_stop selected on selected.organization_tenant_id=p_tenant and selected.route_version_id=v_source.id and selected.id=x.value::uuid where selected.property_id=s.property_id
  ) loop
    perform ops.append_tour_route_stop_transition(p_tenant,v_base.id,v_new,v_stop.id,null,'removed');
  end loop;
  return v_new;
end $_$;


--
-- Name: program5_exact_recovery_rehearsal(uuid, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_exact_recovery_rehearsal(p_release_id uuid, p_not_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
  select r.id
    from ops.release rel
    join ops.run r on r.release_id=rel.id and r.service_id=rel.service_id
    join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id
   where rel.id=$1 and r.environment='staging' and r.state='succeeded' and r.evidence_ref=b.evidence_ref
     and r.run_key=case when rel.recovery_strategy='rollback' then 'recovery.rehearsal.worker' else 'recovery.rehearsal.forward-fix' end
     and b.current_release_id=rel.id and b.service_id=rel.service_id and b.recovery_strategy=rel.recovery_strategy
     and b.recovery_plan_ref=rel.rollback_plan_ref and b.plan_hash=rel.plan_hash
     and b.declared_migration_set_sha256=ops.program5_migration_set_sha256(rel.migration_set)
     and b.declared_migration_count=cardinality(rel.migration_set)
     and b.declared_schema_highest_migration=rel.schema_highest_migration
     and b.declared_schema_applied_count=rel.schema_applied_count
     and b.declared_schema_ledger_sha256=rel.schema_ledger_sha256
     and (rel.recovery_strategy='rollback' or (b.candidate_git_sha=rel.git_sha
          and b.candidate_provider_version_id::text=rel.provider_version_id
          and exists(select 1 from ops.staging_forward_fix_rehearsal_result x where x.id=b.forward_fix_result_id)))
     and (p_not_before is null or b.completed_at>=p_not_before)
   order by b.completed_at desc limit 1
$_$;


--
-- Name: program5_migration_set_sha256(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_migration_set_sha256(p_migration_set text[]) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select 'sha256:'||encode(public.digest(to_jsonb(p_migration_set)::text,'sha256'),'hex')
$$;


--
-- Name: program5_release_approval_is_joe_owned(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_release_approval_is_joe_owned() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.environment='production' and new.readiness_receipt_id is not null then
    if new.approved_by_actor is not null or new.approval_receipt_id is not null
       or new.approved_at is not null or new.approval_expires_at is not null then
      raise exception 'service readiness cannot impersonate Joe approval';
    end if;
    return new;
  end if;
  if new.environment='production'
     and new.state in ('approved','deploying','verifying','complete')
     and (tg_op='INSERT' or old.state not in ('approved','deploying','verifying','complete')) then
    if new.state<>'approved' or session_user<>'carr_authority_joe'
       or new.approved_by_actor<>'joe'
       or new.approval_receipt_id is null or not exists (
         select 1 from ops.release_approval_receipt a
          where a.id=new.approval_receipt_id and a.release_id=new.id
            and a.plan_hash=new.plan_hash and a.approved_by_actor='joe'
            and a.approved_at=new.approved_at
            and a.approval_expires_at=new.approval_expires_at) then
      raise exception 'legacy Production approval requires Joe authority and typed receipt';
    end if;
  end if;
  if tg_op='UPDATE' and old.environment='production'
     and old.state in ('approved','deploying','verifying','complete')
     and new.state in ('approved','deploying','verifying','complete')
     and (new.approved_by_actor,new.approved_at,new.approval_expires_at,new.approval_receipt_id)
       is distinct from
       (old.approved_by_actor,old.approved_at,old.approval_expires_at,old.approval_receipt_id) then
    raise exception 'legacy approval projection is immutable';
  end if;
  return new;
end $$;


--
-- Name: program5_release_verifier_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program5_release_verifier_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.verifier_actor,new.verifier_evidence_ref)
       is distinct from (old.verifier_actor,old.verifier_evidence_ref)
     and (old.approval_receipt_id is not null
          or old.state in ('approved','deploying','verifying','complete'))
     and new.plan_hash is not distinct from old.plan_hash then
    raise exception 'Program 5 verifier evidence is immutable after approval; revise the plan to invalidate approval first';
  end if;
  return new;
end $$;


--
-- Name: program6_browser_action_challenge_redemptions_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program6_browser_action_challenge_redemptions_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'Program 6 browser action challenge redemptions are append-only';
end;
$$;


--
-- Name: program_controller_typed_refs(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.program_controller_typed_refs(p_values text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$ select p_values is not null and not exists (
  select 1 from unnest(p_values) entry where entry !~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$') $_$;


--
-- Name: propose_eval_candidate(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_eval_candidate(p_attempt_id text, p_fact_event_ref text, p_idempotency_key uuid) RETURNS TABLE(candidate_id uuid, candidate_ref text, lifecycle text, promotion_state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare tenant text := current_setting('carr.organization_tenant_id', true); fact ops.attempt_receipt%rowtype;
  envelope_row ops.execution_envelope_v1%rowtype; fact_event jsonb; fact_count integer; fact_kind text;
  source_digest_value text; root_key text; candidate_ref_value text; case_ref_value text; target_set_ref text;
  lane_value text; risk_value text; split_value text; context_value jsonb; basis_value jsonb;
  row_out ops.proposed_eval_candidate%rowtype; previous_event ops.proposed_eval_candidate_event%rowtype;
begin
  if coalesce(tenant,'')='' or p_attempt_id !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_fact_event_ref !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' then
    raise exception 'eval proposal requires tenant-scoped canonical attempt and fact references';
  end if;
  select * into fact from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id for share;
  if not found then raise exception 'eval candidate attempt receipt is not visible to tenant'; end if;
  select * into envelope_row from ops.execution_envelope_v1 where id=fact.execution_envelope_id and organization_tenant_id=tenant for share;
  if not found then raise exception 'eval candidate requires its exact issued evaluation plan'; end if;
  select count(*), (array_agg(item))[1], min(kind) into fact_count,fact_event,fact_kind from (
    select e.value as item, 'correction'::text as kind from jsonb_array_elements(fact.receipt->'reliability'->'corrections') e where e.value->>'event_ref'=p_fact_event_ref
    union all select e.value, 'defect'::text from jsonb_array_elements(fact.receipt->'reliability'->'defects') e where e.value->>'event_ref'=p_fact_event_ref
    union all select e.value, 'incident'::text from jsonb_array_elements(fact.receipt->'reliability'->'incidents') e where e.value->>'event_ref'=p_fact_event_ref
  ) canonical_fact;
  if fact_count<>1 or fact_event->>'kind'<>fact_kind
     or jsonb_typeof(fact_event->'evidence_refs')<>'array'
     or jsonb_array_length(fact_event->'evidence_refs')=0
     or ops.attempt_receipt_contains_raw_content(fact_event) then
    raise exception 'eval proposal fact must be one redacted canonical correction, defect, or incident';
  end if;
  -- `summary` is metadata classification, not a copied client/executor body.
  if coalesce(fact_event->>'summary','') !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' then
    raise exception 'eval proposal fact summary must be a bounded classification ref';
  end if;
  source_digest_value := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(fact_event),'sha256'),'hex');
  -- The event ref identifies this occurrence; summary is the bounded canonical
  -- taxonomy/root-cause classification.  Dedupe therefore means same root
  -- cause *and* same exact source fact, never merely the same event label.
  root_key := 'root:'||fact_kind||':'||lower(regexp_replace(fact_event->>'summary','[^A-Za-z0-9]+','-','g'));
  lane_value := coalesce(envelope_row.evaluation_plan->>'lane_ref','lane:governed-work');
  risk_value := coalesce(envelope_row.evaluation_plan->>'risk_class','R2');
  -- Issued policy currently has a single safe default.  It is deliberately
  -- server-owned and never passed by the executor or human proposer.
  split_value := coalesce(envelope_row.evaluation_plan->>'learning_split_target','development');
  if lane_value !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$' or risk_value !~ '^R[0-6]$'
     or split_value not in ('development','held_out','canary') then
    raise exception 'issued evaluation plan has no valid learning lane/risk/split';
  end if;
  candidate_ref_value := 'eval-candidate:'||substr(replace(source_digest_value,'sha256:',''),1,24);
  case_ref_value := 'case:proposal:'||substr(replace(source_digest_value,'sha256:',''),1,24);
  target_set_ref := 'golden:'||lower(regexp_replace(lane_value,'[^A-Za-z0-9]+','-','g'))||':'||lower(risk_value)||':'||split_value;
  context_value := jsonb_build_object('work_request_id','wr:'||fact.work_request_id::text,'case_digest',source_digest_value);
  basis_value := fact_event->'evidence_refs';
  select * into previous_event from ops.proposed_eval_candidate_event where idempotency_key=p_idempotency_key for share;
  if found then
    select * into row_out from ops.proposed_eval_candidate where id=previous_event.candidate_id and organization_tenant_id=tenant;
    if row_out.id is null or previous_event.event_kind<>'proposed' or row_out.attempt_receipt_id<>fact.id
       or row_out.source_digest<>source_digest_value or row_out.normalized_root_cause_key<>root_key then
      raise exception 'eval candidate proposal idempotency conflict';
    end if;
    return query select row_out.id,row_out.candidate_ref,
      coalesce((select pe.event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=row_out.id order by pe.created_at desc,pe.id desc limit 1),'proposed'),
      row_out.promotion_state,true;
    return;
  end if;
  select * into row_out from ops.proposed_eval_candidate
    where organization_tenant_id=tenant and normalized_root_cause_key=root_key and source_digest=source_digest_value for share;
  if found then
    if row_out.attempt_receipt_id<>fact.id or row_out.case_ref<>case_ref_value or row_out.target_golden_set_ref<>target_set_ref
       or row_out.lane_ref<>lane_value or row_out.risk_class<>risk_value or row_out.split_target<>split_value
       or row_out.provenance<>fact_kind or row_out.context_binding is distinct from context_value or row_out.basis is distinct from basis_value then
      raise exception 'eval candidate source dedupe conflicts with immutable proposal';
    end if;
    return query select row_out.id,row_out.candidate_ref,
      coalesce((select pe.event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=row_out.id order by pe.created_at desc,pe.id desc limit 1),'proposed'),
      row_out.promotion_state,true;
    return;
  end if;
  insert into ops.proposed_eval_candidate(organization_tenant_id,attempt_receipt_id,candidate_ref,case_ref,target_golden_set_ref,normalized_root_cause_key,source_digest,lane_ref,risk_class,provenance,split_target,context_binding,basis)
  values(tenant,fact.id,candidate_ref_value,case_ref_value,target_set_ref,root_key,source_digest_value,lane_value,risk_value,fact_kind,split_value,context_value,basis_value)
  returning * into row_out;
  insert into ops.proposed_eval_candidate_event(candidate_id,event_kind,decision_basis,idempotency_key)
  values(row_out.id,'proposed',jsonb_build_object('source','attempt-receipt','fact_event_ref',p_fact_event_ref,'source_digest',source_digest_value),p_idempotency_key);
  return query select row_out.id,row_out.candidate_ref,'proposed',row_out.promotion_state,false;
end $_$;


--
-- Name: propose_guidance_situation_mapping(uuid, uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_guidance_situation_mapping(p_revision_id uuid, p_concept_id uuid, p_doctrine_section_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare mapping_id uuid;
begin
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'situation mapping proposal requires a reason';
  end if;
  if not exists (
    select 1 from ops.guidance_revision
     where id=p_revision_id and guidance_type='doctrine') then
    raise exception 'situation mappings may be proposed only for doctrine revisions';
  end if;
  insert into ops.guidance_situation_mapping
    (guidance_revision_id,concept_id,doctrine_section_id,state,reason)
  values (p_revision_id,p_concept_id,p_doctrine_section_id,'proposed',p_reason)
  returning id into mapping_id;
  return mapping_id;
end $$;


--
-- Name: propose_meeting_action(uuid, text, jsonb, text, text, integer, integer, bigint, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_meeting_action(p_meeting uuid, p_summary text, p_command jsonb, p_basis text, p_dedupe_key text, p_revises_action_number integer, p_base_revision integer, p_processing_epoch bigint, p_client_instance text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype; v_lease ops.meeting_processing_lease%rowtype;
        v_prior ops.meeting_action_revision%rowtype; v_head ops.meeting_action%rowtype;
        v_latest ops.meeting_action_revision%rowtype; v_number integer; v_revision integer;
        v_source text; v_accepted boolean := false;
begin
  select * into v_who from ops.meeting_mode_actor();
  select * into v_prior from ops.meeting_action_revision where id = p_idempotency_key;
  if v_prior.id is not null then
    if v_prior.meeting_id is distinct from p_meeting or v_prior.summary is distinct from p_summary
       or v_prior.command is distinct from p_command or v_prior.basis is distinct from p_basis
       or v_prior.proposed_by_actor is distinct from v_who.actor_id then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_idempotency_key_reuse');
    end if;
    return jsonb_build_object('ok', true, 'deduplicated', true, 'meeting_id', p_meeting,
      'revision', v_prior.revision,
      'action', ops.meeting_mode_action_view(p_meeting, v_prior.action_number));
  end if;
  if p_basis not in ('tentative_discussion', 'explicit_instruction') then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_basis_invalid');
  end if;
  select * into v_row from ops.meeting
   where id = p_meeting and organization_tenant_id = v_who.tenant for update;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  if v_row.mode_state = 'ended' then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_ended', 'meeting_id', p_meeting);
  end if;

  v_source := case when p_processing_epoch is null then 'participant' else 'processing' end;
  if v_source = 'processing' then
    select * into v_lease from ops.meeting_processing_lease where meeting_id = p_meeting;
    if v_lease.meeting_id is null or v_lease.released_at is not null
       or v_lease.expires_at <= clock_timestamp()
       or v_lease.holder_actor <> v_who.actor_id or v_lease.holder_instance <> p_client_instance
       or v_lease.lease_epoch <> p_processing_epoch then
      return jsonb_build_object('ok', false, 'reason_id', 'stale_processing_lease',
        'current_lease_epoch', v_lease.lease_epoch);
    end if;
  end if;

  if p_revises_action_number is not null then
    select * into v_head from ops.meeting_action
     where meeting_id = p_meeting and action_number = p_revises_action_number for update;
    if v_head.meeting_id is null then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_not_found',
        'action_number', p_revises_action_number);
    end if;
    if v_head.state <> 'proposed' then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_no_longer_pending',
        'action', ops.meeting_mode_action_view(p_meeting, v_head.action_number));
    end if;
    if p_base_revision is distinct from v_head.current_revision then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_revision_conflict',
        'action', ops.meeting_mode_action_view(p_meeting, v_head.action_number));
    end if;
  elsif p_dedupe_key is not null then
    select * into v_head from ops.meeting_action
     where meeting_id = p_meeting and dedupe_key = p_dedupe_key for update;
    if v_head.meeting_id is not null and v_head.state <> 'proposed' then
      return jsonb_build_object('ok', true, 'deduplicated', true, 'already_resolved', true,
        'meeting_id', p_meeting,
        'action', ops.meeting_mode_action_view(p_meeting, v_head.action_number));
    end if;
  elsif p_base_revision is not null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_base_revision_without_action');
  end if;

  if v_head.meeting_id is not null then
    select * into v_latest from ops.meeting_action_revision
     where meeting_id = p_meeting and action_number = v_head.action_number
       and revision = v_head.current_revision;
    if v_latest.summary = p_summary and v_latest.command is not distinct from p_command
       and v_latest.basis = p_basis then
      return jsonb_build_object('ok', true, 'deduplicated', true, 'meeting_id', p_meeting,
        'revision', v_head.current_revision,
        'action', ops.meeting_mode_action_view(p_meeting, v_head.action_number));
    end if;
    v_number := v_head.action_number;
    v_revision := v_head.current_revision + 1;
    update ops.meeting_action set current_revision = v_revision
     where meeting_id = p_meeting and action_number = v_number;
  else
    v_number := v_row.last_action_number + 1;
    v_revision := 1;
    update ops.meeting set last_action_number = v_number where id = p_meeting;
    insert into ops.meeting_action(meeting_id, action_number, dedupe_key, state, current_revision)
    values (p_meeting, v_number, p_dedupe_key, 'proposed', 1);
  end if;

  insert into ops.meeting_action_revision(id, meeting_id, action_number, revision, summary, command,
    basis, source, processing_epoch, proposed_by_actor, proposed_by_instance)
  values (p_idempotency_key, p_meeting, v_number, v_revision, p_summary, p_command, p_basis,
    v_source, p_processing_epoch, v_who.actor_id, p_client_instance);
  perform ops.meeting_mode_append(p_meeting,
    case when v_revision = 1 then 'action_proposed' else 'action_revised' end,
    v_who.actor_id, p_client_instance, null, v_number, v_revision, null, p_idempotency_key);

  if v_source = 'participant' and v_who.is_partner and p_basis = 'explicit_instruction'
     and p_command is not null then
    perform ops.meeting_mode_accept(p_meeting, v_number, v_revision, v_who.actor_id, 'execute',
      v_who.actor_id, p_client_instance, p_idempotency_key);
    v_accepted := true;
  end if;

  return jsonb_build_object('ok', true, 'deduplicated', false, 'meeting_id', p_meeting,
    'revision', v_revision, 'accepted_as_explicit_instruction', v_accepted,
    'action', ops.meeting_mode_action_view(p_meeting, v_number),
    'seq', (select last_seq from ops.meeting where id = p_meeting));
end $$;


--
-- Name: propose_ready_plan_amendment(text, integer, text, text, text, jsonb, text, text, jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_ready_plan_amendment(p_work_request text, p_base_version integer, p_predecessor_plan_hash text, p_scope_summary text, p_runbook_ref text, p_dependency_refs jsonb, p_recovery_ref text, p_observability_ref text, p_caps jsonb, p_heavy_build jsonb, p_proposed_by_actor_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_actor uuid; v_work ops.work_request%rowtype; v_prior ops.sourced_work_request_plan%rowtype;
        v_plan ops.sourced_work_request_plan%rowtype; v_existing ops.sourced_work_request_plan%rowtype;
        v_section uuid; v_revision uuid; v_hash text; v_preimage jsonb;
        v_plan_hash text; v_version integer; v_amendment_hash text;
        v_classification jsonb; v_reasons jsonb; v_admission record;
begin
  v_actor:=ops.portfolio_writer_actor_id();
  if coalesce(p_work_request,'')!~'^WR-[0-9]{1,12}$'
     or p_idempotency_key is null or p_base_version is null or p_base_version<1
     or coalesce(p_predecessor_plan_hash,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(btrim(p_scope_summary),'')='' or char_length(btrim(p_scope_summary))>1000
     or coalesce(btrim(p_runbook_ref),'')!~'^doctrine:runbook#[a-z0-9][a-z0-9-]*$'
     or coalesce(btrim(p_recovery_ref),'')!~'^safe:[a-z0-9][a-z0-9:_./-]*$'
     or char_length(btrim(p_recovery_ref))>300
     or coalesce(btrim(p_observability_ref),'')!~'^safe:[a-z0-9][a-z0-9:_./-]*$'
     or char_length(btrim(p_observability_ref))>300
     or jsonb_typeof(p_dependency_refs) is distinct from 'array'
     or jsonb_array_length(p_dependency_refs)>12
     or exists(select 1 from jsonb_array_elements(p_dependency_refs) dep
       where jsonb_typeof(dep)<>'string' or dep#>>'{}'!~'^safe:[a-z0-9][a-z0-9:_./-]*$'
         or char_length(dep#>>'{}')>300)
     or exists(select dep#>>'{}' from jsonb_array_elements(p_dependency_refs) dep
       group by dep#>>'{}' having count(*)>1)
     or jsonb_typeof(p_caps) is distinct from 'object'
     or ((select array_agg(key order by key) from jsonb_object_keys(p_caps) key)
          is distinct from array['max_duration_minutes','max_steps']::text[]
       and (select array_agg(key order by key) from jsonb_object_keys(p_caps) key)
          is distinct from array['max_duration_minutes','max_steps','source_merge']::text[])
     or coalesce(p_caps->>'max_steps','')!~'^[0-9]+$'
     or coalesce(p_caps->>'max_duration_minutes','')!~'^[0-9]+$'
     or (p_caps->>'max_steps')::integer not between 1 and 20
     or (p_caps->>'max_duration_minutes')::integer not between 1 and 120
     or (p_caps?'source_merge' and not coalesce(ops.source_merge_scope_valid(p_caps->'source_merge'),false))
     or p_proposed_by_actor_id is null or p_proposed_by_actor_id<>v_actor
     or not ops.heavy_build_jsonb_has_exact_keys(p_heavy_build,
          array['builder_session_ref','master_plan','research_manifest'])
     or coalesce(p_heavy_build->>'builder_session_ref','')!~'^session:[a-z0-9][a-z0-9:._/-]{8,199}$'
     or jsonb_typeof(p_heavy_build->'master_plan') is distinct from 'object'
     or jsonb_typeof(p_heavy_build->'research_manifest') is distinct from 'object'
     or p_heavy_build->'master_plan'='{}'::jsonb
     or p_heavy_build->'research_manifest'='{}'::jsonb then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_input_invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('ready-plan-amendment:'||p_work_request,0));
  select * into v_existing from ops.sourced_work_request_plan where idempotency_key=p_idempotency_key;
  if found then
    select * into v_work from ops.work_request where id=v_existing.work_request_id;
    select * into v_prior from ops.sourced_work_request_plan where id=(select predecessor_plan_id from ops.ready_plan_amendment where plan_id=v_existing.id);
    select * into v_admission from ops.heavy_build_admission_revision
      where plan_id=v_existing.id order by version desc limit 1;
    if v_work.ref is distinct from p_work_request or v_prior.plan_hash is distinct from p_predecessor_plan_hash
       or v_existing.work_request_version is distinct from p_base_version
       or v_existing.scope_summary is distinct from btrim(p_scope_summary)
       or v_existing.runbook_ref is distinct from btrim(p_runbook_ref)
       or v_existing.dependency_refs is distinct from p_dependency_refs
       or v_existing.recovery_ref is distinct from btrim(p_recovery_ref)
       or v_existing.observability_ref is distinct from btrim(p_observability_ref)
       or v_existing.caps is distinct from p_caps or v_admission.contract is distinct from p_heavy_build
       or v_admission.proposed_by_actor_id is distinct from p_proposed_by_actor_id then
      return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_idempotency_conflict');
    end if;
    return jsonb_build_object('ok',true,'replayed',true,
      'work_request',jsonb_build_object('id',v_work.id,'ref',v_work.ref,'state','ready','version',v_existing.work_request_version),
      'plan',jsonb_build_object('id',v_existing.id,'ref',v_existing.plan_ref,'hash',v_existing.plan_hash,'version',v_existing.plan_version,
        'predecessor_ref',v_prior.plan_ref,'predecessor_hash',v_prior.plan_hash),
      'build_admission',jsonb_build_object('tier',v_admission.tier,'reasons',v_admission.classifier_reasons,
        'admission_ref',v_admission.admission_ref,'admission_hash',v_admission.admission_hash,
        'builder_session_ref',v_admission.builder_session_ref));
  end if;
  select * into v_work from ops.work_request where ref=p_work_request for update;
  if not found or v_work.state<>'ready' or v_work.version<>p_base_version then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_base_stale');
  end if;
  select p.* into v_prior from ops.sourced_work_request_plan_acceptance_receipt ar
    join ops.sourced_work_request_plan p on p.id=ar.plan_id
   where ar.work_request_id=v_work.id and ar.result_version=v_work.version for share of p,ar;
  if not found or v_prior.plan_hash<>p_predecessor_plan_hash
     or exists(select 1 from ops.engineering_stale_contract_fence f
       where (f.plan_ref=v_prior.plan_ref or f.plan_hash=v_prior.plan_hash)
         and not f.successor_allowed) then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_predecessor_stale');
  end if;
  if exists(select 1 from ops.ready_plan_amendment a
    where a.work_request_id=v_work.id and a.predecessor_plan_id=v_prior.id) then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_fork_exists');
  end if;
  select s.id,r.id,r.content_hash into v_section,v_revision,v_hash
    from public.doctrine_document d join public.doctrine_section s on s.document_id=d.id
    join public.doctrine_revision r on r.id=s.current_revision_id
   where d.slug='runbook' and s.status='active'
     and 'doctrine:'||d.slug||'#'||s.section_key=btrim(p_runbook_ref)
     and r.section_id=s.id and encode(public.digest(r.plain_text,'sha256'),'hex')=r.content_hash
   for share of d,s,r;
  if not found then return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_runbook_stale'); end if;
  select coalesce(max(plan_version),0)+1 into v_version from ops.sourced_work_request_plan where work_request_id=v_work.id;
  v_preimage:=ops.sourced_work_request_plan_preimage(v_work.id,btrim(p_scope_summary),btrim(p_runbook_ref),
    v_section,v_revision,v_hash,p_dependency_refs,btrim(p_recovery_ref),btrim(p_observability_ref),p_caps)
    ||jsonb_build_object('successor_of',jsonb_build_object('plan_id',v_prior.id,'plan_ref',v_prior.plan_ref,'plan_hash',v_prior.plan_hash));
  v_plan_hash:=ops.sourced_work_request_plan_digest(v_preimage);
  if ops.engineering_contract_stale(null,v_plan_hash,null) then
    return jsonb_build_object('ok',false,'reason_id','ready_plan_amendment_plan_stale');
  end if;
  insert into ops.sourced_work_request_plan(work_request_id,plan_version,idempotency_key,work_request_version,
    preimage,scope_summary,runbook_ref,runbook_section_id,runbook_revision_id,runbook_content_hash,
    dependency_refs,recovery_ref,observability_ref,caps,plan_hash,plan_ref)
  values(v_work.id,v_version,p_idempotency_key,v_work.version,v_preimage,btrim(p_scope_summary),btrim(p_runbook_ref),
    v_section,v_revision,v_hash,p_dependency_refs,btrim(p_recovery_ref),btrim(p_observability_ref),p_caps,
    v_plan_hash,'PLAN-'||substr(v_plan_hash,8,12)||'-v'||v_version)
  returning * into v_plan;
  v_amendment_hash:=ops.heavy_build_digest(jsonb_build_object('contract','carr-ready-plan-amendment/v1',
    'work_request_id',v_work.id,'base_version',v_work.version,'predecessor_plan_hash',v_prior.plan_hash,
    'successor_plan_hash',v_plan.plan_hash));
  insert into ops.ready_plan_amendment(plan_id,work_request_id,predecessor_plan_id,
    predecessor_plan_hash,base_version,amendment_hash,proposed_by_actor_id)
  values(v_plan.id,v_work.id,v_prior.id,v_prior.plan_hash,v_work.version,v_amendment_hash,v_actor);
  v_classification:=ops.heavy_build_classification(v_work.id,v_plan.scope_summary,
    v_plan.dependency_refs,v_plan.caps);
  v_reasons:=case when v_classification->>'tier'='heavy' then v_classification->'reasons'
    else jsonb_build_array('caller:explicit-heavy-contract') end;
  select * into v_admission from ops.record_sourced_heavy_build_admission(
    v_plan.id,p_work_request,p_base_version,v_reasons,p_heavy_build,
    p_proposed_by_actor_id,p_idempotency_key);
  return jsonb_build_object('ok',true,'replayed',false,
    'work_request',jsonb_build_object('id',v_work.id,'ref',v_work.ref,'state',v_work.state,'version',v_work.version),
    'plan',jsonb_build_object('id',v_plan.id,'ref',v_plan.plan_ref,'hash',v_plan.plan_hash,'version',v_plan.plan_version,
      'predecessor_ref',v_prior.plan_ref,'predecessor_hash',v_prior.plan_hash),
    'build_admission',jsonb_build_object('tier',v_admission.tier,'reasons',v_admission.classifier_reasons,
      'admission_ref',v_admission.admission_ref,'admission_hash',v_admission.admission_hash,
      'builder_session_ref',v_admission.builder_session_ref));
end $_$;


--
-- Name: propose_sourced_work_request_outcome_feedback(text, integer, text, jsonb, jsonb, text, text, integer, text, boolean, integer, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_sourced_work_request_outcome_feedback(p_work_request text, p_base_version integer, p_plan_hash text, p_criterion_results jsonb, p_evidence_refs jsonb, p_blocker_code text, p_result_summary text, p_observed_minutes integer, p_interaction_surface text, p_heavy_session_used boolean, p_manual_context_transfers integer, p_idempotency_key uuid) RETURNS TABLE(feedback_id uuid, feedback_ref text, feedback_hash text, work_request_id uuid, ref text, state text, version integer, plan_id uuid, plan_ref text, plan_hash text, outcome text, criterion_results jsonb, evidence_refs jsonb, blocker_code text, result_summary text, observed_minutes integer, interaction_surface text, heavy_session_used boolean, manual_context_transfers integer, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype; p ops.sourced_work_request_plan%rowtype;
  ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
  f ops.sourced_work_request_outcome_feedback%rowtype;
  normalized_summary text; derived_outcome text; next_feedback_version integer;
  canonical_preimage jsonb; canonical_hash text;
begin
  normalized_summary := btrim(p_result_summary);
  if coalesce(btrim(p_work_request),'') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1
     or coalesce(p_plan_hash,'') !~ '^sha256:[0-9a-f]{64}$'
     or p_idempotency_key is null
     or coalesce(normalized_summary,'')='' or char_length(normalized_summary)>500
     or p_observed_minutes is null or p_observed_minutes not between 1 and 1440
     or p_interaction_surface not in ('workspace','control_room','mcp','codex','claude_code','other')
     or p_heavy_session_used is null
     or p_manual_context_transfers is null or p_manual_context_transfers not between 0 and 100
     or p_blocker_code not in ('none','evidence_missing','criterion_not_met','external_dependency','system_error')
     or jsonb_typeof(p_criterion_results) is distinct from 'array'
     or jsonb_typeof(p_evidence_refs) is distinct from 'array'
     or jsonb_array_length(p_evidence_refs) not between 1 and 12
     or exists (select 1 from jsonb_array_elements(p_evidence_refs) v
                 where jsonb_typeof(v) <> 'string'
                    or v #>> '{}' !~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
                    or char_length(v #>> '{}') > 300)
     or exists (select v #>> '{}' from jsonb_array_elements(p_evidence_refs) v
                 group by v #>> '{}' having count(*) > 1)
     or exists (select 1 from jsonb_array_elements(p_criterion_results) v
                 where jsonb_typeof(v) <> 'object'
                    or (select array_agg(k order by k) from jsonb_object_keys(v) k)
                         is distinct from array['id','result']::text[]
                    or coalesce(v->>'id','') !~ '^[A-Z][A-Z0-9-]{1,63}$'
                    or v->>'result' not in ('met','not_met','not_observed'))
     or exists (select v->>'id' from jsonb_array_elements(p_criterion_results) v
                 group by v->>'id' having count(*) > 1) then
    raise exception 'outcome feedback requires exact ready plan/version, full criterion results, safe evidence references, bounded observed facts, blocker, summary, and UUID idempotency key';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-outcome-feedback-proposal:' || p_idempotency_key,0));
  select x.* into f from ops.sourced_work_request_outcome_feedback x
   where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into w from ops.work_request x where x.id=f.work_request_id for share;
    select x.* into p from ops.sourced_work_request_plan x where x.id=f.plan_id for share;
    if not found or w.ref is distinct from p_work_request
       or f.work_request_version is distinct from p_base_version
       or p.plan_hash is distinct from p_plan_hash or f.criterion_results is distinct from p_criterion_results
       or f.evidence_refs is distinct from p_evidence_refs or f.blocker_code is distinct from p_blocker_code
       or f.result_summary is distinct from normalized_summary or f.observed_minutes is distinct from p_observed_minutes
       or f.interaction_surface is distinct from p_interaction_surface or f.heavy_session_used is distinct from p_heavy_session_used
       or f.manual_context_transfers is distinct from p_manual_context_transfers then
      raise exception 'idempotency key already names different sourced outcome feedback proposal';
    end if;
    return query select f.id,f.feedback_ref,f.feedback_hash,w.id,w.ref,'ready'::text,f.work_request_version,
      p.id,p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,
      f.result_summary,f.observed_minutes,f.interaction_surface,f.heavy_session_used,
      f.manual_context_transfers,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref=p_work_request for update;
  if not found then raise exception 'exact sourced Work Request not found'; end if;
  select x.* into p from ops.sourced_work_request_plan x
   join ops.sourced_work_request_plan_acceptance_receipt ar0 on ar0.plan_id=x.id
   where x.work_request_id=w.id and x.plan_hash=p_plan_hash for share of x;
  select x.* into ar from ops.sourced_work_request_plan_acceptance_receipt x
   where x.work_request_id=w.id and x.plan_id=p.id for share;
  if not found or w.capture_idempotency_key is null
     or w.organization_tenant_id is distinct from 'carr-internal'
     or w.state is distinct from 'ready' or w.version is distinct from p_base_version
     or p.work_request_version >= w.version or ar.result_version is distinct from w.version
     or ar.plan_hash is distinct from p.plan_hash
     or (w.shape_fixed_surface_ref is distinct from ar.shape_fixed_surface_ref
         and not exists (
           select 1 from ops.sourced_work_request_plan_shape_binding_receipt sb
            where sb.plan_acceptance_receipt_id = ar.id
              and sb.work_request_id = w.id
              and sb.disposition is not distinct from w.shape_disposition
              and sb.fixed_surface_ref is not distinct from w.shape_fixed_surface_ref
              and exists (select 1 from ops.sourced_work_request_shape_disposition_lineage(w.id) e
                           where (e.disposition,e.fixed_surface_ref,e.rationale,e.decided_by_actor_id,e.decided_at)
                             is not distinct from (sb.disposition,sb.fixed_surface_ref,sb.rationale,sb.decided_by_actor_id,sb.decided_at)))) then
    raise exception 'only an exact current ready sourced plan may receive outcome feedback';
  end if;
  if (select array_agg(v->>'id' order by v->>'id') from jsonb_array_elements(p_criterion_results) v)
       is distinct from
     (select array_agg(v->>'id' order by v->>'id') from jsonb_array_elements(w.acceptance_criteria) v) then
    raise exception 'outcome feedback criterion results must name the exact full Work Request acceptance-criteria ID set';
  end if;
  if exists (select 1 from jsonb_array_elements(p_criterion_results) v where v->>'result'='not_met') then
    derived_outcome := 'criteria_not_met';
  elsif exists (select 1 from jsonb_array_elements(p_criterion_results) v where v->>'result'='not_observed') then
    derived_outcome := 'inconclusive';
  else
    derived_outcome := 'criteria_met';
  end if;
  if (derived_outcome='criteria_met' and p_blocker_code <> 'none')
     or (derived_outcome='criteria_not_met' and p_blocker_code='none')
     or (derived_outcome='inconclusive' and p_blocker_code not in ('evidence_missing','external_dependency','system_error')) then
    raise exception 'outcome feedback blocker is inconsistent with its derived criterion outcome';
  end if;

  select coalesce(max(x.feedback_version),0)+1 into next_feedback_version
    from ops.sourced_work_request_outcome_feedback x where x.work_request_id=w.id;
  canonical_preimage := ops.sourced_work_request_outcome_feedback_preimage(
    w.id,p.id,ar.id,p_criterion_results,p_evidence_refs,derived_outcome,p_blocker_code,
    normalized_summary,p_observed_minutes,p_interaction_surface,p_heavy_session_used,
    p_manual_context_transfers);
  canonical_hash := ops.sourced_work_request_outcome_feedback_digest(canonical_preimage);
  if canonical_preimage is null or canonical_hash is null then
    raise exception 'exact ready-plan outcome-feedback preimage is unavailable';
  end if;
  if exists (select 1 from ops.sourced_work_request_outcome_feedback x
              where x.work_request_id=w.id and x.feedback_hash=canonical_hash) then
    raise exception 'the exact sourced outcome feedback already exists under a different idempotency key';
  end if;
  insert into ops.sourced_work_request_outcome_feedback
    (work_request_id,feedback_version,idempotency_key,work_request_version,plan_id,
     plan_acceptance_receipt_id,preimage,criterion_results,evidence_refs,outcome,
     blocker_code,result_summary,observed_minutes,interaction_surface,heavy_session_used,
     manual_context_transfers,feedback_hash,feedback_ref)
  values
    (w.id,next_feedback_version,p_idempotency_key,w.version,p.id,ar.id,canonical_preimage,
     p_criterion_results,p_evidence_refs,derived_outcome,p_blocker_code,normalized_summary,
     p_observed_minutes,p_interaction_surface,p_heavy_session_used,p_manual_context_transfers,
     canonical_hash,'OUTCOME-' || substr(canonical_hash,8,12) || '-v' || next_feedback_version)
  returning * into f;
  return query select f.id,f.feedback_ref,f.feedback_hash,w.id,w.ref,w.state,w.version,
    p.id,p.plan_ref,p.plan_hash,f.outcome,f.criterion_results,f.evidence_refs,f.blocker_code,
    f.result_summary,f.observed_minutes,f.interaction_surface,f.heavy_session_used,
    f.manual_context_transfers,false;
end;
$_$;


--
-- Name: propose_sourced_work_request_plan(text, integer, text, text, jsonb, text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.propose_sourced_work_request_plan(p_work_request text, p_base_version integer, p_scope_summary text, p_runbook_ref text, p_dependency_refs jsonb, p_recovery_ref text, p_observability_ref text, p_caps jsonb, p_idempotency_key uuid) RETURNS TABLE(plan_id uuid, plan_ref text, plan_hash text, work_request_id uuid, ref text, state text, version integer, runbook_ref text, runbook_revision_id uuid, runbook_content_hash text, scope_summary text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype; p ops.sourced_work_request_plan%rowtype;
  rb_section_id uuid; rb_revision_id uuid; rb_content_hash text;
  normalized_scope text; normalized_runbook text; normalized_recovery text; normalized_observability text;
  next_plan_version integer; canonical_preimage jsonb; canonical_hash text;
begin
  normalized_scope := btrim(p_scope_summary); normalized_runbook := btrim(p_runbook_ref);
  normalized_recovery := btrim(p_recovery_ref); normalized_observability := btrim(p_observability_ref);
  if p_idempotency_key is null or p_base_version is null or p_base_version < 1
     or coalesce(normalized_scope,'') = '' or char_length(normalized_scope) > 1000
     or coalesce(normalized_runbook,'') !~ '^doctrine:runbook#[a-z0-9][a-z0-9-]*$'
     or coalesce(normalized_recovery,'') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(normalized_recovery) > 300
     or coalesce(normalized_observability,'') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(normalized_observability) > 300 then
    raise exception 'invalid bounded sourced plan';
  end if;
  if jsonb_typeof(p_dependency_refs) is distinct from 'array' or jsonb_array_length(p_dependency_refs) > 12
     or exists (select 1 from jsonb_array_elements(p_dependency_refs) v where jsonb_typeof(v) <> 'string' or v #>> '{}' !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(v #>> '{}') > 300)
     or exists (select v #>> '{}' from jsonb_array_elements(p_dependency_refs) v group by v #>> '{}' having count(*) > 1) then
    raise exception 'invalid bounded sourced plan dependency references';
  end if;
  if jsonb_typeof(p_caps) is distinct from 'object'
     or ((select array_agg(k order by k) from jsonb_object_keys(p_caps) k)
           is distinct from array['max_duration_minutes','max_steps']::text[]
         and (select array_agg(k order by k) from jsonb_object_keys(p_caps) k)
           is distinct from array['max_duration_minutes','max_steps','source_merge']::text[])
     or coalesce(p_caps->>'max_steps','') !~ '^[0-9]+$' or coalesce(p_caps->>'max_duration_minutes','') !~ '^[0-9]+$'
     or (p_caps->>'max_steps')::integer not between 1 and 20 or (p_caps->>'max_duration_minutes')::integer not between 1 and 120
     or (p_caps ? 'source_merge' and not coalesce(ops.source_merge_scope_valid(p_caps->'source_merge'),false)) then
    raise exception 'invalid bounded sourced plan caps';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-plan-proposal:' || p_idempotency_key, 0));
  select x.* into p from ops.sourced_work_request_plan x where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into w from ops.work_request x where x.id=p.work_request_id for share;
    if not found or w.ref is distinct from p_work_request or p.work_request_version is distinct from p_base_version
       or p.scope_summary is distinct from normalized_scope or p.runbook_ref is distinct from normalized_runbook
       or p.dependency_refs is distinct from p_dependency_refs or p.recovery_ref is distinct from normalized_recovery
       or p.observability_ref is distinct from normalized_observability or p.caps is distinct from p_caps then
      raise exception 'idempotency key already names a different sourced plan proposal';
    end if;
    return query select p.id,p.plan_ref,p.plan_hash,w.id,w.ref,'triaged'::text,p.work_request_version,
      p.runbook_ref,p.runbook_revision_id,'sha256:' || p.runbook_content_hash,p.scope_summary,true;
    return;
  end if;

  select x.* into w from ops.work_request x where x.ref=p_work_request for update;
  if not found or w.state is distinct from 'triaged' or w.version is distinct from p_base_version
     or w.capture_idempotency_key is null or w.organization_tenant_id is distinct from 'carr-internal' then
    raise exception 'exact current triaged sourced Work Request required';
  end if;
  if not (
    ((w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
       is not distinct from (null::text,null::text,null::text,null::uuid,null::timestamptz)
      and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id=w.id))
    or
    (w.shape_disposition='required' and w.shape_fixed_surface_ref is null and w.shape_rationale is not null and btrim(w.shape_rationale) <> ''
      and exists (select 1 from ops.effective_sourced_work_request_shape_disposition(w) e where e.disposition='required')
      and (select sr.work_request_version from ops.work_shape_revision sr where sr.work_request_id=w.id order by sr.version desc limit 1)=w.version)
    or
    (w.shape_disposition='not_required' and w.shape_fixed_surface_ref is not null and btrim(w.shape_fixed_surface_ref) <> ''
      and w.shape_rationale is not null and btrim(w.shape_rationale) <> ''
      and exists (select 1 from ops.effective_sourced_work_request_shape_disposition(w) e where e.disposition='not_required')
      and not exists (select 1 from ops.work_shape_revision sr where sr.work_request_id=w.id))
  ) then
    raise exception 'exact unshaped or current receipt-backed shaped triaged sourced Work Request required';
  end if;

  perform 1 from public.doctrine_document source_document join public.doctrine_section source_section on source_section.document_id=source_document.id
    join public.doctrine_revision source_revision on source_revision.id=source_section.current_revision_id and source_revision.section_id=source_section.id
   where source_document.visibility='shared' and source_section.status='active' and source_section.id=w.doctrine_section_id
     and source_revision.id=w.doctrine_revision_id and source_revision.content_hash ~ '^[0-9a-f]{64}$'
     and encode(public.digest(source_revision.plain_text,'sha256'),'hex')=source_revision.content_hash
     and source_revision.body=jsonb_build_object('text',source_revision.plain_text)
   for share of source_document,source_section,source_revision;
  if not found then raise exception 'sourced Work Request evidence is no longer exact, current, active, and shared'; end if;
  select s.id,r.id,r.content_hash into rb_section_id,rb_revision_id,rb_content_hash
    from public.doctrine_document d join public.doctrine_section s on s.document_id=d.id
    join public.doctrine_revision r on r.id=s.current_revision_id and r.section_id=s.id
   where d.slug='runbook' and d.visibility='shared' and s.status='active'
     and ('doctrine:' || d.slug || '#' || s.section_key)=normalized_runbook and r.content_hash ~ '^[0-9a-f]{64}$'
     and encode(public.digest(r.plain_text,'sha256'),'hex')=r.content_hash and r.body=jsonb_build_object('text',r.plain_text)
   for share of d,s,r;
  if not found then raise exception 'runbook must be an exact current active shared doctrine revision'; end if;
  select coalesce(max(x.plan_version),0)+1 into next_plan_version from ops.sourced_work_request_plan x where x.work_request_id=w.id;
  canonical_preimage := ops.sourced_work_request_plan_preimage(w.id,normalized_scope,normalized_runbook,rb_section_id,rb_revision_id,rb_content_hash,p_dependency_refs,normalized_recovery,normalized_observability,p_caps);
  canonical_hash := ops.sourced_work_request_plan_digest(canonical_preimage);
  if exists (select 1 from ops.sourced_work_request_plan x where x.work_request_id=w.id and x.plan_hash=canonical_hash) then
    raise exception 'the exact sourced plan already exists under a different idempotency key';
  end if;
  insert into ops.sourced_work_request_plan (work_request_id,plan_version,idempotency_key,work_request_version,preimage,scope_summary,runbook_ref,runbook_section_id,runbook_revision_id,runbook_content_hash,dependency_refs,recovery_ref,observability_ref,caps,plan_hash,plan_ref)
  values (w.id,next_plan_version,p_idempotency_key,w.version,canonical_preimage,normalized_scope,normalized_runbook,rb_section_id,rb_revision_id,rb_content_hash,p_dependency_refs,normalized_recovery,normalized_observability,p_caps,canonical_hash,'PLAN-' || substr(canonical_hash,8,12) || '-v' || next_plan_version)
  returning * into p;
  return query select p.id,p.plan_ref,p.plan_hash,w.id,w.ref,w.state,w.version,p.runbook_ref,p.runbook_revision_id,'sha256:' || p.runbook_content_hash,p.scope_summary,false;
end;
$_$;


--
-- Name: protect_staging_readback_deployment(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.protect_staging_readback_deployment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (select 1 from ops.staging_release_readback_receipt where deployment_id=old.id) then
    raise exception 'Program 5 evidence deployment is append-only';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


--
-- Name: put_cognition_cache(text, text, integer, integer, jsonb, text[], integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.put_cognition_cache(p_cache_key text, p_cognition_key text, p_cognition_version integer, p_output_schema_version integer, p_proposal jsonb, p_dependency_refs text[], p_ttl_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if p_ttl_seconds < 1 then raise exception 'positive cache TTL is required'; end if;
  insert into ops.cognition_result_cache
    (cache_key,cognition_key,cognition_version,output_schema_version,proposal,
     dependency_refs,validated_at,expires_at)
  values(p_cache_key,p_cognition_key,p_cognition_version,p_output_schema_version,p_proposal,
         coalesce(p_dependency_refs,'{}'),now(),now()+make_interval(secs=>p_ttl_seconds))
  on conflict(cache_key) do update set
    proposal=excluded.proposal,dependency_refs=excluded.dependency_refs,
    validated_at=excluded.validated_at,expires_at=excluded.expires_at,invalidated_at=null;
  return true;
end $$;


--
-- Name: put_cognition_cache_for_job(uuid, uuid, text, text, integer, integer, jsonb, text[], integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.put_cognition_cache_for_job(p_job_id uuid, p_lease_token uuid, p_cache_key text, p_cognition_key text, p_cognition_version integer, p_output_schema_version integer, p_proposal jsonb, p_dependency_refs text[], p_ttl_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; execution_kind text; declared_cognition_key text; active_contract_count integer; contract ops.cognition_job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select d.execution_kind,d.execution_contract->>'cognition_job'
    into execution_kind,declared_cognition_key from ops.job_definition d
   where d.key=j.definition_key and d.version=j.definition_version;
  if execution_kind is distinct from 'cognition'
     or declared_cognition_key is distinct from p_cognition_key then
    raise exception 'job % is not bound to cognition contract %',p_job_id,p_cognition_key;
  end if;
  select count(*) into active_contract_count from ops.cognition_job where key=declared_cognition_key and active;
  if active_contract_count <> 1 then raise exception 'job % lacks one active cognition contract',p_job_id; end if;
  select * into contract from ops.cognition_job where key=declared_cognition_key and active;
  if p_cognition_key<>contract.key or p_cognition_version<>contract.version
     or p_output_schema_version<>contract.output_schema_version then
    raise exception 'cache write does not match active cognition contract';
  end if;
  if btrim(coalesce(p_cache_key,''))='' or p_ttl_seconds<1 then
    raise exception 'cache key and positive cache TTL are required';
  end if;
  insert into ops.cognition_result_cache
    (cache_key,cognition_key,cognition_version,output_schema_version,proposal,
     dependency_refs,validated_at,expires_at)
  values (p_cache_key,p_cognition_key,p_cognition_version,p_output_schema_version,p_proposal,
          coalesce(p_dependency_refs,'{}'),now(),now()+make_interval(secs=>p_ttl_seconds))
  on conflict(cache_key) do update set proposal=excluded.proposal,
    dependency_refs=excluded.dependency_refs,validated_at=excluded.validated_at,
    expires_at=excluded.expires_at,invalidated_at=null;
  insert into ops.cognition_cache_observation
    (job_id,attempt,workflow_key,workflow_version,mode,cache_key,observation_kind)
  values (j.id,j.attempt,j.definition_key,j.definition_version,j.mode,p_cache_key,'store')
  on conflict (job_id,attempt,cache_key,observation_kind) do nothing;
  return true;
end $$;


--
-- Name: qualify_program5_release(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.qualify_program5_release(p_release_key text, p_plan_hash text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare rel ops.release%rowtype; prior ops.release_readiness_receipt%rowtype;
  rehearsal uuid; stamp timestamptz; digest_value text; receipt_id uuid;
begin
  if session_user<>'carr_jobs' then
    raise exception 'release readiness requires the authenticated jobs service';
  end if;
  if p_idempotency_key is null or p_plan_hash is null
     or p_plan_hash !~ '^plan:[0-9a-f]{32}$' then
    raise exception 'invalid release readiness input';
  end if;
  select * into prior from ops.release_readiness_receipt
    where idempotency_key=p_idempotency_key;
  if found then
    select * into rel from ops.release where id=prior.release_id for update;
    if not found or prior.plan_hash is distinct from p_plan_hash
       or rel.release_key is distinct from p_release_key
       or rel.readiness_receipt_id is distinct from prior.id
       or rel.git_sha is distinct from prior.git_sha
       or rel.provider is distinct from prior.provider
       or rel.provider_version_id is distinct from prior.provider_version_id
       or rel.plan_hash is distinct from prior.plan_hash then
      raise exception 'readiness idempotency key was reused with changed input';
    end if;
    if rel.state='candidate' then
      rehearsal:=ops.program5_exact_recovery_rehearsal(
        rel.id,clock_timestamp()-interval '24 hours');
      if rehearsal is null or rehearsal=prior.recovery_run_id then
        raise exception 'reopened release has no new fresh exact typed recovery rehearsal';
      end if;
      update ops.release set state='ready' where id=rel.id;
      return jsonb_build_object('readiness_receipt_id',prior.id,
        'ready_at',prior.ready_at,'replayed',true,'refreshed',true,
        'current_recovery_run_id',rehearsal);
    end if;
    return jsonb_build_object('readiness_receipt_id',prior.id,
      'ready_at',prior.ready_at,'replayed',true,'refreshed',false);
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment is distinct from 'production'
     or rel.state is distinct from 'candidate'
     or rel.plan_hash is distinct from p_plan_hash
     or rel.provider is distinct from 'cloudflare-workers'
     or coalesce(rel.provider_version_id,'') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or rel.maker_session_user is distinct from 'carr_jobs'
     or rel.maker_actor is distinct from 'carr_jobs'
     or rel.maker_authority_verified is distinct from false
     or rel.approved_by_actor is not null or rel.approval_receipt_id is not null
     or rel.artifact_digest is null or rel.dependency_lock_digest is null
     or rel.test_evidence_ref is null or rel.security_evidence_ref is null
     or rel.verifier_actor is null or rel.verifier_evidence_ref is null
     or rel.verifier_actor=rel.maker_actor or rel.rollback_ready is not true
     or rel.performance_budget_ref is null or coalesce(rel.performance_budget_ms,0)<=0
     or rel.recovery_strategy is null
     or rel.recovery_strategy not in ('rollback','forward_fix')
     or rel.rollback_plan_ref is null then
    raise exception 'release is not an independently verified exact Production candidate';
  end if;
  stamp:=clock_timestamp();
  rehearsal:=ops.program5_exact_recovery_rehearsal(rel.id,stamp-interval '24 hours');
  if rehearsal is null then raise exception 'release has no fresh exact typed recovery rehearsal'; end if;
  digest_value:='sha256:'||encode(public.digest(
    jsonb_build_object('release_id',rel.id,'git_sha',rel.git_sha,
      'provider',rel.provider,'provider_version_id',rel.provider_version_id,
      'plan_hash',rel.plan_hash,'recovery_run_id',rehearsal,
      'verifier_actor',rel.verifier_actor,
      'verifier_evidence_ref',rel.verifier_evidence_ref,
      'session_login',session_user,'ready_at',stamp)::text,'sha256'),'hex');
  insert into ops.release_readiness_receipt
    (idempotency_key,release_id,git_sha,provider,provider_version_id,plan_hash,
     recovery_run_id,verifier_actor,verifier_evidence_ref,session_login,ready_at,receipt_sha256)
  values(p_idempotency_key,rel.id,rel.git_sha,rel.provider,rel.provider_version_id,
    rel.plan_hash,rehearsal,rel.verifier_actor,rel.verifier_evidence_ref,
    session_user,stamp,digest_value) returning id into receipt_id;
  update ops.release set state='ready',ready_at=stamp,
    readiness_receipt_id=receipt_id where id=rel.id;
  return jsonb_build_object('readiness_receipt_id',receipt_id,
    'ready_at',stamp,'replayed',false);
end $_$;


--
-- Name: read_attempt_receipt_reliability(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_attempt_receipt_reliability(p_attempt_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id',true); receipt_row ops.attempt_receipt%rowtype; envelope_row ops.execution_envelope_v1%rowtype;
  expected jsonb; have jsonb; final_state text; reasons jsonb; binding ops.context_activation_binding%rowtype; candidate_refs jsonb; lifecycle_value text; telemetry jsonb; authority_fact_count integer; learning_event_count integer; outcome_horizon_mature boolean;
begin
  select * into receipt_row from ops.attempt_receipt where organization_tenant_id=tenant and attempt_id=p_attempt_id;
  select * into envelope_row from ops.execution_envelope_v1 where id=receipt_row.execution_envelope_id and organization_tenant_id=tenant;
  select * into binding from ops.context_activation_binding where id=receipt_row.activation_binding_id and organization_tenant_id=tenant;
  if receipt_row.id is null or envelope_row.id is null then raise exception 'attempt reliability is not visible to tenant'; end if;
  select coalesce(jsonb_agg(value order by value),'[]'::jsonb) into expected from jsonb_array_elements_text(envelope_row.evaluation_plan->'required_deterministic_check_refs') value;
  -- Projection ordering is server-derived, not room arrival order.  Each
  -- append-only authority fact/event can only raise its count; the horizon
  -- bit can only advance from immature to mature for the frozen issued plan.
  select count(*)::integer into authority_fact_count from ops.attempt_receipt_evaluation_attestation where attempt_receipt_id=receipt_row.id;
  select count(*)::integer into learning_event_count from ops.proposed_eval_candidate_event e join ops.proposed_eval_candidate p on p.id=e.candidate_id where p.attempt_receipt_id=receipt_row.id;
  outcome_horizon_mature := clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz;
  select coalesce(jsonb_agg(a.check_ref order by a.check_ref),'[]'::jsonb) into have from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='deterministic' and a.status='passed';
  if exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='deterministic' and a.status in ('failed','blocked')) then
    final_state := 'blocked'; reasons := jsonb_build_array('reason:critical_deterministic_or_evaluator_failure');
  elsif exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='judge' and a.independent and a.status in ('failed','blocked'))
     or exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='human_acceptance' and a.status in ('failed','blocked')) then
    final_state := 'blocked'; reasons := jsonb_build_array('reason:critical_authority_evaluator_or_human_rejection');
  elsif have is distinct from expected
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='judge' and a.status='passed' and a.independent and a.confidence in ('high','medium') and a.lower_bound_ref is not null and jsonb_array_length(a.calibration_refs) >= coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_calibration_ref_count')::integer,1) and a.held_out_case_count >= coalesce((envelope_row.evaluation_plan->'requirements'->>'minimum_held_out_case_count')::integer,1))
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='human_acceptance' and a.status='passed' and a.outcome_feedback_ref is not null and a.outcome_feedback_hash is not null)
     or not exists (select 1 from ops.attempt_receipt_evaluation_attestation a where a.attempt_receipt_id=receipt_row.id and a.evaluator_kind='outcome_horizon' and a.status='mature' and clock_timestamp() >= (envelope_row.evaluation_plan->>'outcome_horizon_not_before')::timestamptz) then
    final_state := 'insufficient_evidence'; reasons := jsonb_build_array('reason:canonical_evaluation_coverage_incomplete');
  else final_state := 'eligible_for_human_review'; reasons := '[]'::jsonb;
  end if;
  select coalesce(jsonb_agg('candidate:'||p.id::text order by p.created_at,p.id),'[]'::jsonb), coalesce((array_agg(e.event_kind order by e.created_at desc,e.id desc))[1],'none') into candidate_refs,lifecycle_value from ops.proposed_eval_candidate p left join lateral (select id,event_kind,created_at from ops.proposed_eval_candidate_event where candidate_id=p.id order by created_at desc,id desc limit 1) e on true where p.attempt_receipt_id=receipt_row.id;
  select coalesce(jsonb_agg(jsonb_build_object('signal_id',signal_id,'state',state,'trigger_ref',trigger_ref,'consumer_ref',consumer_ref,'enforcement',enforcement,'owner_ref',owner_ref,'remedy_ref',remedy_ref,'verification_ref',verification_ref,'auto_clear',auto_clear) order by signal_id),'[]'::jsonb) into telemetry from ops.activation_reliability_telemetry where attempt_receipt_id=receipt_row.id;
  return jsonb_build_object('canonical_binding',jsonb_build_object('work_request_id',(select ref from ops.work_request where id=receipt_row.work_request_id),'work_request_version',binding.work_request_version,'accepted_plan_digest',receipt_row.plan_hash,'envelope_digest',receipt_row.envelope_digest,'attempt_id',receipt_row.attempt_id,'activation_binding_ref',binding.binding_id),'canonical_revision',jsonb_build_object('authority_fact_count',authority_fact_count,'learning_event_count',learning_event_count,'outcome_horizon_mature',outcome_horizon_mature),'learning',jsonb_build_object('lifecycle',lifecycle_value,'candidate_refs',candidate_refs),'telemetry',telemetry,'reliability',jsonb_build_object('state',final_state,'reasons',reasons,'derived_by','canonical_authority_evaluation','outcome_horizon_state',case when outcome_horizon_mature then 'mature' else 'immature' end,'outcome_horizon_not_before',envelope_row.evaluation_plan->>'outcome_horizon_not_before'));
end $$;


--
-- Name: read_calendar_prebrief_joe_activation(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_calendar_prebrief_joe_activation(p_id uuid) RETURNS TABLE(id uuid, sponsor text, app_evidence_digest text, allowlist_revision_id uuid, activated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$ select id,sponsor,app_evidence_digest,allowlist_revision_id,activated_at from ops.calendar_prebrief_runtime_activation_receipt where id=p_id and session_user='carr_authority_joe' $$;


--
-- Name: read_canonical_ownership_operation(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_canonical_ownership_operation(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare ctx jsonb:=ops.canonical_ownership_trusted_context(); result jsonb;
  l ops.canonical_ownership_lease%rowtype;
begin
  if not coalesce((ctx->>'ok')::boolean,false) then return ctx; end if;
  select response into result from ops.canonical_ownership_operation
   where idempotency_key=p_idempotency_key and runtime_binding_id=(ctx->>'binding_id')::uuid;
  if coalesce((result->>'ok')::boolean,false) and result ? 'lease_id' then
    select * into l from ops.canonical_ownership_lease where id=(result->>'lease_id')::uuid
      and holder_session_ref=ctx->>'ownership_session_ref'
      and subject_envelope_id=(ctx->>'subject_envelope_id')::uuid;
    if not found then return jsonb_build_object('ok',false,'reason_id','ownership_operation_subject_mismatch'); end if;
    result:=result||jsonb_build_object('lease_id',l.id,'lease_token',l.lease_token,'fencing_generation',l.fencing_generation);
  end if;
  return coalesce(result||jsonb_build_object('replayed',true),
    jsonb_build_object('ok',false,'reason_id','ownership_operation_not_found'));
end $$;


--
-- Name: read_context_activation(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_context_activation(p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  -- This is the source-linked read spine consumed by Job Passport, Model
  -- Room, Observatory, and Hermes.  It deliberately reports canary evidence
  -- as unavailable until a receipt/evaluation is recorded; it does not
  -- manufacture a production posture from the feature mode alone.
  select jsonb_build_object(
    'binding',to_jsonb(b),
    'items',coalesce(jsonb_agg(to_jsonb(i) order by i.ordinal),'[]'::jsonb),
    'execution_envelopes',(select coalesce(jsonb_agg(jsonb_build_object(
      'envelope_digest',e.envelope_digest,'runtime_profile',e.runtime_profile,
      'execution_topology',e.execution_topology,'evaluation_plan',e.evaluation_plan,
      'configuration_digest',e.configuration_digest,'issued_at',e.issued_at,'expires_at',e.expires_at
    ) order by e.issued_at),'[]'::jsonb) from ops.execution_envelope_v1 e where e.activation_binding_id=b.id),
    'attempt_receipts',(select coalesce(jsonb_agg(jsonb_build_object(
      'attempt_id',r.attempt_id,'envelope_digest',r.envelope_digest,
      'knowledge_activation',r.receipt->'knowledge_activation','reliability',r.receipt->'reliability','created_at',r.created_at
    ) order by r.created_at),'[]'::jsonb) from ops.attempt_receipt r where r.activation_binding_id=b.id),
    'learning',(select coalesce(jsonb_agg(jsonb_build_object(
      'candidate_ref',p.candidate_ref,'case_ref',p.case_ref,
      'lifecycle',coalesce((select event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=p.id order by pe.created_at desc,pe.id desc limit 1),p.lifecycle),
      'promotion_state',p.promotion_state,'provenance',p.provenance,
      'lane_ref',p.lane_ref,'risk_class',p.risk_class,'split_target',p.split_target,
      'source_digest',p.source_digest,'source_ref','attempt:'||r.attempt_id,
      'basis',p.basis,'created_at',p.created_at,
      'golden_membership',jsonb_build_object(
        'target_golden_set_ref',p.target_golden_set_ref,
        'ever_accepted',exists(select 1 from ops.accepted_eval_golden_membership gm where gm.candidate_id=p.id),
        'active',coalesce((select event_kind from ops.proposed_eval_candidate_event pe where pe.candidate_id=p.id order by pe.created_at desc,pe.id desc limit 1),'proposed')='accepted'
      )
    ) order by p.created_at,p.id),'[]'::jsonb) from ops.proposed_eval_candidate p join ops.attempt_receipt r on r.id=p.attempt_receipt_id where r.activation_binding_id=b.id),
    'evidence_register',jsonb_build_object(
      'work_request_ref',p_work_request,
      'source_ref','plan:'||b.plan_id::text,
      'source_digest',b.plan_hash,
      'admission_ref','activation:'||b.binding_id,
      'retrieval_evidence_ref','context-bundle:'||b.bundle_digest,
      'operator_surface','job-passport:context-activation',
      'telemetry_ref','observatory:activation-reliability:'||b.binding_id,
      'canary',jsonb_build_object('posture',b.mode,
        'evidence_availability',case when exists(select 1 from ops.attempt_receipt r where r.activation_binding_id=b.id) then 'recorded_redacted' else 'not_recorded' end,
        'evidence_ref',case when exists(select 1 from ops.attempt_receipt r where r.activation_binding_id=b.id) then 'attempt-receipt:'||b.binding_id else null end),
      'rollback_ref',coalesce((select recovery_ref from ops.sourced_work_request_plan where id=b.plan_id), 'not_configured'),
      'freshness',jsonb_build_object('state',case when b.expires_at < now() then 'stale' else 'fresh' end,'expires_at',b.expires_at),
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'source_ref',i.canonical_ref,'source_digest',i.content_digest,
        'consumer',i.consumer_ref,'trigger',i.trigger_ref,
        'admission_ref','activation:'||b.binding_id,
        'retrieval_evidence_ref','context-bundle:'||b.bundle_digest,
        'enforcement',case when i.required then 'must-apply' else 'advisory-only' end,
        'operator_surface','job-passport:context-activation',
        'telemetry_ref','observatory:activation-reliability:'||b.binding_id,
        'canary_posture',b.mode,
        'rollback_ref',coalesce((select recovery_ref from ops.sourced_work_request_plan where id=b.plan_id), 'not_configured'),
        'freshness',i.freshness
      ) order by i.ordinal),'[]'::jsonb)
    )
  )
    from ops.context_activation_binding b left join ops.context_activation_item i on i.binding_id=b.id
   where b.organization_tenant_id=current_setting('carr.organization_tenant_id', true)
     and b.binding_id=p_binding_id and b.work_request_id=(select id from ops.work_request where ref=p_work_request and organization_tenant_id=current_setting('carr.organization_tenant_id', true))
   group by b.id;
$$;


--
-- Name: read_doc_outcome_cards_successor(text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_doc_outcome_cards_successor(p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare actor_id uuid; actor_slug text; tenant text; page_limit integer;
  as_of timestamptz:=statement_timestamp(); scope_digest text; cursor jsonb;
  after_updated timestamptz; after_id uuid; result jsonb;
begin
  actor_id:=ops.portfolio_writer_actor_id();
  select slug into actor_slug from public.actor where id=actor_id and active;
  tenant:=nullif(current_setting('carr.organization_tenant_id',true),'');
  if actor_slug is null or tenant is null then
    return jsonb_build_object('ok',false,'reason_id','doc_outcome_actor_context_unavailable');
  end if;
  page_limit:=least(greatest(coalesce(p_limit,25),1),50);
  scope_digest:='sha256:'||encode(public.digest(convert_to(actor_id::text||E'\n'||tenant,'UTF8'),'sha256'),'hex');
  if p_cursor is not null then
    begin
      cursor:=convert_from(decode(p_cursor,'base64'),'UTF8')::jsonb;
      if jsonb_typeof(cursor)<>'object' or cursor->>'v'<>'2'
         or cursor->>'s'<>scope_digest then raise exception 'invalid cursor'; end if;
      as_of:=(cursor->>'a')::timestamptz; after_updated:=(cursor->>'u')::timestamptz;
      after_id:=(cursor->>'i')::uuid;
      if as_of>statement_timestamp() or as_of<statement_timestamp()-interval '24 hours' then raise exception 'stale cursor'; end if;
    exception when others then return jsonb_build_object('ok',false,'reason_id','doc_outcome_cursor_invalid');
    end;
  end if;
  with visible as (
    select w.*, greatest(w.updated_at,coalesce(s.updated_at,w.updated_at),coalesce(j.updated_at,w.updated_at),
      coalesce(e.issued_at,w.updated_at),coalesce(e.created_at,w.updated_at),coalesce(a.started_at,w.updated_at)) observed_at,
      s.id session_id,s.state session_state,s.updated_at session_updated_at,
      j.id job_id,j.state job_state,a.id job_attempt_id,e.id envelope_id,e.envelope,
      e.envelope#>>'{server_binding,adapter,surface}' native_surface
    from ops.work_request w
    left join lateral (select x.* from ops.engineering_execution_envelope x
      where x.work_request_id=w.id and x.issued_at<=as_of and x.created_at<=as_of
        and not exists(select 1 from ops.engineering_execution_envelope y
          where y.supersedes_envelope_id=x.id and y.issued_at<=as_of and y.created_at<=as_of)
      order by x.issued_at desc,x.id desc limit 1) e on true
    left join ops.job j on j.id=e.job_id and j.created_at<=as_of and j.updated_at<=as_of
    left join ops.capability_agent_session s on s.id=e.agent_session_id and s.work_request_id=w.id
      and s.created_at<=as_of and s.updated_at<=as_of
    left join lateral (select x.id,x.started_at from ops.job_attempt x
      where x.job_id=j.id and x.attempt=j.attempt and x.started_at<=as_of order by x.id limit 1) a on true
    where w.organization_tenant_id=tenant and (w.requester_actor=actor_slug or w.owner_actor=actor_slug or w.executor_actor=actor_slug)
      and w.desired_outcome is not null and w.updated_at<=as_of
      and (after_updated is null or (w.updated_at,w.id)<(after_updated,after_id))
  ), rows as (
    select *, case when observed_at<as_of-interval '24 hours' then 'unknown'
      when job_state in ('failed','timed_out','cancelled','dead_lettered') then 'failed'
      when job_state in ('retry_wait','waiting_approval') then 'waiting'
      when job_state='running' then 'active'
      when job_state='queued' then 'queued'
      when job_state='succeeded' and state in ('confirmed_closed','released') then 'verified'
      when job_id is not null then 'unknown'
      when state='failed' then 'failed' when state in ('blocked','needs_joe','awaiting_release') then 'waiting'
      when session_state in ('claimed','in_progress','verification') then 'active'
      when state in ('confirmed_closed','released') then 'verified'
      when state in ('captured','triaged','ready','claimed') then 'queued' else 'unknown' end routing_state
    from visible order by updated_at desc,id desc limit page_limit+1
  ), page as (select *,row_number() over(order by updated_at desc,id desc) rn from rows)
  select jsonb_build_object('ok',true,'schema_version','doc-outcome-cards.v2','as_of',as_of,
    'correlation_version','sha256:'||encode(public.digest(convert_to(scope_digest||E'\n'||as_of::text,'UTF8'),'sha256'),'hex'),
    'more',exists(select 1 from page where rn>page_limit),
    'next_cursor',case when exists(select 1 from page where rn>page_limit) then
      (select replace(encode(convert_to(jsonb_build_object('v',2,'s',scope_digest,'a',as_of,
        'u',p.updated_at,'i',p.id)::text,'UTF8'),'base64'),E'\n','')
       from page p where p.rn=page_limit) end,
    'cards',coalesce(jsonb_agg(jsonb_build_object(
      'card_id','card:doc-outcome:'||id::text,'requested_outcome',desired_outcome,
      'intent_kind',case when job_id is null then 'recommendation' else 'submission' end,
      'work_request_ref',ref,'owner',coalesce(owner_actor,executor_actor,requester_actor),'controlled_phase',state,
      'source_freshness',jsonb_build_object('state',case when observed_at>=as_of-interval '24 hours' then 'fresh' else 'stale' end,'observed_at',observed_at,'source_ref','work-request:'||ref),
      'routing_state',routing_state,'state_evidence',jsonb_build_object('observed_at',observed_at,'routing_source','canonical_work_request'),
      'job_id',jsonb_build_object('value',case when job_id is null then null else 'job:'||job_id::text end,'unavailable_reason',case when job_id is null then 'no_authoritative_job_join' end),
      'attempt_id',jsonb_build_object('value',case when job_attempt_id is null then null else 'job-attempt:'||job_attempt_id::text end,'unavailable_reason',case when job_attempt_id is null then 'no_authoritative_attempt_join' end),
      'canonical_session_id',jsonb_build_object('value',session_id,'unavailable_reason',case when session_id is null then 'no_authoritative_capability_session_join' end),
      'native_task_id',jsonb_build_object('value',null,'unavailable_reason','no_authoritative_native_task_join'),
      'next_check',jsonb_build_object('available',false,'value',null,'unavailable_reason','no_proved_next_check'),
      'result',jsonb_build_object('available',false,'value',null,'unavailable_reason','no_accepted_outcome'),
      'session_entry',jsonb_build_object('available',false,'target',null,'capability',null,
        'unavailable_reason',case when session_id is null then 'session_relation_unavailable'
          when native_surface not in ('codex_desktop','claude_desktop') then 'native_open_unsupported'
          when session_state not in ('cancelled','completed') and session_updated_at>=as_of-interval '2 hours' then 'host_available_but_native_task_unbound'
          else 'host_unavailable' end,
        'fallback',case when session_id is not null and native_surface in ('codex_desktop','claude_desktop')
          and (session_state in ('cancelled','completed') or session_updated_at<as_of-interval '2 hours')
          then jsonb_build_object('kind','copy_session_id','value',session_id::text) else null end,
        'auto_launch',false)
    ) order by updated_at desc,id desc) filter(where rn<=page_limit),'[]'::jsonb)) into result from page;
  return result;
end $$;


--
-- Name: read_execution_environment_providers(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_execution_environment_providers() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'provider_ref','environment-provider:'||p.provider_key||':v'||p.provider_version,
    'display_name',p.manifest->>'display_name','source_class',p.source_class,'backend_kind',p.backend_kind,
    'manifest_digest',p.manifest_digest,'state',ops.execution_environment_provider_current_state(p.id),
    'capability_refs',p.manifest->'capability_refs','isolation_class',p.manifest->>'isolation_class',
    'conformance',case when c.id is null then jsonb_build_object('state','unavailable') else jsonb_build_object(
      'state',c.status,'run_ref',c.run_ref,'run_digest',c.run_digest,'observed_at',c.observed_at,
      'manifest_digest',c.manifest_digest,'implementation_digest',c.implementation_digest,
      'package_digest',c.package_digest,'package_revision_ref',c.observation->>'package_revision_ref',
      'configuration_schema_digest',c.configuration_schema_digest) end,
    'evidence_register',jsonb_build_object(
      'source_ref',p.manifest->>'implementation_ref','source_digest',p.manifest->>'implementation_digest',
      'consumer_ref','consumer:hermes-bot-brief+execution-envelope','trigger_ref','trigger:work-request-execution-assignment',
      'admission_ref','admission:active+conformance-passed','retrieval_ref','tool:read-execution-environment-providers',
      'enforcement_ref','enforcement:assignment+envelope+receipt-db-triggers',
      'operator_surface','job-passport:route-and-agent-topology','telemetry_ref','observatory:execution-environment:'||p.provider_key,
      'canary',case when c.id is null then jsonb_build_object('state','unavailable') else jsonb_build_object('state',c.status,'evidence_refs',c.evidence_refs) end,
      'rollback_ref','rollback:human-active-to-disabled','freshness',case when c.id is null then jsonb_build_object('state','unavailable') else jsonb_build_object('state','observed','observed_at',c.observed_at) end),
    'operator_surface','job-passport:route-and-agent-topology','telemetry_ref','observatory:execution-environment:'||p.provider_key,
    'rollback','active-to-disabled-human-only','grants_authority',false) order by p.provider_key,p.provider_version),'[]'::jsonb)
  from ops.execution_environment_provider p
  left join lateral (select c.* from ops.execution_environment_conformance c where c.provider_id=p.id order by c.observed_at desc,c.id desc limit 1) c on true
$$;


--
-- Name: read_governance_queue(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_governance_queue() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'pending_rule_approvals', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rule_id', r.id, 'statement', r.statement, 'human_quote', r.human_quote,
        'scope', r.scope, 'taught_at', r.created_at,
        'enforcement_class', ra.enforcement_class, 'binding_moment', ra.binding_moment,
        'admission_reason', ra.reason, 'enforcement_status', ra.enforcement_status,
        'fixture_refs', ra.fixture_refs, 'admitted_at', ra.admitted_at
      ) order by ra.admitted_at asc, r.id)
      from rule r join ops.rule_admission ra on ra.rule_id = r.id
      where r.status = 'proposed' and ra.state = 'admitted'
    ), '[]'::jsonb),
    'pending_guidance_import_batches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'batch_id', b.id, 'manifest_digest', b.manifest_digest, 'reason', b.reason,
        'staging_key', b.staging_key, 'staged_at', b.created_at,
        'entry_count', (select count(*) from ops.guidance_import_entry e where e.batch_id = b.id)
      ) order by b.created_at asc, b.id)
      from ops.guidance_import_batch b
      where not exists (select 1 from ops.guidance_import_decision_event d where d.batch_id = b.id)
    ), '[]'::jsonb),
    'pending_retrieval_proposals', coalesce((
      select jsonb_agg(jsonb_build_object(
        'proposal_id', p.id, 'proposal_type', p.proposal_type, 'payload', p.payload,
        'reason', p.reason, 'proposer_actor_id', p.proposer_id, 'version', p.version,
        'proposed_at', p.created_at
      ) order by p.created_at asc, p.id)
      from retrieval_proposal p
      where p.status = 'pending'
    ), '[]'::jsonb)
  )
$$;


--
-- Name: read_sourced_work_request_shape_disposition_lineage(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_sourced_work_request_shape_disposition_lineage(p_work_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  w ops.work_request%rowtype;
  original ops.sourced_work_request_shape_disposition_receipt%rowtype;
  correction ops.sourced_work_request_shape_disposition_correction_receipt%rowtype;
  e record;
  backed boolean;
begin
  select x.* into w from ops.work_request x where x.id = p_work_request_id;
  if not found or w.capture_idempotency_key is null then return null; end if;
  select r.* into original from ops.sourced_work_request_shape_disposition_receipt r where r.work_request_id = w.id;
  if not found then
    return jsonb_build_object('status','none','effective',null,'original',null,'correction',null,
      'backs_current_version',false);
  end if;
  select c.* into correction from ops.sourced_work_request_shape_disposition_correction_receipt c where c.work_request_id = w.id;
  select l.* into e from ops.sourced_work_request_shape_disposition_lineage(w.id) l;
  backed := exists (select 1 from ops.effective_sourced_work_request_shape_disposition(w));
  return jsonb_build_object(
    'status', case when e.receipt_kind = 'correction' then 'corrected' else 'original' end,
    'effective', jsonb_build_object('receipt_kind', e.receipt_kind,
      'receipt_id', coalesce(e.correction_receipt_id, e.original_receipt_id),
      'disposition', e.disposition, 'fixed_surface_ref', e.fixed_surface_ref, 'rationale', e.rationale,
      'decided_by_actor_id', e.decided_by_actor_id, 'decided_at', e.decided_at,
      'base_version', e.base_version, 'result_version', e.result_version),
    'original', jsonb_build_object('receipt_id', original.id, 'disposition', original.disposition,
      'fixed_surface_ref', original.fixed_surface_ref, 'rationale', original.rationale,
      'decided_by_actor_id', original.decided_by_actor_id, 'decided_at', original.decided_at,
      'base_version', original.base_version, 'result_version', original.result_version),
    'correction', case when correction.id is null then null::jsonb else jsonb_build_object(
      'receipt_id', correction.id, 'original_receipt_id', correction.original_receipt_id,
      'disposition', correction.disposition, 'fixed_surface_ref', correction.fixed_surface_ref,
      'rationale', correction.rationale, 'decided_by_actor_id', correction.decided_by_actor_id,
      'decided_at', correction.decided_at, 'base_version', correction.base_version,
      'result_version', correction.result_version) end,
    'backs_current_version', backed);
end;
$$;


--
-- Name: read_staging_forward_fix_rehearsal_declaration(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_staging_forward_fix_rehearsal_declaration(p_idempotency_key uuid) RETURNS TABLE(expected_provider_tag text, declared_migration_set_sha256 text, declared_migration_count integer, declared_schema_highest_migration text, declared_schema_applied_count integer, declared_schema_ledger_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  if session_user<>'carr_program5_forward_fix_verifier'
     or not pg_has_role(session_user,'carr_program5_forward_fix_verifiers','member') then
    raise exception using errcode='42501',message='forward-fix declaration projection requires the exact scoped verifier capability';
  end if;
  return query select a.expected_provider_tag,a.declared_migration_set_sha256,
    a.declared_migration_count,a.declared_schema_highest_migration,
    a.declared_schema_applied_count,a.declared_schema_ledger_sha256
  from ops.staging_forward_fix_rehearsal_attempt a where a.idempotency_key=p_idempotency_key;
end $$;


--
-- Name: read_staging_replacement_project_receipt(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_staging_replacement_project_receipt(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare result jsonb;
begin
  if session_user<>'carr_jobs' and not (
       session_user='carr_program5_forward_fix_verifier'
       and pg_has_role(session_user,'carr_program5_forward_fix_verifiers','member')) then
    raise exception 'staging replacement receipt read requires a scoped session';
  end if;
  select jsonb_build_object(
      'contract_id',c.id,'receipt_id',r.id,'evidence_ref',r.evidence_ref,
      'receipt_sha256',r.receipt_sha256,'git_sha',r.git_sha,
      'source_tree_oid',r.source_tree_oid,'source_tree_sha256',r.source_tree_sha256,
      'source_tree_entry_count',r.source_tree_entry_count,
      'artifact_sha256',r.artifact_sha256,'config_sha256',r.config_sha256,
      'dependency_sha256',r.dependency_sha256,
      'prior_staging_project_id',r.prior_staging_project_id,
      'replacement_project_id',r.replacement_project_id,
      'replacement_branch_id',r.replacement_branch_id,
      'replacement_endpoint_id',r.replacement_endpoint_id,
      'live_migration_ledger',r.live_migration_ledger,
      'live_migration_count',r.live_migration_count,
      'live_migration_highest',r.live_migration_highest,
      'live_migration_ledger_sha256',r.live_migration_ledger_sha256,
      'synthetic_data_count',r.synthetic_data_count,
      'production_overlap_count',r.production_overlap_count,
      'observed_at',r.observed_at)
    into result
    from ops.staging_replacement_project_receipt r
    join ops.staging_replacement_project_contract c on c.id=r.contract_id
   where r.id=p_receipt_id;
  if result is null then raise exception 'staging replacement receipt not found'; end if;
  return result;
end $$;


--
-- Name: read_tour_internal_detail(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_internal_detail(p_tenant text, p_tour_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'id',t.id,'tour_name',t.tour_name,'tour_status',t.tour_status,'route_version',t.route_version,'updated_at',t.updated_at,
    'routes',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'route_version',v.route_version,'routing_source',v.routing_source,'created_at',v.created_at,'accepted',a.id is not null,'stops',coalesce((select jsonb_agg(jsonb_build_object(
      'id',s.id,'property_id',s.property_id,'route_sequence',s.route_sequence,'route_label',s.route_label,'stop_state',s.stop_state,
      'appointment_start',s.appointment_start,'appointment_end',s.appointment_end,'locked_appointment',s.locked_appointment,
      'dwell_minutes',s.dwell_minutes,'buffer_minutes',s.buffer_minutes,'access_coordinate_status',s.access_coordinate_status,
      'property_name',(select fa.value#>>'{}' from ops.tour_field_assertion fa where fa.organization_tenant_id=s.organization_tenant_id and fa.property_id=s.property_id and fa.field_key='display.name' and fa.review_state='reviewed' order by fa.effective_from desc,fa.id desc limit 1),
      'property_address',(select fa.value#>>'{}' from ops.tour_field_assertion fa where fa.organization_tenant_id=s.organization_tenant_id and fa.property_id=s.property_id and fa.field_key='display.address' and fa.review_state='reviewed' order by fa.effective_from desc,fa.id desc limit 1)
    ) order by s.route_sequence nulls last,s.id) from ops.tour_route_stop s where s.organization_tenant_id=v.organization_tenant_id and s.route_version_id=v.id),'[]'::jsonb)) order by v.route_version desc) from ops.tour_route_version v left join ops.tour_route_version_acceptance a on a.organization_tenant_id=v.organization_tenant_id and a.route_version_id=v.id where v.organization_tenant_id=t.organization_tenant_id and v.tour_id=t.id),'[]'::jsonb),
    'cheat_sheet',coalesce((select jsonb_build_object(
      'revision_id',c.id,'revision_number',c.revision_number,'content',c.content,'revision_kind',c.revision_kind,'created_at',c.created_at,
      'restore_revision_id',(select prior.id from ops.tour_cheat_sheet_revision prior where prior.organization_tenant_id=c.organization_tenant_id and prior.tour_id=c.tour_id and prior.revision_number<c.revision_number order by prior.revision_number desc,prior.id desc limit 1)
    ) from ops.tour_cheat_sheet_revision c where c.organization_tenant_id=t.organization_tenant_id and c.tour_id=t.id order by c.revision_number desc,c.id desc limit 1),'{}'::jsonb),
    'projections',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'projection_version',p.projection_version,'route_version',p.route_version,'status',p.status,'as_of',p.as_of,'projection_digest',p.projection_digest) order by p.projection_version desc) from ops.tour_public_projection p where p.organization_tenant_id=t.organization_tenant_id and p.tour_id=t.id),'[]'::jsonb),
    'shares',coalesce((select jsonb_agg(jsonb_build_object(
      'share_grant_id',g.id,'projection_id',g.projection_id,'grant_version',g.grant_version,'permission_scopes',g.permission_scopes,
      'expires_at',g.expires_at,'status',case when r.id is not null then 'revoked' when newer.id is not null then 'rotated' when g.expires_at<=now() then 'expired' else g.status end
    ) order by g.created_at desc,g.id desc)
      from ops.tour_share_grant g
      join ops.tour_public_projection p on p.organization_tenant_id=g.organization_tenant_id and p.id=g.projection_id
      left join ops.tour_share_grant_revocation_receipt r on r.organization_tenant_id=g.organization_tenant_id and r.share_grant_id=g.id
      left join ops.tour_share_grant newer on newer.organization_tenant_id=g.organization_tenant_id and newer.rotated_from_grant_id=g.id
      where p.organization_tenant_id=t.organization_tenant_id and p.tour_id=t.id),'[]'::jsonb),
    'pdf_render',coalesce((select jsonb_build_object(
      'render_job_id',j.id,'projection_id',j.projection_id,'status',case when h.decision='accept' then 'available' when h.decision='reject' then 'rejected' else coalesce(r.status,'queued') end,
      'qc_run_digest',r.qc_run_digest,'human_review_state',case when h.decision='accept' then 'accepted' when h.decision='reject' then 'rejected' else 'pending' end
    ) from ops.tour_pdf_render_job j join ops.tour_public_projection p on p.organization_tenant_id=j.organization_tenant_id and p.id=j.projection_id
      left join lateral (select rr.* from ops.tour_pdf_render_result rr where rr.organization_tenant_id=j.organization_tenant_id and rr.render_job_id=j.id order by rr.attempt_count desc,rr.id desc limit 1) r on true
      left join ops.tour_pdf_human_review h on h.organization_tenant_id=j.organization_tenant_id and h.render_job_id=j.id
      where p.organization_tenant_id=t.organization_tenant_id and p.tour_id=t.id
        and p.id=(select current_projection.id from ops.tour_public_projection current_projection
          where current_projection.organization_tenant_id=t.organization_tenant_id and current_projection.tour_id=t.id
            and current_projection.status in ('approved','published')
          order by current_projection.projection_version desc,current_projection.id desc limit 1)
      order by j.created_at desc,j.id desc limit 1),'{}'::jsonb)
  ) from ops.tour t where t.organization_tenant_id=p_tenant and t.id=p_tour_id and nullif(btrim(p_actor_id),'') is not null;
$$;


--
-- Name: read_tour_packet_for_render(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_packet_for_render(p_tenant text, p_projection_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with projection as (
    select p.*,t.tour_name from ops.tour_public_projection p join ops.tour t on t.organization_tenant_id=p.organization_tenant_id and t.id=p.tour_id
    where p.organization_tenant_id=p_tenant and p.id=p_projection_id and nullif(btrim(p_actor_id),'') is not null and p.status='approved'
      and exists(select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id and s.canonical_projection_digest=p.projection_digest)
      and ops.read_tour_public_projection(p.organization_tenant_id,p.id) is not null
  ), properties as (
    select m.route_sequence,m.route_label,'property:public:'||substr(encode(public.digest(p.organization_tenant_id||':'||p.id::text||':'||m.property_id::text,'sha256'),'hex'),1,32) property_ref,
      max(a.value#>>'{}') filter(where f.display_field_key='display.name') name,
      max(a.value#>>'{}') filter(where f.display_field_key='display.address') address,
      max(a.value#>>'{}') filter(where f.display_field_key='suite') suite,
      max(a.value#>>'{}') filter(where f.display_field_key='property_type') property_type,
      (jsonb_agg(a.value order by f.id) filter(where f.display_field_key='size'))->0 size,
      (jsonb_agg(a.value order by f.id) filter(where f.display_field_key='asking_economics'))->0 asking_economics,
      max(a.value#>>'{}') filter(where f.display_field_key='availability') availability,
      max(a.value#>>'{}') filter(where f.display_field_key='parking') parking,
      max(a.value#>>'{}') filter(where f.display_field_key='caveat') caveat
    from projection p join ops.tour_property_membership m on m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version
    join ops.tour_public_projection_fact f on f.organization_tenant_id=p.organization_tenant_id and f.projection_id=p.id and f.property_id=m.property_id
    join ops.tour_field_assertion a on a.organization_tenant_id=f.organization_tenant_id and a.id=f.field_assertion_id and ops.tour_public_value_safe(a.field_key,a.value)
    group by p.organization_tenant_id,p.id,m.property_id,m.route_sequence,m.route_label
  ) select jsonb_build_object(
    'projection_digest',p.projection_digest,
    'packet',jsonb_build_object('as_of',p.as_of,'caveat','Facts only; verify current availability and economics.','properties',coalesce((select jsonb_agg(to_jsonb(properties) order by route_sequence) from properties),'[]'::jsonb))
  ) from projection p;
$$;


--
-- Name: read_tour_pdf_artifact_for_download(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_pdf_artifact_for_download(p_tenant text, p_render_job_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('storage_ref',r.storage_ref,'artifact_digest',r.artifact_digest,'content_length',r.content_length,'media_type','application/pdf')
  from ops.tour_pdf_render_job j join ops.tour_pdf_render_result r on r.organization_tenant_id=j.organization_tenant_id and r.render_job_id=j.id
  join ops.tour_pdf_human_review h on h.organization_tenant_id=j.organization_tenant_id and h.render_job_id=j.id and h.render_result_id=r.id and h.decision='accept'
  where j.organization_tenant_id=p_tenant and j.id=p_render_job_id and nullif(btrim(p_actor_id),'') is not null
  order by r.attempt_count desc,r.id desc limit 1;
$$;


--
-- Name: read_tour_pdf_artifact_for_review(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_pdf_artifact_for_review(p_tenant text, p_render_job_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('storage_ref',r.storage_ref,'artifact_digest',r.artifact_digest,'content_length',r.content_length,'media_type','application/pdf')
  from ops.tour_pdf_render_job j join ops.tour_pdf_render_result r on r.organization_tenant_id=j.organization_tenant_id and r.render_job_id=j.id and r.status='review_ready'
  where j.organization_tenant_id=p_tenant and j.id=p_render_job_id and nullif(btrim(p_actor_id),'') is not null
  order by r.attempt_count desc,r.id desc limit 1;
$$;


--
-- Name: read_tour_pdf_render(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_pdf_render(p_tenant text, p_render_job_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object('render_job_id',j.id,'status',case when h.decision='accept' then 'available' when h.decision='reject' then 'rejected' else coalesce(r.status,'queued') end,'artifact_ref',r.artifact_ref,'artifact_digest',r.artifact_digest,'projection_digest',j.projection_digest,'template_digest',j.template_digest,'renderer_digest',j.renderer_digest,'qc_ruleset_digest',j.qc_ruleset_digest,'qc_run_digest',r.qc_run_digest,'expected_property_count',j.expected_property_count,'page_count',r.page_count,'blocking_finding_count',r.blocking_finding_count,'attempt_count',r.attempt_count,'created_at',j.created_at,'updated_at',coalesce(r.created_at,j.created_at),'completed_at',r.completed_at,'human_review_state',case when h.decision='accept' then 'accepted' when h.decision='reject' then 'rejected' else 'pending' end,'reviewed_at',h.reviewed_at))
  from ops.tour_pdf_render_job j left join lateral (select * from ops.tour_pdf_render_result where organization_tenant_id=j.organization_tenant_id and render_job_id=j.id order by attempt_count desc,id desc limit 1) r on true
  left join ops.tour_pdf_human_review h on h.organization_tenant_id=j.organization_tenant_id and h.render_job_id=j.id
  where j.organization_tenant_id=p_tenant and j.id=p_render_job_id and nullif(btrim(p_actor_id),'') is not null;
$$;


--
-- Name: read_tour_projection_creation_metadata(text, uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_projection_creation_metadata(p_tenant text, p_tour_id uuid, p_route_version_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'route_version',v.route_version,
    'projection_version',coalesce((select max(p.projection_version) from ops.tour_public_projection p where p.organization_tenant_id=v.organization_tenant_id and p.tour_id=v.tour_id),0)+1
  )
  from ops.tour_route_version v
  join ops.tour_route_version_acceptance a on a.organization_tenant_id=v.organization_tenant_id and a.route_version_id=v.id
  where v.organization_tenant_id=p_tenant and v.tour_id=p_tour_id and v.id=p_route_version_id
    and nullif(btrim(p_actor_id),'') is not null;
$$;


--
-- Name: read_tour_projection_seal_candidates(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_projection_seal_candidates(p_tenant text, p_projection_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with projection as (
    select p.* from ops.tour_public_projection p where p.organization_tenant_id=p_tenant and p.id=p_projection_id and p.status='draft' and nullif(btrim(p_actor_id),'') is not null
  ), candidates as (
    select m.property_id,m.route_sequence,m.route_label,a.id field_assertion_id,a.field_key display_field_key,a.value,a.effective_from
    from projection p join ops.tour_property_membership m on m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version
    join lateral (
      select assertion.* from ops.tour_field_assertion assertion
      join ops.tour_source_evidence e on e.organization_tenant_id=assertion.organization_tenant_id and e.id=assertion.source_evidence_id and e.rights_receipt_id=assertion.rights_receipt_id
      join ops.tour_rights_receipt r on r.organization_tenant_id=assertion.organization_tenant_id and r.id=assertion.rights_receipt_id and r.provider=e.rights_provider and r.policy_key=e.rights_policy_key
      where assertion.organization_tenant_id=m.organization_tenant_id and assertion.property_id=m.property_id and assertion.review_state='reviewed' and assertion.data_classification='public'
        and assertion.effective_from<=p.as_of and (assertion.effective_to is null or assertion.effective_to>p.as_of)
        and r.status='active' and r.revoked_at is null and r.effective_at<=p.as_of and (r.expires_at is null or r.expires_at>p.as_of)
        and r.allowed_use_classes ? 'client_public_display' and (r.allowed_field_classes ? assertion.field_key or r.allowed_field_classes ? '*')
        and not exists(select 1 from ops.tour_rights_receipt newer where newer.organization_tenant_id=r.organization_tenant_id and newer.provider=r.provider and newer.policy_key=r.policy_key and newer.receipt_version>r.receipt_version and newer.effective_at<=p.as_of)
        and ops.tour_public_value_safe(assertion.field_key,assertion.value)
      order by assertion.field_key,assertion.effective_from desc,assertion.id desc
    ) a on true
  ), selected as (
    select distinct on (property_id,display_field_key) property_id,route_sequence,route_label,field_assertion_id,display_field_key,value
    from candidates order by property_id,display_field_key,effective_from desc,field_assertion_id desc
  ), selected_json as (
    select coalesce(jsonb_agg(jsonb_build_object('property_id',property_id,'field_assertion_id',field_assertion_id,'display_field_key',display_field_key) order by property_id::text,display_field_key,field_assertion_id::text),'[]'::jsonb) value from selected
  ), preview as (
    select coalesce(jsonb_agg(jsonb_build_object('route_sequence',route_sequence,'route_label',route_label,'property_id',property_id,'facts',facts) order by route_sequence),'[]'::jsonb) value
    from (select property_id,route_sequence,route_label,jsonb_object_agg(display_field_key,value order by display_field_key) facts from selected group by property_id,route_sequence,route_label) grouped
  ) select jsonb_build_object('projection_id',p.id,'candidate_digest','sha256:'||encode(public.digest(s.value::text,'sha256'),'hex'),'selected_facts',s.value,'preview',v.value)
  from projection p cross join selected_json s cross join preview v;
$$;


--
-- Name: read_tour_public_projection(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_public_projection(p_tenant text, p_projection_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with clock as materialized (select statement_timestamp() as evaluated_at)
  select jsonb_build_object(
    'projection_id',p.id,'tour_id',p.tour_id,'projection_version',p.projection_version,
    'route_version',p.route_version,'as_of',p.as_of,'projection_digest',p.projection_digest,
    'facts',coalesce((
      select jsonb_agg(jsonb_build_object(
        'property_id',f.property_id,'field_assertion_id',f.field_assertion_id,
        'display_field_key',f.display_field_key,'value',a.value,
        'source_evidence_id',a.source_evidence_id,'rights_receipt_id',a.rights_receipt_id,
        'observed_at',a.observed_at,'effective_from',a.effective_from,'effective_to',a.effective_to
      ) order by f.property_id::text,f.display_field_key,f.field_assertion_id::text)
      from ops.tour_public_projection_fact f
      join ops.tour_field_assertion a on a.id=f.field_assertion_id and a.organization_tenant_id=f.organization_tenant_id
      join ops.tour_source_evidence e on e.id=a.source_evidence_id and e.organization_tenant_id=a.organization_tenant_id
      join ops.tour_rights_receipt r on r.id=a.rights_receipt_id and r.organization_tenant_id=a.organization_tenant_id
      where f.organization_tenant_id=p.organization_tenant_id and f.projection_id=p.id
        and a.review_state='reviewed' and a.data_classification='public'
        and a.rights_receipt_id=e.rights_receipt_id
        and r.provider=e.rights_provider and r.policy_key=e.rights_policy_key
    ),'[]'::jsonb))
  from ops.tour_public_projection p
  cross join clock
  where p.organization_tenant_id=p_tenant and p.id=p_projection_id and p.status='approved'
    and exists (select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id and s.canonical_projection_digest=p.projection_digest)
    and not exists (
      select 1 from ops.tour_public_projection_fact f
      join ops.tour_field_assertion a on a.id=f.field_assertion_id and a.organization_tenant_id=f.organization_tenant_id
      join ops.tour_source_evidence e on e.id=a.source_evidence_id and e.organization_tenant_id=a.organization_tenant_id
      join ops.tour_rights_receipt r on r.id=a.rights_receipt_id and r.organization_tenant_id=a.organization_tenant_id
      where f.organization_tenant_id=p.organization_tenant_id and f.projection_id=p.id
        and (a.review_state <> 'reviewed' or a.data_classification <> 'public'
          or a.rights_receipt_id <> e.rights_receipt_id
          or r.provider <> e.rights_provider or r.policy_key <> e.rights_policy_key
          or e.retrieval_status <> 'read' or e.retrieved_at > p.as_of
          or a.confidence not in ('low','medium','high') or a.observed_at > p.as_of
          or r.status <> 'active' or r.effective_at > clock.evaluated_at
          or (r.expires_at is not null and r.expires_at <= clock.evaluated_at)
          or (r.revoked_at is not null and r.revoked_at <= clock.evaluated_at)
          or not (r.allowed_use_classes ? 'client_public_display')
          or not (r.allowed_field_classes ? a.field_key or r.allowed_field_classes ? '*')
          or exists (
            select 1 from ops.tour_rights_receipt newer
            where newer.organization_tenant_id=r.organization_tenant_id
              and newer.provider=r.provider and newer.policy_key=r.policy_key
              and newer.receipt_version > r.receipt_version
              and newer.effective_at <= clock.evaluated_at
          )
          or exists (
            select 1 from ops.tour_fact_conflict conflict
            where conflict.organization_tenant_id=a.organization_tenant_id
              and conflict.property_id=a.property_id and conflict.field_key=a.field_key
              and conflict.state <> 'superseded' and conflict.opened_at <= clock.evaluated_at
              and not exists (
                select 1 from ops.tour_conflict_resolution_receipt resolution
                where resolution.organization_tenant_id=conflict.organization_tenant_id
                  and resolution.conflict_id=conflict.id
                  and resolution.selected_field_assertion_id=a.id
                  and resolution.resolved_at <= clock.evaluated_at
              )
          ))
    );
$$;


--
-- Name: read_tour_selection_cart(text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_selection_cart(p_tenant text, p_tour_id uuid, p_actor_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('tour_id',tour_id,'selection_version_id',id,'selection_version',selection_version,'property_ids',property_ids,'updated_at',created_at)
  from ops.tour_selection_cart_version where organization_tenant_id=p_tenant and tour_id=p_tour_id and nullif(btrim(p_actor_id),'') is not null order by selection_version desc,id desc limit 1;
$$;


--
-- Name: read_tour_share_map(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_share_map(p_session_digest text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with grant_row as (select (ops.tour_share_session_grant(p_session_digest,'view_map')).*), projection as (
    select p.* from grant_row g join ops.tour_public_projection p on p.organization_tenant_id=g.organization_tenant_id and p.id=g.projection_id
    where p.status='approved' and exists(select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id and s.canonical_projection_digest=p.projection_digest)
      and ops.read_tour_public_projection(p.organization_tenant_id,p.id) is not null
      and ops.tour_public_map_projection_ready(p.organization_tenant_id,p.id)
  ) select jsonb_build_object('as_of',p.as_of,'points',coalesce(jsonb_agg(jsonb_build_object(
    'property_ref','property:public:'||substr(encode(public.digest(p.organization_tenant_id||':'||p.id::text||':'||m.property_id::text,'sha256'),'hex'),1,32),
    'route_sequence',m.route_sequence,'route_label',m.route_label,'latitude',c.latitude::double precision,'longitude',c.longitude::double precision
  ) order by m.route_sequence),'[]'::jsonb))
  from projection p join ops.tour_property_membership m on m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version
  join ops.tour_public_projection_map_point mp on mp.organization_tenant_id=p.organization_tenant_id and mp.projection_id=p.id and mp.property_id=m.property_id and mp.route_version=p.route_version
  join ops.tour_coordinate_entrance_verification_receipt er on er.organization_tenant_id=mp.organization_tenant_id and er.id=mp.entrance_verification_receipt_id and er.property_id=mp.property_id and er.coordinate_candidate_id=mp.coordinate_candidate_id
  join ops.tour_property_coordinate_candidate c on c.organization_tenant_id=mp.organization_tenant_id and c.id=mp.coordinate_candidate_id and c.coordinate_role in ('entrance','driveway','parking_access') and c.review_state='reviewed'
  group by p.as_of;
$$;


--
-- Name: read_tour_share_packet(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_share_packet(p_session_digest text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with grant_row as (select (ops.tour_share_session_grant(p_session_digest,'view_packet')).*), projection as (
    select p.* from grant_row g join ops.tour_public_projection p on p.organization_tenant_id=g.organization_tenant_id and p.id=g.projection_id
    where p.status='approved' and exists(select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id and s.canonical_projection_digest=p.projection_digest)
      and ops.read_tour_public_projection(p.organization_tenant_id,p.id) is not null
  ), stops as (
    select m.route_sequence,m.route_label,'property:public:'||substr(encode(public.digest(p.organization_tenant_id||':'||p.id::text||':'||m.property_id::text,'sha256'),'hex'),1,32) property_ref,
      max(a.value#>>'{}') filter(where f.display_field_key='display.name') name,
      max(a.value#>>'{}') filter(where f.display_field_key='display.address') address,
      max(a.value#>>'{}') filter(where f.display_field_key='suite') suite,
      max(a.value#>>'{}') filter(where f.display_field_key='property_type') property_type,
      (jsonb_agg(a.value order by f.id) filter(where f.display_field_key='size'))->0 size,
      (jsonb_agg(a.value order by f.id) filter(where f.display_field_key='asking_economics'))->0 asking_economics,
      max(a.value#>>'{}') filter(where f.display_field_key='availability') availability,
      max(a.value#>>'{}') filter(where f.display_field_key='parking') parking,
      max(a.value#>>'{}') filter(where f.display_field_key='caveat') caveat
    from projection p join ops.tour_property_membership m on m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version
    join ops.tour_public_projection_fact f on f.organization_tenant_id=p.organization_tenant_id and f.projection_id=p.id and f.property_id=m.property_id
    join ops.tour_field_assertion a on a.organization_tenant_id=f.organization_tenant_id and a.id=f.field_assertion_id and ops.tour_public_value_safe(a.field_key,a.value)
    group by p.organization_tenant_id,p.id,m.property_id,m.route_sequence,m.route_label
  ) select jsonb_build_object('as_of',p.as_of,'caveat','Facts only; verify current availability and economics.','stops',coalesce((select jsonb_agg(to_jsonb(stops) order by route_sequence) from stops),'[]'::jsonb)) from projection p;
$$;


--
-- Name: read_tour_sharing_library(text, uuid, text, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.read_tour_sharing_library(p_tenant text, p_projection_id uuid, p_actor_id text, p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_limit integer; v_offset integer; v_count integer; v_items jsonb;
begin
  if nullif(btrim(p_actor_id),'') is null or p_limit is null or p_limit<1 or p_limit>100
     or (p_cursor is not null and p_cursor !~ '^[0-9]{1,9}$') then return null; end if;
  v_limit:=p_limit; v_offset:=coalesce(p_cursor::integer,0);
  with selected as (
    select g.*,r.id revocation_id,r.revoked_at,r.reason,successor.id successor_id
    from ops.tour_share_grant g
    left join ops.tour_share_grant_revocation_receipt r on r.organization_tenant_id=g.organization_tenant_id and r.share_grant_id=g.id
    left join ops.tour_share_grant successor on successor.organization_tenant_id=g.organization_tenant_id and successor.rotated_from_grant_id=g.id
    where g.organization_tenant_id=p_tenant and g.projection_id=p_projection_id
    order by g.grant_version desc,g.id desc limit v_limit+1 offset v_offset
  ), page as (
    select selected.*,row_number() over (order by grant_version desc,id desc) page_row from selected
  )
  select count(*),coalesce(jsonb_agg(jsonb_build_object(
    'share_grant_id',id,'status',case when revocation_id is not null then 'revoked' when successor_id is not null then 'rotated' when expires_at<=now() then 'expired' else 'active' end,
    'permission_scopes',permission_scopes,'expires_at',expires_at,'revoked_at',revoked_at,'reason',reason,'created_at',created_at
  ) order by grant_version desc,id desc) filter(where page_row<=v_limit),'[]'::jsonb)
  into v_count,v_items from page;
  return jsonb_strip_nulls(jsonb_build_object(
    'items',v_items,'has_more',v_count>v_limit,
    'cursor',case when v_count>v_limit then (v_offset+v_limit)::text end));
end;
$_$;


--
-- Name: ready_plan_amendment_census(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ready_plan_amendment_census(p_work_request_id uuid, p_predecessor_plan_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  with envelopes as (
    select e.* from ops.engineering_execution_envelope e
     where e.work_request_id=p_work_request_id and e.accepted_plan_id=p_predecessor_plan_id
       and not exists(select 1 from ops.engineering_execution_envelope n where n.supersedes_envelope_id=e.id)
  ), counts as (
    select
      (select count(*) from ops.canonical_ownership_lease l where l.work_request_id=p_work_request_id
        and l.accepted_plan_id=p_predecessor_plan_id and l.state='active' and l.expires_at>clock_timestamp()) active_leases,
      (select count(*) from envelopes e join ops.job j on j.id=e.job_id
        where j.state in ('queued','running','retry_wait','waiting_approval')) active_jobs,
      (select count(*) from envelopes e join ops.capability_agent_session s on s.id=e.agent_session_id
        where s.state in ('claimed','in_progress','verification')
          and coalesce(s.lease_expires_at,'infinity'::timestamptz)>clock_timestamp()) active_sessions,
      (select count(*) from ops.canonical_ownership_runtime_session rs
        where rs.work_request_id=p_work_request_id and rs.accepted_plan_id=p_predecessor_plan_id
          and rs.state='active' and rs.expires_at>clock_timestamp()) active_runtime_sessions,
      (select count(*) from envelopes e where not exists(select 1 from ops.engineering_slice_receipt r where r.envelope_id=e.id)) unreceipted_envelopes,
      (select coalesce(sum(jsonb_array_length(sp.plan->'slices')),0)
         from ops.engineering_slice_plan sp
        where sp.work_request_id=p_work_request_id and sp.accepted_plan_id=p_predecessor_plan_id
          and jsonb_typeof(sp.plan->'slices')='array') predecessor_slices,
      (select count(*) from ops.ready_plan_amendment_slice_compatibility m
         join ops.ready_plan_amendment a on a.plan_id=m.successor_plan_id
        where a.work_request_id=p_work_request_id and a.predecessor_plan_id=p_predecessor_plan_id)
        mapped_slices,
      (select count(*) from ops.engineering_slice_plan sp
        where sp.work_request_id=p_work_request_id and sp.accepted_plan_id=p_predecessor_plan_id
          and jsonb_typeof(sp.plan->'slices') is distinct from 'array') malformed_slice_plans
  ) select jsonb_build_object('active_leases',active_leases,'active_jobs',active_jobs,
      'active_sessions',active_sessions,'active_runtime_sessions',active_runtime_sessions,
      'unreceipted_envelopes',unreceipted_envelopes,
      'predecessor_slices',predecessor_slices,'mapped_slices',mapped_slices,
      'malformed_slice_plans',malformed_slice_plans,
      'compatibility_complete',predecessor_slices=mapped_slices and malformed_slice_plans=0,
      'safe',active_leases=0 and active_jobs=0 and active_sessions=0 and active_runtime_sessions=0
        and unreceipted_envelopes=0 and predecessor_slices=mapped_slices
        and malformed_slice_plans=0)
    from counts;
$$;


--
-- Name: ready_plan_amendment_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ready_plan_amendment_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin raise exception 'ready-plan amendment history is append-only'; end $$;


--
-- Name: ready_plan_amendment_slice_plan_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.ready_plan_amendment_slice_plan_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  perform 1 from ops.work_request w where w.id=new.work_request_id for share;
  if not found or not exists(
    select 1 from ops.work_request w
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.result_version=w.version
   where w.id=new.work_request_id and w.state='ready'
     and ar.plan_id=new.accepted_plan_id and ar.plan_hash=new.accepted_plan_hash
     and new.work_request_version=w.version) then
    raise exception 'engineering slice plan is not bound to the exact current accepted plan';
  end if;
  return new;
end $$;


--
-- Name: reap_expired_jobs(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reap_expired_jobs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare n integer;
begin
  with expired as materialized (
    select j.id,j.attempt
      from ops.job j
     where j.state='running' and j.leased_until < now()
     for update skip locked
  ), attempts as (
    update ops.job_attempt a
       set state='timed_out',ended_at=now(),failure_class='lease_expired',detail='lease expired'
      from expired e
     where a.job_id=e.id and a.attempt=e.attempt and a.state='running'
    returning a.job_id
  ), transitioned as (
    update ops.job j
       set state=case when j.attempt < j.max_attempts then 'retry_wait' else 'dead_lettered' end,
           next_attempt_at=case when j.attempt < j.max_attempts
                                then now()+make_interval(secs=>ops.retry_delay_seconds(j))
                                else j.next_attempt_at end,
           ended_at=case when j.attempt < j.max_attempts then null else now() end,
           last_failure_class='lease_expired',last_failure_detail='lease expired',
           lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
      from expired e
     where j.id=e.id
    returning j.id,j.attempt,j.state
  ), receipts as (
    insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    select t.id,t.attempt,
           case when t.state='dead_lettered' then 'dead_letter' else 'timeout' end,
           concat('lease-expired:',t.id,':',t.attempt),
           jsonb_build_object('failure_class','lease_expired','next_state',t.state)
      from transitioned t
    returning id
  )
  select count(*) into n from transitioned;
  return n;
end $$;


--
-- Name: reclassify_legacy_rule_admission(uuid, text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reclassify_legacy_rule_admission(p_rule_id uuid, p_new_class text, p_idempotency_key uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_rule rule%rowtype;
  v_admission ops.rule_admission%rowtype;
  v_prior ops.rule_admission_reclassification_receipt%rowtype;
  v_receipt ops.rule_admission_reclassification_receipt%rowtype;
  v_legacy_note text;
  v_contract jsonb;
  v_contract_hash text;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug<>'joe' then
    raise exception 'legacy admission reclassification requires Joe authority';
  end if;
  select id into v_actor_id from actor
   where slug=v_actor_slug and kind='human' and active;
  if v_actor_id is null then raise exception 'Joe authority actor is not active'; end if;
  if btrim(coalesce(p_reason,''))='' or p_idempotency_key is null then
    raise exception 'reclassification reason and idempotency key are required';
  end if;
  if p_new_class not in ('machine_enforceable','judgment_advisory','human_only') then
    raise exception 'unknown enforcement class %',p_new_class;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-reclassification:'||p_idempotency_key::text,0));
  select * into v_prior from ops.rule_admission_reclassification_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if v_prior.rule_id is distinct from p_rule_id
       or v_prior.enforcement_class_after is distinct from p_new_class
       or v_prior.reason is distinct from btrim(p_reason)
       or v_prior.actor_id is distinct from v_actor_id then
      raise exception 'reclassification idempotency key was reused with different input';
    end if;
    return jsonb_build_object('ok',true,'replayed',true,'rule_id',p_rule_id,
      'enforcement_class',v_prior.enforcement_class_after,
      'reclassification_receipt_id',v_prior.id);
  end if;

  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status<>'active' then
    raise exception 'rule % is %, only an active rule''s admission is reclassified here',p_rule_id,v_rule.status;
  end if;
  if exists (select 1 from ops.rule_approval_receipt where rule_id=v_rule.id) then
    raise exception 'rule % carries an approval receipt; its class is bound to the receipt and does not move through the legacy path',p_rule_id;
  end if;
  v_legacy_note := ops.legacy_rule_admission_note(v_rule.id,v_rule.status,v_rule.activated_at);
  if v_legacy_note is null then
    raise exception 'rule % is not a legacy admission; reclassification refused',p_rule_id;
  end if;

  select * into v_admission from ops.rule_admission where rule_id=v_rule.id for update;
  if not found then raise exception 'rule % has no admission row',p_rule_id; end if;
  if v_admission.enforcement_class=p_new_class then
    raise exception 'rule % is already classified %; a no-op reclassification is refused',p_rule_id,p_new_class;
  end if;

  v_contract := jsonb_build_object(
    'rule_id',v_rule.id,'enforcement_class_before',v_admission.enforcement_class,
    'enforcement_class_after',p_new_class,'actor_id',v_actor_id,
    'reason',btrim(p_reason),'legacy_admission',v_legacy_note);
  v_contract_hash := encode(digest(v_contract::text,'sha256'),'hex');

  insert into ops.rule_admission_reclassification_receipt
    (idempotency_key,rule_id,enforcement_class_before,enforcement_class_after,
     actor_id,reason,legacy_admission,contract_hash)
  values (p_idempotency_key,v_rule.id,v_admission.enforcement_class,p_new_class,
          v_actor_id,btrim(p_reason),v_legacy_note,v_contract_hash)
  returning * into v_receipt;

  update ops.rule_admission set enforcement_class=p_new_class
   where rule_id=v_rule.id;

  return jsonb_build_object('ok',true,'replayed',false,'rule_id',v_rule.id,
    'enforcement_class_before',v_receipt.enforcement_class_before,
    'enforcement_class',p_new_class,
    'reclassification_receipt_id',v_receipt.id,
    'legacy_admission',v_receipt.legacy_admission);
end $$;


--
-- Name: FUNCTION reclassify_legacy_rule_admission(p_rule_id uuid, p_new_class text, p_idempotency_key uuid, p_reason text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.reclassify_legacy_rule_admission(p_rule_id uuid, p_new_class text, p_idempotency_key uuid, p_reason text) IS 'Joe-authority-guarded correction of a LEGACY active rule''s admission enforcement_class (0352). Requires ops.legacy_rule_admission_note to prove the rule predates the receipt system; a receipted rule refuses (its class is bound to the receipt). Append-only receipt records before, after, and the legacy fact.';


--
-- Name: record_assurance_evidence_extension(uuid, uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_assurance_evidence_extension(p_receipt_id uuid, p_manifest_id uuid, p_lease_token uuid, p_evidence jsonb, p_evidence_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare m ops.assurance_execution_manifest%rowtype; r ops.engineering_slice_receipt%rowtype;
        e ops.engineering_execution_envelope%rowtype; prior ops.assurance_evidence_extension%rowtype;
        live jsonb; actual_digest text; requirement jsonb; result jsonb; field text;
        artifact_ref jsonb; inserted ops.assurance_evidence_extension%rowtype;
        l ops.canonical_ownership_lease%rowtype; sp ops.engineering_slice_plan%rowtype;
        executor_slug text; started_at timestamptz; finished_at timestamptz;
        now_at timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended('assurance-evidence-door',0));
  select * into m from ops.assurance_execution_manifest where id=p_manifest_id;
  if not found then return ops.assurance_refusal('ASSURANCE_BINDING_STALE','evidence.manifest_id','"existing manifest"'::jsonb,'null'::jsonb); end if;
  perform pg_advisory_xact_lock(hashtextextended('assurance-lease-scan',0));
  live:=ops.assurance_append_lineage_current(m.lease_id,p_receipt_id,clock_timestamp(),p_lease_token,m.fencing_generation);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  lock table ops.canonical_ownership_lease in share mode;
  live:=ops.assurance_append_lineage_current(m.lease_id,p_receipt_id,clock_timestamp(),p_lease_token,m.fencing_generation);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  select * into m from ops.assurance_execution_manifest where id=p_manifest_id for key share;
  if not found then return ops.assurance_refusal('ASSURANCE_BINDING_STALE','evidence.manifest_id','"existing manifest"'::jsonb,'null'::jsonb); end if;
  now_at:=clock_timestamp();
  select * into r from ops.engineering_slice_receipt where id=p_receipt_id for key share;
  select * into e from ops.engineering_execution_envelope where id=r.envelope_id for key share;
  select * into l from ops.canonical_ownership_lease where id=m.lease_id for key share;
  select * into sp from ops.engineering_slice_plan where id=e.slice_plan_id for key share;
  select slug into executor_slug from public.actor
   where id=r.executor_actor_id and active for share;
  if m.repository_stage<>'post_commit' then
    return ops.assurance_refusal('EVIDENCE_STAGE_UNSUPPORTED','manifest.repository_stage','"post_commit"'::jsonb,to_jsonb(m.repository_stage));
  end if;
  if not ops.assurance_all_tokens_absent(jsonb_build_array(
       p_evidence,to_jsonb(p_evidence_digest),to_jsonb(p_idempotency_key))) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','assurance.token_nondisclosure',
      '"lease token absent from evidence inputs"'::jsonb,'"token_present"'::jsonb);
  end if;
  if p_idempotency_key is null
     or not coalesce(ops.assurance_exact_object(p_evidence,array[
       'schema_version','manifest_hash','engineering_receipt_digest','repository','command',
       'environment','toolchain','output','timestamps','artifacts','requirements','fencing_generation']),false)
     or jsonb_typeof(p_evidence->'schema_version') is distinct from 'string'
     or p_evidence->>'schema_version' is distinct from 'assurance-evidence.v1'
     or not coalesce(ops.assurance_exact_object(p_evidence->'repository',array['commit_sha','tree_sha','stage']),false)
     or exists(select 1 from unnest(array['commit_sha','tree_sha','stage']) key
                where jsonb_typeof(p_evidence->'repository'->key) is distinct from 'string')
     or not coalesce(ops.assurance_exact_object(p_evidence->'command',array['argv','cwd']),false)
     or jsonb_typeof(p_evidence#>'{command,cwd}') is distinct from 'string'
     or not coalesce(ops.assurance_exact_object(p_evidence->'output',array['exit_code','stdout_digest','stderr_digest']),false)
     or not coalesce(ops.assurance_exact_object(p_evidence->'timestamps',array['started_at','finished_at']),false)
     or jsonb_typeof(p_evidence#>'{command,argv}')<>'array'
     or jsonb_array_length(p_evidence#>'{command,argv}')=0
     or exists(select 1 from jsonb_array_elements(p_evidence#>'{command,argv}') x
                where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='')
     or not (p_evidence#>>'{command,cwd}'='.'
             or ops.canonical_ownership_path_valid(p_evidence#>>'{command,cwd}'))
     or not coalesce(ops.assurance_exact_object(p_evidence->'environment',
          array['environment_ref','network_access']),false)
     or not ops.assurance_identifier_valid(p_evidence#>>'{environment,environment_ref}')
     or p_evidence#>'{environment,network_access}' is distinct from 'false'::jsonb
     or not coalesce(ops.assurance_exact_object(p_evidence->'toolchain',
          array['runtime','runtime_version','database','database_version']),false)
     or exists(select 1 from unnest(array['runtime','runtime_version','database','database_version']) key
                where jsonb_typeof(p_evidence->'toolchain'->key)<>'string'
                   or btrim(p_evidence->'toolchain'->>key)='')
     or jsonb_typeof(p_evidence->'artifacts')<>'array'
     or jsonb_array_length(p_evidence->'artifacts')=0
     or jsonb_typeof(p_evidence->'requirements')<>'array'
     or jsonb_typeof(p_evidence#>'{output,exit_code}')<>'number'
     or jsonb_typeof(p_evidence->'fencing_generation')<>'number'
     or not coalesce(p_evidence->>'fencing_generation' ~ '^[1-9][0-9]*$',false)
     or not coalesce(p_evidence#>>'{output,exit_code}' ~ '^(0|[1-9][0-9]*)$',false)
     or (p_evidence#>>'{output,exit_code}')::numeric>255
     or not coalesce(p_evidence#>>'{output,stdout_digest}' ~ '^sha256:[0-9a-f]{64}$',false)
     or not coalesce(p_evidence#>>'{output,stderr_digest}' ~ '^sha256:[0-9a-f]{64}$',false)
     or not ops.assurance_timestamp_valid(p_evidence#>>'{timestamps,started_at}')
     or not ops.assurance_timestamp_valid(p_evidence#>>'{timestamps,finished_at}')
     then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','evidence','"closed assurance-evidence.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  actual_digest:=ops.assurance_digest(p_evidence);
  if p_evidence_digest is distinct from actual_digest then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','evidence_digest',to_jsonb(actual_digest),to_jsonb(p_evidence_digest));
  end if;
  if r.id is null or e.id is null or r.outcome is distinct from 'claimed_complete'
     or r.work_request_id is distinct from m.work_request_id or r.slice_ref is distinct from m.slice_ref
     or e.id is distinct from l.subject_envelope_id or e.work_request_id is distinct from m.work_request_id
     or e.accepted_plan_id is distinct from m.accepted_plan_id or e.slice_plan_id is distinct from m.slice_plan_id
     or e.slice_ref is distinct from m.slice_ref or sp.plan_digest is distinct from m.manifest#>>'{input_bindings,engineering_slice_plan_digest}'
     or r.executor_actor_id is distinct from l.holder_actor_id or executor_slug is distinct from l.holder_actor_slug
     or (e.envelope#>>'{agent_session,id}' is distinct from l.holder_session_ref
     and not exists (select 1 from ops.canonical_ownership_runtime_session rs
       where rs.organization_tenant_id=l.organization_tenant_id
         and rs.subject_envelope_id=e.id
         and rs.ownership_session_ref=l.holder_session_ref
         and rs.runtime_session_ref=e.envelope#>>'{agent_session,id}'))
     or m.manifest#>>'{slice,executor_identity,host_ref}' is distinct from l.holder_host_ref
     or m.organization_tenant_id is distinct from l.organization_tenant_id
     or p_evidence->>'manifest_hash' is distinct from m.manifest_hash
     or p_evidence->>'engineering_receipt_digest' is distinct from r.receipt_digest
     or p_evidence#>>'{repository,stage}' is distinct from 'post_commit'
     or p_evidence#>>'{repository,commit_sha}' is distinct from m.repository_commit_sha
     or p_evidence#>>'{repository,tree_sha}' is distinct from m.repository_tree_sha
     or (p_evidence->>'fencing_generation')::bigint is distinct from m.fencing_generation then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','evidence.lineage',
      '"exact post-commit manifest/receipt/envelope/fence"'::jsonb,'"mismatch"'::jsonb);
  end if;
  begin
    started_at:=(p_evidence#>>'{timestamps,started_at}')::timestamptz;
    finished_at:=(p_evidence#>>'{timestamps,finished_at}')::timestamptz;
    if now_at>=m.snapshot_valid_until or (l.state='active' and l.expires_at<=now_at) or (l.state='released' and (l.released_at is null or finished_at>l.released_at))
       or finished_at<started_at or started_at<date_trunc('second',l.acquired_at)
       or finished_at>now_at or finished_at>m.snapshot_valid_until then
      return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','evidence.timestamps','"finished_at >= started_at"'::jsonb,'"reversed"'::jsonb);
    end if;
  exception when others then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','evidence.timestamps','"valid timestamps"'::jsonb,'"invalid"'::jsonb);
  end;
  if exists (select 1 from jsonb_array_elements(p_evidence->'artifacts') a
      where not coalesce(ops.assurance_exact_object(a,array['artifact_ref','path','digest','artifact_kind']),false)
         or exists(select 1 from unnest(array['artifact_ref','path','digest','artifact_kind']) key
                    where jsonb_typeof(a->key) is distinct from 'string')
         or not ops.canonical_ownership_path_valid(a->>'path')
         or not coalesce(a->>'digest' ~ '^sha256:[0-9a-f]{64}$',false)
         or not coalesce(a->>'artifact_ref' ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false)
         or not coalesce(a->>'artifact_kind' ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$',false))
     or exists (select 1 from jsonb_array_elements(p_evidence->'artifacts') a group by a->>'artifact_ref' having count(*)>1)
     or exists (select 1 from jsonb_array_elements(p_evidence->'artifacts') a group by lower(a->>'path') having count(*)>1) then
    return ops.assurance_refusal('EVIDENCE_ARTIFACT_MISMATCH','evidence.artifacts','"unique valid artifacts"'::jsonb,'"invalid"'::jsonb);
  end if;
  if jsonb_array_length(p_evidence->'requirements')<>
     jsonb_array_length(m.manifest#>'{slice,evidence_requirements}') then
    return ops.assurance_refusal('EVIDENCE_REQUIREMENT_MISMATCH','evidence.requirements','"exact manifest requirement set"'::jsonb,'"cardinality mismatch"'::jsonb);
  end if;
  for requirement in select value from jsonb_array_elements(m.manifest#>'{slice,evidence_requirements}') loop
    select value into result from jsonb_array_elements(p_evidence->'requirements')
      where value->>'evidence_ref'=requirement->>'evidence_ref';
    if result is null or not coalesce(ops.assurance_exact_object(result,array[
         'evidence_ref','artifact_kind','field_bindings','artifact_refs']),false)
       or jsonb_typeof(result->'evidence_ref') is distinct from 'string'
       or jsonb_typeof(result->'artifact_kind') is distinct from 'string'
       or result->>'artifact_kind' is distinct from requirement->>'artifact_kind'
       or jsonb_typeof(result->'field_bindings')<>'object'
       or jsonb_typeof(result->'artifact_refs')<>'array'
       or jsonb_array_length(result->'artifact_refs')=0
       or not coalesce(ops.assurance_unique_array(result->'artifact_refs'),false) then
      return ops.assurance_refusal('EVIDENCE_REQUIREMENT_MISMATCH','evidence.requirements.'||(requirement->>'evidence_ref'),requirement,result);
    end if;
    if (select coalesce(array_agg(k order by k),'{}'::text[]) from jsonb_object_keys(result->'field_bindings') k)
       is distinct from
       (select coalesce(array_agg(value order by value),'{}'::text[]) from jsonb_array_elements_text(requirement->'required_fields')) then
      return ops.assurance_refusal('EVIDENCE_REQUIREMENT_MISMATCH','evidence.requirements.field_bindings',requirement->'required_fields',result->'field_bindings');
    end if;
    for field in select value from jsonb_array_elements_text(requirement->'required_fields') loop
      if ops.assurance_pinned_pointer(field) is null then
        return ops.assurance_refusal('EVIDENCE_FIELD_UNSUPPORTED','evidence.required_field','"pinned A3a field"'::jsonb,to_jsonb(field));
      end if;
      if result->'field_bindings'->>field is distinct from ops.assurance_pinned_pointer(field)
         or ops.assurance_pointer_value(p_evidence,result->'field_bindings'->>field) is null
         or ops.assurance_pointer_value(p_evidence,result->'field_bindings'->>field)='null'::jsonb then
        return ops.assurance_refusal('EVIDENCE_POINTER_INVALID','evidence.field_bindings.'||field,to_jsonb(ops.assurance_pinned_pointer(field)),to_jsonb(result->'field_bindings'->>field));
      end if;
    end loop;
    for artifact_ref in select value from jsonb_array_elements(result->'artifact_refs') loop
      if jsonb_typeof(artifact_ref)<>'string' or not exists (
        select 1 from jsonb_array_elements(p_evidence->'artifacts') a
         where a->>'artifact_ref'=artifact_ref#>>'{}' and a->>'artifact_kind'=requirement->>'artifact_kind') then
        return ops.assurance_refusal('EVIDENCE_ARTIFACT_MISMATCH','evidence.requirements.artifact_refs',
          to_jsonb(requirement->>'artifact_kind'),artifact_ref);
      end if;
    end loop;
    result:=null;
  end loop;
  if exists (select 1 from jsonb_array_elements(p_evidence->'requirements') x
      where not exists (select 1 from jsonb_array_elements(m.manifest#>'{slice,evidence_requirements}') q
        where q->>'evidence_ref'=x->>'evidence_ref')) then
    return ops.assurance_refusal('EVIDENCE_REQUIREMENT_MISMATCH','evidence.requirements','"no extra requirement"'::jsonb,'"extra"'::jsonb);
  end if;
  if exists (select 1 from jsonb_array_elements(p_evidence->'artifacts') a
      where not exists (select 1 from jsonb_array_elements(p_evidence->'requirements') q,
                               jsonb_array_elements(q->'artifact_refs') ar
                         where ar#>>'{}'=a->>'artifact_ref')) then
    return ops.assurance_refusal('EVIDENCE_ARTIFACT_MISMATCH','evidence.artifacts',
      '"every artifact referenced by one exact requirement"'::jsonb,'"unreferenced"'::jsonb);
  end if;

  select * into prior from ops.assurance_evidence_extension where idempotency_key=p_idempotency_key;
  if found then
    if prior.receipt_id=p_receipt_id and prior.manifest_id=p_manifest_id
       and prior.evidence=p_evidence and prior.evidence_digest=p_evidence_digest then
      return jsonb_build_object('ok',true,'evidence_id',prior.id,'evidence_digest',prior.evidence_digest,'replayed',true);
    end if;
    return ops.assurance_refusal('IDEMPOTENCY_CONFLICT','assurance_evidence_extension.idempotency_key','"exact prior request"'::jsonb,'"changed request"'::jsonb);
  end if;
  if exists (select 1 from ops.assurance_evidence_extension where receipt_id=p_receipt_id or manifest_id=p_manifest_id) then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','assurance_evidence_extension.one_to_one','"one post-commit extension"'::jsonb,'"already exists"'::jsonb);
  end if;
  now_at:=clock_timestamp();
  if now_at>=m.snapshot_valid_until then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','manifest.snapshot_valid_until',
      to_jsonb(m.snapshot_valid_until),to_jsonb(now_at));
  end if;
  if l.state='active' and l.expires_at<=now_at then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"active unexpired canonical lease at insert"'::jsonb,'"stale"'::jsonb);
  end if;
  insert into ops.assurance_evidence_extension(
    receipt_id,manifest_id,evidence_digest,evidence,idempotency_key,created_at)
    values(p_receipt_id,p_manifest_id,p_evidence_digest,p_evidence,p_idempotency_key,now_at)
    returning * into inserted;
  return jsonb_build_object('ok',true,'evidence_id',inserted.id,'evidence_digest',inserted.evidence_digest,'replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or null_value_not_allowed
                    or check_violation or foreign_key_violation or unique_violation then
  return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','evidence.typed_binding','"well-typed exact evidence"'::jsonb,'"invalid"'::jsonb);
end $_$;


--
-- Name: record_assurance_execution_manifest(uuid, uuid, bigint, text, jsonb, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_assurance_execution_manifest(p_lease_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_repository_stage text, p_compiler_input jsonb, p_manifest jsonb, p_applicable_rules jsonb, p_coordination_snapshot jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare live jsonb; context jsonb; l ops.canonical_ownership_lease%rowtype;
        activated_runtime boolean; runtime_for_lease boolean; accepted_scope_digest text;
        sp ops.engineering_slice_plan%rowtype; prior ops.assurance_execution_manifest%rowtype;
        actual_manifest_hash text; actual_rules_digest text; actual_coord_digest text;
        valid_until timestamptz; inserted ops.assurance_execution_manifest%rowtype;
        compiler_validation jsonb; now_at timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended('assurance-manifest-door',0));
  perform pg_advisory_xact_lock(hashtextextended('assurance-lease-scan',0));
  live:=ops.canonical_ownership_validate_live(p_lease_id,p_lease_token,p_fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  lock table ops.canonical_ownership_lease in share mode;
  live:=ops.canonical_ownership_validate_live(p_lease_id,p_lease_token,p_fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  context:=ops.canonical_ownership_context();
  select * into l from ops.canonical_ownership_lease where id=p_lease_id for key share;
  select * into sp from ops.engineering_slice_plan where id=l.slice_plan_id for key share;
  if not ops.assurance_all_tokens_absent(p_compiler_input)
     or not ops.assurance_all_tokens_absent(p_manifest)
     or not ops.assurance_all_tokens_absent(p_applicable_rules)
     or not ops.assurance_all_tokens_absent(p_coordination_snapshot)
     or not ops.assurance_all_tokens_absent(to_jsonb(p_repository_stage))
     or not ops.assurance_all_tokens_absent(to_jsonb(p_idempotency_key)) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','assurance.token_nondisclosure',
      '"lease token absent from all persisted and returned values"'::jsonb,'"token_present"'::jsonb);
  end if;
  if p_applicable_rules is distinct from p_compiler_input->'applicable_rules'
     or p_coordination_snapshot is distinct from p_compiler_input->'coordination_snapshot' then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','compiler_input.preimages',
      '"exact compiler rule and coordination preimages"'::jsonb,'"mismatch"'::jsonb);
  end if;
  -- An activated lease is identified by its ownership-session runtime, never
  -- merely by the presence of a source scope.  Direct legacy leases can share
  -- that plan and scope.
  select exists(
    select 1 from ops.canonical_ownership_runtime_session rs
     where rs.organization_tenant_id=l.organization_tenant_id
       and rs.subject_envelope_id=l.subject_envelope_id
       and rs.ownership_session_ref=l.holder_session_ref)
    into runtime_for_lease;
  if runtime_for_lease then
    select exists(
      select 1
        from ops.canonical_ownership_runtime_session rs
        join ops.canonical_ownership_issuer_generation g
          on g.principal=session_user and g.state in ('active','draining')
       where rs.organization_tenant_id=l.organization_tenant_id
         and rs.subject_envelope_id=l.subject_envelope_id
         and rs.ownership_session_ref=l.holder_session_ref
         and rs.issuer_principal=session_user
         and rs.state='active' and rs.expires_at>clock_timestamp())
      into activated_runtime;
    if not activated_runtime then
      return ops.assurance_refusal('IDENTITY_CONTEXT_INVALID','manifest.issuer_runtime',
        '"current issuer runtime for this lease subject"'::jsonb,
        '"missing_or_stale"'::jsonb);
    end if;
    select scope.scope_digest into accepted_scope_digest
      from ops.source_merge_plan_scope scope
      join ops.sourced_work_request_plan_acceptance_receipt acceptance
        on acceptance.id=scope.acceptance_receipt_id
     where scope.organization_tenant_id=l.organization_tenant_id
       and scope.work_request_id=l.work_request_id
       and scope.accepted_plan_id=l.accepted_plan_id
       and acceptance.result_version=l.work_request_version;
    if not found or l.contract_digest is distinct from accepted_scope_digest then
      return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.contract_digest',
        to_jsonb(accepted_scope_digest),to_jsonb(l.contract_digest));
    end if;
  elsif p_compiler_input#>>'{assurance_slice,ownership_contract_digest}'
          is distinct from l.contract_digest then
    -- Legacy leases retain the historic compiler-to-lease equality rule.
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH',
      'compiler_input.assurance_slice.ownership_contract_digest',
      to_jsonb(l.contract_digest),
      p_compiler_input#>'{assurance_slice,ownership_contract_digest}');
  end if;
  if jsonb_typeof(p_coordination_snapshot)='object'
     and ops.assurance_timestamp_valid(p_coordination_snapshot->>'valid_until') then
    valid_until:=(p_coordination_snapshot->>'valid_until')::timestamptz;
    if clock_timestamp()>=valid_until then
      return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED',
        'coordination_snapshot.valid_until',to_jsonb(valid_until),to_jsonb(clock_timestamp()));
    end if;
  end if;
  compiler_validation:=ops.assurance_validate_compiler_input(
    p_lease_id,p_compiler_input,p_manifest);
  if not coalesce((compiler_validation->>'ok')::boolean,false) then
    return compiler_validation;
  end if;

  if p_repository_stage is null or p_repository_stage<>all(array[
       'write','run_check','post_commit','push','pull_request','review','merge'])
     or p_idempotency_key is null
     or not coalesce(ops.assurance_exact_object(p_manifest,array[
       'schema_version','compiler','authority_state','verification_state','self_certification',
       'input_digest','input_bindings','slice','currentness','refusal_vocabulary','manifest_hash']),false)
     or p_manifest->>'schema_version'<>'assurance-execution-manifest.v1'
     or p_manifest->>'authority_state'<>'compiled_not_authorized'
     or p_manifest->>'verification_state'<>'unverified'
     or p_manifest->'self_certification'<>'false'::jsonb
     or p_manifest#>>'{compiler,id}'<>'carr-assurance-slice-compiler'
     or not coalesce(btrim(p_manifest#>>'{compiler,version}')<>'',false) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','manifest',
      '"closed A1a non-authorizing manifest and supported repository stage"'::jsonb,'"invalid"'::jsonb);
  end if;

  actual_manifest_hash:=ops.assurance_digest(p_manifest-'manifest_hash');
  if p_manifest->>'manifest_hash' is distinct from actual_manifest_hash then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','manifest.manifest_hash',
      to_jsonb(actual_manifest_hash),to_jsonb(p_manifest->>'manifest_hash'));
  end if;
  if not coalesce(ops.assurance_exact_object(p_applicable_rules,array[
       'schema_version','snapshot_ref','snapshot_digest','rules']),false)
     or p_applicable_rules->>'schema_version'<>'applicable-rule-snapshot.v1'
     or jsonb_typeof(p_applicable_rules->'rules')<>'array' then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','applicable_rules',
      '"normalized applicable-rule-snapshot.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  actual_rules_digest:=ops.assurance_digest(jsonb_build_object(
    'snapshot_ref',p_applicable_rules->'snapshot_ref','rules',p_applicable_rules->'rules'));
  if p_applicable_rules->>'snapshot_digest' is distinct from actual_rules_digest
     or p_manifest#>>'{input_bindings,applicable_rule_snapshot_digest}' is distinct from actual_rules_digest then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','applicable_rules.snapshot_digest',
      to_jsonb(actual_rules_digest),to_jsonb(p_applicable_rules->>'snapshot_digest'));
  end if;
  if not coalesce(ops.assurance_exact_object(p_coordination_snapshot,array[
       'schema_version','snapshot_digest','as_of','valid_until','manifest_phase',
       'requesting_session_id','requesting_host_id','leases','dependencies']),false)
     or p_coordination_snapshot->>'schema_version'<>'assurance-coordination-snapshot.v1'
     or jsonb_typeof(p_coordination_snapshot->'leases')<>'array'
     or jsonb_typeof(p_coordination_snapshot->'dependencies')<>'array' then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','coordination_snapshot',
      '"normalized assurance-coordination-snapshot.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  actual_coord_digest:=ops.assurance_digest(p_coordination_snapshot-'snapshot_digest');
  if p_coordination_snapshot->>'snapshot_digest' is distinct from actual_coord_digest
     or p_manifest#>>'{input_bindings,coordination_snapshot_digest}' is distinct from actual_coord_digest then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','coordination_snapshot.snapshot_digest',
      to_jsonb(actual_coord_digest),to_jsonb(p_coordination_snapshot->>'snapshot_digest'));
  end if;
  begin valid_until:=(p_coordination_snapshot->>'valid_until')::timestamptz;
  exception when others then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','coordination_snapshot.valid_until',
      '"valid timestamp"'::jsonb,'"invalid"'::jsonb);
  end;
  if clock_timestamp()>=valid_until
     or p_manifest#>>'{currentness,snapshot_valid_until}' is distinct from p_coordination_snapshot->>'valid_until' then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','coordination_snapshot.valid_until',
      to_jsonb(valid_until),to_jsonb(clock_timestamp()));
  end if;

  if p_manifest#>>'{input_bindings,work_request,id}' is distinct from 'wr:'||l.work_request_id::text
     or (p_manifest#>>'{input_bindings,work_request,state_version}')::integer is distinct from l.work_request_version
     or p_manifest#>>'{input_bindings,work_request,canonical_record_digest}' is distinct from l.work_request_digest
     or p_manifest#>>'{input_bindings,accepted_plan_revision,id}' is distinct from
        (select plan_ref from ops.sourced_work_request_plan where id=l.accepted_plan_id)
     or p_manifest#>>'{input_bindings,accepted_plan_revision,digest}' is distinct from l.accepted_plan_digest
     or p_manifest#>>'{input_bindings,engineering_slice_plan_digest}' is distinct from l.slice_plan_digest
     or p_manifest#>>'{input_bindings,assurance_slice_ownership_contract_digest}'
          is distinct from p_compiler_input#>>'{assurance_slice,ownership_contract_digest}'
     or p_manifest#>>'{slice,slice_ref}' is distinct from l.slice_ref
     or p_manifest#>>'{slice,lease_binding,lease_id}' is distinct from 'lease:'||l.id::text
     or (p_manifest#>>'{slice,lease_binding,fencing_generation}')::bigint is distinct from l.fencing_generation
     or p_manifest#>>'{slice,lease_binding,holder_session_id}' is distinct from l.holder_session_ref
     or p_manifest#>>'{slice,lease_binding,holder_host_id}' is distinct from l.holder_host_ref
     or p_manifest#>>'{slice,executor_identity,actor_ref}' is distinct from 'actor:'||l.holder_actor_slug
     or p_manifest#>>'{slice,executor_identity,session_ref}' is distinct from l.holder_session_ref
     or p_manifest#>>'{slice,executor_identity,host_ref}' is distinct from l.holder_host_ref
     or p_manifest#>>'{input_bindings,repository,commit_sha}' !~ '^[0-9a-f]{40}$'
     or p_manifest#>>'{input_bindings,repository,tree_sha}' !~ '^[0-9a-f]{40}$'
     or p_coordination_snapshot->>'requesting_session_id' is distinct from l.holder_session_ref
     or p_coordination_snapshot->>'requesting_host_id' is distinct from l.holder_host_ref
     or not exists (select 1 from jsonb_array_elements(p_coordination_snapshot->'leases') x
       where x->>'lease_id'='lease:'||l.id::text
         and (x->>'fencing_generation')::bigint=l.fencing_generation
         and x->>'holder_session_id'=l.holder_session_ref and x->>'holder_host_id'=l.holder_host_ref)
     or context->>'tenant' is distinct from l.organization_tenant_id
     or (context->>'actor_id')::uuid is distinct from l.holder_actor_id
     or context->>'session_ref' is distinct from l.holder_session_ref
     or context->>'host_ref' is distinct from l.holder_host_ref then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','manifest.lineage',
      '"exact current Work Request/plan/slice/lease/context bindings"'::jsonb,'"mismatch"'::jsonb);
  end if;
  if p_manifest#>>'{slice,reviewer_policy,minimum_independent_reviewers}'<>'1'
     or p_manifest#>'{slice,reviewer_policy,owner_acceptance_is_review}'<>'false'::jsonb
     or p_manifest#>'{slice,reviewer_policy,distinct_actor_and_session}'<>'true'::jsonb then
    return ops.assurance_refusal('REVIEWER_POLICY_UNSUPPORTED','manifest.slice.reviewer_policy',
      '{"minimum_independent_reviewers":1,"owner_acceptance_is_review":false,"distinct_actor_and_session":true}'::jsonb,
      p_manifest#>'{slice,reviewer_policy}');
  end if;

  select * into prior from ops.assurance_execution_manifest where idempotency_key=p_idempotency_key;
  if found then
    if prior.repository_stage=p_repository_stage and prior.manifest=p_manifest
       and prior.applicable_rules=p_applicable_rules and prior.coordination_snapshot=p_coordination_snapshot
       and prior.compiler_input=p_compiler_input
       and prior.lease_id=p_lease_id and prior.fencing_generation=p_fencing_generation then
      return jsonb_build_object('ok',true,'manifest_id',prior.id,'manifest_hash',prior.manifest_hash,'replayed',true);
    end if;
    return ops.assurance_refusal('IDEMPOTENCY_CONFLICT','assurance_execution_manifest.idempotency_key',
      '"exact prior request"'::jsonb,'"changed request"'::jsonb);
  end if;
  select * into prior from ops.assurance_execution_manifest where manifest_hash=p_manifest->>'manifest_hash';
  if found then
    if prior.repository_stage=p_repository_stage and prior.manifest=p_manifest
       and prior.compiler_input=p_compiler_input then
      return jsonb_build_object('ok',true,'manifest_id',prior.id,
        'manifest_hash',prior.manifest_hash,'replayed',true);
    end if;
    return ops.assurance_refusal('ASSURANCE_STAGE_MISMATCH','manifest.manifest_hash',
      to_jsonb(prior.repository_stage),to_jsonb(p_repository_stage));
  end if;

  now_at:=clock_timestamp();
  if now_at>=valid_until or l.expires_at<=now_at then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','manifest.snapshot_valid_until',
      to_jsonb(valid_until),to_jsonb(now_at));
  end if;
  insert into ops.assurance_execution_manifest(
    organization_tenant_id,work_request_id,accepted_plan_id,slice_plan_id,slice_ref,
    lease_id,fencing_generation,repository_stage,repository_commit_sha,repository_tree_sha,
    compiler_id,compiler_version,input_digest,manifest_hash,applicable_rule_snapshot_digest,
    coordination_snapshot_digest,snapshot_valid_until,applicable_rules,coordination_snapshot,
    compiler_input,ownership_contract_digest,manifest,idempotency_key,created_at)
  values(l.organization_tenant_id,l.work_request_id,l.accepted_plan_id,l.slice_plan_id,l.slice_ref,
    l.id,l.fencing_generation,p_repository_stage,
    p_manifest#>>'{input_bindings,repository,commit_sha}',p_manifest#>>'{input_bindings,repository,tree_sha}',
    p_manifest#>>'{compiler,id}',p_manifest#>>'{compiler,version}',p_manifest->>'input_digest',
    p_manifest->>'manifest_hash',actual_rules_digest,actual_coord_digest,valid_until,
    p_applicable_rules,p_coordination_snapshot,p_compiler_input,
    p_compiler_input#>>'{assurance_slice,ownership_contract_digest}',
    p_manifest,p_idempotency_key,now_at)
  returning * into inserted;
  return jsonb_build_object('ok',true,'manifest_id',inserted.id,'manifest_hash',inserted.manifest_hash,'replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or null_value_not_allowed then
  return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','manifest.typed_binding',
    '"well-typed exact bindings"'::jsonb,'"invalid"'::jsonb);
end $_$;


--
-- Name: record_assurance_owner_acceptance(uuid, uuid, text, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_assurance_owner_acceptance(p_review_manifest_id uuid, p_evidence_id uuid, p_decision text, p_acceptance jsonb, p_acceptance_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare authority_slug text; context jsonb; actor_row public.actor%rowtype;
        m ops.assurance_execution_manifest%rowtype; ev ops.assurance_evidence_extension%rowtype;
        em ops.assurance_execution_manifest%rowtype; prior ops.assurance_owner_acceptance_fact%rowtype;
        actual text; inserted ops.assurance_owner_acceptance_fact%rowtype;
        l ops.canonical_ownership_lease%rowtype; decided_at timestamptz; finished_at timestamptz;
        now_at timestamptz; lineage_current jsonb; lease_probe uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('assurance-owner-door',0));
  authority_slug:=ops.authority_actor_slug();
  context:=ops.canonical_ownership_context_v1();
  if not coalesce((context->>'ok')::boolean,false) then return context; end if;
  select * into actor_row from public.actor where slug=authority_slug and kind='human' and active for share;
  if authority_slug<>all(array['joe','dell']) or actor_row.id is null
     or context->>'actor_slug' is distinct from authority_slug
     or (context->>'actor_id')::uuid is distinct from actor_row.id then
    return ops.assurance_refusal('OWNER_IDENTITY_MISMATCH','owner.identity',
      jsonb_build_object('authority_slug',authority_slug,'context_actor_slug',authority_slug),
      jsonb_build_object('authority_context_equal',false));
  end if;
  select lease_id into lease_probe from ops.assurance_execution_manifest
   where id=p_review_manifest_id;
  if lease_probe is not null and exists (
    select 1 from ops.assurance_evidence_extension where id=p_evidence_id) then
    perform pg_advisory_xact_lock(hashtextextended('assurance-lease-scan',0));
    lineage_current:=ops.assurance_append_lineage_current(lease_probe,
      (select receipt_id from ops.assurance_evidence_extension where id=p_evidence_id),clock_timestamp());
    if not coalesce((lineage_current->>'ok')::boolean,false) then return lineage_current; end if;
    lock table ops.canonical_ownership_lease in share mode;
    lineage_current:=ops.assurance_append_lineage_current(lease_probe,
      (select receipt_id from ops.assurance_evidence_extension where id=p_evidence_id),clock_timestamp());
    if not coalesce((lineage_current->>'ok')::boolean,false) then return lineage_current; end if;
  end if;
  now_at:=clock_timestamp();
  select * into m from ops.assurance_execution_manifest where id=p_review_manifest_id for key share;
  select * into ev from ops.assurance_evidence_extension where id=p_evidence_id for key share;
  select * into em from ops.assurance_execution_manifest where id=ev.manifest_id for key share;
  select * into l from ops.canonical_ownership_lease where id=m.lease_id;
  if not ops.assurance_all_tokens_absent(jsonb_build_array(
       p_acceptance,to_jsonb(p_decision),to_jsonb(p_acceptance_digest),to_jsonb(p_idempotency_key))) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','assurance.token_nondisclosure',
      '"lease token absent from owner acceptance"'::jsonb,'"token_present"'::jsonb);
  end if;
  if p_decision is null or p_decision<>all(array['accept','hold','reject']) or p_idempotency_key is null
     or m.id is null or ev.id is null
     or not coalesce(ops.assurance_exact_object(p_acceptance,array[
       'schema_version','manifest_hash','evidence_digest','decision','owner_acceptance',
       'independent_review','actor_ref','session_ref','host_ref','reason','decided_at']),false)
     or jsonb_typeof(p_acceptance->'schema_version') is distinct from 'string'
     or p_acceptance->>'schema_version' is distinct from 'assurance-owner-acceptance.v1'
     or p_acceptance->'owner_acceptance' is distinct from 'true'::jsonb
     or p_acceptance->'independent_review' is distinct from 'false'::jsonb
     or exists(select 1 from unnest(array[
          'manifest_hash','evidence_digest','decision','actor_ref','session_ref','host_ref']) key
          where jsonb_typeof(p_acceptance->key) is distinct from 'string')
     or jsonb_typeof(p_acceptance->'reason')<>'string'
     or not coalesce(btrim(p_acceptance->>'reason')<>'',false)
     or not ops.assurance_timestamp_valid(p_acceptance->>'decided_at') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','owner_acceptance','"closed assurance-owner-acceptance.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  actual:=ops.assurance_digest(p_acceptance);
  if p_acceptance_digest is distinct from actual then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','acceptance_digest',to_jsonb(actual),to_jsonb(p_acceptance_digest));
  end if;
  if m.repository_stage is distinct from 'review' or em.repository_stage is distinct from 'post_commit'
     or m.repository_commit_sha is distinct from em.repository_commit_sha or m.repository_tree_sha is distinct from em.repository_tree_sha
     or m.work_request_id is distinct from em.work_request_id or m.accepted_plan_id is distinct from em.accepted_plan_id
     or m.slice_plan_id is distinct from em.slice_plan_id or m.slice_ref is distinct from em.slice_ref
     or m.lease_id is distinct from em.lease_id or m.fencing_generation is distinct from em.fencing_generation
     or m.manifest->'slice' is distinct from em.manifest->'slice'
     or m.organization_tenant_id is distinct from context->>'tenant'
     or p_acceptance->>'manifest_hash' is distinct from m.manifest_hash
     or p_acceptance->>'evidence_digest' is distinct from ev.evidence_digest
     or p_acceptance->>'decision' is distinct from p_decision
     or p_acceptance->>'actor_ref' is distinct from 'actor:'||authority_slug
     or p_acceptance->>'session_ref' is distinct from context->>'session_ref'
     or p_acceptance->>'host_ref' is distinct from context->>'host_ref' then
    return ops.assurance_refusal('OWNER_IDENTITY_MISMATCH','owner_acceptance.lineage','"exact authority/context/review-stage-manifest/evidence binding"'::jsonb,'"mismatch"'::jsonb);
  end if;
  if now_at>=m.snapshot_valid_until or (l.state='active' and l.expires_at<=now_at)
     or (l.state='released' and l.released_at is null) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','owner_acceptance.decided_at',
      '"live lease and review manifest window"'::jsonb,'"expired"'::jsonb);
  end if;
  select * into prior from ops.assurance_owner_acceptance_fact where idempotency_key=p_idempotency_key;
  if found then
    if prior.review_manifest_id=p_review_manifest_id and prior.evidence_id=p_evidence_id
       and prior.decision=p_decision and prior.acceptance=p_acceptance
       and prior.acceptance_digest=p_acceptance_digest and prior.owner_actor_id=actor_row.id then
      return jsonb_build_object('ok',true,'acceptance_id',prior.id,'decision',prior.decision,'replayed',true);
    end if;
    return ops.assurance_refusal('IDEMPOTENCY_CONFLICT','assurance_owner_acceptance_fact.idempotency_key','"exact prior request"'::jsonb,'"changed request"'::jsonb);
  end if;
  decided_at:=(p_acceptance->>'decided_at')::timestamptz;
  finished_at:=(ev.evidence#>>'{timestamps,finished_at}')::timestamptz;
  if decided_at<finished_at or decided_at>now_at
     or decided_at<now_at-interval '30 seconds'
     or decided_at>m.snapshot_valid_until then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','owner_acceptance.decided_at',
      '"evidence finished_at <= decided_at <= live manifest window"'::jsonb,'"invalid"'::jsonb);
  end if;
  now_at:=clock_timestamp();
  if now_at>=m.snapshot_valid_until then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','manifest.snapshot_valid_until',
      to_jsonb(m.snapshot_valid_until),to_jsonb(now_at));
  end if;
  if l.state='active' and l.expires_at<=now_at then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"active unexpired canonical lease at insert"'::jsonb,'"stale"'::jsonb);
  end if;
  insert into ops.assurance_owner_acceptance_fact(
    organization_tenant_id,review_manifest_id,evidence_id,owner_actor_id,owner_actor_slug,
    owner_session_ref,owner_host_ref,decision,acceptance_digest,acceptance,idempotency_key,created_at)
  values(context->>'tenant',p_review_manifest_id,p_evidence_id,actor_row.id,authority_slug,
    context->>'session_ref',context->>'host_ref',p_decision,p_acceptance_digest,p_acceptance,
    p_idempotency_key,now_at)
  returning * into inserted;
  return jsonb_build_object('ok',true,'acceptance_id',inserted.id,'decision',inserted.decision,'replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or null_value_not_allowed
                    or check_violation or foreign_key_violation or unique_violation then
  return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','owner_acceptance.typed_binding','"well-typed exact acceptance"'::jsonb,'"invalid"'::jsonb);
end $$;


--
-- Name: record_assurance_review_extension(uuid, uuid, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_assurance_review_extension(p_reviewer_fact_id uuid, p_review_manifest_id uuid, p_evidence_id uuid, p_review jsonb, p_review_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare f ops.engineering_reviewer_fact%rowtype; r ops.engineering_slice_receipt%rowtype;
        m ops.assurance_execution_manifest%rowtype; ev ops.assurance_evidence_extension%rowtype;
        em ops.assurance_execution_manifest%rowtype; prior ops.assurance_review_extension%rowtype;
        actual text; inserted ops.assurance_review_extension%rowtype;
        l ops.canonical_ownership_lease%rowtype; context jsonb; reviewer public.actor%rowtype;
        reviewed_at timestamptz; finished_at timestamptz; now_at timestamptz;
        lineage_current jsonb; lease_probe uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('assurance-review-door',0));
  context:=ops.canonical_ownership_context_v1();
  if not coalesce((context->>'ok')::boolean,false) then return context; end if;
  select lease_id into lease_probe from ops.assurance_execution_manifest
   where id=p_review_manifest_id;
  if lease_probe is not null and exists (
    select 1 from ops.assurance_evidence_extension where id=p_evidence_id) then
    perform pg_advisory_xact_lock(hashtextextended('assurance-lease-scan',0));
    lineage_current:=ops.assurance_append_lineage_current(lease_probe,
      (select receipt_id from ops.assurance_evidence_extension where id=p_evidence_id),clock_timestamp());
    if not coalesce((lineage_current->>'ok')::boolean,false) then return lineage_current; end if;
    lock table ops.canonical_ownership_lease in share mode;
    lineage_current:=ops.assurance_append_lineage_current(lease_probe,
      (select receipt_id from ops.assurance_evidence_extension where id=p_evidence_id),clock_timestamp());
    if not coalesce((lineage_current->>'ok')::boolean,false) then return lineage_current; end if;
  end if;
  now_at:=clock_timestamp();
  select * into f from ops.engineering_reviewer_fact where id=p_reviewer_fact_id for key share;
  select * into r from ops.engineering_slice_receipt where id=f.receipt_id for key share;
  select * into m from ops.assurance_execution_manifest where id=p_review_manifest_id for key share;
  select * into ev from ops.assurance_evidence_extension where id=p_evidence_id for key share;
  select * into em from ops.assurance_execution_manifest where id=ev.manifest_id for key share;
  select * into l from ops.canonical_ownership_lease where id=m.lease_id;
  select * into reviewer from public.actor where id=f.reviewer_actor_id and active for share;
  if not ops.assurance_all_tokens_absent(jsonb_build_array(
       p_review,to_jsonb(p_review_digest),to_jsonb(p_idempotency_key))) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','assurance.token_nondisclosure',
      '"lease token absent from review inputs"'::jsonb,'"token_present"'::jsonb);
  end if;
  if p_idempotency_key is null or f.id is null or r.id is null or m.id is null or ev.id is null
     or not coalesce(ops.assurance_exact_object(p_review,array[
       'schema_version','manifest_hash','evidence_digest','state','self_issued',
       'owner_acceptance','reviewer_actor_ref','reviewer_session_ref','reviewer_host_ref',
       'evidence_refs','reviewed_deviation_refs','resolved_deviation_refs','reviewed_at']),false)
     or jsonb_typeof(p_review->'schema_version') is distinct from 'string'
     or p_review->>'schema_version' is distinct from 'assurance-review.v1'
     or p_review->'self_issued' is distinct from 'false'::jsonb
     or p_review->'owner_acceptance' is distinct from 'false'::jsonb
     or jsonb_typeof(p_review->'manifest_hash') is distinct from 'string'
     or jsonb_typeof(p_review->'evidence_digest') is distinct from 'string'
     or jsonb_typeof(p_review->'state') is distinct from 'string'
     or not ops.assurance_identifier_valid(p_review->>'reviewer_actor_ref')
     or not ops.assurance_identifier_valid(p_review->>'reviewer_session_ref')
     or not ops.assurance_identifier_valid(p_review->>'reviewer_host_ref')
     or jsonb_typeof(p_review->'evidence_refs')<>'array'
     or jsonb_array_length(p_review->'evidence_refs')=0
     or jsonb_typeof(p_review->'reviewed_deviation_refs')<>'array'
     or jsonb_typeof(p_review->'resolved_deviation_refs')<>'array'
     or not coalesce(ops.assurance_unique_array(p_review->'evidence_refs'),false)
     or not coalesce(ops.assurance_unique_array(p_review->'reviewed_deviation_refs'),false)
     or not coalesce(ops.assurance_unique_array(p_review->'resolved_deviation_refs'),false)
     or not ops.assurance_timestamp_valid(p_review->>'reviewed_at') then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','review','"closed independent assurance-review.v1"'::jsonb,'"invalid"'::jsonb);
  end if;
  actual:=ops.assurance_digest(p_review);
  if p_review_digest is distinct from actual then
    return ops.assurance_refusal('ASSURANCE_DIGEST_MISMATCH','review_digest',to_jsonb(actual),to_jsonb(p_review_digest));
  end if;
  if m.repository_stage is distinct from 'review' or em.repository_stage is distinct from 'post_commit'
     or m.repository_commit_sha is distinct from em.repository_commit_sha or m.repository_tree_sha is distinct from em.repository_tree_sha
     or m.organization_tenant_id is distinct from em.organization_tenant_id
     or m.work_request_id is distinct from em.work_request_id or m.accepted_plan_id is distinct from em.accepted_plan_id
     or m.slice_plan_id is distinct from em.slice_plan_id or m.slice_ref is distinct from em.slice_ref
     or m.lease_id is distinct from em.lease_id or m.fencing_generation is distinct from em.fencing_generation
     or m.manifest->'slice' is distinct from em.manifest->'slice'
     or m.work_request_id is distinct from r.work_request_id or m.slice_ref is distinct from r.slice_ref or ev.receipt_id is distinct from r.id
     or f.contract_version is distinct from 'engineering-review.v1'
     or not coalesce(ops.assurance_exact_object(f.fact,array[
          'attempt_id','evidence_refs','is_independent','resolved_deviation_refs',
          'reviewed_deviation_refs','reviewer_ref','session_ref','slice_ref','state']),false)
     or reviewer.id is null or context->>'tenant' is distinct from m.organization_tenant_id
     or (context->>'actor_id')::uuid is distinct from f.reviewer_actor_id
     or context->>'session_ref' is distinct from f.reviewer_session_ref
     or p_review->>'reviewer_actor_ref' is distinct from 'actor:'||reviewer.slug
     or p_review->>'reviewer_session_ref' is distinct from f.reviewer_session_ref
     or p_review->>'reviewer_host_ref' is distinct from context->>'host_ref'
     or f.work_request_id is distinct from r.work_request_id or f.slice_ref is distinct from r.slice_ref
     or f.state is distinct from 'passed'
     or f.fact->'is_independent' is distinct from 'true'::jsonb
     or f.fact->>'attempt_id' is distinct from r.attempt_id
     or f.fact->>'slice_ref' is distinct from r.slice_ref
     or f.fact->>'state' is distinct from f.state
     or not coalesce(f.fact->>'reviewer_ref'=any(array[
          reviewer.slug,'actor:'||reviewer.slug,'reviewer:'||reviewer.slug]),false)
     or f.fact->>'session_ref' is distinct from f.reviewer_session_ref
     or f.fact->'evidence_refs' is distinct from p_review->'evidence_refs'
     or f.fact->'reviewed_deviation_refs' is distinct from p_review->'reviewed_deviation_refs'
     or f.fact->'resolved_deviation_refs' is distinct from p_review->'resolved_deviation_refs'
     or p_review->>'manifest_hash' is distinct from m.manifest_hash
     or p_review->>'evidence_digest' is distinct from ev.evidence_digest
     or p_review->>'state' is distinct from f.state then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','review.lineage','"exact review-stage manifest plus post-commit evidence"'::jsonb,'"mismatch"'::jsonb);
  end if;
  if f.reviewer_actor_id=r.executor_actor_id
     or f.reviewer_session_ref=r.receipt#>>'{attribution,session_ref}' then
    return ops.assurance_refusal('ASSURANCE_SELF_REVIEW','review.reviewer','"distinct actor and session"'::jsonb,'"self"'::jsonb);
  end if;
  if f.state='passed' and (ev.evidence#>>'{output,exit_code}')::integer<>0 then
    return ops.assurance_refusal('EVIDENCE_REQUIREMENT_MISMATCH','review.pass','"exit_code 0"'::jsonb,ev.evidence#>'{output,exit_code}');
  end if;
  reviewed_at:=(p_review->>'reviewed_at')::timestamptz;
  finished_at:=(ev.evidence#>>'{timestamps,finished_at}')::timestamptz;
  if now_at>=m.snapshot_valid_until or reviewed_at<finished_at or reviewed_at>now_at
     or reviewed_at is distinct from date_trunc('second',f.created_at)
     or reviewed_at>m.snapshot_valid_until or (l.state='active' and l.expires_at<=now_at)
     or (l.state='released' and l.released_at is null) then
    return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','review.reviewed_at',
      '"evidence completion <= reviewed_at <= live manifest window"'::jsonb,'"invalid"'::jsonb);
  end if;
  select * into prior from ops.assurance_review_extension where idempotency_key=p_idempotency_key;
  if found then
    if prior.reviewer_fact_id=p_reviewer_fact_id and prior.review_manifest_id=p_review_manifest_id
       and prior.evidence_id=p_evidence_id and prior.review=p_review and prior.review_digest=p_review_digest then
      return jsonb_build_object('ok',true,'review_id',prior.id,'review_digest',prior.review_digest,'replayed',true);
    end if;
    return ops.assurance_refusal('IDEMPOTENCY_CONFLICT','assurance_review_extension.idempotency_key','"exact prior request"'::jsonb,'"changed request"'::jsonb);
  end if;
  if exists (select 1 from ops.assurance_review_extension where reviewer_fact_id=p_reviewer_fact_id or evidence_id=p_evidence_id) then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','assurance_review_extension.one_to_one','"one existing independent review extension"'::jsonb,'"already exists"'::jsonb);
  end if;
  now_at:=clock_timestamp();
  if now_at>=m.snapshot_valid_until then
    return ops.assurance_refusal('ASSURANCE_SNAPSHOT_EXPIRED','manifest.snapshot_valid_until',
      to_jsonb(m.snapshot_valid_until),to_jsonb(now_at));
  end if;
  if l.state='active' and l.expires_at<=now_at then
    return ops.assurance_refusal('ASSURANCE_BINDING_STALE','lease.currentness',
      '"active unexpired canonical lease at insert"'::jsonb,'"stale"'::jsonb);
  end if;
  insert into ops.assurance_review_extension(
    reviewer_fact_id,review_manifest_id,evidence_id,review_digest,review,idempotency_key,created_at)
    values(p_reviewer_fact_id,p_review_manifest_id,p_evidence_id,p_review_digest,p_review,
      p_idempotency_key,now_at) returning * into inserted;
  return jsonb_build_object('ok',true,'review_id',inserted.id,'review_digest',inserted.review_digest,'replayed',false);
exception when invalid_text_representation or numeric_value_out_of_range or null_value_not_allowed
                    or check_violation or foreign_key_violation or unique_violation then
  return ops.assurance_refusal('ASSURANCE_INPUT_INVALID','review.typed_binding','"well-typed exact review"'::jsonb,'"invalid"'::jsonb);
end $$;


--
-- Name: record_attempt_receipt(text, text, text, uuid, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_attempt_receipt(p_work_request text, p_plan_hash text, p_envelope_digest text, p_activation_binding_id uuid, p_receipt jsonb, p_idempotency_key uuid) RETURNS TABLE(attempt_receipt_id uuid, attempt_id text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id', true); existing ops.attempt_receipt%rowtype; work_id uuid; envelope_id uuid;
begin
  if coalesce(tenant,'')='' then raise exception 'reliability record requires authenticated tenant context'; end if;
  select w.id into work_id from ops.work_request w
   join ops.context_activation_binding b on b.id=p_activation_binding_id and b.work_request_id=w.id
   join ops.sourced_work_request_plan p on p.id=b.plan_id
   join ops.sourced_work_request_plan_acceptance_receipt ar on ar.work_request_id=w.id and ar.plan_id=p.id
   where w.ref=p_work_request and w.organization_tenant_id=tenant and b.organization_tenant_id=tenant
     and b.expires_at>=now() and w.version=b.work_request_version and p.work_request_id=w.id
     and p.plan_hash=p_plan_hash and b.plan_hash=p_plan_hash
     and ar.plan_hash=p_plan_hash and ar.result_version=w.version;
  if work_id is null then raise exception 'reliability Work Request is not visible to tenant'; end if;
  if jsonb_typeof(p_receipt) <> 'object' or p_receipt->>'schema_version' <> 'attempt-receipt.v1'
     or p_receipt->>'envelope_digest' <> p_envelope_digest or coalesce(p_receipt->>'attempt_id','') = '' then
    raise exception 'exact attempt receipt v1/envelope binding is required';
  end if;
  select id into envelope_id from ops.execution_envelope_v1
   where organization_tenant_id=tenant and work_request_id=work_id and plan_hash=p_plan_hash
     and activation_binding_id=p_activation_binding_id and envelope_digest=p_envelope_digest;
  if envelope_id is null then raise exception 'attempt receipt requires exact server-issued execution envelope'; end if;
  select * into existing from ops.attempt_receipt where organization_tenant_id=tenant and idempotency_key=p_idempotency_key;
  if found then
    if existing.work_request_id<>work_id or existing.attempt_id<>p_receipt->>'attempt_id' or existing.envelope_digest<>p_envelope_digest or existing.receipt is distinct from p_receipt then raise exception 'attempt receipt idempotency conflict'; end if;
    return query select existing.id, existing.attempt_id, true; return;
  end if;
  insert into ops.attempt_receipt(idempotency_key,organization_tenant_id,work_request_id,plan_hash,envelope_digest,attempt_id,activation_binding_id,execution_envelope_id,receipt)
  values(p_idempotency_key,tenant,work_id,p_plan_hash,p_envelope_digest,p_receipt->>'attempt_id',p_activation_binding_id,envelope_id,p_receipt)
  returning id, ops.attempt_receipt.attempt_id into attempt_receipt_id, attempt_id;
  -- Observatory telemetry is generated from the admitted canonical receipt,
  -- never accepted from executor-supplied telemetry JSON.
  insert into ops.activation_reliability_telemetry(organization_tenant_id,attempt_receipt_id,signal_id,trigger_ref,consumer_ref,enforcement,owner_ref,remedy_ref,verification_ref,auto_clear,state)
  values(tenant,attempt_receipt_id,'telemetry:knowledge-activation','trigger:required-knowledge-closure','consumer:observatory','enforcement:block-reliability-closure','owner:execution-governance','remedy:resolve-required-activation','verification:canonical-receipt-binding',true,
    case when p_receipt->'knowledge_activation'->'closure'->>'state'='closed' then 'verified' else 'open' end);
  return query select attempt_receipt_id, attempt_id, false;
end $$;


--
-- Name: calendar_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    source_snapshot_id uuid NOT NULL,
    source_snapshot_digest text NOT NULL,
    source_contact_count integer NOT NULL,
    output_digest text NOT NULL,
    exact_count integer NOT NULL,
    domain_count integer NOT NULL,
    unknown_count integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT calendar_canary_receipt_domain_count_check CHECK ((domain_count >= 0)),
    CONSTRAINT calendar_canary_receipt_exact_count_check CHECK ((exact_count >= 0)),
    CONSTRAINT calendar_canary_receipt_output_digest_check CHECK ((output_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_canary_receipt_unknown_count_check CHECK ((unknown_count >= 0))
);


--
-- Name: record_calendar_canary_receipt(uuid, uuid, uuid, text, integer, integer, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_calendar_canary_receipt(p_job_id uuid, p_lease uuid, p_source_snapshot_id uuid, p_output_digest text, p_exact integer, p_domain integer, p_unknown integer) RETURNS ops.calendar_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare j ops.job%rowtype;s ops.calendar_canary_source_snapshot%rowtype;r ops.calendar_canary_receipt%rowtype;e ops.calendar_canary_receipt%rowtype;
begin
 j:=ops.calendar_canary_live_job(p_job_id,p_lease); select * into s from ops.calendar_canary_source_snapshot where id=p_source_snapshot_id and job_id=j.id and attempt=j.attempt;
 if not found then raise exception using errcode='22023',message='source snapshot is not bound to this job attempt'; end if;
 if p_output_digest!~'^[0-9a-f]{64}$' or p_exact<0 or p_domain<0 or p_unknown<0 then raise exception using errcode='22023',message='invalid calendar canary aggregate'; end if;
 insert into ops.calendar_canary_receipt(job_id,attempt,source_snapshot_id,source_snapshot_digest,source_contact_count,output_digest,exact_count,domain_count,unknown_count)
 values(j.id,j.attempt,s.id,s.snapshot_digest,s.contact_count,p_output_digest,p_exact,p_domain,p_unknown) on conflict(job_id,attempt) do nothing returning * into r;
 if found then return r; end if; select * into e from ops.calendar_canary_receipt where job_id=j.id and attempt=j.attempt;
 if e.source_snapshot_id<>s.id or e.output_digest<>p_output_digest or e.exact_count<>p_exact or e.domain_count<>p_domain or e.unknown_count<>p_unknown then raise exception using errcode='23505',message='calendar canary receipt replay conflicts with immutable attempt'; end if; return e;
end $_$;


--
-- Name: calendar_prebrief_source_attestation_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_source_attestation_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    lease_token uuid CONSTRAINT calendar_prebrief_source_attestation_recei_lease_token_not_null NOT NULL,
    sponsor text NOT NULL,
    attestor_identity text CONSTRAINT calendar_prebrief_source_attestation_attestor_identity_not_null NOT NULL,
    mode text NOT NULL,
    destination text CONSTRAINT calendar_prebrief_source_attestation_recei_destination_not_null NOT NULL,
    snapshot_at timestamp with time zone CONSTRAINT calendar_prebrief_source_attestation_recei_snapshot_at_not_null NOT NULL,
    allowlist_revision_id uuid CONSTRAINT calendar_prebrief_source_attesta_allowlist_revision_id_not_null NOT NULL,
    capture_challenge_id uuid CONSTRAINT calendar_prebrief_source_attestat_capture_challenge_id_not_null NOT NULL,
    allowlist_digest text CONSTRAINT calendar_prebrief_source_attestation__allowlist_digest_not_null NOT NULL,
    observed_calendar_keys text[] CONSTRAINT calendar_prebrief_source_attest_observed_calendar_keys_not_null NOT NULL,
    event_count integer CONSTRAINT calendar_prebrief_source_attestation_recei_event_count_not_null NOT NULL,
    canonical_event_digest text CONSTRAINT calendar_prebrief_source_attest_canonical_event_digest_not_null NOT NULL,
    collector_key_fingerprint text CONSTRAINT calendar_prebrief_source_att_collector_key_fingerprint_not_null NOT NULL,
    signature_sha256 text CONSTRAINT calendar_prebrief_source_attestation__signature_sha256_not_null NOT NULL,
    collector_version text CONSTRAINT calendar_prebrief_source_attestation_collector_version_not_null NOT NULL,
    attested_at timestamp with time zone DEFAULT now() CONSTRAINT calendar_prebrief_source_attestation_recei_attested_at_not_null NOT NULL,
    CONSTRAINT calendar_prebrief_source_attest_collector_key_fingerprint_check CHECK ((collector_key_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestati_canonical_event_digest_check CHECK ((canonical_event_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_re_attestor_identity_check CHECK ((attestor_identity = ANY (ARRAY['carr_calendar_prebrief_attestor_joe'::text, 'carr_calendar_prebrief_attestor_dell'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_re_collector_version_check CHECK ((collector_version ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_rec_allowlist_digest_check CHECK ((allowlist_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_rec_signature_sha256_check CHECK ((signature_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_destination_check CHECK ((destination = ANY (ARRAY['live'::text, 'calendar-prebrief-canary-joe'::text, 'calendar-prebrief-canary-dell'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_event_count_check CHECK (((event_count >= 0) AND (event_count <= 128))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_mode_check CHECK ((mode = ANY (ARRAY['live'::text, 'canary'::text]))),
    CONSTRAINT calendar_prebrief_source_attestation_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: record_calendar_prebrief_verified_envelope(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone, uuid, text, text[], text[], jsonb, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_calendar_prebrief_verified_envelope(p_job_id uuid, p_lease uuid, p_challenge_id uuid, p_scheduled_for timestamp with time zone, p_window_starts_at timestamp with time zone, p_window_ends_at timestamp with time zone, p_allowlist_revision_id uuid, p_allowlist_digest text, p_calendar_keys text[], p_observed_calendar_keys text[], p_events jsonb, p_destination text, p_collector_key_fingerprint text, p_signature_sha256 text, p_collector_version text) RETURNS ops.calendar_prebrief_source_attestation_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare v_job ops.job%rowtype; v_challenge ops.calendar_prebrief_capture_challenge%rowtype;
  v_existing ops.calendar_prebrief_source_attestation_receipt%rowtype; v_attestor_sponsor text;
  v_current_keys text[]; v_current_digest text; v_current_revision uuid; v_observed text[]; v_event_count integer; v_event_digest text;
begin
  v_attestor_sponsor:=ops.calendar_prebrief_attestor_sponsor();
  if p_challenge_id is null or p_signature_sha256 is null or p_signature_sha256 !~ '^[0-9a-f]{64}$'
     or p_collector_key_fingerprint is null or p_collector_key_fingerprint !~ '^[0-9a-f]{64}$'
     or p_collector_version is null or p_collector_version !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires bounded signed claim and collector evidence';
  end if;
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.state<>'running' or v_job.lease_token is distinct from p_lease or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='calendar prebrief verified envelope requires current live job lease';
  end if;
  select * into v_challenge from ops.calendar_prebrief_capture_challenge where id=p_challenge_id for update;
  if not found or v_challenge.job_id<>v_job.id or v_challenge.attempt<>v_job.attempt or v_challenge.lease_token<>p_lease
     or v_challenge.sponsor<>v_attestor_sponsor or v_challenge.scheduled_for<>p_scheduled_for
     or v_challenge.window_starts_at<>p_window_starts_at or v_challenge.window_ends_at<>p_window_ends_at
     or v_challenge.allowlist_revision_id<>p_allowlist_revision_id or v_challenge.allowlist_digest<>p_allowlist_digest
     or v_challenge.calendar_keys is distinct from p_calendar_keys or v_challenge.destination<>p_destination or v_challenge.mode<>v_job.mode then
    raise exception using errcode='42501',message='calendar prebrief verified envelope signed claim does not match its DB-issued capture contract';
  end if;
  select calendar_keys,configuration_digest,active_revision_id into v_current_keys,v_current_digest,v_current_revision
    from ops.calendar_prebrief_allowed_calendar where sponsor=v_challenge.sponsor for update;
  if not found or v_current_revision<>v_challenge.allowlist_revision_id or v_current_digest<>v_challenge.allowlist_digest
     or v_current_keys is distinct from v_challenge.calendar_keys then
    raise exception using errcode='22023',message='calendar prebrief verified envelope capture contract is stale against DB allowlist';
  end if;
  select array_agg(k order by k) into v_observed from unnest(coalesce(p_observed_calendar_keys,'{}'::text[])) keys(k);
  if v_observed is distinct from v_challenge.calendar_keys then
    raise exception using errcode='22023',message='calendar prebrief verified envelope requires exact signed allowlist coverage';
  end if;
  select event_count,canonical_event_digest into v_event_count,v_event_digest from ops.calendar_prebrief_canonical_event_digest(p_events);
  perform pg_advisory_xact_lock(hashtextextended('calendar-prebrief-source:' || v_job.id::text,0));
  select * into v_existing from ops.calendar_prebrief_source_attestation_receipt where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_existing.capture_challenge_id<>p_challenge_id or v_existing.lease_token<>p_lease or v_existing.sponsor<>v_challenge.sponsor
       or v_existing.attestor_identity<>session_user or v_existing.mode<>v_challenge.mode or v_existing.destination<>p_destination
       or v_existing.snapshot_at<>p_scheduled_for or v_existing.allowlist_revision_id<>p_allowlist_revision_id
       or v_existing.allowlist_digest<>p_allowlist_digest or v_existing.observed_calendar_keys is distinct from v_observed
       or v_existing.event_count<>v_event_count or v_existing.canonical_event_digest<>v_event_digest
       or v_existing.collector_key_fingerprint<>p_collector_key_fingerprint or v_existing.signature_sha256<>p_signature_sha256
       or v_existing.collector_version<>p_collector_version then
      raise exception using errcode='23505',message='calendar prebrief verified envelope replay conflicts with immutable attempt';
    end if;
    return v_existing;
  end if;
  if exists(select 1 from ops.calendar_prebrief_source_attestation_receipt where capture_challenge_id=p_challenge_id or signature_sha256=p_signature_sha256) then
    raise exception using errcode='23505',message='calendar prebrief verified envelope challenge or signature was already consumed';
  end if;
  insert into ops.calendar_prebrief_source_attestation_receipt
    (job_id,attempt,lease_token,sponsor,attestor_identity,mode,destination,snapshot_at,allowlist_revision_id,capture_challenge_id,allowlist_digest,observed_calendar_keys,event_count,canonical_event_digest,collector_key_fingerprint,signature_sha256,collector_version)
  values(v_job.id,v_job.attempt,p_lease,v_challenge.sponsor,session_user,v_challenge.mode,p_destination,p_scheduled_for,p_allowlist_revision_id,p_challenge_id,p_allowlist_digest,v_observed,v_event_count,v_event_digest,p_collector_key_fingerprint,p_signature_sha256,p_collector_version)
  returning * into v_existing;
  return v_existing;
end $_$;


--
-- Name: record_claude_scheduler_observation(text, text, text, text, boolean, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_claude_scheduler_observation(p_surface_id text, p_provider_task_id text, p_cron_expression text, p_timezone text, p_enabled boolean, p_definition_sha256 text, p_provider_revision text, p_source_fingerprint text, p_observed_at timestamp with time zone, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  principal ops.device_evidence_principal%rowtype;
  contract ops.legacy_schedule_provider_contract%rowtype;
  existing ops.legacy_schedule_observation_receipt%rowtype;
  state text;
  ref text;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'scheduler observation session user is not an active provisioned device principal';
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'scheduler observation idempotency key is required';
  end if;
  if btrim(coalesce(p_surface_id,''))='' or btrim(coalesce(p_provider_task_id,''))=''
     or btrim(coalesce(p_cron_expression,''))='' or btrim(coalesce(p_timezone,''))=''
     or p_enabled is null then
    raise exception 'scheduler observation identity, recurrence, and state are required';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < now() - interval '15 minutes' then
    raise exception 'scheduler observation is outside the freshness window';
  end if;
  if coalesce(p_definition_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source_fingerprint,'') !~ '^[0-9a-f]{64}$'
     or btrim(coalesce(p_provider_revision,''))='' then
    raise exception 'scheduler observation provenance is malformed';
  end if;

  select * into contract from ops.legacy_schedule_provider_contract
   where surface_id=p_surface_id for share;
  if not found then raise exception 'scheduler provider surface is not registered'; end if;
  if p_provider_task_id <> contract.locator
     or p_cron_expression <> contract.cron_expression
     or p_timezone <> contract.timezone
     or p_definition_sha256 <> contract.definition_sha256 then
    raise exception 'scheduler observation does not match the registered provider contract';
  end if;
  state := case when p_enabled then 'enabled' else 'disabled' end;

  select * into existing from ops.legacy_schedule_observation_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.surface_id<>p_surface_id or existing.locator<>p_provider_task_id
       or existing.scheduler_state<>state or existing.cron_expression<>p_cron_expression
       or existing.timezone<>p_timezone or existing.definition_sha256<>p_definition_sha256
       or existing.provider_revision<>p_provider_revision
       or existing.source_fingerprint<>p_source_fingerprint
       or existing.observed_at<>p_observed_at or existing.device_id<>principal.device_id then
      raise exception 'scheduler observation idempotency key was reused with different evidence';
    end if;
    return existing.receipt_ref;
  end if;

  ref := 'scheduler-observation:' || p_idempotency_key;
  insert into ops.legacy_schedule_observation_receipt
    (receipt_ref,idempotency_key,surface_id,workflow_key,workflow_version,locator,
     scheduler_state,cron_expression,timezone,definition_sha256,provider_revision,
     source_fingerprint,observed_at,device_id)
  values
    (ref,p_idempotency_key,contract.surface_id,contract.workflow_key,contract.workflow_version,
     contract.locator,state,contract.cron_expression,contract.timezone,contract.definition_sha256,
     p_provider_revision,p_source_fingerprint,p_observed_at,principal.device_id);
  return ref;
end $_$;


--
-- Name: record_device_evidence(uuid, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_device_evidence(p_job_id uuid, p_builder_key text, p_observed_at timestamp with time zone, p_values jsonb, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  principal ops.device_evidence_principal%rowtype;
  j ops.job%rowtype;
  existing ops.device_evidence_receipt%rowtype;
  expected_workflow text;
  expected_platform text;
  posts jsonb;
  post jsonb;
  result_id uuid;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'device evidence session user is not an active provisioned principal';
  end if;

  select * into j from ops.job where id=p_job_id for share;
  if not found then raise exception 'device evidence job does not exist'; end if;
  if j.state not in ('queued','retry_wait','running') then
    raise exception 'device evidence job is not open for collection';
  end if;

  case p_builder_key
    when 'linkedin.source-posts' then
      expected_workflow := 'linkedin-engagement-daily';
      expected_platform := 'linkedin';
    when 'x.source-posts' then
      expected_workflow := 'x-reply-run-daily';
      expected_platform := 'x';
    else raise exception 'device evidence builder is not registered';
  end case;
  if j.definition_key <> expected_workflow then
    raise exception 'device evidence builder does not match ledger workflow';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < j.scheduled_for - interval '24 hours'
     or p_observed_at > j.scheduled_for + interval '24 hours' then
    raise exception 'device evidence is outside the registered job freshness window';
  end if;
  if jsonb_typeof(p_values) <> 'object'
     or (p_values - array['platform','collector_state','source_posts','voice_version']) <> '{}'::jsonb
     or p_values->>'platform' <> expected_platform
     or p_values->>'collector_state' <> 'available'
     or jsonb_typeof(p_values->'voice_version') <> 'number'
     or (p_values->>'voice_version')::integer <= 0
     or jsonb_typeof(p_values->'source_posts') <> 'array' then
    raise exception 'device evidence envelope does not match the registered schema';
  end if;
  posts := p_values->'source_posts';
  if (p_builder_key='linkedin.source-posts' and jsonb_array_length(posts) not between 3 and 5)
     or (p_builder_key='x.source-posts' and jsonb_array_length(posts) not between 1 and 20) then
    raise exception 'device evidence post count is outside the registered range';
  end if;
  for post in select value from jsonb_array_elements(posts) loop
    if jsonb_typeof(post) <> 'object'
       or btrim(coalesce(post->>'url',''))='' then
      raise exception 'device evidence post lacks its source URL';
    end if;
    if p_builder_key='linkedin.source-posts'
       and jsonb_typeof(post->'network_priority') <> 'boolean' then
      raise exception 'LinkedIn device evidence lacks network priority';
    end if;
    if p_builder_key='x.source-posts'
       and btrim(coalesce(post->>'read_at',''))='' then
      raise exception 'X device evidence lacks actual-read timestamp';
    end if;
  end loop;

  select * into existing from ops.device_evidence_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.job_id<>p_job_id or existing.builder_key<>p_builder_key
       or existing.device_id<>principal.device_id
       or existing.observed_at<>p_observed_at or existing.evidence<>p_values then
      raise exception 'device evidence idempotency key was reused with different evidence';
    end if;
    return existing.id;
  end if;

  insert into ops.device_evidence_receipt
    (job_id,builder_key,workflow_key,workflow_version,mode,scheduled_for,
     device_id,observed_at,evidence,idempotency_key)
  values
    (j.id,p_builder_key,j.definition_key,j.definition_version,j.mode,j.scheduled_for,
     principal.device_id,p_observed_at,p_values,p_idempotency_key)
  returning id into result_id;
  return result_id;
end $$;


--
-- Name: record_dispatch_link(uuid, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_dispatch_link(p_turn_msg_id uuid, p_session_id text, p_work_request_id uuid, p_dispatch_ref uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_slug text; v_id bigint; v_key text; v_turn_id bigint;
        v_prior public.room_dispatch_link%rowtype;
begin
  v_actor := ops.portfolio_writer_actor_id();
  select a.slug into v_slug from public.actor a where a.id = v_actor;
  -- THE RESTRICTION, INSIDE THE DEFINER. Any other derived identity -- even
  -- one that holds execute on this function -- is refused here.
  if v_slug is distinct from 'hermes-pilot' then
    return jsonb_build_object('ok', false,
      'reason_id', 'dispatch_link_hermes_pilot_only');
  end if;
  if p_dispatch_ref is null then
    return jsonb_build_object('ok', false, 'reason_id', 'dispatch_ref_required');
  end if;
  v_key := nullif(btrim(coalesce(p_session_id, '')), '');
  if v_key is null then
    return jsonb_build_object('ok', false, 'reason_id', 'session_id_required');
  end if;
  -- THE CALLER NAMES THE TURN BY ITS msg_id, which is what the bridge holds in
  -- its hand at the moment it appends the turn. The bigserial id is resolved
  -- here, so no caller has to have read the row back to write the link.
  select t.id into v_turn_id
    from public.partner_room_turn t where t.msg_id = p_turn_msg_id;
  if v_turn_id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'dispatch_turn_not_found');
  end if;

  -- IDEMPOTENT ON THE ASSIGNMENT ITSELF, not only on the minted key. One
  -- assignment is one link row: a bridge that retried a cycle and minted a
  -- fresh dispatch_ref for a turn it had already linked would otherwise leave
  -- two links for one assignment, and `sent` would be proved twice.
  select * into v_prior from public.room_dispatch_link
   where turn_id = v_turn_id and session_id = v_key;
  if v_prior.id is not null then
    return jsonb_build_object('ok', true, 'deduplicated', true, 'id', v_prior.id,
      'dispatch_ref', v_prior.dispatch_ref, 'turn_id', v_prior.turn_id,
      'turn_msg_id', p_turn_msg_id,
      'session_id', v_prior.session_id, 'written_by', v_prior.written_by);
  end if;

  insert into public.room_dispatch_link(
    turn_id, session_id, work_request_id, dispatch_ref, written_by)
  values (v_turn_id, v_key, p_work_request_id, p_dispatch_ref, v_slug)
  on conflict (dispatch_ref) do nothing
  returning id into v_id;

  if v_id is null then
    select * into v_prior from public.room_dispatch_link
     where dispatch_ref = p_dispatch_ref;
    if v_prior.id is null then
      return jsonb_build_object('ok', false, 'reason_id', 'dedup_row_vanished');
    end if;
    if v_prior.turn_id is distinct from v_turn_id
       or v_prior.session_id is distinct from v_key
       or v_prior.work_request_id is distinct from p_work_request_id then
      return jsonb_build_object('ok', false,
        'reason_id', 'dispatch_ref_reuse', 'dispatch_ref', p_dispatch_ref);
    end if;
    return jsonb_build_object('ok', true, 'deduplicated', true, 'id', v_prior.id,
      'dispatch_ref', v_prior.dispatch_ref, 'turn_id', v_prior.turn_id,
      'turn_msg_id', p_turn_msg_id,
      'session_id', v_prior.session_id, 'written_by', v_prior.written_by);
  end if;

  return jsonb_build_object('ok', true, 'deduplicated', false, 'id', v_id,
    'dispatch_ref', p_dispatch_ref, 'turn_id', v_turn_id,
    'turn_msg_id', p_turn_msg_id,
    'session_id', v_key, 'written_by', v_slug);
end $$;


--
-- Name: FUNCTION record_dispatch_link(p_turn_msg_id uuid, p_session_id text, p_work_request_id uuid, p_dispatch_ref uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.record_dispatch_link(p_turn_msg_id uuid, p_session_id text, p_work_request_id uuid, p_dispatch_ref uuid) IS 'WR-000119: the ONLY writer of public.room_dispatch_link. The caller is derived from the server-installed transaction context and refused inside this body unless it is hermes-pilot, so the room bridge being the sole minter of a dispatch link is a database fact and not a handler courtesy. dispatch_ref is the idempotency key and the row identity, so a replay is one row and a reused key with different content is refused.';


--
-- Name: record_executed_lease(text, integer, date, date, date, integer, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_executed_lease(p_deal text, p_base_version integer, p_executed_on date, p_commencement_on date, p_expiration_on date, p_term_months integer, p_evidence_kind text, p_evidence_ref text, p_source text) RETURNS TABLE(lease_id uuid, version integer, superseded_lease_id uuid, deal_id uuid, client_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_deal_ids uuid[];
  v_deal_id uuid;
  v_client_id uuid;
  v_owner_id uuid;
  v_current_id uuid;
  v_current_version integer;
  v_new_id uuid;
  v_new_version integer;
begin
  v_actor_slug:=ops.authority_actor_slug();
  select id into v_actor_id from actor where slug=v_actor_slug and active;
  if v_actor_id is null then raise exception 'lease authority actor is unavailable'; end if;
  if nullif(btrim(coalesce(p_deal,'')),'') is null then raise exception 'deal is required'; end if;
  if p_deal ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select array_agg(id) into v_deal_ids from deal where id=p_deal::uuid;
  else
    select array_agg(id order by id) into v_deal_ids from deal where lower(name)=lower(btrim(p_deal));
  end if;
  if coalesce(array_length(v_deal_ids,1),0)=0 then raise exception 'lease deal was not found'; end if;
  if array_length(v_deal_ids,1)<>1 then raise exception 'lease deal needs exact disambiguation'; end if;
  v_deal_id:=v_deal_ids[1];

  perform pg_advisory_xact_lock(hashtextextended('executed-lease:'||v_deal_id::text,0));
  select d.client_id,
         coalesce((select dp.actor_id from deal_participant dp
                    where dp.deal_id=d.id and dp.role='lead' and dp.to_at is null limit 1),
                  c.created_by)
    into v_client_id,v_owner_id
    from deal d join client c on c.id=d.client_id
   where d.id=v_deal_id;
  if v_owner_id is distinct from v_actor_id then
    raise exception 'lease authority does not own the current deal';
  end if;
  if p_executed_on is null or p_expiration_on is null then
    raise exception 'executed_on and expiration_on are required';
  end if;
  if p_commencement_on is not null and p_expiration_on<=p_commencement_on then
    raise exception 'lease expiration must follow commencement';
  end if;
  if p_term_months is not null and (p_term_months<1 or p_term_months>480) then
    raise exception 'lease term_months is outside 1..480';
  end if;
  if p_evidence_kind not in ('executed_lease','lease_amendment','lease_abstract') then
    raise exception 'lease evidence kind is not admitted';
  end if;
  if nullif(btrim(coalesce(p_evidence_ref,'')),'') is null or length(p_evidence_ref)>1000 then
    raise exception 'lease evidence reference is required and bounded';
  end if;
  if nullif(btrim(coalesce(p_source,'')),'') is null or length(p_source)>500 then
    raise exception 'lease source is required and bounded';
  end if;

  select l.id,l.version into v_current_id,v_current_version
    from lease l where l.deal_id=v_deal_id and l.status='current' for update;
  if v_current_id is not null and p_base_version is distinct from v_current_version then
    raise exception 'lease version conflict: expected %',v_current_version;
  end if;
  if v_current_id is null and p_base_version is not null then
    raise exception 'no current lease exists for supplied base version';
  end if;
  if v_current_id is not null then
    update lease as held set status='superseded',superseded_at=now(),updated_by=v_actor_id
     where held.id=v_current_id and held.version=v_current_version and held.status='current';
    if not found then raise exception 'lease version conflict during replacement'; end if;
  end if;
  insert into lease
    (deal_id,client_id,owner_id,executed_on,commencement_on,expiration_on,term_months,
     evidence_kind,evidence_ref,source,created_by,updated_by,status,supersedes_lease_id)
  values
    (v_deal_id,v_client_id,v_actor_id,p_executed_on,p_commencement_on,p_expiration_on,p_term_months,
     p_evidence_kind,btrim(p_evidence_ref),btrim(p_source),v_actor_id,v_actor_id,'current',v_current_id)
  returning id,lease.version into v_new_id,v_new_version;
  lease_id:=v_new_id; version:=v_new_version; superseded_lease_id:=v_current_id;
  deal_id:=v_deal_id; client_id:=v_client_id;
  return next;
end $_$;


--
-- Name: record_guidance_decision(uuid, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_guidance_decision(p_revision_id uuid, p_state text, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  authority_slug text;
  authority_actor uuid;
  item_id uuid;
  revision_hash text;
  receipt_id uuid;
  binding_id uuid;
  event_id uuid;
  receipt_kind text;
  receipt_decision text;
  existing record;
begin
  authority_slug := ops.authority_actor_slug();
  select id into authority_actor from actor
   where slug=authority_slug and kind='human';
  if authority_actor is null then
    raise exception 'guidance decision requires an admitted human authority actor';
  end if;
  if p_state not in ('active','retired','superseded') then
    raise exception 'unsupported guidance lifecycle decision %',p_state;
  end if;
  if coalesce(btrim(p_idempotency_key),'')='' or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance decision requires idempotency key and reason';
  end if;
  select guidance_item_id,ops.guidance_revision_contract_hash(id)
    into item_id,revision_hash
    from ops.guidance_revision where id=p_revision_id;
  if item_id is null or revision_hash is null then
    raise exception 'unknown guidance revision %',p_revision_id;
  end if;
  receipt_kind := case p_state
    when 'active' then 'activation'
    when 'retired' then 'rejection'
    else 'amendment' end;
  receipt_decision := case p_state
    when 'active' then 'approved'
    when 'retired' then 'retired'
    else 'superseded' end;

  select ar.id,ar.kind,ar.subject_type,ar.subject_id,ar.actor_id,ar.decision,
         ar.contract_hash,le.id as event_id
    into existing
    from ops.authority_receipt ar
    left join ops.guidance_authority_binding b on b.authority_receipt_id=ar.id
    left join ops.guidance_lifecycle_event le
      on le.authority_binding_id=b.id and le.state=p_state
   where ar.idempotency_key=p_idempotency_key;
  if existing.id is not null then
    if existing.kind<>receipt_kind or existing.subject_type<>'guidance'
       or existing.subject_id<>item_id or existing.actor_id<>authority_actor
       or existing.decision<>receipt_decision
       or existing.contract_hash is distinct from revision_hash
       or existing.event_id is null then
      raise exception 'idempotency key already names a different or incomplete guidance decision';
    end if;
    return existing.event_id;
  end if;

  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,
     contract_hash,evidence_refs)
  values
    (p_idempotency_key,receipt_kind,'guidance',item_id,authority_actor,
     receipt_decision,revision_hash,array[p_revision_id::text])
  returning id into receipt_id;
  insert into ops.guidance_authority_binding
    (guidance_revision_id,authority_receipt_id,contract_hash)
  values (p_revision_id,receipt_id,revision_hash)
  returning id into binding_id;
  insert into ops.guidance_lifecycle_event
    (guidance_revision_id,state,authority_binding_id,reason)
  values (p_revision_id,p_state,binding_id,p_reason)
  returning id into event_id;
  return event_id;
end $$;


--
-- Name: record_launchd_scheduler_observation(text, text, text, boolean, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_launchd_scheduler_observation(p_surface_id text, p_label text, p_timezone text, p_enabled boolean, p_plist_sha256 text, p_schedule_sha256 text, p_launchctl_revision text, p_source_fingerprint text, p_observed_at timestamp with time zone, p_idempotency_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  principal ops.device_evidence_principal%rowtype;
  contract ops.legacy_schedule_launchd_contract%rowtype;
  existing ops.legacy_schedule_observation_receipt%rowtype;
  state text;
  ref text;
begin
  select * into principal from ops.device_evidence_principal
   where login_role=session_user and active;
  if not found then
    raise exception 'launchd observation session user is not an active provisioned device principal';
  end if;
  if btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'launchd observation idempotency key is required';
  end if;
  if btrim(coalesce(p_surface_id,''))='' or btrim(coalesce(p_label,''))=''
     or btrim(coalesce(p_timezone,''))='' or p_enabled is null then
    raise exception 'launchd observation identity, timezone, and state are required';
  end if;
  if p_observed_at > now() + interval '5 minutes'
     or p_observed_at < now() - interval '15 minutes' then
    raise exception 'launchd observation is outside the freshness window';
  end if;
  if coalesce(p_plist_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_schedule_sha256,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_launchctl_revision,'') !~ '^[0-9a-f]{64}$'
     or coalesce(p_source_fingerprint,'') !~ '^[0-9a-f]{64}$' then
    raise exception 'launchd observation provenance is malformed';
  end if;

  select * into contract from ops.legacy_schedule_launchd_contract
   where surface_id=p_surface_id for share;
  if not found then raise exception 'launchd scheduler surface is not registered'; end if;
  if p_label <> contract.locator or p_timezone <> contract.timezone
     or p_plist_sha256 <> contract.plist_sha256
     or p_schedule_sha256 <> contract.schedule_sha256 then
    raise exception 'launchd observation does not match the registered native contract';
  end if;
  state := case when p_enabled then 'enabled' else 'disabled' end;

  select * into existing from ops.legacy_schedule_observation_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if existing.surface_id is distinct from p_surface_id
       or existing.locator is distinct from p_label
       or existing.scheduler_kind is distinct from 'launchd'
       or existing.scheduler_state is distinct from state
       or existing.cron_expression is distinct from p_schedule_sha256
       or existing.timezone is distinct from p_timezone
       or existing.definition_sha256 is distinct from p_plist_sha256
       or existing.provider_revision is distinct from p_launchctl_revision
       or existing.source_fingerprint is distinct from p_source_fingerprint
       or existing.observed_at is distinct from p_observed_at
       or existing.device_id is distinct from principal.device_id then
      raise exception 'launchd observation idempotency key was reused with different evidence';
    end if;
    return existing.receipt_ref;
  end if;

  ref := 'scheduler-observation:' || p_idempotency_key;
  insert into ops.legacy_schedule_observation_receipt
    (receipt_ref,idempotency_key,surface_id,workflow_key,workflow_version,locator,
     scheduler_kind,scheduler_state,cron_expression,timezone,definition_sha256,
     provider_revision,source_fingerprint,observed_at,device_id)
  values
    (ref,p_idempotency_key,contract.surface_id,contract.workflow_key,contract.workflow_version,
     contract.locator,'launchd',state,contract.schedule_sha256,contract.timezone,
     contract.plist_sha256,p_launchctl_revision,p_source_fingerprint,p_observed_at,
     principal.device_id);
  return ref;
end $_$;


--
-- Name: record_meeting_action_outcome(uuid, integer, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_meeting_action_outcome(p_meeting uuid, p_action_number integer, p_client_instance text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_row ops.meeting%rowtype; v_head ops.meeting_action%rowtype;
        v_decided ops.meeting_action_revision%rowtype; v_call public.tool_call%rowtype;
        v_state text; v_outcome jsonb;
begin
  select * into v_who from ops.meeting_mode_actor();
  select * into v_row from ops.meeting
   where id = p_meeting and organization_tenant_id = v_who.tenant for update;
  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_not_found');
  end if;
  select * into v_head from ops.meeting_action
   where meeting_id = p_meeting and action_number = p_action_number for update;
  if v_head.meeting_id is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_not_found',
      'action_number', p_action_number);
  end if;
  if v_head.state in ('executed', 'delegated') then
    return jsonb_build_object('ok', true, 'already', true, 'reconciled', true,
      'meeting_id', p_meeting, 'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  if v_head.state <> 'accepted' then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_action_not_accepted',
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  select * into v_decided from ops.meeting_action_revision
   where meeting_id = p_meeting and action_number = p_action_number
     and revision = v_head.decided_revision;
  select * into v_call from public.tool_call where idempotency_key = v_head.operation_key::text;
  if v_call.idempotency_key is null then
    return jsonb_build_object('ok', true, 'already', false, 'reconciled', false,
      'outcome_state', 'not_observed', 'meeting_id', p_meeting,
      'retry', jsonb_build_object('verb', v_decided.command->>'verb',
        'args', v_decided.command->'args', 'idempotency_key', v_head.operation_key,
        'rule', 'retry only with this exact idempotency_key; never mint a new one'),
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  if v_call.verb is distinct from v_decided.command->>'verb'
     or v_call.organization_tenant_id is distinct from v_row.organization_tenant_id then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_operation_key_bound_elsewhere',
      'observed_verb', v_call.verb,
      'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
  end if;
  v_state := case when v_head.disposition = 'delegate' then 'delegated' else 'executed' end;
  v_outcome := jsonb_build_object('verb', v_call.verb, 'idempotency_key', v_call.idempotency_key,
    'committed_at', v_call.created_at,
    'committed_by', (select slug from public.actor where id = v_call.actor_id),
    'response_digest', 'sha256:' || encode(public.digest(convert_to(v_call.response::text, 'UTF8'), 'sha256'), 'hex'),
    'evidence', 'public.tool_call');
  update ops.meeting_action set state = v_state, outcome = v_outcome
   where meeting_id = p_meeting and action_number = p_action_number;
  perform ops.meeting_mode_append(p_meeting,
    case when v_state = 'delegated' then 'action_delegated' else 'action_executed' end,
    v_who.actor_id, p_client_instance, null, p_action_number, v_head.decided_revision, null,
    p_idempotency_key);
  return jsonb_build_object('ok', true, 'already', false, 'reconciled', true,
    'outcome_state', v_state, 'meeting_id', p_meeting,
    'action', ops.meeting_mode_action_view(p_meeting, p_action_number));
end $$;


--
-- Name: nightly_availability_canary_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.nightly_availability_canary_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    source_snapshot_id uuid NOT NULL,
    source_snapshot_digest text CONSTRAINT nightly_availability_canary_rec_source_snapshot_digest_not_null NOT NULL,
    availability_count integer NOT NULL,
    open_search_count integer NOT NULL,
    match_count integer NOT NULL,
    output_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nightly_availability_canary_receipt_availability_count_check CHECK ((availability_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_match_count_check CHECK ((match_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_open_search_count_check CHECK ((open_search_count >= 0)),
    CONSTRAINT nightly_availability_canary_receipt_output_digest_check CHECK ((output_digest ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: record_nightly_availability_canary_receipt(uuid, uuid, uuid, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_nightly_availability_canary_receipt(p_job_id uuid, p_lease uuid, p_source_snapshot_id uuid, p_output_digest text, p_match_count integer) RETURNS ops.nightly_availability_canary_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare j ops.job%rowtype;s ops.nightly_availability_canary_source_snapshot%rowtype;r ops.nightly_availability_canary_receipt%rowtype;e ops.nightly_availability_canary_receipt%rowtype;
begin
 j:=ops.nightly_availability_canary_live_job(p_job_id,p_lease);
 select * into s from ops.nightly_availability_canary_source_snapshot where id=p_source_snapshot_id and job_id=j.id and attempt=j.attempt;
 if not found then raise exception using errcode='22023',message='nightly availability source snapshot is not bound to this job attempt'; end if;
 if p_output_digest!~'^[0-9a-f]{64}$' or p_match_count<0 then raise exception using errcode='22023',message='invalid nightly availability canary aggregate'; end if;
 insert into ops.nightly_availability_canary_receipt(job_id,attempt,source_snapshot_id,source_snapshot_digest,availability_count,open_search_count,match_count,output_digest)
 values(j.id,j.attempt,s.id,s.snapshot_digest,s.availability_count,s.open_search_count,p_match_count,p_output_digest)
 on conflict(job_id,attempt) do nothing returning * into r;
 if found then return r; end if;
 select * into e from ops.nightly_availability_canary_receipt where job_id=j.id and attempt=j.attempt;
 if e.source_snapshot_id<>s.id or e.output_digest<>p_output_digest or e.match_count<>p_match_count then raise exception using errcode='23505',message='nightly availability canary receipt replay conflicts with immutable attempt'; end if;
 return e;
end $_$;


--
-- Name: record_npi_device_evidence(uuid, timestamp with time zone, text, text, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_npi_device_evidence(p_job_id uuid, p_observed_at timestamp with time zone, p_source_release text, p_source_checksum text, p_results jsonb, p_idempotency_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare principal ops.device_evidence_principal%rowtype; j ops.job%rowtype;
        existing ops.npi_device_evidence_receipt%rowtype; result jsonb; item jsonb; rid uuid;
begin
  select * into principal from ops.device_evidence_principal where login_role=session_user and active;
  if not found then raise exception 'NPI evidence session user is not an active provisioned principal'; end if;
  select * into j from ops.job where id=p_job_id for share;
  if not found or j.definition_key<>'npi-sweep-weekly' or j.state not in ('queued','retry_wait','running') then
    raise exception 'NPI evidence must bind an open npi-sweep-weekly ledger job'; end if;
  if p_observed_at < j.scheduled_for-interval '24 hours' or p_observed_at > j.scheduled_for+interval '24 hours'
     or p_observed_at > now()+interval '5 minutes' then raise exception 'NPI evidence is outside its ledger freshness window'; end if;
  if btrim(coalesce(p_source_release,''))='' or coalesce(p_source_checksum,'') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_results)<>'array' or jsonb_array_length(p_results)=0 then
    raise exception 'NPI evidence requires release, SHA-256 checksum, and nonempty result array'; end if;
  for item in select value from jsonb_array_elements(p_results) loop
    if jsonb_typeof(item)<>'object' or (item - array['source_ref','npi','enumeration_type','last_updated','addresses','taxonomies'])<>'{}'::jsonb
       or btrim(coalesce(item->>'source_ref',''))='' or coalesce(item->>'npi','') !~ '^[0-9]{10}$'
       or btrim(coalesce(item->>'enumeration_type',''))='' or btrim(coalesce(item->>'last_updated',''))=''
       or jsonb_typeof(item->'addresses')<>'array' or jsonb_typeof(item->'taxonomies')<>'array'
       or jsonb_array_length(item->'taxonomies')=0
       or exists (select 1 from jsonb_array_elements(item->'taxonomies') code where jsonb_typeof(code)<>'string')
       or exists (select 1 from jsonb_array_elements(item->'addresses') address
                   where jsonb_typeof(address)<>'object' or jsonb_typeof(address->'postal_code')<>'string') then
      raise exception 'NPI result does not match the typed raw NPPES contract'; end if;
  end loop;
  select * into existing from ops.npi_device_evidence_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.job_id<>p_job_id or existing.device_id<>principal.device_id or existing.observed_at<>p_observed_at
       or existing.source_release<>p_source_release or existing.source_checksum<>p_source_checksum or existing.results<>p_results then
      raise exception 'NPI evidence idempotency key was reused with different evidence'; end if;
    return existing.id;
  end if;
  insert into ops.npi_device_evidence_receipt(job_id,builder_key,workflow_key,workflow_version,mode,scheduled_for,
      device_id,observed_at,source_release,source_checksum,results,idempotency_key)
    values(j.id,'npi.weekly-delta',j.definition_key,j.definition_version,j.mode,j.scheduled_for,
      principal.device_id,p_observed_at,p_source_release,p_source_checksum,p_results,p_idempotency_key)
    returning id into rid;
  return rid;
end $_$;


--
-- Name: record_program_controller_fact(text, uuid, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_program_controller_fact(p_fact_kind text, p_idempotency_key uuid, p_body jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_prior ops.program_controller_fact_ledger%rowtype;
  v_result jsonb;
  v_id uuid;
  v_target text;
  v_actor text;
  v_kind text;
  v_expected text[];
  v_digest text;
begin
  if p_fact_kind is null or p_fact_kind not in ('slice_source_lease','slice_lease_release','program_width_evidence','program_width_state','slice_checkpoint','release_receipt','origin_head_observation','admission_refusal') then
    raise exception 'program controller fact kind % is not a kind this writer records', p_fact_kind;
  end if;
  if p_idempotency_key is null or jsonb_typeof(p_body) <> 'object' then
    raise exception 'a program controller fact requires an idempotency key and a json object body';
  end if;

  if p_fact_kind = 'admission_refusal' then
    if not pg_has_role(session_user, 'carr_writer', 'member')
       and not pg_has_role(session_user, 'carr_authority', 'member') then
      raise exception using errcode='42501',
        message='recording an admission refusal requires the writer or authority capability';
    end if;
  else
    -- The membership test comes FIRST so a routine writer is refused with 42501
    -- rather than with ops.authority_actor_slug()'s own unadmitted-principal
    -- exception, which carries no privilege errcode.
    if not pg_has_role(session_user, 'carr_authority', 'member') then
      raise exception using errcode='42501',
        message='recording this program controller fact requires the authority capability';
    end if;
    if ops.authority_actor_slug() <> 'joe' then
      raise exception using errcode='42501',
        message='recording this program controller fact requires Joe authority';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text, 517));

  select * into v_prior from ops.program_controller_fact_ledger
    where idempotency_key = p_idempotency_key;
  if found then
    if v_prior.fact_kind <> p_fact_kind then
      raise exception 'program controller idempotency key was reused under fact kind % after %',
        p_fact_kind, v_prior.fact_kind;
    end if;
    return v_prior.result;
  end if;

  v_actor := session_user::text;

  if p_fact_kind = 'slice_source_lease' then
    insert into ops.slice_source_lease (
      slice_ref, worktree_ref, worktree_path, branch_ref, base_commit_sha, source_paths,
      database_disposition, database_resources, serialized_surfaces, repository_actions,
      reuse_disposition, model_roles, held_by_actor, correlation_id)
    values (
      p_body->>'slice_ref', p_body->>'worktree_ref', p_body->>'worktree_path',
      p_body->>'branch_ref', p_body->>'base_commit_sha', coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'source_paths','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'),
      p_body->>'database_disposition', coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'database_resources','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'),
      coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'serialized_surfaces','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'), coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'repository_actions','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'),
      p_body->>'reuse_disposition', coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'model_roles','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'),
      coalesce(p_body->>'held_by_actor', v_actor), p_body->>'correlation_id')
    returning id into v_id;
    v_target := 'ops.slice_source_lease';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  elsif p_fact_kind = 'slice_lease_release' then
    update ops.slice_source_lease set released_at = now()
      where slice_ref = p_body->>'slice_ref' and released_at is null
      returning id into v_id;
    if v_id is null then
      raise exception 'no live source lease for %', p_body->>'slice_ref';
    end if;
    v_target := 'ops.slice_source_lease';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  elsif p_fact_kind = 'program_width_evidence' then
    insert into ops.program_width_evidence (
      program_ref, evidence_class, state, bound_base_sha, evidence_ref, observed_at, accepted_at)
    values (
      p_body->>'program_ref', p_body->>'evidence_class', p_body->>'state',
      p_body->>'bound_base_sha', p_body->>'evidence_ref',
      (p_body->>'observed_at')::timestamptz, (p_body->>'accepted_at')::timestamptz)
    on conflict (program_ref, evidence_class, bound_base_sha) do update
      set state = excluded.state, evidence_ref = excluded.evidence_ref,
          observed_at = excluded.observed_at, accepted_at = excluded.accepted_at
    returning id into v_id;
    v_target := 'ops.program_width_evidence';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  elsif p_fact_kind = 'program_width_state' then
    insert into ops.program_width_state (program_ref, current_width, requested_width)
    values (p_body->>'program_ref', (p_body->>'current_width')::integer,
            (p_body->>'requested_width')::integer)
    on conflict (program_ref) do update
      set current_width = excluded.current_width,
          requested_width = excluded.requested_width, set_at = now()
    returning id into v_id;
    v_target := 'ops.program_width_state';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  elsif p_fact_kind = 'slice_checkpoint' then
    insert into ops.slice_checkpoint (
      slice_ref, checkpoint_ref, checkpoint_digest, base_commit_sha, worktree_ref, lease_id,
      next_step_ref, completed_step_refs, record_evidence_refs, reconstruction_source,
      inherited_transcript_used, recorded_at)
    values (
      p_body->>'slice_ref', p_body->>'checkpoint_ref', p_body->>'checkpoint_digest',
      p_body->>'base_commit_sha', p_body->>'worktree_ref', (p_body->>'lease_id')::uuid,
      p_body->>'next_step_ref', coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'completed_step_refs','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'),
      coalesce((select array_agg(value order by ordinality) from jsonb_array_elements_text(coalesce(p_body->'record_evidence_refs','[]'::jsonb)) with ordinality t(value, ordinality)), '{}'), p_body->>'reconstruction_source',
      coalesce((p_body->>'inherited_transcript_used')::boolean, false),
      (p_body->>'recorded_at')::timestamptz)
    returning id into v_id;
    v_target := 'ops.slice_checkpoint';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  elsif p_fact_kind = 'release_receipt' then
    -- A receipt is minted ONLY here. The reference must be the sha256 of the
    -- canonical body -- the controller's own digest check, mirrored -- and the
    -- body keys must be exactly the kind's declared shape.
    v_kind := p_body#>>'{body,kind}';
    if v_kind is null or v_kind is distinct from p_body->>'receipt_kind' then
      raise exception 'release receipt body kind % does not match receipt_kind %',
        v_kind, p_body->>'receipt_kind';
    end if;
    v_expected := case v_kind
      when 'head_observation' then array['head_sha','kind','observed_head_sha','slice_ref']
      when 'merge_slot' then array['head_sha','held_by_slice_ref','kind','slice_ref','state']
      when 'readback' then array['delivered_source_digest','expected_source_digest','head_sha','kind','main_sha','slice_ref','state']
      when 'required_checks' then array['checks','head_sha','kind','slice_ref']
      when 'revalidation' then array['current_main_sha','head_sha','kind','required','revalidated_against_sha','slice_ref']
      when 'review' then array['head_sha','kind','maker_actor_id','reviewed_head_sha','reviewer_actor_id','slice_ref','state']
    end;
    if v_expected is null then
      raise exception 'release receipt kind % has no declared body shape', v_kind;
    end if;
    if (select array_agg(key order by key) from jsonb_object_keys(p_body->'body') key)
       is distinct from (select array_agg(key order by key) from unnest(v_expected) key) then
      raise exception 'release receipt body for kind % is not exactly the declared shape', v_kind;
    end if;
    v_digest := 'receipt:sha256:' || encode(public.digest(
      convert_to(ops.scac_canonical_json(p_body->'body'), 'UTF8'), 'sha256'), 'hex');
    if p_body->>'receipt_ref' is distinct from v_digest then
      raise exception 'release receipt reference is not the digest of its own canonical body';
    end if;
    insert into ops.release_receipt (release_ref, slice_ref, head_sha, receipt_ref, receipt_kind, body)
    values (p_body->>'release_ref', p_body#>>'{body,slice_ref}', p_body#>>'{body,head_sha}',
            p_body->>'receipt_ref', v_kind, p_body->'body')
    returning id into v_id;
    v_target := 'ops.release_receipt';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id,
      'receipt_ref', p_body->>'receipt_ref');

  elsif p_fact_kind = 'origin_head_observation' then
    insert into ops.program_origin_head_observation (
      repository_root, origin_main_sha, observed_at, observed_by)
    values (p_body->>'repository_root', p_body->>'origin_main_sha',
            (p_body->>'observed_at')::timestamptz, coalesce(p_body->>'observed_by', v_actor))
    returning id into v_id;
    v_target := 'ops.program_origin_head_observation';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind, 'id', v_id);

  else
    -- admission_refusal: the decided outcome this Work Request requires to be
    -- persisted. It names no other store, so the writer cannot mint itself a
    -- lease, a width row or a receipt.
    if p_body->>'slice_ref' is null or p_body->>'reason_id' is null then
      raise exception 'an admission refusal records the slice it refused and the reason it refused it';
    end if;
    v_target := 'ops.program_controller_fact_ledger';
    v_result := jsonb_build_object('ok', true, 'fact_kind', p_fact_kind,
      'slice_ref', p_body->>'slice_ref', 'reason_id', p_body->>'reason_id',
      'blocking_check', p_body->>'blocking_check', 'decided_at', p_body->>'decided_at',
      'decision_digest', p_body->>'decision_digest');
  end if;

  insert into ops.program_controller_fact_ledger
    (idempotency_key, fact_kind, recorded_by, target_table, target_id, result)
  values (p_idempotency_key, p_fact_kind, v_actor, v_target, v_id, v_result);
  return v_result;
end $$;


--
-- Name: FUNCTION record_program_controller_fact(p_fact_kind text, p_idempotency_key uuid, p_body jsonb); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.record_program_controller_fact(p_fact_kind text, p_idempotency_key uuid, p_body jsonb) IS 'WR-000110: the single privileged writer for the V5-F02 program-controller seams. Gated on fact kind first; the routine writer bundle may record only an admission refusal.';


--
-- Name: record_provider_observation(text, text, integer, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_provider_observation(p_route_key text, p_status text, p_latency_ms integer, p_error_class text, p_ttl_seconds integer, p_source_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare rid uuid;
begin
  if p_ttl_seconds < 1 or btrim(coalesce(p_source_ref,''))='' then
    raise exception 'positive observation TTL and source_ref are required';
  end if;
  insert into ops.provider_observation
    (route_key,status,latency_ms,error_class,expires_at,source_ref)
  values(p_route_key,p_status,p_latency_ms,p_error_class,
         now()+make_interval(secs=>p_ttl_seconds),p_source_ref)
  returning id into rid;
  return rid;
end $$;


--
-- Name: record_ready_plan_amendment_admission_internal(uuid, text, integer, jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_ready_plan_amendment_admission_internal(p_plan_id uuid, p_work_request text, p_base_version integer, p_classifier_reasons jsonb, p_contract jsonb, p_proposed_by_actor_id uuid, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, plan_ref text, admission_ref text, admission_hash text, tier text, classifier_reasons jsonb, builder_session_ref text, replayed boolean)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_work ops.work_request%rowtype; v_plan ops.sourced_work_request_plan%rowtype;
        v_amend ops.ready_plan_amendment%rowtype; v_admission ops.heavy_build_admission_revision%rowtype;
        v_actor public.actor%rowtype; v_classification jsonb; v_expected jsonb;
        v_research jsonb; v_master jsonb; v_field text; v_minimum integer;
        v_version integer; v_preimage jsonb; v_digest text;
begin
  if p_plan_id is null or coalesce(p_work_request,'')!~'^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version<1 or p_proposed_by_actor_id is null
     or p_idempotency_key is null or jsonb_typeof(p_classifier_reasons) is distinct from 'array'
     or jsonb_array_length(p_classifier_reasons)=0
     or not ops.heavy_build_jsonb_has_exact_keys(p_contract,
          array['builder_session_ref','master_plan','research_manifest'])
     or coalesce(p_contract->>'builder_session_ref','')!~'^session:[a-z0-9][a-z0-9:._/-]{8,199}$'
     or jsonb_typeof(p_contract->'master_plan') is distinct from 'object'
     or jsonb_typeof(p_contract->'research_manifest') is distinct from 'object'
     or p_contract->'master_plan'='{}'::jsonb or p_contract->'research_manifest'='{}'::jsonb then
    raise exception 'ready-plan amendment admission requires exact plan, version, classifier, closed heavy contract, actor, and idempotency key';
  end if;
  v_research:=p_contract->'research_manifest';
  v_master:=p_contract->'master_plan';
  if not ops.heavy_build_jsonb_has_exact_keys(v_research,
       array['conclusion','current_baseline','failure_modes','maintained_repositories',
             'practitioner_evidence','primary_sources','unresolved_contradictions'])
     or char_length(btrim(coalesce(v_research->>'conclusion',''))) not between 20 and 1000
     or jsonb_typeof(v_research->'unresolved_contradictions') is distinct from 'array'
     or jsonb_array_length(v_research->'unresolved_contradictions')>12
     or exists(select 1 from jsonb_array_elements(v_research->'unresolved_contradictions') item
       where jsonb_typeof(item)<>'string'
          or char_length(btrim(item#>>'{}')) not between 10 and 500) then
    raise exception 'ready-plan amendment research manifest is incomplete';
  end if;
  foreach v_field in array array['primary_sources','maintained_repositories',
      'practitioner_evidence','current_baseline','failure_modes'] loop
    v_minimum:=case when v_field='maintained_repositories' then 2 else 1 end;
    if jsonb_typeof(v_research->v_field) is distinct from 'array'
       or jsonb_array_length(v_research->v_field) not between v_minimum and 12 then
      raise exception 'ready-plan amendment research class % is incomplete',v_field;
    end if;
  end loop;
  if exists(
    select 1 from (values
      ('primary_sources','primary_source'),
      ('maintained_repositories','maintained_repository'),
      ('practitioner_evidence','practitioner_evidence'),
      ('current_baseline','current_baseline'),('failure_modes','failure_mode')
    ) expected(field_name,class_name)
    cross join lateral jsonb_array_elements(v_research->expected.field_name) item
    where not ops.heavy_build_jsonb_has_exact_keys(item,
            array['content_digest','finding','locator','observed_at','source_class','source_ref'])
       or coalesce(item->>'source_ref','')!~'^safe:[a-z0-9][a-z0-9:_./-]*$'
       or item->>'source_class' is distinct from expected.class_name
       or coalesce(item->>'locator','')!~'^https://'
       or coalesce(item->>'observed_at','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
       or case when coalesce(item->>'observed_at','')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
            then (item->>'observed_at')::timestamptz>now()+interval '5 minutes' else true end
       or coalesce(item->>'content_digest','')!~'^sha256:[0-9a-f]{64}$'
       or char_length(btrim(coalesce(item->>'finding',''))) not between 20 and 1000
  ) then raise exception 'ready-plan amendment research evidence is invalid'; end if;
  if exists(select source_ref from (
      select item->>'source_ref' source_ref
        from (values ('primary_sources'),('maintained_repositories'),
          ('practitioner_evidence'),('current_baseline'),('failure_modes')) fields(field_name)
        cross join lateral jsonb_array_elements(v_research->fields.field_name) item
    ) refs group by source_ref having count(*)>1) then
    raise exception 'ready-plan amendment research source refs must be unique';
  end if;
  if not ops.heavy_build_jsonb_has_exact_keys(v_master,
       array['architecture','authority_boundaries','baseline_comparison','dependency_dag',
             'fully_shipped_definition','non_goals','observability_strategy','planned_checks',
             'prerequisite_policy','product_goal','release_strategy','rollback_strategy']) then
    raise exception 'ready-plan amendment master plan is incomplete';
  end if;
  foreach v_field in array array['product_goal','baseline_comparison','release_strategy',
      'rollback_strategy','observability_strategy','fully_shipped_definition','prerequisite_policy'] loop
    if char_length(btrim(coalesce(v_master->>v_field,''))) not between 20 and 2000 then
      raise exception 'ready-plan amendment master plan field % is incomplete',v_field;
    end if;
  end loop;
  foreach v_field in array array['non_goals','architecture','authority_boundaries'] loop
    v_minimum:=case when v_field='architecture' then 2 else 1 end;
    if jsonb_typeof(v_master->v_field) is distinct from 'array'
       or jsonb_array_length(v_master->v_field) not between v_minimum
          and (case when v_field='architecture' then 20 else 12 end)
       or exists(select 1 from jsonb_array_elements(v_master->v_field) item
         where jsonb_typeof(item)<>'string'
           or char_length(btrim(item#>>'{}')) not between 10 and 1000) then
      raise exception 'ready-plan amendment master plan field % is incomplete',v_field;
    end if;
  end loop;
  if jsonb_typeof(v_master->'dependency_dag') is distinct from 'array'
     or jsonb_array_length(v_master->'dependency_dag') not between 1 and 20
     or exists(select 1 from jsonb_array_elements(v_master->'dependency_dag') step
       where not ops.heavy_build_jsonb_has_exact_keys(step,array['depends_on','step_ref'])
         or coalesce(step->>'step_ref','')!~'^step:[a-z0-9][a-z0-9:._/-]*$'
         or jsonb_typeof(step->'depends_on')<>'array'
         or exists(select 1 from jsonb_array_elements(step->'depends_on') dep
           where jsonb_typeof(dep)<>'string'
              or dep#>>'{}'!~'^step:[a-z0-9][a-z0-9:._/-]*$'
              or dep#>>'{}'=step->>'step_ref'))
     or exists(select step->>'step_ref' from jsonb_array_elements(v_master->'dependency_dag') step
       group by step->>'step_ref' having count(*)>1)
     or exists(select 1 from jsonb_array_elements(v_master->'dependency_dag') step
       cross join lateral jsonb_array_elements_text(step->'depends_on') dep
       where not exists(select 1 from jsonb_array_elements(v_master->'dependency_dag') declared
         where declared->>'step_ref'=dep)) then
    raise exception 'ready-plan amendment dependency DAG is invalid';
  end if;
  if exists(with recursive edges(src,dst) as (
      select step->>'step_ref',dep from jsonb_array_elements(v_master->'dependency_dag') step
      cross join lateral jsonb_array_elements_text(step->'depends_on') dep
    ), walk(start_node,node,path,cycle) as (
      select src,dst,array[src,dst],dst=src from edges
      union all
      select walk.start_node,edges.dst,walk.path||edges.dst,edges.dst=any(walk.path)
        from walk join edges on edges.src=walk.node where not walk.cycle
    ) select 1 from walk where cycle limit 1) then
    raise exception 'ready-plan amendment dependency DAG contains a cycle';
  end if;
  if jsonb_typeof(v_master->'planned_checks') is distinct from 'array'
     or jsonb_array_length(v_master->'planned_checks') not between 1 and 20
     or exists(select 1 from jsonb_array_elements(v_master->'planned_checks') item
       where not ops.heavy_build_jsonb_has_exact_keys(item,
              array['artifact','comparator','failure_condition'])
         or char_length(btrim(coalesce(item->>'artifact',''))) not between 5 and 500
         or char_length(btrim(coalesce(item->>'comparator',''))) not between 5 and 500
         or char_length(btrim(coalesce(item->>'failure_condition',''))) not between 5 and 500) then
    raise exception 'ready-plan amendment planned checks are invalid';
  end if;
  select * into v_actor from public.actor where id=p_proposed_by_actor_id and active for share;
  if not found then raise exception 'ready-plan amendment admission actor is not active'; end if;
  perform pg_advisory_xact_lock(hashtextextended('heavy-build-admission:'||p_idempotency_key,0));
  select * into v_admission from ops.heavy_build_admission_revision
   where idempotency_key=p_idempotency_key for share;
  if found then
    select * into v_work from ops.work_request where id=v_admission.work_request_id;
    select * into v_plan from ops.sourced_work_request_plan where id=v_admission.plan_id;
    if v_work.ref is distinct from p_work_request or v_plan.id is distinct from p_plan_id
       or v_plan.work_request_version is distinct from p_base_version
       or v_admission.classifier_reasons is distinct from p_classifier_reasons
       or v_admission.contract is distinct from p_contract
       or v_admission.proposed_by_actor_id is distinct from p_proposed_by_actor_id then
      raise exception 'idempotency key already names a different ready-plan amendment admission';
    end if;
    return query select v_work.id,v_work.ref,v_plan.id,v_plan.plan_ref,
      v_admission.admission_ref,v_admission.admission_hash,v_admission.tier,
      v_admission.classifier_reasons,v_admission.builder_session_ref,true;
    return;
  end if;
  select * into v_work from ops.work_request where ref=p_work_request for share;
  if not found or v_work.state<>'ready' or v_work.version<>p_base_version then
    raise exception 'exact current ready Work Request required for amendment admission';
  end if;
  select * into v_plan from ops.sourced_work_request_plan
   where id=p_plan_id and work_request_id=v_work.id for share;
  select * into v_amend from ops.ready_plan_amendment
   where plan_id=p_plan_id and work_request_id=v_work.id and base_version=v_work.version for share;
  if v_plan.id is null or v_amend.plan_id is null
     or v_plan.work_request_version<>v_work.version then
    raise exception 'exact current ready-plan amendment required for admission';
  end if;
  v_classification:=ops.heavy_build_classification(v_work.id,v_plan.scope_summary,
    v_plan.dependency_refs,v_plan.caps);
  if coalesce((v_classification->>'shape_ready')::boolean,false) is not true then
    raise exception 'ready-plan amendment requires the current evidence-backed Work Shape';
  end if;
  v_expected:=case when v_classification->>'tier'='heavy' then v_classification->'reasons'
    else jsonb_build_array('caller:explicit-heavy-contract') end;
  if p_classifier_reasons is distinct from v_expected then
    raise exception 'ready-plan amendment classifier reasons must be server-derived';
  end if;
  select coalesce(max(version),0)+1 into v_version
    from ops.heavy_build_admission_revision where plan_id=v_plan.id;
  v_preimage:=jsonb_build_object('contract','carr-heavy-build-admission/v1',
    'work_request_id',v_work.id,'work_request_version',v_work.version,
    'plan_id',v_plan.id,'plan_hash',v_plan.plan_hash,'classifier_reasons',v_expected,
    'heavy_build',p_contract,'proposed_by_actor_id',p_proposed_by_actor_id,'version',v_version);
  v_digest:=ops.heavy_build_digest(v_preimage);
  insert into ops.heavy_build_admission_revision(admission_ref,work_request_id,plan_id,
    version,idempotency_key,tier,classifier_reasons,contract,builder_session_ref,
    admission_hash,proposed_by_actor_id)
  values('HBA-'||substr(v_digest,8,12)||'-v'||v_version,v_work.id,v_plan.id,
    v_version,p_idempotency_key,'heavy',v_expected,p_contract,
    p_contract->>'builder_session_ref',v_digest,p_proposed_by_actor_id)
  returning * into v_admission;
  return query select v_work.id,v_work.ref,v_plan.id,v_plan.plan_ref,
    v_admission.admission_ref,v_admission.admission_hash,v_admission.tier,
    v_admission.classifier_reasons,v_admission.builder_session_ref,false;
end $_$;


--
-- Name: record_sourced_heavy_build_admission(uuid, text, integer, jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_sourced_heavy_build_admission(p_plan_id uuid, p_work_request text, p_base_version integer, p_classifier_reasons jsonb, p_contract jsonb, p_proposed_by_actor_id uuid, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, plan_ref text, admission_ref text, admission_hash text, tier text, classifier_reasons jsonb, builder_session_ref text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if exists(select 1 from ops.ready_plan_amendment a
    where a.plan_id=p_plan_id and a.base_version=p_base_version) then
    return query select * from ops.record_ready_plan_amendment_admission_internal(
      p_plan_id,p_work_request,p_base_version,p_classifier_reasons,p_contract,
      p_proposed_by_actor_id,p_idempotency_key);
  else
    return query select * from ops.record_sourced_heavy_build_admission_v1(
      p_plan_id,p_work_request,p_base_version,p_classifier_reasons,p_contract,
      p_proposed_by_actor_id,p_idempotency_key);
  end if;
end $$;


--
-- Name: record_sourced_heavy_build_admission_v1(uuid, text, integer, jsonb, jsonb, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_sourced_heavy_build_admission_v1(p_plan_id uuid, p_work_request text, p_base_version integer, p_classifier_reasons jsonb, p_contract jsonb, p_proposed_by_actor_id uuid, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, plan_ref text, admission_ref text, admission_hash text, tier text, classifier_reasons jsonb, builder_session_ref text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype;
  p ops.sourced_work_request_plan%rowtype;
  a ops.heavy_build_admission_revision%rowtype;
  actor public.actor%rowtype;
  classification jsonb;
  expected_reasons jsonb;
  research jsonb;
  master_plan jsonb;
  field text;
  minimum integer;
  next_version integer;
  preimage jsonb;
  digest text;
begin
  if p_plan_id is null or coalesce(p_work_request,'') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1 or p_idempotency_key is null
     or p_proposed_by_actor_id is null or jsonb_typeof(p_classifier_reasons) is distinct from 'array'
     or jsonb_array_length(p_classifier_reasons) = 0
     or not ops.heavy_build_jsonb_has_exact_keys(p_contract, array['builder_session_ref','master_plan','research_manifest'])
     or coalesce(p_contract->>'builder_session_ref','') !~ '^session:[a-z0-9][a-z0-9:._/-]{8,199}$' then
    raise exception 'heavy build admission requires exact plan, Work Request version, classifier reasons, typed contract, actor, and idempotency key';
  end if;

  research := p_contract->'research_manifest';
  master_plan := p_contract->'master_plan';
  if not ops.heavy_build_jsonb_has_exact_keys(research,
       array['conclusion','current_baseline','failure_modes','maintained_repositories','practitioner_evidence','primary_sources','unresolved_contradictions'])
     or char_length(btrim(coalesce(research->>'conclusion',''))) not between 20 and 1000
     or jsonb_typeof(research->'unresolved_contradictions') is distinct from 'array'
     or jsonb_array_length(research->'unresolved_contradictions') > 12
     or exists (select 1 from jsonb_array_elements(research->'unresolved_contradictions') item
                 where jsonb_typeof(item) <> 'string' or char_length(btrim(item #>> '{}')) not between 10 and 500) then
    raise exception 'heavy build research manifest is incomplete';
  end if;

  foreach field in array array['primary_sources','maintained_repositories','practitioner_evidence','current_baseline','failure_modes'] loop
    minimum := case when field = 'maintained_repositories' then 2 else 1 end;
    if jsonb_typeof(research->field) is distinct from 'array'
       or jsonb_array_length(research->field) not between minimum and 12 then
      raise exception 'heavy build research class % requires % to 12 evidence items', field, minimum;
    end if;
  end loop;

  if exists (
    select 1
      from (values
        ('primary_sources','primary_source'),
        ('maintained_repositories','maintained_repository'),
        ('practitioner_evidence','practitioner_evidence'),
        ('current_baseline','current_baseline'),
        ('failure_modes','failure_mode')
      ) expected(field_name, class_name)
      cross join lateral jsonb_array_elements(research->expected.field_name) item
     where not ops.heavy_build_jsonb_has_exact_keys(item, array['content_digest','finding','locator','observed_at','source_class','source_ref'])
        or coalesce(item->>'source_ref','') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
        or item->>'source_class' is distinct from expected.class_name
        or coalesce(item->>'locator','') !~ '^https://'
        or coalesce(item->>'observed_at','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
        or case when coalesce(item->>'observed_at','') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'
             then (item->>'observed_at')::timestamptz > now() + interval '5 minutes' else true end
        or coalesce(item->>'content_digest','') !~ '^sha256:[0-9a-f]{64}$'
        or char_length(btrim(coalesce(item->>'finding',''))) not between 20 and 1000
  ) then raise exception 'heavy build research evidence item is invalid or in the wrong source class'; end if;

  if exists (
    select source_ref from (
      select item->>'source_ref' source_ref
        from (values ('primary_sources'),('maintained_repositories'),('practitioner_evidence'),('current_baseline'),('failure_modes')) fields(field_name)
        cross join lateral jsonb_array_elements(research->fields.field_name) item
    ) refs group by source_ref having count(*) > 1
  ) then raise exception 'heavy build research source refs must be unique across classes'; end if;

  if not ops.heavy_build_jsonb_has_exact_keys(master_plan,
       array['architecture','authority_boundaries','baseline_comparison','dependency_dag','fully_shipped_definition','non_goals','observability_strategy','planned_checks','prerequisite_policy','product_goal','release_strategy','rollback_strategy']) then
    raise exception 'heavy build master plan must name the complete target-product contract';
  end if;
  foreach field in array array['product_goal','baseline_comparison','release_strategy','rollback_strategy','observability_strategy','fully_shipped_definition','prerequisite_policy'] loop
    if char_length(btrim(coalesce(master_plan->>field,''))) not between 20 and 2000 then
      raise exception 'heavy build master plan field % is incomplete', field;
    end if;
  end loop;
  foreach field in array array['non_goals','architecture','authority_boundaries'] loop
    minimum := case when field = 'architecture' then 2 else 1 end;
    if jsonb_typeof(master_plan->field) is distinct from 'array'
       or jsonb_array_length(master_plan->field) not between minimum and (case when field='architecture' then 20 else 12 end)
       or exists (select 1 from jsonb_array_elements(master_plan->field) item
                   where jsonb_typeof(item) <> 'string' or char_length(btrim(item #>> '{}')) not between 10 and 1000) then
      raise exception 'heavy build master plan field % requires substantive entries', field;
    end if;
  end loop;
  if jsonb_typeof(master_plan->'dependency_dag') is distinct from 'array'
     or jsonb_array_length(master_plan->'dependency_dag') not between 1 and 20
     or exists (select 1 from jsonb_array_elements(master_plan->'dependency_dag') step
                 where not ops.heavy_build_jsonb_has_exact_keys(step,array['depends_on','step_ref'])
                    or coalesce(step->>'step_ref','') !~ '^step:[a-z0-9][a-z0-9:._/-]*$'
                    or jsonb_typeof(step->'depends_on') <> 'array'
                    or exists (select 1 from jsonb_array_elements(step->'depends_on') dep
                                where jsonb_typeof(dep) <> 'string' or dep #>> '{}' !~ '^step:[a-z0-9][a-z0-9:._/-]*$' or dep #>> '{}' = step->>'step_ref'))
     or exists (select step->>'step_ref' from jsonb_array_elements(master_plan->'dependency_dag') step group by step->>'step_ref' having count(*) > 1)
     or exists (select 1 from jsonb_array_elements(master_plan->'dependency_dag') step
                 cross join lateral jsonb_array_elements_text(step->'depends_on') dep
                where not exists (select 1 from jsonb_array_elements(master_plan->'dependency_dag') declared where declared->>'step_ref'=dep)) then
    raise exception 'heavy build dependency DAG is invalid';
  end if;
  if exists (
    with recursive edges(src,dst) as (
      select step->>'step_ref', dep
        from jsonb_array_elements(master_plan->'dependency_dag') step
        cross join lateral jsonb_array_elements_text(step->'depends_on') dep
    ), walk(start_node,node,path,cycle) as (
      select src,dst,array[src,dst],dst=src from edges
      union all
      select walk.start_node,edges.dst,walk.path||edges.dst,edges.dst=any(walk.path)
        from walk join edges on edges.src=walk.node where not walk.cycle
    ) select 1 from walk where cycle limit 1
  ) then raise exception 'heavy build dependency graph contains a cycle'; end if;
  if jsonb_typeof(master_plan->'planned_checks') is distinct from 'array'
     or jsonb_array_length(master_plan->'planned_checks') not between 1 and 20
     or exists (select 1 from jsonb_array_elements(master_plan->'planned_checks') check_item
                 where not ops.heavy_build_jsonb_has_exact_keys(check_item,array['artifact','comparator','failure_condition'])
                    or char_length(btrim(coalesce(check_item->>'artifact',''))) not between 5 and 500
                    or char_length(btrim(coalesce(check_item->>'comparator',''))) not between 5 and 500
                    or char_length(btrim(coalesce(check_item->>'failure_condition',''))) not between 5 and 500) then
    raise exception 'heavy build planned checks must name artifact, comparator, and failure condition';
  end if;

  select x.* into actor from public.actor x where x.id=p_proposed_by_actor_id and x.active for share;
  if not found then raise exception 'heavy build admission actor is not active'; end if;
  perform pg_advisory_xact_lock(hashtextextended('heavy-build-admission:' || p_idempotency_key,0));
  select x.* into a from ops.heavy_build_admission_revision x where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into w from ops.work_request x where x.id=a.work_request_id;
    select x.* into p from ops.sourced_work_request_plan x where x.id=a.plan_id;
    if not found or w.ref is distinct from p_work_request or p.id is distinct from p_plan_id
       or p.work_request_version is distinct from p_base_version or a.classifier_reasons is distinct from p_classifier_reasons
       or a.contract is distinct from p_contract or a.proposed_by_actor_id is distinct from p_proposed_by_actor_id then
      raise exception 'idempotency key already names a different heavy build admission';
    end if;
    return query select w.id,w.ref,p.id,p.plan_ref,a.admission_ref,a.admission_hash,a.tier,a.classifier_reasons,a.builder_session_ref,true;
    return;
  end if;

  select w0.* into w from ops.work_request w0 where w0.ref=p_work_request for update;
  if not found or w.state is distinct from 'triaged' or w.version is distinct from p_base_version then
    raise exception 'exact current triaged Work Request and immutable plan required for heavy build admission';
  end if;
  select p0.* into p from ops.sourced_work_request_plan p0 where p0.id=p_plan_id and p0.work_request_id=w.id for share;
  if not found or p.work_request_version is distinct from w.version then
    raise exception 'exact current triaged Work Request and immutable plan required for heavy build admission';
  end if;
  classification := ops.heavy_build_classification(w.id,p.scope_summary,p.dependency_refs,p.caps);
  if coalesce((classification->>'shape_ready')::boolean,false) is not true then
    raise exception 'heavy build requires a current evidence-backed Work Shape before plan proposal';
  end if;
  expected_reasons := case when classification->>'tier'='heavy' then classification->'reasons' else jsonb_build_array('caller:explicit-heavy-contract') end;
  if p_classifier_reasons is distinct from expected_reasons then raise exception 'heavy build classifier reasons must be server-derived'; end if;

  select coalesce(max(x.version),0)+1 into next_version from ops.heavy_build_admission_revision x where x.plan_id=p.id;
  preimage := jsonb_build_object('contract','carr-heavy-build-admission/v1','work_request_id',w.id,'work_request_version',w.version,
    'plan_id',p.id,'plan_hash',p.plan_hash,'classifier_reasons',expected_reasons,'heavy_build',p_contract,
    'proposed_by_actor_id',p_proposed_by_actor_id,'version',next_version);
  digest := ops.heavy_build_digest(preimage);
  if exists (select 1 from ops.heavy_build_admission_revision x where x.plan_id=p.id and x.admission_hash=digest) then
    raise exception 'the exact heavy build admission already exists under a different idempotency key';
  end if;
  insert into ops.heavy_build_admission_revision
    (admission_ref,work_request_id,plan_id,version,idempotency_key,tier,classifier_reasons,contract,builder_session_ref,admission_hash,proposed_by_actor_id)
  values ('HBA-'||substr(digest,8,12)||'-v'||next_version,w.id,p.id,next_version,p_idempotency_key,'heavy',expected_reasons,p_contract,p_contract->>'builder_session_ref',digest,p_proposed_by_actor_id)
  returning * into a;
  return query select w.id,w.ref,p.id,p.plan_ref,a.admission_ref,a.admission_hash,a.tier,a.classifier_reasons,a.builder_session_ref,false;
end;
$_$;


--
-- Name: record_staging_forward_fix_rehearsal(uuid, uuid, text, integer, text, integer, text, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_forward_fix_rehearsal(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_schema_ledger_sha256 text, p_doctrine_generation bigint, p_program6_actions_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare attempt ops.staging_forward_fix_rehearsal_attempt%rowtype; existing ops.staging_forward_fix_rehearsal_result%rowtype;
  result_uuid uuid; bundle_uuid uuid; run_uuid uuid; observed_time timestamptz:=clock_timestamp();
  projection jsonb; projection_hash text; result_ref text; bundle_projection jsonb; bundle_hash text; bundle_ref text;
begin
  if session_user<>'carr_program5_forward_fix_verifier'
     or not pg_has_role(session_user,'carr_program5_forward_fix_verifiers','member') then
    raise exception using errcode='42501',message='forward-fix rehearsal result requires the exact scoped verifier capability';
  end if;
  if p_idempotency_key is null or p_provider_version_id is null or coalesce(p_provider_tag,'') !~ '^carr-staging-forward-fix-[0-9a-f]{32}$'
     or coalesce(p_verb_count,0)<=0 or coalesce(p_schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(p_schema_applied_count,0)<=0 or coalesce(p_schema_ledger_sha256,'') !~ '^sha256:[0-9a-f]{64}$'
     or coalesce(p_doctrine_generation,-1)<0 or p_program6_actions_enabled is null then
    raise exception 'invalid typed forward-fix staging readback input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,315));
  select * into attempt from ops.staging_forward_fix_rehearsal_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'forward-fix rehearsal result has no prepared attempt'; end if;
  if not exists(select 1 from ops.staging_forward_fix_rehearsal_claim where rehearsal_attempt_id=attempt.id) then
    raise exception 'forward-fix rehearsal result was never claimed';
  end if;
  select * into existing from ops.staging_forward_fix_rehearsal_result where rehearsal_attempt_id=attempt.id;
  if found then
    if (existing.provider_version_id,existing.provider_tag,existing.verb_count,existing.schema_highest_migration,
        existing.schema_applied_count,existing.schema_ledger_sha256,existing.doctrine_generation,existing.program6_actions_enabled) is distinct from
       (p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,p_schema_applied_count,
        p_schema_ledger_sha256,p_doctrine_generation,p_program6_actions_enabled) then
      raise exception 'forward-fix rehearsal result idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('forward_fix_rehearsal_result_id',existing.id,'result_ref',existing.evidence_ref,
      'bundle_id',(select id from ops.staging_recovery_rehearsal_bundle where forward_fix_result_id=existing.id),
      'recovery_run_id',(select id from ops.run where recovery_rehearsal_bundle_id=(select id from ops.staging_recovery_rehearsal_bundle where forward_fix_result_id=existing.id)),
      'replayed',true);
  end if;
  if p_provider_version_id=attempt.candidate_provider_version_id or p_provider_tag<>attempt.expected_provider_tag
     or p_schema_highest_migration<>attempt.declared_schema_highest_migration
     or p_schema_applied_count<>attempt.declared_schema_applied_count
     or p_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256 then
    raise exception 'forward-fix rehearsal readback does not match the exact staging candidate boundary';
  end if;
  projection:=jsonb_build_object('forward_fix_rehearsal_attempt_id',attempt.id,'release_id',attempt.release_id,
    'service_id',attempt.service_id,'environment','staging','git_sha',attempt.git_sha,
    'candidate_provider_version_id',attempt.candidate_provider_version_id,'provider_version_id',p_provider_version_id,
    'provider_tag',p_provider_tag,'verb_count',p_verb_count,'schema_highest_migration',p_schema_highest_migration,
    'schema_applied_count',p_schema_applied_count,'schema_ledger_sha256',p_schema_ledger_sha256,
    'doctrine_generation',p_doctrine_generation,'program6_actions_enabled',p_program6_actions_enabled);
  projection_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  result_ref:='ops.staging-forward-fix-readback:'||projection_hash;
  insert into ops.staging_forward_fix_rehearsal_result(
    idempotency_key,rehearsal_attempt_id,provider_version_id,provider_tag,verb_count,schema_highest_migration,
    schema_applied_count,schema_ledger_sha256,doctrine_generation,program6_actions_enabled,
    projection_sha256,evidence_ref,observed_at,writer_session_user)
  values(p_idempotency_key,attempt.id,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
    p_schema_applied_count,p_schema_ledger_sha256,p_doctrine_generation,p_program6_actions_enabled,
    projection_hash,result_ref,observed_time,session_user) returning id into result_uuid;
  bundle_projection:=jsonb_build_object('forward_fix_rehearsal_attempt_id',attempt.id,'forward_fix_result_id',result_uuid,
    'current_release_id',attempt.release_id,'service_id',attempt.service_id,'environment','staging','git_sha',attempt.git_sha,
    'candidate_provider_version_id',attempt.candidate_provider_version_id,'recovery_strategy','forward_fix',
    'recovery_plan_ref',attempt.recovery_plan_ref,'plan_hash',attempt.plan_hash,
    'declared_migration_set_sha256',attempt.declared_migration_set_sha256,
    'declared_migration_count',attempt.declared_migration_count,
    'declared_schema_highest_migration',attempt.declared_schema_highest_migration,
    'declared_schema_applied_count',attempt.declared_schema_applied_count,
    'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256);
  bundle_hash:='sha256:'||encode(public.digest(bundle_projection::text,'sha256'),'hex');
  bundle_ref:='ops.staging-recovery-bundle:'||bundle_hash;
  insert into ops.staging_recovery_rehearsal_bundle(
    recovery_attempt_id,correlation_id,current_release_id,prior_release_id,service_id,environment,
    current_before_receipt_id,prior_after_rollback_receipt_id,current_after_restore_receipt_id,
    forward_fix_result_id,candidate_git_sha,candidate_provider_version_id,recovery_strategy,recovery_plan_ref,
    plan_hash,declared_migration_set_sha256,declared_migration_count,declared_schema_highest_migration,
    declared_schema_applied_count,declared_schema_ledger_sha256,bundle_sha256,evidence_ref,completed_at,writer_session_user)
  values(attempt.id,attempt.correlation_id,attempt.release_id,null,attempt.service_id,'staging',null,null,null,
    result_uuid,attempt.git_sha,attempt.candidate_provider_version_id,'forward_fix',attempt.recovery_plan_ref,
    attempt.plan_hash,attempt.declared_migration_set_sha256,attempt.declared_migration_count,
    attempt.declared_schema_highest_migration,attempt.declared_schema_applied_count,
    attempt.declared_schema_ledger_sha256,bundle_hash,bundle_ref,observed_time,session_user)
  returning id into bundle_uuid;
  insert into ops.run(correlation_id,kind,service_id,environment,run_key,state,started_at,ended_at,source_kind,
    source_ref,observed_at,evidence_ref,release_id,recovery_strategy,recovery_plan_ref,recovery_rehearsal_bundle_id)
  values(attempt.correlation_id,'check',attempt.service_id,'staging','recovery.rehearsal.forward-fix','succeeded',
    observed_time,observed_time,'wrapper','ops.record_staging_forward_fix_rehearsal',observed_time,bundle_ref,
    attempt.release_id,'forward_fix',attempt.recovery_plan_ref,bundle_uuid) returning id into run_uuid;
  return jsonb_build_object('forward_fix_rehearsal_result_id',result_uuid,'result_ref',result_ref,
    'bundle_id',bundle_uuid,'recovery_run_id',run_uuid,'replayed',false);
end $_$;


--
-- Name: record_staging_release_readback(uuid, uuid, text, integer, text, integer, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_release_readback_receipt%rowtype;
  attempt ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  deployment_uuid uuid; receipt_uuid uuid; projection jsonb; projection_hash text;
  receipt_ref text; observed_time timestamptz := clock_timestamp();
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_provider_version_id is null
     or coalesce(p_provider_tag,'') !~ '^carr-staging-[a-z0-9-]{8,50}$'
     or coalesce(p_verb_count,0)<=0
     or coalesce(p_schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(p_schema_applied_count,0)<=0 or coalesce(p_doctrine_generation,-1)<0 then
    raise exception 'invalid typed staging readback input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging readback has no prepared deployment attempt'; end if;
  if attempt.recovery_step <> 'prior' or attempt.recovery_attempt_id is null
     or attempt.prior_release_id is null or attempt.observed_release_id is distinct from attempt.prior_release_id then
    raise exception 'legacy staging readback is limited to the exact historical Production prior observation';
  end if;
  if not exists(select 1 from ops.legacy_prior_staging_readback_allowlist l
                where l.idempotency_key=p_idempotency_key and l.deployment_attempt_id=attempt.id) then
    raise exception 'legacy staging readback idempotency key was not captured at migration time';
  end if;
  if not exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=attempt.id) then
    raise exception 'staging readback deployment attempt was never claimed'; end if;
  perform pg_advisory_xact_lock(hashtextextended(attempt.recovery_attempt_id::text,202));
  select * into existing from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.deployment_attempt_id<>attempt.id
       or (existing.git_sha,existing.provider_version_id,existing.provider_tag,existing.verb_count,
           existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation,
           existing.program6_actions_enabled) is distinct from
          (attempt.git_sha,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
           p_schema_applied_count,p_doctrine_generation,null::boolean) then
      raise exception 'staging readback idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('receipt_id',existing.id,'receipt_ref',existing.evidence_ref,'replayed',true,
      'bundle_id',(select id from ops.staging_recovery_rehearsal_bundle where recovery_attempt_id=attempt.recovery_attempt_id),
      'recovery_run_id',(select r.id from ops.run r join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id where b.recovery_attempt_id=attempt.recovery_attempt_id));
  end if;
  select * into strict current_release from ops.release where id=attempt.rehearsal_release_id;
  select * into strict prior_release from ops.release where id=attempt.prior_release_id;
  if prior_release.environment <> 'production' or prior_release.state <> 'complete' then
    raise exception 'legacy staging readback requires a completed historical Production prior release'; end if;
  if not exists(select 1 from ops.staging_release_readback_receipt before_receipt
                where before_receipt.recovery_attempt_id=attempt.recovery_attempt_id
                  and before_receipt.recovery_step='current_before'
                  and before_receipt.rehearsal_release_id=current_release.id
                  and before_receipt.observed_release_id=current_release.id
                  and before_receipt.prior_release_id=prior_release.id) then
    raise exception 'legacy staging readback prior requires its exact current_before receipt'; end if;
  if attempt.declared_migration_set_sha256<>ops.program5_migration_set_sha256(current_release.migration_set)
     or attempt.declared_migration_count<>cardinality(current_release.migration_set)
     or attempt.declared_schema_highest_migration<>current_release.schema_highest_migration
     or attempt.declared_schema_applied_count<>current_release.schema_applied_count
     or attempt.declared_schema_ledger_sha256<>current_release.schema_ledger_sha256
     or p_schema_highest_migration<>attempt.declared_schema_highest_migration
     or p_schema_applied_count<>attempt.declared_schema_applied_count then
    raise exception 'staging readback schema does not match the exact declared candidate migration set'; end if;
  if p_provider_tag<>attempt.expected_provider_tag then raise exception 'staging readback provider tag does not match its prepared attempt'; end if;
  projection:=jsonb_build_object(
    'deployment_attempt_id',attempt.id,'correlation_id',attempt.correlation_id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'recovery_step',attempt.recovery_step,'rehearsal_release_id',current_release.id,'observed_release_id',prior_release.id,
    'prior_release_id',attempt.prior_release_id,'service_id',current_release.service_id,'environment','staging','git_sha',attempt.git_sha,
    'provider','cloudflare-workers','provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,
    'verb_count',p_verb_count,'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,
    'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256,
    'doctrine_generation',p_doctrine_generation);
  projection_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex'); receipt_ref:='ops.staging-release-readback:'||projection_hash;
  insert into ops.deployment(correlation_id,service_id,environment,state,git_sha,provider,provider_version_id,release_id,deployed_by_actor,verb_count,schema_highest_migration,doctrine_generation,started_at,ended_at,read_back_at,verification_evidence_ref,source_kind,source_ref,observed_at)
  values(attempt.correlation_id,current_release.service_id,'staging','complete',attempt.git_sha,'cloudflare-workers',p_provider_version_id::text,prior_release.id,session_user,p_verb_count,p_schema_highest_migration,p_doctrine_generation,observed_time,observed_time,observed_time,receipt_ref,'wrapper','bin/deploy-worker.sh',observed_time) returning id into deployment_uuid;
  insert into ops.staging_release_readback_receipt(idempotency_key,deployment_attempt_id,recovery_attempt_id,recovery_step,correlation_id,deployment_id,rehearsal_release_id,observed_release_id,prior_release_id,service_id,environment,git_sha,provider,provider_version_id,provider_tag,verb_count,schema_highest_migration,schema_applied_count,declared_migration_set_sha256,declared_migration_count,declared_schema_applied_count,declared_schema_ledger_sha256,doctrine_generation,program6_actions_enabled,projection_sha256,evidence_ref,observed_at,writer_session_user)
  values(p_idempotency_key,attempt.id,attempt.recovery_attempt_id,attempt.recovery_step,attempt.correlation_id,deployment_uuid,current_release.id,prior_release.id,attempt.prior_release_id,current_release.service_id,'staging',attempt.git_sha,'cloudflare-workers',p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,p_schema_applied_count,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,p_doctrine_generation,null,projection_hash,receipt_ref,observed_time,session_user) returning id into receipt_uuid;
  return jsonb_build_object('receipt_id',receipt_uuid,'receipt_ref',receipt_ref,'replayed',false,'bundle_id',null,'recovery_run_id',null);
end $_$;


--
-- Name: record_staging_release_readback(uuid, uuid, text, integer, text, integer, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare legacy_posture boolean;
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select program6_actions_enabled into legacy_posture
  from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found and legacy_posture is null then
    raise exception 'Program 6 recorder cannot replay a legacy NULL-posture receipt';
  end if;
  return ops.record_staging_release_readback_program6(p_idempotency_key,p_provider_version_id,p_provider_tag,
    p_verb_count,p_schema_highest_migration,p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled);
end $$;


--
-- Name: record_staging_release_readback_program6(uuid, uuid, text, integer, text, integer, bigint, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_release_readback_program6(p_idempotency_key uuid, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  existing ops.staging_release_readback_receipt%rowtype;
  attempt ops.staging_deployment_attempt%rowtype;
  current_release ops.release%rowtype;
  prior_release ops.release%rowtype;
  observed_release ops.release%rowtype;
  service_uuid uuid; deployment_uuid uuid; receipt_uuid uuid;
  before_receipt ops.staging_release_readback_receipt%rowtype;
  prior_receipt ops.staging_release_readback_receipt%rowtype;
  after_receipt ops.staging_release_readback_receipt%rowtype;
  bundle_uuid uuid; run_uuid uuid; projection jsonb; projection_hash text;
  receipt_ref text; bundle_projection jsonb; bundle_hash text; bundle_ref text;
  observed_time timestamptz := clock_timestamp();
begin
  if session_user <> 'carr_jobs' then raise exception 'staging readback writer requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_provider_version_id is null
     or coalesce(p_provider_tag,'') !~ '^carr-staging-[a-z0-9-]{8,50}$'
     or coalesce(p_verb_count,0)<=0
     or coalesce(p_schema_highest_migration,'') !~ '^[0-9]{4}[a-z]?_[a-z0-9_.-]+\.sql$'
     or coalesce(p_schema_applied_count,0)<=0 or coalesce(p_doctrine_generation,-1)<0
     or p_program6_actions_enabled is null then
    raise exception 'invalid typed staging readback input';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_deployment_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging readback has no prepared deployment attempt'; end if;
  if not exists(select 1 from ops.staging_deployment_claim where deployment_attempt_id=attempt.id) then
    raise exception 'staging readback deployment attempt was never claimed'; end if;
  if attempt.recovery_attempt_id is not null then perform pg_advisory_xact_lock(hashtextextended(attempt.recovery_attempt_id::text,202)); end if;
  select * into existing from ops.staging_release_readback_receipt where idempotency_key=p_idempotency_key;
  if found then
    if existing.deployment_attempt_id<>attempt.id
       or (existing.git_sha,existing.provider_version_id,existing.provider_tag,existing.verb_count,
           existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation) is distinct from
          (attempt.git_sha,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
           p_schema_applied_count,p_doctrine_generation)
       or (existing.program6_actions_enabled is not null
           and existing.program6_actions_enabled is distinct from p_program6_actions_enabled) then
      raise exception 'staging readback idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('receipt_id',existing.id,'receipt_ref',existing.evidence_ref,'replayed',true,
      'bundle_id',(select id from ops.staging_recovery_rehearsal_bundle where recovery_attempt_id=attempt.recovery_attempt_id),
      'recovery_run_id',(select r.id from ops.run r join ops.staging_recovery_rehearsal_bundle b on b.id=r.recovery_rehearsal_bundle_id where b.recovery_attempt_id=attempt.recovery_attempt_id));
  end if;
  select * into strict current_release from ops.release where id=attempt.rehearsal_release_id;
  if attempt.declared_migration_set_sha256<>ops.program5_migration_set_sha256(current_release.migration_set)
     or attempt.declared_migration_count<>cardinality(current_release.migration_set)
     or attempt.declared_schema_highest_migration<>current_release.schema_highest_migration
     or attempt.declared_schema_applied_count<>current_release.schema_applied_count
     or attempt.declared_schema_ledger_sha256<>current_release.schema_ledger_sha256
     or p_schema_highest_migration<>attempt.declared_schema_highest_migration
     or p_schema_applied_count<>attempt.declared_schema_applied_count then
    raise exception 'staging readback schema does not match the exact declared candidate migration set'; end if;
  if p_provider_tag<>attempt.expected_provider_tag then raise exception 'staging readback provider tag does not match its prepared attempt'; end if;
  service_uuid:=current_release.service_id;
  select * into strict observed_release from ops.release where id=attempt.observed_release_id;
  if attempt.prior_release_id is not null then select * into strict prior_release from ops.release where id=attempt.prior_release_id; end if;
  projection:=jsonb_build_object(
    'deployment_attempt_id',attempt.id,'correlation_id',attempt.correlation_id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'recovery_step',attempt.recovery_step,'rehearsal_release_id',current_release.id,'observed_release_id',observed_release.id,
    'prior_release_id',attempt.prior_release_id,'service_id',service_uuid,'environment','staging','git_sha',attempt.git_sha,
    'provider','cloudflare-workers','provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,
    'verb_count',p_verb_count,'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,
    'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256,
    'doctrine_generation',p_doctrine_generation,'program6_actions_enabled',p_program6_actions_enabled);
  projection_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex'); receipt_ref:='ops.staging-release-readback:'||projection_hash;
  insert into ops.deployment(correlation_id,service_id,environment,state,git_sha,provider,provider_version_id,release_id,deployed_by_actor,verb_count,schema_highest_migration,doctrine_generation,started_at,ended_at,read_back_at,verification_evidence_ref,source_kind,source_ref,observed_at)
  values(attempt.correlation_id,service_uuid,'staging','complete',attempt.git_sha,'cloudflare-workers',p_provider_version_id::text,observed_release.id,session_user,p_verb_count,p_schema_highest_migration,p_doctrine_generation,observed_time,observed_time,observed_time,receipt_ref,'wrapper','bin/deploy-worker.sh',observed_time) returning id into deployment_uuid;
  insert into ops.staging_release_readback_receipt(idempotency_key,deployment_attempt_id,recovery_attempt_id,recovery_step,correlation_id,deployment_id,rehearsal_release_id,observed_release_id,prior_release_id,service_id,environment,git_sha,provider,provider_version_id,provider_tag,verb_count,schema_highest_migration,schema_applied_count,declared_migration_set_sha256,declared_migration_count,declared_schema_applied_count,declared_schema_ledger_sha256,doctrine_generation,program6_actions_enabled,projection_sha256,evidence_ref,observed_at,writer_session_user)
  values(p_idempotency_key,attempt.id,attempt.recovery_attempt_id,attempt.recovery_step,attempt.correlation_id,deployment_uuid,current_release.id,observed_release.id,attempt.prior_release_id,service_uuid,'staging',attempt.git_sha,'cloudflare-workers',p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,p_schema_applied_count,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,p_doctrine_generation,p_program6_actions_enabled,projection_hash,receipt_ref,observed_time,session_user) returning id into receipt_uuid;
  if attempt.recovery_step='current_after' then
    select * into before_receipt from ops.staging_release_readback_receipt where recovery_attempt_id=attempt.recovery_attempt_id and recovery_step='current_before'; if not found then raise exception 'current_after requires current_before receipt'; end if;
    select * into prior_receipt from ops.staging_release_readback_receipt where recovery_attempt_id=attempt.recovery_attempt_id and recovery_step='prior'; if not found then raise exception 'current_after requires prior receipt'; end if;
    select * into strict after_receipt from ops.staging_release_readback_receipt where id=receipt_uuid;
    if before_receipt.rehearsal_release_id<>current_release.id or prior_receipt.rehearsal_release_id<>current_release.id
       or before_receipt.prior_release_id<>prior_release.id or prior_receipt.prior_release_id<>prior_release.id
       or before_receipt.observed_release_id<>current_release.id or prior_receipt.observed_release_id<>prior_release.id or after_receipt.observed_release_id<>current_release.id
       or before_receipt.service_id<>service_uuid or prior_receipt.service_id<>service_uuid
       or before_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256 or prior_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256 or after_receipt.declared_migration_set_sha256<>attempt.declared_migration_set_sha256
       or before_receipt.declared_migration_count<>attempt.declared_migration_count or prior_receipt.declared_migration_count<>attempt.declared_migration_count or after_receipt.declared_migration_count<>attempt.declared_migration_count
       or before_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration or prior_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration or after_receipt.schema_highest_migration<>attempt.declared_schema_highest_migration
       or before_receipt.schema_applied_count<>attempt.declared_schema_applied_count or prior_receipt.schema_applied_count<>attempt.declared_schema_applied_count or after_receipt.schema_applied_count<>attempt.declared_schema_applied_count
       or before_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256 or prior_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256 or after_receipt.declared_schema_ledger_sha256<>attempt.declared_schema_ledger_sha256
       or not(before_receipt.observed_at<prior_receipt.observed_at and prior_receipt.observed_at<after_receipt.observed_at) or after_receipt.observed_at-before_receipt.observed_at>interval '1 hour' then
      raise exception 'recovery receipts do not form an ordered current-prior-current chain'; end if;
    bundle_projection:=jsonb_build_object('recovery_attempt_id',attempt.recovery_attempt_id,'current_release_id',current_release.id,'prior_release_id',prior_release.id,'service_id',service_uuid,'current_before_receipt_id',before_receipt.id,'prior_after_rollback_receipt_id',prior_receipt.id,'current_after_restore_receipt_id',after_receipt.id,'recovery_strategy',current_release.recovery_strategy,'recovery_plan_ref',current_release.rollback_plan_ref,'plan_hash',current_release.plan_hash,'declared_migration_set_sha256',attempt.declared_migration_set_sha256,'declared_migration_count',attempt.declared_migration_count,'declared_schema_highest_migration',attempt.declared_schema_highest_migration,'declared_schema_applied_count',attempt.declared_schema_applied_count,'declared_schema_ledger_sha256',attempt.declared_schema_ledger_sha256);
    bundle_hash:='sha256:'||encode(public.digest(bundle_projection::text,'sha256'),'hex'); bundle_ref:='ops.staging-recovery-bundle:'||bundle_hash;
    insert into ops.staging_recovery_rehearsal_bundle(recovery_attempt_id,correlation_id,current_release_id,prior_release_id,service_id,environment,current_before_receipt_id,prior_after_rollback_receipt_id,current_after_restore_receipt_id,recovery_strategy,recovery_plan_ref,plan_hash,bundle_sha256,evidence_ref,declared_migration_set_sha256,declared_migration_count,declared_schema_highest_migration,declared_schema_applied_count,declared_schema_ledger_sha256,completed_at,writer_session_user)
    values(attempt.recovery_attempt_id,attempt.correlation_id,current_release.id,prior_release.id,service_uuid,'staging',before_receipt.id,prior_receipt.id,after_receipt.id,'rollback',current_release.rollback_plan_ref,current_release.plan_hash,bundle_hash,bundle_ref,attempt.declared_migration_set_sha256,attempt.declared_migration_count,attempt.declared_schema_highest_migration,attempt.declared_schema_applied_count,attempt.declared_schema_ledger_sha256,after_receipt.observed_at,session_user) returning id into bundle_uuid;
    insert into ops.run(correlation_id,kind,service_id,environment,run_key,state,started_at,ended_at,source_kind,source_ref,observed_at,evidence_ref,release_id,recovery_strategy,recovery_plan_ref,recovery_rehearsal_bundle_id)
    values(attempt.correlation_id,'check',service_uuid,'staging','recovery.rehearsal.worker','succeeded',before_receipt.observed_at,after_receipt.observed_at,'wrapper','bin/deploy-worker.sh',after_receipt.observed_at,bundle_ref,current_release.id,'rollback',current_release.rollback_plan_ref,bundle_uuid) returning id into run_uuid;
  end if;
  return jsonb_build_object('receipt_id',receipt_uuid,'receipt_ref',receipt_ref,'replayed',false,'bundle_id',bundle_uuid,'recovery_run_id',run_uuid);
end $_$;


--
-- Name: record_staging_replacement_project(uuid, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_replacement_project(p_idempotency_key uuid, p_observation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare
  expected_keys constant text[] := array[
    'artifact_sha256','config_sha256','dependency_sha256','git_sha',
    'prior_staging_project_id','production_overlap_count','replacement_branch_id',
    'replacement_endpoint_id','replacement_project_id','schema_version',
    'source_tree_entry_count','source_tree_oid','source_tree_sha256','synthetic_data_count'
  ];
  supplied_keys text[]; contract ops.staging_replacement_project_contract%rowtype;
  existing ops.staging_replacement_project_receipt%rowtype; receipt_uuid uuid;
  live_ledger jsonb; live_count integer; live_highest text; live_digest text;
  derived_synthetic_count bigint; observed_at_value timestamptz;
  projection jsonb; receipt_digest text; receipt_ref text;
begin
  if session_user<>'carr_program5_forward_fix_verifier'
     or not pg_has_role(session_user,'carr_program5_forward_fix_verifiers','member') then
    raise exception 'staging replacement recording requires the scoped verifier session';
  end if;
  if p_idempotency_key is null or jsonb_typeof(p_observation)<>'object' then
    raise exception 'invalid staging replacement observation input';
  end if;
  select array_agg(k order by k collate "C") into supplied_keys
    from jsonb_object_keys(p_observation) as keys(k);
  if supplied_keys is distinct from expected_keys
     or jsonb_typeof(p_observation->'source_tree_entry_count')<>'number'
     or jsonb_typeof(p_observation->'synthetic_data_count')<>'number'
     or jsonb_typeof(p_observation->'production_overlap_count')<>'number' then
    raise exception 'staging replacement observation has missing, unknown, or invalid typed keys';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,322));
  select * into contract from ops.staging_replacement_project_contract
   where idempotency_key=p_idempotency_key;
  if not found then raise exception 'staging replacement contract was not prepared'; end if;

  if (p_observation->>'schema_version',p_observation->>'git_sha',
      p_observation->>'source_tree_oid',p_observation->>'source_tree_sha256',
      (p_observation->>'source_tree_entry_count')::integer,
      p_observation->>'artifact_sha256',p_observation->>'config_sha256',
      p_observation->>'dependency_sha256',p_observation->>'prior_staging_project_id',
      p_observation->>'replacement_project_id',p_observation->>'replacement_branch_id',
      p_observation->>'replacement_endpoint_id') is distinct from
     ('clean-staging-replacement-observation.v1',contract.git_sha,
      contract.source_tree_oid,contract.source_tree_sha256,contract.source_tree_entry_count,
      contract.artifact_sha256,contract.config_sha256,contract.dependency_sha256,
      contract.prior_staging_project_id,contract.replacement_project_id,
      contract.replacement_branch_id,contract.replacement_endpoint_id) then
    raise exception 'staging replacement observation does not match the prepared immutable identity';
  end if;

  -- The local count is derived here from the replacement database. Production
  -- overlap is cross-project evidence: this function can only require the
  -- controller's governed G1 table-ID comparison assertion to be exactly zero.
  if to_regclass('public.party') is null or to_regclass('public.client') is null
     or to_regclass('public.deal') is null or to_regclass('public.lead') is null
     or to_regclass('public.vendor') is null then
    raise exception 'replacement database lacks a required synthetic-data table';
  end if;
  select (select count(*) from public.party)
       + (select count(*) from public.client)
       + (select count(*) from public.deal)
       + (select count(*) from public.lead)
       + (select count(*) from public.vendor)
    into derived_synthetic_count;
  if derived_synthetic_count<=0
     or (p_observation->>'synthetic_data_count')::bigint<>derived_synthetic_count
     or derived_synthetic_count<>contract.expected_synthetic_data_count
     or (p_observation->>'production_overlap_count')::bigint<>0
     or contract.expected_production_overlap_count<>0 then
    raise exception 'staging replacement synthetic-data or no-Production-overlap assertion failed';
  end if;

  select coalesce(jsonb_object_agg(filename,sha256 order by filename collate "C"),'{}'::jsonb),
         count(*)::integer,max(filename collate "C"),
         'sha256:'||encode(public.digest(
           coalesce(string_agg(convert_to(filename,'UTF8')||decode('00','hex')||
             convert_to(sha256,'UTF8')||decode('0a','hex'),''::bytea
             order by filename collate "C"),''::bytea),'sha256'),'hex')
    into live_ledger,live_count,live_highest,live_digest
    from public.schema_migrations;
  if live_ledger is distinct from contract.migration_ledger
     or live_count is distinct from contract.migration_count
     or live_highest is distinct from contract.migration_highest
     or live_digest is distinct from contract.migration_ledger_sha256 then
    raise exception 'replacement database live full migration ledger does not match the exact declared tree';
  end if;

  select * into existing from ops.staging_replacement_project_receipt
   where contract_id=contract.id;
  if found then
    if (existing.schema_version,existing.git_sha,existing.source_tree_oid,
        existing.source_tree_sha256,existing.source_tree_entry_count,
        existing.artifact_sha256,existing.config_sha256,existing.dependency_sha256,
        existing.prior_staging_project_id,existing.replacement_project_id,
        existing.replacement_branch_id,existing.replacement_endpoint_id,
        existing.live_migration_ledger,existing.live_migration_count,
        existing.live_migration_highest,existing.live_migration_ledger_sha256,
        existing.synthetic_data_count,existing.production_overlap_count) is distinct from
       (p_observation->>'schema_version',contract.git_sha,contract.source_tree_oid,
        contract.source_tree_sha256,contract.source_tree_entry_count,contract.artifact_sha256,
        contract.config_sha256,contract.dependency_sha256,contract.prior_staging_project_id,
        contract.replacement_project_id,contract.replacement_branch_id,
        contract.replacement_endpoint_id,live_ledger,live_count,live_highest,live_digest,
        derived_synthetic_count,0::bigint) then
      raise exception 'staging replacement observation replay changed recorded evidence';
    end if;
    return jsonb_build_object('contract_id',contract.id,'receipt_id',existing.id,
      'evidence_ref',existing.evidence_ref,'state','observed','replayed',true);
  end if;

  observed_at_value:=clock_timestamp();
  projection:=jsonb_build_object('contract_id',contract.id,'git_sha',contract.git_sha,
    'source_tree_oid',contract.source_tree_oid,'source_tree_sha256',contract.source_tree_sha256,
    'source_tree_entry_count',contract.source_tree_entry_count,
    'artifact_sha256',contract.artifact_sha256,'config_sha256',contract.config_sha256,
    'dependency_sha256',contract.dependency_sha256,
    'prior_staging_project_id',contract.prior_staging_project_id,
    'replacement_project_id',contract.replacement_project_id,
    'replacement_branch_id',contract.replacement_branch_id,
    'replacement_endpoint_id',contract.replacement_endpoint_id,
    'live_migration_ledger',live_ledger,'live_migration_count',live_count,
    'live_migration_highest',live_highest,'live_migration_ledger_sha256',live_digest,
    'synthetic_data_count',derived_synthetic_count,'production_overlap_count',0,
    'observed_at',observed_at_value);
  receipt_digest:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  receipt_ref:='ops.staging-replacement-project:'||receipt_digest;
  insert into ops.staging_replacement_project_receipt(
    idempotency_key,contract_id,schema_version,git_sha,source_tree_oid,
    source_tree_sha256,source_tree_entry_count,artifact_sha256,config_sha256,
    dependency_sha256,prior_staging_project_id,replacement_project_id,
    replacement_branch_id,replacement_endpoint_id,live_migration_ledger,
    live_migration_count,live_migration_highest,live_migration_ledger_sha256,
    synthetic_data_count,production_overlap_count,receipt_sha256,evidence_ref,
    writer_session_user,observed_at)
  values(p_idempotency_key,contract.id,p_observation->>'schema_version',contract.git_sha,
    contract.source_tree_oid,contract.source_tree_sha256,contract.source_tree_entry_count,
    contract.artifact_sha256,contract.config_sha256,contract.dependency_sha256,
    contract.prior_staging_project_id,contract.replacement_project_id,
    contract.replacement_branch_id,contract.replacement_endpoint_id,live_ledger,
    live_count,live_highest,live_digest,derived_synthetic_count,0,receipt_digest,
    receipt_ref,session_user,observed_at_value)
  returning id into receipt_uuid;
  return jsonb_build_object('contract_id',contract.id,'receipt_id',receipt_uuid,
    'evidence_ref',receipt_ref,'state','observed','replayed',false);
end $$;


--
-- Name: record_staging_restore_only_result(uuid, text, uuid, text, integer, text, integer, bigint, boolean, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_staging_restore_only_result(p_idempotency_key uuid, p_status text, p_provider_version_id uuid, p_provider_tag text, p_verb_count integer, p_schema_highest_migration text, p_schema_applied_count integer, p_doctrine_generation bigint, p_program6_actions_enabled boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare attempt ops.staging_restore_only_attempt%rowtype; existing ops.staging_restore_only_result%rowtype;
  projection jsonb; result_hash text; result_ref text; result_uuid uuid;
begin
  if session_user<>'carr_jobs' then raise exception 'restore-only result requires the carr_jobs session'; end if;
  if p_idempotency_key is null or p_status not in ('succeeded','failed','unknown') then raise exception 'invalid restore-only result input'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,202));
  select * into attempt from ops.staging_restore_only_attempt where idempotency_key=p_idempotency_key;
  if not found then raise exception 'restore-only result has no prepared attempt'; end if;
  if not exists(select 1 from ops.staging_restore_only_claim where restore_attempt_id=attempt.id) then raise exception 'restore-only result was never claimed'; end if;
  select * into existing from ops.staging_restore_only_result where restore_attempt_id=attempt.id;
  if found then
    if (existing.status,existing.provider_version_id,existing.provider_tag,existing.verb_count,
        existing.schema_highest_migration,existing.schema_applied_count,existing.doctrine_generation,
        existing.program6_actions_enabled,existing.reason) is distinct from
       (p_status,p_provider_version_id,p_provider_tag,p_verb_count,p_schema_highest_migration,
        p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled,p_reason) then
      raise exception 'restore-only result idempotency key was reused with changed input';
    end if;
    return jsonb_build_object('restore_result_id',existing.id,'result_ref',existing.evidence_ref,'status',existing.status,'replayed',true);
  end if;
  if p_status='succeeded' then
    if p_provider_version_id is null or p_provider_tag<>attempt.expected_provider_tag or coalesce(p_verb_count,0)<=0
       or coalesce(p_schema_highest_migration,'')<>attempt.declared_schema_highest_migration
       or p_schema_applied_count<>attempt.declared_schema_applied_count or p_doctrine_generation is null
       or p_program6_actions_enabled is null or p_reason is not null then
      raise exception 'restore-only success lacks exact current-target readback';
    end if;
  elsif p_provider_version_id is not null or p_provider_tag is not null or p_verb_count is not null
     or p_schema_highest_migration is not null or p_schema_applied_count is not null
     or p_doctrine_generation is not null or p_program6_actions_enabled is not null
     or coalesce(p_reason,'') !~ '^[a-z0-9_.:-]{1,240}$' then
    raise exception 'restore-only non-success requires only a bounded reason';
  end if;
  projection:=jsonb_build_object('restore_attempt_id',attempt.id,'recovery_attempt_id',attempt.recovery_attempt_id,
    'target_release_id',attempt.rehearsal_release_id,'prior_release_id',attempt.prior_release_id,
    'target_provider_version_id',attempt.target_provider_version_id,'environment','staging','status',p_status,
    'provider_version_id',p_provider_version_id,'provider_tag',p_provider_tag,'verb_count',p_verb_count,
    'schema_highest_migration',p_schema_highest_migration,'schema_applied_count',p_schema_applied_count,
    'doctrine_generation',p_doctrine_generation,'program6_actions_enabled',p_program6_actions_enabled,'reason',p_reason);
  result_hash:='sha256:'||encode(public.digest(projection::text,'sha256'),'hex');
  result_ref:='ops.staging-restore-only:'||result_hash;
  insert into ops.staging_restore_only_result(idempotency_key,restore_attempt_id,status,provider_version_id,
    provider_tag,verb_count,schema_highest_migration,schema_applied_count,doctrine_generation,
    program6_actions_enabled,reason,result_sha256,evidence_ref,writer_session_user)
  values(p_idempotency_key,attempt.id,p_status,p_provider_version_id,p_provider_tag,p_verb_count,
    p_schema_highest_migration,p_schema_applied_count,p_doctrine_generation,p_program6_actions_enabled,
    p_reason,result_hash,result_ref,session_user) returning id into result_uuid;
  return jsonb_build_object('restore_result_id',result_uuid,'result_ref',result_ref,'status',p_status,'replayed',false);
end $_$;


--
-- Name: record_tour_map_promotion_receipt(text, uuid, jsonb, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_tour_map_promotion_receipt(p_tenant text, p_projection_id uuid, p_payload jsonb, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_id uuid; v_projection ops.tour_public_projection%rowtype; v_tour ops.tour%rowtype;
  v_verified_slug text; v_verified_actor_id text;
  v_required_check_keys constant text[]:=array[
    'canonical_address_and_coordinate_review','claims_and_layers_have_source_as_of_rights_and_review_state',
    'deterministic_rebuild_from_canonical_record','exact_native_navigation_handoff',
    'locked_appointments_dwell_and_buffers_preserved','map_list_route_offline_order_parity',
    'no_unresolved_route_critical_unknown_or_conflict','optional_context_layers_progressively_disclosed',
    'ordered_offline_itinerary_verified','phone_and_ipad_interaction_test',
    'provider_terms_attribution_expiry_and_cost_gate_passed'];
begin
  if jsonb_typeof(p_payload)<>'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_payload) k) is distinct from array[
       'brief_version','canonical_dataset_version','component_registry_version','decision','decision_reason',
       'mobile_test_evidence','native_navigation_test_evidence','offline_test_evidence',
       'provider_rights_receipt_ids','receipt_digest','required_checks','reviewed_at',
       'route_version','selected_prototype_id']
  then raise exception 'tour map promotion receipt payload is invalid'; end if;
  v_verified_slug:=nullif(btrim(current_setting('carr.verified_human_actor_slug',true)),'');
  select id::text into v_verified_actor_id from public.actor where slug=v_verified_slug;
  if v_verified_actor_id is null or v_verified_actor_id is distinct from p_actor_id then
    raise exception 'tour map promotion requires a verified human authority session';
  end if;
  select * into v_projection from ops.tour_public_projection
    where organization_tenant_id=p_tenant and id=p_projection_id and status='approved';
  select * into v_tour from ops.tour
    where organization_tenant_id=p_tenant and id=v_projection.tour_id;
  if not found or v_projection.id is null
     or not ops.tour_public_map_projection_evidence_ready(p_tenant,p_projection_id)
     or p_payload->>'decision' not in ('approved','rejected')
     or nullif(btrim(p_payload->>'decision_reason'),'') is null
     or char_length(btrim(p_payload->>'decision_reason'))>500
     or p_payload->>'decision_reason' ~ '[[:cntrl:]]'
     or (p_payload->>'reviewed_at')::timestamptz>now()
     or nullif(btrim(p_payload->>'brief_version'),'') is null
     or nullif(btrim(p_payload->>'selected_prototype_id'),'') is null
     or nullif(btrim(p_payload->>'component_registry_version'),'') is null
     or p_payload->>'canonical_dataset_version' is distinct from v_tour.canonical_dataset_version
     or (p_payload->>'route_version')::integer is distinct from v_projection.route_version
     or p_payload->>'receipt_digest' !~ '^sha256:[a-f0-9]{64}$'
     or jsonb_typeof(p_payload->'provider_rights_receipt_ids')<>'array'
     or jsonb_array_length(p_payload->'provider_rights_receipt_ids')=0
     or exists(select 1 from jsonb_array_elements_text(p_payload->'provider_rights_receipt_ids') x where x !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
     or (select count(*) from jsonb_array_elements_text(p_payload->'provider_rights_receipt_ids'))
        <> (select count(distinct x) from jsonb_array_elements_text(p_payload->'provider_rights_receipt_ids') x)
     or jsonb_typeof(p_payload->'mobile_test_evidence')<>'object' or p_payload->'mobile_test_evidence'='{}'::jsonb
     or jsonb_typeof(p_payload->'native_navigation_test_evidence')<>'object' or p_payload->'native_navigation_test_evidence'='{}'::jsonb
     or jsonb_typeof(p_payload->'offline_test_evidence')<>'object' or p_payload->'offline_test_evidence'='{}'::jsonb
     or jsonb_typeof(p_payload->'required_checks')<>'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_payload->'required_checks') k) is distinct from v_required_check_keys
     or exists(select 1 from jsonb_each(p_payload->'required_checks') check_row where check_row.value not in ('true'::jsonb,'false'::jsonb))
     or (p_payload->>'decision'='approved' and (
       exists(select 1 from jsonb_each(p_payload->'required_checks') check_row where check_row.value<>'true'::jsonb)
       or p_payload#>>'{mobile_test_evidence,status}' is distinct from 'passed'
       or p_payload#>>'{native_navigation_test_evidence,status}' is distinct from 'passed'
       or p_payload#>>'{offline_test_evidence,status}' is distinct from 'passed'))
     or (p_payload->>'decision'='rejected' and not (
       exists(select 1 from jsonb_each(p_payload->'required_checks') check_row where check_row.value='false'::jsonb)
       or p_payload#>>'{mobile_test_evidence,status}'='failed'
       or p_payload#>>'{native_navigation_test_evidence,status}'='failed'
       or p_payload#>>'{offline_test_evidence,status}'='failed'))
  then raise exception 'tour map promotion receipt is invalid or incomplete'; end if;
  if exists (
    (select x::uuid from jsonb_array_elements_text(p_payload->'provider_rights_receipt_ids') x
     except
     select distinct r.id from ops.tour_public_projection_map_point mp
       join ops.tour_property_coordinate_candidate c on c.organization_tenant_id=mp.organization_tenant_id and c.id=mp.coordinate_candidate_id
       join ops.tour_rights_receipt r on r.organization_tenant_id=c.organization_tenant_id and r.id=c.rights_receipt_id
      where mp.organization_tenant_id=p_tenant and mp.projection_id=p_projection_id)
    union all
    (select distinct r.id from ops.tour_public_projection_map_point mp
       join ops.tour_property_coordinate_candidate c on c.organization_tenant_id=mp.organization_tenant_id and c.id=mp.coordinate_candidate_id
       join ops.tour_rights_receipt r on r.organization_tenant_id=c.organization_tenant_id and r.id=c.rights_receipt_id
      where mp.organization_tenant_id=p_tenant and mp.projection_id=p_projection_id
     except
     select x::uuid from jsonb_array_elements_text(p_payload->'provider_rights_receipt_ids') x)
  ) then raise exception 'tour map promotion provider-rights evidence mismatch'; end if;
  insert into ops.tour_map_promotion_receipt(
    organization_tenant_id,projection_id,reviewer_actor_id,reviewed_at,decision,decision_reason,
    brief_version,canonical_dataset_version,selected_prototype_id,component_registry_version,
    route_version,provider_rights_receipt_ids,mobile_test_evidence,native_navigation_test_evidence,
    offline_test_evidence,required_checks,receipt_digest)
  values(p_tenant,p_projection_id,p_actor_id,(p_payload->>'reviewed_at')::timestamptz,p_payload->>'decision',btrim(p_payload->>'decision_reason'),
    p_payload->>'brief_version',p_payload->>'canonical_dataset_version',p_payload->>'selected_prototype_id',
    p_payload->>'component_registry_version',(p_payload->>'route_version')::integer,
    p_payload->'provider_rights_receipt_ids',p_payload->'mobile_test_evidence',
    p_payload->'native_navigation_test_evidence',p_payload->'offline_test_evidence',
    p_payload->'required_checks',p_payload->>'receipt_digest') returning id into v_id;
  return v_id;
end $_$;


--
-- Name: record_tour_pdf_human_review(text, uuid, text, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_tour_pdf_human_review(p_tenant text, p_render_job_id uuid, p_qc_run_digest text, p_decision text, p_reviewed_at timestamp with time zone, p_review_receipt_digest text, p_reason text, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_result ops.tour_pdf_render_result%rowtype; v_id uuid; v_verified_slug text; v_verified_actor_id text;
begin
  v_verified_slug:=nullif(btrim(current_setting('carr.verified_human_actor_slug',true)),'');
  select id::text into v_verified_actor_id from public.actor where slug=v_verified_slug;
  if v_verified_actor_id is null or v_verified_actor_id is distinct from p_actor_id then
    raise exception 'tour PDF review requires a verified human authority session';
  end if;
  select * into v_result from ops.tour_pdf_render_result where organization_tenant_id=p_tenant and render_job_id=p_render_job_id and status='review_ready' and qc_run_digest=p_qc_run_digest order by attempt_count desc,id desc limit 1 for update;
  if not found or p_decision not in ('accept','reject') or p_review_receipt_digest !~ '^sha256:[a-f0-9]{64}$' or nullif(btrim(p_reason),'') is null or nullif(btrim(p_actor_id),'') is null then raise exception 'tour PDF human review is invalid'; end if;
  insert into ops.tour_pdf_human_review(organization_tenant_id,render_job_id,render_result_id,qc_run_digest,decision,reviewed_at,review_receipt_digest,reason,reviewer_actor_id)
  values(p_tenant,p_render_job_id,v_result.id,p_qc_run_digest,p_decision,p_reviewed_at,p_review_receipt_digest,p_reason,p_actor_id) returning id into v_id;
  return v_id;
end $_$;


--
-- Name: record_tour_pdf_render_result(text, uuid, text, text, text, text, integer, integer, integer, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_tour_pdf_render_result(p_tenant text, p_render_job_id uuid, p_status text, p_artifact_ref text, p_artifact_digest text, p_storage_ref text, p_content_length integer, p_page_count integer, p_blocking_finding_count integer, p_qc_run_digest text, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_job ops.tour_pdf_render_job%rowtype; v_attempt integer; v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_tenant||':'||p_render_job_id::text||':pdf-result',403));
  select * into v_job from ops.tour_pdf_render_job where organization_tenant_id=p_tenant and id=p_render_job_id for share;
  if not found or p_status not in ('review_ready','qc_blocked','failed') or nullif(btrim(p_actor_id),'') is null
     or p_qc_run_digest !~ '^sha256:[a-f0-9]{64}$' or p_blocking_finding_count<0
     or exists(select 1 from ops.tour_pdf_human_review h where h.organization_tenant_id=p_tenant and h.render_job_id=p_render_job_id)
     or (p_status='failed' and (p_artifact_ref is not null or p_artifact_digest is not null or p_storage_ref is not null
       or p_content_length is not null or p_page_count is not null or p_blocking_finding_count<>0))
     or (p_status<>'failed' and (p_artifact_digest !~ '^sha256:[a-f0-9]{64}$'
       or p_page_count<>v_job.expected_property_count or p_content_length<=0
       or (p_status='review_ready' and p_blocking_finding_count<>0)
       or p_artifact_ref !~ '^artifact:tour-pdf:[A-Za-z0-9_-]{16,128}$'
       or p_storage_ref !~ '^tour-pdf/[A-Za-z0-9._/-]{16,400}\.pdf$')) then
    raise exception 'tour PDF render result is invalid';
  end if;
  select coalesce(max(attempt_count),0)+1 into v_attempt from ops.tour_pdf_render_result where organization_tenant_id=p_tenant and render_job_id=p_render_job_id;
  insert into ops.tour_pdf_render_result(organization_tenant_id,render_job_id,status,artifact_ref,artifact_digest,storage_ref,content_length,page_count,blocking_finding_count,qc_run_digest,attempt_count,completed_at)
  values(p_tenant,p_render_job_id,p_status,p_artifact_ref,p_artifact_digest,p_storage_ref,p_content_length,p_page_count,p_blocking_finding_count,p_qc_run_digest,v_attempt,now()) returning id into v_id;
  return v_id;
end $_$;


--
-- Name: record_workflow_acceptance(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v integer; rid uuid; authority_actor text;
begin
  authority_actor := ops.authority_actor_slug();
  if p_status='accepted' and p_mode='canary' and authority_actor <> 'joe' then
    raise exception 'accepted canary workflow evidence requires Joe authority session';
  end if;
  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  if p_status='accepted' and not exists (
    select 1 from ops.job j join ops.job_receipt r on r.job_id=j.id
     where j.definition_key=p_workflow_key and j.definition_version=v
       and j.mode=p_mode and r.kind='completion' and r.receipt_ref=p_receipt_ref
  ) then
    raise exception 'accepted workflow evidence must name a completion receipt from the matching workflow and mode';
  end if;
  insert into ops.workflow_acceptance
    (workflow_key,workflow_version,mode,status,receipt_ref,accepted_by)
  values(p_workflow_key,v,p_mode,p_status,p_receipt_ref,
         case when p_status='accepted' then authority_actor else null end)
  returning id into rid;
  return rid;
end $$;


--
-- Name: FUNCTION record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text) IS 'Control Plane: accepted canary evidence requires Joe; shadow acceptance remains available to admitted human authority sessions.';


--
-- Name: record_workflow_acceptance(text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.record_workflow_acceptance(p_workflow_key text, p_mode text, p_status text, p_receipt_ref text, p_actor text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v integer; rid uuid; human_actor actor%rowtype;
begin
  select version into v from ops.job_definition
   where key=p_workflow_key order by version desc limit 1;
  if v is null then raise exception 'unknown workflow %',p_workflow_key; end if;
  if p_status='accepted' then
    select * into human_actor from actor
     where slug=p_actor and kind='human' and active;
    if not found then
      raise exception 'accepted workflow evidence requires an active human actor';
    end if;
    if not exists (
      select 1
        from ops.job j join ops.job_receipt r on r.job_id=j.id
       where j.definition_key=p_workflow_key and j.definition_version=v
         and j.mode=p_mode and r.kind='completion' and r.receipt_ref=p_receipt_ref
    ) then
      raise exception 'accepted workflow evidence must name a completion receipt from the matching workflow and mode';
    end if;
  end if;
  insert into ops.workflow_acceptance
    (workflow_key,workflow_version,mode,status,receipt_ref,accepted_by)
  values(p_workflow_key,v,p_mode,p_status,p_receipt_ref,
         case when p_status='accepted' then human_actor.slug else null end)
  returning id into rid;
  return rid;
end $$;


--
-- Name: redeem_program6_browser_action_challenge(text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.redeem_program6_browser_action_challenge(p_token_digest text, p_session_digest text, p_action text, p_material_digest text, p_idempotency_key uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  v_actor_slug text;
  v_actor public.actor%rowtype;
  v_inserted_id uuid;
begin
  if coalesce(p_token_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_session_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_material_digest, '') !~ '^[0-9a-f]{64}$'
     or coalesce(p_action, '') not in ('accept-ready-plan','accept-outcome-feedback')
     or p_idempotency_key is null then
    raise exception 'browser approval challenge requires lowercase SHA-256 token, session, and material digests, one approved action, and a UUID idempotency key';
  end if;

  v_actor_slug := ops.authority_actor_slug();
  select a.* into v_actor
    from public.actor a
   where a.slug = v_actor_slug
     and a.active
     and a.kind = 'human'
   for share;
  if not found then
    raise exception 'authority session user is not an active human actor';
  end if;

  -- The token's unique index makes concurrent redemption atomic.  A token
  -- that has already been consumed is an ordinary false result, never a
  -- second authority action and never a mutation of the first audit fact.
  insert into ops.program6_browser_action_challenge_redemption
    (token_digest,session_digest,action,material_digest,idempotency_key,redeemed_by_actor_id)
  values
    (p_token_digest,p_session_digest,p_action,p_material_digest,p_idempotency_key,v_actor.id)
  on conflict (token_digest) do nothing
  returning id into v_inserted_id;

  return v_inserted_id is not null;
end;
$_$;


--
-- Name: refuse_approved_rule_contract_rewrite(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.refuse_approved_rule_contract_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_rule_id uuid;
begin
  v_rule_id := case when tg_op='INSERT' then new.rule_id else old.rule_id end;
  if exists (select 1 from ops.rule_approval_receipt where rule_id=v_rule_id) then
    raise exception 'approved rule % contract is immutable; approve a replacement rule',v_rule_id;
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


