--
-- Name: register_execution_environment_provider(jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.register_execution_environment_provider(p_manifest jsonb, p_idempotency_key uuid) RETURNS TABLE(provider_ref text, manifest_digest text, state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare actor_row actor%rowtype; existing ops.execution_environment_provider%rowtype;
  row_out ops.execution_environment_provider%rowtype; digest_value text; v_actor_slug text; allowed text[] := array[
    'schema_version','provider_key','provider_version','display_name','source_class','backend_kind',
    'implementation_ref','implementation_digest','capability_refs','operation_refs','isolation_class',
    'egress_policy_ref','secret_policy_ref','persistence_mode','resource_policy_ref','cleanup_policy_ref',
    'threat_model_ref','conformance_contract_ref','conformance_contract_digest','configuration_schema_digest',
    'package_provenance','collision_policy','contains_secrets','manifest_digest'];
begin
  if session_user ~ '^carr_authority_' then
    v_actor_slug := regexp_replace(session_user,'^carr_authority_','');
  elsif session_user = 'carr_writer' then
    v_actor_slug := nullif(btrim(current_setting('carr.acting_actor_slug', true)), '');
  else
    raise exception 'provider registration requires the authority connection or a sponsored writer session';
  end if;
  select * into actor_row from actor where slug=v_actor_slug and kind in ('human','automation') and active;
  if actor_row.id is null or jsonb_typeof(p_manifest)<>'object'
     or not (p_manifest ?& allowed)
     or exists(select 1 from jsonb_object_keys(p_manifest) k where k<>all(allowed))
     or p_manifest->>'schema_version'<>'execution-environment-provider.v1'
     or p_manifest->>'source_class'<>'plugin' or p_manifest->>'collision_policy'<>'digest_pinned'
     or p_manifest->>'contains_secrets'<>'false'
     or p_manifest->>'provider_key' !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'
     or p_manifest->>'provider_key'=any(array['hermes-local','hermes-docker','hermes-ssh','hermes-singularity','hermes-modal','hermes-daytona','hermes-vercel-sandbox'])
     or coalesce((p_manifest->>'provider_version')::integer,0)<1
     or p_manifest->>'backend_kind' not in ('none','local','container','remote','cloud')
     or p_manifest->>'isolation_class' not in ('none','host_process','container','microvm','remote_host')
     or jsonb_typeof(p_manifest->'capability_refs')<>'array' or jsonb_array_length(p_manifest->'capability_refs')=0
     or jsonb_typeof(p_manifest->'operation_refs')<>'array'
     or not (p_manifest->'operation_refs' ?& array['operation:create','operation:exec','operation:cancel','operation:destroy','operation:health'])
     or jsonb_typeof(p_manifest->'package_provenance')<>'object'
     or not (p_manifest->'package_provenance' ?& array['package_ref','package_digest','signature_ref','sbom_ref'])
     or exists(select 1 from jsonb_object_keys(p_manifest->'package_provenance') k where k<>all(array['package_ref','package_digest','signature_ref','sbom_ref']))
     or p_manifest->>'display_name' !~ '^.{1,80}$'
     or p_manifest->>'display_name' ~ '[[:cntrl:]]'
     or p_manifest->>'implementation_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_manifest->>'implementation_digest' !~ '^sha256:[0-9a-f]{64}$'
     or p_manifest->>'conformance_contract_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_manifest->>'conformance_contract_digest' !~ '^sha256:[0-9a-f]{64}$'
     or p_manifest->>'configuration_schema_digest' !~ '^sha256:[0-9a-f]{64}$'
     or p_manifest->'package_provenance'->>'package_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_manifest->'package_provenance'->>'package_digest' !~ '^sha256:[0-9a-f]{64}$'
     or p_manifest->'package_provenance'->>'signature_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_manifest->'package_provenance'->>'sbom_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
     or p_manifest->>'persistence_mode' not in ('none','command_scoped','session_scoped','durable_workspace')
     or exists(select 1 from unnest(array['egress_policy_ref','secret_policy_ref','resource_policy_ref','cleanup_policy_ref','threat_model_ref']) field where p_manifest->>field !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$')
     or exists(select 1 from jsonb_array_elements_text(p_manifest->'operation_refs') op where op !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$')
     or (select count(*) from jsonb_array_elements_text(p_manifest->'operation_refs'))<>(select count(distinct op) from jsonb_array_elements_text(p_manifest->'operation_refs') op)
     or (select count(*) from jsonb_array_elements_text(p_manifest->'capability_refs'))<>(select count(distinct cap) from jsonb_array_elements_text(p_manifest->'capability_refs') cap)
     or exists(select 1 from jsonb_array_elements_text(p_manifest->'capability_refs') c where c not in ('environment:none','environment:exec','environment:filesystem','environment:process','environment:network-governed','environment:snapshot','environment:transfer','environment:persistent-workspace')) then
    raise exception 'execution environment plugin manifest is not closed, safe, or complete';
  end if;
  digest_value := 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(p_manifest-'manifest_digest'),'sha256'),'hex');
  if p_manifest->>'manifest_digest' is distinct from digest_value then raise exception 'execution environment plugin manifest digest mismatch'; end if;
  select * into existing from ops.execution_environment_provider where idempotency_key=p_idempotency_key for share;
  if found then
    if existing.manifest is distinct from p_manifest then raise exception 'execution environment provider idempotency conflict'; end if;
    return query select 'environment-provider:'||existing.provider_key||':v'||existing.provider_version,existing.manifest_digest,ops.execution_environment_provider_current_state(existing.id),true; return;
  end if;
  if exists(select 1 from ops.execution_environment_provider p where p.provider_key=p_manifest->>'provider_key' and (p.protected_builtin or p.provider_version>=(p_manifest->>'provider_version')::integer)) then
    raise exception 'execution environment provider key/version is protected, stale, or already registered';
  end if;
  insert into ops.execution_environment_provider(provider_key,provider_version,source_class,backend_kind,manifest_digest,manifest,protected_builtin,created_by_actor_id,idempotency_key)
  values(p_manifest->>'provider_key',(p_manifest->>'provider_version')::integer,'plugin',p_manifest->>'backend_kind',digest_value,p_manifest,false,actor_row.id,p_idempotency_key) returning * into row_out;
  insert into ops.execution_environment_provider_event(provider_id,from_state,to_state,evidence_refs,ruled_by_actor_id,idempotency_key)
  values(row_out.id,null,'discovered',jsonb_build_array('evidence:human-provider-registration'),actor_row.id,p_idempotency_key);
  return query select 'environment-provider:'||row_out.provider_key||':v'||row_out.provider_version,row_out.manifest_digest,'discovered',false;
end $_$;


--
-- Name: reject_fabricated_drill_row(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reject_fabricated_drill_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.source_ref in ('bin/key-recovery-test.sh','bin/restore-rehearse.sh')
     and (   new.detail like '%carr-20260101%'
          or new.detail like '%carr-20260201%'
          or new.detail like '%carr-20260301%'
          or new.detail like '%(999B%'
          or new.detail like '%(123456B%') then
    raise exception
      'ops.run refused a fabricated backup-drill row: detail names a dump or size only a selftest fixture produces (%). A selftest reached the production ledger — the checkout running it predates the PR #340 credential belts; rebase it onto main. See migration 0225.',
      left(new.detail, 120);
  end if;
  return new;
end $$;


--
-- Name: reject_stale_engineering_migration(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reject_stale_engineering_migration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if ops.engineering_contract_stale(null,null,new.filename) then
    raise exception using errcode='55000',
      message='stale engineering migration filename is permanently non-executable',
      detail=new.filename;
  end if;
  return new;
end $$;


--
-- Name: release_approval_requires_recovery_rehearsal(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_approval_requires_recovery_rehearsal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.environment='production' and new.state in ('ready','approved')
     and (tg_op='INSERT' or old.state is distinct from new.state)
     and ops.program5_exact_recovery_rehearsal(new.id) is null then
    raise exception 'Production release % has no exact typed recovery bundle',new.release_key;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION release_approval_requires_recovery_rehearsal(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.release_approval_requires_recovery_rehearsal() IS 'Program 5: Production approval requires a successful linked staging or rehearsal recovery receipt.';


--
-- Name: release_assurance_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_assurance_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.state in ('ready','approved','deploying','verifying','complete')
     and new.state<>'candidate'
     and new.plan_hash is not distinct from old.plan_hash
     and (new.performance_budget_ref,new.performance_budget_ms,
          new.recovery_strategy,new.rollback_ready,new.rollback_plan_ref,
          new.service_id,new.environment,new.git_sha,new.artifact_digest,
          new.dependency_lock_digest,new.config_fingerprint,
          new.schema_highest_migration,new.schema_applied_count,
          new.schema_ledger_sha256,new.migration_set) is distinct from
         (old.performance_budget_ref,old.performance_budget_ms,
          old.recovery_strategy,old.rollback_ready,old.rollback_plan_ref,
          old.service_id,old.environment,old.git_sha,old.artifact_digest,
          old.dependency_lock_digest,old.config_fingerprint,
          old.schema_highest_migration,old.schema_applied_count,
          old.schema_ledger_sha256,old.migration_set) then
    raise exception 'promoted release material is immutable';
  end if;
  return new;
end $$;


--
-- Name: FUNCTION release_assurance_is_immutable(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.release_assurance_is_immutable() IS 'Program 5: promoted release material is immutable until a changed plan hash invalidates approval and returns it to candidate.';


--
-- Name: release_canonical_ownership_lease(uuid, uuid, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_canonical_ownership_lease(p_lease_id uuid, p_lease_token uuid, p_fencing_generation bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare live jsonb; context jsonb; now_at timestamptz;
begin
  live:=ops.canonical_ownership_validate_live(p_lease_id,p_lease_token,p_fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  context:=ops.canonical_ownership_context(); now_at:=(live->>'evaluated_at')::timestamptz;
  update ops.canonical_ownership_lease set state='released',released_at=now_at,updated_at=now_at
   where id=p_lease_id and state='active' and lease_token=p_lease_token and fencing_generation=p_fencing_generation and expires_at>now_at;
  if not found then return ops.canonical_ownership_refusal('LEASE_EXPIRED','lease.expiry','"releasable live lease"'::jsonb,'"changed while releasing"'::jsonb); end if;
  insert into ops.canonical_ownership_lease_event
    (organization_tenant_id,lease_id,event_kind,fencing_generation,actor_id,
     session_ref,host_ref,cause,occurred_at,created_at)
  values(context->>'tenant',p_lease_id,'released',p_fencing_generation,(context->>'actor_id')::uuid,
    context->>'session_ref',context->>'host_ref',
    '{"reason":"holder_release"}',now_at,now_at);
  return jsonb_build_object('ok',true,'lease_id',p_lease_id,'fencing_generation',p_fencing_generation,'state','released');
end $$;


--
-- Name: release_completion_requires_a_read_back(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_completion_requires_a_read_back() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.state='complete' and (tg_op='INSERT' or old.state is distinct from 'complete') then
    if not exists(select 1 from ops.deployment d where d.release_id=new.id
      and d.service_id=new.service_id and d.environment='production'
      and d.state='complete' and d.read_back_at is not null
      and d.git_sha=new.git_sha and d.provider=new.provider
      and d.provider_version_id=new.provider_version_id) then
      raise exception 'release % has no exact Production read-back',new.release_key;
    end if;
    if not exists(select 1 from ops.run r join ops.deployment d
      on d.release_id=r.release_id and d.service_id=r.service_id
      and d.correlation_id=r.correlation_id where r.release_id=new.id
      and r.service_id=new.service_id and r.environment='production'
      and r.run_key like 'performance.%' and r.state='succeeded'
      and r.evidence_ref is not null and r.budget_ms=new.performance_budget_ms
      and r.duration_ms>0 and r.duration_ms<=r.budget_ms
      and d.environment='production' and d.state='complete'
      and d.read_back_at is not null and d.git_sha=new.git_sha
      and d.provider=new.provider and d.provider_version_id=new.provider_version_id) then
      raise exception 'release % has no within-budget Production performance receipt',new.release_key;
    end if;
    if ops.program5_exact_recovery_rehearsal(new.id,
      coalesce(new.ready_at,new.approved_at)-interval '24 hours') is null then
      raise exception 'release % has no fresh exact typed recovery bundle',new.release_key;
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION release_completion_requires_a_read_back(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.release_completion_requires_a_read_back() IS 'Program 5: completion requires an exact Production deployment read-back plus linked within-budget performance and recovery-plan-matched rehearsal receipts.';


--
-- Name: release_job_cost(uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_job_cost(p_reservation_id uuid, p_job_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; n integer;
begin
  select * into j from ops.job where id=p_job_id;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  update ops.cost_reservation set state='released',settled_at=now()
   where id=p_reservation_id and job_id=j.id and attempt=j.attempt and state='reserved';
  get diagnostics n=row_count;
  return n=1;
end $$;


--
-- Name: release_maker_session_provenance(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_maker_session_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_slug text;
begin
  if tg_op = 'INSERT' then
    -- THE ONE UNCONDITIONAL LINE, and the whole basis of the provenance: whatever
    -- the caller passed for this column is discarded and the session's own login
    -- role is recorded instead. SET ROLE does not move session_user, so a role
    -- that reached this table through a membership is still recorded under the
    -- name it authenticated as.
    new.maker_session_user := session_user;
    v_slug := ops.authority_login_slug(new.maker_session_user);

    if v_slug is not null then
      -- AN AUTHORITY SESSION FILED IT, so the maker and its derivation marker are
      -- written here from the recorded login and not from the caller's arguments.
      new.maker_actor := v_slug;
      new.maker_verification_ref := 'ops.authority-principal:' || v_slug;
    else
      if new.maker_verification_ref like 'ops.authority-principal:%' then
        raise exception using errcode = '42501',
          message = format('the authority-derivation marker is written by the '
                           'database from session_user, never by a caller; login '
                           '%L is not an admitted human authority principal',
                           new.maker_session_user);
      end if;
      -- ops.release.maker_actor is NOT NULL, 0169's
      -- an_approved_release_carries_its_evidence needs maker_verification_ref
      -- before a row may leave candidacy, and `release candidate` no longer
      -- asserts either. Where nobody claimed them, the filing login is the honest
      -- answer to both -- under a DIFFERENT marker prefix, so an unauthenticated
      -- row says plainly which credential filed it and can never be mistaken for
      -- an authority derivation by the store's `'ops.authority-principal:' ||
      -- maker_actor` predicate. Where somebody did claim them, both stand as the
      -- ordinary untrusted text they always were.
      if new.maker_actor is null then
        new.maker_actor := new.maker_session_user;
      end if;
      if new.maker_verification_ref is null then
        new.maker_verification_ref := 'ops.session-login:' || new.maker_session_user;
      end if;
    end if;
    return new;
  end if;

  -- UPDATE: the recorded filer is written once, at insert.
  if new.maker_session_user is distinct from old.maker_session_user then
    raise exception using errcode = '42501',
      message = 'maker_session_user records who filed this row and is immutable';
  end if;
  v_slug := ops.authority_login_slug(old.maker_session_user);
  if v_slug is null
     and new.maker_verification_ref is distinct from old.maker_verification_ref
     and new.maker_verification_ref like 'ops.authority-principal:%' then
    raise exception using errcode = '42501',
      message = 'the authority-derivation marker cannot be added to a row that '
                'was not filed on a human authority credential';
  end if;
  if v_slug is not null
     and (new.maker_actor is distinct from old.maker_actor
          or new.maker_verification_ref is distinct from old.maker_verification_ref) then
    raise exception using errcode = '42501',
      message = 'the derived maker provenance on an authority-filed release row '
                'is immutable';
  end if;
  return new;
end $$;


--
-- Name: FUNCTION release_maker_session_provenance(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.release_maker_session_provenance() IS 'Records the filing login role on ops.release from session_user and refuses a caller-typed authority-derivation marker. Named a_ so it fires before every other row trigger on this table.';


--
-- Name: release_plan_revision_invalidates_approval(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_plan_revision_invalidates_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.plan_hash is distinct from old.plan_hash
     and old.state in ('ready','approved','deploying','verifying') then
    new.state:='candidate';
    new.approved_by_actor:=null; new.approved_at:=null;
    new.approval_expires_at:=null; new.approval_receipt_id:=null;
    new.staging_approval_receipt_id:=null;
    new.readiness_receipt_id:=null; new.ready_at:=null;
  end if;
  new.updated_at:=now(); return new;
end $$;


--
-- Name: release_provider_identity_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_provider_identity_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.environment='production'
     and old.state in ('ready','approved','deploying','verifying','complete')
     and new.state<>'candidate'
     and (new.provider,new.provider_version_id) is distinct from
         (old.provider,old.provider_version_id) then
    raise exception 'Production provider identity is immutable after readiness';
  end if;
  return new;
end $$;


--
-- Name: release_readiness_append_only(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_readiness_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin raise exception 'release readiness evidence is append-only'; end $$;


--
-- Name: release_readiness_is_typed(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_readiness_is_typed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare receipt ops.release_readiness_receipt%rowtype;
begin
  if tg_op='UPDATE' and old.readiness_receipt_id is not null
     and new.state<>'candidate'
     and (new.readiness_receipt_id,new.ready_at) is distinct from
         (old.readiness_receipt_id,old.ready_at) then
    raise exception 'promoted release readiness is immutable';
  end if;
  if new.environment<>'production' or new.state not in
      ('ready','deploying','verifying','complete') or
      new.readiness_receipt_id is null then return new; end if;
  select * into receipt from ops.release_readiness_receipt
    where id=new.readiness_receipt_id;
  if not found or receipt.release_id is distinct from new.id
     or receipt.git_sha is distinct from new.git_sha
     or receipt.provider is distinct from new.provider
     or receipt.provider_version_id is distinct from new.provider_version_id
     or receipt.plan_hash is distinct from new.plan_hash
     or receipt.verifier_actor is distinct from new.verifier_actor
     or receipt.verifier_evidence_ref is distinct from new.verifier_evidence_ref
     or receipt.ready_at is distinct from new.ready_at
     or not exists (select 1 from ops.run r
       where r.id=receipt.recovery_run_id and r.release_id=new.id
         and r.state='succeeded' and r.evidence_ref is not null)
     or new.approved_by_actor is not null or new.approved_at is not null
     or new.approval_expires_at is not null then
    raise exception 'Production release readiness does not match exact typed evidence';
  end if;
  return new;
end $$;


--
-- Name: release_schema_declaration_matches_live(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_schema_declaration_matches_live() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare live_count integer; live_highest text; live_digest text;
begin
  if new.environment='production' and new.state in ('ready','approved') then
    select count(*)::integer,max(filename collate "C"),
      'sha256:'||encode(public.digest(coalesce(string_agg(
        convert_to(filename,'UTF8')||decode('00','hex')||
        convert_to(sha256,'UTF8')||decode('0a','hex'),
        ''::bytea order by filename collate "C"),''::bytea),'sha256'),'hex')
      into live_count,live_highest,live_digest from public.schema_migrations;
    if new.schema_applied_count is null
       or new.schema_highest_migration is distinct from live_highest
       or new.schema_applied_count<>live_count
       or new.schema_ledger_sha256 is distinct from live_digest then
      raise exception
        'Production release % schema declaration does not match live ops schema truth',
        new.release_key
        using detail = jsonb_build_object(
          'release_key',new.release_key,
          'declared_schema_highest_migration',new.schema_highest_migration,
          'declared_schema_applied_count',new.schema_applied_count,
          'declared_schema_ledger_sha256',new.schema_ledger_sha256,
          'live_schema_highest_migration',live_highest,
          'live_schema_applied_count',live_count,
          'live_schema_ledger_sha256',live_digest,
          'evidence_source','public.schema_migrations')::text;
    end if;
  end if;
  return new;
end $$;


--
-- Name: FUNCTION release_schema_declaration_matches_live(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.release_schema_declaration_matches_live() IS 'Production approval gate: declared highest migration, count, and locale-stable exact digest must equal live schema_migrations truth.';


--
-- Name: release_technical_readiness_current(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.release_technical_readiness_current(p_release_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select exists(
    select 1 from ops.release r
    join ops.release_readiness_receipt q on q.id=r.readiness_receipt_id
    where r.id=p_release_id and r.environment='production'
      and r.state in ('ready','deploying','verifying')
      and q.release_id=r.id and q.git_sha=r.git_sha
      and q.provider=r.provider and q.provider_version_id=r.provider_version_id
      and q.plan_hash=r.plan_hash
      and ops.program5_exact_recovery_rehearsal(r.id,now()-interval '24 hours') is not null)
$$;


--
-- Name: rename_doc_conversation(uuid, integer, text, boolean, boolean, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rename_doc_conversation(p_conversation uuid, p_base_version integer, p_title text, p_pinned boolean, p_archived boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_row ops.doc_conversation%rowtype; v_version integer;
begin
  v_actor := ops.portfolio_writer_actor_id();

  select * into v_row from ops.doc_conversation where id = p_conversation;
  if v_row.id is null
     or not (v_row.created_by_actor = v_actor
             or exists (select 1 from ops.doc_conversation_grant g
                         where g.conversation_id = v_row.id and g.grantee_actor = v_actor
                           and g.revoked_at is null)) then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_not_found');
  end if;
  -- BEFORE the version comparison and BEFORE any write.
  if v_row.created_by_actor <> v_actor then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_creator_only');
  end if;

  if p_title is null and p_pinned is null and p_archived is null then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_no_change_requested');
  end if;

  -- The PRIOR title, appended only when the title actually moves, and only
  -- under the same version predicate the update below carries.
  -- clock_timestamp() for the same primary-key reason as the grant (0520:43).
  insert into ops.doc_conversation_title_revision(conversation_id, title, at, by_actor)
  select id, title, clock_timestamp(), v_actor from ops.doc_conversation
   where id = p_conversation and version = p_base_version
     and p_title is not null and p_title is distinct from title;

  -- The compare-and-swap is a predicated update and NOT FOUND *is* the refusal.
  update ops.doc_conversation
     set title       = coalesce(p_title, title),
         pinned_at   = case when p_pinned   is null then pinned_at
                            when p_pinned   then coalesce(pinned_at, now()) else null end,
         archived_at = case when p_archived is null then archived_at
                            when p_archived then coalesce(archived_at, now()) else null end,
         version     = version + 1,
         updated_at  = now()
   where id = p_conversation and version = p_base_version
  returning version into v_version;
  if not found then
    return jsonb_build_object('ok', false, 'reason_id', 'version_conflict',
      'current_version', (select version from ops.doc_conversation where id = p_conversation));
  end if;

  select * into v_row from ops.doc_conversation where id = p_conversation;
  return jsonb_build_object('ok', true, 'id', p_conversation, 'version', v_version,
    'title', v_row.title, 'pinned', v_row.pinned_at is not null,
    'archived', v_row.archived_at is not null);
end $$;


--
-- Name: FUNCTION rename_doc_conversation(p_conversation uuid, p_base_version integer, p_title text, p_pinned boolean, p_archived boolean, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.rename_doc_conversation(p_conversation uuid, p_base_version integer, p_title text, p_pinned boolean, p_archived boolean, p_idempotency_key uuid) IS 'WR-000114: the only door that renames, pins, unpins, archives or unarchives a Doc conversation. Creator-only, raised inside this body before any version comparison and before any write; the prior title is appended under the same version predicate the compare-and-swap carries, so a refused rename leaves no orphan revision.';


--
-- Name: render_context_activation_for_brief(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.render_context_activation_for_brief(p_work_request text, p_binding_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text:=current_setting('carr.organization_tenant_id',true); item record; rendered jsonb:='[]'::jsonb; body text; actual_digest text;
begin
  if not exists (
    select 1
      from ops.context_activation_binding b
      join ops.work_request w on w.id=b.work_request_id
      join ops.sourced_work_request_plan p on p.id=b.plan_id
      join ops.sourced_work_request_plan_acceptance_receipt ar on ar.work_request_id=w.id and ar.plan_id=p.id
     where b.binding_id=p_binding_id and w.ref=p_work_request and b.organization_tenant_id=tenant
       and b.expires_at>=now() and w.version=b.work_request_version
       and p.work_request_id=w.id and p.plan_hash=b.plan_hash
       and ar.plan_hash=b.plan_hash and ar.result_version=w.version
  ) then raise exception 'context activation binding is expired, stale, or no longer the exact accepted plan'; end if;
  for item in select i.* from ops.context_activation_item i join ops.context_activation_binding b on b.id=i.binding_id join ops.work_request w on w.id=b.work_request_id where b.binding_id=p_binding_id and w.ref=p_work_request and b.organization_tenant_id=tenant order by i.ordinal loop
    body:=null; actual_digest:=null;
    if item.artifact_kind='doctrine' then
      select r.plain_text,'sha256:'||r.content_hash into body,actual_digest from public.doctrine_revision r where ('revision:'||r.id::text)=item.revision;
    elsif item.artifact_kind='rule' then
      select r.statement,'sha256:'||encode(public.digest(r.statement,'sha256'),'hex') into body,actual_digest from public.rule r where ('rule:'||r.id::text)=item.canonical_ref;
    elsif item.artifact_kind='decision' then
      select jsonb_build_object('title',d.title,'human_quote',d.human_quote,'agent_rationale',d.agent_rationale,'provenance',d.provenance,'entry_date',d.entry_date)::text,
        'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object('title',d.title,'human_quote',d.human_quote,'agent_rationale',d.agent_rationale,'provenance',d.provenance,'entry_date',d.entry_date)),'sha256'),'hex')
        into body,actual_digest from public.v_decision_entry d where ('decision:'||d.decision_id::text)=item.canonical_ref and ('revision:'||d.event_id::text)=item.revision;
    elsif item.artifact_kind='memory' then
      select m.statement,'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object('id',m.id,'version',m.version,'kind',m.kind,'statement',m.statement,'context',m.context,'scope',m.scope,'organization_tenant_id',m.organization_tenant_id,'work_request_id',m.work_request_id,'work_request_version',m.work_request_version,'plan_id',m.plan_id,'status',m.status,'confidence',m.confidence)),'sha256'),'hex') into body,actual_digest
        from public.memory_item m where ('memory:'||m.id::text)=item.canonical_ref and ('revision:'||m.id::text||':v'||m.version::text)=item.revision;
    elsif item.artifact_kind='prior_failure' then
      select '[redacted prior-failure metadata]','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object('id',d.id,'occurred_on',d.occurred_on,'defect_class',d.defect_class,'claimed',d.claimed,'actual',d.actual,'source_unread',d.source_unread,'rule_violated',d.rule_violated,'detected_by',d.detected_by,'session_key',d.session_key,'cost_note',d.cost_note,'created_at',d.created_at,'created_by',d.created_by)),'sha256'),'hex') into body,actual_digest
        from public.defect d where ('defect:'||d.id::text)=item.canonical_ref and ('occurred:'||d.occurred_on::text)=item.revision;
    end if;
    if item.freshness->>'state' <> 'fresh' or body is null or actual_digest is distinct from item.content_digest then
      if item.required then raise exception 'required frozen context revision cannot render or is stale'; end if;
      rendered:=rendered||jsonb_build_array(jsonb_build_object('canonical_ref',item.canonical_ref,'delivery_mode','reference_only','state','unavailable'));
    elsif item.delivery_mode='reference_only' then
      rendered:=rendered||jsonb_build_array(jsonb_build_object('canonical_ref',item.canonical_ref,'revision',item.revision,'content_digest',item.content_digest,'delivery_mode','reference_only','state','reference_only'));
    else
      rendered:=rendered||jsonb_build_array(jsonb_build_object('canonical_ref',item.canonical_ref,'revision',item.revision,'content_digest',item.content_digest,'delivery_mode',item.delivery_mode,'state','rendered','content',body));
    end if;
  end loop;
  return rendered;
end $$;


--
-- Name: renew_canonical_ownership_lease(uuid, uuid, bigint, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.renew_canonical_ownership_lease(p_lease_id uuid, p_lease_token uuid, p_fencing_generation bigint, p_ttl_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare live jsonb; context jsonb:=ops.canonical_ownership_context(); now_at timestamptz; new_expiry timestamptz;
begin
  if not coalesce((context->>'ok')::boolean,false) then return context; end if;
  if p_ttl_seconds is null or p_ttl_seconds<30 or p_ttl_seconds>1800 then return ops.canonical_ownership_refusal('INPUT_INVALID','lease.ttl','"30..1800 seconds"'::jsonb,to_jsonb(p_ttl_seconds)); end if;
  live:=ops.canonical_ownership_validate_live(p_lease_id,p_lease_token,p_fencing_generation,true);
  if not coalesce((live->>'ok')::boolean,false) then return live; end if;
  now_at:=(live->>'evaluated_at')::timestamptz; new_expiry:=now_at+make_interval(secs=>p_ttl_seconds);
  update ops.canonical_ownership_lease set renewed_at=now_at,expires_at=new_expiry,updated_at=now_at
   where id=p_lease_id and state='active' and lease_token=p_lease_token and fencing_generation=p_fencing_generation and expires_at>now_at;
  if not found then return ops.canonical_ownership_refusal('LEASE_EXPIRED','lease.expiry','"renewable live lease"'::jsonb,'"changed while renewing"'::jsonb); end if;
  insert into ops.canonical_ownership_lease_event
    (organization_tenant_id,lease_id,event_kind,fencing_generation,actor_id,
     session_ref,host_ref,cause,occurred_at,created_at)
  values(context->>'tenant',p_lease_id,'renewed',p_fencing_generation,(context->>'actor_id')::uuid,
    context->>'session_ref',context->>'host_ref',
    jsonb_build_object('expires_at',new_expiry),now_at,now_at);
  return jsonb_build_object('ok',true,'lease_id',p_lease_id,'fencing_generation',p_fencing_generation,'expires_at',new_expiry);
end $$;


--
-- Name: candidate_pool; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.candidate_pool (
    id uuid DEFAULT gen_random_uuid() CONSTRAINT prospect_pool_id_not_null NOT NULL,
    source text CONSTRAINT prospect_pool_source_not_null NOT NULL,
    source_key text CONSTRAINT prospect_pool_source_key_not_null NOT NULL,
    source_seq integer,
    source_row jsonb CONSTRAINT prospect_pool_source_row_not_null NOT NULL,
    name text CONSTRAINT prospect_pool_name_not_null NOT NULL,
    org_name text,
    vertical text,
    address text,
    city text,
    county text,
    state text,
    email text,
    phone text,
    segment text,
    segment_play text,
    score numeric(5,2),
    score_basis text,
    est_lease_event date,
    est_basis text,
    status text DEFAULT 'pool'::text CONSTRAINT prospect_pool_status_not_null NOT NULL,
    promoted_lead_id uuid,
    dup_tier text,
    dup_subject_type text,
    dup_subject_id uuid,
    dup_ref text,
    dup_basis text,
    dup_do_not_contact boolean DEFAULT false CONSTRAINT prospect_pool_dup_do_not_contact_not_null NOT NULL,
    version integer DEFAULT 1 CONSTRAINT prospect_pool_version_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() CONSTRAINT prospect_pool_created_at_not_null NOT NULL,
    created_by uuid CONSTRAINT prospect_pool_created_by_not_null NOT NULL,
    updated_at timestamp with time zone DEFAULT now() CONSTRAINT prospect_pool_updated_at_not_null NOT NULL,
    updated_by uuid CONSTRAINT prospect_pool_updated_by_not_null NOT NULL,
    declined_at timestamp with time zone,
    declined_by uuid,
    decline_reason text,
    CONSTRAINT candidate_pool_declined_has_reason CHECK (((status = 'declined'::text) = ((decline_reason IS NOT NULL) AND (decline_reason <> ''::text)))),
    CONSTRAINT candidate_pool_declined_has_stamp CHECK (((status = 'declined'::text) = (declined_at IS NOT NULL))),
    CONSTRAINT candidate_pool_status_check CHECK ((status = ANY (ARRAY['pool'::text, 'promoted'::text, 'suppressed_dup'::text, 'declined'::text]))),
    CONSTRAINT pool_dup_tier_pairs_with_pointer CHECK (((dup_tier IS NULL) = (dup_subject_type IS NULL))),
    CONSTRAINT pool_promoted_has_lead CHECK (((status = 'promoted'::text) = (promoted_lead_id IS NOT NULL))),
    CONSTRAINT pool_suppressed_iff_tier_suppressed CHECK (((status = 'suppressed_dup'::text) = (COALESCE(dup_tier, ''::text) = 'suppressed'::text))),
    CONSTRAINT prospect_pool_dup_subject_type_check CHECK ((dup_subject_type = ANY (ARRAY['lead'::text, 'client'::text]))),
    CONSTRAINT prospect_pool_dup_tier_check CHECK ((dup_tier = ANY (ARRAY['suppressed'::text, 'review'::text])))
);


--
-- Name: TABLE candidate_pool; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.candidate_pool IS 'The candidate reservoir: raw, unjudged rows from licence sweeps and radar lanes. 9,860 at rename. Deliberately carries NO party_id — a candidate has no identity until promote-pool mints one, which is why 9,860 rows cost nothing and why merging never has to consider them. Qualifying context lives here as STRUCTURED columns (source_row 100%, score_basis 100%, segment_play 87%) rather than as a dossier: candidate context is uniform because it came from a list, and narrative context begins at promotion, when a human starts working an individual. Renamed from prospect_pool in 0048 to free the word "prospect" for the funnel stage after lead.';


--
-- Name: COLUMN candidate_pool.score; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_pool.score IS 'PRESENTED, never filtering. Nothing may use this to decide whether a row lands.';


--
-- Name: COLUMN candidate_pool.dup_do_not_contact; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_pool.dup_do_not_contact IS 'The renewal-radar suppressor DROPS a do-not-contact match. The pool keeps the row and raises this flag instead — never deleted, never re-presented.';


--
-- Name: COLUMN candidate_pool.decline_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.candidate_pool.decline_reason IS 'WHY a human said no, in his own words. Required when status is declined. This is the input to the lane-retirement decision: a lane whose declines are all "no contact channel" has a fixable defect, a lane whose declines are all "out of territory" is mis-scoped, and a lane whose declines are all "not a fit" is working correctly and simply has a low hit rate. Without it every lane looks identical from the outside.';


--
-- Name: renewal_decision_candidate_digest(public.candidate_pool); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.renewal_decision_candidate_digest(p_candidate public.candidate_pool) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select encode(digest(convert_to((to_jsonb(p_candidate) - array['updated_at','updated_by'])::text,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: reopen_program5_release_rehearsal(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reopen_program5_release_rehearsal(p_release_key text, p_plan_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare rel ops.release%rowtype;
begin
  if session_user<>'carr_jobs' then
    raise exception 'recovery rehearsal reopen requires the authenticated jobs service';
  end if;
  select * into rel from ops.release where release_key=p_release_key for update;
  if not found or rel.environment is distinct from 'production'
     or rel.plan_hash is distinct from p_plan_hash
     or rel.readiness_receipt_id is null
     or not exists (select 1 from ops.release_readiness_receipt q
       where q.id=rel.readiness_receipt_id and q.release_id=rel.id
         and q.git_sha=rel.git_sha and q.provider=rel.provider
         and q.provider_version_id=rel.provider_version_id
         and q.plan_hash=rel.plan_hash) then
    raise exception 'release has no exact service readiness to rehearse';
  end if;
  if rel.state='candidate' then
    return jsonb_build_object('release_id',rel.id,'replayed',true);
  end if;
  if rel.state<>'ready' or ops.release_technical_readiness_current(rel.id) then
    raise exception 'only a stale ready release may reopen rehearsal';
  end if;
  update ops.release set state='candidate' where id=rel.id;
  return jsonb_build_object('release_id',rel.id,'replayed',false);
end $$;


--
-- Name: calendar_prebrief_allowlist_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.calendar_prebrief_allowlist_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sponsor text NOT NULL,
    calendar_keys text[] NOT NULL,
    configuration_digest text CONSTRAINT calendar_prebrief_allowlist_recei_configuration_digest_not_null NOT NULL,
    configured_at timestamp with time zone DEFAULT now() NOT NULL,
    configured_by text NOT NULL,
    CONSTRAINT calendar_prebrief_allowlist_receipt_calendar_keys_check CHECK ((cardinality(calendar_keys) > 0)),
    CONSTRAINT calendar_prebrief_allowlist_receipt_configuration_digest_check CHECK ((configuration_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT calendar_prebrief_allowlist_receipt_configured_by_check CHECK ((configured_by = ANY (ARRAY['joe'::text, 'dell'::text]))),
    CONSTRAINT calendar_prebrief_allowlist_receipt_sponsor_check CHECK ((sponsor = ANY (ARRAY['joe'::text, 'dell'::text])))
);


--
-- Name: replace_calendar_prebrief_allowlist(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.replace_calendar_prebrief_allowlist(p_calendar_keys text[]) RETURNS ops.calendar_prebrief_allowlist_receipt
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_sponsor text;
  v_keys text[];
  v_configuration_digest text;
  v_receipt ops.calendar_prebrief_allowlist_receipt%rowtype;
begin
  v_sponsor := ops.authority_actor_slug();
  select array_agg(k order by k) into v_keys from unnest(coalesce(p_calendar_keys,'{}'::text[])) keys(k);
  if coalesce(cardinality(v_keys),0)=0
     or array_position(v_keys,null) is not null
     or exists (select 1 from unnest(v_keys) keys(k) where k !~ '^[0-9a-f]{64}$')
     or cardinality(v_keys) <> (select count(distinct k) from unnest(v_keys) keys(k)) then
    raise exception using errcode='22023',message='calendar prebrief allowlist requires nonempty distinct opaque 64-hex calendar keys';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('calendar-prebrief-allowlist:' || v_sponsor,0));
  v_configuration_digest:=encode(digest(convert_to(jsonb_build_object(
      'sponsor',v_sponsor,'calendar_keys',to_jsonb(v_keys))::text,'UTF8'),'sha256'),'hex');
  insert into ops.calendar_prebrief_allowlist_receipt
    (sponsor,calendar_keys,configuration_digest,configured_by)
  values(v_sponsor,v_keys,v_configuration_digest,v_sponsor)
  returning * into v_receipt;
  insert into ops.calendar_prebrief_allowed_calendar(sponsor,calendar_keys,configuration_digest,active_revision_id,configured_at,configured_by)
  values(v_sponsor,v_keys,v_configuration_digest,v_receipt.id,now(),v_sponsor)
  on conflict(sponsor) do update set calendar_keys=excluded.calendar_keys,
    configuration_digest=excluded.configuration_digest,active_revision_id=excluded.active_revision_id,
    configured_at=excluded.configured_at,configured_by=excluded.configured_by;
  return v_receipt;
end $_$;


--
-- Name: request_tour_pdf_render(text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.request_tour_pdf_render(p_tenant text, p_actor_id text, p_request jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_projection ops.tour_public_projection%rowtype;
begin
  if jsonb_typeof(p_request)<>'object' or nullif(btrim(p_actor_id),'') is null then raise exception 'tour PDF request is invalid'; end if;
  select * into v_projection from ops.tour_public_projection where organization_tenant_id=p_tenant and id=(p_request->>'projection_id')::uuid and status='approved' for share;
  if not found or v_projection.projection_digest<>(p_request->>'projection_digest') or not exists(select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=p_tenant and s.projection_id=v_projection.id and s.canonical_projection_digest=v_projection.projection_digest) then raise exception 'tour PDF requires a sealed projection'; end if;
  if (p_request->>'expected_property_count')::integer<>(select count(*) from ops.tour_property_membership m where m.organization_tenant_id=p_tenant and m.tour_id=v_projection.tour_id and m.route_version=v_projection.route_version) then raise exception 'tour PDF property count mismatch'; end if;
  insert into ops.tour_pdf_render_job(organization_tenant_id,projection_id,requested_by_actor_id,request,projection_digest,packet_digest,template_digest,renderer_digest,qc_ruleset_digest,expected_property_count)
  values(p_tenant,v_projection.id,p_actor_id,p_request,p_request->>'projection_digest',p_request->>'packet_digest',p_request->>'template_digest',p_request->>'renderer_digest',p_request->>'qc_ruleset_digest',(p_request->>'expected_property_count')::integer) returning id into v_id;
  return v_id;
end $$;


--
-- Name: require_cutover_evidence(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.require_cutover_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare modes integer;
begin
  if old.legacy_disabled_at is null and new.legacy_disabled_at is not null then
    select count(distinct mode) into modes from ops.workflow_acceptance
     where workflow_key=new.key and workflow_version=new.version
       and status='accepted' and mode in ('shadow','canary');
    if modes <> 2 then
      raise exception 'workflow % v% cannot disable legacy schedule: accepted shadow and canary receipts are required',new.key,new.version;
    end if;
  end if;
  return new;
end $$;


--
-- Name: require_rule_admission(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.require_rule_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  a ops.rule_admission%rowtype;
  v_approval ops.rule_approval_receipt%rowtype;
begin
  if tg_op='UPDATE' and old.status='retired' then
    raise exception 'retired rule % is immutable',old.id;
  end if;
  -- Once the approval receipt exists, the entire rule row is immutable except
  -- for the three exact authority transitions owned below: proposed -> active
  -- in ops.approve_rule, proposed/active -> retired in ops.retire_rule, and
  -- (new, 0349) active -> active with ONLY the statement changed, in
  -- ops.amend_rule_statement. This also blocks no-op UPDATEs that would
  -- otherwise bump the optimistic version and silently make an active receipt
  -- stale through trg_touch_row.
  if tg_op='UPDATE'
     and exists (select 1 from ops.rule_approval_receipt where rule_id=old.id) then
    if old.status='proposed' and new.status='active'
       and new.id is not distinct from old.id
       and new.statement is not distinct from old.statement
       and new.human_quote is not distinct from old.human_quote
       and new.taught_by is not distinct from old.taught_by
       and new.scope is not distinct from old.scope
       and new.personal_to is not distinct from old.personal_to
       and new.supersedes is not distinct from old.supersedes
       and new.created_at is not distinct from old.created_at
       and new.version is not distinct from old.version
       and new.updated_at is not distinct from old.updated_at
       and new.retired_by is not distinct from old.retired_by
       and new.retired_at is not distinct from old.retired_at then
      null; -- exact activation fields are validated below
    elsif old.status in ('proposed','active') and new.status='retired'
       and new.id is not distinct from old.id
       and new.statement is not distinct from old.statement
       and new.human_quote is not distinct from old.human_quote
       and new.taught_by is not distinct from old.taught_by
       and new.scope is not distinct from old.scope
       and new.personal_to is not distinct from old.personal_to
       and new.activated_by is not distinct from old.activated_by
       and new.activated_at is not distinct from old.activated_at
       and new.enforcement is not distinct from old.enforcement
       and new.supersedes is not distinct from old.supersedes
       and new.created_at is not distinct from old.created_at
       and new.version is not distinct from old.version
       and new.updated_at is not distinct from old.updated_at then
      null; -- exact retirement actor/receipt is validated below
    elsif old.status='active' and new.status='active'
       and new.id is not distinct from old.id
       and new.statement is distinct from old.statement
       and new.human_quote is not distinct from old.human_quote
       and new.taught_by is not distinct from old.taught_by
       and new.scope is not distinct from old.scope
       and new.personal_to is not distinct from old.personal_to
       and new.activated_by is not distinct from old.activated_by
       and new.activated_at is not distinct from old.activated_at
       and new.enforcement is not distinct from old.enforcement
       and new.supersedes is not distinct from old.supersedes
       and new.created_at is not distinct from old.created_at
       and new.version is not distinct from old.version
       and new.updated_at is not distinct from old.updated_at
       and new.retired_by is not distinct from old.retired_by
       and new.retired_at is not distinct from old.retired_at
       and exists (
         select 1 from ops.rule_amendment_receipt ar
          where ar.rule_id=old.id
            and ar.rule_version_before=old.version
            and ar.prior_statement_hash=encode(digest(old.statement,'sha256'),'hex')
            and ar.new_statement=new.statement
       ) then
      null; -- exact amendment receipt is validated below
    else
      raise exception 'approved rule % is immutable except through exact Joe approval, retirement or amendment',new.id;
    end if;
  end if;
  if tg_op='UPDATE' and old.status is distinct from 'retired' and new.status='retired' then
    if new.retired_by is null or new.retired_at is null or not exists (
      select 1 from ops.rule_retirement_receipt rr
       where rr.rule_id=old.id and rr.actor_id=new.retired_by
         and rr.rule_version_before=old.version
         and rr.statement_hash=encode(digest(old.statement,'sha256'),'hex')
         and rr.previous_status=old.status
    ) then
      raise exception 'rule % cannot retire without an exact Joe authority receipt',new.id;
    end if;
  end if;
  if not (new.status='active' and
          (tg_op='INSERT' or old.status is distinct from 'active')) then
    return new;
  end if;
  if new.activated_by is null then
    raise exception 'rule % cannot activate without a human activator',new.id;
  end if;
  select * into a from ops.rule_admission where rule_id=new.id;
  if not found or a.state<>'admitted' then
    raise exception 'rule % cannot activate: admitted rule contract is missing',new.id;
  end if;
  if a.enforcement_status not in ('hard_enforced','authority_enforced') then
    raise exception 'rule % cannot activate: active requires installed enforcement, got %',
      new.id,a.enforcement_status;
  end if;
  select * into v_approval from ops.rule_approval_receipt
   where rule_id=new.id and actor_id=new.activated_by
     and enforcement_status=a.enforcement_status
     and statement_hash=encode(digest(new.statement,'sha256'),'hex')
   order by created_at desc limit 1;
  if not found then
    raise exception 'rule % cannot activate: immutable enforced approval receipt is missing',new.id;
  end if;
  if new.enforcement is distinct from
       (case when v_approval.enforcement_status='hard_enforced' then 'gate' else 'constraint' end) then
    raise exception 'rule % cannot activate: enforcement label does not match approval',new.id;
  end if;
  if exists (
    select 1 from unnest(v_approval.requested_control_keys) as requested(control_key)
     where not exists (
       select 1
         from ops.rule_enforcement_point ep
         join ops.enforcement_control_catalog c using (control_key)
         join ops.rule_control_binding b
           on b.rule_id=ep.rule_id and b.control_key=ep.control_key
        where ep.rule_id=new.id and ep.control_key=requested.control_key
          and ep.installed and c.installed and c.verified_at is not null
          and b.statement_hash=encode(digest(new.statement,'sha256'),'hex')
          and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')
     )
  ) then
    raise exception 'rule % cannot activate: exact requested enforcement is incomplete',new.id;
  end if;
  return new;
end $$;


--
-- Name: require_rule_approval_lifecycle_anchor(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.require_rule_approval_lifecycle_anchor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
begin
  -- An anchor is not an override and has no caller-supplied trust boundary.
  -- It can only certify the exact old-0194 pre-activation receipt against the
  -- current active rule, Joe authority, admitted contract and installed gates.
  if not exists (
    select 1
      from ops.rule_approval_receipt ar
      join rule r on r.id=ar.rule_id and r.status='active'
      join actor joe on joe.id=ar.actor_id
       and joe.slug='joe' and joe.kind='human' and joe.active
      join ops.rule_admission a on a.rule_id=r.id
     where ar.id=new.approval_receipt_id
       and ar.rule_id=new.rule_id
       and ar.rule_version+1=new.rule_version_after
       and new.rule_version_after=r.version
       and new.statement_hash=ar.statement_hash
       and ar.statement_hash=encode(digest(r.statement,'sha256'),'hex')
       and r.activated_by=ar.actor_id
       and r.enforcement=(case when ar.enforcement_status='hard_enforced'
                               then 'gate' else 'constraint' end)
       and a.state='admitted' and a.admitted_by=ar.actor_id
       and ar.policy_kind=a.enforcement_class
       and ar.enforcement_status=a.enforcement_status
       and ar.normalized_contract->>'binding_moment'=a.binding_moment
       and ar.normalized_contract->'applicability'=a.applicability
       and ar.normalized_contract->'projection'=a.projection
       and ar.normalized_contract->'reachability'=a.reachability
       and ar.normalized_contract->'input_contract'=a.input_contract
       and ar.evidence_refs=a.fixture_refs
       and exists (
         select 1 from ops.authority_receipt auth
          where auth.idempotency_key='approval:'||ar.idempotency_key
            and auth.kind='activation' and auth.subject_type='rule'
            and auth.subject_id=r.id and auth.actor_id=ar.actor_id
            and auth.contract_hash=ar.contract_hash)
       and not exists (
         select 1 from unnest(ar.requested_control_keys) requested(control_key)
          where not exists (
            select 1 from ops.rule_enforcement_point ep
            join ops.enforcement_control_catalog c using (control_key)
            join ops.rule_control_binding b
              on b.rule_id=ep.rule_id and b.control_key=ep.control_key
             where ep.rule_id=r.id and ep.control_key=requested.control_key
               and ep.installed and c.installed and c.verified_at is not null
               and b.statement_hash=ar.statement_hash
               and c.enforcement_class in ('deny_gate','stop_gate','schema','transactional_schema')))
  ) then
    raise exception 'legacy approval anchor requires an exact active Joe-approved 0194 receipt chain';
  end if;
  return new;
end $$;


--
-- Name: reserve_job_cost(uuid, uuid, text, numeric); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.reserve_job_cost(p_job_id uuid, p_lease_token uuid, p_route_key text, p_estimated_cost_usd numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; route ops.provider_route%rowtype; spent numeric; reserved numeric; rid uuid;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select * into route from ops.provider_route where route_key=p_route_key and enabled;
  if not found then raise exception 'provider route % is not enabled',p_route_key; end if;
  if p_estimated_cost_usd<0 then raise exception 'estimated cost must be non-negative'; end if;
  select coalesce(sum(a.cost_usd),0) into spent from ops.job_attempt a
   where a.provider_route=p_route_key and a.started_at>=date_trunc('month',now());
  select coalesce(sum(r.estimated_cost_usd),0) into reserved from ops.cost_reservation r
   where r.route_key=p_route_key and r.state='reserved'
     and r.created_at>=date_trunc('month',now());
  if route.monthly_budget_usd is not null
     and spent+reserved+p_estimated_cost_usd>route.monthly_budget_usd then
    raise exception 'provider route % monthly budget would be exceeded',p_route_key;
  end if;
  insert into ops.cost_reservation(job_id,attempt,route_key,estimated_cost_usd)
    values(j.id,j.attempt,p_route_key,p_estimated_cost_usd)
  returning id into rid;
  return rid;
end $$;


--
-- Name: resolve_calendar_canary_receipt(uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.resolve_calendar_canary_receipt(p_job_id uuid, p_attempt integer) RETURNS SETOF ops.calendar_canary_receipt
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$select * from ops.calendar_canary_receipt where job_id=p_job_id and attempt=p_attempt$$;


--
-- Name: resolve_calendar_prebrief_email_ref(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.resolve_calendar_prebrief_email_ref(p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare v_count integer; v_ref text;
begin
  perform ops.calendar_prebrief_resolver_sponsor();
  if p_email is null or length(p_email)>320
     or lower(btrim(p_email)) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='42501',message='calendar prebrief email resolver requires one bounded exact email';
  end if;
  select count(distinct r.ref),min(r.ref) into v_count,v_ref
    from party p join v_ref_index r on r.party_id=p.id and not r.merged
   where lower(btrim(p.email))=lower(btrim(p_email));
  if v_count<>1 then
    raise exception using errcode='22023',message='calendar prebrief email resolver requires exactly one live unmerged canonical ref';
  end if;
  return v_ref;
end $_$;


