 select * from ops.nightly_availability_canary_receipt where job_id=p_job_id and attempt=p_attempt
$$;


--
-- Name: resolve_tour_public_asset(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.resolve_tour_public_asset(p_session_digest text, p_asset_ref text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  with g as (select (ops.tour_share_session_grant(p_session_digest,'view_packet')).*)
  select jsonb_strip_nulls(jsonb_build_object('media_type',a.media_type,'content_length',a.content_length,'alt',a.alt,'caption',a.caption))
  from g join ops.tour_public_asset a on a.organization_tenant_id=g.organization_tenant_id and a.projection_id=g.projection_id and a.asset_ref=p_asset_ref;
$$;


--
-- Name: restore_tour_cheat_sheet_revision(text, uuid, uuid, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.restore_tour_cheat_sheet_revision(p_tenant text, p_tour_id uuid, p_restore_revision_id uuid, p_expected_revision_number integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_source ops.tour_cheat_sheet_revision%rowtype; v_prior ops.tour_cheat_sheet_revision%rowtype; v_id uuid; v_actor text;
begin
  v_actor:=ops.tour_server_actor_id(); perform pg_advisory_xact_lock(hashtextextended(p_tenant || ':' || p_tour_id::text || ':cheat-sheet',386));
  select * into v_source from ops.tour_cheat_sheet_revision where id=p_restore_revision_id and organization_tenant_id=p_tenant and tour_id=p_tour_id;
  select * into v_prior from ops.tour_cheat_sheet_revision where organization_tenant_id=p_tenant and tour_id=p_tour_id order by revision_number desc,id desc limit 1 for update;
  if v_source.id is null or p_expected_revision_number<>coalesce(v_prior.revision_number,0) then raise exception 'cheat sheet restore refuses unavailable or stale revision'; end if;
  -- Restore creates a new cheat sheet revision; it never rewrites the source.
  insert into ops.tour_cheat_sheet_revision(organization_tenant_id,tour_id,revision_number,content,editor_actor_id,status,revision_kind,parent_revision_id,restored_from_revision_id,content_digest) values(p_tenant,p_tour_id,v_prior.revision_number+1,v_source.content,v_actor,'draft','restore',v_prior.id,v_source.id,'sha256:'||encode(public.digest(v_source.content::text,'sha256'),'hex')) returning id into v_id; return v_id;
end $$;


--
-- Name: retire_rule(uuid, text, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.retire_rule(p_rule_id uuid, p_reason text, p_superseded_by uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_actor_slug text;
  v_actor_id uuid;
  v_rule rule%rowtype;
  v_prior ops.rule_retirement_receipt%rowtype;
  v_receipt ops.rule_retirement_receipt%rowtype;
  v_approval_id uuid;
  v_legacy_note text;
  v_contract jsonb;
  v_contract_hash text;
  v_retired_at timestamptz;
begin
  v_actor_slug := ops.authority_actor_slug();
  if v_actor_slug<>'joe' then
    raise exception 'system rule retirement requires Joe authority';
  end if;
  select id into v_actor_id from actor
   where slug=v_actor_slug and kind='human' and active;
  if v_actor_id is null then raise exception 'Joe authority actor is not active'; end if;
  if btrim(coalesce(p_reason,''))='' or btrim(coalesce(p_idempotency_key,''))='' then
    raise exception 'retirement reason and idempotency key are required';
  end if;
  if p_superseded_by is not null and p_superseded_by=p_rule_id then
    raise exception 'a rule cannot supersede itself';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('rule-retirement:'||p_idempotency_key,0));
  select * into v_prior from ops.rule_retirement_receipt
   where idempotency_key=p_idempotency_key;
  if found then
    if v_prior.rule_id is distinct from p_rule_id
       or v_prior.reason is distinct from btrim(p_reason)
       or v_prior.superseded_by is distinct from p_superseded_by
       or v_prior.actor_id is distinct from v_actor_id then
      raise exception 'rule retirement idempotency key was reused with different input';
    end if;
    select * into v_rule from rule where id=p_rule_id for update;
    if not found
       or v_rule.status is distinct from 'retired'
       or v_rule.version is distinct from v_prior.rule_version_after
       or encode(digest(v_rule.statement,'sha256'),'hex') is distinct from v_prior.statement_hash
       or v_rule.retired_by is distinct from v_prior.actor_id
       or v_rule.retired_at is distinct from v_prior.retired_at then
      raise exception 'rule retirement replay refused: current retired rule no longer matches the immutable retirement';
    end if;
    return jsonb_build_object('ok',true,'replayed',true,'rule_id',p_rule_id,
      'previous_status',v_prior.previous_status,'status','retired',
      'retirement_receipt_id',v_prior.id,'legacy_admission',v_prior.legacy_admission);
  end if;

  select * into v_rule from rule where id=p_rule_id for update;
  if not found then raise exception 'rule % not found',p_rule_id; end if;
  if v_rule.status not in ('proposed','active') then
    raise exception 'rule % is %, expected proposed or active',p_rule_id,v_rule.status;
  end if;
  if p_superseded_by is not null and not exists (select 1 from rule where id=p_superseded_by) then
    raise exception 'superseding rule % does not exist',p_superseded_by;
  end if;
  if v_rule.status='active' then
    select id into v_approval_id from ops.rule_approval_receipt
     where rule_id=v_rule.id
       and (rule_version=v_rule.version or exists (
         select 1 from ops.rule_approval_lifecycle_anchor legacy
          where legacy.approval_receipt_id=ops.rule_approval_receipt.id
            and legacy.rule_id=v_rule.id and legacy.rule_version_after=v_rule.version
            and legacy.statement_hash=ops.rule_approval_receipt.statement_hash))
       and statement_hash=encode(digest(v_rule.statement,'sha256'),'hex')
     order by created_at desc limit 1;
    if v_approval_id is null then
      -- (0351) Not every receiptless active rule is a defect: 217 of 219
      -- were activated before the receipt system existed at all. Fall
      -- through to the shared legacy predicate before refusing outright.
      v_legacy_note := ops.legacy_rule_admission_note(v_rule.id,v_rule.status,v_rule.activated_at);
      if v_legacy_note is null then
        raise exception 'active rule % lacks its exact approval receipt',v_rule.id;
      end if;
    end if;
  end if;

  v_retired_at := now();

  v_contract := jsonb_build_object(
    'rule_id',v_rule.id,'rule_version_before',v_rule.version,
    'rule_version_after',v_rule.version+1,
    'statement_hash',encode(digest(v_rule.statement,'sha256'),'hex'),
    'previous_status',v_rule.status,'actor_id',v_actor_id,
    'reason',btrim(p_reason),'superseded_by',p_superseded_by,
    'approval_receipt_id',v_approval_id,'legacy_admission',v_legacy_note,'retired_at',v_retired_at);
  v_contract_hash := encode(digest(v_contract::text,'sha256'),'hex');
  insert into ops.rule_retirement_receipt
    (idempotency_key,rule_id,rule_version_before,rule_version_after,statement_hash,previous_status,
     actor_id,reason,superseded_by,approval_receipt_id,legacy_admission,contract_hash,retired_at)
  values (p_idempotency_key,v_rule.id,v_rule.version,v_rule.version+1,
          encode(digest(v_rule.statement,'sha256'),'hex'),v_rule.status,
          v_actor_id,btrim(p_reason),p_superseded_by,v_approval_id,v_legacy_note,v_contract_hash,v_retired_at)
  returning * into v_receipt;
  insert into ops.authority_receipt
    (idempotency_key,kind,subject_type,subject_id,actor_id,decision,contract_hash,evidence_refs)
  values ('retirement:'||p_idempotency_key,'override','rule',v_rule.id,v_actor_id,
          'retired by Joe authority: '||btrim(p_reason),v_contract_hash,
          case when v_approval_id is null then '{}'::text[]
               else array[v_approval_id::text] end);
  update rule set status='retired',retired_by=v_actor_id,retired_at=v_retired_at
   where id=v_rule.id and status=v_rule.status;
  if not found then raise exception 'rule % retirement raced',v_rule.id; end if;
  return jsonb_build_object('ok',true,'replayed',false,'rule_id',v_rule.id,
    'previous_status',v_rule.status,'status','retired',
    'retirement_receipt_id',v_receipt.id,'legacy_admission',v_receipt.legacy_admission);
end $$;


--
-- Name: FUNCTION retire_rule(p_rule_id uuid, p_reason text, p_superseded_by uuid, p_idempotency_key text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.retire_rule(p_rule_id uuid, p_reason text, p_superseded_by uuid, p_idempotency_key text) IS 'Joe-authority-guarded retirement. An ACTIVE rule normally requires its exact ops.rule_approval_receipt; (0351) an active rule with none is still accepted when ops.legacy_rule_admission_note proves it predates the receipt system, and the retirement receipt records that fact in legacy_admission instead of an approval_receipt_id. A rule that postdates the cutover and still lacks a receipt keeps failing -- this is not a general relaxation.';


--
-- Name: retired_rule_delivery_cleanup(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.retired_rule_delivery_cleanup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
begin
  if old.status in ('proposed','active') and new.status='retired' then
    delete from ops.rule_load_layer where rule_id=new.id;
  end if;
  return new;
end
$$;


--
-- Name: FUNCTION retired_rule_delivery_cleanup(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.retired_rule_delivery_cleanup() IS 'Forward SIEP repair: retirement atomically removes the no-longer-deliverable rule layer so deferred policy-epoch readback cannot retain an orphan.';


--
-- Name: retry_delay_seconds(ops.job); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.retry_delay_seconds(p_job ops.job) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select least(
    (d.retry_policy->>'cap_seconds')::integer,
    case d.retry_policy->>'backoff'
      when 'constant' then (d.retry_policy->>'base_seconds')::integer
      when 'linear' then (d.retry_policy->>'base_seconds')::integer * greatest(p_job.attempt,1)
      else (d.retry_policy->>'base_seconds')::integer
           * power(2,greatest(p_job.attempt-1,0))::integer
    end)
  from ops.job_definition d
  where d.key=p_job.definition_key and d.version=p_job.definition_version
$$;


--
-- Name: review_ready_plan_amendment_internal(text, text, text, uuid, text, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.review_ready_plan_amendment_internal(p_work_request text, p_plan_hash text, p_admission_hash text, p_reviewer_actor_id uuid, p_verdict text, p_reviewer_session_ref text, p_review_summary text, p_evidence_refs jsonb, p_gaps jsonb, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, admission_ref text, admission_hash text, review_ref text, review_hash text, verdict text, reviewer_session_ref text, replayed boolean)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare v_work ops.work_request%rowtype; v_plan ops.sourced_work_request_plan%rowtype;
        v_admission ops.heavy_build_admission_revision%rowtype;
        v_review ops.heavy_build_plan_review%rowtype; v_actor public.actor%rowtype;
        v_version integer; v_preimage jsonb; v_digest text;
begin
  if coalesce(p_work_request,'')!~'^WR-[0-9]{1,12}$'
     or coalesce(p_plan_hash,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_admission_hash,'')!~'^sha256:[0-9a-f]{64}$'
     or p_reviewer_actor_id is null or p_idempotency_key is null
     or p_verdict not in ('pass','fail')
     or coalesce(p_reviewer_session_ref,'')!~'^session:[a-z0-9][a-z0-9:._/-]{8,199}$'
     or char_length(btrim(coalesce(p_review_summary,''))) not between 20 and 1000
     or jsonb_typeof(p_evidence_refs) is distinct from 'array'
     or jsonb_array_length(p_evidence_refs) not between 1 and 12
     or exists(select 1 from jsonb_array_elements(p_evidence_refs) item
       where jsonb_typeof(item)<>'string' or item#>>'{}'!~'^safe:[a-z0-9][a-z0-9:_./-]*$')
     or exists(select item#>>'{}' from jsonb_array_elements(p_evidence_refs) item
       group by item#>>'{}' having count(*)>1)
     or jsonb_typeof(p_gaps) is distinct from 'array' or jsonb_array_length(p_gaps)>12
     or exists(select 1 from jsonb_array_elements(p_gaps) item where jsonb_typeof(item)<>'string'
       or char_length(btrim(item#>>'{}')) not between 10 and 500)
     or (p_verdict='pass' and jsonb_array_length(p_gaps)<>0)
     or (p_verdict='fail' and jsonb_array_length(p_gaps)=0) then
    raise exception 'ready-plan amendment review requires exact hashes, fresh session, verdict-consistent gaps, evidence, actor, and idempotency key';
  end if;
  select * into v_actor from public.actor where id=p_reviewer_actor_id and active for share;
  if not found then raise exception 'ready-plan amendment reviewer actor is not active'; end if;
  perform pg_advisory_xact_lock(hashtextextended('heavy-build-review:'||p_idempotency_key,0));
  select * into v_review from ops.heavy_build_plan_review
   where idempotency_key=p_idempotency_key for share;
  if found then
    select * into v_admission from ops.heavy_build_admission_revision where id=v_review.admission_id;
    select * into v_plan from ops.sourced_work_request_plan where id=v_admission.plan_id;
    select * into v_work from ops.work_request where id=v_admission.work_request_id;
    if v_work.ref is distinct from p_work_request or v_plan.plan_hash is distinct from p_plan_hash
       or v_admission.admission_hash is distinct from p_admission_hash
       or v_review.reviewer_actor_id is distinct from p_reviewer_actor_id
       or v_review.verdict is distinct from p_verdict
       or v_review.reviewer_session_ref is distinct from p_reviewer_session_ref
       or v_review.review_summary is distinct from btrim(p_review_summary)
       or v_review.evidence_refs is distinct from p_evidence_refs
       or v_review.gaps is distinct from p_gaps then
      raise exception 'idempotency key already names a different ready-plan amendment review';
    end if;
    return query select v_work.id,v_work.ref,v_plan.id,v_admission.admission_ref,
      v_admission.admission_hash,v_review.review_ref,v_review.review_hash,
      v_review.verdict,v_review.reviewer_session_ref,true;
    return;
  end if;
  select * into v_work from ops.work_request
   where ref=p_work_request and state='ready' for share;
  select * into v_plan from ops.sourced_work_request_plan
   where work_request_id=v_work.id and plan_hash=p_plan_hash for share;
  if v_work.id is null or v_plan.id is null or not exists(
    select 1 from ops.ready_plan_amendment amendment where amendment.plan_id=v_plan.id
      and amendment.work_request_id=v_work.id and amendment.base_version=v_work.version) then
    raise exception 'exact current ready-plan amendment review target not found';
  end if;
  select * into v_admission from ops.heavy_build_admission_revision
   where plan_id=v_plan.id and admission_hash=p_admission_hash
     and version=(select max(latest.version) from ops.heavy_build_admission_revision latest
                   where latest.plan_id=v_plan.id) for share;
  if not found then raise exception 'exact current ready-plan amendment review target not found'; end if;
  if p_reviewer_session_ref=v_admission.builder_session_ref then
    raise exception 'ready-plan amendment review requires a fresh session distinct from the builder context';
  end if;
  select coalesce(max(version),0)+1 into v_version from ops.heavy_build_plan_review
   where admission_id=v_admission.id;
  v_preimage:=jsonb_build_object('contract','carr-heavy-build-review/v1',
    'admission_id',v_admission.id,'admission_hash',v_admission.admission_hash,
    'plan_hash',v_plan.plan_hash,'verdict',p_verdict,
    'reviewer_actor_id',p_reviewer_actor_id,'reviewer_session_ref',p_reviewer_session_ref,
    'review_summary',btrim(p_review_summary),'evidence_refs',p_evidence_refs,
    'gaps',p_gaps,'version',v_version);
  v_digest:=ops.heavy_build_digest(v_preimage);
  insert into ops.heavy_build_plan_review(review_ref,admission_id,version,idempotency_key,
    verdict,reviewer_actor_id,reviewer_session_ref,review_summary,evidence_refs,gaps,review_hash)
  values('HBR-'||substr(v_digest,8,12)||'-v'||v_version,v_admission.id,v_version,
    p_idempotency_key,p_verdict,p_reviewer_actor_id,p_reviewer_session_ref,
    btrim(p_review_summary),p_evidence_refs,p_gaps,v_digest)
  returning * into v_review;
  return query select v_work.id,v_work.ref,v_plan.id,v_admission.admission_ref,
    v_admission.admission_hash,v_review.review_ref,v_review.review_hash,
    v_review.verdict,v_review.reviewer_session_ref,false;
end $_$;


--
-- Name: review_sourced_heavy_build_plan(text, text, text, uuid, text, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.review_sourced_heavy_build_plan(p_work_request text, p_plan_hash text, p_admission_hash text, p_reviewer_actor_id uuid, p_verdict text, p_reviewer_session_ref text, p_review_summary text, p_evidence_refs jsonb, p_gaps jsonb, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, admission_ref text, admission_hash text, review_ref text, review_hash text, verdict text, reviewer_session_ref text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if exists(select 1 from ops.work_request w
    join ops.sourced_work_request_plan p on p.work_request_id=w.id
    join ops.ready_plan_amendment a on a.plan_id=p.id
    where w.ref=p_work_request and p.plan_hash=p_plan_hash) then
    return query select * from ops.review_ready_plan_amendment_internal(
      p_work_request,p_plan_hash,p_admission_hash,p_reviewer_actor_id,p_verdict,
      p_reviewer_session_ref,p_review_summary,p_evidence_refs,p_gaps,p_idempotency_key);
  else
    return query select * from ops.review_sourced_heavy_build_plan_v1(
      p_work_request,p_plan_hash,p_admission_hash,p_reviewer_actor_id,p_verdict,
      p_reviewer_session_ref,p_review_summary,p_evidence_refs,p_gaps,p_idempotency_key);
  end if;
end $$;


--
-- Name: review_sourced_heavy_build_plan_v1(text, text, text, uuid, text, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.review_sourced_heavy_build_plan_v1(p_work_request text, p_plan_hash text, p_admission_hash text, p_reviewer_actor_id uuid, p_verdict text, p_reviewer_session_ref text, p_review_summary text, p_evidence_refs jsonb, p_gaps jsonb, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, admission_ref text, admission_hash text, review_ref text, review_hash text, verdict text, reviewer_session_ref text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype;
  p ops.sourced_work_request_plan%rowtype;
  a ops.heavy_build_admission_revision%rowtype;
  r ops.heavy_build_plan_review%rowtype;
  actor public.actor%rowtype;
  next_version integer;
  preimage jsonb;
  digest text;
begin
  if coalesce(p_work_request,'') !~ '^WR-[0-9]{1,12}$' or coalesce(p_plan_hash,'') !~ '^sha256:[0-9a-f]{64}$'
     or coalesce(p_admission_hash,'') !~ '^sha256:[0-9a-f]{64}$' or p_reviewer_actor_id is null or p_idempotency_key is null
     or p_verdict not in ('pass','fail') or coalesce(p_reviewer_session_ref,'') !~ '^session:[a-z0-9][a-z0-9:._/-]{8,199}$'
     or char_length(btrim(coalesce(p_review_summary,''))) not between 20 and 1000
     or jsonb_typeof(p_evidence_refs) is distinct from 'array' or jsonb_array_length(p_evidence_refs) not between 1 and 12
     or exists (select 1 from jsonb_array_elements(p_evidence_refs) item where jsonb_typeof(item)<>'string' or item #>> '{}' !~ '^safe:[a-z0-9][a-z0-9:_./-]*$')
     or exists (select item #>> '{}' from jsonb_array_elements(p_evidence_refs) item group by item #>> '{}' having count(*)>1)
     or jsonb_typeof(p_gaps) is distinct from 'array' or jsonb_array_length(p_gaps)>12
     or exists (select 1 from jsonb_array_elements(p_gaps) item where jsonb_typeof(item)<>'string' or char_length(btrim(item #>> '{}')) not between 10 and 500)
     or (p_verdict='pass' and jsonb_array_length(p_gaps)<>0) or (p_verdict='fail' and jsonb_array_length(p_gaps)=0) then
    raise exception 'heavy build review requires exact hashes, fresh session, verdict-consistent gaps, evidence, actor, and idempotency key';
  end if;
  select x.* into actor from public.actor x where x.id=p_reviewer_actor_id and x.active for share;
  if not found then raise exception 'heavy build reviewer actor is not active'; end if;
  perform pg_advisory_xact_lock(hashtextextended('heavy-build-review:'||p_idempotency_key,0));
  select x.* into r from ops.heavy_build_plan_review x where x.idempotency_key=p_idempotency_key for share;
  if found then
    select x.* into a from ops.heavy_build_admission_revision x where x.id=r.admission_id;
    select x.* into p from ops.sourced_work_request_plan x where x.id=a.plan_id;
    select x.* into w from ops.work_request x where x.id=a.work_request_id;
    if not found or w.ref is distinct from p_work_request or p.plan_hash is distinct from p_plan_hash
       or a.admission_hash is distinct from p_admission_hash or r.reviewer_actor_id is distinct from p_reviewer_actor_id
       or r.verdict is distinct from p_verdict or r.reviewer_session_ref is distinct from p_reviewer_session_ref
       or r.review_summary is distinct from btrim(p_review_summary) or r.evidence_refs is distinct from p_evidence_refs or r.gaps is distinct from p_gaps then
      raise exception 'idempotency key already names a different heavy build review';
    end if;
    return query select w.id,w.ref,p.id,a.admission_ref,a.admission_hash,r.review_ref,r.review_hash,r.verdict,r.reviewer_session_ref,true;
    return;
  end if;
  select w0.* into w from ops.work_request w0 where w0.ref=p_work_request and w0.state='triaged' for share;
  if not found then raise exception 'exact current heavy build review target not found'; end if;
  select p0.* into p from ops.sourced_work_request_plan p0 where p0.work_request_id=w.id and p0.plan_hash=p_plan_hash for share;
  if not found then raise exception 'exact current heavy build review target not found'; end if;
  select a0.* into a from ops.heavy_build_admission_revision a0
   where a0.plan_id=p.id and a0.admission_hash=p_admission_hash
     and a0.version=(select max(latest.version) from ops.heavy_build_admission_revision latest where latest.plan_id=p.id)
   for share;
  if not found then raise exception 'exact current heavy build review target not found'; end if;
  if p_reviewer_session_ref=a.builder_session_ref then raise exception 'heavy build review requires a fresh session distinct from the builder context'; end if;
  select coalesce(max(x.version),0)+1 into next_version from ops.heavy_build_plan_review x where x.admission_id=a.id;
  preimage := jsonb_build_object('contract','carr-heavy-build-review/v1','admission_id',a.id,'admission_hash',a.admission_hash,
    'plan_hash',p.plan_hash,'verdict',p_verdict,'reviewer_actor_id',p_reviewer_actor_id,'reviewer_session_ref',p_reviewer_session_ref,
    'review_summary',btrim(p_review_summary),'evidence_refs',p_evidence_refs,'gaps',p_gaps,'version',next_version);
  digest := ops.heavy_build_digest(preimage);
  insert into ops.heavy_build_plan_review
    (review_ref,admission_id,version,idempotency_key,verdict,reviewer_actor_id,reviewer_session_ref,review_summary,evidence_refs,gaps,review_hash)
  values ('HBR-'||substr(digest,8,12)||'-v'||next_version,a.id,next_version,p_idempotency_key,p_verdict,p_reviewer_actor_id,p_reviewer_session_ref,btrim(p_review_summary),p_evidence_refs,p_gaps,digest)
  returning * into r;
  return query select w.id,w.ref,p.id,a.admission_ref,a.admission_hash,r.review_ref,r.review_hash,r.verdict,r.reviewer_session_ref,false;
end;
$_$;


--
-- Name: revoke_tour_rights_receipt(text, uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.revoke_tour_rights_receipt(p_tenant text, p_rights_receipt_id uuid, p_revoked_at timestamp with time zone, p_actor_id text, p_receipt_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_prior ops.tour_rights_receipt%rowtype; v_id uuid;
begin
  select * into v_prior from ops.tour_rights_receipt
   where id=p_rights_receipt_id and organization_tenant_id=p_tenant for update;
  if not found or v_prior.status <> 'active' or v_prior.revoked_at is not null or p_revoked_at is null
     or p_actor_id is null or p_receipt_digest is null then
    raise exception 'rights receipt revocation target is invalid';
  end if;
  insert into ops.tour_rights_receipt (organization_tenant_id,provider,sku,policy_key,receipt_version,receipt_digest,terms_url,reviewed_at,reviewer,intended_use,allowed_field_classes,allowed_use_classes,effective_at,revoked_at,supersedes_receipt_id,status)
  values (p_tenant,v_prior.provider,v_prior.sku,v_prior.policy_key,v_prior.receipt_version+1,p_receipt_digest,v_prior.terms_url,p_revoked_at,p_actor_id,'revocation',v_prior.allowed_field_classes,v_prior.allowed_use_classes,p_revoked_at,p_revoked_at,v_prior.id,'revoked')
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: revoke_tour_share_grant(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.revoke_tour_share_grant(p_tenant text, p_share_grant_id uuid, p_reason text, p_receipt_digest text, p_revoked_at timestamp with time zone, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
begin
  perform 1 from ops.tour_share_grant where organization_tenant_id=p_tenant and id=p_share_grant_id for update;
  if not found or exists(select 1 from ops.tour_share_grant_revocation_receipt where organization_tenant_id=p_tenant and share_grant_id=p_share_grant_id) or p_receipt_digest !~ '^sha256:[a-f0-9]{64}$' or nullif(btrim(p_reason),'') is null or nullif(btrim(p_actor_id),'') is null then raise exception 'tour share revocation is invalid'; end if;
  insert into ops.tour_share_grant_revocation_receipt(organization_tenant_id,share_grant_id,revoked_at,actor_id,reason,receipt_digest)
  values(p_tenant,p_share_grant_id,p_revoked_at,p_actor_id,p_reason,p_receipt_digest);
  return p_share_grant_id;
end $_$;


--
-- Name: rotate_tour_share_grant(text, uuid, uuid, text, jsonb, timestamp with time zone, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rotate_tour_share_grant(p_tenant text, p_share_grant_id uuid, p_projection_id uuid, p_token_digest text, p_permission_scopes jsonb, p_expires_at timestamp with time zone, p_receipt_digest text, p_actor_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_prior ops.tour_share_grant%rowtype; v_projection ops.tour_public_projection%rowtype; v_id uuid;
begin
  select * into v_prior from ops.tour_share_grant where organization_tenant_id=p_tenant and id=p_share_grant_id for update;
  if not found or v_prior.projection_id<>p_projection_id or exists(select 1 from ops.tour_share_grant_revocation_receipt r where r.organization_tenant_id=p_tenant and r.share_grant_id=v_prior.id) or exists(select 1 from ops.tour_share_grant g where g.organization_tenant_id=p_tenant and g.rotated_from_grant_id=v_prior.id) then raise exception 'tour share rotation target is inactive'; end if;
  if p_token_digest !~ '^sha256:[a-f0-9]{64}$' or p_receipt_digest !~ '^sha256:[a-f0-9]{64}$' or p_expires_at<=now() or jsonb_typeof(p_permission_scopes)<>'array' or not (p_permission_scopes <@ '["view_packet","view_map"]'::jsonb) or jsonb_array_length(p_permission_scopes)=0 or nullif(btrim(p_actor_id),'') is null then raise exception 'tour share payload is invalid'; end if;
  select * into v_projection from ops.tour_public_projection where organization_tenant_id=p_tenant and id=p_projection_id;
  if not found or ops.read_tour_public_projection(p_tenant,p_projection_id) is null then raise exception 'tour share requires a current sealed projection'; end if;
  if p_permission_scopes ? 'view_map' and not ops.tour_public_map_projection_ready(p_tenant,p_projection_id)
  then raise exception 'tour map share requires current rights, sealed entrance coordinates, and an approved promotion receipt'; end if;
  insert into ops.tour_share_grant(organization_tenant_id,projection_id,grant_version,token_digest,audience,permission_scopes,rotated_from_grant_id,expires_at,status,receipt_digest,created_by_actor_id)
  values(p_tenant,p_projection_id,v_prior.grant_version+1,p_token_digest,'client',p_permission_scopes,v_prior.id,p_expires_at,'active',p_receipt_digest,p_actor_id) returning id into v_id;
  return v_id;
end $_$;


--
-- Name: rule_amendment_reaches(uuid, integer, text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rule_amendment_reaches(p_rule_id uuid, p_from_version integer, p_from_hash text, p_to_version integer, p_to_hash text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  with recursive chain(rule_version_after, new_statement_hash) as (
    select r.rule_version_after, r.new_statement_hash
      from ops.rule_amendment_receipt r
     where r.rule_id = p_rule_id
       and r.rule_version_before = p_from_version
       and r.prior_statement_hash = p_from_hash
    union all
    select nx.rule_version_after, nx.new_statement_hash
      from ops.rule_amendment_receipt nx
      join chain c on nx.rule_version_before = c.rule_version_after
     where nx.rule_id = p_rule_id
  )
  select exists (
    select 1 from chain
     where rule_version_after = p_to_version
       and new_statement_hash = p_to_hash
  )
$$;


--
-- Name: FUNCTION rule_amendment_reaches(p_rule_id uuid, p_from_version integer, p_from_hash text, p_to_version integer, p_to_hash text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.rule_amendment_reaches(p_rule_id uuid, p_from_version integer, p_from_hash text, p_to_version integer, p_to_hash text) IS 'True when an unbroken chain of ops.rule_amendment_receipt rows connects the approval receipt''s frozen (version, statement_hash) to the rule''s CURRENT (version, statement_hash). Used only by ops.applicable_rules() so an amended active rule keeps reciting.';


--
-- Name: rule_delivery_audit_counts(integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rule_delivery_audit_counts(p_layer0_shared_cap integer DEFAULT 35) RETURNS TABLE(total bigint, untagged bigint, orphaned bigint, layer0 bigint, control bigint, pack bigint, layer0_shared bigint, layer0_shared_cap integer, wildcarded bigint, packless bigint, packs bigint, emptypack bigint, scope_mismatch bigint, mode text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select
    (select count(*) from public.rule r where r.status = 'active'),
    (select count(*)
       from public.rule r
       left join ops.rule_load_layer l on l.rule_id = r.id
      where r.status = 'active' and l.rule_id is null),
    (select count(*)
       from ops.rule_load_layer l
      where not exists (
        select 1 from public.rule r
         where r.id = l.rule_id and r.status = 'active')),
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where l.load_layer = 'layer0'),
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where l.load_layer = 'control'),
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where l.load_layer = 'pack'),
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where l.load_layer = 'layer0' and l.scope = 'shared'),
    p_layer0_shared_cap,
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where '*' = any(l.packs)),
    (select count(*)
       from ops.rule_load_layer l
       join public.rule r on r.id = l.rule_id and r.status = 'active'
      where l.load_layer = 'pack' and cardinality(l.packs) = 0),
    (select count(*) from ops.rule_pack),
    (select count(*)
       from ops.rule_pack p
      where not exists (
        select 1
          from ops.rule_load_layer l
          join public.rule r on r.id = l.rule_id and r.status = 'active'
         where p.pack = any(l.packs))),
    (select count(*)
       from public.rule r
       join ops.rule_load_layer l on l.rule_id = r.id
       left join public.actor owner on owner.id = r.personal_to
      where r.status = 'active'
        and l.scope is distinct from coalesce(owner.slug, 'shared')),
    coalesce(
      (select p.mode from ops.rule_delivery_policy p limit 1),
      '(none)')
$$;


--
-- Name: FUNCTION rule_delivery_audit_counts(p_layer0_shared_cap integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.rule_delivery_audit_counts(p_layer0_shared_cap integer) IS 'Aggregate delivery coverage, layer, scope and policy health. SECURITY DEFINER so carr_jobs can detect missing current rules and personal-scope drift without receiving SELECT on rule text or actor rows.';


--
-- Name: rule_delivery_cutover_preflight(uuid[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rule_delivery_cutover_preflight(p_curation_proposal_ids uuid[]) RETURNS TABLE(current_mode text, target_count bigint, receipt_count bigint, curation_found bigint, curation_approved bigint, curation_human_reviewed bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
begin
  if session_user <> 'carr_authority_joe'
     or ops.authority_actor_slug() <> 'joe' then
    raise exception using errcode='42501',
      message='rule-delivery cutover preflight requires the Joe authority login';
  end if;
  if cardinality(p_curation_proposal_ids) <> 38
     or (select count(distinct proposal_id) from unnest(p_curation_proposal_ids) proposal_id) <> 38 then
    raise exception 'rule-delivery cutover preflight requires the exact 38-item curation batch';
  end if;
  return query
    select (select p.mode from ops.rule_delivery_policy p where p.singleton),
           (select count(*) from ops.rule_delivery_activation_target),
           (select count(*) from ops.rule_delivery_activation_receipt),
           count(rp.id),
           count(*) filter(where rp.status='approved'),
           count(*) filter(where rp.status='approved' and a.kind='human')
      from public.retrieval_proposal rp
      left join public.actor a on a.id=rp.reviewer_id
     where rp.id=any(p_curation_proposal_ids);
end $$;


--
-- Name: rule_delivery_plan(text, text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rule_delivery_plan(p_actor text DEFAULT NULL::text, p_packs text[] DEFAULT '{}'::text[]) RETURNS TABLE(rule_id uuid, short_id text, load_layer text, packs text[], scope text, selected boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select r.id, l.short_id, l.load_layer, l.packs, l.scope,
         (l.load_layer = 'layer0'
          or l.packs && coalesce(p_packs, '{}'::text[])) as selected
    from public.rule r
    join ops.rule_load_layer l on l.rule_id = r.id
   where r.status = 'active'
     and (l.scope = 'shared' or (p_actor is not null and l.scope = p_actor))
   order by l.load_layer, l.short_id
$$;


--
-- Name: FUNCTION rule_delivery_plan(p_actor text, p_packs text[]); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.rule_delivery_plan(p_actor text, p_packs text[]) IS 'The DELIVERY selector: which active rules a scoped boot would hand this partner for these packs. Not ops.applicable_rules, which is the receipt-bound ENFORCEMENT compiler and returns only rules carrying a live approval receipt.';


--
-- Name: rule_pack_index(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.rule_pack_index() RETURNS TABLE(pack text, title text, description text, triggers text[], rule_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select p.pack, p.title, p.description, p.triggers,
         count(l.rule_id) filter (where r.status = 'active') as rule_count
    from ops.rule_pack p
    left join ops.rule_load_layer l on p.pack = any(l.packs)
    left join public.rule r on r.id = l.rule_id
   group by p.pack, p.title, p.description, p.triggers
   order by p.pack
$$;


--
-- Name: FUNCTION rule_pack_index(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.rule_pack_index() IS 'The PACK INDEX a Layer 0 boot returns instead of the packs themselves: names and triggers, so an undeclared session knows what exists and what would load it.';


--
-- Name: scac_admit_mutation(text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_admit_mutation(p_token_ref_digest text, p_operation_manifest jsonb, p_admission_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare b ops.scac_token_verification_binding%rowtype; t ops.scac_capability_token_receipt%rowtype;
        c ops.scac_pop_challenge%rowtype; e ops.scac_device_enrollment%rowtype;
        pe ops.scac_policy_epoch%rowtype; re ops.scac_mutation_registry_entry%rowtype;
        ob ops.scac_operation_effect_binding%rowtype;
        prior ops.scac_reference_monitor_receipt%rowtype; state jsonb; control jsonb;
        root_state jsonb; bundle text; manifest_digest text; effect_digest text;
        effects text[]; admission uuid; studio_benchmark_count integer;
        expected_keys constant text[]:=array[
          'device_key_digest','device_ref','domain','effect_keys','environment','facts_digest',
          'idempotency_digest','ingress_key','mutation_kind','policy_epoch','policy_epoch_digest',
          'principal_digest','registry_digest','registry_version','request_payload_digest',
          'schema_version','target_surface','tenant_scope','workload_digest'];
begin
  bundle:=ops.scac_runtime_privilege_bundle();
  if bundle is null then raise exception 'scac.refusal.identity_unverified: SIEP-18 caller role refused'; end if;
  if coalesce(p_token_ref_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     p_admission_idempotency_key is null or
     not ops.scac_json_has_exact_keys(p_operation_manifest,expected_keys) or
     p_operation_manifest->>'domain'<>'CARR-SCAC-OPERATION-V1' or
     p_operation_manifest->>'schema_version'<>'scac-operation-manifest.v1' or
     p_operation_manifest->>'tenant_scope'<>'carr-internal' or
     p_operation_manifest->>'environment'<>'source-test' or
     jsonb_typeof(p_operation_manifest->'effect_keys')<>'array' then
    raise exception 'scac.refusal.request_shape_invalid: SIEP-18 manifest malformed or open';
  end if;
  select array_agg(value order by value collate "C") into effects
    from jsonb_array_elements_text(p_operation_manifest->'effect_keys');
  if effects is null or cardinality(effects)=0 or
     cardinality(effects)<>(select count(distinct x) from unnest(effects) x) or
     exists(select 1 from unnest(effects) x where
       x!~'^db-relation-acl:[^:]+:[a-z_]+:(insert|update|delete|truncate)$'
       and x!~'^db-column-acl:[^:]+:[a-z_]+:update$') then
    raise exception 'scac.refusal.request_shape_invalid: SIEP-18 effect set malformed';
  end if;
  manifest_digest:=ops.scac_reference_monitor_sha256(p_operation_manifest);
  effect_digest:=ops.scac_reference_monitor_sha256(to_jsonb(effects));
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-reference-monitor',0));
  select * into prior from ops.scac_reference_monitor_receipt
    where admission_idempotency_key=p_admission_idempotency_key;
  if prior.admission_id is not null then
    if prior.token_ref_digest<>p_token_ref_digest or
       prior.operation_manifest_digest<>manifest_digest or prior.session_principal<>session_user or
       prior.transaction_id<>txid_current() or prior.backend_pid<>pg_backend_pid() then
      raise exception 'scac.refusal.replay: SIEP-18 admission idempotency mismatch'; end if;
    perform set_config('carr.scac_admission_id',prior.admission_id::text,true);
    return jsonb_build_object('admitted',true,'admission_id',prior.admission_id::text,
      'decision',prior.decision,'monitor_state',prior.monitor_state,
      'production_enforcement_active',false);
  end if;
  select * into b from ops.scac_token_verification_binding
    where token_ref_digest=p_token_ref_digest for key share;
  select * into t from ops.scac_capability_token_receipt
    where token_ref_digest=p_token_ref_digest for key share;
  select * into c from ops.scac_pop_challenge where challenge_id=t.challenge_id for key share;
  select * into e from ops.scac_device_enrollment where device_ref=c.device_ref for key share;
  select * into pe from ops.scac_policy_epoch order by epoch desc limit 1 for key share;
  select * into re from ops.scac_mutation_registry_entry
    where registry_version=pe.registry_version and ingress_key=c.ingress_key for key share;
  select * into ob from ops.scac_operation_effect_binding
    where registry_version=pe.registry_version and ingress_key=c.ingress_key
      and privilege_bundle=bundle for key share;
  state:=ops.scac_reference_monitor_state(); control:=ops.scac_token_control_snapshot();
  root_state:=ops.scac_root_trust_chain_state();
  if b.token_ref_digest is null or t.token_ref_digest is null or c.challenge_id is null or
     e.device_ref is null or re.ingress_key is null or ob.binding_digest is null then
    raise exception 'scac.refusal.token_invalid: SIEP-18 required bound fact missing'; end if;
  if e.profile_key='studio-executor' then
    select count(*) into studio_benchmark_count
      from ops.scac_device_benchmark_receipt br
      where br.device_ref=e.device_ref and br.facts_digest=e.facts_digest and br.passed;
    if not exists(select 1 from ops.scac_device_fact_receipt fr
           where fr.device_ref=e.device_ref and fr.facts_digest=e.facts_digest)
       or studio_benchmark_count<>9 then
      raise exception 'scac.refusal.device_benchmark_incomplete: SIEP-18 Studio evidence incomplete';
    end if;
  end if;
  if state->>'monitor_state'<>'current' then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 monitor or grant state stale'; end if;
  if state->>'mode'<>'enforced_source_test' then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 shadow is non-authorizing'; end if;
  if control->>'kill_switch_state'<>'inactive' then
    raise exception 'scac.refusal.kill_switch: SIEP-18 global control engaged'; end if;
  if t.expires_at<=clock_timestamp() or c.expires_at<=clock_timestamp() then
    raise exception 'scac.refusal.token_invalid: SIEP-18 token or proof expired'; end if;
  if pe.epoch<>c.policy_epoch or pe.epoch_digest<>c.policy_epoch_digest or
     pe.registry_version<>c.registry_version or pe.registry_digest<>c.registry_digest then
    raise exception 'scac.refusal.epoch_incompatible: SIEP-18 token policy is not current'; end if;
  if re.effect_class='read_only' or coalesce((re.contract->>'classification_authorizing')::boolean,true) or
     re.contract->>'mutation_kind'<>c.mutation_kind or re.contract->>'target_surface'<>c.target_surface then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 ingress contract unavailable'; end if;
  if ob.registry_entry_digest<>re.entry_digest or
     ob.effect_keys is distinct from effects or ob.effect_set_digest<>effect_digest then
    raise exception 'scac.refusal.scope_violation: SIEP-18 exact operation effect set mismatch'; end if;
  if manifest_digest<>c.operation_manifest_digest or
     p_operation_manifest->>'principal_digest'<>c.principal_digest or
     p_operation_manifest->>'device_ref'<>c.device_ref or
     p_operation_manifest->>'device_key_digest'<>c.device_key_digest or
     p_operation_manifest->>'facts_digest'<>c.facts_digest or
     (p_operation_manifest->>'workload_digest') is distinct from c.workload_digest or
     p_operation_manifest->>'registry_version'<>c.registry_version or
     p_operation_manifest->>'registry_digest'<>c.registry_digest or
     p_operation_manifest->>'ingress_key'<>c.ingress_key or
     p_operation_manifest->>'mutation_kind'<>c.mutation_kind or
     p_operation_manifest->>'target_surface'<>c.target_surface or
     (p_operation_manifest->>'policy_epoch')::bigint<>c.policy_epoch or
     p_operation_manifest->>'policy_epoch_digest'<>c.policy_epoch_digest or
     p_operation_manifest->>'idempotency_digest'<>c.idempotency_digest or
     coalesce(p_operation_manifest->>'request_payload_digest','')!~'^sha256:[0-9a-f]{64}$' then
    raise exception 'scac.refusal.token_invalid: SIEP-18 request/manifest/token binding mismatch'; end if;
  if coalesce((root_state->>'structurally_valid')::boolean,false) is not true or
     root_state->>'latest_event_digest'<>b.issuer_root_event_digest then
    raise exception 'scac.refusal.root_untrusted: SIEP-18 issuer root is not current'; end if;
  if exists(select 1 from ops.scac_token_revocation_event r where
       (r.subject_kind='device' and r.subject_digest=ops.scac_token_sha256_text(c.device_ref)) or
       (r.subject_kind='device_key' and r.subject_digest=c.device_key_digest) or
       (r.subject_kind='facts' and r.subject_digest=c.facts_digest) or
       (c.workload_digest is not null and r.subject_kind='workload' and r.subject_digest=c.workload_digest) or
       (r.subject_kind='challenge' and r.subject_digest=c.challenge_digest) or
       (r.subject_kind='token' and r.subject_digest=t.token_ref_digest) or
       (r.subject_kind='issuer_key' and r.subject_digest=t.issuer_key_digest) or
       (r.subject_kind='root_event' and r.subject_digest=t.issuer_root_event_digest)) then
    raise exception 'scac.refusal.revoked: SIEP-18 subject revoked'; end if;
  if exists(select 1 from unnest(effects) x where not exists(
       select 1 from ops.scac_mutation_registry_entry xre
       where xre.registry_version=pe.registry_version and xre.ingress_key=x
         and xre.ingress_kind in ('db_relation_acl','db_column_acl')
         and xre.contract->>'grantee'=bundle
         and xre.contract->>'privilege' in ('insert','update','delete','truncate'))) then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 effect is not a current grant'; end if;
  admission:=gen_random_uuid();
  insert into ops.scac_reference_monitor_receipt
    (admission_id,token_ref_digest,operation_manifest_digest,request_payload_digest,
     idempotency_digest,ingress_key,effect_keys,effect_set_digest,
     operation_effect_binding_digest,policy_epoch,
     policy_epoch_digest,registry_version,registry_digest,principal_digest,
     session_principal,privilege_bundle,grant_digest,backend_pid,transaction_id,
     admission_idempotency_key,decision,monitor_state,direct_grant_guarded)
  values (admission,p_token_ref_digest,manifest_digest,
    p_operation_manifest->>'request_payload_digest',c.idempotency_digest,c.ingress_key,
    effects,effect_digest,ob.binding_digest,pe.epoch,pe.epoch_digest,pe.registry_version,pe.registry_digest,
    c.principal_digest,session_user,bundle,state->>'grant_digest',pg_backend_pid(),txid_current(),
    p_admission_idempotency_key,'admit_source_test_nonproduction','current',true);
  perform set_config('carr.scac_admission_id',admission::text,true);
  return jsonb_build_object('admitted',true,'admission_id',admission::text,
    'decision','admit_source_test_nonproduction','monitor_state','current',
    'grant_digest',state->>'grant_digest','production_enforcement_active',false);
end $_$;


--
-- Name: scac_artifact_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'SIEP-13 artifact registry, signatures, and transparency chain are append-only';
end $$;


--
-- Name: scac_artifact_integrity_state(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_integrity_state(p_artifact_digest text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare m ops.scac_artifact_manifest%rowtype; signatures integer; inclusions integer;
begin
  if p_artifact_digest is null or p_artifact_digest !~ '^sha256:[0-9a-f]{64}$' then
    return jsonb_build_object('artifact_digest',p_artifact_digest,'artifact_trust_state','untrusted',
      'signature_state','unavailable','transparency_state','unavailable','reason_id','scac.refusal.untrusted_artifact',
      'root_trust_operational',false,'production_enforcement_active',false);
  end if;
  select * into m from ops.scac_artifact_manifest where artifact_digest=p_artifact_digest;
  if m.artifact_digest is null then
    return jsonb_build_object('artifact_digest',p_artifact_digest,'artifact_trust_state','untrusted',
      'signature_state','unavailable','transparency_state','unavailable','reason_id','scac.refusal.untrusted_artifact',
      'root_trust_operational',false,'production_enforcement_active',false);
  end if;
  select count(*) into signatures from ops.scac_artifact_signature where manifest_digest=m.manifest_digest;
  select count(*) into inclusions from ops.scac_artifact_transparency_entry where manifest_digest=m.manifest_digest;
  return jsonb_build_object('artifact_digest',m.artifact_digest,'manifest_digest',m.manifest_digest,
    'artifact_trust_state','untrusted_pending_siep14','signature_state',
      case when signatures>0 then 'recorded_requires_typed_ed25519_verification' else 'unavailable' end,
    'transparency_state',case when inclusions>0 then 'included_append_only' else 'unavailable' end,
    'reason_id',case when signatures>0 and inclusions>0 then 'scac.refusal.root_untrusted'
                     else 'scac.refusal.untrusted_artifact' end,
    'root_trust_operational',false,'production_enforcement_active',false);
end $_$;


--
-- Name: scac_artifact_manifest_digest(text, text, text, bigint, text, text, text, text, bigint, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_manifest_digest(p_artifact_digest text, p_artifact_kind text, p_media_type text, p_byte_length bigint, p_source_ref text, p_source_digest text, p_sbom_digest text, p_provenance_digest text, p_policy_epoch bigint, p_policy_epoch_digest text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-artifact-manifest.v1','artifact_digest',p_artifact_digest,
    'artifact_kind',p_artifact_kind,'media_type',p_media_type,'byte_length',p_byte_length,
    'source_ref',p_source_ref,'source_digest',p_source_digest,'sbom_digest',p_sbom_digest,
    'provenance_digest',p_provenance_digest,'policy_epoch',p_policy_epoch,
    'policy_epoch_digest',p_policy_epoch_digest)),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_artifact_manifest_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_manifest_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare expected_digest text;
begin
  expected_digest := ops.scac_artifact_manifest_digest(
    new.artifact_digest,new.artifact_kind,new.media_type,new.byte_length,new.source_ref,
    new.source_digest,coalesce(new.sbom_digest,'sha256:' || repeat('0',64)),new.provenance_digest,
    new.policy_epoch,new.policy_epoch_digest);
  if new.manifest_digest is distinct from expected_digest then
    raise exception 'SIEP-13 artifact manifest digest mismatch';
  end if;
  if not exists(select 1 from ops.scac_policy_epoch e where e.epoch=new.policy_epoch
                  and e.epoch_digest=new.policy_epoch_digest) then
    raise exception 'SIEP-13 artifact manifest policy epoch is unavailable';
  end if;
  return new;
end $$;


--
-- Name: scac_artifact_root_binding_state(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_root_binding_state(p_artifact_digest text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare root_state jsonb; signer_count integer; active_key text;
begin
  root_state:=ops.scac_root_trust_chain_state(); active_key:=root_state->>'active_key_digest';
  select count(*) into signer_count from ops.scac_artifact_manifest m join ops.scac_artifact_signature s
    on s.manifest_digest=m.manifest_digest where m.artifact_digest=p_artifact_digest and s.signer_key_digest=active_key;
  return jsonb_build_object('artifact_digest',p_artifact_digest,'root_binding_state',
    case when coalesce((root_state->>'valid')::boolean,false) and active_key is not null and signer_count>0
      then 'current_key_recorded_requires_typed_ed25519_verification' else 'untrusted_or_revoked_root' end,
    'artifact_trust_state','untrusted_for_production','reason_id',
    case when signer_count>0 then 'scac.refusal.production_trust_inactive' else 'scac.refusal.root_untrusted' end,
    'root_trust_operational',false,'production_enforcement_active',false);
end $$;


--
-- Name: scac_artifact_signature_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_signature_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if not exists(select 1 from ops.scac_artifact_manifest m
                 where m.manifest_digest=new.manifest_digest) then
    raise exception 'SIEP-13 signature manifest is unavailable';
  end if;
  return new;
end $$;


--
-- Name: scac_artifact_transparency_entry_digest(bigint, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_transparency_entry_digest(p_entry_no bigint, p_previous_entry_digest text, p_manifest_digest text, p_signature_digest text, p_statement_digest text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:' || encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-artifact-transparency.v1','entry_no',p_entry_no,
    'previous_entry_digest',p_previous_entry_digest,'manifest_digest',p_manifest_digest,
    'signature_digest',p_signature_digest,'statement_digest',p_statement_digest,
    'entry_kind','artifact_inclusion')),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_artifact_transparency_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_transparency_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare tip ops.scac_artifact_transparency_entry%rowtype; signature_manifest text; expected_digest text;
begin
  lock table ops.scac_artifact_transparency_entry in share row exclusive mode;
  select * into tip from ops.scac_artifact_transparency_entry order by entry_no desc limit 1;
  if (tip.entry_no is null and (new.entry_no<>1 or new.previous_entry_digest is not null))
     or (tip.entry_no is not null and
         (new.entry_no<>tip.entry_no+1 or new.previous_entry_digest is distinct from tip.entry_digest)) then
    raise exception 'SIEP-13 transparency chain gap or fork';
  end if;
  select manifest_digest into signature_manifest from ops.scac_artifact_signature
   where signature_digest=new.signature_digest;
  if signature_manifest is null or signature_manifest is distinct from new.manifest_digest then
    raise exception 'SIEP-13 transparency signature does not bind the manifest';
  end if;
  expected_digest := ops.scac_artifact_transparency_entry_digest(new.entry_no,
    new.previous_entry_digest,new.manifest_digest,new.signature_digest,new.statement_digest);
  if new.entry_digest is distinct from expected_digest then
    raise exception 'SIEP-13 transparency entry digest mismatch';
  end if;
  return new;
end $$;


--
-- Name: scac_artifact_truncate_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_artifact_truncate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'SIEP-13 artifact registry, signatures, and transparency chain cannot be truncated';
end $$;


--
-- Name: scac_bind_trusted_principal(jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_bind_trusted_principal(p_server_principal jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare actor_row public.actor%rowtype; prior ops.scac_trusted_principal_binding%rowtype;
        expected_bundle text; manifest jsonb; principal_digest text; binding_digest text; binding uuid;
        expected_keys constant text[]:=array['actor_id','actor_kind','actor_slug','authorization_class',
          'authority_sponsor_slug','backend_pid','client_id','human','native_agent_verified',
          'organization_tenant_id','principal_digest','privilege_bundle','production_enforcement_active',
          'schema_version','session_principal','source','sponsoring_human_slug','via'];
begin
  expected_bundle:=ops.scac_runtime_privilege_bundle();
  if expected_bundle is null then
    raise exception 'scac.refusal.identity_unverified: SIEP-18 runtime session refused'; end if;
  if p_idempotency_key is null or not ops.scac_json_has_exact_keys(p_server_principal,expected_keys) or
     jsonb_typeof(p_server_principal->'actor_id') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'actor_kind') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'actor_slug') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'authorization_class') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'organization_tenant_id') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'principal_digest') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'privilege_bundle') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'schema_version') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'session_principal') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'source') is distinct from 'string' or
     jsonb_typeof(p_server_principal->'backend_pid') is distinct from 'number' or
     jsonb_typeof(p_server_principal->'human') is distinct from 'boolean' or
     jsonb_typeof(p_server_principal->'native_agent_verified') is distinct from 'boolean' or
     jsonb_typeof(p_server_principal->'production_enforcement_active') is distinct from 'boolean' or
     coalesce(jsonb_typeof(p_server_principal->'authority_sponsor_slug') not in ('string','null'),true) or
     coalesce(jsonb_typeof(p_server_principal->'client_id') not in ('string','null'),true) or
     coalesce(jsonb_typeof(p_server_principal->'sponsoring_human_slug') not in ('string','null'),true) or
     coalesce(jsonb_typeof(p_server_principal->'via') not in ('string','null'),true) or
     p_server_principal->>'schema_version' is distinct from 'scac-trusted-principal.v1' or
     p_server_principal->>'organization_tenant_id' is distinct from 'carr-internal' or
     p_server_principal->>'source' is distinct from 'server_authenticated_actor_plus_database_readback' or
     p_server_principal->'production_enforcement_active' is distinct from 'false'::jsonb or
     coalesce(p_server_principal->>'actor_id','')!~
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or
     p_server_principal->>'actor_kind' not in ('human','automation','system') or
     p_server_principal->>'session_principal' is distinct from session_user or
     p_server_principal->>'privilege_bundle' is distinct from expected_bundle or
     p_server_principal->'backend_pid' is distinct from to_jsonb(pg_backend_pid()) or
     coalesce(p_server_principal->>'principal_digest','')!~'^sha256:[0-9a-f]{64}$' then
    raise exception 'scac.refusal.identity_unverified: SIEP-18 trusted principal malformed or session-mismatched';
  end if;
  manifest:=p_server_principal-'principal_digest'-'source'-'production_enforcement_active';
  principal_digest:=ops.scac_reference_monitor_sha256(manifest);
  if principal_digest<>p_server_principal->>'principal_digest' then
    raise exception 'scac.refusal.identity_unverified: SIEP-18 trusted principal digest mismatch'; end if;
  select * into actor_row from public.actor
    where id=(p_server_principal->>'actor_id')::uuid
      and slug=p_server_principal->>'actor_slug' and active for key share;
  if actor_row.id is null then
    raise exception 'scac.refusal.identity_unverified: SIEP-18 authenticated actor unavailable'; end if;
  if actor_row.kind is distinct from p_server_principal->>'actor_kind' or
     p_server_principal->'human' is distinct from to_jsonb(actor_row.kind='human') or
     (actor_row.kind='human' and
       (actor_row.slug not in ('joe','dell') or
        p_server_principal->>'sponsoring_human_slug' is distinct from actor_row.slug or
        p_server_principal->>'authorization_class' is distinct from 'verified_partner' or
        p_server_principal->'native_agent_verified' is distinct from 'false'::jsonb)) or
     (actor_row.kind='automation' and
       (p_server_principal->>'authorization_class' is distinct from case
          when p_server_principal->>'sponsoring_human_slug' in ('joe','dell')
            then 'sponsored_agent' else 'unsponsored_agent' end or
        (p_server_principal->>'sponsoring_human_slug' is not null and not (
          (actor_row.slug in ('codex','claude') and
            p_server_principal->>'sponsoring_human_slug' in ('joe','dell')) or
          (actor_row.slug='joe-local' and p_server_principal->>'sponsoring_human_slug'='joe') or
          (actor_row.slug='dell-local' and p_server_principal->>'sponsoring_human_slug'='dell'))))) or
     actor_row.kind='system' or
     (expected_bundle='carr_authority' and
       (p_server_principal->>'authority_sponsor_slug' is null or
        p_server_principal->>'authority_sponsor_slug' not in ('joe','dell') or
        p_server_principal->>'authority_sponsor_slug' is distinct from
          p_server_principal->>'sponsoring_human_slug' or
        session_user is distinct from
          'carr_authority_'||(p_server_principal->>'authority_sponsor_slug') or
        (actor_row.kind='human' and actor_row.slug is distinct from
          p_server_principal->>'authority_sponsor_slug') or
        (actor_row.kind='automation' and
          (actor_row.slug not in ('codex','claude','joe-local','dell-local') or
           p_server_principal->'native_agent_verified' is distinct from 'true'::jsonb)))) or
     (expected_bundle<>'carr_authority' and
       p_server_principal->>'authority_sponsor_slug' is not null) then
    raise exception 'scac.refusal.identity_unverified: SIEP-18 actor kind, sponsor, or authority semantics mismatched';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-trusted-principal',0));
  select * into prior from ops.scac_trusted_principal_binding where idempotency_key=p_idempotency_key;
  if prior.binding_id is not null then
    if prior.principal_manifest<>manifest or prior.principal_digest<>principal_digest or
       prior.session_principal<>session_user or prior.backend_pid<>pg_backend_pid() or
       prior.transaction_id<>txid_current() then
      raise exception 'scac.refusal.replay: SIEP-18 trusted-principal idempotency mismatch'; end if;
    return jsonb_build_object('binding_id',prior.binding_id::text,
      'binding_digest',prior.binding_digest,'binding_state','current_source_test',
      'production_enforcement_active',false);
  end if;
  binding:=gen_random_uuid();
  binding_digest:=ops.scac_reference_monitor_sha256(jsonb_build_object(
    'schema_version','scac-trusted-principal-binding.v1','binding_id',binding::text,
    'principal_digest',principal_digest,'session_principal',session_user,
    'privilege_bundle',expected_bundle,'backend_pid',pg_backend_pid(),
    'transaction_id',txid_current(),'idempotency_key',p_idempotency_key::text));
  insert into ops.scac_trusted_principal_binding
    (binding_id,principal_manifest,principal_digest,actor_id,actor_slug,session_principal,
     privilege_bundle,backend_pid,transaction_id,binding_digest,idempotency_key,source_contract)
  values (binding,manifest,principal_digest,actor_row.id,actor_row.slug,session_user,
    expected_bundle,pg_backend_pid(),txid_current(),binding_digest,p_idempotency_key,
    'mcp-server/src/scac-exact-effects.js');
  return jsonb_build_object('binding_id',binding::text,'binding_digest',binding_digest,
    'binding_state','current_source_test','production_enforcement_active',false);
end $_$;


--
-- Name: scac_canonical_json(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_canonical_json(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare kind text:=jsonb_typeof(p_value); rendered text;
begin
  if kind='object' then
    select '{'||coalesce(string_agg(to_jsonb(key)::text||':'||ops.scac_canonical_json(value),',' order by key collate "C"),'')||'}' into rendered from jsonb_each(p_value);
    return rendered;
  elsif kind='array' then
    select '['||coalesce(string_agg(ops.scac_canonical_json(value),',' order by ordinal),'')||']' into rendered from jsonb_array_elements(p_value) with ordinality as a(value,ordinal);
    return rendered;
  end if;
  return p_value::text;
end $$;


--
-- Name: scac_capability_token_status(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_capability_token_status(p_token_ref_digest text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare t ops.scac_capability_token_receipt%rowtype; c ops.scac_pop_challenge%rowtype;
        control jsonb; revoked boolean:=false; token_state text; reason text;
begin
  control:=ops.scac_token_control_snapshot();
  select * into t from ops.scac_capability_token_receipt where token_ref_digest=p_token_ref_digest;
  if t.token_ref_digest is null then
    return jsonb_build_object('found',false,'token_state','missing','reason_id','scac.refusal.token_invalid',
      'kill_switch_state',control->>'kill_switch_state','revocation_state','clear',
      'admission_state','ineligible_pending_siep18','routing_eligible',false,
      'privileges_active',false,'production_enforcement_active',false);
  end if;
  select * into c from ops.scac_pop_challenge where challenge_id=t.challenge_id;
  select exists(select 1 from ops.scac_token_revocation_event r where
    (r.subject_kind='token' and r.subject_digest=t.token_ref_digest) or
    (r.subject_kind='challenge' and r.subject_digest=t.challenge_digest) or
    (r.subject_kind='device' and r.subject_digest=ops.scac_token_sha256_text(c.device_ref)) or
    (r.subject_kind='device_key' and r.subject_digest=c.device_key_digest) or
    (r.subject_kind='facts' and r.subject_digest=c.facts_digest) or
    (c.workload_digest is not null and r.subject_kind='workload' and r.subject_digest=c.workload_digest) or
    (r.subject_kind='issuer_key' and r.subject_digest=t.issuer_key_digest) or
    (r.subject_kind='root_event' and r.subject_digest=t.issuer_root_event_digest)) into revoked;
  if revoked then token_state:='revoked';
  elsif t.expires_at<=clock_timestamp() then token_state:='expired';
  else token_state:='valid'; end if;
  if control->>'kill_switch_state'='active' then reason:='scac.refusal.kill_switch';
  elsif revoked then reason:='scac.refusal.revoked';
  elsif token_state='expired' then reason:='scac.refusal.token_invalid';
  else reason:=null; end if;
  return jsonb_build_object('found',true,'token_ref_digest',t.token_ref_digest,
    'challenge_digest',t.challenge_digest,'token_state',token_state,'reason_id',reason,
    'kill_switch_state',control->>'kill_switch_state',
    'revocation_state',case when revoked then 'revoked' else 'clear' end,
    'cryptographic_state',t.cryptographic_state,
    'issuer_trust_state','unverified_pending_siep18_transaction_bridge',
    'admission_state','ineligible_pending_siep18','routing_eligible',false,
    'privileges_active',false,'production_enforcement_active',false);
end $$;


--
-- Name: scac_consume_verified_pop_challenge(uuid, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_consume_verified_pop_challenge(p_challenge_id uuid, p_challenge_digest text, p_nonce text, p_pop_verification_digest text, p_consume_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare c ops.scac_pop_challenge%rowtype; prior ops.scac_pop_challenge_consumption%rowtype;
        control jsonb; v_now timestamptz; consumption_hash text; inserted_id uuid;
begin
  if session_user<>'carr_jobs' then raise exception 'SIEP-17 challenge consumer role refused'; end if;
  if p_challenge_id is null or coalesce(p_challenge_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_pop_verification_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or p_consume_idempotency_key is null or p_nonce is null then
    raise exception 'SIEP-17 challenge consumption input malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep17-token-control',0));
  select * into c from ops.scac_pop_challenge where challenge_id=p_challenge_id for update;
  if c.challenge_id is null then raise exception 'scac.refusal.token_invalid: SIEP-17 challenge missing'; end if;
  control:=ops.scac_token_control_snapshot();
  if control->>'kill_switch_state'<>'inactive' then
    raise exception 'scac.refusal.kill_switch: SIEP-17 challenge consumption unavailable'; end if;
  v_now:=clock_timestamp();
  if c.expires_at<=v_now then raise exception 'scac.refusal.token_invalid: SIEP-17 challenge expired'; end if;
  if c.challenge_digest<>p_challenge_digest or encode(c.nonce_bytes,'base64')<>p_nonce or
     encode(decode(p_nonce,'base64'),'base64')<>p_nonce or
     c.nonce_digest<>'sha256:'||encode(public.digest(decode(p_nonce,'base64'),'sha256'),'hex') then
    raise exception 'scac.refusal.token_invalid: SIEP-17 challenge binding mismatch'; end if;
  if not exists(select 1 from ops.scac_policy_epoch pe where pe.epoch=c.policy_epoch
      and pe.epoch_digest=c.policy_epoch_digest and pe.epoch=(select max(epoch) from ops.scac_policy_epoch))
     or not exists(select 1 from ops.scac_device_enrollment e where e.device_ref=c.device_ref
      and e.device_key_digest=c.device_key_digest and e.facts_digest=c.facts_digest
      and e.policy_epoch=c.policy_epoch and e.policy_epoch_digest=c.policy_epoch_digest) then
    raise exception 'scac.refusal.token_invalid: SIEP-17 challenge policy or device is stale'; end if;
  if exists(select 1 from ops.scac_token_revocation_event r where
       (r.subject_kind='device' and r.subject_digest=ops.scac_token_sha256_text(c.device_ref)) or
       (r.subject_kind='device_key' and r.subject_digest=c.device_key_digest) or
       (r.subject_kind='facts' and r.subject_digest=c.facts_digest) or
       (c.workload_digest is not null and r.subject_kind='workload' and r.subject_digest=c.workload_digest) or
       (r.subject_kind='challenge' and r.subject_digest=c.challenge_digest)) then
    raise exception 'scac.refusal.revoked: SIEP-17 challenge subject revoked'; end if;
  select * into prior from ops.scac_pop_challenge_consumption where challenge_id=c.challenge_id;
  if prior.challenge_id is not null then
    if prior.consume_idempotency_key=p_consume_idempotency_key and
       prior.pop_verification_digest=p_pop_verification_digest and
       prior.challenge_digest=p_challenge_digest then
      return jsonb_build_object('challenge_digest',prior.challenge_digest,
        'consumption_digest',prior.consumption_digest,'token_intent_state',prior.token_intent_state,
        'token_state','missing','revocation_state','clear','kill_switch_state','inactive',
        'admission_state','ineligible_pending_siep18','routing_eligible',false,
        'privileges_active',false,'production_enforcement_active',false);
    end if;
    raise exception 'scac.refusal.token_invalid: SIEP-17 challenge replayed';
  end if;
  consumption_hash:=ops.scac_token_sha256_text(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-pop-challenge-consumption.v1','challenge_digest',c.challenge_digest,
    'pop_verification_digest',p_pop_verification_digest,
    'consume_idempotency_key',p_consume_idempotency_key::text)));
  insert into ops.scac_pop_challenge_consumption
    (challenge_id,challenge_digest,pop_verification_digest,consumption_digest,consume_idempotency_key)
  values (c.challenge_id,c.challenge_digest,p_pop_verification_digest,consumption_hash,p_consume_idempotency_key)
  on conflict (challenge_id) do nothing returning challenge_id into inserted_id;
  if inserted_id is null then raise exception 'scac.refusal.token_invalid: SIEP-17 challenge replayed'; end if;
  return jsonb_build_object('challenge_digest',c.challenge_digest,'consumption_digest',consumption_hash,
    'token_intent_state','eligible_for_external_signing_non_authorizing',
    'token_state','missing','revocation_state','clear','kill_switch_state','inactive',
    'admission_state','ineligible_pending_siep18','routing_eligible',false,
    'privileges_active',false,'production_enforcement_active',false);
end $_$;


--
-- Name: scac_device_benchmark_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_device_benchmark_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare e ops.scac_device_enrollment%rowtype; expected text;
begin
  select * into e from ops.scac_device_enrollment where device_ref=new.device_ref for key share;
  expected:=ops.scac_device_benchmark_payload_digest(new.benchmark_kind,new.device_ref,
    new.facts_digest,new.profile_digest,new.metrics_digest,new.passed,new.observed_at);
  if e.device_ref is null or not exists(select 1 from ops.scac_device_fact_receipt f
       where f.device_ref=new.device_ref and f.facts_digest=new.facts_digest) or
     new.facts_digest is distinct from e.facts_digest or new.receipt_digest is distinct from expected or
     new.signed_payload_digest is distinct from expected then
    raise exception 'SIEP-15 benchmark does not bind signed device facts and the reviewed profile';
  end if;
  return new;
end $$;


--
-- Name: scac_device_benchmark_payload_digest(text, text, text, text, text, boolean, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_device_benchmark_payload_digest(p_benchmark_kind text, p_device_ref text, p_facts_digest text, p_profile_digest text, p_metrics_digest text, p_passed boolean, p_observed_at text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-device-benchmark.v1','benchmark_kind',p_benchmark_kind,
    'device_ref',p_device_ref,'facts_digest',p_facts_digest,'profile_digest',p_profile_digest,
    'metrics_digest',p_metrics_digest,'passed',p_passed,'observed_at',p_observed_at)),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_device_enrollment_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_device_enrollment_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin raise exception 'SIEP-15 device enrollment facts are append-only'; end $$;


--
-- Name: scac_device_enrollment_status(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_device_enrollment_status(p_device_ref text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare e ops.scac_device_enrollment%rowtype; fact_count integer; benchmark_count integer;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-15 Joe Studio status authority refused';
  end if;
  select * into e from ops.scac_device_enrollment where device_ref=p_device_ref;
  if e.device_ref is null then
    return jsonb_build_object('found',false,'reason_id','scac.refusal.device_not_registered',
      'routing_eligible',false,'privileges_active',false,'production_enforcement_active',false);
  end if;
  select count(*) into fact_count from ops.scac_device_fact_receipt where device_ref=e.device_ref;
  select count(*) into benchmark_count from ops.scac_device_benchmark_receipt
    where device_ref=e.device_ref and passed and facts_digest=e.facts_digest;
  return jsonb_build_object('found',true,'device_ref',e.device_ref,'sponsor',e.sponsor,
    'profile_key',e.profile_key,'facts_digest',e.facts_digest,'enrollment_state',e.lifecycle_state,
    'cryptographic_device_state','external_verification_required','pop_state','pending_siep16',
    'benchmark_receipt_count',benchmark_count,'benchmark_receipt_required',9,
    'assurance_state',case when fact_count=1 and benchmark_count=9
      then 'structurally_complete_non_authorizing' else 'receipts_incomplete' end,
    'optional_non_blocking',true,'source_of_truth',false,'critical_dependency',false,
    'routing_eligible',false,'privileges_active',false,'production_enforcement_active',false);
end $$;


--
-- Name: scac_device_enrollment_truncate_guard(); Type: FUNCTION; Schema: ops; Owner: -
