--
-- Name: scac_mutation_catalog_v2_current(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_mutation_catalog_v2_current() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select exists(select 1 from ops.scac_mutation_registry_version
    where registry_version='scac-mutation-registry.v2'
      and registry_digest='sha256:6dc9f8353712e0f9ee9dcbc96d05b802631e420cfa698944c2b6401a11c6a9ff'
      and entry_count=1391 and source_entry_count=800)
$$;


--
-- Name: FUNCTION scac_mutation_catalog_v2_current(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.scac_mutation_catalog_v2_current() IS 'Historical v2 seal availability after v3; it is not a claim that the live catalog remains v2.';


