--
-- Name: scac_mutation_catalog_v3_current(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_mutation_catalog_v3_current() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select exists(select 1 from ops.scac_mutation_registry_version
    where registry_version='scac-mutation-registry.v3'
      and registry_digest='sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7'
      and entry_count=1395 and source_entry_count=800)
$$;


--
-- Name: FUNCTION scac_mutation_catalog_v3_current(); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.scac_mutation_catalog_v3_current() IS 'Historical v3 seal availability after v35; it is not a claim that the live catalog remains v3.';


