    raise exception 'sealed historical SCAC mutation registry is unavailable or corrupt';
  end if;
  registry_ok:=ops.scac_mutation_registration_v51('sha256:f41878345bfd9a4c6c55cb96362a22a401d8410747521df662d9e437f10dc51c','mcp-tool:standing-context');
