--
-- Name: scac_pop_challenge_digest(uuid, text, text, text, bigint, text, text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_pop_challenge_digest(p_challenge_id uuid, p_device_ref text, p_device_key_digest text, p_facts_digest text, p_policy_epoch bigint, p_policy_epoch_digest text, p_operation_manifest_digest text, p_nonce text, p_issued_at text, p_expires_at text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'domain','CARR-SCAC-POP-V1','schema_version','scac-pop-challenge.v1',
    'challenge_id',p_challenge_id::text,'device_ref',p_device_ref,
    'device_key_digest',p_device_key_digest,'facts_digest',p_facts_digest,
    'policy_epoch',p_policy_epoch,'policy_epoch_digest',p_policy_epoch_digest,
    'operation_manifest_digest',p_operation_manifest_digest,'nonce',p_nonce,
    'issued_at',p_issued_at,'expires_at',p_expires_at)),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_record_capability_token_receipt(text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_record_capability_token_receipt(p_challenge_digest text, p_token_ref_digest text, p_signed_payload_digest text, p_signature_digest text, p_issuer_key_digest text, p_issuer_root_event_digest text, p_external_verification_receipt_digest text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone, p_record_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare c ops.scac_pop_challenge%rowtype; prior ops.scac_capability_token_receipt%rowtype;
        control jsonb;
begin
  if session_user<>'carr_jobs' then raise exception 'SIEP-17 token receipt recorder role refused'; end if;
  if coalesce(p_challenge_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_token_ref_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_signed_payload_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_signature_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_issuer_key_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_issuer_root_event_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_external_verification_receipt_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or p_record_idempotency_key is null then raise exception 'SIEP-17 token receipt input malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep17-token-control',0));
  control:=ops.scac_token_control_snapshot();
  if control->>'kill_switch_state'<>'inactive' then
    raise exception 'scac.refusal.kill_switch: SIEP-17 token receipt unavailable'; end if;
  select * into prior from ops.scac_capability_token_receipt
    where record_idempotency_key=p_record_idempotency_key;
  if prior.token_ref_digest is not null then
    if prior.token_ref_digest<>p_token_ref_digest or prior.challenge_digest<>p_challenge_digest
       or prior.signed_payload_digest<>p_signed_payload_digest
       or prior.signature_digest<>p_signature_digest
       or prior.issuer_key_digest<>p_issuer_key_digest
       or prior.issuer_root_event_digest<>p_issuer_root_event_digest
       or prior.external_verification_receipt_digest<>p_external_verification_receipt_digest
       or prior.issued_at is distinct from p_issued_at
       or prior.expires_at is distinct from p_expires_at then
      raise exception 'SIEP-17 token receipt idempotency binding mismatch'; end if;
    return ops.scac_capability_token_status(prior.token_ref_digest);
  end if;
  select ch.* into c from ops.scac_pop_challenge ch join ops.scac_pop_challenge_consumption x
    on x.challenge_id=ch.challenge_id where ch.challenge_digest=p_challenge_digest for key share of ch;
  if c.challenge_id is null or p_issued_at<c.issued_at or p_issued_at>clock_timestamp()
     or p_expires_at<=clock_timestamp() or p_expires_at>p_issued_at+interval '5 minutes'
     or p_expires_at>c.expires_at then raise exception 'scac.refusal.token_invalid: SIEP-17 token time or challenge invalid'; end if;
  if exists(select 1 from ops.scac_token_revocation_event r where
       (r.subject_kind='device' and r.subject_digest=ops.scac_token_sha256_text(c.device_ref)) or
       (r.subject_kind='device_key' and r.subject_digest=c.device_key_digest) or
       (r.subject_kind='facts' and r.subject_digest=c.facts_digest) or
       (c.workload_digest is not null and r.subject_kind='workload' and r.subject_digest=c.workload_digest) or
       (r.subject_kind='challenge' and r.subject_digest=c.challenge_digest) or
       (r.subject_kind='token' and r.subject_digest=p_token_ref_digest) or
       (r.subject_kind='issuer_key' and r.subject_digest=p_issuer_key_digest) or
       (r.subject_kind='root_event' and r.subject_digest=p_issuer_root_event_digest)) then
    raise exception 'scac.refusal.revoked: SIEP-17 token receipt subject revoked'; end if;
  insert into ops.scac_capability_token_receipt
    (token_ref_digest,challenge_id,challenge_digest,signed_payload_digest,signature_digest,
     issuer_key_digest,issuer_root_event_digest,external_verification_receipt_digest,
     issued_at,expires_at,record_idempotency_key)
  values (p_token_ref_digest,c.challenge_id,p_challenge_digest,p_signed_payload_digest,p_signature_digest,
    p_issuer_key_digest,p_issuer_root_event_digest,p_external_verification_receipt_digest,
    p_issued_at,p_expires_at,p_record_idempotency_key);
  return ops.scac_capability_token_status(p_token_ref_digest);
end $_$;


--
-- Name: scac_record_token_verification_binding(text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_record_token_verification_binding(p_token_ref_digest text, p_token_payload jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare receipt ops.scac_capability_token_receipt%rowtype; c ops.scac_pop_challenge%rowtype;
        issuer ops.scac_token_issuer_binding%rowtype; prior ops.scac_token_verification_binding%rowtype;
        payload_digest text; binding_digest text; expected_keys constant text[]:=array[
          'challenge_digest','device_key_digest','device_ref','domain','environment','expires_at',
          'facts_digest','idempotency_digest','ingress_key','issued_at','issuer_key_digest',
          'issuer_root_event_digest','mutation_kind','operation_manifest_digest','policy_epoch',
          'policy_epoch_digest','principal_digest','registry_digest','registry_version',
          'request_digest','schema_version','target_surface','tenant_scope','token_id','workload_digest'];
begin
  if session_user<>'carr_jobs' then raise exception 'SIEP-18 token binding recorder role refused'; end if;
  if coalesce(p_token_ref_digest,'')!~'^sha256:[0-9a-f]{64}$' or p_idempotency_key is null or
     not ops.scac_json_has_exact_keys(p_token_payload,expected_keys) then
    raise exception 'SIEP-18 token verification binding malformed or open'; end if;
  payload_digest:=ops.scac_reference_monitor_sha256(p_token_payload);
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-reference-monitor',0));
  select * into prior from ops.scac_token_verification_binding where idempotency_key=p_idempotency_key;
  if prior.token_ref_digest is not null then
    if prior.token_ref_digest<>p_token_ref_digest or prior.token_payload_digest<>payload_digest then
      raise exception 'SIEP-18 token binding idempotency mismatch'; end if;
    return jsonb_build_object('token_ref_digest',prior.token_ref_digest,
      'verification_binding_digest',prior.verification_binding_digest,
      'binding_state','current_source_test','production_enforcement_active',false);
  end if;
  select * into receipt from ops.scac_capability_token_receipt
    where token_ref_digest=p_token_ref_digest for key share;
  select * into c from ops.scac_pop_challenge where challenge_id=receipt.challenge_id for key share;
  select * into issuer from ops.scac_token_issuer_binding
    where issuer_key_digest=receipt.issuer_key_digest for key share;
  if receipt.token_ref_digest is null or c.challenge_id is null or issuer.issuer_key_digest is null or
     receipt.signed_payload_digest<>payload_digest or
     p_token_payload->>'domain'<>'CARR-SCAC-TOKEN-V1' or
     p_token_payload->>'schema_version'<>'scac-capability-token.v1' or
     p_token_payload->>'tenant_scope'<>'carr-internal' or
     p_token_payload->>'environment'<>'source-test' or
     p_token_payload->>'challenge_digest'<>c.challenge_digest or
     p_token_payload->>'principal_digest'<>c.principal_digest or
     p_token_payload->>'device_ref'<>c.device_ref or
     p_token_payload->>'device_key_digest'<>c.device_key_digest or
     p_token_payload->>'facts_digest'<>c.facts_digest or
     (p_token_payload->>'workload_digest') is distinct from c.workload_digest or
     p_token_payload->>'registry_version'<>c.registry_version or
     p_token_payload->>'registry_digest'<>c.registry_digest or
     p_token_payload->>'ingress_key'<>c.ingress_key or
     p_token_payload->>'mutation_kind'<>c.mutation_kind or
     p_token_payload->>'target_surface'<>c.target_surface or
     (p_token_payload->>'policy_epoch')::bigint<>c.policy_epoch or
     p_token_payload->>'policy_epoch_digest'<>c.policy_epoch_digest or
     p_token_payload->>'operation_manifest_digest'<>c.operation_manifest_digest or
     p_token_payload->>'request_digest'<>c.request_digest or
     p_token_payload->>'idempotency_digest'<>c.idempotency_digest or
     p_token_payload->>'issuer_key_digest'<>receipt.issuer_key_digest or
     p_token_payload->>'issuer_root_event_digest'<>receipt.issuer_root_event_digest or
     (p_token_payload->>'issued_at')::timestamptz is distinct from receipt.issued_at or
     (p_token_payload->>'expires_at')::timestamptz is distinct from receipt.expires_at or
     issuer.issuer_root_event_digest<>receipt.issuer_root_event_digest then
    raise exception 'scac.refusal.token_invalid: SIEP-18 signed token binding mismatch';
  end if;
  binding_digest:=ops.scac_reference_monitor_sha256(jsonb_build_object(
    'schema_version','scac-token-verification-binding.v1','token_ref_digest',p_token_ref_digest,
    'token_payload_digest',payload_digest,'challenge_digest',c.challenge_digest,
    'issuer_key_digest',receipt.issuer_key_digest,
    'issuer_root_event_digest',receipt.issuer_root_event_digest));
  insert into ops.scac_token_verification_binding
    (token_ref_digest,token_payload,token_payload_digest,challenge_digest,
     issuer_key_digest,issuer_root_event_digest,verification_binding_digest,
     idempotency_key,verifier_contract)
  values (p_token_ref_digest,p_token_payload,payload_digest,c.challenge_digest,
    receipt.issuer_key_digest,receipt.issuer_root_event_digest,binding_digest,
    p_idempotency_key,'mcp-server/src/scac-token.js');
  return jsonb_build_object('token_ref_digest',p_token_ref_digest,
    'verification_binding_digest',binding_digest,'binding_state','current_source_test',
    'production_enforcement_active',false);
end $_$;


--
-- Name: scac_reference_monitor_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_reference_monitor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare mode_state jsonb; admission_text text; receipt ops.scac_reference_monitor_receipt%rowtype;
        bundle text; effect_key text; changed_ok boolean;
begin
  bundle:=ops.scac_runtime_privilege_bundle();
  mode_state:=ops.scac_reference_monitor_mode();
  if mode_state->>'mode'='shadow' and mode_state->>'integrity_state'<>'invalid_fail_closed' then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if mode_state->>'mode'<>'enforced_source_test' or
     mode_state->>'integrity_state'<>'valid_append_only_chain' then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 mode control invalid';
  end if;
  if bundle is null then
    if session_user in ('neondb_owner','carr_ci') then
      return case when tg_op='DELETE' then old else new end;
    end if;
    raise exception 'scac.refusal.identity_unverified: SIEP-18 unknown DML principal';
  end if;
  admission_text:=current_setting('carr.scac_admission_id',true);
  if coalesce(admission_text,'')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 admission missing';
  end if;
  select * into receipt from ops.scac_reference_monitor_receipt
    where admission_id=admission_text::uuid and backend_pid=pg_backend_pid()
      and transaction_id=txid_current() and session_principal=session_user;
  if receipt.admission_id is null then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 admission not current transaction';
  end if;
  effect_key:='db-relation-acl:'||tg_table_schema||'.'||tg_table_name||':'||
    bundle||':'||lower(tg_op);
  if effect_key=any(receipt.effect_keys) then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if tg_op='UPDATE' and tg_level='ROW' then
    select coalesce(bool_and(('db-column-acl:'||tg_table_schema||'.'||tg_table_name||'.'||k||':'||
      bundle||':update')=any(receipt.effect_keys)),false) into changed_ok
    from jsonb_object_keys(to_jsonb(new)) k where (to_jsonb(new)->k) is distinct from (to_jsonb(old)->k);
    if changed_ok then return new; end if;
  end if;
  raise exception 'scac.refusal.scope_violation: SIEP-18 effect % not admitted',effect_key;
end $_$;


--
-- Name: scac_reference_monitor_mode(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_reference_monitor_mode() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare r ops.scac_reference_monitor_mode_event%rowtype; expected bigint:=1;
        prior text:=null; expected_digest text; latest_mode text:='shadow'; latest_grant text:=null;
begin
  for r in select * from ops.scac_reference_monitor_mode_event order by event_no loop
    expected_digest:=ops.scac_reference_monitor_sha256(jsonb_build_object(
      'schema_version','scac-reference-monitor-mode-event.v1','event_no',r.event_no,
      'previous_event_digest',r.previous_event_digest,'mode',r.mode,
      'reason_digest',r.reason_digest,'grant_digest',r.grant_digest,
      'idempotency_key',r.idempotency_key::text,'recorded_by','joe'));
    if r.event_no<>expected or r.previous_event_digest is distinct from prior or
       r.event_digest is distinct from expected_digest or r.production_enforcement_active then
      return jsonb_build_object('mode','shadow','integrity_state','invalid_fail_closed',
        'latest_event_digest',prior,'production_enforcement_active',false);
    end if;
    prior:=r.event_digest; latest_mode:=r.mode; latest_grant:=r.grant_digest;
    expected:=expected+1;
  end loop;
  return jsonb_build_object('mode',latest_mode,
    'integrity_state',case when expected=1 then 'uninitialized_shadow' else 'valid_append_only_chain' end,
    'latest_event_digest',prior,'bound_grant_digest',latest_grant,
    'production_enforcement_active',false);
end $$;


--
-- Name: scac_reference_monitor_sha256(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_reference_monitor_sha256(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(
    convert_to(ops.scac_canonical_json(p_value),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_reference_monitor_state(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_reference_monitor_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare grant_snapshot jsonb; mode_state jsonb; epoch_chain jsonb;
        latest ops.scac_policy_epoch%rowtype;
        registry ops.scac_mutation_registry_version%rowtype; missing_guards integer;
        unsupported_writable integer;
        grant_state text; guard_state text;
begin
  grant_snapshot:=ops.scac_runtime_dml_grant_snapshot();
  mode_state:=ops.scac_reference_monitor_mode();
  epoch_chain:=ops.scac_policy_epoch_chain_state();
  select * into latest from ops.scac_policy_epoch order by epoch desc limit 1;
  select * into registry from ops.scac_mutation_registry_version
    where registry_version=latest.registry_version;
  grant_state:=case when registry.registry_version='scac-mutation-registry.v51' and
    (grant_snapshot->>'entry_count')::integer=312 and
    grant_snapshot->>'grant_digest'='sha256:f3a7344a4e690971141c39b207c2fd3410b12946f53130c67ee9679b5c7bf5e0'
    then 'current' else 'drifted_or_unbound' end;
  with recursive connected(oid) as (
    select oid from pg_roles where rolname in ('carr_writer','carr_jobs','carr_authority')
  ), writable as (
    select distinct c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
    where c.relkind in ('r','p') and a.grantee<>c.relowner
      and (a.grantee=0 or a.grantee in(select oid from connected))
      and a.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
    union
    select distinct c.oid from pg_attribute att join pg_class c on c.oid=att.attrelid
    cross join lateral aclexplode(att.attacl) a
    where c.relkind in ('r','p') and att.attnum>0 and not att.attisdropped
      and a.grantee<>c.relowner
      and (a.grantee=0 or a.grantee in(select oid from connected))
      and a.privilege_type in ('INSERT','UPDATE')
  )
  select count(*) into missing_guards from writable w where not exists(
    select 1 from pg_trigger t where t.tgrelid=w.oid and not t.tgisinternal
      and t.tgfoid='ops.scac_reference_monitor_guard()'::regprocedure
      and (t.tgtype & 1)=1);
  with runtime_roles as (
    select oid from pg_roles where rolname in ('carr_writer','carr_jobs','carr_authority')
  ), unsupported as (
    select distinct c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
    where n.nspname not in ('pg_catalog','information_schema') and
      c.relkind in ('v','m','f') and a.grantee<>c.relowner and
      (a.grantee=0 or a.grantee in(select oid from runtime_roles))
      and a.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
    union
    select distinct c.oid from pg_attribute att join pg_class c on c.oid=att.attrelid
    join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(att.attacl) a
    where n.nspname not in ('pg_catalog','information_schema') and
      c.relkind in ('v','m','f') and att.attnum>0 and not att.attisdropped and
      a.grantee<>c.relowner and
      (a.grantee=0 or a.grantee in(select oid from runtime_roles))
      and a.privilege_type in ('INSERT','UPDATE')
  ) select count(*) into unsupported_writable from unsupported;
  guard_state:=case when unsupported_writable>0 then 'unsupported_writable_relation'
    when missing_guards=0 then 'complete' else 'incomplete' end;
  return jsonb_build_object('schema_version','scac-reference-monitor-state.v1',
    'monitor_state',case when grant_state='current' and guard_state='complete'
      and coalesce((epoch_chain->>'valid')::boolean,false)
      and (epoch_chain->>'current_epoch')::bigint=latest.epoch
      and epoch_chain->>'current_epoch_digest'=latest.epoch_digest
      and mode_state->>'integrity_state'<>'invalid_fail_closed' then 'current'
      else 'unavailable' end,
    'grant_state',grant_state,'grant_digest',grant_snapshot->>'grant_digest',
    'guard_state',guard_state,'missing_guard_count',missing_guards,
    'unsupported_writable_relation_count',unsupported_writable,
    'mode',mode_state->>'mode','mode_integrity_state',mode_state->>'integrity_state',
    'policy_epoch_state',case when coalesce((epoch_chain->>'valid')::boolean,false)
      and (epoch_chain->>'current_epoch')::bigint=latest.epoch
      and epoch_chain->>'current_epoch_digest'=latest.epoch_digest
      then 'current' else 'invalid_or_unavailable' end,
    'policy_epoch',latest.epoch,'policy_epoch_digest',latest.epoch_digest,
    'registry_version',latest.registry_version,'registry_digest',latest.registry_digest,
    'direct_database_grant_cutover',false,'production_enforcement_active',false);
end $$;


--
-- Name: scac_register_exact_effect_contract(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_register_exact_effect_contract(p_registry_version text, p_ingress_key text, p_registry_entry_digest text, p_contract jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare re ops.scac_mutation_registry_entry%rowtype;
        prior ops.scac_exact_effect_contract%rowtype;
        normalized_effects jsonb; normalized_delegates jsonb; contract_digest text;
        resolved_registry_delegates jsonb; registry_delegates_exact boolean;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-18 exact-effect review authority is Joe-only'; end if;
  if coalesce(p_registry_version,'')!~'^scac-mutation-registry\.v[1-9][0-9]*$' or
     coalesce(p_ingress_key,'')!~'^[a-z][a-z0-9_-]+:' or p_ingress_key~E'[\n\r\t]' or
     char_length(p_ingress_key)>1000 or
     coalesce(p_registry_entry_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     p_idempotency_key is null or
     not ops.scac_json_has_exact_keys(p_contract,array['schema_version','ingress_key',
       'direct_effects','delegates_to','sql_state','integration_state']) or
     p_contract->>'schema_version'<>'scac-exact-effect-contract.v1' or
     p_contract->>'ingress_key'<>p_ingress_key or
     p_contract->>'sql_state'<>'static_reviewed' or
     p_contract->>'integration_state'<>'reviewed_source_test' or
     jsonb_typeof(p_contract->'direct_effects')<>'array' or
     jsonb_typeof(p_contract->'delegates_to')<>'array' then
    raise exception 'SIEP-18 exact-effect contract malformed or non-static';
  end if;
  -- This is the SQL spelling of scac-exact-effects.js effectKey(): kind,
  -- exact target, then the already-canonical finite column list.
  select coalesce(jsonb_agg(e order by (case when e->>'kind'='execute'
      then 'execute:'||coalesce(e->>'function_signature','')
      else coalesce(e->>'kind','')||':'||coalesce(e->>'relation','')||':'||
        coalesce((select string_agg(c,',' order by ord) from
          jsonb_array_elements_text(coalesce(e->'columns','[]'::jsonb))
          with ordinality as column_value(c,ord)),'') end) collate "C"),'[]'::jsonb)
    into normalized_effects from jsonb_array_elements(p_contract->'direct_effects') e;
  select coalesce(jsonb_agg(to_jsonb(d) order by d collate "C"),'[]'::jsonb)
    into normalized_delegates from jsonb_array_elements_text(p_contract->'delegates_to') d;
  if p_contract->'direct_effects'<>normalized_effects or
     (select count(*) from jsonb_array_elements(p_contract->'direct_effects'))<>
       (select count(distinct ops.scac_canonical_json(e)) from jsonb_array_elements(p_contract->'direct_effects') e) or
     p_contract->'delegates_to'<>normalized_delegates or
     (select count(*) from jsonb_array_elements_text(p_contract->'delegates_to'))<>
       (select count(distinct d) from jsonb_array_elements_text(p_contract->'delegates_to') d) or
     exists(select 1 from jsonb_array_elements_text(p_contract->'delegates_to') d
       where d!~'^[a-z][a-z0-9_-]+:' or d~E'[\n\r\t*]' or char_length(d)>1000) or
     (jsonb_array_length(p_contract->'direct_effects')=0 and
      jsonb_array_length(p_contract->'delegates_to')=0) then
    raise exception 'SIEP-18 exact-effect contract is empty, duplicate, wildcard, or non-canonical';
  end if;
  if exists(
    select 1 from jsonb_array_elements(p_contract->'direct_effects') e where
      case e->>'kind'
        when 'execute' then
          not ops.scac_json_has_exact_keys(e,array['kind','function_signature']) or
          coalesce(e->>'function_signature','')!~'^[a-z_][a-z0-9_$]*\.[a-z_][a-z0-9_$]*\([^;\n\r]*\)$'
        when 'insert' then
          not ops.scac_json_has_exact_keys(e,array['kind','relation','columns']) or
          coalesce(e->>'relation','')!~'^[a-z_][a-z0-9_$]*\.[a-z_][a-z0-9_$]*$' or
          jsonb_typeof(e->'columns')<>'array' or jsonb_array_length(e->'columns')=0 or
          exists(select 1 from jsonb_array_elements_text(e->'columns') c where c!~'^[a-z_][a-z0-9_$]*$') or
          (select jsonb_agg(to_jsonb(c) order by c collate "C") from jsonb_array_elements_text(e->'columns') c)<>e->'columns' or
          (select count(*) from jsonb_array_elements_text(e->'columns'))<>(select count(distinct c) from jsonb_array_elements_text(e->'columns') c)
        when 'update' then
          not ops.scac_json_has_exact_keys(e,array['kind','relation','columns']) or
          coalesce(e->>'relation','')!~'^[a-z_][a-z0-9_$]*\.[a-z_][a-z0-9_$]*$' or
          jsonb_typeof(e->'columns')<>'array' or jsonb_array_length(e->'columns')=0 or
          exists(select 1 from jsonb_array_elements_text(e->'columns') c where c!~'^[a-z_][a-z0-9_$]*$') or
          (select jsonb_agg(to_jsonb(c) order by c collate "C") from jsonb_array_elements_text(e->'columns') c)<>e->'columns' or
          (select count(*) from jsonb_array_elements_text(e->'columns'))<>(select count(distinct c) from jsonb_array_elements_text(e->'columns') c)
        when 'delete' then
          not ops.scac_json_has_exact_keys(e,array['kind','relation','columns']) or
          coalesce(e->>'relation','')!~'^[a-z_][a-z0-9_$]*\.[a-z_][a-z0-9_$]*$' or
          jsonb_typeof(e->'columns')<>'array' or jsonb_array_length(e->'columns')=0 or
          exists(select 1 from jsonb_array_elements_text(e->'columns') c where c!~'^[a-z_][a-z0-9_$]*$') or
          (select jsonb_agg(to_jsonb(c) order by c collate "C") from jsonb_array_elements_text(e->'columns') c)<>e->'columns' or
          (select count(*) from jsonb_array_elements_text(e->'columns'))<>(select count(distinct c) from jsonb_array_elements_text(e->'columns') c)
        else true end
  ) then raise exception 'SIEP-18 exact effect target or finite column set malformed'; end if;
  select * into re from ops.scac_mutation_registry_entry
    where registry_version=p_registry_version and ingress_key=p_ingress_key for key share;
  if re.ingress_key is null or re.entry_digest<>p_registry_entry_digest or
     re.effect_class='read_only' or
     coalesce((re.contract->>'classification_authorizing')::boolean,true) then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 registry/effect contract mismatch';
  end if;
  -- Registry delegates are sealed operation names; exact-effect contracts use
  -- full ingress keys. Resolve each name through the same sealed version and
  -- require exactly one candidate. Prefix guessing and wildcard expansion are
  -- forbidden, so cross-surface edges stay explicit and ambiguity stays deny.
  with raw(d) as (
    select value from jsonb_array_elements_text(coalesce(re.contract->'delegates_to','[]'::jsonb))
  ), candidates as (
    select raw.d,array_agg(de.ingress_key order by de.ingress_key collate "C") keys
      from raw left join ops.scac_mutation_registry_entry de
        on de.registry_version=p_registry_version and
          (de.ingress_key=raw.d or de.contract->>'operation'=raw.d)
     group by raw.d
  )
  select coalesce(jsonb_agg(to_jsonb(keys[1]) order by keys[1] collate "C"),'[]'::jsonb),
         coalesce(bool_and(cardinality(keys)=1),true)
    into resolved_registry_delegates,registry_delegates_exact from candidates;
  if not registry_delegates_exact or
     resolved_registry_delegates<>p_contract->'delegates_to' then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 registry/effect delegate mismatch';
  end if;
  contract_digest:=ops.scac_reference_monitor_sha256(p_contract);
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-exact-effects',0));
  select * into prior from ops.scac_exact_effect_contract where idempotency_key=p_idempotency_key;
  if prior.contract_digest is not null then
    if prior.registry_version<>p_registry_version or prior.ingress_key<>p_ingress_key or
       prior.registry_entry_digest<>p_registry_entry_digest or prior.contract<>p_contract then
      raise exception 'SIEP-18 exact-effect idempotency mismatch'; end if;
    return jsonb_build_object('contract_digest',prior.contract_digest,
      'contract_state','reviewed_source_test','production_enforcement_active',false);
  end if;
  insert into ops.scac_exact_effect_contract
    (registry_version,ingress_key,registry_entry_digest,contract,contract_digest,
     idempotency_key,recorded_by)
  values (p_registry_version,p_ingress_key,p_registry_entry_digest,p_contract,
    contract_digest,p_idempotency_key,'joe');
  return jsonb_build_object('contract_digest',contract_digest,
    'contract_state','reviewed_source_test','production_enforcement_active',false);
end $_$;


--
-- Name: scac_register_operation_effect_binding(text, text, text, text, text[], uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_register_operation_effect_binding(p_registry_version text, p_ingress_key text, p_privilege_bundle text, p_registry_entry_digest text, p_effect_keys text[], p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare re ops.scac_mutation_registry_entry%rowtype;
        prior ops.scac_operation_effect_binding%rowtype;
        effects text[]; effect_digest text; next_digest text;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-18 operation-effect binding authority is Joe-only'; end if;
  select array_agg(value order by value collate "C") into effects from unnest(p_effect_keys) value;
  if coalesce(p_registry_version,'')!~'^scac-mutation-registry\.v[1-9][0-9]*$' or
     coalesce(p_ingress_key,'')!~'^[a-z][a-z0-9_-]+:' or p_ingress_key~E'[\n\r\t]' or
     char_length(p_ingress_key)>1000 or
     p_privilege_bundle not in ('carr_writer','carr_jobs','carr_authority') or
     coalesce(p_registry_entry_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     p_idempotency_key is null or effects is null or cardinality(effects)=0 or
     cardinality(effects)<>(select count(distinct x) from unnest(effects) x) or
     exists(select 1 from unnest(effects) x where
       x!~'^db-relation-acl:[^:]+:[a-z_]+:(insert|update|delete|truncate)$'
       and x!~'^db-column-acl:[^:]+:[a-z_]+:update$') then
    raise exception 'SIEP-18 operation-effect binding malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-reference-monitor',0));
  select * into prior from ops.scac_operation_effect_binding
    where idempotency_key=p_idempotency_key;
  if prior.binding_digest is not null then
    if prior.registry_version<>p_registry_version or prior.ingress_key<>p_ingress_key or
       prior.privilege_bundle<>p_privilege_bundle or
       prior.registry_entry_digest<>p_registry_entry_digest or
       prior.effect_keys is distinct from effects then
      raise exception 'SIEP-18 operation-effect binding idempotency mismatch'; end if;
    return jsonb_build_object('binding_digest',prior.binding_digest,
      'effect_set_digest',prior.effect_set_digest,'binding_state','current_source_test',
      'production_enforcement_active',false);
  end if;
  select * into re from ops.scac_mutation_registry_entry
    where registry_version=p_registry_version and ingress_key=p_ingress_key for key share;
  if re.ingress_key is null or re.entry_digest<>p_registry_entry_digest or
     re.effect_class='read_only' or
     coalesce((re.contract->>'classification_authorizing')::boolean,true) then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 logical operation unavailable';
  end if;
  if exists(select 1 from unnest(effects) x where not exists(
       select 1 from ops.scac_mutation_registry_entry xre
       where xre.registry_version=p_registry_version and xre.ingress_key=x
         and xre.ingress_kind in ('db_relation_acl','db_column_acl')
         and xre.contract->>'grantee'=p_privilege_bundle
         and ((xre.ingress_kind='db_relation_acl' and
               xre.contract->>'privilege' in ('insert','update','delete','truncate')) or
              (xre.ingress_kind='db_column_acl' and
               xre.contract->>'privilege'='update')))) then
    raise exception 'scac.refusal.mutation_unregistered: SIEP-18 effect is not a current exact grant';
  end if;
  effect_digest:=ops.scac_reference_monitor_sha256(to_jsonb(effects));
  next_digest:=ops.scac_reference_monitor_sha256(jsonb_build_object(
    'schema_version','scac-operation-effect-binding.v1',
    'registry_version',p_registry_version,'ingress_key',p_ingress_key,
    'privilege_bundle',p_privilege_bundle,'registry_entry_digest',p_registry_entry_digest,
    'effect_keys',to_jsonb(effects),'effect_set_digest',effect_digest,
    'idempotency_key',p_idempotency_key::text,'recorded_by','joe'));
  insert into ops.scac_operation_effect_binding
    (registry_version,ingress_key,privilege_bundle,registry_entry_digest,effect_keys,
     effect_set_digest,binding_digest,idempotency_key,recorded_by)
  values (p_registry_version,p_ingress_key,p_privilege_bundle,p_registry_entry_digest,
    effects,effect_digest,next_digest,p_idempotency_key,'joe');
  return jsonb_build_object('binding_digest',next_digest,'effect_set_digest',effect_digest,
    'binding_state','current_source_test','production_enforcement_active',false);
end $_$;


--
-- Name: scac_register_token_issuer_binding(text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_register_token_issuer_binding(p_issuer_key_digest text, p_issuer_root_event_digest text, p_certification_receipt_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare root_state jsonb; prior ops.scac_token_issuer_binding%rowtype;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-18 issuer binding authority is Joe-only';
  end if;
  if coalesce(p_issuer_key_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     coalesce(p_issuer_root_event_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     coalesce(p_certification_receipt_digest,'')!~'^sha256:[0-9a-f]{64}$' or
     p_idempotency_key is null then raise exception 'SIEP-18 issuer binding input malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-reference-monitor',0));
  select * into prior from ops.scac_token_issuer_binding where idempotency_key=p_idempotency_key;
  if prior.issuer_key_digest is not null then
    if prior.issuer_key_digest<>p_issuer_key_digest or
       prior.issuer_root_event_digest<>p_issuer_root_event_digest or
       prior.certification_receipt_digest<>p_certification_receipt_digest then
      raise exception 'SIEP-18 issuer binding idempotency mismatch'; end if;
    return jsonb_build_object('issuer_key_digest',prior.issuer_key_digest,
      'issuer_root_event_digest',prior.issuer_root_event_digest,
      'binding_state',prior.binding_state,'production_enforcement_active',false);
  end if;
  root_state:=ops.scac_root_trust_chain_state();
  if coalesce((root_state->>'structurally_valid')::boolean,false) is not true or
     root_state->>'latest_event_digest'<>p_issuer_root_event_digest or
     root_state->>'active_key_digest' is null then
    raise exception 'scac.refusal.root_untrusted: SIEP-18 current root event unavailable';
  end if;
  if root_state->>'active_key_digest'=p_issuer_key_digest then
    raise exception 'SIEP-18 offline root key cannot be the online token issuer';
  end if;
  insert into ops.scac_token_issuer_binding
    (issuer_key_digest,issuer_root_event_digest,certification_receipt_digest,
     idempotency_key,recorded_by)
  values (p_issuer_key_digest,p_issuer_root_event_digest,p_certification_receipt_digest,
    p_idempotency_key,'joe');
  return jsonb_build_object('issuer_key_digest',p_issuer_key_digest,
    'issuer_root_event_digest',p_issuer_root_event_digest,
    'binding_state','source_test_current','production_enforcement_active',false);
end $_$;


--
-- Name: scac_revoke_token_subject(text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_revoke_token_subject(p_subject_kind text, p_subject_digest text, p_reason_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare prior ops.scac_token_revocation_event%rowtype; inserted_id uuid;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-17 revocation authority is Joe-only';
  end if;
  if p_subject_kind not in ('device','device_key','facts','workload','challenge','token','issuer_key','root_event')
     or coalesce(p_subject_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or coalesce(p_reason_digest,'')!~'^sha256:[0-9a-f]{64}$' or p_idempotency_key is null then
    raise exception 'SIEP-17 revocation input malformed';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep17-token-control',0));
  select * into prior from ops.scac_token_revocation_event where idempotency_key=p_idempotency_key;
  if prior.event_id is not null then
    if prior.subject_kind is distinct from p_subject_kind or prior.subject_digest is distinct from p_subject_digest
       or prior.reason_digest is distinct from p_reason_digest then
      raise exception 'SIEP-17 revocation idempotency binding mismatch';
    end if;
    return jsonb_build_object('revocation_state','revoked','subject_kind',prior.subject_kind,
      'subject_digest',prior.subject_digest,'reason_id','scac.refusal.revoked',
      'admission_state','ineligible_pending_siep18','production_enforcement_active',false);
  end if;
  insert into ops.scac_token_revocation_event
    (subject_kind,subject_digest,reason_digest,idempotency_key,recorded_by)
  values (p_subject_kind,p_subject_digest,p_reason_digest,p_idempotency_key,'joe')
  on conflict (subject_kind,subject_digest) do nothing returning event_id into inserted_id;
  if inserted_id is null then
    raise exception 'SIEP-17 revocation subject already bound to a different idempotency key';
  end if;
  return jsonb_build_object('revocation_state','revoked','subject_kind',p_subject_kind,
    'subject_digest',p_subject_digest,'reason_id','scac.refusal.revoked',
    'admission_state','ineligible_pending_siep18','production_enforcement_active',false);
end $_$;


--
-- Name: scac_root_attestation_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_attestation_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare e ops.scac_root_trust_event%rowtype; expected_payload text;
begin
  select * into e from ops.scac_root_trust_event where event_digest=new.event_digest;
  expected_payload:=ops.scac_root_trust_event_statement_digest(e.event_no,e.previous_event_digest,e.action,
    e.subject_key_digest,e.replacement_key_digest,e.threshold,e.custodian_set_digest,
    e.recovery_receipt_digest,e.policy_epoch,e.policy_epoch_digest);
  if e.event_digest is null or new.signed_payload_digest is distinct from expected_payload or
     not (new.signature_digest=any(e.custodian_approval_digests)) or
     not exists(select 1 from ops.scac_root_custodian_set_member m
                where m.custodian_set_digest=e.custodian_set_digest
                  and m.custodian_key_digest=new.custodian_key_digest) then
    raise exception 'SIEP-14 custodian attestation does not bind the ceremony';
  end if;
  return new;
end $$;


--
-- Name: scac_root_custodian_set_digest(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_custodian_set_digest(p_custodian_key_digests text[]) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-root-custodian-set.v1',
    'custodian_key_digests',to_jsonb(p_custodian_key_digests))),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_root_trust_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin raise exception 'SIEP-14 root trust facts are append-only'; end $$;


--
-- Name: scac_root_trust_chain_state(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_chain_state() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare r ops.scac_root_trust_event%rowtype; expected bigint:=1; prior text:=null; active_key text:=null;
        expected_digest text; sorted_digests text[]; recorded_digests text[]; recorded_keys text[];
        reviewed_keys text[]; expected_custodian_set text:=null; reviewed_custodian_set text;
        expected_threshold integer:=null;
begin
  for r in select * from ops.scac_root_trust_event order by event_no loop
    select array_agg(v order by v) into sorted_digests from unnest(r.custodian_approval_digests) v;
    select array_agg(signature_digest order by signature_digest) into recorded_digests
      from ops.scac_root_custodian_attestation where event_digest=r.event_digest;
    select array_agg(custodian_key_digest order by custodian_key_digest) into recorded_keys
      from ops.scac_root_custodian_attestation where event_digest=r.event_digest;
    select array_agg(custodian_key_digest order by custodian_key_digest) into reviewed_keys
      from ops.scac_root_custodian_set_member where custodian_set_digest=r.custodian_set_digest;
    reviewed_custodian_set:=case when reviewed_keys is null then null else ops.scac_root_custodian_set_digest(reviewed_keys) end;
    expected_digest:=ops.scac_root_trust_event_digest(r.event_no,r.previous_event_digest,r.action,
      r.subject_key_digest,r.replacement_key_digest,r.threshold,r.custodian_set_digest,sorted_digests,
      r.recovery_receipt_digest,r.policy_epoch,r.policy_epoch_digest);
    if r.event_no<>expected or r.previous_event_digest is distinct from prior or
       r.event_digest is distinct from expected_digest or sorted_digests is distinct from r.custodian_approval_digests or
       cardinality(sorted_digests)<>(select count(distinct v) from unnest(sorted_digests) v) or
       cardinality(sorted_digests)<r.threshold or recorded_digests is distinct from sorted_digests or
       cardinality(recorded_keys)<r.threshold or reviewed_custodian_set is distinct from r.custodian_set_digest or
       exists(select 1 from unnest(recorded_keys) k where not (k=any(reviewed_keys))) or
       (expected_custodian_set is not null and r.custodian_set_digest is distinct from expected_custodian_set) or
       (expected_threshold is not null and r.threshold is distinct from expected_threshold) or
       r.production_trust_active then
      return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_chain_gap_fork_digest_or_quorum',
        'cryptographic_quorum_state','external_verification_required');
    end if;
    expected_custodian_set:=r.custodian_set_digest;
    expected_threshold:=r.threshold;
    if r.action='establish' then
      if expected<>1 or active_key is not null then return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_transition_invalid'); end if;
      active_key:=r.subject_key_digest;
    elsif r.action='rotate' then
      if active_key is distinct from r.subject_key_digest then return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_transition_invalid'); end if;
      active_key:=r.replacement_key_digest;
    elsif r.action='revoke' then
      if active_key is distinct from r.subject_key_digest then return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_transition_invalid'); end if;
      active_key:=null;
    elsif active_key is distinct from r.subject_key_digest then
      return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_transition_invalid');
    end if;
    prior:=r.event_digest; expected:=expected+1;
  end loop;
  if expected=1 then return jsonb_build_object('valid',false,'structurally_valid',false,'reason','root_chain_unavailable'); end if;
  return jsonb_build_object('valid',false,'structurally_valid',true,
    'reason','structurally_valid_external_crypto_required','cryptographic_quorum_state','external_verification_required',
    'active_key_digest',active_key,
    'latest_event_no',expected-1,'latest_event_digest',prior,
    'root_trust_operational',false,'production_enforcement_active',false);
end $$;


--
-- Name: scac_root_trust_event_digest(bigint, text, text, text, text, integer, text, text[], text, bigint, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_event_digest(p_event_no bigint, p_previous_event_digest text, p_action text, p_subject_key_digest text, p_replacement_key_digest text, p_threshold integer, p_custodian_set_digest text, p_custodian_approval_digests text[], p_recovery_receipt_digest text, p_policy_epoch bigint, p_policy_epoch_digest text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-root-trust-event.v1','event_no',p_event_no,
    'previous_event_digest',p_previous_event_digest,'action',p_action,
    'subject_key_digest',p_subject_key_digest,'replacement_key_digest',p_replacement_key_digest,
    'threshold',p_threshold,'custodian_set_digest',p_custodian_set_digest,
    'recovery_receipt_digest',p_recovery_receipt_digest,
    'policy_epoch',p_policy_epoch,'policy_epoch_digest',p_policy_epoch_digest,
    'custodian_approval_digests',to_jsonb(p_custodian_approval_digests))),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_root_trust_event_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_event_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare tip ops.scac_root_trust_event%rowtype; state jsonb; sorted_digests text[]; expected_digest text;
        reviewed_keys text[]; reviewed_custodian_set text;
begin
  lock table ops.scac_root_trust_event in share row exclusive mode;
  select * into tip from ops.scac_root_trust_event order by event_no desc limit 1;
  if (tip.event_no is null and (new.event_no<>1 or new.previous_event_digest is not null)) or
     (tip.event_no is not null and (new.event_no<>tip.event_no+1 or new.previous_event_digest is distinct from tip.event_digest)) then
    raise exception 'SIEP-14 root ceremony gap or fork';
  end if;
  select array_agg(v order by v) into sorted_digests from unnest(new.custodian_approval_digests) v;
  if sorted_digests is distinct from new.custodian_approval_digests or
     cardinality(sorted_digests)<>(select count(distinct v) from unnest(sorted_digests) v) then
    raise exception 'SIEP-14 custodian approvals must be distinct and sorted';
  end if;
  select array_agg(custodian_key_digest order by custodian_key_digest) into reviewed_keys
    from ops.scac_root_custodian_set_member where custodian_set_digest=new.custodian_set_digest;
  reviewed_custodian_set:=case when reviewed_keys is null then null else ops.scac_root_custodian_set_digest(reviewed_keys) end;
  if reviewed_custodian_set is distinct from new.custodian_set_digest or cardinality(reviewed_keys)<new.threshold then
    raise exception 'SIEP-14 reviewed custodian set is unavailable, drifted, or below threshold';
  end if;
  expected_digest:=ops.scac_root_trust_event_digest(new.event_no,new.previous_event_digest,new.action,
    new.subject_key_digest,new.replacement_key_digest,new.threshold,new.custodian_set_digest,sorted_digests,
    new.recovery_receipt_digest,new.policy_epoch,new.policy_epoch_digest);
  if new.event_digest is distinct from expected_digest then raise exception 'SIEP-14 root ceremony digest mismatch'; end if;
  if not exists(select 1 from ops.scac_policy_epoch where epoch=new.policy_epoch and epoch_digest=new.policy_epoch_digest)
     then raise exception 'SIEP-14 policy epoch unavailable'; end if;
  state:=ops.scac_root_trust_chain_state();
  if tip.event_no is not null and coalesce((state->>'structurally_valid')::boolean,false) is not true
     then raise exception 'SIEP-14 prior root chain invalid'; end if;
  if new.action='establish' and tip.event_no is not null then raise exception 'SIEP-14 duplicate root establishment'; end if;
  if tip.event_no is not null and new.custodian_set_digest is distinct from tip.custodian_set_digest
     then raise exception 'SIEP-14 custodian set is not the reviewed chain set'; end if;
  if tip.event_no is not null and new.threshold is distinct from tip.threshold
     then raise exception 'SIEP-14 custodian threshold is not the established chain threshold'; end if;
  if new.action<>'establish' and (state->>'active_key_digest') is distinct from new.subject_key_digest
     then raise exception 'SIEP-14 ceremony subject is not the current root'; end if;
  return new;
end $$;


--
-- Name: scac_root_trust_event_statement_digest(bigint, text, text, text, text, integer, text, text, bigint, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_event_statement_digest(p_event_no bigint, p_previous_event_digest text, p_action text, p_subject_key_digest text, p_replacement_key_digest text, p_threshold integer, p_custodian_set_digest text, p_recovery_receipt_digest text, p_policy_epoch bigint, p_policy_epoch_digest text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-root-trust-event.v1','event_no',p_event_no,
    'previous_event_digest',p_previous_event_digest,'action',p_action,
    'subject_key_digest',p_subject_key_digest,'replacement_key_digest',p_replacement_key_digest,
    'threshold',p_threshold,'custodian_set_digest',p_custodian_set_digest,
    'recovery_receipt_digest',p_recovery_receipt_digest,
    'policy_epoch',p_policy_epoch,'policy_epoch_digest',p_policy_epoch_digest)),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_root_trust_truncate_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_root_trust_truncate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
