--
-- Name: scac_token_control_snapshot(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_token_control_snapshot() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare e ops.scac_token_kill_switch_event%rowtype; expected_no bigint:=1; prior text:=null;
        expected_digest text; latest_action text:=null;
begin
  for e in select * from ops.scac_token_kill_switch_event order by event_no loop
    expected_digest:=ops.scac_token_kill_event_digest(e.event_no,e.previous_event_digest,
      e.action,e.reason_digest,e.idempotency_key);
    if e.event_no<>expected_no or e.previous_event_digest is distinct from prior or
       e.event_digest is distinct from expected_digest or e.production_enforcement_active then
      return jsonb_build_object('schema_version','siep17-token-control-snapshot.v1',
        'kill_switch_state','active','reason_id','scac.refusal.kill_switch',
        'control_integrity_state','invalid_fail_closed','latest_event_digest',prior,
        'admission_state','ineligible_pending_siep18','production_enforcement_active',false);
    end if;
    prior:=e.event_digest; latest_action:=e.action; expected_no:=expected_no+1;
  end loop;
  if expected_no=1 then
    return jsonb_build_object('schema_version','siep17-token-control-snapshot.v1',
      'kill_switch_state','active','reason_id','scac.refusal.kill_switch',
      'control_integrity_state','uninitialized_fail_closed','latest_event_digest',null,
      'admission_state','ineligible_pending_siep18','production_enforcement_active',false);
  end if;
  return jsonb_build_object('schema_version','siep17-token-control-snapshot.v1',
    'kill_switch_state',case when latest_action='release' then 'inactive' else 'active' end,
    'reason_id',case when latest_action='release' then null else 'scac.refusal.kill_switch' end,
    'control_integrity_state','valid_append_only_chain','latest_event_digest',prior,
    'admission_state','ineligible_pending_siep18','production_enforcement_active',false);
end $$;


--
-- Name: scac_token_kill_event_digest(bigint, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_token_kill_event_digest(p_event_no bigint, p_previous_event_digest text, p_action text, p_reason_digest text, p_idempotency_key uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
    'schema_version','scac-token-kill-switch-event.v1','event_no',p_event_no,
    'previous_event_digest',p_previous_event_digest,'action',p_action,
    'reason_digest',p_reason_digest,'idempotency_key',p_idempotency_key::text,
    'recorded_by','joe')),'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_token_sha256_text(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_token_sha256_text(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(convert_to(p_value,'UTF8'),'sha256'),'hex')
$$;


--
-- Name: scac_transition_reference_monitor_mode(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_transition_reference_monitor_mode(p_mode text, p_reason_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare tip ops.scac_reference_monitor_mode_event%rowtype; prior ops.scac_reference_monitor_mode_event%rowtype;
        state jsonb; next_no bigint; next_digest text;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-18 monitor mode authority is Joe-only'; end if;
  if p_mode not in ('shadow','enforced_source_test') or
     coalesce(p_reason_digest,'')!~'^sha256:[0-9a-f]{64}$' or p_idempotency_key is null then
    raise exception 'SIEP-18 monitor mode input malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep18-reference-monitor',0));
  select * into prior from ops.scac_reference_monitor_mode_event where idempotency_key=p_idempotency_key;
  if prior.event_no is not null then
    if prior.mode<>p_mode or prior.reason_digest<>p_reason_digest then
      raise exception 'SIEP-18 monitor mode idempotency mismatch'; end if;
    return ops.scac_reference_monitor_mode();
  end if;
  state:=ops.scac_reference_monitor_state();
  if p_mode='enforced_source_test' and
     (state->>'grant_state'<>'current' or state->>'guard_state'<>'complete') then
    raise exception 'scac.refusal.reference_monitor_unavailable: SIEP-18 cannot enforce stale grants'; end if;
  select * into tip from ops.scac_reference_monitor_mode_event order by event_no desc limit 1;
  if coalesce(tip.mode,'shadow')=p_mode then raise exception 'SIEP-18 mode transition must change state'; end if;
  next_no:=coalesce(tip.event_no,0)+1;
  next_digest:=ops.scac_reference_monitor_sha256(jsonb_build_object(
    'schema_version','scac-reference-monitor-mode-event.v1','event_no',next_no,
    'previous_event_digest',tip.event_digest,'mode',p_mode,'reason_digest',p_reason_digest,
    'grant_digest',state->>'grant_digest','idempotency_key',p_idempotency_key::text,
    'recorded_by','joe'));
  insert into ops.scac_reference_monitor_mode_event
    (event_no,event_digest,previous_event_digest,mode,reason_digest,grant_digest,
     idempotency_key,recorded_by)
  values (next_no,next_digest,tip.event_digest,p_mode,p_reason_digest,state->>'grant_digest',
    p_idempotency_key,'joe');
  return ops.scac_reference_monitor_mode();
end $_$;


--
-- Name: scac_transition_token_kill_switch(text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.scac_transition_token_kill_switch(p_action text, p_reason_digest text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $_$
declare tip ops.scac_token_kill_switch_event%rowtype; prior ops.scac_token_kill_switch_event%rowtype;
        next_no bigint; next_digest text;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP-17 global kill-switch authority is Joe-only';
  end if;
  if p_action not in ('engage','release') or coalesce(p_reason_digest,'')!~'^sha256:[0-9a-f]{64}$'
     or p_idempotency_key is null then raise exception 'SIEP-17 kill-switch input malformed'; end if;
  perform pg_advisory_xact_lock(hashtextextended('carr-siep17-token-control',0));
  select * into prior from ops.scac_token_kill_switch_event where idempotency_key=p_idempotency_key;
  if prior.event_no is not null then
    if prior.action is distinct from p_action or prior.reason_digest is distinct from p_reason_digest then
      raise exception 'SIEP-17 kill-switch idempotency binding mismatch';
    end if;
    return ops.scac_token_control_snapshot();
  end if;
  select * into tip from ops.scac_token_kill_switch_event order by event_no desc limit 1;
  if tip.event_no is not null and
     ((tip.action='release' and p_action='release') or (tip.action='engage' and p_action='engage')) then
    raise exception 'SIEP-17 kill-switch transition must change current state';
  end if;
  next_no:=coalesce(tip.event_no,0)+1;
  next_digest:=ops.scac_token_kill_event_digest(next_no,tip.event_digest,p_action,
    p_reason_digest,p_idempotency_key);
  insert into ops.scac_token_kill_switch_event
    (event_no,event_digest,previous_event_digest,action,reason_digest,idempotency_key,recorded_by)
  values (next_no,next_digest,tip.event_digest,p_action,p_reason_digest,p_idempotency_key,'joe');
  return ops.scac_token_control_snapshot();
end $_$;


--
-- Name: schedule_calendar_prebrief_joe_live_job(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.schedule_calendar_prebrief_joe_live_job() RETURNS TABLE(job_id uuid, scheduled_for timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare due timestamptz; jid uuid;
begin
 if session_user<>'carr_jobs' then raise exception 'Joe scheduler identity refused'; end if;
 due := ops.calendar_prebrief_joe_live_due_at(now());
 if due is null then return; end if;
 if not exists(select 1 from ops.job_definition where key='calendar-prebrief-projection-joe-daily' and version=1 and owner_actor='joe' and enabled) or not exists(
   select 1
     from ops.calendar_prebrief_allowed_calendar a
     join lateral (
       select r.allowlist_revision_id
         from ops.calendar_prebrief_runtime_activation_receipt r
        where r.sponsor='joe'
        order by r.activated_at desc,r.id desc limit 1
     ) latest on latest.allowlist_revision_id=a.active_revision_id
     join ops.calendar_prebrief_allowlist_receipt l
       on l.id=a.active_revision_id and l.sponsor='joe'
      and l.configuration_digest=a.configuration_digest
    where a.sponsor='joe'
 ) then raise exception 'Joe scheduler activation gate refused'; end if;
 select (ops.enqueue_job('calendar-prebrief-projection-joe-daily',1,due,jsonb_build_object('workflow_key','calendar-prebrief-projection-joe-daily','scheduled_for',due),'calendar-prebrief:joe:'||due::text,'live')).id into jid;
 return query select jid,due;
end $$;


--
-- Name: renewal_decision_source_run; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.renewal_decision_source_run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    member_count integer NOT NULL,
    source_snapshot_id uuid,
    CONSTRAINT renewal_decision_source_run_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT renewal_decision_source_run_member_count_check CHECK ((member_count >= 0))
);


--
-- Name: seal_renewal_decision_source_run(uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.seal_renewal_decision_source_run(p_job_id uuid, p_lease uuid) RETURNS ops.renewal_decision_source_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare
  v_job ops.job%rowtype;
  v_run ops.renewal_decision_source_run%rowtype;
  v_count integer;
begin
  if not pg_has_role(session_user,'carr_jobs','member') then
    raise exception using errcode='42501',message='renewal source-run sealing requires the jobs capability';
  end if;
  select * into v_job from ops.job where id=p_job_id for update;
  if not found or v_job.definition_key<>'renewal-radar-source-daily' or v_job.definition_version<>1
     or v_job.mode<>'live' or v_job.state<>'running' or v_job.lease_token is distinct from p_lease
     or v_job.leased_until is null or v_job.leased_until<now() then
    raise exception using errcode='55000',message='renewal source-run sealing requires its current static job lease';
  end if;
  if v_job.scheduled_for < now()-interval '36 hours' or v_job.scheduled_for > now()+interval '5 minutes' then
    raise exception using errcode='22023',message='renewal source-run sealing refuses a job outside its DB-clock window';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('renewal-decision-source-run',0));
  select * into v_run from ops.renewal_decision_source_run where job_id=v_job.id and attempt=v_job.attempt;
  if found then
    if v_run.member_count <> (select count(*) from candidate_pool where source='renewal-radar' and status='pool')
       or exists (
          (select candidate_id,row_digest from ops.renewal_decision_source_run_member where source_run_id=v_run.id)
          except
          (select cp.id,ops.renewal_decision_candidate_digest(cp) from candidate_pool cp where cp.source='renewal-radar' and cp.status='pool')
       ) or exists (
          (select cp.id,ops.renewal_decision_candidate_digest(cp) from candidate_pool cp where cp.source='renewal-radar' and cp.status='pool')
          except
          (select candidate_id,row_digest from ops.renewal_decision_source_run_member where source_run_id=v_run.id)
       ) then
      raise exception using errcode='23505',message='renewal source-run replay conflicts with immutable source membership';
    end if;
    return v_run;
  end if;
  select count(*) into v_count from candidate_pool where source='renewal-radar' and status='pool';
  insert into ops.renewal_decision_source_run(job_id,attempt,snapshot_at,member_count)
  values(v_job.id,v_job.attempt,v_job.scheduled_for,v_count) returning * into v_run;
  insert into ops.renewal_decision_source_run_member(source_run_id,candidate_id,row_digest)
    select v_run.id,cp.id,ops.renewal_decision_candidate_digest(cp)
      from candidate_pool cp where cp.source='renewal-radar' and cp.status='pool';
  return v_run;
end $$;


--
-- Name: seal_renewal_decision_source_run(uuid, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.seal_renewal_decision_source_run(p_job_id uuid, p_lease uuid, p_snapshot_id uuid) RETURNS ops.renewal_decision_source_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare v_job ops.job%rowtype; v_snapshot ops.renewal_source_snapshot%rowtype; v_run ops.renewal_decision_source_run%rowtype; v_count integer;
begin
 if session_user<>'carr_renewal_source_attestor' or not pg_has_role(session_user,'carr_renewal_source_attestors','member') then raise exception using errcode='42501',message='renewal source-run sealing requires the exact renewal source attestor capability'; end if;
 select * into v_job from ops.job where id=p_job_id for update;
 if not found or v_job.definition_key<>'renewal-radar-source-daily' or v_job.definition_version<>1 or v_job.mode<>'live' or v_job.state<>'running' or v_job.lease_token is distinct from p_lease or v_job.leased_until is null or v_job.leased_until<now() then raise exception using errcode='55000',message='renewal source-run sealing requires its current static job lease'; end if;
 if v_job.scheduled_for < now()-interval '36 hours' or v_job.scheduled_for > now()+interval '5 minutes' then raise exception using errcode='22023',message='renewal source-run sealing refuses a job outside its DB-clock window'; end if;
 select * into v_snapshot from ops.renewal_source_snapshot where id=p_snapshot_id and job_id=v_job.id and attempt=v_job.attempt for update;
 if not found then raise exception using errcode='22023',message='renewal source-run sealing requires the exact leased signed source snapshot'; end if;
 if v_snapshot.row_count<>(select count(*) from ops.renewal_source_snapshot_member where snapshot_id=v_snapshot.id)
    or exists(select 1 from ops.renewal_source_snapshot_member sm left join candidate_pool cp on cp.id=sm.candidate_id where sm.snapshot_id=v_snapshot.id and (cp.id is null or cp.source<>'renewal-radar' or cp.status<>'pool')) then
   raise exception using errcode='23505',message='renewal source snapshot members are not a current mutable projection'; end if;
 perform pg_advisory_xact_lock(hashtextextended('renewal-decision-source-run',0));
 select * into v_run from ops.renewal_decision_source_run where job_id=v_job.id and attempt=v_job.attempt;
 if found then
   if v_run.source_snapshot_id is distinct from v_snapshot.id or v_run.member_count<>v_snapshot.row_count
      or exists((select sm.candidate_id,ops.renewal_decision_candidate_digest(cp) from ops.renewal_source_snapshot_member sm join candidate_pool cp on cp.id=sm.candidate_id where sm.snapshot_id=v_snapshot.id)
                except (select candidate_id,row_digest from ops.renewal_decision_source_run_member where source_run_id=v_run.id))
      or exists((select candidate_id,row_digest from ops.renewal_decision_source_run_member where source_run_id=v_run.id)
                except (select sm.candidate_id,ops.renewal_decision_candidate_digest(cp) from ops.renewal_source_snapshot_member sm join candidate_pool cp on cp.id=sm.candidate_id where sm.snapshot_id=v_snapshot.id)) then
     raise exception using errcode='23505',message='renewal source-run replay conflicts with immutable signed source membership';
   end if;
   return v_run;
 end if;
 select count(*) into v_count from ops.renewal_source_snapshot_member where snapshot_id=v_snapshot.id;
 insert into ops.renewal_decision_source_run(job_id,attempt,snapshot_at,member_count,source_snapshot_id) values(v_job.id,v_job.attempt,v_job.scheduled_for,v_count,v_snapshot.id) returning * into v_run;
 insert into ops.renewal_decision_source_run_member(source_run_id,candidate_id,row_digest)
 select v_run.id,sm.candidate_id,ops.renewal_decision_candidate_digest(cp) from ops.renewal_source_snapshot_member sm join candidate_pool cp on cp.id=sm.candidate_id where sm.snapshot_id=v_snapshot.id;
 return v_run;
end $$;


--
-- Name: seal_tour_public_projection(text, uuid, jsonb, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.seal_tour_public_projection(p_tenant text, p_projection_id uuid, p_selected_facts jsonb, p_actor_id text, p_receipt_digest text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_projection ops.tour_public_projection%rowtype; v_digest text;
begin
  if jsonb_typeof(p_selected_facts) <> 'array' or jsonb_array_length(p_selected_facts)=0
     or exists (select 1 from jsonb_array_elements(p_selected_facts) item where jsonb_typeof(item)<>'object' or (select array_agg(k order by k) from jsonb_object_keys(item) k) is distinct from array['display_field_key','field_assertion_id','property_id'])
     or exists (select 1 from jsonb_array_elements(p_selected_facts) item where coalesce(item->>'property_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or coalesce(item->>'field_assertion_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or coalesce(item->>'display_field_key','')='')
  then raise exception 'projection seal selected facts are invalid'; end if;
  select * into v_projection from ops.tour_public_projection where id=p_projection_id and organization_tenant_id=p_tenant for update;
  if not found then raise exception 'projection seal target is unavailable'; end if;
  if v_projection.status <> 'draft' or exists (select 1 from ops.tour_public_projection_seal_receipt where organization_tenant_id=p_tenant and projection_id=p_projection_id) then raise exception 'projection is not an unsealed draft'; end if;
  if exists (select 1 from ops.tour_public_projection_fact where organization_tenant_id=p_tenant and projection_id=p_projection_id) then raise exception 'projection seal facts already exist'; end if;
  if exists (select 1 from jsonb_to_recordset(p_selected_facts) x(property_id uuid,field_assertion_id uuid,display_field_key text) group by property_id,display_field_key having count(*)<>1) then raise exception 'projection seal selected facts are duplicated'; end if;
  if exists (
    select 1 from ops.tour_property_membership m cross join (values ('display.name'::text),('display.address'::text)) required(field_key)
    where m.organization_tenant_id=p_tenant and m.tour_id=v_projection.tour_id and m.route_version=v_projection.route_version
      and not exists (select 1 from jsonb_to_recordset(p_selected_facts) x(property_id uuid,field_assertion_id uuid,display_field_key text) where x.property_id=m.property_id and x.display_field_key=required.field_key)
  ) then raise exception 'projection seal requires one complete selected-property fact set'; end if;
  insert into ops.tour_public_projection_fact (organization_tenant_id,projection_id,property_id,field_assertion_id,route_version,display_field_key)
  select p_tenant,p_projection_id,x.property_id,x.field_assertion_id,v_projection.route_version,x.display_field_key
    from jsonb_to_recordset(p_selected_facts) x(property_id uuid,field_assertion_id uuid,display_field_key text);
  insert into ops.tour_public_projection_map_point(
    organization_tenant_id,projection_id,property_id,coordinate_candidate_id,entrance_verification_receipt_id,route_version
  )
  select p_tenant,p_projection_id,m.property_id,chosen.coordinate_candidate_id,chosen.verification_receipt_id,v_projection.route_version
  from ops.tour_property_membership m
  join lateral (
    select c.id coordinate_candidate_id,er.id verification_receipt_id
    from ops.tour_coordinate_entrance_verification_receipt er
    join ops.tour_property_coordinate_candidate c on c.organization_tenant_id=er.organization_tenant_id and c.id=er.coordinate_candidate_id and c.property_id=er.property_id
    join ops.tour_source_evidence e on e.organization_tenant_id=c.organization_tenant_id and e.id=c.source_evidence_id and e.rights_receipt_id=c.rights_receipt_id
    join ops.tour_rights_receipt r on r.organization_tenant_id=e.organization_tenant_id and r.id=e.rights_receipt_id and r.provider=e.rights_provider and r.policy_key=e.rights_policy_key
    where er.organization_tenant_id=p_tenant and er.property_id=m.property_id
      and er.verified_at<=v_projection.as_of and c.observed_at<=v_projection.as_of
      and c.coordinate_role in ('entrance','driveway','parking_access') and c.review_state='reviewed'
      and r.status='active' and r.revoked_at is null and r.effective_at<=now() and (r.expires_at is null or r.expires_at>now())
      and r.allowed_use_classes ? 'client_public_display'
      -- Coordinates are a separately governed public field class, not an
      -- implicit consequence of broad display permission.
      and (r.allowed_field_classes ? 'coordinates' or r.allowed_field_classes ? '*')
      and not exists(select 1 from ops.tour_rights_receipt newer where newer.organization_tenant_id=r.organization_tenant_id and newer.provider=r.provider and newer.policy_key=r.policy_key and newer.receipt_version>r.receipt_version and newer.effective_at<=now())
    order by er.verified_at desc,er.id desc,c.id desc limit 1
  ) chosen on true
  where m.organization_tenant_id=p_tenant and m.tour_id=v_projection.tour_id and m.route_version=v_projection.route_version;
  v_digest:=ops.tour_canonical_projection_digest(p_tenant,p_projection_id);
  insert into ops.tour_public_projection_seal_receipt (organization_tenant_id,projection_id,sealed_at,sealed_state,actor_id,receipt_digest,canonical_projection_digest)
  values (p_tenant,p_projection_id,now(),'approved',p_actor_id,p_receipt_digest,v_digest);
  return v_digest;
end $_$;


--
-- Name: search_tour_properties(text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.search_tour_properties(p_tenant text, p_actor_id text, p_filters jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_limit integer; v_offset integer; v_count integer; v_items jsonb; v_has_more boolean; v_cursor text;
begin
  if p_tenant is null or p_actor_id is null or jsonb_typeof(p_filters)<>'object' then raise exception 'tour search context is invalid'; end if;
  v_limit:=least(greatest(coalesce((p_filters->>'limit')::integer,25),1),100);
  if p_filters->>'cursor' is not null and p_filters->>'cursor' !~ '^[0-9]{1,9}$' then raise exception 'tour search cursor is invalid'; end if;
  v_offset:=coalesce((p_filters->>'cursor')::integer,0);
  with candidates as (
    select p.id,
      encode(public.digest(p_tenant||':'||p.id::text,'sha256'),'hex') as public_key,
      j.county_name,
      name.value as name_value,address.value as address_value,type.value as type_value,
      size_fact.value as size_value,econ.value as econ_value,avail.value as availability_value,
      exists(select 1 from ops.tour_coordinate_entrance_verification_receipt er where er.organization_tenant_id=p_tenant and er.property_id=p.id) as entrance_verified,
      exists(select 1 from ops.tour_public_projection_fact pf join ops.tour_public_projection pp on pp.id=pf.projection_id and pp.organization_tenant_id=pf.organization_tenant_id where pf.organization_tenant_id=p_tenant and pf.property_id=p.id and pp.status='approved' and exists(select 1 from ops.tour_public_projection_seal_receipt ps where ps.organization_tenant_id=pp.organization_tenant_id and ps.projection_id=pp.id and ps.canonical_projection_digest=pp.projection_digest) and ops.read_tour_public_projection(pp.organization_tenant_id,pp.id) is not null) as public_projection_ready,
      coalesce(jsonb_array_length(case when jsonb_typeof(photos.value)='array' then photos.value else '[]'::jsonb end),0) as photo_count,
      greatest(p.created_at,j.created_at,name.created_at,address.created_at,type.created_at,
        size_fact.created_at,econ.created_at,avail.created_at,photos.created_at) as updated_at,
      greatest(j.as_of,name.observed_at,name.effective_from,address.observed_at,address.effective_from,
        type.observed_at,type.effective_from,size_fact.observed_at,size_fact.effective_from,
        econ.observed_at,econ.effective_from,avail.observed_at,avail.effective_from,
        photos.observed_at,photos.effective_from) as fact_as_of
    from ops.tour_property p
    join lateral (
      select d.county_name,a.created_at,a.as_of from ops.tour_property_jurisdiction_assertion a join ops.tour_jurisdiction_dataset d on d.id=a.jurisdiction_dataset_id and d.organization_tenant_id=a.organization_tenant_id
       where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.review_state='reviewed' and d.review_state='reviewed' and d.state_code='FL'
       order by a.as_of desc,a.id desc limit 1
    ) j on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='display.name' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) name on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='display.address' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) address on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='property_type' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) type on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='size' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) size_fact on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='asking_economics' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) econ on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='availability' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) avail on true
    left join lateral (select value,created_at,observed_at,effective_from from ops.tour_field_assertion a where a.organization_tenant_id=p.organization_tenant_id and a.property_id=p.id and a.field_key='photos' and a.review_state='reviewed' and a.effective_from<=now() and (a.effective_to is null or a.effective_to>now()) order by a.effective_from desc,a.id desc limit 1) photos on true
    where p.organization_tenant_id=p_tenant and p.property_status='active'
  ), filtered as (
    select * from candidates c where
      (coalesce(jsonb_array_length(p_filters->'counties'),0)=0 or p_filters->'counties' ? c.county_name)
      and (nullif(p_filters->>'query','') is null or coalesce(c.name_value#>>'{}','') ilike '%'||(p_filters->>'query')||'%' or coalesce(c.address_value#>>'{}','') ilike '%'||(p_filters->>'query')||'%')
      and (coalesce(jsonb_array_length(p_filters->'property_types'),0)=0 or p_filters->'property_types' ? coalesce(c.type_value#>>'{}',''))
      and (coalesce(jsonb_array_length(p_filters->'availability'),0)=0 or p_filters->'availability' ? coalesce(c.availability_value#>>'{}','unknown'))
      and ((p_filters->>'entrance_verified') is null or c.entrance_verified=(p_filters->>'entrance_verified')::boolean)
      and ((p_filters->>'public_projection_ready') is null or c.public_projection_ready=(p_filters->>'public_projection_ready')::boolean)
      and ((p_filters->>'photos_available') is null or (c.photo_count>0)=(p_filters->>'photos_available')::boolean)
      and ((p_filters->>'min_square_feet') is null or (case when c.size_value->>'value' ~ '^-?[0-9]+(?:\.[0-9]+)?$' then (c.size_value->>'value')::numeric end) >= (p_filters->>'min_square_feet')::numeric)
      and ((p_filters->>'max_square_feet') is null or (case when c.size_value->>'value' ~ '^-?[0-9]+(?:\.[0-9]+)?$' then (c.size_value->>'value')::numeric end) <= (p_filters->>'max_square_feet')::numeric)
  ), ordered as (
    select filtered.*,row_number() over (order by
      case when p_filters->>'sort'='address_asc' then address_value#>>'{}' end asc,
      case when p_filters->>'sort'='size_asc' and size_value->>'value' ~ '^-?[0-9]+(?:\.[0-9]+)?$' then (size_value->>'value')::numeric end asc nulls last,
      case when p_filters->>'sort'='size_desc' and size_value->>'value' ~ '^-?[0-9]+(?:\.[0-9]+)?$' then (size_value->>'value')::numeric end desc nulls last,
      updated_at desc,id
    ) result_position from filtered
  ), page_plus_one as (
    select * from ordered where result_position>v_offset order by result_position limit v_limit+1
  ), page as (
    select * from page_plus_one order by result_position limit v_limit
  )
  select count(*)::integer,coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'property_id',id,'property_ref','property:public:'||substr(public_key,1,32),
    'name',name_value#>>'{}','address',address_value#>>'{}','county',county_name,'state','FL',
    'property_type',type_value#>>'{}','size',size_value,'asking_economics',econ_value,
    'availability',coalesce(availability_value#>>'{}','unknown'),'entrance_verified',entrance_verified,
    'public_projection_ready',public_projection_ready,'photos_available',photo_count>0,'photo_count',photo_count,
    'updated_at',updated_at,'fact_as_of',fact_as_of,'caveat','Facts shown are source-reviewed as of the displayed timestamp.'
  )) order by result_position),'[]'::jsonb),
  exists(select 1 from page_plus_one where result_position>v_offset+v_limit)
  into v_count,v_items,v_has_more from page;
  v_cursor:=case when v_has_more then (v_offset+v_count)::text else null end;
  return jsonb_strip_nulls(jsonb_build_object('count',v_count,'has_more',v_has_more,'cursor',v_cursor,'items',v_items));
end $_$;


--
-- Name: select_provider_routes(text[]); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.select_provider_routes(p_requested text[]) RETURNS TABLE(route_key text, priority integer, endpoint_ref text, health text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
  select v.route_key,v.priority,v.endpoint_ref,v.health
    from ops.v_provider_route v
   where v.route_key=any(p_requested) and v.enabled
     and v.health not in ('disabled','unavailable','rate_limited')
   order by array_position(p_requested,v.route_key),v.priority,v.route_key
$$;


--
-- Name: session_dispatch_history(text, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.session_dispatch_history(p_session_id text, p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_slug text; v_limit integer; v_key text;
        v_cursor jsonb; v_cursor_at timestamptz; v_cursor_id text;
        v_parent text; v_result jsonb;
begin
  v_actor := ops.portfolio_writer_actor_id();
  select a.slug into v_slug from public.actor a where a.id = v_actor;
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_key := nullif(btrim(coalesce(p_session_id, '')), '');
  if v_key is null then
    return jsonb_build_object('ok', false, 'reason_id', 'session_id_required');
  end if;

  if p_cursor is not null then
    begin
      v_cursor := convert_from(decode(p_cursor, 'base64'), 'utf8')::jsonb;
      v_cursor_at := (v_cursor->>'a')::timestamptz;
      v_cursor_id := v_cursor->>'e';
    exception when others then
      -- The token is the server's own; any failure to read one back is ONE
      -- refusal, never a partial page from a half-understood key.
      return jsonb_build_object('ok', false, 'reason_id', 'dispatch_cursor_invalid');
    end;
    if v_cursor_at is null or v_cursor_id is null then
      return jsonb_build_object('ok', false, 'reason_id', 'dispatch_cursor_invalid');
    end if;
  end if;

  select l.parent_session_id into v_parent
    from public.claude_continuity_leaf l where l.session_id = v_key limit 1;

  with sent_turns as (
    -- ONE set of sent turns from TWO sources, labelled. The left join is the
    -- proved path; the substring match is admitted only where no link row
    -- exists for the turn at all, which is what keeps a proved dispatch and an
    -- inferred one from ever being the same row.
    select t.id                                             as turn_id,
           t.at                                             as at,
           t.msg_id                                         as msg_id,
           t.room_id                                        as room_id,
           t.body                                           as body,
           t.origin_actor                                   as origin_actor,
           t.seat                                           as seat,
           t.sponsor                                        as sponsor,
           l.id                                             as link_id,
           l.dispatch_ref                                   as dispatch_ref,
           l.work_request_id                                as work_request_id,
           case when l.id is null then 'body_match'
                else 'proved' end                           as link_source
      from public.partner_room_turn t
      left join public.room_dispatch_link l
        on l.turn_id = t.id and l.session_id = v_key
     where t.kind = 'turn'
       and (l.id is not null
            or (position(v_key in t.body) > 0
                and not exists (select 1 from public.room_dispatch_link x
                                 where x.turn_id = t.id)))
  ),
  events as (
    -- SENT. Proved by a link row where one exists, inferred from the body
    -- where none does, and the row says which.
    select 'turn:' || s.turn_id                              as event_id,
           s.at                                              as at,
           'sent'                                            as stage,
           'public.partner_room_turn id ' || s.turn_id
             || ' msg_id ' || s.msg_id
             || ' in room ' || s.room_id
             || coalesce(' linked by public.room_dispatch_link id '
                  || s.link_id || ' dispatch_ref ' || s.dispatch_ref, '')
                                                             as stage_evidence,
           left(s.body, 500)                                 as rationale,
           s.origin_actor                                    as from_seat,
           s.seat                                            as to_seat,
           s.sponsor                                         as sponsor,
           s.room_id                                         as room_id,
           lead('turn:' || s.turn_id) over (
             partition by s.room_id order by s.at asc, s.turn_id asc)
                                                             as superseded_by,
           s.work_request_id::text                           as work_request_ref,
           null::text                                        as attempt_ref,
           (s.origin_actor = v_slug or s.seat = v_slug)      as may_see,
           s.link_source                                     as link_source,
           s.dispatch_ref::text                              as dispatch_ref,
           -- PER DISPATCH, computed on this row and nowhere else.
           case when s.link_id is null then 'no_dispatch_spine'
                when not exists (select 1 from public.room_dispatch_ack a
                                  where a.dispatch_ref = s.dispatch_ref
                                    and a.stage = 'received')
                  then 'not_acknowledged'
                else null end                                as stage_unavailable_reason
      from sent_turns s
    union all
    -- RECEIVED and ACKNOWLEDGED. One row per room_dispatch_ack row, each
    -- carrying the ack row that proves it. Nothing here is inferred from an
    -- adjacent turn or an adjacent receipt: if the desk never wrote a row,
    -- this branch returns nothing and the sent row's own reason says so.
    select 'ack:' || a.id,
           a.at,
           a.stage,
           'public.room_dispatch_ack id ' || a.id
             || ' for dispatch_ref ' || a.dispatch_ref,
           a.evidence,
           a.by_actor,
           t.seat,
           t.sponsor,
           t.room_id,
           null::text,
           l.work_request_id::text,
           null::text,
           (t.origin_actor = v_slug or t.seat = v_slug),
           'proved',
           a.dispatch_ref::text,
           null::text
      from public.room_dispatch_ack a
      join public.room_dispatch_link l on l.dispatch_ref = a.dispatch_ref
      join public.partner_room_turn t on t.id = l.turn_id
     where l.session_id = v_key
    union all
    -- ACTED. Unchanged from 0529: the capability session's OWN recorded
    -- transitions, each carrying the timestamp column that proves it.
    select 'capability:' || s.id || ':' || e.column_name,
           e.at,
           'acted',
           'ops.capability_agent_session ' || s.id || ' column ' || e.column_name
             || ', state ' || s.state,
           'capability session reached ' || e.reached,
           null::text,
           null::text,
           null::text,
           null::text,
           null::text,
           s.work_request_id::text,
           s.id::text,
           (s.executor_actor_id = v_actor or s.created_by_actor_id = v_actor),
           'proved',
           null::text,
           null::text
      from ops.capability_agent_session s
      cross join lateral (values
          ('started_at', s.started_at, 'in_progress'),
          ('prepared_at', s.prepared_at, 'verification'),
          ('completed_at', s.completed_at, 'completed'),
          ('cancelled_at', s.cancelled_at, 'cancelled')
        ) as e(column_name, at, reached)
     where e.at is not null
       and (s.id::text = v_key or position(v_key in s.worktree_ref) > 0)
  ),
  paged as (
    select e.*,
           case when e.may_see then row_number() over (
             partition by e.may_see order by e.at desc, e.event_id desc) end as rn
      from events e
     where p_cursor is null
        or row(e.at, e.event_id) < row(v_cursor_at, v_cursor_id)
  )
  select jsonb_build_object(
    'ok', true,
    'session_id', v_key,
    'parent_session_id', v_parent,
    'total_seen', count(*),
    'total_returned', count(*) filter (where may_see),
    'permission_filtered', count(*) > count(*) filter (where may_see),
    'more', count(*) filter (where may_see) > v_limit,
    'next_cursor', (
      select encode(convert_to(jsonb_build_object('a', p.at, 'e', p.event_id)::text, 'utf8'), 'base64')
        from paged p where p.may_see and p.rn = v_limit
         and (select count(*) filter (where q.may_see) from paged q) > v_limit),
    -- NOT CONSTANTS ANY MORE. Each of these three is read off the newest
    -- visible row that carries it, and the reason is the newest dispatch's own
    -- per-row value -- so an answer with one proved dispatch and one pre-spine
    -- dispatch reports each honestly in `events` and never averages them here.
    'received', (select p.at from paged p
                  where p.may_see and p.stage = 'received'
                  order by p.at desc, p.event_id desc limit 1),
    'acknowledged', (select p.at from paged p
                      where p.may_see and p.stage = 'acknowledged'
                      order by p.at desc, p.event_id desc limit 1),
    'stage_unavailable_reason', (select p.stage_unavailable_reason from paged p
                                  where p.may_see and p.stage = 'sent'
                                  order by p.at desc, p.event_id desc limit 1),
    'events', coalesce(jsonb_agg(jsonb_build_object(
        'event_id', event_id,
        'at', at,
        'stage', stage,
        'stage_evidence', stage_evidence,
        'rationale', rationale,
        'from_seat', from_seat,
        'to_seat', to_seat,
        'sponsor', sponsor,
        'room_id', room_id,
        'session_id', v_key,
        'parent_session_id', v_parent,
        'attempt_ref', attempt_ref,
        'superseded_by', superseded_by,
        'work_request_ref', work_request_ref,
        'link_source', link_source,
        'dispatch_ref', dispatch_ref,
        'stage_unavailable_reason', stage_unavailable_reason)
      order by at desc, event_id desc)
      filter (where may_see and rn <= v_limit), '[]'::jsonb))
    into v_result
    from paged;

  return v_result;
end $$;


--
-- Name: FUNCTION session_dispatch_history(p_session_id text, p_cursor text, p_limit integer); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.session_dispatch_history(p_session_id text, p_cursor text, p_limit integer) IS 'WR-000119: the dispatch history for one session, newest first. The actor is derived from the server-installed transaction context; p_session_id is a lookup key against rows already filtered by it and never an identity claim. All four stages now carry evidence: sent from public.room_dispatch_link (link_source proved) or, for pre-spine turns only, from the body match (link_source body_match); received and acknowledged from public.room_dispatch_ack rows; acted from ops.capability_agent_session timestamp columns. stage_unavailable_reason is PER DISPATCH -- null once proved, not_acknowledged where a link has no ack row of that stage, no_dispatch_spine only where no link row exists.';


--
-- Name: session_identity_facts(text, integer, boolean); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.session_identity_facts(p_query text, p_limit integer, p_include_closed boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_limit integer; v_include_closed boolean; v_query text;
        v_result jsonb;
begin
  -- The acting actor, resolved from the server-installed transaction context.
  -- A caller cannot name one: there is no parameter for it.
  v_actor := ops.portfolio_writer_actor_id();
  -- Clamped, never refused: the idiom is 0520:181's and 0525:100's.
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_include_closed := coalesce(p_include_closed, false);
  v_query := nullif(btrim(coalesce(p_query, '')), '');

  with books as (
    -- CLAUDE. The only book of the four that records a parent column, so the
    -- only one that can report parent_known true.
    select l.session_id                                     as canonical_session_id,
           'claude'                                         as surface,
           coalesce(nullif(btrim(l.project_affinity), ''), 'claude session')
             || ' / ' || left(l.session_id, 12)             as display_name,
           l.parent_session_id                              as parent_session_id,
           true                                             as parent_known,
           l.native_agent_id                                as native_host_id,
           true                                             as native_host_supported,
           l.updated_at                                     as last_observed_at,
           'continuity_event'                               as observation_source,
           l.project_affinity                               as project_affinity,
           l.latest_cwd                                     as latest_cwd,
           l.latest_model_id                                as latest_model_id,
           (select count(*) from public.claude_continuity_leaf s
             where coalesce(s.parent_session_id, s.session_id)
                 = coalesce(l.parent_session_id, l.session_id))::integer
                                                            as attempt_count,
           (select s.session_id from public.claude_continuity_leaf s
             where coalesce(s.parent_session_id, s.session_id)
                 = coalesce(l.parent_session_id, l.session_id)
             order by s.updated_at desc, s.session_id desc limit 1)
                                                            as latest_attempt_ref,
           (l.owner_actor_id = v_actor or l.surface_principal_actor_id = v_actor)
                                                            as may_see,
           false                                            as closed,
           null::text                                       as state_hint
      from public.claude_continuity_leaf l
    union all
    -- CODEX. No parent column exists in this book, so a null parent here means
    -- UNRECORDED and parent_known is false. It records no lineage column
    -- either, so an attempt group cannot be formed and the count is the row.
    select c.native_task_id,
           'codex',
           coalesce(nullif(btrim(c.project_id), ''), 'codex session')
             || ' / ' || left(c.native_task_id, 12),
           null::text,
           false,
           c.native_task_id,
           true,
           c.updated_at,
           'checkpoint',
           c.project_id,
           c.cwd,
           null::text,
           1,
           c.native_task_id,
           (c.owner_actor_id = v_actor),
           false,
           null::text
      from public.codex_continuity_checkpoint c
    union all
    -- CAPABILITY. The server's own build-session book. It records no parent
    -- session and no native host id, so both are reported unrecorded rather
    -- than absent. Its attempt group IS recorded: every session against one
    -- work request is one attempt of it.
    select s.id::text,
           'capability',
           'capability ' || left(s.id::text, 8) || ' @ ' || left(s.source_commit_sha, 7),
           null::text,
           false,
           null::text,
           false,
           s.updated_at,
           'server_session',
           s.worktree_ref,
           s.worktree_ref,
           null::text,
           (select count(*) from ops.capability_agent_session a
             where a.work_request_id = s.work_request_id)::integer,
           (select a.id::text from ops.capability_agent_session a
             where a.work_request_id = s.work_request_id
             order by a.updated_at desc, a.id desc limit 1),
           (s.executor_actor_id = v_actor or s.created_by_actor_id = v_actor),
           (s.state in ('completed', 'cancelled')),
           s.state
      from ops.capability_agent_session s
    union all
    -- HARVESTED. public.session_work has NO owner column, so may_see is the
    -- constant true and this branch adds nothing to the withheld count. It also
    -- has no parent column and no native host id, and its last_seen is the
    -- HARVEST's clock, which is why work_state below is forced to `unknown`.
    select w.id,
           'harvested',
           w.title,
           null::text,
           false,
           null::text,
           false,
           w.last_seen,
           'harvest',
           w.kind,
           null::text,
           null::text,
           1,
           null::text,
           true,
           (not w.open_loop),
           null::text
      from public.session_work w
  ),
  -- ONE age rule for every book, computed from the row's own last_observed_at
  -- against now() inside the function.
  judged as (
    select b.*,
           now() - b.last_observed_at as observed_age,
           case
             when b.surface = 'harvested' then 'unknown'
             when b.state_hint = 'completed' then 'complete_unacknowledged'
             when b.state_hint = 'cancelled' then 'disconnected'
             when now() - b.last_observed_at <= interval '15 minutes' then 'working'
             when now() - b.last_observed_at <= interval '2 hours' then 'idle'
             else 'disconnected'
           end as work_state
      from books b
  ),
  matched as (
    select j.* from judged j
     where (v_include_closed or not j.closed)
       and (v_query is null
            or j.canonical_session_id ilike '%' || v_query || '%'
            or j.display_name ilike '%' || v_query || '%'
            or coalesce(j.native_host_id, '') ilike '%' || v_query || '%'
            or coalesce(j.project_affinity, '') ilike '%' || v_query || '%'
            or coalesce(j.latest_cwd, '') ilike '%' || v_query || '%')
  ),
  ranked as (
    select m.*,
           case when m.may_see then row_number() over (
             partition by m.may_see
             order by m.last_observed_at desc, m.canonical_session_id desc) end as rn
      from matched m
  )
  select jsonb_build_object(
    'ok', true,
    'total_seen', count(*),
    'total_returned', count(*) filter (where may_see),
    -- THE COUNT COMPARISON. Not a constant, and not "the page came back empty".
    'permission_filtered', count(*) > count(*) filter (where may_see),
    'sessions', coalesce(jsonb_agg(jsonb_build_object(
        'canonical_session_id', canonical_session_id,
        'surface', surface,
        'display_name', display_name,
        'alias_source', 'derived',
        'parent_session_id', parent_session_id,
        'parent_known', parent_known,
        'native_host_id', native_host_id,
        'native_host_supported', native_host_supported,
        'work_state', work_state,
        'work_state_evidence', observation_source || ' row observed at '
          || to_char(last_observed_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
          || ', age ' || observed_age::text
          || case when surface = 'harvested'
                  then '; the harvest stamps its own run time and is not scheduled, so liveness is not claimed'
                  when state_hint is not null then '; server session state ' || state_hint
                  else '' end,
        'last_observed_at', last_observed_at,
        'observation_source', observation_source,
        'project_affinity', project_affinity,
        'latest_cwd', latest_cwd,
        'latest_model_id', latest_model_id,
        'attempt_count', attempt_count,
        'latest_attempt_ref', latest_attempt_ref)
      order by last_observed_at desc, canonical_session_id desc)
      filter (where may_see and rn <= v_limit), '[]'::jsonb))
    into v_result
    from ranked;

  return v_result;
end $$;


--
-- Name: FUNCTION session_identity_facts(p_query text, p_limit integer, p_include_closed boolean); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.session_identity_facts(p_query text, p_limit integer, p_include_closed boolean) IS 'WR-000117: the only door that projects the four disjoint session books into one identity row shape. The actor is derived from the server-installed transaction context -- there is no parameter for it -- p_query is a search string and never an identity claim, every row names the book that observed it, an unrecorded parent is distinguishable from a root, and permission filtering is reported as total_seen against total_returned.';


--
-- Name: set_notification_preference(integer, boolean, time without time zone, time without time zone, text, boolean, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.set_notification_preference(p_base_version integer, p_device_opt_in boolean, p_quiet_hours_start time without time zone, p_quiet_hours_end time without time zone, p_timezone text, p_clear_quiet_hours boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_pref ops.notification_preference%rowtype;
        v_prior ops.notification_preference_write%rowtype;
        v_digest text; v_clear boolean; v_start time; v_end time;
        v_version integer; v_result jsonb; v_row ops.notification_preference%rowtype;
begin
  if not (pg_has_role(current_user, 'carr_writer', 'member')
       or pg_has_role(current_user, 'carr_authority', 'member')) then
    raise exception using errcode = '42501',
      message = 'setting notification preferences requires the writer or authority capability';
  end if;
  v_actor := ops.portfolio_writer_actor_id();
  v_clear := coalesce(p_clear_quiet_hours, false);

  if p_idempotency_key is null then
    return jsonb_build_object('ok', false,
      'reason_id', 'notification_preference_idempotency_key_required');
  end if;

  -- THE REPLAY LOOKUP IS THE FIRST ACT AFTER THE KEY CHECK. A replayed key with
  -- the same payload returns the first call's result and touches nothing; a
  -- replayed key with a DIFFERENT payload is two intentions under one key and
  -- is refused by name.
  v_digest := encode(public.digest(convert_to(jsonb_build_object(
    'actor', v_actor, 'base_version', p_base_version, 'device_opt_in', p_device_opt_in,
    'quiet_hours_start', p_quiet_hours_start, 'quiet_hours_end', p_quiet_hours_end,
    'timezone', p_timezone, 'clear_quiet_hours', v_clear)::text, 'UTF8'), 'sha256'), 'hex');
  select * into v_prior from ops.notification_preference_write
   where idempotency_key = p_idempotency_key;
  if v_prior.idempotency_key is not null then
    if v_prior.request_digest <> v_digest then
      return jsonb_build_object('ok', false,
        'reason_id', 'notification_preference_idempotency_key_reused');
    end if;
    return v_prior.result || jsonb_build_object('deduplicated', true);
  end if;

  select * into v_pref from ops.notification_preference where actor = v_actor;

  if v_clear and (p_quiet_hours_start is not null or p_quiet_hours_end is not null) then
    return jsonb_build_object('ok', false,
      'reason_id', 'notification_preference_quiet_hours_conflicting_request');
  end if;

  -- The POST-MERGE pair: what the row would become.
  if v_clear then
    v_start := null; v_end := null;
  else
    v_start := coalesce(p_quiet_hours_start, v_pref.quiet_hours_start);
    v_end   := coalesce(p_quiet_hours_end,   v_pref.quiet_hours_end);
  end if;
  if (v_start is null) <> (v_end is null) then
    return jsonb_build_object('ok', false,
      'reason_id', 'notification_preference_quiet_hours_incomplete');
  end if;

  if p_timezone is not null
     and not exists (select 1 from pg_catalog.pg_timezone_names where name = p_timezone) then
    return jsonb_build_object('ok', false,
      'reason_id', 'notification_preference_timezone_unknown');
  end if;

  -- Insert-if-absent-under-base_version-1, else compare-and-swap.
  insert into ops.notification_preference(actor, device_opt_in, quiet_hours_start,
                                          quiet_hours_end, timezone, version)
  select v_actor, coalesce(p_device_opt_in, false), v_start, v_end,
         coalesce(p_timezone, 'UTC'), 2
   where p_base_version = 1
     and not exists (select 1 from ops.notification_preference where actor = v_actor)
  on conflict (actor) do nothing;

  -- The compare-and-swap is the predicated update and NOT FOUND *is* the
  -- refusal. A first save that just landed sits at version 2 and p_base_version
  -- of 1 no longer matches it, so the update finds nothing -- which is why the
  -- row is re-read below and a freshly inserted row is reported as success
  -- rather than as a conflict.
  update ops.notification_preference
     set device_opt_in = coalesce(p_device_opt_in, device_opt_in),
         quiet_hours_start = case when v_clear then null
                                  else coalesce(p_quiet_hours_start, quiet_hours_start) end,
         quiet_hours_end   = case when v_clear then null
                                  else coalesce(p_quiet_hours_end, quiet_hours_end) end,
         timezone = coalesce(p_timezone, timezone),
         version  = version + 1
   where actor = v_actor and version = p_base_version
  returning version into v_version;

  if v_version is null then
    select * into v_row from ops.notification_preference where actor = v_actor;
    if v_pref.actor is null and v_row.actor is not null and p_base_version = 1 then
      v_version := v_row.version;
    else
      return jsonb_build_object('ok', false, 'reason_id', 'version_conflict',
        'current_version', (select version from ops.notification_preference
                             where actor = v_actor));
    end if;
  end if;

  select * into v_row from ops.notification_preference where actor = v_actor;
  v_result := jsonb_build_object(
    'ok', true,
    'exists', true,
    'device_opt_in', v_row.device_opt_in,
    'quiet_hours_start', v_row.quiet_hours_start,
    'quiet_hours_end', v_row.quiet_hours_end,
    'timezone', v_row.timezone,
    'version', v_version,
    'deduplicated', false);

  insert into ops.notification_preference_write(idempotency_key, actor, request_digest, result)
  values (p_idempotency_key, v_actor, v_digest, v_result);

  return v_result;
end $$;


--
-- Name: FUNCTION set_notification_preference(p_base_version integer, p_device_opt_in boolean, p_quiet_hours_start time without time zone, p_quiet_hours_end time without time zone, p_timezone text, p_clear_quiet_hours boolean, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.set_notification_preference(p_base_version integer, p_device_opt_in boolean, p_quiet_hours_start time without time zone, p_quiet_hours_end time without time zone, p_timezone text, p_clear_quiet_hours boolean, p_idempotency_key uuid) IS 'WR-000116: the only door that sets a partner''s own notification preferences. No argument names an actor. Four ordered refusals return a reason_id before any write, the compare-and-swap is a predicated update whose NOT FOUND is the refusal, a first save against base_version 1 inserts under the same predicate, and one idempotency key applies exactly once.';


--
-- Name: set_rule_delivery_mode(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.set_rule_delivery_mode(p_mode text, p_reason text, p_expected_map_digest text) RETURNS TABLE(mode text, changed_controls bigint, receipt_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
begin
  if session_user <> 'carr_authority_joe'
     or ops.authority_actor_slug() <> 'joe' then
    raise exception using errcode='42501',
      message='rule-delivery cutover requires the Joe authority login';
  end if;
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'rule-delivery cutover reason is required';
  end if;
  return query
    select result.mode,result.changed_controls,result.receipt_id
      from ops.set_rule_delivery_mode(
        p_mode,'joe',btrim(p_reason),p_expected_map_digest
      ) result;
end $$;


--
-- Name: FUNCTION set_rule_delivery_mode(p_mode text, p_reason text, p_expected_map_digest text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.set_rule_delivery_mode(p_mode text, p_reason text, p_expected_map_digest text) IS 'Joe-only atomic rule-delivery cutover. The authenticated session supplies attribution; no caller actor label is accepted.';


--
-- Name: set_rule_delivery_mode(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.set_rule_delivery_mode(p_mode text, p_changed_by text, p_reason text, p_expected_map_digest text) RETURNS TABLE(mode text, changed_controls bigint, receipt_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'ops'
    AS $$
declare
  v_from_mode text;
  v_expected_control text;
  v_expected_class text;
  v_next_control text;
  v_next_class text;
  v_count bigint;
  v_receipt uuid;
  v_health record;
begin
  if p_mode not in ('shadow','enforced') then
    raise exception 'unknown rule-delivery mode %',p_mode;
  end if;
  if coalesce(btrim(p_changed_by),'')='' or coalesce(btrim(p_reason),'')='' then
    raise exception 'changed_by and reason are required';
  end if;
  if (select count(*) from ops.rule_delivery_activation_target) <> 8 then
    raise exception 'activation target set is not exactly eight';
  end if;
  if exists (select 1 from ops.rule_delivery_activation_target
              where map_digest<>p_expected_map_digest) then
    raise exception 'activation map digest preimage differs';
  end if;

  select p.mode into v_from_mode
    from ops.rule_delivery_policy p where p.singleton for update;
  if v_from_mode is null then raise exception 'delivery policy singleton is absent'; end if;
  if v_from_mode=p_mode then
    raise exception 'delivery policy already %; refusing a receipt-free no-op',p_mode;
  end if;
  if v_from_mode='shadow' and p_mode='enforced' then
    v_expected_control:='session_boot'; v_expected_class:='surfacing';
    v_next_control:='pack_delivery'; v_next_class:='stop_gate';
  elsif v_from_mode='enforced' and p_mode='shadow' then
    v_expected_control:='pack_delivery'; v_expected_class:='stop_gate';
    v_next_control:='session_boot'; v_next_class:='surfacing';
  else
    raise exception 'unsupported delivery transition % -> %',v_from_mode,p_mode;
  end if;

  select * into v_health from ops.rule_delivery_audit_counts(35);
  if v_health.total=0 or v_health.untagged<>0 or v_health.orphaned<>0
     or v_health.wildcarded<>0 or v_health.packless<>0 or v_health.emptypack<>0
     or v_health.scope_mismatch<>0 then
    raise exception 'delivery coverage is not activation-safe: %',row_to_json(v_health);
  end if;

  perform r.id from public.rule r
    join ops.rule_delivery_activation_target t on left(r.id::text,8)=t.short_id
   where r.status='active' for update of r;
  get diagnostics v_count=row_count;
  if v_count<>8 then raise exception 'active target preimage count is %, expected 8',v_count; end if;

  perform l.rule_id from ops.rule_load_layer l
    join ops.rule_delivery_activation_target t on t.short_id=l.short_id
   where l.scope=t.expected_scope and l.packs=array[t.expected_pack]
     and l.load_layer='pack' and l.map_digest=t.map_digest
   for update of l;
  get diagnostics v_count=row_count;
  if v_count<>8 then raise exception 'delivery target tag preimage count is %, expected 8',v_count; end if;

  perform a.rule_id from ops.rule_admission a
    join public.rule r on r.id=a.rule_id
    join ops.rule_delivery_activation_target t on left(r.id::text,8)=t.short_id
   where a.state='admitted'
     and a.reason='Backfilled from the reviewed active rule enforcement map'
     and a.enforcement_status='blocked'
     and not exists (select 1 from ops.rule_approval_receipt ar where ar.rule_id=r.id)
   for update of a;
  get diagnostics v_count=row_count;
  if v_count<>8 then raise exception 'admission target preimage count is %, expected 8',v_count; end if;

  select count(*) into v_count
    from ops.rule_enforcement_point ep
    join public.rule r on r.id=ep.rule_id
    join ops.rule_delivery_activation_target t on left(r.id::text,8)=t.short_id
   where ep.control_key=v_expected_control
     and ep.enforcement_class=v_expected_class and ep.installed;
  if v_count<>8 or (select count(*) from ops.rule_enforcement_point ep
      join public.rule r on r.id=ep.rule_id
      join ops.rule_delivery_activation_target t on left(r.id::text,8)=t.short_id)<>8 then
    raise exception 'enforcement-point preimage is not the exact eight %/% rows',
      v_expected_control,v_expected_class;
  end if;
  if p_mode='enforced' and not exists (
      select 1 from ops.enforcement_control_catalog c
       where c.control_key='pack_delivery' and c.enforcement_class='stop_gate'
         and c.installed and c.verified_at is not null) then
    raise exception 'pack_delivery is not an installed, verified stop gate';
  end if;

  delete from ops.rule_enforcement_point ep using public.rule r,
      ops.rule_delivery_activation_target t
   where ep.rule_id=r.id and left(r.id::text,8)=t.short_id;
  insert into ops.rule_enforcement_point
    (rule_id,control_key,implementation_ref,test_ref,enforcement_class,installed,verified_at)
  select r.id,
         case when p_mode='enforced' then t.to_control else t.from_control end,
         case when p_mode='enforced' then t.to_implementation_ref else t.from_implementation_ref end,
         case when p_mode='enforced' then t.to_test_ref else t.from_test_ref end,
         case when p_mode='enforced' then t.to_enforcement_class else t.from_enforcement_class end,
         true,now()
    from public.rule r join ops.rule_delivery_activation_target t
      on left(r.id::text,8)=t.short_id where r.status='active';

  update ops.rule_admission a
     set coverage_detail=jsonb_set(a.coverage_detail,'{rule_delivery}',
           jsonb_build_object('mode',p_mode,'control',v_next_control,
                              'changed_by',p_changed_by,'changed_at',now()),true),
         version=a.version+1,updated_at=now()
    from public.rule r join ops.rule_delivery_activation_target t
      on left(r.id::text,8)=t.short_id
   where a.rule_id=r.id;

  perform set_config('carr.rule_delivery_cutover','on',true);
  update ops.rule_delivery_policy
     set mode=p_mode,changed_by=p_changed_by,reason=p_reason,changed_at=now()
   where singleton;

  insert into ops.rule_delivery_activation_receipt
    (from_mode,to_mode,changed_by,reason,map_digest,target_short_ids)
  select v_from_mode,p_mode,p_changed_by,p_reason,p_expected_map_digest,
         array_agg(t.short_id order by t.short_id)
    from ops.rule_delivery_activation_target t returning id into v_receipt;
  return query select p_mode,8::bigint,v_receipt;
end $$;


--
-- Name: set_sourced_work_request_shape_disposition(text, integer, text, text, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.set_sourced_work_request_shape_disposition(p_work_request text, p_base_version integer, p_disposition text, p_fixed_surface_ref text, p_rationale text, p_decided_by_actor_id uuid, p_idempotency_key uuid) RETURNS TABLE(work_request_id uuid, ref text, state text, version integer, shape_disposition text, shape_fixed_surface_ref text, shape_rationale text, shape_decided_by_actor_id uuid, shape_decided_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  w ops.work_request%rowtype;
  original ops.sourced_work_request_shape_disposition_receipt%rowtype;
  correction ops.sourced_work_request_shape_disposition_correction_receipt%rowtype;
  actor public.actor%rowtype;
  classification jsonb;
  normalized_fixed_surface text := nullif(btrim(coalesce(p_fixed_surface_ref,'')), '');
  normalized_rationale text := nullif(btrim(coalesce(p_rationale,'')), '');
begin
  if coalesce(btrim(p_work_request),'') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1
     or p_disposition not in ('required','not_required')
     or normalized_rationale is null
     or p_decided_by_actor_id is null
     or p_idempotency_key is null
     or (p_disposition = 'required' and normalized_fixed_surface is not null)
     or (p_disposition = 'not_required' and normalized_fixed_surface is null) then
    raise exception 'sourced shape disposition requires exact Work Request/base version, closed disposition, exact fixed surface rule, rationale, active actor, and UUID idempotency key';
  end if;

  select a.* into actor from public.actor a
   where a.id = p_decided_by_actor_id and a.active
   for share;
  if not found then
    raise exception 'sourced shape disposition actor is not active';
  end if;

  -- One advisory lock on the caller key precedes BOTH receipt lookups, so two
  -- first calls with the same key serialize before either can observe an
  -- empty table, and a key can never be reused across the two tables.
  perform pg_advisory_xact_lock(hashtextextended('program6-sourced-shape-disposition:' || p_idempotency_key, 0));
  select r.* into original
    from ops.sourced_work_request_shape_disposition_receipt r
   where r.idempotency_key = p_idempotency_key
   for share;
  if found then
    select x.* into w from ops.work_request x where x.id = original.work_request_id for share;
    if not found
       or w.ref is distinct from p_work_request
       or original.base_version is distinct from p_base_version
       or original.disposition is distinct from p_disposition
       or original.fixed_surface_ref is distinct from normalized_fixed_surface
       or original.rationale is distinct from normalized_rationale
       or original.decided_by_actor_id is distinct from p_decided_by_actor_id
       or w.state is distinct from 'triaged'
       or w.version is distinct from original.result_version
       or (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
          is distinct from
          (original.disposition,original.fixed_surface_ref,original.rationale,original.decided_by_actor_id,original.decided_at) then
      raise exception 'idempotency key already names a different sourced shape disposition';
    end if;
    return query select w.id,w.ref,w.state,w.version,w.shape_disposition,w.shape_fixed_surface_ref,
      w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at,true;
    return;
  end if;
  select c.* into correction
    from ops.sourced_work_request_shape_disposition_correction_receipt c
   where c.idempotency_key = p_idempotency_key
   for share;
  if found then
    select x.* into w from ops.work_request x where x.id = correction.work_request_id for share;
    if not found
       or w.ref is distinct from p_work_request
       or correction.base_version is distinct from p_base_version
       or p_disposition is distinct from 'required'
       or normalized_fixed_surface is not null
       or correction.rationale is distinct from normalized_rationale
       or correction.decided_by_actor_id is distinct from p_decided_by_actor_id
       or w.state is distinct from 'triaged'
       or w.version is distinct from correction.result_version
       or (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
          is distinct from
          (correction.disposition,correction.fixed_surface_ref,correction.rationale,correction.decided_by_actor_id,correction.decided_at) then
      raise exception 'idempotency key already names a different sourced shape correction';
    end if;
    return query select w.id,w.ref,w.state,w.version,w.shape_disposition,w.shape_fixed_surface_ref,
      w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at,true;
    return;
  end if;

  select x.* into w from ops.work_request x
   where x.ref = p_work_request
   for update;
  if not found
     or w.capture_idempotency_key is null
     or w.organization_tenant_id is distinct from 'carr-internal'
     or w.state is distinct from 'triaged'
     or w.version is distinct from p_base_version
     or w.program_key is not null or w.program_ordinal is not null then
    raise exception 'exact current triaged sourced Work Request required';
  end if;

  select r.* into original
    from ops.sourced_work_request_shape_disposition_receipt r
   where r.work_request_id = w.id
   for share;
  if found then
    -- Forward correction: exactly one monotonic not_required -> required on
    -- the exact current receipt-backed row, before any Shape revision, with
    -- no prior correction. No classifier call: an intrinsically heavy request
    -- is precisely the one that must be able to move to required.
    if p_disposition is distinct from 'required'
       or normalized_fixed_surface is not null
       or original.disposition is distinct from 'not_required'
       or original.result_version is distinct from w.version
       or (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
          is distinct from
          (original.disposition,original.fixed_surface_ref,original.rationale,original.decided_by_actor_id,original.decided_at)
       or exists (select 1 from ops.work_shape_revision sr where sr.work_request_id = w.id)
       or exists (select 1 from ops.sourced_work_request_shape_disposition_correction_receipt c
                   where c.work_request_id = w.id or c.original_receipt_id = original.id) then
      raise exception 'only an exact current sourced not_required receipt may receive one required correction before Shape';
    end if;
    insert into ops.sourced_work_request_shape_disposition_correction_receipt
      (work_request_id,idempotency_key,original_receipt_id,base_version,result_version,disposition,fixed_surface_ref,rationale,decided_by_actor_id)
    values
      (w.id,p_idempotency_key,original.id,w.version,w.version + 1,'required',null,normalized_rationale,p_decided_by_actor_id)
    returning * into correction;
    update ops.work_request x
       set shape_disposition = correction.disposition,
           shape_fixed_surface_ref = correction.fixed_surface_ref,
           shape_rationale = correction.rationale,
           shape_decided_by_actor_id = correction.decided_by_actor_id,
           shape_decided_at = correction.decided_at,
           version = correction.result_version,
           updated_at = now()
     where x.id = w.id;
  else
    if (w.shape_disposition,w.shape_fixed_surface_ref,w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at)
         is distinct from (null::text,null::text,null::text,null::uuid,null::timestamptz)
       or exists (select 1 from ops.work_shape_revision sr where sr.work_request_id = w.id) then
      raise exception 'only the exact current unshaped triaged sourced Work Request may record a shape disposition';
    end if;
    if p_disposition = 'not_required' then
      classification := ops.heavy_build_classification(w.id, '', '[]'::jsonb, '{}'::jsonb);
      if classification is null or classification->>'tier' is distinct from 'standard' then
        raise exception 'an intrinsically heavy sourced Work Request requires a Work Shape; not_required is refused';
      end if;
    end if;
    insert into ops.sourced_work_request_shape_disposition_receipt
      (work_request_id,idempotency_key,base_version,result_version,disposition,fixed_surface_ref,rationale,decided_by_actor_id)
    values
      (w.id,p_idempotency_key,p_base_version,w.version + 1,p_disposition,normalized_fixed_surface,normalized_rationale,p_decided_by_actor_id)
    returning * into original;
    update ops.work_request x
       set shape_disposition = original.disposition,
           shape_fixed_surface_ref = original.fixed_surface_ref,
           shape_rationale = original.rationale,
           shape_decided_by_actor_id = original.decided_by_actor_id,
           shape_decided_at = original.decided_at,
           version = original.result_version,
           updated_at = now()
     where x.id = w.id;
  end if;
  select x.* into w from ops.work_request x where x.id = w.id;
  return query select w.id,w.ref,w.state,w.version,w.shape_disposition,w.shape_fixed_surface_ref,
    w.shape_rationale,w.shape_decided_by_actor_id,w.shape_decided_at,false;
end;
$_$;


--
-- Name: settle_job_cost(uuid, uuid, uuid, integer, integer, numeric); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.settle_job_cost(p_reservation_id uuid, p_job_id uuid, p_lease_token uuid, p_input_tokens integer, p_output_tokens integer, p_actual_cost_usd numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; r ops.cost_reservation%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state<>'running' or j.lease_token<>p_lease_token or j.leased_until<now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  select * into r from ops.cost_reservation where id=p_reservation_id for update;
  if not found or r.job_id<>j.id or r.attempt<>j.attempt or r.state<>'reserved' then
    raise exception 'cost reservation does not belong to this live attempt';
  end if;
  if p_actual_cost_usd<0 or p_actual_cost_usd>r.estimated_cost_usd then
    raise exception 'actual cost exceeds admitted reservation';
  end if;
  update ops.cost_reservation set state='settled',actual_cost_usd=p_actual_cost_usd,
         settled_at=now() where id=r.id;
  update ops.job_attempt set provider_route=r.route_key,input_tokens=p_input_tokens,
         output_tokens=p_output_tokens,cost_usd=p_actual_cost_usd
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  return true;
end $$;


--
-- Name: share_doc_conversation(uuid, text, boolean, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.share_doc_conversation(p_conversation uuid, p_grantee_slug text, p_granted boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_actor uuid; v_row ops.doc_conversation%rowtype; v_grantee uuid;
        v_existing boolean; v_remaining integer;
begin
  v_actor := ops.portfolio_writer_actor_id();

  select * into v_row from ops.doc_conversation where id = p_conversation;
  -- Absent, or invisible to this actor: one answer for both.
  if v_row.id is null
     or not (v_row.created_by_actor = v_actor
             or exists (select 1 from ops.doc_conversation_grant g
                         where g.conversation_id = v_row.id and g.grantee_actor = v_actor
                           and g.revoked_at is null)) then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_not_found');
  end if;
  -- Visible but not the creator. BEFORE ANY WRITE.
  if v_row.created_by_actor <> v_actor then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_creator_only');
  end if;

  select id into v_grantee from public.actor
   where slug = p_grantee_slug and active = true;
  if v_grantee is null then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_grantee_not_found');
  end if;
  -- The creator is already visible by 0520:186; a self-grant would put a
  -- meaningless row in effective_grants.
  if v_grantee = v_actor then
    return jsonb_build_object('ok', false, 'reason_id', 'doc_conversation_grantee_is_creator');
  end if;

  v_existing := exists (select 1 from ops.doc_conversation_grant
                         where conversation_id = p_conversation and grantee_actor = v_grantee
                           and revoked_at is null);

  if p_granted then
    if v_existing then
      return jsonb_build_object('ok', true, 'already', true, 'granted', true,
        'conversation_id', p_conversation, 'grantee_slug', p_grantee_slug);
    end if;
    -- clock_timestamp(), NOT the column default. The primary key is
    -- (conversation_id, grantee_actor, granted_at) (0520:67) and now() is
    -- constant for a whole transaction, so grant -> revoke -> re-grant inside
    -- one transaction would collide on the key with the default.
    insert into ops.doc_conversation_grant(
      conversation_id, grantee_actor, granted_at, granted_by_actor)
    values (p_conversation, v_grantee, clock_timestamp(), v_actor);
    -- The header field the read door already returns (0520:218). Leaving it
    -- stale would make the app show "private" for a shared conversation. No
    -- version bump: sharing is not a rename, the caller never read a version to
    -- swap against, and bumping it would invalidate a rename in flight.
    update ops.doc_conversation
       set visibility = 'shared', updated_at = now()
     where id = p_conversation;
    return jsonb_build_object('ok', true, 'already', false, 'granted', true,
      'conversation_id', p_conversation, 'grantee_slug', p_grantee_slug);
  end if;

  update ops.doc_conversation_grant set revoked_at = now()
   where conversation_id = p_conversation and grantee_actor = v_grantee
     and revoked_at is null;
  if not found then
    -- Revoking what is not granted is a no-op, not an error.
    return jsonb_build_object('ok', true, 'already', true, 'granted', false,
      'conversation_id', p_conversation, 'grantee_slug', p_grantee_slug);
  end if;
  select count(*) into v_remaining from ops.doc_conversation_grant
   where conversation_id = p_conversation and revoked_at is null;
  update ops.doc_conversation
     set visibility = case when v_remaining = 0 then 'private' else 'shared' end,
         updated_at = now()
   where id = p_conversation;
  return jsonb_build_object('ok', true, 'already', false, 'granted', false,
    'conversation_id', p_conversation, 'grantee_slug', p_grantee_slug);
end $$;


--
-- Name: FUNCTION share_doc_conversation(p_conversation uuid, p_grantee_slug text, p_granted boolean, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.share_doc_conversation(p_conversation uuid, p_grantee_slug text, p_granted boolean, p_idempotency_key uuid) IS 'WR-000114: the only door that widens or withdraws access to a Doc conversation. Creator-only, raised inside this body before any write; a withdrawal STAMPS revoked_at and never deletes, so the grantor and the moment survive for the audit.';


--
-- Name: siep_acquire_lane_lock(text, text, integer, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_acquire_lane_lock(p_component text, p_session_ref text, p_lease_seconds integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare k text; aid uuid; tok uuid; current_lock ops.siep_lane_lock%rowtype;
        c ops.siep_package_contract%rowtype; w ops.work_request%rowtype;
        prior ops.siep_command_receipt%rowtype; request_digest text; result jsonb;
begin
  k:=ops.siep_resolve_package(p_component);
  select * into c from ops.siep_package_contract where package_key=k;
  select id into aid from public.actor where slug='system' and active;
  if k is null or aid is null
     or coalesce(p_session_ref,'') !~ '^session:[a-zA-Z0-9._:-]{1,240}$' or p_lease_seconds not between 60 and 3600
     or p_idempotency_key is null then raise exception 'bounded typed SIEP lane lock fields are required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-package:'||k,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-lane:'||c.lane_key,0));
  request_digest:=ops.siep_request_digest(jsonb_build_object(
    'package_key',k,'session_ref',p_session_ref,'lease_seconds',p_lease_seconds));
  if exists(select 1 from ops.siep_evidence_link where idempotency_key=p_idempotency_key) then
    raise exception 'idempotency_key_reuse: SIEP evidence key cannot be reused for a command';
  end if;
  select * into prior from ops.siep_command_receipt where idempotency_key=p_idempotency_key;
  if found then
    if prior.verb<>'acquire_lane' or prior.package_key<>k or prior.request_digest<>request_digest then
      raise exception 'idempotency_key_reuse: SIEP lane-lock inputs changed';
    end if;
    return prior.result||jsonb_build_object('replayed',true);
  end if;
  select * into w from ops.work_request where id=c.work_request_id for update;
  select * into current_lock from ops.siep_lane_lock where lane_key=c.lane_key for update;
  if current_lock.lane_key is not null and current_lock.expires_at>now() then
    raise exception 'SIEP lane % is already locked by another lease',c.lane_key;
  end if;
  if current_lock.lane_key is not null and current_lock.package_key<>k and exists(
    select 1 from ops.siep_package_contract pc join ops.work_request pw on pw.id=pc.work_request_id
     where pc.package_key=current_lock.package_key and pw.state not in ('ready','confirmed_closed')
  ) then raise exception 'SIEP lane recovery must resume the prior nonterminal package'; end if;
  if exists(select 1 from ops.siep_package_contract pc join ops.work_request pw on pw.id=pc.work_request_id
     where pc.lane_key=c.lane_key and pc.package_key<>k
       and pw.state not in ('ready','confirmed_closed')) then
    raise exception 'SIEP lane has another nonterminal package requiring recovery';
  end if;
  if w.state not in ('ready','claimed','in_progress','verification','awaiting_release','released') then raise exception 'SIEP package cannot acquire a lane in state %',w.state; end if;
  tok:=gen_random_uuid();
  insert into ops.siep_lane_lock(lane_key,package_key,work_request_version,holder_actor_id,executor_tier,session_ref,lease_token,expires_at,idempotency_key)
  values(c.lane_key,k,w.version,aid,c.minimum_executor_tier,p_session_ref,tok,now()+make_interval(secs=>p_lease_seconds),p_idempotency_key)
  on conflict(lane_key) do update set package_key=excluded.package_key,work_request_version=excluded.work_request_version,
    holder_actor_id=excluded.holder_actor_id,executor_tier=excluded.executor_tier,
    session_ref=excluded.session_ref,lease_token=excluded.lease_token,acquired_at=now(),expires_at=excluded.expires_at,idempotency_key=excluded.idempotency_key;
  insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,old_value,new_value,cause,agent_rationale,idempotency_key)
  values(now(),aid,'siep-acquire-lane-lock','work_request',w.id,'lane_lock',null,
    jsonb_build_object('package_key',k,
      'session_digest','sha256:'||encode(public.digest(p_session_ref,'sha256'),'hex'),
      'lease_seconds',p_lease_seconds,
      'lane_key',c.lane_key,'work_request_version',w.version),
    'system','typed SIEP lane acquisition',null);
  select jsonb_build_object('lane_key',c.lane_key,'package_key',k,'work_request_version',w.version,
    'lease_digest','sha256:'||encode(public.digest(lease_token::text,'sha256'),'hex'),
    'expires_at',expires_at) into result
    from ops.siep_lane_lock where lane_key=c.lane_key and package_key=k;
  insert into ops.siep_command_receipt(idempotency_key,verb,package_key,request_digest,result,recorded_actor_id)
  values(p_idempotency_key,'acquire_lane',k,request_digest,result,aid);
  -- The raw lease token is a one-time delivery secret.  Exact replay remains a
  -- no-op and returns the stable safe result, never a shared-role token oracle.
  return result||jsonb_build_object('lease_token',tok,'replayed',false);
end $_$;


--
-- Name: siep_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'SIEP program contracts, dependencies, aliases, and evidence links are append-only';
end $$;


--
-- Name: siep_attach_evidence(text, text, uuid, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_attach_evidence(p_component text, p_evidence_kind text, p_ledger_id uuid, p_ledger_kind text, p_evidence_digest text, p_note text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare k text; aid uuid; prior ops.siep_evidence_link%rowtype; eid uuid; actor_slug text;
        w ops.work_request%rowtype; c ops.siep_package_contract%rowtype;
        source_row jsonb; source_at timestamptz;
        server_digest text;
begin
  k:=ops.siep_resolve_package(p_component);
  if k is null or p_idempotency_key is null or p_note !~ '^safe:[a-z0-9][a-z0-9:_./-]*$' or char_length(p_note)>300 then
    raise exception 'known SIEP package, safe reference, and UUID idempotency key are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  select * into prior from ops.siep_evidence_link where idempotency_key=p_idempotency_key;
  if found then
    if (prior.package_key,prior.evidence_kind,prior.ledger_kind,prior.ledger_id,prior.evidence_digest,prior.note)
       is distinct from (k,p_evidence_kind,p_ledger_kind,p_ledger_id,p_evidence_digest,p_note) then
      raise exception 'idempotency_key_reuse: SIEP evidence inputs changed';
    end if;
    return jsonb_build_object('id',prior.id,'package_key',prior.package_key,'replayed',true);
  end if;
  if exists(select 1 from ops.siep_command_receipt where idempotency_key=p_idempotency_key) then
    raise exception 'idempotency_key_reuse: SIEP command key cannot be reused for evidence';
  end if;
  select w0.* into w from ops.work_request w0 join ops.siep_package_contract pc on pc.work_request_id=w0.id where pc.package_key=k for share;
  select * into c from ops.siep_package_contract where package_key=k;
  case p_ledger_kind
    when 'job_receipt' then
      select system_actor.id,jsonb_build_object('receipt',to_jsonb(r),'job',to_jsonb(j),
                                                'attempt',to_jsonb(ja),'binding',to_jsonb(b)),r.created_at
        into aid,source_row,source_at
        from ops.job_receipt r join ops.job j on j.id=r.job_id
        join ops.job_attempt ja on ja.job_id=j.id and ja.attempt=r.attempt
        join ops.siep_job_evidence_binding b on b.job_id=j.id
        join public.actor system_actor on system_actor.slug='system' and system_actor.active
       where r.id=p_ledger_id and j.payload->>'work_request'=w.ref
         and j.state='succeeded' and ja.state='succeeded'
         and j.attempt=r.attempt and r.kind='completion'
         and b.package_key=k and b.work_request_version=w.version
         and b.manifest_digest=ops.siep_manifest_digest()
         and b.evidence_kind=p_evidence_kind
         and b.definition_key=j.definition_key and b.definition_version=j.definition_version;
    when 'decision_event' then
      select e.actor_id,to_jsonb(e),e.occurred_at into aid,source_row,source_at
        from public.event e where e.id=p_ledger_id and e.verb='siep-joe-decision'
          and e.new_value->>'package_key'=k;
    else source_row:=null;
  end case;
  if source_row is null or aid is null then raise exception 'evidence target is not a valid package-bound canonical fact'; end if;
  if source_at>now()+interval '1 minute' then raise exception 'future SIEP evidence is refused'; end if;
  if source_at < (case when p_evidence_kind in ('joe_approval','joe_go_no_go') then w.captured_at
                       else coalesce(w.claimed_at,w.captured_at) end) then
    raise exception 'stale SIEP evidence predates the package execution boundary';
  end if;
  server_digest:=ops.siep_current_evidence_digest(p_ledger_kind,p_ledger_id);
  if p_evidence_digest is distinct from server_digest then raise exception 'SIEP evidence digest does not match its canonical ledger row'; end if;
  if p_ledger_kind='job_receipt' and not (
       source_row#>>'{job,definition_key}'='engineering-slice'
       and source_row#>>'{job,definition_version}'='1'
       and source_row#>>'{job,payload,manifest_digest}'=ops.siep_manifest_digest()
     ) then
    raise exception 'SIEP evidence requires the fixed package-purpose verifier contract';
  end if;
  select slug into actor_slug from public.actor where id=aid;
  if p_evidence_kind in ('joe_approval','joe_go_no_go')
     and (session_user<>'carr_authority_joe' or p_ledger_kind<>'decision_event' or actor_slug<>'joe') then
    raise exception 'Joe approval evidence requires the authenticated Joe authority session and a package-bound Joe decision';
  end if;
  if p_evidence_kind in ('joe_approval','joe_go_no_go') and not (
       source_row#>>'{new_value,package_key}'=k
       and source_row#>>'{new_value,gate}'=p_evidence_kind
       and source_row#>>'{new_value,manifest_digest}'=ops.siep_manifest_digest()
       and source_row#>>'{new_value,decision}'=case when p_evidence_kind='joe_go_no_go' then 'go' else 'approved' end
     ) then raise exception 'Joe approval evidence requires an exact positive typed decision'; end if;
  if p_evidence_kind in ('independent_review','live_readback','zero_unresolved_findings',
                         'zero_blockers','two_clean_audit_cycles') then
    if session_user<>'carr_authority_joe' then
      raise exception 'SIEP independent and terminal evidence requires the authenticated Joe authority session';
    end if;
    select id into aid from public.actor where slug='joe' and active;
    if aid is null or w.executor_actor='joe' then
      raise exception 'independent authority evidence requires active Joe distinct from the package executor';
    end if;
  end if;
  if p_evidence_kind not in ('joe_approval','joe_go_no_go') and not (
       p_ledger_kind='job_receipt' and source_row#>>'{receipt,evidence,status}'='pass'
       and source_row#>>'{receipt,evidence,operation}'=
         case when p_evidence_kind='two_clean_audit_cycles' then 'clean_audit_cycle' else p_evidence_kind end
     ) then raise exception 'SIEP evidence requires a successful package-bound lease completion receipt'; end if;
  if p_evidence_kind='source' and coalesce(source_row#>>'{receipt,evidence,commit_sha}','') !~ '^[0-9a-f]{40,64}$'
    then raise exception 'source evidence requires a commit-bound receipt'; end if;
  if p_evidence_kind='tests' and coalesce(source_row#>>'{receipt,evidence,result_digest}','') !~ '^sha256:[0-9a-f]{64}$'
    then raise exception 'test evidence requires a result-bound receipt'; end if;
  if p_evidence_kind in ('readback','live_readback')
     and coalesce(source_row#>>'{receipt,evidence,target_ref}','') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
    then raise exception 'readback evidence requires a typed target'; end if;
  if p_evidence_kind='rollback'
     and coalesce(source_row#>>'{receipt,evidence,recovery_ref}','') !~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
    then raise exception 'rollback evidence requires a typed recovery reference'; end if;
  if p_evidence_kind='independent_review'
     and coalesce(source_row#>>'{receipt,evidence,reviewed_artifact_digest}','') !~ '^sha256:[0-9a-f]{64}$'
    then raise exception 'independent review requires an authority-attested artifact-bound receipt'; end if;
  if p_evidence_kind in ('zero_unresolved_findings','zero_blockers') and not (
       source_row#>>'{receipt,evidence,count}'='0'
       and coalesce(source_row#>>'{receipt,evidence,baseline_digest}','') ~ '^sha256:[0-9a-f]{64}$'
     ) then raise exception 'zero-state evidence requires a baseline-bound canonical zero count'; end if;
  if p_evidence_kind='material_fix' and not (
       coalesce(source_row#>>'{receipt,evidence,commit_sha}','') ~ '^[0-9a-f]{40,64}$'
     ) then raise exception 'material-fix evidence requires a commit-bound receipt';
  end if;
  if p_evidence_kind='two_clean_audit_cycles' and not (
    (source_row#>>'{receipt,evidence,cycle}') in ('1','2')
    and (source_row#>>'{receipt,evidence,unresolved_count}')='0'
    and (source_row#>>'{receipt,evidence,blocker_count}')='0'
    and coalesce(source_row#>>'{receipt,evidence,baseline_digest}','') ~ '^sha256:[0-9a-f]{64}$'
    and coalesce(source_row#>>'{receipt,evidence,run_id}','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) then raise exception 'clean audit evidence must be a zero-finding zero-blocker canonical cycle'; end if;
  insert into ops.siep_evidence_link(package_key,evidence_kind,ledger_kind,ledger_id,work_request_version,
    manifest_digest,evidence_digest,note,linked_actor_id,attested_session_principal,source_observed_at,idempotency_key)
  values(k,p_evidence_kind,p_ledger_kind,p_ledger_id,w.version,ops.siep_manifest_digest(),
    p_evidence_digest,p_note,aid,session_user,source_at,p_idempotency_key)
  returning id into eid;
  return jsonb_build_object('id',eid,'package_key',k,'replayed',false);
end $_$;


--
-- Name: siep_bind_evidence_job(text, integer, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_bind_evidence_job(p_component text, p_base_version integer, p_evidence_kind text, p_job_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare result jsonb; contract_version text;
begin
  result:=ops.siep_bind_evidence_job_unchecked_0324(p_component,p_base_version,p_evidence_kind,p_job_id,p_idempotency_key);
  select b.engineering_contract_version into contract_version
    from ops.siep_job_evidence_binding b
    join ops.engineering_execution_envelope envelope on envelope.job_id=b.job_id
   where b.job_id=p_job_id
     and not exists (
       select 1 from ops.engineering_execution_envelope successor
        where successor.supersedes_envelope_id=envelope.id
     )
     and 1=(
       select count(*) from ops.engineering_execution_envelope leaf
        where leaf.slice_plan_id=envelope.slice_plan_id
          and leaf.slice_ref=envelope.slice_ref
          and not exists (
            select 1 from ops.engineering_execution_envelope successor
             where successor.supersedes_envelope_id=leaf.id
          )
     );
  if contract_version is distinct from 'engineering-review.v1' then
    raise exception 'historical or superseded SIEP Engineering evidence binding is not 0335 verified';
  end if;
  return result;
end $$;


--
-- Name: siep_bind_evidence_job_unchecked_0324(text, integer, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_bind_evidence_job_unchecked_0324(p_component text, p_base_version integer, p_evidence_kind text, p_job_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare k text; w ops.work_request%rowtype; existing ops.siep_job_evidence_binding%rowtype;
        aid uuid; result jsonb;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP evidence binding requires the authenticated Joe authority session';
  end if;
  k:=ops.siep_resolve_package(p_component);
  if k is null or p_base_version is null or p_job_id is null or p_idempotency_key is null
     or p_evidence_kind not in ('source','tests','migration','deploy','readback','live_readback',
       'rollback','independent_review','zero_unresolved_findings','zero_blockers',
       'two_clean_audit_cycles','material_fix') then
    raise exception 'known package, version, purpose, admitted job, and idempotency key are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-evidence-job:'||p_job_id,0));
  select * into existing from ops.siep_job_evidence_binding
   where idempotency_key=p_idempotency_key or job_id=p_job_id order by bound_at limit 1;
  if found then
    if (existing.package_key,existing.work_request_version,existing.evidence_kind,existing.job_id)
       is distinct from (k,p_base_version,p_evidence_kind,p_job_id) then
      raise exception 'idempotency_key_reuse: SIEP evidence binding inputs changed';
    end if;
    return jsonb_build_object('job_id',existing.job_id,'package_key',existing.package_key,
      'evidence_kind',existing.evidence_kind,'replayed',true);
  end if;
  select w0.* into w from ops.work_request w0 join ops.siep_package_contract c
    on c.work_request_id=w0.id where c.package_key=k for share;
  if w.version<>p_base_version then raise exception 'SIEP evidence binding requires the exact Work Request version'; end if;
  select id into aid from public.actor where slug='joe' and active;
  if aid is null then raise exception 'active Joe actor is required'; end if;
  if not exists(
    select 1 from ops.job j
      join ops.engineering_execution_envelope env on env.job_id=j.id and env.work_request_id=w.id
      join ops.engineering_slice_plan sp on sp.id=env.slice_plan_id and sp.work_request_id=w.id
      join ops.engineering_slice_receipt er on er.envelope_id=env.id and er.work_request_id=w.id
      join ops.job_attempt ja on ja.id=er.job_attempt_id and ja.job_id=j.id
        and ja.attempt=j.attempt and ja.state='succeeded'
      join ops.engineering_reviewer_fact rf on rf.receipt_id=er.id and rf.work_request_id=w.id
     where j.id=p_job_id and j.definition_key='engineering-slice' and j.definition_version=1
       and j.payload->>'work_request'=w.ref and j.state='succeeded'
       and env.state_version=p_base_version and sp.work_request_version=p_base_version
       and er.outcome='claimed_complete' and rf.state='passed'
       and rf.reviewer_actor_id=aid and rf.reviewer_actor_id<>er.executor_actor_id
       and exists(select 1 from ops.job_receipt jr where jr.job_id=j.id
                    and jr.attempt=j.attempt and jr.kind='completion')
  ) then
    raise exception 'SIEP evidence binding requires an exact independently reviewed engineering envelope and completion';
  end if;
  insert into ops.siep_job_evidence_binding(job_id,package_key,work_request_version,
    manifest_digest,evidence_kind,definition_key,definition_version,bound_by_actor_id,idempotency_key)
  values(p_job_id,k,p_base_version,ops.siep_manifest_digest(),p_evidence_kind,
    'engineering-slice',1,aid,p_idempotency_key);
  result:=jsonb_build_object('job_id',p_job_id,'package_key',k,
    'evidence_kind',p_evidence_kind,'replayed',false);
  return result;
end $$;


--
-- Name: siep_claim_package(text, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_claim_package(p_component text, p_session_ref text, p_lease_token uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare k text; w ops.work_request%rowtype; c ops.siep_package_contract%rowtype;
        a public.actor%rowtype; prior ops.siep_command_receipt%rowtype; lane ops.siep_lane_lock%rowtype;
        result jsonb; request_digest text;
begin
  k:=ops.siep_resolve_package(p_component);
  if k is null or p_idempotency_key is null or p_lease_token is null
     or coalesce(p_session_ref,'') !~ '^session:[a-zA-Z0-9._:-]{1,240}$' then
    raise exception 'known SIEP package, bounded session, lease token, and UUID idempotency key are required';
  end if;
  select * into c from ops.siep_package_contract where package_key=k;
  select * into a from public.actor where slug='system' and active for share;
  if not found then raise exception 'active system actor is required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-package:'||k,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-lane:'||c.lane_key,0));
  request_digest:=ops.siep_request_digest(jsonb_build_object(
    'package_key',k,'session_ref',p_session_ref,'lease_token',p_lease_token));
  if exists(select 1 from ops.siep_evidence_link where idempotency_key=p_idempotency_key) then
    raise exception 'idempotency_key_reuse: SIEP evidence key cannot be reused for a command';
  end if;
  select * into prior from ops.siep_command_receipt where idempotency_key=p_idempotency_key;
  if found then
    if prior.verb<>'claim' or prior.package_key<>k or prior.request_digest<>request_digest then
      raise exception 'idempotency_key_reuse: SIEP claim inputs changed';
    end if;
    return prior.result||jsonb_build_object('replayed',true);
  end if;
  select w0.* into w from ops.work_request w0 where w0.id=c.work_request_id for update;
  if w.state<>'ready' then raise exception 'SIEP package % is %, not ready',k,w.state; end if;
  select * into lane from ops.siep_lane_lock where lane_key=c.lane_key for update;
  if not found or lane.package_key<>k or lane.holder_actor_id<>a.id
     or lane.executor_tier<>c.minimum_executor_tier or lane.work_request_version<>w.version
     or lane.session_ref<>p_session_ref or lane.lease_token<>p_lease_token
     or lane.expires_at<=now() then
    raise exception 'SIEP claim requires the exact live server-derived lane lock and Work Request version';
  end if;
  if exists (select 1 from ops.siep_program_dependency d join ops.siep_package_contract dc on dc.package_key=d.depends_on_package_key
             join ops.work_request dw on dw.id=dc.work_request_id where d.package_key=k and dw.state<>'confirmed_closed') then
    raise exception 'SIEP package % has unresolved dependencies',k;
  end if;
  if c.approval_gate<>'none' and not ops.siep_current_approval(k,w.version,c.approval_gate)
    then raise exception 'SIEP package % admission requires %',k,c.approval_gate; end if;
  result:=jsonb_build_object('package_key',k,'state','claimed','version',w.version+1,
                             'executor_actor','system','executor_tier',c.minimum_executor_tier,
                             'lane_key',c.lane_key,'session_ref',p_session_ref,
                             'lease_digest','sha256:'||encode(public.digest(p_lease_token::text,'sha256'),'hex'));
  insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,old_value,new_value,cause,agent_rationale,idempotency_key)
  values(now(),a.id,'siep-claim-package','work_request',w.id,'state',to_jsonb(w.state),
         result,
         'system','typed SIEP dependency-first claim',p_idempotency_key::text);
  update ops.work_request set state='claimed',executor_actor='system',claimed_at=now(),updated_at=now(),version=version+1 where id=w.id;
  update ops.siep_lane_lock set work_request_version=w.version+1
   where lane_key=c.lane_key and lease_token=p_lease_token and session_ref=p_session_ref;
  insert into ops.siep_command_receipt(idempotency_key,verb,package_key,request_digest,result,recorded_actor_id)
  values(p_idempotency_key,'claim',k,request_digest,result,a.id);
  return result||jsonb_build_object('replayed',false);
end $_$;


--
-- Name: siep_current_approval(text, integer, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_current_approval(p_package_key text, p_work_request_version integer, p_gate text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select exists(
    select 1 from ops.siep_package_contract c
      join ops.work_request w on w.id=c.work_request_id
      join ops.siep_evidence_link e on e.package_key=c.package_key
      join public.event d on d.id=e.ledger_id and e.ledger_kind='decision_event'
      join public.actor joe on joe.id=d.actor_id and joe.slug='joe' and joe.active
     where c.package_key=p_package_key and c.approval_gate=p_gate
       and p_gate in ('joe_approval','joe_go_no_go')
       and e.work_request_version=p_work_request_version and e.evidence_kind=p_gate
       and e.manifest_digest=ops.siep_manifest_digest()
       and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)
       and e.source_observed_at=d.occurred_at and d.verb='siep-joe-decision'
       and d.new_value->>'package_key'=c.package_key
       and d.new_value->>'gate'=c.approval_gate
       and d.new_value->>'manifest_digest'=ops.siep_manifest_digest()
       and d.new_value->>'decision'=case when p_gate='joe_go_no_go' then 'go' else 'approved' end
       and d.occurred_at>=coalesce((
         select max(dw.closed_at) from ops.siep_program_dependency dep
           join ops.siep_package_contract dc on dc.package_key=dep.depends_on_package_key
           join ops.work_request dw on dw.id=dc.work_request_id
          where dep.package_key=c.package_key
       ),w.captured_at)
       and not exists(
         select 1 from public.event later
          where later.actor_id=joe.id and later.verb='siep-joe-decision'
            and later.new_value->>'package_key'=c.package_key
            and later.new_value->>'gate'=c.approval_gate
            and (later.occurred_at,later.id)>(d.occurred_at,d.id)
       )
  )
$$;


--
-- Name: siep_current_evidence_digest(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_current_evidence_digest(p_ledger_kind text, p_ledger_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(source_row),'sha256'),'hex')
    from (
      select jsonb_build_object('receipt',to_jsonb(r),'job',to_jsonb(j),'attempt',to_jsonb(a),
                                'binding',to_jsonb(b)) source_row
        from ops.job_receipt r join ops.job j on j.id=r.job_id
        join ops.job_attempt a on a.job_id=j.id and a.attempt=r.attempt
        join ops.siep_job_evidence_binding b on b.job_id=j.id
        join ops.engineering_execution_envelope envelope on envelope.job_id=j.id
       where p_ledger_kind='job_receipt' and r.id=p_ledger_id
         and b.engineering_contract_version='engineering-review.v1'
         and not exists (
           select 1 from ops.engineering_execution_envelope successor
            where successor.supersedes_envelope_id=envelope.id
         )
         and 1=(
           select count(*) from ops.engineering_execution_envelope leaf
            where leaf.slice_plan_id=envelope.slice_plan_id
              and leaf.slice_ref=envelope.slice_ref
              and not exists (
                select 1 from ops.engineering_execution_envelope successor
                 where successor.supersedes_envelope_id=leaf.id
              )
         )
      union all select to_jsonb(e) from public.event e
       where p_ledger_kind='decision_event' and e.id=p_ledger_id
    ) canonical
$$;


--
-- Name: siep_evidence_actor(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_evidence_actor(p_ledger_kind text, p_ledger_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare aid uuid;
begin
  case p_ledger_kind
    when 'job_receipt' then select a.id into aid from ops.job_receipt r join ops.job j on j.id=r.job_id join public.actor a on a.slug=coalesce(j.lease_owner,'system') where r.id=p_ledger_id;
    when 'decision_event' then select actor_id into aid from public.event where id=p_ledger_id and verb='siep-joe-decision';
    else aid:=null;
  end case;
  if aid is null then raise exception 'evidence target does not exist in its canonical ledger'; end if;
  return aid;
end $$;


--
-- Name: siep_evidence_node_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_evidence_node_digest(p_row jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(
    ops.guidance_import_canonical_json(p_row),'sha256'),'hex')
$$;


--
-- Name: siep_joe_decision_event_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_joe_decision_event_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare old_scoped boolean:=false; new_scoped boolean:=false;
begin
  if tg_op<>'INSERT' then
    select old.verb='siep-joe-decision'
      and old.new_value->>'program_key'='carr-system-integrity-elimination-v1'
      and ops.siep_resolve_package(old.new_value->>'package_key') is not null
      and old.new_value->>'gate' in ('joe_approval','joe_go_no_go')
      into old_scoped;
  end if;
  if tg_op<>'DELETE' then
    select new.verb='siep-joe-decision'
      and new.new_value->>'program_key'='carr-system-integrity-elimination-v1'
      and ops.siep_resolve_package(new.new_value->>'package_key') is not null
      and new.new_value->>'gate' in ('joe_approval','joe_go_no_go')
      into new_scoped;
  end if;
  if tg_op='INSERT' and new_scoped and session_user<>'carr_authority_joe' then
    raise exception 'SIEP Joe decisions require the authenticated Joe authority session';
  end if;
  if tg_op in ('UPDATE','DELETE') and (old_scoped or new_scoped) then
    raise exception 'SIEP Joe decision events are immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


--
-- Name: siep_manifest_digest(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_manifest_digest() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(jsonb_build_object(
    'program_key','carr-system-integrity-elimination-v1',
    'packages',(select jsonb_agg(jsonb_build_object('key',c.package_key,'work_request',w.ref,
      'ordinal',w.program_ordinal,'title',w.title,'lane',c.lane_key,'tier',c.minimum_executor_tier,
      'approval_gate',c.approval_gate,'test_contract',c.test_contract,
      'delivery_contract',c.delivery_contract,'rollback_contract',c.rollback_contract,
      'required_evidence_kinds',to_jsonb(c.required_evidence_kinds)) order by w.program_ordinal)
      from ops.siep_package_contract c join ops.work_request w on w.id=c.work_request_id),
    'dependencies',(select jsonb_agg(jsonb_build_array(package_key,depends_on_package_key)
      order by package_key,depends_on_package_key) from ops.siep_program_dependency),
    'aliases',(select jsonb_agg(jsonb_build_array(alias_key,package_key) order by alias_key)
      from ops.siep_component_alias)
  )),'sha256'),'hex')
$$;


--
-- Name: siep_manifest_insert_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_manifest_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'the reviewed SIEP package, dependency, and alias manifest is sealed';
end $$;


--
-- Name: siep_program_identity_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_program_identity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if old.program_key='carr-system-integrity-elimination-v1'
     and (to_jsonb(new)-array['state','executor_actor','claimed_at','started_at','closed_at','updated_at','version',
                                  'completion_kind','completion_evidence','verification_accepted_at','verification_evidence_ref'])
         is distinct from
         (to_jsonb(old)-array['state','executor_actor','claimed_at','started_at','closed_at','updated_at','version',
                                  'completion_kind','completion_evidence','verification_accepted_at','verification_evidence_ref']) then
    raise exception 'SIEP package identity and contract projection are immutable';
  end if;
  return new;
end $$;


--
-- Name: siep_program_transition_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_program_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  if old.program_key is distinct from 'carr-system-integrity-elimination-v1' then return new; end if;
  if old.state='confirmed_closed' and new is distinct from old then raise exception 'closed SIEP package is immutable'; end if;
  if old.state is not distinct from new.state and new is distinct from old then raise exception 'SIEP package mutations require a typed state transition'; end if;
  if old.state is distinct from new.state and (old.state,new.state) not in (
    ('ready','claimed'),('claimed','in_progress'),('in_progress','verification'),
    ('verification','awaiting_release'),('awaiting_release','released'),('released','confirmed_closed')
  ) then raise exception 'invalid SIEP package state transition'; end if;
  if new.version<>old.version+1 then raise exception 'SIEP package transitions require exact version plus one'; end if;
  if old.state='ready' and (new.executor_actor is distinct from 'system' or old.executor_actor is not null) then
    raise exception 'SIEP claim executor is server-derived';
  end if;
  if old.state<>'ready' and new.executor_actor is distinct from old.executor_actor then
    raise exception 'SIEP executor binding is immutable after claim';
  end if;
  if not exists(
    select 1 from public.event e where e.subject_type='work_request' and e.subject_id=old.id
      and e.verb=case when old.state='ready' then 'siep-claim-package' else 'siep-transition-package' end
      and e.old_value=to_jsonb(old.state) and e.new_value->>'state'=new.state
      and (e.new_value->>'version')::integer=new.version
  ) then raise exception 'SIEP package transition requires its exact command event'; end if;
  if new.state<>'confirmed_closed' and (
    new.completion_kind is distinct from old.completion_kind
    or new.completion_evidence is distinct from old.completion_evidence
    or new.verification_accepted_at is distinct from old.verification_accepted_at
    or new.verification_evidence_ref is distinct from old.verification_evidence_ref
    or new.closed_at is distinct from old.closed_at
  ) then raise exception 'SIEP completion fields may change only at terminal package closure'; end if;
  return new;
end $$;


--
-- Name: siep_read_evidence_graph(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_read_evidence_graph(p_component text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare
  k text;
  graph_body jsonb;
begin
  if p_component is not null then
    k:=ops.siep_resolve_package(p_component);
    if k is null then
      raise exception 'known SIEP package or component alias is required';
    end if;
  end if;

  with recursive
  selected_package as (
    select c.package_key
      from ops.siep_package_contract c
     where k is null or c.package_key=k
  ),
  graph_package(package_key) as (
    select package_key from selected_package
    union
    select d.depends_on_package_key
      from ops.siep_program_dependency d
      join graph_package g on g.package_key=d.package_key
  ),
  package_row as (
    select c.*,w.ref work_request_ref,w.title work_request_title,w.state work_request_state,
           w.version work_request_version,w.program_ordinal,w.executor_actor,
           w.captured_at,w.claimed_at,w.closed_at,
           ops.siep_evidence_node_digest(to_jsonb(c)) package_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(w)) work_request_node_digest
      from ops.siep_package_contract c
      join graph_package g on g.package_key=c.package_key
      join ops.work_request w on w.id=c.work_request_id
  ),
  evidence_row as (
    select e.*,w.version current_work_request_version,w.state work_request_state,
           ops.siep_evidence_node_digest(to_jsonb(e)) evidence_link_node_digest,
           ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id) current_digest,
           case e.ledger_kind
             when 'job_receipt' then jr.created_at
             when 'decision_event' then de.occurred_at
           end canonical_observed_at,
           b.package_key binding_package_key,b.work_request_version binding_work_request_version,
           b.manifest_digest binding_manifest_digest,b.evidence_kind binding_evidence_kind,
           b.job_id binding_job_id,jr.evidence->>'cycle' audit_cycle,
           case when e.ledger_kind='decision_event' then
             ops.siep_current_approval(e.package_key,e.work_request_version,e.evidence_kind)
             else true end authority_current,
           case when e.ledger_kind='job_receipt' then
             jr.id is not null and j.id is not null and ja.id is not null and b.job_id is not null
             and env.id is not null and sp.id is not null and er.id is not null and rf.id is not null
             and jr.kind='completion' and j.state='succeeded' and ja.state='succeeded'
             and j.attempt=jr.attempt and j.definition_key='engineering-slice'
             and j.definition_version=1 and j.payload->>'work_request'=w.ref
             and j.payload->>'manifest_digest'=b.manifest_digest
             and b.package_key=e.package_key and b.work_request_version=e.work_request_version
             and b.manifest_digest=e.manifest_digest and b.evidence_kind=e.evidence_kind
             and env.state_version=b.work_request_version
             and sp.work_request_version=b.work_request_version
             and env.accepted_plan_id=sp.accepted_plan_id
             and er.job_attempt_id=ja.id and er.outcome='claimed_complete'
             and er.slice_ref=env.slice_ref and rf.slice_ref=er.slice_ref
             and rf.state='passed' and rf.reviewer_actor_id=b.bound_by_actor_id
             and rf.reviewer_actor_id<>er.executor_actor_id
             and jr.evidence->>'status'='pass'
             and jr.evidence->>'operation'=case when e.evidence_kind='two_clean_audit_cycles'
               then 'clean_audit_cycle' else e.evidence_kind end
             and case e.evidence_kind
               when 'source' then coalesce(jr.evidence->>'commit_sha','') ~ '^[0-9a-f]{40,64}$'
               when 'tests' then coalesce(jr.evidence->>'result_digest','') ~ '^sha256:[0-9a-f]{64}$'
               when 'readback' then coalesce(jr.evidence->>'target_ref','') ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
               when 'live_readback' then coalesce(jr.evidence->>'target_ref','') ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
               when 'rollback' then coalesce(jr.evidence->>'recovery_ref','') ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
               when 'independent_review' then coalesce(jr.evidence->>'reviewed_artifact_digest','') ~ '^sha256:[0-9a-f]{64}$'
               when 'zero_unresolved_findings' then jr.evidence->>'count'='0'
                 and coalesce(jr.evidence->>'baseline_digest','') ~ '^sha256:[0-9a-f]{64}$'
               when 'zero_blockers' then jr.evidence->>'count'='0'
                 and coalesce(jr.evidence->>'baseline_digest','') ~ '^sha256:[0-9a-f]{64}$'
               when 'material_fix' then coalesce(jr.evidence->>'commit_sha','') ~ '^[0-9a-f]{40,64}$'
               when 'two_clean_audit_cycles' then jr.evidence->>'cycle' in ('1','2')
                 and jr.evidence->>'unresolved_count'='0' and jr.evidence->>'blocker_count'='0'
                 and coalesce(jr.evidence->>'baseline_digest','') ~ '^sha256:[0-9a-f]{64}$'
                 and coalesce(jr.evidence->>'run_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
               else true end
           when e.ledger_kind='decision_event' then
             de.id is not null and de.verb='siep-joe-decision'
             and de.subject_type='work_request' and de.subject_id=w.id
             and de.actor_id=e.linked_actor_id
             and e.attested_session_principal='carr_authority_joe'
             and de.new_value->>'program_key'='carr-system-integrity-elimination-v1'
             and de.new_value->>'package_key'=e.package_key
             and de.new_value->>'gate'=e.evidence_kind
             and pc.approval_gate=e.evidence_kind
             and de.new_value->>'manifest_digest'=e.manifest_digest
             and de.new_value->>'work_request_version'=e.work_request_version::text
             and de.new_value->>'decision'=case when e.evidence_kind='joe_go_no_go' then 'go' else 'approved' end
           else false end purpose_current
      from ops.siep_evidence_link e
      join graph_package s on s.package_key=e.package_key
      join ops.siep_package_contract pc on pc.package_key=e.package_key
      join ops.work_request w on w.id=pc.work_request_id
      left join ops.job_receipt jr on e.ledger_kind='job_receipt' and jr.id=e.ledger_id
      left join ops.job j on j.id=jr.job_id
      left join ops.job_attempt ja on ja.job_id=j.id and ja.attempt=jr.attempt
      left join ops.siep_job_evidence_binding b on b.job_id=j.id
      left join ops.engineering_execution_envelope env
        on env.job_id=j.id and env.work_request_id=w.id
      left join ops.engineering_slice_plan sp
        on sp.id=env.slice_plan_id and sp.work_request_id=w.id
      left join ops.engineering_slice_receipt er
        on er.envelope_id=env.id and er.job_attempt_id=ja.id and er.work_request_id=w.id
      left join ops.engineering_reviewer_fact rf
        on rf.receipt_id=er.id and rf.work_request_id=w.id
      left join public.event de on e.ledger_kind='decision_event' and de.id=e.ledger_id
  ),
  evidence_health as (
    select e.*,
      e.current_digest is not null
      and e.evidence_digest=e.current_digest
      and e.manifest_digest=ops.siep_manifest_digest()
      and (e.evidence_kind in ('joe_approval','joe_go_no_go') or
        case
          when e.work_request_state='released' then
            e.work_request_version between e.current_work_request_version-1 and e.current_work_request_version
          when e.work_request_state='confirmed_closed' then
            e.work_request_version between e.current_work_request_version-2 and e.current_work_request_version
          else e.work_request_version=e.current_work_request_version
        end)
      and e.canonical_observed_at=e.source_observed_at
      and e.canonical_observed_at<=now()+interval '1 minute'
      and e.purpose_current
      and e.authority_current as is_current,
      array_remove(array[
        case when e.current_digest is null then 'missing_source' end,
        case when e.current_digest is not null and e.evidence_digest<>e.current_digest then 'digest_mismatch' end,
        case when e.manifest_digest<>ops.siep_manifest_digest() then 'manifest_mismatch' end,
        case when e.evidence_kind not in ('joe_approval','joe_go_no_go') and not case
          when e.work_request_state='released' then
            e.work_request_version between e.current_work_request_version-1 and e.current_work_request_version
          when e.work_request_state='confirmed_closed' then
            e.work_request_version between e.current_work_request_version-2 and e.current_work_request_version
          else e.work_request_version=e.current_work_request_version
        end then 'stale_work_request_version' end,
        case when e.canonical_observed_at is distinct from e.source_observed_at then 'observed_at_mismatch' end,
        case when e.canonical_observed_at>now()+interval '1 minute' then 'future_source' end,
        case when not e.purpose_current then 'purpose_or_lineage_mismatch' end,
        case when not e.authority_current then 'superseded_authority' end
      ],null)::text[] health_reasons
    from evidence_row e
  ),
  job_source as (
    select h.id evidence_link_id,h.evidence_kind bound_evidence_kind,jr.*,j.state job_state,j.mode job_mode,
           j.definition_key,j.definition_version,j.attempt job_attempt,
           ja.id job_attempt_id,ja.state attempt_state,
           b.idempotency_key binding_idempotency_key,b.bound_by_actor_id,b.bound_at,
           env.id envelope_id,env.slice_plan_id,env.accepted_plan_id,env.agent_session_id,
           env.state_version,env.canonical_record_digest,env.envelope_digest,
           env.issued_at,env.expires_at,
           sp.plan_digest,sp.accepted_plan_hash,sp.work_request_version slice_work_request_version,
           ap.plan_ref,ap.plan_hash,ap.plan_version,
           er.id engineering_receipt_id,er.executor_actor_id,er.receipt_digest,
           er.outcome engineering_outcome,
           rf.id reviewer_fact_id,rf.reviewer_actor_id,rf.state reviewer_state,
           ops.siep_evidence_node_digest(to_jsonb(jr)) job_receipt_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(j)) job_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(ja)) job_attempt_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(b)) binding_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(env)) envelope_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(sp)) slice_plan_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(ap)) accepted_plan_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(er)) engineering_receipt_node_digest,
           ops.siep_evidence_node_digest(to_jsonb(rf)) reviewer_fact_node_digest
      from evidence_health h
      join ops.job_receipt jr on h.ledger_kind='job_receipt' and jr.id=h.ledger_id
      join ops.job j on j.id=jr.job_id
      join ops.job_attempt ja on ja.job_id=j.id and ja.attempt=jr.attempt
      join ops.siep_job_evidence_binding b on b.job_id=j.id
      left join ops.engineering_execution_envelope env on env.job_id=j.id
      left join ops.engineering_slice_plan sp on sp.id=env.slice_plan_id
      left join ops.sourced_work_request_plan ap on ap.id=env.accepted_plan_id
      left join ops.engineering_slice_receipt er
        on er.envelope_id=env.id and er.job_attempt_id=ja.id
      left join ops.engineering_reviewer_fact rf on rf.receipt_id=er.id
  ),
  authoritative_decision as (
    select d.*,a.slug actor_slug,a.active actor_active,
           ops.siep_evidence_node_digest(to_jsonb(d)) decision_node_digest,
           row_number() over(partition by d.new_value->>'package_key',d.new_value->>'gate'
             order by d.occurred_at,d.id) decision_ordinal,
           lag(d.id) over(partition by d.new_value->>'package_key',d.new_value->>'gate'
             order by d.occurred_at,d.id) prior_decision_id,
           true authoritative,d.new_value->>'package_key' projected_package_key
      from public.event d
      join public.actor a on a.id=d.actor_id
      join graph_package s on s.package_key=d.new_value->>'package_key'
      join ops.siep_package_contract pc on pc.package_key=s.package_key
      join ops.work_request w on w.id=pc.work_request_id and w.id=d.subject_id
     where d.verb='siep-joe-decision'
       and d.subject_type='work_request'
       and a.slug='joe' and a.active
       and d.new_value->>'program_key'='carr-system-integrity-elimination-v1'
       and d.new_value->>'gate'=pc.approval_gate
       and pc.approval_gate in ('joe_approval','joe_go_no_go')
       and d.new_value->>'manifest_digest'=ops.siep_manifest_digest()
       and coalesce(d.new_value->>'work_request_version','') ~ '^[1-9][0-9]*$'
       and case pc.approval_gate
         when 'joe_approval' then d.new_value->>'decision' in ('approved','rejected','revoked')
         when 'joe_go_no_go' then d.new_value->>'decision' in ('go','no_go','revoked')
         else false end
  ),
  attached_decision as (
    select d.*,a.slug actor_slug,a.active actor_active,
           ops.siep_evidence_node_digest(to_jsonb(d)) decision_node_digest,
           null::bigint decision_ordinal,null::uuid prior_decision_id,
           false authoritative,h.package_key projected_package_key
      from evidence_health h
      join public.event d on h.ledger_kind='decision_event' and d.id=h.ledger_id
      join public.actor a on a.id=d.actor_id
  ),
  decision_source as (
    select distinct on (id) * from (
      select * from authoritative_decision
      union all
      select * from attached_decision
    ) decision_union
    order by id,authoritative desc
  ),
  node as (
    select 'package:'||p.package_key node_key,'package' node_type,
      jsonb_build_object('package_key',p.package_key,'lane_key',p.lane_key,
        'minimum_executor_tier',p.minimum_executor_tier,'approval_gate',p.approval_gate,
        'required_evidence_kinds',to_jsonb(p.required_evidence_kinds)) attributes,
      p.package_node_digest node_digest
      from package_row p
    union all
    select 'work_request:'||p.work_request_id,'work_request',
      jsonb_build_object('ref',p.work_request_ref,'title',p.work_request_title,
        'state',p.work_request_state,'version',p.work_request_version,
        'program_ordinal',p.program_ordinal,'executor_actor',p.executor_actor,
        'captured_at',p.captured_at,'claimed_at',p.claimed_at,'closed_at',p.closed_at),
      p.work_request_node_digest
      from package_row p
    union all
    select 'evidence_link:'||h.id,'evidence_link',
      jsonb_build_object('package_key',h.package_key,'evidence_kind',h.evidence_kind,
        'ledger_kind',h.ledger_kind,'work_request_version',h.work_request_version,
        'version_relation',case when h.work_request_version=h.current_work_request_version then 'current' else 'historical' end,
        'manifest_digest',h.manifest_digest,'evidence_digest',h.evidence_digest,
        'current_digest',h.current_digest,'source_observed_at',h.source_observed_at,
        'linked_at',h.linked_at,'note',h.note,'current',h.is_current,
        'health_reasons',to_jsonb(h.health_reasons)),h.evidence_link_node_digest
      from evidence_health h
    union all
    select 'job_receipt:'||j.id,'job_receipt',
      jsonb_build_object('kind',j.kind,'created_at',j.created_at,
        'bound_evidence_kind',j.bound_evidence_kind,
        'status_pass',j.evidence->>'status'='pass',
        'operation_matches',j.evidence->>'operation'=case
          when j.bound_evidence_kind='two_clean_audit_cycles' then 'clean_audit_cycle'
          else j.bound_evidence_kind end)
      ||case
        when j.bound_evidence_kind in ('source','material_fix')
          and coalesce(j.evidence->>'commit_sha','') ~ '^[0-9a-f]{40,64}$'
          then jsonb_build_object('commit_sha',j.evidence->>'commit_sha')
        when j.bound_evidence_kind='tests'
          and coalesce(j.evidence->>'result_digest','') ~ '^sha256:[0-9a-f]{64}$'
          then jsonb_build_object('result_digest',j.evidence->>'result_digest')
        when j.bound_evidence_kind in ('readback','live_readback')
          and coalesce(j.evidence->>'target_ref','') ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
          then jsonb_build_object('target_ref',j.evidence->>'target_ref')
        when j.bound_evidence_kind='rollback'
          and coalesce(j.evidence->>'recovery_ref','') ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'
          then jsonb_build_object('recovery_ref',j.evidence->>'recovery_ref')
        when j.bound_evidence_kind='independent_review'
          and coalesce(j.evidence->>'reviewed_artifact_digest','') ~ '^sha256:[0-9a-f]{64}$'
          then jsonb_build_object('reviewed_artifact_digest',j.evidence->>'reviewed_artifact_digest')
        when j.bound_evidence_kind in ('zero_unresolved_findings','zero_blockers')
          and j.evidence->>'count'='0'
          and coalesce(j.evidence->>'baseline_digest','') ~ '^sha256:[0-9a-f]{64}$'
          then jsonb_build_object('count',0,'baseline_digest',j.evidence->>'baseline_digest')
        when j.bound_evidence_kind='two_clean_audit_cycles'
          and j.evidence->>'cycle' in ('1','2')
          and coalesce(j.evidence->>'baseline_digest','') ~ '^sha256:[0-9a-f]{64}$'
          and coalesce(j.evidence->>'run_id','') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          then jsonb_build_object('cycle',(j.evidence->>'cycle')::integer,
            'run_id',j.evidence->>'run_id','baseline_digest',j.evidence->>'baseline_digest',
            'unresolved_count',case when j.evidence->>'unresolved_count'='0' then 0 end,
            'blocker_count',case when j.evidence->>'blocker_count'='0' then 0 end)
        else '{}'::jsonb end,
      j.job_receipt_node_digest from job_source j
    union all
    select 'job:'||j.job_id,'job',jsonb_build_object('definition_key',j.definition_key,
        'definition_version',j.definition_version,'mode',j.job_mode,'state',j.job_state,
        'attempt',j.job_attempt),j.job_node_digest from job_source j
    union all
    select 'job_attempt:'||j.job_attempt_id,'job_attempt',jsonb_build_object(
        'attempt',j.attempt,'state',j.attempt_state),j.job_attempt_node_digest from job_source j
    union all
    select 'evidence_binding:'||j.job_id,'evidence_binding',jsonb_build_object(
        'package_key',h.package_key,'evidence_kind',h.evidence_kind,
        'work_request_version',h.binding_work_request_version,
        'manifest_digest',h.binding_manifest_digest,'bound_at',j.bound_at),j.binding_node_digest
      from job_source j join evidence_health h on h.id=j.evidence_link_id
    union all
    select 'engineering_envelope:'||j.envelope_id,'engineering_envelope',jsonb_build_object(
        'state_version',j.state_version,'canonical_record_digest',j.canonical_record_digest,
        'envelope_digest',j.envelope_digest,'issued_at',j.issued_at,'expires_at',j.expires_at),
      j.envelope_node_digest
      from job_source j where j.envelope_id is not null
    union all
    select 'engineering_slice_plan:'||j.slice_plan_id,'engineering_slice_plan',jsonb_build_object(
        'work_request_version',j.slice_work_request_version,'plan_digest',j.plan_digest,
        'accepted_plan_hash',j.accepted_plan_hash),j.slice_plan_node_digest
      from job_source j where j.slice_plan_id is not null
    union all
    select 'accepted_plan:'||j.accepted_plan_id,'accepted_plan',jsonb_build_object(
        'plan_ref',j.plan_ref,'plan_hash',j.plan_hash,'plan_version',j.plan_version),
      j.accepted_plan_node_digest
      from job_source j where j.accepted_plan_id is not null
    union all
    select 'engineering_receipt:'||j.engineering_receipt_id,'engineering_receipt',jsonb_build_object(
        'outcome',j.engineering_outcome,'receipt_digest',j.receipt_digest),
      j.engineering_receipt_node_digest
      from job_source j where j.engineering_receipt_id is not null
    union all
    select 'reviewer_fact:'||j.reviewer_fact_id,'reviewer_fact',jsonb_build_object(
        'state',j.reviewer_state,'actor_separated',j.reviewer_actor_id<>j.executor_actor_id,
        'session_independence','deferred_to_siep_03'),j.reviewer_fact_node_digest
      from job_source j where j.reviewer_fact_id is not null
    union all
    select 'decision:'||d.id,'decision',jsonb_build_object(
        'gate',case when d.new_value->>'gate' in ('joe_approval','joe_go_no_go')
          then d.new_value->>'gate' end,
        'decision',case when d.new_value->>'decision' in ('approved','rejected','go','no_go','revoked')
          then d.new_value->>'decision' end,
        'work_request_version',case when coalesce(d.new_value->>'work_request_version','') ~ '^[1-9][0-9]*$'
          then (d.new_value->>'work_request_version')::integer end,
        'manifest_digest',case when coalesce(d.new_value->>'manifest_digest','') ~ '^sha256:[0-9a-f]{64}$'
          then d.new_value->>'manifest_digest' end,
        'occurred_at',d.occurred_at,'authoritative',d.authoritative,
        'decision_ordinal',d.decision_ordinal),d.decision_node_digest
      from decision_source d
    union all
    select distinct 'actor:'||a.id,'actor',jsonb_build_object('slug',a.slug,'active',a.active),
      ops.siep_evidence_node_digest(to_jsonb(a))
      from public.actor a
     where a.id in (
       select linked_actor_id from evidence_health
       union select executor_actor_id from job_source where executor_actor_id is not null
       union select reviewer_actor_id from job_source where reviewer_actor_id is not null
       union select actor_id from decision_source
     )
  ),
  edge as (
    select 'package:'||p.package_key source_key,'authorizes' relation,
           'work_request:'||p.work_request_id target_key,'package_contract:'||p.package_key basis_ref from package_row p
    union all
    select 'package:'||d.package_key,'depends_on','package:'||d.depends_on_package_key,
           'dependency:'||d.package_key||':'||d.depends_on_package_key
      from ops.siep_program_dependency d join graph_package s on s.package_key=d.package_key
    union all
    select 'package:'||h.package_key,'has_evidence','evidence_link:'||h.id,'evidence_link:'||h.id from evidence_health h
    union all
    select 'evidence_link:'||h.id,'attests',
           case h.ledger_kind when 'job_receipt' then 'job_receipt:' else 'decision:' end||h.ledger_id,
           'evidence_link:'||h.id
      from evidence_health h
    union all
    select 'evidence_link:'||h.id,'linked_by','actor:'||h.linked_actor_id,'evidence_link:'||h.id from evidence_health h
    union all
    select 'job_receipt:'||j.id,'receipt_for','job:'||j.job_id,'job_receipt:'||j.id from job_source j
    union all
    select 'job_receipt:'||j.id,'records_attempt','job_attempt:'||j.job_attempt_id,'job_receipt:'||j.id from job_source j
    union all
    select 'job:'||j.job_id,'purpose_bound_by','evidence_binding:'||j.job_id,'evidence_binding:'||j.job_id from job_source j
    union all
    select 'job:'||j.job_id,'authorized_by','engineering_envelope:'||j.envelope_id,'engineering_envelope:'||j.envelope_id
      from job_source j where j.envelope_id is not null
    union all
    select 'engineering_envelope:'||j.envelope_id,'projects','engineering_slice_plan:'||j.slice_plan_id,'engineering_envelope:'||j.envelope_id
      from job_source j where j.envelope_id is not null and j.slice_plan_id is not null
    union all
    select 'engineering_slice_plan:'||j.slice_plan_id,'derives_from','accepted_plan:'||j.accepted_plan_id,'engineering_slice_plan:'||j.slice_plan_id
      from job_source j where j.slice_plan_id is not null and j.accepted_plan_id is not null
    union all
    select 'engineering_receipt:'||j.engineering_receipt_id,'closes','engineering_envelope:'||j.envelope_id,'engineering_receipt:'||j.engineering_receipt_id
      from job_source j where j.engineering_receipt_id is not null
    union all
    select 'engineering_receipt:'||j.engineering_receipt_id,'records_attempt','job_attempt:'||j.job_attempt_id,'engineering_receipt:'||j.engineering_receipt_id
      from job_source j where j.engineering_receipt_id is not null
    union all
    select 'reviewer_fact:'||j.reviewer_fact_id,'reviews','engineering_receipt:'||j.engineering_receipt_id,'reviewer_fact:'||j.reviewer_fact_id
      from job_source j where j.reviewer_fact_id is not null
    union all
    select 'engineering_receipt:'||j.engineering_receipt_id,'executed_by','actor:'||j.executor_actor_id,'engineering_receipt:'||j.engineering_receipt_id
      from job_source j where j.engineering_receipt_id is not null
    union all
    select 'reviewer_fact:'||j.reviewer_fact_id,'reviewed_by','actor:'||j.reviewer_actor_id,'reviewer_fact:'||j.reviewer_fact_id
      from job_source j where j.reviewer_fact_id is not null
    union all
    select 'decision:'||d.id,'decided_by','actor:'||d.actor_id,'decision:'||d.id from decision_source d
    union all
    select 'decision:'||d.id,'decides','package:'||d.projected_package_key,'decision:'||d.id
      from decision_source d
    union all
    select 'decision:'||d.id,'supersedes','decision:'||d.prior_decision_id,'decision:'||d.id
      from decision_source d where d.authoritative and d.prior_decision_id is not null
  ),
  unique_node as (
    select node_key,min(node_type) node_type,min(attributes::text)::jsonb attributes,
           min(node_digest) node_digest
      from node group by node_key
  ),
  unique_edge as (
    select distinct source_key,relation,target_key,basis_ref from edge
  ),
  required_kind as (
    select p.package_key,kind evidence_kind
      from package_row p
      cross join lateral unnest(p.required_evidence_kinds||array['independent_review']) kind
    group by p.package_key,kind
  ),
  coverage as (
    select r.package_key,r.evidence_kind,
      case when r.evidence_kind='two_clean_audit_cycles' then
        (select count(distinct a.audit_cycle) from evidence_health a
          where a.package_key=r.package_key and a.evidence_kind=r.evidence_kind
            and a.audit_cycle in ('1','2') and a.is_current)=2
      else coalesce((select bool_or(a.is_current) from evidence_health a
        where a.package_key=r.package_key and a.evidence_kind=r.evidence_kind
          ),false) end covered
      from required_kind r
  ),
  integrity as (
    select count(*) link_count,
           count(*) filter(where is_current) current_link_count,
           count(*) filter(where not is_current) noncurrent_link_count,
           count(*) filter(where current_digest is null
             or (current_digest is not null and evidence_digest<>current_digest)
             or canonical_observed_at is distinct from source_observed_at
             or canonical_observed_at>now()+interval '1 minute'
             or not coalesce(purpose_current,false)) structural_invalid_link_count,
           count(*) filter(where current_digest is null) missing_source_count,
           count(*) filter(where current_digest is not null and evidence_digest<>current_digest) digest_mismatch_count,
           count(*) filter(where manifest_digest<>ops.siep_manifest_digest()) manifest_mismatch_count,
           count(*) filter(where canonical_observed_at is distinct from source_observed_at) observed_at_mismatch_count,
           count(*) filter(where canonical_observed_at>now()+interval '1 minute') future_source_count,
           count(*) filter(where evidence_kind not in ('joe_approval','joe_go_no_go') and not case
             when work_request_state='released' then
               work_request_version between current_work_request_version-1 and current_work_request_version
             when work_request_state='confirmed_closed' then
               work_request_version between current_work_request_version-2 and current_work_request_version
             else work_request_version=current_work_request_version end) stale_version_count,
           count(*) filter(where not purpose_current) purpose_or_lineage_mismatch_count,
           count(*) filter(where not authority_current) superseded_authority_count
      from evidence_health
  )
  select jsonb_build_object(
    'schema_version','siep-evidence-graph.v1',
    'program_key','carr-system-integrity-elimination-v1',
    'scope',case when k is null then 'program' else 'package:'||k end,
    'manifest_digest',ops.siep_manifest_digest(),
    'nodes',coalesce((select jsonb_agg(jsonb_build_object('key',node_key,'type',node_type,
      'attributes',attributes,'node_digest',node_digest) order by node_key) from unique_node),'[]'::jsonb),
    'edges',coalesce((select jsonb_agg(jsonb_build_object('from',source_key,'relation',relation,
      'to',target_key,'basis_ref',basis_ref,'edge_digest','sha256:'||encode(public.digest(
        ops.guidance_import_canonical_json(jsonb_build_object('from',source_key,'relation',relation,
          'to',target_key,'basis_ref',basis_ref)),'sha256'),'hex'))
      order by source_key,relation,target_key,basis_ref) from unique_edge),'[]'::jsonb),
    'attachments',coalesce((select jsonb_agg(jsonb_build_object(
      'ref','evidence_link:'||id,'package_key',package_key,'evidence_kind',evidence_kind,
      'ledger_ref',case ledger_kind when 'job_receipt' then 'job_receipt:' else 'decision:' end||ledger_id,
      'current',is_current,'status',case when is_current then 'current'
        when current_digest is null then 'missing_target'
        when evidence_digest<>current_digest then 'source_digest_mismatch'
        when manifest_digest<>ops.siep_manifest_digest() then 'stale_manifest'
        when 'stale_work_request_version'=any(health_reasons) then 'stale_work_request_version'
        when not purpose_current then 'incomplete_engineering_chain'
        when not authority_current then 'superseded_or_negative_decision'
        when canonical_observed_at>now()+interval '1 minute' then 'future_source'
        else 'invalid' end,
      'reasons',to_jsonb(health_reasons),
      'baseline_membership',case when evidence_kind in ('zero_unresolved_findings','zero_blockers')
        then 'attested_not_independently_recomputable_until_siep_40' else 'not_applicable' end
      ) order by package_key,evidence_kind,id) from evidence_health),'[]'::jsonb),
    'current_coverage',coalesce((select jsonb_agg(jsonb_build_object('package_key',package_key,
      'evidence_kind',evidence_kind,'covered',covered) order by package_key,evidence_kind)
      from coverage),'[]'::jsonb),
    'integrity',(select jsonb_build_object(
      'valid',structural_invalid_link_count=0 and not exists(select 1 from coverage where not covered),
      'immutable_integrity_valid',structural_invalid_link_count=0,
      'current_coverage_complete',not exists(select 1 from coverage where not covered),
      'link_count',link_count,'current_link_count',current_link_count,
      'noncurrent_link_count',noncurrent_link_count,
      'structural_invalid_link_count',structural_invalid_link_count,
      'missing_current_requirement_count',(select count(*) from coverage where not covered),
      'missing_source_count',missing_source_count,
      'digest_mismatch_count',digest_mismatch_count,'manifest_mismatch_count',manifest_mismatch_count,
      'observed_at_mismatch_count',observed_at_mismatch_count,'future_source_count',future_source_count,
      'stale_work_request_version_count',stale_version_count,
      'purpose_or_lineage_mismatch_count',purpose_or_lineage_mismatch_count,
      'superseded_authority_count',superseded_authority_count,
      'session_independence','deferred_to_siep_03','terminal_authority','siep_06b') from integrity)
  ) into graph_body;

  return graph_body||jsonb_build_object('read_at',now(),
    'graph_digest','sha256:'||encode(public.digest(
      ops.guidance_import_canonical_json(graph_body),'sha256'),'hex'));
end $_$;


--
-- Name: FUNCTION siep_read_evidence_graph(p_component text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.siep_read_evidence_graph(p_component text) IS 'SIEP-06A deterministic redacted projection over canonical ledgers. It stores no graph state, grants no execution authority, and does not certify terminal closure.';


--
-- Name: siep_read_program(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_read_program() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_build_object(
    'program_key','carr-system-integrity-elimination-v1',
    'manifest_digest',ops.siep_manifest_digest(),
    'packages',coalesce(jsonb_agg(jsonb_build_object(
      'package_key',c.package_key,'work_request_ref',w.ref,'title',w.title,'state',w.state,
      'version',w.version,'owner',w.owner_actor,'executor',w.executor_actor,
      'minimum_executor_tier',c.minimum_executor_tier,'approval_gate',c.approval_gate,
      'dependencies',(select coalesce(jsonb_agg(d.depends_on_package_key order by d.depends_on_package_key),'[]'::jsonb)
                        from ops.siep_program_dependency d where d.package_key=c.package_key),
      'evidence',(select coalesce(jsonb_object_agg(e.evidence_kind,e.count),'{}'::jsonb)
                    from (select evidence_kind,count(*) from ops.siep_evidence_link
                           where package_key=c.package_key group by evidence_kind) e),
      'delivery_contract',c.delivery_contract
    ) order by w.program_ordinal),'[]'::jsonb)
  ) from ops.siep_package_contract c join ops.work_request w on w.id=c.work_request_id
$$;


--
-- Name: siep_record_joe_decision(text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_record_joe_decision(p_component text, p_gate text, p_decision text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare k text; c ops.siep_package_contract%rowtype; w ops.work_request%rowtype;
        joe_id uuid; existing public.event%rowtype; eid uuid; payload jsonb;
        decision_at timestamptz;
begin
  if session_user<>'carr_authority_joe' then
    raise exception 'SIEP decisions require the authenticated Joe authority session';
  end if;
  k:=ops.siep_resolve_package(p_component);
  select * into c from ops.siep_package_contract where package_key=k;
  select * into w from ops.work_request where id=c.work_request_id;
  if k is null or p_idempotency_key is null or p_gate<>c.approval_gate
     or p_gate not in ('joe_approval','joe_go_no_go')
     or (p_gate='joe_approval' and p_decision not in ('approved','rejected','revoked'))
     or (p_gate='joe_go_no_go' and p_decision not in ('go','no_go','revoked')) then
    raise exception 'exact SIEP approval gate and typed decision are required';
  end if;
  select id into joe_id from public.actor where slug='joe' and active;
  if joe_id is null then raise exception 'active Joe actor is required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-joe-decision:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-joe-decision-package:'||k,0));
  payload:=jsonb_build_object('program_key','carr-system-integrity-elimination-v1',
    'package_key',k,'work_request_version',w.version,'gate',p_gate,'decision',p_decision,
    'manifest_digest',ops.siep_manifest_digest());
  select * into existing from public.event where actor_id=joe_id and verb='siep-joe-decision'
    and idempotency_key=p_idempotency_key::text order by occurred_at,id limit 1;
  if found then
    if existing.subject_id<>w.id or existing.new_value<>payload then
      raise exception 'idempotency_key_reuse: SIEP Joe decision inputs changed';
    end if;
    return existing.id;
  end if;
  select greatest(clock_timestamp(),coalesce(max(e.occurred_at)+interval '1 microsecond',clock_timestamp()))
    into decision_at from public.event e
   where e.actor_id=joe_id and e.verb='siep-joe-decision'
     and e.new_value->>'package_key'=k and e.new_value->>'gate'=p_gate;
  insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,
                           old_value,new_value,cause,agent_rationale,idempotency_key)
  values(decision_at,joe_id,'siep-joe-decision','work_request',w.id,'decision',null,payload,
         'human_stated','typed SIEP authority decision',p_idempotency_key::text)
  returning id into eid;
  return eid;
end $$;


--
-- Name: siep_release_lane_lock(text, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_release_lane_lock(p_component text, p_session_ref text, p_lease_token uuid, p_idempotency_key uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare k text; n integer; c ops.siep_package_contract%rowtype; w ops.work_request%rowtype;
        prior ops.siep_command_receipt%rowtype; aid uuid; released boolean;
        request_digest text; result jsonb; lane ops.siep_lane_lock%rowtype;
begin
  k:=ops.siep_resolve_package(p_component);
  select * into c from ops.siep_package_contract where package_key=k;
  if k is null or p_lease_token is null or p_idempotency_key is null
     or coalesce(p_session_ref,'') !~ '^session:[a-zA-Z0-9._:-]{1,240}$' then
    raise exception 'known package, bounded session, lease token, and idempotency key are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-package:'||k,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-lane:'||c.lane_key,0));
  request_digest:=ops.siep_request_digest(jsonb_build_object(
    'package_key',k,'session_ref',p_session_ref,'lease_token',p_lease_token));
  if exists(select 1 from ops.siep_evidence_link where idempotency_key=p_idempotency_key) then
    raise exception 'idempotency_key_reuse: SIEP evidence key cannot be reused for a command';
  end if;
  select * into prior from ops.siep_command_receipt where idempotency_key=p_idempotency_key;
  if found then
    if prior.verb<>'release_lane' or prior.package_key<>k or prior.request_digest<>request_digest then
      raise exception 'idempotency_key_reuse: SIEP lane-release inputs changed';
    end if;
    return (prior.result->>'released')::boolean;
  end if;
  select w0.* into w from ops.work_request w0 where w0.id=c.work_request_id for update;
  select * into lane from ops.siep_lane_lock where lane_key=c.lane_key for update;
  delete from ops.siep_lane_lock where lane_key=c.lane_key and package_key=k
    and session_ref=p_session_ref and lease_token=p_lease_token
    and (expires_at<=now() or w.state in ('ready','confirmed_closed','declined','superseded'));
  get diagnostics n=row_count; released:=n=1;
  select id into aid from public.actor where slug='system' and active;
  result:=jsonb_build_object('package_key',k,'session_ref',p_session_ref,
      'lease_digest','sha256:'||encode(public.digest(p_lease_token::text,'sha256'),'hex'),'released',released);
  insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,old_value,new_value,cause,agent_rationale,idempotency_key)
  values(now(),aid,'siep-release-lane-lock','work_request',w.id,'lane_lock',null,
    result,
    'system','typed SIEP lane release',p_idempotency_key::text);
  insert into ops.siep_command_receipt(idempotency_key,verb,package_key,request_digest,result,recorded_actor_id)
  values(p_idempotency_key,'release_lane',k,request_digest,result,aid);
  return released;
end $_$;


--
-- Name: siep_request_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_request_digest(p_request jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
  select 'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(p_request),'sha256'),'hex')
$$;


--
-- Name: siep_resolve_package(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_resolve_package(p_component text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select coalesce(
    (select package_key from ops.siep_package_contract where package_key=p_component),
    (select package_key from ops.siep_component_alias where alias_key=p_component)
  )
$$;


--
-- Name: siep_terminal_status(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_terminal_status() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  with facts as (
    select count(*) filter(where w.state<>'confirmed_closed') as open_packages,
           count(*) as contract_packages,
           (select count(*) from ops.work_request sw where sw.program_key='carr-system-integrity-elimination-v1') as program_rows,
           count(*) filter(where w.state='blocked' or w.blocker_code is not null) as blocked_packages,
           bool_or(c.package_key='06B' and w.state='confirmed_closed') as closure_authority_closed,
           bool_or(c.package_key='44' and w.state='confirmed_closed') as retirement_closed
      from ops.siep_package_contract c join ops.work_request w on w.id=c.work_request_id
  ), audit as (
    select count(distinct (r.evidence->>'cycle')) as clean_cycles,
           count(distinct (r.evidence->>'baseline_digest')) as baseline_count,
           count(distinct (r.evidence->>'run_id')) as audit_run_count,
           min(e.source_observed_at) filter(where r.evidence->>'cycle'='1') as cycle_one_at,
           min(e.source_observed_at) filter(where r.evidence->>'cycle'='2') as cycle_two_at
      from ops.siep_evidence_link e join ops.job_receipt r on r.id=e.ledger_id
     where e.package_key='44' and e.evidence_kind='two_clean_audit_cycles'
       and e.ledger_kind='job_receipt' and r.evidence->>'operation'='clean_audit_cycle'
       and r.evidence->>'cycle' in ('1','2') and r.evidence->>'unresolved_count'='0'
       and r.evidence->>'blocker_count'='0'
       and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)
  ), mutation as (
    select max(source_observed_at) as last_material_fix_at
      from ops.siep_evidence_link e where evidence_kind='material_fix'
       and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)
  ), zeroes as (
    select exists(select 1 from ops.siep_evidence_link e join ops.job_receipt r on r.id=e.ledger_id
      where e.package_key='44' and e.evidence_kind='zero_unresolved_findings'
        and r.evidence->>'operation'='zero_unresolved_findings' and r.evidence->>'count'='0'
        and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)) as zero_findings,
      exists(select 1 from ops.siep_evidence_link e join ops.job_receipt r on r.id=e.ledger_id
      where e.package_key='44' and e.evidence_kind='zero_blockers'
        and r.evidence->>'operation'='zero_blockers' and r.evidence->>'count'='0'
        and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)) as zero_blockers
  ), live as (
    select exists(select 1 from ops.siep_lane_lock where expires_at>now()) as live_lane_lock,
           exists(select 1 from ops.incident i join ops.incident_link l on l.incident_id=i.id
                   where l.kind='work_request' and l.ref like 'WR-SIEP-%'
                     and i.state not in ('resolved','reviewed')) as open_incident,
           exists(select 1 from ops.siep_evidence_link e join ops.job_receipt r on r.id=e.ledger_id
             where e.package_key='44' and e.evidence_kind='live_readback'
               and r.evidence->>'operation'='live_readback' and r.evidence->>'status'='pass'
               and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)) as live_readback
  )
  select jsonb_build_object(
    'complete',open_packages=0 and contract_packages=40 and program_rows=40 and blocked_packages=0
      and closure_authority_closed and retirement_closed and zero_findings and zero_blockers
      and clean_cycles=2 and audit_run_count=2 and baseline_count=1
      and cycle_one_at>coalesce(last_material_fix_at,'-infinity'::timestamptz) and cycle_two_at>cycle_one_at
      and not live_lane_lock and not open_incident and live_readback,
    'open_packages',open_packages,'closure_authority_closed',closure_authority_closed,
    'retirement_closed',retirement_closed,'blocked_packages',blocked_packages,
    'clean_audit_cycles',clean_cycles,'audit_run_count',audit_run_count,'audit_baseline_count',baseline_count,
    'exact_program_rowset',contract_packages=40 and program_rows=40,
    'last_material_fix_at',last_material_fix_at,'live_lane_lock',live_lane_lock,
    'open_incident',open_incident,'live_readback',live_readback,
    'required_terminal_evidence',jsonb_build_array('zero_unresolved_findings','zero_blockers','two_clean_audit_cycles','live_readback')
  ) from facts cross join audit cross join mutation cross join zeroes cross join live
$$;


--
-- Name: siep_transition_package(text, integer, text, text, uuid, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.siep_transition_package(p_component text, p_base_version integer, p_target_state text, p_session_ref text, p_lease_token uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare k text; w ops.work_request%rowtype; c ops.siep_package_contract%rowtype;
        actor_id uuid; prior ops.siep_command_receipt%rowtype; review_id uuid; missing text[];
        lane ops.siep_lane_lock%rowtype; result jsonb; clean_cycles integer; baselines integer; audit_runs integer;
        last_fix timestamptz; cycle_one timestamptz; cycle_two timestamptz; attestor text; request_digest text;
begin
  k:=ops.siep_resolve_package(p_component);
  if k is null or p_idempotency_key is null or p_lease_token is null or p_base_version<1
     or coalesce(p_session_ref,'') !~ '^session:[a-zA-Z0-9._:-]{1,240}$' then
    raise exception 'known package, positive base version, bounded session, lease token, and UUID idempotency key are required';
  end if;
  select * into c from ops.siep_package_contract where package_key=k;
  perform pg_advisory_xact_lock(hashtextextended('siep-idempotency:'||p_idempotency_key,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-package:'||k,0));
  perform pg_advisory_xact_lock(hashtextextended('siep-lane:'||c.lane_key,0));
  request_digest:=ops.siep_request_digest(jsonb_build_object(
    'package_key',k,'base_version',p_base_version,'target_state',p_target_state,
    'session_ref',p_session_ref,'lease_token',p_lease_token));
  if exists(select 1 from ops.siep_evidence_link where idempotency_key=p_idempotency_key) then
    raise exception 'idempotency_key_reuse: SIEP evidence key cannot be reused for a command';
  end if;
  select * into prior from ops.siep_command_receipt where idempotency_key=p_idempotency_key;
  if found then
    if prior.verb<>'transition' or prior.package_key<>k or prior.request_digest<>request_digest then
      raise exception 'idempotency_key_reuse: SIEP transition inputs changed';
    end if;
    return prior.result||jsonb_build_object('replayed',true);
  end if;
  select w0.* into w from ops.work_request w0
    join ops.siep_package_contract c0 on c0.work_request_id=w0.id
   where c0.package_key=k for update of w0;
  if w.version<>p_base_version then raise exception 'version_conflict: expected %, current %',p_base_version,w.version; end if;
  select * into lane from ops.siep_lane_lock where lane_key=c.lane_key for update;
  if not found or lane.package_key<>k or lane.work_request_version<>p_base_version
     or lane.session_ref<>p_session_ref or lane.lease_token<>p_lease_token or lane.expires_at<=now() then
    raise exception 'SIEP transition requires the exact live holder-bound package lane lock';
  end if;
  if (w.state,p_target_state) not in (('claimed','in_progress'),('in_progress','verification'),('verification','awaiting_release'),('awaiting_release','released'),('released','confirmed_closed')) then
    raise exception 'invalid SIEP transition % -> %',w.state,p_target_state;
  end if;
  if p_target_state in ('released','confirmed_closed') then
    select array_agg(req) into missing from unnest(c.required_evidence_kinds) req
     where not exists(select 1 from ops.siep_evidence_link e where e.package_key=k and e.evidence_kind=req
       and e.manifest_digest=ops.siep_manifest_digest()
       and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)
       and (req in ('joe_approval','joe_go_no_go')
            or e.work_request_version>=w.version-case when p_target_state='confirmed_closed' then 1 else 0 end));
    if missing is not null then raise exception 'SIEP package % missing evidence: %',k,missing; end if;
    if not exists(select 1 from ops.siep_evidence_link e
                   where e.package_key=k and e.evidence_kind='independent_review'
                     and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id)) then
      raise exception 'SIEP package % requires independent evidence',k;
    end if;
  end if;
  if p_target_state='confirmed_closed' then
    if exists(select 1 from ops.siep_program_dependency d join ops.siep_package_contract dc on dc.package_key=d.depends_on_package_key
              join ops.work_request dw on dw.id=dc.work_request_id where d.package_key=k and dw.state<>'confirmed_closed') then
      raise exception 'SIEP package % cannot close before its dependencies',k;
    end if;
    if k='44' and exists(select 1 from ops.siep_package_contract pc join ops.work_request pw on pw.id=pc.work_request_id
                          where pc.package_key<>'44' and pw.state<>'confirmed_closed') then
      raise exception 'SIEP terminal authority refuses completion: packages remain open';
    end if;
    if k='44' and ((select count(*) from ops.work_request where program_key='carr-system-integrity-elimination-v1')<>40
                   or (select count(*) from ops.siep_package_contract)<>40) then
      raise exception 'SIEP terminal authority refuses completion: program rowset is not exact';
    end if;
    if k='44' then
      select count(distinct r.evidence->>'cycle'),count(distinct r.evidence->>'baseline_digest'),
             count(distinct r.evidence->>'run_id'),
             min(e.source_observed_at) filter(where r.evidence->>'cycle'='1'),
             min(e.source_observed_at) filter(where r.evidence->>'cycle'='2')
        into clean_cycles,baselines,audit_runs,cycle_one,cycle_two
        from ops.siep_evidence_link e join ops.job_receipt r on r.id=e.ledger_id
       where e.package_key='44' and e.evidence_kind='two_clean_audit_cycles' and e.ledger_kind='job_receipt'
         and r.evidence->>'operation'='clean_audit_cycle' and r.evidence->>'cycle' in ('1','2')
         and r.evidence->>'unresolved_count'='0' and r.evidence->>'blocker_count'='0'
         and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id);
      select max(source_observed_at) into last_fix from ops.siep_evidence_link e where evidence_kind='material_fix'
       and e.evidence_digest=ops.siep_current_evidence_digest(e.ledger_kind,e.ledger_id);
      if clean_cycles<>2 or audit_runs<>2 or baselines<>1
         or cycle_one<=coalesce(last_fix,'-infinity'::timestamptz) or cycle_two<=cycle_one
         or exists(select 1 from ops.siep_lane_lock where expires_at>now() and package_key<>'44')
         or exists(select 1 from ops.incident i join ops.incident_link l on l.incident_id=i.id
                   where l.kind='work_request' and l.ref like 'WR-SIEP-%' and i.state not in ('resolved','reviewed'))
         or exists(select 1 from ops.siep_package_contract pc join ops.work_request pw on pw.id=pc.work_request_id
                   where pw.state='blocked' or pw.blocker_code is not null) then
        raise exception 'SIEP terminal authority refuses completion: final clean-cycle, blocker, incident, or lane predicate failed';
      end if;
    end if;
    select e.id,a.slug into review_id,attestor from ops.siep_evidence_link e
      join public.actor a on a.id=e.linked_actor_id
     where e.package_key=k and e.evidence_kind='independent_review' order by e.linked_at desc limit 1;
  end if;
  select id into actor_id from public.actor where slug=coalesce(w.executor_actor,'system') and active;
  if actor_id is null then raise exception 'SIEP transition requires an active claimed executor'; end if;
  result:=jsonb_build_object('package_key',k,'base_version',p_base_version,'state',p_target_state,
    'version',w.version+1,'session_ref',p_session_ref,
    'lease_digest','sha256:'||encode(public.digest(p_lease_token::text,'sha256'),'hex'));
  insert into public.event(occurred_at,actor_id,verb,subject_type,subject_id,field,old_value,new_value,cause,agent_rationale,idempotency_key)
  values(now(),actor_id,'siep-transition-package','work_request',w.id,'state',to_jsonb(w.state),result,
         'system','typed SIEP transition',p_idempotency_key::text);
  update ops.work_request set state=p_target_state,version=version+1,updated_at=now(),
    started_at=case when p_target_state='in_progress' then coalesce(started_at,now()) else started_at end,
    closed_at=case when p_target_state='confirmed_closed' then now() else closed_at end,
    completion_kind=case when p_target_state='confirmed_closed' then 'extended' else completion_kind end,
    completion_evidence=case when p_target_state='confirmed_closed' then jsonb_build_object(
      'acceptance_predicates',to_jsonb(c.required_evidence_kinds),
      'change_ref',ops.siep_manifest_digest(),'user_facing',false,'attested_by',attestor,
      'siep_package',k,'evidence_links',(select jsonb_agg(id order by linked_at) from ops.siep_evidence_link where package_key=k)) else completion_evidence end,
    verification_accepted_at=case when p_target_state='confirmed_closed' then now() else verification_accepted_at end,
    verification_evidence_ref=case when p_target_state='confirmed_closed' then review_id::text else verification_evidence_ref end
   where id=w.id;
  if p_target_state='confirmed_closed' then
    delete from ops.siep_lane_lock where lane_key=c.lane_key and package_key=k
      and session_ref=p_session_ref and lease_token=p_lease_token;
  else
    update ops.siep_lane_lock set work_request_version=w.version+1
     where lane_key=c.lane_key and package_key=k
       and session_ref=p_session_ref and lease_token=p_lease_token;
  end if;
  insert into ops.siep_command_receipt(idempotency_key,verb,package_key,request_digest,result,recorded_actor_id)
  values(p_idempotency_key,'transition',k,request_digest,result,actor_id);
  return result||jsonb_build_object('replayed',false);
end $_$;


--
-- Name: skip_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.skip_job(p_job_id uuid, p_lease_token uuid, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype;
begin
  select * into j from ops.job where id=p_job_id for update;
  if not found or j.state <> 'running' or j.lease_token <> p_lease_token
     or j.leased_until < now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  -- NOT A FAILURE. This is terminal on the attempt that just ran, always --
  -- never the fail_job/timeout_job branch that checks attempt < max_attempts
  -- and routes back through retry_wait. A missing credential does not
  -- self-heal on a timer, so spending retry budget on it only delays the
  -- honest dead_lettered outcome a real failure deserves, and this job never
  -- reaches dead_lettered for this reason at all.
  --
  -- last_failure_class/last_failure_detail are deliberately left untouched:
  -- those columns are read as failure evidence elsewhere (0308's health
  -- view), and a not-configured run is not that. The message lives only in
  -- the immutable 'skipped' receipt below, where a reader has to ask for it
  -- by name instead of tripping over it in a failure surface.
  update ops.job_attempt set state='skipped',ended_at=now(),detail=p_detail
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  update ops.job set state='skipped',ended_at=now(),
         lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
   where id=j.id;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,'skipped',concat('skipped:',j.id,':',j.attempt),
           jsonb_build_object('detail',p_detail));
  return 'skipped';
end $$;


--
-- Name: source_merge_authority_projection(uuid, text, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.source_merge_authority_projection(p_decision_id uuid, p_work_request text, p_head_sha text, p_pr_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_stale boolean;
begin
  perform 1 from ops.work_request w where w.ref=p_work_request for share;
  select ops.engineering_contract_stale(p.plan_ref,p.plan_hash,null) into v_stale
    from ops.work_request w
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.result_version=w.version
    join ops.sourced_work_request_plan p on p.id=ar.plan_id
   where w.ref=p_work_request;
  if coalesce(v_stale,false) then
    return jsonb_build_object('ok',false,'error','source_merge_accepted_plan_retired',
      'execution_authorized',false);
  end if;
  return ops.source_merge_authority_projection_v1(
    p_decision_id,p_work_request,p_head_sha,p_pr_number);
end $$;


--
-- Name: source_merge_authority_projection_v1(uuid, text, text, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.source_merge_authority_projection_v1(p_decision_id uuid, p_work_request text, p_head_sha text, p_pr_number integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
declare tenant constant text:='carr-internal';
        work_ref text:=nullif(btrim(p_work_request),'');
        candidate_count integer;
        w ops.work_request%rowtype;
        p ops.sourced_work_request_plan%rowtype;
        ar ops.sourced_work_request_plan_acceptance_receipt%rowtype;
        scope ops.source_merge_plan_scope%rowtype;
        sp ops.engineering_slice_plan%rowtype;
        decision record;
        acceptor record;
        facts jsonb;
        assurance_bindings jsonb;
        lease_path_claims jsonb;
        evaluated_at timestamptz:=statement_timestamp();
begin
  if p_decision_id is null
     or (work_ref is not null and work_ref !~ '^WR-[0-9]{1,12}$')
     or coalesce(p_head_sha,'') !~ '^[0-9a-f]{40}$'
     or p_pr_number is null or p_pr_number<1 then
    return jsonb_build_object('ok',false,'error','source_merge_locator_invalid');
  end if;

  if work_ref is null then
    select min(candidate.ref),count(distinct candidate.id)
      into work_ref,candidate_count
      from ops.work_request candidate
      join ops.source_merge_plan_scope candidate_scope
        on candidate_scope.work_request_id=candidate.id
       and candidate_scope.organization_tenant_id=tenant
      join ops.engineering_slice_receipt candidate_receipt
        on candidate_receipt.work_request_id=candidate.id
       and candidate_receipt.outcome='claimed_complete'
       and candidate_receipt.receipt#>>'{source_evidence,source_sha}'=p_head_sha
      join ops.engineering_execution_envelope candidate_envelope
        on candidate_envelope.id=candidate_receipt.envelope_id
      left join ops.engineering_execution_envelope candidate_successor
        on candidate_successor.supersedes_envelope_id=candidate_envelope.id
     where candidate.organization_tenant_id=tenant
       and candidate.state='ready' and candidate.blocker_code is null
       and candidate_successor.id is null;
    if candidate_count is distinct from 1 then
      return jsonb_build_object('ok',false,'error','source_merge_candidate_not_unique');
    end if;
  end if;

  select e.id::text event_id,e.subject_id::text decision_id,e.new_value->>'title' title,
         e.sponsoring_human_slug
    into decision
    from public.event e
   where e.subject_type='decision' and e.verb='log-decision'
     and e.subject_id=p_decision_id
     and e.authorization_class='human' and e.new_value->'quote_absent'='false'::jsonb
     and e.human_quote='I approve Gate A2 for '||work_ref||' PR #'||p_pr_number::text||' at '||p_head_sha||' for 120 minutes'
     and e.occurred_at<=statement_timestamp() and e.occurred_at+interval '120 minutes'>statement_timestamp()
   order by e.recorded_at desc,e.id desc limit 1;
  if decision.event_id is null
     or decision.title is distinct from 'Gate A2 source-merge authority: '||work_ref
     or decision.sponsoring_human_slug is distinct from 'joe' then
    return jsonb_build_object('ok',false,'error','source_merge_decision_not_current');
  end if;

  select x.* into w from ops.work_request x
   where x.ref=work_ref and x.organization_tenant_id=tenant;
  if not found or w.state is distinct from 'ready' or w.blocker_code is not null then
    return jsonb_build_object('ok',false,'error','source_merge_work_not_current');
  end if;
  select x.* into ar from ops.sourced_work_request_plan_acceptance_receipt x
   where x.work_request_id=w.id and x.result_version=w.version;
  select x.* into p from ops.sourced_work_request_plan x where x.id=ar.plan_id;
  select x.* into scope from ops.source_merge_plan_scope x
   where x.work_request_id=w.id and x.accepted_plan_id=p.id
     and x.acceptance_receipt_id=ar.id and x.organization_tenant_id=tenant;
  select a.id,a.slug into acceptor from public.actor a
   where a.id=ar.accepted_by_actor_id and a.slug='joe' and a.kind='human' and a.active;
  if ar.id is null or p.id is null or scope.id is null or acceptor.id is null
     or ar.result_version is distinct from w.version
     or ar.plan_hash is distinct from p.plan_hash
     or scope.accepted_by_actor_id is distinct from ar.accepted_by_actor_id
     or not coalesce(ops.source_merge_scope_valid(jsonb_build_object(
          'schema_version','source-merge-scope.v1','repository',scope.repository,
          'base_branch',scope.base_branch,'authorized_paths',scope.authorized_paths)),false) then
    return jsonb_build_object('ok',false,'error','source_merge_plan_scope_not_authorized');
  end if;

  select x.* into sp from ops.engineering_slice_plan x
   where x.accepted_plan_id=p.id and x.work_request_id=w.id
     and x.accepted_plan_hash=p.plan_hash and x.work_request_version=w.version;
  if not found or sp.plan#>>'{work_request,state_version}' is distinct from w.version::text
     or sp.plan#>>'{accepted_plan_revision,digest}' is distinct from p.plan_hash
     or jsonb_typeof(sp.plan->'slices') is distinct from 'array'
     or jsonb_array_length(sp.plan->'slices')=0
     or exists(select 1 from jsonb_array_elements(sp.plan->'slices') slice
                where slice->'manual_qa_required' is distinct from 'false'::jsonb) then
    return jsonb_build_object('ok',false,'error','source_merge_slice_plan_not_current_or_requires_manual_qa');
  end if;

  facts:=ops.engineering_passport_facts(work_ref);
  if facts is null or jsonb_typeof(facts->'source') is distinct from 'object' then
    return jsonb_build_object('ok',false,'error','source_merge_passport_unavailable');
  end if;

  -- These raw assurance and ownership relations deliberately grant no runtime
  -- SELECT. This SECURITY DEFINER projection exposes only exact, current
  -- closure bindings; it never returns evidence bodies, lease tokens, or a
  -- path outside the accepted plan-hash scope.
  select coalesce(jsonb_agg(jsonb_build_object(
      'slice_ref',receipt.slice_ref,
      'attempt_id',receipt.attempt_id,
      'evidence_manifest_ref','assurance-manifest:'||evidence_manifest.id::text,
      'review_manifest_ref','assurance-manifest:'||review_manifest.id::text,
      'evidence_ref','assurance-evidence:'||evidence.id::text,
      'reviewer_fact_ref','engineering-review:'||reviewer.id::text,
      'review_extension_ref','assurance-review:'||review.id::text,
      'reviewer_state',reviewer.state,
      'evidence_digest',evidence.evidence_digest,
      'review_digest',review.review_digest,
      'repository_commit_sha',evidence_manifest.repository_commit_sha,
      'repository_tree_sha',evidence_manifest.repository_tree_sha,
      'snapshot_valid_until',least(evidence_manifest.snapshot_valid_until,review_manifest.snapshot_valid_until)
    ) order by receipt.slice_ref collate "C",receipt.attempt_id collate "C"),'[]'::jsonb)
    into assurance_bindings
    from ops.assurance_evidence_extension evidence
    join ops.assurance_execution_manifest evidence_manifest on evidence_manifest.id=evidence.manifest_id
    join ops.assurance_review_extension review on review.evidence_id=evidence.id
    join ops.assurance_execution_manifest review_manifest on review_manifest.id=review.review_manifest_id
    join ops.engineering_slice_receipt receipt on receipt.id=evidence.receipt_id
    join ops.engineering_execution_envelope envelope on envelope.id=receipt.envelope_id
    join ops.engineering_reviewer_fact reviewer on reviewer.id=review.reviewer_fact_id
    join ops.canonical_ownership_lease lease on lease.id=evidence_manifest.lease_id
   where evidence_manifest.organization_tenant_id=tenant
     and evidence_manifest.work_request_id=w.id
     and evidence_manifest.accepted_plan_id=p.id
     and evidence_manifest.slice_plan_id=sp.id
     and evidence_manifest.repository_stage='post_commit'
     and review_manifest.organization_tenant_id=tenant
     and review_manifest.work_request_id=w.id
     and review_manifest.accepted_plan_id=p.id
     and review_manifest.slice_plan_id=sp.id
     and review_manifest.repository_stage='review'
     and review_manifest.repository_commit_sha=evidence_manifest.repository_commit_sha
     and review_manifest.repository_tree_sha=evidence_manifest.repository_tree_sha
     and evidence_manifest.repository_commit_sha=p_head_sha
     and envelope.slice_plan_id=sp.id and envelope.work_request_id=w.id
     and reviewer.receipt_id=receipt.id and reviewer.state='passed'
     and receipt.work_request_id=w.id and receipt.outcome='claimed_complete'
     and receipt.receipt#>>'{source_evidence,source_sha}'=p_head_sha
     and evidence_manifest.snapshot_valid_until>evaluated_at
     and review_manifest.snapshot_valid_until>evaluated_at
     and lease.organization_tenant_id=tenant
     and lease.work_request_id=w.id and lease.accepted_plan_id=p.id and lease.slice_plan_id=sp.id
     and lease.state in ('active','released')
     and lease.id=review_manifest.lease_id
     and lease.fencing_generation=evidence_manifest.fencing_generation
     and lease.fencing_generation=review_manifest.fencing_generation
     and coalesce((select owner.decision from ops.assurance_owner_acceptance_fact owner
                    where owner.organization_tenant_id=tenant and owner.evidence_id=evidence.id
                    order by owner.created_at desc,owner.id desc limit 1),'accept')
         not in ('hold','reject');

  select coalesce(jsonb_agg(jsonb_build_object(
      'lease_ref','canonical-ownership-lease:'||covered.lease_id::text,
      'path',accepted.path,
      'mode','file',
      'operation','write',
      'claim_path',covered.claim_value,
      'claim_mode',covered.claim_mode,
      'claim_operation',covered.operation
    ) order by lower(accepted.path) collate "C",accepted.path collate "C"),'[]'::jsonb)
    into lease_path_claims
    from jsonb_array_elements_text(scope.authorized_paths) accepted(path)
    cross join lateral (
      select lease.id lease_id,claim.claim_value,claim.claim_mode,claim.operation
        from ops.canonical_ownership_lease lease
        join ops.canonical_ownership_claim claim on claim.lease_id=lease.id
       where lease.organization_tenant_id=tenant and lease.work_request_id=w.id
         and lease.accepted_plan_id=p.id and lease.slice_plan_id=sp.id
         and lease.state='active' and lease.expires_at>evaluated_at
         and claim.organization_tenant_id=tenant and claim.claim_kind='path'
         and claim.operation='write' and claim.claim_mode in ('file','tree')
         and (claim.claim_mode='file' and claim.claim_value=accepted.path
           or claim.claim_mode='tree' and
              (accepted.path=claim.claim_value or accepted.path like claim.claim_value||'/%'))
         and exists (select 1 from ops.canonical_ownership_runtime_session merge_session
                      join ops.canonical_ownership_merge_binding merge_binding
                        on merge_binding.runtime_binding_id=merge_session.id
                     where merge_session.ownership_session_ref=lease.holder_session_ref
                       and merge_session.phase='merge'
                       and merge_binding.decision_id=p_decision_id
                       and merge_binding.head_sha=p_head_sha and merge_binding.pr_number=p_pr_number
                       and ops.canonical_ownership_merge_binding_valid(merge_session.id))
       order by (claim.claim_mode='file') desc,length(claim.claim_value) desc,
                lease.fencing_generation desc,lease.id,claim.claim_value collate "C"
       limit 1
    ) covered;

  if jsonb_array_length(assurance_bindings)=0
     or jsonb_array_length(lease_path_claims)<>jsonb_array_length(scope.authorized_paths) then
    return jsonb_build_object('ok',false,'error','source_merge_assurance_or_ownership_incomplete');
  end if;

  return jsonb_build_object(
    'ok',true,
    'passport_facts',facts,
    'authority',jsonb_build_object(
      'schema_version','source-merge-authority.v1',
      'derived_by','source-merge-authority-projection',
      'decision',jsonb_build_object(
        'decision_ref','decision:'||decision.decision_id,
        'event_ref','event:'||decision.event_id,
        'sponsoring_human_slug',decision.sponsoring_human_slug,
        'title',decision.title),
      'exact_head_sha',p_head_sha,
      'pr_number',p_pr_number,
      'source_merge_only',true,
      'allowed_actions',jsonb_build_array('repository:merge-pr'),
      'scope_ref','source-merge-scope:'||scope.id::text,
      'scope_digest',scope.scope_digest,
      'authorized_path_claims',lease_path_claims,
      'assurance_bindings',assurance_bindings,
      'currentness_evaluated_at',evaluated_at));
exception when others then
  return jsonb_build_object('ok',false,'error','source_merge_projection_refused','sqlstate',sqlstate);
end $_$;


--
-- Name: source_merge_rows_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.source_merge_rows_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin raise exception 'source merge plan scope is append-only'; end $$;


--
-- Name: source_merge_scope_valid(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.source_merge_scope_valid(p_scope jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $_$
begin
  if jsonb_typeof(p_scope) is distinct from 'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_scope) k)
        is distinct from array['authorized_paths','base_branch','repository','schema_version']::text[]
     or p_scope->>'schema_version' is distinct from 'source-merge-scope.v1'
     or p_scope->>'repository' is distinct from 'jbookout/carr-system'
     or p_scope->>'base_branch' is distinct from 'main'
     or jsonb_typeof(p_scope->'authorized_paths') is distinct from 'array'
     or jsonb_array_length(p_scope->'authorized_paths') not between 1 and 100 then
    return false;
  end if;
  if exists (
       select 1 from jsonb_array_elements(p_scope->'authorized_paths') item
        where jsonb_typeof(item) is distinct from 'string'
     ) then
    return false;
  end if;
  if exists (
       select 1 from jsonb_array_elements_text(p_scope->'authorized_paths') path
        where char_length(path) not between 1 and 500
           or path !~ '^[!-~]+$'
           or position(chr(92) in path)>0
           or path ~ '(^/|/$|//|[?*\[\]{}!]|(^|/)\.\.?(/|$))'
     ) or exists (
       select 1 from jsonb_array_elements_text(p_scope->'authorized_paths') path
        group by lower(path) having count(*)>1
     ) or (select jsonb_agg(to_jsonb(path) order by lower(path) collate "C",path collate "C")
             from jsonb_array_elements_text(p_scope->'authorized_paths') path)
          is distinct from p_scope->'authorized_paths' then
    return false;
  end if;
  return true;
end
$_$;


--
-- Name: sourced_heavy_build_review_target(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_heavy_build_review_target(p_work_request text, p_plan_hash text, p_admission_hash text) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, admission_id uuid, admission_ref text, builder_session_ref text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select w.id,w.ref,p.id,a.id,a.admission_ref,a.builder_session_ref
    from ops.work_request w
    join ops.sourced_work_request_plan p on p.work_request_id=w.id
    join ops.heavy_build_admission_revision a on a.plan_id=p.id
   where w.ref=p_work_request and p.plan_hash=p_plan_hash
     and a.admission_hash=p_admission_hash
     and a.version=(select max(latest.version) from ops.heavy_build_admission_revision latest
                     where latest.plan_id=p.id)
     and w.organization_tenant_id='carr-internal'
     and (w.state='triaged' or (w.state='ready' and exists(
       select 1 from ops.ready_plan_amendment amendment
        where amendment.plan_id=p.id and amendment.work_request_id=w.id
          and amendment.base_version=w.version)));
$$;


--
-- Name: sourced_heavy_build_review_target_v1(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_heavy_build_review_target_v1(p_work_request text, p_plan_hash text, p_admission_hash text) RETURNS TABLE(work_request_id uuid, ref text, plan_id uuid, admission_id uuid, admission_ref text, builder_session_ref text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select w.id,w.ref,p.id,a.id,a.admission_ref,a.builder_session_ref
    from ops.work_request w
    join ops.sourced_work_request_plan p on p.work_request_id=w.id
    join ops.heavy_build_admission_revision a on a.plan_id=p.id
   where w.ref=p_work_request and w.state='triaged' and p.plan_hash=p_plan_hash and a.admission_hash=p_admission_hash
     and a.version=(select max(latest.version) from ops.heavy_build_admission_revision latest where latest.plan_id=p.id)
     and w.organization_tenant_id='carr-internal';
$$;


