--
-- Name: sourced_work_request_is_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_is_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  -- INSERT WAS NEVER COVERED. This trigger was BEFORE UPDATE only, so a sourced
  -- row could be INSERTed already terminal: no receipt, no version history, no
  -- pointer check, nothing. Every other INSERT trigger on this table returns
  -- early for these states, so the constraint alone stood between a fabricated
  -- withdrawal and the table. A sourced request is born captured or not at all.
  if tg_op = 'INSERT' then
    if new.capture_idempotency_key is not null and new.state <> 'captured' then
      raise exception 'a sourced Work Request must be INSERTed in state captured, not %', new.state;
    end if;
    return new;
  end if;

  if old.capture_idempotency_key is null then
    return new;
  end if;

  if old.state = 'captured'
     and new.state = 'triaged'
     and new.version = old.version + 1
     and (to_jsonb(new) - array['state','triage_classification','triaged_by_actor_id','triaged_at','version','updated_at'])
           is not distinct from
         (to_jsonb(old) - array['state','triage_classification','triaged_by_actor_id','triaged_at','version','updated_at'])
     and exists (
       select 1 from ops.work_request_triage_receipt r
        where r.work_request_id = old.id and r.base_version = old.version
          and r.result_version = new.version and r.classification = new.triage_classification
          and r.triaged_by_actor_id = new.triaged_by_actor_id and r.triaged_at = new.triaged_at
     ) then
    return new;
  end if;

  if old.state = 'triaged'
     and new.state = 'triaged'
     and new.version = old.version + 1
     and (to_jsonb(new) - array['shape_disposition','shape_fixed_surface_ref','shape_rationale','shape_decided_by_actor_id','shape_decided_at','version','updated_at'])
           is not distinct from
         (to_jsonb(old) - array['shape_disposition','shape_fixed_surface_ref','shape_rationale','shape_decided_by_actor_id','shape_decided_at','version','updated_at'])
     and exists (
       select 1 from ops.effective_sourced_work_request_shape_disposition(new) e
        where e.base_version = old.version and e.result_version = new.version
     ) then
    return new;
  end if;

  if old.state = 'triaged'
     and new.state = 'ready'
     and new.version = old.version + 1
     and (to_jsonb(new) - array['state','version','updated_at','shape_disposition','shape_fixed_surface_ref','shape_rationale','shape_decided_by_actor_id','shape_decided_at'])
           is not distinct from
         (to_jsonb(old) - array['state','version','updated_at','shape_disposition','shape_fixed_surface_ref','shape_rationale','shape_decided_by_actor_id','shape_decided_at'])
     and exists (
       select 1
         from ops.sourced_work_request_plan_acceptance_receipt ar
         join ops.sourced_work_request_plan p on p.id = ar.plan_id
         left join ops.sourced_work_request_plan_shape_binding_receipt b
           on b.plan_acceptance_receipt_id = ar.id
        where ar.work_request_id = old.id and ar.base_version = old.version
          and ar.result_version = new.version and ar.plan_hash = p.plan_hash
          and (
            (b.id is null
             and new.shape_disposition = 'not_required'
             and new.shape_fixed_surface_ref = ar.shape_fixed_surface_ref
             and new.shape_fixed_surface_ref = ('sourced-plan:' || p.plan_ref || '#' || p.plan_hash)
             and new.shape_rationale = ar.shape_rationale
             and new.shape_rationale = ('Accepted immutable plan ' || p.plan_ref || ' for ' || p.runbook_ref || ' at sha256:' || p.runbook_content_hash)
             and new.shape_decided_by_actor_id = ar.accepted_by_actor_id
             and new.shape_decided_at = ar.accepted_at)
            or
            (b.id is not null
             and b.work_request_id = old.id
             and (new.shape_disposition,new.shape_fixed_surface_ref,new.shape_rationale,new.shape_decided_by_actor_id,new.shape_decided_at)
                 is not distinct from
                 (b.disposition,b.fixed_surface_ref,b.rationale,b.decided_by_actor_id,b.decided_at))
          )
     ) then
    return new;
  end if;


  -- A ready plan may move only to an independently accepted successor on the
  -- same Work Request.  No business field changes; the version bump makes all
  -- predecessor envelopes, slice plans, leases, and feedback bindings stale.
  if old.state = 'ready'
     and new.state = 'ready'
     and new.version = old.version + 1
     and (to_jsonb(new) - array['version','updated_at']) is not distinct from
         (to_jsonb(old) - array['version','updated_at'])
     and exists (
       select 1 from ops.ready_plan_amendment_acceptance_receipt a
       join ops.sourced_work_request_plan_acceptance_receipt ar
         on ar.id = a.plan_acceptance_receipt_id
        where a.work_request_id = old.id and a.base_version = old.version
          and a.result_version = new.version and ar.plan_id = a.successor_plan_id
          and ar.base_version = old.version and ar.result_version = new.version
     ) then
    return new;
  end if;

  -- CAPTURED -> DECLINED or SUPERSEDED, receipt-backed like every other arm.
  -- Only from captured: a triaged row carries a triage receipt and may carry a
  -- shape disposition, and withdrawing it would strand both.
  if old.state = 'captured'
     and new.state in ('declined','superseded')
     and new.version = old.version + 1
     and (to_jsonb(new) - array['state','exit_reason','closed_at','superseded_by','version','updated_at'])
           is not distinct from
         (to_jsonb(old) - array['state','exit_reason','closed_at','superseded_by','version','updated_at'])
     and exists (
       select 1 from ops.work_request_withdrawal_receipt r
        where r.work_request_id = old.id and r.base_version = old.version
          and r.result_version = new.version and r.final_state = new.state
          and r.exit_reason = new.exit_reason
          and r.superseded_by is not distinct from new.superseded_by
     ) then
    return new;
  end if;

  raise exception 'sourced Program 6 Work Requests permit only receipt-backed captured-to-triaged, triaged shape-disposition, triaged-to-ready, or captured-to-withdrawn transitions';
end;
$$;


--
-- Name: sourced_work_request_outcome_feedback_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_outcome_feedback_digest(p_preimage jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select 'sha256:' || encode(public.digest(p_preimage::text, 'sha256'), 'hex');
$$;


--
-- Name: sourced_work_request_outcome_feedback_preimage(uuid, uuid, uuid, jsonb, jsonb, text, text, text, integer, text, boolean, integer); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_outcome_feedback_preimage(p_work_request_id uuid, p_plan_id uuid, p_plan_acceptance_receipt_id uuid, p_criterion_results jsonb, p_evidence_refs jsonb, p_outcome text, p_blocker_code text, p_result_summary text, p_observed_minutes integer, p_interaction_surface text, p_heavy_session_used boolean, p_manual_context_transfers integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select jsonb_build_object(
    'contract', 'carr-sourced-outcome-feedback/v2',
    'work_request', jsonb_build_object(
      'id', w.id, 'ref', w.ref, 'state', w.state, 'version', w.version,
      'title', w.title, 'desired_outcome', w.desired_outcome,
      'acceptance_criteria', w.acceptance_criteria, 'origin_ref', w.origin_ref,
      'doctrine_section_id', w.doctrine_section_id,
      'doctrine_revision_id', w.doctrine_revision_id,
      'triage_classification', w.triage_classification,
      'triaged_by_actor_id', w.triaged_by_actor_id, 'triaged_at', w.triaged_at,
      'shape_fixed_surface_ref', w.shape_fixed_surface_ref
    ),
    'accepted_plan', jsonb_build_object(
      'id', p.id, 'ref', p.plan_ref, 'hash', p.plan_hash,
      'work_request_version', p.work_request_version, 'runbook_ref', p.runbook_ref,
      'runbook_section_id', p.runbook_section_id, 'runbook_revision_id', p.runbook_revision_id,
      'runbook_content_hash', 'sha256:' || p.runbook_content_hash,
      'scope_summary', p.scope_summary, 'dependency_refs', p.dependency_refs,
      'recovery_ref', p.recovery_ref, 'observability_ref', p.observability_ref,
      'caps', p.caps
    ),
    'acceptance', jsonb_build_object(
      'receipt_id', ar.id, 'base_version', ar.base_version,
      'result_version', ar.result_version, 'plan_hash', ar.plan_hash,
      'accepted_by_actor_id', ar.accepted_by_actor_id, 'accepted_at', ar.accepted_at,
      'shape_fixed_surface_ref', ar.shape_fixed_surface_ref
    ),
    'feedback', jsonb_build_object(
      'criterion_results', p_criterion_results, 'evidence_refs', p_evidence_refs,
      'outcome', p_outcome, 'blocker_code', p_blocker_code,
      'result_summary', p_result_summary, 'observed_minutes', p_observed_minutes,
      'interaction_surface', p_interaction_surface, 'heavy_session_used', p_heavy_session_used,
      'manual_context_transfers', p_manual_context_transfers
    )
  )
    from ops.work_request w
    join ops.sourced_work_request_plan p on p.work_request_id=w.id and p.id=p_plan_id
    join ops.sourced_work_request_plan_acceptance_receipt ar
      on ar.work_request_id=w.id and ar.plan_id=p.id and ar.id=p_plan_acceptance_receipt_id
   where w.id=p_work_request_id;
$$;


--
-- Name: sourced_work_request_plan_digest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_plan_digest(p_preimage jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
  select 'sha256:' || encode(public.digest(p_preimage::text, 'sha256'), 'hex');
$$;


--
-- Name: sourced_work_request_plan_preimage(uuid, text, text, uuid, uuid, text, jsonb, text, text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_plan_preimage(p_work_request_id uuid, p_scope_summary text, p_runbook_ref text, p_runbook_section_id uuid, p_runbook_revision_id uuid, p_runbook_content_hash text, p_dependency_refs jsonb, p_recovery_ref text, p_observability_ref text, p_caps jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
with base as (
  select jsonb_build_object(
    'contract','carr-sourced-ready-plan/v1',
    'work_request',jsonb_build_object('id',w.id,'ref',w.ref,'state',w.state,'version',w.version,'title',w.title,'desired_outcome',w.desired_outcome,'acceptance_criteria',w.acceptance_criteria,'origin_ref',w.origin_ref,'doctrine_section_id',w.doctrine_section_id,'doctrine_revision_id',w.doctrine_revision_id,'doctrine_content_hash',(select 'sha256:'||r.content_hash from public.doctrine_revision r where r.id=w.doctrine_revision_id and r.section_id=w.doctrine_section_id),'triage_classification',w.triage_classification,'triaged_by_actor_id',w.triaged_by_actor_id,'triaged_at',w.triaged_at,'shape_disposition',w.shape_disposition,'shape_fixed_surface_ref',w.shape_fixed_surface_ref,'shape_rationale',w.shape_rationale,'shape_decided_by_actor_id',w.shape_decided_by_actor_id,'shape_decided_at',w.shape_decided_at),
    'runbook',jsonb_build_object('ref',p_runbook_ref,'section_id',p_runbook_section_id,'revision_id',p_runbook_revision_id,'content_hash','sha256:'||p_runbook_content_hash),
    'plan',jsonb_build_object('scope_summary',p_scope_summary,'dependency_refs',p_dependency_refs,'recovery_ref',p_recovery_ref,'observability_ref',p_observability_ref,'caps',p_caps)
  ) preimage, w as work, p_runbook_revision_id
  from ops.work_request w where w.id=p_work_request_id
), item as (
  select ('plan:runbook:'||p_runbook_revision_id::text) plan_revision_ref,
         (work).triaged_at as issued_at, (work).organization_tenant_id, (work).ref, base.preimage,
         ops.context_activation_compiler_items((work).id,(work).organization_tenant_id,p_dependency_refs) compiler_items
  from base
)
  select preimage || jsonb_build_object('context_activation', jsonb_build_object(
    'bundle_digest',ops.context_activation_bundle_digest(ops.context_activation_bundle_from_items(
      organization_tenant_id, ref, plan_revision_ref, 1,
      'sha256:'||encode(public.digest(ops.guidance_import_canonical_json(preimage),'sha256'),'hex'),
      issued_at, compiler_items
    )),
    'item_refs',(select jsonb_agg(value->'canonical_ref' order by ordinal)
      from jsonb_array_elements(compiler_items) with ordinality as x(value,ordinal)),
    'base_plan_digest','sha256:'||encode(public.digest(ops.guidance_import_canonical_json(preimage),'sha256'),'hex')
  ), 'context_activation_items',compiler_items) from item;
$$;


--
-- Name: sourced_work_request_shape_disposition_lineage(uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_request_shape_disposition_lineage(p_work_request_id uuid) RETURNS TABLE(work_request_id uuid, original_receipt_id uuid, correction_receipt_id uuid, receipt_kind text, disposition text, fixed_surface_ref text, rationale text, decided_by_actor_id uuid, decided_at timestamp with time zone, base_version integer, result_version integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  original ops.sourced_work_request_shape_disposition_receipt%rowtype;
  correction ops.sourced_work_request_shape_disposition_correction_receipt%rowtype;
begin
  if p_work_request_id is null then return; end if;
  select r.* into original from ops.sourced_work_request_shape_disposition_receipt r
   where r.work_request_id = p_work_request_id;
  if not found then return; end if;
  select c.* into correction from ops.sourced_work_request_shape_disposition_correction_receipt c
   where c.work_request_id = p_work_request_id;
  if not found then
    if exists (select 1 from ops.sourced_work_request_shape_disposition_correction_receipt c
                where c.original_receipt_id = original.id) then
      raise exception 'sourced shape disposition lineage is ambiguous';
    end if;
    return query select original.work_request_id, original.id, null::uuid, 'original'::text,
      original.disposition, original.fixed_surface_ref, original.rationale,
      original.decided_by_actor_id, original.decided_at, original.base_version, original.result_version;
    return;
  end if;
  if correction.original_receipt_id is distinct from original.id
     or correction.base_version is distinct from original.result_version
     or correction.result_version is distinct from original.result_version + 1
     or original.disposition is distinct from 'not_required'
     or correction.disposition is distinct from 'required'
     or correction.fixed_surface_ref is not null then
    raise exception 'sourced shape disposition lineage is ambiguous';
  end if;
  return query select original.work_request_id, original.id, correction.id, 'correction'::text,
    correction.disposition, correction.fixed_surface_ref, correction.rationale,
    correction.decided_by_actor_id, correction.decided_at, correction.base_version, correction.result_version;
end;
$$;


--
-- Name: sourced_work_shape_receipts_are_immutable(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_shape_receipts_are_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
begin
  raise exception 'sourced Work Request shape receipts are append-only';
end;
$$;


--
-- Name: sourced_work_shape_revision_requires_effective_required(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sourced_work_shape_revision_requires_effective_required() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  w ops.work_request%rowtype;
begin
  select x.* into w from ops.work_request x where x.id = new.work_request_id;
  if not found or w.capture_idempotency_key is null
     or not exists (select 1 from ops.sourced_work_request_shape_disposition_receipt r
                     where r.work_request_id = w.id) then
    return new;
  end if;
  if new.work_request_version is distinct from w.version
     or not exists (select 1 from ops.effective_sourced_work_request_shape_disposition(w) e
                     where e.disposition = 'required') then
    raise exception 'a sourced Work Shape revision requires the exact current receipt-backed required disposition';
  end if;
  return new;
end;
$$;


--
-- Name: stage_guidance_import_batch(text, text, uuid, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.stage_guidance_import_batch(p_manifest_digest text, p_canonical_manifest_text text, p_classifier_actor_id uuid, p_idempotency_key text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_batch_id uuid;
  v_source_digest text;
  v_manifest jsonb;
  v_existing record;
  v_entry jsonb;
  v_ordinal integer := 0;
begin
  if p_manifest_digest !~ '^[0-9a-f]{64}$'
     or coalesce(btrim(p_idempotency_key),'')=''
     or coalesce(btrim(p_reason),'')='' then
    raise exception 'guidance import staging requires digest, idempotency key and reason';
  end if;
  if coalesce(p_canonical_manifest_text,'')='' or right(p_canonical_manifest_text,1) <> E'\n'
     or position(E'\r' in p_canonical_manifest_text) <> 0 then
    raise exception 'guidance import manifest must be the declared newline-terminated UTF-8 canonical artifact';
  end if;
  begin
    v_manifest := p_canonical_manifest_text::jsonb;
  exception when others then
    raise exception 'guidance import manifest is not valid JSON';
  end;
  perform ops.validate_guidance_import_manifest(v_manifest);
  if coalesce(v_manifest->>'canonicalization','') <> 'utf8-json-sort-keys-compact-newline/v1' then
    raise exception 'guidance import manifest has an unsupported canonicalization identifier';
  end if;
  if current_setting('server_encoding') <> 'UTF8'
     or p_canonical_manifest_text <> ops.guidance_import_canonical_json(v_manifest) || E'\n' then
    raise exception 'guidance import manifest bytes do not match utf8-json-sort-keys-compact-newline/v1';
  end if;
  if p_manifest_digest is distinct from ops.guidance_import_manifest_digest(p_canonical_manifest_text) then
    raise exception 'guidance import digest does not match the canonical manifest';
  end if;
  select id,manifest_digest,canonical_manifest_text,manifest_json,source_manifest_digest,classifier_actor_id,reason
    into v_existing from ops.guidance_import_batch where staging_key=p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.manifest_digest<>p_manifest_digest
       or v_existing.canonical_manifest_text is distinct from p_canonical_manifest_text
       or v_existing.manifest_json is distinct from v_manifest
       or v_existing.classifier_actor_id<>p_classifier_actor_id
       or v_existing.reason<>p_reason then
      raise exception 'idempotency key already names a different guidance import stage';
    end if;
    return v_existing.id;
  end if;
  if exists (select 1 from ops.guidance_import_batch where manifest_digest=p_manifest_digest) then
    raise exception 'guidance import digest is already staged under another idempotency key';
  end if;
  if not exists (select 1 from actor where id=p_classifier_actor_id
                 and kind in ('automation','system') and active) then
    raise exception 'guidance import staging requires an active non-human classifier actor';
  end if;
  v_source_digest := v_manifest->'source_manifest'->>'sha256';
  insert into ops.guidance_import_batch
    (manifest_digest,canonical_manifest_text,manifest_json,source_manifest_digest,classifier_actor_id,staging_key,reason)
  values (p_manifest_digest,p_canonical_manifest_text,v_manifest,v_source_digest,p_classifier_actor_id,p_idempotency_key,p_reason)
  returning id into v_batch_id;
  for v_entry in select value from jsonb_array_elements(v_manifest->'entries') loop
    v_ordinal := v_ordinal + 1;
    insert into ops.guidance_import_entry
      (batch_id,ordinal,guidance_id,source_rule_id,source_clause,is_primary,split_group_key,
       guidance_type,scope,activation,consumer,verification,provenance,delivery,
       is_constitution,revision_reason,situation_mappings)
    values
      (v_batch_id,v_ordinal,v_entry->>'guidance_id',(v_entry->>'source_rule_id')::uuid,
       v_entry->>'source_clause',(v_entry->>'is_primary')::boolean,
       nullif(v_entry->>'split_group_key',''),v_entry->>'guidance_type',v_entry->'scope',
       v_entry->'activation',v_entry->>'consumer',v_entry->'verification',v_entry->'provenance',
       v_entry->'delivery',(v_entry->>'is_constitution')::boolean,v_entry->>'reason',
       coalesce(v_entry->'activation'->'situation_mappings','[]'::jsonb));
  end loop;
  perform ops.assert_guidance_import_inventory(v_batch_id);
  return v_batch_id;
end $_$;


--
-- Name: staging_release_approval_is_typed(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.staging_release_approval_is_typed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare receipt ops.staging_release_approval_receipt%rowtype;
begin
  if tg_op='UPDATE' and old.environment='staging'
     and old.state in ('approved','deploying','verifying','complete')
     and new.environment is distinct from old.environment then
    raise exception 'promoted staging release environment is immutable';
  end if;
  if new.environment<>'staging' or new.state not in ('approved','deploying','verifying','complete') then return new; end if;
  if new.staging_approval_receipt_id is null then raise exception 'staging promoted release requires its typed approval receipt'; end if;
  select * into receipt from ops.staging_release_approval_receipt where id=new.staging_approval_receipt_id;
  if not found or receipt.release_id<>new.id or receipt.plan_hash<>new.plan_hash
     or receipt.approved_by_actor<>'joe' or new.approved_by_actor<>receipt.approved_by_actor
     or new.approved_at<>receipt.approved_at or new.approval_expires_at<>receipt.approval_expires_at
     or new.verifier_actor<>receipt.verifier_actor or new.verifier_evidence_ref<>receipt.verifier_evidence_ref then
    raise exception 'staging promoted release does not match its typed approval receipt';
  end if;
  if tg_op='UPDATE' and old.state in ('approved','deploying','verifying','complete')
     and (new.staging_approval_receipt_id,new.approved_by_actor,new.approved_at,new.approval_expires_at,
          new.verifier_actor,new.verifier_evidence_ref) is distinct from
         (old.staging_approval_receipt_id,old.approved_by_actor,old.approved_at,old.approval_expires_at,
          old.verifier_actor,old.verifier_evidence_ref) then
    raise exception 'staging approval projection is immutable across promoted states';
  end if;
  if (tg_op='INSERT' or old.state not in ('approved','deploying','verifying','complete'))
     and session_user<>'carr_authority_joe' then raise exception 'staging approval requires Joe authority'; end if;
  return new;
end $$;


--
-- Name: staging_release_plan_revision_invalidates_approval(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.staging_release_plan_revision_invalidates_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.environment='staging' and old.plan_hash is distinct from new.plan_hash
     and old.state='complete' then raise exception 'complete staging release plan is immutable';
  end if;
  if old.environment='staging' and old.plan_hash is distinct from new.plan_hash
     and old.state in ('approved','deploying','verifying') then
    new.state:='candidate'; new.approved_by_actor:=null; new.approved_at:=null;
    new.approval_expires_at:=null; new.staging_approval_receipt_id:=null;
  end if;
  return new;
end $$;


--
-- Name: standing_guidance(text, text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.standing_guidance(p_actor text, p_workflow text DEFAULT NULL::text, p_surface text DEFAULT NULL::text, p_tier text DEFAULT NULL::text) RETURNS TABLE(source_rule_id uuid, statement text, human_quote text, taught_by text, personal_to text, scope jsonb, guidance_type text, is_constitution boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select r.id,r.statement,r.human_quote,teacher.display_name,owner.slug,g.scope,
         g.guidance_type,g.is_constitution
    from ops.v_guidance_current g
    join public.rule r on r.id=g.source_rule_id and r.status='active'
    join public.actor teacher on teacher.id=r.taught_by
    left join public.actor owner on owner.id=r.personal_to
   where exists (
           select 1
             from ops.v_guidance_registry_state s
             join ops.guidance_registry registry
               on registry.id=s.registry_id and registry.singleton
            where s.state='active'
         )
     and (r.personal_to is null or owner.slug=p_actor)
     and (
       g.is_constitution
       or (g.guidance_type='constraint' and exists (
         select 1 from ops.applicable_rules(p_workflow,p_surface,p_tier) ar
          where ar.rule_id=r.id))
     )
   order by g.is_constitution desc,r.personal_to nulls first,r.created_at,r.id
$$;


--
-- Name: FUNCTION standing_guidance(p_actor text, p_workflow text, p_surface text, p_tier text); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.standing_guidance(p_actor text, p_workflow text, p_surface text, p_tier text) IS 'Reader-facing active Guidance Registry projection. SECURITY DEFINER with a fixed search_path so carr_reader can consume the sanctioned projection without receiving direct public.rule or public.actor table access.';


--
-- Name: start_meeting(text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.start_meeting(p_platform text, p_source_system text, p_native_id text, p_native_id_epoch text, p_title text, p_activation_intent text, p_client_instance text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public'
    AS $$
declare v_who record; v_id uuid; v_row ops.meeting%rowtype; v_seq bigint;
begin
  select * into v_who from ops.meeting_mode_actor();
  if v_who.tenant is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_tenant_context_unavailable');
  end if;
  if not v_who.is_partner then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_start_requires_verified_partner');
  end if;
  if p_activation_intent is distinct from 'one_tap_user_activation' then
    return jsonb_build_object('ok', false, 'reason_id', 'explicit_human_activation_required');
  end if;
  if p_idempotency_key is null then
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_idempotency_key_required');
  end if;

  insert into ops.meeting(id, organization_tenant_id, platform, source_system, native_id,
    native_id_epoch, title, activation_intent, started_by_actor)
  values (p_idempotency_key, v_who.tenant, p_platform, p_source_system, p_native_id,
    p_native_id_epoch, p_title, p_activation_intent, v_who.actor_id)
  on conflict do nothing
  returning id into v_id;

  if v_id is not null then
    perform ops.meeting_mode_append(v_id, 'meeting_started', v_who.actor_id, p_client_instance,
      null, null, null, null, p_idempotency_key);
    select * into v_row from ops.meeting where id = v_id;
    return jsonb_build_object('ok', true, 'deduplicated', false, 'joined_existing', false,
      'meeting_id', v_row.id, 'title', v_row.title, 'mode_state', v_row.mode_state,
      'started_by', v_who.actor_slug, 'last_seq', v_row.last_seq);
  end if;

  select * into v_row from ops.meeting
   where organization_tenant_id = v_who.tenant and coalesce(platform, '') = coalesce(p_platform, '')
     and source_system = p_source_system and native_id = p_native_id
     and native_id_epoch = p_native_id_epoch
   for update;
  if v_row.id is null then
    -- The conflict was on the primary key: this idempotency key already names
    -- a DIFFERENT meeting. That is a reuse, never a join.
    return jsonb_build_object('ok', false, 'reason_id', 'meeting_idempotency_key_reuse');
  end if;
  if v_row.id = p_idempotency_key then
    if v_row.started_by_actor is distinct from v_who.actor_id or v_row.title is distinct from p_title then
      return jsonb_build_object('ok', false, 'reason_id', 'meeting_idempotency_key_reuse');
    end if;
    return jsonb_build_object('ok', true, 'deduplicated', true, 'joined_existing', false,
      'meeting_id', v_row.id, 'title', v_row.title, 'mode_state', v_row.mode_state,
      'started_by', (select slug from public.actor where id = v_row.started_by_actor),
      'last_seq', v_row.last_seq);
  end if;
  -- An ended meeting is reported as ended and gains no join entry: it cannot
  -- be reopened by starting it again.
  if v_row.mode_state <> 'ended' then
    v_seq := ops.meeting_mode_append(v_row.id, 'meeting_joined', v_who.actor_id, p_client_instance,
      null, null, null, null, p_idempotency_key);
  end if;
  return jsonb_build_object('ok', true, 'deduplicated', v_seq is null and v_row.mode_state <> 'ended',
    'joined_existing', true,
    'meeting_id', v_row.id, 'title', v_row.title, 'mode_state', v_row.mode_state,
    'started_by', (select slug from public.actor where id = v_row.started_by_actor),
    'last_seq', (select last_seq from ops.meeting where id = v_row.id));
end $$;


--
-- Name: supersede_sourced_work_request(text, integer, text, text, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.supersede_sourced_work_request(p_work_request text, p_base_version integer, p_exit_reason text, p_superseded_by text, p_actor_slug text, p_idempotency_key uuid) RETURNS TABLE(ref text, state text, version integer, exit_reason text, closed_at timestamp with time zone, superseded_by_ref text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
declare
  v_id uuid;
  v_succ uuid;
  v_succ_state text;
  v_succ_sourced boolean;
  v_actor uuid;
  v_now timestamp with time zone := now();
begin
  if p_exit_reason is null or btrim(p_exit_reason) = '' then
    raise exception 'a withdrawal must record why';
  end if;
  select a.id into v_actor from public.actor a where a.slug = p_actor_slug;
  if v_actor is null then
    raise exception 'unknown actor %', p_actor_slug;
  end if;

  select w.id into v_id from ops.work_request w
   where w.ref = p_work_request and w.capture_idempotency_key is not null
     and w.state = 'captured' and w.version = p_base_version
   for update;
  if v_id is null then
    raise exception 'no captured sourced Work Request % at version %', p_work_request, p_base_version;
  end if;

  select w.id, w.state, (w.capture_idempotency_key is not null)
    into v_succ, v_succ_state, v_succ_sourced
    from ops.work_request w where w.ref = p_superseded_by;
  if v_succ is null then
    raise exception 'no Work Request % to supersede it', p_superseded_by;
  end if;
  -- The four refusals the foreign key does not give.
  if v_succ = v_id then
    raise exception 'a Work Request cannot supersede itself';
  end if;
  if v_succ_state in ('declined','superseded') then
    raise exception 'the successor % is itself withdrawn; superseding into a dead row loses the trail', p_superseded_by;
  end if;
  if not v_succ_sourced then
    raise exception 'the successor % is not a sourced Work Request', p_superseded_by;
  end if;
  if exists (select 1 from ops.work_request w
              where w.id = v_succ and w.superseded_by = v_id) then
    raise exception 'that would make a two-row supersession cycle';
  end if;

  insert into ops.work_request_withdrawal_receipt
    (work_request_id, idempotency_key, base_version, result_version, final_state,
     exit_reason, superseded_by, withdrawn_by_actor_id, withdrawn_at)
  values (v_id, p_idempotency_key, p_base_version, p_base_version + 1, 'superseded',
          p_exit_reason, v_succ, v_actor, v_now)
  on conflict (idempotency_key) do nothing;

  update ops.work_request w
     set state = 'superseded', exit_reason = p_exit_reason, closed_at = v_now,
         superseded_by = v_succ, version = w.version + 1, updated_at = v_now
   where w.id = v_id;

  return query
    select w.ref, w.state, w.version, w.exit_reason, w.closed_at, s.ref
      from ops.work_request w
      left join ops.work_request s on s.id = w.superseded_by
     where w.id = v_id;
end;
$$;


--
-- Name: sync_system_rule_control_bindings(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sync_system_rule_control_bindings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_expected record;
  v_rule rule%rowtype;
  v_rows integer;
  v_inserted integer := 0;
begin
  for v_expected in
    select * from (values
      ('ae44e0c0-e773-456c-a85b-2dc4cf4dd49e'::uuid,
       '9e02f7eee01220fd604ba97d605830ea903d3266f95b626a5ca5d9a73567c8f9',
       '{}'::jsonb,
       '4a0e59ce-728a-49b5-a055-116156e9470e'::uuid,
       '1fe7c57e-c23f-4fb0-9cff-36f6d3cfcf08'::uuid,
       'Joe is the sole required authority for system development and high-level system decisions',
       $q$One thing I need to make sure of, I do not want this system to become dependent on dell’s approval for changes. He is not involved in system development at all. He is basically just a user of the system who may train a new work flow here and there but he will not be involved in building the system or making high level decisions about the way the system functions. He’s relying on me for that. Don’t block him from any of those decisions but don’t require his approval either$q$,
       'human_authority_runtime',
       'Joe-approved sole system authority'),
      ('a57d981a-8f6d-4c18-95ee-0e63a5a90b89'::uuid,
       'c6fd62eb91d3f03b21a6098a6fd6b2848b902a45b8c0430b1717edf4e143f668',
       $scope${"domain":"system","applies_to":["github","neon","cloudflare","anthropic","openai","google","healthchecks","blotato","make"]}$scope$::jsonb,
       '8b31938a-e2f2-4b8f-9c29-187efa5c1650'::uuid,
       'f7ea060c-268b-47f1-8a17-7168841b77e0'::uuid,
       'Make cost discipline permanent; expire only the temporary emergency restriction',
       $q$But also, we want a budget rule in affect going forward not just expiring in September. We need to operate the system with cost in mind. Not to the point where it limits the system but just to the point where excessive spending is avoided$q$,
       'platform_metering_pre_dispatch',
       'Joe-approved permanent platform cost policy')
    ) as expected(rule_id,statement_hash,rule_scope,decision_id,decision_event_id,
                  decision_title,human_quote,control_key,source)
  loop
    select * into v_rule from rule where id=v_expected.rule_id;
    if not found then continue; end if;
    if v_rule.id='a57d981a-8f6d-4c18-95ee-0e63a5a90b89'::uuid
       and exists (select 1 from public.event
                     where id='34f34e23-225b-4d0f-946f-478b59fbce63'::uuid) then
      -- The legacy cost restriction was truthfully retired before 0228 reached
      -- Production.  This is an exact one-row tombstone, not a general escape
      -- hatch for retired rules; any drift remains a hard refusal.
      if not exists (
        select 1
          from rule r
          join public.actor taught_by on taught_by.id=r.taught_by
          join public.event e on e.id='34f34e23-225b-4d0f-946f-478b59fbce63'::uuid
          join public.actor event_actor on event_actor.id=e.actor_id
         where r.id='a57d981a-8f6d-4c18-95ee-0e63a5a90b89'::uuid
           and r.status='retired' and r.version=2
           and encode(digest(r.statement,'sha256'),'hex')='c6fd62eb91d3f03b21a6098a6fd6b2848b902a45b8c0430b1717edf4e143f668'
           and r.human_quote=$q$Also, how does this budgeting plan become impossible to overlook? If it’s just prose the system won’t remember it$q$
           and r.scope='{"domain":"system","applies_to":["github","neon","cloudflare","anthropic","openai","google","healthchecks","blotato","make"]}'::jsonb
           and r.personal_to is null and r.enforcement='prose'
           and r.activated_by is null and r.activated_at is null
           and r.supersedes is null
           and r.created_at='2026-08-17T08:29:06.905178Z'::timestamptz
           and r.updated_at='2026-08-21T21:38:29.049309Z'::timestamptz
           and taught_by.id='b6c38b27-d006-4fad-9c38-49edf3130a07'::uuid
           and taught_by.slug='joe' and taught_by.kind='human' and taught_by.active
           and not exists (select 1 from rule successor where successor.supersedes=r.id)
           and e.actor_id='b6c38b27-d006-4fad-9c38-49edf3130a07'::uuid
           and event_actor.slug='joe' and event_actor.kind='human' and event_actor.active
           and e.verb='retire-rule' and e.subject_type='rule' and e.subject_id=r.id
           and e.field='status'
           and e.old_value='{"status":"proposed"}'::jsonb
           and e.new_value='{"status":"retired"}'::jsonb
           and e.cause='automation_job'
           and e.human_quote is null
           and e.occurred_at='2026-08-21T21:38:29.049309Z'::timestamptz
           and e.recorded_at='2026-08-21T21:38:29.049309Z'::timestamptz
           and e.via='oauth-google'
           and e.client_id='https://claude.ai/oauth/mcp-oauth-client-metadata'
           and e.sponsoring_human_slug='joe'
           and e.personal_scope='joe-personal'
           and e.authorization_class='verified_partner'
           and e.organization_tenant_id='carr-internal'
           and e.correlation_id='6923f7f8-4ae6-4db0-93ab-9424d5aea0f1'::uuid
           and e.idempotency_key='c4ad90f7-d8dd-4bf3-8785-659bae3d3f27'
           and encode(digest(coalesce(e.agent_rationale,''),'sha256'),'hex')='82cf84d571cbe49eb61bf9570e2c8f86a114fa216e9ab1b3799181045c881137'
      ) then
        raise exception 'legacy retired system cost rule does not match its exact retirement tombstone preimage';
      end if;
      continue;
    end if;
    if v_rule.status not in ('proposed','active') then
      raise exception 'system rule % is %, expected proposed or active',v_rule.id,v_rule.status;
    end if;
    if v_rule.personal_to is not null
       or v_rule.scope is distinct from v_expected.rule_scope then
      raise exception 'system rule % does not match its exact approved shared scope',v_rule.id;
    end if;
    if encode(digest(v_rule.statement,'sha256'),'hex') is distinct from v_expected.statement_hash then
      raise exception 'system rule % statement does not match Joe-approved preimage',v_rule.id;
    end if;
    if not exists (
      select 1 from public.v_decision_entry d
       where d.decision_id=v_expected.decision_id
         and d.event_id=v_expected.decision_event_id
         and d.title=v_expected.decision_title
         and d.human_quote=v_expected.human_quote
    ) then
      raise exception 'system rule % lacks its exact Joe decision evidence',v_rule.id;
    end if;
    if not exists (
      select 1 from ops.enforcement_control_catalog c
       where c.control_key=v_expected.control_key
         and c.installed and c.verified_at is not null
    ) then
      raise exception 'system rule % control % is not installed',v_rule.id,v_expected.control_key;
    end if;

    if not exists (
      select 1 from ops.rule_control_binding
       where rule_id=v_rule.id and control_key=v_expected.control_key
    ) then
      insert into ops.rule_control_binding
        (rule_id,control_key,statement_hash,binding_contract)
      select v_rule.id,v_expected.control_key,v_expected.statement_hash,
             jsonb_build_object(
               'source',v_expected.source,
               'durable_decision_ref',v_expected.decision_id,
               'decision_event_ref',v_expected.decision_event_id,
               'rule_id',v_rule.id,
               'rule_version',v_rule.version,
               'implementation_ref',c.implementation_ref,
               'test_ref',c.test_ref)
        from ops.enforcement_control_catalog c
       where c.control_key=v_expected.control_key;
      get diagnostics v_rows = row_count;
    else
      v_rows := 0;
    end if;
    v_inserted := v_inserted + v_rows;

    if not exists (
      select 1 from ops.rule_control_binding b
       where b.rule_id=v_rule.id and b.control_key=v_expected.control_key
         and b.statement_hash=v_expected.statement_hash
         and b.binding_contract->>'durable_decision_ref'=v_expected.decision_id::text
         and b.binding_contract->>'decision_event_ref'=v_expected.decision_event_id::text
    ) then
      raise exception 'system rule % has a stale or conflicting control binding',v_rule.id;
    end if;
  end loop;
  return v_inserted;
end $_$;


--
-- Name: timeout_job(uuid, uuid, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.timeout_job(p_job_id uuid, p_lease_token uuid, p_detail text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare j ops.job%rowtype; next_state text;
begin
  select * into j from ops.job where id=p_job_id for update;
  if found and j.definition_key='engineering-slice' then
    raise exception 'engineering jobs require scoped controller functions';
  end if;
  if not found or j.state <> 'running' or j.lease_token <> p_lease_token
     or j.leased_until < now() then
    raise exception 'job % does not hold this live lease',p_job_id;
  end if;
  next_state := case when j.attempt < j.max_attempts then 'retry_wait' else 'dead_lettered' end;
  update ops.job_attempt set state='timed_out',ended_at=now(),
         failure_class='execution_timeout',detail=p_detail
   where job_id=j.id and attempt=j.attempt and lease_token=p_lease_token;
  update ops.job set state=next_state,
         next_attempt_at=case when next_state='retry_wait'
                              then now()+make_interval(secs=>ops.retry_delay_seconds(j))
                              else next_attempt_at end,
         ended_at=case when next_state='dead_lettered' then now() else null end,
         last_failure_class='execution_timeout',last_failure_detail=p_detail,
         lease_owner=null,lease_token=null,leased_until=null,updated_at=now()
   where id=j.id;
  insert into ops.job_receipt(job_id,attempt,kind,receipt_ref,evidence)
    values(j.id,j.attempt,case when next_state='dead_lettered' then 'dead_letter' else 'timeout' end,
           concat('timeout:',j.id,':',j.attempt),
           jsonb_build_object('failure_class','execution_timeout','detail',p_detail,'next_state',next_state));
  return next_state;
end $$;


--
-- Name: tour_assertion_rights_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_assertion_rights_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_provider text; v_policy_key text;
begin
  select e.rights_provider,e.rights_policy_key into v_provider,v_policy_key
    from ops.tour_source_evidence e
   where e.id=new.source_evidence_id and e.organization_tenant_id=new.organization_tenant_id;
  if not found or v_provider is null or v_policy_key is null then
    raise exception 'assertion evidence rights lineage is unavailable';
  end if;
  perform ops.tour_rights_provider_policy_lock(new.organization_tenant_id,v_provider,v_policy_key);
  if not exists (
    select 1 from ops.tour_rights_receipt r
     where r.id=new.rights_receipt_id and r.organization_tenant_id=new.organization_tenant_id
       and r.id=(select e.rights_receipt_id from ops.tour_source_evidence e
                  where e.id=new.source_evidence_id and e.organization_tenant_id=new.organization_tenant_id)
       and r.provider=v_provider and r.policy_key=v_policy_key
       and r.status='active' and r.effective_at <= new.observed_at
       and (r.expires_at is null or r.expires_at > new.observed_at) and r.revoked_at is null
       and r.allowed_use_classes ? 'canonical_fact'
       and (r.allowed_field_classes ? new.field_key or r.allowed_field_classes ? '*')
       and not exists (
         select 1 from ops.tour_rights_receipt newer
          where newer.organization_tenant_id=r.organization_tenant_id
            and newer.provider=r.provider and newer.policy_key=r.policy_key
            and newer.receipt_version > r.receipt_version and newer.effective_at <= new.observed_at
       )
  ) then
    raise exception 'rights receipt refuses asserted field/use';
  end if;
  return new;
end $$;


--
-- Name: tour_canonical_projection_digest(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_canonical_projection_digest(p_tenant text, p_projection_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_projection ops.tour_public_projection%rowtype; v_fact_lines text; v_map_lines text; v_bytes text;
begin
  select * into v_projection from ops.tour_public_projection where id=p_projection_id and organization_tenant_id=p_tenant;
  if not found then raise exception 'canonical projection digest target is unavailable'; end if;
  select string_agg(
    f.property_id::text || '|' || f.field_assertion_id::text || '|' || f.route_version::text || '|' ||
    replace(encode(convert_to(f.display_field_key,'UTF8'),'base64'),E'\n',''),
    E'\n' order by f.property_id::text,convert_to(f.display_field_key,'UTF8'),f.field_assertion_id::text
  ) into v_fact_lines from ops.tour_public_projection_fact f
   where f.organization_tenant_id=p_tenant and f.projection_id=p_projection_id;
  select string_agg(
    mp.property_id::text || '|' || mp.coordinate_candidate_id::text || '|' ||
    mp.entrance_verification_receipt_id::text || '|' || mp.route_version::text,
    E'\n' order by mp.property_id::text,mp.coordinate_candidate_id::text,mp.entrance_verification_receipt_id::text
  ) into v_map_lines from ops.tour_public_projection_map_point mp
   where mp.organization_tenant_id=p_tenant and mp.projection_id=p_projection_id;
  v_bytes := array_to_string(array[
    'public-tour-projection-digest.v2',
    replace(encode(convert_to(p_tenant,'UTF8'),'base64'),E'\n',''),
    v_projection.tour_id::text,p_projection_id::text,v_projection.projection_version::text,
    v_projection.route_version::text,
    to_char(date_trunc('milliseconds',v_projection.as_of at time zone 'UTC'),'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  ],E'\n') || case when v_fact_lines is null then '' else E'\n' || v_fact_lines end
    || case when v_map_lines is null then '' else E'\nmap' || E'\n' || v_map_lines end;
  return 'sha256:' || encode(public.digest(convert_to(v_bytes,'UTF8'),'sha256'),'hex');
end $$;


--
-- Name: tour_conflict_participant_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_conflict_participant_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from ops.tour_fact_conflict c join ops.tour_field_assertion a on a.id=new.field_assertion_id and a.organization_tenant_id=new.organization_tenant_id where c.id=new.conflict_id and c.organization_tenant_id=new.organization_tenant_id and c.property_id=a.property_id and c.field_key=a.field_key) then raise exception 'conflict participant does not match conflict property and field'; end if;
  return new;
end $$;


--
-- Name: tour_conflict_resolution_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_conflict_resolution_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from ops.tour_fact_conflict_participant p join ops.tour_fact_conflict c on c.id=p.conflict_id and c.organization_tenant_id=p.organization_tenant_id join ops.tour_field_assertion a on a.id=p.field_assertion_id and a.organization_tenant_id=p.organization_tenant_id where p.conflict_id=new.conflict_id and p.organization_tenant_id=new.organization_tenant_id and p.field_assertion_id=new.selected_field_assertion_id and a.property_id=c.property_id and a.field_key=c.field_key) then raise exception 'conflict resolution selection is not a matching participant'; end if;
  return new;
end $$;


--
-- Name: tour_delivery_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_delivery_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin raise exception '% is append-only',tg_table_name; end $$;


--
-- Name: tour_membership_seal_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_membership_seal_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform 1 from ops.tour where id=new.tour_id and organization_tenant_id=new.organization_tenant_id for update;
  if exists (select 1 from ops.tour_public_projection p where p.organization_tenant_id=new.organization_tenant_id and p.tour_id=new.tour_id and p.route_version=new.route_version) then raise exception 'tour route version is sealed by an existing projection'; end if;
  return new;
end $$;


--
-- Name: tour_projection_creation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_projection_creation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  if new.status <> 'draft' then raise exception 'projection creation requires draft status'; end if;
  perform 1 from ops.tour where id=new.tour_id and organization_tenant_id=new.organization_tenant_id for update;
  if not exists (select 1 from ops.tour_property_membership m where m.organization_tenant_id=new.organization_tenant_id and m.tour_id=new.tour_id and m.route_version=new.route_version)
     or exists (select 1 from ops.tour_property_membership m where m.organization_tenant_id=new.organization_tenant_id and m.tour_id=new.tour_id and m.route_version=new.route_version and m.selected_at > new.as_of) then
    raise exception 'projection requires a complete membership set selected by as_of';
  end if;
  return new;
end $$;


--
-- Name: tour_projection_fact_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_projection_fact_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare p ops.tour_public_projection%rowtype; v_provider text; v_policy_key text;
begin
  if tg_op <> 'INSERT' then raise exception 'tour_public_projection_fact is append-only'; end if;
  select * into p from ops.tour_public_projection
   where id=new.projection_id and organization_tenant_id=new.organization_tenant_id for update;
  if not found then raise exception 'projection fact projection is unavailable'; end if;
  select e.rights_provider,e.rights_policy_key into v_provider,v_policy_key
    from ops.tour_field_assertion a join ops.tour_source_evidence e
      on e.id=a.source_evidence_id and e.organization_tenant_id=a.organization_tenant_id
   where a.id=new.field_assertion_id and a.organization_tenant_id=new.organization_tenant_id;
  if not found or v_provider is null or v_policy_key is null then raise exception 'projection fact evidence rights lineage is unavailable'; end if;
  perform ops.tour_rights_provider_policy_lock(new.organization_tenant_id,v_provider,v_policy_key);
  if not exists (
    select 1 from ops.tour_field_assertion a
    join ops.tour_source_evidence e on e.id=a.source_evidence_id and e.organization_tenant_id=a.organization_tenant_id
    join ops.tour_rights_receipt r on r.id=a.rights_receipt_id and r.organization_tenant_id=a.organization_tenant_id
    join ops.tour_property_membership m on m.tour_id=p.tour_id and m.property_id=new.property_id and m.organization_tenant_id=new.organization_tenant_id and m.route_version=p.route_version
    where p.status='draft' and not exists (select 1 from ops.tour_public_projection_seal_receipt seal where seal.organization_tenant_id=p.organization_tenant_id and seal.projection_id=p.id)
      and new.route_version=p.route_version and a.id=new.field_assertion_id and a.organization_tenant_id=new.organization_tenant_id
      and a.property_id=new.property_id and a.field_key=new.display_field_key and a.rights_receipt_id=e.rights_receipt_id
      and r.provider=e.rights_provider and r.policy_key=e.rights_policy_key
      and e.retrieval_status='read' and e.retrieved_at <= p.as_of
      and a.review_state='reviewed' and a.data_classification='public' and a.confidence <> 'unknown'
      and m.selected_at <= p.as_of and a.observed_at <= p.as_of
      and a.effective_from <= p.as_of and (a.effective_to is null or a.effective_to > p.as_of)
      and r.status='active' and r.effective_at <= p.as_of and (r.expires_at is null or r.expires_at > p.as_of) and r.revoked_at is null
      and r.allowed_use_classes ? 'client_public_display' and (r.allowed_field_classes ? a.field_key or r.allowed_field_classes ? '*')
      and not exists (select 1 from ops.tour_rights_receipt newer where newer.organization_tenant_id=r.organization_tenant_id and newer.provider=r.provider and newer.policy_key=r.policy_key and newer.receipt_version > r.receipt_version and newer.effective_at <= p.as_of)
      and not exists (
        select 1 from ops.tour_fact_conflict conflict
        where conflict.organization_tenant_id=a.organization_tenant_id
          and conflict.property_id=a.property_id and conflict.field_key=a.field_key
          and conflict.state <> 'superseded' and conflict.opened_at <= p.as_of
          and not exists (
            select 1 from ops.tour_conflict_resolution_receipt resolution
            where resolution.organization_tenant_id=conflict.organization_tenant_id
              and resolution.conflict_id=conflict.id
              and resolution.selected_field_assertion_id=a.id
              and resolution.resolved_at <= p.as_of
          )
      )
      and ops.tour_public_value_safe(a.field_key,a.value)
  ) then raise exception 'projection fact lacks current public assertion, rights, or safe value'; end if;
  return new;
end $$;


--
-- Name: tour_projection_seal_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_projection_seal_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_projection ops.tour_public_projection%rowtype; v_digest text;
begin
  select * into v_projection from ops.tour_public_projection where id=new.projection_id and organization_tenant_id=new.organization_tenant_id for update;
  if not found then raise exception 'projection seal target is unavailable'; end if;
  if new.sealed_state <> 'approved' then raise exception 'projection seal cannot publish'; end if;
  if v_projection.status <> 'draft' or exists (select 1 from ops.tour_public_projection_seal_receipt s where s.organization_tenant_id=v_projection.organization_tenant_id and s.projection_id=v_projection.id) then raise exception 'projection is not an unsealed draft'; end if;
  if exists (
    select 1 from ops.tour_property_membership m
    cross join (values ('display.name'::text),('display.address'::text)) required(field_key)
    where m.organization_tenant_id=new.organization_tenant_id and m.tour_id=v_projection.tour_id and m.route_version=v_projection.route_version
      and not exists (select 1 from ops.tour_public_projection_fact f where f.organization_tenant_id=m.organization_tenant_id and f.projection_id=v_projection.id and f.property_id=m.property_id and f.display_field_key=required.field_key)
  ) then raise exception 'projection seal requires one complete selected-property fact set'; end if;
  v_digest:=ops.tour_canonical_projection_digest(new.organization_tenant_id,new.projection_id);
  if new.canonical_projection_digest is distinct from v_digest then raise exception 'projection canonical digest is database-computed'; end if;
  update ops.tour_public_projection set status='approved',projection_digest=v_digest
    where id=v_projection.id and organization_tenant_id=v_projection.organization_tenant_id;
  return new;
end $$;


--
-- Name: tour_public_map_projection_evidence_ready(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_public_map_projection_evidence_ready(p_tenant text, p_projection_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from ops.tour_public_projection p
    where p.organization_tenant_id=p_tenant and p.id=p_projection_id and p.status='approved'
      and ops.read_tour_public_projection(p.organization_tenant_id,p.id) is not null
      and exists(select 1 from ops.tour_property_membership m where m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version)
      and (select count(*) from ops.tour_public_projection_map_point mp where mp.organization_tenant_id=p.organization_tenant_id and mp.projection_id=p.id)
        = (select count(*) from ops.tour_property_membership m where m.organization_tenant_id=p.organization_tenant_id and m.tour_id=p.tour_id and m.route_version=p.route_version)
      and not exists (
        select 1 from ops.tour_public_projection_map_point mp
        where mp.organization_tenant_id=p.organization_tenant_id and mp.projection_id=p.id
          and not exists (
            select 1 from ops.tour_property_coordinate_candidate c
            join ops.tour_coordinate_entrance_verification_receipt er on er.organization_tenant_id=c.organization_tenant_id and er.coordinate_candidate_id=c.id and er.property_id=c.property_id
            join ops.tour_source_evidence e on e.organization_tenant_id=c.organization_tenant_id and e.id=c.source_evidence_id and e.rights_receipt_id=c.rights_receipt_id
            join ops.tour_rights_receipt r on r.organization_tenant_id=e.organization_tenant_id and r.id=e.rights_receipt_id and r.provider=e.rights_provider and r.policy_key=e.rights_policy_key
            where c.organization_tenant_id=mp.organization_tenant_id and c.id=mp.coordinate_candidate_id and c.property_id=mp.property_id
              and er.id=mp.entrance_verification_receipt_id and c.coordinate_role in ('entrance','driveway','parking_access') and c.review_state='reviewed'
              and r.status='active' and r.effective_at<=now() and (r.expires_at is null or r.expires_at>now()) and (r.revoked_at is null or r.revoked_at>now())
              and r.allowed_use_classes ? 'client_public_display' and (r.allowed_field_classes ? 'coordinates' or r.allowed_field_classes ? '*')
              and not exists(select 1 from ops.tour_rights_receipt newer where newer.organization_tenant_id=r.organization_tenant_id and newer.provider=r.provider and newer.policy_key=r.policy_key and newer.receipt_version>r.receipt_version and newer.effective_at<=now())
          )
      )
  );
$$;


--
-- Name: tour_public_map_projection_ready(text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_public_map_projection_ready(p_tenant text, p_projection_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select ops.tour_public_map_projection_evidence_ready(p_tenant,p_projection_id)
    and coalesce((
      select r.decision='approved'
      from ops.tour_map_promotion_receipt r
      join ops.tour_public_projection p on p.organization_tenant_id=r.organization_tenant_id and p.id=r.projection_id
      join ops.tour t on t.organization_tenant_id=p.organization_tenant_id and t.id=p.tour_id
      where r.organization_tenant_id=p_tenant and r.projection_id=p_projection_id
        and r.route_version=p.route_version and r.canonical_dataset_version=t.canonical_dataset_version
      order by r.receipt_sequence desc limit 1
    ),false);
$$;


--
-- Name: tour_public_projection_mutation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_public_projection_mutation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  if tg_op <> 'UPDATE' or pg_trigger_depth() < 2
     or old.status <> 'draft' or new.status <> 'approved'
     or (to_jsonb(new)-array['status','projection_digest']) is distinct from (to_jsonb(old)-array['status','projection_digest'])
     or new.projection_digest <> ops.tour_canonical_projection_digest(new.organization_tenant_id,new.id) then
    raise exception 'projection mutation requires atomic approved seal';
  end if;
  return new;
end $$;


--
-- Name: tour_public_value_safe(text, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_public_value_safe(p_field_key text, p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select case
    when p_field_key in ('display.name','display.address') then
      jsonb_typeof(p_value) = 'string' and btrim(p_value #>> '{}') <> '' and char_length(btrim(p_value #>> '{}')) <= 360
    when p_field_key in ('suite','property_type','availability','parking','access','source_attribution','as_of','caveat') then jsonb_typeof(p_value) = 'string'
    when p_field_key in ('size','asking_economics') then
      jsonb_typeof(p_value) = 'object'
      and (p_value ? 'value' or p_value ? 'min' or p_value ? 'max')
      and not exists (
        select 1 from jsonb_each(p_value) e
         where e.key not in ('value','unit','min','max','currency','period','label')
            or (e.key in ('value','min','max') and (
                 jsonb_typeof(e.value) not in ('string','number')
                 or (jsonb_typeof(e.value)='string' and (btrim(e.value #>> '{}')='' or char_length(btrim(e.value #>> '{}'))>120))))
            or (e.key in ('unit','currency','period','label') and (
                 jsonb_typeof(e.value)<>'string'
                 or btrim(e.value #>> '{}')='' or char_length(btrim(e.value #>> '{}'))>120))
      )
      and not (
        jsonb_typeof(p_value->'min')='number' and jsonb_typeof(p_value->'max')='number'
        and (p_value->>'min')::numeric > (p_value->>'max')::numeric
      )
    when p_field_key in ('photos','floor_plan') then jsonb_typeof(p_value) = 'array' and not exists (
      select 1 from jsonb_array_elements(p_value) item
       where jsonb_typeof(item) <> 'object'
          or not (item ? 'asset_ref')
          or (item->>'asset_ref') !~ '^asset:public:[A-Za-z0-9_-]+$'
          or char_length(item->>'asset_ref') not between 29 and 269
          or exists (select 1 from jsonb_each(item) e where e.key not in ('asset_ref','alt','caption','source') or jsonb_typeof(e.value) <> 'string')
    )
    else false end;
$_$;


--
-- Name: tour_publication_creation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_publication_creation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  if new.publication_state <> 'draft' then raise exception 'publication creation requires draft state'; end if;
  if not exists (
    select 1 from ops.tour_public_projection p
     where p.id=new.projection_id and p.organization_tenant_id=new.organization_tenant_id
       and p.status='approved' and p.projection_digest=new.projection_digest
       and exists (select 1 from ops.tour_public_projection_seal_receipt s
                    where s.organization_tenant_id=p.organization_tenant_id and s.projection_id=p.id
                      and s.canonical_projection_digest=p.projection_digest)
  ) then raise exception 'publication projection digest is unavailable'; end if;
  return new;
end $$;


--
-- Name: tour_reject_mutation(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ begin raise exception '% is append-only', tg_table_name; end $$;


--
-- Name: tour_rights_lineage_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_rights_lineage_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare prior ops.tour_rights_receipt%rowtype;
begin
  perform ops.tour_rights_provider_policy_lock(new.organization_tenant_id,new.provider,new.policy_key);
  if new.supersedes_receipt_id is null and new.receipt_version <> 1 then
    raise exception 'rights receipt version requires supersession lineage';
  end if;
  if new.supersedes_receipt_id is not null then
    select * into prior from ops.tour_rights_receipt
      where id=new.supersedes_receipt_id and organization_tenant_id=new.organization_tenant_id for update;
    if not found or prior.policy_key <> new.policy_key or prior.provider <> new.provider
       or new.receipt_version <> prior.receipt_version + 1 then
      raise exception 'rights receipt supersession lineage is invalid';
    end if;
  end if;
  return new;
end $$;


--
-- Name: tour_rights_provider_policy_lock(text, text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_rights_provider_policy_lock(p_tenant text, p_provider text, p_policy_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended(p_tenant || chr(31) || p_provider || chr(31) || p_policy_key, 0));
end $$;


--
-- Name: tour_route_append_only_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_route_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$ begin raise exception '% is append-only',tg_table_name; end $$;


--
-- Name: tour_server_actor_id(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_server_actor_id() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $_$
declare v_actor text;
begin
  if session_user ~ '^carr_authority_' then v_actor:=regexp_replace(session_user,'^carr_authority_','');
  elsif session_user in ('carr_writer','carr_authority') then v_actor:=nullif(btrim(current_setting('carr.acting_actor_slug', true)), '');
  else raise exception 'tour mutation requires an authority connection or sponsored writer session'; end if;
  if v_actor is null or v_actor !~ '^[A-Za-z0-9._:-]{1,160}$' then raise exception 'tour mutation has no server-derived actor'; end if;
  return v_actor;
end $_$;


--
-- Name: tour_share_revocation_receipt_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_share_revocation_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_created_at timestamptz;
begin
  select created_at into v_created_at from ops.tour_share_grant
   where id=new.share_grant_id and organization_tenant_id=new.organization_tenant_id;
  if not found or new.revoked_at < v_created_at then raise exception 'share grant revocation receipt lineage is invalid'; end if;
  return new;
end $$;


--
-- Name: tour_share_rotation_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_share_rotation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare prior ops.tour_share_grant%rowtype;
begin
  if new.rotated_from_grant_id is null and new.grant_version <> 1 then raise exception 'share grant version requires rotation lineage'; end if;
  if new.rotated_from_grant_id is not null then
    if new.rotated_from_grant_id = new.id then raise exception 'share grant cannot rotate itself'; end if;
    select * into prior from ops.tour_share_grant where id=new.rotated_from_grant_id and organization_tenant_id=new.organization_tenant_id for update;
    if not found or prior.projection_id <> new.projection_id or new.grant_version <> prior.grant_version + 1 then raise exception 'share grant rotation lineage is invalid'; end if;
  end if;
  return new;
end $$;


--
-- Name: tour_share_grant; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.tour_share_grant (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    projection_id uuid NOT NULL,
    grant_version integer NOT NULL,
    token_digest text NOT NULL,
    audience text NOT NULL,
    permission_scopes jsonb NOT NULL,
    rotated_from_grant_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    status text NOT NULL,
    receipt_digest text,
    created_by_actor_id text,
    CONSTRAINT tour_share_grant_audience_check CHECK ((audience = ANY (ARRAY['client'::text, 'internal'::text]))),
    CONSTRAINT tour_share_grant_check CHECK (((expires_at IS NULL) OR (expires_at > created_at))),
    CONSTRAINT tour_share_grant_check1 CHECK (((status <> 'revoked'::text) OR (revoked_at IS NOT NULL))),
    CONSTRAINT tour_share_grant_grant_version_check CHECK ((grant_version > 0)),
    CONSTRAINT tour_share_grant_permission_scopes_check CHECK (((jsonb_typeof(permission_scopes) = 'array'::text) AND (jsonb_array_length(permission_scopes) > 0) AND (permission_scopes <@ '["view_packet", "view_map"]'::jsonb))),
    CONSTRAINT tour_share_grant_receipt_digest_valid CHECK (((receipt_digest IS NULL) OR (receipt_digest ~ '^sha256:[a-f0-9]{64}$'::text))),
    CONSTRAINT tour_share_grant_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text, 'expired'::text, 'rotated'::text]))),
    CONSTRAINT tour_share_grant_token_digest_check CHECK ((token_digest ~ '^sha256:[a-f0-9]{64}$'::text))
);


--
-- Name: TABLE tour_share_grant; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.tour_share_grant IS 'Stores opaque-token digests and scope/version/rotation lineage; never plaintext tokens.';


--
-- Name: tour_share_session_grant(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_share_session_grant(p_session_digest text, p_scope text) RETURNS ops.tour_share_grant
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
  select g from ops.tour_share_session s join ops.tour_share_grant g on g.id=s.share_grant_id and g.organization_tenant_id=s.organization_tenant_id
  where s.session_digest=p_session_digest and s.expires_at>now() and s.permission_scopes ? p_scope and g.expires_at>now()
    and not exists(select 1 from ops.tour_share_grant_revocation_receipt r where r.organization_tenant_id=g.organization_tenant_id and r.share_grant_id=g.id)
    and not exists(select 1 from ops.tour_share_grant successor where successor.organization_tenant_id=g.organization_tenant_id and successor.rotated_from_grant_id=g.id)
  limit 1;
$$;


--
-- Name: tour_slice3_alias_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_slice3_alias_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from ops.tour_property_identifier_assertion i where i.id=new.identifier_assertion_id and i.organization_tenant_id=new.organization_tenant_id and i.property_id=new.property_id) then raise exception 'identifier alias does not match canonical property identity'; end if;
  perform ops.tour_slice3_rights_guard(new.organization_tenant_id,new.source_evidence_id,new.rights_receipt_id,new.observed_at,'canonical_fact');
  return new;
end $$;


