--
-- Name: tour_slice3_rights_guard(text, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_slice3_rights_guard(p_tenant text, p_evidence_id uuid, p_rights_id uuid, p_at timestamp with time zone, p_use_class text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
declare v_provider text; v_policy_key text;
begin
  select rights_provider,rights_policy_key into v_provider,v_policy_key
    from ops.tour_source_evidence where id=p_evidence_id and organization_tenant_id=p_tenant;
  if not found or v_provider is null or v_policy_key is null then
    raise exception 'Tour Slice 3 requires exact evidence rights lineage';
  end if;
  perform ops.tour_rights_provider_policy_lock(p_tenant,v_provider,v_policy_key);
  if not exists (
    select 1 from ops.tour_rights_receipt r
     where r.id=p_rights_id and r.organization_tenant_id=p_tenant
       and r.id=(select e.rights_receipt_id from ops.tour_source_evidence e where e.id=p_evidence_id and e.organization_tenant_id=p_tenant)
       and r.provider=v_provider and r.policy_key=v_policy_key and r.status='active'
       and r.effective_at<=p_at and (r.expires_at is null or r.expires_at>p_at) and r.revoked_at is null
       and r.allowed_use_classes ? p_use_class
       and not exists (select 1 from ops.tour_rights_receipt newer where newer.organization_tenant_id=r.organization_tenant_id and newer.provider=r.provider and newer.policy_key=r.policy_key and newer.receipt_version>r.receipt_version and newer.effective_at<=p_at)
  ) then raise exception 'Tour Slice 3 rights receipt refuses evidence use'; end if;
end $$;


--
-- Name: tour_source_rights_guard(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.tour_source_rights_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'public', 'pg_temp'
    AS $$
begin
  if new.rights_provider is null or new.rights_policy_key is null then
    raise exception 'source evidence requires exact rights provider and policy lineage';
  end if;
  perform ops.tour_rights_provider_policy_lock(new.organization_tenant_id,new.rights_provider,new.rights_policy_key);
  if not exists (
    select 1 from ops.tour_rights_receipt r
     where r.id=new.rights_receipt_id and r.organization_tenant_id=new.organization_tenant_id
       and r.provider=new.rights_provider and r.policy_key=new.rights_policy_key
       and r.status='active' and r.effective_at <= new.retrieved_at
       and (r.expires_at is null or r.expires_at > new.retrieved_at) and r.revoked_at is null
       and r.allowed_use_classes ? 'source_intake'
       and not exists (
         select 1 from ops.tour_rights_receipt newer
          where newer.organization_tenant_id=r.organization_tenant_id
            and newer.provider=r.provider and newer.policy_key=r.policy_key
            and newer.receipt_version > r.receipt_version and newer.effective_at <= new.retrieved_at
       )
  ) then
    raise exception 'rights receipt refuses source intake';
  end if;
  return new;
end $$;


--
-- Name: transition_execution_environment_provider(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.transition_execution_environment_provider(p_provider_ref text, p_expected_state text, p_target_state text, p_evidence_refs jsonb, p_idempotency_key uuid) RETURNS TABLE(provider_ref text, state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare actor_row actor%rowtype; provider ops.execution_environment_provider%rowtype; current_state text; existing ops.execution_environment_provider_event%rowtype;
begin
  if session_user !~ '^carr_authority_' then raise exception 'environment provider transition requires human authority'; end if;
  select * into actor_row from actor where slug=regexp_replace(session_user,'^carr_authority_','') and kind='human' and active;
  -- The immutable provider row is the lifecycle stream's serialization head.
  -- The second concurrent CAS caller cannot inspect state until the first
  -- commits, so it must then fail the expected-state comparison below.
  select * into provider from ops.execution_environment_provider p where p_provider_ref='environment-provider:'||p.provider_key||':v'||p.provider_version for update;
  if actor_row.id is null or provider.id is null or jsonb_typeof(p_evidence_refs)<>'array' or jsonb_array_length(p_evidence_refs)=0
     or exists(select 1 from jsonb_array_elements_text(p_evidence_refs) value where value !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$') then
    raise exception 'environment provider transition lacks valid authority, provider, or evidence';
  end if;
  select * into existing from ops.execution_environment_provider_event where idempotency_key=p_idempotency_key for share;
  if found then
    if existing.provider_id<>provider.id or existing.from_state is distinct from p_expected_state or existing.to_state<>p_target_state or existing.evidence_refs is distinct from p_evidence_refs then raise exception 'environment provider transition idempotency conflict'; end if;
    return query select p_provider_ref,existing.to_state,true; return;
  end if;
  current_state := ops.execution_environment_provider_current_state(provider.id);
  if current_state is distinct from p_expected_state
     or not ((p_expected_state='discovered' and p_target_state='quarantined')
       or (p_expected_state='quarantined' and p_target_state='conformance_passed')
       or (p_expected_state='conformance_passed' and p_target_state='shadow')
       or (p_expected_state='shadow' and p_target_state='canary')
       or (p_expected_state='canary' and p_target_state='active')
       or (p_expected_state='active' and p_target_state='disabled')
       or (p_expected_state='disabled' and p_target_state='canary')
       or (p_expected_state<>'retired' and p_target_state='retired')) then
    raise exception 'environment provider transition is stale or forbidden';
  end if;
  if p_target_state in ('conformance_passed','shadow','canary','active') and coalesce((
    select c.status from ops.execution_environment_conformance c where c.provider_id=provider.id order by c.observed_at desc,c.id desc limit 1),'unavailable')<>'passed' then
    raise exception 'environment provider cannot advance without passed conformance';
  end if;
  insert into ops.execution_environment_provider_event(provider_id,from_state,to_state,evidence_refs,ruled_by_actor_id,idempotency_key)
  values(provider.id,p_expected_state,p_target_state,p_evidence_refs,actor_row.id,p_idempotency_key);
  return query select p_provider_ref,p_target_state,false;
end $_$;


--
-- Name: transition_proposed_eval_candidate(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.transition_proposed_eval_candidate(p_work_request text, p_candidate_ref text, p_next_state text, p_decision_basis jsonb, p_idempotency_key uuid) RETURNS TABLE(candidate_id uuid, lifecycle text, golden_member boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $$
declare tenant text := current_setting('carr.organization_tenant_id', true); candidate ops.proposed_eval_candidate%rowtype; actor_row actor%rowtype;
  current_state text; replay_event ops.proposed_eval_candidate_event%rowtype; v_actor_slug text;
begin
  if session_user ~ '^carr_authority_' then
    v_actor_slug := regexp_replace(session_user,'^carr_authority_','');
  elsif session_user = 'carr_writer' then
    v_actor_slug := nullif(btrim(current_setting('carr.acting_actor_slug', true)), '');
  else
    raise exception 'eval candidate transition requires the authority connection or a sponsored writer session';
  end if;
  select * into actor_row from actor where slug=v_actor_slug and kind in ('human','automation') and active;
  select p.* into candidate from ops.proposed_eval_candidate p join ops.attempt_receipt r on r.id=p.attempt_receipt_id join ops.work_request w on w.id=r.work_request_id
   where p.organization_tenant_id=tenant and p.candidate_ref=p_candidate_ref and w.ref=p_work_request and w.organization_tenant_id=tenant for update of p;
  if actor_row.id is null or candidate.id is null or jsonb_typeof(p_decision_basis)<>'object' then raise exception 'eval candidate transition lacks visible authority/candidate/basis'; end if;
  if ops.attempt_receipt_contains_raw_content(p_decision_basis) then raise exception 'eval candidate decision basis must be metadata-only'; end if;
  select * into replay_event from ops.proposed_eval_candidate_event where idempotency_key=p_idempotency_key for share;
  if found then
    if replay_event.candidate_id<>candidate.id or replay_event.event_kind<>p_next_state or replay_event.decision_basis is distinct from p_decision_basis then raise exception 'eval candidate transition idempotency conflict'; end if;
    select pe.event_kind into current_state from ops.proposed_eval_candidate_event pe where pe.candidate_id=candidate.id order by pe.created_at desc,pe.id desc limit 1;
    return query select candidate.id,current_state,current_state='accepted'; return;
  end if;
  select pe.event_kind into current_state from ops.proposed_eval_candidate_event pe where pe.candidate_id=candidate.id order by pe.created_at desc,pe.id desc limit 1;
  if p_next_state not in ('triaged','accepted','retired')
     or (current_state='proposed' and p_next_state<>'triaged')
     or (current_state='triaged' and p_next_state<>'accepted')
     or (current_state='accepted' and p_next_state<>'retired')
     or current_state not in ('proposed','triaged','accepted') then
    raise exception 'invalid append-only eval candidate lifecycle transition';
  end if;
  insert into ops.proposed_eval_candidate_event(candidate_id,event_kind,decided_by_actor_id,decision_basis,idempotency_key)
  values(candidate.id,p_next_state,actor_row.id,p_decision_basis,p_idempotency_key);
  if p_next_state='accepted' then
    insert into ops.accepted_eval_golden_membership(candidate_id,target_golden_set_ref,accepted_by_actor_id)
    values(candidate.id,candidate.target_golden_set_ref,actor_row.id);
  end if;
  return query select candidate.id,p_next_state,(p_next_state='accepted');
end $$;


--
-- Name: triage_sourced_work_request(text, integer, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.triage_sourced_work_request(p_work_request text, p_base_version integer, p_classification text, p_idempotency_key uuid) RETURNS TABLE(id uuid, ref text, state text, version integer, classification text, triaged_by_actor_slug text, triaged_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
declare
  v_actor_slug text;
  v_actor public.actor%rowtype;
  v_work_request ops.work_request%rowtype;
  v_receipt ops.work_request_triage_receipt%rowtype;
begin
  if coalesce(btrim(p_work_request), '') !~ '^WR-[0-9]{1,12}$'
     or p_base_version is null or p_base_version < 1
     or p_classification is null
     or p_classification not in ('operational','needs_judgment','safety_review')
     or p_idempotency_key is null then
    raise exception 'human triage requires a Work Request ref, exact positive base version, closed classification, and UUID idempotency key';
  end if;

  v_actor_slug := ops.authority_actor_slug();
  select a.* into v_actor from public.actor a
   where a.slug = v_actor_slug and a.active and a.kind = 'human'
   for share;
  if not found then
    raise exception 'authority session user is not an active human actor';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('program6-human-triage:' || p_idempotency_key, 0));
  select r.* into v_receipt from ops.work_request_triage_receipt r
   where r.idempotency_key = p_idempotency_key
   for share;
  if found then
    select w.* into v_work_request from ops.work_request w where w.id = v_receipt.work_request_id for share;
    if not found
       or v_receipt.base_version is distinct from p_base_version
       or v_receipt.classification is distinct from p_classification
       or v_receipt.triaged_by_actor_id is distinct from v_actor.id
       or v_work_request.ref is distinct from p_work_request
       or v_work_request.state is distinct from 'triaged'
       or v_work_request.version is distinct from v_receipt.result_version then
      raise exception 'idempotency key already names a different human triage';
    end if;
    return query select v_work_request.id, v_work_request.ref, v_work_request.state,
      v_work_request.version, v_receipt.classification, v_actor.slug, v_receipt.triaged_at, true;
    return;
  end if;

  select w.* into v_work_request from ops.work_request w
   where w.ref = p_work_request
   for update;
  if not found
     or v_work_request.capture_idempotency_key is null
     or v_work_request.organization_tenant_id is distinct from 'carr-internal'
     or v_work_request.state is distinct from 'captured'
     or v_work_request.version is distinct from p_base_version
     or v_work_request.program_key is not null or v_work_request.program_ordinal is not null then
    raise exception 'only the exact current captured sourced Work Request may be triaged';
  end if;

  insert into ops.work_request_triage_receipt
    (work_request_id,idempotency_key,base_version,classification,triaged_by_actor_id,result_version)
  values
    (v_work_request.id,p_idempotency_key,p_base_version,p_classification,v_actor.id,v_work_request.version + 1)
  returning * into v_receipt;

  update ops.work_request w
     set state = 'triaged',
         triage_classification = p_classification,
         triaged_by_actor_id = v_actor.id,
         triaged_at = v_receipt.triaged_at,
         version = v_receipt.result_version,
         updated_at = now()
   where w.id = v_work_request.id;
  select w.* into v_work_request from ops.work_request w where w.id = v_work_request.id;
  return query select v_work_request.id, v_work_request.ref, v_work_request.state,
    v_work_request.version, v_receipt.classification, v_actor.slug, v_receipt.triaged_at, false;
end;
$_$;


--
-- Name: FUNCTION triage_sourced_work_request(p_work_request text, p_base_version integer, p_classification text, p_idempotency_key uuid); Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON FUNCTION ops.triage_sourced_work_request(p_work_request text, p_base_version integer, p_classification text, p_idempotency_key uuid) IS 'Human-only Program 6 review. The reviewer is derived from session_user through authority_actor_slug(); no caller actor, tenant, state, assignment, dispatch, approval, or execution field is accepted.';


--
-- Name: validate_attempt_environment_evidence(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_attempt_environment_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare runtime jsonb; evidence jsonb; allowed text[] := array['binding_digest','session_ref','lease_state','operation_count','policy_refusal_refs','security_event_refs','cleanup_state','cleanup_evidence_refs','side_effect_state','resource_usage','evidence_refs'];
begin
  select e.runtime_profile into runtime from ops.execution_envelope_v1 e where e.id=new.execution_envelope_id;
  if runtime ? 'environment_binding_digest' then
    evidence := new.receipt->'reliability'->'environment_evidence';
    if new.receipt->'reliability'->>'environment_binding_digest' is distinct from runtime->>'environment_binding_digest'
       or jsonb_typeof(evidence)<>'object' or not (evidence ?& allowed)
       or exists(select 1 from jsonb_object_keys(evidence) k where k<>all(allowed))
       or evidence->>'binding_digest' is distinct from runtime->>'environment_binding_digest'
       or evidence->>'session_ref' !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'
       or evidence->>'lease_state' not in ('active','released','expired','failed','unknown')
       or jsonb_typeof(evidence->'operation_count')<>'number' or evidence->>'operation_count' !~ '^[0-9]+$'
       or evidence->>'cleanup_state' not in ('not_required','pending','verified','failed','unknown')
       or evidence->>'side_effect_state' not in ('none','attempted','refused','observed','unknown')
       or exists(select 1 from unnest(array['policy_refusal_refs','security_event_refs','cleanup_evidence_refs','evidence_refs']) field
         where jsonb_typeof(evidence->field)<>'array' or exists(select 1 from jsonb_array_elements_text(evidence->field) value where value !~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'))
       or jsonb_typeof(evidence->'evidence_refs')<>'array' or jsonb_array_length(evidence->'evidence_refs')=0
       or (evidence->>'cleanup_state' in ('verified','failed') and (jsonb_typeof(evidence->'cleanup_evidence_refs')<>'array' or jsonb_array_length(evidence->'cleanup_evidence_refs')=0))
       or jsonb_typeof(evidence->'resource_usage')<>'object'
       or not (evidence->'resource_usage' ?& array['cpu_ms','memory_peak_mb','disk_peak_mb','network_egress_bytes'])
       or exists(select 1 from jsonb_object_keys(evidence->'resource_usage') key where key<>all(array['cpu_ms','memory_peak_mb','disk_peak_mb','network_egress_bytes']))
       or exists(select 1 from jsonb_each(evidence->'resource_usage') metric where jsonb_typeof(metric.value)<>'number' or metric.value#>>'{}' !~ '^[0-9]+$') then
      raise exception 'AttemptReceipt environment evidence does not bind the issued provider and cleanup contract';
    end if;
  elsif new.receipt->'reliability' ?| array['environment_binding_digest','environment_evidence'] then
    raise exception 'legacy ExecutionEnvelope cannot accept execution environment evidence';
  end if;
  return new;
end $_$;


--
-- Name: validate_guidance_authority_binding(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_guidance_authority_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  receipt_subject uuid;
  receipt_type text;
  receipt_hash text;
  receipt_decision text;
  receipt_actor_kind text;
  item_id uuid;
begin
  select ar.subject_id,ar.subject_type,ar.contract_hash,ar.decision,a.kind
    into receipt_subject,receipt_type,receipt_hash,receipt_decision,receipt_actor_kind
    from ops.authority_receipt ar join actor a on a.id=ar.actor_id
   where ar.id=new.authority_receipt_id
     and ar.kind in ('activation','amendment','rejection');
  select guidance_item_id into item_id
    from ops.guidance_revision where id=new.guidance_revision_id;
  if receipt_type <> 'guidance' or receipt_subject <> item_id then
    raise exception 'authority receipt must name the exact guidance item';
  end if;
  if receipt_actor_kind is distinct from 'human'
     or receipt_decision not in ('approved','retired','superseded') then
    raise exception 'guidance authority binding requires an explicit human decision';
  end if;
  if receipt_hash is distinct from new.contract_hash then
    raise exception 'authority receipt hash does not match the exact guidance revision contract';
  end if;
  if new.contract_hash is distinct from
       ops.guidance_revision_contract_hash(new.guidance_revision_id) then
    raise exception 'authority binding hash does not match the exact stored guidance revision';
  end if;
  return new;
end $$;


--
-- Name: validate_guidance_import_manifest(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_guidance_import_manifest(p_manifest jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'ops', 'public', 'pg_temp'
    AS $_$
declare
  v_entry jsonb;
  v_position integer := 0;
  v_previous_key text := null;
  v_constitution_ids text[];
  v_entry_constitution_ids text[];
  v_constitution_source_ids text[];
  v_entry_constitution_source_ids text[];
  v_short text;
  v_uuid text;
begin
  if jsonb_typeof(p_manifest) <> 'object'
     or p_manifest->>'schema' <> 'guidance-activation-manifest/v1'
     or jsonb_typeof(p_manifest->'source_manifest') <> 'object'
     or coalesce(p_manifest->'source_manifest'->>'sha256','') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_manifest->'base_inventory') <> 'object'
     or jsonb_typeof(p_manifest->'base_inventory'->'active_source_ids') <> 'array'
     or jsonb_typeof(p_manifest->'base_inventory'->'source_rule_ids') <> 'object'
     or jsonb_typeof(p_manifest->'constitution_guidance_ids') <> 'array'
     or jsonb_typeof(p_manifest->'constitution_source_rule_ids') <> 'array'
     or jsonb_typeof(p_manifest->'entries') <> 'array'
     or jsonb_array_length(p_manifest->'entries') = 0 then
    raise exception 'guidance import manifest has an invalid top-level contract';
  end if;
  if coalesce(p_manifest->'source_manifest'->>'path','') = ''
     or p_manifest->'source_manifest'->>'manifest' <> 'carr-guidance-migration'
     or p_manifest->'source_manifest'->>'schema_version' <> '1.0.0'
     or p_manifest->'source_manifest'->>'source_classification' <> 'judgment_ambient'
     or coalesce((p_manifest->'source_manifest'->>'entry_count')::integer,0) < 1
     or coalesce(p_manifest->'base_inventory'->>'path','') = ''
     or coalesce(p_manifest->'base_inventory'->>'sha256','') !~ '^[0-9a-f]{64}$'
     or coalesce((p_manifest->'base_inventory'->>'active_source_count')::integer,0) < 1 then
    raise exception 'guidance import manifest provenance or inventory contract is incomplete';
  end if;
  if (p_manifest->'base_inventory'->>'active_source_count')::integer
       <> (select count(*) from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids')) then
    raise exception 'guidance import manifest active source count does not match its inventory';
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids') id
     where id.value !~ '^[0-9a-f]{8}$'
  ) then
    raise exception 'guidance import manifest base inventory must contain short source ids';
  end if;
  if (select count(*) from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids'))
     <> (select count(distinct value) from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids')) then
    raise exception 'guidance import manifest base inventory has duplicate source ids';
  end if;
  for v_short,v_uuid in select key,value from jsonb_each_text(p_manifest->'base_inventory'->'source_rule_ids') loop
    if v_short !~ '^[0-9a-f]{8}$'
       or v_uuid !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or v_short <> left(v_uuid,8) then
      raise exception 'guidance import manifest source_rule_ids must map each short id to its matching full UUID';
    end if;
  end loop;
  if (select count(*) from jsonb_object_keys(p_manifest->'base_inventory'->'source_rule_ids'))
       <> (select count(distinct value) from jsonb_each_text(p_manifest->'base_inventory'->'source_rule_ids')) then
    raise exception 'guidance import manifest source_rule_ids has duplicate UUID values';
  end if;
  if exists (
    (select value from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids'))
    except
    (select source_key.key from jsonb_object_keys(p_manifest->'base_inventory'->'source_rule_ids') as source_key(key))
  ) or exists (
    (select source_key.key from jsonb_object_keys(p_manifest->'base_inventory'->'source_rule_ids') as source_key(key))
    except
    (select value from jsonb_array_elements_text(p_manifest->'base_inventory'->'active_source_ids'))
  ) then
    raise exception 'guidance import manifest short source inventory and UUID map differ';
  end if;
  for v_entry in select value from jsonb_array_elements(p_manifest->'entries') loop
    v_position := v_position + 1;
    if jsonb_typeof(v_entry) <> 'object'
       or coalesce((v_entry->>'ordinal')::integer,0) <> v_position
       or coalesce(v_entry->>'guidance_id','') = ''
       or coalesce(v_entry->>'source_rule_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v_entry->>'source_clause','') = ''
       or jsonb_typeof(v_entry->'is_primary') <> 'boolean'
       or coalesce(v_entry->>'guidance_type','') not in
          ('constraint','procedure','doctrine','rubric','preference','precedent','example')
       or jsonb_typeof(v_entry->'scope') <> 'object'
       or jsonb_typeof(v_entry->'activation') <> 'object'
       or coalesce(v_entry->>'consumer','') = ''
       or jsonb_typeof(v_entry->'verification') <> 'object'
       or jsonb_typeof(v_entry->'provenance') <> 'object'
       or jsonb_typeof(v_entry->'delivery') <> 'object'
       or jsonb_typeof(v_entry->'is_constitution') <> 'boolean'
       or coalesce((v_entry->'lifecycle'->>'version')::integer,0) <> 1
       or coalesce(v_entry->>'reason','') = ''
       or jsonb_typeof(coalesce(v_entry->'activation'->'situation_mappings','[]'::jsonb)) <> 'array' then
      raise exception 'guidance import entry % has an invalid contract',v_position;
    end if;
    if v_previous_key is not null and v_entry->>'guidance_id' <= v_previous_key then
      raise exception 'guidance import entries must be strictly sorted by guidance_id';
    end if;
    v_previous_key := v_entry->>'guidance_id';
    if not exists (
      select 1 from jsonb_each_text(p_manifest->'base_inventory'->'source_rule_ids') source_map
       where source_map.value=(v_entry->>'source_rule_id')) then
      raise exception 'guidance import entry % names a source outside base inventory',v_position;
    end if;
    if exists (
      select 1 from jsonb_array_elements(coalesce(v_entry->'activation'->'situation_mappings','[]'::jsonb)) mapping
       where jsonb_typeof(mapping.value) <> 'object'
          or coalesce(mapping.value->>'concept_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or coalesce(mapping.value->>'doctrine_section_id','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          or coalesce(mapping.value->>'reason','') = '') then
      raise exception 'guidance import entry % has an unresolved doctrine mapping contract',v_position;
    end if;
    if v_entry->>'guidance_type' = 'doctrine'
       and jsonb_array_length(coalesce(v_entry->'activation'->'situation_mappings','[]'::jsonb)) = 0 then
      raise exception 'doctrine guidance requires exact situation mappings';
    end if;
    if (v_entry->>'is_constitution')::boolean
       and not (v_entry->>'is_primary')::boolean then
      raise exception 'constitution guidance must be a primary source clause';
    end if;
    if v_entry->>'guidance_type' <> 'doctrine'
       and jsonb_array_length(coalesce(v_entry->'activation'->'situation_mappings','[]'::jsonb)) <> 0 then
      raise exception 'only doctrine guidance may name situation mappings';
    end if;
  end loop;
  if (select count(distinct entry.value->>'guidance_id')
        from jsonb_array_elements(p_manifest->'entries') entry)
       <> jsonb_array_length(p_manifest->'entries') then
    raise exception 'guidance import manifest has duplicate entry keys';
  end if;
  if exists (
    (select value from jsonb_each_text(p_manifest->'base_inventory'->'source_rule_ids'))
    except
    (select distinct entry.value->>'source_rule_id' from jsonb_array_elements(p_manifest->'entries') entry)
  ) or exists (
    (select distinct entry.value->>'source_rule_id' from jsonb_array_elements(p_manifest->'entries') entry)
    except
    (select value from jsonb_each_text(p_manifest->'base_inventory'->'source_rule_ids'))
  ) then
    raise exception 'guidance import manifest entries do not exactly cover base inventory';
  end if;
  select array_agg(value order by value) into v_constitution_ids
    from jsonb_array_elements_text(p_manifest->'constitution_guidance_ids');
  select array_agg(entry.value->>'guidance_id' order by entry.value->>'guidance_id')
    into v_entry_constitution_ids
    from jsonb_array_elements(p_manifest->'entries') entry
   where (entry.value->>'is_constitution')::boolean;
  select array_agg(value order by value) into v_constitution_source_ids
    from jsonb_array_elements_text(p_manifest->'constitution_source_rule_ids');
  select array_agg(distinct entry.value->>'source_rule_id' order by entry.value->>'source_rule_id')
    into v_entry_constitution_source_ids
    from jsonb_array_elements(p_manifest->'entries') entry
   where (entry.value->>'is_constitution')::boolean and (entry.value->>'is_primary')::boolean;
  if v_constitution_ids is null or cardinality(v_constitution_ids) not between 5 and 10
     or v_constitution_ids is distinct from v_entry_constitution_ids then
    raise exception 'guidance import manifest must bind exactly five to ten selected constitution guidance ids';
  end if;
  if v_constitution_source_ids is null or cardinality(v_constitution_source_ids) not between 5 and 10
     or v_constitution_source_ids is distinct from v_entry_constitution_source_ids then
    raise exception 'guidance import manifest constitution source ids do not exactly match flagged primary entries';
  end if;
end $_$;


--
-- Name: validate_guidance_lifecycle_event(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_guidance_lifecycle_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  bound_revision uuid;
  receipt_decision text;
begin
  select b.guidance_revision_id,ar.decision
    into bound_revision,receipt_decision
    from ops.guidance_authority_binding b
    join ops.authority_receipt ar on ar.id=b.authority_receipt_id
   where b.id=new.authority_binding_id;
  if bound_revision is distinct from new.guidance_revision_id then
    raise exception 'lifecycle event authority must bind the exact guidance revision';
  end if;
  if (new.state='active' and receipt_decision <> 'approved')
     or (new.state='retired' and receipt_decision <> 'retired')
     or (new.state='superseded' and receipt_decision <> 'superseded') then
    raise exception 'lifecycle state % does not match authority decision %',
      new.state,receipt_decision;
  end if;
  return new;
end $$;


--
-- Name: validate_guidance_revision(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_guidance_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  expected_projection text;
  prior_item uuid;
  prior_version integer;
  installed_evidence boolean;
begin
  if jsonb_typeof(new.scope) <> 'object'
     or coalesce(btrim(new.scope->>'tenant'),'') = ''
     or coalesce(btrim(new.scope->>'actor'),'') = '' then
    raise exception 'guidance revision requires tenant and actor scope';
  end if;
  if jsonb_typeof(new.activation) <> 'object'
     or coalesce(btrim(new.activation->>'trigger'),'') = '' then
    raise exception 'guidance revision requires an activation trigger';
  end if;
  if jsonb_typeof(new.verification) <> 'object'
     or coalesce(btrim(new.verification->>'mechanism'),'') = '' then
    raise exception 'guidance revision requires a verification mechanism';
  end if;
  if jsonb_typeof(new.provenance) <> 'object'
     or new.provenance->>'preserve_source_record' <> 'true' then
    raise exception 'guidance revision must preserve source provenance';
  end if;
  if jsonb_typeof(new.delivery) <> 'object' then
    raise exception 'guidance revision requires a delivery contract';
  end if;
  -- Constitution feeds standing_guidance and precedent feeds the precedent
  -- projection, both of which resolve the canonical rule record.  Intake-only
  -- items remain useful for other typed guidance, but they must not be able to
  -- enter either of these rule-backed read paths (or activation's constitution
  -- count) and then disappear at retrieval time.
  if new.is_constitution or new.guidance_type='precedent' then
    if not exists (
      select 1 from ops.guidance_item i
       where i.id=new.guidance_item_id
         and i.source_rule_id is not null
    ) then
      raise exception 'constitution and precedent revisions require a source_rule_id';
    end if;
  end if;
  expected_projection := case new.guidance_type
    when 'constraint' then 'constraint_enforcement'
    when 'procedure' then 'procedure_workflow'
    when 'doctrine' then 'doctrine_retrieval'
    when 'rubric' then 'verification_rubric'
    when 'preference' then 'scoped_preference'
    when 'precedent' then 'precedent_search'
    when 'example' then 'example_retrieval'
  end;
  if new.delivery->>'projection' is distinct from expected_projection then
    raise exception 'guidance type % requires delivery projection %',
      new.guidance_type, expected_projection;
  end if;
  if new.guidance_type='constraint' and (
       coalesce(btrim(new.delivery->>'enforcement_control'),'') = ''
       or jsonb_typeof(new.delivery->'evidence') <> 'array'
       or jsonb_array_length(new.delivery->'evidence') = 0
       or jsonb_typeof(new.delivery->'tests') <> 'array'
       or jsonb_array_length(new.delivery->'tests') = 0) then
    raise exception 'constraint requires installed enforcement evidence and tests';
  elsif new.guidance_type='procedure' and (
       coalesce(btrim(new.activation->>'entry_condition'),'') = ''
       or coalesce(btrim(new.verification->>'completion_condition'),'') = '') then
    raise exception 'procedure requires entry and completion conditions';
  elsif new.guidance_type='doctrine' and (
       jsonb_typeof(new.activation->'situation_mappings') <> 'array'
       or jsonb_array_length(new.activation->'situation_mappings') = 0) then
    raise exception 'doctrine requires situation mappings';
  elsif new.guidance_type='rubric' and (
       coalesce(btrim(new.verification->>'verifier'),'') = ''
       or jsonb_typeof(new.verification->'acceptance_criteria') <> 'array'
       or jsonb_array_length(new.verification->'acceptance_criteria') = 0) then
    raise exception 'rubric requires verifier and acceptance criteria';
  elsif new.guidance_type='preference'
        and new.scope->>'actor' in ('','all') then
    raise exception 'preference requires a scoped actor';
  end if;
  if new.guidance_type='constraint' then
    select exists (
      select 1
        from ops.guidance_item i
        join ops.rule_enforcement_point ep
          on ep.rule_id=i.source_rule_id
         and ep.control_key=new.delivery->>'enforcement_control'
         and ep.installed
       where i.id=new.guidance_item_id
         and new.delivery->'evidence' ? ep.implementation_ref
         and new.delivery->'tests' ? ep.test_ref
    ) into installed_evidence;
    if not installed_evidence then
      raise exception 'constraint revision requires an installed enforcement point with exact implementation and test evidence';
    end if;
  end if;
  select max(version) into prior_version
    from ops.guidance_revision where guidance_item_id=new.guidance_item_id;
  if new.version <> coalesce(prior_version,0)+1 then
    raise exception 'guidance revision version must be the next append-only version';
  end if;
  if new.supersedes_revision_id is not null then
    select guidance_item_id into prior_item
      from ops.guidance_revision where id=new.supersedes_revision_id;
    if prior_item is distinct from new.guidance_item_id then
      raise exception 'a revision may supersede only a revision of the same guidance item';
    end if;
  end if;
  return new;
end $$;


--
-- Name: validate_guidance_situation_mapping(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_guidance_situation_mapping() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  bound_revision uuid;
  receipt_decision text;
  revision_type text;
begin
  if new.state='active' then
    select b.guidance_revision_id,ar.decision,r.guidance_type
      into bound_revision,receipt_decision,revision_type
      from ops.guidance_authority_binding b
      join ops.authority_receipt ar on ar.id=b.authority_receipt_id
      join ops.guidance_revision r on r.id=b.guidance_revision_id
     where b.id=new.authority_binding_id;
    if bound_revision is distinct from new.guidance_revision_id
       or receipt_decision <> 'approved'
       or revision_type <> 'doctrine' then
      raise exception 'active situation mapping requires approved human authority for the exact doctrine revision';
    end if;
  end if;
  return new;
end $$;


--
-- Name: validate_recovery_rehearsal_run(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_recovery_rehearsal_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare b ops.staging_recovery_rehearsal_bundle%rowtype; expected_started timestamptz;
begin
  if new.run_key like 'recovery.rehearsal.%' and new.state='succeeded'
     and new.recovery_rehearsal_bundle_id is null then
    raise exception 'successful recovery rehearsal run requires a typed bundle';
  end if;
  if new.recovery_rehearsal_bundle_id is null then return new; end if;
  select * into strict b from ops.staging_recovery_rehearsal_bundle where id=new.recovery_rehearsal_bundle_id;
  expected_started:=case when b.recovery_strategy='rollback' then
    (select observed_at from ops.staging_release_readback_receipt where id=b.current_before_receipt_id)
    else (select observed_at from ops.staging_forward_fix_rehearsal_result where id=b.forward_fix_result_id) end;
  if new.kind<>'check' or new.run_key<>(case when b.recovery_strategy='rollback' then 'recovery.rehearsal.worker' else 'recovery.rehearsal.forward-fix' end)
     or new.state<>'succeeded' or new.environment<>'staging' or new.release_id<>b.current_release_id
     or new.service_id<>b.service_id or new.correlation_id<>b.correlation_id
     or new.recovery_strategy<>b.recovery_strategy or new.recovery_plan_ref<>b.recovery_plan_ref
     or new.evidence_ref<>b.evidence_ref or new.started_at is distinct from expected_started
     or new.ended_at is distinct from b.completed_at then
    raise exception 'recovery rehearsal run does not exactly match its typed bundle';
  end if;
  return new;
end $$;


--
-- Name: validate_rule_load_layer_packs(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_rule_load_layer_packs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare missing text;
begin
  select string_agg(p, ', ') into missing
    from unnest(new.packs) p
   where not exists (select 1 from ops.rule_pack rp where rp.pack = p);
  if missing is not null then
    raise exception 'rule % names undefined pack(s): %', new.short_id, missing;
  end if;
  return new;
end $$;


--
-- Name: work_request_card(text, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.work_request_card(p_work_request text, p_organization_tenant_id text) RETURNS TABLE(ref text, title text, state text, version integer, origin_ref text, desired_outcome text, acceptance_criteria jsonb, doctrine_section_id uuid, doctrine_revision_id uuid, doctrine_source_label text, source_current boolean, triage_classification text, triaged_by_actor_slug text, triaged_at timestamp with time zone, plan_ref text, plan_hash text, scope_summary text, runbook_ref text, runbook_revision_id uuid, runbook_content_hash text, plan_caps jsonb, dependency_refs jsonb, recovery_ref text, observability_ref text, accepted_by_actor_slug text, accepted_at timestamp with time zone, shape_disposition text, shape_fixed_surface_ref text, outcome_feedback jsonb, outcome_feedback_history jsonb, accepted_feedback_count bigint, exit_reason text, closed_at timestamp with time zone, superseded_by_ref text, incident_evidence jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
  select w.ref,w.title,w.state,w.version,w.origin_ref,w.desired_outcome,
         w.acceptance_criteria,w.doctrine_section_id,w.doctrine_revision_id,
         coalesce(s.title,s.section_key),
         (s.status='active' and s.current_revision_id=w.doctrine_revision_id),
         w.triage_classification,ta.slug,w.triaged_at,
         p.plan_ref,p.plan_hash,p.scope_summary,p.runbook_ref,p.runbook_revision_id,
         case when p.runbook_content_hash is null then null else 'sha256:' || p.runbook_content_hash end,
         p.caps,p.dependency_refs,p.recovery_ref,p.observability_ref,aa.slug,ar.accepted_at,
         w.shape_disposition,w.shape_fixed_surface_ref,
         latest.feedback,coalesce(history.feedback_history,'[]'::jsonb),coalesce(counted.accepted_count,0),
         w.exit_reason,w.closed_at,succ.ref,coalesce(incident_evidence.items,'[]'::jsonb)
    from ops.work_request w
    join public.doctrine_section s on s.id=w.doctrine_section_id
    join public.doctrine_document d on d.id=s.document_id
    left join public.actor ta on ta.id=w.triaged_by_actor_id
    left join ops.work_request succ on succ.id=w.superseded_by
    left join lateral (
      select x.* from ops.sourced_work_request_plan x
      left join ops.sourced_work_request_plan_acceptance_receipt accepted on accepted.plan_id=x.id
       where x.work_request_id=w.id
       order by (accepted.id is not null) desc,x.plan_version desc limit 1
    ) p on true
    left join ops.sourced_work_request_plan_acceptance_receipt ar on ar.plan_id=p.id
    left join public.actor aa on aa.id=ar.accepted_by_actor_id
    left join lateral (
      select jsonb_build_object(
        'feedback_ref',f.feedback_ref,'feedback_hash',f.feedback_hash,'outcome',f.outcome,
        'criterion_results',f.criterion_results,'evidence_refs',f.evidence_refs,
        'blocker_code',f.blocker_code,'result_summary',f.result_summary,
        'observed_minutes',f.observed_minutes,'interaction_surface',f.interaction_surface,
        'heavy_session_used',f.heavy_session_used,'manual_context_transfers',f.manual_context_transfers,
        'accepted_by_actor_slug',fa.slug,'accepted_at',fr.accepted_at) as feedback
        from ops.sourced_work_request_outcome_feedback f
        join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
        join public.actor fa on fa.id=fr.accepted_by_actor_id
       where f.work_request_id=w.id
       order by fr.accepted_at desc,fr.id desc limit 1
    ) latest on true
    left join lateral (
      select jsonb_agg(h.feedback order by h.accepted_at,h.acceptance_id) as feedback_history
        from (
          select fr.accepted_at,fr.id as acceptance_id,jsonb_build_object(
            'feedback_ref',f.feedback_ref,'feedback_hash',f.feedback_hash,'outcome',f.outcome,
            'criterion_results',f.criterion_results,'evidence_refs',f.evidence_refs,
            'blocker_code',f.blocker_code,'result_summary',f.result_summary,
            'observed_minutes',f.observed_minutes,'interaction_surface',f.interaction_surface,
            'heavy_session_used',f.heavy_session_used,'manual_context_transfers',f.manual_context_transfers,
            'accepted_by_actor_slug',fa.slug,'accepted_at',fr.accepted_at) as feedback
            from ops.sourced_work_request_outcome_feedback f
            join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
            join public.actor fa on fa.id=fr.accepted_by_actor_id
           where f.work_request_id=w.id
           order by fr.accepted_at desc,fr.id desc limit 20
        ) h
    ) history on true
    left join lateral (
      select count(*)::bigint as accepted_count
        from ops.sourced_work_request_outcome_feedback f
        join ops.sourced_work_request_outcome_feedback_acceptance_receipt fr on fr.feedback_id=f.id
       where f.work_request_id=w.id
    ) counted on true
    left join lateral (
      select jsonb_agg(to_jsonb(projected) order by projected.detected_at,projected.incident_ref) as items
        from (
          select i.ref as incident_ref,i.title,i.state,i.severity,i.environment,
                 to_jsonb(i.detected_at)#>>'{}' as detected_at,
                 to_jsonb(i.observed_at)#>>'{}' as observed_at,
                 to_jsonb(i.resolved_at)#>>'{}' as resolved_at,
                 occurrence.occurrences,occurrence.occurrence_evidence_status,
                 occurrence.legacy_overlap_unknown,occurrence.unresolved_occurrence_edge_count,
                 jsonb_build_object('kind','work_request','ref',w.ref) as association,
                 coalesce(evidence.items,'[]'::jsonb) as evidence
            from ops.incident_link anchor
            join ops.incident i on i.id=anchor.incident_id
            left join lateral (
              with occurrence_links as (
                select l.kind,l.ref,
                       case when l.ref ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                            then l.ref::uuid else null::uuid end as target_uuid
                  from ops.incident_link l
                 where l.incident_id=i.id and l.kind in ('run','deployment')
              ), resolved_links as (
                select x.kind,x.ref,
                       case when x.kind='run' then
                              (select r.correlation_id::text from ops.run r where r.id=x.target_uuid)
                            when x.kind='deployment' then
                              (select dep.correlation_id::text from ops.deployment dep where dep.id=x.target_uuid)
                       end as resolved_correlation
                  from occurrence_links x
              ), correlation_suffixes as (
                select distinct substring(f.source_ref from 13) as correlation_suffix
                  from ops.incident_fact f
                 where f.incident_id=i.id and f.source_ref like 'correlation:%'
              ), occurrence_counts as (
                select (select count(*) from resolved_links)::int as link_count,
                       (select count(*) from correlation_suffixes)::int as correlation_count,
                       (select count(*) from resolved_links where resolved_correlation is null)::int as unresolved_count,
                       (select count(*) from correlation_suffixes c where not exists (
                          select 1 from resolved_links r where r.resolved_correlation=c.correlation_suffix
                       ))::int as unpaired_correlation_count
              )
              select case when unresolved_count=0
                          then greatest(1,link_count+unpaired_correlation_count)
                          else greatest(1,link_count,correlation_count) end::int as occurrences,
                     case when unresolved_count>0 then 'legacy_overlap_unknown' else 'complete' end as occurrence_evidence_status,
                     (unresolved_count>0) as legacy_overlap_unknown,
                     unresolved_count as unresolved_occurrence_edge_count
                from occurrence_counts
            ) occurrence on true
            left join lateral (
              select jsonb_agg(item order by item->>'occurred_at' nulls last,item->>'kind',
                                            coalesce(item->>'ref',item->>'source_ref')) as items
                from (
                  select jsonb_build_object('evidence_type','link','kind',l.kind,'ref',l.ref,
                                            'occurred_at',null) as item
                    from ops.incident_link l
                   where l.incident_id=i.id and l.kind in ('run','deployment')
                  union all
                  select jsonb_build_object('evidence_type','fact','kind','fact','text',f.text,
                                            'source_ref',f.source_ref,
                                            'recorded_at',to_jsonb(f.recorded_at)#>>'{}',
                                            'occurred_at',to_jsonb(f.recorded_at)#>>'{}') as item
                    from ops.incident_fact f
                   where f.incident_id=i.id and f.source_ref is not null
                  union all
                  select jsonb_build_object('evidence_type','trace','kind',t.kind,'ref',t.ref,
                                            'correlation_id',t.correlation_id,'state',t.state,
                                            'environment',t.environment,'service_key',t.service_key,
                                            'failure_class',t.failure_class,'detail',t.detail,
                                            'source_kind',t.source_kind,'source_ref',t.source_ref,
                                            'freshness_state',t.freshness_state,
                                            'occurred_at',to_jsonb(t.occurred_at)#>>'{}') as item
                    from ops.v_trace t
                   where t.correlation_id=i.correlation_id
                      or t.correlation_id in (
                        select substring(f.source_ref from 13)::uuid
                          from ops.incident_fact f
                         where f.incident_id=i.id
                           and f.source_ref ~ '^correlation:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
                      )
                ) evidence_rows
            ) evidence on true
           where anchor.kind='work_request' and anchor.ref=w.ref
        ) projected
    ) incident_evidence on true
   where p_organization_tenant_id='carr-internal'
     and w.organization_tenant_id='carr-internal' and w.ref=p_work_request
     and w.state in ('captured','triaged','ready','declined','superseded')
     and d.visibility='shared';
$_$;


--
-- Name: work_request_shape_gate(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.work_request_shape_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  shape_work_request_version integer;
begin
  if tg_op = 'INSERT' then
    if new.state in ('claimed','in_progress','verification','awaiting_release','released','confirmed_closed') then
      raise exception 'new Work Request cannot enter implementation directly';
    end if;
    if new.state = 'ready' then
      if new.shape_disposition is null then
        raise exception 'ready Work Request requires an explicit shape disposition';
      elsif new.shape_disposition = 'required' then
        raise exception 'required shape analysis needs a captured or triaged Work Request before ready';
      end if;
    end if;
    return new;
  end if;

  if old.state not in ('captured','triaged','ready')
     and (new.shape_disposition,
          new.shape_fixed_surface_ref,
          new.shape_rationale,
          new.shape_decided_by_actor_id,
          new.shape_decided_at)
         is distinct from
         (old.shape_disposition,
          old.shape_fixed_surface_ref,
          old.shape_rationale,
          old.shape_decided_by_actor_id,
          old.shape_decided_at) then
    raise exception 'implementation shape disposition is frozen after claim';
  end if;

  if new.state = 'ready' and old.state is distinct from 'ready' then
    if new.shape_disposition is null then
      raise exception 'ready Work Request requires an explicit shape disposition';
    end if;
    if new.shape_disposition = 'required' then
      select r.work_request_version into shape_work_request_version
        from ops.work_shape_revision r
       where r.work_request_id = old.id
       order by r.version desc
       limit 1;
      if shape_work_request_version is null
         or shape_work_request_version <> old.version then
        raise exception 'required work shape is missing or stale for Work Request version %', old.version;
      end if;
    end if;
  end if;

  -- This is the actual implementation-entry gate. It catches application code,
  -- future verbs, and direct carr_writer SQL equally. Later transitions inside
  -- the implementation-state set use the disposition frozen at first entry.
  if new.state in ('claimed','in_progress','verification','awaiting_release','released','confirmed_closed')
     and old.state not in ('claimed','in_progress','verification','awaiting_release','released','confirmed_closed') then
    if (new.shape_disposition,
        new.shape_fixed_surface_ref,
        new.shape_rationale,
        new.shape_decided_by_actor_id,
        new.shape_decided_at)
       is distinct from
       (old.shape_disposition,
        old.shape_fixed_surface_ref,
        old.shape_rationale,
        old.shape_decided_by_actor_id,
        old.shape_decided_at) then
      raise exception 'shape disposition must be recorded before the implementation transition';
    end if;
    if new.shape_disposition is null then
      raise exception 'Work Request requires an explicit shape disposition before implementation';
    end if;
    if new.shape_disposition = 'required' then
      select r.work_request_version into shape_work_request_version
        from ops.work_shape_revision r
       where r.work_request_id = old.id
       order by r.version desc
       limit 1;
      if shape_work_request_version is null
         or shape_work_request_version <> old.version then
        raise exception 'required work shape is missing or stale for Work Request version %', old.version;
      end if;
    end if;
  end if;

  return new;
end;
$$;


