    CONSTRAINT assurance_execution_manifest_organization_tenant_id_check CHECK ((btrim(organization_tenant_id) <> ''::text)),
    CONSTRAINT assurance_execution_manifest_ownership_contract_digest_check CHECK ((ownership_contract_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT assurance_execution_manifest_repository_commit_sha_check CHECK ((repository_commit_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT assurance_execution_manifest_repository_stage_check CHECK ((repository_stage = ANY (ARRAY['write'::text, 'run_check'::text, 'post_commit'::text, 'push'::text, 'pull_request'::text, 'review'::text, 'merge'::text]))),
    CONSTRAINT assurance_execution_manifest_repository_tree_sha_check CHECK ((repository_tree_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT assurance_execution_manifest_slice_ref_check CHECK ((slice_ref ~ '^[A-Za-z][A-Za-z0-9._:-]{2,127}$'::text))
);


