-- Name: attempt_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.attempt_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key uuid NOT NULL,
    organization_tenant_id text NOT NULL,
