    CONSTRAINT authority_receipt_subject_type_check CHECK ((subject_type = ANY (ARRAY['rule'::text, 'guidance'::text, 'policy'::text])))
);


--
-- Name: benchmark_manifest_acceptance_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_acceptance_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    benchmark_ref text NOT NULL,
    idempotency_key uuid NOT NULL,
    gate_id text NOT NULL,
    producer_step_ref text CONSTRAINT benchmark_manifest_acceptance_receip_producer_step_ref_not_null NOT NULL,
    status text NOT NULL,
    accepted_payload_digest text CONSTRAINT benchmark_manifest_acceptance__accepted_payload_digest_not_null NOT NULL,
    review_id uuid NOT NULL,
    portfolio_ref text NOT NULL,
    portfolio_revision_id uuid CONSTRAINT benchmark_manifest_acceptance_re_portfolio_revision_id_not_null NOT NULL,
    portfolio_accepted_digest text CONSTRAINT benchmark_manifest_acceptanc_portfolio_accepted_digest_not_null NOT NULL,
    portfolio_accepted_at timestamp with time zone CONSTRAINT benchmark_manifest_acceptance_re_portfolio_accepted_at_not_null NOT NULL,
    gate_zero_step_ref text CONSTRAINT benchmark_manifest_acceptance_recei_gate_zero_step_ref_not_null NOT NULL,
    gate_zero_outcome_digest text CONSTRAINT benchmark_manifest_acceptance_gate_zero_outcome_digest_not_null NOT NULL,
    gate_zero_observed_at timestamp with time zone CONSTRAINT benchmark_manifest_acceptance_re_gate_zero_observed_at_not_null NOT NULL,
    accepted_by_actor_id uuid CONSTRAINT benchmark_manifest_acceptance_rec_accepted_by_actor_id_not_null NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_by_session_ref text,
    CONSTRAINT benchmark_acceptance_after_gate_zero CHECK ((accepted_at > gate_zero_observed_at)),
    CONSTRAINT benchmark_acceptance_after_portfolio CHECK ((accepted_at > portfolio_accepted_at)),
    CONSTRAINT benchmark_manifest_acceptance_r_portfolio_accepted_digest_check CHECK ((portfolio_accepted_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_acceptance_re_gate_zero_outcome_digest_check CHECK ((gate_zero_outcome_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_acceptance_rec_accepted_payload_digest_check CHECK ((accepted_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_acceptance_receipt_gate_id_check CHECK ((gate_id = 'benchmark-contract-accepted'::text)),
    CONSTRAINT benchmark_manifest_acceptance_receipt_gate_zero_step_ref_check CHECK ((gate_zero_step_ref = 'step:gate-zero-read-only-outcome'::text)),
    CONSTRAINT benchmark_manifest_acceptance_receipt_producer_step_ref_check CHECK ((producer_step_ref = 'step:benchmark-contract-human-exact-hash-acceptance-receipt'::text)),
    CONSTRAINT benchmark_manifest_acceptance_receipt_status_check CHECK ((status = 'accepted'::text))
);


--
-- Name: TABLE benchmark_manifest_acceptance_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_acceptance_receipt IS 'Private verified-partner receipt accepting one exact benchmark payload digest, strictly after both r7 prerequisites: the portfolio constitution the acceptor named (accepted and intact, not a lineage claim) and the Gate Zero read-only outcome as authenticated in this record layer. It grants no dispatch, activation or execution authority and starts no clock; it only makes that draft the accepted benchmark contract. Both bindings are implemented as of migration 0502: the coverage attestation and the Gate Zero outcome record. A row can exist only when both answer, and each still refuses on its own grounds.';


--
-- Name: benchmark_manifest_browser; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_browser (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
