    CONSTRAINT benchmark_manifest_browser_name_check CHECK ((char_length(name) >= 1)),
    CONSTRAINT benchmark_manifest_browser_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT benchmark_manifest_browser_version_check CHECK ((char_length(version) >= 1))
);


--
-- Name: TABLE benchmark_manifest_browser; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_browser IS 'The browser triples of one benchmark manifest draft. Each triple indexes a matrix cell, so a repeated triple is refused.';


--
-- Name: benchmark_manifest_concurrency; Type: TABLE; Schema: ops; Owner: -
