--
-- Name: TABLE benchmark_manifest_concurrency; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_concurrency IS 'The concurrency levels of one benchmark manifest draft; an ordered set of distinct positive integers.';


--
-- Name: benchmark_manifest_dimension; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_dimension (
