    CONSTRAINT benchmark_manifest_dimension_dimension_check CHECK ((dimension = ANY (ARRAY['capacity_profiles'::text, 'arrival_patterns'::text, 'routes'::text, 'runtime_versions'::text, 'device_profiles'::text, 'hardware_profiles'::text, 'network_profiles'::text, 'acknowledgement_endpoints'::text, 'comparator_versions'::text, 'cache_states'::text]))),
    CONSTRAINT benchmark_manifest_dimension_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT benchmark_manifest_dimension_value_check CHECK ((char_length(value) >= 1))
);


