-- Name: TABLE benchmark_manifest_dimension; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_dimension IS 'The ten ordered unique string dimensions of one benchmark manifest draft. Order is part of the hash: a reorder is a different manifest.';


--
-- Name: benchmark_manifest_draft; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_draft (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    benchmark_ref text NOT NULL,
    draft_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
    schema_version text NOT NULL,
    payload_domain_tag text NOT NULL,
    gate_id text NOT NULL,
    producer_step_ref text NOT NULL,
    producer_role text NOT NULL,
    combiner text NOT NULL,
    subject_digest text NOT NULL,
    candidate_digest text NOT NULL,
    policy_digest text NOT NULL,
    cost_expectation_matrix_digest text CONSTRAINT benchmark_manifest_draft_cost_expectation_matrix_diges_not_null NOT NULL,
    samples_per_cell integer NOT NULL,
    warmup_runs integer NOT NULL,
    p95_aggregation_method text NOT NULL,
    outlier_rule text NOT NULL,
    payload_digest text NOT NULL,
    proposed_by_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    proposed_by_session_ref text,
    CONSTRAINT benchmark_manifest_draft_benchmark_ref_check CHECK ((benchmark_ref ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,199}$'::text)),
    CONSTRAINT benchmark_manifest_draft_candidate_digest_check CHECK ((candidate_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_draft_combiner_check CHECK ((combiner = 'exact_verified_partner_hash_acceptance'::text)),
    CONSTRAINT benchmark_manifest_draft_cost_expectation_matrix_digest_check CHECK ((cost_expectation_matrix_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_draft_draft_version_check CHECK ((draft_version > 0)),
    CONSTRAINT benchmark_manifest_draft_gate_id_check CHECK ((gate_id = 'benchmark-contract-accepted'::text)),
    CONSTRAINT benchmark_manifest_draft_outlier_rule_check CHECK (((char_length(outlier_rule) >= 5) AND (char_length(outlier_rule) <= 300))),
    CONSTRAINT benchmark_manifest_draft_p95_aggregation_method_check CHECK ((p95_aggregation_method = 'nearest-rank-per-required-cell-all-cells-must-pass'::text)),
    CONSTRAINT benchmark_manifest_draft_payload_digest_check CHECK ((payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_draft_payload_domain_tag_check CHECK ((payload_domain_tag = 'doctorcre:benchmark-payload:v1'::text)),
    CONSTRAINT benchmark_manifest_draft_policy_digest_check CHECK ((policy_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_draft_producer_role_check CHECK ((producer_role = 'verified_partner_benchmark_authority'::text)),
    CONSTRAINT benchmark_manifest_draft_producer_step_ref_check CHECK ((producer_step_ref = 'step:benchmark-contract-human-exact-hash-acceptance-receipt'::text)),
    CONSTRAINT benchmark_manifest_draft_samples_per_cell_check CHECK ((samples_per_cell >= 20)),
    CONSTRAINT benchmark_manifest_draft_schema_version_check CHECK ((schema_version = 'benchmark-manifest.v1'::text)),
    CONSTRAINT benchmark_manifest_draft_subject_digest_check CHECK ((subject_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_draft_warmup_runs_check CHECK ((warmup_runs >= 1))
);


--
-- Name: TABLE benchmark_manifest_draft; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_draft IS 'One inert DoctorCRE v5 benchmark manifest draft. payload_digest is the r7 exact hash a verified partner would have to accept, and is recomputed from this draft''s own rows at every read, review and acceptance. A draft creates no job, envelope, capability, schedule, deployment or clock, and starts no J1 clock.';


--
-- Name: benchmark_manifest_evaluator; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_evaluator (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    ordinal integer NOT NULL,
    actor_id text NOT NULL,
    session_ref text NOT NULL,
    authority_class text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT benchmark_manifest_evaluator_actor_id_check CHECK ((char_length(actor_id) >= 1)),
    CONSTRAINT benchmark_manifest_evaluator_authority_class_check CHECK ((char_length(authority_class) >= 1)),
    CONSTRAINT benchmark_manifest_evaluator_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT benchmark_manifest_evaluator_session_ref_check CHECK ((session_ref ~ '^session:[a-z0-9][a-z0-9:._/-]{8,199}$'::text))
);


--
-- Name: TABLE benchmark_manifest_evaluator; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_evaluator IS 'The declared evaluator seats of one benchmark manifest draft. Hashed payload content only: no row here grants authority, and authority_class is never read back out to decide anything.';


--
-- Name: benchmark_manifest_request_size; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_request_size (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    ordinal integer NOT NULL,
    percentile integer NOT NULL,
    bytes bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT benchmark_manifest_request_size_bytes_check CHECK (((bytes >= 0) AND (bytes <= '9007199254740991'::bigint))),
    CONSTRAINT benchmark_manifest_request_size_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT benchmark_manifest_request_size_percentile_check CHECK (((percentile >= 1) AND (percentile <= 100)))
);


--
-- Name: TABLE benchmark_manifest_request_size; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_request_size IS 'The request-size distribution of one benchmark manifest draft: a mapping from percentile to bytes within a cell. The per-percentile uniqueness is derived, matching benchmark-minimum.v5.js.';


--
-- Name: benchmark_manifest_review; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_review (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    reviewed_payload_digest text NOT NULL,
    verdict text NOT NULL,
    measurement_set_digest text,
    review_summary text NOT NULL,
    reviewer_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewer_session_ref text,
    CONSTRAINT benchmark_manifest_review_measurement_set_digest_check CHECK ((measurement_set_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_review_review_summary_check CHECK (((btrim(review_summary) <> ''::text) AND (char_length(review_summary) <= 1000))),
    CONSTRAINT benchmark_manifest_review_reviewed_payload_digest_check CHECK ((reviewed_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_review_verdict_check CHECK ((verdict = ANY (ARRAY['pass'::text, 'fail'::text]))),
    CONSTRAINT benchmark_review_pass_binds_measurements CHECK (((verdict <> 'pass'::text) OR (measurement_set_digest IS NOT NULL)))
);


--
-- Name: TABLE benchmark_manifest_review; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_review IS 'Append-only independent review of one exact benchmark payload digest. A review naming a digest the draft no longer produces is refused at write time, so a passing review can never be carried onto different bytes. A passing review must additionally NAME the exact measurement set its writer read AND carry a coverage attestation in ops.benchmark_measurement_coverage_attestation recorded in the same call: naming is still not proving, this database still evaluates no coverage, and the attestation is what makes the assertion attributed and checkable rather than anonymous.';


--
-- Name: benchmark_manifest_workload; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_manifest_workload (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    draft_id uuid NOT NULL,
    ordinal integer NOT NULL,
    workload_id text NOT NULL,
    weight_basis_points integer NOT NULL,
    operation_mix_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT benchmark_manifest_workload_operation_mix_digest_check CHECK ((operation_mix_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_manifest_workload_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT benchmark_manifest_workload_weight_basis_points_check CHECK (((weight_basis_points >= 1) AND (weight_basis_points <= 10000))),
    CONSTRAINT benchmark_manifest_workload_workload_id_check CHECK ((char_length(workload_id) >= 1))
);


--
-- Name: TABLE benchmark_manifest_workload; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_manifest_workload IS 'The workload mix of one benchmark manifest draft. Weights are basis points and must total exactly 10000 before the draft may commit.';


--
-- Name: benchmark_measurement_coverage_attestation; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.benchmark_measurement_coverage_attestation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    review_id uuid NOT NULL,
    draft_id uuid NOT NULL,
    coverage_proved_by text CONSTRAINT benchmark_measurement_coverage_atte_coverage_proved_by_not_null NOT NULL,
    benchmark_payload_digest text CONSTRAINT benchmark_measurement_coverag_benchmark_payload_digest_not_null NOT NULL,
    measurement_set_digest text CONSTRAINT benchmark_measurement_coverage__measurement_set_digest_not_null NOT NULL,
    evaluation_digest text CONSTRAINT benchmark_measurement_coverage_attes_evaluation_digest_not_null NOT NULL,
    attested_by_actor_id uuid CONSTRAINT benchmark_measurement_coverage_at_attested_by_actor_id_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT benchmark_measurement_coverage_a_benchmark_payload_digest_check CHECK ((benchmark_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_measurement_coverage_att_measurement_set_digest_check CHECK ((measurement_set_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT benchmark_measurement_coverage_attesta_coverage_proved_by_check CHECK ((coverage_proved_by = 'benchmark-minimum.v5.js#evaluateBenchmarkWorkloadCoverage'::text)),
    CONSTRAINT benchmark_measurement_coverage_attestat_evaluation_digest_check CHECK ((evaluation_digest ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE benchmark_measurement_coverage_attestation; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.benchmark_measurement_coverage_attestation IS 'The trusted writer''s explicit, attributed statement that benchmark-minimum.v5.js proved coverage for one passing review: the evaluator by name from a closed set, the payload digest that evaluator returned, the measurement digest it proved over, and the digest of its result. Written in the same definer call as the review it attests, so an unattested pass cannot be written. It is not a verification: the samples stay outside this record layer and the database cannot repeat the evaluation.';


--
-- Name: calendar_canary_source_snapshot; Type: TABLE; Schema: ops; Owner: -
