--

CREATE TABLE ops.completion_observation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    subject_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_ref text NOT NULL,
    source_revision text NOT NULL,
    coherent_revision text NOT NULL,
    observation_kind text NOT NULL,
    authority_class text NOT NULL,
    content_digest text NOT NULL,
    value_digest text NOT NULL,
    redacted_value jsonb NOT NULL,
    evidence_locator text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    collector_name text NOT NULL,
    collector_version text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_observation_authority_class_check CHECK ((authority_class = ANY (ARRAY['authoritative'::text, 'supporting'::text]))),
    CONSTRAINT completion_observation_check CHECK ((expires_at > observed_at)),
    CONSTRAINT completion_observation_coherent_revision_check CHECK (((length(btrim(coherent_revision)) >= 1) AND (length(btrim(coherent_revision)) <= 240))),
    CONSTRAINT completion_observation_collector_name_check CHECK ((collector_name ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_observation_collector_version_check CHECK (((length(btrim(collector_version)) >= 1) AND (length(btrim(collector_version)) <= 80))),
    CONSTRAINT completion_observation_content_digest_check CHECK ((content_digest ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT completion_observation_evidence_locator_check CHECK (((length(btrim(evidence_locator)) >= 1) AND (length(btrim(evidence_locator)) <= 500))),
    CONSTRAINT completion_observation_observation_kind_check CHECK ((observation_kind = ANY (ARRAY['canonical_owner'::text, 'intended_consumer'::text, 'workflow_trigger'::text, 'retrieval_admission'::text, 'enforcement_closure'::text, 'operator_surface'::text, 'telemetry'::text, 'canonical_implementation'::text, 'activation'::text, 'live_readback'::text, 'rollback'::text, 'intent'::text, 'implementation_artifact'::text, 'blocker'::text]))),
    CONSTRAINT completion_observation_redacted_value_check CHECK (ops.completion_json_is_redacted(redacted_value)),
    CONSTRAINT completion_observation_source_kind_check CHECK ((source_kind ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_observation_source_ref_check CHECK (((length(btrim(source_ref)) >= 1) AND (length(btrim(source_ref)) <= 500))),
    CONSTRAINT completion_observation_source_revision_check CHECK (((length(btrim(source_revision)) >= 1) AND (length(btrim(source_revision)) <= 240))),
    CONSTRAINT completion_observation_value_digest_check CHECK ((value_digest ~ '^sha256:[a-f0-9]{64}$'::text))
);


--
-- Name: TABLE completion_observation; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.completion_observation IS 'Append-only, receipt-bound, redacted source evidence. Operational is forbidden as authored evidence and derived only in ops.completion_projection.';


--
-- Name: completion_current_observation; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.completion_current_observation WITH (security_barrier='true') AS
 SELECT DISTINCT ON (organization_tenant_id, subject_id, observation_kind, source_kind, source_ref) id,
    organization_tenant_id,
    subject_id,
    receipt_id,
    source_kind,
    source_ref,
    source_revision,
    coherent_revision,
    observation_kind,
    authority_class,
    content_digest,
    value_digest,
    redacted_value,
    evidence_locator,
    observed_at,
    expires_at,
    collector_name,
    collector_version
   FROM ops.completion_observation o
  WHERE (organization_tenant_id = ops.completion_runtime_tenant())
  ORDER BY organization_tenant_id, subject_id, observation_kind, source_kind, source_ref, observed_at DESC, id DESC;


--
-- Name: completion_policy; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.completion_policy (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    policy_key text NOT NULL,
    policy_version integer NOT NULL,
    capability_class text NOT NULL,
    required_dimensions text[] NOT NULL,
    default_freshness interval NOT NULL,
    state_precedence text[] NOT NULL,
    effective_at timestamp with time zone NOT NULL,
    policy_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_policy_capability_class_check CHECK ((capability_class ~ '^[a-z][a-z0-9_-]{0,79}$'::text)),
    CONSTRAINT completion_policy_default_freshness_check CHECK ((default_freshness > '00:00:00'::interval)),
    CONSTRAINT completion_policy_policy_digest_check CHECK ((policy_digest ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT completion_policy_policy_key_check CHECK ((policy_key ~ '^[a-z][a-z0-9_-]{0,79}$'::text)),
    CONSTRAINT completion_policy_policy_version_check CHECK ((policy_version > 0)),
    CONSTRAINT completion_policy_required_dimensions_check CHECK (ops.completion_dimensions_valid(required_dimensions)),
    CONSTRAINT completion_policy_state_precedence_check CHECK (ops.completion_precedence_valid(state_precedence))
);


--
-- Name: TABLE completion_policy; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.completion_policy IS 'Append-only versioned required-evidence, freshness, and conservative precedence policy.';


--
-- Name: completion_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.completion_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    receipt_ref text NOT NULL,
    collector_name text NOT NULL,
    collector_version text NOT NULL,
    source_kind text NOT NULL,
    source_ref text NOT NULL,
    source_cursor jsonb NOT NULL,
    rows_observed integer NOT NULL,
    rows_changed integer NOT NULL,
    outcome text NOT NULL,
    failure_class text,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    evidence_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_receipt_check CHECK (((rows_changed >= 0) AND (rows_changed <= rows_observed))),
    CONSTRAINT completion_receipt_check1 CHECK ((finished_at >= started_at)),
    CONSTRAINT completion_receipt_check2 CHECK ((expires_at > finished_at)),
    CONSTRAINT completion_receipt_check3 CHECK ((((outcome = 'succeeded'::text) AND (failure_class IS NULL)) OR ((outcome <> 'succeeded'::text) AND (length(btrim(failure_class)) > 0)))),
    CONSTRAINT completion_receipt_collector_name_check CHECK ((collector_name ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_receipt_collector_version_check CHECK (((length(btrim(collector_version)) >= 1) AND (length(btrim(collector_version)) <= 80))),
    CONSTRAINT completion_receipt_evidence_digest_check CHECK ((evidence_digest ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT completion_receipt_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'failed'::text, 'unavailable'::text]))),
    CONSTRAINT completion_receipt_receipt_ref_check CHECK (((length(btrim(receipt_ref)) >= 1) AND (length(btrim(receipt_ref)) <= 240))),
    CONSTRAINT completion_receipt_rows_observed_check CHECK ((rows_observed >= 0)),
    CONSTRAINT completion_receipt_source_cursor_check CHECK (((jsonb_typeof(source_cursor) = 'object'::text) AND ops.completion_json_is_redacted(source_cursor))),
    CONSTRAINT completion_receipt_source_kind_check CHECK ((source_kind ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_receipt_source_ref_check CHECK (((length(btrim(source_ref)) >= 1) AND (length(btrim(source_ref)) <= 500)))
);


--
-- Name: TABLE completion_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.completion_receipt IS 'Append-only collector receipt metadata; failures cannot support observations.';


--
-- Name: completion_subject; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.completion_subject (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    stable_key text NOT NULL,
    human_label text NOT NULL,
    capability_class text NOT NULL,
    canonical_source_kind text,
    canonical_source_ref text,
    created_provenance jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_subject_canonical_source_kind_check CHECK ((canonical_source_kind ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_subject_canonical_source_ref_check CHECK (((length(btrim(canonical_source_ref)) >= 1) AND (length(btrim(canonical_source_ref)) <= 500))),
    CONSTRAINT completion_subject_capability_class_check CHECK ((capability_class ~ '^[a-z][a-z0-9_-]{0,79}$'::text)),
    CONSTRAINT completion_subject_check CHECK (((canonical_source_kind IS NULL) = (canonical_source_ref IS NULL))),
    CONSTRAINT completion_subject_created_provenance_check CHECK (((jsonb_typeof(created_provenance) = 'object'::text) AND ops.completion_json_is_redacted(created_provenance))),
    CONSTRAINT completion_subject_human_label_check CHECK (((length(btrim(human_label)) >= 1) AND (length(btrim(human_label)) <= 240))),
    CONSTRAINT completion_subject_stable_key_check CHECK ((stable_key ~ '^[a-z0-9][a-z0-9:._/-]{0,239}$'::text))
);


--
-- Name: TABLE completion_subject; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.completion_subject IS 'Immutable tenant-derived capability identities. No execution or lifecycle status is stored.';


--
-- Name: completion_dimension_matrix; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.completion_dimension_matrix WITH (security_barrier='true') AS
 WITH subject_policy AS (
         SELECT s.id AS subject_id,
            s.organization_tenant_id,
            s.stable_key,
            p.policy_key,
            p.policy_version,
            p.policy_digest,
            p.required_dimensions,
            p.default_freshness,
            p.state_precedence
           FROM (ops.completion_subject s
             CROSS JOIN LATERAL ( SELECT candidate.id,
                    candidate.organization_tenant_id,
                    candidate.policy_key,
                    candidate.policy_version,
                    candidate.capability_class,
                    candidate.required_dimensions,
                    candidate.default_freshness,
                    candidate.state_precedence,
                    candidate.effective_at,
                    candidate.policy_digest,
                    candidate.created_at
                   FROM ops.completion_policy candidate
                  WHERE ((candidate.organization_tenant_id = s.organization_tenant_id) AND (candidate.capability_class = ANY (ARRAY[s.capability_class, 'default'::text])) AND (candidate.effective_at <= now()))
                  ORDER BY (candidate.capability_class = s.capability_class) DESC, candidate.effective_at DESC, candidate.policy_version DESC
                 LIMIT 1) p)
          WHERE (s.organization_tenant_id = ops.completion_runtime_tenant())
        ), required AS (
         SELECT sp.subject_id,
            sp.organization_tenant_id,
            sp.stable_key,
            sp.policy_key,
            sp.policy_version,
            sp.policy_digest,
            sp.required_dimensions,
            sp.default_freshness,
            sp.state_precedence,
            dimension.dimension,
            (dimension.ordinality)::integer AS dimension_ordinal
           FROM (subject_policy sp
             CROSS JOIN LATERAL unnest(sp.required_dimensions) WITH ORDINALITY dimension(dimension, ordinality))
        )
 SELECT r.organization_tenant_id,
    r.subject_id,
    r.stable_key,
    r.policy_key,
    r.policy_version,
    r.policy_digest,
    r.default_freshness,
    r.state_precedence,
    r.dimension,
    r.dimension_ordinal,
        CASE
            WHEN (count(DISTINCT o.value_digest) FILTER (WHERE ((o.authority_class = 'authoritative'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) > 1) THEN 'conflicting'::text
            WHEN (count(*) FILTER (WHERE ((o.authority_class = 'authoritative'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) > 0) THEN 'present'::text
            WHEN (count(o.id) FILTER (WHERE (o.authority_class = 'authoritative'::text)) > 0) THEN 'stale'::text
            ELSE 'missing'::text
        END AS dimension_state,
    min(o.observed_at) FILTER (WHERE ((o.authority_class = 'authoritative'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS oldest_fresh_observed_at,
    min(LEAST(o.expires_at, (o.observed_at + r.default_freshness))) FILTER (WHERE ((o.authority_class = 'authoritative'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS earliest_fresh_expiry,
    COALESCE(jsonb_agg(jsonb_build_object('observation_id', ('observation:'::text || (o.id)::text), 'receipt_ref', receipt.receipt_ref, 'source_kind', o.source_kind, 'source_ref', o.source_ref, 'source_revision', o.source_revision, 'coherent_revision', o.coherent_revision, 'observed_at', o.observed_at, 'source_expires_at', o.expires_at, 'expires_at', LEAST(o.expires_at, (o.observed_at + r.default_freshness)), 'evidence_locator', o.evidence_locator) ORDER BY o.observed_at DESC, o.id DESC) FILTER (WHERE (o.id IS NOT NULL)), '[]'::jsonb) AS evidence
   FROM ((required r
     LEFT JOIN ops.completion_current_observation o ON (((o.organization_tenant_id = r.organization_tenant_id) AND (o.subject_id = r.subject_id) AND (o.observation_kind = r.dimension))))
     LEFT JOIN ops.completion_receipt receipt ON (((receipt.organization_tenant_id = o.organization_tenant_id) AND (receipt.id = o.receipt_id))))
  GROUP BY r.organization_tenant_id, r.subject_id, r.stable_key, r.policy_key, r.policy_version, r.policy_digest, r.default_freshness, r.state_precedence, r.dimension, r.dimension_ordinal;


--
-- Name: completion_disposition; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.completion_disposition (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    subject_id uuid NOT NULL,
    disposition text NOT NULL,
    replacement_subject_id uuid,
    decision_ref text NOT NULL,
    rationale text NOT NULL,
    decided_by_actor_id uuid NOT NULL,
    decided_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_disposition_check CHECK ((((disposition = 'superseded'::text) AND (replacement_subject_id IS NOT NULL)) OR ((disposition = 'canceled'::text) AND (replacement_subject_id IS NULL)))),
    CONSTRAINT completion_disposition_check1 CHECK ((replacement_subject_id IS DISTINCT FROM subject_id)),
    CONSTRAINT completion_disposition_decision_ref_check CHECK (((length(btrim(decision_ref)) >= 1) AND (length(btrim(decision_ref)) <= 240))),
    CONSTRAINT completion_disposition_disposition_check CHECK ((disposition = ANY (ARRAY['canceled'::text, 'superseded'::text]))),
    CONSTRAINT completion_disposition_rationale_check CHECK (((length(btrim(rationale)) >= 1) AND (length(btrim(rationale)) <= 2000)))
);


--
-- Name: TABLE completion_disposition; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.completion_disposition IS 'Append-only human disposition for source-less artifacts only; never an operational assertion.';


--
-- Name: completion_projection; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.completion_projection WITH (security_barrier='true') AS
 WITH matrix_rollup AS (
         SELECT m.organization_tenant_id,
            m.subject_id,
            m.stable_key,
            m.policy_key,
            m.policy_version,
            m.policy_digest,
            m.default_freshness,
            m.state_precedence,
            bool_or((m.dimension_state = 'conflicting'::text)) AS has_conflict,
            bool_or((m.dimension_state = 'stale'::text)) AS has_stale,
            bool_and((m.dimension_state = 'present'::text)) AS every_required_present,
            min(m.dimension_ordinal) FILTER (WHERE (m.dimension_state <> 'present'::text)) AS first_unmet_ordinal,
            jsonb_object_agg(m.dimension, jsonb_build_object('state', m.dimension_state, 'ordinal', m.dimension_ordinal, 'oldest_fresh_observed_at', m.oldest_fresh_observed_at, 'earliest_fresh_expiry', m.earliest_fresh_expiry, 'evidence', m.evidence) ORDER BY m.dimension_ordinal) AS evidence_matrix
           FROM ops.completion_dimension_matrix m
          GROUP BY m.organization_tenant_id, m.subject_id, m.stable_key, m.policy_key, m.policy_version, m.policy_digest, m.default_freshness, m.state_precedence
        ), subject_state AS (
         SELECT r.organization_tenant_id,
            r.subject_id,
            r.stable_key,
            r.policy_key,
            r.policy_version,
            r.policy_digest,
            r.default_freshness,
            r.state_precedence,
            r.has_conflict,
            r.has_stale,
            r.every_required_present,
            r.first_unmet_ordinal,
            r.evidence_matrix,
            s.human_label,
            s.capability_class,
            s.canonical_source_kind,
            s.canonical_source_ref,
            unmet.dimension AS next_required_dimension,
            disposition.disposition,
            disposition.decision_ref AS disposition_decision_ref,
            disposition.replacement_subject_id,
            COALESCE(flags.has_intent, false) AS has_intent,
            COALESCE(flags.has_artifact, false) AS has_artifact,
            COALESCE(flags.has_canonical, false) AS has_canonical,
            COALESCE(flags.has_activation, false) AS has_activation,
            COALESCE(flags.has_readback, false) AS has_readback,
            COALESCE(flags.has_telemetry, false) AS has_telemetry,
            COALESCE(flags.has_blocker, false) AS has_blocker,
            COALESCE(coherence.coherent_revision_count, (0)::bigint) AS coherent_revision_count,
            coherence.coherent_revision
           FROM (((((matrix_rollup r
             JOIN ops.completion_subject s ON (((s.organization_tenant_id = r.organization_tenant_id) AND (s.id = r.subject_id))))
             LEFT JOIN ops.completion_dimension_matrix unmet ON (((unmet.organization_tenant_id = r.organization_tenant_id) AND (unmet.subject_id = r.subject_id) AND (unmet.dimension_ordinal = r.first_unmet_ordinal))))
             LEFT JOIN LATERAL ( SELECT d.disposition,
                    d.decision_ref,
                    d.replacement_subject_id
                   FROM ops.completion_disposition d
                  WHERE ((d.organization_tenant_id = r.organization_tenant_id) AND (d.subject_id = r.subject_id))
                  ORDER BY d.decided_at DESC, d.id DESC
                 LIMIT 1) disposition ON (true))
             LEFT JOIN LATERAL ( SELECT bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'intent'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_intent,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'implementation_artifact'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_artifact,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'canonical_implementation'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_canonical,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'activation'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_activation,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'live_readback'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_readback,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'telemetry'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_telemetry,
                    bool_or(((o.authority_class = 'authoritative'::text) AND (o.observation_kind = 'blocker'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) AS has_blocker
                   FROM ops.completion_current_observation o
                  WHERE ((o.organization_tenant_id = r.organization_tenant_id) AND (o.subject_id = r.subject_id))) flags ON (true))
             LEFT JOIN LATERAL ( SELECT count(DISTINCT o.coherent_revision) FILTER (WHERE (o.coherent_revision IS NOT NULL)) AS coherent_revision_count,
                    min(o.coherent_revision) FILTER (WHERE (o.coherent_revision IS NOT NULL)) AS coherent_revision
                   FROM ops.completion_current_observation o
                  WHERE ((o.organization_tenant_id = r.organization_tenant_id) AND (o.subject_id = r.subject_id) AND (o.observation_kind IN ( SELECT m.dimension
                           FROM ops.completion_dimension_matrix m
                          WHERE ((m.organization_tenant_id = r.organization_tenant_id) AND (m.subject_id = r.subject_id)))) AND (o.authority_class = 'authoritative'::text) AND (LEAST(o.expires_at, (o.observed_at + r.default_freshness)) > now()))) coherence ON (true))
        ), candidate AS (
         SELECT s.organization_tenant_id,
            s.subject_id,
            s.stable_key,
            s.policy_key,
            s.policy_version,
            s.policy_digest,
            s.default_freshness,
            s.state_precedence,
            s.has_conflict,
            s.has_stale,
            s.every_required_present,
            s.first_unmet_ordinal,
            s.evidence_matrix,
            s.human_label,
            s.capability_class,
            s.canonical_source_kind,
            s.canonical_source_ref,
            s.next_required_dimension,
            s.disposition,
            s.disposition_decision_ref,
            s.replacement_subject_id,
            s.has_intent,
            s.has_artifact,
            s.has_canonical,
            s.has_activation,
            s.has_readback,
            s.has_telemetry,
            s.has_blocker,
            s.coherent_revision_count,
            s.coherent_revision,
            chosen.lifecycle_state,
            array_position(s.state_precedence, chosen.lifecycle_state) AS precedence_rank
           FROM (subject_state s
             CROSS JOIN LATERAL ( SELECT possibility.lifecycle_state
                   FROM ( VALUES ('conflicting'::text,s.has_conflict), ('canceled'::text,(s.disposition = 'canceled'::text)), ('superseded'::text,(s.disposition = 'superseded'::text)), ('unknown_stale'::text,s.has_stale), ('blocked'::text,s.has_blocker), ('planned'::text,(s.has_intent AND (NOT s.has_artifact) AND (NOT s.has_canonical))), ('built_unmerged'::text,(s.has_artifact AND (NOT s.has_canonical))), ('merged_unactivated'::text,(s.has_canonical AND (NOT s.has_activation))), ('active_unproven'::text,(s.has_activation AND ((NOT s.has_readback) OR (NOT s.has_telemetry)))), ('partially_built'::text,(NOT (s.every_required_present AND (s.coherent_revision_count = 1)))), ('operational'::text,(s.every_required_present AND (s.coherent_revision_count = 1)))) possibility(lifecycle_state, applies)
                  WHERE possibility.applies
                  ORDER BY (array_position(s.state_precedence, possibility.lifecycle_state))
                 LIMIT 1) chosen)
        )
 SELECT organization_tenant_id,
    subject_id,
    stable_key,
    human_label,
    capability_class,
    canonical_source_kind,
    canonical_source_ref,
    lifecycle_state,
    precedence_rank,
    state_precedence,
    policy_key,
    policy_version,
    policy_digest,
    default_freshness,
    coherent_revision,
    evidence_matrix,
    next_required_dimension,
        CASE
            WHEN (lifecycle_state = 'conflicting'::text) THEN 'resolve authoritative evidence conflict'::text
            WHEN (lifecycle_state = ANY (ARRAY['canceled'::text, 'superseded'::text])) THEN NULL::text
            WHEN (lifecycle_state = 'unknown_stale'::text) THEN ('refresh '::text || COALESCE(next_required_dimension, 'expired evidence'::text))
            WHEN (lifecycle_state = 'blocked'::text) THEN 'clear canonical blocker'::text
            WHEN (next_required_dimension IS NOT NULL) THEN ('supply '::text || next_required_dimension)
            ELSE NULL::text
        END AS next_action,
    disposition_decision_ref,
        CASE
            WHEN (replacement_subject_id IS NULL) THEN NULL::text
            ELSE ('subject:'::text || (replacement_subject_id)::text)
        END AS replacement_subject_ref
   FROM candidate;


--
-- Name: VIEW completion_projection; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.completion_projection IS 'Tenant-derived deterministic lifecycle projection. Conflicts and stale evidence outrank positive completion evidence.';


--
-- Name: completion_relation; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.completion_relation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    from_subject_id uuid NOT NULL,
    to_subject_id uuid NOT NULL,
    relation_kind text NOT NULL,
    authority_class text NOT NULL,
    source_kind text NOT NULL,
    source_ref text NOT NULL,
    source_revision text NOT NULL,
    relation_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT completion_relation_authority_class_check CHECK ((authority_class = ANY (ARRAY['exact_source'::text, 'human_decision'::text]))),
    CONSTRAINT completion_relation_check CHECK ((from_subject_id <> to_subject_id)),
    CONSTRAINT completion_relation_relation_digest_check CHECK ((relation_digest ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT completion_relation_relation_kind_check CHECK ((relation_kind = ANY (ARRAY['implements'::text, 'evidenced_by'::text, 'duplicates'::text, 'supersedes'::text, 'blocked_by'::text, 'owned_by'::text]))),
    CONSTRAINT completion_relation_source_kind_check CHECK ((source_kind ~ '^[a-z][a-z0-9_.-]{0,79}$'::text)),
    CONSTRAINT completion_relation_source_ref_check CHECK (((length(btrim(source_ref)) >= 1) AND (length(btrim(source_ref)) <= 500))),
    CONSTRAINT completion_relation_source_revision_check CHECK (((length(btrim(source_revision)) >= 1) AND (length(btrim(source_revision)) <= 240)))
);


