--

CREATE TABLE ops.engineering_execution_envelope (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    work_request_id uuid NOT NULL,
    accepted_plan_id uuid NOT NULL,
    slice_plan_id uuid NOT NULL,
