--
-- Name: gate_zero_read_only_outcome; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.gate_zero_read_only_outcome (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key uuid NOT NULL,
    step_ref text NOT NULL,
    receipt_producer_step_ref text NOT NULL,
    gate_id text NOT NULL,
    receipt_schema text NOT NULL,
    producer_role text NOT NULL,
    independent_oracle_ref text NOT NULL,
    oracle_version text NOT NULL,
    evidence_scope text NOT NULL,
    subject_environment text NOT NULL,
    negative_admission_result text NOT NULL,
    producing_seat_ref text NOT NULL,
    producing_actor_id uuid NOT NULL,
    candidate_digest text NOT NULL,
    subject_digest text NOT NULL,
    policy_digest text NOT NULL,
    environment_manifest_digest text CONSTRAINT gate_zero_read_only_outcome_environment_manifest_diges_not_null NOT NULL,
    fixture_set_digest text NOT NULL,
    evidence_ref text NOT NULL,
    receipt jsonb NOT NULL,
    outcome_digest text NOT NULL,
    candidate_scoped_digest text NOT NULL,
    status text NOT NULL,
    comparator text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    ttl_expires_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gate_zero_outcome_expiry_after_observation CHECK ((ttl_expires_at > observed_at)),
    CONSTRAINT gate_zero_outcome_recorded_after_observation CHECK ((recorded_at >= observed_at)),
    CONSTRAINT gate_zero_read_only_outcome_candidate_digest_check CHECK ((candidate_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_candidate_scoped_digest_check CHECK ((candidate_scoped_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_comparator_check CHECK (((char_length(comparator) >= 5) AND (char_length(comparator) <= 300))),
    CONSTRAINT gate_zero_read_only_outcome_environment_manifest_digest_check CHECK ((environment_manifest_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_evidence_ref_check CHECK ((evidence_ref ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_evidence_scope_check CHECK ((evidence_scope = 'candidate-and-test'::text)),
    CONSTRAINT gate_zero_read_only_outcome_fixture_set_digest_check CHECK ((fixture_set_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_gate_id_check CHECK ((gate_id = 'gate-zero-read-only-accepted'::text)),
    CONSTRAINT gate_zero_read_only_outcome_independent_oracle_ref_check CHECK ((independent_oracle_ref = 'oracle:gate-producer:gate-zero-read-only'::text)),
    CONSTRAINT gate_zero_read_only_outcome_negative_admission_result_check CHECK ((negative_admission_result = 'all_required_denials_observed'::text)),
    CONSTRAINT gate_zero_read_only_outcome_oracle_version_check CHECK ((oracle_version = '1.0.0'::text)),
    CONSTRAINT gate_zero_read_only_outcome_outcome_digest_check CHECK ((outcome_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_policy_digest_check CHECK ((policy_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_producer_role_check CHECK ((producer_role = 'independent_control_plane_oracle'::text)),
    CONSTRAINT gate_zero_read_only_outcome_producing_seat_ref_check CHECK ((producing_seat_ref ~ '^seat:[a-z0-9][a-z0-9.-]*:[a-z0-9][a-z0-9.-]*$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_receipt_check CHECK ((jsonb_typeof(receipt) = 'object'::text)),
    CONSTRAINT gate_zero_read_only_outcome_receipt_producer_step_ref_check CHECK ((receipt_producer_step_ref = 'step:gate-zero-read-only-outcome'::text)),
    CONSTRAINT gate_zero_read_only_outcome_receipt_schema_check CHECK ((receipt_schema = 'consumer-gate-receipt.v1'::text)),
    CONSTRAINT gate_zero_read_only_outcome_status_check CHECK ((status = ANY (ARRAY['pass'::text, 'fail'::text, 'unknown'::text, 'stale'::text, 'quarantined'::text]))),
    CONSTRAINT gate_zero_read_only_outcome_step_ref_check CHECK ((step_ref = 'step:gate-zero-read-only-outcome'::text)),
    CONSTRAINT gate_zero_read_only_outcome_subject_digest_check CHECK ((subject_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT gate_zero_read_only_outcome_subject_environment_check CHECK ((subject_environment = 'candidate'::text))
);


--
-- Name: TABLE gate_zero_read_only_outcome; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.gate_zero_read_only_outcome IS 'The authenticated Gate Zero read-only outcome: one consumer-gate-receipt.v1 per candidate, its digest recomputed from the stored receipt, the instant it was observed, and the independent oracle seat that produced it. Append-only and retryable, every run kept. It grants nothing and starts no clock; it is the value benchmark acceptance binds and the zero the v5 clock is measured from.';


--
-- Name: COLUMN gate_zero_read_only_outcome.producing_seat_ref; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.gate_zero_read_only_outcome.producing_seat_ref IS 'The staffed oracle seat that produced this receipt, derived from the server-established actor context and the frozen holder ref. Never a parameter.';


--
-- Name: COLUMN gate_zero_read_only_outcome.outcome_digest; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.gate_zero_read_only_outcome.outcome_digest IS 'Recomputed from `receipt` with ops.gate_zero_outcome_digest, which is sha256 over the canonical JSON of the TAGGED two-element array ["consumer-gate-receipt.v1", receipt] as r7''s receipt_payload_digest_rule declares (amended 2026-09-13). Never supplied by a caller. ops.portfolio_canonical_json matches artifact-trust.js canonicalJson byte for byte, over that same array.';


--
-- Name: COLUMN gate_zero_read_only_outcome.candidate_scoped_digest; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.gate_zero_read_only_outcome.candidate_scoped_digest IS 'Informational comparison value: ops.gate_zero_outcome_candidate_digest(receipt), the canonical-JSON sha256 over the receipt minus observed_at, ttl_expires_at and each identity''s per-call session_ref. It is not evidence and not an admission or idempotency key. The unique candidate_digest column arbitrates one immutable row per candidate; a later call returns that recorded row unchanged and reports whether its offered receipt differed.';


