    CONSTRAINT legacy_schedule_disable_receipt_approved_by_check CHECK ((approved_by = 'joe'::text)),
    CONSTRAINT legacy_schedule_disable_receipt_reason_check CHECK ((btrim(reason) <> ''::text))
);


