    locator text NOT NULL,
    scheduler_kind text NOT NULL,
    duplicate_group text,
    CONSTRAINT legacy_schedule_duplicate_group_nonblank CHECK (((duplicate_group IS NULL) OR (btrim(duplicate_group) <> ''::text))),
    CONSTRAINT legacy_schedule_surface_registry_scheduler_kind_check CHECK ((scheduler_kind = ANY (ARRAY['launchd'::text, 'claude-code'::text])))
);


--
-- Name: meeting; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting (
    id uuid NOT NULL,
    organization_tenant_id text NOT NULL,
    platform text,
    source_system text NOT NULL,
    native_id text NOT NULL,
    native_id_epoch text NOT NULL,
    title text NOT NULL,
    activation_intent text NOT NULL,
    recording text DEFAULT 'denied'::text NOT NULL,
    mode_state text DEFAULT 'active_non_recording'::text NOT NULL,
    started_by_actor uuid NOT NULL,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    ended_by_actor uuid,
    ended_at timestamp with time zone,
    last_seq bigint DEFAULT 0 NOT NULL,
    last_note_number integer DEFAULT 0 NOT NULL,
    last_action_number integer DEFAULT 0 NOT NULL,
    CONSTRAINT meeting_activation_intent_check CHECK ((activation_intent = 'one_tap_user_activation'::text)),
    CONSTRAINT meeting_end_is_coherent CHECK ((((mode_state = 'ended'::text) = (ended_at IS NOT NULL)) AND ((ended_at IS NULL) = (ended_by_actor IS NULL)))),
    CONSTRAINT meeting_last_action_number_check CHECK ((last_action_number >= 0)),
    CONSTRAINT meeting_last_note_number_check CHECK ((last_note_number >= 0)),
    CONSTRAINT meeting_last_seq_check CHECK ((last_seq >= 0)),
    CONSTRAINT meeting_mode_state_check CHECK ((mode_state = ANY (ARRAY['active_non_recording'::text, 'ended'::text]))),
    CONSTRAINT meeting_native_id_check CHECK ((native_id ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,254}$'::text)),
    CONSTRAINT meeting_native_id_epoch_check CHECK ((native_id_epoch ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_organization_tenant_id_check CHECK ((organization_tenant_id <> ''::text)),
    CONSTRAINT meeting_platform_check CHECK ((platform = ANY (ARRAY['teams'::text, 'zoom'::text]))),
    CONSTRAINT meeting_recording_check CHECK ((recording = 'denied'::text)),
    CONSTRAINT meeting_source_system_check CHECK ((source_system ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_title_check CHECK ((((char_length(title) >= 1) AND (char_length(title) <= 200)) AND (title !~ '[[:cntrl:]]'::text)))
);


--
-- Name: TABLE meeting; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.meeting IS 'V5-UX-B11: one shared non-recording meeting per tenant and native source identity. recording is CHECKed to denied; there is no audio column.';


--
-- Name: meeting_action; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting_action (
    meeting_id uuid NOT NULL,
    action_number integer NOT NULL,
    dedupe_key text,
    state text NOT NULL,
    current_revision integer NOT NULL,
    decided_revision integer,
    decided_by_actor uuid,
    decided_at timestamp with time zone,
    disposition text,
    assignee_actor uuid,
    operation_key uuid,
    outcome jsonb,
    CONSTRAINT meeting_action_acceptance_is_coherent CHECK (((state = ANY (ARRAY['accepted'::text, 'executed'::text, 'delegated'::text])) = ((operation_key IS NOT NULL) AND (disposition IS NOT NULL) AND (assignee_actor IS NOT NULL)))),
    CONSTRAINT meeting_action_action_number_check CHECK ((action_number >= 1)),
    CONSTRAINT meeting_action_current_revision_check CHECK ((current_revision >= 1)),
    CONSTRAINT meeting_action_decided_revision_check CHECK ((decided_revision >= 1)),
    CONSTRAINT meeting_action_decision_is_coherent CHECK ((((state = 'proposed'::text) = (decided_at IS NULL)) AND ((decided_at IS NULL) = (decided_by_actor IS NULL)) AND ((decided_at IS NULL) = (decided_revision IS NULL)))),
    CONSTRAINT meeting_action_dedupe_key_check CHECK ((dedupe_key ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_action_disposition_check CHECK ((disposition = ANY (ARRAY['execute'::text, 'delegate'::text]))),
    CONSTRAINT meeting_action_outcome_is_evidence CHECK ((((state = ANY (ARRAY['executed'::text, 'delegated'::text])) = (outcome IS NOT NULL)) AND ((state <> 'executed'::text) OR (disposition = 'execute'::text)) AND ((state <> 'delegated'::text) OR (disposition = 'delegate'::text)))),
    CONSTRAINT meeting_action_state_check CHECK ((state = ANY (ARRAY['proposed'::text, 'accepted'::text, 'executed'::text, 'delegated'::text, 'declined'::text])))
);


--
-- Name: meeting_action_revision; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting_action_revision (
    id uuid NOT NULL,
    meeting_id uuid NOT NULL,
    action_number integer NOT NULL,
    revision integer NOT NULL,
    summary text NOT NULL,
    command jsonb,
    basis text NOT NULL,
    source text NOT NULL,
    processing_epoch bigint,
    proposed_by_actor uuid NOT NULL,
    proposed_by_instance text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT meeting_action_revision_basis_check CHECK ((basis = ANY (ARRAY['tentative_discussion'::text, 'explicit_instruction'::text]))),
    CONSTRAINT meeting_action_revision_check CHECK (((source = 'processing'::text) = (processing_epoch IS NOT NULL))),
    CONSTRAINT meeting_action_revision_command_check CHECK (((command IS NULL) OR ((jsonb_typeof(command) = 'object'::text) AND (jsonb_typeof((command -> 'verb'::text)) = 'string'::text) AND (jsonb_typeof((command -> 'args'::text)) = 'object'::text) AND (((command - 'verb'::text) - 'args'::text) = '{}'::jsonb) AND (octet_length((command)::text) <= 8192)))),
    CONSTRAINT meeting_action_revision_processing_epoch_check CHECK ((processing_epoch >= 1)),
    CONSTRAINT meeting_action_revision_proposed_by_instance_check CHECK ((proposed_by_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_action_revision_revision_check CHECK ((revision >= 1)),
    CONSTRAINT meeting_action_revision_source_check CHECK ((source = ANY (ARRAY['participant'::text, 'processing'::text]))),
    CONSTRAINT meeting_action_revision_summary_check CHECK (((char_length(summary) >= 1) AND (char_length(summary) <= 2000)))
);


--
-- Name: meeting_note; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting_note (
    id uuid NOT NULL,
    meeting_id uuid NOT NULL,
    note_number integer NOT NULL,
    revision integer NOT NULL,
    body text NOT NULL,
    author_actor uuid NOT NULL,
    author_instance text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT meeting_note_author_instance_check CHECK ((author_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_note_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 20000))),
    CONSTRAINT meeting_note_note_number_check CHECK ((note_number >= 1)),
    CONSTRAINT meeting_note_revision_check CHECK ((revision >= 1))
);


--
-- Name: meeting_processing_lease; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting_processing_lease (
    meeting_id uuid NOT NULL,
    holder_actor uuid NOT NULL,
    holder_instance text NOT NULL,
    lease_epoch bigint NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    released_at timestamp with time zone,
    CONSTRAINT meeting_processing_lease_check CHECK ((expires_at > acquired_at)),
    CONSTRAINT meeting_processing_lease_holder_instance_check CHECK ((holder_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_processing_lease_lease_epoch_check CHECK ((lease_epoch >= 1))
);


--
-- Name: meeting_stream; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.meeting_stream (
    meeting_id uuid NOT NULL,
    seq bigint NOT NULL,
    kind text NOT NULL,
    actor_id uuid NOT NULL,
    client_instance text NOT NULL,
    note_number integer,
    action_number integer,
    revision integer,
    lease_epoch bigint,
    idempotency_key uuid NOT NULL,
    at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT meeting_stream_client_instance_check CHECK ((client_instance ~ '^[A-Za-z0-9][A-Za-z0-9._:/@!+=-]{0,127}$'::text)),
    CONSTRAINT meeting_stream_kind_check CHECK ((kind = ANY (ARRAY['meeting_started'::text, 'meeting_joined'::text, 'processing_acquired'::text, 'processing_taken_over'::text, 'processing_released'::text, 'note_added'::text, 'note_revised'::text, 'action_proposed'::text, 'action_revised'::text, 'action_accepted'::text, 'action_declined'::text, 'action_executed'::text, 'action_delegated'::text, 'meeting_ended'::text]))),
    CONSTRAINT meeting_stream_seq_check CHECK ((seq >= 1))
);


--
-- Name: model_role_current_pointer; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.model_role_current_pointer (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant text NOT NULL,
    role_key text NOT NULL,
    pointer_no integer NOT NULL,
    revision_id uuid NOT NULL,
    revision_no integer NOT NULL,
    role_digest text NOT NULL,
    expected_prior_revision_no integer,
    idempotency_key uuid NOT NULL,
    authority_class text NOT NULL,
    authority_grant_kind text NOT NULL,
    set_by_partner_slug text NOT NULL,
    set_by_actor_id uuid NOT NULL,
    acting_actor_id uuid NOT NULL,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT model_role_pointer_authority_class CHECK ((authority_class = 'system_authority'::text)),
    CONSTRAINT model_role_pointer_authority_grant_kind CHECK ((authority_grant_kind = 'retained_system_authority'::text)),
    CONSTRAINT model_role_pointer_creation_shape CHECK ((((pointer_no = 1) AND (expected_prior_revision_no IS NULL)) OR ((pointer_no > 1) AND (expected_prior_revision_no IS NOT NULL)))),
    CONSTRAINT model_role_pointer_digest_shape CHECK ((role_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT model_role_pointer_no_positive CHECK ((pointer_no > 0)),
    CONSTRAINT model_role_pointer_not_self_expected CHECK (((expected_prior_revision_no IS NULL) OR (expected_prior_revision_no <> revision_no))),
    CONSTRAINT model_role_pointer_revision_no_positive CHECK ((revision_no > 0)),
    CONSTRAINT model_role_pointer_role_key CHECK ((role_key = ANY (ops.model_role_keys()))),
    CONSTRAINT model_role_pointer_tenant CHECK ((tenant = ops.model_role_tenant()))
);


--
-- Name: TABLE model_role_current_pointer; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.model_role_current_pointer IS 'The append-only ledger of which revision of a role description has been current. The highest pointer_no per role is the current one; the rest are the history of what was. Each row records the compare-and-swap it won, the retained system authority it was made under, the authority LOGIN scope and, separately, the actual acting principal. It confers nothing.';


--
-- Name: model_role_revision; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.model_role_revision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant text NOT NULL,
    role_key text NOT NULL,
    revision_no integer NOT NULL,
    idempotency_key uuid NOT NULL,
    schema_version text NOT NULL,
    role_digest text NOT NULL,
    title text NOT NULL,
    mission text NOT NULL,
    minimum_strength_ref text NOT NULL,
    authority_class text NOT NULL,
    recorded_by_actor_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    created_xid xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT model_role_revision_authority_class_not_system CHECK ((authority_class <> 'system_authority'::text)),
    CONSTRAINT model_role_revision_authority_class_occupiable CHECK ((authority_class = ANY (ops.model_role_occupiable_authority_classes()))),
    CONSTRAINT model_role_revision_digest_shape CHECK ((role_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT model_role_revision_minimum_strength_ref CHECK (ops.model_role_is_ref(minimum_strength_ref)),
    CONSTRAINT model_role_revision_mission_nonempty CHECK (ops.model_role_is_nonempty_text(mission)),
    CONSTRAINT model_role_revision_no_positive CHECK ((revision_no > 0)),
    CONSTRAINT model_role_revision_role_key CHECK ((role_key = ANY (ops.model_role_keys()))),
    CONSTRAINT model_role_revision_schema_version CHECK ((schema_version = ops.model_role_schema_version())),
    CONSTRAINT model_role_revision_tenant CHECK ((tenant = ops.model_role_tenant())),
    CONSTRAINT model_role_revision_title_nonempty CHECK (ops.model_role_is_nonempty_text(title))
);


--
-- Name: TABLE model_role_revision; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.model_role_revision IS 'One immutable revision of a durable DoctorCRE v5 role description. Its digest is the one model-routing.v5.js''s defineRole computes and is recomputed from these rows at every read, write and current-pointer change. A revision is inert: it selects nothing, grants nothing, binds no occupant and qualifies no model.';


--
-- Name: model_role_revision_ref; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.model_role_revision_ref (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    revision_id uuid NOT NULL,
    field text NOT NULL,
    ordinal integer NOT NULL,
    value text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT model_role_ref_grammar CHECK (ops.model_role_is_ref(value)),
    CONSTRAINT model_role_revision_ref_field CHECK ((field = ANY (ARRAY['capability_refs'::text, 'quality_floor_refs'::text, 'task_classes'::text]))),
    CONSTRAINT model_role_revision_ref_ordinal_nonnegative CHECK ((ordinal >= 0))
);


--
-- Name: TABLE model_role_revision_ref; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.model_role_revision_ref IS 'The reference sets of one role description: the capability references its jobs may draw on, the NAMED quality floors it requires, and its task classes. Named references, never numbers: this rail sets no business floor.';


--
-- Name: model_role_revision_text; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.model_role_revision_text (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    revision_id uuid NOT NULL,
    field text NOT NULL,
    ordinal integer NOT NULL,
    value text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT model_role_revision_text_field CHECK ((field = ANY (ARRAY['evidence_requirements'::text, 'rules'::text, 'skills'::text]))),
    CONSTRAINT model_role_revision_text_ordinal_nonnegative CHECK ((ordinal >= 0)),
    CONSTRAINT model_role_revision_text_value_nonempty CHECK (ops.model_role_is_nonempty_text(value))
);


--
-- Name: TABLE model_role_revision_text; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.model_role_revision_text IS 'The ordered human-readable halves of one role description: its skills, the rules it must never break, and the evidence it requires. Order participates in the role digest, and every value is non-empty under the same ECMAScript trim rule defineRole applies.';


--
-- Name: nightly_availability_canary_source_snapshot; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.nightly_availability_canary_source_snapshot (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id uuid NOT NULL,
    attempt integer NOT NULL,
    workflow_version integer CONSTRAINT nightly_availability_canary_source_sn_workflow_version_not_null NOT NULL,
    snapshot jsonb NOT NULL,
    snapshot_digest text CONSTRAINT nightly_availability_canary_source_sna_snapshot_digest_not_null NOT NULL,
    availability_count integer CONSTRAINT nightly_availability_canary_source__availability_count_not_null NOT NULL,
    open_search_count integer CONSTRAINT nightly_availability_canary_source_s_open_search_count_not_null NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nightly_availability_canary_source_sna_availability_count_check CHECK ((availability_count >= 0)),
    CONSTRAINT nightly_availability_canary_source_snap_open_search_count_check CHECK ((open_search_count >= 0)),
    CONSTRAINT nightly_availability_canary_source_snaps_workflow_version_check CHECK ((workflow_version = 3)),
    CONSTRAINT nightly_availability_canary_source_snapsh_snapshot_digest_check CHECK ((snapshot_digest ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: notification; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.notification (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_type text NOT NULL,
    subject_ref text NOT NULL,
    event_ref uuid NOT NULL,
    event_source text NOT NULL,
