    CONSTRAINT notification_event_source_check CHECK ((event_source = ANY (ARRAY['event'::text, 'signal_event'::text]))),
    CONSTRAINT notification_reason_check CHECK (((btrim(reason) <> ''::text) AND (length(reason) <= 500))),
    CONSTRAINT notification_severity_check CHECK ((severity = ANY (ARRAY['action_required'::text, 'completion'::text, 'failure'::text]))),
    CONSTRAINT notification_subject_ref_check CHECK ((btrim(subject_ref) <> ''::text)),
    CONSTRAINT notification_subject_type_check CHECK ((btrim(subject_type) <> ''::text))
);


--
-- Name: notification_delivery; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.notification_delivery (
