    CONSTRAINT notification_delivery_check1 CHECK (((state = 'pending'::text) = (settled_at IS NULL))),
    CONSTRAINT notification_delivery_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'delivered'::text, 'suppressed_quiet_hours'::text, 'failed'::text])))
);


