    CONSTRAINT portfolio_child_revision_child_version_check CHECK ((child_version > 0))
);


--
-- Name: TABLE portfolio_child_revision; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_child_revision IS 'The four immutable DoctorCRE v5 child programs for one portfolio revision, each with its own version, content digest and applicable accepted source binding.';


--
-- Name: portfolio_node; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.portfolio_node (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    portfolio_revision_id uuid NOT NULL,
    node_ref text NOT NULL,
    node_kind text NOT NULL,
    ordinal integer NOT NULL,
    parent_ref text NOT NULL,
    child_ref text NOT NULL,
    authority_class text NOT NULL,
    effect_class text NOT NULL,
    data_class text NOT NULL,
    budget_identity text NOT NULL,
    budget_ceiling numeric NOT NULL,
    model_floor jsonb NOT NULL,
    recovery_ref text NOT NULL,
    terminal_predicate text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_node_authority_class_check CHECK ((authority_class ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT portfolio_node_budget_ceiling_check CHECK (((budget_ceiling >= (0)::numeric) AND (budget_ceiling <= ('1000000000000'::bigint)::numeric) AND ops.portfolio_canonical_number_valid(budget_ceiling))),
    CONSTRAINT portfolio_node_budget_identity_check CHECK (((btrim(budget_identity) <> ''::text) AND (char_length(budget_identity) <= 200))),
    CONSTRAINT portfolio_node_child_ref_check CHECK ((child_ref = ANY (ARRAY['foundation-and-control-plane'::text, 'assurance-fabric'::text, 'product-journeys'::text, 'rollout-and-retirement'::text]))),
    CONSTRAINT portfolio_node_data_class_check CHECK ((data_class ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT portfolio_node_effect_class_check CHECK ((effect_class ~ '^[a-z][a-z0-9_]{1,63}$'::text)),
    CONSTRAINT portfolio_node_model_floor_closed CHECK (ops.portfolio_model_floor_valid(model_floor)),
    CONSTRAINT portfolio_node_node_kind_check CHECK ((node_kind = ANY (ARRAY['portfolio'::text, 'child'::text, 'milestone'::text, 'slice'::text]))),
    CONSTRAINT portfolio_node_node_ref_check CHECK ((node_ref ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,199}$'::text)),
    CONSTRAINT portfolio_node_not_self_parent CHECK ((parent_ref <> node_ref)),
    CONSTRAINT portfolio_node_ordinal_check CHECK (((ordinal >= 1) AND (ordinal <= 21))),
    CONSTRAINT portfolio_node_parent_ref_check CHECK ((parent_ref ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,199}$'::text)),
    CONSTRAINT portfolio_node_recovery_ref_check CHECK ((recovery_ref ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,199}$'::text)),
    CONSTRAINT portfolio_node_terminal_predicate_check CHECK (((btrim(terminal_predicate) <> ''::text) AND (char_length(terminal_predicate) <= 500)))
);


--
-- Name: TABLE portfolio_node; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_node IS 'The 21 master milestone nodes of one portfolio revision, with complete typed metadata and the child program that governs each.';


--
-- Name: portfolio_node_edge; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.portfolio_node_edge (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
