    to_node_ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_edge_not_self CHECK ((from_node_ref <> to_node_ref))
);


--
-- Name: TABLE portfolio_node_edge; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_node_edge IS 'Dependency edges of one portfolio revision; from_node_ref must complete before to_node_ref.';


--
-- Name: portfolio_revision; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.portfolio_revision (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    portfolio_ref text NOT NULL,
    revision_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
    schema_version text NOT NULL,
    accepted_schema_version text NOT NULL,
    preimage jsonb NOT NULL,
    graph_digest text NOT NULL,
    accepted_digest text NOT NULL,
    node_count integer NOT NULL,
    edge_count integer NOT NULL,
    child_count integer NOT NULL,
    proposed_by_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_revision_accepted_digest_check CHECK ((accepted_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_revision_accepted_schema_version_check CHECK ((accepted_schema_version = 'doctorcre-v5-portfolio-accepted-revision.v1'::text)),
    CONSTRAINT portfolio_revision_child_count_check CHECK ((child_count = 4)),
    CONSTRAINT portfolio_revision_edge_count_check CHECK ((edge_count >= 0)),
    CONSTRAINT portfolio_revision_graph_digest_check CHECK ((graph_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_revision_node_count_check CHECK ((node_count = 21)),
    CONSTRAINT portfolio_revision_portfolio_ref_check CHECK ((portfolio_ref ~ '^[A-Za-z0-9][A-Za-z0-9:._-]{2,199}$'::text)),
    CONSTRAINT portfolio_revision_preimage_check CHECK ((jsonb_typeof(preimage) = 'object'::text)),
    CONSTRAINT portfolio_revision_revision_version_check CHECK ((revision_version > 0)),
    CONSTRAINT portfolio_revision_schema_version_check CHECK ((schema_version = 'doctorcre-v5-portfolio-revision.v1'::text))
);


--
-- Name: TABLE portfolio_revision; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_revision IS 'Append-only DoctorCRE v5 portfolio revision. graph_digest covers the settled 21-node shape; accepted_digest additionally covers every child binding and is the hash a partner accepts. Inert: creates no job, envelope, capability or schedule.';


--
-- Name: portfolio_revision_acceptance_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.portfolio_revision_acceptance_receipt (
