    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_revision_acceptance_receipt_accepted_digest_check CHECK ((accepted_digest ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE portfolio_revision_acceptance_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_revision_acceptance_receipt IS 'Private verified-partner receipt accepting one exact portfolio accepted digest. It grants no dispatch or execution authority; it only makes that revision the current accepted ancestor.';


--
-- Name: portfolio_revision_review; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.portfolio_revision_review (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    portfolio_revision_id uuid NOT NULL,
