    reviewed_digest text NOT NULL,
    verdict text NOT NULL,
    review_summary text NOT NULL,
    reviewer_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portfolio_revision_review_review_summary_check CHECK (((btrim(review_summary) <> ''::text) AND (char_length(review_summary) <= 1000))),
    CONSTRAINT portfolio_revision_review_reviewed_digest_check CHECK ((reviewed_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT portfolio_revision_review_verdict_check CHECK ((verdict = ANY (ARRAY['pass'::text, 'fail'::text])))
);


--
-- Name: TABLE portfolio_revision_review; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.portfolio_revision_review IS 'Append-only independent review of one exact accepted digest. A review naming a digest the revision does not currently have is refused at write time, so a passing review can never be carried onto different bytes.';


--
-- Name: program6_browser_action_challenge_redemption; Type: TABLE; Schema: ops; Owner: -
