    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    enforcement_status text DEFAULT 'blocked'::text NOT NULL,
    coverage_detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT rule_admission_binding_moment_check CHECK ((btrim(binding_moment) <> ''::text)),
    CONSTRAINT rule_admission_enforcement_class_check CHECK ((enforcement_class = ANY (ARRAY['machine_enforceable'::text, 'judgment_advisory'::text, 'human_only'::text]))),
    CONSTRAINT rule_admission_enforcement_status_check CHECK ((enforcement_status = ANY (ARRAY['hard_enforced'::text, 'authority_enforced'::text, 'blocked'::text]))),
    CONSTRAINT rule_admission_state_check CHECK ((state = ANY (ARRAY['draft'::text, 'admitted'::text, 'rejected'::text, 'needs_revision'::text]))),
    CONSTRAINT rule_admission_version_check CHECK ((version > 0))
);


--
-- Name: TABLE rule_admission; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_admission IS 'Normalized authority contract for one rule. AI may propose this shape; only an admitted row plus the rule activation route can make it binding.';


--
-- Name: rule_admission_reclassification_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_admission_reclassification_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key uuid CONSTRAINT rule_admission_reclassification_receip_idempotency_key_not_null NOT NULL,
    rule_id uuid NOT NULL,
    enforcement_class_before text CONSTRAINT rule_admission_reclassificati_enforcement_class_before_not_null NOT NULL,
    enforcement_class_after text CONSTRAINT rule_admission_reclassificatio_enforcement_class_after_not_null NOT NULL,
    actor_id uuid NOT NULL,
    reason text NOT NULL,
    legacy_admission text CONSTRAINT rule_admission_reclassification_recei_legacy_admission_not_null NOT NULL,
    contract_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT reclassification_class_vocabulary CHECK ((enforcement_class_after = ANY (ARRAY['machine_enforceable'::text, 'judgment_advisory'::text, 'human_only'::text]))),
    CONSTRAINT reclassification_is_a_change CHECK ((enforcement_class_before <> enforcement_class_after))
);


--
-- Name: TABLE rule_admission_reclassification_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_admission_reclassification_receipt IS 'Append-only ledger of legacy admission reclassifications (0352). Only an ACTIVE rule with no ops.rule_approval_receipt row that predates the receipt system (ops.legacy_rule_admission_note non-null) can be reclassified, and only by Joe authority. legacy_admission is NOT NULL by design: a receipted rule''s class is bound to its approval receipt and never moves through this path.';


--
-- Name: rule_amendment_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_amendment_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version_before integer NOT NULL,
    rule_version_after integer NOT NULL,
    prior_statement_hash text NOT NULL,
    new_statement text NOT NULL,
    new_statement_hash text NOT NULL,
    amended_by uuid NOT NULL,
    rationale text NOT NULL,
    contract_hash text NOT NULL,
    amended_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_admission text,
    CONSTRAINT rule_amendment_receipt_contract_hash_check CHECK ((contract_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_amendment_receipt_idempotency_key_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT rule_amendment_receipt_legacy_admission_check CHECK (((legacy_admission IS NULL) OR (btrim(legacy_admission) <> ''::text))),
    CONSTRAINT rule_amendment_receipt_new_hash_check CHECK ((new_statement_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_amendment_receipt_new_statement_check CHECK ((btrim(new_statement) <> ''::text)),
    CONSTRAINT rule_amendment_receipt_not_noop CHECK ((prior_statement_hash <> new_statement_hash)),
    CONSTRAINT rule_amendment_receipt_prior_hash_check CHECK ((prior_statement_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_amendment_receipt_rationale_check CHECK ((btrim(rationale) <> ''::text)),
    CONSTRAINT rule_amendment_receipt_rule_version_before_check CHECK ((rule_version_before > 0)),
    CONSTRAINT rule_amendment_receipt_version_check CHECK ((rule_version_after = (rule_version_before + 1)))
);


--
-- Name: TABLE rule_amendment_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_amendment_receipt IS 'Append-only ledger of statement-only amendments to an already-taught rule (proposed or active). Each row hashes the PRIOR statement (tamper-evident chain) and records the new text, the Joe-authority actor, and the rationale. human_quote, scope, taught_by and every activation/retirement field are untouched by this path -- see ops.amend_rule_statement.';


--
-- Name: COLUMN rule_amendment_receipt.legacy_admission; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.rule_amendment_receipt.legacy_admission IS 'Null for the ordinary amendment path (proposed rule, or an active rule carrying an approval receipt). Populated only when ops.amend_rule_statement amended an ACTIVE rule that has no ops.rule_approval_receipt row because it predates the receipt system entirely -- see ops.legacy_rule_admission_note. amend_rule_statement never required a receipt to function; this column exists purely so the ledger names the legacy fact rather than staying silent about it.';


--
-- Name: rule_approval_lifecycle_anchor; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_approval_lifecycle_anchor (
    approval_receipt_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    rule_version_after integer NOT NULL,
    statement_hash text NOT NULL,
    anchored_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_approval_lifecycle_anchor_rule_version_after_check CHECK ((rule_version_after > 0)),
    CONSTRAINT rule_approval_lifecycle_anchor_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: rule_approval_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_approval_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version integer NOT NULL,
    statement_hash text NOT NULL,
    actor_id uuid NOT NULL,
    policy_kind text NOT NULL,
    enforcement_status text NOT NULL,
    requested_control_keys text[] NOT NULL,
    installed_control_keys text[] NOT NULL,
    reason text NOT NULL,
    normalized_contract jsonb NOT NULL,
    contract_hash text NOT NULL,
    evidence_refs text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approved_controls_are_exact CHECK ((requested_control_keys = installed_control_keys)),
    CONSTRAINT rule_approval_contract_hash_matches CHECK ((contract_hash = encode(public.digest((normalized_contract)::text, 'sha256'::text), 'hex'::text))),
    CONSTRAINT rule_approval_receipt_contract_hash_check CHECK ((contract_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_approval_receipt_enforcement_status_check CHECK ((enforcement_status = ANY (ARRAY['hard_enforced'::text, 'authority_enforced'::text]))),
    CONSTRAINT rule_approval_receipt_evidence_refs_check CHECK ((cardinality(evidence_refs) > 0)),
    CONSTRAINT rule_approval_receipt_installed_control_keys_check CHECK ((cardinality(installed_control_keys) > 0)),
    CONSTRAINT rule_approval_receipt_normalized_contract_check CHECK ((jsonb_typeof(normalized_contract) = 'object'::text)),
    CONSTRAINT rule_approval_receipt_policy_kind_check CHECK ((policy_kind = ANY (ARRAY['machine_enforceable'::text, 'human_only'::text]))),
    CONSTRAINT rule_approval_receipt_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT rule_approval_receipt_requested_control_keys_check CHECK ((cardinality(requested_control_keys) > 0)),
    CONSTRAINT rule_approval_receipt_rule_version_check CHECK ((rule_version > 0)),
    CONSTRAINT rule_approval_receipt_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: rule_control_binding; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_control_binding (
    rule_id uuid NOT NULL,
    control_key text NOT NULL,
    statement_hash text NOT NULL,
    binding_contract jsonb NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_control_binding_binding_contract_check CHECK ((jsonb_typeof(binding_contract) = 'object'::text)),
    CONSTRAINT rule_control_binding_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE rule_control_binding; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_control_binding IS 'Owner/deployment-authored exact semantic binding. A globally installed gate cannot be claimed for an unrelated rule or changed statement.';


--
-- Name: rule_delivery_activation_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_delivery_activation_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    from_mode text NOT NULL,
    to_mode text NOT NULL,
    changed_by text NOT NULL,
    reason text NOT NULL,
    map_digest text NOT NULL,
    target_short_ids text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_delivery_activation_receipt_changed_by_check CHECK ((btrim(changed_by) <> ''::text)),
    CONSTRAINT rule_delivery_activation_receipt_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT rule_delivery_activation_receipt_target_short_ids_check CHECK ((cardinality(target_short_ids) = ANY (ARRAY[8, 9])))
);


--
-- Name: rule_delivery_activation_target; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_delivery_activation_target (
    short_id text NOT NULL,
    expected_scope text NOT NULL,
    expected_pack text NOT NULL,
    from_control text NOT NULL,
    from_enforcement_class text NOT NULL,
    from_implementation_ref text CONSTRAINT rule_delivery_activation_targe_from_implementation_ref_not_null NOT NULL,
    from_test_ref text NOT NULL,
    to_control text NOT NULL,
    to_enforcement_class text NOT NULL,
    to_implementation_ref text NOT NULL,
    to_test_ref text NOT NULL,
    map_digest text NOT NULL,
    CONSTRAINT rule_delivery_activation_target_expected_scope_check CHECK ((expected_scope = ANY (ARRAY['shared'::text, 'joe'::text, 'dell'::text]))),
    CONSTRAINT rule_delivery_activation_target_map_digest_check CHECK ((map_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_delivery_activation_target_short_id_check CHECK ((short_id ~ '^[0-9a-f]{8}$'::text))
);


--
-- Name: rule_delivery_policy; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_delivery_policy (
    singleton boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'shadow'::text NOT NULL,
    changed_by text,
    reason text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_delivery_policy_mode CHECK ((mode = ANY (ARRAY['shadow'::text, 'enforced'::text]))),
    CONSTRAINT rule_delivery_policy_singleton CHECK (singleton)
);


--
-- Name: TABLE rule_delivery_policy; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_delivery_policy IS 'shadow = compute the scoped set, report it, recite everything anyway. enforced = deliver the scoped set. Both council chairs required a week of shadow at zero unexplained misses before this row may say enforced.';


--
-- Name: rule_enforcement_point; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_enforcement_point (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_id uuid NOT NULL,
    control_key text NOT NULL,
    implementation_ref text NOT NULL,
    test_ref text NOT NULL,
    enforcement_class text NOT NULL,
    installed boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    CONSTRAINT installed_control_has_verification CHECK (((NOT installed) OR (btrim(test_ref) <> ''::text))),
    CONSTRAINT rule_enforcement_point_enforcement_class_check CHECK ((enforcement_class = ANY (ARRAY['deny_gate'::text, 'stop_gate'::text, 'schema'::text, 'surfacing'::text, 'transactional_schema'::text, 'judgment_ambient'::text])))
);


--
-- Name: rule_load_layer; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_load_layer (
    rule_id uuid NOT NULL,
    short_id text NOT NULL,
    load_layer text NOT NULL,
    packs text[] DEFAULT '{}'::text[] NOT NULL,
    scope text NOT NULL,
    why text,
    source text NOT NULL,
    map_digest text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_load_layer_known CHECK ((load_layer = ANY (ARRAY['layer0'::text, 'control'::text, 'pack'::text]))),
    CONSTRAINT rule_load_layer_layer0_reasoned CHECK (((load_layer <> 'layer0'::text) OR (COALESCE(btrim(why), ''::text) <> ''::text))),
    CONSTRAINT rule_load_layer_layer0_unconditional CHECK (((load_layer <> 'layer0'::text) OR (cardinality(packs) = 0))),
    CONSTRAINT rule_load_layer_no_wildcard CHECK ((NOT ('*'::text = ANY (packs)))),
    CONSTRAINT rule_load_layer_pack_has_pack CHECK (((load_layer <> 'pack'::text) OR (cardinality(packs) >= 1))),
    CONSTRAINT rule_load_layer_scope CHECK ((scope = ANY (ARRAY['shared'::text, 'joe'::text, 'dell'::text])))
);


--
-- Name: TABLE rule_load_layer; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_load_layer IS 'WHEN each active rule''s text reaches a session. layer0 = every boot. control = an installed deny/stop/schema control prints it at the moment it binds. pack = when the observed work matches a pack trigger. ops/rule-load-layer-check.py holds the same contract statically, including the one this table cannot see: that `control` is only honest for a rule whose enforcement_class is actually built.';


--
-- Name: rule_pack; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_pack (
    pack text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    triggers text[] NOT NULL,
    source text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT rule_pack_has_triggers CHECK ((cardinality(triggers) >= 1)),
    CONSTRAINT rule_pack_named CHECK (((btrim(pack) <> ''::text) AND (pack <> '*'::text) AND (btrim(title) <> ''::text) AND (btrim(description) <> ''::text))),
    CONSTRAINT rule_pack_no_wildcard_trigger CHECK ((NOT ('*'::text = ANY (triggers))))
);


--
-- Name: TABLE rule_pack; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.rule_pack IS 'The task packs a session can load. Triggers are OBSERVED-WORK nouns and verbs, never session names: rule 347a9ca6 forbids predicting the work from the title.';


--
-- Name: rule_retirement_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.rule_retirement_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    idempotency_key text NOT NULL,
    rule_id uuid NOT NULL,
    rule_version_before integer NOT NULL,
    rule_version_after integer NOT NULL,
    statement_hash text NOT NULL,
    previous_status text NOT NULL,
    actor_id uuid NOT NULL,
    reason text NOT NULL,
    superseded_by uuid,
    approval_receipt_id uuid,
    contract_hash text NOT NULL,
    retired_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    legacy_admission text,
    CONSTRAINT active_retirement_has_approval CHECK (((previous_status <> 'active'::text) OR (approval_receipt_id IS NOT NULL) OR (legacy_admission IS NOT NULL))),
    CONSTRAINT retirement_legacy_excludes_receipt CHECK (((legacy_admission IS NULL) OR (approval_receipt_id IS NULL))),
    CONSTRAINT rule_retirement_receipt_check CHECK ((rule_version_after = (rule_version_before + 1))),
    CONSTRAINT rule_retirement_receipt_contract_hash_check CHECK ((contract_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT rule_retirement_receipt_idempotency_key_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT rule_retirement_receipt_legacy_admission_check CHECK (((legacy_admission IS NULL) OR (btrim(legacy_admission) <> ''::text))),
    CONSTRAINT rule_retirement_receipt_previous_status_check CHECK ((previous_status = ANY (ARRAY['proposed'::text, 'active'::text]))),
    CONSTRAINT rule_retirement_receipt_reason_check CHECK ((btrim(reason) <> ''::text)),
    CONSTRAINT rule_retirement_receipt_rule_version_before_check CHECK ((rule_version_before > 0)),
    CONSTRAINT rule_retirement_receipt_statement_hash_check CHECK ((statement_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: COLUMN rule_retirement_receipt.legacy_admission; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.rule_retirement_receipt.legacy_admission IS 'Null for the ordinary receipted retirement path. Populated only when ops.retire_rule accepted an ACTIVE rule that has no ops.rule_approval_receipt row because it predates the receipt system entirely (see ops.legacy_rule_admission_note) -- records the rule''s activation time and the receipt-system cutover it predates, so the tamper-evident chain shows what actually happened rather than implying a receipt that never existed.';


--
-- Name: run; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    service_id uuid NOT NULL,
    environment text NOT NULL,
    run_key text NOT NULL,
    state text NOT NULL,
    failure_class text,
    exit_code integer,
    attempt integer DEFAULT 1 NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    duration_ms integer GENERATED ALWAYS AS (
CASE
    WHEN ((started_at IS NOT NULL) AND (ended_at IS NOT NULL)) THEN ((EXTRACT(epoch FROM (ended_at - started_at)) * (1000)::numeric))::integer
    ELSE NULL::integer
END) STORED,
    source_kind text NOT NULL,
    source_ref text NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    evidence_ref text,
    detail text,
    release_id uuid,
    budget_ms integer,
    recovery_strategy text,
    recovery_plan_ref text,
    recovery_rehearsal_bundle_id uuid,
    CONSTRAINT a_failure_names_its_class CHECK (((state <> ALL (ARRAY['failed'::text, 'timed_out'::text])) OR (failure_class IS NOT NULL))),
    CONSTRAINT a_run_that_ended_also_started CHECK (((ended_at IS NULL) OR (started_at IS NOT NULL))),
    CONSTRAINT a_terminal_run_has_ended CHECK (((state <> ALL (ARRAY['succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'skipped'::text])) OR (ended_at IS NOT NULL))),
    CONSTRAINT run_attempt_check CHECK ((attempt >= 1)),
    CONSTRAINT run_environment_check CHECK ((environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text]))),
    CONSTRAINT run_kind_check CHECK ((kind = ANY (ARRAY['job'::text, 'check'::text]))),
    CONSTRAINT run_source_kind_check CHECK ((source_kind = ANY (ARRAY['collector'::text, 'registry'::text, 'wrapper'::text, 'operator'::text]))),
    CONSTRAINT run_state_check CHECK ((state = ANY (ARRAY['scheduled'::text, 'queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'timed_out'::text, 'cancelled'::text, 'skipped'::text, 'stale'::text, 'unknown'::text])))
);


--
-- Name: TABLE run; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.run IS 'The job-run ledger and the synthetic golden-workflow ledger, one shape, as the frozen Run contract defines them. Holds NO business payload: evidence_ref points, detail is one redacted line.';


--
-- Name: scac_artifact_manifest; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.scac_artifact_manifest (
    artifact_digest text NOT NULL,
    manifest_digest text NOT NULL,
    artifact_kind text NOT NULL,
    media_type text NOT NULL,
    byte_length bigint NOT NULL,
    source_ref text NOT NULL,
    source_digest text NOT NULL,
    sbom_digest text,
    provenance_digest text NOT NULL,
    policy_epoch bigint NOT NULL,
    policy_epoch_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    root_trust_operational boolean DEFAULT false NOT NULL,
    production_enforcement_active boolean DEFAULT false NOT NULL,
    CONSTRAINT scac_artifact_manifest_artifact_digest_check CHECK ((artifact_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_manifest_artifact_kind_check CHECK ((artifact_kind = ANY (ARRAY['source_bundle'::text, 'container_image'::text, 'vm_image'::text, 'installer'::text, 'binary'::text, 'policy_bundle'::text, 'model_bundle'::text]))),
    CONSTRAINT scac_artifact_manifest_byte_length_check CHECK ((byte_length > 0)),
    CONSTRAINT scac_artifact_manifest_manifest_digest_check CHECK ((manifest_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_manifest_media_type_check CHECK ((media_type ~ '^[a-z0-9][a-z0-9.+-]*/[a-z0-9][a-z0-9.+-]{0,126}$'::text)),
    CONSTRAINT scac_artifact_manifest_policy_epoch_digest_check CHECK ((policy_epoch_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_manifest_production_enforcement_active_check CHECK ((NOT production_enforcement_active)),
    CONSTRAINT scac_artifact_manifest_provenance_digest_check CHECK ((provenance_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_manifest_root_trust_operational_check CHECK ((NOT root_trust_operational)),
    CONSTRAINT scac_artifact_manifest_sbom_digest_check CHECK (((sbom_digest IS NULL) OR (sbom_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT scac_artifact_manifest_source_digest_check CHECK ((source_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_manifest_source_ref_check CHECK (((btrim(source_ref) <> ''::text) AND (char_length(source_ref) <= 500)))
);


--
-- Name: TABLE scac_artifact_manifest; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.scac_artifact_manifest IS 'SIEP-13 immutable artifact facts. A digest or manifest row is not trust, authorization, or deploy approval.';


--
-- Name: scac_artifact_signature; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.scac_artifact_signature (
    signature_digest text NOT NULL,
    manifest_digest text NOT NULL,
    algorithm text NOT NULL,
    signer_key_digest text NOT NULL,
    public_key_bytes bytea NOT NULL,
    signature_bytes bytea NOT NULL,
    signed_payload_digest text NOT NULL,
    signature_scope text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    root_trust_operational boolean DEFAULT false NOT NULL,
    production_enforcement_active boolean DEFAULT false NOT NULL,
    CONSTRAINT scac_artifact_signature_algorithm_check CHECK ((algorithm = 'ed25519'::text)),
    CONSTRAINT scac_artifact_signature_check CHECK ((signature_digest = ('sha256:'::text || encode(public.digest(signature_bytes, 'sha256'::text), 'hex'::text)))),
    CONSTRAINT scac_artifact_signature_check1 CHECK ((signer_key_digest = ('sha256:'::text || encode(public.digest(public_key_bytes, 'sha256'::text), 'hex'::text)))),
    CONSTRAINT scac_artifact_signature_check2 CHECK ((signed_payload_digest = manifest_digest)),
    CONSTRAINT scac_artifact_signature_production_enforcement_active_check CHECK ((NOT production_enforcement_active)),
    CONSTRAINT scac_artifact_signature_public_key_bytes_check CHECK ((octet_length(public_key_bytes) = 32)),
    CONSTRAINT scac_artifact_signature_root_trust_operational_check CHECK ((NOT root_trust_operational)),
    CONSTRAINT scac_artifact_signature_signature_bytes_check CHECK ((octet_length(signature_bytes) = 64)),
    CONSTRAINT scac_artifact_signature_signature_digest_check CHECK ((signature_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_signature_signature_scope_check CHECK ((signature_scope = 'scac-artifact-manifest.v1'::text)),
    CONSTRAINT scac_artifact_signature_signed_payload_digest_check CHECK ((signed_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_artifact_signature_signer_key_digest_check CHECK ((signer_key_digest ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE scac_artifact_signature; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.scac_artifact_signature IS 'SIEP-13 raw Ed25519 signature material. Cryptographic validity is verified by the typed verifier; signer/root trust belongs to SIEP-14.';


--
-- Name: scac_artifact_transparency_entry; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.scac_artifact_transparency_entry (
    entry_no bigint NOT NULL,
    entry_digest text NOT NULL,
    previous_entry_digest text,
    manifest_digest text NOT NULL,
    signature_digest text NOT NULL,
    statement_digest text NOT NULL,
    entry_kind text NOT NULL,
    included_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    root_trust_operational boolean DEFAULT false CONSTRAINT scac_artifact_transparency_entr_root_trust_operational_not_null NOT NULL,
    production_enforcement_active boolean DEFAULT false CONSTRAINT scac_artifact_transparency__production_enforcement_act_not_null NOT NULL,
