    CONSTRAINT scac_root_custodian_attestation_check CHECK ((custodian_key_digest = ('sha256:'::text || encode(public.digest(public_key_bytes, 'sha256'::text), 'hex'::text)))),
    CONSTRAINT scac_root_custodian_attestation_check1 CHECK ((signature_digest = ('sha256:'::text || encode(public.digest(signature_bytes, 'sha256'::text), 'hex'::text)))),
    CONSTRAINT scac_root_custodian_attestation_custodian_key_digest_check CHECK ((custodian_key_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
