    CONSTRAINT scac_root_custodian_attestation_public_key_bytes_check CHECK ((octet_length(public_key_bytes) = 32)),
    CONSTRAINT scac_root_custodian_attestation_signature_bytes_check CHECK ((octet_length(signature_bytes) = 64)),
    CONSTRAINT scac_root_custodian_attestation_signature_digest_check CHECK ((signature_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_root_custodian_attestation_signed_payload_digest_check CHECK ((signed_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_root_custodian_attestation_verifier_contract_check CHECK ((verifier_contract = 'mcp-server/src/root-trust.js'::text))
);


