--
-- Name: scac_root_trust_event; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.scac_root_trust_event (
    event_no bigint NOT NULL,
    event_digest text NOT NULL,
    previous_event_digest text,
    action text NOT NULL,
    subject_key_digest text NOT NULL,
    replacement_key_digest text,
    threshold integer NOT NULL,
    custodian_set_digest text NOT NULL,
    custodian_approval_digests text[] NOT NULL,
    recovery_receipt_digest text,
    policy_epoch bigint NOT NULL,
    policy_epoch_digest text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    production_trust_active boolean DEFAULT false NOT NULL,
    CONSTRAINT scac_root_trust_event_action_check CHECK ((action = ANY (ARRAY['establish'::text, 'rotate'::text, 'revoke'::text, 'recovery_drill'::text]))),
    CONSTRAINT scac_root_trust_event_check CHECK (((cardinality(custodian_approval_digests) >= threshold) AND (cardinality(custodian_approval_digests) <= 12))),
    CONSTRAINT scac_root_trust_event_check1 CHECK ((((event_no = 1) AND (previous_event_digest IS NULL)) OR ((event_no > 1) AND (previous_event_digest IS NOT NULL)))),
    CONSTRAINT scac_root_trust_event_check2 CHECK (((replacement_key_digest IS NULL) OR (replacement_key_digest <> subject_key_digest))),
    CONSTRAINT scac_root_trust_event_check3 CHECK ((((action = 'rotate'::text) AND (replacement_key_digest IS NOT NULL) AND (recovery_receipt_digest IS NULL)) OR ((action = 'recovery_drill'::text) AND (replacement_key_digest IS NULL) AND (recovery_receipt_digest IS NOT NULL)) OR ((action = ANY (ARRAY['establish'::text, 'revoke'::text])) AND (replacement_key_digest IS NULL) AND (recovery_receipt_digest IS NULL)))),
    CONSTRAINT scac_root_trust_event_custodian_set_digest_check CHECK ((custodian_set_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_root_trust_event_event_digest_check CHECK ((event_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_root_trust_event_event_no_check CHECK ((event_no > 0)),
    CONSTRAINT scac_root_trust_event_policy_epoch_digest_check CHECK ((policy_epoch_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT scac_root_trust_event_production_trust_active_check CHECK ((NOT production_trust_active)),
    CONSTRAINT scac_root_trust_event_recovery_receipt_digest_check CHECK (((recovery_receipt_digest IS NULL) OR (recovery_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT scac_root_trust_event_threshold_check CHECK (((threshold >= 2) AND (threshold <= 8)))
);


