--
-- Name: TABLE service_dependency; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.service_dependency IS 'Upstream/downstream blast radius. The BDUF requires every dependency graphic to have an accessible list equivalent; this table IS that list, and the graphic is derived from it rather than the other way round.';


--
-- Name: service_environment; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.service_environment (
    service_id uuid NOT NULL,
    environment text NOT NULL,
    endpoint text,
    deploy_mechanism text,
    expected_cadence_seconds integer,
    cadence_grace_seconds integer DEFAULT 0 NOT NULL,
    notes text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT service_environment_cadence_grace_seconds_check CHECK ((cadence_grace_seconds >= 0)),
    CONSTRAINT service_environment_environment_check CHECK ((environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text]))),
    CONSTRAINT service_environment_expected_cadence_seconds_check CHECK (((expected_cadence_seconds IS NULL) OR (expected_cadence_seconds > 0)))
);


--
-- Name: COLUMN service_environment.expected_cadence_seconds; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.service_environment.expected_cadence_seconds IS 'How long an observation of this service in this environment stays believable when the run does not declare its own expiry. NULL means unscheduled, which makes every observation unknown rather than fresh — deliberately.';


--
-- Name: settings_change; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.settings_change (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text NOT NULL,
    target text NOT NULL,
    reason text NOT NULL,
    outcome text NOT NULL,
    session_id text NOT NULL,
    actor text,
    command text,
    environment text,
    correlation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT a_reason_has_to_say_something CHECK ((length(btrim(reason)) >= 8)),
    CONSTRAINT settings_change_environment_check CHECK (((environment IS NULL) OR (environment = ANY (ARRAY['local'::text, 'rehearsal'::text, 'staging'::text, 'production'::text])))),
    CONSTRAINT settings_change_outcome_check CHECK ((outcome = ANY (ARRAY['applied'::text, 'failed'::text])))
);


--
-- Name: TABLE settings_change; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.settings_change IS 'Every change to a control plane this system does not own — GitHub rulesets, Actions variables and secrets, branch protection, launchd jobs, git config, Worker secrets. Written by hooks/settings-change-gate.py AT THE MOMENT OF THE CHANGE, because a record that waits for the session to finish dies with it.';


--
-- Name: COLUMN settings_change.reason; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON COLUMN ops.settings_change.reason IS 'Why the change was made, in the words of whoever made it. The 2026-08-14 ruleset incident was not a missing change log — it was a missing REASON: the change itself was discoverable from GitHub''s own version history within minutes, and still nobody could tell an authorised change from tampering.';


--
-- Name: siep_command_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_command_receipt (
    idempotency_key uuid NOT NULL,
    verb text NOT NULL,
    package_key text NOT NULL,
    request_digest text NOT NULL,
    result jsonb NOT NULL,
    recorded_actor_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT siep_command_receipt_never_stores_lease_token CHECK ((NOT (result ? 'lease_token'::text))),
    CONSTRAINT siep_command_receipt_request_digest_check CHECK ((request_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT siep_command_receipt_result_check CHECK ((jsonb_typeof(result) = 'object'::text)),
    CONSTRAINT siep_command_receipt_verb_check CHECK ((verb = ANY (ARRAY['claim'::text, 'transition'::text, 'acquire_lane'::text, 'release_lane'::text])))
);


--
-- Name: siep_component_alias; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_component_alias (
    alias_key text NOT NULL,
    package_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT siep_component_alias_alias_key_check CHECK ((alias_key ~ '^(SCAC-[0-9]{2}|MPE-17[A-H])$'::text))
);


--
-- Name: siep_evidence_link; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_evidence_link (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    package_key text NOT NULL,
    evidence_kind text NOT NULL,
    ledger_kind text NOT NULL,
    ledger_id uuid NOT NULL,
    work_request_version integer NOT NULL,
    manifest_digest text NOT NULL,
    evidence_digest text NOT NULL,
    note text NOT NULL,
    linked_actor_id uuid NOT NULL,
    attested_session_principal text NOT NULL,
    source_observed_at timestamp with time zone NOT NULL,
    idempotency_key uuid NOT NULL,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT siep_evidence_link_evidence_digest_check CHECK ((evidence_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT siep_evidence_link_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['source'::text, 'tests'::text, 'migration'::text, 'deploy'::text, 'readback'::text, 'live_readback'::text, 'rollback'::text, 'independent_review'::text, 'joe_approval'::text, 'joe_go_no_go'::text, 'zero_unresolved_findings'::text, 'zero_blockers'::text, 'two_clean_audit_cycles'::text, 'material_fix'::text]))),
    CONSTRAINT siep_evidence_link_ledger_kind_check CHECK ((ledger_kind = ANY (ARRAY['job_receipt'::text, 'decision_event'::text]))),
    CONSTRAINT siep_evidence_link_manifest_digest_check CHECK ((manifest_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT siep_evidence_link_note_check CHECK (((note ~ '^safe:[a-z0-9][a-z0-9:_./-]*$'::text) AND (char_length(note) <= 300))),
    CONSTRAINT siep_evidence_link_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: TABLE siep_evidence_link; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.siep_evidence_link IS 'Typed links into existing receipt, event, decision, and finding ledgers. Evidence bodies are never copied here.';


--
-- Name: siep_job_evidence_binding; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_job_evidence_binding (
    job_id uuid NOT NULL,
    package_key text NOT NULL,
    work_request_version integer NOT NULL,
    manifest_digest text NOT NULL,
    evidence_kind text NOT NULL,
    definition_key text NOT NULL,
    definition_version integer NOT NULL,
    bound_by_actor_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    bound_at timestamp with time zone DEFAULT now() NOT NULL,
    engineering_contract_version text,
    CONSTRAINT siep_job_evidence_binding_check CHECK (((definition_key = 'engineering-slice'::text) AND (definition_version = 1))),
    CONSTRAINT siep_job_evidence_binding_engineering_contract_check CHECK (((engineering_contract_version IS NULL) OR (engineering_contract_version = 'engineering-review.v1'::text))),
    CONSTRAINT siep_job_evidence_binding_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['source'::text, 'tests'::text, 'migration'::text, 'deploy'::text, 'readback'::text, 'live_readback'::text, 'rollback'::text, 'independent_review'::text, 'zero_unresolved_findings'::text, 'zero_blockers'::text, 'two_clean_audit_cycles'::text, 'material_fix'::text]))),
    CONSTRAINT siep_job_evidence_binding_manifest_digest_check CHECK ((manifest_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT siep_job_evidence_binding_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: siep_lane_lock; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_lane_lock (
    lane_key text NOT NULL,
    package_key text NOT NULL,
    work_request_version integer NOT NULL,
    holder_actor_id uuid NOT NULL,
    executor_tier text NOT NULL,
    session_ref text NOT NULL,
    lease_token uuid NOT NULL,
    acquired_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    idempotency_key uuid NOT NULL,
    CONSTRAINT siep_lane_lock_check CHECK ((expires_at > acquired_at)),
    CONSTRAINT siep_lane_lock_executor_tier_check CHECK ((executor_tier = ANY (ARRAY['luna'::text, 'terra'::text, 'sol'::text, 'main'::text]))),
    CONSTRAINT siep_lane_lock_lane_key_check CHECK ((lane_key = ANY (ARRAY['program-control'::text, 'heavy-build'::text, 'scac-core'::text, 'dell-mpe'::text]))),
    CONSTRAINT siep_lane_lock_session_ref_check CHECK (((btrim(session_ref) <> ''::text) AND (char_length(session_ref) <= 300))),
    CONSTRAINT siep_lane_lock_work_request_version_check CHECK ((work_request_version > 0))
);


--
-- Name: siep_package_contract; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_package_contract (
    package_key text NOT NULL,
    work_request_id uuid NOT NULL,
    lane_key text NOT NULL,
    minimum_executor_tier text NOT NULL,
    test_contract jsonb NOT NULL,
    delivery_contract jsonb NOT NULL,
    rollback_contract jsonb NOT NULL,
    required_evidence_kinds text[] NOT NULL,
    approval_gate text DEFAULT 'none'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT siep_package_contract_approval_gate_check CHECK ((approval_gate = ANY (ARRAY['none'::text, 'joe_approval'::text, 'joe_go_no_go'::text]))),
    CONSTRAINT siep_package_contract_delivery_contract_check CHECK (((jsonb_typeof(delivery_contract) = 'object'::text) AND (delivery_contract ?& ARRAY['source'::text, 'migration'::text, 'deploy'::text, 'readback'::text, 'rollback'::text]))),
    CONSTRAINT siep_package_contract_lane_key_check CHECK ((lane_key = ANY (ARRAY['program-control'::text, 'heavy-build'::text, 'scac-core'::text, 'dell-mpe'::text]))),
    CONSTRAINT siep_package_contract_minimum_executor_tier_check CHECK ((minimum_executor_tier = ANY (ARRAY['luna'::text, 'terra'::text, 'sol'::text, 'main'::text, 'human_authority'::text]))),
    CONSTRAINT siep_package_contract_package_key_check CHECK ((package_key ~ '^(B0|00|0[1-5]|06A|06B|1[0-9]|2[0-3]|24A|24B|25|26|3[0-7]|4[0-4])$'::text)),
    CONSTRAINT siep_package_contract_required_evidence_kinds_check CHECK ((cardinality(required_evidence_kinds) > 0)),
    CONSTRAINT siep_package_contract_rollback_contract_check CHECK ((jsonb_typeof(rollback_contract) = 'object'::text)),
    CONSTRAINT siep_package_contract_test_contract_check CHECK ((jsonb_typeof(test_contract) = 'object'::text))
);


--
-- Name: TABLE siep_package_contract; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.siep_package_contract IS 'Immutable SIEP package contract linked one-to-one to the sole lifecycle row in ops.work_request; it is not a task tracker.';


--
-- Name: siep_program_dependency; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.siep_program_dependency (
    package_key text NOT NULL,
    depends_on_package_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT siep_program_dependency_check CHECK ((package_key <> depends_on_package_key))
);


--
-- Name: slice_checkpoint; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.slice_checkpoint (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slice_ref text NOT NULL,
    checkpoint_ref text NOT NULL,
    checkpoint_digest text NOT NULL,
    base_commit_sha text NOT NULL,
    worktree_ref text NOT NULL,
    lease_id uuid NOT NULL,
    next_step_ref text NOT NULL,
    completed_step_refs text[] DEFAULT '{}'::text[] NOT NULL,
    record_evidence_refs text[] DEFAULT '{}'::text[] NOT NULL,
    reconstruction_source text NOT NULL,
    inherited_transcript_used boolean DEFAULT false NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    written_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT slice_checkpoint_base_commit_sha_check CHECK ((base_commit_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT slice_checkpoint_checkpoint_digest_check CHECK ((checkpoint_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT slice_checkpoint_checkpoint_ref_check CHECK ((checkpoint_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text)),
    CONSTRAINT slice_checkpoint_completed_step_refs_check CHECK (ops.program_controller_typed_refs(completed_step_refs)),
    CONSTRAINT slice_checkpoint_next_step_ref_check CHECK ((next_step_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text)),
    CONSTRAINT slice_checkpoint_reconstruction_source_check CHECK ((reconstruction_source = ANY (ARRAY['durable_records'::text, 'inherited_transcript'::text]))),
    CONSTRAINT slice_checkpoint_record_evidence_refs_check CHECK (ops.program_controller_typed_refs(record_evidence_refs)),
    CONSTRAINT slice_checkpoint_slice_ref_check CHECK ((slice_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text)),
    CONSTRAINT slice_checkpoint_worktree_ref_check CHECK ((worktree_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text))
);


--
-- Name: slice_source_lease; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.slice_source_lease (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slice_ref text NOT NULL,
    worktree_ref text NOT NULL,
    worktree_path text NOT NULL,
    branch_ref text NOT NULL,
    base_commit_sha text NOT NULL,
    source_paths text[] NOT NULL,
    database_disposition text NOT NULL,
    database_resources text[] DEFAULT '{}'::text[] NOT NULL,
    serialized_surfaces text[] DEFAULT '{}'::text[] NOT NULL,
    repository_actions text[] DEFAULT '{}'::text[] NOT NULL,
    reuse_disposition text NOT NULL,
    model_roles text[] DEFAULT '{}'::text[] NOT NULL,
    held_by_actor text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    correlation_id text,
    CONSTRAINT slice_source_lease_base_commit_sha_check CHECK ((base_commit_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT slice_source_lease_branch_ref_check CHECK ((branch_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text)),
    CONSTRAINT slice_source_lease_database_disposition_check CHECK ((database_disposition = ANY (ARRAY['approved_sanitized_parent'::text, 'equal_trust_branch'::text, 'hermetic_fixture'::text, 'no_database'::text, 'schema_only_fixture'::text, 'raw_production_fork'::text]))),
    CONSTRAINT slice_source_lease_database_resources_check CHECK (ops.program_controller_typed_refs(database_resources)),
    CONSTRAINT slice_source_lease_held_by_actor_check CHECK ((length(btrim(held_by_actor)) > 0)),
    CONSTRAINT slice_source_lease_model_roles_check CHECK ((model_roles <@ ARRAY['author'::text, 'observer'::text, 'reviewer'::text])),
    CONSTRAINT slice_source_lease_repository_actions_check CHECK ((repository_actions <@ ARRAY['repository:create-worktree'::text, 'repository:create-branch'::text, 'repository:write-declared-scope'::text, 'repository:run-checks'::text, 'repository:commit'::text, 'repository:push-branch'::text, 'repository:open-pr'::text])),
    CONSTRAINT slice_source_lease_reuse_disposition_check CHECK ((reuse_disposition = ANY (ARRAY['extend'::text, 'replace'::text, 'reuse'::text]))),
    CONSTRAINT slice_source_lease_serialized_surfaces_check CHECK ((serialized_surfaces <@ ARRAY['deployment_activation_retirement_controller'::text, 'generated_schema_or_seal'::text, 'migration_number_frontier'::text, 'scac_mutation_registry'::text, 'shared_interface_or_command_contract'::text, 'shared_source_inventory_fixture'::text])),
    CONSTRAINT slice_source_lease_slice_ref_check CHECK ((slice_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text)),
    CONSTRAINT slice_source_lease_source_paths_check CHECK ((cardinality(source_paths) > 0)),
    CONSTRAINT slice_source_lease_worktree_path_check CHECK ((length(btrim(worktree_path)) > 0)),
    CONSTRAINT slice_source_lease_worktree_ref_check CHECK ((worktree_ref ~ '^[a-z][a-z0-9-]*:[A-Za-z0-9][A-Za-z0-9._/-]{0,127}$'::text))
);


--
-- Name: source_merge_plan_scope; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.source_merge_plan_scope (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    work_request_id uuid NOT NULL,
    accepted_plan_id uuid NOT NULL,
    acceptance_receipt_id uuid NOT NULL,
    accepted_by_actor_id uuid NOT NULL,
    repository text NOT NULL,
    base_branch text NOT NULL,
    authorized_paths jsonb NOT NULL,
    scope_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT source_merge_plan_scope_authorized_paths_check CHECK (((jsonb_typeof(authorized_paths) = 'array'::text) AND (jsonb_array_length(authorized_paths) > 0))),
    CONSTRAINT source_merge_plan_scope_base_branch_check CHECK ((base_branch = 'main'::text)),
    CONSTRAINT source_merge_plan_scope_organization_tenant_id_check CHECK ((btrim(organization_tenant_id) <> ''::text)),
    CONSTRAINT source_merge_plan_scope_repository_check CHECK ((repository = 'jbookout/carr-system'::text)),
    CONSTRAINT source_merge_plan_scope_scope_digest_check CHECK ((scope_digest ~ '^sha256:[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE source_merge_plan_scope; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.source_merge_plan_scope IS 'Append-only exact file boundary copied from the accepted plan hash at the human plan-acceptance transaction. It authorizes only later source merge eligibility; lease claims and reviewer facts cannot add paths.';


--
-- Name: sourced_work_request_outcome_feedback; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_outcome_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    feedback_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
    work_request_version integer CONSTRAINT sourced_work_request_outcome_feed_work_request_version_not_null NOT NULL,
    plan_id uuid NOT NULL,
    plan_acceptance_receipt_id uuid CONSTRAINT sourced_work_request_outcom_plan_acceptance_receipt_id_not_null NOT NULL,
    preimage jsonb NOT NULL,
    criterion_results jsonb CONSTRAINT sourced_work_request_outcome_feedbac_criterion_results_not_null NOT NULL,
    evidence_refs jsonb NOT NULL,
    outcome text NOT NULL,
    blocker_code text NOT NULL,
    result_summary text NOT NULL,
    observed_minutes integer NOT NULL,
    interaction_surface text CONSTRAINT sourced_work_request_outcome_feedb_interaction_surface_not_null NOT NULL,
    heavy_session_used boolean CONSTRAINT sourced_work_request_outcome_feedba_heavy_session_used_not_null NOT NULL,
    manual_context_transfers integer CONSTRAINT sourced_work_request_outcome__manual_context_transfers_not_null NOT NULL,
    feedback_hash text NOT NULL,
    feedback_ref text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sourced_work_request_outcome_fee_manual_context_transfers_check CHECK (((manual_context_transfers >= 0) AND (manual_context_transfers <= 100))),
    CONSTRAINT sourced_work_request_outcome_feedbac_work_request_version_check CHECK ((work_request_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_blocker_code_check CHECK ((blocker_code = ANY (ARRAY['none'::text, 'evidence_missing'::text, 'criterion_not_met'::text, 'external_dependency'::text, 'system_error'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_criterion_results_check CHECK ((jsonb_typeof(criterion_results) = 'array'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_evidence_refs_check CHECK ((jsonb_typeof(evidence_refs) = 'array'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_hash_check CHECK ((feedback_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_ref_check CHECK ((feedback_ref ~ '^OUTCOME-[0-9a-f]{12}-v[1-9][0-9]*$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_feedback_version_check CHECK ((feedback_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_interaction_surface_check CHECK ((interaction_surface = ANY (ARRAY['workspace'::text, 'control_room'::text, 'mcp'::text, 'codex'::text, 'claude_code'::text, 'other'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_observed_minutes_check CHECK (((observed_minutes >= 1) AND (observed_minutes <= 1440))),
    CONSTRAINT sourced_work_request_outcome_feedback_outcome_check CHECK ((outcome = ANY (ARRAY['criteria_met'::text, 'criteria_not_met'::text, 'inconclusive'::text]))),
    CONSTRAINT sourced_work_request_outcome_feedback_preimage_check CHECK ((jsonb_typeof(preimage) = 'object'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_result_summary_check CHECK (((btrim(result_summary) <> ''::text) AND (char_length(result_summary) <= 500)))
);


--
-- Name: TABLE sourced_work_request_outcome_feedback; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.sourced_work_request_outcome_feedback IS 'Append-only bounded Program 6 outcome-feedback proposal. It binds every criterion result, evidence reference, blocker and measured operating fact to one accepted ready plan; it is not a claim of execution.';


--
-- Name: sourced_work_request_outcome_feedback_acceptance_receipt; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_outcome_feedback_acceptance_receipt (
    id uuid DEFAULT gen_random_uuid() CONSTRAINT sourced_work_request_outcome_feedback_acceptance_re_id_not_null NOT NULL,
    work_request_id uuid CONSTRAINT sourced_work_request_outcome_feedback__work_request_id_not_null NOT NULL,
    feedback_id uuid CONSTRAINT sourced_work_request_outcome_feedback_acce_feedback_id_not_null NOT NULL,
    idempotency_key uuid CONSTRAINT sourced_work_request_outcome_feedback__idempotency_key_not_null NOT NULL,
    base_version integer CONSTRAINT sourced_work_request_outcome_feedback_acc_base_version_not_null NOT NULL,
    feedback_hash text CONSTRAINT sourced_work_request_outcome_feedback_ac_feedback_hash_not_null NOT NULL,
    accepted_by_actor_id uuid CONSTRAINT sourced_work_request_outcome_feed_accepted_by_actor_id_not_null NOT NULL,
    accepted_at timestamp with time zone DEFAULT clock_timestamp() CONSTRAINT sourced_work_request_outcome_feedback_acce_accepted_at_not_null NOT NULL,
    result_version integer CONSTRAINT sourced_work_request_outcome_feedback_a_result_version_not_null NOT NULL,
    CONSTRAINT sourced_work_request_outcome_feedback_acce_result_version_check CHECK ((result_version > 0)),
    CONSTRAINT sourced_work_request_outcome_feedback_accep_feedback_hash_check CHECK ((feedback_hash ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT sourced_work_request_outcome_feedback_accept_base_version_check CHECK ((base_version > 0))
);


--
-- Name: TABLE sourced_work_request_outcome_feedback_acceptance_receipt; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON TABLE ops.sourced_work_request_outcome_feedback_acceptance_receipt IS 'Private append-only human-authority receipt for an outcome-feedback proposal. Independence is the routine-writer proposal versus human acceptance; acceptance leaves the Work Request ready and grants no execution authority.';


--
-- Name: sourced_work_request_plan; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.sourced_work_request_plan (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_request_id uuid NOT NULL,
    plan_version integer NOT NULL,
    idempotency_key uuid NOT NULL,
