    CONSTRAINT staging_deployment_attempt_git_sha_check CHECK ((git_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT staging_deployment_attempt_provider_check CHECK ((provider = 'cloudflare-workers'::text)),
