    decision text NOT NULL,
    decision_reason text NOT NULL,
    brief_version text NOT NULL,
    canonical_dataset_version text NOT NULL,
    selected_prototype_id text NOT NULL,
    component_registry_version text NOT NULL,
    route_version integer NOT NULL,
    provider_rights_receipt_ids jsonb NOT NULL,
    mobile_test_evidence jsonb NOT NULL,
