    required_checks jsonb NOT NULL,
    receipt_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tour_map_promotion_receipt_check CHECK (((jsonb_typeof(mobile_test_evidence) = 'object'::text) AND (jsonb_typeof(native_navigation_test_evidence) = 'object'::text) AND (jsonb_typeof(offline_test_evidence) = 'object'::text) AND (jsonb_typeof(required_checks) = 'object'::text))),
    CONSTRAINT tour_map_promotion_receipt_decision_check CHECK ((decision = ANY (ARRAY['approved'::text, 'rejected'::text]))),
    CONSTRAINT tour_map_promotion_receipt_decision_reason_check CHECK (((char_length(btrim(decision_reason)) >= 1) AND (char_length(btrim(decision_reason)) <= 500))),
