    CONSTRAINT tour_map_promotion_receipt_receipt_digest_check CHECK ((receipt_digest ~ '^sha256:[a-f0-9]{64}$'::text)),
    CONSTRAINT tour_map_promotion_receipt_route_version_check CHECK ((route_version > 0))
);


--
-- Name: tour_map_promotion_receipt_receipt_sequence_seq; Type: SEQUENCE; Schema: ops; Owner: -
--

ALTER TABLE ops.tour_map_promotion_receipt ALTER COLUMN receipt_sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME ops.tour_map_promotion_receipt_receipt_sequence_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


