    CONSTRAINT tour_route_stop_check1 CHECK ((((appointment_start IS NULL) AND (appointment_end IS NULL) AND (NOT locked_appointment)) OR ((appointment_start IS NOT NULL) AND (appointment_end IS NOT NULL) AND (appointment_end >= appointment_start)))),
    CONSTRAINT tour_route_stop_dwell_minutes_check CHECK (((dwell_minutes >= 0) AND (dwell_minutes <= 1440))),
