    CONSTRAINT tour_route_stop_transition_disposition_check CHECK ((disposition = ANY (ARRAY['unchanged'::text, 'reordered'::text, 'removed'::text, 'held'::text, 'excluded'::text, 'merged'::text, 'added'::text])))
);


