--
-- Name: v_capability_program_next; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_capability_program_next AS
 SELECT w.id,
    w.ref,
    w.state,
    w.title,
    w.desired_outcome,
    w.acceptance_criteria,
    w.origin_ref,
    w.requester_actor,
    w.owner_actor,
    w.executor_actor,
    w.blocker_code,
    w.blocker_detail,
    w.verification_accepted_at,
    w.verification_evidence_ref,
    w.exit_reason,
    w.superseded_by,
    w.captured_at,
    w.claimed_at,
    w.started_at,
    w.closed_at,
    w.updated_at,
    w.correlation_id,
    w.program_key,
    w.program_ordinal,
    w.disposition,
    w.existing_status,
    w.project_context,
    w.completion_kind,
    w.completion_evidence,
    w.version,
    w.shape_disposition,
    w.shape_fixed_surface_ref,
    w.shape_rationale,
    w.shape_decided_by_actor_id,
    w.shape_decided_at,
    w.organization_tenant_id,
    w.doctrine_section_id,
    w.doctrine_revision_id,
    w.capture_idempotency_key,
    w.sourced_capture_sequence,
    w.triage_classification,
    w.triaged_by_actor_id,
    w.triaged_at
   FROM ops.work_request w
  WHERE ((w.program_key IS NOT NULL) AND (w.program_key <> 'carr-system-integrity-elimination-v1'::text) AND (w.state <> 'confirmed_closed'::text) AND (NOT (EXISTS ( SELECT 1
           FROM ops.work_request p
          WHERE ((p.program_key = w.program_key) AND (p.program_ordinal < w.program_ordinal) AND (p.state <> 'confirmed_closed'::text))))))
UNION ALL
 SELECT w.id,
    w.ref,
    w.state,
    w.title,
    w.desired_outcome,
    w.acceptance_criteria,
    w.origin_ref,
    w.requester_actor,
    w.owner_actor,
    w.executor_actor,
    w.blocker_code,
    w.blocker_detail,
    w.verification_accepted_at,
    w.verification_evidence_ref,
    w.exit_reason,
    w.superseded_by,
    w.captured_at,
    w.claimed_at,
    w.started_at,
    w.closed_at,
    w.updated_at,
    w.correlation_id,
    w.program_key,
    w.program_ordinal,
    w.disposition,
    w.existing_status,
    w.project_context,
    w.completion_kind,
    w.completion_evidence,
    w.version,
    w.shape_disposition,
    w.shape_fixed_surface_ref,
    w.shape_rationale,
    w.shape_decided_by_actor_id,
    w.shape_decided_at,
    w.organization_tenant_id,
    w.doctrine_section_id,
    w.doctrine_revision_id,
    w.capture_idempotency_key,
    w.sourced_capture_sequence,
    w.triage_classification,
    w.triaged_by_actor_id,
    w.triaged_at
   FROM (ops.work_request w
     JOIN ops.siep_package_contract c ON ((c.work_request_id = w.id)))
  WHERE ((w.state <> 'confirmed_closed'::text) AND (NOT (EXISTS ( SELECT 1
           FROM ((ops.siep_program_dependency d
             JOIN ops.siep_package_contract dc ON ((dc.package_key = d.depends_on_package_key)))
             JOIN ops.work_request dw ON ((dw.id = dc.work_request_id)))
          WHERE ((d.package_key = c.package_key) AND (dw.state <> 'confirmed_closed'::text))))));


--
-- Name: VIEW v_capability_program_next; Type: COMMENT; Schema: ops; Owner: -
--

COMMENT ON VIEW ops.v_capability_program_next IS 'Exactly the first not-yet-verified Work Request in each ordered capability program. Blocked, failed, needs-Joe and verification rows remain current; later rows never skip them.';


--
-- Name: v_check_run; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.v_check_run AS
 SELECT id,
    correlation_id,
