    environment,
    run_key,
    state,
    failure_class,
    exit_code,
    attempt,
    started_at,
    ended_at,
    duration_ms,
    source_kind,
    source_ref,
    observed_at,
    expires_at,
    evidence_ref,
    detail
   FROM ops.run
  WHERE (kind = 'check'::text);


