    CONSTRAINT work_shape_revision_mind_changing_fact_check CHECK ((btrim(mind_changing_fact) <> ''::text)),
    CONSTRAINT work_shape_revision_repo_searches_check CHECK ((jsonb_typeof(repo_searches) = 'array'::text)),
