    CONSTRAINT claude_continuity_checkpoint_compaction_generation_check CHECK (((compaction_generation >= 0) AND (compaction_generation <= '9007199254740991'::bigint))),
    CONSTRAINT claude_continuity_checkpoint_cursor_check CHECK (((jsonb_typeof(cursor) = 'object'::text) AND (octet_length((cursor)::text) <= 2000))),
    CONSTRAINT claude_continuity_checkpoint_state_check CHECK (((jsonb_typeof(state) = 'object'::text) AND (octet_length((state)::text) <= 24000))),
    CONSTRAINT claude_continuity_checkpoint_transcript_digest_check CHECK (((transcript_digest IS NULL) OR (transcript_digest ~ '^[0-9a-f]{64}$'::text)))
);


