    CONSTRAINT claude_continuity_event_telemetry_check CHECK (((telemetry IS NULL) OR ((jsonb_typeof(telemetry) = 'object'::text) AND (octet_length((telemetry)::text) <= 4000)))),
    CONSTRAINT claude_continuity_event_transcript_digest_check CHECK (((transcript_digest IS NULL) OR (transcript_digest ~ '^[0-9a-f]{64}$'::text)))
);


--
-- Name: claude_continuity_leaf; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.claude_continuity_leaf (
