    CONSTRAINT claude_continuity_leaf_latest_model_id_check CHECK (((latest_model_id IS NULL) OR ((length(btrim(latest_model_id)) >= 1) AND (length(btrim(latest_model_id)) <= 200)))),
    CONSTRAINT claude_continuity_leaf_native_agent_id_check CHECK (((native_agent_id IS NULL) OR ((length(btrim(native_agent_id)) >= 1) AND (length(btrim(native_agent_id)) <= 200)))),
    CONSTRAINT claude_continuity_leaf_parent_session_id_check CHECK (((parent_session_id IS NULL) OR ((length(btrim(parent_session_id)) >= 1) AND (length(btrim(parent_session_id)) <= 200)))),
    CONSTRAINT claude_continuity_leaf_project_affinity_check CHECK (((length(btrim(project_affinity)) >= 1) AND (length(btrim(project_affinity)) <= 500))),
    CONSTRAINT claude_continuity_leaf_session_id_check CHECK ((session_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$'::text)),
    CONSTRAINT claude_continuity_leaf_transcript_path_digest_check CHECK ((transcript_path_digest ~ '^[0-9a-f]{64}$'::text))
);


