    CONSTRAINT codex_continuity_checkpoint_checkpoint_version_check CHECK ((checkpoint_version > 0)),
    CONSTRAINT codex_continuity_checkpoint_cursor_check CHECK (((cursor IS NULL) OR ((jsonb_typeof(cursor) = 'object'::text) AND (octet_length((cursor)::text) <= 2000)))),
    CONSTRAINT codex_continuity_checkpoint_cwd_check CHECK (((length(btrim(cwd)) >= 1) AND (length(btrim(cwd)) <= 1000))),
    CONSTRAINT codex_continuity_checkpoint_native_task_id_check CHECK ((native_task_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$'::text)),
    CONSTRAINT codex_continuity_checkpoint_project_id_check CHECK (((length(btrim(project_id)) >= 1) AND (length(btrim(project_id)) <= 500))),
    CONSTRAINT codex_continuity_checkpoint_reference_manifest_check CHECK (((jsonb_typeof(reference_manifest) = 'object'::text) AND (octet_length((reference_manifest)::text) <= 128000))),
    CONSTRAINT codex_continuity_checkpoint_state_check CHECK (((jsonb_typeof(state) = 'object'::text) AND (octet_length((state)::text) <= 24000)))
);


--
-- Name: codex_continuity_event; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.codex_continuity_event (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_tenant_id text NOT NULL,
    owner_actor_id uuid NOT NULL,
    native_task_id text NOT NULL,
    project_id text NOT NULL,
    cwd text NOT NULL,
    event_type text NOT NULL,
    cursor jsonb,
    transcript_ref text,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT codex_continuity_event_cursor_check CHECK (((cursor IS NULL) OR ((jsonb_typeof(cursor) = 'object'::text) AND (octet_length((cursor)::text) <= 2000)))),
    CONSTRAINT codex_continuity_event_cwd_check CHECK (((length(btrim(cwd)) >= 1) AND (length(btrim(cwd)) <= 1000))),
    CONSTRAINT codex_continuity_event_event_type_check CHECK (((length(btrim(event_type)) >= 1) AND (length(btrim(event_type)) <= 100))),
    CONSTRAINT codex_continuity_event_idempotency_key_check CHECK (((length(btrim(idempotency_key)) >= 1) AND (length(btrim(idempotency_key)) <= 500))),
    CONSTRAINT codex_continuity_event_native_task_id_check CHECK ((native_task_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$'::text)),
    CONSTRAINT codex_continuity_event_project_id_check CHECK (((length(btrim(project_id)) >= 1) AND (length(btrim(project_id)) <= 500))),
    CONSTRAINT codex_continuity_event_transcript_ref_check CHECK (((transcript_ref IS NULL) OR (length(transcript_ref) <= 1000)))
);


