    CONSTRAINT codex_continuity_revision_reference_manifest_check CHECK (((jsonb_typeof(reference_manifest) = 'object'::text) AND (octet_length((reference_manifest)::text) <= 128000))),
    CONSTRAINT codex_continuity_revision_state_check CHECK (((jsonb_typeof(state) = 'object'::text) AND (octet_length((state)::text) <= 24000)))
);


