SELECT
    NULL::uuid AS session_id,
    NULL::text AS workspace_kind,
    NULL::uuid AS account_client_id,
    NULL::text AS started_by,
    NULL::timestamp with time zone AS started_at,
    NULL::timestamp with time zone AS ended_at,
