--
-- Name: vendor_category; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendor_category (
    slug text NOT NULL,
    label text NOT NULL,
    sort integer NOT NULL
);


--
-- Name: vendor_stage; Type: TABLE; Schema: public; Owner: -
